$function$;
CREATE OR REPLACE FUNCTION public.bn_submit_claim_application(p_ssn text, p_product_code text, p_claim_date date, p_channel text, p_form_payload jsonb, p_employer_regno text DEFAULT NULL::text, p_submitted_by_user_id text DEFAULT NULL::text, p_source_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS TABLE(claim_id uuid, claim_number text, workflow_instance_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product_id UUID;
  v_version_id UUID;
  v_channel_config_id UUID;
  v_workflow_template_id UUID;
  v_workflow_def_id UUID;
  v_claim_id UUID;
  v_claim_no TEXT;
  v_wf_instance UUID := NULL;
  v_person RECORD;
  v_employer RECORD;
  v_contrib RECORD;
  v_user_text TEXT := COALESCE(NULLIF(p_submitted_by_user_id, ''), 'SYSTEM');
  v_channel_config_code TEXT;
BEGIN
  v_channel_config_code := CASE
    WHEN p_channel = 'PUBLIC_ONLINE' THEN 'ONLINE'
    ELSE 'OFFLINE'
  END;

  SELECT p.id, pv.id, pcc.id,
         COALESCE(pcc.workflow_template_id, pv.workflow_template_id),
         pcc.workflow_definition_id
    INTO v_product_id, v_version_id, v_channel_config_id, v_workflow_template_id, v_workflow_def_id
  FROM public.bn_product p
  JOIN public.bn_product_version pv ON pv.product_id = p.id
  LEFT JOIN public.bn_product_channel_config pcc
    ON pcc.product_version_id = pv.id
   AND pcc.channel_code = v_channel_config_code
   AND COALESCE(pcc.is_enabled, true) = true
  WHERE p.benefit_code = p_product_code
    AND p.status = 'ACTIVE'
    AND pv.status = 'ACTIVE'
    AND pv.effective_from <= p_claim_date
    AND (pv.effective_to IS NULL OR pv.effective_to >= p_claim_date)
  ORDER BY pv.effective_from DESC
  LIMIT 1;

  IF v_product_id IS NULL THEN
    RAISE EXCEPTION 'No active product version found for % on %', p_product_code, p_claim_date;
  END IF;

  v_claim_no := 'BN-' || to_char(now(),'YYYYMMDD') || '-' || lpad((floor(random()*100000))::text, 5, '0');

  INSERT INTO public.bn_claim (
    claim_number, ssn, product_id, product_version_id, employer_regno,
    status, priority, claim_date, submission_date, source, application_channel, channel_code,
    contact_phone, contact_email, bank_account, bank_routing_number,
    declaration, entered_by, entered_at, workflow_definition_id, channel_config_id
  )
  VALUES (
    v_claim_no, p_ssn, v_product_id, v_version_id, p_employer_regno,
    'INTAKE', COALESCE(NULLIF(p_form_payload->>'priority', ''), 'NORMAL'), p_claim_date, now(), p_channel, p_channel, v_channel_config_code,
    NULLIF(p_form_payload->>'contact_phone', ''), NULLIF(p_form_payload->>'contact_email', ''),
    NULLIF(p_form_payload->>'bank_account', ''), NULLIF(p_form_payload->>'bank_routing_number', ''),
    COALESCE((p_form_payload->>'declaration_accepted')::boolean, false),
    v_user_text, now(), v_workflow_def_id, v_channel_config_id
  )
  RETURNING id INTO v_claim_id;

  INSERT INTO public.bn_claim_application (
    claim_id, product_id, product_version_id, application_channel,
    submitted_by_type, submitted_by_user_id, submitted_at,
    declaration_accepted, raw_application_json, source_ip, user_agent,
    entered_by
  ) VALUES (
    v_claim_id, v_product_id, v_version_id, p_channel,
    CASE WHEN p_channel='PUBLIC_ONLINE' THEN 'PUBLIC_USER' ELSE 'EMPLOYEE' END,
    v_user_text, now(),
    COALESCE((p_form_payload->>'declaration_accepted')::boolean, false),
    p_form_payload, p_source_ip, p_user_agent, v_user_text
  );

  SELECT ssn, firstname, surname, dob, sex, status, email_addr, phone,
         resident_addr1, resident_addr2, district, place_of_residence
    INTO v_person
  FROM public.ip_master WHERE ssn = p_ssn LIMIT 1;

  IF FOUND THEN
    INSERT INTO public.bn_claim_person_snapshot (
      claim_id, ssn, full_name, date_of_birth, gender, person_status,
      address_json, phone, email
    ) VALUES (
      v_claim_id, v_person.ssn,
      trim(coalesce(v_person.firstname,'') || ' ' || coalesce(v_person.surname,'')),
      v_person.dob, v_person.sex, v_person.status,
      jsonb_build_object('line1', v_person.resident_addr1, 'line2', v_person.resident_addr2,
                         'district', v_person.district, 'country', v_person.place_of_residence),
      v_person.phone, v_person.email_addr
    );
  END IF;

  IF p_employer_regno IS NOT NULL THEN
    SELECT regno, name, status, maddr1, maddr2, hq_addr1, hq_addr2
      INTO v_employer
    FROM public.er_master WHERE regno = p_employer_regno LIMIT 1;
    IF FOUND THEN
      INSERT INTO public.bn_claim_employer_snapshot (
        claim_id, employer_regno, employer_name, employer_status, address_json
      ) VALUES (
        v_claim_id, v_employer.regno, v_employer.name, v_employer.status,
        jsonb_build_object('line1', COALESCE(v_employer.maddr1, v_employer.hq_addr1),
                           'line2', COALESCE(v_employer.maddr2, v_employer.hq_addr2))
      );
    END IF;
  END IF;

  BEGIN
    SELECT
      MIN(period) AS period_from,
      MAX(period) AS period_to,
      COUNT(*)::int AS total_weeks,
      COALESCE(SUM(total_wages),0) AS total_wages
    INTO v_contrib
    FROM public.ip_wages
    WHERE ssn = p_ssn;

    INSERT INTO public.bn_claim_contribution_snapshot (
      claim_id, period_from, period_to, total_weeks, paid_weeks, credited_weeks,
      total_wages, average_weekly_wage, contribution_json
    ) VALUES (
      v_claim_id, v_contrib.period_from, v_contrib.period_to,
      COALESCE(v_contrib.total_weeks, 0), COALESCE(v_contrib.total_weeks, 0), 0,
      COALESCE(v_contrib.total_wages, 0),
      CASE WHEN COALESCE(v_contrib.total_weeks, 0) > 0 THEN COALESCE(v_contrib.total_wages, 0) / v_contrib.total_weeks ELSE 0 END,
      jsonb_build_object('source','ip_wages', 'rows', COALESCE(v_contrib.total_weeks, 0))
    );
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.bn_claim_intake_validation (claim_id, check_code, status, message, details_json)
    VALUES (v_claim_id, 'CONTRIBUTION_SNAPSHOT', 'WARN', 'Contribution snapshot could not be generated', jsonb_build_object('error', SQLERRM));
  END;

  BEGIN
    INSERT INTO public.bn_evidence_checklist (claim_id, requirement_id, status, is_blocking, entered_at)
    SELECT v_claim_id, dr.id, 'OUTSTANDING', COALESCE(dr.blocks_submission, true), now()
    FROM public.bn_doc_requirement dr
    WHERE dr.product_version_id = v_version_id
      AND COALESCE(dr.is_active, true) = true;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.bn_claim_intake_validation (claim_id, check_code, status, message, details_json)
    VALUES (v_claim_id, 'DOCUMENT_CHECKLIST', 'WARN', 'Document checklist could not be generated', jsonb_build_object('error', SQLERRM));
  END;

  INSERT INTO public.bn_claim_intake_validation (claim_id, check_code, status, message)
  VALUES
    (v_claim_id, 'PERSON_FOUND',
       CASE WHEN v_person.ssn IS NOT NULL THEN 'PASS' ELSE 'FAIL' END,
       CASE WHEN v_person.ssn IS NOT NULL THEN 'Claimant matched in ip_master' ELSE 'No matching person for SSN' END),
    (v_claim_id, 'PRODUCT_VERSION_ACTIVE', 'PASS', 'Active product version resolved');

  -- NOTE: Direct workflow_instances INSERT removed.
  -- Workflow start is now exclusively handled by claimIntakeService via the
  -- central workflow engine (triggerBnWorkflow) after this RPC returns.
  -- This eliminates the double-start risk that existed when both the RPC
  -- and the frontend service tried to start the same workflow.

  INSERT INTO public.bn_claim_event (claim_id, event_type, from_status, to_status, notes, performed_by, metadata)
  VALUES (v_claim_id, 'CLAIM_SUBMITTED', NULL, 'INTAKE', 'Claim submitted via intake registration', v_user_text, jsonb_build_object('channel', p_channel));

  RETURN QUERY SELECT v_claim_id, v_claim_no, v_wf_instance;
END;
$function$;
CREATE OR REPLACE FUNCTION public.bn_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.bn_workbaskets_for_user(p_user_id uuid)
 RETURNS TABLE(workbasket_id uuid, basket_code character varying, basket_name character varying, role_name text, is_primary boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT wb.id, wb.basket_code, wb.basket_name, wbr.role_name, wbr.is_primary
  FROM public.bn_workbasket wb
  JOIN public.bn_workbasket_role wbr ON wbr.workbasket_id = wb.id
  JOIN public.v_bn_user_effective_roles er
    ON er.role_name = wbr.role_name AND er.user_id = p_user_id
  WHERE wb.is_active = true;
$function$;
CREATE OR REPLACE FUNCTION public.build_comm_hub_certification_dependency_hash(p_template_version_id uuid)
 RETURNS TABLE(dependency_hash text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_manifest jsonb;
  v_hash text;
BEGIN
  IF p_template_version_id IS NULL THEN
    RETURN QUERY SELECT NULL::text; RETURN;
  END IF;
  BEGIN
    v_manifest := public.build_comm_hub_template_dependency_manifest(p_template_version_id);
    v_hash := public.comm_hub_evidence_hash(
      'comm-hub/template-dependency-manifest/v1', v_manifest);
  EXCEPTION WHEN OTHERS THEN
    v_hash := NULL;
  END;
  RETURN QUERY SELECT v_hash;
END;
$function$;
CREATE OR REPLACE FUNCTION public.build_comm_hub_dependency_manifest(p_entity_type text, p_entity_id uuid, p_entity_version_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_manifest jsonb := jsonb_build_object(
    'manifest_schema_version', 1,
    'manifest_builder_version', '2026.07.22.b2.3',
    'canonical_renderer_version', '2026.07.22.canonical.1',
    'security_policy_version', '1',
    'template_type_policy_version', '1',
    'entity_type', p_entity_type,
    'entity_id', p_entity_id,
    'entity_version_id', p_entity_version_id,
    'dependencies', '{}'::jsonb,
    'dependency_categories', '[]'::jsonb,
    'warnings', '[]'::jsonb,
    'build_status', 'OK'
  );
  v_missing text[] := ARRAY[]::text[];
  v_deps jsonb := '{}'::jsonb;
  v_cats text[] := ARRAY[]::text[];
  v_purpose text;
  v_template record;
  v_version record;
  v_mapping record;
BEGIN
  IF p_entity_type = 'TEMPLATE_VERSION' THEN
    SELECT id, template_id, version_no, status, subject, body_html, body_text, layout_id
      INTO v_version FROM public.core_template_version WHERE id = p_entity_id;
    IF NOT FOUND THEN
      v_missing := v_missing || ARRAY['DEPENDENCY_TEMPLATE_VERSION_MISSING']::text[];
    ELSE
      SELECT id, code, template_type, status, module_code, country_code, institution_code
        INTO v_template FROM public.core_template WHERE id = v_version.template_id;
      v_purpose := public.comm_hub_classify_template_purpose(v_template.id);
      v_deps := jsonb_build_object(
        'template_id', v_template.id,
        'template_code', v_template.code,
        'template_type', v_template.template_type,
        'template_status', upper(coalesce(v_template.status,'')),
        'module_code', v_template.module_code,
        'country_code', v_template.country_code,
        'institution_code', v_template.institution_code,
        'template_purpose', v_purpose,
        'template_version_id', v_version.id,
        'template_version_no', v_version.version_no,
        'template_version_status', upper(coalesce(v_version.status,'')),
        'subject_hash', encode(extensions.digest(convert_to(coalesce(v_version.subject,''),'UTF8'),'sha256'),'hex'),
        'body_html_hash', encode(extensions.digest(convert_to(coalesce(v_version.body_html,''),'UTF8'),'sha256'),'hex'),
        'body_text_hash', encode(extensions.digest(convert_to(coalesce(v_version.body_text,''),'UTF8'),'sha256'),'hex'),
        'layout_id', v_version.layout_id);
      v_cats := ARRAY['TEMPLATE_CONTENT','TEMPLATE_VERSION','TEMPLATE_PURPOSE','TEMPLATE_TYPE']::text[];

      v_deps := v_deps || jsonb_build_object(
        'sections', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', s.id, 'section_key', s.section_key,
            'section_order', s.sort_order, 'is_required', s.is_required,
            'content_hash', encode(extensions.digest(convert_to(coalesce(s.content_html,''),'UTF8'),'sha256'),'hex')
          ) ORDER BY s.sort_order NULLS LAST, s.id)
          FROM public.core_template_section s WHERE s.version_id = v_version.id
        ), '[]'::jsonb));
      v_cats := v_cats || ARRAY['SECTION']::text[];

      v_deps := v_deps || jsonb_build_object(
        'variable_bindings', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', vb.id, 'token_code', vb.token_code, 'is_required', vb.is_required,
            'default_hash', encode(extensions.digest(convert_to(coalesce(vb.default_value,''),'UTF8'),'sha256'),'hex')
          ) ORDER BY vb.token_code, vb.id)
          FROM public.core_template_variable_binding vb WHERE vb.template_version_id = v_version.id
        ), '[]'::jsonb));
      v_cats := v_cats || ARRAY['VARIABLE_CONTRACT']::text[];

      IF v_purpose = 'EVENT_COMMUNICATION' THEN
        SELECT id, module_code, event_code, channel, sender_profile_id, active, risk_level
          INTO v_mapping FROM public.communication_hub_event_template_map
         WHERE template_id = v_template.id AND active = true
         ORDER BY module_code, event_code, channel LIMIT 1;
        IF NOT FOUND THEN
          v_missing := v_missing || ARRAY['DEPENDENCY_MAPPING_MISSING']::text[];
        ELSE
          v_deps := v_deps || jsonb_build_object(
            'event_mapping', jsonb_build_object(
              'id', v_mapping.id, 'module_code', v_mapping.module_code,
              'event_code', v_mapping.event_code, 'channel', lower(v_mapping.channel),
              'sender_profile_id', v_mapping.sender_profile_id, 'risk_level', v_mapping.risk_level));
          v_cats := v_cats || ARRAY['EVENT_MAPPING','SENDER_CONFIGURATION']::text[];
          v_deps := v_deps || jsonb_build_object(
            'sender_readiness', COALESCE((
              SELECT jsonb_build_object(
                'sender_profile_id', sr.sender_profile_id, 'sender_version', sr.sender_version,
                'readiness_state', sr.readiness_state,
                'state_hash', encode(extensions.digest(convert_to(coalesce(sr.readiness_state::text,''),'UTF8'),'sha256'),'hex'))
              FROM public.comm_hub_sender_readiness sr
              WHERE sr.sender_profile_id = v_mapping.sender_profile_id
              ORDER BY sr.computed_at DESC LIMIT 1), 'null'::jsonb));
          v_cats := v_cats || ARRAY['SENDER_READINESS']::text[];
        END IF;
      ELSIF v_purpose IS NULL OR v_purpose = 'UNCLASSIFIED' THEN
        v_missing := v_missing || ARRAY['TEMPLATE_PURPOSE_UNCLASSIFIED']::text[];
      END IF;

      v_manifest := v_manifest
        || jsonb_build_object('template_purpose', v_purpose)
        || jsonb_build_object('module_code', v_template.module_code)
        || jsonb_build_object('dependencies', v_deps)
        || jsonb_build_object('dependency_categories', to_jsonb(
             (SELECT array_agg(DISTINCT c ORDER BY c) FROM unnest(v_cats) c)));
    END IF;
  ELSE
    v_manifest := v_manifest || jsonb_build_object(
      'dependencies', jsonb_build_object(
        'entity_type', p_entity_type, 'entity_id', p_entity_id,
        'entity_version_id', p_entity_version_id));
  END IF;

  IF array_length(v_missing,1) IS NOT NULL THEN
    v_manifest := v_manifest
      || jsonb_build_object('build_status','BLOCKED')
      || jsonb_build_object('missing_dependencies', to_jsonb(v_missing));
  END IF;
  RETURN v_manifest;
END $function$;
CREATE OR REPLACE FUNCTION public.build_comm_hub_recipient_context(p_recipient_policy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb; r record;
BEGIN
  SELECT * INTO r FROM public.communication_hub_recipient_policy WHERE id = p_recipient_policy_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('mode','UNKNOWN','address',NULL,'display_name',NULL);
  END IF;
  v := jsonb_build_object(
    'policy_id', r.id,
    'mode', r.active_mode,
    'address', r.single_configured_address,
    'display_name', r.single_configured_display_name,
    'display_name_confirmed', coalesce(r.single_configured_display_name_confirmed,false),
    'policy_version', r.policy_version
  );
  RETURN v;
END; $function$;
CREATE OR REPLACE FUNCTION public.build_comm_hub_request_context(p_source text DEFAULT 'deterministic-runner'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'source', coalesce(p_source,'deterministic-runner'),
    'requested_at', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'trace_id', gen_random_uuid()::text
  );
$function$;
CREATE OR REPLACE FUNCTION public.build_comm_hub_system_context()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'organization_name','Social Security Board',
    'organization_short_name','SSB',
    'jurisdiction','KN',
    'generated_at', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
$function$;
CREATE OR REPLACE FUNCTION public.build_comm_hub_template_dependency_manifest(p_template_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ver record; v_tpl record; v_vc jsonb;
BEGIN
  SELECT v.id, v.version_no, v.status, v.subject, v.body_html, v.body_text, v.template_id
    INTO v_ver FROM public.core_template_version v WHERE v.id = p_template_version_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('build_status','BLOCKED','reason','TEMPLATE_VERSION_NOT_FOUND',
      'template_version_id', p_template_version_id);
  END IF;
  SELECT id, code, status, active_version_id INTO v_tpl FROM public.core_template WHERE id = v_ver.template_id;

  SELECT jsonb_agg(jsonb_build_object(
           'variable_name', variable_name,
           'source_type', source_type,
           'canonical_path', canonical_path,
           'is_required', is_required,
           'contract_status', contract_status
         ) ORDER BY variable_name)
    INTO v_vc
    FROM public.communication_hub_template_variable_contract
   WHERE template_version_id = p_template_version_id;

  RETURN jsonb_build_object(
    'build_status','OK',
    'schema_version','comm-hub-template-dependency-manifest/v1',
    'template_id', v_tpl.id::text,
    'template_code', v_tpl.code,
    'template_status', v_tpl.status,
    'template_version_id', v_ver.id::text,
    'template_version_no', v_ver.version_no,
    'template_version_status', v_ver.status,
    'subject_hash',   public.comm_hub_sha256_hex(coalesce(v_ver.subject,'')),
    'body_html_hash', public.comm_hub_sha256_hex(coalesce(v_ver.body_html,'')),
    'body_text_hash', public.comm_hub_sha256_hex(coalesce(v_ver.body_text,'')),
    'variable_contract', coalesce(v_vc,'[]'::jsonb),
    'variable_contract_count', coalesce(jsonb_array_length(v_vc),0),
    'renderer_version', 'comm-hub-render/1',
    'canonicalization_version', public.comm_hub_canonicalization_version(),
    'certification_policy_version', 'template-cert-policy/v1'
  );
END $function$;
CREATE OR REPLACE FUNCTION public.c3_config_period_deletability(p_period_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period RECORD;
  v_current_month_start DATE := date_trunc('month', CURRENT_DATE)::DATE;
  v_submission_count INT;
  v_active_count INT;
BEGIN
  SELECT * INTO v_period FROM c3_config_periods WHERE id = p_period_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('can_delete', false, 'reason', 'Period not found');
  END IF;

  IF v_period.last_published_at IS NOT NULL THEN
    RETURN jsonb_build_object('can_delete', false, 'reason', 'Already published — cannot be deleted');
  END IF;

  IF v_period.start_date < v_current_month_start THEN
    RETURN jsonb_build_object('can_delete', false, 'reason', 'Period is in the past — already used in C3 generation and frozen');
  END IF;

  SELECT count(*) INTO v_submission_count
    FROM c3_submissions
   WHERE filing_period IS NOT NULL
     AND to_date(filing_period || '-01', 'YYYY-MM-DD') BETWEEN v_period.start_date
         AND COALESCE(v_period.end_date, DATE '9999-12-31');
  IF v_submission_count > 0 THEN
    RETURN jsonb_build_object('can_delete', false, 'reason', 'Period has C3 submissions and cannot be deleted');
  END IF;

  SELECT count(*) INTO v_active_count FROM c3_config_periods WHERE is_active = true;
  IF v_period.is_active AND v_active_count <= 1 THEN
    RETURN jsonb_build_object('can_delete', false, 'reason', 'At least one active period must remain');
  END IF;

  RETURN jsonb_build_object('can_delete', true, 'reason', null);
END;
$function$;
CREATE OR REPLACE FUNCTION public.c3_config_periods_force_unpublished_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.last_published_at := NULL;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.calculate_c3_contributions(p_period_year integer, p_period_month integer, p_received_date date, p_employee_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_config RECORD;
  v_period_date DATE;
  v_due_date DATE;
  v_days_late INTEGER;
  v_additional_30_periods INTEGER;
  v_months_late INTEGER;
  v_months_late_calendar INTEGER;
  v_employee JSONB;
  v_employee_result JSONB;
  v_employees_result JSONB := '[]'::JSONB;
  v_totals JSONB;
  v_employee_age INTEGER;
  v_week1 NUMERIC; v_week2 NUMERIC; v_week3 NUMERIC; v_week4 NUMERIC; v_week5 NUMERIC;
  v_bonus NUMERIC; v_holiday NUMERIC;
  v_total_wages NUMERIC; v_taxable_wages NUMERIC;
  v_pay_period VARCHAR; v_pay_period_code VARCHAR;
  v_term_start_date DATE; v_date_of_birth DATE;
  v_is_december_start BOOLEAN;
  v_ss_wage_base NUMERIC; v_ss_insurable NUMERIC;
  v_employee_ss NUMERIC; v_employer_ss NUMERIC; v_employer_eib NUMERIC; v_employer_ss_total NUMERIC;
  v_employee_levy NUMERIC; v_bonus_levy NUMERIC;
  v_employer_levy NUMERIC; v_employer_severance NUMERIC;
  v_is_age_exempt_ss BOOLEAN; v_is_age_exempt_levy BOOLEAN;
  v_levy_slab RECORD;
  v_week_amount NUMERIC; v_week_levy NUMERIC;
  v_i INTEGER;
  v_amounts_array NUMERIC[];
  v_monthly_total_for_levy NUMERIC;
  v_use_monthly_override BOOLEAN;
  v_bonus_include_in_levy BOOLEAN;
  v_bonus_flat_rate_raw NUMERIC;
  v_bonus_flat_rate NUMERIC;
  v_bp_calculation_method VARCHAR;
  v_bp_calc_flat_enabled BOOLEAN;
  v_bp_calc_slab_enabled BOOLEAN;
  v_bp_distribution JSONB;
  v_bp_min_bonus NUMERIC;
  v_bp_max_bonus NUMERIC;
  v_bp_contrib_employee BOOLEAN;
  v_bp_contrib_employer BOOLEAN;
  v_bp_contrib_eir BOOLEAN;
  v_bp_contrib_severance BOOLEAN;
  v_bp_include_in_severance BOOLEAN;
  v_bonus_eligible BOOLEAN;
  v_merged_amounts NUMERIC[];
  v_merge_total NUMERIC;
  v_employer_ss_base NUMERIC;
  v_employer_eib_base NUMERIC;
  v_employer_levy_base NUMERIC;
  v_severance_base NUMERIC;
  v_employee_ss_base NUMERIC;
  v_merge_count INTEGER;
  v_per_week_bonus NUMERIC;
  v_bp_found BOOLEAN := false;
  v_hp_policy JSONB;
  v_hp_levy_include BOOLEAN;
  v_hp_levy_method VARCHAR;
  v_hp_levy_flat_enabled BOOLEAN;
  v_hp_levy_flat_pct NUMERIC;
  v_hp_levy_slab_enabled BOOLEAN;
  v_hp_levy_distribution JSONB;
  v_hp_ssc_include BOOLEAN;
  v_hp_ssc_employee BOOLEAN;
  v_hp_ssc_employer BOOLEAN;
  v_hp_ssc_eib BOOLEAN;
  v_hp_include_severance BOOLEAN;
  v_hp_min NUMERIC;
  v_hp_max NUMERIC;
  v_hp_eligible BOOLEAN;
  v_holiday_levy NUMERIC;
  v_holiday_has_dates BOOLEAN;
  v_hp_policy_type TEXT;
  v_hol_start DATE;
  v_hol_end DATE;
  v_monday DATE;
  v_week_start DATE;
  v_week_end DATE;
  v_mondays DATE[];
  v_monday_count INTEGER;
  v_overlap_days INTEGER[];
  v_total_overlap INTEGER;
  v_hol_distributed NUMERIC[];
  v_holiday_distribution JSONB;
  v_hp_distribution_enabled BOOLEAN;
  v_hp_target_slot INTEGER;
  v_sum_period_gross NUMERIC := 0; v_sum_taxable_wages NUMERIC := 0;
  v_sum_employee_ss NUMERIC := 0; v_sum_employer_ss NUMERIC := 0;
  v_sum_employee_levy NUMERIC := 0; v_sum_employer_levy NUMERIC := 0;
  v_sum_employer_severance NUMERIC := 0;
  v_levy_penalty NUMERIC := 0; v_severance_penalty NUMERIC := 0;
  v_ss_fine NUMERIC := 0; v_total_late_charges NUMERIC := 0;
  v_levy_penalty_base NUMERIC := 0; v_severance_penalty_base NUMERIC := 0; v_ss_fine_base NUMERIC := 0;
  v_due_year INTEGER; v_due_month INTEGER; v_received_year INTEGER; v_received_month INTEGER;
  v_slab_code VARCHAR;
  v_week_start_day INTEGER;
  v_filing_window_unit INTEGER;
  v_filing_window_value INTEGER;
  v_penalty_initial_threshold INTEGER;
  v_penalty_subsequent_threshold INTEGER;
  v_filing_deadline DATE;
  v_delay_periods INTEGER;
  v_initial_penalty_periods INTEGER;
  v_subsequent_penalty_periods INTEGER;
  v_pg_dow INTEGER;
BEGIN
  v_period_date := make_date(p_period_year, p_period_month + 1, 1);
  
  SELECT * INTO v_config FROM public.get_c3_config_for_period(v_period_date);
  IF v_config IS NULL THEN
    RAISE EXCEPTION 'No active configuration found for period %', v_period_date;
  END IF;
  
  SELECT COALESCE((SELECT config_value FROM c3_calculation_config WHERE config_key = 'week_start_day' AND is_active = true), 1)::INTEGER INTO v_week_start_day;
  SELECT COALESCE((SELECT config_value FROM c3_calculation_config WHERE config_key = 'filing_window_unit' AND is_active = true), 1)::INTEGER INTO v_filing_window_unit;
  SELECT COALESCE((SELECT config_value FROM c3_calculation_config WHERE config_key = 'filing_window_value' AND is_active = true), 1)::INTEGER INTO v_filing_window_value;
  SELECT COALESCE((SELECT config_value FROM c3_calculation_config WHERE config_key = 'penalty_initial_threshold' AND is_active = true), 1)::INTEGER INTO v_penalty_initial_threshold;
  SELECT COALESCE((SELECT config_value FROM c3_calculation_config WHERE config_key = 'penalty_subsequent_threshold' AND is_active = true), 1)::INTEGER INTO v_penalty_subsequent_threshold;
  
  IF v_week_start_day = 7 THEN v_pg_dow := 0; ELSE v_pg_dow := v_week_start_day; END IF;

  v_mondays := ARRAY[]::DATE[];
  v_monday := v_period_date;
  WHILE EXTRACT(DOW FROM v_monday)::INTEGER != v_pg_dow LOOP
    v_monday := v_monday + 1;
  END LOOP;
  WHILE EXTRACT(MONTH FROM v_monday) = (p_period_month + 1) LOOP
    v_mondays := v_mondays || v_monday;
    v_monday := v_monday + 7;
  END LOOP;
  v_monday_count := array_length(v_mondays, 1);
  IF v_monday_count IS NULL THEN v_monday_count := 0; END IF;

  SELECT include_in_levy, calc_flat_percentage, calculation_method,
         calc_flat_enabled, calc_slab_enabled, distribution::jsonb,
         min_bonus_amount, max_bonus_amount,
         COALESCE(contrib_employee, false), COALESCE(contrib_employer, false),
         COALESCE(contrib_eir, false), COALESCE(contrib_severance, false),
         COALESCE(include_in_severance, false)
  INTO v_bonus_include_in_levy, v_bonus_flat_rate_raw, v_bp_calculation_method,
       v_bp_calc_flat_enabled, v_bp_calc_slab_enabled, v_bp_distribution,
       v_bp_min_bonus, v_bp_max_bonus,
       v_bp_contrib_employee, v_bp_contrib_employer, v_bp_contrib_eir, v_bp_contrib_severance,
       v_bp_include_in_severance
  FROM public.c3_bonus_policy_exceptions
  WHERE is_active = true AND override_default = true
    AND exception_month = (p_period_month + 1)
    AND year_from <= p_period_year
    AND (year_to IS NULL OR year_to >= p_period_year)
  ORDER BY date_from DESC LIMIT 1;
  
  IF FOUND THEN v_bp_found := true; END IF;
  
  IF NOT v_bp_found THEN
    SELECT include_in_levy, calc_flat_percentage, calculation_method,
           calc_flat_enabled, calc_slab_enabled, distribution::jsonb,
           min_bonus_amount, max_bonus_amount,
           COALESCE(contrib_employee, false), COALESCE(contrib_employer, false),
           COALESCE(contrib_eir, false), COALESCE(contrib_severance, false),
           COALESCE(include_in_severance, false)
    INTO v_bonus_include_in_levy, v_bonus_flat_rate_raw, v_bp_calculation_method,
         v_bp_calc_flat_enabled, v_bp_calc_slab_enabled, v_bp_distribution,
         v_bp_min_bonus, v_bp_max_bonus,
         v_bp_contrib_employee, v_bp_contrib_employer, v_bp_contrib_eir, v_bp_contrib_severance,
         v_bp_include_in_severance
    FROM public.c3_bonus_policy_default
    WHERE is_active = true AND v_period_date >= date_from AND (date_to IS NULL OR v_period_date <= date_to)
    ORDER BY created_on DESC LIMIT 1;
  END IF;
  
  v_bonus_include_in_levy := COALESCE(v_bonus_include_in_levy, false);
  v_bonus_flat_rate := COALESCE(v_bonus_flat_rate_raw, 0) / 100.0;
  v_bp_calculation_method := COALESCE(v_bp_calculation_method, 'merge');
  v_bp_calc_flat_enabled := COALESCE(v_bp_calc_flat_enabled, false);
  v_bp_calc_slab_enabled := COALESCE(v_bp_calc_slab_enabled, false);
  v_bp_contrib_employee := COALESCE(v_bp_contrib_employee, false);
  v_bp_contrib_employer := COALESCE(v_bp_contrib_employer, false);
  v_bp_contrib_eir := COALESCE(v_bp_contrib_eir, false);
  v_bp_contrib_severance := COALESCE(v_bp_contrib_severance, false);
  v_bp_include_in_severance := COALESCE(v_bp_include_in_severance, false);
  
  -- ===== DUE DATE (legacy, kept for display) =====
  IF v_config.submission_due_day = 0 THEN
    v_due_date := (make_date(
      CASE WHEN p_period_month + 1 > 11 THEN p_period_year + 1 ELSE p_period_year END,
      CASE WHEN p_period_month + 1 > 11 THEN 1 ELSE p_period_month + 2 END, 1
    ) + INTERVAL '1 month' - INTERVAL '1 day')::DATE;
  ELSE
    v_due_date := make_date(
      CASE WHEN p_period_month + 1 > 11 THEN p_period_year + 1 ELSE p_period_year END,
      CASE WHEN p_period_month + 1 > 11 THEN 1 ELSE p_period_month + 2 END,
      LEAST(v_config.submission_due_day, 28)
    );
  END IF;
  
  -- ===== FIXED FILING DEADLINE =====
  -- Compute directly from period to avoid double-counting.
  -- p_period_month is 0-indexed. Target 1-indexed month = p_period_month + v_filing_window_value + 1
  IF v_filing_window_unit = 1 THEN
    DECLARE
      v_fl_target_month INTEGER;
      v_fl_target_year INTEGER;
    BEGIN
      v_fl_target_month := p_period_month + v_filing_window_value + 1;
      v_fl_target_year := p_period_year;
      WHILE v_fl_target_month > 12 LOOP
        v_fl_target_month := v_fl_target_month - 12;
        v_fl_target_year := v_fl_target_year + 1;
      END LOOP;
      v_filing_deadline := (make_date(v_fl_target_year, v_fl_target_month, 1) + INTERVAL '1 month' - INTERVAL '1 day')::DATE;
    END;
  ELSE
    -- Days-based: add days to the last day of the period month
    v_filing_deadline := (make_date(p_period_year, p_period_month + 1, 1) + INTERVAL '1 month' - INTERVAL '1 day')::DATE + v_filing_window_value;
  END IF;
  
  v_days_late := GREATEST(0, p_received_date - v_filing_deadline);
  v_due_year := EXTRACT(YEAR FROM v_filing_deadline)::INTEGER;
  v_due_month := EXTRACT(MONTH FROM v_filing_deadline)::INTEGER;
  v_received_year := EXTRACT(YEAR FROM p_received_date)::INTEGER;
  v_received_month := EXTRACT(MONTH FROM p_received_date)::INTEGER;
  v_months_late_calendar := GREATEST(0, (v_received_year * 12 + v_received_month) - (v_due_year * 12 + v_due_month));
  
  IF v_days_late > 30 THEN v_additional_30_periods := CEIL((v_days_late - 30)::NUMERIC / 30);
  ELSE v_additional_30_periods := 0; END IF;
  IF v_days_late > 0 THEN v_months_late := CEIL(v_days_late::NUMERIC / 30);
  ELSE v_months_late := 0; END IF;
  
  IF v_filing_window_unit = 1 THEN v_delay_periods := v_months_late_calendar;
  ELSE v_delay_periods := v_months_late; END IF;
  
  v_initial_penalty_periods := LEAST(v_delay_periods, v_penalty_initial_threshold);
  v_subsequent_penalty_periods := GREATEST(0, v_delay_periods - v_penalty_initial_threshold);
  
  -- ===== PROCESS EMPLOYEES =====
  FOR v_employee IN SELECT * FROM jsonb_array_elements(p_employee_data)
  LOOP
    v_week1 := COALESCE((v_employee->>'week1')::NUMERIC, (v_employee->'weeklyWages'->>0)::NUMERIC, 0);
    v_week2 := COALESCE((v_employee->>'week2')::NUMERIC, (v_employee->'weeklyWages'->>1)::NUMERIC, 0);
    v_week3 := COALESCE((v_employee->>'week3')::NUMERIC, (v_employee->'weeklyWages'->>2)::NUMERIC, 0);
    v_week4 := COALESCE((v_employee->>'week4')::NUMERIC, (v_employee->'weeklyWages'->>3)::NUMERIC, 0);
    v_week5 := COALESCE((v_employee->>'week5')::NUMERIC, (v_employee->'weeklyWages'->>4)::NUMERIC, 0);
    v_bonus := COALESCE((v_employee->>'bonus')::NUMERIC, (v_employee->'weeklyWages'->>5)::NUMERIC, 0);
    v_holiday := COALESCE((v_employee->>'holiday')::NUMERIC, (v_employee->'weeklyWages'->>6)::NUMERIC, 0);
    v_pay_period := COALESCE(v_employee->>'payPeriod', 'Monthly');
    v_term_start_date := (v_employee->>'termStartDate')::DATE;
    v_date_of_birth := (v_employee->>'dateOfBirth')::DATE;
    
    v_holiday_has_dates := (v_employee->>'holidayStartDate') IS NOT NULL 
                           AND (v_employee->>'holidayStartDate') != ''
                           AND (v_employee->>'holidayNoDates') IS DISTINCT FROM 'true';
    
    IF v_holiday_has_dates THEN v_hp_policy_type := 'with_dates';
    ELSE v_hp_policy_type := 'without_dates'; END IF;
    
    -- ===== HOLIDAY DATE-BASED DISTRIBUTION =====
    v_holiday_distribution := NULL;
    v_hol_distributed := ARRAY[0::NUMERIC, 0::NUMERIC, 0::NUMERIC, 0::NUMERIC, 0::NUMERIC];
    
    IF v_holiday > 0 AND v_holiday_has_dates AND v_monday_count > 0 THEN
      v_hol_start := (v_employee->>'holidayStartDate')::DATE;
      v_hol_end := COALESCE((v_employee->>'holidayEndDate')::DATE, v_hol_start);
      
      v_hp_policy := public.resolve_holiday_pay_policy(
        v_period_date, (p_period_month + 1), p_period_year, 'with_dates'
      );
      v_hp_distribution_enabled := COALESCE((v_hp_policy->>'distribution_enabled')::BOOLEAN, true);
      
      IF v_hp_distribution_enabled THEN
        v_overlap_days := ARRAY[0, 0, 0, 0, 0];
        v_total_overlap := 0;
        
        FOR v_i IN 1..v_monday_count LOOP
          v_week_start := v_mondays[v_i];
          IF v_i < v_monday_count THEN v_week_end := v_mondays[v_i + 1] - 1;
          ELSE v_week_end := (v_period_date + INTERVAL '1 month' - INTERVAL '1 day')::DATE; END IF;
          
          IF v_hol_start <= v_week_end AND v_hol_end >= v_week_start THEN
            v_overlap_days[v_i] := GREATEST(0, 
              (LEAST(v_hol_end, v_week_end) - GREATEST(v_hol_start, v_week_start))::INTEGER + 1);
            v_total_overlap := v_total_overlap + v_overlap_days[v_i];
          END IF;
        END LOOP;
        
        IF v_total_overlap > 0 THEN
          FOR v_i IN 1..5 LOOP
            IF v_i <= v_monday_count AND v_overlap_days[v_i] > 0 THEN
              v_hol_distributed[v_i] := ROUND(v_holiday * v_overlap_days[v_i]::NUMERIC / v_total_overlap::NUMERIC, 2);
            END IF;
          END LOOP;
          
          DECLARE
            v_dist_sum NUMERIC := 0;
            v_last_dist_week INTEGER := 1;
          BEGIN
            FOR v_i IN 1..5 LOOP
              v_dist_sum := v_dist_sum + v_hol_distributed[v_i];
              IF v_hol_distributed[v_i] > 0 THEN v_last_dist_week := v_i; END IF;
            END LOOP;
            IF v_dist_sum != v_holiday THEN
              v_hol_distributed[v_last_dist_week] := v_hol_distributed[v_last_dist_week] + (v_holiday - v_dist_sum);
            END IF;
          END;
          
          v_week1 := v_week1 + v_hol_distributed[1];
          v_week2 := v_week2 + v_hol_distributed[2];
          v_week3 := v_week3 + v_hol_distributed[3];
          v_week4 := v_week4 + v_hol_distributed[4];
          v_week5 := v_week5 + v_hol_distributed[5];
          v_holiday := 0;
          
          v_holiday_distribution := jsonb_build_object(
            'distributed', true,
            'week1', v_hol_distributed[1], 'week2', v_hol_distributed[2],
            'week3', v_hol_distributed[3], 'week4', v_hol_distributed[4],
            'week5', v_hol_distributed[5],
            'totalDistributed', v_hol_distributed[1]+v_hol_distributed[2]+v_hol_distributed[3]+v_hol_distributed[4]+v_hol_distributed[5],
            'overlapDays', to_jsonb(v_overlap_days),
            'holidayStart', v_hol_start, 'holidayEnd', v_hol_end
          );
        END IF;
      END IF;
    END IF;
    
    IF v_date_of_birth IS NOT NULL THEN
      v_employee_age := EXTRACT(YEAR FROM AGE(CURRENT_DATE, v_date_of_birth))::INTEGER;
    ELSE v_employee_age := 30; END IF;
    
    v_pay_period_code := CASE v_pay_period
      WHEN 'Weekly' THEN 'W' WHEN 'Bi-Weekly' THEN 'E2W'
      WHEN '2 Monthly' THEN '2M' WHEN 'Monthly' THEN 'M' ELSE 'M'
    END;
    
    v_is_december_start := v_term_start_date IS NOT NULL AND EXTRACT(MONTH FROM v_term_start_date) = 12;
    v_total_wages := v_week1 + v_week2 + v_week3 + v_week4 + v_week5 + v_bonus + v_holiday;
    v_taxable_wages := v_total_wages - v_bonus;
    v_is_age_exempt_ss := v_employee_age < v_config.min_age_ss OR v_employee_age > v_config.max_age_ss;
    v_is_age_exempt_levy := v_employee_age < v_config.min_age_levy OR v_employee_age > v_config.max_age_levy;
    
    IF v_holiday_distribution IS NULL THEN v_hp_policy := NULL; END IF;
    v_holiday_levy := 0;
    v_hp_eligible := v_holiday > 0;
    
    IF v_hp_eligible THEN
      IF v_hp_policy IS NULL THEN
        v_hp_policy := public.resolve_holiday_pay_policy(
          v_period_date, (p_period_month + 1), p_period_year, v_hp_policy_type
        );
      END IF;
    END IF;
    
    v_hp_levy_include := COALESCE((v_hp_policy->>'levy_include')::BOOLEAN, false);
    v_hp_levy_method := COALESCE(v_hp_policy->>'levy_calculation_method', 'merge');
    v_hp_levy_flat_enabled := COALESCE((v_hp_policy->>'levy_calc_flat_enabled')::BOOLEAN, false);
    v_hp_levy_flat_pct := COALESCE((v_hp_policy->>'levy_calc_flat_percentage')::NUMERIC, 0) / 100.0;
    v_hp_levy_slab_enabled := COALESCE((v_hp_policy->>'levy_calc_slab_enabled')::BOOLEAN, false);
    v_hp_levy_distribution := v_hp_policy->'levy_distribution';
    v_hp_ssc_include := COALESCE((v_hp_policy->>'ssc_include')::BOOLEAN, false);
    v_hp_ssc_employee := COALESCE((v_hp_policy->>'ssc_contrib_employee')::BOOLEAN, false);
    v_hp_ssc_employer := COALESCE((v_hp_policy->>'ssc_contrib_employer')::BOOLEAN, false);
    v_hp_ssc_eib := COALESCE((v_hp_policy->>'ssc_contrib_eib')::BOOLEAN, false);
    v_hp_include_severance := COALESCE((v_hp_policy->>'include_in_severance')::BOOLEAN, false);
    v_hp_min := (v_hp_policy->>'min_holiday_amount')::NUMERIC;
    v_hp_max := (v_hp_policy->>'max_holiday_amount')::NUMERIC;
    
    IF v_holiday_distribution IS NOT NULL THEN
      v_hp_eligible := false;
      v_hp_levy_include := false;
      v_hp_ssc_include := false;
      v_hp_include_severance := false;
    END IF;
    
    IF v_hp_eligible AND (v_hp_min IS NOT NULL OR v_hp_max IS NOT NULL) THEN
      IF v_hp_min IS NOT NULL AND v_holiday < v_hp_min THEN v_hp_eligible := false; END IF;
      IF v_hp_max IS NOT NULL AND v_holiday > v_hp_max THEN v_hp_eligible := false; END IF;
    END IF;
    
    v_hp_target_slot := 0;
    IF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'merge' AND v_hp_levy_distribution IS NOT NULL THEN
      IF v_pay_period_code = 'W' THEN
        IF COALESCE((v_hp_levy_distribution->'weekly'->>'w4')::boolean, false) THEN v_hp_target_slot := 4;
        ELSIF COALESCE((v_hp_levy_distribution->'weekly'->>'w3')::boolean, false) THEN v_hp_target_slot := 3;
        ELSIF COALESCE((v_hp_levy_distribution->'weekly'->>'w2')::boolean, false) THEN v_hp_target_slot := 2;
        ELSIF COALESCE((v_hp_levy_distribution->'weekly'->>'w1')::boolean, false) THEN v_hp_target_slot := 1;
        ELSE v_hp_target_slot := 4;
        END IF;
      ELSIF v_pay_period_code = 'E2W' THEN
        IF COALESCE((v_hp_levy_distribution->'biweekly'->>'b2')::boolean, false) THEN v_hp_target_slot := 3;
        ELSIF COALESCE((v_hp_levy_distribution->'biweekly'->>'b1')::boolean, false) THEN v_hp_target_slot := 1;
        ELSE v_hp_target_slot := 3;
        END IF;
      ELSIF v_pay_period_code = '2M' THEN
        IF COALESCE((v_hp_levy_distribution->'semimonthly'->>'s2')::boolean, false) THEN v_hp_target_slot := 3;
        ELSIF COALESCE((v_hp_levy_distribution->'semimonthly'->>'s1')::boolean, false) THEN v_hp_target_slot := 1;
        ELSE v_hp_target_slot := 3;
        END IF;
      ELSE
        v_hp_target_slot := 0;
      END IF;
    END IF;
    
    v_bonus_eligible := v_bonus > 0;
    IF v_bonus_eligible AND (v_bp_min_bonus IS NOT NULL OR v_bp_max_bonus IS NOT NULL) THEN
      IF v_bp_min_bonus IS NOT NULL AND v_bonus < v_bp_min_bonus THEN v_bonus_eligible := false; END IF;
      IF v_bp_max_bonus IS NOT NULL AND v_bonus > v_bp_max_bonus THEN v_bonus_eligible := false; END IF;
    END IF;
    
    v_ss_wage_base := CASE WHEN v_is_december_start THEN v_taxable_wages ELSE v_total_wages - v_bonus END;
    
    v_employee_ss_base := v_taxable_wages;
    IF v_bonus_eligible AND v_bp_contrib_employee THEN v_employee_ss_base := v_employee_ss_base + v_bonus; END IF;
    IF v_holiday > 0 AND (NOT v_hp_ssc_include OR NOT v_hp_ssc_employee) THEN
      v_employee_ss_base := v_employee_ss_base - v_holiday;
    END IF;
    v_ss_insurable := LEAST(v_employee_ss_base, v_config.employee_ss_max_wage);
    
    IF NOT v_is_age_exempt_ss THEN
      v_employee_ss := ROUND(v_ss_insurable * v_config.employee_ss_rate, 2);
      v_employer_ss_base := v_taxable_wages;
      IF v_bonus_eligible AND v_bp_contrib_employer THEN v_employer_ss_base := v_employer_ss_base + v_bonus; END IF;
      IF v_holiday > 0 AND (NOT v_hp_ssc_include OR NOT v_hp_ssc_employer) THEN
        v_employer_ss_base := v_employer_ss_base - v_holiday;
      END IF;
      v_employer_ss := ROUND(LEAST(v_employer_ss_base, v_config.employee_ss_max_wage) * v_config.employer_ss_rate, 2);
      v_employer_eib_base := v_taxable_wages;
      IF v_bonus_eligible AND v_bp_contrib_eir THEN v_employer_eib_base := v_employer_eib_base + v_bonus; END IF;
      IF v_holiday > 0 AND (NOT v_hp_ssc_include OR NOT v_hp_ssc_eib) THEN
        v_employer_eib_base := v_employer_eib_base - v_holiday;
      END IF;
      v_employer_eib := ROUND(LEAST(v_employer_eib_base, v_config.employee_ss_max_wage) * v_config.employer_eib_rate, 2);
    ELSE
      v_employee_ss := 0; v_employer_ss := 0;
      v_employer_eib_base := v_taxable_wages;
      IF v_bonus_eligible AND v_bp_contrib_eir THEN v_employer_eib_base := v_employer_eib_base + v_bonus; END IF;
      IF v_hp_eligible AND v_hp_ssc_include AND v_hp_ssc_eib THEN NULL;
      ELSIF v_holiday > 0 THEN v_employer_eib_base := v_employer_eib_base - v_holiday; END IF;
      v_employer_eib := ROUND(LEAST(v_employer_eib_base, v_config.employee_ss_max_wage) * v_config.employer_eib_rate, 2);
    END IF;
    v_employer_ss_total := v_employer_ss + v_employer_eib;
    
    v_employee_levy := 0;
    v_bonus_levy := 0;
    v_holiday_levy := 0;
    
    IF NOT v_is_age_exempt_levy THEN
      v_monthly_total_for_levy := v_week1 + v_week2 + v_week3 + v_week4 + v_week5;
      
      IF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'merge' THEN
        v_monthly_total_for_levy := v_monthly_total_for_levy + v_holiday;
      ELSIF NOT v_hp_eligible OR NOT v_hp_levy_include THEN
        v_monthly_total_for_levy := v_monthly_total_for_levy + v_holiday;
      END IF;
      
      IF v_bonus_eligible AND v_bonus_include_in_levy AND v_bp_calculation_method = 'merge' THEN
        v_merged_amounts := ARRAY[v_week1, v_week2, v_week3, v_week4, v_week5, 0::NUMERIC];
        
        IF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'merge' THEN
          IF v_hp_target_slot > 0 AND v_hp_target_slot <= 5 THEN
            v_merged_amounts[v_hp_target_slot] := v_merged_amounts[v_hp_target_slot] + v_holiday;
          ELSE
            v_merged_amounts[6] := v_holiday;
          END IF;
        ELSIF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'separate' THEN
          v_merged_amounts[6] := 0;
        ELSE
          IF v_hp_target_slot > 0 AND v_hp_target_slot <= 5 THEN
            v_merged_amounts[v_hp_target_slot] := v_merged_amounts[v_hp_target_slot] + v_holiday;
          ELSE
            v_merged_amounts[6] := v_holiday;
          END IF;
        END IF;
        
        IF v_pay_period_code = 'W' THEN
          IF v_bp_distribution IS NOT NULL AND v_bp_distribution->'weekly' IS NOT NULL
             AND COALESCE((v_bp_distribution->'weekly'->>'divide')::boolean, false) = false THEN
            v_merge_count := 0;
            IF COALESCE((v_bp_distribution->'weekly'->>'w1')::boolean, false) THEN v_merge_count := v_merge_count + 1; END IF;
            IF COALESCE((v_bp_distribution->'weekly'->>'w2')::boolean, false) THEN v_merge_count := v_merge_count + 1; END IF;
            IF COALESCE((v_bp_distribution->'weekly'->>'w3')::boolean, false) THEN v_merge_count := v_merge_count + 1; END IF;
            IF COALESCE((v_bp_distribution->'weekly'->>'w4')::boolean, false) THEN v_merge_count := v_merge_count + 1; END IF;
            IF v_merge_count = 0 THEN
              FOR v_i IN 1..5 LOOP v_merged_amounts[v_i] := v_merged_amounts[v_i] + ROUND(v_bonus / 5.0, 2); END LOOP;
            ELSIF v_merge_count = 1 THEN
              IF COALESCE((v_bp_distribution->'weekly'->>'w1')::boolean, false) THEN v_merged_amounts[1] := v_merged_amounts[1] + v_bonus; END IF;
              IF COALESCE((v_bp_distribution->'weekly'->>'w2')::boolean, false) THEN v_merged_amounts[2] := v_merged_amounts[2] + v_bonus; END IF;
              IF COALESCE((v_bp_distribution->'weekly'->>'w3')::boolean, false) THEN v_merged_amounts[3] := v_merged_amounts[3] + v_bonus; END IF;
              IF COALESCE((v_bp_distribution->'weekly'->>'w4')::boolean, false) THEN v_merged_amounts[4] := v_merged_amounts[4] + v_bonus; END IF;
            ELSE
              v_per_week_bonus := ROUND(v_bonus / v_merge_count, 2);
              IF COALESCE((v_bp_distribution->'weekly'->>'w1')::boolean, false) THEN v_merged_amounts[1] := v_merged_amounts[1] + v_per_week_bonus; END IF;
              IF COALESCE((v_bp_distribution->'weekly'->>'w2')::boolean, false) THEN v_merged_amounts[2] := v_merged_amounts[2] + v_per_week_bonus; END IF;
              IF COALESCE((v_bp_distribution->'weekly'->>'w3')::boolean, false) THEN v_merged_amounts[3] := v_merged_amounts[3] + v_per_week_bonus; END IF;
              IF COALESCE((v_bp_distribution->'weekly'->>'w4')::boolean, false) THEN v_merged_amounts[4] := v_merged_amounts[4] + v_per_week_bonus; END IF;
            END IF;
          ELSE
            FOR v_i IN 1..5 LOOP v_merged_amounts[v_i] := v_merged_amounts[v_i] + ROUND(v_bonus / 5.0, 2); END LOOP;
          END IF;
        ELSIF v_pay_period_code = 'E2W' THEN
          IF v_bp_distribution IS NOT NULL AND v_bp_distribution->'biweekly' IS NOT NULL
             AND COALESCE((v_bp_distribution->'biweekly'->>'divide')::boolean, false) THEN
            v_merged_amounts[1] := v_merged_amounts[1] + ROUND(v_bonus / 2.0, 2);
            v_merged_amounts[3] := v_merged_amounts[3] + ROUND(v_bonus / 2.0, 2);
          ELSIF v_bp_distribution IS NOT NULL AND COALESCE((v_bp_distribution->'biweekly'->>'b1')::boolean, false) THEN
            v_merged_amounts[1] := v_merged_amounts[1] + v_bonus;
          ELSIF v_bp_distribution IS NOT NULL AND COALESCE((v_bp_distribution->'biweekly'->>'b2')::boolean, false) THEN
            v_merged_amounts[3] := v_merged_amounts[3] + v_bonus;
          ELSE
            v_merged_amounts[1] := v_merged_amounts[1] + v_bonus;
          END IF;
        ELSE
          v_merged_amounts[1] := v_merged_amounts[1] + v_bonus;
        END IF;
        
        v_merge_total := v_merged_amounts[1] + v_merged_amounts[2] + v_merged_amounts[3] + v_merged_amounts[4] + v_merged_amounts[5] + v_merged_amounts[6];
        
        v_use_monthly_override := false;
        IF v_pay_period_code != 'M'
           AND COALESCE(v_config.levy_use_monthly_when_exceeded, false)
           AND v_merge_total > COALESCE(v_config.levy_monthly_threshold, 0)
           AND COALESCE(v_config.levy_monthly_threshold, 0) > 0 THEN
          v_use_monthly_override := true;
        END IF;
        
        IF v_use_monthly_override OR v_pay_period_code = 'M' THEN
          SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
          WHERE slab_id = v_config.levy_slab_id AND pay_period = 'M' AND is_active = true AND v_merge_total > over_amt
          ORDER BY over_amt DESC LIMIT 1;
          IF v_levy_slab IS NOT NULL THEN
            v_employee_levy := ROUND(v_levy_slab.base_amt + ((v_merge_total - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
          END IF;
        ELSE
          v_slab_code := v_pay_period_code;
          v_employee_levy := public.evaluate_levy_amounts(v_merged_amounts, v_config.levy_slab_id, v_slab_code);
        END IF;
        
      ELSIF v_bonus_eligible AND v_bonus_include_in_levy AND v_bp_calculation_method = 'separate' THEN
        IF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'separate' THEN
          v_monthly_total_for_levy := v_monthly_total_for_levy - v_holiday;
        END IF;
        
        v_use_monthly_override := false;
        IF v_pay_period_code != 'M'
           AND COALESCE(v_config.levy_use_monthly_when_exceeded, false)
           AND v_monthly_total_for_levy > COALESCE(v_config.levy_monthly_threshold, 0)
           AND COALESCE(v_config.levy_monthly_threshold, 0) > 0 THEN
          v_use_monthly_override := true;
        END IF;
        
        IF v_use_monthly_override THEN
          SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
          WHERE slab_id = v_config.levy_slab_id AND pay_period = 'M' AND is_active = true AND v_monthly_total_for_levy > over_amt
          ORDER BY over_amt DESC LIMIT 1;
          IF v_levy_slab IS NOT NULL THEN
            v_employee_levy := ROUND(v_levy_slab.base_amt + ((v_monthly_total_for_levy - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
          END IF;
        ELSIF v_pay_period_code = 'M' THEN
          IF v_monthly_total_for_levy > 0 THEN
            SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
            WHERE slab_id = v_config.levy_slab_id AND pay_period = 'M' AND is_active = true AND v_monthly_total_for_levy > over_amt
            ORDER BY over_amt DESC LIMIT 1;
            IF v_levy_slab IS NOT NULL THEN
              v_employee_levy := ROUND(v_levy_slab.base_amt + ((v_monthly_total_for_levy - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
            END IF;
          END IF;
        ELSE
          v_slab_code := v_pay_period_code;
          v_amounts_array := ARRAY[v_week1, v_week2, v_week3, v_week4, v_week5];
          IF NOT (v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'separate') THEN
            IF v_hp_target_slot > 0 AND v_hp_target_slot <= 5 THEN
              v_amounts_array[v_hp_target_slot] := v_amounts_array[v_hp_target_slot] + v_holiday;
            ELSE
              v_amounts_array := v_amounts_array || v_holiday;
            END IF;
          END IF;
          v_employee_levy := public.evaluate_levy_amounts(v_amounts_array, v_config.levy_slab_id, v_slab_code);
        END IF;
        
        IF v_bonus > 0 THEN
          IF v_bp_calc_flat_enabled AND v_bonus_flat_rate > 0 THEN
            v_bonus_levy := ROUND(v_bonus * v_bonus_flat_rate, 2);
          ELSIF v_bp_calc_slab_enabled THEN
            SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
            WHERE slab_id = v_config.levy_slab_id AND pay_period = v_pay_period_code AND is_active = true AND v_bonus > over_amt
            ORDER BY over_amt DESC LIMIT 1;
            IF v_levy_slab IS NOT NULL THEN
              v_bonus_levy := ROUND(v_levy_slab.base_amt + ((v_bonus - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
            END IF;
          END IF;
          v_employee_levy := v_employee_levy + v_bonus_levy;
        END IF;
        
      ELSE
        IF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'separate' THEN
          v_monthly_total_for_levy := v_monthly_total_for_levy - v_holiday;
        END IF;
        
        v_use_monthly_override := false;
        IF v_pay_period_code != 'M'
           AND COALESCE(v_config.levy_use_monthly_when_exceeded, false) = true
           AND v_monthly_total_for_levy > COALESCE(v_config.levy_monthly_threshold, 0)
           AND COALESCE(v_config.levy_monthly_threshold, 0) > 0 THEN
          v_use_monthly_override := true;
        END IF;
        
        IF v_use_monthly_override THEN
          SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
          WHERE slab_id = v_config.levy_slab_id AND pay_period = 'M' AND is_active = true AND v_monthly_total_for_levy > over_amt
          ORDER BY over_amt DESC LIMIT 1;
          IF v_levy_slab IS NOT NULL THEN
            v_employee_levy := ROUND(v_levy_slab.base_amt + ((v_monthly_total_for_levy - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
          END IF;
        ELSIF v_pay_period_code = 'M' THEN
          IF v_monthly_total_for_levy > 0 THEN
            SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
            WHERE slab_id = v_config.levy_slab_id AND pay_period = 'M' AND is_active = true AND v_monthly_total_for_levy > over_amt
            ORDER BY over_amt DESC LIMIT 1;
            IF v_levy_slab IS NOT NULL THEN
              v_employee_levy := ROUND(v_levy_slab.base_amt + ((v_monthly_total_for_levy - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
            END IF;
          END IF;
        ELSE
          v_slab_code := v_pay_period_code;
          v_amounts_array := ARRAY[v_week1, v_week2, v_week3, v_week4, v_week5];
          IF NOT (v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'separate') THEN
            IF v_hp_target_slot > 0 AND v_hp_target_slot <= 5 THEN
              v_amounts_array[v_hp_target_slot] := v_amounts_array[v_hp_target_slot] + v_holiday;
            ELSE
              v_amounts_array := v_amounts_array || v_holiday;
            END IF;
          END IF;
          v_employee_levy := public.evaluate_levy_amounts(v_amounts_array, v_config.levy_slab_id, v_slab_code);
        END IF;
      END IF;
      
      IF v_hp_eligible AND v_hp_levy_include AND v_hp_levy_method = 'separate' AND v_holiday > 0 THEN
        IF v_hp_levy_flat_enabled AND v_hp_levy_flat_pct > 0 THEN
          v_holiday_levy := ROUND(v_holiday * v_hp_levy_flat_pct, 2);
        ELSIF v_hp_levy_slab_enabled THEN
          SELECT * INTO v_levy_slab FROM public.tb_levy_slab_details
          WHERE slab_id = v_config.levy_slab_id AND pay_period = v_pay_period_code AND is_active = true AND v_holiday > over_amt
          ORDER BY over_amt DESC LIMIT 1;
          IF v_levy_slab IS NOT NULL THEN
            v_holiday_levy := ROUND(v_levy_slab.base_amt + ((v_holiday - v_levy_slab.over_amt + 0.01) * v_levy_slab.tax_rate), 2);
          END IF;
        END IF;
        v_employee_levy := v_employee_levy + v_holiday_levy;
      END IF;
    END IF;
    
    v_employer_levy_base := v_taxable_wages;
    IF v_bonus_eligible AND v_bonus_include_in_levy THEN v_employer_levy_base := v_employer_levy_base + v_bonus; END IF;
    IF v_holiday > 0 AND NOT (v_hp_eligible AND v_hp_levy_include) THEN
      v_employer_levy_base := v_employer_levy_base - v_holiday;
    END IF;
    v_employer_levy := ROUND(v_employer_levy_base * v_config.employer_levy_rate, 2);
    
    v_severance_base := v_taxable_wages;
    IF v_bonus_eligible AND (v_bp_include_in_severance OR v_bp_contrib_severance) THEN v_severance_base := v_severance_base + v_bonus; END IF;
    IF v_holiday > 0 AND NOT (v_hp_eligible AND v_hp_include_severance) THEN
      v_severance_base := v_severance_base - v_holiday;
    END IF;
    v_employer_severance := ROUND(v_severance_base * v_config.employer_severance_rate, 2);
    
    v_employee_result := jsonb_build_object(
      'ssn', v_employee->>'ssn', 'name', v_employee->>'name',
      'totalWages', v_total_wages, 'taxableWages', v_taxable_wages,
      'employeeAge', v_employee_age,
      'isAgeExemptSS', v_is_age_exempt_ss, 'isAgeExemptLevy', v_is_age_exempt_levy,
      'ssWageBase', v_ss_wage_base, 'ssInsurable', v_ss_insurable,
      'employeeSS', v_employee_ss, 'employerSS', v_employer_ss,
      'employerEIB', v_employer_eib, 'employerSSTotal', v_employer_ss_total,
      'employeeLevy', v_employee_levy, 'bonusLevy', v_bonus_levy,
      'holidayLevy', v_holiday_levy,
      'employerLevy', v_employer_levy, 'employerSeverance', v_employer_severance,
      'periodGross', v_total_wages,
      'totalWagesPlusEmployeeLevyPlusSS', v_total_wages + v_employee_levy + v_employee_ss,
      'employersThreePercentLevyPlusSS', v_employer_levy + v_employer_ss_total,
      'employersOnePercentSeverancePay', v_employer_severance,
      'holidayPolicyApplied', CASE WHEN v_hp_policy IS NOT NULL AND v_hp_eligible THEN v_hp_policy->>'id' ELSE NULL END,
      'holidayPolicyType', CASE WHEN v_hp_policy IS NOT NULL THEN v_hp_policy_type ELSE NULL END,
      'holidayDistribution', COALESCE(v_holiday_distribution, NULL)
    );
    
    v_employees_result := v_employees_result || v_employee_result;
    v_sum_period_gross := v_sum_period_gross + v_total_wages;
    v_sum_taxable_wages := v_sum_taxable_wages + v_taxable_wages;
    v_sum_employee_ss := v_sum_employee_ss + v_employee_ss;
    v_sum_employer_ss := v_sum_employer_ss + v_employer_ss_total;
    v_sum_employee_levy := v_sum_employee_levy + v_employee_levy;
    v_sum_employer_levy := v_sum_employer_levy + v_employer_levy;
    v_sum_employer_severance := v_sum_employer_severance + v_employer_severance;
  END LOOP;
  
  IF v_delay_periods > 0 THEN
    v_levy_penalty_base := COALESCE(v_sum_employee_levy, 0) + COALESCE(v_sum_employer_levy, 0);
    v_levy_penalty := ROUND(
      v_levy_penalty_base * v_config.levy_penalty_initial_rate * v_initial_penalty_periods +
      v_levy_penalty_base * v_config.levy_penalty_subsequent_rate * v_subsequent_penalty_periods, 2);
    v_severance_penalty_base := COALESCE(v_sum_employer_severance, 0);
    v_severance_penalty := ROUND(
      v_severance_penalty_base * v_config.severance_penalty_initial_rate * v_initial_penalty_periods +
      v_severance_penalty_base * v_config.severance_penalty_subsequent_rate * v_subsequent_penalty_periods, 2);
    v_ss_fine_base := COALESCE(v_sum_employee_ss, 0) + COALESCE(v_sum_employer_ss, 0);
    v_ss_fine := ROUND(
      v_ss_fine_base * v_config.ss_fine_initial_rate * v_initial_penalty_periods +
      v_ss_fine_base * COALESCE(v_config.ss_fine_subsequent_rate, v_config.ss_fine_initial_rate) * v_subsequent_penalty_periods, 2);
    v_total_late_charges := v_levy_penalty + v_severance_penalty + v_ss_fine;
  END IF;
  
  v_totals := jsonb_build_object(
    'periodGross', ROUND(v_sum_period_gross, 2),
    'taxableWages', ROUND(v_sum_taxable_wages, 2),
    'employeeSS', ROUND(v_sum_employee_ss, 2),
    'employerSS', ROUND(v_sum_employer_ss, 2),
    'employeeLevy', ROUND(v_sum_employee_levy, 2),
    'employerLevy', ROUND(v_sum_employer_levy, 2),
    'employerSeverance', ROUND(v_sum_employer_severance, 2),
    'totalWagesPlusEmployeeLevyPlusSS', ROUND(v_sum_period_gross + v_sum_employee_levy + v_sum_employee_ss, 2),
    'employersThreePercentLevyPlusSS', ROUND(v_sum_employer_levy + v_sum_employer_ss, 2),
    'employersOnePercentSeverancePay', ROUND(v_sum_employer_severance, 2),
    'dueDate', v_due_date,
    'filingDeadline', v_filing_deadline,
    'daysLate', v_days_late,
    'additional30DayPeriods', v_additional_30_periods,
    'monthsLate', v_months_late_calendar,
    'delayPeriods', v_delay_periods,
    'initialPenaltyPeriods', v_initial_penalty_periods,
    'subsequentPenaltyPeriods', v_subsequent_penalty_periods,
    'filingWindowUnit', CASE WHEN v_filing_window_unit = 1 THEN 'Months' ELSE 'Days' END,
    'filingWindowValue', v_filing_window_value,
    'penaltyInitialThreshold', v_penalty_initial_threshold,
    'penaltySubsequentThreshold', v_penalty_subsequent_threshold,
    'weekStartDay', v_week_start_day,
    'levyPenaltyBase', v_levy_penalty_base,
    'severancePenaltyBase', v_severance_penalty_base,
    'ssFinBase', v_ss_fine_base,
    'levyPenalty', v_levy_penalty,
    'severancePenalty', v_severance_penalty,
    'ssFine', v_ss_fine,
    'totalLateCharges', v_total_late_charges
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'config', jsonb_build_object(
      'periodId', v_config.config_period_id,
      'startDate', v_config.start_date,
      'endDate', v_config.end_date,
      'minAgeSS', v_config.min_age_ss,
      'maxAgeSS', v_config.max_age_ss,
      'minAgeLevy', v_config.min_age_levy,
      'maxAgeLevy', v_config.max_age_levy,
      'employeeSSRate', v_config.employee_ss_rate,
      'employeeSSMaxWage', v_config.employee_ss_max_wage,
      'employerSSRate', v_config.employer_ss_rate,
      'employerEIBRate', v_config.employer_eib_rate,
      'employerLevyRate', v_config.employer_levy_rate,
      'employerSeveranceRate', v_config.employer_severance_rate
    ),
    'employees', v_employees_result,
    'totals', v_totals
  );
  
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;
CREATE OR REPLACE FUNCTION public.calculate_c3_contributions_with_other_payments(p_period_year integer, p_period_month integer, p_received_date date, p_employee_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base jsonb;
  v_period_date date;
  v_config record;

  v_input_employees jsonb := COALESCE(p_employee_data, '[]'::jsonb);
  v_transformed_employees jsonb := '[]'::jsonb;
  v_employees jsonb;
  v_totals jsonb;

  v_i integer;
  v_j integer;

  v_input_employee jsonb;
  v_transformed_employee jsonb;
  v_base_employee jsonb;
  v_other_payments jsonb;
  v_payment jsonb;
  v_calc jsonb;
  v_policy jsonb;

  v_income_code_id_text text;
  v_code_label text;
  v_amount_text text;
  v_payment_amount numeric;
  v_seen_codes text[];

  v_week1 numeric;
  v_week2 numeric;
  v_week3 numeric;
  v_week4 numeric;
  v_week5 numeric;
  v_target_week integer;

  v_emp_merge_amount numeric;
  v_emp_op_amount numeric;
  v_emp_op_employee_ss numeric;
  v_emp_op_employee_levy numeric;
  v_emp_op_employer_ss numeric;
  v_emp_op_employer_eib numeric;
  v_emp_op_employer_levy numeric;
  v_emp_op_employer_severance numeric;

  v_adj_total_wages numeric;
  v_adj_employee_ss numeric;
  v_adj_employee_levy numeric;
  v_adj_employer_ss numeric;
  v_adj_employer_eib numeric;
  v_adj_employer_ss_total numeric;
  v_adj_employer_levy numeric;
  v_adj_employer_severance numeric;

  v_sum_period_gross numeric;
  v_sum_employee_ss numeric;
  v_sum_employer_ss numeric;
  v_sum_employee_levy numeric;
  v_sum_employer_levy numeric;
  v_sum_employer_severance numeric;

  v_op_total_merged_amount numeric := 0;
  v_op_total_separate_amount numeric := 0;
  v_op_total_employee_ss numeric := 0;
  v_op_total_employee_levy numeric := 0;
  v_op_total_employer_ss numeric := 0;
  v_op_total_employer_eib numeric := 0;
  v_op_total_employer_levy numeric := 0;
  v_op_total_employer_severance numeric := 0;

  v_months_late integer;
  v_levy_penalty_base numeric := 0;
  v_severance_penalty_base numeric := 0;
  v_ss_fine_base numeric := 0;
  v_levy_penalty numeric := 0;
  v_severance_penalty numeric := 0;
  v_ss_fine numeric := 0;
  v_total_late_charges numeric := 0;
BEGIN
  IF jsonb_typeof(v_input_employees) <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Employee payload must be a JSON array');
  END IF;

  IF jsonb_array_length(v_input_employees) = 0 THEN
    RETURN public.calculate_c3_contributions(
      p_period_year,
      p_period_month,
      p_received_date,
      v_input_employees
    );
  END IF;

  -- Pass 1: validate + merge eligible other-payments into the last week payment base.
  FOR v_i IN 0..jsonb_array_length(v_input_employees) - 1 LOOP
    v_input_employee := v_input_employees->v_i;

    v_week1 := COALESCE((v_input_employee->>'week1')::numeric, (v_input_employee->'weeklyWages'->>0)::numeric, 0);
    v_week2 := COALESCE((v_input_employee->>'week2')::numeric, (v_input_employee->'weeklyWages'->>1)::numeric, 0);
    v_week3 := COALESCE((v_input_employee->>'week3')::numeric, (v_input_employee->'weeklyWages'->>2)::numeric, 0);
    v_week4 := COALESCE((v_input_employee->>'week4')::numeric, (v_input_employee->'weeklyWages'->>3)::numeric, 0);
    v_week5 := COALESCE((v_input_employee->>'week5')::numeric, (v_input_employee->'weeklyWages'->>4)::numeric, 0);

    v_seen_codes := ARRAY[]::text[];
    v_other_payments := COALESCE(v_input_employee->'otherPayments', '[]'::jsonb);

    IF jsonb_typeof(v_other_payments) = 'array' AND jsonb_array_length(v_other_payments) > 0 THEN
      FOR v_j IN 0..jsonb_array_length(v_other_payments) - 1 LOOP
        v_payment := v_other_payments->v_j;

        v_income_code_id_text := NULLIF(TRIM(COALESCE(v_payment->>'income_code_id', '')), '');
        IF v_income_code_id_text IS NULL THEN
          CONTINUE;
        END IF;

        v_code_label := COALESCE(NULLIF(TRIM(COALESCE(v_payment->>'income_code', '')), ''), v_income_code_id_text);

        IF v_income_code_id_text = ANY(v_seen_codes) THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('Duplicate income code "%s" is not allowed in Other Payments for SSN %s', v_code_label, COALESCE(v_input_employee->>'ssn', 'N/A'))
          );
        END IF;
        v_seen_codes := array_append(v_seen_codes, v_income_code_id_text);

        v_amount_text := TRIM(COALESCE(v_payment->>'amount', ''));
        IF v_amount_text = '' OR v_amount_text !~ '^\d+(\.\d+)?$' THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('Invalid amount for income code "%s". Amount must be numeric and non-negative.', v_code_label)
          );
        END IF;

        v_payment_amount := v_amount_text::numeric;
        IF v_payment_amount <= 0 THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('Amount for income code "%s" must be greater than zero.', v_code_label)
          );
        END IF;

        v_policy := public.get_income_code_policy_for_period(
          v_income_code_id_text::uuid,
          p_period_year,
          p_period_month
        );

        IF v_policy IS NULL OR COALESCE((v_policy->>'found')::boolean, false) = false THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('No active policy configured for income code "%s" in selected period.', v_code_label)
          );
        END IF;

        IF COALESCE((v_policy->>'affects_last_week_payment')::boolean, false) THEN
          IF COALESCE(v_week5, 0) > 0 THEN
            v_target_week := 5;
          ELSIF COALESCE(v_week4, 0) > 0 THEN
            v_target_week := 4;
          ELSIF COALESCE(v_week3, 0) > 0 THEN
            v_target_week := 3;
          ELSIF COALESCE(v_week2, 0) > 0 THEN
            v_target_week := 2;
          ELSE
            v_target_week := 5;
          END IF;

          CASE v_target_week
            WHEN 1 THEN v_week1 := COALESCE(v_week1, 0) + v_payment_amount;
            WHEN 2 THEN v_week2 := COALESCE(v_week2, 0) + v_payment_amount;
            WHEN 3 THEN v_week3 := COALESCE(v_week3, 0) + v_payment_amount;
            WHEN 4 THEN v_week4 := COALESCE(v_week4, 0) + v_payment_amount;
            ELSE v_week5 := COALESCE(v_week5, 0) + v_payment_amount;
          END CASE;
        END IF;
      END LOOP;
    END IF;

    v_transformed_employee := v_input_employee || jsonb_build_object(
      'week1', ROUND(COALESCE(v_week1, 0), 2),
      'week2', ROUND(COALESCE(v_week2, 0), 2),
      'week3', ROUND(COALESCE(v_week3, 0), 2),
      'week4', ROUND(COALESCE(v_week4, 0), 2),
      'week5', ROUND(COALESCE(v_week5, 0), 2)
    );

    v_transformed_employees := v_transformed_employees || jsonb_build_array(v_transformed_employee);
  END LOOP;

  -- Recalculate statutory components on transformed wage base.
  v_base := public.calculate_c3_contributions(
    p_period_year,
    p_period_month,
    p_received_date,
    v_transformed_employees
  );

  IF v_base IS NULL OR COALESCE((v_base->>'success')::boolean, false) = false THEN
    RETURN COALESCE(v_base, jsonb_build_object('success', false, 'error', 'Base calculation failed'));
  END IF;

  v_period_date := make_date(p_period_year, p_period_month + 1, 1);
  SELECT * INTO v_config FROM public.get_c3_config_for_period(v_period_date) LIMIT 1;
  IF v_config IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active C3 configuration found for selected period');
  END IF;

  v_employees := COALESCE(v_base->'employees', '[]'::jsonb);
  v_totals := COALESCE(v_base->'totals', '{}'::jsonb);

  v_sum_period_gross := COALESCE((v_totals->>'periodGross')::numeric, 0);
  v_sum_employee_ss := COALESCE((v_totals->>'employeeSS')::numeric, 0);
  v_sum_employer_ss := COALESCE((v_totals->>'employerSS')::numeric, 0);
  v_sum_employee_levy := COALESCE((v_totals->>'employeeLevy')::numeric, 0);
  v_sum_employer_levy := COALESCE((v_totals->>'employerLevy')::numeric, 0);
  v_sum_employer_severance := COALESCE((v_totals->>'employerSeverance')::numeric, 0);

  -- Pass 2: add only non-merge (separate) policy contributions after base recomputation.
  FOR v_i IN 0..jsonb_array_length(v_input_employees) - 1 LOOP
    v_input_employee := v_input_employees->v_i;
    v_base_employee := COALESCE(v_employees->v_i, '{}'::jsonb);

    v_seen_codes := ARRAY[]::text[];
    v_emp_merge_amount := 0;
    v_emp_op_amount := 0;
    v_emp_op_employee_ss := 0;
    v_emp_op_employee_levy := 0;
    v_emp_op_employer_ss := 0;
    v_emp_op_employer_eib := 0;
    v_emp_op_employer_levy := 0;
    v_emp_op_employer_severance := 0;

    v_other_payments := COALESCE(v_input_employee->'otherPayments', '[]'::jsonb);

    IF jsonb_typeof(v_other_payments) = 'array' AND jsonb_array_length(v_other_payments) > 0 THEN
      FOR v_j IN 0..jsonb_array_length(v_other_payments) - 1 LOOP
        v_payment := v_other_payments->v_j;

        v_income_code_id_text := NULLIF(TRIM(COALESCE(v_payment->>'income_code_id', '')), '');
        IF v_income_code_id_text IS NULL THEN
          CONTINUE;
        END IF;

        IF v_income_code_id_text = ANY(v_seen_codes) THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('Duplicate income code detected in Other Payments for SSN %s', COALESCE(v_input_employee->>'ssn', 'N/A'))
          );
        END IF;
        v_seen_codes := array_append(v_seen_codes, v_income_code_id_text);

        v_amount_text := TRIM(COALESCE(v_payment->>'amount', ''));
        IF v_amount_text = '' OR v_amount_text !~ '^\d+(\.\d+)?$' THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('Invalid amount detected for SSN %s in Other Payments', COALESCE(v_input_employee->>'ssn', 'N/A'))
          );
        END IF;

        v_payment_amount := v_amount_text::numeric;
        IF v_payment_amount <= 0 THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('Amount must be greater than zero for SSN %s in Other Payments', COALESCE(v_input_employee->>'ssn', 'N/A'))
          );
        END IF;

        v_policy := public.get_income_code_policy_for_period(
          v_income_code_id_text::uuid,
          p_period_year,
          p_period_month
        );

        IF v_policy IS NULL OR COALESCE((v_policy->>'found')::boolean, false) = false THEN
          RETURN jsonb_build_object(
            'success', false,
            'error', format('No active policy for income code %s', v_income_code_id_text)
          );
        END IF;

        IF COALESCE((v_policy->>'affects_last_week_payment')::boolean, false) THEN
          v_emp_merge_amount := v_emp_merge_amount + v_payment_amount;
          CONTINUE;
        END IF;

        v_calc := public.calculate_other_payment_components(
          v_income_code_id_text::uuid,
          p_period_year,
          p_period_month,
          v_payment_amount
        );

        IF COALESCE((v_calc->>'success')::boolean, false)
           AND COALESCE((v_calc->>'found')::boolean, false) THEN
          v_emp_op_amount := v_emp_op_amount + COALESCE((v_calc->>'amount')::numeric, 0);
          v_emp_op_employee_ss := v_emp_op_employee_ss + COALESCE((v_calc->>'employee_ss')::numeric, 0);
          v_emp_op_employee_levy := v_emp_op_employee_levy + COALESCE((v_calc->>'employee_levy')::numeric, 0);
          v_emp_op_employer_ss := v_emp_op_employer_ss + COALESCE((v_calc->>'employer_ss')::numeric, 0);
          v_emp_op_employer_eib := v_emp_op_employer_eib + COALESCE((v_calc->>'employer_eib')::numeric, 0);
          v_emp_op_employer_levy := v_emp_op_employer_levy + COALESCE((v_calc->>'employer_levy')::numeric, 0);
          v_emp_op_employer_severance := v_emp_op_employer_severance + COALESCE((v_calc->>'employer_severance')::numeric, 0);
        ELSE
          RETURN jsonb_build_object(
            'success', false,
            'error', COALESCE(v_calc->>'error', format('Other payment calculation failed for income code %s', v_income_code_id_text))
          );
        END IF;
      END LOOP;
    END IF;

    IF v_i < jsonb_array_length(v_employees) THEN
      v_adj_total_wages := COALESCE((v_base_employee->>'totalWages')::numeric, 0) + v_emp_op_amount;
      v_adj_employee_ss := COALESCE((v_base_employee->>'employeeSS')::numeric, 0) + v_emp_op_employee_ss;
      v_adj_employee_levy := COALESCE((v_base_employee->>'employeeLevy')::numeric, 0) + v_emp_op_employee_levy;
      v_adj_employer_ss := COALESCE((v_base_employee->>'employerSS')::numeric, 0) + v_emp_op_employer_ss;
      v_adj_employer_eib := COALESCE((v_base_employee->>'employerEIB')::numeric, 0) + v_emp_op_employer_eib;
      v_adj_employer_ss_total := COALESCE((v_base_employee->>'employerSSTotal')::numeric, 0) + v_emp_op_employer_ss + v_emp_op_employer_eib;
      v_adj_employer_levy := COALESCE((v_base_employee->>'employerLevy')::numeric, 0) + v_emp_op_employer_levy;
      v_adj_employer_severance := COALESCE((v_base_employee->>'employerSeverance')::numeric, 0) + v_emp_op_employer_severance;

      v_base_employee := v_base_employee || jsonb_build_object(
        'otherPaymentAmount', ROUND(v_emp_merge_amount + v_emp_op_amount, 2),
        'otherPaymentMergedIntoLastWeek', ROUND(v_emp_merge_amount, 2),
        'otherPaymentSeparateAmount', ROUND(v_emp_op_amount, 2),
        'otherPaymentEmployeeSS', ROUND(v_emp_op_employee_ss, 2),
        'otherPaymentEmployeeLevy', ROUND(v_emp_op_employee_levy, 2),
        'otherPaymentEmployerSS', ROUND(v_emp_op_employer_ss, 2),
        'otherPaymentEmployerEIB', ROUND(v_emp_op_employer_eib, 2),
        'otherPaymentEmployerLevy', ROUND(v_emp_op_employer_levy, 2),
        'otherPaymentEmployerSeverance', ROUND(v_emp_op_employer_severance, 2),
        'totalWages', ROUND(v_adj_total_wages, 2),
        'periodGross', ROUND(v_adj_total_wages, 2),
        'employeeSS', ROUND(v_adj_employee_ss, 2),
        'employeeLevy', ROUND(v_adj_employee_levy, 2),
        'employerSS', ROUND(v_adj_employer_ss, 2),
        'employerEIB', ROUND(v_adj_employer_eib, 2),
        'employerSSTotal', ROUND(v_adj_employer_ss_total, 2),
        'employerLevy', ROUND(v_adj_employer_levy, 2),
        'employerSeverance', ROUND(v_adj_employer_severance, 2),
        'totalWagesPlusEmployeeLevyPlusSS', ROUND(v_adj_total_wages + v_adj_employee_levy + v_adj_employee_ss, 2),
        'employersThreePercentLevyPlusSS', ROUND(v_adj_employer_levy + v_adj_employer_ss_total, 2),
        'employersOnePercentSeverancePay', ROUND(v_adj_employer_severance, 2)
      );

      v_employees := jsonb_set(v_employees, ARRAY[v_i::text], v_base_employee, true);
    END IF;

    v_op_total_merged_amount := v_op_total_merged_amount + v_emp_merge_amount;
    v_op_total_separate_amount := v_op_total_separate_amount + v_emp_op_amount;
    v_op_total_employee_ss := v_op_total_employee_ss + v_emp_op_employee_ss;
    v_op_total_employee_levy := v_op_total_employee_levy + v_emp_op_employee_levy;
    v_op_total_employer_ss := v_op_total_employer_ss + v_emp_op_employer_ss;
    v_op_total_employer_eib := v_op_total_employer_eib + v_emp_op_employer_eib;
    v_op_total_employer_levy := v_op_total_employer_levy + v_emp_op_employer_levy;
    v_op_total_employer_severance := v_op_total_employer_severance + v_emp_op_employer_severance;
  END LOOP;

  -- Base totals already include merged amounts. Add only separate-policy deltas.
  v_sum_period_gross := v_sum_period_gross + v_op_total_separate_amount;
  v_sum_employee_ss := v_sum_employee_ss + v_op_total_employee_ss;
  v_sum_employer_ss := v_sum_employer_ss + v_op_total_employer_ss + v_op_total_employer_eib;
  v_sum_employee_levy := v_sum_employee_levy + v_op_total_employee_levy;
  v_sum_employer_levy := v_sum_employer_levy + v_op_total_employer_levy;
  v_sum_employer_severance := v_sum_employer_severance + v_op_total_employer_severance;

  v_months_late := COALESCE((v_totals->>'monthsLate')::integer, 0);

  IF v_months_late > 0 THEN
    v_levy_penalty_base := COALESCE(v_sum_employee_levy, 0) + COALESCE(v_sum_employer_levy, 0);
    v_levy_penalty := ROUND(
      v_levy_penalty_base * COALESCE(v_config.levy_penalty_initial_rate, 0)::numeric +
      v_levy_penalty_base * COALESCE(v_config.levy_penalty_subsequent_rate, 0)::numeric * GREATEST(v_months_late - 1, 0),
      2
    );

    v_severance_penalty_base := COALESCE(v_sum_employer_severance, 0);
    v_severance_penalty := ROUND(
      v_severance_penalty_base * COALESCE(v_config.severance_penalty_initial_rate, 0)::numeric +
      v_severance_penalty_base * COALESCE(v_config.severance_penalty_subsequent_rate, 0)::numeric * GREATEST(v_months_late - 1, 0),
      2
    );

    v_ss_fine_base := COALESCE(v_sum_employee_ss, 0) + COALESCE(v_sum_employer_ss, 0);
    v_ss_fine := ROUND(
      v_ss_fine_base * COALESCE(v_config.ss_fine_initial_rate, 0)::numeric +
      v_ss_fine_base * COALESCE(v_config.ss_fine_subsequent_rate, v_config.ss_fine_initial_rate, 0)::numeric * GREATEST(v_months_late - 1, 0),
      2
    );

    v_total_late_charges := v_levy_penalty + v_severance_penalty + v_ss_fine;
  END IF;

  v_totals := v_totals || jsonb_build_object(
    'periodGross', ROUND(v_sum_period_gross, 2),
    'employeeSS', ROUND(v_sum_employee_ss, 2),
    'employerSS', ROUND(v_sum_employer_ss, 2),
    'employeeLevy', ROUND(v_sum_employee_levy, 2),
    'employerLevy', ROUND(v_sum_employer_levy, 2),
    'employerSeverance', ROUND(v_sum_employer_severance, 2),
    'totalWagesPlusEmployeeLevyPlusSS', ROUND(v_sum_period_gross + v_sum_employee_levy + v_sum_employee_ss, 2),
    'employersThreePercentLevyPlusSS', ROUND(v_sum_employer_levy + v_sum_employer_ss, 2),
    'employersOnePercentSeverancePay', ROUND(v_sum_employer_severance, 2),
    'levyPenaltyBase', ROUND(v_levy_penalty_base, 2),
    'severancePenaltyBase', ROUND(v_severance_penalty_base, 2),
    'ssFinBase', ROUND(v_ss_fine_base, 2),
    'levyPenalty', ROUND(v_levy_penalty, 2),
    'severancePenalty', ROUND(v_severance_penalty, 2),
    'ssFine', ROUND(v_ss_fine, 2),
    'totalLateCharges', ROUND(v_total_late_charges, 2)
  );

  RETURN v_base || jsonb_build_object(
    'employees', v_employees,
    'totals', v_totals,
    'otherPaymentsTotals', jsonb_build_object(
      'amount', ROUND(v_op_total_merged_amount + v_op_total_separate_amount, 2),
      'mergedIntoLastWeek', ROUND(v_op_total_merged_amount, 2),
      'separateAmount', ROUND(v_op_total_separate_amount, 2),
      'employeeSS', ROUND(v_op_total_employee_ss, 2),
      'employeeLevy', ROUND(v_op_total_employee_levy, 2),
      'employerSS', ROUND(v_op_total_employer_ss, 2),
      'employerEIB', ROUND(v_op_total_employer_eib, 2),
      'employerLevy', ROUND(v_op_total_employer_levy, 2),
      'employerSeverance', ROUND(v_op_total_employer_severance, 2)
    )
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;
CREATE OR REPLACE FUNCTION public.calculate_historical_risk_adjustment(p_function_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  adjustment NUMERIC := 0;
  high_count INTEGER := 0;
  medium_count INTEGER := 0;
  low_count INTEGER := 0;
BEGIN
  -- Count findings from closed audits linked to this function's department
  SELECT
    COALESCE(SUM(CASE WHEN f.risk_rating = 'High' THEN 1 ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN f.risk_rating = 'Medium' THEN 1 ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN f.risk_rating = 'Low' THEN 1 ELSE 0 END), 0)
  INTO high_count, medium_count, low_count
  FROM ia_findings f
  JOIN ia_department_audits da ON f.department_audit_id = da.id
  JOIN ia_department_functions df ON df.department_id = da.department_id
  WHERE df.id = p_function_id
    AND f.status = 'Closed';

  adjustment := (high_count * 5) + (medium_count * 3) + (low_count * 1);
  RETURN adjustment;
END;
$function$;
CREATE OR REPLACE FUNCTION public.calculate_other_payment_components(p_income_code_id uuid, p_period_year integer, p_period_month integer, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy jsonb;
  v_config record;
  v_period_date date;
  v_employee_ss numeric := 0;
  v_employee_levy numeric := 0;
  v_employer_ss numeric := 0;
  v_employer_eib numeric := 0;
  v_employer_levy numeric := 0;
  v_employer_severance numeric := 0;
BEGIN
  IF p_income_code_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'found', false,
      'error', 'Income code is required'
    );
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'found', false,
      'error', 'Amount must be greater than zero'
    );
  END IF;

  v_period_date := make_date(p_period_year, p_period_month + 1, 1);

  v_policy := public.get_income_code_policy_for_period(
    p_income_code_id,
    p_period_year,
    p_period_month
  );

  IF v_policy IS NULL OR COALESCE((v_policy->>'found')::boolean, false) = false THEN
    RETURN jsonb_build_object(
      'success', false,
      'found', false,
      'error', COALESCE(v_policy->>'error', 'No active policy configured for this income code and period')
    );
  END IF;

  SELECT *
  INTO v_config
  FROM public.get_c3_config_for_period(v_period_date)
  LIMIT 1;

  IF v_config IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'found', false,
      'error', 'No active C3 configuration found for selected period'
    );
  END IF;

  v_employee_ss := CASE
    WHEN COALESCE((v_policy->>'ssc_contrib_employee')::boolean, false)
      THEN ROUND(p_amount * COALESCE(v_config.employee_ss_rate, 0)::numeric, 2)
    ELSE 0
  END;

  v_employee_levy := CASE
    WHEN COALESCE((v_policy->>'levy_include')::boolean, false)
      THEN ROUND(p_amount * COALESCE(v_config.employer_levy_rate, 0)::numeric, 2)
    ELSE 0
  END;

  v_employer_ss := CASE
    WHEN COALESCE((v_policy->>'ssc_contrib_employer')::boolean, false)
      THEN ROUND(p_amount * COALESCE(v_config.employer_ss_rate, 0)::numeric, 2)
    ELSE 0
  END;

  v_employer_eib := CASE
    WHEN COALESCE((v_policy->>'contrib_eib')::boolean, false)
      THEN ROUND(p_amount * COALESCE(v_config.employer_eib_rate, 0)::numeric, 2)
    ELSE 0
  END;

  v_employer_levy := CASE
    WHEN COALESCE((v_policy->>'levy_include')::boolean, false)
      THEN ROUND(p_amount * COALESCE(v_config.employer_levy_rate, 0)::numeric, 2)
    ELSE 0
  END;

  v_employer_severance := CASE
    WHEN COALESCE((v_policy->>'include_in_severance')::boolean, false)
      THEN ROUND(p_amount * COALESCE(v_config.employer_severance_rate, 0)::numeric, 2)
    ELSE 0
  END;

  RETURN jsonb_build_object(
    'success', true,
    'found', true,
    'policy_id', v_policy->>'policy_id',
    'policy_type', v_policy->>'policy_type',
    'date_entry_mode', v_policy->>'date_entry_mode',
    'has_exception', COALESCE((v_policy->>'has_exception')::boolean, false),
    'exception_id', v_policy->>'exception_id',
    'levy_include', COALESCE((v_policy->>'levy_include')::boolean, false),
    'ssc_contrib_employee', COALESCE((v_policy->>'ssc_contrib_employee')::boolean, false),
    'ssc_contrib_employer', COALESCE((v_policy->>'ssc_contrib_employer')::boolean, false),
    'contrib_eib', COALESCE((v_policy->>'contrib_eib')::boolean, false),
    'include_in_severance', COALESCE((v_policy->>'include_in_severance')::boolean, false),
    'amount', ROUND(p_amount, 2),
    'employee_ss', v_employee_ss,
    'employee_levy', v_employee_levy,
    'employer_ss', v_employer_ss,
    'employer_eib', v_employer_eib,
    'employer_levy', v_employer_levy,
    'employer_severance', v_employer_severance
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.calculate_vc_avg_weekly_wage(p_ssn character varying, p_date_registered date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config RECORD;
  v_start_date DATE;
  v_end_date DATE;
  v_total_wages NUMERIC(15,2) := 0;
  v_avg_earnings NUMERIC(15,2);
  v_weekly_avg NUMERIC(15,2);
BEGIN
  -- Get VC configuration from renamed table
  SELECT * INTO v_config
  FROM public.tb_vc_eligibility_config
  WHERE is_active = true
    AND effstart <= p_date_registered
    AND (effend IS NULL OR effend >= p_date_registered)
  ORDER BY effstart DESC
  LIMIT 1;
  
  IF v_config IS NULL THEN
    RETURN jsonb_build_object('error', 'Configuration not found');
  END IF;

  v_end_date := p_date_registered;
  v_start_date := p_date_registered - (v_config.wage_history_months || ' months')::INTERVAL;

  SELECT COALESCE(SUM(
    COALESCE(wages_paid1, 0) + COALESCE(wages_paid2, 0) + COALESCE(wages_paid3, 0) + 
    COALESCE(wages_paid4, 0) + COALESCE(wages_paid5, 0) + COALESCE(wages_paid6, 0) + COALESCE(wages_paid7, 0)
  ), 0)
  INTO v_total_wages
  FROM public.ip_wages
  WHERE ssn = p_ssn
    AND period >= v_start_date
    AND period < v_end_date
    AND posting_status = 'VAC';

  v_avg_earnings := ROUND(v_total_wages / 2, 2);
  v_weekly_avg := ROUND(v_avg_earnings / v_config.weeks_per_year, 2);

  RETURN jsonb_build_object(
    'total_wages', v_total_wages,
    'avg_earnings', v_avg_earnings,
    'weekly_avg', v_weekly_avg,
    'start_date', v_start_date,
    'end_date', v_end_date,
    'months_covered', v_config.wage_history_months
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_access_communication_request(_request_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.communication_request r
    WHERE r.id = _request_id
      AND (
        public.is_admin(auth.uid())
        OR public.has_permission(auth.uid(), 'notification_logs', 'view-logs')
        OR public.has_permission(auth.uid(), 'system_administration', 'view')
        OR r.requested_by = auth.uid()
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.can_access_module(_user_id uuid, _module_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Admins can access ALL active modules
  IF public.is_admin(_user_id) THEN
    RETURN true;
  END IF;

  -- Check if user has 'view' permission for this module through any role
  RETURN EXISTS(
    SELECT 1
    FROM app_modules m
    INNER JOIN module_actions ma ON ma.module_id = m.id
    INNER JOIN role_permissions rp ON rp.module_id = m.id AND rp.action_id = ma.id
    INNER JOIN roles r ON r.id = rp.role_id
    INNER JOIN user_roles ur ON ur.role = r.role_name
    WHERE ur.user_id = _user_id
      AND m.name = _module_name
      AND m.is_enabled = true
      AND ma.action_name = 'view'
      AND ma.is_enabled = true
      AND rp.is_granted = true
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.cancel_comm_hub_message(p_message_id uuid, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_msg communication_message%ROWTYPE;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN RAISE EXCEPTION 'actor_user_id required'; END IF;
  IF NOT public.has_role(p_actor_user_id, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden: admin required';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'reason required'; END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id = p_message_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'message not found: %', p_message_id; END IF;
  IF COALESCE(v_msg.origin, '') <> 'comm_hub' THEN
    RAISE EXCEPTION 'refusing to cancel: message origin=% (comm_hub only)', v_msg.origin;
  END IF;
  IF v_msg.status NOT IN ('queued','sending','failed','suppressed') THEN
    RAISE EXCEPTION 'refusing to cancel: status=% (allowed: queued/sending/failed/suppressed)', v_msg.status;
  END IF;

  v_old := jsonb_build_object(
    'status', v_msg.status, 'test_mode', v_msg.test_mode,
    'provider_message_id', v_msg.provider_message_id,
    'locked_at', v_msg.locked_at, 'locked_by', v_msg.locked_by,
    'error_code', v_msg.error_code, 'error_message', v_msg.error_message
  );

  UPDATE public.communication_message
     SET status='cancelled',
         error_code=COALESCE(NULLIF(error_code,''),'CANCELLED_BY_ADMIN'),
         error_message=left(p_reason, 1000),
         locked_at=NULL, locked_by=NULL, updated_at=now()
   WHERE id = p_message_id;

  v_new := jsonb_build_object('status','cancelled','cancelled_by',p_actor_user_id,'cancelled_at',now());

  INSERT INTO public.communication_event_log
    (message_id, request_id, event_type, source, payload, actor_user_id)
  VALUES
    (v_msg.id, v_msg.request_id, 'cancelled', 'cancel_comm_hub_message',
     jsonb_build_object('stage','MESSAGE_CANCELLED_BY_ADMIN','reason',p_reason,'actor',p_actor_user_id,
                        'previous_status',v_msg.status),
     p_actor_user_id);

  INSERT INTO public.communication_hub_control_audit
    (setting_key, old_value, new_value, reason, changed_by, source)
  VALUES
    ('message_cancelled:' || p_message_id::text, v_old, v_new, p_reason, p_actor_user_id, 'cancel_comm_hub_message');

  BEGIN
    PERFORM public.recompute_communication_request_status(v_msg.request_id);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('ok', true, 'message_id', p_message_id,
                            'request_id', v_msg.request_id,
                            'previous_status', v_msg.status, 'new_status', 'cancelled');
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_actor_can(_user_id uuid, _capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_caps text[];
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF public.is_admin(_user_id) THEN RETURN true; END IF;

  v_role := public.ce_compliance_role(_user_id);

  v_caps := CASE v_role
    WHEN 'head' THEN ARRAY[
      'compliance.field.execute','compliance.field.plan','compliance.field.approve_plans',
      'compliance.field.report','compliance.field.approve_reports','compliance.field.sampling',
      'compliance.violations.manage','compliance.violations.link_to_case',
      'compliance.cases.manage','compliance.cases.approve_requests',
      'compliance.cases.view_confidential_documents','compliance.inspections.view_employer_history',
      'compliance.enforcement.notices','compliance.enforcement.arrangements',
      'compliance.enforcement.legal','compliance.workbench.team','compliance.workbench.enterprise',
      'compliance.reports.operational','compliance.reports.analytics']
    WHEN 'senior' THEN ARRAY[
      'compliance.field.execute','compliance.field.plan','compliance.field.approve_plans',
      'compliance.field.report','compliance.field.approve_reports','compliance.field.sampling',
      'compliance.violations.manage','compliance.violations.link_to_case',
      'compliance.cases.manage','compliance.inspections.view_employer_history',
      'compliance.enforcement.notices','compliance.enforcement.arrangements',
      'compliance.enforcement.legal','compliance.workbench.team','compliance.reports.operational']
    WHEN 'inspector' THEN ARRAY[
      'compliance.field.execute','compliance.field.plan','compliance.field.report',
      'compliance.violations.manage','compliance.cases.manage',
      'compliance.enforcement.notices','compliance.reports.operational']
    ELSE ARRAY[]::text[]
  END;

  IF _capability = ANY (v_caps) THEN RETURN true; END IF;

  -- Legacy module/action fallback (never weaker: only widens for explicit grants)
  RETURN public.has_permission(_user_id, 'manage_compliance',
           CASE WHEN _capability LIKE '%.approve%' THEN 'approve' ELSE 'edit' END);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_actor_user_code(_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(p.user_code, p.employee_code, p.email, _user_id::text)
  FROM public.profiles p WHERE p.id = _user_id
$function$;
CREATE OR REPLACE FUNCTION public.ce_allocate_employer_payment(p_source_payment_id bigint, p_employer_id character varying, p_allocation_mode text DEFAULT 'oldest_due_first'::text, p_triggered_by character varying DEFAULT 'SYSTEM'::character varying, p_effective_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sync RECORD;
  v_debit RECORD;
  v_remaining NUMERIC;
  v_alloc_amount NUMERIC;
  v_seq INT := 0;
  v_allocated_total NUMERIC := 0;
  v_alloc_count INT := 0;
  v_credit_entry_id UUID;
BEGIN
  SELECT * INTO v_sync FROM public.ce_payment_ledger_sync_log
  WHERE source_payment_id = p_source_payment_id AND employer_id = p_employer_id AND sync_status = 'posted'
  LIMIT 1;

  IF v_sync IS NULL THEN
    RETURN jsonb_build_object('error', 'No posted sync record found for this payment');
  END IF;

  SELECT id INTO v_credit_entry_id FROM public.ce_employer_financial_ledger
  WHERE idempotency_key = 'pay-cnpmt-' || p_source_payment_id::text AND entry_type = 'PAYMENT_RECEIVED'
  LIMIT 1;

  v_remaining := v_sync.amount_snapshot - COALESCE(
    (SELECT SUM(allocated_amount) FROM public.ce_payment_allocations
     WHERE source_payment_id = p_source_payment_id AND source_table = v_sync.source_table), 0
  );

  IF v_remaining <= 0 THEN
    RETURN jsonb_build_object('error', 'Payment already fully allocated', 'remaining', v_remaining);
  END IF;

  FOR v_debit IN
    SELECT efl.id, efl.period, efl.fund_type::text, efl.entry_type::text,
           (efl.debit_amount - efl.credit_amount) AS outstanding, efl.posted_at
    FROM public.ce_employer_financial_ledger efl
    WHERE efl.employer_id = p_employer_id
      AND efl.debit_amount > efl.credit_amount
      AND efl.status = 'POSTED'::ce_ledger_status
      AND efl.entry_type IN ('C3_DUES_POSTED','PENALTY_ASSESSED','INTEREST_ACCRUED')
    ORDER BY
      CASE p_allocation_mode
        WHEN 'dues_then_penalty' THEN
          CASE efl.entry_type WHEN 'C3_DUES_POSTED' THEN 1 WHEN 'PENALTY_ASSESSED' THEN 2 WHEN 'INTEREST_ACCRUED' THEN 3 ELSE 4 END
        ELSE 0
      END,
      efl.period ASC, efl.posted_at ASC
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_alloc_amount := LEAST(v_remaining, v_debit.outstanding);
    v_seq := v_seq + 1;

    INSERT INTO public.ce_payment_allocations (
      source_payment_id, source_table, employer_id, ledger_credit_entry_id,
      target_ledger_debit_entry_id, target_type, target_period, fund_type,
      allocated_amount, allocation_sequence, allocation_mode, allocated_by
    ) VALUES (
      p_source_payment_id, v_sync.source_table, p_employer_id, v_credit_entry_id,
      v_debit.id,
      CASE v_debit.entry_type WHEN 'C3_DUES_POSTED' THEN 'dues' WHEN 'PENALTY_ASSESSED' THEN 'penalty' WHEN 'INTEREST_ACCRUED' THEN 'interest' ELSE 'other' END,
      v_debit.period, v_debit.fund_type, v_alloc_amount, v_seq, p_allocation_mode, p_triggered_by
    );

    v_remaining := v_remaining - v_alloc_amount;
    v_allocated_total := v_allocated_total + v_alloc_amount;
    v_alloc_count := v_alloc_count + 1;
  END LOOP;

  UPDATE public.ce_payment_ledger_sync_log
  SET allocation_status = CASE WHEN v_remaining <= 0 THEN 'fully_allocated' ELSE 'partial' END
  WHERE source_payment_id = p_source_payment_id AND source_table = v_sync.source_table AND employer_id = p_employer_id;

  RETURN jsonb_build_object(
    'allocated_count', v_alloc_count, 'allocated_total', v_allocated_total,
    'remaining_unallocated', v_remaining, 'allocation_mode', p_allocation_mode
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_apply_status_transition(p_entity_type text, p_record_id uuid, p_action_code text, p_user_code text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_key TEXT := p_entity_type || '.status.' || p_action_code;
  v_mapping    RECORD;
  v_table      TEXT;
  v_from       TEXT;
  v_to         TEXT;
  v_wf_id      UUID;
  v_baseline_wf UUID;
  v_step_id    UUID;
  v_now        TIMESTAMPTZ := now();
BEGIN
  SELECT id INTO v_baseline_wf
    FROM public.workflow_definitions
   WHERE name = 'CE Status — Trivial Transitions'
   LIMIT 1;

  SELECT * INTO v_mapping
    FROM public.ce_workflow_mappings
   WHERE event_key = v_event_key
   ORDER BY priority ASC
   LIMIT 1;

  IF v_mapping.id IS NOT NULL AND v_mapping.enabled AND v_mapping.workflow_definition_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'mode', 'WORKFLOW_REQUIRED',
      'workflow_definition_id', v_mapping.workflow_definition_id,
      'event_key', v_event_key
    );
  END IF;

  IF v_mapping.id IS NOT NULL AND v_mapping.fallback_behavior = 'BLOCK' THEN
    RAISE EXCEPTION 'Transition % is blocked by workflow mapping.', v_event_key
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_mapping.id IS NOT NULL AND v_mapping.fallback_behavior = 'REQUIRE_NOTE'
     AND (p_notes IS NULL OR length(trim(p_notes)) = 0) THEN
    RAISE EXCEPTION 'A note is required for transition %.', v_event_key
      USING ERRCODE = 'not_null_violation';
  END IF;

  CASE p_entity_type
    WHEN 'violation'             THEN v_table := 'ce_violations';
    WHEN 'case'                  THEN v_table := 'ce_cases';
    WHEN 'notice'                THEN v_table := 'ce_notices';
    WHEN 'inspection'            THEN v_table := 'ce_inspections';
    WHEN 'arrangement'           THEN v_table := 'ce_payment_arrangements';
    WHEN 'waiver'                THEN v_table := 'ce_waivers';
    WHEN 'legal_recommendation'  THEN v_table := 'ce_legal_recommendations';
    WHEN 'legal_referral'        THEN v_table := 'ce_legal_referrals';
    ELSE
      RAISE EXCEPTION 'Unsupported entity_type: %', p_entity_type;
  END CASE;

  EXECUTE format('SELECT status FROM public.%I WHERE id = $1', v_table)
    INTO v_from USING p_record_id;

  IF v_from IS NULL THEN
    RAISE EXCEPTION 'Record % not found in %', p_record_id, v_table;
  END IF;

  v_wf_id := COALESCE(v_mapping.workflow_definition_id, v_baseline_wf);

  SELECT wsa.result_status, ws.id
    INTO v_to, v_step_id
    FROM public.workflow_steps ws
    JOIN public.workflow_step_actions wsa ON wsa.step_id = ws.id
   WHERE ws.workflow_id = v_wf_id
     AND ws.from_status = v_from
     AND wsa.action_code = p_action_code
     AND split_part(ws.step_name, ':', 1) = p_entity_type
   LIMIT 1;

  IF v_to IS NULL THEN
    RAISE EXCEPTION 'Transition % is not allowed from status % for %', p_action_code, v_from, p_entity_type
      USING ERRCODE = 'check_violation';
  END IF;

  EXECUTE format(
    'UPDATE public.%I SET status = $1, updated_by = $2, updated_at = $3 WHERE id = $4',
    v_table
  ) USING v_to, p_user_code, v_now, p_record_id;

  IF p_entity_type = 'violation' THEN
    INSERT INTO public.ce_violation_history
      (violation_id, action, from_value, to_value, notes, performed_by, performed_at)
    VALUES
      (p_record_id, p_action_code, v_from, v_to, p_notes, p_user_code, v_now);
  ELSIF p_entity_type = 'case' THEN
    INSERT INTO public.ce_case_history
      (case_id, action, from_status, to_status, notes, performed_by, performed_at)
    VALUES
      (p_record_id, p_action_code, v_from, v_to, p_notes, p_user_code, v_now);
  END IF;

  INSERT INTO public.system_audit_trail
    (action, module, entity_type, entity_id, severity, payload_json, user_name, timestamp)
  VALUES
    ('ce.status_transition',
     'Compliance',
     p_entity_type,
     p_record_id::text,
     'info',
     jsonb_build_object(
       'event_key', v_event_key,
       'from_status', v_from,
       'to_status', v_to,
       'action_code', p_action_code,
       'notes', p_notes
     ),
     p_user_code,
     v_now);

  RETURN jsonb_build_object(
    'mode', 'APPLIED',
    'from_status', v_from,
    'to_status', v_to,
    'event_key', v_event_key
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.ce_batch_recompute_compliance(p_employer_ids character varying[] DEFAULT NULL::character varying[], p_territory character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 500, p_triggered_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_emp RECORD; v_processed INT := 0; v_failed INT := 0;
  v_errors JSONB := '[]'::jsonb;
BEGIN
  FOR v_emp IN
    SELECT regno FROM public.er_master
    WHERE (p_employer_ids IS NULL OR regno = ANY(p_employer_ids))
      AND (p_territory IS NULL OR village_code = p_territory)
    ORDER BY regno LIMIT p_limit
  LOOP
    BEGIN
      PERFORM public.ce_recompute_employer_compliance(v_emp.regno, p_triggered_by);
      PERFORM public.ce_recompute_employer_risk(v_emp.regno, p_triggered_by);
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_errors := v_errors || jsonb_build_object('employer_id', v_emp.regno, 'error', SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('processed', v_processed, 'failed', v_failed, 'errors', v_errors, 'completed_at', now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_breach_check_arrangements(p_as_of_date date DEFAULT CURRENT_DATE, p_checked_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS TABLE(arrangement_id uuid, arrangement_number character varying, employer_id character varying, missed_count bigint, total_overdue numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH overdue_installments AS (
    SELECT 
      i.arrangement_id,
      COUNT(*) AS missed_count,
      SUM(i.amount_due - COALESCE(i.amount_paid, 0)) AS total_overdue
    FROM ce_installments i
    JOIN ce_payment_arrangements pa ON i.arrangement_id = pa.id
    WHERE pa.status = 'Active'
      AND i.status IN ('Pending', 'Overdue')
      AND i.due_date < p_as_of_date
    GROUP BY i.arrangement_id
    HAVING COUNT(*) >= 1
  )
  SELECT 
    oi.arrangement_id,
    pa.arrangement_number,
    pa.employer_id,
    oi.missed_count,
    oi.total_overdue
  FROM overdue_installments oi
  JOIN ce_payment_arrangements pa ON oi.arrangement_id = pa.id
  -- Only flag if not already breached
  WHERE NOT EXISTS (
    SELECT 1 FROM ce_arrangement_breaches ab
    WHERE ab.arrangement_id = oi.arrangement_id
      AND ab.resolution IS NULL
  );

  -- Insert breach records for newly detected breaches
  INSERT INTO ce_arrangement_breaches (arrangement_id, breach_type, description, detected_at, detected_by, created_by)
  SELECT 
    oi.arrangement_id,
    CASE WHEN oi.missed_count >= 3 THEN 'Critical' WHEN oi.missed_count >= 2 THEN 'Major' ELSE 'Minor' END,
    oi.missed_count || ' overdue installment(s) totaling ' || oi.total_overdue,
    now(),
    p_checked_by,
    p_checked_by
  FROM (
    SELECT 
      i.arrangement_id,
      COUNT(*) AS missed_count,
      SUM(i.amount_due - COALESCE(i.amount_paid, 0)) AS total_overdue
    FROM ce_installments i
    JOIN ce_payment_arrangements pa ON i.arrangement_id = pa.id
    WHERE pa.status = 'Active'
      AND i.status IN ('Pending', 'Overdue')
      AND i.due_date < p_as_of_date
    GROUP BY i.arrangement_id
    HAVING COUNT(*) >= 1
  ) oi
  WHERE NOT EXISTS (
    SELECT 1 FROM ce_arrangement_breaches ab
    WHERE ab.arrangement_id = oi.arrangement_id
      AND ab.resolution IS NULL
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_calculate_employer_arrears(p_employer_id character varying)
 RETURNS TABLE(fund_type ce_fund_type, principal_due numeric, penalties numeric, interest numeric, payments numeric, waivers numeric, adjustments numeric, write_offs numeric, net_balance numeric, period_count bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    lp.fund_type,
    COALESCE(SUM(lp.principal_due), 0) AS principal_due,
    COALESCE(SUM(lp.penalties), 0) AS penalties,
    COALESCE(SUM(lp.interest), 0) AS interest,
    COALESCE(SUM(lp.payments), 0) AS payments,
    COALESCE(SUM(lp.waivers), 0) AS waivers,
    COALESCE(SUM(lp.adjustments), 0) AS adjustments,
    COALESCE(SUM(lp.write_offs), 0) AS write_offs,
    COALESCE(SUM(lp.balance), 0) AS net_balance,
    COUNT(*) AS period_count
  FROM ce_ledger_periods lp
  WHERE lp.employer_id = p_employer_id
  GROUP BY lp.fund_type;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_case_command_audit(_actor uuid, _event_code text, _action text, _entity_id text, _outcome text, _after jsonb, _reason text, _correlation_id text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.core_audit_log (
    event_code, event_name, event_category, severity, risk_level,
    actor_user_id, actor_name, module_code, domain_code, entity_type, entity_id,
    action, outcome, after_value, reason, correlation_id, source, is_system_generated
  ) VALUES (
    _event_code, _event_code, 'COMPLIANCE_CASE_REQUEST', 'INFO', 'MEDIUM',
    _actor, public.ce_actor_user_code(_actor), 'manage_compliance', 'COMPLIANCE',
    'ce_case_request', _entity_id, _action, _outcome, _after, _reason, _correlation_id,
    'ce_case_command', false
  );
$function$;
CREATE OR REPLACE FUNCTION public.ce_compliance_role(_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = _user_id
                 AND replace(lower(ur.role::text), ' ', '') LIKE '%compliancehead%') THEN 'head'
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = _user_id
                 AND replace(lower(ur.role::text), ' ', '') LIKE '%seniorinspector%') THEN 'senior'
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = _user_id
                 AND (replace(lower(ur.role::text), ' ', '') LIKE '%complianceinspector%'
                      OR lower(ur.role::text) = 'inspector')) THEN 'inspector'
    ELSE 'other'
  END
$function$;
CREATE OR REPLACE FUNCTION public.ce_create_employer_snapshot(p_employer_id text, p_trigger text, p_trigger_id text DEFAULT NULL::text, p_trigger_type text DEFAULT NULL::text, p_snapshot_by text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_snapshot_id UUID;
  v_master RECORD;
  v_cs RECORD;
  v_rp RECORD;
  v_gm RECORD;
  v_cp RECORD;
  v_flags JSONB;
BEGIN
  -- Read from protected employer master (read-only)
  SELECT * INTO v_master FROM public.er_master WHERE regno = p_employer_id;

  -- Read compliance status
  SELECT * INTO v_cs FROM public.ce_employer_compliance_status WHERE employer_id = p_employer_id;

  -- Read risk profile
  SELECT * INTO v_rp FROM public.ce_risk_profiles WHERE employer_id = p_employer_id;

  -- Read group membership
  SELECT gm.group_id, gm.role, g.group_name
  INTO v_gm
  FROM public.ce_employer_group_membership gm
  JOIN public.ce_employer_groups g ON g.id = gm.group_id
  WHERE gm.employer_id = p_employer_id AND gm.is_active = true
  LIMIT 1;

  -- Read contact preferences
  SELECT * INTO v_cp FROM public.ce_employer_contact_preferences WHERE employer_id = p_employer_id AND is_active = true;

  -- Aggregate active compliance flags
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'flag_code', flag_code,
    'flag_name', flag_name,
    'severity', severity,
    'effective_from', effective_from
  )), '[]'::jsonb)
  INTO v_flags
  FROM public.ce_employer_compliance_flags
  WHERE employer_id = p_employer_id AND is_active = true;

  -- Create immutable snapshot
  INSERT INTO public.ce_employer_snapshots (
    employer_id, snapshot_trigger, snapshot_trigger_id, snapshot_trigger_type, snapshot_by,
    employer_name, employer_status, trade_name, registration_date,
    sector_code, industrial_code, ownership_code, office_code, village_code,
    parent_regno, regno,
    phone, fax, email, mobile,
    mailing_address_1, mailing_address_2, hq_address_1, hq_address_2,
    compliance_status, filing_status, payment_status,
    current_arrears, current_penalties,
    active_violations, active_cases, active_arrangements,
    last_filing_period, last_payment_date,
    risk_score, risk_band, filing_risk_score, payment_risk_score, enforcement_risk_score,
    group_id, group_name, group_role,
    parent_employer_id, parent_employer_name,
    preferred_channel, compliance_email, compliance_phone,
    authorized_contact_name, legal_representative_name, consent_given,
    active_flags,
    raw_master_data, raw_compliance_data, raw_risk_data,
    created_by
  ) VALUES (
    p_employer_id, p_trigger, p_trigger_id, p_trigger_type, p_snapshot_by,
    v_master.name, v_master.status, v_master.trade_name, v_master.registration_date,
    v_master.sector_code, v_master.industrial_code, v_master.ownership_code,
    v_master.office_code, v_master.village_code,
    v_master.parent_regno, v_master.regno,
    v_master.phone, v_master.fax, v_master.email, v_master.mobile,
    v_master.maddr1, v_master.maddr2, v_master.hq_addr1, v_master.hq_addr2,
    v_cs.overall_compliance_status, v_cs.filing_status, v_cs.payment_status,
    v_cs.current_arrears_amount, v_cs.current_penalty_amount,
    v_cs.active_violation_count, v_cs.active_case_count, v_cs.active_arrangement_count,
    v_cs.last_filing_period, v_cs.last_payment_date::TEXT,
    v_rp.total_score, v_rp.risk_band, v_rp.filing_score, v_rp.payment_behavior_score, v_rp.enforcement_risk_score,
    v_gm.group_id, v_gm.group_name, v_gm.role,
    v_master.parent_regno, NULL,
    v_cp.preferred_channel, v_cp.notice_email, v_cp.notice_phone,
    v_cp.authorized_contact_name, v_cp.legal_representative_name, v_cp.consent_given,
    v_flags,
    to_jsonb(v_master), to_jsonb(v_cs), to_jsonb(v_rp),
    p_snapshot_by
  )
  RETURNING id INTO v_snapshot_id;

  RETURN v_snapshot_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_evaluate_arrangement_breaches(p_as_of_date date DEFAULT CURRENT_DATE, p_grace_days integer DEFAULT 5, p_actor character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_arr RECORD;
  v_inst RECORD;
  v_missed INT;
  v_overdue_total NUMERIC;
  v_breach_created INT := 0;
  v_defaulted INT := 0;
  v_installments_flagged INT := 0;
  v_arrangements_scanned INT := 0;
  v_existing_breach BOOLEAN;
  v_case RECORD;
  v_notice_num VARCHAR;
BEGIN
  -- ── Phase 1: Flag overdue installments ────────────────────
  -- Update any PENDING or PARTIAL installment past due + grace
  UPDATE ce_installments i
  SET
    status = 'OVERDUE',
    is_overdue = true,
    overdue_days = (p_as_of_date - i.due_date)
  FROM ce_payment_arrangements pa
  WHERE i.arrangement_id = pa.id
    AND pa.status = 'ACTIVE'
    AND i.status IN ('PENDING', 'PARTIAL')
    AND i.due_date < (p_as_of_date - p_grace_days)
    AND i.is_overdue = false;

  GET DIAGNOSTICS v_installments_flagged = ROW_COUNT;

  -- ── Phase 2: Evaluate each ACTIVE arrangement ────────────
  FOR v_arr IN
    SELECT pa.*
    FROM ce_payment_arrangements pa
    WHERE pa.status = 'ACTIVE'
  LOOP
    v_arrangements_scanned := v_arrangements_scanned + 1;

    -- Count missed (overdue) installments for this arrangement
    SELECT
      COUNT(*),
      COALESCE(SUM(i.amount - COALESCE(i.paid_amount, 0)), 0)
    INTO v_missed, v_overdue_total
    FROM ce_installments i
    WHERE i.arrangement_id = v_arr.id
      AND i.status = 'OVERDUE';

    -- Update arrangement missed_payments
    UPDATE ce_payment_arrangements
    SET
      missed_payments = v_missed,
      updated_by = p_actor,
      updated_at = now()
    WHERE id = v_arr.id
      AND missed_payments IS DISTINCT FROM v_missed;

    -- ── Breach detection ──────────────────────────────────
    -- Only create breach if missed >= max threshold AND no unresolved breach exists
    IF v_missed >= COALESCE(v_arr.max_missed_before_breach, 2) THEN

      SELECT EXISTS (
        SELECT 1 FROM ce_arrangement_breaches ab
        WHERE ab.arrangement_id = v_arr.id
          AND (ab.resolution IS NULL OR ab.resolution = '')
      ) INTO v_existing_breach;

      IF NOT v_existing_breach THEN
        -- Create breach record
        INSERT INTO ce_arrangement_breaches (
          arrangement_id, breach_type, description,
          detected_at, detected_by, created_by
        ) VALUES (
          v_arr.id,
          CASE
            WHEN v_missed >= COALESCE(v_arr.max_missed_before_breach, 2) + 2 THEN 'CRITICAL'
            WHEN v_missed >= COALESCE(v_arr.max_missed_before_breach, 2) + 1 THEN 'MAJOR'
            ELSE 'STANDARD'
          END,
          format('%s overdue installment(s) totaling $%s. Threshold: %s.',
                 v_missed, TRIM(to_char(v_overdue_total, '999,999,990.00')),
                 v_arr.max_missed_before_breach),
          now(), p_actor, p_actor
        );

        -- Flag arrangement as breached
        UPDATE ce_payment_arrangements
        SET
          breach_detected = true,
          breach_date = p_as_of_date,
          breach_reason = format('Missed %s installments (threshold: %s)',
                                v_missed, v_arr.max_missed_before_breach),
          updated_by = p_actor,
          updated_at = now()
        WHERE id = v_arr.id;

        v_breach_created := v_breach_created + 1;

        -- Audit the breach detection
        INSERT INTO ce_audit_log (
          entity_type, entity_id, action, description,
          new_values, performed_by, performed_at
        ) VALUES (
          'ARRANGEMENT', v_arr.id, 'BREACH_DETECTED',
          format('Breach detected on arrangement %s: %s missed installments',
                 v_arr.arrangement_number, v_missed),
          jsonb_build_object('missed_payments', v_missed, 'overdue_total', v_overdue_total),
          p_actor, now()
        );
      END IF;

      -- ── DEFAULTED transition ───────────────────────────
      -- Default if missed exceeds threshold by 1+ (breach unresolved)
      IF v_missed > COALESCE(v_arr.max_missed_before_breach, 2)
         AND v_arr.status != 'DEFAULTED' THEN

        UPDATE ce_payment_arrangements
        SET
          status = 'DEFAULTED',
          breach_reason = COALESCE(breach_reason, '') ||
            format(' | Defaulted on %s: %s missed payments exceed threshold.',
                   p_as_of_date, v_missed),
          updated_by = p_actor,
          updated_at = now()
        WHERE id = v_arr.id;

        v_defaulted := v_defaulted + 1;

        -- Audit the default
        INSERT INTO ce_audit_log (
          entity_type, entity_id, action, description,
          old_values, new_values, performed_by, performed_at
        ) VALUES (
          'ARRANGEMENT', v_arr.id, 'STATUS_CHANGE',
          format('Arrangement %s defaulted: %s missed payments',
                 v_arr.arrangement_number, v_missed),
          jsonb_build_object('status', 'ACTIVE'),
          jsonb_build_object('status', 'DEFAULTED', 'missed_payments', v_missed),
          p_actor, now()
        );

        -- ── Cascade to linked case ──────────────────────
        IF v_arr.case_id IS NOT NULL THEN
          SELECT * INTO v_case
          FROM ce_cases
          WHERE id = v_arr.case_id
            AND COALESCE(is_deleted, false) = false;

          IF v_case IS NOT NULL AND v_case.status NOT IN ('CLOSED', 'ESCALATED') THEN
            UPDATE ce_cases
            SET
              status = 'ESCALATED',
              updated_by = p_actor,
              updated_at = now()
            WHERE id = v_case.id;

            INSERT INTO ce_case_history (
              case_id, action, from_status, to_status,
              notes, performed_by, performed_at
            ) VALUES (
              v_case.id, 'ARRANGEMENT_DEFAULTED', v_case.status, 'ESCALATED',
              format('Auto-escalated: arrangement %s defaulted with %s missed payments',
                     v_arr.arrangement_number, v_missed),
              p_actor, now()
            );
          END IF;

          -- ── Create default notice ──────────────────────
          v_notice_num := 'NTC-DEF-' || SUBSTRING(gen_random_uuid()::TEXT FROM 1 FOR 8);

          INSERT INTO ce_notices (
            notice_number, employer_id, employer_name,
            case_id, notice_type, status,
            subject, body, delivery_method,
            created_by, created_at
          ) VALUES (
            v_notice_num, v_arr.employer_id, v_arr.employer_name,
            v_arr.case_id, 'ARRANGEMENT_DEFAULT', 'DRAFT',
            format('Payment Arrangement %s — Default Notice', v_arr.arrangement_number),
            format('Arrangement %s has been defaulted due to %s consecutive missed payments. '
                   || 'Outstanding balance: $%s. Immediate action is required.',
                   v_arr.arrangement_number, v_missed,
                   TRIM(to_char(v_overdue_total, '999,999,990.00'))),
            'EMAIL',
            p_actor, now()
          );
        END IF;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'as_of_date', p_as_of_date,
    'grace_days', p_grace_days,
    'arrangements_scanned', v_arrangements_scanned,
    'installments_flagged_overdue', v_installments_flagged,
    'breaches_created', v_breach_created,
    'arrangements_defaulted', v_defaulted
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_execute_automation_job(p_job_code character varying, p_dry_run boolean DEFAULT false, p_triggered_by character varying DEFAULT 'system'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job RECORD;
  v_run_id UUID;
  v_result JSONB;
  v_start TIMESTAMPTZ;
  v_duration INT;
BEGIN
  SELECT * INTO v_job FROM ce_automation_jobs WHERE job_code = p_job_code;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Job not found: ' || p_job_code);
  END IF;

  v_start := clock_timestamp();

  INSERT INTO ce_automation_job_runs (job_id, run_status, is_dry_run, triggered_by, started_at)
  VALUES (v_job.id, 'running', p_dry_run, p_triggered_by, v_start)
  RETURNING id INTO v_run_id;

  BEGIN
    CASE p_job_code
      WHEN 'EMP-COMPLIANCE-REFRESH' THEN
        v_result := ce_run_employer_compliance_refresh(p_dry_run, COALESCE((v_job.parameters->>'batch_size')::int, 500));
      WHEN 'EMP-RISK-REFRESH' THEN
        v_result := ce_run_employer_risk_refresh(p_dry_run, COALESCE((v_job.parameters->>'batch_size')::int, 500));
      WHEN 'EMP-FLAG-GEN' THEN
        v_result := ce_run_employer_flag_generation(p_dry_run);
      WHEN 'EMP-SNAPSHOT-GEN' THEN
        v_result := jsonb_build_object('processed', 0, 'affected', 0, 'errors', 0, 'dry_run', p_dry_run, 'note', 'Snapshot generation uses ce_create_employer_snapshot RPC per-employer');
      WHEN 'EMP-STALE-REVIEW' THEN
        v_result := ce_run_stale_employer_review(p_dry_run, COALESCE((v_job.parameters->>'stale_months')::int, 6));
      WHEN 'EMP-GROUP-ROLLUP' THEN
        v_result := ce_run_group_rollup_refresh(p_dry_run);
      WHEN 'EMP-NOTICE-VALIDATE' THEN
        v_result := ce_run_notice_recipient_validation(p_dry_run);
      WHEN 'EMP-RECON-EXCEPTION' THEN
        v_result := ce_run_recon_exception_detection(p_dry_run, COALESCE((v_job.parameters->>'tolerance_amount')::numeric, 0.01));
      ELSE
        v_result := jsonb_build_object('error', 'No handler for job: ' || p_job_code);
    END CASE;

    v_duration := EXTRACT(EPOCH FROM (clock_timestamp() - v_start))::int * 1000;

    UPDATE ce_automation_job_runs SET
      run_status = CASE WHEN p_dry_run THEN 'dry_run' ELSE 'success' END,
      records_processed = COALESCE((v_result->>'processed')::int, 0),
      records_affected = COALESCE((v_result->>'affected')::int, 0),
      errors_count = COALESCE((v_result->>'errors')::int, 0),
      summary = v_result,
      completed_at = clock_timestamp(),
      duration_ms = v_duration
    WHERE id = v_run_id;

    UPDATE ce_automation_jobs SET
      last_run_at = clock_timestamp(),
      last_run_status = CASE WHEN p_dry_run THEN 'dry_run' ELSE 'success' END
    WHERE id = v_job.id;

  EXCEPTION WHEN OTHERS THEN
    v_duration := EXTRACT(EPOCH FROM (clock_timestamp() - v_start))::int * 1000;
    UPDATE ce_automation_job_runs SET
      run_status = 'failed',
      error_details = jsonb_build_object('message', SQLERRM, 'state', SQLSTATE),
      completed_at = clock_timestamp(),
      duration_ms = v_duration
    WHERE id = v_run_id;

    UPDATE ce_automation_jobs SET
      last_run_at = clock_timestamp(),
      last_run_status = 'failed'
    WHERE id = v_job.id;

    v_result := jsonb_build_object('error', SQLERRM);
  END;

  RETURN jsonb_build_object('run_id', v_run_id, 'result', v_result);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_feature_flag_enabled(_flag_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((SELECT f.is_enabled FROM public.feature_flags f WHERE f.flag_key = _flag_key), true)
$function$;
CREATE OR REPLACE FUNCTION public.ce_fetch_unobserved_payments(p_employer_id character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 200)
 RETURNS TABLE(ledger_entry_id uuid, employer_id character varying, employer_name character varying, entry_type text, fund_type text, period character varying, credit_amount numeric, ledger_idempotency_key character varying, reference_type character varying, reference_id uuid, description text, posted_by character varying, posted_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    v.ledger_entry_id,
    v.employer_id,
    v.employer_name,
    v.entry_type::TEXT,
    v.fund_type::TEXT,
    v.period,
    v.credit_amount,
    v.ledger_idempotency_key,
    v.reference_type,
    v.reference_id,
    v.description,
    v.posted_by,
    v.posted_at
  FROM ce_v_unobserved_payment_entries v
  WHERE (p_employer_id IS NULL OR v.employer_id = p_employer_id)
  ORDER BY v.posted_at ASC
  LIMIT p_limit;
$function$;
CREATE OR REPLACE FUNCTION public.ce_generate_audit_report_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year text := to_char(now(), 'YYYY');
  v_seq bigint := nextval('public.ce_employer_audit_report_seq');
BEGIN
  RETURN 'AR-' || v_year || '-' || lpad(v_seq::text, 6, '0');
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_generate_employer_statement(p_employer_id character varying, p_from_period character varying DEFAULT NULL::character varying, p_to_period character varying DEFAULT NULL::character varying, p_fund_type ce_fund_type DEFAULT NULL::ce_fund_type)
 RETURNS TABLE(entry_id uuid, posted_at timestamp with time zone, period character varying, fund_type ce_fund_type, entry_type ce_ledger_entry_type, description text, debit_amount numeric, credit_amount numeric, running_balance numeric, status ce_ledger_status, reference_type character varying, reference_id uuid, reversal_of_id uuid, reversal_reason text, posted_by character varying)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    l.id AS entry_id,
    l.posted_at,
    l.period,
    l.fund_type,
    l.entry_type,
    l.description,
    l.debit_amount,
    l.credit_amount,
    l.running_balance,
    l.status,
    l.reference_type,
    l.reference_id,
    l.reversal_of_id,
    l.reversal_reason,
    l.posted_by
  FROM ce_employer_financial_ledger l
  WHERE l.employer_id = p_employer_id
    AND (p_from_period IS NULL OR l.period >= p_from_period)
    AND (p_to_period IS NULL OR l.period <= p_to_period)
    AND (p_fund_type IS NULL OR l.fund_type = p_fund_type)
  ORDER BY l.posted_at ASC;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_get_employer_balance(p_employer_id character varying, p_as_of_date timestamp with time zone DEFAULT now(), p_fund_type ce_fund_type DEFAULT NULL::ce_fund_type)
 RETURNS TABLE(fund ce_fund_type, total_debits numeric, total_credits numeric, balance numeric, entry_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    l.fund_type,
    COALESCE(SUM(l.debit_amount), 0)::NUMERIC(15,2),
    COALESCE(SUM(l.credit_amount), 0)::NUMERIC(15,2),
    COALESCE(SUM(l.debit_amount - l.credit_amount), 0)::NUMERIC(15,2),
    COUNT(*)
  FROM ce_employer_financial_ledger l
  WHERE l.employer_id = p_employer_id
    AND l.status = 'POSTED'
    AND l.posted_at <= p_as_of_date
    AND (p_fund_type IS NULL OR l.fund_type = p_fund_type)
  GROUP BY l.fund_type;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_get_employer_compliance_summary(p_employer_id character varying)
 RETURNS TABLE(has_active_arrangement boolean, arrangement_status character varying, arrangement_number character varying, arrangement_id uuid, total_debt numeric, total_paid numeric, next_due_date date, overdue_installment_count integer, outstanding_installment_amount numeric, breach_detected boolean, unresolved_breach_count integer, linked_open_case_count integer, warning_message text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_arr RECORD;
  v_overdue_count INT := 0;
  v_outstanding NUMERIC := 0;
  v_breach BOOLEAN := false;
  v_unresolved_breaches INT := 0;
  v_open_cases INT := 0;
  v_warning TEXT := NULL;
BEGIN
  -- Find the most relevant arrangement: ACTIVE first, then DEFAULTED
  SELECT * INTO v_arr
  FROM ce_payment_arrangements pa
  WHERE pa.employer_id = p_employer_id
    AND pa.status IN ('ACTIVE', 'DEFAULTED')
  ORDER BY
    CASE pa.status WHEN 'ACTIVE' THEN 0 WHEN 'DEFAULTED' THEN 1 ELSE 2 END,
    pa.start_date DESC
  LIMIT 1;

  -- If no active/defaulted arrangement, check for any arrangement at all
  IF v_arr IS NULL THEN
    SELECT * INTO v_arr
    FROM ce_payment_arrangements pa
    WHERE pa.employer_id = p_employer_id
    ORDER BY pa.created_at DESC
    LIMIT 1;
  END IF;

  -- Installment metrics (only if arrangement exists)
  IF v_arr IS NOT NULL THEN
    SELECT
      COUNT(*) FILTER (WHERE i.status IN ('OVERDUE') OR (i.status IN ('PENDING','PARTIAL') AND i.due_date < CURRENT_DATE)),
      COALESCE(SUM(i.amount - COALESCE(i.paid_amount, 0)) FILTER (WHERE i.status IN ('PENDING','PARTIAL','OVERDUE')), 0)
    INTO v_overdue_count, v_outstanding
    FROM ce_installments i
    WHERE i.arrangement_id = v_arr.id;

    v_breach := COALESCE(v_arr.breach_detected, false);

    -- Unresolved breaches
    SELECT COUNT(*) INTO v_unresolved_breaches
    FROM ce_arrangement_breaches ab
    WHERE ab.arrangement_id = v_arr.id
      AND (ab.resolution IS NULL OR ab.resolution = '');
  END IF;

  -- Open cases for this employer
  SELECT COUNT(*) INTO v_open_cases
  FROM ce_cases c
  WHERE c.employer_id = p_employer_id
    AND c.status IN ('OPEN', 'IN_PROGRESS', 'UNDER_REVIEW', 'ESCALATED')
    AND COALESCE(c.is_deleted, false) = false;

  -- Derive warning message
  IF v_arr IS NOT NULL AND v_arr.status = 'DEFAULTED' THEN
    v_warning := 'Payment arrangement has been defaulted. Legal escalation may apply.';
  ELSIF v_breach THEN
    v_warning := format('Breach detected on arrangement %s. %s overdue installment(s).',
                        v_arr.arrangement_number, v_overdue_count);
  ELSIF v_overdue_count > 0 THEN
    v_warning := format('%s installment(s) overdue. Outstanding: $%s.',
                        v_overdue_count, TRIM(to_char(v_outstanding, '999,999,990.00')));
  ELSIF v_open_cases > 0 AND v_arr IS NULL THEN
    v_warning := format('%s open compliance case(s) with no active payment arrangement.', v_open_cases);
  END IF;

  RETURN QUERY SELECT
    (v_arr IS NOT NULL AND v_arr.status = 'ACTIVE')::BOOLEAN,
    v_arr.status,
    v_arr.arrangement_number,
    v_arr.id,
    v_arr.total_debt,
    COALESCE(v_arr.total_paid, 0::NUMERIC),
    v_arr.next_due_date,
    v_overdue_count,
    v_outstanding,
    v_breach,
    v_unresolved_breaches,
    v_open_cases,
    v_warning;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_inspections_set_inspection_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.inspection_number IS NULL OR NEW.inspection_number = '' THEN
    NEW.inspection_number := 'INS-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''), 1, 8));
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_list_case_documents(p_case_id uuid)
 RETURNS TABLE(id uuid, title text, document_type text, description text, uploaded_by_name text, created_at timestamp with time zone, verified boolean, is_confidential boolean, is_masked boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_confidential boolean;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;
  IF NOT public.ce_actor_can(v_actor, 'compliance.cases.manage') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ce_cases c
                 WHERE c.id = p_case_id AND coalesce(c.is_deleted, false) = false) THEN
    RAISE EXCEPTION 'CASE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  v_confidential := public.ce_actor_can(v_actor, 'compliance.cases.view_confidential_documents');

  RETURN QUERY
  SELECT d.id,
         CASE WHEN coalesce(d.is_confidential, false) AND NOT v_confidential
              THEN 'Confidential document' ELSE d.title::text END,
         d.document_type::text,
         CASE WHEN coalesce(d.is_confidential, false) AND NOT v_confidential
              THEN NULL ELSE d.description END,
         CASE WHEN coalesce(d.is_confidential, false) AND NOT v_confidential
              THEN NULL ELSE d.uploaded_by_name::text END,
         d.created_at,
         coalesce(d.verified, false),
         coalesce(d.is_confidential, false),
         (coalesce(d.is_confidential, false) AND NOT v_confidential)
  FROM public.ce_case_documents d
  WHERE d.case_id = p_case_id
  ORDER BY d.created_at DESC
  LIMIT 200;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_list_case_inspections(p_case_id uuid, p_include_employer boolean DEFAULT false)
 RETURNS TABLE(id uuid, inspection_number text, inspection_type text, status text, scheduled_date date, visit_date date, inspector_name text, scope text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_employer text;
  v_employer_scope boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;
  IF NOT public.ce_actor_can(v_actor, 'compliance.cases.manage') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT c.employer_id INTO v_employer FROM public.ce_cases c
    WHERE c.id = p_case_id AND coalesce(c.is_deleted, false) = false;
  IF NOT FOUND THEN RAISE EXCEPTION 'CASE_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;

  IF coalesce(p_include_employer, false) THEN
    IF NOT public.ce_actor_can(v_actor, 'compliance.inspections.view_employer_history') THEN
      RAISE EXCEPTION 'FORBIDDEN_EMPLOYER_SCOPE' USING ERRCODE = '42501';
    END IF;
    v_employer_scope := true;
  END IF;

  RETURN QUERY
  SELECT i.id, i.inspection_number::text, i.inspection_type::text, i.status::text,
         i.scheduled_date, i.visit_date, i.inspector_name::text,
         CASE WHEN i.case_id = p_case_id THEN 'CASE' ELSE 'EMPLOYER' END
  FROM public.ce_inspections i
  WHERE i.case_id = p_case_id
     OR (v_employer_scope AND v_employer IS NOT NULL AND i.employer_id = v_employer)
  ORDER BY (CASE WHEN i.case_id = p_case_id THEN 0 ELSE 1 END),
           coalesce(i.visit_date, i.scheduled_date) DESC NULLS LAST
  LIMIT 100;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_log_compliance_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR OLD.compliance_status IS DISTINCT FROM NEW.compliance_status THEN
    INSERT INTO public.ce_employer_status_history (
      employer_id, previous_status, new_status, changed_by, reason_code, reason_detail, source_event, source_reference_id
    ) VALUES (
      NEW.employer_id,
      CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.compliance_status END,
      NEW.compliance_status,
      COALESCE(NEW.updated_by, NEW.created_by, 'SYSTEM'),
      NEW.reason_code, NEW.reason_detail, 'status_table_change', NEW.id::text
    );
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_mark_payment_observed(p_ledger_entry_id uuid, p_employer_id character varying, p_observation_type character varying DEFAULT 'DETECTED'::character varying, p_notes text DEFAULT NULL::text, p_observed_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idem_key VARCHAR;
  v_id UUID;
BEGIN
  -- Deterministic idempotency key: one observation per entry+type
  v_idem_key := 'obs-' || p_ledger_entry_id::TEXT || '-' || p_observation_type;

  -- Check if already observed
  SELECT id INTO v_id
  FROM ce_payment_observation_log
  WHERE idempotency_key = v_idem_key;

  IF v_id IS NOT NULL THEN
    RETURN v_id;  -- Already observed, safe to re-call
  END IF;

  INSERT INTO ce_payment_observation_log (
    ledger_entry_id, employer_id, observation_type,
    notes, observed_by, idempotency_key
  ) VALUES (
    p_ledger_entry_id, p_employer_id, p_observation_type,
    p_notes, p_observed_by, v_idem_key
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_mobile_get_officer_context(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'user_id', p.id,
    'user_code', p.user_code,
    'full_name', p.full_name,
    'email', p.email,
    'role_name', ur.role,
    'role_id', r.id,
    'is_active', COALESCE(p.is_active, false),
    'territory', p.office_code
  )
  INTO v_result
  FROM public.profiles p
  LEFT JOIN LATERAL (
    SELECT role
    FROM public.user_roles
    WHERE user_id = p.id
    ORDER BY created_at ASC NULLS LAST, role ASC
    LIMIT 1
  ) ur ON true
  LEFT JOIN public.roles r ON r.role_name = ur.role
  WHERE p.id = p_user_id
  LIMIT 1;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_post_financial_event(p_employer_id character varying, p_employer_name character varying, p_territory character varying, p_entry_type ce_ledger_entry_type, p_fund_type ce_fund_type, p_period character varying, p_debit_amount numeric DEFAULT 0, p_credit_amount numeric DEFAULT 0, p_reference_type character varying DEFAULT 'manual'::character varying, p_reference_id uuid DEFAULT NULL::uuid, p_description text DEFAULT ''::text, p_idempotency_key character varying DEFAULT NULL::character varying, p_posted_by character varying DEFAULT 'system'::character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_id UUID;
  v_idem_key VARCHAR(200);
  v_running_balance NUMERIC(15,2);
  v_existing_id UUID;
BEGIN
  v_idem_key := COALESCE(p_idempotency_key, 
    p_employer_id || ':' || p_entry_type || ':' || p_fund_type || ':' || p_period || ':' || gen_random_uuid()::text);
  
  SELECT id INTO v_existing_id 
  FROM ce_employer_financial_ledger 
  WHERE idempotency_key = v_idem_key;
  
  IF v_existing_id IS NOT NULL THEN
    RETURN v_existing_id;
  END IF;
  
  SELECT COALESCE(SUM(debit_amount - credit_amount), 0)
  INTO v_running_balance
  FROM ce_employer_financial_ledger
  WHERE employer_id = p_employer_id AND status = 'POSTED';
  
  v_running_balance := v_running_balance + p_debit_amount - p_credit_amount;
  
  INSERT INTO ce_employer_financial_ledger (
    employer_id, employer_name, territory,
    entry_type, fund_type, period,
    debit_amount, credit_amount, running_balance,
    reference_type, reference_id,
    description, idempotency_key, posted_by
  ) VALUES (
    p_employer_id, p_employer_name, p_territory,
    p_entry_type, p_fund_type, p_period,
    p_debit_amount, p_credit_amount, v_running_balance,
    p_reference_type, p_reference_id,
    p_description, v_idem_key, p_posted_by
  ) RETURNING id INTO v_entry_id;
  
  PERFORM ce_recalculate_period_summary(p_employer_id, p_period, p_fund_type);
  
  INSERT INTO ce_audit_log (entity_type, entity_id, action, description, performed_by)
  VALUES ('LEDGER', v_entry_id, p_entry_type::text, p_description, p_posted_by);
  
  RETURN v_entry_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_post_ledger_entry(p_employer_id character varying, p_employer_name character varying DEFAULT NULL::character varying, p_territory character varying DEFAULT NULL::character varying, p_entry_type ce_ledger_entry_type DEFAULT 'C3_DUES_POSTED'::ce_ledger_entry_type, p_fund_type ce_fund_type DEFAULT 'SS'::ce_fund_type, p_period character varying DEFAULT NULL::character varying, p_amount numeric DEFAULT 0, p_description text DEFAULT ''::text, p_reference_type character varying DEFAULT NULL::character varying, p_reference_id uuid DEFAULT NULL::uuid, p_idempotency_key character varying DEFAULT NULL::character varying, p_posted_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_id UUID;
  v_new_id UUID;
  v_debit NUMERIC := 0;
  v_credit NUMERIC := 0;
  v_running_balance NUMERIC := 0;
  v_idem_key VARCHAR;
BEGIN
  -- Generate idempotency key if not provided
  v_idem_key := COALESCE(p_idempotency_key, gen_random_uuid()::VARCHAR);

  -- Check idempotency: return existing if duplicate
  SELECT id INTO v_existing_id
  FROM ce_employer_financial_ledger
  WHERE idempotency_key = v_idem_key;

  IF v_existing_id IS NOT NULL THEN
    RETURN v_existing_id;
  END IF;

  -- Determine debit/credit based on entry type
  -- Debits increase balance owed (dues, penalties, interest)
  -- Credits decrease balance owed (payments, waivers, write-offs)
  IF p_entry_type IN ('C3_DUES_POSTED', 'PENALTY_ASSESSED', 'INTEREST_ACCRUED', 'OPENING_BALANCE', 'TRANSFER_IN') THEN
    v_debit := ABS(p_amount);
    v_credit := 0;
  ELSIF p_entry_type IN ('PAYMENT_RECEIVED', 'WAIVER_APPLIED', 'WRITE_OFF', 'ARRANGEMENT_CREDIT', 'REFUND') THEN
    v_debit := 0;
    v_credit := ABS(p_amount);
  ELSIF p_entry_type = 'ADJUSTMENT' THEN
    IF p_amount >= 0 THEN
      v_debit := ABS(p_amount);
    ELSE
      v_credit := ABS(p_amount);
    END IF;
  ELSIF p_entry_type = 'REVERSAL' THEN
    -- Reversals handled by ce_reverse_ledger_entry
    IF p_amount >= 0 THEN
      v_credit := ABS(p_amount);
    ELSE
      v_debit := ABS(p_amount);
    END IF;
  END IF;

  -- Calculate running balance (latest balance for this employer + fund)
  SELECT COALESCE(SUM(debit_amount) - SUM(credit_amount), 0) INTO v_running_balance
  FROM ce_employer_financial_ledger
  WHERE employer_id = p_employer_id
    AND fund_type = p_fund_type
    AND status = 'POSTED';

  v_running_balance := v_running_balance + v_debit - v_credit;

  -- Insert ledger entry
  INSERT INTO ce_employer_financial_ledger (
    employer_id, employer_name, territory, entry_type, fund_type, period,
    debit_amount, credit_amount, running_balance, status,
    idempotency_key, reference_type, reference_id, description, posted_by
  ) VALUES (
    p_employer_id, p_employer_name, p_territory, p_entry_type, p_fund_type, COALESCE(p_period, to_char(now(), 'YYYYMM')),
    v_debit, v_credit, v_running_balance, 'POSTED',
    v_idem_key, p_reference_type, p_reference_id, p_description, p_posted_by
  )
  RETURNING id INTO v_new_id;

  -- Upsert period summary
  INSERT INTO ce_ledger_periods (employer_id, period, fund_type)
  VALUES (p_employer_id, COALESCE(p_period, to_char(now(), 'YYYYMM')), p_fund_type)
  ON CONFLICT (employer_id, period, fund_type) DO NOTHING;

  -- Update period summary buckets
  UPDATE ce_ledger_periods
  SET
    principal_due = principal_due + CASE WHEN p_entry_type IN ('C3_DUES_POSTED', 'OPENING_BALANCE', 'TRANSFER_IN') THEN v_debit ELSE 0 END,
    penalties = penalties + CASE WHEN p_entry_type = 'PENALTY_ASSESSED' THEN v_debit ELSE 0 END,
    interest = interest + CASE WHEN p_entry_type = 'INTEREST_ACCRUED' THEN v_debit ELSE 0 END,
    payments = payments + CASE WHEN p_entry_type IN ('PAYMENT_RECEIVED', 'ARRANGEMENT_CREDIT') THEN v_credit ELSE 0 END,
    waivers = waivers + CASE WHEN p_entry_type = 'WAIVER_APPLIED' THEN v_credit ELSE 0 END,
    adjustments = adjustments + CASE WHEN p_entry_type = 'ADJUSTMENT' THEN (v_debit - v_credit) ELSE 0 END,
    write_offs = write_offs + CASE WHEN p_entry_type = 'WRITE_OFF' THEN v_credit ELSE 0 END,
    balance = principal_due + penalties + interest - payments - waivers + adjustments - write_offs
      + CASE WHEN p_entry_type IN ('C3_DUES_POSTED', 'OPENING_BALANCE', 'TRANSFER_IN') THEN v_debit ELSE 0 END
      + CASE WHEN p_entry_type = 'PENALTY_ASSESSED' THEN v_debit ELSE 0 END
      + CASE WHEN p_entry_type = 'INTEREST_ACCRUED' THEN v_debit ELSE 0 END
      - CASE WHEN p_entry_type IN ('PAYMENT_RECEIVED', 'ARRANGEMENT_CREDIT') THEN v_credit ELSE 0 END
      - CASE WHEN p_entry_type = 'WAIVER_APPLIED' THEN v_credit ELSE 0 END
      + CASE WHEN p_entry_type = 'ADJUSTMENT' THEN (v_debit - v_credit) ELSE 0 END
      - CASE WHEN p_entry_type = 'WRITE_OFF' THEN v_credit ELSE 0 END
      - (principal_due + penalties + interest - payments - waivers + adjustments - write_offs),
    entry_count = entry_count + 1,
    last_recalculated_at = now(),
    last_recalculated_by = p_posted_by
  WHERE employer_id = p_employer_id
    AND period = COALESCE(p_period, to_char(now(), 'YYYYMM'))
    AND fund_type = p_fund_type;

  RETURN v_new_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_prevent_ledger_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'POSTED' AND NEW.status = 'REVERSED' 
       AND OLD.id = NEW.id AND OLD.entry_type = NEW.entry_type
       AND OLD.debit_amount = NEW.debit_amount AND OLD.credit_amount = NEW.credit_amount THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Ledger entries are immutable. Use reversal entries instead.';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Ledger entries cannot be deleted. Use reversal entries instead.';
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_prevent_penalty_calc_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'Penalty calculation records are immutable.';
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_recalculate_arrangement_summary(p_arrangement_id uuid, p_actor character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_paid    NUMERIC;
  v_inst_paid_cnt INT;
  v_next_due      DATE;
  v_num_inst      INT;
  v_new_status    VARCHAR;
BEGIN
  SELECT
    COALESCE(SUM(paid_amount), 0),
    COUNT(*) FILTER (WHERE status = 'PAID')
  INTO v_total_paid, v_inst_paid_cnt
  FROM ce_installments
  WHERE arrangement_id = p_arrangement_id;

  SELECT MIN(due_date) INTO v_next_due
  FROM ce_installments
  WHERE arrangement_id = p_arrangement_id
    AND status IN ('PENDING', 'PARTIAL', 'OVERDUE');

  SELECT number_of_installments INTO v_num_inst
  FROM ce_payment_arrangements
  WHERE id = p_arrangement_id;

  IF v_inst_paid_cnt >= v_num_inst THEN
    v_new_status := 'COMPLETED';
  ELSE
    v_new_status := 'ACTIVE';
  END IF;

  UPDATE ce_payment_arrangements
  SET total_paid = v_total_paid,
      installments_paid = v_inst_paid_cnt,
      next_due_date = v_next_due,
      status = v_new_status,
      updated_by = p_actor,
      updated_at = now()
  WHERE id = p_arrangement_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_recalculate_breach_state(p_arrangement_id uuid, p_actor character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_missed INT;
  v_arr RECORD;
  v_was_breached BOOLEAN;
  v_unresolved INT;
BEGIN
  SELECT * INTO v_arr
  FROM ce_payment_arrangements
  WHERE id = p_arrangement_id;

  IF v_arr IS NULL THEN
    RETURN jsonb_build_object('error', 'Arrangement not found');
  END IF;

  v_was_breached := COALESCE(v_arr.breach_detected, false);

  -- Recount overdue installments
  SELECT COUNT(*) INTO v_missed
  FROM ce_installments
  WHERE arrangement_id = p_arrangement_id
    AND status = 'OVERDUE';

  -- Update arrangement missed count
  UPDATE ce_payment_arrangements
  SET
    missed_payments = v_missed,
    updated_by = p_actor,
    updated_at = now()
  WHERE id = p_arrangement_id;

  -- Count unresolved breaches
  SELECT COUNT(*) INTO v_unresolved
  FROM ce_arrangement_breaches
  WHERE arrangement_id = p_arrangement_id
    AND (resolution IS NULL OR resolution = '');

  -- If no more overdue AND no unresolved breaches, clear breach flag
  IF v_missed = 0 AND v_unresolved = 0 AND v_was_breached THEN
    UPDATE ce_payment_arrangements
    SET
      breach_detected = false,
      updated_by = p_actor,
      updated_at = now()
    WHERE id = p_arrangement_id;

    INSERT INTO ce_audit_log (
      entity_type, entity_id, action, description,
      old_values, new_values, performed_by, performed_at
    ) VALUES (
      'ARRANGEMENT', p_arrangement_id, 'BREACH_CURED',
      'All overdue installments resolved; breach flag cleared',
      jsonb_build_object('breach_detected', true, 'missed_payments', v_arr.missed_payments),
      jsonb_build_object('breach_detected', false, 'missed_payments', 0),
      p_actor, now()
    );
  END IF;

  RETURN jsonb_build_object(
    'arrangement_id', p_arrangement_id,
    'previous_missed', v_arr.missed_payments,
    'current_missed', v_missed,
    'was_breached', v_was_breached,
    'is_breached', (v_missed > 0 OR v_unresolved > 0),
    'unresolved_breaches', v_unresolved
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_recalculate_period_summary(p_employer_id character varying, p_period character varying, p_fund_type ce_fund_type)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_principal NUMERIC(15,2) := 0;
  v_penalties NUMERIC(15,2) := 0;
  v_interest NUMERIC(15,2) := 0;
  v_payments NUMERIC(15,2) := 0;
  v_waivers NUMERIC(15,2) := 0;
  v_adjustments NUMERIC(15,2) := 0;
  v_write_offs NUMERIC(15,2) := 0;
  v_count INTEGER := 0;
BEGIN
  SELECT 
    COALESCE(SUM(CASE WHEN entry_type = 'C3_DUES_POSTED' THEN debit_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN entry_type = 'PENALTY_ASSESSED' THEN debit_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN entry_type = 'INTEREST_ACCRUED' THEN debit_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN entry_type IN ('PAYMENT_RECEIVED', 'ARRANGEMENT_CREDIT') THEN credit_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN entry_type = 'WAIVER_APPLIED' THEN credit_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN entry_type = 'ADJUSTMENT' THEN (credit_amount - debit_amount) ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN entry_type = 'WRITE_OFF' THEN credit_amount ELSE 0 END), 0),
    COUNT(*)
  INTO v_principal, v_penalties, v_interest, v_payments, v_waivers, v_adjustments, v_write_offs, v_count
  FROM ce_employer_financial_ledger
  WHERE employer_id = p_employer_id
    AND period = p_period
    AND fund_type = p_fund_type
    AND status = 'POSTED';
  
  INSERT INTO ce_ledger_periods (
    employer_id, period, fund_type,
    principal_due, penalties, interest, payments, waivers, adjustments, write_offs,
    balance, last_recalculated_at, entry_count
  ) VALUES (
    p_employer_id, p_period, p_fund_type,
    v_principal, v_penalties, v_interest, v_payments, v_waivers, v_adjustments, v_write_offs,
    (v_principal + v_penalties + v_interest - v_payments - v_waivers - v_adjustments - v_write_offs),
    now(), v_count
  )
  ON CONFLICT (employer_id, period, fund_type)
  DO UPDATE SET
    principal_due = EXCLUDED.principal_due,
    penalties = EXCLUDED.penalties,
    interest = EXCLUDED.interest,
    payments = EXCLUDED.payments,
    waivers = EXCLUDED.waivers,
    adjustments = EXCLUDED.adjustments,
    write_offs = EXCLUDED.write_offs,
    balance = EXCLUDED.balance,
    last_recalculated_at = EXCLUDED.last_recalculated_at,
    entry_count = EXCLUDED.entry_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_recompute_employer_compliance(p_employer_id character varying, p_triggered_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_debits NUMERIC(15,2) := 0;
  v_credits NUMERIC(15,2) := 0;
  v_balance NUMERIC(15,2) := 0;
  v_open_cases INT := 0;
  v_open_violations INT := 0;
  v_open_arrangements INT := 0;
  v_last_payment DATE;
  v_filing_status VARCHAR := 'unknown';
  v_payment_status VARCHAR := 'unknown';
  v_overall VARCHAR := 'unknown';
  v_existing_id UUID;
BEGIN
  SELECT COALESCE(SUM(COALESCE(debit_amount,0)),0), COALESCE(SUM(COALESCE(credit_amount,0)),0)
  INTO v_debits, v_credits
  FROM public.ce_employer_financial_ledger
  WHERE employer_id = p_employer_id AND reversal_of_id IS NULL;
  v_balance := v_debits - v_credits;

  SELECT COUNT(*) INTO v_open_cases FROM public.ce_cases
  WHERE employer_id = p_employer_id AND status NOT IN ('closed','cancelled','resolved') AND NOT COALESCE(is_deleted,false);

  SELECT COUNT(*) INTO v_open_violations FROM public.ce_violations
  WHERE employer_id = p_employer_id AND status NOT IN ('closed','cancelled','resolved','dismissed') AND NOT COALESCE(is_deleted,false);

  SELECT MAX(posted_at::date) INTO v_last_payment FROM public.ce_employer_financial_ledger
  WHERE employer_id = p_employer_id AND entry_type = 'PAYMENT_RECEIVED' AND reversal_of_id IS NULL;

  v_payment_status := CASE
    WHEN v_last_payment IS NULL THEN 'never_paid'
    WHEN v_last_payment < CURRENT_DATE - INTERVAL '60 days' THEN 'delinquent'
    WHEN v_last_payment < CURRENT_DATE - INTERVAL '30 days' THEN 'late'
    ELSE 'current' END;

  v_overall := CASE
    WHEN v_balance <= 0 AND v_open_violations = 0 AND v_open_cases = 0 THEN 'compliant'
    WHEN v_balance > 500000 OR v_open_violations > 5 THEN 'critical'
    WHEN v_balance > 0 OR v_open_violations > 0 THEN 'non_compliant'
    ELSE 'partially_compliant' END;

  SELECT id INTO v_existing_id FROM public.ce_employer_compliance_status
  WHERE employer_id = p_employer_id AND effective_to IS NULL LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.ce_employer_compliance_status SET
      filing_status = v_filing_status, payment_status = v_payment_status,
      overall_compliance_status = v_overall, compliance_status = v_overall,
      current_arrears_amount = GREATEST(v_balance,0), current_penalty_amount = v_credits,
      last_payment_date = v_last_payment,
      active_case_count = v_open_cases, active_violation_count = v_open_violations,
      active_arrangement_count = v_open_arrangements,
      last_computed_at = now(), computed_by = p_triggered_by, updated_by = p_triggered_by
    WHERE id = v_existing_id;
  ELSE
    INSERT INTO public.ce_employer_compliance_status (
      employer_id, compliance_status, filing_status, payment_status,
      overall_compliance_status, current_arrears_amount, current_penalty_amount,
      last_payment_date, active_case_count, active_violation_count,
      active_arrangement_count, last_computed_at, computed_by, created_by
    ) VALUES (
      p_employer_id, v_overall, v_filing_status, v_payment_status,
      v_overall, GREATEST(v_balance,0), v_credits,
      v_last_payment, v_open_cases, v_open_violations,
      v_open_arrangements, now(), p_triggered_by, p_triggered_by
    );
  END IF;

  RETURN jsonb_build_object(
    'employer_id', p_employer_id, 'overall_status', v_overall,
    'filing_status', v_filing_status, 'payment_status', v_payment_status,
    'arrears', v_balance, 'open_cases', v_open_cases,
    'open_violations', v_open_violations, 'computed_at', now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_recompute_employer_risk(p_employer_id character varying, p_triggered_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cs RECORD;
  v_arrears_s NUMERIC(5,2); v_violation_s NUMERIC(5,2); v_filing_s NUMERIC(5,2);
  v_payment_s NUMERIC(5,2); v_enforcement_s NUMERIC(5,2); v_legal_s NUMERIC(5,2);
  v_total NUMERIC(5,2); v_band VARCHAR; v_name VARCHAR; v_terr VARCHAR;
BEGIN
  SELECT * INTO v_cs FROM public.ce_employer_compliance_status
  WHERE employer_id = p_employer_id AND effective_to IS NULL LIMIT 1;
  IF v_cs IS NULL THEN
    RETURN jsonb_build_object('error','Run ce_recompute_employer_compliance first');
  END IF;

  SELECT name, village_code INTO v_name, v_terr FROM public.er_master WHERE regno = p_employer_id LIMIT 1;

  v_arrears_s := CASE
    WHEN COALESCE(v_cs.current_arrears_amount,0) > 500000 THEN 100
    WHEN COALESCE(v_cs.current_arrears_amount,0) > 150000 THEN 80
    WHEN COALESCE(v_cs.current_arrears_amount,0) > 50000 THEN 60
    WHEN COALESCE(v_cs.current_arrears_amount,0) > 10000 THEN 40
    WHEN COALESCE(v_cs.current_arrears_amount,0) > 0 THEN 20
    ELSE 0 END;
  v_violation_s := LEAST(COALESCE(v_cs.active_violation_count,0)*20, 100);
  v_filing_s := CASE v_cs.filing_status WHEN 'never_filed' THEN 100 WHEN 'delinquent' THEN 80 WHEN 'late' THEN 50 WHEN 'current' THEN 0 ELSE 50 END;
  v_payment_s := CASE v_cs.payment_status WHEN 'never_paid' THEN 100 WHEN 'delinquent' THEN 80 WHEN 'late' THEN 50 WHEN 'current' THEN 0 ELSE 50 END;
  v_enforcement_s := LEAST((COALESCE(v_cs.active_case_count,0)*25)+(COALESCE(v_cs.active_arrangement_count,0)*10), 100);
  v_legal_s := CASE WHEN COALESCE(v_cs.active_case_count,0) > 2 THEN 80 WHEN COALESCE(v_cs.active_case_count,0) > 0 THEN 40 ELSE 0 END;
  v_total := (v_arrears_s*0.25)+(v_violation_s*0.25)+(v_filing_s*0.20)+(v_payment_s*0.20)+(v_legal_s*0.10);
  v_band := CASE WHEN v_total >= 80 THEN 'Critical' WHEN v_total >= 60 THEN 'High' WHEN v_total >= 40 THEN 'Medium' ELSE 'Low' END;

  INSERT INTO public.ce_risk_profiles (
    employer_id, employer_name, territory, arrears_score, violation_score, filing_score,
    payment_behavior_score, legal_history_score, enforcement_risk_score,
    total_score, risk_band, scoring_version, last_calculated_at, next_review_date,
    assessed_by, created_by, updated_by
  ) VALUES (
    p_employer_id, v_name, v_terr, v_arrears_s, v_violation_s, v_filing_s,
    v_payment_s, v_legal_s, v_enforcement_s,
    v_total, v_band, 'v1.0', now(), CURRENT_DATE + INTERVAL '30 days',
    p_triggered_by, p_triggered_by, p_triggered_by
  )
  ON CONFLICT (employer_id) DO UPDATE SET
    employer_name = EXCLUDED.employer_name, territory = EXCLUDED.territory,
    arrears_score = EXCLUDED.arrears_score, violation_score = EXCLUDED.violation_score,
    filing_score = EXCLUDED.filing_score, payment_behavior_score = EXCLUDED.payment_behavior_score,
    legal_history_score = EXCLUDED.legal_history_score, enforcement_risk_score = EXCLUDED.enforcement_risk_score,
    total_score = EXCLUDED.total_score,
    risk_band = CASE WHEN ce_risk_profiles.override_band IS NOT NULL THEN ce_risk_profiles.risk_band ELSE EXCLUDED.risk_band END,
    scoring_version = EXCLUDED.scoring_version, last_calculated_at = now(),
    next_review_date = CURRENT_DATE + INTERVAL '30 days',
    assessed_by = EXCLUDED.assessed_by, updated_by = EXCLUDED.updated_by, updated_at = now();

  RETURN jsonb_build_object('employer_id', p_employer_id, 'total_score', v_total, 'risk_band', v_band);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_reconcile_ledger_payment_to_arrangement(p_ledger_entry_id uuid, p_actor character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS ce_reconcile_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result        ce_reconcile_result;
  v_ledger        RECORD;
  v_arrangement   RECORD;
  v_remaining     NUMERIC;
  v_inst          RECORD;
  v_alloc         NUMERIC;
  v_new_paid      NUMERIC;
  v_inst_touched  INT := 0;
  v_obs_idem_key  VARCHAR;
  v_existing_obs  UUID;
  v_total_paid    NUMERIC;
  v_inst_paid_cnt INT;
  v_next_due      DATE;
  v_old_arr_status VARCHAR;
  v_new_arr_status VARCHAR;
BEGIN
  -- Initialize result
  v_result.was_duplicate := false;
  v_result.arrangement_completed := false;
  v_result.installments_touched := 0;
  v_result.allocated_amount := 0;

  -- ── 1. Idempotency check via observation log ──
  v_obs_idem_key := 'obs-' || p_ledger_entry_id::TEXT || '-ALLOCATED';

  SELECT id INTO v_existing_obs
  FROM ce_payment_observation_log
  WHERE idempotency_key = v_obs_idem_key;

  IF v_existing_obs IS NOT NULL THEN
    v_result.observation_id := v_existing_obs;
    v_result.was_duplicate := true;
    RETURN v_result;
  END IF;

  -- ── 2. Load the ledger entry ──
  SELECT * INTO v_ledger
  FROM ce_employer_financial_ledger
  WHERE id = p_ledger_entry_id
    AND status = 'POSTED'
    AND entry_type IN ('PAYMENT_RECEIVED', 'ARRANGEMENT_CREDIT', 'REFUND')
    AND reversal_of_id IS NULL;

  IF v_ledger IS NULL THEN
    RAISE EXCEPTION 'Ledger entry % not found or not a payment-type entry', p_ledger_entry_id;
  END IF;

  -- ── 3. Find matching arrangement ──
  -- Strategy A: direct reference match
  IF v_ledger.reference_type = 'PAYMENT_ARRANGEMENT' AND v_ledger.reference_id IS NOT NULL THEN
    SELECT * INTO v_arrangement
    FROM ce_payment_arrangements
    WHERE id = v_ledger.reference_id
      AND status = 'ACTIVE';
  END IF;

  -- Strategy B: employer match — oldest ACTIVE arrangement
  IF v_arrangement IS NULL THEN
    SELECT * INTO v_arrangement
    FROM ce_payment_arrangements
    WHERE employer_id = v_ledger.employer_id
      AND status = 'ACTIVE'
    ORDER BY start_date ASC
    LIMIT 1;
  END IF;

  -- No matching arrangement — mark as DETECTED only (no allocation)
  IF v_arrangement IS NULL THEN
    INSERT INTO ce_payment_observation_log (
      ledger_entry_id, employer_id, observation_type,
      notes, observed_by, idempotency_key
    ) VALUES (
      p_ledger_entry_id, v_ledger.employer_id, 'DETECTED',
      'No active arrangement found for employer; payment not allocated to arrangement',
      p_actor,
      'obs-' || p_ledger_entry_id::TEXT || '-DETECTED'
    )
    ON CONFLICT (idempotency_key) DO NOTHING
    RETURNING id INTO v_result.observation_id;

    -- If ON CONFLICT hit, fetch existing
    IF v_result.observation_id IS NULL THEN
      SELECT id INTO v_result.observation_id
      FROM ce_payment_observation_log
      WHERE idempotency_key = 'obs-' || p_ledger_entry_id::TEXT || '-DETECTED';
    END IF;

    RETURN v_result;
  END IF;

  v_result.arrangement_id := v_arrangement.id;
  v_remaining := v_ledger.credit_amount;
  v_old_arr_status := v_arrangement.status;

  -- ── 4. Allocate to installments (oldest unpaid first) ──
  FOR v_inst IN
    SELECT *
    FROM ce_installments
    WHERE arrangement_id = v_arrangement.id
      AND status IN ('PENDING', 'PARTIAL', 'OVERDUE')
    ORDER BY installment_number ASC
  LOOP
    EXIT WHEN v_remaining <= 0;

    -- How much this installment still needs
    v_alloc := LEAST(v_remaining, v_inst.amount - COALESCE(v_inst.paid_amount, 0));

    IF v_alloc <= 0 THEN
      CONTINUE;
    END IF;

    v_new_paid := COALESCE(v_inst.paid_amount, 0) + v_alloc;

    UPDATE ce_installments
    SET paid_amount = v_new_paid,
        paid_date = CASE WHEN v_new_paid >= amount THEN CURRENT_DATE ELSE paid_date END,
        payment_reference = COALESCE(
          payment_reference || '; ' || v_ledger.idempotency_key,
          v_ledger.idempotency_key
        ),
        status = CASE
          WHEN v_new_paid >= amount THEN 'PAID'
          WHEN v_new_paid > 0 THEN 'PARTIAL'
          ELSE status
        END
    WHERE id = v_inst.id;

    v_remaining := v_remaining - v_alloc;
    v_result.allocated_amount := v_result.allocated_amount + v_alloc;
    v_inst_touched := v_inst_touched + 1;
  END LOOP;

  v_result.installments_touched := v_inst_touched;

  -- ── 5. Recalculate arrangement summary ──
  SELECT
    COALESCE(SUM(paid_amount), 0),
    COUNT(*) FILTER (WHERE status = 'PAID')
  INTO v_total_paid, v_inst_paid_cnt
  FROM ce_installments
  WHERE arrangement_id = v_arrangement.id;

  -- Next due = earliest unpaid installment
  SELECT MIN(due_date) INTO v_next_due
  FROM ce_installments
  WHERE arrangement_id = v_arrangement.id
    AND status IN ('PENDING', 'PARTIAL', 'OVERDUE');

  -- Determine new arrangement status
  IF v_inst_paid_cnt >= v_arrangement.number_of_installments THEN
    v_new_arr_status := 'COMPLETED';
    v_result.arrangement_completed := true;
  ELSE
    v_new_arr_status := 'ACTIVE';
  END IF;

  UPDATE ce_payment_arrangements
  SET total_paid = v_total_paid,
      installments_paid = v_inst_paid_cnt,
      next_due_date = v_next_due,
      status = v_new_arr_status,
      updated_by = p_actor,
      updated_at = now()
  WHERE id = v_arrangement.id;

  -- ── 6. If arrangement completed, update linked case ──
  IF v_result.arrangement_completed AND v_arrangement.case_id IS NOT NULL THEN
    -- Log case history
    INSERT INTO ce_case_history (
      case_id, action, from_status, to_status,
      notes, performed_by, performed_at
    ) VALUES (
      v_arrangement.case_id,
      'ARRANGEMENT_COMPLETED',
      NULL,
      NULL,
      format('Payment arrangement %s completed. Total paid: %s',
             v_arrangement.arrangement_number, v_total_paid),
      p_actor,
      now()
    );

    -- Update amount_collected on the case
    UPDATE ce_cases
    SET amount_collected = COALESCE(amount_collected, 0) + v_result.allocated_amount,
        updated_by = p_actor,
        updated_at = now()
    WHERE id = v_arrangement.case_id;
  END IF;

  -- ── 7. Audit log ──
  INSERT INTO ce_audit_log (
    entity_type, entity_id, action,
    description, old_values, new_values,
    performed_by, performed_at
  ) VALUES (
    'PAYMENT_ARRANGEMENT',
    v_arrangement.id,
    'PAYMENT_RECONCILED',
    format('Reconciled ledger entry %s: allocated %s to %s installment(s) on arrangement %s',
           p_ledger_entry_id, v_result.allocated_amount, v_inst_touched, v_arrangement.arrangement_number),
    jsonb_build_object(
      'total_paid', v_arrangement.total_paid,
      'installments_paid', v_arrangement.installments_paid,
      'status', v_old_arr_status
    ),
    jsonb_build_object(
      'total_paid', v_total_paid,
      'installments_paid', v_inst_paid_cnt,
      'status', v_new_arr_status,
      'allocated_amount', v_result.allocated_amount,
      'ledger_entry_id', p_ledger_entry_id
    ),
    p_actor,
    now()
  );

  -- ── 8. Mark as ALLOCATED in observation log ──
  INSERT INTO ce_payment_observation_log (
    ledger_entry_id, employer_id, observation_type,
    notes, observed_by, idempotency_key
  ) VALUES (
    p_ledger_entry_id,
    v_ledger.employer_id,
    'ALLOCATED',
    format('Allocated %s to arrangement %s (%s installments)',
           v_result.allocated_amount, v_arrangement.arrangement_number, v_inst_touched),
    p_actor,
    v_obs_idem_key
  )
  RETURNING id INTO v_result.observation_id;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_request_case_action(p_case_id uuid, p_request_type text, p_reason text, p_target_case_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT NULL::jsonb, p_idempotency_key text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_code text;
  v_case record;
  v_target record;
  v_closed boolean;
  v_flag text;
  v_id uuid;
  v_result jsonb;
  v_existing jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  p_request_type := upper(coalesce(p_request_type, ''));
  IF p_request_type NOT IN ('CLOSURE', 'REOPEN', 'MERGE') THEN
    RAISE EXCEPTION 'INVALID_REQUEST_TYPE' USING ERRCODE = '22023';
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'REASON_REQUIRED' USING ERRCODE = '22023';
  END IF;

  -- Idempotent replay
  IF p_idempotency_key IS NOT NULL THEN
    SELECT result_json INTO v_existing FROM public.ce_case_command_idempotency
      WHERE idempotency_key = p_idempotency_key;
    IF v_existing IS NOT NULL THEN
      RETURN v_existing || jsonb_build_object('replayed', true);
    END IF;
  END IF;

  IF NOT public.ce_actor_can(v_actor, 'compliance.cases.manage') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  v_flag := CASE p_request_type
    WHEN 'CLOSURE' THEN 'compliance.core.case_closure_approval'
    WHEN 'REOPEN' THEN 'compliance.core.case_reopen'
    ELSE 'compliance.core.case_merge' END;
  IF NOT public.ce_feature_flag_enabled(v_flag) THEN
    RAISE EXCEPTION 'FEATURE_DISABLED' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_case FROM public.ce_cases WHERE id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CASE_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF coalesce(v_case.is_deleted, false) THEN
    RAISE EXCEPTION 'CASE_DELETED' USING ERRCODE = '22023';
  END IF;

  v_closed := upper(coalesce(v_case.status, '')) IN ('RESOLVED', 'CLOSED', 'COMPLETED');

  IF p_request_type = 'REOPEN' AND NOT v_closed THEN
    RAISE EXCEPTION 'CASE_NOT_CLOSED' USING ERRCODE = '22023';
  END IF;
  IF p_request_type IN ('CLOSURE', 'MERGE') AND v_closed THEN
    RAISE EXCEPTION 'CASE_ALREADY_CLOSED' USING ERRCODE = '22023';
  END IF;
  IF p_request_type IN ('CLOSURE', 'MERGE') AND coalesce(v_case.is_merged, false) THEN
    RAISE EXCEPTION 'CASE_ALREADY_MERGED' USING ERRCODE = '22023';
  END IF;

  IF p_request_type = 'MERGE' THEN
    IF p_target_case_id IS NULL THEN
      RAISE EXCEPTION 'TARGET_REQUIRED' USING ERRCODE = '22023';
    END IF;
    IF p_target_case_id = p_case_id THEN
      RAISE EXCEPTION 'TARGET_SAME_AS_SOURCE' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_target FROM public.ce_cases WHERE id = p_target_case_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
    IF coalesce(v_target.is_deleted, false)
       OR coalesce(v_target.is_merged, false)
       OR upper(coalesce(v_target.status, '')) IN ('RESOLVED','CLOSED','COMPLETED','CANCELLED') THEN
      RAISE EXCEPTION 'TARGET_NOT_ELIGIBLE' USING ERRCODE = '22023';
    END IF;
    IF v_target.merged_into_case_id = p_case_id THEN
      RAISE EXCEPTION 'CIRCULAR_MERGE' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM public.ce_case_requests
             WHERE case_id = p_case_id AND request_type = p_request_type AND status = 'PENDING') THEN
    RAISE EXCEPTION 'DUPLICATE_PENDING_REQUEST' USING ERRCODE = '40001';
  END IF;

  v_code := public.ce_actor_user_code(v_actor);

  INSERT INTO public.ce_case_requests (
    case_id, request_type, target_case_id, reason, status,
    requested_by, requested_at, metadata
  ) VALUES (
    p_case_id, p_request_type, CASE WHEN p_request_type = 'MERGE' THEN p_target_case_id END,
    btrim(p_reason), 'PENDING', v_code, now(),
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('requested_by_user_id', v_actor, 'correlation_id', p_correlation_id)
  ) RETURNING id INTO v_id;

  PERFORM public.ce_case_command_audit(
    v_actor, 'CE_CASE_REQUEST_CREATED', p_request_type, v_id::text, 'SUCCESS',
    jsonb_build_object('case_id', p_case_id, 'target_case_id', p_target_case_id,
                       'request_type', p_request_type),
    btrim(p_reason), p_correlation_id);

  v_result := jsonb_build_object('ok', true, 'request_id', v_id, 'status', 'PENDING',
                                 'request_type', p_request_type, 'replayed', false);

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO public.ce_case_command_idempotency
      (idempotency_key, command_name, actor_user_id, correlation_id, result_json)
    VALUES (p_idempotency_key, 'ce_request_case_action', v_actor, p_correlation_id, v_result)
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_reverse_financial_event(p_original_entry_id uuid, p_reason text, p_reversed_by character varying DEFAULT 'system'::character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_original RECORD;
  v_reversal_id UUID;
  v_idem_key VARCHAR(200);
  v_running_balance NUMERIC(15,2);
BEGIN
  SELECT * INTO v_original
  FROM ce_employer_financial_ledger
  WHERE id = p_original_entry_id AND status = 'POSTED';
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Original entry not found or already reversed: %', p_original_entry_id;
  END IF;
  
  IF EXISTS (
    SELECT 1 FROM ce_employer_financial_ledger 
    WHERE reversal_of_id = p_original_entry_id AND status = 'POSTED'
  ) THEN
    RAISE EXCEPTION 'Entry already has an active reversal: %', p_original_entry_id;
  END IF;
  
  v_idem_key := 'REV:' || p_original_entry_id::text;
  
  SELECT COALESCE(SUM(debit_amount - credit_amount), 0)
  INTO v_running_balance
  FROM ce_employer_financial_ledger
  WHERE employer_id = v_original.employer_id AND status = 'POSTED';
  
  v_running_balance := v_running_balance + v_original.credit_amount - v_original.debit_amount;
  
  INSERT INTO ce_employer_financial_ledger (
    employer_id, employer_name, territory,
    entry_type, fund_type, period,
    debit_amount, credit_amount, running_balance,
    status, reference_type, reference_id,
    reversal_of_id, reversal_reason,
    description, idempotency_key, posted_by
  ) VALUES (
    v_original.employer_id, v_original.employer_name, v_original.territory,
    'REVERSAL', v_original.fund_type, v_original.period,
    v_original.credit_amount, v_original.debit_amount, v_running_balance,
    'POSTED', 'reversal', p_original_entry_id,
    p_original_entry_id, p_reason,
    'Reversal of ' || v_original.entry_type || ': ' || p_reason,
    v_idem_key, p_reversed_by
  ) RETURNING id INTO v_reversal_id;
  
  UPDATE ce_employer_financial_ledger SET status = 'REVERSED' WHERE id = p_original_entry_id;
  
  PERFORM ce_recalculate_period_summary(v_original.employer_id, v_original.period, v_original.fund_type);
  
  INSERT INTO ce_audit_log (entity_type, entity_id, action, description, old_values, performed_by)
  VALUES ('LEDGER', v_reversal_id, 'REVERSAL', p_reason, 
    jsonb_build_object('original_entry_id', p_original_entry_id, 'original_type', v_original.entry_type),
    p_reversed_by);
  
  RETURN v_reversal_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_reverse_ledger_entry(p_original_entry_id uuid, p_reversal_reason text, p_reversed_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_original RECORD;
  v_reversal_id UUID;
  v_new_running_balance NUMERIC;
BEGIN
  -- Get and validate original entry
  SELECT * INTO v_original
  FROM ce_employer_financial_ledger
  WHERE id = p_original_entry_id AND status = 'POSTED';

  IF v_original IS NULL THEN
    RAISE EXCEPTION 'Entry % not found or already reversed', p_original_entry_id;
  END IF;

  -- Calculate new running balance
  SELECT COALESCE(SUM(debit_amount) - SUM(credit_amount), 0) INTO v_new_running_balance
  FROM ce_employer_financial_ledger
  WHERE employer_id = v_original.employer_id
    AND fund_type = v_original.fund_type
    AND status = 'POSTED';

  v_new_running_balance := v_new_running_balance - v_original.debit_amount + v_original.credit_amount;

  -- Create reversal entry (mirror amounts)
  INSERT INTO ce_employer_financial_ledger (
    employer_id, employer_name, territory, entry_type, fund_type, period,
    debit_amount, credit_amount, running_balance, status,
    idempotency_key, reference_type, reference_id, 
    reversal_of_id, reversal_reason, description, posted_by
  ) VALUES (
    v_original.employer_id, v_original.employer_name, v_original.territory,
    'REVERSAL', v_original.fund_type, v_original.period,
    v_original.credit_amount, v_original.debit_amount, -- MIRROR
    v_new_running_balance, 'POSTED',
    'REV-' || p_original_entry_id::VARCHAR, v_original.reference_type, v_original.reference_id,
    p_original_entry_id, p_reversal_reason,
    'Reversal of: ' || v_original.description, p_reversed_by
  )
  RETURNING id INTO v_reversal_id;

  -- Mark original as REVERSED
  UPDATE ce_employer_financial_ledger
  SET status = 'REVERSED'
  WHERE id = p_original_entry_id;

  -- Update period summary: subtract the original amounts
  UPDATE ce_ledger_periods
  SET
    principal_due = principal_due - CASE WHEN v_original.entry_type::TEXT IN ('C3_DUES_POSTED', 'OPENING_BALANCE', 'TRANSFER_IN') THEN v_original.debit_amount ELSE 0 END,
    penalties = penalties - CASE WHEN v_original.entry_type::TEXT = 'PENALTY_ASSESSED' THEN v_original.debit_amount ELSE 0 END,
    interest = interest - CASE WHEN v_original.entry_type::TEXT = 'INTEREST_ACCRUED' THEN v_original.debit_amount ELSE 0 END,
    payments = payments - CASE WHEN v_original.entry_type::TEXT IN ('PAYMENT_RECEIVED', 'ARRANGEMENT_CREDIT') THEN v_original.credit_amount ELSE 0 END,
    waivers = waivers - CASE WHEN v_original.entry_type::TEXT = 'WAIVER_APPLIED' THEN v_original.credit_amount ELSE 0 END,
    adjustments = adjustments - CASE WHEN v_original.entry_type::TEXT = 'ADJUSTMENT' THEN (v_original.debit_amount - v_original.credit_amount) ELSE 0 END,
    write_offs = write_offs - CASE WHEN v_original.entry_type::TEXT = 'WRITE_OFF' THEN v_original.credit_amount ELSE 0 END,
    entry_count = entry_count + 1,
    last_recalculated_at = now(),
    last_recalculated_by = p_reversed_by
  WHERE employer_id = v_original.employer_id
    AND period = v_original.period
    AND fund_type = v_original.fund_type;

  -- Recalculate balance on period
  UPDATE ce_ledger_periods
  SET balance = principal_due + penalties + interest - payments - waivers + adjustments - write_offs
  WHERE employer_id = v_original.employer_id
    AND period = v_original.period
    AND fund_type = v_original.fund_type;

  -- Log to audit
  INSERT INTO ce_audit_log (entity_type, entity_id, action, description, old_values, new_values, performed_by)
  VALUES (
    'ledger_entry', p_original_entry_id, 'REVERSAL',
    'Reversed ledger entry: ' || v_original.description,
    jsonb_build_object('status', 'POSTED', 'debit', v_original.debit_amount, 'credit', v_original.credit_amount),
    jsonb_build_object('status', 'REVERSED', 'reversal_id', v_reversal_id, 'reason', p_reversal_reason),
    p_reversed_by
  );

  RETURN v_reversal_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_review_case_request(p_request_id uuid, p_approve boolean, p_notes text, p_expected_status text DEFAULT 'PENDING'::text, p_idempotency_key text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_code text;
  v_req record;
  v_case record;
  v_target record;
  v_flag text;
  v_transition jsonb;
  v_result jsonb;
  v_existing jsonb;
  v_today date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;
  IF coalesce(btrim(p_notes), '') = '' THEN
    RAISE EXCEPTION 'REVIEW_NOTES_REQUIRED' USING ERRCODE = '22023';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT result_json INTO v_existing FROM public.ce_case_command_idempotency
      WHERE idempotency_key = p_idempotency_key;
    IF v_existing IS NOT NULL THEN
      RETURN v_existing || jsonb_build_object('replayed', true);
    END IF;
  END IF;

  IF NOT public.ce_actor_can(v_actor, 'compliance.cases.approve_requests') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_req FROM public.ce_case_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;

  IF v_req.status <> coalesce(p_expected_status, 'PENDING') OR v_req.status <> 'PENDING' THEN
    RAISE EXCEPTION 'REQUEST_NOT_PENDING' USING ERRCODE = '40001';
  END IF;

  v_code := public.ce_actor_user_code(v_actor);

  -- Maker-checker: the requester may not review their own request
  IF v_req.requested_by = v_code
     OR (v_req.metadata ->> 'requested_by_user_id') = v_actor::text THEN
    RAISE EXCEPTION 'MAKER_CHECKER_VIOLATION' USING ERRCODE = '42501';
  END IF;

  v_flag := CASE v_req.request_type
    WHEN 'CLOSURE' THEN 'compliance.core.case_closure_approval'
    WHEN 'REOPEN' THEN 'compliance.core.case_reopen'
    ELSE 'compliance.core.case_merge' END;
  IF NOT public.ce_feature_flag_enabled(v_flag) THEN
    RAISE EXCEPTION 'FEATURE_DISABLED' USING ERRCODE = '55000';
  END IF;

  UPDATE public.ce_case_requests SET
    status = CASE WHEN p_approve THEN 'APPROVED' ELSE 'REJECTED' END,
    reviewed_by = v_code,
    reviewed_at = now(),
    review_notes = btrim(p_notes),
    metadata = coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object('reviewed_by_user_id', v_actor,
                            'review_correlation_id', p_correlation_id),
    updated_at = now()
  WHERE id = p_request_id;

  IF p_approve THEN
    SELECT * INTO v_case FROM public.ce_cases WHERE id = v_req.case_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'CASE_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;

    IF v_req.request_type = 'CLOSURE' THEN
      IF upper(coalesce(v_case.status, '')) IN ('RESOLVED','CLOSED','COMPLETED') THEN
        RAISE EXCEPTION 'CASE_ALREADY_CLOSED' USING ERRCODE = '40001';
      END IF;
      v_transition := public.ce_apply_status_transition('case', v_req.case_id, 'CLOSE', v_code, v_req.reason);
      IF NOT coalesce((v_transition ->> 'success')::boolean, false) THEN
        RAISE EXCEPTION 'TRANSITION_FAILED: %', coalesce(v_transition ->> 'error', 'unknown')
          USING ERRCODE = '22023';
      END IF;
      UPDATE public.ce_cases
        SET closed_date = v_today, closure_reason = v_req.reason, updated_at = now(), updated_by = v_code
        WHERE id = v_req.case_id;

    ELSIF v_req.request_type = 'REOPEN' THEN
      IF upper(coalesce(v_case.status, '')) NOT IN ('RESOLVED','CLOSED','COMPLETED') THEN
        RAISE EXCEPTION 'CASE_NOT_CLOSED' USING ERRCODE = '40001';
      END IF;
      v_transition := public.ce_apply_status_transition('case', v_req.case_id, 'REOPEN', v_code, v_req.reason);
      IF NOT coalesce((v_transition ->> 'success')::boolean, false) THEN
        RAISE EXCEPTION 'TRANSITION_FAILED: %', coalesce(v_transition ->> 'error', 'unknown')
          USING ERRCODE = '22023';
      END IF;
      UPDATE public.ce_cases
        SET closed_date = NULL, closure_reason = NULL,
            reopened_count = coalesce(reopened_count, 0) + 1,
            updated_at = now(), updated_by = v_code
        WHERE id = v_req.case_id;

    ELSIF v_req.request_type = 'MERGE' THEN
      IF v_req.target_case_id IS NULL THEN
        RAISE EXCEPTION 'TARGET_REQUIRED' USING ERRCODE = '22023';
      END IF;
      IF v_req.target_case_id = v_req.case_id THEN
        RAISE EXCEPTION 'TARGET_SAME_AS_SOURCE' USING ERRCODE = '22023';
      END IF;
      IF coalesce(v_case.is_merged, false)
         OR upper(coalesce(v_case.status, '')) IN ('RESOLVED','CLOSED','COMPLETED') THEN
        RAISE EXCEPTION 'SOURCE_NOT_ELIGIBLE' USING ERRCODE = '40001';
      END IF;
      SELECT * INTO v_target FROM public.ce_cases WHERE id = v_req.target_case_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
      IF coalesce(v_target.is_deleted, false)
         OR coalesce(v_target.is_merged, false)
         OR upper(coalesce(v_target.status, '')) IN ('RESOLVED','CLOSED','COMPLETED','CANCELLED') THEN
        RAISE EXCEPTION 'TARGET_NOT_ELIGIBLE' USING ERRCODE = '40001';
      END IF;
      IF v_target.merged_into_case_id = v_req.case_id THEN
        RAISE EXCEPTION 'CIRCULAR_MERGE' USING ERRCODE = '22023';
      END IF;

      v_transition := public.ce_apply_status_transition('case', v_req.case_id, 'CLOSE', v_code,
                        'Merged: ' || v_req.reason);
      IF NOT coalesce((v_transition ->> 'success')::boolean, false) THEN
        RAISE EXCEPTION 'TRANSITION_FAILED: %', coalesce(v_transition ->> 'error', 'unknown')
          USING ERRCODE = '22023';
      END IF;
      UPDATE public.ce_cases
        SET is_merged = true, merged_into_case_id = v_req.target_case_id,
            closed_date = v_today, closure_reason = 'Merged: ' || v_req.reason,
            updated_at = now(), updated_by = v_code
        WHERE id = v_req.case_id;
    END IF;
  END IF;

  PERFORM public.ce_case_command_audit(
    v_actor,
    CASE WHEN p_approve THEN 'CE_CASE_REQUEST_APPROVED' ELSE 'CE_CASE_REQUEST_REJECTED' END,
    v_req.request_type, p_request_id::text, 'SUCCESS',
    jsonb_build_object('case_id', v_req.case_id, 'target_case_id', v_req.target_case_id,
                       'approved', p_approve),
    btrim(p_notes), p_correlation_id);

  v_result := jsonb_build_object('ok', true, 'request_id', p_request_id,
                'status', CASE WHEN p_approve THEN 'APPROVED' ELSE 'REJECTED' END,
                'request_type', v_req.request_type, 'replayed', false);

  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO public.ce_case_command_idempotency
      (idempotency_key, command_name, actor_user_id, correlation_id, result_json)
    VALUES (p_idempotency_key, 'ce_review_case_request', v_actor, p_correlation_id, v_result)
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_rule_history_record_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_by varchar(50);
  v_code text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'INSERT';
    v_by := COALESCE(NEW.created_by, NEW.updated_by);
    v_code := NEW.rule_code;
    INSERT INTO public.ce_rule_history
      (rule_table, rule_id, rule_code, action, before_value, after_value, changed_by)
    VALUES
      (TG_TABLE_NAME, NEW.id, v_code, v_action, NULL, to_jsonb(NEW), v_by);
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF COALESCE(OLD.is_enabled, false) = false AND COALESCE(NEW.is_enabled, false) = true THEN
      v_action := 'ACTIVATE';
    ELSIF COALESCE(OLD.is_enabled, false) = true AND COALESCE(NEW.is_enabled, false) = false THEN
      v_action := 'DEACTIVATE';
    ELSE
      v_action := 'UPDATE';
    END IF;
    v_by := COALESCE(NEW.updated_by, OLD.updated_by);
    v_code := COALESCE(NEW.rule_code, OLD.rule_code);
    INSERT INTO public.ce_rule_history
      (rule_table, rule_id, rule_code, action, before_value, after_value, changed_by)
    VALUES
      (TG_TABLE_NAME, NEW.id, v_code, v_action, to_jsonb(OLD), to_jsonb(NEW), v_by);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.ce_rule_history
      (rule_table, rule_id, rule_code, action, before_value, after_value, changed_by)
    VALUES
      (TG_TABLE_NAME, OLD.id, OLD.rule_code, 'DELETE', to_jsonb(OLD), NULL, OLD.updated_by);
    RETURN OLD;
  END IF;
  RETURN NULL;
END
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_employer_compliance_refresh(p_dry_run boolean DEFAULT false, p_batch_size integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
  v_errors INT := 0;
  v_employer RECORD;
  v_last_c3 RECORD;
  v_filing_status VARCHAR(30);
  v_payment_status VARCHAR(30);
  v_overall_status VARCHAR(30);
  v_arrears NUMERIC;
BEGIN
  FOR v_employer IN
    SELECT em.regno AS employer_id, em.name, em.status
    FROM er_master em
    WHERE em.status IS NOT NULL
    LIMIT p_batch_size
  LOOP
    v_processed := v_processed + 1;
    BEGIN
      -- Get latest C3 filing
      SELECT period, posting_status INTO v_last_c3
      FROM cn_c3_reported
      WHERE payer_id = v_employer.employer_id
      ORDER BY period DESC LIMIT 1;

      -- Determine filing status
      IF v_last_c3.period IS NULL THEN
        v_filing_status := 'never_filed';
      ELSE
        v_filing_status := 'filed';
      END IF;

      -- Get arrears from ledger
      SELECT COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE -amount END), 0)
      INTO v_arrears
      FROM ce_employer_financial_ledger
      WHERE employer_id = v_employer.employer_id;

      v_payment_status := CASE WHEN v_arrears > 0 THEN 'arrears' WHEN v_arrears = 0 THEN 'current' ELSE 'credit' END;
      v_overall_status := CASE
        WHEN v_filing_status = 'never_filed' THEN 'non_compliant'
        WHEN v_arrears > 0 THEN 'partially_compliant'
        ELSE 'compliant'
      END;

      IF NOT p_dry_run THEN
        INSERT INTO ce_employer_compliance_status (
          employer_id, filing_status, payment_status, overall_compliance_status,
          current_arrears_amount, last_filing_period, last_reviewed_at
        ) VALUES (
          v_employer.employer_id, v_filing_status, v_payment_status, v_overall_status,
          v_arrears, v_last_c3.period, now()
        )
        ON CONFLICT (employer_id) DO UPDATE SET
          filing_status = EXCLUDED.filing_status,
          payment_status = EXCLUDED.payment_status,
          overall_compliance_status = EXCLUDED.overall_compliance_status,
          current_arrears_amount = EXCLUDED.current_arrears_amount,
          last_filing_period = EXCLUDED.last_filing_period,
          last_reviewed_at = now(),
          updated_at = now();
        v_affected := v_affected + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', v_errors, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_employer_flag_generation(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
  v_errors INT := 0;
  v_emp RECORD;
BEGIN
  FOR v_emp IN
    SELECT cs.employer_id, cs.current_arrears_amount, cs.overall_compliance_status,
           rp.risk_band, rp.overall_risk_score
    FROM ce_employer_compliance_status cs
    LEFT JOIN ce_employer_risk_profile rp ON rp.employer_id = cs.employer_id
  LOOP
    v_processed := v_processed + 1;
    BEGIN
      IF NOT p_dry_run THEN
        -- High arrears flag
        IF COALESCE(v_emp.current_arrears_amount, 0) > 50000 THEN
          INSERT INTO ce_employer_compliance_flags (employer_id, flag_type, flag_reason, is_active)
          VALUES (v_emp.employer_id, 'high_arrears', 'Arrears exceed $50,000 threshold', true)
          ON CONFLICT DO NOTHING;
          v_affected := v_affected + 1;
        END IF;
        -- Critical risk flag
        IF v_emp.risk_band = 'critical' THEN
          INSERT INTO ce_employer_compliance_flags (employer_id, flag_type, flag_reason, is_active)
          VALUES (v_emp.employer_id, 'critical_risk', 'Risk band is critical', true)
          ON CONFLICT DO NOTHING;
          v_affected := v_affected + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', v_errors, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_employer_risk_refresh(p_dry_run boolean DEFAULT false, p_batch_size integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
  v_errors INT := 0;
  v_emp RECORD;
  v_arrears NUMERIC;
  v_score NUMERIC;
  v_band VARCHAR(20);
BEGIN
  FOR v_emp IN
    SELECT employer_id, current_arrears_amount, overall_compliance_status
    FROM ce_employer_compliance_status
    LIMIT p_batch_size
  LOOP
    v_processed := v_processed + 1;
    BEGIN
      v_arrears := COALESCE(v_emp.current_arrears_amount, 0);
      -- Simple scoring: arrears-driven with status modifier
      v_score := LEAST(100, GREATEST(0,
        CASE
          WHEN v_arrears > 500000 THEN 95
          WHEN v_arrears > 150000 THEN 75
          WHEN v_arrears > 50000 THEN 55
          WHEN v_arrears > 10000 THEN 35
          ELSE 15
        END +
        CASE WHEN v_emp.overall_compliance_status = 'non_compliant' THEN 5 ELSE 0 END
      ));
      v_band := CASE
        WHEN v_score >= 80 THEN 'critical'
        WHEN v_score >= 60 THEN 'high'
        WHEN v_score >= 40 THEN 'medium'
        WHEN v_score >= 20 THEN 'low'
        ELSE 'minimal'
      END;

      IF NOT p_dry_run THEN
        INSERT INTO ce_employer_risk_profile (
          employer_id, overall_risk_score, risk_band, last_assessed_at
        ) VALUES (
          v_emp.employer_id, v_score, v_band, now()
        )
        ON CONFLICT (employer_id) DO UPDATE SET
          overall_risk_score = EXCLUDED.overall_risk_score,
          risk_band = EXCLUDED.risk_band,
          last_assessed_at = now(),
          updated_at = now();
        v_affected := v_affected + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', v_errors, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_group_rollup_refresh(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
BEGIN
  -- Count groups
  SELECT COUNT(*) INTO v_processed FROM ce_employer_groups WHERE is_active = true;

  -- The group summary view (ce_employer_group_summary_view) auto-aggregates.
  -- This job refreshes any materialized caches if needed.
  -- Currently the view is live so this is a validation pass.

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', 0, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_notice_recipient_validation(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
  v_rec RECORD;
BEGIN
  FOR v_rec IN
    SELECT id, employer_id, recipient_email, recipient_name
    FROM ce_employer_notice_recipients
    WHERE is_active = true
  LOOP
    v_processed := v_processed + 1;
    IF v_rec.recipient_email IS NULL OR v_rec.recipient_email = '' THEN
      IF NOT p_dry_run THEN
        INSERT INTO ce_employer_compliance_flags (employer_id, flag_type, flag_reason, is_active)
        VALUES (v_rec.employer_id, 'invalid_notice_contact', 'Notice recipient missing email: ' || COALESCE(v_rec.recipient_name, 'unknown'), true)
        ON CONFLICT DO NOTHING;
      END IF;
      v_affected := v_affected + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', 0, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_recon_exception_detection(p_dry_run boolean DEFAULT false, p_tolerance numeric DEFAULT 0.01)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
  v_emp RECORD;
  v_source_total NUMERIC;
  v_ledger_total NUMERIC;
BEGIN
  FOR v_emp IN
    SELECT DISTINCT employer_id FROM ce_employer_compliance_status
  LOOP
    v_processed := v_processed + 1;

    -- Source total from C3
    SELECT COALESCE(SUM(COALESCE(emp_ss_amt_rpt,0) + COALESCE(emp_pe_amt_rpt,0) + COALESCE(emp_levy_amt_rpt,0)), 0)
    INTO v_source_total
    FROM cn_c3_reported WHERE payer_id = v_emp.employer_id;

    -- Ledger total
    SELECT COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE 0 END), 0)
    INTO v_ledger_total
    FROM ce_employer_financial_ledger WHERE employer_id = v_emp.employer_id;

    IF ABS(v_source_total - v_ledger_total) > p_tolerance THEN
      IF NOT p_dry_run THEN
        INSERT INTO ce_employer_compliance_flags (employer_id, flag_type, flag_reason, is_active)
        VALUES (v_emp.employer_id, 'recon_exception',
          'Source/ledger mismatch: source=' || v_source_total || ' ledger=' || v_ledger_total, true)
        ON CONFLICT DO NOTHING;
      END IF;
      v_affected := v_affected + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', 0, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_run_stale_employer_review(p_dry_run boolean DEFAULT false, p_stale_months integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed INT := 0;
  v_affected INT := 0;
  v_cutoff DATE;
BEGIN
  v_cutoff := (now() - (p_stale_months || ' months')::interval)::date;

  SELECT COUNT(*) INTO v_processed
  FROM er_master em
  LEFT JOIN ce_employer_compliance_status cs ON cs.employer_id = em.regno
  WHERE em.status = 'A'
    AND (cs.last_reviewed_at IS NULL OR cs.last_reviewed_at < v_cutoff);

  IF NOT p_dry_run THEN
    INSERT INTO ce_employer_compliance_flags (employer_id, flag_type, flag_reason, is_active)
    SELECT em.regno, 'stale_review', 'No compliance review in ' || p_stale_months || ' months', true
    FROM er_master em
    LEFT JOIN ce_employer_compliance_status cs ON cs.employer_id = em.regno
    WHERE em.status = 'A'
      AND (cs.last_reviewed_at IS NULL OR cs.last_reviewed_at < v_cutoff)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_affected = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object(
    'processed', v_processed, 'affected', v_affected,
    'errors', 0, 'dry_run', p_dry_run
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_search_merge_candidates(p_case_id uuid, p_search text, p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, case_number text, employer_name text, status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_term text := btrim(coalesce(p_search, ''));
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '42501';
  END IF;
  IF NOT public.ce_actor_can(v_actor, 'compliance.cases.manage') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF char_length(v_term) < 2 OR char_length(v_term) > 100 THEN
    RAISE EXCEPTION 'INVALID_SEARCH_LENGTH' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT c.id, c.case_number::text, c.employer_name::text, c.status::text
  FROM public.ce_cases c
  WHERE c.id <> p_case_id
    AND coalesce(c.is_deleted, false) = false
    AND coalesce(c.is_merged, false) = false
    AND upper(coalesce(c.status, '')) NOT IN ('RESOLVED','CLOSED','COMPLETED','CANCELLED')
    AND (c.case_number ILIKE '%' || v_term || '%' ESCAPE '\'
         OR c.employer_name ILIKE '%' || v_term || '%' ESCAPE '\')
  ORDER BY c.case_number
  LIMIT LEAST(GREATEST(coalesce(p_limit, 20), 1), 50);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.ce_sync_c3_to_ledger(p_employer_id character varying DEFAULT NULL::character varying, p_period date DEFAULT NULL::date, p_limit integer DEFAULT 500, p_dry_run boolean DEFAULT false, p_triggered_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run_id UUID := gen_random_uuid();
  v_rec RECORD;
  v_processed INTEGER := 0;
  v_posted INTEGER := 0;
  v_skipped INTEGER := 0;
  v_failed INTEGER := 0;
  v_errors JSONB := '[]'::JSONB;
  v_entry_id UUID;
  v_entry_ids UUID[];
  v_idem_key VARCHAR;
  v_amount NUMERIC;
  v_fund ce_fund_type;
  v_entry_type ce_ledger_entry_type;
  v_desc TEXT;
  v_component RECORD;
  v_snapshot VARCHAR;
  v_period_code TEXT;
BEGIN
  FOR v_rec IN
    SELECT * FROM ce_v_c3_unposted_to_ledger v
    WHERE (p_employer_id IS NULL OR v.payer_id = p_employer_id)
      AND (p_period IS NULL OR v.period = p_period)
    ORDER BY v.period, v.payer_id
    LIMIT p_limit
  LOOP
    v_processed := v_processed + 1;
    v_entry_ids := '{}';
    v_snapshot := COALESCE(v_rec.posting_status, 'VAC');
    v_period_code := to_char(v_rec.period, 'YYYY-MM');

    BEGIN
      FOR v_component IN
        SELECT * FROM (VALUES
          ('SS',   'C3_DUES_POSTED',   v_rec.ss_dues,      'c3-ss-'),
          ('LEVY', 'C3_DUES_POSTED',   v_rec.levy_dues,    'c3-levy-'),
          ('EI',   'C3_DUES_POSTED',   v_rec.ei_dues,      'c3-ei-'),
          ('SS',   'PENALTY_ASSESSED', v_rec.ss_penalty,   'c3-fine-ss-'),
          ('LEVY', 'PENALTY_ASSESSED', v_rec.levy_penalty, 'c3-fine-levy-'),
          ('EI',   'PENALTY_ASSESSED', v_rec.pe_penalty,   'c3-fine-pe-')
        ) AS t(fund, entry_type, amount, key_prefix)
      LOOP
        v_amount := v_component.amount;
        IF v_amount IS NULL OR v_amount <= 0 THEN
          CONTINUE;
        END IF;

        -- Idempotency key uses full ISO date for stability with prior seeds
        v_idem_key := v_component.key_prefix || v_rec.payer_id || '-' || v_rec.period::text || '-' || v_rec.sequence_no::text;
        v_fund := v_component.fund::ce_fund_type;
        v_entry_type := v_component.entry_type::ce_ledger_entry_type;
        v_desc := v_component.entry_type || ' from C3 ' || v_period_code || ' seq ' || v_rec.sequence_no;

        IF p_dry_run THEN
          v_posted := v_posted + 1;
          CONTINUE;
        END IF;

        SELECT id INTO v_entry_id
        FROM ce_employer_financial_ledger
        WHERE idempotency_key = v_idem_key;

        IF v_entry_id IS NOT NULL THEN
          v_skipped := v_skipped + 1;
          v_entry_ids := array_append(v_entry_ids, v_entry_id);
          CONTINUE;
        END IF;

        v_entry_id := ce_post_ledger_entry(
          p_employer_id := v_rec.payer_id,
          p_employer_name := v_rec.employer_name,
          p_entry_type := v_entry_type,
          p_fund_type := v_fund,
          p_period := v_period_code,
          p_amount := v_amount,
          p_description := v_desc,
          p_reference_type := 'C3_SUBMISSION',
          p_idempotency_key := v_idem_key,
          p_posted_by := p_triggered_by
        );

        v_entry_ids := array_append(v_entry_ids, v_entry_id);
        v_posted := v_posted + 1;
      END LOOP;

      IF NOT p_dry_run THEN
        INSERT INTO ce_c3_ledger_sync_log (
          payer_id, period, sequence_no, posting_status_snapshot,
          sync_status, ledger_entry_ids, sync_run_id, synced_by
        ) VALUES (
          v_rec.payer_id, v_rec.period, v_rec.sequence_no, v_snapshot,
          'success', v_entry_ids, v_run_id, p_triggered_by
        )
        ON CONFLICT ON CONSTRAINT uq_ce_c3_sync_source DO UPDATE
          SET sync_status = 'success',
              ledger_entry_ids = EXCLUDED.ledger_entry_ids,
              sync_run_id = EXCLUDED.sync_run_id,
              synced_at = now(),
              synced_by = EXCLUDED.synced_by,
              error_message = NULL,
              posting_status_snapshot = EXCLUDED.posting_status_snapshot;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_errors := v_errors || jsonb_build_object(
        'payer_id', v_rec.payer_id,
        'period', v_rec.period::text,
        'sequence_no', v_rec.sequence_no,
        'error', SQLERRM
      );

      IF NOT p_dry_run THEN
        INSERT INTO ce_c3_ledger_sync_log (
          payer_id, period, sequence_no, posting_status_snapshot,
          sync_status, sync_run_id, synced_by, error_message
        ) VALUES (
          v_rec.payer_id, v_rec.period, v_rec.sequence_no, v_snapshot,
          'failed', v_run_id, p_triggered_by, SQLERRM
        )
        ON CONFLICT ON CONSTRAINT uq_ce_c3_sync_source DO UPDATE
          SET sync_status = 'failed',
              sync_run_id = EXCLUDED.sync_run_id,
              synced_at = now(),
              error_message = EXCLUDED.error_message,
              posting_status_snapshot = EXCLUDED.posting_status_snapshot;
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'run_id', v_run_id,
    'dry_run', p_dry_run,
    'processed_count', v_processed,
    'posted_count', v_posted,
    'skipped_count', v_skipped,
    'failed_count', v_failed,
    'errors', v_errors
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_sync_payments_to_ledger(p_employer_id character varying DEFAULT NULL::character varying, p_payment_date_from timestamp without time zone DEFAULT NULL::timestamp without time zone, p_payment_date_to timestamp without time zone DEFAULT NULL::timestamp without time zone, p_source_payment_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 500, p_dry_run boolean DEFAULT false, p_triggered_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec RECORD;
  v_run_id UUID := gen_random_uuid();
  v_processed INT := 0;
  v_posted INT := 0;
  v_skipped INT := 0;
  v_failed INT := 0;
  v_total_amount NUMERIC := 0;
  v_errors JSONB := '[]'::jsonb;
  v_ledger_id UUID;
  v_fund ce_fund_type;
BEGIN
  FOR v_rec IN
    SELECT * FROM public.ce_v_payments_unposted_to_ledger vp
    WHERE (p_employer_id IS NULL OR vp.employer_id = p_employer_id)
      AND (p_payment_date_from IS NULL OR vp.payment_date >= p_payment_date_from)
      AND (p_payment_date_to IS NULL OR vp.payment_date <= p_payment_date_to)
      AND (p_source_payment_id IS NULL OR vp.source_payment_id = p_source_payment_id)
    ORDER BY vp.payment_date ASC, vp.source_payment_id ASC
    LIMIT p_limit
  LOOP
    v_processed := v_processed + 1;

    IF p_dry_run THEN
      INSERT INTO public.ce_payment_ledger_sync_log (
        source_table, source_payment_id, employer_id, receipt_no,
        payment_date, amount_snapshot, fund_code, payment_code,
        status_snapshot, sync_status, sync_run_id, synced_at, synced_by
      ) VALUES (
        v_rec.payment_source_table, v_rec.source_payment_id, v_rec.employer_id,
        v_rec.receipt_number, v_rec.payment_date, v_rec.amount,
        v_rec.fund_code, v_rec.payment_code, v_rec.receipt_status,
        'dry_run', v_run_id, now(), p_triggered_by
      ) ON CONFLICT (source_table, source_payment_id, fund_code) DO NOTHING;
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      v_fund := CASE
        WHEN UPPER(COALESCE(v_rec.fund_code,'')) LIKE '%SS%' THEN 'SS'::ce_fund_type
        WHEN UPPER(COALESCE(v_rec.fund_code,'')) LIKE '%LEV%' THEN 'LEVY'::ce_fund_type
        WHEN UPPER(COALESCE(v_rec.fund_code,'')) LIKE '%EI%' OR UPPER(COALESCE(v_rec.fund_code,'')) LIKE '%PE%' THEN 'EI'::ce_fund_type
        ELSE 'SS'::ce_fund_type
      END;

      v_ledger_id := public.ce_post_ledger_entry(
        p_employer_id := v_rec.employer_id,
        p_entry_type := 'PAYMENT_RECEIVED'::ce_ledger_entry_type,
        p_fund_type := v_fund,
        p_period := COALESCE(to_char(v_rec.period, 'YYYY-MM'), to_char(v_rec.payment_date, 'YYYY-MM')),
        p_amount := v_rec.amount,
        p_description := 'Payment sync from ' || v_rec.payment_source_table || ' #' || v_rec.source_payment_id::text,
        p_reference_type := 'payment_sync',
        p_idempotency_key := v_rec.sync_key,
        p_posted_by := p_triggered_by
      );

      INSERT INTO public.ce_payment_ledger_sync_log (
        source_table, source_payment_id, employer_id, receipt_no,
        payment_date, amount_snapshot, fund_code, payment_code,
        status_snapshot, sync_status, ledger_entry_ids,
        sync_run_id, synced_at, synced_by
      ) VALUES (
        v_rec.payment_source_table, v_rec.source_payment_id, v_rec.employer_id,
        v_rec.receipt_number, v_rec.payment_date, v_rec.amount,
        v_rec.fund_code, v_rec.payment_code, v_rec.receipt_status,
        'posted', jsonb_build_array(v_ledger_id),
        v_run_id, now(), p_triggered_by
      ) ON CONFLICT (source_table, source_payment_id, fund_code) DO UPDATE
        SET sync_status = 'posted',
            ledger_entry_ids = jsonb_build_array(v_ledger_id),
            synced_at = now(), synced_by = p_triggered_by, sync_run_id = v_run_id;

      v_posted := v_posted + 1;
      v_total_amount := v_total_amount + COALESCE(v_rec.amount, 0);

    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_errors := v_errors || jsonb_build_object(
        'source_payment_id', v_rec.source_payment_id,
        'employer_id', v_rec.employer_id,
        'error', SQLERRM
      );
      INSERT INTO public.ce_payment_ledger_sync_log (
        source_table, source_payment_id, employer_id, receipt_no,
        payment_date, amount_snapshot, fund_code, payment_code,
        status_snapshot, sync_status, error_message,
        sync_run_id, synced_at, synced_by
      ) VALUES (
        v_rec.payment_source_table, v_rec.source_payment_id, v_rec.employer_id,
        v_rec.receipt_number, v_rec.payment_date, v_rec.amount,
        v_rec.fund_code, v_rec.payment_code, v_rec.receipt_status,
        'failed', SQLERRM, v_run_id, now(), p_triggered_by
      ) ON CONFLICT (source_table, source_payment_id, fund_code) DO UPDATE
        SET sync_status = 'failed', error_message = SQLERRM,
            synced_at = now(), sync_run_id = v_run_id;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'run_id', v_run_id, 'processed_count', v_processed,
    'posted_count', v_posted, 'skipped_count', v_skipped,
    'failed_count', v_failed, 'total_amount_processed', v_total_amount,
    'dry_run', p_dry_run, 'error_summary', v_errors
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_trigger_violation_to_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case_id UUID;
  v_case_number VARCHAR;
  v_next_seq INT;
BEGIN
  -- Only on INSERT
  IF TG_OP = 'INSERT' THEN
    -- Find existing open case for this employer
    SELECT id INTO v_case_id
    FROM ce_cases
    WHERE employer_id = NEW.employer_id
      AND status IN ('OPEN', 'UNDER_REVIEW', 'NOTICE_ISSUED', 'AWAITING_RESPONSE')
      AND (is_deleted = false OR is_deleted IS NULL)
    ORDER BY opened_date DESC
    LIMIT 1;

    -- Link violation to case
    IF v_case_id IS NOT NULL THEN
      INSERT INTO ce_case_violations (case_id, violation_id, linked_by)
      VALUES (v_case_id, NEW.id, COALESCE(NEW.created_by, 'SYSTEM'))
      ON CONFLICT (case_id, violation_id) DO NOTHING;

      -- Update case totals
      UPDATE ce_cases
      SET updated_at = now(),
          updated_by = COALESCE(NEW.created_by, 'SYSTEM')
      WHERE id = v_case_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ce_update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.cease_voluntary_contributor(p_ssn character varying, p_reason character varying DEFAULT 'MANUAL'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_active_record RECORD;
BEGIN
  -- Find active VC record
  SELECT * INTO v_active_record
  FROM public.ip_vol_contrib
  WHERE ssn = p_ssn AND date_ceased IS NULL;
  
  IF v_active_record IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No active voluntary contributor record found'
    );
  END IF;

  -- Update ip_vol_contrib - set date_ceased
  UPDATE public.ip_vol_contrib
  SET date_ceased = NOW()
  WHERE ssn = p_ssn AND date_ceased IS NULL;

  -- Update ip_master - set vol_contrib = 'N'
  UPDATE public.ip_master
  SET vol_contrib = 'N',
      updated_at = NOW()
  WHERE ssn = p_ssn;

  RETURN jsonb_build_object(
    'success', true,
    'ssn', p_ssn,
    'date_ceased', CURRENT_DATE,
    'reason', p_reason
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.certify_all_comm_hub_template_versions()
 RETURNS TABLE(template_version_id uuid, template_code text, template_purpose text, result text, is_certified boolean, blocker_count integer, warning_count integer, detail jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT v.id, t.code,
         r->>'template_purpose', r->>'result',
         (r->>'is_certified')::boolean,
         (r->>'blocker_count')::int,
         (r->>'warning_count')::int,
         r
  FROM public.core_template_version v
  JOIN public.core_template t ON t.id = v.template_id
  CROSS JOIN LATERAL public.certify_comm_hub_template_version(v.id) AS r
  WHERE lower(COALESCE(v.status,'')) IN ('active','published');
$function$;
CREATE OR REPLACE FUNCTION public.certify_comm_hub_dry_run(p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc jsonb;
  v_exec public.communication_dry_run_execution%ROWTYPE;
  v_snap public.communication_preview_snapshot%ROWTYPE;
  v_appr public.communication_preview_approval%ROWTYPE;
  v_msg public.communication_message%ROWTYPE;
  v_tr jsonb; v_bind jsonb;
  v_cert_id uuid; v_existing_cert uuid; v_cert_no text;
  v_provider_count int;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation('comm-hub-dry-run','CERTIFY_DRY_RUN');
  IF NOT COALESCE((v_svc->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','service_identity',
      'failure_stage','SERVICE_IDENTITY',
      'resolved_role', v_svc->>'resolved_role',
      'role_source', v_svc->>'role_source',
      'blockers', COALESCE(v_svc->'blockers','[]'::jsonb));
  END IF;

  IF p_execution_id IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED',
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_id_required')));
  END IF;

  SELECT * INTO v_exec FROM public.communication_dry_run_execution WHERE id=p_execution_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED',
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_not_found')));
  END IF;

  SELECT id INTO v_existing_cert
    FROM public.communication_dry_run_certification
    WHERE preview_snapshot_id=v_exec.preview_snapshot_id
      AND preview_approval_id=v_exec.preview_approval_id
      AND status='ACTIVE' LIMIT 1;
  IF v_existing_cert IS NOT NULL THEN
    RETURN jsonb_build_object('status','IDEMPOTENT','certification_id',v_existing_cert,
      'dry_run_execution_id', v_exec.id, 'note','existing ACTIVE certification returned');
  END IF;

  SELECT * INTO v_snap FROM public.communication_preview_snapshot WHERE id=v_exec.preview_snapshot_id;
  SELECT * INTO v_appr FROM public.communication_preview_approval WHERE id=v_exec.preview_approval_id;

  v_tr := public.check_comm_hub_runtime_transition_safe('CERTIFY_DRY_RUN',
    jsonb_build_object('module_code', v_exec.module_code,'event_code', v_exec.event_code,
      'channel', v_exec.channel,'preview_snapshot_id', v_exec.preview_snapshot_id,
      'preview_approval_id', v_exec.preview_approval_id,
      'correlation_id', v_snap.correlation_id,
      'service_operation', 'CERTIFY_DRY_RUN',
      'execution_id', v_exec.id,'invoked_from','certify_comm_hub_dry_run'));
  IF NOT COALESCE((v_tr->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','runtime_transition',
      'blockers', COALESCE(v_tr->'blockers','[]'::jsonb),
      'transition_log_id', v_tr->>'transition_log_id');
  END IF;

  IF v_exec.state <> 'PROCESSED' THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','execution_state',
      'blockers', jsonb_build_array(jsonb_build_object('code','EXECUTION_NOT_PROCESSED','current_state',v_exec.state)));
  END IF;

  v_bind := public.check_comm_hub_preview_approval_binding(
    v_exec.preview_approval_id, v_exec.preview_snapshot_id, v_snap.correlation_id,
    v_appr.content_hash_at_approval, v_appr.recipient_set_hash_at_approval,
    v_appr.configuration_hash_at_approval);
  IF NOT COALESCE((v_bind->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','approval_binding',
      'blockers', COALESCE(v_bind->'blockers','[]'::jsonb));
  END IF;

  IF v_exec.request_id IS NULL OR v_exec.message_id IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','linkage',
      'blockers', jsonb_build_array(jsonb_build_object('code','EXECUTION_LINKAGE_INCOMPLETE')));
  END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id=v_exec.message_id;
  IF NOT FOUND OR v_msg.request_id <> v_exec.request_id OR COALESCE(v_msg.send_context,'') <> 'dry_run' THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','message_linkage',
      'blockers', jsonb_build_array(jsonb_build_object('code','MESSAGE_LINKAGE_INVALID')));
  END IF;

  SELECT COUNT(*) INTO v_provider_count
    FROM public.communication_delivery_attempt
    WHERE message_id = v_exec.message_id;
  IF v_provider_count > 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','provider_call_absence',
      'blockers', jsonb_build_array(jsonb_build_object('code','PROVIDER_CALL_DETECTED','count',v_provider_count)));
  END IF;

  v_cert_no := 'DRC-' || to_char(now() at time zone 'utc','YYYYMMDDHH24MISS')
               || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,8);
  INSERT INTO public.communication_dry_run_certification(
    certification_no, module_code, event_code, channel,
    preview_snapshot_id, preview_approval_id,
    communication_request_id, communication_message_id, trace_id,
    recipient_set_hash, template_id, template_version_id, sender_profile_id,
    content_hash, configuration_version, recipient_policy_version,
    send_policy_version, review_policy_version,
    original_decision_id, result, status, provider_call_attempted)
  VALUES (
    v_cert_no, v_exec.module_code, v_exec.event_code, v_exec.channel,
    v_exec.preview_snapshot_id, v_exec.preview_approval_id,
    v_exec.request_id, v_exec.message_id, v_exec.trace_id,
    v_exec.recipient_set_hash, v_snap.template_id, v_snap.template_version_id, v_snap.sender_profile_id,
    v_appr.content_hash_at_approval, v_snap.configuration_version, v_snap.recipient_policy_version,
    NULL, NULL, v_exec.original_decision_id, 'DRY_RUN_PASSED','ACTIVE', false)
  RETURNING id INTO v_cert_id;

  UPDATE public.communication_dry_run_execution
    SET state='CERTIFIED', certification_id=v_cert_id, updated_at=now()
    WHERE id=v_exec.id;

  RETURN jsonb_build_object('status','CERTIFIED','certification_id',v_cert_id,
    'certification_no',v_cert_no,'dry_run_execution_id',v_exec.id,
    'evidence',jsonb_build_object(
      'service_operation','CERTIFY_DRY_RUN',
      'canonical_approval_evidence_hash', v_appr.canonical_approval_evidence_hash,
      'transition_log_id', v_tr->>'transition_log_id'));
EXCEPTION WHEN unique_violation THEN
  SELECT id INTO v_existing_cert FROM public.communication_dry_run_certification
    WHERE preview_snapshot_id=v_exec.preview_snapshot_id
      AND preview_approval_id=v_exec.preview_approval_id AND status='ACTIVE' LIMIT 1;
  RETURN jsonb_build_object('status','IDEMPOTENT','certification_id',v_existing_cert,
    'dry_run_execution_id', v_exec.id);
END; $function$;
CREATE OR REPLACE FUNCTION public.certify_comm_hub_event_automated_production(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_module text := p_payload->>'module_code';
  v_event  text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_reason text := p_payload->>'reason';
  v_typed  text := coalesce(p_payload->>'typed_confirmation','');
  v_current public.communication_hub_event_certification%ROWTYPE;
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_obs public.communication_manual_production_observation%ROWTYPE;
  v_att public.communication_delivery_attempt%ROWTYPE;
  v_msg public.communication_message%ROWTYPE;
  v_provider public.notification_providers%ROWTYPE;
  v_distinct_ok int;
  v_pinned uuid[];
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF v_typed <> 'CERTIFY AUTOMATED PRODUCTION' THEN RAISE EXCEPTION 'typed_confirmation_mismatch' USING ERRCODE='22023'; END IF;
  IF coalesce(length(trim(v_reason)),0) < 6 THEN RAISE EXCEPTION 'reason_required' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';
  IF NOT FOUND THEN RAISE EXCEPTION 'settings_missing' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_current FROM public.communication_hub_event_certification
    WHERE module_code=v_module AND event_code=v_event AND channel=v_channel FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'manual_production_certification_required' USING ERRCODE='22023'; END IF;

  IF v_current.status='live_cron_allowed' THEN
    RETURN jsonb_build_object('ok',true,'idempotent',true,'status','live_cron_allowed','certification_row_id',v_current.id);
  END IF;
  IF v_current.status<>'live_manual_only' THEN RAISE EXCEPTION 'event_not_in_live_manual_only' USING ERRCODE='22023'; END IF;
  IF v_current.drift_detected_at IS NOT NULL THEN RAISE EXCEPTION 'drift_detected_cannot_certify' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_obs FROM public.communication_manual_production_observation
    WHERE module_code=v_module AND event_code=v_event AND channel=v_channel
      AND event_certification_id=v_current.id
      AND send_context='manual_production'
      AND status='CONFIRMED' AND inbox_confirmation_status='CONFIRMED'
      AND provider_call_attempted=true AND provider_message_id IS NOT NULL
      AND delivery_attempt_id IS NOT NULL AND trace_id IS NOT NULL
      AND dispatched_at > v_current.approved_at
    ORDER BY dispatched_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'insufficient_manual_observation' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id=v_obs.message_id;
  IF NOT FOUND OR v_msg.status NOT IN ('sent','delivered') OR v_msg.test_mode=true THEN
    RAISE EXCEPTION 'observation_message_not_valid' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_att FROM public.communication_delivery_attempt WHERE id=v_obs.delivery_attempt_id;
  IF NOT FOUND OR v_att.status NOT IN ('success','delivered','sent') THEN
    RAISE EXCEPTION 'observation_attempt_not_successful' USING ERRCODE='22023'; END IF;
  IF v_att.provider_id IS NOT NULL THEN
    SELECT * INTO v_provider FROM public.notification_providers WHERE id=v_att.provider_id;
    IF FOUND AND lower(coalesce(v_provider.mode,'')) IN ('stub','dry_run','dryrun','test') THEN
      RAISE EXCEPTION 'observation_provider_is_stub_or_dry_run' USING ERRCODE='22023';
    END IF;
  END IF;

  -- Nine DISTINCT check codes, strictly tied to THIS event certification.
  SELECT array_agg(id), count(DISTINCT check_code)
    INTO v_pinned, v_distinct_ok
   FROM public.comm_hub_automation_readiness_results
  WHERE module_code=v_module AND event_code=v_event AND channel=v_channel
    AND event_certification_id = v_current.id
    AND result=true AND expires_at > now()
    AND checked_at > v_current.approved_at
    AND check_code IN ('scheduler','automatic_triggers','retry_worker','dead_letter',
                       'rate_limits','batch_limits','provider_circuit_breaker',
                       'emergency_stop','alerting_monitoring');
  IF v_distinct_ok < 9 THEN
    RAISE EXCEPTION 'automation_readiness_incomplete' USING ERRCODE='22023',
      DETAIL=format('distinct_ok=%s', v_distinct_ok);
  END IF;

  UPDATE public.communication_hub_event_certification
     SET status='live_cron_allowed',
         automation_certified_at=now(),
         automation_certified_by=v_uid,
         reason=v_reason,
         pinned_readiness_result_ids=v_pinned,
         pinned_configuration_version=v_settings.configuration_version
   WHERE id=v_current.id;

  UPDATE public.communication_hub_event_live_control
     SET status='live_cron_allowed', reason=v_reason,
         changed_by=v_uid, changed_at=now(), updated_at=now()
   WHERE module_code=v_module AND event_code=v_event;

  RETURN jsonb_build_object('ok',true,'status','live_cron_allowed',
    'certification_row_id',v_current.id,
    'pinned_readiness_count', array_length(v_pinned,1),
    'pinned_configuration_version', v_settings.configuration_version);
END $function$;
CREATE OR REPLACE FUNCTION public.certify_comm_hub_event_manual_production(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_module text := p_payload->>'module_code';
  v_event text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_ore_cert_id uuid := (p_payload->>'one_real_email_certification_id')::uuid;
  v_reason text := p_payload->>'reason';
  v_typed text := coalesce(p_payload->>'typed_confirmation','');
  v_ore record;
  v_exec record;
  v_grant record;
  v_msg record;
  v_att record;
  v_stub_cert_id uuid;
  v_row_id uuid;
  v_existing record;
  v_cfg_version bigint;
  v_sender_profile_id uuid;
  v_template_version_id uuid;
  v_template_hash text;
  v_current_fp text;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF v_typed <> 'CERTIFY MANUAL PRODUCTION' THEN RAISE EXCEPTION 'typed_confirmation_mismatch' USING ERRCODE='22023'; END IF;
  IF v_reason IS NULL OR length(trim(v_reason)) < 6 THEN RAISE EXCEPTION 'reason_required' USING ERRCODE='22023'; END IF;
  IF v_module IS NULL OR v_event IS NULL OR v_ore_cert_id IS NULL THEN
    RAISE EXCEPTION 'module_event_ore_required' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_existing FROM public.communication_hub_event_certification
    WHERE module_code=v_module AND event_code=v_event AND channel=v_channel FOR UPDATE;
  IF FOUND AND v_existing.status IN ('live_manual_only','live_cron_allowed') THEN
    RETURN jsonb_build_object('ok',true,'idempotent',true,'status',v_existing.status,'certification_row_id',v_existing.id);
  END IF;

  SELECT * INTO v_ore FROM public.communication_controlled_live_certification
   WHERE id=v_ore_cert_id AND certification_kind='ONE_REAL_EMAIL'
     AND module_code=v_module AND event_code=v_event AND channel=v_channel;

  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','CERTIFICATION_MISSING'));
  ELSE
    IF v_ore.invalidated_at IS NOT NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','CERTIFICATION_INVALIDATED'));
    END IF;
    IF v_ore.status NOT IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY') THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','ATTEMPT_NOT_SUCCESSFUL','status',v_ore.status));
    END IF;
    IF coalesce(v_ore.provider_message_id,'') = '' THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','PROVIDER_MESSAGE_ID_MISSING'));
    END IF;
    IF v_ore.trace_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','TRACE_MISSING'));
    END IF;
    IF coalesce(v_ore.manual_verification_status,'') <> 'CONFIRMED'
       OR v_ore.manual_verified_at IS NULL
       OR v_ore.manual_verification_recipient IS NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','INBOX_CONFIRMATION_MISSING'));
    END IF;

    IF v_ore.execution_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','LINEAGE_MISMATCH'));
    ELSE
      SELECT * INTO v_exec FROM public.communication_controlled_live_execution WHERE id=v_ore.execution_id;
      IF NOT FOUND OR COALESCE(v_exec.provider_call_attempted,false)=false THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','PROVIDER_CALL_NOT_ATTEMPTED'));
      END IF;

      SELECT * INTO v_grant FROM public.communication_controlled_live_grant
        WHERE execution_id=v_ore.execution_id ORDER BY issued_at DESC LIMIT 1;
      IF NOT FOUND OR v_grant.status <> 'CONSUMED' THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','GRANT_NOT_CONSUMED'));
      END IF;

      IF FOUND AND v_exec.message_id IS NOT NULL THEN
        SELECT * INTO v_msg FROM public.communication_message WHERE id=v_exec.message_id;
        IF NOT FOUND OR v_msg.status NOT IN ('sent','delivered') THEN
          v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','MESSAGE_NOT_SENT'));
        END IF;
      ELSE
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','MESSAGE_NOT_SENT'));
      END IF;

      IF FOUND AND v_exec.delivery_attempt_id IS NOT NULL THEN
        SELECT * INTO v_att FROM public.communication_delivery_attempt WHERE id=v_exec.delivery_attempt_id;
        IF NOT FOUND OR v_att.status <> 'success' OR COALESCE(v_att.provider_call_attempted,false)=false THEN
          v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','ATTEMPT_NOT_SUCCESSFUL'));
        END IF;
      ELSE
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','ATTEMPT_NOT_SUCCESSFUL'));
      END IF;

      IF FOUND AND COALESCE(v_exec.provider_call_attempted,false)=true
         AND v_ore.status NOT IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY') THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','RECONCILIATION_REQUIRED'));
      END IF;
    END IF;
  END IF;

  -- Runtime-mode version is captured but not used for evidence gating.
  SELECT configuration_version INTO v_cfg_version FROM public.communication_hub_control_settings WHERE singleton_guard='primary';

  IF v_ore.message_id IS NOT NULL THEN
    SELECT template_version_id, sender_profile_id INTO v_template_version_id, v_sender_profile_id
      FROM public.communication_message WHERE id = v_ore.message_id;
  END IF;

  BEGIN
    EXECUTE 'SELECT manifest_hash FROM public.core_template_version WHERE id=$1'
      INTO v_template_hash USING v_template_version_id;
  EXCEPTION WHEN undefined_table OR undefined_column THEN v_template_hash := NULL;
  END;

  -- Evidence-fingerprint drift check (safety-relevant inputs only).
  v_current_fp := public._comm_hub_evidence_fingerprint(
      v_module, v_event, v_channel,
      v_template_version_id, v_template_hash, v_sender_profile_id,
      v_ore.recipient_policy_version::text, v_ore.recipient_set_hash, NULL::text);

  IF v_ore.id IS NOT NULL AND v_ore.evidence_fingerprint IS NOT NULL
     AND v_ore.evidence_fingerprint <> v_current_fp THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','EVIDENCE_DRIFT',
      'stored', v_ore.evidence_fingerprint,
      'current', v_current_fp));
  END IF;

  IF jsonb_array_length(v_blockers) > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'stage6_prerequisites_not_met',
      'blockers', v_blockers,
      'one_real_email_certification_id', v_ore_cert_id
    );
  END IF;

  SELECT (audit_metadata->>'controlled_stub_certification_id')::uuid INTO v_stub_cert_id
    FROM public.communication_controlled_live_execution WHERE id = v_ore.execution_id;
  IF v_stub_cert_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error','stub_lineage_missing',
      'blockers', jsonb_build_array(jsonb_build_object('code','LINEAGE_MISMATCH')));
  END IF;

  -- Persist fingerprint on the ORE cert (backfill for legacy rows).
  IF v_ore.evidence_fingerprint IS NULL THEN
    UPDATE public.communication_controlled_live_certification
       SET evidence_fingerprint = v_current_fp
     WHERE id = v_ore.id;
  END IF;

  INSERT INTO public.communication_hub_event_certification
    (module_code,event_code,channel,status,
     controlled_stub_certification_id, one_real_email_certification_id,
     configuration_version, recipient_policy_version,
     template_version_id, template_manifest_hash,
     sender_profile_id, recipient_set_hash,
     evidence_fingerprint,
     approved_by, reason,
     manual_verification_status, manual_verified_at,
     manual_verified_by, manual_verified_recipient)
  VALUES
    (v_module, v_event, v_channel, 'live_manual_only',
     v_stub_cert_id, v_ore_cert_id,
     v_cfg_version, v_ore.recipient_policy_version,
     v_template_version_id, v_template_hash,
     v_sender_profile_id, v_ore.recipient_set_hash,
     v_current_fp,
     v_uid, v_reason,
     'CONFIRMED', v_ore.manual_verified_at,
     v_ore.manual_verified_by, v_ore.manual_verification_recipient)
  ON CONFLICT (module_code,event_code,channel) DO UPDATE
    SET status='live_manual_only',
        controlled_stub_certification_id=EXCLUDED.controlled_stub_certification_id,
        one_real_email_certification_id=EXCLUDED.one_real_email_certification_id,
        configuration_version=EXCLUDED.configuration_version,
        recipient_policy_version=EXCLUDED.recipient_policy_version,
        template_version_id=EXCLUDED.template_version_id,
        template_manifest_hash=EXCLUDED.template_manifest_hash,
        sender_profile_id=EXCLUDED.sender_profile_id,
        recipient_set_hash=EXCLUDED.recipient_set_hash,
        evidence_fingerprint=EXCLUDED.evidence_fingerprint,
        approved_by=EXCLUDED.approved_by, approved_at=now(),
        reason=EXCLUDED.reason,
        manual_verification_status='CONFIRMED',
        manual_verified_at=EXCLUDED.manual_verified_at,
        manual_verified_by=EXCLUDED.manual_verified_by,
        manual_verified_recipient=EXCLUDED.manual_verified_recipient,
        drift_detected_at=NULL, drift_reason=NULL, suspended_at=NULL,
        automation_certified_at=NULL, automation_certified_by=NULL
  RETURNING id INTO v_row_id;

  INSERT INTO public.communication_hub_event_live_control
    (module_code,event_code,status,risk_level,reason,changed_by)
  VALUES (v_module,v_event,'live_manual_only','medium',v_reason,v_uid)
  ON CONFLICT (module_code,event_code) DO UPDATE
    SET status='live_manual_only', reason=EXCLUDED.reason,
        changed_by=v_uid, changed_at=now(), updated_at=now();

  RETURN jsonb_build_object('ok',true,'certification_row_id',v_row_id,'status','live_manual_only',
    'derived',jsonb_build_object(
      'runtime_mode_version', v_cfg_version,
      'evidence_fingerprint', v_current_fp,
      'recipient_policy_version', v_ore.recipient_policy_version,
      'template_version_id', v_template_version_id,
      'template_manifest_hash', v_template_hash,
      'sender_profile_id', v_sender_profile_id,
      'controlled_stub_certification_id', v_stub_cert_id,
      'recipient_set_hash', v_ore.recipient_set_hash
    ));
END $function$;
CREATE OR REPLACE FUNCTION public.certify_comm_hub_template_version(p_template_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ver RECORD; v_tpl RECORD; v_map RECORD; v_scenario RECORD;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_render jsonb; v_purpose text; v_result text;
  v_mapping_applicable boolean; v_has_map boolean := false;
  v_sender_id uuid; v_contract_count int := 0; v_schema_count int := 0;
BEGIN
  IF p_template_version_id IS NULL THEN
    RETURN jsonb_build_object('result','BLOCKED_TEMPLATE_CONTENT','is_certified',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','template_version_missing')));
  END IF;
  SELECT * INTO v_ver FROM public.core_template_version WHERE id = p_template_version_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('result','BLOCKED_TEMPLATE_CONTENT','is_certified',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','template_version_not_found','template_version_id',p_template_version_id)));
  END IF;
  SELECT * INTO v_tpl FROM public.core_template WHERE id = v_ver.template_id;
  v_purpose := public.comm_hub_classify_template_purpose(v_ver.template_id);
  v_mapping_applicable := (v_purpose = 'EVENT_COMMUNICATION');

  IF lower(COALESCE(v_ver.status,'')) NOT IN ('active','published') THEN
    v_blockers := v_blockers || jsonb_build_object('code','status_not_publishable','status',v_ver.status);
  END IF;

  SELECT * INTO v_map FROM public.communication_hub_event_template_map
    WHERE template_id = v_tpl.id ORDER BY updated_at DESC NULLS LAST LIMIT 1;
  v_has_map := FOUND;

  IF v_mapping_applicable AND NOT v_has_map THEN
    v_blockers := v_blockers || jsonb_build_object('code','event_mapping_required',
      'template_code', v_tpl.code);
  END IF;

  IF v_has_map THEN
    v_sender_id := v_map.sender_profile_id;
    IF v_sender_id IS NULL THEN
      SELECT id INTO v_sender_id FROM public.communication_hub_sender_profile
       WHERE is_enabled AND is_default LIMIT 1;
    END IF;
    IF v_sender_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object('code','sender_not_resolvable');
    END IF;

    SELECT count(*) INTO v_schema_count
      FROM public.communication_hub_event_payload_schema
     WHERE module_code = v_map.module_code AND event_code = v_map.event_code;
    IF v_schema_count = 0 THEN v_warnings := v_warnings || jsonb_build_object('code','no_payload_schema'); END IF;
  END IF;

  SELECT count(*) INTO v_contract_count
    FROM public.communication_hub_template_variable_contract
   WHERE template_version_id = v_ver.id OR template_id = v_tpl.id OR template_code = v_tpl.code;
  IF v_contract_count = 0 THEN
    v_warnings := v_warnings || jsonb_build_object('code','no_variable_contract_bound','template_code',v_tpl.code);
  END IF;

  v_render := public.render_comm_hub_template_version(v_ver.id, '{}'::jsonb, 'EMAIL','PREVIEW_TEST');
  IF jsonb_array_length(v_render->'blockers') > 0 THEN
    v_blockers := v_blockers || (v_render->'blockers');
  END IF;

  IF v_mapping_applicable AND v_has_map THEN
    SELECT * INTO v_scenario FROM public.communication_hub_event_test_scenario
      WHERE module_code=v_map.module_code AND event_code=v_map.event_code
        AND channel=v_map.channel AND is_active=true
      ORDER BY scenario_key='default' DESC, updated_at DESC LIMIT 1;
    IF FOUND THEN
      v_render := public.render_comm_hub_template_version(v_ver.id,
        public.comm_hub_scrub_protected_keys(COALESCE(v_scenario.tokens,'{}'::jsonb)),
        'EMAIL','PREVIEW_TEST');
      IF (v_render->>'unresolved_count')::int > 0 THEN
        v_warnings := v_warnings || jsonb_build_object('code','unresolved_tokens_under_scenario',
          'unresolved', v_render->'unresolved');
      END IF;
    ELSE
      v_warnings := v_warnings || jsonb_build_object('code','no_test_scenario');
    END IF;
  END IF;

  v_result := CASE
    WHEN jsonb_array_length(v_blockers) = 0 AND v_purpose <> 'UNCLASSIFIED_REVIEW_REQUIRED' THEN 'CERTIFIED'
    WHEN v_purpose = 'UNCLASSIFIED_REVIEW_REQUIRED' THEN 'TEMPLATE_PURPOSE_UNCLASSIFIED'
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) x WHERE x->>'code'='event_mapping_required')
                                                    THEN 'BLOCKED_EVENT_MAPPING'
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) x WHERE x->>'code'='sender_not_resolvable')
                                                    THEN 'BLOCKED_SENDER'
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) x
                 WHERE x->>'code' IN ('body_missing','document_body_missing','subject_empty'))
                                                    THEN 'BLOCKED_TEMPLATE_CONTENT'
    ELSE 'BLOCKED_OTHER'
  END;

  RETURN jsonb_build_object(
    'result', v_result,
    'is_certified', (v_result = 'CERTIFIED'),
    'template_purpose', v_purpose,
    'mapping_applicable', v_mapping_applicable,
    'template_version_id', v_ver.id,
    'template_id', v_tpl.id,
    'template_code', v_tpl.code,
    'template_type', v_tpl.template_type,
    'status', v_ver.status,
    'blockers', v_blockers,
    'blocker_count', jsonb_array_length(v_blockers),
    'warnings', v_warnings,
    'warning_count', jsonb_array_length(v_warnings),
    'canonical_renderer_version','phase3_v1'
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.ch_esp_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.change_ip_status(p_unique_uuid uuid, p_new_status character varying, p_current_status character varying, p_user_id uuid DEFAULT NULL::uuid, p_user_code character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_allowed_transitions VARCHAR[];
  v_is_valid_transition BOOLEAN := false;
BEGIN
  -- Lock the record to prevent concurrent modifications
  SELECT * INTO v_record
  FROM public.ip_master
  WHERE unique_uuid = p_unique_uuid
  FOR UPDATE;
  
  IF v_record IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'RECORD_NOT_FOUND',
      'message', 'Insured person record not found'
    );
  END IF;
  
  -- Check if current status matches what client thinks it is (race condition prevention)
  IF v_record.status IS DISTINCT FROM p_current_status THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'STATUS_CHANGED',
      'message', 'The record status has been changed by another user. Please refresh and try again.',
      'current_status', v_record.status
    );
  END IF;
  
  -- Define allowed transitions based on current status
  CASE v_record.status
    WHEN 'V' THEN
      -- Verified can only go to Active
      v_allowed_transitions := ARRAY['A'];
    WHEN 'A' THEN
      -- Active can go to Suspended, Deleted, or Terminated
      v_allowed_transitions := ARRAY['S', 'D', 'T'];
    WHEN 'S' THEN
      -- Suspended can go to Active, Terminated, or Deleted
      v_allowed_transitions := ARRAY['A', 'T', 'D'];
    ELSE
      -- P, Z, T, D - no changes allowed
      v_allowed_transitions := ARRAY[]::VARCHAR[];
  END CASE;
  
  -- Check if the requested transition is allowed
  IF p_new_status = ANY(v_allowed_transitions) THEN
    v_is_valid_transition := true;
  END IF;
  
  IF NOT v_is_valid_transition THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'INVALID_TRANSITION',
      'message', format('Status change from %s to %s is not allowed', v_record.status, p_new_status),
      'current_status', v_record.status,
      'allowed_transitions', v_allowed_transitions
    );
  END IF;
  
  -- Perform the status update
  IF p_new_status = 'T' THEN
    -- Terminated status requires additional fields
    UPDATE public.ip_master
    SET 
      status = p_new_status,
      termination_date = CURRENT_DATE,
      termination_code = '1',
      updated_at = NOW(),
      updated_by = p_user_id
    WHERE unique_uuid = p_unique_uuid;
  ELSE
    -- Other status changes
    UPDATE public.ip_master
    SET 
      status = p_new_status,
      updated_at = NOW(),
      updated_by = p_user_id
    WHERE unique_uuid = p_unique_uuid;
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', format('Status changed from %s to %s successfully', v_record.status, p_new_status),
    'old_status', v_record.status,
    'new_status', p_new_status,
    'ssn', v_record.ssn,
    'unique_uuid', p_unique_uuid,
    'termination_date', CASE WHEN p_new_status = 'T' THEN CURRENT_DATE ELSE NULL END,
    'termination_code', CASE WHEN p_new_status = 'T' THEN '1' ELSE NULL END
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.change_sep_status(p_ssn character varying, p_self_ref_no character varying, p_new_status character, p_userid character varying DEFAULT NULL::character varying)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_status text;
  v_activity record;
BEGIN
  SELECT status INTO v_current_status
  FROM ip_self_employ
  WHERE ssn = p_ssn AND self_ref_no = p_self_ref_no
  ORDER BY activity_seq_no
  LIMIT 1;

  IF v_current_status IS NULL THEN
    RAISE EXCEPTION 'No self-employment record found for SSN % with SREF %', p_ssn, p_self_ref_no;
  END IF;

  IF p_new_status = 'A' AND v_current_status NOT IN ('P', 'V', 'S') THEN
    RAISE EXCEPTION 'Cannot activate from status %', v_current_status;
  END IF;
  IF p_new_status = 'S' AND v_current_status NOT IN ('A', 'V') THEN
    RAISE EXCEPTION 'Cannot suspend from status %', v_current_status;
  END IF;
  IF p_new_status = 'C' AND v_current_status NOT IN ('A', 'S', 'P', 'V') THEN
    RAISE EXCEPTION 'Cannot cease from status %', v_current_status;
  END IF;
  IF p_new_status = 'V' AND v_current_status NOT IN ('P') THEN
    RAISE EXCEPTION 'Cannot verify from status %', v_current_status;
  END IF;

  FOR v_activity IN
    SELECT * FROM ip_self_employ
    WHERE ssn = p_ssn AND self_ref_no = p_self_ref_no
  LOOP
    INSERT INTO au_ip_self_employ (
      ssn, self_ref_no, activity_seq_no, activity_type, date_commenced, date_ceased,
      occupation_code, industrial_code, office_code, village_code, phone, fax,
      inspector_code, inspector_name, sector_code, arrears, legal_action, persons_employed,
      self_guide, self_edu, date_educated, self_maddr1, self_maddr2, self_paddr1, self_paddr2,
      status, date_of_entry, date_of_issue, date_modified, date_verified, date_of_application,
      entered_by, verified_by, userid, modifier, modified_date, action
    ) VALUES (
      v_activity.ssn, v_activity.self_ref_no, v_activity.activity_seq_no,
      v_activity.activity_type, v_activity.date_commenced, v_activity.date_ceased,
      v_activity.occupation_code, v_activity.industrial_code, v_activity.office_code,
      v_activity.village_code, v_activity.phone, v_activity.fax,
      v_activity.inspector_code, v_activity.inspector_name, v_activity.sector_code,
      v_activity.arrears, v_activity.legal_action, v_activity.persons_employed,
      v_activity.self_guide, v_activity.self_edu, v_activity.date_educated,
      v_activity.self_maddr1, v_activity.self_maddr2, v_activity.self_paddr1, v_activity.self_paddr2,
      v_activity.status, v_activity.date_of_entry, v_activity.date_of_issue,
      v_activity.date_modified, v_activity.date_verified, v_activity.date_of_application,
      v_activity.entered_by, v_activity.verified_by, v_activity.userid,
      COALESCE(p_userid, current_user), now(), 'Before Update'
    );

    UPDATE ip_self_employ
    SET status = p_new_status,
        userid = COALESCE(p_userid, userid),
        date_modified = now()
    WHERE ssn = p_ssn
      AND self_ref_no = p_self_ref_no
      AND activity_seq_no = v_activity.activity_seq_no;

    IF p_new_status = 'C' THEN
      UPDATE ip_self_employ
      SET date_ceased = now()
      WHERE ssn = p_ssn
        AND self_ref_no = p_self_ref_no
        AND activity_seq_no = v_activity.activity_seq_no
        AND date_ceased IS NULL;

      UPDATE ip_self_commence
      SET date_ceased = now()
      WHERE ssn = p_ssn
        AND self_ref_no = p_self_ref_no
        AND activity_seq_no = v_activity.activity_seq_no
        AND date_ceased IS NULL;
    END IF;

    INSERT INTO au_ip_self_employ (
      ssn, self_ref_no, activity_seq_no, activity_type, date_commenced, date_ceased,
      occupation_code, industrial_code, office_code, village_code, phone, fax,
      inspector_code, inspector_name, sector_code, arrears, legal_action, persons_employed,
      self_guide, self_edu, date_educated, self_maddr1, self_maddr2, self_paddr1, self_paddr2,
      status, date_of_entry, date_of_issue, date_modified, date_verified, date_of_application,
      entered_by, verified_by, userid, modifier, modified_date, action
    )
    SELECT
      e.ssn, e.self_ref_no, e.activity_seq_no, e.activity_type, e.date_commenced, e.date_ceased,
      e.occupation_code, e.industrial_code, e.office_code, e.village_code, e.phone, e.fax,
      e.inspector_code, e.inspector_name, e.sector_code, e.arrears, e.legal_action, e.persons_employed,
      e.self_guide, e.self_edu, e.date_educated, e.self_maddr1, e.self_maddr2, e.self_paddr1, e.self_paddr2,
      e.status, e.date_of_entry, e.date_of_issue, e.date_modified, e.date_verified, e.date_of_application,
      e.entered_by, e.verified_by, e.userid,
      COALESCE(p_userid, current_user), now(), 'After Update'
    FROM ip_self_employ e
    WHERE e.ssn = p_ssn AND e.self_ref_no = p_self_ref_no AND e.activity_seq_no = v_activity.activity_seq_no;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_all_comm_hub_template_renderability()
 RETURNS TABLE(template_id uuid, template_version_id uuid, template_code text, version_no integer, status text, purpose text, module_code text, event_code text, channel text, detected_variable_count integer, contract_row_count integer, fixture_present boolean, recipient_required boolean, sender_required boolean, renderable boolean, raw_token_count integer, unresolved_required_count integer, blockers jsonb, recommended_action text, dependency_hash text, checked_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rec record;
  v_manifest jsonb;
  v_purpose text;
  v_map record;
  v_contract_ct int;
  v_fixture record;
  v_blockers jsonb;
  v_render_subj jsonb;
  v_render_html jsonb;
  v_raw int;
BEGIN
  FOR rec IN
    SELECT v.id AS tv_id, v.template_id, v.version_no, v.status,
           v.subject, v.body_html, v.body_text,
           t.code AS template_code, t.module_code AS t_module
      FROM core_template_version v
      JOIN core_template t ON t.id=v.template_id
     WHERE upper(v.status::text) IN ('ACTIVE','PUBLISHED')
  LOOP
    v_blockers := '[]'::jsonb;
    v_purpose := comm_hub_classify_template_purpose(rec.template_id);
    SELECT m.module_code, m.event_code, m.channel, m.id AS map_id
      INTO v_map
      FROM communication_hub_event_template_map m
     WHERE m.template_id=rec.template_id AND m.active=true
     ORDER BY updated_at DESC LIMIT 1;
    SELECT count(*) INTO v_contract_ct
      FROM communication_hub_template_variable_contract
     WHERE template_version_id=rec.tv_id;
    IF v_map.module_code IS NOT NULL THEN
      SELECT * INTO v_fixture FROM communication_hub_event_test_scenario
       WHERE module_code=v_map.module_code AND event_code=v_map.event_code AND is_active=true LIMIT 1;
    ELSE
      v_fixture := NULL;
    END IF;

    -- purpose-specific rules
    IF v_purpose='EVENT_COMMUNICATION' THEN
      IF v_map.module_code IS NULL THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','event_mapping_missing'));
      END IF;
      IF v_contract_ct=0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','variable_contract_missing'));
      END IF;
      IF v_fixture IS NULL THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','governed_fixture_missing'));
      END IF;
    ELSIF v_purpose='MANUAL_CORRESPONDENCE' THEN
      IF v_contract_ct=0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','manual_correspondence_context_missing'));
      END IF;
    ELSIF v_purpose='DOCUMENT_GENERATION' THEN
      IF v_contract_ct=0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','document_fixture_missing'));
      END IF;
    ELSIF v_purpose='FORM_OUTPUT' THEN
      IF v_contract_ct=0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','form_output_context_missing'));
      END IF;
    END IF;

    -- synthetic render with empty context to count raw tokens present in template body
    v_raw := 0;
    BEGIN
      IF coalesce(length(rec.subject),0)>0 THEN
        v_render_subj := comm_hub_render_template(rec.subject,'{}'::jsonb);
        v_raw := v_raw + jsonb_array_length(coalesce(v_render_subj->'raw_tokens','[]'::jsonb));
      END IF;
      IF coalesce(length(rec.body_html),0)>0 THEN
        v_render_html := comm_hub_render_template(rec.body_html,'{}'::jsonb);
        v_raw := v_raw + jsonb_array_length(coalesce(v_render_html->'raw_tokens','[]'::jsonb));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','render_error','details',SQLERRM));
    END;

    template_id := rec.template_id;
    template_version_id := rec.tv_id;
    template_code := rec.template_code;
    version_no := rec.version_no;
    status := rec.status::text;
    purpose := coalesce(v_purpose,'UNKNOWN');
    module_code := v_map.module_code;
    event_code := v_map.event_code;
    channel := v_map.channel;
    detected_variable_count := v_raw;
    contract_row_count := v_contract_ct;
    fixture_present := v_fixture IS NOT NULL;
    recipient_required := (v_contract_ct>0);
    sender_required := (v_map.map_id IS NOT NULL);
    raw_token_count := v_raw;
    unresolved_required_count := CASE WHEN v_contract_ct=0 THEN v_raw ELSE 0 END;
    renderable := jsonb_array_length(v_blockers)=0;
    blockers := v_blockers;
    recommended_action := CASE
      WHEN jsonb_array_length(v_blockers)=0 THEN 'READY'
      WHEN v_purpose='EVENT_COMMUNICATION' AND v_map.module_code IS NULL THEN 'CREATE_EVENT_MAPPING'
      WHEN v_contract_ct=0 THEN 'DEFINE_VARIABLE_CONTRACT'
      WHEN v_fixture IS NULL THEN 'DEFINE_GOVERNED_FIXTURE'
      ELSE 'REVIEW_BLOCKERS' END;
    dependency_hash := NULL;
    checked_at := now();
    RETURN NEXT;
  END LOOP;
END; $function$;
CREATE OR REPLACE FUNCTION public.check_and_log_unauthorized_access(_ip_address text, _route text, _module_name text DEFAULT NULL::text, _user_id uuid DEFAULT NULL::uuid, _user_email text DEFAULT NULL::text, _reason text DEFAULT 'unauthorized_access'::text, _severity text DEFAULT 'medium'::text, _user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _max_attempts INT;
  _window_minutes INT;
  _block_duration INT;
  _recent_count INT;
  _is_blocked BOOLEAN;
  _result JSONB;
BEGIN
  -- Log the unauthorized access attempt
  INSERT INTO unauthorized_access_logs (user_id, user_email, ip_address, route_attempted, module_name, reason, severity, user_agent)
  VALUES (_user_id, _user_email, _ip_address, _route, _module_name, _reason, _severity, _user_agent);

  -- Check if IP is already blocked
  SELECT EXISTS(
    SELECT 1 FROM security_ip_blocks 
    WHERE ip_address = _ip_address AND is_active = true AND expires_at > now()
  ) INTO _is_blocked;

  IF _is_blocked THEN
    RETURN jsonb_build_object('blocked', true, 'reason', 'IP is currently blocked');
  END IF;

  -- Get rate limit config
  SELECT COALESCE((SELECT config_value::INT FROM security_policy_config WHERE config_key = 'ip_rate_limit_max_attempts'), 10) INTO _max_attempts;
  SELECT COALESCE((SELECT config_value::INT FROM security_policy_config WHERE config_key = 'ip_rate_limit_window_minutes'), 15) INTO _window_minutes;
  SELECT COALESCE((SELECT config_value::INT FROM security_policy_config WHERE config_key = 'ip_block_duration_minutes'), 60) INTO _block_duration;

  -- Count recent attempts from this IP
  SELECT COUNT(*) INTO _recent_count
  FROM unauthorized_access_logs
  WHERE ip_address = _ip_address
    AND timestamp > now() - (_window_minutes || ' minutes')::INTERVAL;

  -- Block IP if threshold exceeded
  IF _recent_count >= _max_attempts THEN
    INSERT INTO security_ip_blocks (ip_address, block_reason, block_duration_minutes, expires_at)
    VALUES (_ip_address, 'Rate limit exceeded: ' || _recent_count || ' attempts in ' || _window_minutes || ' minutes', 
            _block_duration, now() + (_block_duration || ' minutes')::INTERVAL);
    
    RETURN jsonb_build_object('blocked', true, 'reason', 'IP blocked due to rate limit exceeded', 'attempts', _recent_count);
  END IF;

  -- Check global attack threshold
  DECLARE
    _global_threshold INT;
    _global_window INT;
    _global_count INT;
    _lockdown_enabled BOOLEAN;
  BEGIN
    SELECT COALESCE((SELECT config_value::INT FROM security_policy_config WHERE config_key = 'global_attack_threshold'), 50) INTO _global_threshold;
    SELECT COALESCE((SELECT config_value::INT FROM security_policy_config WHERE config_key = 'global_attack_window_minutes'), 10) INTO _global_window;
    SELECT COALESCE((SELECT config_value::BOOLEAN FROM security_policy_config WHERE config_key = 'lockdown_enabled'), true) INTO _lockdown_enabled;

    IF _lockdown_enabled THEN
      SELECT COUNT(*) INTO _global_count
      FROM unauthorized_access_logs
      WHERE timestamp > now() - (_global_window || ' minutes')::INTERVAL;

      IF _global_count >= _global_threshold THEN
        -- Trigger application lockdown
        UPDATE app_lockdown_state SET 
          is_locked = true, 
          locked_at = now(), 
          locked_reason = 'Automatic lockdown: ' || _global_count || ' unauthorized attempts detected globally',
          locked_by = 'SYSTEM',
          updated_at = now()
        WHERE id = (SELECT id FROM app_lockdown_state ORDER BY created_at DESC LIMIT 1);
        
        RETURN jsonb_build_object('blocked', true, 'lockdown', true, 'reason', 'Application lockdown triggered');
      END IF;
    END IF;
  END;

  RETURN jsonb_build_object('blocked', false, 'attempts', _recent_count, 'max', _max_attempts);
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_certification_freshness(p_certification_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cert record; v_dep jsonb; v_hash text; v_status text;
BEGIN
  SELECT id, entity_type::text AS entity_type, entity_id, entity_version,
         dependency_manifest, dependency_hash, superseded_by, is_stale,
         certification_layer, provenance_state, hash_algorithm,
         canonicalization_version
    INTO v_cert FROM public.comm_hub_certification WHERE id = p_certification_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='CERTIFICATION_NOT_FOUND';
  END IF;

  IF v_cert.provenance_state IS DISTINCT FROM 'AUTHORITATIVE' THEN
    RETURN jsonb_build_object('certification_id', v_cert.id,
      'freshness_status','NON_AUTHORITATIVE',
      'certified_hash', v_cert.dependency_hash,
      'changed_dependency_categories','[]'::jsonb,
      'stale_reason_codes', jsonb_build_array('NON_AUTHORITATIVE'),
      'evaluated_at', now());
  END IF;

  IF v_cert.superseded_by IS NOT NULL THEN
    RETURN jsonb_build_object('certification_id', v_cert.id,
      'freshness_status','SUPERSEDED',
      'certified_hash', v_cert.dependency_hash,
      'changed_dependency_categories','[]'::jsonb,
      'stale_reason_codes', jsonb_build_array('SUPERSEDED'),
      'evaluated_at', now());
  END IF;

  IF v_cert.is_stale THEN
    RETURN jsonb_build_object('certification_id', v_cert.id,
      'freshness_status','STALE','certified_hash',v_cert.dependency_hash,
      'stale_reason_codes', jsonb_build_array('MARKED_STALE'),
      'changed_dependency_categories','[]'::jsonb,
      'evaluated_at', now());
  END IF;

  IF v_cert.entity_type = 'TEMPLATE_VERSION' THEN
    v_dep := public.build_comm_hub_template_dependency_manifest(v_cert.entity_id);
    IF (v_dep->>'build_status') <> 'OK' THEN
      RETURN jsonb_build_object('certification_id', v_cert.id,
        'freshness_status','STALE','certified_hash',v_cert.dependency_hash,
        'stale_reason_codes', jsonb_build_array(coalesce(v_dep->>'reason','MANIFEST_BUILD_FAILED')),
        'changed_dependency_categories','[]'::jsonb,
        'evaluated_at', now());
    END IF;
    v_hash := public.comm_hub_evidence_hash(
      'comm-hub/template-dependency-manifest/v1', v_dep);
  ELSE
    -- non-template layers keep prior behaviour via legacy builder if present
    v_hash := v_cert.dependency_hash;
  END IF;

  IF coalesce(v_cert.hash_algorithm,'SHA-256') <> 'SHA-256' THEN
    v_status := 'STALE';
  ELSIF v_hash = v_cert.dependency_hash THEN
    v_status := 'CURRENT';
  ELSE
    v_status := 'STALE';
  END IF;

  RETURN jsonb_build_object(
    'certification_id', v_cert.id,
    'entity_type', v_cert.entity_type,
    'entity_id', v_cert.entity_id,
    'certification_layer', v_cert.certification_layer,
    'certified_hash', v_cert.dependency_hash,
    'current_hash', v_hash,
    'hash_algorithm', 'SHA-256',
    'canonicalization_version', public.comm_hub_canonicalization_version(),
    'dependency_manifest_version','comm-hub-template-dependency-manifest/v1',
    'freshness_status', v_status,
    'changed_dependency_categories','[]'::jsonb,
    'stale_reason_codes','[]'::jsonb,
    'evaluated_at', now(),
    'recommended_action', CASE WHEN v_status='CURRENT' THEN 'NONE' ELSE 'RECERTIFY' END
  );
END $function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_dispatch_secret_compatibility(p_canonical_present boolean, p_legacy_present boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'canonical_name','COMMUNICATION_HUB_DISPATCH_SECRET',
    'legacy_names', jsonb_build_array('COMM_HUB_DISPATCH_SECRET'),
    'canonical_present', p_canonical_present,
    'legacy_present', p_legacy_present,
    'result', CASE
      WHEN p_canonical_present AND NOT p_legacy_present THEN 'PASS'
      WHEN p_canonical_present AND p_legacy_present     THEN 'WARNING_BOTH_PRESENT'
      WHEN NOT p_canonical_present AND p_legacy_present THEN 'WARNING_LEGACY_ONLY'
      ELSE 'BLOCKER_ABSENT'
    END,
    'schema_version','dispatch-secret-compat/v1');
$function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_dry_run_certification_binding(p_dry_run_certification_id uuid, p_dry_run_execution_id uuid, p_preview_approval_id uuid, p_preview_snapshot_id uuid, p_expected_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c record; v_e record; v_corr uuid; v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF p_dry_run_certification_id IS NULL THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','DRY_RUN_CERTIFICATION_MISSING','message','Certification id required')));
  END IF;
  SELECT id,status,preview_snapshot_id,preview_approval_id,superseded_by,invalidated_at
    INTO v_c FROM public.communication_dry_run_certification WHERE id = p_dry_run_certification_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','DRY_RUN_CERTIFICATION_MISSING','message','Certification not found')));
  END IF;
  IF v_c.status <> 'ACTIVE' THEN
    v_blockers := v_blockers || jsonb_build_object('code','CERTIFICATION_STATUS_INVALID','message','Not ACTIVE','detail',jsonb_build_object('status',v_c.status));
  END IF;
  IF v_c.superseded_by IS NOT NULL OR v_c.invalidated_at IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','CERTIFICATION_SUPERSEDED_OR_INVALIDATED','message','Superseded or invalidated');
  END IF;

  SELECT id,preview_snapshot_id,preview_approval_id,certification_id
    INTO v_e FROM public.communication_dry_run_execution WHERE id = p_dry_run_execution_id;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_object('code','DRY_RUN_EXECUTION_MISSING','message','Execution not found');
  ELSE
    IF v_e.certification_id IS DISTINCT FROM v_c.id THEN
      v_blockers := v_blockers || jsonb_build_object('code','CERTIFICATION_EXECUTION_MISMATCH','message','Execution/cert mismatch');
    END IF;
    IF v_e.preview_approval_id IS DISTINCT FROM p_preview_approval_id THEN
      v_blockers := v_blockers || jsonb_build_object('code','EXECUTION_APPROVAL_MISMATCH','message','Execution/approval mismatch');
    END IF;
    IF v_e.preview_snapshot_id IS DISTINCT FROM p_preview_snapshot_id THEN
      v_blockers := v_blockers || jsonb_build_object('code','EXECUTION_SNAPSHOT_MISMATCH','message','Execution/snapshot mismatch');
    END IF;
  END IF;
  IF v_c.preview_snapshot_id IS DISTINCT FROM p_preview_snapshot_id THEN
    v_blockers := v_blockers || jsonb_build_object('code','CERTIFICATION_SNAPSHOT_MISMATCH','message','Cert/snapshot mismatch');
  END IF;
  IF v_c.preview_approval_id IS DISTINCT FROM p_preview_approval_id THEN
    v_blockers := v_blockers || jsonb_build_object('code','CERTIFICATION_APPROVAL_MISMATCH','message','Cert/approval mismatch');
  END IF;
  IF p_expected_correlation_id IS NOT NULL THEN
    SELECT correlation_id INTO v_corr FROM public.communication_preview_snapshot WHERE id = p_preview_snapshot_id;
    IF v_corr IS DISTINCT FROM p_expected_correlation_id THEN
      v_blockers := v_blockers || jsonb_build_object('code','CERTIFICATION_CORRELATION_MISMATCH','message','Correlation mismatch');
    END IF;
  END IF;

  RETURN jsonb_build_object('allowed', jsonb_array_length(v_blockers)=0, 'blockers', v_blockers,
    'evidence', jsonb_build_object('certification_id',v_c.id,'execution_id',p_dry_run_execution_id,'evaluator_version','4b3.slice2.dryrun_cert'));
END; $function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_event_fixture_compatibility(p_module_code text, p_event_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text := upper(coalesce(p_module_code,''));
  v_event  text := upper(coalesce(p_event_code,''));
  v_schema jsonb; v_schema_status text;
  v_contract_enforced boolean := false;
  v_fixtures record; v_var record;
  v_missing_paths jsonb; v_required_missing jsonb;
  v_scenario_reports jsonb := '[]'::jsonb; v_scenario_report jsonb;
  v_json_ptr jsonb; v_seg text; v_path_segments text[];
  v_scenario_count int := 0; v_compatible_count int := 0; v_ok boolean;
BEGIN
  SELECT json_schema, status INTO v_schema, v_schema_status
  FROM communication_hub_event_payload_schema
  WHERE module_code=v_module AND event_code=v_event
  ORDER BY schema_version DESC LIMIT 1;

  SELECT bool_or(contract_status = 'ENFORCED') INTO v_contract_enforced
  FROM communication_hub_template_variable_contract
  WHERE module_code=v_module AND event_code=v_event;

  FOR v_fixtures IN
    SELECT id, scenario_key, tokens
      FROM communication_hub_event_test_scenario
     WHERE module_code=v_module AND event_code=v_event AND is_active=true
  LOOP
    v_scenario_count := v_scenario_count + 1;
    v_missing_paths := '[]'::jsonb;
    v_required_missing := '[]'::jsonb;

    FOR v_var IN
      SELECT variable_name, canonical_path, source_type, is_required
        FROM communication_hub_template_variable_contract
       WHERE module_code=v_module AND event_code=v_event
    LOOP
      v_path_segments := string_to_array(v_var.canonical_path,'.');
      v_json_ptr := CASE v_var.source_type
        WHEN 'event_payload'     THEN COALESCE(v_fixtures.tokens,'{}'::jsonb)
        WHEN 'recipient_context' THEN COALESCE(v_fixtures.tokens -> 'recipient_context', jsonb_build_object('display_name','Test Recipient','email','test@example.com'))
        WHEN 'request_context'   THEN COALESCE(v_fixtures.tokens -> 'request_context', jsonb_build_object('request_no','REQ-STUB','reference','REF-STUB'))
        WHEN 'system_context'    THEN COALESCE(v_fixtures.tokens -> 'system_context', jsonb_build_object('generated_at', now()))
        ELSE NULL END;
      v_ok := v_json_ptr IS NOT NULL;
      IF v_ok THEN
        FOREACH v_seg IN ARRAY v_path_segments LOOP
          IF v_json_ptr IS NULL OR jsonb_typeof(v_json_ptr) <> 'object' OR NOT (v_json_ptr ? v_seg) THEN
            v_ok := false; EXIT;
          END IF;
          v_json_ptr := v_json_ptr -> v_seg;
        END LOOP;
        IF v_ok AND (v_json_ptr IS NULL OR jsonb_typeof(v_json_ptr) = 'null') THEN v_ok := false; END IF;
      END IF;
      IF NOT v_ok THEN
        v_missing_paths := v_missing_paths || jsonb_build_object(
          'variable', v_var.variable_name, 'source_type', v_var.source_type,
          'canonical_path', v_var.canonical_path, 'is_required', v_var.is_required);
        IF v_var.is_required THEN
          v_required_missing := v_required_missing || to_jsonb(v_var.variable_name);
        END IF;
      END IF;
    END LOOP;

    v_scenario_report := jsonb_build_object(
      'scenario_id', v_fixtures.id, 'scenario_key', v_fixtures.scenario_key,
      'missing_variable_paths', v_missing_paths, 'required_missing', v_required_missing,
      'compatible', (jsonb_array_length(v_required_missing) = 0));
    v_scenario_reports := v_scenario_reports || v_scenario_report;
    IF (jsonb_array_length(v_required_missing) = 0) THEN
      v_compatible_count := v_compatible_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'module_code', v_module, 'event_code', v_event,
    'schema_present', v_schema IS NOT NULL,
    'schema_status', COALESCE(v_schema_status,'MISSING'),
    'contract_enforced', COALESCE(v_contract_enforced,false),
    'scenario_count', v_scenario_count,
    'compatible_scenario_count', v_compatible_count,
    'is_compatible', (v_scenario_count > 0 AND v_scenario_count = v_compatible_count),
    'scenarios', v_scenario_reports,
    'evaluated_at', now());
END;$function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_event_fixture_compatibility_v2(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text, p_template_version_id uuid DEFAULT NULL::uuid, p_scenario_id uuid DEFAULT NULL::uuid, p_platform_test_context_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text := upper(coalesce(p_module_code,''));
  v_event text := upper(coalesce(p_event_code,''));
  v_channel text := lower(coalesce(p_channel,'email'));
  v_map communication_hub_event_template_map%ROWTYPE;
  v_tv_id uuid := p_template_version_id;
  v_tv core_template_version%ROWTYPE;
  v_scen communication_hub_event_test_scenario%ROWTYPE;
  v_ctx comm_hub_platform_test_context%ROWTYPE;
  v_schema communication_hub_event_payload_schema%ROWTYPE;
  v_reserved text[] := ARRAY['recipient_name','recipient_email','request_no','request_id',
    'generated_at','module_code','event_code','sender_email','sender_display_name',
    'reply_to','template_id','template_version_id'];
  v_reserved_hits jsonb := '[]'::jsonb; v_r text;
  v_schema_result jsonb; v_variables jsonb := '[]'::jsonb; v_var record;
  v_source_json jsonb; v_segments text[]; v_seg text; v_ptr jsonb; v_resolved boolean;
  v_missing_required int := 0;
  v_blockers jsonb := '[]'::jsonb; v_warnings jsonb := '[]'::jsonb;
  v_alias jsonb := '{}'::jsonb;
  v_rendered_subject jsonb; v_rendered_body jsonb;
  v_raw_tokens int := 0; v_manifest jsonb; v_compat_hash text;
BEGIN
  IF NOT (pg_has_role('service_role','USAGE') OR has_role(auth.uid(),'Admin'::app_role)) THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_map FROM communication_hub_event_template_map
    WHERE module_code=v_module AND event_code=v_event AND channel=v_channel AND active=true LIMIT 1;
  IF v_map.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'schema_version','event-fixture-compatibility/v1','is_compatible',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','MAPPING_NOT_FOUND','channel',v_channel)));
  END IF;
  IF v_tv_id IS NULL THEN
    SELECT tv.id INTO v_tv_id FROM core_template_version tv
      WHERE tv.template_id = v_map.template_id ORDER BY tv.version_no DESC LIMIT 1;
  END IF;
  SELECT * INTO v_tv FROM core_template_version WHERE id=v_tv_id;
  IF v_tv.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'is_compatible',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','TEMPLATE_VERSION_NOT_FOUND','template_version_id',v_tv_id)));
  END IF;
  SELECT * INTO v_schema FROM communication_hub_event_payload_schema
    WHERE module_code=v_module AND event_code=v_event AND status='ENFORCED'
    ORDER BY schema_version DESC LIMIT 1;
  IF v_schema.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','ENFORCED_SCHEMA_MISSING');
  END IF;
  IF p_scenario_id IS NOT NULL THEN
    SELECT * INTO v_scen FROM communication_hub_event_test_scenario WHERE id=p_scenario_id;
  ELSE
    SELECT * INTO v_scen FROM communication_hub_event_test_scenario
      WHERE module_code=v_module AND event_code=v_event AND channel=v_channel AND is_active=true
      ORDER BY (scenario_key='default') DESC, updated_at DESC LIMIT 1;
  END IF;
  IF v_scen.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','GOVERNED_SCENARIO_MISSING');
  END IF;
  IF p_platform_test_context_id IS NOT NULL THEN
    SELECT * INTO v_ctx FROM comm_hub_platform_test_context WHERE id=p_platform_test_context_id AND status='ACTIVE';
  ELSE
    SELECT * INTO v_ctx FROM comm_hub_platform_test_context
      WHERE context_code='DEFAULT_PLATFORM_TEST_CONTEXT' AND status='ACTIVE'
      ORDER BY version DESC LIMIT 1;
  END IF;
  IF v_ctx.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','PLATFORM_TEST_CONTEXT_MISSING');
  END IF;

  IF v_scen.id IS NOT NULL AND v_schema.id IS NOT NULL THEN
    IF (SELECT COUNT(*) FROM jsonb_object_keys(v_scen.tokens) k
        JOIN jsonb_object_keys(v_schema.json_schema->'properties') p ON k=p)=0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','LEGACY_FLAT_TEMPLATE_TOKENS',
        'message','Scenario stores flat template aliases; canonical eventPayload required.');
    END IF;
  END IF;

  IF v_scen.id IS NOT NULL THEN
    FOREACH v_r IN ARRAY v_reserved LOOP
      IF v_scen.tokens ? v_r THEN
        v_reserved_hits := v_reserved_hits || jsonb_build_object('field',v_r,'path',v_r);
      END IF;
    END LOOP;
    IF jsonb_array_length(v_reserved_hits) > 0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','PLATFORM_OWNED_FIELD_SUPPLIED_BY_EVENT','fields',v_reserved_hits);
    END IF;
  END IF;

  IF v_schema.id IS NOT NULL AND v_scen.id IS NOT NULL THEN
    v_schema_result := public.validate_comm_hub_event_payload_pure(v_schema.json_schema, v_scen.tokens);
    IF NOT COALESCE((v_schema_result->>'valid')::boolean,false) THEN
      v_blockers := v_blockers || jsonb_build_object('code','SCHEMA_VALIDATION_FAILED','detail',v_schema_result);
    END IF;
  END IF;

  FOR v_var IN
    SELECT variable_name, canonical_path, source_type, is_required
      FROM communication_hub_template_variable_contract
     WHERE template_version_id = v_tv_id AND contract_status='ENFORCED'
  LOOP
    v_source_json := CASE v_var.source_type
      WHEN 'event_payload'     THEN COALESCE(v_scen.tokens,'{}'::jsonb)
      WHEN 'recipient_context' THEN v_ctx.recipient_context
      WHEN 'request_context'   THEN v_ctx.request_context
      WHEN 'system_context'    THEN v_ctx.system_context
      WHEN 'sender_context'    THEN v_ctx.sender_context
      ELSE NULL END;
    v_ptr := v_source_json;
    v_resolved := v_ptr IS NOT NULL;
    IF v_resolved AND coalesce(v_var.canonical_path,'')<>'' THEN
      v_segments := string_to_array(v_var.canonical_path,'.');
      FOREACH v_seg IN ARRAY v_segments LOOP
        IF v_ptr IS NULL OR jsonb_typeof(v_ptr)<>'object' OR NOT (v_ptr ? v_seg) THEN
          v_resolved := false; v_ptr := NULL; EXIT;
        END IF;
        v_ptr := v_ptr -> v_seg;
      END LOOP;
    END IF;
    v_variables := v_variables || jsonb_build_object(
      'variable_name',v_var.variable_name,'source_type',v_var.source_type,
      'canonical_path',v_var.canonical_path,'required',v_var.is_required,
      'resolution_status', CASE
        WHEN v_resolved AND v_var.source_type='event_payload'     THEN 'FIXTURE_RESOLVED'
        WHEN v_resolved AND v_var.source_type='recipient_context' THEN 'RECIPIENT_CONTEXT_RESOLVED'
        WHEN v_resolved AND v_var.source_type='request_context'   THEN 'REQUEST_CONTEXT_RESOLVED'
        WHEN v_resolved AND v_var.source_type='system_context'    THEN 'SYSTEM_CONTEXT_RESOLVED'
        WHEN v_resolved AND v_var.source_type='sender_context'    THEN 'SENDER_CONTEXT_RESOLVED'
        WHEN v_resolved AND v_var.source_type='derived'           THEN 'DERIVED'
        WHEN v_resolved AND v_var.source_type='template_default'  THEN 'DEFAULTED'
        WHEN v_resolved AND v_var.source_type='late_bound'        THEN 'LATE_BOUND'
        WHEN (NOT v_resolved) AND v_var.is_required THEN 'REQUIRED_MISSING'
        ELSE 'OPTIONAL_MISSING' END,
      'resolved_value_type', jsonb_typeof(v_ptr),
      'value_present', v_resolved);
    IF v_resolved THEN
      v_alias := v_alias || jsonb_build_object(v_var.variable_name,
        CASE jsonb_typeof(v_ptr) WHEN 'string' THEN to_jsonb(v_ptr#>>'{}') ELSE v_ptr END);
    ELSIF v_var.is_required THEN
      v_missing_required := v_missing_required + 1;
    END IF;
  END LOOP;
  IF v_missing_required > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','REQUIRED_VARIABLES_MISSING','count',v_missing_required);
  END IF;

  IF jsonb_array_length(v_blockers)=0 THEN
    v_rendered_subject := public.render_comm_hub_content(v_tv.subject, v_alias, 'text');
    v_rendered_body    := public.render_comm_hub_content(COALESCE(v_tv.body_html, v_tv.body_text, ''), v_alias, 'html');
    v_raw_tokens := COALESCE((v_rendered_subject->>'unresolved_count')::int,0)
                  + COALESCE((v_rendered_body->>'unresolved_count')::int,0);
    IF v_raw_tokens > 0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','RAW_TOKENS_REMAINING','count',v_raw_tokens);
    END IF;
  END IF;

  v_manifest := jsonb_build_object(
    'module_code',v_module,'event_code',v_event,'channel',v_channel,
    'mapping_id',v_map.id,'template_version_id',v_tv_id,'template_version_no',v_tv.version_no,
    'schema_id',v_schema.id,'schema_version',v_schema.schema_version,
    'scenario_id',v_scen.id,'scenario_version',v_scen.scenario_version,'scenario_hash',v_scen.scenario_hash,
    'platform_test_context_id',v_ctx.id,'platform_test_context_version',v_ctx.version,
    'platform_test_context_hash',v_ctx.context_hash,
    'validator_name','comm-hub-json-schema-subset','validator_version','v1',
    'resolver_version','resolve_comm_hub_template_variables/1',
    'renderer_version','render_comm_hub_content/1',
    'source_ownership_policy_version','source-ownership/v1',
    'event_payload_hash', encode(extensions.digest(COALESCE(v_scen.tokens,'{}'::jsonb)::text,'sha256'),'hex'),
    'subject_hash', encode(extensions.digest(COALESCE(v_rendered_subject->>'rendered',''),'sha256'),'hex'),
    'body_hash',    encode(extensions.digest(COALESCE(v_rendered_body->>'rendered',''),'sha256'),'hex'));
  v_compat_hash := encode(extensions.digest('comm-hub/event-fixture-compatibility/v1|'||v_manifest::text,'sha256'),'hex');
  RETURN jsonb_build_object(
    'ok',(jsonb_array_length(v_blockers)=0),'schema_version','event-fixture-compatibility/v1',
    'is_compatible',(jsonb_array_length(v_blockers)=0),
    'schema_valid', COALESCE((v_schema_result->>'valid')::boolean,false),
    'schema_errors', COALESCE(v_schema_result->'errors','[]'::jsonb),
    'variables', v_variables,
    'source_ownership_violations', v_reserved_hits,
    'renderable',(jsonb_array_length(v_blockers)=0),
    'raw_tokens_count', v_raw_tokens,
    'blockers',v_blockers,'warnings',v_warnings,
    'manifest',v_manifest,'compatibility_hash',v_compat_hash);
END; $function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_manual_observation_eligibility(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_pending record;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  BEGIN v_is_admin := public.is_comm_hub_operator_admin(v_uid);
  EXCEPTION WHEN undefined_function THEN
    SELECT public.has_role(v_uid,'Admin'::public.app_role) INTO v_is_admin; END;
  IF NOT v_is_admin THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';

  IF lower(coalesce(v_settings.operating_mode::text,'')) NOT IN ('manual_production','automated_production') THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','OPERATING_MODE_INELIGIBLE','current', v_settings.operating_mode));
  END IF;

  IF lower(coalesce(v_settings.operating_mode::text,'')) = 'emergency_stop' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','EMERGENCY_STOP_ACTIVE'));
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=p_channel;

  IF NOT FOUND OR v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','EVENT_NOT_CERTIFIED'));
  ELSE
    IF v_ec.evidence_fingerprint IS NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','FINGERPRINT_MISSING'));
    END IF;
    IF v_ec.drift_detected_at IS NOT NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','EVIDENCE_DRIFT'));
    END IF;
    IF v_ec.suspended_at IS NOT NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','EVENT_SUSPENDED'));
    END IF;
    IF coalesce(v_ec.manual_verified_recipient,'') = '' THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','APPROVED_RECIPIENT_MISSING'));
    END IF;
  END IF;

  BEGIN
    SELECT id, phase INTO v_pending
      FROM public.communication_manual_production_observation_intent
     WHERE module_code=p_module_code AND event_code=p_event_code AND channel=p_channel
       AND phase NOT IN ('CONFIRMED','NOT_RECEIVED','FAILED','VOIDED')
     ORDER BY created_at DESC LIMIT 1;
  EXCEPTION WHEN undefined_table THEN v_pending := NULL; END;
  IF v_pending.id IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','UNRESOLVED_OBSERVATION_INTENT',
      'intent_id', v_pending.id,
      'phase', v_pending.phase));
  END IF;

  RETURN jsonb_build_object(
    'eligible', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'runtime_mode_version', v_settings.runtime_mode_version,
    'automation_generation', v_settings.automation_generation,
    'operating_mode', v_settings.operating_mode,
    'event_status', v_ec.status,
    'evidence_fingerprint', v_ec.evidence_fingerprint
  );
END $function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_preview_approval_binding(p_preview_approval_id uuid, p_preview_snapshot_id uuid, p_expected_correlation_id uuid, p_expected_content_hash text, p_expected_recipient_hash text, p_expected_configuration_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_a public.communication_preview_approval%ROWTYPE;
  v_s public.communication_preview_snapshot%ROWTYPE;
  v_blockers jsonb := '[]'::jsonb;
  v_recomputed text;
  v_evidence jsonb;
  v_ok boolean;
BEGIN
  SELECT * INTO v_a FROM public.communication_preview_approval WHERE id = p_preview_approval_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false, 'allowed', false, 'evaluator_version','comm-hub-preview-approval-binding/v2',
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_APPROVAL_NOT_FOUND')),
      'evidence','{}'::jsonb);
  END IF;
  SELECT * INTO v_s FROM public.communication_preview_snapshot WHERE id = p_preview_snapshot_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false, 'allowed', false, 'evaluator_version','comm-hub-preview-approval-binding/v2',
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_SNAPSHOT_NOT_FOUND')),
      'evidence','{}'::jsonb);
  END IF;

  IF v_a.snapshot_id <> v_s.id THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_SNAPSHOT_MISMATCH');
  END IF;
  IF v_a.status <> 'ACTIVE' THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_NOT_ACTIVE','status',v_a.status);
  END IF;
  IF v_a.expires_at <= now() THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_EXPIRED');
  END IF;
  IF v_s.status <> 'PREPARED' THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_NOT_PREPARED','status',v_s.status);
  END IF;

  IF v_a.evidence_version IS DISTINCT FROM 'comm-hub-approval-evidence/v1'
     OR v_a.canonical_approval_evidence_hash IS NULL
     OR v_a.placeholder_evidence_hash_at_approval IS NULL
     OR v_a.snapshot_id_at_approval IS NULL
     OR v_a.correlation_id_at_approval IS NULL
     OR v_a.recipient_set_hash_at_approval IS NULL
     OR v_a.template_version_id_at_approval IS NULL
     OR v_a.configuration_hash_at_approval IS NULL
     OR v_a.scanner_version_at_approval IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_EVIDENCE_MISSING_OR_LEGACY','evidence_version', v_a.evidence_version);
  ELSE
    v_recomputed := public._comm_hub_compute_canonical_approval_evidence_v1(
      v_a.snapshot_id_at_approval, v_a.correlation_id_at_approval,
      v_a.content_hash_at_approval, v_a.recipient_set_hash_at_approval,
      v_a.template_version_id_at_approval, v_a.configuration_hash_at_approval,
      v_a.scanner_version_at_approval, v_a.placeholder_evidence_hash_at_approval,
      v_a.approved_by, v_a.approved_at, v_a.expires_at);
    IF v_recomputed IS DISTINCT FROM v_a.canonical_approval_evidence_hash THEN
      v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_CANONICAL_EVIDENCE_HASH_MISMATCH');
    END IF;
  END IF;

  IF p_expected_content_hash IS NOT NULL AND p_expected_content_hash <> v_a.content_hash_at_approval THEN
    v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_CONTENT_HASH_MISMATCH');
  END IF;
  IF p_expected_recipient_hash IS NOT NULL AND p_expected_recipient_hash <> COALESCE(v_a.recipient_set_hash_at_approval,'') THEN
    v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_RECIPIENT_HASH_MISMATCH');
  END IF;
  IF p_expected_configuration_hash IS NOT NULL AND p_expected_configuration_hash <> COALESCE(v_a.configuration_hash_at_approval,'') THEN
    v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_CONFIGURATION_HASH_MISMATCH');
  END IF;
  IF p_expected_correlation_id IS NOT NULL AND p_expected_correlation_id <> COALESCE(v_a.correlation_id_at_approval,'00000000-0000-0000-0000-000000000000') THEN
    v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_CORRELATION_MISMATCH');
  END IF;

  IF v_a.content_hash_at_approval IS DISTINCT FROM v_s.content_hash THEN
    v_blockers := v_blockers || jsonb_build_object('code','SNAPSHOT_CONTENT_HASH_DRIFT');
  END IF;
  IF v_a.recipient_set_hash_at_approval IS DISTINCT FROM v_s.recipient_set_hash THEN
    v_blockers := v_blockers || jsonb_build_object('code','SNAPSHOT_RECIPIENT_HASH_DRIFT');
  END IF;
  IF v_a.configuration_hash_at_approval IS DISTINCT FROM v_s.certified_dependency_hash THEN
    v_blockers := v_blockers || jsonb_build_object('code','SNAPSHOT_CONFIGURATION_HASH_DRIFT');
  END IF;

  v_ok := jsonb_array_length(v_blockers)=0;
  v_evidence := jsonb_build_object(
    'approval', jsonb_build_object(
      'id', v_a.id, 'status', v_a.status, 'expires_at', v_a.expires_at,
      'evidence_version', v_a.evidence_version,
      'canonical_approval_evidence_hash', v_a.canonical_approval_evidence_hash,
      'correlation_id_at_approval', v_a.correlation_id_at_approval,
      'content_hash_at_approval', v_a.content_hash_at_approval,
      'recipient_set_hash_at_approval', v_a.recipient_set_hash_at_approval,
      'template_version_id_at_approval', v_a.template_version_id_at_approval,
      'configuration_hash_at_approval', v_a.configuration_hash_at_approval),
    'snapshot', jsonb_build_object(
      'id', v_s.id, 'status', v_s.status,
      'correlation_id', v_s.correlation_id, 'expires_at', v_s.expires_at,
      'certified_dependency_hash', v_s.certified_dependency_hash));

  RETURN jsonb_build_object(
    'ok', v_ok, 'allowed', v_ok,
    'blockers', v_blockers,
    'evidence', v_evidence,
    'evaluator_version','comm-hub-preview-approval-binding/v2',
    'approval', v_evidence->'approval',
    'snapshot', v_evidence->'snapshot');
END $function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_preview_runtime_evidence(p_snapshot_id uuid, p_module_code text, p_event_code text, p_channel text, p_correlation_id uuid, p_expected_content_hash text, p_expected_recipient_hash text, p_expected_template_version_id uuid, p_expected_configuration_hash text, p_transition_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_snap record;
  v_ge jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_requires_approval boolean;
  v_has_active_approval boolean;
  v_evidence jsonb;
  v_allowed boolean;
  v_ev_version text;
  v_resolver jsonb;
  v_required_unresolved int;
  v_canonical_raw text;
BEGIN
  IF p_transition_stage IS NULL OR p_transition_stage = '' THEN
    RETURN jsonb_build_object(
      'allowed', false, 'ok', false, 'evaluator_version','comm-hub-preview-runtime-evidence/v3',
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_TRANSITION_STAGE_UNKNOWN','message','Transition stage required')),
      'evidence', '{}'::jsonb);
  END IF;
  IF p_transition_stage NOT IN (
    'APPROVE_PREVIEW','START_DRY_RUN','PROCESS_DRY_RUN','CERTIFY_DRY_RUN',
    'START_CONTROLLED_STUB','CREATE_TARGETED_MESSAGE','CLAIM_TARGETED_MESSAGE',
    'DISPATCH_CONTROLLED_STUB','CERTIFY_CONTROLLED_STUB'
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false, 'ok', false, 'evaluator_version','comm-hub-preview-runtime-evidence/v3',
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_TRANSITION_STAGE_UNKNOWN','message','Transition stage not permitted','detail',jsonb_build_object('transition_stage',p_transition_stage))),
      'evidence', jsonb_build_object('transition_stage',p_transition_stage));
  END IF;

  v_requires_approval := (p_transition_stage <> 'APPROVE_PREVIEW');

  IF p_snapshot_id IS NULL THEN
    RETURN jsonb_build_object(
      'allowed', false, 'ok', false, 'evaluator_version','comm-hub-preview-runtime-evidence/v3',
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_SNAPSHOT_MISSING','message','Preview snapshot id required')),
      'evidence','{}'::jsonb);
  END IF;

  SELECT id,status,module_code,event_code,channel,expires_at,
         placeholder_scanner_version,raw_placeholder_count,renderer_unresolved_variables,
         correlation_id,content_hash,recipient_set_hash,template_version_id,
         certified_dependency_hash,current_dependency_hash,governance_evidence
    INTO v_snap
    FROM public.communication_preview_snapshot
   WHERE id = p_snapshot_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false, 'ok', false, 'evaluator_version','comm-hub-preview-runtime-evidence/v3',
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_SNAPSHOT_MISSING','message','Preview snapshot not found')),
      'evidence','{}'::jsonb);
  END IF;

  v_ge := COALESCE(v_snap.governance_evidence,'{}'::jsonb);
  v_ev_version := v_ge->>'evidence_version';
  v_resolver := v_ge->'resolver';

  IF v_snap.status <> 'PREPARED' THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_STATUS_INVALID','message','Snapshot must be in PREPARED lifecycle status','detail',jsonb_build_object('status',v_snap.status,'transition_stage',p_transition_stage));
  END IF;
  IF v_snap.status='EXPIRED' OR (v_snap.expires_at IS NOT NULL AND v_snap.expires_at<now()) THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_EXPIRED','message','Preview snapshot expired');
  END IF;
  IF v_snap.status='SUPERSEDED' THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_SUPERSEDED','message','Preview snapshot superseded');
  END IF;

  IF v_requires_approval THEN
    SELECT EXISTS(
      SELECT 1 FROM public.communication_preview_approval a
       WHERE a.snapshot_id = v_snap.id
         AND a.status IN ('ACTIVE','RESERVED')
         AND (a.expires_at IS NULL OR a.expires_at > now())
    ) INTO v_has_active_approval;
    IF NOT v_has_active_approval THEN
      v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_NOT_APPROVED','message','Downstream transitions require an active preview approval','detail',jsonb_build_object('transition_stage',p_transition_stage));
    END IF;
  ELSE
    IF EXISTS(
      SELECT 1 FROM public.communication_preview_approval a
       WHERE a.snapshot_id = v_snap.id
         AND a.status IN ('ACTIVE','RESERVED')
         AND (a.expires_at IS NULL OR a.expires_at > now())
    ) THEN
      v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_ALREADY_APPROVED','message','Snapshot already has an active approval');
    END IF;
  END IF;

  IF v_snap.module_code IS DISTINCT FROM p_module_code THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_MODULE_MISMATCH','message','Module mismatch');
  END IF;
  IF v_snap.event_code IS DISTINCT FROM p_event_code THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_EVENT_MISMATCH','message','Event mismatch');
  END IF;
  IF p_channel IS NOT NULL AND v_snap.channel IS DISTINCT FROM p_channel THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_CHANNEL_MISMATCH','message','Channel mismatch');
  END IF;

  IF p_correlation_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','CORRELATION_ID_REQUIRED','message','Correlation id required');
  ELSIF v_snap.correlation_id IS DISTINCT FROM p_correlation_id THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_CORRELATION_MISMATCH','message','Correlation mismatch');
  END IF;

  IF COALESCE(v_snap.placeholder_scanner_version,'') <> 'comm-hub-raw-placeholder-scanner/v2' THEN
    v_blockers := v_blockers || jsonb_build_object('code','SCANNER_VERSION_MISMATCH','message','Scanner version must be exactly comm-hub-raw-placeholder-scanner/v2','detail',jsonb_build_object('scanner_version',v_snap.placeholder_scanner_version));
  END IF;
  IF COALESCE(v_snap.raw_placeholder_count,0) <> 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','RAW_PLACEHOLDER_RESIDUE','message','Raw placeholder residue present');
  END IF;
  IF COALESCE((v_ge->'malformed_braces'->>'count')::int, -1) <> 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','MALFORMED_BRACES_PRESENT','message','Malformed brace count non-zero or missing');
  END IF;
  IF COALESCE(jsonb_array_length(COALESCE(v_snap.renderer_unresolved_variables,'[]'::jsonb)),0) <> 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','RENDERER_UNRESOLVED_PRESENT','message','Renderer unresolved variables present');
  END IF;

  -- Canonical resolver evidence key: required_unresolved_count.
  -- For evidence_version = comm-hub-preview-governance-evidence/v1 the canonical key is authoritative.
  -- Missing / non-numeric canonical value => RESOLVER_EVIDENCE_INVALID (never blame a real variable).
  -- Legacy reversed key `unresolved_required_count` is honoured only for other/older evidence versions.
  IF v_resolver IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_EVIDENCE_MISSING','message','Resolver evidence object missing');
  ELSIF v_ev_version = 'comm-hub-preview-governance-evidence/v1' THEN
    v_canonical_raw := v_resolver->>'required_unresolved_count';
    IF v_canonical_raw IS NULL OR v_canonical_raw !~ '^-?[0-9]+$' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','RESOLVER_EVIDENCE_INVALID',
        'message','v1 resolver evidence missing canonical required_unresolved_count',
        'detail', jsonb_build_object(
          'evidence_version', v_ev_version,
          'resolver', v_resolver,
          'canonical_key','required_unresolved_count'));
    ELSE
      v_required_unresolved := v_canonical_raw::int;
      IF v_required_unresolved > 0 THEN
        v_blockers := v_blockers || jsonb_build_object(
          'code','RESOLVER_REQUIRED_UNRESOLVED',
          'message','Resolver required unresolved',
          'detail', jsonb_build_object(
            'evidence_version', v_ev_version,
            'required_unresolved_count', v_required_unresolved,
            'total_unresolved_count', COALESCE((v_resolver->>'total_unresolved_count')::int, NULL),
            'unresolved_variables', COALESCE(v_snap.governance_evidence->'resolver'->'required_unresolved_variables','[]'::jsonb)));
      END IF;
    END IF;
  ELSE
    -- legacy / unknown evidence versions: accept either key, prefer canonical
    v_canonical_raw := COALESCE(v_resolver->>'required_unresolved_count', v_resolver->>'unresolved_required_count');
    IF v_canonical_raw IS NULL OR v_canonical_raw !~ '^-?[0-9]+$' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','RESOLVER_EVIDENCE_INVALID',
        'message','Resolver required-unresolved count missing or non-numeric',
        'detail', jsonb_build_object('evidence_version', v_ev_version, 'resolver', v_resolver));
    ELSIF v_canonical_raw::int > 0 THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','RESOLVER_REQUIRED_UNRESOLVED',
        'message','Resolver required unresolved',
        'detail', jsonb_build_object('evidence_version', v_ev_version, 'required_unresolved_count', v_canonical_raw::int));
    END IF;
  END IF;

  IF NOT (v_ge ? 'raw_placeholders') THEN v_blockers := v_blockers || jsonb_build_object('code','RAW_PLACEHOLDER_EVIDENCE_MISSING'); END IF;
  IF NOT (v_ge ? 'malformed_braces') THEN v_blockers := v_blockers || jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_MISSING'); END IF;
  IF NOT (v_ge ? 'renderer')         THEN v_blockers := v_blockers || jsonb_build_object('code','RENDERER_EVIDENCE_MISSING'); END IF;
  IF NOT (v_ge ? 'resolver')         THEN v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_EVIDENCE_MISSING'); END IF;

  IF v_snap.content_hash IS NULL OR v_snap.content_hash='' THEN
    v_blockers := v_blockers || jsonb_build_object('code','CONTENT_HASH_MISSING');
  ELSIF p_expected_content_hash IS NOT NULL AND v_snap.content_hash <> p_expected_content_hash THEN
    v_blockers := v_blockers || jsonb_build_object('code','CONTENT_HASH_MISMATCH');
  END IF;
  IF v_snap.recipient_set_hash IS NULL OR v_snap.recipient_set_hash='' THEN
    v_blockers := v_blockers || jsonb_build_object('code','RECIPIENT_HASH_MISSING');
  ELSIF p_expected_recipient_hash IS NOT NULL AND v_snap.recipient_set_hash <> p_expected_recipient_hash THEN
    v_blockers := v_blockers || jsonb_build_object('code','RECIPIENT_HASH_MISMATCH');
  END IF;
  IF p_expected_template_version_id IS NOT NULL THEN
    IF v_snap.template_version_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object('code','TEMPLATE_VERSION_MISSING');
    ELSIF v_snap.template_version_id <> p_expected_template_version_id THEN
      v_blockers := v_blockers || jsonb_build_object('code','TEMPLATE_VERSION_MISMATCH');
    END IF;
  END IF;
  IF p_expected_configuration_hash IS NOT NULL THEN
    IF COALESCE(v_snap.certified_dependency_hash,'')='' THEN
      v_blockers := v_blockers || jsonb_build_object('code','CONFIGURATION_HASH_MISSING');
    ELSIF v_snap.certified_dependency_hash <> p_expected_configuration_hash THEN
      v_blockers := v_blockers || jsonb_build_object('code','CONFIGURATION_HASH_MISMATCH');
    END IF;
    IF v_snap.certified_dependency_hash IS DISTINCT FROM v_snap.current_dependency_hash THEN
      v_blockers := v_blockers || jsonb_build_object('code','DEPENDENCY_HASH_DRIFT');
    END IF;
  END IF;

  v_allowed := jsonb_array_length(v_blockers)=0;
  v_evidence := jsonb_build_object(
    'snapshot_id',v_snap.id, 'status',v_snap.status,
    'content_hash',v_snap.content_hash, 'recipient_set_hash',v_snap.recipient_set_hash,
    'template_version_id',v_snap.template_version_id,
    'certified_dependency_hash',v_snap.certified_dependency_hash,
    'current_dependency_hash',v_snap.current_dependency_hash,
    'correlation_id',v_snap.correlation_id, 'expires_at',v_snap.expires_at,
    'scanner_version',v_snap.placeholder_scanner_version,
    'raw_placeholder_count',v_snap.raw_placeholder_count,
    'evidence_version', v_ev_version,
    'resolver_required_unresolved_count', COALESCE((v_resolver->>'required_unresolved_count')::int, NULL),
    'resolver_total_unresolved_count', COALESCE((v_resolver->>'total_unresolved_count')::int, NULL),
    'transition_stage',p_transition_stage);

  RETURN jsonb_build_object(
    'allowed', v_allowed,
    'ok', v_allowed,
    'blockers', v_blockers,
    'evidence', v_evidence,
    'evaluator_version','comm-hub-preview-runtime-evidence/v3',
    'transition_stage', p_transition_stage);
END $function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_readiness(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module   text := NULLIF(p_payload->>'module_code','');
  v_event    text := NULLIF(p_payload->>'event_code','');
  v_channel  text := COALESCE(NULLIF(p_payload->>'channel',''),'email');
  v_target   text := COALESCE(NULLIF(p_payload->>'target_stage',''),'SAFE_TESTING');
  v_stub_id  uuid := NULLIF(p_payload->>'controlled_stub_certification_id','')::uuid;
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_profile  public.communication_hub_mode_profile%ROWTYPE;
  v_send_ctx text;
  v_decision jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_actions  jsonb := '[]'::jsonb;
  v_ready    boolean := true;
  v_to       jsonb := '[]'::jsonb;
  v_dry_id   uuid;
  v_stub     public.communication_controlled_live_certification%ROWTYPE;
  v_exec     public.communication_controlled_live_execution%ROWTYPE;
  v_dry      public.communication_dry_run_certification%ROWTYPE;
BEGIN
  SELECT * INTO v_settings FROM public.communication_hub_control_settings
  ORDER BY updated_at DESC NULLS LAST LIMIT 1;

  SELECT * INTO v_profile
  FROM public.communication_hub_mode_profile
  WHERE operating_mode = v_settings.operating_mode::text;

  IF v_settings.operating_mode::text = 'EMERGENCY_STOP' THEN
    v_ready := false;
    v_blockers := v_blockers || jsonb_build_object(
      'code','emergency_stop_active','stage','platform','severity','critical',
      'title','Emergency Stop is engaged',
      'message','New dispatch is blocked while Emergency Stop is engaged.',
      'fixAction','emergency_stop','fixRoute','/admin/communication-hub/go-live');
  END IF;

  v_send_ctx := CASE v_target
    WHEN 'SAFE_TESTING'         THEN 'dry_run'
    WHEN 'CONTROLLED_STUB'      THEN 'controlled_live'
    WHEN 'ONE_REAL_EMAIL'       THEN 'controlled_live'
    WHEN 'MANUAL_PRODUCTION'    THEN 'manual_production'
    WHEN 'AUTOMATED_PRODUCTION' THEN 'cron'
    ELSE 'dry_run'
  END;

  -- Stage 6 authoritative lineage derivation. Ignore browser-supplied
  -- recipient / dry_run values; derive from durable server rows.
  IF v_target = 'ONE_REAL_EMAIL' AND v_module IS NOT NULL AND v_event IS NOT NULL THEN
    IF v_stub_id IS NULL THEN
      v_ready := false;
      v_blockers := v_blockers || jsonb_build_object(
        'code','controlled_stub_certification_missing','stage','stage5','severity','critical',
        'title','Controlled Stub certification not provided',
        'message','Stage 6 readiness requires an authoritative Controlled Stub certification id.');
    ELSE
      SELECT * INTO v_stub
      FROM public.communication_controlled_live_certification
      WHERE id = v_stub_id;

      IF NOT FOUND
         OR v_stub.certification_kind <> 'CONTROLLED_STUB'
         OR v_stub.invalidated_at IS NOT NULL
         OR v_stub.module_code <> v_module
         OR v_stub.event_code <> v_event
         OR v_stub.channel <> v_channel THEN
        v_ready := false;
        v_blockers := v_blockers || jsonb_build_object(
          'code','controlled_stub_certification_invalid','stage','stage5','severity','critical',
          'title','Controlled Stub certification invalid',
          'message','The referenced Controlled Stub certification is missing, invalidated, or lineage-mismatched.');
      ELSE
        SELECT * INTO v_exec
        FROM public.communication_controlled_live_execution
        WHERE id = v_stub.execution_id;

        IF NOT FOUND OR COALESCE(v_exec.recipient,'') = '' THEN
          v_ready := false;
          v_blockers := v_blockers || jsonb_build_object(
            'code','controlled_live_execution_missing','stage','stage5','severity','critical',
            'title','Controlled Stub execution has no recipient',
            'message','The controlled-live execution linked to the certification could not be loaded.');
        ELSE
          v_to := jsonb_build_array(v_exec.recipient);
          v_dry_id := v_stub.dry_run_certification_id;

          SELECT * INTO v_dry
          FROM public.communication_dry_run_certification
          WHERE id = v_dry_id;

          IF NOT FOUND THEN
            v_ready := false;
            v_blockers := v_blockers || jsonb_build_object(
              'code','dry_run_certification_missing','stage','stage3','severity','critical',
              'title','Dry Run certification missing',
              'message','The Dry Run certification bound to the Controlled Stub could not be found.');
          ELSIF v_dry.status <> 'ACTIVE'
             OR v_dry.result <> 'DRY_RUN_PASSED'
             OR v_dry.invalidated_at IS NOT NULL
             OR (v_dry.expires_at IS NOT NULL AND v_dry.expires_at < now()) THEN
            v_ready := false;
            v_blockers := v_blockers || jsonb_build_object(
              'code','dry_run_certification_not_active','stage','stage3','severity','critical',
              'title','Dry Run certification not active',
              'message','Dry Run certification is expired, invalidated, or not in the ACTIVE/DRY_RUN_PASSED state.');
          ELSIF v_dry.module_code <> v_module
             OR v_dry.event_code <> v_event
             OR v_dry.channel <> v_channel THEN
            v_ready := false;
            v_blockers := v_blockers || jsonb_build_object(
              'code','dry_run_certification_lineage_mismatch','stage','stage3','severity','critical',
              'title','Dry Run certification lineage mismatch',
              'message','Dry Run certification does not match the current module/event/channel.');
          ELSIF v_stub.preview_approval_id IS NOT NULL
                AND v_dry.preview_approval_id IS NOT NULL
                AND v_stub.preview_approval_id <> v_dry.preview_approval_id THEN
            v_ready := false;
            v_blockers := v_blockers || jsonb_build_object(
              'code','preview_approval_lineage_mismatch','stage','stage4','severity','critical',
              'title','Preview approval lineage mismatch',
              'message','Controlled Stub and Dry Run certifications reference different preview approvals.');
          ELSIF (v_stub.configuration_version IS NOT NULL
                 AND v_settings.configuration_version IS NOT NULL
                 AND v_stub.configuration_version <> v_settings.configuration_version) THEN
            v_ready := false;
            v_blockers := v_blockers || jsonb_build_object(
              'code','configuration_version_stale','stage','platform','severity','critical',
              'title','Configuration version changed since certification',
              'message','Rerun Controlled Stub after the configuration change.');
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_module IS NOT NULL AND v_event IS NOT NULL THEN
    v_decision := public._evaluate_comm_hub_send_rules(jsonb_build_object(
      'module_code', v_module,
      'event_code', v_event,
      'channel', v_channel,
      'send_context', v_send_ctx,
      'to_recipients', v_to,
      'cc_recipients', '[]'::jsonb,
      'bcc_recipients', '[]'::jsonb,
      'preview_confirmed', (v_target = 'ONE_REAL_EMAIL'),
      'dry_run_certification_id', to_jsonb(v_dry_id)
    ));
    IF v_decision IS NOT NULL THEN
      IF NOT COALESCE((v_decision->>'allowed')::boolean, false) THEN
        v_ready := false;
      END IF;
      v_blockers := v_blockers || COALESCE(v_decision->'blockers','[]'::jsonb);
      v_warnings := v_warnings || COALESCE(v_decision->'warnings','[]'::jsonb);
    END IF;
  END IF;

  IF v_target = 'MANUAL_PRODUCTION' AND v_module IS NOT NULL AND v_event IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.communication_hub_event_live_control
      WHERE module_code = v_module AND event_code = v_event
        AND status IN ('live_manual_only','live_cron_allowed')
    ) THEN
      v_ready := false;
      v_blockers := v_blockers || jsonb_build_object(
        'code','event_not_certified_for_manual_production','stage','event','severity','critical',
        'title','Event not certified for Manual Production',
        'message','This event has no live_manual_only or live_cron_allowed certification.',
        'fixAction','event_configuration');
    END IF;
  END IF;

  IF v_target = 'AUTOMATED_PRODUCTION' AND v_module IS NOT NULL AND v_event IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.communication_hub_event_live_control
      WHERE module_code = v_module AND event_code = v_event
        AND status = 'live_cron_allowed'
    ) THEN
      v_ready := false;
      v_blockers := v_blockers || jsonb_build_object(
        'code','event_not_certified_for_automated_production','stage','event','severity','critical',
        'title','Event not certified for Automated Production',
        'message','This event has no live_cron_allowed certification.',
        'fixAction','event_configuration');
    END IF;
  END IF;

  IF v_target IN ('ONE_REAL_EMAIL','CONTROLLED_STUB') AND v_settings.operating_mode::text = 'DRY_RUN' THEN
    v_warnings := v_warnings || jsonb_build_object(
      'code','operating_mode_dry_run_only','stage','mode',
      'message','Current mode is Safe Testing; switch to Controlled Testing to run this stage.');
  END IF;
  IF v_target = 'MANUAL_PRODUCTION' AND v_settings.operating_mode::text NOT IN ('MANUAL_PRODUCTION','AUTOMATED_PRODUCTION') THEN
    v_ready := false;
    v_blockers := v_blockers || jsonb_build_object(
      'code','operating_mode_not_production','stage','mode','severity','high',
      'title','Operating mode is not Production',
      'message','Activate Manual Production from the mode cards to enable this stage.');
  END IF;
  IF v_target = 'AUTOMATED_PRODUCTION' AND v_settings.operating_mode::text <> 'AUTOMATED_PRODUCTION' THEN
    v_ready := false;
    v_blockers := v_blockers || jsonb_build_object(
      'code','operating_mode_not_automated','stage','mode','severity','high',
      'title','Operating mode is not Automated Production',
      'message','Activate Automated Production from the mode cards to enable this stage.');
  END IF;

  RETURN jsonb_build_object(
    'ready', v_ready,
    'currentMode', v_settings.operating_mode::text,
    'targetStage', v_target,
    'configurationVersion', v_settings.configuration_version,
    'profile', to_jsonb(v_profile),
    'blockers', v_blockers,
    'warnings', v_warnings,
    'availableActions', v_actions,
    'evaluatedAt', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_runtime_governance(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text, p_target_stage text DEFAULT 'PREVIEW_READY'::text, p_preview_snapshot_id uuid DEFAULT NULL::uuid, p_preview_approval_id uuid DEFAULT NULL::uuid, p_dry_run_certification_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_canonical text := public.normalize_comm_hub_go_live_stage_strict(p_target_stage);
  -- Map canonical stages back to legacy vocabulary the impl understands
  v_legacy text := CASE v_canonical
    WHEN 'READINESS_ONLY' THEN 'READINESS_ONLY'
    WHEN 'PREVIEW_READY' THEN 'PREVIEW_TEST'
    WHEN 'APPROVAL_READY' THEN 'PREVIEW_APPROVAL'
    WHEN 'DRY_RUN_READY' THEN 'DRY_RUN'
    WHEN 'CONTROLLED_STUB_READY' THEN 'CONTROLLED_STUB'
    WHEN 'ONE_REAL_EMAIL_READY' THEN 'CONTROLLED_LIVE'
    WHEN 'MANUAL_PRODUCTION_READY' THEN 'CONTROLLED_LIVE'
    WHEN 'AUTOMATED_PRODUCTION_READY' THEN 'CONTROLLED_LIVE'
    ELSE 'PREVIEW_TEST'
  END;
  v_result jsonb;
BEGIN
  v_result := public._check_comm_hub_runtime_governance_impl(
    p_module_code, p_event_code, p_channel, v_legacy,
    p_preview_snapshot_id, p_preview_approval_id, p_dry_run_certification_id);
  RETURN v_result
    || jsonb_build_object('requested_stage_canonical', v_canonical,
                          'requested_stage_legacy', v_legacy,
                          'schema_version','runtime-governance-wrap/1');
END;$function$;
CREATE OR REPLACE FUNCTION public.check_comm_hub_runtime_transition_safe(p_action text, p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb; v_blockers jsonb;
BEGIN
  BEGIN v_result := public.assert_comm_hub_runtime_transition(p_action, p_context);
  EXCEPTION WHEN OTHERS THEN
    v_result := jsonb_build_object('allowed',false,
      'denied_reasons', jsonb_build_array(jsonb_build_object('code','runtime_gate_error','message',SQLERRM,'sqlstate',SQLSTATE)),
      'blockers',       jsonb_build_array(jsonb_build_object('code','runtime_gate_error','message',SQLERRM,'sqlstate',SQLSTATE)),
      'transition_log_id', NULL,
      'correlation_id', NULLIF(p_context->>'correlation_id','')::uuid,
      'evaluator_version','4b3.dry-run-wiring.safe');
    RETURN v_result;
  END;
  v_blockers := COALESCE(v_result->'blockers', v_result->'denied_reasons','[]'::jsonb);
  -- Guarantee non-empty blockers whenever allowed=false
  IF COALESCE((v_result->>'allowed')::boolean,false) = false
     AND jsonb_array_length(v_blockers) = 0 THEN
    v_blockers := jsonb_build_array(jsonb_build_object('code','RUNTIME_TRANSITION_DENIED_UNSPECIFIED'));
  END IF;
  v_result := v_result
    || jsonb_build_object('blockers', v_blockers, 'denied_reasons', v_blockers);
  RETURN v_result;
END; $function$;
CREATE OR REPLACE FUNCTION public.check_dms_transfer_eligibility(p_ssn text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_pending_count integer;
  v_result jsonb;
  v_blocked_statuses text[] := ARRAY['Z', 'D', 'P', 'R']; -- Draft, Draft, Pending, Rejected
BEGIN
  -- Get the application status from ip_master
  SELECT status INTO v_status
  FROM ip_master
  WHERE ssn = p_ssn
  LIMIT 1;

  -- If no record found, not eligible
  IF v_status IS NULL THEN
    RETURN jsonb_build_object(
      'can_transfer_to_dms', false,
      'reason', 'no_record',
      'message', 'No IP master record found for this SSN',
      'application_status', NULL,
      'pending_document_count', 0
    );
  END IF;

  -- Check if status is in blocked list
  IF v_status = ANY(v_blocked_statuses) THEN
    RETURN jsonb_build_object(
      'can_transfer_to_dms', false,
      'reason', 'status_blocked',
      'message', 'Application status does not allow DMS transfer',
      'application_status', v_status,
      'pending_document_count', 0
    );
  END IF;

  -- Count documents pending transfer
  SELECT count(*) INTO v_pending_count
  FROM ip_application_documents
  WHERE ssn = p_ssn
    AND (transfer_status IS NULL OR transfer_status IN ('Pending', 'Failed'));

  -- Must have at least one pending document
  IF v_pending_count = 0 THEN
    RETURN jsonb_build_object(
      'can_transfer_to_dms', false,
      'reason', 'no_pending_documents',
      'message', 'No documents pending DMS transfer',
      'application_status', v_status,
      'pending_document_count', 0
    );
  END IF;

  -- All conditions met
  RETURN jsonb_build_object(
    'can_transfer_to_dms', true,
    'reason', 'eligible',
    'message', 'DMS transfer is available',
    'application_status', v_status,
    'pending_document_count', v_pending_count
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_duplicate_open_batch(p_cashier_user_code text, p_batch_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mode TEXT;
  v_config_value JSONB;
  v_existing_count INT;
  v_existing_batch TEXT;
BEGIN
  -- Read the duplicate_open_batch config from payment_module_config
  SELECT config_value INTO v_config_value
  FROM payment_module_config
  WHERE config_key = 'duplicate_open_batch';

  v_mode := COALESCE(v_config_value->>'mode', 'warning');

  -- Check for existing open batches for same cashier on same date
  SELECT COUNT(*), MAX(batch_number)
  INTO v_existing_count, v_existing_batch
  FROM cn_batch
  WHERE entered_by = p_cashier_user_code
    AND batch_status = 'O'
    AND (batch_date::date) = p_batch_date;

  IF v_existing_count > 0 THEN
    RETURN jsonb_build_object(
      'has_duplicate', true,
      'mode', v_mode,
      'existing_batch', v_existing_batch,
      'existing_count', v_existing_count,
      'message', 'An open batch already exists for cashier ' || p_cashier_user_code || ' on ' || p_batch_date::text
    );
  END IF;

  RETURN jsonb_build_object(
    'has_duplicate', false,
    'mode', v_mode,
    'existing_batch', null,
    'existing_count', 0,
    'message', null
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_feature_flag(_flag_key text, _user_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _flag record;
BEGIN
  SELECT * INTO _flag FROM feature_flags WHERE flag_key = _flag_key;
  IF NOT FOUND OR NOT _flag.is_enabled THEN
    RETURN false;
  END IF;
  RETURN public.check_module_rollout_access(
    COALESCE(_user_id, auth.uid()),
    _flag.rollout_state,
    false,
    _flag.pilot_user_ids,
    _flag.pilot_role_ids
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_ip_duplicates(p_first_name text, p_last_name text, p_dob date, p_gender text, p_exclude_uuid uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, ssn text, full_name text, date_of_birth date, gender text, match_score integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    im.id,
    im.ssn::text,
    CONCAT(im.firstname, ' ', COALESCE(im.middle_name, ''), ' ', im.surname)::text as full_name,
    im.dob as date_of_birth,
    im.sex::text as gender,
    (
      CASE WHEN LOWER(im.firstname) = LOWER(p_first_name) THEN 30 ELSE 0 END +
      CASE WHEN LOWER(im.surname) = LOWER(p_last_name) THEN 30 ELSE 0 END +
      CASE WHEN im.dob = p_dob THEN 25 ELSE 0 END +
      CASE WHEN LOWER(im.sex) = LOWER(p_gender) THEN 15 ELSE 0 END
    ) as match_score
  FROM ip_master im
  WHERE im.unique_uuid != COALESCE(p_exclude_uuid, '00000000-0000-0000-0000-000000000000'::UUID)
    AND (
      (LOWER(im.firstname) = LOWER(p_first_name) AND LOWER(im.surname) = LOWER(p_last_name))
      OR (im.dob = p_dob AND LOWER(im.sex) = LOWER(p_gender))
    )
  ORDER BY match_score DESC
  LIMIT 10;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_ip_whitelist(p_ip_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule RECORD;
  v_ip_num BIGINT;
  v_start_num BIGINT;
  v_end_num BIGINT;
  v_has_active_rules BOOLEAN;
  v_policy_enabled BOOLEAN;
BEGIN
  SELECT COALESCE(
    (SELECT config_value = 'true' FROM security_policy_config WHERE config_key = 'ip_access_policy_enabled'),
    false
  ) INTO v_policy_enabled;

  IF NOT v_policy_enabled THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'policy_disabled');
  END IF;

  SELECT EXISTS(SELECT 1 FROM ip_access_rules WHERE is_active = true) INTO v_has_active_rules;
  
  IF NOT v_has_active_rules THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'no_active_rules');
  END IF;

  IF p_ip_address IS NULL OR p_ip_address = '' OR p_ip_address = 'unknown' THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_ip');
  END IF;

  v_ip_num := (split_part(p_ip_address, '.', 1)::BIGINT * 16777216) +
              (split_part(p_ip_address, '.', 2)::BIGINT * 65536) +
              (split_part(p_ip_address, '.', 3)::BIGINT * 256) +
              (split_part(p_ip_address, '.', 4)::BIGINT);

  FOR v_rule IN SELECT * FROM ip_access_rules WHERE is_active = true AND rule_type = 'single' LOOP
    IF v_rule.single_ip = p_ip_address THEN
      RETURN jsonb_build_object('allowed', true, 'reason', 'single_ip_match', 'rule_id', v_rule.id);
    END IF;
  END LOOP;

  FOR v_rule IN SELECT * FROM ip_access_rules WHERE is_active = true AND rule_type = 'range' LOOP
    v_start_num := (split_part(v_rule.range_start_ip, '.', 1)::BIGINT * 16777216) +
                   (split_part(v_rule.range_start_ip, '.', 2)::BIGINT * 65536) +
                   (split_part(v_rule.range_start_ip, '.', 3)::BIGINT * 256) +
                   (split_part(v_rule.range_start_ip, '.', 4)::BIGINT);
    v_end_num := (split_part(v_rule.range_end_ip, '.', 1)::BIGINT * 16777216) +
                 (split_part(v_rule.range_end_ip, '.', 2)::BIGINT * 65536) +
                 (split_part(v_rule.range_end_ip, '.', 3)::BIGINT * 256) +
                 (split_part(v_rule.range_end_ip, '.', 4)::BIGINT);
    IF v_ip_num >= v_start_num AND v_ip_num <= v_end_num THEN
      RETURN jsonb_build_object('allowed', true, 'reason', 'range_match', 'rule_id', v_rule.id);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('allowed', false, 'reason', 'no_matching_rule');
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_meeting_overlap(p_assigned_user_id uuid, p_meeting_date date, p_meeting_start_time time without time zone, p_buffer_minutes integer DEFAULT 20, p_exclude_meeting_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(has_overlap boolean, conflicting_meeting_id uuid, conflicting_reference text, conflicting_start_time time without time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_slot_end_time TIME;
  v_meeting_row   RECORD;
  v_reserve_row   RECORD;
BEGIN
  v_slot_end_time := p_meeting_start_time + (p_buffer_minutes || ' minutes')::INTERVAL;

  -- 1. Check active scheduled meetings
  --    'Paused' was removed — it is NOT a valid meeting_status enum value.
  --    Valid statuses: Scheduled, Rescheduled, InProgress, Closed, Cancelled, Rejected
  SELECT m.id, m.meeting_reference, m.meeting_time
  INTO v_meeting_row
  FROM public.meetings m
  WHERE
    m.assigned_user_id = p_assigned_user_id
    AND m.meeting_date  = p_meeting_date
    AND m.status IN ('Scheduled', 'InProgress')
    AND (p_exclude_meeting_id IS NULL OR m.id <> p_exclude_meeting_id)
    AND p_meeting_start_time < (m.meeting_time + (p_buffer_minutes || ' minutes')::INTERVAL)
    AND v_slot_end_time > m.meeting_time
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT TRUE, v_meeting_row.id, v_meeting_row.meeting_reference, v_meeting_row.meeting_time;
    RETURN;
  END IF;

  -- 2. Check phantom slot reservations (releasePreviousSlot=false)
  SELECT r.id, r.meeting_time
  INTO v_reserve_row
  FROM public.meeting_slot_reservations r
  WHERE
    r.assigned_user_id = p_assigned_user_id
    AND r.meeting_date  = p_meeting_date
    AND r.is_active     = TRUE
    AND p_meeting_start_time < (r.meeting_time + (p_buffer_minutes || ' minutes')::INTERVAL)
    AND v_slot_end_time > r.meeting_time
  LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT TRUE, NULL::UUID, 'Reserved Slot'::TEXT, v_reserve_row.meeting_time;
    RETURN;
  END IF;

  -- 3. No conflict
  RETURN QUERY SELECT FALSE, NULL::UUID, NULL::TEXT, NULL::TIME;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_module_rollout_access(_user_id uuid, _rollout_state text, _internal_only boolean, _pilot_user_ids uuid[], _pilot_role_ids uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _rollout_state = 'public' AND NOT _internal_only THEN
    RETURN true;
  END IF;
  IF _rollout_state = 'hidden' THEN
    RETURN false;
  END IF;
  IF public.is_admin(_user_id) THEN
    RETURN true;
  END IF;
  IF _internal_only THEN
    RETURN false;
  END IF;
  IF _rollout_state = 'internal_pilot' THEN
    IF _user_id = ANY(_pilot_user_ids) THEN
      RETURN true;
    END IF;
    IF array_length(_pilot_role_ids, 1) > 0 THEN
      RETURN EXISTS (
        SELECT 1 FROM user_roles ur
        JOIN roles r ON r.role_name = ur.role::text
        WHERE ur.user_id = _user_id
          AND r.id = ANY(_pilot_role_ids)
      );
    END IF;
    RETURN false;
  END IF;
  RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_row_access(_user_id uuid, _module_name text, _table_name text, _action text, _record jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result JSONB;
  user_roles TEXT[];
  rule_record RECORD;
  is_allowed BOOLEAN := false;
  rules_applied JSONB := '[]'::jsonb;
  denial_reason TEXT := NULL;
BEGIN
  IF public.is_admin(_user_id) THEN
    RETURN jsonb_build_object('allowed', true, 'rules_applied', '[{"type": "admin_bypass"}]'::jsonb, 'reason', NULL);
  END IF;

  SELECT array_agg(ur.role::TEXT) INTO user_roles FROM user_roles ur WHERE ur.user_id = _user_id;

  IF user_roles IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'rules_applied', '[]'::jsonb, 'reason', 'No roles assigned');
  END IF;

  FOR rule_record IN
    SELECT dsr.*, r.role_name
    FROM data_scope_rules dsr
    JOIN roles r ON r.id = dsr.role_id
    WHERE dsr.target_table = _table_name AND dsr.is_active = true AND r.role_name = ANY(user_roles)
    ORDER BY dsr.priority ASC
  LOOP
    IF (_action = 'view' AND rule_record.can_view) OR
       (_action = 'edit' AND rule_record.can_edit) OR
       (_action = 'delete' AND rule_record.can_delete) THEN
      rules_applied := rules_applied || jsonb_build_array(jsonb_build_object(
        'type', 'data_scope_rule', 'id', rule_record.id, 'role', rule_record.role_name
      ));
      is_allowed := true;
    END IF;
  END LOOP;

  IF NOT is_allowed THEN denial_reason := 'No matching rules'; END IF;

  RETURN jsonb_build_object('allowed', is_allowed, 'rules_applied', rules_applied, 'reason', denial_reason);
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_sep_eligibility(p_ssn character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_ip_exists boolean;
    v_self_ref_no varchar(6);
    v_ip_status text;
    v_ip_name text;
BEGIN
    SELECT EXISTS(SELECT 1 FROM ip_master WHERE ssn = p_ssn) INTO v_ip_exists;
    
    IF NOT v_ip_exists THEN
        RETURN jsonb_build_object('eligible', false, 'reason', 'SSN does not exist in ip_master', 'ip_exists', false, 'sep_exists', false, 'self_ref_no', null, 'ip_status', null, 'ip_name', null);
    END IF;

    SELECT status, COALESCE(firstname || ' ' || COALESCE(surname, ''), firstname) INTO v_ip_status, v_ip_name
    FROM ip_master WHERE ssn = p_ssn;

    SELECT self_ref_no INTO v_self_ref_no FROM ip_self_employ WHERE ssn = p_ssn LIMIT 1;

    IF v_ip_status IN ('S', 'C') THEN
        RETURN jsonb_build_object('eligible', false, 'reason', 'IP status does not allow SEP registration', 'ip_exists', true, 'sep_exists', v_self_ref_no IS NOT NULL, 'self_ref_no', v_self_ref_no, 'ip_status', v_ip_status, 'ip_name', v_ip_name);
    END IF;

    RETURN jsonb_build_object(
        'eligible', v_self_ref_no IS NULL,
        'reason', CASE WHEN v_self_ref_no IS NOT NULL THEN 'Already registered as self-employed' ELSE 'Eligible' END,
        'ip_exists', true, 'sep_exists', v_self_ref_no IS NOT NULL,
        'self_ref_no', v_self_ref_no, 'ip_status', v_ip_status, 'ip_name', v_ip_name
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_vc_eligibility(p_ssn character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ip_record RECORD;
  v_age INTEGER;
  v_config RECORD;
  v_active_employment RECORD;
  v_last_employment_end DATE;
  v_last_self_emp_end DATE;
  v_termination_date DATE;
  v_weeks_since_termination INTEGER;
  v_today DATE := CURRENT_DATE;
  v_errors JSONB := '[]'::JSONB;
  v_is_eligible BOOLEAN := true;
  v_active_vc RECORD;
BEGIN
  SELECT * INTO v_config
  FROM public.tb_vc_eligibility_config
  WHERE is_active = true
    AND effstart <= v_today
    AND (effend IS NULL OR effend >= v_today)
  ORDER BY effstart DESC
  LIMIT 1;
  
  IF v_config IS NULL THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'errors', '[{"code": "NO_CONFIG", "message": "Voluntary contributor configuration not found"}]'::JSONB
    );
  END IF;

  SELECT * INTO v_ip_record
  FROM public.ip_master
  WHERE ssn = p_ssn;
  
  IF v_ip_record IS NULL THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'errors', '[{"code": "SSN_NOT_FOUND", "message": "Insured person not found with the given SSN"}]'::JSONB
    );
  END IF;

  SELECT * INTO v_active_vc
  FROM public.ip_vol_contrib
  WHERE ssn = p_ssn AND date_ceased IS NULL;
  
  IF v_active_vc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'errors', '[{"code": "ALREADY_VC", "message": "This person is already registered as an active voluntary contributor"}]'::JSONB
    );
  END IF;

  -- Check 1: Residency (canonical: place_of_residence)
  IF COALESCE(v_ip_record.place_of_residence, '') <> 'SKN' THEN
    v_is_eligible := false;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code', 'INVALID_RESIDENCY',
      'message', 'Place of residence must be St. Kitts & Nevis (SKN). Current: ' || COALESCE(v_ip_record.place_of_residence, 'Not Set')
    ));
  END IF;

  -- Check 2: Age (canonical: dob)
  v_age := EXTRACT(YEAR FROM AGE(v_today, v_ip_record.dob));
  
  IF v_age IS NULL THEN
    v_is_eligible := false;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code', 'NO_DOB',
      'message', 'Date of birth is required to verify age eligibility'
    ));
  ELSIF v_age < v_config.min_age OR v_age > v_config.max_age THEN
    v_is_eligible := false;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code', 'AGE_OUT_OF_RANGE',
      'message', format('Age must be between %s and %s years. Current age: %s', v_config.min_age, v_config.max_age, v_age)
    ));
  END IF;

  SELECT * INTO v_active_employment
  FROM public.ip_employer
  WHERE ssn = p_ssn 
    AND term_end_date IS NULL
    AND posting_status = 'VAC'
  LIMIT 1;
  
  IF v_active_employment IS NOT NULL THEN
    v_is_eligible := false;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code', 'ACTIVELY_EMPLOYED',
      'message', 'Cannot register as voluntary contributor while actively employed. Current employer: ' || v_active_employment.employer_id
    ));
  END IF;

  IF COALESCE(v_ip_record.asp_num, 'N') = 'Y' THEN
    v_is_eligible := false;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code', 'ASSISTANCE_PENSIONER',
      'message', 'Assistance pensioners are not eligible for voluntary contribution'
    ));
  END IF;

  IF v_active_employment IS NULL THEN
    SELECT MAX(term_end_date) INTO v_last_employment_end
    FROM public.ip_employer
    WHERE ssn = p_ssn 
      AND term_end_date IS NOT NULL
      AND posting_status = 'VAC';
    
    SELECT MAX(effective_end_date::DATE) INTO v_last_self_emp_end
    FROM public.ip_self_category
    WHERE ssn = p_ssn 
      AND effective_end_date IS NOT NULL;
    
    v_termination_date := GREATEST(COALESCE(v_last_employment_end, '1900-01-01'::DATE), COALESCE(v_last_self_emp_end, '1900-01-01'::DATE));
    
    IF v_termination_date > '1900-01-01'::DATE THEN
      v_weeks_since_termination := FLOOR((v_today - v_termination_date)::INTEGER / 7)::INTEGER;
      
      IF v_weeks_since_termination > v_config.termination_grace_weeks THEN
        v_is_eligible := false;
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'code', 'GRACE_PERIOD_EXPIRED',
          'message', format('Registration must occur within %s weeks of employment termination. Last termination: %s (%s weeks ago)', 
            v_config.termination_grace_weeks, v_termination_date::TEXT, v_weeks_since_termination)
        ));
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'eligible', v_is_eligible,
    'errors', v_errors,
    'ip_details', jsonb_build_object(
      'ssn', p_ssn,
      'name', v_ip_record.surname || ', ' || v_ip_record.firstname,
      'dob', v_ip_record.dob,
      'age', v_age,
      'place_of_residence', v_ip_record.place_of_residence,
      'vol_contrib', v_ip_record.vol_contrib
    ),
    'config', jsonb_build_object(
      'min_age', v_config.min_age,
      'max_age', v_config.max_age,
      'contrib_pct', v_config.vc_contrib_pct,
      'termination_grace_weeks', v_config.termination_grace_weeks,
      'wage_history_months', v_config.wage_history_months
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_vc_residency_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_residence text;
  v_new_residence text;
  v_has_active_vc boolean;
BEGIN
  v_old_residence := COALESCE(OLD.place_of_residence, '');
  v_new_residence := COALESCE(NEW.place_of_residence, '');

  IF v_old_residence IS DISTINCT FROM v_new_residence THEN
    IF v_new_residence NOT IN ('SKN') THEN
      SELECT EXISTS (
        SELECT 1 FROM ip_vol_contrib
        WHERE ssn = NEW.ssn AND date_ceased IS NULL
      ) INTO v_has_active_vc;

      IF v_has_active_vc THEN
        UPDATE ip_vol_contrib
        SET date_ceased = CURRENT_DATE
        WHERE ssn = NEW.ssn AND date_ceased IS NULL;

        UPDATE ip_master
        SET vol_contrib = 'N'
        WHERE ssn = NEW.ssn;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_workflow_task_access(_user_id uuid, _workflow_instance_id uuid, _action text DEFAULT 'view'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_workflow workflow_instances;
  v_definition workflow_definitions;
  v_user_profile profiles;
  v_is_admin boolean := false;
  v_row_access jsonb;
  v_field_rules jsonb;
  v_result jsonb;
  v_has_task_assignment boolean := false;
  v_secured_table text;
  v_secured_module_id uuid;
BEGIN
  -- Get user profile
  SELECT * INTO v_user_profile FROM profiles WHERE id = _user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'User not found');
  END IF;
  
  -- Check if user is admin using the existing function
  v_is_admin := is_admin(_user_id);
  
  -- Admin bypasses all checks
  IF v_is_admin THEN
    RETURN jsonb_build_object(
      'allowed', true, 
      'reason', 'Admin access',
      'is_admin', true,
      'visible_fields', '[]'::jsonb,
      'editable_fields', '[]'::jsonb,
      'available_actions', '["approve","reject","query","send_back"]'::jsonb
    );
  END IF;
  
  -- Get workflow instance
  SELECT * INTO v_workflow FROM workflow_instances WHERE id = _workflow_instance_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Workflow instance not found');
  END IF;
  
  -- Get workflow definition
  SELECT * INTO v_definition FROM workflow_definitions WHERE id = v_workflow.workflow_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Workflow definition not found');
  END IF;
  
  v_secured_table := v_definition.secured_table;
  v_secured_module_id := v_definition.secured_module_id;
  
  -- Check if user has task assignment (by role, designation, or direct assignment)
  SELECT EXISTS (
    SELECT 1 FROM workflow_tasks wt
    WHERE wt.instance_id = _workflow_instance_id
    AND wt.status IN ('Pending', 'InProgress')
    AND (
      wt.assigned_user_id = _user_id
      OR wt.assigned_role_id IN (SELECT role_id FROM user_roles WHERE user_id = _user_id)
      OR wt.assigned_designation_id = v_user_profile.designation_id
    )
  ) INTO v_has_task_assignment;
  
  IF NOT v_has_task_assignment THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'No task assignment for this user');
  END IF;
  
  -- If no secured table is defined, allow access with no field restrictions
  IF v_secured_table IS NULL OR v_secured_table = '' THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'reason', 'No security binding defined',
      'visible_fields', '[]'::jsonb,
      'editable_fields', '[]'::jsonb,
      'available_actions', '["approve","reject","query","send_back"]'::jsonb
    );
  END IF;
  
  -- Check row-level access via data_scope_rules
  v_row_access := check_row_access(_user_id, '', v_secured_table, _action);
  
  IF NOT COALESCE((v_row_access->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', COALESCE(v_row_access->>'reason', 'Row access denied'),
      'scope_rules_applied', v_row_access->'rules_applied'
    );
  END IF;
  
  -- Get field visibility rules
  v_field_rules := get_visible_fields(_user_id, '', v_secured_table);
  
  -- Build available actions based on action permissions
  v_result := jsonb_build_object(
    'allowed', true,
    'reason', 'Access granted via data policies',
    'workflow_instance_id', _workflow_instance_id,
    'secured_table', v_secured_table,
    'visible_fields', v_field_rules,
    'editable_fields', (
      SELECT COALESCE(jsonb_agg(f), '[]'::jsonb)
      FROM jsonb_array_elements(v_field_rules) f
      WHERE (f->>'can_edit')::boolean = true
    ),
    'scope_rules_applied', v_row_access->'rules_applied',
    'available_actions', CASE 
      WHEN COALESCE((v_row_access->>'can_edit')::boolean, false) THEN '["approve","reject","query","send_back"]'::jsonb
      ELSE '["view"]'::jsonb
    END
  );
  
  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.chk_comm_hub_control_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.email_live_enabled = true
     AND (NEW.allowed_email_addresses IS NULL OR array_length(NEW.allowed_email_addresses, 1) IS NULL)
     AND (NEW.allowed_email_domains IS NULL OR array_length(NEW.allowed_email_domains, 1) IS NULL)
  THEN
    RAISE EXCEPTION 'email_live_enabled requires at least one allowed_email_addresses or allowed_email_domains entry';
  END IF;

  -- Auto-set live_eligible_after when email_live_enabled transitions false -> true
  -- and caller has not explicitly provided a new value.
  IF TG_OP = 'UPDATE'
     AND OLD.email_live_enabled IS DISTINCT FROM NEW.email_live_enabled
     AND NEW.email_live_enabled = true
     AND NEW.live_eligible_after IS NULL
  THEN
    NEW.live_eligible_after := now();
  END IF;

  -- Never auto-clear live_eligible_after on true -> false; keep for audit history.
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.chub_mer_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.cl_payout_req_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_comm_hub_message_by_id(p_message_id uuid, p_worker_id text, p_include_live boolean, p_live_eligible_after timestamp with time zone DEFAULT NULL::timestamp with time zone, p_live_max_age_minutes integer DEFAULT 30)
 RETURNS SETOF communication_message
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_message;
  v_max_age int := COALESCE(p_live_max_age_minutes, 30);
BEGIN
  IF p_message_id IS NULL OR p_worker_id IS NULL OR length(p_worker_id) = 0 THEN
    RETURN;
  END IF;

  SELECT *
    INTO v_row
    FROM public.communication_message
   WHERE id = p_message_id
     AND origin = 'comm_hub'
     AND channel = 'email'
     AND status = 'queued'
     AND targeted_dispatch_only = false
     AND (send_context IS DISTINCT FROM 'controlled_live')
     AND controlled_live_execution_id IS NULL
     AND (next_attempt_at IS NULL OR next_attempt_at <= now())
     AND (locked_at IS NULL OR locked_at < now() - interval '10 minutes')
   FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_row.test_mode = false THEN
    IF NOT p_include_live THEN RETURN; END IF;
    IF p_live_eligible_after IS NULL THEN RETURN; END IF;
    IF v_row.created_at < p_live_eligible_after THEN RETURN; END IF;
    IF v_row.created_at < now() - make_interval(mins => v_max_age) THEN RETURN; END IF;
  END IF;

  UPDATE public.communication_message
     SET status = 'sending',
         attempt_count = attempt_count + 1,
         locked_at = now(),
         locked_by = p_worker_id,
         last_attempt_at = now(),
         updated_at = now()
   WHERE id = v_row.id
  RETURNING * INTO v_row;

  RETURN NEXT v_row;
  RETURN;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_comm_hub_messages(p_batch_size integer, p_worker_id text, p_include_live boolean, p_live_eligible_after timestamp with time zone DEFAULT NULL::timestamp with time zone, p_live_max_age_minutes integer DEFAULT 30)
 RETURNS SETOF communication_message
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch int := GREATEST(1, LEAST(COALESCE(p_batch_size, 25), 200));
  v_max_age int := GREATEST(1, LEAST(COALESCE(p_live_max_age_minutes, 30), 1440));
  v_live_ok boolean := p_include_live IS TRUE AND p_live_eligible_after IS NOT NULL;
BEGIN
  RETURN QUERY
  WITH cte AS (
    SELECT id
    FROM public.communication_message
    WHERE origin = 'comm_hub'
      AND channel = 'email'
      AND status = 'queued'
      AND targeted_dispatch_only = false
      AND (send_context IS DISTINCT FROM 'controlled_live')
      AND controlled_live_execution_id IS NULL
      AND (next_attempt_at IS NULL OR next_attempt_at <= now())
      AND (locked_at IS NULL OR locked_at < now() - interval '10 minutes')
      AND (
        test_mode IS TRUE
        OR (
          v_live_ok
          AND test_mode IS FALSE
          AND created_at >= p_live_eligible_after
          AND created_at >= now() - make_interval(mins => v_max_age)
        )
      )
    ORDER BY created_at
    LIMIT v_batch
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.communication_message m
  SET status = 'sending',
      locked_at = now(),
      locked_by = p_worker_id,
      attempt_count = m.attempt_count + 1,
      last_attempt_at = now(),
      updated_at = now()
  FROM cte
  WHERE m.id = cte.id
  RETURNING m.*;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_comm_hub_targeted_message(p_message_id uuid, p_execution_id uuid, p_grant_id uuid, p_action text, p_worker_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_message;
  v_existing_attempt uuid;
BEGIN
  IF p_message_id IS NULL OR p_execution_id IS NULL OR p_grant_id IS NULL
     OR p_action IS NULL OR p_worker_id IS NULL OR length(p_worker_id) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'input_invalid', 'message', 'all parameters are required');
  END IF;

  SELECT * INTO v_row
    FROM public.communication_message
   WHERE id = p_message_id
   FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_message_locked',
      'message', 'message row is either missing or locked');
  END IF;

  IF v_row.targeted_dispatch_only IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_dispatch_flag_missing');
  END IF;
  IF v_row.controlled_action IS DISTINCT FROM p_action THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_action_mismatch',
      'expected', p_action, 'actual', v_row.controlled_action);
  END IF;
  IF v_row.controlled_live_execution_id IS DISTINCT FROM p_execution_id THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_execution_mismatch');
  END IF;
  IF v_row.controlled_live_grant_id IS DISTINCT FROM p_grant_id THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_grant_mismatch');
  END IF;
  IF v_row.send_context IS DISTINCT FROM 'controlled_live' THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_context_mismatch');
  END IF;
  IF v_row.origin IS DISTINCT FROM 'comm_hub' OR v_row.channel IS DISTINCT FROM 'email' THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_context_mismatch');
  END IF;
  IF v_row.status <> 'queued' THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_message_not_queued',
      'status', v_row.status);
  END IF;
  IF v_row.locked_at IS NOT NULL AND v_row.locked_at > now() - interval '10 minutes' THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_claim_conflict',
      'locked_by', v_row.locked_by, 'locked_at', v_row.locked_at);
  END IF;

  SELECT id INTO v_existing_attempt
    FROM public.communication_delivery_attempt
   WHERE message_id = v_row.id
     AND attempt_type = 'controlled_live'
     AND provider_call_attempted = true
   LIMIT 1;
  IF v_existing_attempt IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'claimed', false,
      'code', 'targeted_attempt_already_exists',
      'delivery_attempt_id', v_existing_attempt);
  END IF;

  PERFORM set_config('comm_hub.allow_targeted_update', 'true', true);

  UPDATE public.communication_message
     SET status = 'sending',
         attempt_count = attempt_count + 1,
         locked_at = now(),
         locked_by = p_worker_id,
         last_attempt_at = now(),
         updated_at = now()
   WHERE id = v_row.id
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'ok', true, 'claimed', true, 'code', 'claimed',
    'message_id', v_row.id, 'request_id', v_row.request_id,
    'execution_id', v_row.controlled_live_execution_id,
    'grant_id', v_row.controlled_live_grant_id,
    'action', v_row.controlled_action,
    'status', v_row.status,
    'locked_at', v_row.locked_at,
    'locked_by', v_row.locked_by,
    'attempt_count', v_row.attempt_count,
    'preview_snapshot_id', v_row.preview_snapshot_id,
    'preview_approval_id', v_row.preview_approval_id,
    'dry_run_certification_id', v_row.dry_run_certification_id,
    'governance_certification_id', v_row.governance_certification_id,
    'certified_dependency_hash', v_row.certified_dependency_hash,
    'recipient_id', v_row.recipient_id,
    'template_version_id', v_row.template_version_id,
    'sender_profile_id', v_row.sender_profile_id,
    'from_email', v_row.from_email,
    'from_display_name', v_row.from_display_name,
    'reply_to_email', v_row.reply_to_email,
    'recipient_set_hash', v_row.recipient_set_hash,
    'subject_hash', v_row.subject_hash,
    'body_hash', v_row.body_hash,
    'content_hash', v_row.content_hash,
    'send_context', v_row.send_context,
    'origin', v_row.origin,
    'channel', v_row.channel,
    'test_mode', v_row.test_mode
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.cleanup_expired_auth_exchange_codes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM public.auth_exchange_codes
  WHERE expires_at < now() - interval '1 hour'
     OR (consumed_at IS NOT NULL AND consumed_at < now() - interval '1 hour');
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.clear_comm_hub_message_lock(p_message_id uuid, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_msg communication_message%ROWTYPE;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN RAISE EXCEPTION 'actor_user_id required'; END IF;
  IF NOT public.has_role(p_actor_user_id, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden: admin required';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'reason required'; END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id = p_message_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'message not found: %', p_message_id; END IF;
  IF COALESCE(v_msg.origin, '') <> 'comm_hub' THEN
    RAISE EXCEPTION 'refusing: message origin=% (comm_hub only)', v_msg.origin;
  END IF;
  IF v_msg.status <> 'sending' THEN
    RAISE EXCEPTION 'refusing: status=% (only sending eligible for stale-lock clear)', v_msg.status;
  END IF;
  IF v_msg.locked_at IS NULL OR v_msg.locked_at > now() - INTERVAL '10 minutes' THEN
    RAISE EXCEPTION 'refusing: lock not stale (>10 minutes required)';
  END IF;

  v_old := jsonb_build_object('status', v_msg.status, 'locked_at', v_msg.locked_at, 'locked_by', v_msg.locked_by);

  UPDATE public.communication_message
     SET status='queued',
         locked_at=NULL,
         locked_by=NULL,
         next_attempt_at=now(),
         updated_at=now()
   WHERE id = p_message_id;

  v_new := jsonb_build_object('status','queued','next_attempt_at',now(),'cleared_by',p_actor_user_id);

  INSERT INTO public.communication_event_log
    (message_id, request_id, event_type, source, payload, actor_user_id)
  VALUES
    (v_msg.id, v_msg.request_id, 'queued', 'clear_comm_hub_message_lock',
     jsonb_build_object(
       'stage','STALE_LOCK_CLEARED_BY_ADMIN',
       'logical_event_type','lock_cleared',
       'reason',p_reason,
       'actor',p_actor_user_id,
       'previous_locked_at',v_msg.locked_at,
       'previous_locked_by',v_msg.locked_by
     ),
     p_actor_user_id);

  INSERT INTO public.communication_hub_control_audit
    (setting_key, old_value, new_value, reason, changed_by, source)
  VALUES
    ('message_lock_cleared:' || p_message_id::text, v_old, v_new, p_reason, p_actor_user_id, 'clear_comm_hub_message_lock');

  RETURN jsonb_build_object('ok', true, 'message_id', p_message_id, 'new_status', 'queued');
END;
$function$;
CREATE OR REPLACE FUNCTION public.clone_c3_config(p_source_period_id uuid, p_new_start_date date, p_new_end_date date DEFAULT NULL::date, p_description text DEFAULT NULL::text, p_user_code character varying DEFAULT NULL::character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_period_id UUID;
  v_old_values JSONB;
BEGIN
  -- Get source config values for audit
  SELECT jsonb_build_object(
    'start_date', cp.start_date,
    'end_date', cp.end_date,
    'config', row_to_json(cd)
  ) INTO v_old_values
  FROM public.c3_config_periods cp
  JOIN public.c3_config_details cd ON cd.config_period_id = cp.id
  WHERE cp.id = p_source_period_id;
  
  IF v_old_values IS NULL THEN
    RAISE EXCEPTION 'Source configuration not found';
  END IF;
  
  -- Create new period
  INSERT INTO public.c3_config_periods (start_date, end_date, description, is_active, created_by)
  VALUES (p_new_start_date, p_new_end_date, COALESCE(p_description, 'Cloned from existing configuration'), true, p_user_code)
  RETURNING id INTO v_new_period_id;
  
  -- Clone details (including employer_eib_max_wage)
  INSERT INTO public.c3_config_details (
    config_period_id, min_age_ss, max_age_ss, min_age_levy, max_age_levy,
    bonus_exempt_from_levy, bonus_levy_rate,
    employee_ss_rate, employee_ss_max_wage,
    employer_ss_rate, employer_eib_rate, employer_eib_max_wage, employer_ss_max_wage,
    employer_levy_rate, employer_severance_rate,
    submission_due_day,
    levy_penalty_initial_rate, levy_penalty_subsequent_rate,
    severance_penalty_initial_rate, severance_penalty_subsequent_rate,
    ss_fine_initial_rate, ss_fine_subsequent_rate,
    interest_rate_ss_principal, interest_rate_levy_principal,
    interest_rate_severance_principal, interest_rate_penalties, interest_rate_fines,
    levy_slab_id, created_by
  )
  SELECT 
    v_new_period_id, min_age_ss, max_age_ss, min_age_levy, max_age_levy,
    bonus_exempt_from_levy, bonus_levy_rate,
    employee_ss_rate, employee_ss_max_wage,
    employer_ss_rate, employer_eib_rate, employer_eib_max_wage, employer_ss_max_wage,
    employer_levy_rate, employer_severance_rate,
    submission_due_day,
    levy_penalty_initial_rate, levy_penalty_subsequent_rate,
    severance_penalty_initial_rate, severance_penalty_subsequent_rate,
    ss_fine_initial_rate, ss_fine_subsequent_rate,
    interest_rate_ss_principal, interest_rate_levy_principal,
    interest_rate_severance_principal, interest_rate_penalties, interest_rate_fines,
    levy_slab_id, p_user_code
  FROM public.c3_config_details
  WHERE config_period_id = p_source_period_id;
  
  -- Log audit
  INSERT INTO public.c3_config_audit (config_period_id, action, old_values, new_values, changed_by, reason)
  VALUES (v_new_period_id, 'CLONE', v_old_values, 
    jsonb_build_object('source_id', p_source_period_id, 'new_start_date', p_new_start_date, 'new_end_date', p_new_end_date),
    p_user_code, 'Configuration cloned from period ' || p_source_period_id::text);
  
  RETURN v_new_period_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.clone_role(source_role_id uuid, new_role_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_role_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.has_role(auth.uid(), 'Admin'::app_role) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF new_role_name IS NULL OR btrim(new_role_name) = '' THEN
    RAISE EXCEPTION 'Role name is required';
  END IF;

  IF EXISTS (SELECT 1 FROM public.roles WHERE role_name = new_role_name) THEN
    RAISE EXCEPTION 'Role name already exists';
  END IF;

  INSERT INTO public.roles (role_name, description, is_active, is_system_role, mfa_required)
  SELECT new_role_name,
         'Cloned from ' || r.role_name,
         true,
         false,
         COALESCE(r.mfa_required, false)
  FROM public.roles r
  WHERE r.id = source_role_id
  RETURNING id INTO new_role_id;

  IF new_role_id IS NULL THEN
    RAISE EXCEPTION 'Source role not found';
  END IF;

  INSERT INTO public.role_permissions (role_id, module_id, action_id, is_granted)
  SELECT new_role_id, rp.module_id, rp.action_id, rp.is_granted
  FROM public.role_permissions rp
  WHERE rp.role_id = source_role_id;

  RETURN new_role_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.clone_workflow(p_source_workflow_id uuid, p_new_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_workflow_id UUID;
  v_source_workflow RECORD;
  v_step RECORD;
  v_action RECORD;
  v_new_step_id UUID;
  v_new_action_id UUID;
  v_step_id_map JSONB := '{}'::JSONB;
  v_user_id UUID;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  
  -- Fetch source workflow
  SELECT * INTO v_source_workflow
  FROM public.workflow_definitions
  WHERE id = p_source_workflow_id;
  
  IF v_source_workflow IS NULL THEN
    RAISE EXCEPTION 'Source workflow not found';
  END IF;
  
  -- Create new workflow definition
  INSERT INTO public.workflow_definitions (
    name,
    description,
    process_type,
    default_sla_hours,
    is_active,
    version,
    created_by,
    secured_module_id,
    secured_table
  ) VALUES (
    COALESCE(p_new_name, v_source_workflow.name || ' (Copy)'),
    v_source_workflow.description,
    v_source_workflow.process_type,
    v_source_workflow.default_sla_hours,
    false, -- Always create as inactive
    1,
    v_user_id,
    v_source_workflow.secured_module_id,
    v_source_workflow.secured_table
  )
  RETURNING id INTO v_new_workflow_id;
  
  -- Clone workflow steps and build ID mapping
  FOR v_step IN 
    SELECT * FROM public.workflow_steps 
    WHERE workflow_id = p_source_workflow_id
    ORDER BY step_number
  LOOP
    INSERT INTO public.workflow_steps (
      workflow_id,
      step_number,
      step_name,
      description,
      assigned_role,
      assigned_designation,
      action_type,
      sla_hours,
      is_final_step,
      approver_type,
      approver_role_ids,
      approver_designation_ids,
      approver_user_ids,
      parallel_approval,
      required_approvals,
      auto_approve_on_timeout,
      has_condition,
      condition_expression,
      escalation_enabled,
      escalation_notification_type,
      escalation_module_id,
      escalation_template_id
    ) VALUES (
      v_new_workflow_id,
      v_step.step_number,
      v_step.step_name,
      v_step.description,
      v_step.assigned_role,
      v_step.assigned_designation,
      v_step.action_type,
      v_step.sla_hours,
      v_step.is_final_step,
      v_step.approver_type,
      v_step.approver_role_ids,
      v_step.approver_designation_ids,
      v_step.approver_user_ids,
      v_step.parallel_approval,
      v_step.required_approvals,
      v_step.auto_approve_on_timeout,
      v_step.has_condition,
      v_step.condition_expression,
      v_step.escalation_enabled,
      v_step.escalation_notification_type,
      v_step.escalation_module_id,
      v_step.escalation_template_id
    )
    RETURNING id INTO v_new_step_id;
    
    -- Store mapping of old step ID to new step ID
    v_step_id_map := v_step_id_map || jsonb_build_object(v_step.id::text, v_new_step_id::text);
  END LOOP;
  
  -- Clone step actions with updated step references
  FOR v_step IN 
    SELECT * FROM public.workflow_steps 
    WHERE workflow_id = p_source_workflow_id
  LOOP
    FOR v_action IN 
      SELECT * FROM public.workflow_step_actions 
      WHERE step_id = v_step.id
      ORDER BY display_order
    LOOP
      INSERT INTO public.workflow_step_actions (
        step_id,
        action_name,
        action_type,
        next_step_type,
        next_step_id,
        end_state,
        is_final_action,
        display_order,
        notification_type,
        notification_module_id,
        notification_template_id
      ) VALUES (
        (v_step_id_map->>(v_step.id::text))::UUID,
        v_action.action_name,
        v_action.action_type,
        v_action.next_step_type,
        -- Map next_step_id to new step if it exists in the map
        CASE 
          WHEN v_action.next_step_id IS NOT NULL AND v_step_id_map ? (v_action.next_step_id::text)
          THEN (v_step_id_map->>(v_action.next_step_id::text))::UUID
          ELSE NULL
        END,
        v_action.end_state,
        v_action.is_final_action,
        v_action.display_order,
        v_action.notification_type,
        v_action.notification_module_id,
        v_action.notification_template_id
      )
      RETURNING id INTO v_new_action_id;
      
      -- Clone action notifications
      INSERT INTO public.workflow_action_notifications (
        action_id,
        notification_type,
        template_id
      )
      SELECT 
        v_new_action_id,
        notification_type,
        template_id
      FROM public.workflow_action_notifications
      WHERE action_id = v_action.id;
      
      -- Clone action field updates
      INSERT INTO public.workflow_action_field_updates (
        action_id,
        field_name,
        field_value,
        display_order,
        created_by
      )
      SELECT 
        v_new_action_id,
        field_name,
        field_value,
        display_order,
        v_user_id
      FROM public.workflow_action_field_updates
      WHERE action_id = v_action.id;
    END LOOP;
  END LOOP;
  
  RETURN v_new_workflow_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.close_batch(p_batch_number text, p_user_code text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch RECORD;
  v_physical_csh NUMERIC := 0;
  v_physical_chq NUMERIC := 0;
  v_physical_crd NUMERIC := 0;
  v_physical_drd NUMERIC := 0;
  v_unverified_count INTEGER := 0;
  v_system RECORD;
  v_sys_csh NUMERIC := 0;
  v_result JSON;
BEGIN
  SELECT * INTO v_batch FROM cn_batch WHERE batch_number = p_batch_number;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Batch % not found', p_batch_number;
  END IF;
  IF v_batch.batch_status != 'O' THEN
    RAISE EXCEPTION 'Batch % is not open (status: %)', p_batch_number, v_batch.batch_status;
  END IF;

  -- Physical CSH
  SELECT COALESCE(SUM(
    cc.count * cd.denomination_value *
    CASE WHEN cur.is_main_currency THEN 1 ELSE COALESCE(cur.exchange_rate, 1) END
  ), 0) INTO v_physical_csh
  FROM cn_cash_count cc
  JOIN cashier_currency_denominations cd ON cd.id = cc.denomination_id
  JOIN tb_currencies cur ON cur.id = cc.currency_id
  WHERE cc.batch_number = p_batch_number;

  -- Physical CHQ from verified cheques only (cn_payment is single source of truth)
  SELECT COALESCE(SUM(
    COALESCE(v.override_amount, sub.amount) *
    CASE WHEN cur.is_main_currency THEN 1 ELSE COALESCE(cur.exchange_rate, 1) END
  ), 0) INTO v_physical_chq
  FROM (
    SELECT
      p.payment_sequence_no::TEXT AS source_record_id,
      'cn_payment' AS source_table,
      COALESCE(p.payment_amount, 0) AS amount,
      p.currency_code
    FROM cn_payment p
    JOIN cn_payment_header h ON h.payment_id = p.payment_id
    JOIN cn_receipt r ON r.payment_id = h.payment_id AND r.status != 'C'
    WHERE h.batch_number = p_batch_number
      AND p.mop_code = 'CHQ'
      AND COALESCE(h.status, 'active') != 'cancelled'
  ) sub
  JOIN cn_batch_cheque_verification v
    ON v.batch_number = p_batch_number
    AND v.source_table = sub.source_table
    AND v.source_record_id = sub.source_record_id
    AND v.is_verified = true
  JOIN tb_currencies cur ON cur.currency_code = COALESCE(sub.currency_code, 'XCD') AND cur.is_active = true;

  -- Count unverified cheques (cn_payment is single source of truth)
  SELECT COUNT(*) INTO v_unverified_count
  FROM (
    SELECT
      p.payment_sequence_no::TEXT AS source_record_id,
      'cn_payment' AS source_table
    FROM cn_payment p
    JOIN cn_payment_header h ON h.payment_id = p.payment_id
    JOIN cn_receipt r ON r.payment_id = h.payment_id AND r.status != 'C'
    WHERE h.batch_number = p_batch_number
      AND p.mop_code = 'CHQ'
      AND COALESCE(h.status, 'active') != 'cancelled'
  ) all_chq
  WHERE NOT EXISTS (
    SELECT 1 FROM cn_batch_cheque_verification v
    WHERE v.batch_number = p_batch_number
      AND v.source_table = all_chq.source_table
      AND v.source_record_id = all_chq.source_record_id
      AND v.is_verified = true
  );

  -- Physical CRD / DRD — now derived from cn_payment (auto-reconciled)
  SELECT
    COALESCE(SUM(CASE WHEN p.mop_code = 'CRD' THEN p.payment_amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN p.mop_code = 'DRD' THEN p.payment_amount ELSE 0 END), 0)
  INTO v_physical_crd, v_physical_drd
  FROM cn_payment p
  JOIN cn_payment_header h ON h.payment_id = p.payment_id
  JOIN cn_receipt r ON r.payment_id = h.payment_id AND r.status != 'C'
  WHERE h.batch_number = p_batch_number
    AND p.mop_code IN ('CRD', 'DRD')
    AND COALESCE(h.status, 'active') != 'cancelled';

  -- System totals verification (only active-receipt-backed transactions from cn_payment)
  FOR v_system IN
    SELECT p.mop_code, COALESCE(SUM(p.payment_amount), 0) AS total
    FROM cn_payment p
    JOIN cn_payment_header h ON h.payment_id = p.payment_id
    JOIN cn_receipt r ON r.payment_id = h.payment_id AND r.status != 'C'
    WHERE h.batch_number = p_batch_number
      AND COALESCE(h.status, 'active') != 'cancelled'
    GROUP BY p.mop_code
  LOOP
    IF v_system.mop_code = 'CSH' THEN
      v_sys_csh := v_system.total + COALESCE(v_batch.offset_amount, 0);
      IF ROUND(v_physical_csh * 100) != ROUND(v_sys_csh * 100) THEN
        RAISE EXCEPTION 'CSH mismatch: Physical % vs System %', v_physical_csh, v_sys_csh;
      END IF;
    END IF;
    IF v_system.mop_code = 'CHQ' AND ROUND(v_physical_chq * 100) != ROUND(v_system.total * 100) THEN
      RAISE EXCEPTION 'CHQ mismatch: Physical % vs System %. Unverified cheques: %', v_physical_chq, v_system.total, v_unverified_count;
    END IF;
    -- CRD and DRD are auto-reconciled (physical = system), no mismatch possible
  END LOOP;

  -- Handle case where no CSH payments exist but there is an opening balance
  IF v_sys_csh = 0 AND COALESCE(v_batch.offset_amount, 0) != 0 THEN
    v_sys_csh := COALESCE(v_batch.offset_amount, 0);
    IF ROUND(v_physical_csh * 100) != ROUND(v_sys_csh * 100) THEN
      RAISE EXCEPTION 'CSH mismatch: Physical % vs System %', v_physical_csh, v_sys_csh;
    END IF;
  END IF;

  UPDATE cn_batch SET
    batch_status = 'P',
    posted_by = p_user_code,
    date_posted = now()
  WHERE batch_number = p_batch_number;

  v_result := json_build_object(
    'success', true,
    'batch_number', p_batch_number,
    'physical_csh', v_physical_csh,
    'physical_chq', v_physical_chq,
    'physical_crd', v_physical_crd,
    'physical_drd', v_physical_drd,
    'unverified_cheque_count', v_unverified_count
  );

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.close_comm_hub_live_window(p_reason text, p_emergency boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_src text;
BEGIN
  IF v_uid IS NULL OR NOT public.has_role(v_uid, 'Admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN RAISE EXCEPTION 'reason is required'; END IF;
  SELECT * INTO v_settings FROM public.communication_hub_control_settings ORDER BY created_at ASC LIMIT 1;
  IF v_settings.id IS NULL THEN RAISE EXCEPTION 'control settings row missing'; END IF;
  v_src := CASE WHEN p_emergency THEN 'close_comm_hub_live_window:emergency' ELSE 'close_comm_hub_live_window' END;
  INSERT INTO public.communication_hub_control_audit
    (setting_key, old_value, new_value, reason, changed_by, source)
  VALUES
    ('dry_run_only', to_jsonb(v_settings.dry_run_only), to_jsonb(true),
      CASE WHEN p_emergency THEN 'EMERGENCY close: ' ELSE 'live-window RPC close: ' END || p_reason, v_uid, v_src),
    ('email_live_enabled', to_jsonb(v_settings.email_live_enabled), to_jsonb(false),
      CASE WHEN p_emergency THEN 'EMERGENCY close' ELSE 'live-window RPC close' END, v_uid, v_src);
  UPDATE public.communication_hub_control_settings
     SET dry_run_only = true, email_live_enabled = false, dispatch_enabled = true, updated_by = v_uid
   WHERE id = v_settings.id;
  RETURN jsonb_build_object('ok', true, 'closed_at', now(), 'emergency', p_emergency);
END;
$function$;
CREATE OR REPLACE FUNCTION public.close_comm_hub_one_real_email_gate_after_stage6(p_module_code text, p_event_code text, p_channel text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ec record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF p_reason IS NULL OR length(trim(p_reason))<6 THEN RAISE EXCEPTION 'reason_required' USING ERRCODE='22023'; END IF;

  -- Require Stage 6 complete: event certification exists and is live_manual_only or live_cron_allowed
  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=coalesce(p_channel,'email');
  IF NOT FOUND OR v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    RAISE EXCEPTION 'stage_6_not_complete' USING ERRCODE='22023';
  END IF;

  UPDATE public.communication_hub_real_email_gate
     SET enabled=false, closed_by=v_uid, closed_at=now(),
         reason='STAGE_6_COMPLETE: '||p_reason, updated_at=now()
   WHERE lower(trim(module_code))=lower(trim(p_module_code))
     AND lower(trim(event_code))=lower(trim(p_event_code))
     AND lower(trim(channel))=lower(trim(coalesce(p_channel,'email')));

  UPDATE public.communication_hub_event_certification
     SET real_email_gate_closed_at=now(),
         real_email_gate_closed_by=v_uid,
         real_email_gate_closed_reason=p_reason
   WHERE id = v_ec.id;

  RETURN jsonb_build_object('ok',true,'gate_closed',true);
END $function$;
CREATE OR REPLACE FUNCTION public.comm_asset_where_used(p_asset_id uuid)
 RETURNS TABLE(scope text, ref_id uuid, ref_code text, ref_name text, detail text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 'DEPARTMENT'::text,
         dp.id,
         dp.department_code,
         dp.department_name,
         CASE
           WHEN dp.default_logo_asset_id          = p_asset_id THEN 'default_logo'
           WHEN dp.default_small_logo_asset_id    = p_asset_id THEN 'default_small_logo'
           WHEN dp.default_header_asset_id        = p_asset_id THEN 'default_header'
           WHEN dp.default_footer_asset_id        = p_asset_id THEN 'default_footer'
           WHEN dp.default_email_header_asset_id  = p_asset_id THEN 'default_email_header'
           WHEN dp.default_email_footer_asset_id  = p_asset_id THEN 'default_email_footer'
           WHEN dp.default_watermark_asset_id     = p_asset_id THEN 'default_watermark'
           WHEN dp.default_seal_asset_id          = p_asset_id THEN 'default_seal'
           WHEN dp.default_stamp_asset_id         = p_asset_id THEN 'default_stamp'
           WHEN dp.default_signature_asset_id     = p_asset_id THEN 'default_signature'
           WHEN dp.default_qr_asset_id            = p_asset_id THEN 'default_qr'
           WHEN dp.default_letterhead_id          = p_asset_id THEN 'default_letterhead'
         END
  FROM public.core_department_profile dp
  WHERE p_asset_id IN (
    dp.default_logo_asset_id, dp.default_small_logo_asset_id, dp.default_header_asset_id,
    dp.default_footer_asset_id, dp.default_email_header_asset_id, dp.default_email_footer_asset_id,
    dp.default_watermark_asset_id, dp.default_seal_asset_id, dp.default_stamp_asset_id,
    dp.default_signature_asset_id, dp.default_qr_asset_id, dp.default_letterhead_id
  )
  UNION ALL
  SELECT 'OVERRIDE'::text, m.id,
         m.communication_type,
         COALESCE(m.communication_type, m.module_code, m.department_code, 'global'),
         m.category::text || COALESCE(' · ' || m.communication_type, '')
  FROM public.comm_asset_mapping m
  WHERE m.asset_id = p_asset_id AND m.is_active
  UNION ALL
  SELECT 'GENERATED'::text, g.id, g.reference_no, g.doc_type_code,
         g.generated_at::text
  FROM public.core_generated_document g
  WHERE (to_jsonb(g.*) ->> 'resolved_tokens') ILIKE '%' || p_asset_id::text || '%'
  ORDER BY 1
  LIMIT 500;
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_backfill_governance_assessment()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_is_admin boolean := false;
  v_now timestamptz := now(); v_correlation uuid := gen_random_uuid();
  v_total int := 0; v_inserted int := 0; v_skipped int := 0;
  v_by_class jsonb := '{}'::jsonb; v_by_purpose jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NOT NULL THEN
    BEGIN v_is_admin := public.is_comm_hub_operator_admin(v_uid);
    EXCEPTION WHEN OTHERS THEN
      SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=v_uid AND role='Admin') INTO v_is_admin;
    END;
    IF NOT v_is_admin THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='not_authorised'; END IF;
  END IF;
  WITH src AS (
    SELECT ctv.id AS version_id, COALESCE(ctv.version_no::text,'1') AS version_no,
           upper(ctv.status) AS pub_status,
           COALESCE(public.comm_hub_classify_template_purpose(ct.id), 'UNCLASSIFIED') AS purpose,
           EXISTS (SELECT 1 FROM public.communication_hub_event_template_map m
                    WHERE m.template_id = ct.id AND m.active IS TRUE) AS has_active_mapping
      FROM public.core_template_version ctv
      JOIN public.core_template ct ON ct.id = ctv.template_id
     WHERE upper(ctv.status) IN ('PUBLISHED','ACTIVE')
  ),
  classified AS (
    SELECT s.*,
           CASE
             WHEN s.purpose = 'EVENT_COMMUNICATION' AND NOT s.has_active_mapping THEN 'BLOCKED_CONFIGURATION'
             WHEN s.purpose = 'UNCLASSIFIED' THEN 'LEGACY_REVIEW_REQUIRED'
             WHEN s.purpose IN ('MANUAL_CORRESPONDENCE','DOCUMENT_GENERATION','FORM_OUTPUT') THEN 'NOT_APPLICABLE_TO_EVENT_MAPPING'
             ELSE 'LEGACY_ASSESSED_CERTIFIABLE'
           END AS classification
      FROM src s
  ),
  ins AS (
    INSERT INTO public.comm_hub_governance_record (
      entity_type, entity_id, entity_version, governance_status, governance_version,
      validation_status, certification_status, enforcement_status,
      dependency_manifest, is_stale, classification, reason,
      correlation_id, created_by, updated_by, created_at, updated_at)
    SELECT 'TEMPLATE_VERSION', c.version_id, c.version_no,
           'DISCOVERED', 1, 'PENDING','PENDING','PENDING',
           jsonb_build_object('legacy_backfill', true, 'template_purpose', c.purpose,
             'publishing_status', c.pub_status, 'has_active_mapping', c.has_active_mapping),
           false, c.classification,
           'Phase 4B Turn B1 legacy backfill from Phase 3 assessment',
           v_correlation, v_uid, v_uid, v_now, v_now
      FROM classified c
    ON CONFLICT (entity_type, entity_id, entity_version) DO NOTHING
    RETURNING id
  )
  SELECT (SELECT count(*) FROM classified), (SELECT count(*) FROM ins),
         (SELECT jsonb_object_agg(classification, cnt) FROM (SELECT classification, count(*)::int AS cnt FROM classified GROUP BY 1) t),
         (SELECT jsonb_object_agg(purpose, cnt)        FROM (SELECT purpose,        count(*)::int AS cnt FROM classified GROUP BY 1) t)
  INTO v_total, v_inserted, v_by_class, v_by_purpose;
  v_skipped := v_total - v_inserted;
  INSERT INTO public.comm_hub_governance_audit (
    entity_type, entity_id, entity_version, action, previous_status, new_status,
    actor, reason, correlation_id, detail
  ) VALUES (
    'TEMPLATE_VERSION', '00000000-0000-0000-0000-000000000000'::uuid, 'BULK',
    'BACKFILL_DISCOVER', NULL, 'DISCOVERED', v_uid,
    'Phase 4B Turn B1 legacy backfill', v_correlation,
    jsonb_build_object('total_candidates', v_total, 'inserted', v_inserted,
      'skipped_existing', v_skipped,
      'by_classification', COALESCE(v_by_class,'{}'::jsonb),
      'by_template_purpose', COALESCE(v_by_purpose,'{}'::jsonb)));
  RETURN jsonb_build_object('ok', true, 'total_candidates', v_total, 'inserted', v_inserted,
    'skipped_existing', v_skipped, 'by_classification', COALESCE(v_by_class,'{}'::jsonb),
    'by_template_purpose', COALESCE(v_by_purpose,'{}'::jsonb), 'correlation_id', v_correlation);
END $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_canonical_jsonb(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN jsonb_typeof(p) = 'object' THEN
      COALESCE((SELECT jsonb_object_agg(k, public.comm_hub_canonical_jsonb(v) ORDER BY k)
                  FROM jsonb_each(p) AS e(k, v)
                 WHERE v IS NOT NULL AND jsonb_typeof(v) <> 'null'),
               '{}'::jsonb)
    WHEN jsonb_typeof(p) = 'array' THEN
      COALESCE((SELECT jsonb_agg(public.comm_hub_canonical_jsonb(v))
                  FROM jsonb_array_elements(p) AS a(v)),
               '[]'::jsonb)
    ELSE p
  END
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_canonicalization_version()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$ SELECT 'comm-hub-canonical-json/v1'::text $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_canonicalize_jsonb(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_type text; v_key text; v_keys text[]; v_parts text[];
BEGIN
  IF p_value IS NULL THEN RETURN 'null'; END IF;
  v_type := jsonb_typeof(p_value);
  IF v_type = 'null'    THEN RETURN 'null'; END IF;
  IF v_type = 'boolean' THEN RETURN CASE WHEN p_value = 'true'::jsonb THEN 'true' ELSE 'false' END; END IF;
  IF v_type = 'number'  THEN RETURN p_value::text; END IF;
  IF v_type = 'string'  THEN RETURN to_jsonb(p_value #>> '{}')::text; END IF;
  IF v_type = 'array' THEN
    v_parts := ARRAY[]::text[];
    FOR v_key IN
      SELECT public.comm_hub_canonicalize_jsonb(elem)
        FROM jsonb_array_elements(p_value) WITH ORDINALITY AS t(elem, idx)
       ORDER BY t.idx
    LOOP v_parts := v_parts || v_key; END LOOP;
    RETURN '[' || array_to_string(v_parts, ',') || ']';
  END IF;
  IF v_type = 'object' THEN
    SELECT array_agg(k ORDER BY k) INTO v_keys FROM jsonb_object_keys(p_value) AS k;
    v_parts := ARRAY[]::text[];
    IF v_keys IS NOT NULL THEN
      FOREACH v_key IN ARRAY v_keys LOOP
        v_parts := v_parts || (to_jsonb(v_key)::text || ':' || public.comm_hub_canonicalize_jsonb(p_value -> v_key));
      END LOOP;
    END IF;
    RETURN '{' || array_to_string(v_parts, ',') || '}';
  END IF;
  RETURN 'null';
END $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_classify_template_purpose(p_template_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN t.is_base_layout = true                                             THEN 'SHARED_LAYOUT'
    WHEN upper(COALESCE(t.template_type,'')) IN ('DOCUMENT','STATEMENT','RECEIPT','CERTIFICATE')
                                                                             THEN 'DOCUMENT_GENERATION'
    WHEN upper(COALESCE(t.template_type,'')) = 'FORM'                        THEN 'FORM_OUTPUT'
    WHEN upper(COALESCE(t.template_type,'')) IN ('LETTER','NOTICE')          THEN 'MANUAL_CORRESPONDENCE'
    WHEN upper(COALESCE(t.template_type,'')) IN ('EMAIL','SMS','IN_APP')     THEN 'EVENT_COMMUNICATION'
    ELSE 'UNCLASSIFIED_REVIEW_REQUIRED'
  END
  FROM public.core_template t WHERE t.id = p_template_id;
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_compute_scenario_hash(p_scenario_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_row communication_hub_event_test_scenario%ROWTYPE; v_sv integer; v_canonical text;
BEGIN
  SELECT * INTO v_row FROM communication_hub_event_test_scenario WHERE id=p_scenario_id;
  IF v_row.id IS NULL THEN RETURN NULL; END IF;
  SELECT schema_version INTO v_sv FROM communication_hub_event_payload_schema
    WHERE module_code=v_row.module_code AND event_code=v_row.event_code AND status='ENFORCED'
    ORDER BY schema_version DESC LIMIT 1;
  v_canonical := 'comm-hub/scenario/v1|'||upper(v_row.module_code)||'|'||upper(v_row.event_code)
    ||'|'||v_row.channel||'|'||v_row.scenario_key
    ||'|schema_version='||COALESCE(v_sv::text,'null')
    ||'|payload='||COALESCE(v_row.tokens::text,'{}');
  RETURN encode(extensions.digest(v_canonical,'sha256'),'hex');
END; $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_controlled_live_scope_hash(p_operator uuid, p_module text, p_event text, p_channel text, p_recipient_hash text, p_preview_approval uuid, p_dryrun_cert uuid)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT encode(digest(
    coalesce(p_operator::text,'') || '|' ||
    coalesce(p_module,'')          || '|' ||
    coalesce(p_event,'')           || '|' ||
    coalesce(p_channel,'')         || '|' ||
    coalesce(p_recipient_hash,'')  || '|' ||
    coalesce(p_preview_approval::text,'') || '|' ||
    coalesce(p_dryrun_cert::text,''), 'sha256'), 'hex')
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_controlled_live_scope_hash_v2(p_operator uuid, p_module text, p_event text, p_channel text, p_recipient_hash text, p_preview_approval uuid, p_dryrun_cert uuid, p_send_context text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT encode(
    extensions.digest(
      concat_ws('|',
        coalesce(p_operator::text,''),
        coalesce(p_module,''),
        coalesce(p_event,''),
        coalesce(p_channel,''),
        coalesce(p_recipient_hash,''),
        coalesce(p_preview_approval::text,''),
        coalesce(p_dryrun_cert::text,''),
        coalesce(p_send_context,'STUB')
      ),
      'sha256'
    ),
    'hex'
  );
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_diff_manifests(p_certified jsonb, p_current jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_changes text[] := ARRAY[]::text[];
  cd jsonb := coalesce(p_certified->'dependencies','{}'::jsonb);
  nd jsonb := coalesce(p_current->'dependencies','{}'::jsonb);
BEGIN
  IF (p_certified->>'manifest_builder_version') IS DISTINCT FROM (p_current->>'manifest_builder_version') THEN v_changes := v_changes || ARRAY['MANIFEST_BUILDER_CHANGED']::text[]; END IF;
  IF (p_certified->>'canonical_renderer_version') IS DISTINCT FROM (p_current->>'canonical_renderer_version') THEN v_changes := v_changes || ARRAY['RENDERER_VERSION_CHANGED']::text[]; END IF;
  IF (p_certified->>'security_policy_version') IS DISTINCT FROM (p_current->>'security_policy_version') THEN v_changes := v_changes || ARRAY['SECURITY_POLICY_CHANGED']::text[]; END IF;
  IF (p_certified->>'template_type_policy_version') IS DISTINCT FROM (p_current->>'template_type_policy_version') THEN v_changes := v_changes || ARRAY['TYPE_CHANNEL_POLICY_CHANGED']::text[]; END IF;
  IF (cd->>'subject_hash') IS DISTINCT FROM (nd->>'subject_hash')
     OR (cd->>'body_html_hash') IS DISTINCT FROM (nd->>'body_html_hash')
     OR (cd->>'body_text_hash') IS DISTINCT FROM (nd->>'body_text_hash') THEN v_changes := v_changes || ARRAY['TEMPLATE_CONTENT_CHANGED']::text[]; END IF;
  IF (cd->>'template_version_no') IS DISTINCT FROM (nd->>'template_version_no')
     OR (cd->>'template_version_status') IS DISTINCT FROM (nd->>'template_version_status') THEN v_changes := v_changes || ARRAY['TEMPLATE_VERSION_CHANGED']::text[]; END IF;
  IF (cd->>'template_purpose') IS DISTINCT FROM (nd->>'template_purpose') THEN v_changes := v_changes || ARRAY['TEMPLATE_PURPOSE_CHANGED']::text[]; END IF;
  IF (cd->>'template_type') IS DISTINCT FROM (nd->>'template_type') THEN v_changes := v_changes || ARRAY['TEMPLATE_TYPE_CHANGED']::text[]; END IF;
  IF (cd->>'layout_id') IS DISTINCT FROM (nd->>'layout_id') THEN v_changes := v_changes || ARRAY['LAYOUT_CHANGED']::text[]; END IF;
  IF (cd->'sections') IS DISTINCT FROM (nd->'sections') THEN v_changes := v_changes || ARRAY['SECTION_CHANGED']::text[]; END IF;
  IF (cd->'variable_bindings') IS DISTINCT FROM (nd->'variable_bindings') THEN v_changes := v_changes || ARRAY['VARIABLE_CONTRACT_CHANGED']::text[]; END IF;
  IF (cd->'event_mapping') IS DISTINCT FROM (nd->'event_mapping') THEN v_changes := v_changes || ARRAY['EVENT_MAPPING_CHANGED']::text[]; END IF;
  IF (cd->'sender_readiness') IS DISTINCT FROM (nd->'sender_readiness') THEN v_changes := v_changes || ARRAY['SENDER_READINESS_CHANGED']::text[]; END IF;
  IF array_length(v_changes,1) IS NULL
     AND public.compute_comm_hub_dependency_hash(p_certified) IS DISTINCT FROM public.compute_comm_hub_dependency_hash(p_current)
  THEN v_changes := v_changes || ARRAY['DEPENDENCY_HASH_MISMATCH_UNCATEGORISED']::text[]; END IF;
  RETURN v_changes;
END $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_dry_run_scope_hash(p_actor uuid, p_module text, p_event text, p_channel text, p_snapshot uuid, p_recipient_hash text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT encode(sha256(convert_to(
    coalesce(p_actor::text,'') || '|' || coalesce(p_module,'') || '|' ||
    coalesce(p_event,'') || '|' || coalesce(p_channel,'') || '|' ||
    coalesce(p_snapshot::text,'') || '|' || coalesce(p_recipient_hash,''),
    'UTF8')), 'hex')
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_evidence_hash(p_domain text, p_value jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT public.comm_hub_sha256_hex(
    coalesce(p_domain,'')
    || E'\x1f'
    || public.comm_hub_canonicalization_version()
    || E'\x1f'
    || public.comm_hub_canonicalize_jsonb(p_value)
  );
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_flatten_tokens(p_tokens jsonb, p_prefix text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_out jsonb := '{}'::jsonb;
  v_key text;
  v_val jsonb;
  v_path text;
BEGIN
  IF p_tokens IS NULL OR jsonb_typeof(p_tokens) <> 'object' THEN
    RETURN v_out;
  END IF;
  FOR v_key, v_val IN SELECT * FROM jsonb_each(p_tokens) LOOP
    v_path := CASE WHEN p_prefix = '' THEN v_key ELSE p_prefix || '.' || v_key END;
    IF jsonb_typeof(v_val) = 'object' THEN
      v_out := v_out || public.comm_hub_flatten_tokens(v_val, v_path);
      v_out := v_out || jsonb_build_object(v_path, v_val::text);
    ELSIF jsonb_typeof(v_val) = 'array' THEN
      v_out := v_out || jsonb_build_object(v_path, v_val::text);
    ELSIF jsonb_typeof(v_val) = 'null' THEN
      v_out := v_out || jsonb_build_object(v_path, '');
    ELSE
      v_out := v_out || jsonb_build_object(v_path, trim(both '"' from v_val::text));
    END IF;
  END LOOP;
  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_governance_is_valid_transition(p_entity_type comm_hub_governance_entity_type, p_from text, p_to text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_forward jsonb; v_correction jsonb;
BEGIN
  IF p_from IS NULL OR p_to IS NULL THEN RETURN false; END IF;
  IF p_from = p_to THEN RETURN false; END IF;
  v_forward := CASE p_entity_type
    WHEN 'TEMPLATE_VERSION' THEN jsonb_build_object(
      'DRAFT',ARRAY['DISCOVERED'],'DISCOVERED',ARRAY['VALIDATED'],
      'VALIDATED',ARRAY['CERTIFIED'],'CERTIFIED',ARRAY['ACTIVE'],'ACTIVE',ARRAY['RETIRED'])
    WHEN 'TEMPLATE_VARIABLE_CONTRACT' THEN jsonb_build_object(
      'DRAFT',ARRAY['DISCOVERED'],'DISCOVERED',ARRAY['VALIDATED'],
      'VALIDATED',ARRAY['ENFORCED'],'ENFORCED',ARRAY['RETIRED'])
    WHEN 'EVENT_PAYLOAD_SCHEMA' THEN jsonb_build_object(
      'DRAFT',ARRAY['DISCOVERED'],'DISCOVERED',ARRAY['VALIDATED'],
      'VALIDATED',ARRAY['ENFORCED'],'ENFORCED',ARRAY['RETIRED'])
    WHEN 'EVENT_TEMPLATE_MAPPING' THEN jsonb_build_object(
      'DRAFT',ARRAY['VALIDATED'],'VALIDATED',ARRAY['CERTIFIED'],
      'CERTIFIED',ARRAY['ACTIVE'],'ACTIVE',ARRAY['RETIRED'])
    WHEN 'TEST_SCENARIO' THEN jsonb_build_object(
      'DRAFT',ARRAY['SCHEMA_VALID'],'SCHEMA_VALID',ARRAY['TEMPLATE_COMPATIBLE'],
      'TEMPLATE_COMPATIBLE',ARRAY['FULLY_RENDERABLE'],
      'FULLY_RENDERABLE',ARRAY['ACTIVE'],'ACTIVE',ARRAY['RETIRED'])
    WHEN 'SENDER_CONFIGURATION' THEN jsonb_build_object(
      'BLOCKED',ARRAY['TEST_READY','STALE'],
      'TEST_READY',ARRAY['REAL_EMAIL_READY','STALE','BLOCKED'],
      'REAL_EMAIL_READY',ARRAY['STALE','BLOCKED','TEST_READY'],
      'STALE',ARRAY['BLOCKED','TEST_READY','REAL_EMAIL_READY'])
    WHEN 'EVENT_RELEASE_CERTIFICATION' THEN jsonb_build_object(
      'NOT_CERTIFIED',ARRAY['CONTROLLED_STUB_CERTIFIED'],
      'CONTROLLED_STUB_CERTIFIED',ARRAY['MANUAL_PRODUCTION_CERTIFIED','STALE','SUSPENDED','RETIRED'],
      'MANUAL_PRODUCTION_CERTIFIED',ARRAY['AUTOMATED_PRODUCTION_CERTIFIED','STALE','SUSPENDED','RETIRED'],
      'AUTOMATED_PRODUCTION_CERTIFIED',ARRAY['STALE','SUSPENDED','RETIRED'],
      'STALE',ARRAY['CONTROLLED_STUB_CERTIFIED','SUSPENDED','RETIRED'],
      'SUSPENDED',ARRAY['CONTROLLED_STUB_CERTIFIED','RETIRED'])
  END;
  v_correction := CASE p_entity_type
    WHEN 'TEMPLATE_VERSION' THEN jsonb_build_object(
      'DISCOVERED',ARRAY['DRAFT'],'VALIDATED',ARRAY['DRAFT'],'CERTIFIED',ARRAY['VALIDATED'])
    WHEN 'TEMPLATE_VARIABLE_CONTRACT' THEN jsonb_build_object('DISCOVERED',ARRAY['DRAFT'],'VALIDATED',ARRAY['DRAFT'])
    WHEN 'EVENT_PAYLOAD_SCHEMA' THEN jsonb_build_object('DISCOVERED',ARRAY['DRAFT'],'VALIDATED',ARRAY['DRAFT'])
    WHEN 'EVENT_TEMPLATE_MAPPING' THEN jsonb_build_object('VALIDATED',ARRAY['DRAFT'],'CERTIFIED',ARRAY['VALIDATED'])
    WHEN 'TEST_SCENARIO' THEN jsonb_build_object(
      'SCHEMA_VALID',ARRAY['DRAFT'],'TEMPLATE_COMPATIBLE',ARRAY['SCHEMA_VALID'],
      'FULLY_RENDERABLE',ARRAY['TEMPLATE_COMPATIBLE'])
    ELSE '{}'::jsonb
  END;
  IF v_forward ? p_from AND (v_forward->p_from) @> to_jsonb(p_to) THEN RETURN true; END IF;
  IF v_correction ? p_from AND (v_correction->p_from) @> to_jsonb(p_to) THEN RETURN true; END IF;
  RETURN false;
END $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_governance_status_is_valid(p_entity_type comm_hub_governance_entity_type, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_ok boolean := false;
BEGIN
  IF p_status IS NULL THEN RETURN false; END IF;
  BEGIN
    CASE p_entity_type
      WHEN 'TEMPLATE_VERSION'            THEN PERFORM p_status::public.comm_hub_template_lifecycle;
      WHEN 'TEMPLATE_VARIABLE_CONTRACT'  THEN PERFORM p_status::public.comm_hub_contract_lifecycle;
      WHEN 'EVENT_PAYLOAD_SCHEMA'        THEN PERFORM p_status::public.comm_hub_schema_lifecycle;
      WHEN 'EVENT_TEMPLATE_MAPPING'      THEN PERFORM p_status::public.comm_hub_mapping_lifecycle;
      WHEN 'TEST_SCENARIO'               THEN PERFORM p_status::public.comm_hub_scenario_lifecycle;
      WHEN 'SENDER_CONFIGURATION'        THEN PERFORM p_status::public.comm_hub_sender_readiness_state;
      WHEN 'EVENT_RELEASE_CERTIFICATION' THEN PERFORM p_status::public.comm_hub_release_lifecycle;
    END CASE;
    v_ok := true;
  EXCEPTION WHEN OTHERS THEN v_ok := false;
  END;
  RETURN v_ok;
END $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_governance_transition(p_entity_type text, p_entity_id uuid, p_entity_version text, p_target_status text, p_reason text, p_expected_version bigint DEFAULT NULL::bigint, p_action text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_is_admin boolean := false;
  v_et public.comm_hub_governance_entity_type;
  v_act public.comm_hub_governance_action;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='authentication_required'; END IF;
  BEGIN v_is_admin := public.is_comm_hub_operator_admin(v_uid);
  EXCEPTION WHEN undefined_function THEN
    SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=v_uid AND role='Admin') INTO v_is_admin;
  END;
  IF NOT v_is_admin THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='not_authorised'; END IF;
  BEGIN v_et := p_entity_type::public.comm_hub_governance_entity_type;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='unknown_entity_type'; END;
  BEGIN v_act := COALESCE(p_action,'VALIDATE')::public.comm_hub_governance_action;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='unknown_governance_action'; END;
  RETURN public._comm_hub_governance_transition_core(
    v_et, p_entity_id, p_entity_version, p_target_status,
    p_expected_version, p_reason, v_uid, v_act, 'comm_hub_governance_transition');
END $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_html_escape(p_in text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT replace(replace(replace(replace(replace(
    COALESCE(p_in,''),
    '&','&amp;'),
    '<','&lt;'),
    '>','&gt;'),
    '"','&quot;'),
    '''','&#39;');
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_json_schema_subset_scan_keywords(p_schema jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  WITH RECURSIVE
  allow(kw) AS (
    VALUES ('type'),('required'),('properties'),('items'),('enum'),('const'),
           ('minimum'),('maximum'),('minLength'),('maxLength'),('pattern'),
           ('additionalProperties'),('format'),
           ('title'),('description'),('examples'),('$schema'),('$comment'),('default')
  ),
  walker(node, path) AS (
    SELECT p_schema, '#'::text
    UNION ALL
    SELECT sub.node, sub.path FROM walker w
    CROSS JOIN LATERAL (
      SELECT (e.value) AS node, w.path || '/properties/' || e.key AS path
      FROM jsonb_each(w.node -> 'properties') e
      WHERE jsonb_typeof(w.node)='object' AND jsonb_typeof(w.node -> 'properties')='object'
      UNION ALL
      SELECT w.node -> 'items', w.path || '/items'
      WHERE jsonb_typeof(w.node)='object' AND jsonb_typeof(w.node -> 'items')='object'
      UNION ALL
      SELECT w.node -> 'additionalProperties', w.path || '/additionalProperties'
      WHERE jsonb_typeof(w.node)='object' AND jsonb_typeof(w.node -> 'additionalProperties')='object'
    ) sub
  ),
  bad AS (
    SELECT k.key AS keyword, w.path AS schema_path FROM walker w
    JOIN LATERAL jsonb_object_keys(w.node) k(key) ON jsonb_typeof(w.node)='object'
    WHERE k.key NOT IN (SELECT kw FROM allow)
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object('keyword',keyword,'schema_path',schema_path)),'[]'::jsonb) FROM bad;
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_normalize_gate_key(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT lower(trim(coalesce(p_value, '')));
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_normalize_recipient_set(p_to jsonb, p_cc jsonb, p_bcc jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_to  jsonb;
  v_cc  jsonb;
  v_bcc jsonb;
  v_hash text;
  v_norm text;
BEGIN
  SELECT coalesce(jsonb_agg(distinct lower(trim(x)) ORDER BY lower(trim(x))), '[]'::jsonb)
    INTO v_to FROM jsonb_array_elements_text(coalesce(p_to,'[]'::jsonb)) x WHERE trim(x) <> '';
  SELECT coalesce(jsonb_agg(distinct lower(trim(x)) ORDER BY lower(trim(x))), '[]'::jsonb)
    INTO v_cc FROM jsonb_array_elements_text(coalesce(p_cc,'[]'::jsonb)) x WHERE trim(x) <> '';
  SELECT coalesce(jsonb_agg(distinct lower(trim(x)) ORDER BY lower(trim(x))), '[]'::jsonb)
    INTO v_bcc FROM jsonb_array_elements_text(coalesce(p_bcc,'[]'::jsonb)) x WHERE trim(x) <> '';
  v_norm := 'TO:'||coalesce(v_to::text,'[]')||'|CC:'||coalesce(v_cc::text,'[]')||'|BCC:'||coalesce(v_bcc::text,'[]');
  v_hash := md5(v_norm);
  RETURN jsonb_build_object(
    'to', v_to, 'cc', v_cc, 'bcc', v_bcc,
    'hash', v_hash,
    'recipient_set_hash', v_hash
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_preview_snapshot_bind_versions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.configuration_version IS NULL THEN
    SELECT configuration_version INTO NEW.configuration_version
      FROM public.communication_hub_control_settings
      WHERE singleton_guard = 'primary';
  END IF;
  IF NEW.recipient_policy_version IS NULL THEN
    SELECT policy_version INTO NEW.recipient_policy_version
      FROM public.communication_hub_recipient_policy
      WHERE singleton_guard = 'primary';
  END IF;
  RETURN NEW;
END;
$function$;
