CREATE OR REPLACE FUNCTION public.comm_hub_sha256_hex(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'public', 'extensions'
AS $function$ SELECT lower(encode(extensions.digest(p_text, 'sha256'), 'hex')); $function$;
CREATE OR REPLACE FUNCTION public.comm_hub_snapshot_align_recipient_hash()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_norm jsonb;
BEGIN
  v_norm := public.comm_hub_normalize_recipient_set(
    COALESCE(NEW.to_recipients, '[]'::jsonb),
    COALESCE(NEW.cc_recipients, '[]'::jsonb),
    COALESCE(NEW.bcc_recipients, '[]'::jsonb)
  );
  NEW.recipient_set_hash := v_norm->>'recipient_set_hash';
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.comm_hub_transition_log_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'comm_hub_runtime_transition_log is append-only (op=%)', TG_OP;
END; $function$;
CREATE OR REPLACE FUNCTION public.communication_controlled_live_execution_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.idempotency_key   IS DISTINCT FROM OLD.idempotency_key   THEN RAISE EXCEPTION 'idempotency_key is write-once'; END IF;
    IF NEW.scope_hash        IS DISTINCT FROM OLD.scope_hash        THEN RAISE EXCEPTION 'scope_hash is write-once'; END IF;
    IF NEW.requested_by      IS DISTINCT FROM OLD.requested_by      THEN RAISE EXCEPTION 'requested_by is write-once'; END IF;
    IF NEW.module_code       IS DISTINCT FROM OLD.module_code       THEN RAISE EXCEPTION 'module_code is write-once'; END IF;
    IF NEW.event_code        IS DISTINCT FROM OLD.event_code        THEN RAISE EXCEPTION 'event_code is write-once'; END IF;
    IF NEW.channel           IS DISTINCT FROM OLD.channel           THEN RAISE EXCEPTION 'channel is write-once'; END IF;
    IF NEW.recipient_set_hash IS DISTINCT FROM OLD.recipient_set_hash THEN RAISE EXCEPTION 'recipient_set_hash is write-once'; END IF;
    IF NEW.recipient         IS DISTINCT FROM OLD.recipient         THEN RAISE EXCEPTION 'recipient is write-once'; END IF;
    IF NEW.preview_approval_id IS DISTINCT FROM OLD.preview_approval_id THEN RAISE EXCEPTION 'preview_approval_id is write-once'; END IF;
    IF NEW.dry_run_certification_id IS DISTINCT FROM OLD.dry_run_certification_id THEN RAISE EXCEPTION 'dry_run_certification_id is write-once'; END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.communication_controlled_live_grant_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.execution_id             IS DISTINCT FROM OLD.execution_id             THEN RAISE EXCEPTION 'execution_id is write-once'; END IF;
    IF NEW.module_code              IS DISTINCT FROM OLD.module_code              THEN RAISE EXCEPTION 'module_code is write-once'; END IF;
    IF NEW.event_code               IS DISTINCT FROM OLD.event_code               THEN RAISE EXCEPTION 'event_code is write-once'; END IF;
    IF NEW.channel                  IS DISTINCT FROM OLD.channel                  THEN RAISE EXCEPTION 'channel is write-once'; END IF;
    IF NEW.recipient_set_hash       IS DISTINCT FROM OLD.recipient_set_hash       THEN RAISE EXCEPTION 'recipient_set_hash is write-once'; END IF;
    IF NEW.scope_hash               IS DISTINCT FROM OLD.scope_hash               THEN RAISE EXCEPTION 'scope_hash is write-once'; END IF;
    IF NEW.preview_approval_id      IS DISTINCT FROM OLD.preview_approval_id      THEN RAISE EXCEPTION 'preview_approval_id is write-once'; END IF;
    IF NEW.dry_run_certification_id IS DISTINCT FROM OLD.dry_run_certification_id THEN RAISE EXCEPTION 'dry_run_certification_id is write-once'; END IF;
    IF NEW.issued_by                IS DISTINCT FROM OLD.issued_by                THEN RAISE EXCEPTION 'issued_by is write-once'; END IF;
    IF NEW.issued_at                IS DISTINCT FROM OLD.issued_at                THEN RAISE EXCEPTION 'issued_at is write-once'; END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.communication_dry_run_cert_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_evidence_changed boolean := false;
  v_lifecycle_changed boolean := false;
  v_is_service boolean := (current_setting('role', true) = 'service_role')
                       OR (session_user = 'service_role')
                       OR (current_user = 'postgres');
BEGIN
  -- Evidence immutability
  IF NEW.id IS DISTINCT FROM OLD.id
   OR NEW.certification_no IS DISTINCT FROM OLD.certification_no
   OR NEW.module_code IS DISTINCT FROM OLD.module_code
   OR NEW.event_code IS DISTINCT FROM OLD.event_code
   OR NEW.channel IS DISTINCT FROM OLD.channel
   OR NEW.preview_snapshot_id IS DISTINCT FROM OLD.preview_snapshot_id
   OR NEW.preview_approval_id IS DISTINCT FROM OLD.preview_approval_id
   OR NEW.communication_request_id IS DISTINCT FROM OLD.communication_request_id
   OR NEW.communication_message_id IS DISTINCT FROM OLD.communication_message_id
   OR NEW.communication_delivery_attempt_id IS DISTINCT FROM OLD.communication_delivery_attempt_id
   OR NEW.trace_id IS DISTINCT FROM OLD.trace_id
   OR NEW.recipient_set_hash IS DISTINCT FROM OLD.recipient_set_hash
   OR NEW.template_id IS DISTINCT FROM OLD.template_id
   OR NEW.template_version_id IS DISTINCT FROM OLD.template_version_id
   OR NEW.sender_profile_id IS DISTINCT FROM OLD.sender_profile_id
   OR NEW.rendered_subject_hash IS DISTINCT FROM OLD.rendered_subject_hash
   OR NEW.rendered_body_hash IS DISTINCT FROM OLD.rendered_body_hash
   OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
   OR NEW.configuration_version IS DISTINCT FROM OLD.configuration_version
   OR NEW.recipient_policy_version IS DISTINCT FROM OLD.recipient_policy_version
   OR NEW.send_policy_version IS DISTINCT FROM OLD.send_policy_version
   OR NEW.review_policy_version IS DISTINCT FROM OLD.review_policy_version
   OR NEW.original_decision_id IS DISTINCT FROM OLD.original_decision_id
   OR NEW.dispatcher_revalidation_decision_id IS DISTINCT FROM OLD.dispatcher_revalidation_decision_id
   OR NEW.provider_call_attempted IS DISTINCT FROM OLD.provider_call_attempted
   OR NEW.certified_by IS DISTINCT FROM OLD.certified_by
   OR NEW.certified_at IS DISTINCT FROM OLD.certified_at
   OR NEW.result IS DISTINCT FROM OLD.result
   OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
   OR NEW.audit_metadata IS DISTINCT FROM OLD.audit_metadata
  THEN
    RAISE EXCEPTION 'communication_dry_run_certification evidence fields are immutable';
  END IF;

  -- Any lifecycle changes must come from service_role/definer context.
  IF NEW.status IS DISTINCT FROM OLD.status
   OR NEW.revoked_by IS DISTINCT FROM OLD.revoked_by
   OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at
   OR NEW.revocation_reason IS DISTINCT FROM OLD.revocation_reason
   OR NEW.invalidation_reason IS DISTINCT FROM OLD.invalidation_reason
   OR NEW.invalidated_at IS DISTINCT FROM OLD.invalidated_at
   OR NEW.invalidated_by IS DISTINCT FROM OLD.invalidated_by
   OR NEW.superseded_by IS DISTINCT FROM OLD.superseded_by
  THEN
    v_lifecycle_changed := true;
    IF NOT v_is_service THEN
      RAISE EXCEPTION 'communication_dry_run_certification lifecycle fields may only be updated via authorised RPC';
    END IF;
    NEW.lifecycle_updated_at := now();
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.communication_hub_transport_guard_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'communication_hub_transport_guard_audit is append-only'
      USING ERRCODE = '42501';
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'communication_hub_transport_guard_audit is append-only'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.communication_message_send_context_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.dry_run_locked IS TRUE THEN
    IF NEW.send_context IS DISTINCT FROM OLD.send_context THEN
      RAISE EXCEPTION 'communication_message.send_context is immutable for dry-run-locked messages';
    END IF;
    IF NEW.dry_run_locked IS DISTINCT FROM OLD.dry_run_locked THEN
      RAISE EXCEPTION 'communication_message.dry_run_locked is immutable once set';
    END IF;
  END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.communication_message_targeted_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_allowed text := current_setting('comm_hub.allow_targeted_update', true);
BEGIN
  IF v_allowed IS DISTINCT FROM 'true' THEN
    IF NEW.targeted_dispatch_only IS DISTINCT FROM OLD.targeted_dispatch_only
       OR NEW.controlled_action IS DISTINCT FROM OLD.controlled_action
       OR NEW.controlled_live_execution_id IS DISTINCT FROM OLD.controlled_live_execution_id
       OR NEW.controlled_live_grant_id IS DISTINCT FROM OLD.controlled_live_grant_id
       OR NEW.preview_snapshot_id IS DISTINCT FROM OLD.preview_snapshot_id
       OR NEW.preview_approval_id IS DISTINCT FROM OLD.preview_approval_id
       OR NEW.dry_run_certification_id IS DISTINCT FROM OLD.dry_run_certification_id
       OR NEW.governance_certification_id IS DISTINCT FROM OLD.governance_certification_id
       OR NEW.certified_dependency_hash IS DISTINCT FROM OLD.certified_dependency_hash
       OR NEW.recipient_set_hash IS DISTINCT FROM OLD.recipient_set_hash
       OR NEW.subject_hash IS DISTINCT FROM OLD.subject_hash
       OR NEW.body_hash IS DISTINCT FROM OLD.body_hash
       OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.revalidation_execution_id IS DISTINCT FROM OLD.revalidation_execution_id THEN
      RAISE EXCEPTION 'targeted classification is immutable (message %)', OLD.id
        USING ERRCODE = '42501';
    END IF;
    IF OLD.targeted_dispatch_only THEN
      IF NEW.send_context IS DISTINCT FROM OLD.send_context
         OR NEW.template_version_id IS DISTINCT FROM OLD.template_version_id
         OR NEW.sender_profile_id IS DISTINCT FROM OLD.sender_profile_id
         OR NEW.from_email IS DISTINCT FROM OLD.from_email
         OR NEW.from_display_name IS DISTINCT FROM OLD.from_display_name
         OR NEW.reply_to_email IS DISTINCT FROM OLD.reply_to_email
         OR NEW.origin IS DISTINCT FROM OLD.origin
         OR NEW.channel IS DISTINCT FROM OLD.channel
         OR NEW.request_id IS DISTINCT FROM OLD.request_id
         OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id THEN
        RAISE EXCEPTION 'frozen evidence fields are immutable on targeted messages (message %)', OLD.id
          USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.communication_preview_approval_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.snapshot_id IS DISTINCT FROM OLD.snapshot_id
     OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
     OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
     OR NEW.approval_reason IS DISTINCT FROM OLD.approval_reason
     OR NEW.content_hash_at_approval IS DISTINCT FROM OLD.content_hash_at_approval
     OR NEW.configuration_version IS DISTINCT FROM OLD.configuration_version
     OR NEW.recipient_policy_version IS DISTINCT FROM OLD.recipient_policy_version THEN
    RAISE EXCEPTION 'communication_preview_approval is immutable for approval evidence fields';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.communication_request_targeted_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_allowed text := current_setting('comm_hub.allow_targeted_update', true);
BEGIN
  IF v_allowed IS DISTINCT FROM 'true' THEN
    IF NEW.targeted_dispatch_only IS DISTINCT FROM OLD.targeted_dispatch_only
       OR NEW.controlled_action IS DISTINCT FROM OLD.controlled_action
       OR NEW.controlled_live_execution_id IS DISTINCT FROM OLD.controlled_live_execution_id
       OR NEW.controlled_live_grant_id IS DISTINCT FROM OLD.controlled_live_grant_id THEN
      RAISE EXCEPTION 'targeted classification is immutable (request %)', OLD.id
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.complete_comm_hub_scheduler_tick(p_lease_id uuid, p_arm_audit_id uuid, p_automation_generation bigint, p_readiness_hash text, p_counts jsonb, p_error jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lease record;
  v_cs    record;
  v_arm   record;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_service_role_caller() THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'not_service_role'));
  END IF;

  SELECT * INTO v_lease FROM public.comm_hub_scheduler_tick_leases WHERE id = p_lease_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'lease_not_found'));
  END IF;
  IF v_lease.status <> 'RUNNING' THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'lease_not_running'));
  END IF;

  SELECT * INTO v_cs FROM public.communication_hub_control_settings
    WHERE singleton_guard = 'primary' FOR UPDATE;

  IF v_cs.operating_mode <> 'AUTOMATED_PRODUCTION' THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'not_automated_production'); END IF;
  IF v_cs.automation_state <> 'ARMED' THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'not_armed'); END IF;
  IF v_cs.current_arm_audit_id IS DISTINCT FROM p_arm_audit_id THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'arm_audit_mismatch'); END IF;
  IF v_cs.current_arm_audit_id IS DISTINCT FROM v_lease.arm_audit_id THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'lease_arm_audit_mismatch'); END IF;
  IF v_cs.automation_generation IS DISTINCT FROM p_automation_generation THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'automation_generation_mismatch'); END IF;
  IF v_cs.automation_generation IS DISTINCT FROM v_lease.automation_generation THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'lease_generation_mismatch'); END IF;

  SELECT * INTO v_arm FROM public.communication_hub_arm_audit WHERE id = p_arm_audit_id;
  IF NOT FOUND OR v_arm.action <> 'ARMED' THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'arm_audit_not_armed'); END IF;

  IF jsonb_array_length(v_blockers) > 0 THEN
    UPDATE public.comm_hub_scheduler_tick_leases
       SET status = 'ABANDONED', finished_at = now(), error = COALESCE(p_error, error)
     WHERE id = p_lease_id;
    RETURN jsonb_build_object('ok', false, 'blockers', v_blockers);
  END IF;

  UPDATE public.comm_hub_scheduler_tick_leases
     SET status          = CASE WHEN p_error IS NULL THEN 'COMPLETED' ELSE 'FAILED' END,
         finished_at     = now(),
         processed_count = COALESCE((p_counts->>'processed')::int, 0),
         sent_count      = COALESCE((p_counts->>'sent')::int, 0),
         retried_count   = COALESCE((p_counts->>'retried')::int, 0),
         failed_count    = COALESCE((p_counts->>'failed')::int, 0),
         skipped_count   = COALESCE((p_counts->>'skipped')::int, 0),
         error           = p_error
   WHERE id = p_lease_id;

  IF p_error IS NULL THEN
    UPDATE public.communication_hub_control_settings
       SET last_scheduler_heartbeat_at     = now(),
           scheduler_worker_version        = COALESCE(v_lease.worker_version, scheduler_worker_version),
           last_processed_count            = COALESCE((p_counts->>'processed')::bigint, 0),
           last_scheduler_error            = NULL,
           heartbeat_arm_audit_id          = p_arm_audit_id,
           heartbeat_automation_generation = p_automation_generation,
           heartbeat_readiness_hash        = p_readiness_hash
     WHERE singleton_guard = 'primary';
  ELSE
    UPDATE public.communication_hub_control_settings
       SET last_scheduler_error = p_error::text
     WHERE singleton_guard = 'primary';
  END IF;

  RETURN jsonb_build_object('ok', true, 'lease_id', p_lease_id,
    'heartbeat_recorded', (p_error IS NULL));
END $function$;
CREATE OR REPLACE FUNCTION public.complete_comm_hub_trace(p_trace_id uuid, p_status text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.communication_hub_trace
     SET status = COALESCE(p_status, status),
         current_stage = COALESCE(NULLIF(p_payload->>'current_stage',''), current_stage),
         blocked_stage = COALESCE(NULLIF(p_payload->>'blocked_stage',''), blocked_stage),
         provider_message_id = COALESCE(NULLIF(p_payload->>'provider_message_id',''), provider_message_id),
         updated_at = now()
   WHERE id = p_trace_id;
  RETURN jsonb_build_object('ok', true);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END; $function$;
CREATE OR REPLACE FUNCTION public.compute_comm_hub_dependency_hash(p_manifest jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT encode(extensions.digest(convert_to(public.comm_hub_canonical_jsonb(p_manifest)::text, 'UTF8'), 'sha256'), 'hex')
$function$;
CREATE OR REPLACE FUNCTION public.compute_comm_hub_provider_capability_evidence(p_provider_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid; v_state text; v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb; v_advisories jsonb := '[]'::jsonb;
  v_dispatch_status text := 'UNKNOWN';
  v_env jsonb := jsonb_build_object('environment','database','environment_version','pg/v1');
  v_evidence jsonb; v_hash text;
BEGIN
  -- Dispatch secret compatibility is evaluated by the caller (Edge Function) and
  -- persisted via ingest; if no explicit row exists, treat as UNKNOWN.
  SELECT dispatch_secret_status INTO v_dispatch_status
    FROM public.comm_hub_provider_capability_evidence
   WHERE provider_code = p_provider_code
   ORDER BY evidence_at DESC LIMIT 1;
  v_dispatch_status := coalesce(v_dispatch_status,'UNKNOWN');

  -- Deterministic simulator is always available for controlled stub in-DB path
  v_state := 'READY';

  v_evidence := jsonb_build_object(
    'provider_code', p_provider_code,
    'test_adapter_available', true,
    'test_adapter_enabled', true,
    'live_adapter_available', false,
    'live_adapter_enabled', false,
    'credentials_present', false,
    'external_send_gate_enabled', false,
    'connectivity_check_status','NOT_CHECKED',
    'dispatch_secret_status', v_dispatch_status,
    'environment', v_env,
    'blockers', v_blockers, 'warnings', v_warnings, 'advisories', v_advisories);
  v_hash := public.comm_hub_evidence_hash('comm-hub/provider-capability-evidence/v1', v_evidence);

  INSERT INTO public.comm_hub_provider_capability_evidence (
    provider_code, test_adapter_available, test_adapter_enabled,
    live_adapter_available, live_adapter_enabled, credentials_present,
    connectivity_check_status, dispatch_secret_status,
    state, blockers, warnings, advisories, evidence_hash, evidence_at, computed_by
  ) VALUES (
    p_provider_code, true, true, false, false, false,
    'NOT_CHECKED', v_dispatch_status,
    v_state, v_blockers, v_warnings, v_advisories, v_hash, now(), auth.uid()
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object('evidence_id', v_id, 'provider_code', p_provider_code,
    'state', v_state, 'evidence_hash', v_hash,
    'dispatch_secret_status', v_dispatch_status,
    'test_adapter_enabled', true, 'live_adapter_enabled', false);
END $function$;
CREATE OR REPLACE FUNCTION public.compute_comm_hub_sender_readiness(p_sender_profile_id uuid, p_readiness_kind text DEFAULT 'TEST_READY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v record; v_kind text := upper(coalesce(p_readiness_kind,'TEST_READY'));
  v_blockers jsonb := '[]'::jsonb; v_warnings jsonb := '[]'::jsonb; v_advisories jsonb := '[]'::jsonb;
  v_status text; v_reason text;
  v_sender_cfg jsonb; v_verif jsonb; v_evidence jsonb;
  v_sender_ver text; v_verif_ver text; v_hash text;
  v_provider_cap jsonb; v_prov_state text;
  v_expires timestamptz; v_result_id uuid;
BEGIN
  IF v_kind NOT IN ('TEST_READY','REAL_EMAIL_READY') THEN
    RAISE EXCEPTION 'SENDER_READINESS_KIND_UNSUPPORTED: %', v_kind;
  END IF;

  SELECT id, profile_code, profile_name, provider_identity_status, from_email, display_name,
         reply_to_email, provider_code, domain_verified, is_enabled, is_default,
         spf_status, dkim_status, dmarc_status, last_checked_at, updated_at,
         sender_category, audience_type, risk_level, provider_identity_id
    INTO v FROM public.communication_hub_sender_profile WHERE id = p_sender_profile_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'SENDER_PROFILE_NOT_FOUND: %', p_sender_profile_id;
  END IF;

  -- Structural blockers
  IF v.from_email IS NULL OR trim(v.from_email)='' THEN
    v_blockers := v_blockers || jsonb_build_object('code','from_email_missing','severity','BLOCKER'); END IF;
  IF v.provider_code IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','provider_missing','severity','BLOCKER'); END IF;
  IF NOT COALESCE(v.is_enabled,false) THEN
    v_blockers := v_blockers || jsonb_build_object('code','sender_disabled','severity','BLOCKER'); END IF;

  -- Kind-scoped verification requirements
  IF v_kind='REAL_EMAIL_READY' THEN
    IF v.provider_identity_status IS DISTINCT FROM 'verified' THEN
      v_blockers := v_blockers || jsonb_build_object('code','sender_not_verified','severity','BLOCKER','detail',v.provider_identity_status); END IF;
    IF NOT COALESCE(v.domain_verified,false) THEN
      v_blockers := v_blockers || jsonb_build_object('code','domain_not_verified','severity','BLOCKER'); END IF;
    IF v.spf_status IS DISTINCT FROM 'valid' THEN
      v_blockers := v_blockers || jsonb_build_object('code','spf_not_valid','severity','BLOCKER','detail',v.spf_status); END IF;
    IF v.dkim_status IS DISTINCT FROM 'valid' THEN
      v_blockers := v_blockers || jsonb_build_object('code','dkim_not_valid','severity','BLOCKER','detail',v.dkim_status); END IF;
    IF v.dmarc_status IS DISTINCT FROM 'valid' THEN
      v_warnings := v_warnings || jsonb_build_object('code','dmarc_not_valid','severity','WARNING','detail',v.dmarc_status); END IF;
  ELSE
    -- TEST_READY: DNS/verification-only downgraded to warnings
    IF v.provider_identity_status IS DISTINCT FROM 'verified' THEN
      v_warnings := v_warnings || jsonb_build_object('code','sender_not_verified','severity','WARNING','detail',v.provider_identity_status); END IF;
    IF NOT COALESCE(v.domain_verified,false) THEN
      v_warnings := v_warnings || jsonb_build_object('code','domain_not_verified','severity','WARNING'); END IF;
    IF v.spf_status IS DISTINCT FROM 'valid' THEN
      v_warnings := v_warnings || jsonb_build_object('code','spf_not_valid','severity','WARNING','detail',v.spf_status); END IF;
    IF v.dkim_status IS DISTINCT FROM 'valid' THEN
      v_warnings := v_warnings || jsonb_build_object('code','dkim_not_valid','severity','WARNING','detail',v.dkim_status); END IF;
    IF v.dmarc_status IS DISTINCT FROM 'valid' THEN
      v_advisories := v_advisories || jsonb_build_object('code','dmarc_not_valid','severity','ADVISORY','detail',v.dmarc_status); END IF;
  END IF;

  -- Provider-capability evidence (best-effort read; no external calls here)
  BEGIN
    SELECT to_jsonb(e.*) INTO v_provider_cap
      FROM public.comm_hub_provider_capability_evidence e
     WHERE e.provider_code = v.provider_code
     ORDER BY e.evidence_at DESC NULLS LAST LIMIT 1;
  EXCEPTION WHEN undefined_table THEN v_provider_cap := NULL;
  END;
  v_prov_state := coalesce(v_provider_cap->>'state','NOT_CHECKED');

  IF v_kind='REAL_EMAIL_READY' THEN
    IF v_provider_cap IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object('code','provider_capability_missing','severity','BLOCKER');
    ELSIF v_prov_state <> 'READY' THEN
      v_blockers := v_blockers || jsonb_build_object('code','provider_capability_not_ready','severity','BLOCKER','detail',v_prov_state);
    END IF;
  ELSE
    -- TEST_READY requires deterministic simulator available/enabled
    IF v_provider_cap IS NULL
       OR COALESCE((v_provider_cap->>'test_adapter_available')::boolean,false) = false
       OR COALESCE((v_provider_cap->>'test_adapter_enabled')::boolean,false) = false THEN
      v_blockers := v_blockers || jsonb_build_object('code','deterministic_simulator_unavailable','severity','BLOCKER','detail',v_provider_cap);
    END IF;
    -- dispatch configuration
    IF v_provider_cap IS NOT NULL
       AND COALESCE(v_provider_cap->>'dispatch_secret_status','MISSING') = 'MISSING' THEN
      v_blockers := v_blockers || jsonb_build_object('code','dispatch_configuration_missing','severity','BLOCKER');
    END IF;
  END IF;

  -- Classify status
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) x
             WHERE x->>'code' IN ('from_email_missing','provider_missing','sender_disabled')) THEN
    v_status := 'BLOCKED_CONFIGURATION'; v_reason := 'Sender lacks required configuration.';
  ELSIF jsonb_array_length(v_blockers) > 0 THEN
    v_status := CASE v_kind WHEN 'REAL_EMAIL_READY' THEN 'BLOCKED_VERIFICATION' ELSE 'BLOCKED_CONFIGURATION' END;
    v_reason := 'Requirements insufficient for '||v_kind||'.';
  ELSIF v_kind='REAL_EMAIL_READY' THEN
    v_status := 'REAL_EMAIL_READY'; v_reason := 'Sender meets real-email verification and provider capability requirements.';
  ELSE
    v_status := 'TEST_READY'; v_reason := 'Sender meets deterministic simulator test requirements.';
  END IF;

  -- Configuration-only sender_version (SHA-256, no kind)
  v_sender_cfg := jsonb_build_object(
    'profile_id', v.id::text, 'profile_code', v.profile_code,
    'from_email', v.from_email, 'display_name', v.display_name,
    'reply_to_email', v.reply_to_email,
    'provider_code', v.provider_code,
    'is_enabled', v.is_enabled, 'is_default', v.is_default,
    'sender_category', v.sender_category,
    'audience_type', v.audience_type, 'risk_level', v.risk_level);
  v_sender_ver := public.comm_hub_evidence_hash('comm-hub/sender-configuration/v1', v_sender_cfg);

  -- Verification evidence version (SHA-256, no secrets)
  v_verif := jsonb_build_object(
    'provider_identity_status', v.provider_identity_status,
    'provider_identity_id', v.provider_identity_id,
    'domain_verified', v.domain_verified,
    'spf_status', v.spf_status, 'dkim_status', v.dkim_status, 'dmarc_status', v.dmarc_status,
    'last_checked_at', v.last_checked_at,
    'verification_source_version','sender-verification-source/v1');
  v_verif_ver := public.comm_hub_evidence_hash('comm-hub/sender-verification-evidence/v1', v_verif);

  v_evidence := jsonb_build_object(
    'sender_configuration', v_sender_cfg,
    'verification_evidence', v_verif,
    'provider_capability_evidence', v_provider_cap,
    'readiness_kind', v_kind,
    'blockers', v_blockers, 'warnings', v_warnings, 'advisories', v_advisories);
  v_hash := public.comm_hub_evidence_hash('comm-hub/sender-readiness-evidence/v1', v_evidence);
  v_expires := now() + interval '30 days';

  -- Mark prior current row(s) for this profile+kind as stale
  UPDATE public.comm_hub_sender_readiness
     SET is_stale = true,
         stale_reason = coalesce(stale_reason,'SUPERSEDED')
   WHERE sender_profile_id = v.id
     AND readiness_kind = v_kind
     AND is_stale = false;

  INSERT INTO public.comm_hub_sender_readiness (
    id, sender_profile_id, sender_version, readiness_state, readiness_details, computed_at,
    is_stale, readiness_kind, verification_evidence_version, provider_code, evidence_hash,
    expires_at, blockers, warnings, advisories, computed_by, reason
  ) VALUES (
    gen_random_uuid(), v.id, v_sender_ver, v_status::comm_hub_sender_readiness_state,
    v_evidence, now(), false, v_kind, v_verif_ver, v.provider_code, v_hash,
    v_expires, v_blockers, v_warnings, v_advisories, auth.uid(), v_reason
  ) RETURNING id INTO v_result_id;

  RETURN jsonb_build_object('readiness_id', v_result_id, 'sender_profile_id', v.id,
    'profile_code', v.profile_code, 'readiness_kind', v_kind,
    'status', v_status, 'reason', v_reason,
    'sender_version', v_sender_ver,
    'verification_evidence_version', v_verif_ver,
    'evidence_hash', v_hash,
    'provider_capability_state', v_prov_state,
    'blockers', v_blockers, 'warnings', v_warnings, 'advisories', v_advisories,
    'expires_at', v_expires);
END $function$;
CREATE OR REPLACE FUNCTION public.confirm_comm_hub_manual_production_observation(p_observation_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_obs       record;
  v_msg       record;
  v_att       record;
  v_provider  record;
  v_ec        record;
  v_trace_ok  boolean := false;
  v_blockers  jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'authentication_required'));
  END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'not_comm_hub_admin'));
  END IF;
  IF p_decision NOT IN ('CONFIRMED','NOT_RECEIVED') THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'invalid_decision'));
  END IF;

  SELECT * INTO v_obs FROM public.communication_manual_production_observation
    WHERE id = p_observation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'observation_not_found'));
  END IF;

  IF v_obs.inbox_confirmation_status = p_decision THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', true,
      'observation_id', v_obs.id,
      'inbox_confirmation_status', v_obs.inbox_confirmation_status,
      'status', v_obs.status);
  END IF;

  IF v_obs.inbox_confirmation_status IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'blockers', public._comm_hub_append_blocker('[]'::jsonb,'inbox_already_decided'));
  END IF;

  IF p_decision = 'NOT_RECEIVED' THEN
    UPDATE public.communication_manual_production_observation
       SET inbox_confirmation_status = 'NOT_RECEIVED',
           inbox_confirmed_at = now(), inbox_confirmed_by = v_uid,
           inbox_confirmation_note = p_note, status = 'FAILED', updated_at = now()
     WHERE id = p_observation_id;
    RETURN jsonb_build_object('ok', true, 'observation_id', p_observation_id,
      'inbox_confirmation_status', 'NOT_RECEIVED', 'status', 'FAILED');
  END IF;

  IF v_obs.send_context IS DISTINCT FROM 'manual_production' THEN
    v_blockers := public._comm_hub_append_blocker(v_blockers, 'send_context_not_manual_production');
  END IF;
  IF NOT COALESCE(v_obs.provider_call_attempted, false) THEN
    v_blockers := public._comm_hub_append_blocker(v_blockers, 'provider_call_not_attempted');
  END IF;
  IF v_obs.provider_message_id IS NULL OR length(v_obs.provider_message_id) = 0 THEN
    v_blockers := public._comm_hub_append_blocker(v_blockers, 'provider_message_id_missing');
  END IF;
  IF v_obs.delivery_attempt_id IS NULL THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'delivery_attempt_missing'); END IF;
  IF v_obs.trace_id            IS NULL THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'trace_missing'); END IF;
  IF v_obs.message_id          IS NULL THEN v_blockers := public._comm_hub_append_blocker(v_blockers,'message_missing'); END IF;

  IF v_obs.message_id IS NOT NULL THEN
    SELECT * INTO v_msg FROM public.communication_message WHERE id = v_obs.message_id;
    IF NOT FOUND THEN
      v_blockers := public._comm_hub_append_blocker(v_blockers,'message_row_missing');
    ELSE
      IF v_msg.status NOT IN ('sent','delivered') THEN
        v_blockers := public._comm_hub_append_blocker(v_blockers,'message_not_sent_or_delivered');
      END IF;
      IF COALESCE(v_msg.test_mode, false) THEN
        v_blockers := public._comm_hub_append_blocker(v_blockers,'message_test_mode_true');
      END IF;
    END IF;
  END IF;

  IF v_obs.delivery_attempt_id IS NOT NULL THEN
    SELECT * INTO v_att FROM public.communication_delivery_attempt WHERE id = v_obs.delivery_attempt_id;
    IF NOT FOUND THEN
      v_blockers := public._comm_hub_append_blocker(v_blockers,'attempt_row_missing');
    ELSE
      IF v_att.status NOT IN ('success','delivered','sent') THEN
        v_blockers := public._comm_hub_append_blocker(v_blockers,'attempt_not_successful');
      END IF;
      IF v_att.send_context IS DISTINCT FROM 'manual_production' THEN
        v_blockers := public._comm_hub_append_blocker(v_blockers,'attempt_send_context_not_manual_production');
      END IF;
      IF v_att.provider_id IS NOT NULL THEN
        SELECT * INTO v_provider FROM public.notification_providers WHERE id = v_att.provider_id;
        IF FOUND AND lower(coalesce(v_provider.email_provider_type,'')) IN ('stub','dry_run','dryrun','test') THEN
          v_blockers := public._comm_hub_append_blocker(v_blockers,'provider_is_stub_or_dry_run');
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_obs.trace_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM public.communication_hub_trace WHERE id = v_obs.trace_id) INTO v_trace_ok;
    IF NOT v_trace_ok THEN
      v_blockers := public._comm_hub_append_blocker(v_blockers,'trace_row_missing');
    END IF;
  END IF;

  IF v_obs.event_certification_id IS NOT NULL THEN
    SELECT * INTO v_ec FROM public.communication_hub_event_certification WHERE id = v_obs.event_certification_id;
    IF NOT FOUND THEN
      v_blockers := public._comm_hub_append_blocker(v_blockers,'event_certification_missing');
    ELSE
      IF v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
        v_blockers := public._comm_hub_append_blocker(v_blockers,'event_not_manually_certified');
      END IF;
      IF v_obs.dispatched_at <= v_ec.approved_at THEN
        v_blockers := public._comm_hub_append_blocker(v_blockers,'observation_predates_manual_approval');
      END IF;
    END IF;
  END IF;

  IF jsonb_array_length(v_blockers) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'blockers', v_blockers);
  END IF;

  UPDATE public.communication_manual_production_observation
     SET inbox_confirmation_status = 'CONFIRMED',
         inbox_confirmed_at = now(), inbox_confirmed_by = v_uid,
         inbox_confirmation_note = p_note, status = 'CONFIRMED', updated_at = now()
   WHERE id = p_observation_id;

  RETURN jsonb_build_object('ok', true, 'observation_id', p_observation_id,
    'inbox_confirmation_status', 'CONFIRMED', 'status', 'CONFIRMED');
END $function$;
CREATE OR REPLACE FUNCTION public.consume_comm_hub_controlled_live_grant(p_grant_id uuid, p_consumed_by uuid, p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN jsonb_build_object('allowed',false,'blockers',
    jsonb_build_array(jsonb_build_object(
      'code','LEGACY_GRANT_API_DISABLED',
      'message','Legacy consume overload is disabled. Use hardened consume_comm_hub_controlled_live_grant(uuid,uuid,uuid,uuid,text).'
    )));
END; $function$;
CREATE OR REPLACE FUNCTION public.consume_comm_hub_controlled_live_grant(p_grant_id uuid, p_execution_id uuid, p_message_id uuid, p_expected_correlation_id uuid, p_service_operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g record; v_msg_exec uuid; v_evidence_count int;
BEGIN
  IF p_service_operation IS DISTINCT FROM 'DISPATCH_CONTROLLED_STUB' THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','SERVICE_OPERATION_INVALID',
        'message','p_service_operation must be DISPATCH_CONTROLLED_STUB',
        'detail', jsonb_build_object('supplied', p_service_operation)))); END IF;
  v_svc := public._comm_hub_assert_bound_service_operation('comm-hub-dispatch','DISPATCH_CONTROLLED_STUB');
  IF NOT COALESCE((v_svc->>'allowed')::bool, false) THEN
    RETURN jsonb_build_object('allowed', false, 'blockers', v_svc->'blockers'); END IF;
  SELECT g.*, s.correlation_id AS snap_correlation INTO v_g
    FROM public.communication_controlled_live_grant g
    JOIN public.communication_preview_approval a ON a.id = g.preview_approval_id
    JOIN public.communication_preview_snapshot s ON s.id = a.snapshot_id
   WHERE g.id = p_grant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_NOT_FOUND','message','Grant not found'))); END IF;
  IF v_g.status::text = 'CONSUMED' THEN RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status','CONSUMED','idempotent', true); END IF;
  IF v_g.status::text <> 'RESERVED' THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_STATE_INVALID','message','Not RESERVED',
      'detail', jsonb_build_object('status', v_g.status)))); END IF;
  IF v_g.execution_id IS DISTINCT FROM p_execution_id THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_EXECUTION_MISMATCH','message','Execution mismatch'))); END IF;
  IF p_expected_correlation_id IS NOT NULL AND v_g.snap_correlation IS DISTINCT FROM p_expected_correlation_id THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_CORRELATION_MISMATCH','message','Correlation mismatch'))); END IF;
  IF p_message_id IS NULL THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_MESSAGE_BINDING_MISMATCH','message','Message id required'))); END IF;
  SELECT controlled_live_execution_id INTO v_msg_exec FROM public.communication_message WHERE id = p_message_id;
  IF v_msg_exec IS DISTINCT FROM p_execution_id THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_MESSAGE_BINDING_MISMATCH','message','Message not bound to execution'))); END IF;
  SELECT count(*) INTO v_evidence_count FROM public.communication_delivery_attempt
   WHERE message_id = p_message_id AND attempt_type='controlled_live'
     AND provider_call_attempted=true
     AND provider_status IN ('PROVIDER_ACCEPTED','DELIVERY_PENDING','PROVIDER_REJECTED');
  IF v_evidence_count <> 1 THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_MESSAGE_BINDING_MISMATCH',
      'message','Message must have exactly one durable provider-attempted attempt',
      'detail', jsonb_build_object('count', v_evidence_count)))); END IF;
  UPDATE public.communication_controlled_live_grant
     SET status='CONSUMED', consumed_at=now(), updated_at=now() WHERE id = v_g.id;
  RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'CONSUMED');
END; $function$;
CREATE OR REPLACE FUNCTION public.consume_comm_hub_controlled_live_grant(p_grant_id uuid, p_execution_id uuid, p_provider_invocation_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row communication_controlled_live_grant%rowtype;
  v_started boolean;
begin
  select * into v_row from communication_controlled_live_grant where id = p_grant_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'grant_not_found'); end if;
  if v_row.execution_id <> p_execution_id then
    return jsonb_build_object('ok', false, 'code', 'grant_execution_mismatch');
  end if;
  if v_row.status = 'CONSUMED' then
    return jsonb_build_object('ok', true, 'status', 'CONSUMED', 'idempotent', true);
  end if;
  if v_row.status <> 'RESERVED' then
    return jsonb_build_object('ok', false, 'code', 'grant_not_reserved', 'status', v_row.status);
  end if;
  select provider_call_attempted into v_started
    from communication_controlled_live_execution where id = p_execution_id;
  if not coalesce(v_started, false) then
    return jsonb_build_object('ok', false, 'code', 'provider_call_not_attempted');
  end if;
  update communication_controlled_live_grant
     set status = 'CONSUMED', consumed_at = now(),
         audit_metadata = coalesce(audit_metadata,'{}'::jsonb)
           || jsonb_build_object('consumed_at', now(), 'provider_invocation_key', p_provider_invocation_key)
   where id = p_grant_id and status = 'RESERVED';
  return jsonb_build_object('ok', true, 'status', 'CONSUMED');
end $function$;
CREATE OR REPLACE FUNCTION public.consume_comm_hub_one_real_email_grant(p_grant_id uuid, p_execution_id uuid, p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g public.communication_controlled_live_grant%ROWTYPE;
        v_msg_exec uuid;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-send-one-real-email','DISPATCH_ONE_REAL_EMAIL');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('allowed', false, 'blockers', v_svc->'blockers');
  END IF;

  SELECT * INTO v_g FROM public.communication_controlled_live_grant WHERE id=p_grant_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_NOT_FOUND')));
  END IF;
  IF v_g.execution_id <> p_execution_id THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_EXECUTION_MISMATCH')));
  END IF;
  IF v_g.send_context <> 'REAL_EMAIL' THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_NOT_REAL_EMAIL')));
  END IF;
  IF v_g.status = 'CONSUMED' THEN
    RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'CONSUMED',
      'idempotent_replay', true);
  END IF;
  IF v_g.status <> 'RESERVED' THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_STATE_INVALID','detail',
        jsonb_build_object('status', v_g.status))));
  END IF;

  SELECT controlled_live_execution_id INTO v_msg_exec
    FROM public.communication_message WHERE id = p_message_id;
  IF v_msg_exec IS NULL OR v_msg_exec <> p_execution_id THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','MESSAGE_EXECUTION_MISMATCH')));
  END IF;

  UPDATE public.communication_controlled_live_grant
     SET status='CONSUMED', consumed_at=now(), updated_at=now()
   WHERE id=v_g.id;
  RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'CONSUMED');
END $function$;
CREATE OR REPLACE FUNCTION public.consume_comm_hub_preview_approval(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appr_id uuid := (p_payload->>'approval_id')::uuid;
  v_token uuid := nullif(p_payload->>'reservation_token','')::uuid;
  v_req_id uuid := nullif(p_payload->>'request_id','')::uuid;
  v_now timestamptz := now();
BEGIN
  IF v_appr_id IS NULL THEN RAISE EXCEPTION 'approval_id is required'; END IF;
  IF v_token IS NULL THEN RAISE EXCEPTION 'reservation_token is required'; END IF;

  UPDATE public.communication_preview_approval
     SET status='CONSUMED', consumed_at=v_now, consumed_by=v_uid, consumed_request_id=v_req_id
   WHERE id=v_appr_id AND status='RESERVED' AND reservation_token=v_token;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approval_not_consumable';
  END IF;
  RETURN jsonb_build_object('ok',true,'approval_id',v_appr_id,'status','CONSUMED','consumed_at',v_now);
END;
$function$;
CREATE OR REPLACE FUNCTION public.convert_application_atomic(p_unique_uuid uuid, p_application_id character varying, p_application_ref_number character varying, p_temp_ssn character varying, p_name_prefix character varying, p_firstname character varying, p_middle_name character varying, p_second_middle_name character varying, p_surname character varying, p_name_suffix character varying, p_previous_name character varying, p_alias character varying, p_sex character, p_dob date, p_birth_place character varying, p_nationality character varying, p_marital_status character varying, p_date_married date, p_heightfeet numeric, p_heightinches numeric, p_eyecolor character varying, p_resident_addr1 character varying, p_resident_addr2 character varying, p_district character varying, p_mail_addr1 character varying, p_mail_addr2 character varying, p_email_addr character varying, p_phone character varying, p_phone_mobile character varying, p_contact character varying, p_contact_relation character varying, p_contact_addr1 character varying, p_contact_addr2 character varying, p_contact_phone character varying, p_contact_mobile character varying, p_contact_email character varying, p_father_name character varying, p_mother_name character varying, p_spouse_name character varying, p_spouse_addr1 character varying, p_spouse_addr2 character varying, p_spouse_ssn character varying, p_spouse_dob date, p_witness_name character varying, p_date_witnessed date, p_beneficiary character varying, p_ben_addr1 character varying, p_ben_addr2 character varying, p_primary_occup character varying, p_work_permit character varying, p_work_permit_expiration date, p_npf character varying, p_citizenship_flag character varying, p_ip_signature character varying, p_application_date date, p_date_of_residency date, p_place_of_residence character varying, p_employer_name character varying, p_employer_address character varying, p_employer_phone character varying, p_employer_town character varying, p_photo_location text, p_remarks text, p_entered_by character varying, p_created_by uuid, p_dependants jsonb DEFAULT '[]'::jsonb, p_documents jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_master_id            UUID;
  v_submit_result        JSONB;
  v_final_ssn            VARCHAR(6);
  v_dep                  JSONB;
  v_dep_idx              INT := 0;
  v_depend_id            VARCHAR(6);
  v_dep_sex              CHAR(1);
  v_dep_relation         VARCHAR(3);
  v_dep_dob              DATE;
  v_dep_ssn              VARCHAR(6);
  v_dependants_added     INT := 0;
  v_doc                  JSONB;
  v_docs_added           INT := 0;
  v_master_docs_mirrored INT := 0;
  v_uploaded_at          TIMESTAMPTZ;
  v_record_name          TEXT;
  v_workflow_instance_id UUID;
  v_doc_count            INT;
BEGIN
  v_doc_count := COALESCE(jsonb_array_length(p_documents), 0);
  RAISE LOG '[convert_application_atomic] Received % document(s) for app_ref=%', v_doc_count, p_application_ref_number;

  IF NULLIF(TRIM(p_application_ref_number), '') IS NULL THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: application_reference_number is required for conversion';
  END IF;

  IF EXISTS (SELECT 1 FROM ip_master WHERE application_id = p_application_id) THEN
    RAISE EXCEPTION 'DUPLICATE_APPLICATION: Application ID % has already been converted', p_application_id;
  END IF;

  INSERT INTO ip_master (
    unique_uuid, application_id, application_reference_number, temp_ssn, status,
    name_prefix, firstname, middle_name, second_middle_name,
    surname, name_suffix, previous_name, alias,
    sex, dob, birth_place, nationality,
    marital_status, date_married,
    heightfeet, heightinches, eyecolor,
    resident_addr1, resident_addr2, district,
    mail_addr1, mail_addr2,
    email_addr, telephone, mobile, phone, phone_mobile,
    contact, contact_relation, contact_addr1, contact_addr2,
    contact_phone, contact_mobile, contact_email,
    father_name, mother_name,
    spouse_name, spouse_addr1, spouse_addr2, spouse_ssn, spouse_dob,
    witness_name, date_witnessed,
    beneficiary, ben_addr1, ben_addr2,
    primary_occup, work_permit, work_permit_expiration,
    npf, citizenship_flag, citizenship,
    ip_signature, application_date, date_of_residency, place_of_residence,
    employer_name, employer_address, employer_phone, employer_town,
    photo_location, application_remarks,
    entered_by, created_by, updated_by, created_at, updated_at
  ) VALUES (
    p_unique_uuid, p_application_id, TRIM(p_application_ref_number), p_temp_ssn, 'Z',
    NULLIF(p_name_prefix,''), p_firstname, NULLIF(p_middle_name,''), NULLIF(p_second_middle_name,''),
    p_surname, NULLIF(p_name_suffix,''), NULLIF(p_previous_name,''), NULLIF(p_alias,''),
    p_sex, p_dob, NULLIF(p_birth_place,''), p_nationality,
    p_marital_status, p_date_married,
    p_heightfeet, p_heightinches, NULLIF(p_eyecolor,''),
    NULLIF(p_resident_addr1,''), NULLIF(p_resident_addr2,''), NULLIF(p_district,''),
    NULLIF(p_mail_addr1,''), NULLIF(p_mail_addr2,''),
    NULLIF(p_email_addr,''), NULLIF(p_phone,''), NULLIF(p_phone_mobile,''), NULLIF(p_phone,''), NULLIF(p_phone_mobile,''),
    NULLIF(p_contact,''), NULLIF(p_contact_relation,''), NULLIF(p_contact_addr1,''), NULLIF(p_contact_addr2,''),
    NULLIF(p_contact_phone,''), NULLIF(p_contact_mobile,''), NULLIF(p_contact_email,''),
    NULLIF(p_father_name,''), NULLIF(p_mother_name,''),
    NULLIF(p_spouse_name,''), NULLIF(p_spouse_addr1,''), NULLIF(p_spouse_addr2,''), NULLIF(p_spouse_ssn,''), p_spouse_dob,
    NULLIF(p_witness_name,''), p_date_witnessed,
    NULLIF(p_beneficiary,''), NULLIF(p_ben_addr1,''), NULLIF(p_ben_addr2,''),
    NULLIF(p_primary_occup,''), COALESCE(p_work_permit,'N'), p_work_permit_expiration,
    COALESCE(p_npf,'N'), COALESCE(p_citizenship_flag,'N'), COALESCE(p_citizenship_flag,'N'),
    'N', COALESCE(p_application_date, CURRENT_DATE), p_date_of_residency, NULLIF(p_place_of_residence,''),
    NULLIF(p_employer_name,''), NULLIF(p_employer_address,''), NULLIF(p_employer_phone,''), NULLIF(p_employer_town,''),
    NULLIF(p_photo_location,''), NULLIF(LEFT(TRIM(COALESCE(p_remarks,'')),250),''),
    p_entered_by, p_created_by, p_created_by, NOW(), NOW()
  ) RETURNING id INTO v_master_id;

  IF v_master_id IS NULL THEN
    RAISE EXCEPTION 'INSERT_FAILED: ip_master insert returned no ID';
  END IF;

  SELECT submit_ip_registration(p_unique_uuid) INTO v_submit_result;
  IF v_submit_result IS NULL OR NOT (v_submit_result->>'success')::BOOLEAN THEN
    RAISE EXCEPTION 'SUBMIT_FAILED: %', COALESCE(v_submit_result->>'message', 'submit_ip_registration returned failure');
  END IF;

  v_final_ssn := v_submit_result->>'ssn';
  IF v_final_ssn IS NULL OR LENGTH(v_final_ssn) = 0 THEN
    RAISE EXCEPTION 'SUBMIT_FAILED: submit_ip_registration succeeded but returned no SSN';
  END IF;

  -- Dependants
  FOR v_dep IN SELECT * FROM jsonb_array_elements(p_dependants)
  LOOP
    v_dep_idx := v_dep_idx + 1;
    IF NULLIF(TRIM(v_dep->>'firstName'),'') IS NULL AND NULLIF(TRIM(v_dep->>'lastName'),'') IS NULL THEN CONTINUE; END IF;
    SELECT generate_depend_id(v_final_ssn) INTO v_depend_id;
    v_depend_id := COALESCE(v_depend_id, LPAD(v_dep_idx::TEXT, 6, '0'));
    v_dep_sex := CASE WHEN UPPER(v_dep->>'gender') IN ('M','MALE') THEN 'M' WHEN UPPER(v_dep->>'gender') IN ('F','FEMALE') THEN 'F' ELSE 'N' END;
    v_dep_relation := NULL;
    IF v_dep->>'relationCode' IS NOT NULL AND LENGTH(TRIM(v_dep->>'relationCode')) > 0 THEN
      SELECT code INTO v_dep_relation FROM tb_relation WHERE UPPER(code) = UPPER(TRIM(LEFT(v_dep->>'relationCode', 3))) LIMIT 1;
    END IF;
    BEGIN v_dep_dob := (v_dep->>'dob')::DATE; EXCEPTION WHEN OTHERS THEN v_dep_dob := NULL; END;
    v_dep_ssn := NULLIF(TRIM(LEFT(COALESCE(v_dep->>'depSsn',''),6)),'');
    INSERT INTO ip_depend (ssn, depend_id, depend_ssn, surname, firstname, middle_name, dob, sex, relation, depend_addr1, depend_addr2, school_child, invalid, status, userid, tran_code, date_modified)
    VALUES (v_final_ssn, v_depend_id, v_dep_ssn,
      NULLIF(TRIM(LEFT(COALESCE(v_dep->>'lastName',''),25)),''), NULLIF(TRIM(LEFT(COALESCE(v_dep->>'firstName',''),25)),''), NULLIF(TRIM(LEFT(COALESCE(v_dep->>'middleName',''),25)),''),
      v_dep_dob, v_dep_sex, v_dep_relation,
      NULLIF(TRIM(LEFT(COALESCE(v_dep->>'address',''),50)),''), NULLIF(TRIM(LEFT(COALESCE(v_dep->>'address1',''),50)),''),
      CASE WHEN (v_dep->>'isInSchool')::BOOLEAN THEN 'Y' ELSE 'N' END, CASE WHEN (v_dep->>'isInvalid')::BOOLEAN THEN 'Y' ELSE 'N' END,
      'P', NULLIF(LEFT(COALESCE(v_dep->>'userCode', p_entered_by,''),5),''), 'ADD', NOW());
    v_dependants_added := v_dependants_added + 1;
  END LOOP;

  -- Insert into ip_application_documents (staging/audit)
  IF p_documents IS NOT NULL AND jsonb_array_length(p_documents) > 0 THEN
    RAISE LOG '[convert_application_atomic] Inserting % staging document(s) for SSN=% app_ref=%',
      jsonb_array_length(p_documents), v_final_ssn, p_application_ref_number;
    FOR v_doc IN SELECT * FROM jsonb_array_elements(p_documents) LOOP
      BEGIN v_uploaded_at := (v_doc->>'uploadedAt')::TIMESTAMPTZ; EXCEPTION WHEN OTHERS THEN v_uploaded_at := NOW(); END;
      BEGIN
        INSERT INTO ip_application_documents (
          ssn, application_reference_number, document_name, document_type, file_name, file_path, url, signed_url,
          mime_type, file_size, uploaded_at, source_document_id, verification_type, verification_category,
          is_supportive, supportive_doc_type, metadata, created_by, version, is_active
        )
        VALUES (
          v_final_ssn,
          NULLIF(TRIM(p_application_ref_number), ''),
          NULLIF(TRIM(COALESCE(v_doc->>'name', v_doc->>'fileName','')),''),
          NULLIF(TRIM(COALESCE(v_doc->>'documentType', v_doc->>'type','')),''),
          NULLIF(TRIM(COALESCE(v_doc->>'fileName', v_doc->>'name','')),''),
          NULLIF(TRIM(v_doc->>'filePath'),''),
          NULLIF(TRIM(v_doc->>'url'),''),
          NULLIF(TRIM(v_doc->>'signedUrl'),''),
          NULLIF(TRIM(v_doc->>'mimeType'),''),
          CASE WHEN v_doc->>'fileSize' IS NOT NULL AND v_doc->>'fileSize' ~ '^\d+$' THEN (v_doc->>'fileSize')::BIGINT ELSE NULL END,
          v_uploaded_at,
          NULLIF(TRIM(v_doc->>'id'),''),
          NULLIF(TRIM(COALESCE(v_doc->>'verificationType', v_doc->>'verification_type','')),''),
          NULLIF(TRIM(COALESCE(v_doc->>'verificationType', v_doc->>'verification_type','')),''),
          COALESCE((v_doc->>'isSupportive')::BOOLEAN, FALSE),
          NULLIF(TRIM(COALESCE(v_doc->>'supportiveDocType','')),''),
          CASE WHEN v_doc ? 'metadata' THEN v_doc->'metadata' ELSE NULL END,
          p_created_by,
          1, TRUE
        );
        v_docs_added := v_docs_added + 1;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'DOCUMENT_INSERT_FAILED: Failed to insert document "%" — %',
          COALESCE(v_doc->>'name', v_doc->>'fileName', 'unknown'), SQLERRM;
      END;
    END LOOP;
    RAISE LOG '[convert_application_atomic] Successfully inserted % staging document(s)', v_docs_added;
  END IF;

  -- Inline mirror to ip_documents (master) — same transaction
  BEGIN
    INSERT INTO ip_documents (
      unique_uuid, ssn, document_type, document_name, doc_code,
      file_name, file_path, mime_type, file_size, uploaded_at, uploaded_by,
      verification_type, verification_category, is_supportive, supportive_doc_type,
      source_document_id, application_reference_number, is_active, transfer_status, metadata
    )
    SELECT
      p_unique_uuid,
      iad.ssn,
      iad.document_type,
      iad.document_name,
      COALESCE(iad.metadata->>'doc_code', NULL),
      iad.file_name,
      iad.file_path,
      iad.mime_type,
      iad.file_size,
      iad.uploaded_at,
      p_created_by,
      iad.verification_type,
      iad.verification_category,
      COALESCE(iad.is_supportive, FALSE),
      iad.supportive_doc_type,
      iad.source_document_id,
      iad.application_reference_number,
      TRUE,
      'Pending',
      iad.metadata
    FROM ip_application_documents iad
    WHERE iad.application_reference_number = TRIM(p_application_ref_number)
      AND COALESCE(iad.is_active, TRUE) = TRUE
      AND COALESCE(iad.is_deleted, FALSE) = FALSE
      AND COALESCE(iad.file_path, iad.url, '') <> ''
      AND NOT EXISTS (
        SELECT 1 FROM ip_documents d
         WHERE d.unique_uuid = p_unique_uuid
           AND COALESCE(d.source_document_id, '') = COALESCE(iad.source_document_id, '')
           AND COALESCE(d.file_path, '') = COALESCE(iad.file_path, '')
      );

    GET DIAGNOSTICS v_master_docs_mirrored = ROW_COUNT;
    RAISE LOG '[convert_application_atomic] Mirrored % doc(s) into ip_documents for SSN=%', v_master_docs_mirrored, v_final_ssn;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'MASTER_DOC_MIRROR_FAILED: %', SQLERRM;
  END;

  -- Workflow
  v_record_name := TRIM(COALESCE(p_firstname, '') || ' ' || COALESCE(p_surname, ''));
  v_workflow_instance_id := initiate_ip_registration_workflow(
    p_unique_uuid,
    v_final_ssn,
    v_record_name,
    p_created_by,
    COALESCE(p_entered_by, 'SYSTEM'),
    'online_application_conversion'
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'ssn', v_final_ssn,
    'ip_master_id', v_master_id,
    'unique_uuid', p_unique_uuid,
    'dependants_added', v_dependants_added,
    'documents_added', v_docs_added,
    'master_documents_mirrored', v_master_docs_mirrored,
    'application_reference_number', TRIM(p_application_ref_number),
    'workflow_instance_id', v_workflow_instance_id,
    'message', 'IP Registration created successfully. SSN: ' || v_final_ssn ||
      CASE WHEN v_dependants_added > 0 THEN ' (' || v_dependants_added || ' dependant(s) linked)' ELSE '' END ||
      CASE WHEN v_docs_added > 0 THEN ' (' || v_docs_added || ' document(s) saved, ' || v_master_docs_mirrored || ' mirrored to master)' ELSE '' END ||
      CASE WHEN v_workflow_instance_id IS NOT NULL THEN ' [Workflow initiated]' ELSE '' END
  );
EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION '%', SQLERRM;
END;
$function$;
CREATE OR REPLACE FUNCTION public.convert_application_atomic(p_unique_uuid uuid, p_application_id character varying, p_application_ref_number character varying, p_temp_ssn character varying, p_name_prefix character varying, p_firstname character varying, p_middle_name character varying, p_second_middle_name character varying, p_surname character varying, p_name_suffix character varying, p_previous_name character varying, p_alias character varying, p_sex character, p_dob date, p_birth_place character varying, p_nationality character varying, p_marital_status character varying, p_date_married date, p_heightfeet numeric, p_heightinches numeric, p_eyecolor character varying, p_resident_addr1 character varying, p_resident_addr2 character varying, p_district character varying, p_mail_addr1 character varying, p_mail_addr2 character varying, p_email_addr character varying, p_phone character varying, p_phone_mobile character varying, p_contact character varying, p_contact_relation character varying, p_contact_addr1 character varying, p_contact_addr2 character varying, p_contact_phone character varying, p_contact_mobile character varying, p_contact_email character varying, p_father_name character varying, p_mother_name character varying, p_spouse_name character varying, p_spouse_addr1 character varying, p_spouse_addr2 character varying, p_spouse_ssn character varying, p_spouse_dob date, p_witness_name character varying, p_date_witnessed date, p_beneficiary character varying, p_ben_addr1 character varying, p_ben_addr2 character varying, p_primary_occup character varying, p_work_permit character varying, p_work_permit_expiration date, p_npf character varying, p_citizenship_flag character varying, p_ip_signature character varying, p_application_date date, p_date_of_residency date, p_place_of_residence character varying, p_employer_name character varying, p_employer_address character varying, p_employer_phone character varying, p_employer_town character varying, p_photo_location text, p_remarks text, p_entered_by character varying, p_created_by uuid, p_dependants jsonb DEFAULT '[]'::jsonb, p_documents jsonb DEFAULT '[]'::jsonb, p_doc_decisions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_master_id            UUID;
  v_submit_result        JSONB;
  v_final_ssn            VARCHAR(6);
  v_dep                  JSONB;
  v_dep_idx              INT := 0;
  v_depend_id            VARCHAR(6);
  v_dep_sex              CHAR(1);
  v_dep_relation         VARCHAR(3);
  v_dep_dob              DATE;
  v_dep_ssn              VARCHAR(6);
  v_dependants_added     INT := 0;
  v_doc                  JSONB;
  v_decision             JSONB;
  v_docs_added           INT := 0;
  v_master_docs_mirrored INT := 0;
  v_uploaded_at          TIMESTAMPTZ;
  v_record_name          TEXT;
  v_workflow_instance_id UUID;
  v_doc_count            INT;
BEGIN
  v_doc_count := COALESCE(jsonb_array_length(p_documents), 0);
  RAISE LOG '[convert_application_atomic] Received % document(s) for app_ref=%', v_doc_count, p_application_ref_number;

  IF NULLIF(TRIM(p_application_ref_number), '') IS NULL THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: application_reference_number is required for conversion';
  END IF;

  IF EXISTS (SELECT 1 FROM ip_master WHERE application_id = p_application_id) THEN
    RAISE EXCEPTION 'DUPLICATE_APPLICATION: Application ID % has already been converted', p_application_id;
  END IF;

  INSERT INTO ip_master (
    unique_uuid, application_id, application_reference_number, temp_ssn, status,
    name_prefix, firstname, middle_name, second_middle_name,
    surname, name_suffix, previous_name, alias,
    sex, dob, birth_place, nationality,
    marital_status, date_married,
    heightfeet, heightinches, eyecolor,
    resident_addr1, resident_addr2, district,
    mail_addr1, mail_addr2,
    email_addr, telephone, mobile, phone, phone_mobile,
    contact, contact_relation, contact_addr1, contact_addr2,
    contact_phone, contact_mobile, contact_email,
    father_name, mother_name,
    spouse_name, spouse_addr1, spouse_addr2, spouse_ssn, spouse_dob,
    witness_name, date_witnessed,
    beneficiary, ben_addr1, ben_addr2,
    primary_occup, work_permit, work_permit_expiration,
    npf, citizenship_flag, citizenship,
    ip_signature, application_date, date_of_residency, place_of_residence,
    employer_name, employer_address, employer_phone, employer_town,
    photo_location, application_remarks,
    entered_by, created_by, updated_by, created_at, updated_at
  ) VALUES (
    p_unique_uuid, p_application_id, TRIM(p_application_ref_number), p_temp_ssn, 'Z',
    p_name_prefix, p_firstname, p_middle_name, p_second_middle_name,
    p_surname, p_name_suffix, p_previous_name, p_alias,
    p_sex, p_dob, p_birth_place, p_nationality,
    p_marital_status, p_date_married,
    p_heightfeet, p_heightinches, p_eyecolor,
    p_resident_addr1, p_resident_addr2, p_district,
    p_mail_addr1, p_mail_addr2,
    p_email_addr, p_phone, p_phone_mobile, p_phone, p_phone_mobile,
    p_contact, p_contact_relation, p_contact_addr1, p_contact_addr2,
    p_contact_phone, p_contact_mobile, p_contact_email,
    p_father_name, p_mother_name,
    p_spouse_name, p_spouse_addr1, p_spouse_addr2, p_spouse_ssn, p_spouse_dob,
    p_witness_name, p_date_witnessed,
    p_beneficiary, p_ben_addr1, p_ben_addr2,
    p_primary_occup, p_work_permit, p_work_permit_expiration,
    p_npf, p_citizenship_flag, p_citizenship_flag,
    p_ip_signature, p_application_date, p_date_of_residency, p_place_of_residence,
    p_employer_name, p_employer_address, p_employer_phone, p_employer_town,
    p_photo_location, p_remarks,
    p_entered_by, p_created_by, p_created_by, NOW(), NOW()
  )
  RETURNING id, COALESCE(ssn, temp_ssn) INTO v_master_id, v_final_ssn;

  -- Submit (assigns permanent SSN if your existing flow does so)
  BEGIN
    v_submit_result := submit_ip_application(p_unique_uuid, p_created_by);
    IF v_submit_result IS NOT NULL AND (v_submit_result->>'ssn') IS NOT NULL THEN
      v_final_ssn := v_submit_result->>'ssn';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'SUBMIT_FAILED: %', SQLERRM;
  END;

  -- Dependants
  IF p_dependants IS NOT NULL AND jsonb_array_length(p_dependants) > 0 THEN
    FOR v_dep IN SELECT * FROM jsonb_array_elements(p_dependants) LOOP
      v_dep_idx := v_dep_idx + 1;
      v_depend_id := lpad(v_dep_idx::text, 6, '0');
      v_dep_sex   := COALESCE(NULLIF(v_dep->>'gender',''), 'N');
      v_dep_relation := NULLIF(TRIM(v_dep->>'relationCode'), '');
      BEGIN v_dep_dob := (v_dep->>'dob')::DATE; EXCEPTION WHEN OTHERS THEN v_dep_dob := NULL; END;
      v_dep_ssn := NULLIF(TRIM(v_dep->>'depSsn'), '');

      BEGIN
        INSERT INTO ip_depend (
          ssn, depend_id, depend_ssn, surname, firstname, middle_name_dep,
          dob, sex, relation, depend_addr1, depend_addr2,
          school_child, invalid, status, userid, tran_code, date_modified
        ) VALUES (
          v_final_ssn, v_depend_id, v_dep_ssn,
          NULLIF(TRIM(v_dep->>'lastName'), ''),
          NULLIF(TRIM(v_dep->>'firstName'), ''),
          NULLIF(TRIM(v_dep->>'middleName'), ''),
          v_dep_dob, v_dep_sex, v_dep_relation,
          NULLIF(TRIM(v_dep->>'address'),  ''),
          NULLIF(TRIM(v_dep->>'address1'), ''),
          CASE WHEN COALESCE((v_dep->>'isInSchool')::BOOLEAN, FALSE) THEN 'Y' ELSE 'N' END,
          CASE WHEN COALESCE((v_dep->>'isInvalid')::BOOLEAN,  FALSE) THEN 'Y' ELSE 'N' END,
          'P',
          NULLIF(v_dep->>'userCode', ''),
          'ADD',
          NOW()
        );
        v_dependants_added := v_dependants_added + 1;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'DEPENDANT_INSERT_FAILED: dep#% — %', v_dep_idx, SQLERRM;
      END;
    END LOOP;
  END IF;

  -- Insert into ip_application_documents (staging/audit)
  IF p_documents IS NOT NULL AND jsonb_array_length(p_documents) > 0 THEN
    RAISE LOG '[convert_application_atomic] Inserting % staging document(s) for SSN=% app_ref=%',
      jsonb_array_length(p_documents), v_final_ssn, p_application_ref_number;
    FOR v_doc IN SELECT * FROM jsonb_array_elements(p_documents) LOOP
      BEGIN v_uploaded_at := (v_doc->>'uploadedAt')::TIMESTAMPTZ; EXCEPTION WHEN OTHERS THEN v_uploaded_at := NOW(); END;
      BEGIN
        INSERT INTO ip_application_documents (
          ssn, application_reference_number, document_name, document_type, file_name, file_path, url, signed_url,
          mime_type, file_size, uploaded_at, source_document_id, verification_type, verification_category,
          is_supportive, supportive_doc_type, metadata, created_by, version, is_active
        )
        VALUES (
          v_final_ssn,
          NULLIF(TRIM(p_application_ref_number), ''),
          NULLIF(TRIM(COALESCE(v_doc->>'name', v_doc->>'fileName','')),''),
          NULLIF(TRIM(COALESCE(v_doc->>'documentType', v_doc->>'type','')),''),
          NULLIF(TRIM(COALESCE(v_doc->>'fileName', v_doc->>'name','')),''),
          NULLIF(TRIM(v_doc->>'filePath'),''),
          NULLIF(TRIM(v_doc->>'url'),''),
          NULLIF(TRIM(v_doc->>'signedUrl'),''),
          NULLIF(TRIM(v_doc->>'mimeType'),''),
          CASE WHEN v_doc->>'fileSize' IS NOT NULL AND v_doc->>'fileSize' ~ '^\d+$' THEN (v_doc->>'fileSize')::BIGINT ELSE NULL END,
          v_uploaded_at,
          NULLIF(TRIM(v_doc->>'id'),''),
          NULLIF(TRIM(COALESCE(v_doc->>'verificationType', v_doc->>'verification_type','')),''),
          NULLIF(TRIM(COALESCE(v_doc->>'verificationType', v_doc->>'verification_type','')),''),
          COALESCE((v_doc->>'isSupportive')::BOOLEAN, FALSE),
          NULLIF(TRIM(COALESCE(v_doc->>'supportiveDocType','')),''),
          CASE WHEN v_doc ? 'metadata' THEN v_doc->'metadata' ELSE NULL END,
          p_created_by,
          1, TRUE
        );
        v_docs_added := v_docs_added + 1;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'DOCUMENT_INSERT_FAILED: Failed to insert document "%" — %',
          COALESCE(v_doc->>'name', v_doc->>'fileName', 'unknown'), SQLERRM;
      END;
    END LOOP;
    RAISE LOG '[convert_application_atomic] Successfully inserted % staging document(s)', v_docs_added;
  END IF;

  -- Inline mirror to ip_documents (master) — same transaction
  BEGIN
    INSERT INTO ip_documents (
      unique_uuid, ssn, document_type, document_name, doc_code,
      file_name, file_path, mime_type, file_size, uploaded_at, uploaded_by,
      verification_type, verification_category, is_supportive, supportive_doc_type,
      source_document_id, application_reference_number, is_active, transfer_status, metadata
    )
    SELECT
      p_unique_uuid,
      iad.ssn,
      iad.document_type,
      iad.document_name,
      COALESCE(
        iad.metadata->>'doc_code',
        CASE WHEN iad.document_type IS NOT NULL AND char_length(iad.document_type) = 1
             THEN upper(iad.document_type) ELSE NULL END
      ),
      iad.file_name,
      iad.file_path,
      iad.mime_type,
      iad.file_size,
      iad.uploaded_at,
      p_created_by,
      iad.verification_type,
      iad.verification_category,
      COALESCE(iad.is_supportive, FALSE)
        OR COALESCE(iad.verification_category,'') = 'supportive'
        OR iad.supportive_doc_type IS NOT NULL,
      iad.supportive_doc_type,
      iad.source_document_id,
      iad.application_reference_number,
      TRUE,
      'Pending',
      iad.metadata
    FROM ip_application_documents iad
    WHERE iad.application_reference_number = TRIM(p_application_ref_number)
      AND COALESCE(iad.is_active, TRUE) = TRUE
      AND COALESCE(iad.is_deleted, FALSE) = FALSE
      AND COALESCE(iad.file_path, iad.url, '') <> ''
      AND NOT EXISTS (
        SELECT 1 FROM ip_documents d
         WHERE d.unique_uuid = p_unique_uuid
           AND COALESCE(d.source_document_id, '') = COALESCE(iad.source_document_id, '')
           AND COALESCE(d.file_path, '') = COALESCE(iad.file_path, '')
      );

    GET DIAGNOSTICS v_master_docs_mirrored = ROW_COUNT;
    RAISE LOG '[convert_application_atomic] Mirrored % doc(s) into ip_documents for SSN=%', v_master_docs_mirrored, v_final_ssn;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'MASTER_DOC_MIRROR_FAILED: %', SQLERRM;
  END;

  -- Persist merge audit decisions (one row per decision)
  IF p_doc_decisions IS NOT NULL AND jsonb_array_length(p_doc_decisions) > 0 THEN
    BEGIN
      FOR v_decision IN SELECT * FROM jsonb_array_elements(p_doc_decisions) LOOP
        INSERT INTO ip_application_doc_merge_audit (
          application_reference_number, ssn, unique_uuid, source_document_id,
          decision, before_snapshot, after_snapshot, created_by
        ) VALUES (
          TRIM(p_application_ref_number),
          v_final_ssn,
          p_unique_uuid,
          NULLIF(TRIM(v_decision->>'source_document_id'), ''),
          v_decision->>'decision',
          v_decision->'before_snapshot',
          v_decision->'after_snapshot',
          p_created_by
        );
      END LOOP;
    EXCEPTION WHEN OTHERS THEN
      RAISE LOG '[convert_application_atomic] Merge audit write failed (non-blocking): %', SQLERRM;
    END;
  END IF;

  -- Workflow
  v_record_name := TRIM(COALESCE(p_firstname, '') || ' ' || COALESCE(p_surname, ''));
  v_workflow_instance_id := initiate_ip_registration_workflow(
    p_unique_uuid,
    v_final_ssn,
    v_record_name,
    p_created_by,
    COALESCE(p_entered_by, 'SYSTEM'),
    'online_application_conversion'
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'ssn', v_final_ssn,
    'ip_master_id', v_master_id,
    'unique_uuid', p_unique_uuid,
    'dependants_added', v_dependants_added,
    'documents_added', v_docs_added,
    'master_documents_mirrored', v_master_docs_mirrored,
    'application_reference_number', TRIM(p_application_ref_number),
    'workflow_instance_id', v_workflow_instance_id,
    'message', 'IP Registration created successfully. SSN: ' || v_final_ssn ||
      CASE WHEN v_dependants_added > 0 THEN ' (' || v_dependants_added || ' dependant(s) linked)' ELSE '' END ||
      CASE WHEN v_docs_added > 0 THEN ' (' || v_docs_added || ' document(s) saved, ' || v_master_docs_mirrored || ' mirrored to master)' ELSE '' END ||
      CASE WHEN v_workflow_instance_id IS NOT NULL THEN ' [Workflow initiated]' ELSE '' END
  );
EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION '%', SQLERRM;
END;
$function$;
CREATE OR REPLACE FUNCTION public.convert_application_to_employer(p_application_reference text DEFAULT NULL::text, p_employer_name text DEFAULT NULL::text, p_trade_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_fax text DEFAULT NULL::text, p_hq_addr1 text DEFAULT NULL::text, p_hq_addr2 text DEFAULT NULL::text, p_maddr1 text DEFAULT NULL::text, p_maddr2 text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_mobile text DEFAULT NULL::text, p_office_code text DEFAULT 'STK'::text, p_ownership_code text DEFAULT NULL::text, p_sector_code text DEFAULT 'O'::text, p_industrial_code text DEFAULT '0000'::text, p_village_code text DEFAULT '000'::text, p_activity_type text DEFAULT NULL::text, p_inspector_code text DEFAULT 'UNK'::text, p_males_employed double precision DEFAULT NULL::double precision, p_females_employed double precision DEFAULT NULL::double precision, p_date_wages_first_paid text DEFAULT NULL::text, p_application_date text DEFAULT NULL::text, p_date_incorporated text DEFAULT NULL::text, p_date_of_acquisition text DEFAULT NULL::text, p_previous_owner text DEFAULT NULL::text, p_prev_owner_addr1 text DEFAULT NULL::text, p_prev_owner_addr2 text DEFAULT NULL::text, p_computer_payroll text DEFAULT 'N'::text, p_make_model text DEFAULT NULL::text, p_acquired_code text DEFAULT 'N'::text, p_parent_regno text DEFAULT NULL::text, p_registry_num text DEFAULT NULL::text, p_entered_by text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_owners_json text DEFAULT '[]'::text, p_locations_json text DEFAULT '[]'::text, p_notes_json text DEFAULT '[]'::text, p_documents_json text DEFAULT '[]'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_regno TEXT;
  v_owner JSONB;
  v_location JSONB;
  v_note JSONB;
  v_doc JSONB;
  v_staging RECORD;
  v_location_seq BIGINT := 0;
  v_owner_seq BIGINT := 0;
  v_note_seq BIGINT := 0;
  v_doc_count BIGINT := 0;
  v_master_count BIGINT := 0;
  v_owners_arr JSONB;
  v_locations_arr JSONB;
  v_notes_arr JSONB;
  v_docs_arr JSONB;
BEGIN
  IF p_application_reference IS NOT NULL AND p_application_reference <> '' THEN
    IF EXISTS (SELECT 1 FROM er_master WHERE registry_num = p_application_reference) THEN
      RETURN jsonb_build_object(
        'success', false,
        'message', 'An employer registration already exists for application reference: ' || p_application_reference
      );
    END IF;
  END IF;

  v_regno := public.generate_temp_er_regno();

  INSERT INTO er_master (
    regno, name, trade_name, phone, fax,
    hq_addr1, hq_addr2, maddr1, maddr2,
    email, mobile,
    office_code, ownership_code, sector_code, industrial_code, village_code,
    activity_type, inspector_code,
    males_employed, females_employed,
    date_wages_first_paid, application_date, date_incorporated, date_of_acquisition,
    previous_owner, prev_owner_addr1, prev_owner_addr2,
    computer_payroll, make_model, acquired_code,
    parent_regno, registry_num,
    status, entered_by, date_of_entry,
    arrears, legal_action
  ) VALUES (
    v_regno, COALESCE(p_employer_name, 'Unknown'), p_trade_name, p_phone, p_fax,
    p_hq_addr1, p_hq_addr2, p_maddr1, p_maddr2,
    p_email, p_mobile,
    COALESCE(p_office_code, 'STK'), p_ownership_code, COALESCE(p_sector_code, 'O'),
    COALESCE(p_industrial_code, '0000'), COALESCE(p_village_code, '000'),
    p_activity_type, COALESCE(p_inspector_code, 'UNK'),
    p_males_employed, p_females_employed,
    CASE WHEN p_date_wages_first_paid IS NOT NULL THEN p_date_wages_first_paid::timestamp ELSE NULL END,
    CASE WHEN p_application_date IS NOT NULL THEN p_application_date::timestamp ELSE now() END,
    CASE WHEN p_date_incorporated IS NOT NULL THEN p_date_incorporated::timestamp ELSE NULL END,
    CASE WHEN p_date_of_acquisition IS NOT NULL THEN p_date_of_acquisition::timestamp ELSE NULL END,
    p_previous_owner, p_prev_owner_addr1, p_prev_owner_addr2,
    COALESCE(p_computer_payroll, 'N'), p_make_model, COALESCE(p_acquired_code, 'N'),
    p_parent_regno, p_application_reference,
    'P', p_entered_by, now(), 'N', 'N'
  );

  v_owners_arr := p_owners_json::jsonb;
  IF jsonb_array_length(v_owners_arr) > 0 THEN
    FOR v_owner IN SELECT * FROM jsonb_array_elements(v_owners_arr) LOOP
      v_owner_seq := v_owner_seq + 1;
      INSERT INTO er_owner (regno, location_id, owner_id, name, title, phone, mobile, email, ssn)
      VALUES (v_regno, 0, v_owner_seq,
              v_owner->>'name', v_owner->>'title', v_owner->>'phone',
              v_owner->>'mobile', v_owner->>'email', v_owner->>'ssn');
    END LOOP;
  END IF;

  v_locations_arr := p_locations_json::jsonb;
  IF jsonb_array_length(v_locations_arr) > 0 THEN
    FOR v_location IN SELECT * FROM jsonb_array_elements(v_locations_arr) LOOP
      v_location_seq := v_location_seq + 1;
      INSERT INTO er_locations (regno, location_id, trade_name, loc_addr1, loc_addr2, activity_type)
      VALUES (v_regno, v_location_seq,
              v_location->>'trade_name', v_location->>'loc_addr1',
              v_location->>'loc_addr2', v_location->>'activity_type');
    END LOOP;
  END IF;

  v_notes_arr := p_notes_json::jsonb;
  IF jsonb_array_length(v_notes_arr) > 0 THEN
    FOR v_note IN SELECT * FROM jsonb_array_elements(v_notes_arr) LOOP
      v_note_seq := v_note_seq + 1;
      INSERT INTO er_notes (regno, seq_no, note, note_date, user_id)
      VALUES (v_regno, v_note_seq,
              v_note->>'note',
              CASE WHEN (v_note->>'note_date') IS NOT NULL THEN (v_note->>'note_date')::timestamp ELSE now() END,
              COALESCE(v_note->>'user_id', p_entered_by));
    END LOOP;
  END IF;

  -- Insert staging rows (er_application_documents)
  v_docs_arr := p_documents_json::jsonb;
  IF jsonb_array_length(v_docs_arr) > 0 THEN
    FOR v_doc IN SELECT * FROM jsonb_array_elements(v_docs_arr) LOOP
      v_doc_count := v_doc_count + 1;
      INSERT INTO er_application_documents (
        regno, source_application_reference,
        doc_code, document_type, document_description,
        file_name, file_path, storage_url, file_size, mime_type,
        uploaded_by, uploaded_by_code, transferred_by,
        is_active, metadata
      ) VALUES (
        v_regno, COALESCE(p_application_reference, ''),
        v_doc->>'doc_code', v_doc->>'document_type', v_doc->>'document_description',
        COALESCE(v_doc->>'file_name', 'unknown'),
        COALESCE(v_doc->>'file_path', ''),
        COALESCE(v_doc->>'storage_url', ''),
        (v_doc->>'file_size')::bigint,
        v_doc->>'mime_type',
        v_doc->>'uploaded_by', v_doc->>'uploaded_by_code', p_entered_by,
        true,
        CASE WHEN v_doc->'metadata' IS NOT NULL AND v_doc->>'metadata' <> 'null'
             THEN v_doc->'metadata' ELSE NULL END
      );
    END LOOP;
  END IF;

  -- Mirror the ACTIVE set from er_application_documents into er_documents.
  -- This captures both the freshly-inserted staging rows above AND any
  -- pre-existing reviewer-replaced rows that were persisted earlier via
  -- er_app_doc_upsert. The trigger trg_er_documents_enqueue_dms will pick
  -- them up for DMS transfer.
  FOR v_staging IN
    SELECT *
    FROM er_application_documents
    WHERE regno = v_regno
      AND is_active = true
  LOOP
    INSERT INTO er_documents (
      regno,
      file_name, file_path, storage_url,
      document_type, document_description, doc_code,
      mime_type, file_size,
      uploaded_by, uploaded_by_code, is_supportive,
      metadata,
      source_application_reference, application_reference_number,
      source_document_id,
      is_active,
      transferred_by, transferred_at,
      transfer_status
    ) VALUES (
      v_regno,
      v_staging.file_name, v_staging.file_path, v_staging.storage_url,
      v_staging.document_type, v_staging.document_description, v_staging.doc_code,
      v_staging.mime_type, v_staging.file_size,
      v_staging.uploaded_by, v_staging.uploaded_by_code, COALESCE(v_staging.is_supportive, false),
      v_staging.metadata,
      v_staging.source_application_reference,
      COALESCE(p_application_reference, v_staging.source_application_reference),
      v_staging.id::text,
      true,
      p_entered_by, now(),
      'Pending'
    );
    v_master_count := v_master_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'regno', v_regno,
    'message', 'Employer Registration ' || v_regno || ' created successfully',
    'owners_added', v_owner_seq,
    'locations_added', v_location_seq,
    'notes_added', v_note_seq,
    'documents_added', v_doc_count,
    'master_documents_mirrored', v_master_count
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Conversion failed: ' || SQLERRM
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.convert_application_to_employer(p_application_reference text DEFAULT NULL::text, p_employer_name text DEFAULT NULL::text, p_trade_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_fax text DEFAULT NULL::text, p_hq_addr1 text DEFAULT NULL::text, p_hq_addr2 text DEFAULT NULL::text, p_maddr1 text DEFAULT NULL::text, p_maddr2 text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_mobile text DEFAULT NULL::text, p_office_code text DEFAULT NULL::text, p_ownership_code text DEFAULT NULL::text, p_sector_code text DEFAULT NULL::text, p_industrial_code text DEFAULT NULL::text, p_village_code text DEFAULT NULL::text, p_activity_type text DEFAULT NULL::text, p_inspector_code text DEFAULT NULL::text, p_males_employed integer DEFAULT NULL::integer, p_females_employed integer DEFAULT NULL::integer, p_date_wages_first_paid text DEFAULT NULL::text, p_application_date text DEFAULT NULL::text, p_date_incorporated text DEFAULT NULL::text, p_date_of_acquisition text DEFAULT NULL::text, p_previous_owner text DEFAULT NULL::text, p_prev_owner_addr1 text DEFAULT NULL::text, p_prev_owner_addr2 text DEFAULT NULL::text, p_computer_payroll text DEFAULT 'N'::text, p_make_model text DEFAULT NULL::text, p_acquired_code text DEFAULT 'N'::text, p_parent_regno text DEFAULT NULL::text, p_registry_num text DEFAULT NULL::text, p_entered_by text DEFAULT NULL::text, p_user_id text DEFAULT NULL::text, p_owners_json text DEFAULT '[]'::text, p_locations_json text DEFAULT '[]'::text, p_notes_json text DEFAULT '[]'::text, p_documents_json text DEFAULT '[]'::text, p_hq_city text DEFAULT NULL::text, p_hq_state text DEFAULT NULL::text, p_hq_country text DEFAULT NULL::text, p_mailing_city text DEFAULT NULL::text, p_mailing_state text DEFAULT NULL::text, p_mailing_country text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_regno TEXT;
  v_now TIMESTAMP := now();
  v_today DATE := CURRENT_DATE;
  v_location_id INTEGER := 0;
  v_owner_id INTEGER := 0;
  v_seq_no INTEGER := 0;
  v_location JSONB;
  v_owner JSONB;
  v_note JSONB;
  v_doc JSONB;
  v_doc_count INTEGER := 0;
  v_existing_regno TEXT;
BEGIN
  IF p_application_reference IS NOT NULL THEN
    SELECT regno INTO v_existing_regno FROM er_master WHERE registry_num = p_application_reference LIMIT 1;
    IF v_existing_regno IS NOT NULL THEN
      RETURN jsonb_build_object('success', false,
        'message', format('Application %s has already been converted to employer %s', p_application_reference, v_existing_regno),
        'regno', v_existing_regno);
    END IF;
  END IF;

  SELECT COALESCE('T' || LPAD((COALESCE(MAX(SUBSTRING(regno FROM 2)::INTEGER), 0) + 1)::TEXT, 5, '0'), 'T00001')
  INTO v_regno FROM er_master WHERE regno ~ '^T\d{5}$';

  INSERT INTO er_master (
    regno, name, trade_name, phone, fax, hq_addr1, hq_addr2, maddr1, maddr2,
    email, mobile, office_code, ownership_code, sector_code, industrial_code, village_code,
    activity_type, inspector_code, males_employed, females_employed,
    date_wages_first_paid, application_date, date_incorporated, date_of_acquisition,
    previous_owner, prev_owner_addr1, prev_owner_addr2, computer_payroll, make_model, acquired_code,
    parent_regno, registry_num, entered_by, date_of_entry, status, arrears, legal_action,
    hq_city, hq_state, hq_country, mailing_city, mailing_state, mailing_country
  ) VALUES (
    v_regno, p_employer_name, p_trade_name, p_phone, p_fax, p_hq_addr1, p_hq_addr2, p_maddr1, p_maddr2,
    p_email, p_mobile, COALESCE(p_office_code, 'STK'), p_ownership_code,
    COALESCE(p_sector_code, 'O'), COALESCE(p_industrial_code, '0000'), COALESCE(p_village_code, '000'),
    p_activity_type, COALESCE(p_inspector_code, 'UNK'), p_males_employed, p_females_employed,
    p_date_wages_first_paid::DATE, COALESCE(p_application_date::DATE, v_today),
    p_date_incorporated::DATE, p_date_of_acquisition::DATE,
    p_previous_owner, p_prev_owner_addr1, p_prev_owner_addr2,
    COALESCE(p_computer_payroll, 'N'), p_make_model, COALESCE(p_acquired_code, 'N'),
    p_parent_regno, p_application_reference, p_entered_by, v_today, 'Z', 'N', 'N',
    p_hq_city, p_hq_state, p_hq_country, p_mailing_city, p_mailing_state, p_mailing_country
  );

  FOR v_location IN SELECT * FROM jsonb_array_elements(p_locations_json::JSONB) LOOP
    v_location_id := v_location_id + 1;
    INSERT INTO er_locations (regno, location_id, trade_name, loc_addr1, loc_addr2, activity_type, city, state, country)
    VALUES (v_regno, v_location_id, v_location->>'trade_name', v_location->>'loc_addr1', v_location->>'loc_addr2',
      v_location->>'activity_type', v_location->>'city', v_location->>'state', v_location->>'country');
  END LOOP;

  FOR v_owner IN SELECT * FROM jsonb_array_elements(p_owners_json::JSONB) LOOP
    v_owner_id := v_owner_id + 1;
    INSERT INTO er_owner (regno, location_id, owner_id, name, title, phone, mobile, email, ssn)
    VALUES (v_regno, 0, v_owner_id, v_owner->>'name', v_owner->>'title', v_owner->>'phone',
      v_owner->>'mobile', v_owner->>'email', v_owner->>'ssn');
  END LOOP;

  FOR v_note IN SELECT * FROM jsonb_array_elements(p_notes_json::JSONB) LOOP
    v_seq_no := v_seq_no + 1;
    INSERT INTO er_notes (regno, seq_no, note_date, note, user_id)
    VALUES (v_regno, v_seq_no, COALESCE((v_note->>'note_date')::DATE, v_today),
      v_note->>'note', COALESCE(v_note->>'user_id', p_entered_by));
  END LOOP;

  FOR v_doc IN SELECT * FROM jsonb_array_elements(p_documents_json::JSONB) LOOP
    v_doc_count := v_doc_count + 1;
    INSERT INTO er_documents (
      regno, file_name, file_path, storage_url,
      document_type, document_description, doc_code,
      mime_type, file_size, uploaded_by, uploaded_by_code,
      is_supportive, metadata, created_at,
      source_application_reference, is_active, transferred_at, transferred_by, updated_at
    ) VALUES (
      v_regno, v_doc->>'file_name', v_doc->>'file_path', v_doc->>'storage_url',
      v_doc->>'document_type', v_doc->>'document_description', v_doc->>'doc_code',
      v_doc->>'mime_type', (v_doc->>'file_size')::BIGINT,
      p_user_id, p_entered_by,
      COALESCE((v_doc->>'is_supportive')::BOOLEAN, false),
      CASE WHEN v_doc->'metadata' IS NOT NULL THEN v_doc->'metadata' ELSE NULL END,
      v_now,
      p_application_reference, true, v_now, p_entered_by, v_now
    );
  END LOOP;

  INSERT INTO system_audit_trail (action, module, entity_type, entity_id, payload_json, user_name, created_at)
  VALUES ('CONVERT_APPLICATION', 'employer-registration', 'employer', v_regno,
    jsonb_build_object('application_reference', p_application_reference, 'employer_name', p_employer_name,
      'documents_added', v_doc_count, 'locations_added', v_location_id,
      'owners_added', v_owner_id, 'notes_added', v_seq_no),
    COALESCE(p_entered_by, p_user_id), v_now);

  RETURN jsonb_build_object('success', true, 'regno', v_regno,
    'message', format('Employer registration %s created successfully', v_regno),
    'documents_added', v_doc_count);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false,
    'message', format('Failed to create employer registration: %s', SQLERRM));
END;
$function$;
CREATE OR REPLACE FUNCTION public.convert_application_to_ip(p_reference_number text, p_title text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_middle_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_second_middle_name text DEFAULT NULL::text, p_suffix text DEFAULT NULL::text, p_maiden_name text DEFAULT NULL::text, p_alias text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_date_of_birth date DEFAULT NULL::date, p_height_feet integer DEFAULT NULL::integer, p_height_inches integer DEFAULT NULL::integer, p_eye_color text DEFAULT NULL::text, p_birth_place text DEFAULT NULL::text, p_nationality text DEFAULT NULL::text, p_marital_status text DEFAULT NULL::text, p_date_married date DEFAULT NULL::date, p_photo_url text DEFAULT NULL::text, p_address_line1 text DEFAULT NULL::text, p_address_line2 text DEFAULT NULL::text, p_postal_district text DEFAULT NULL::text, p_mailing_addr1 text DEFAULT NULL::text, p_mailing_addr2 text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_phone_mobile text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_contact_name text DEFAULT NULL::text, p_contact_relation text DEFAULT NULL::text, p_contact_addr1 text DEFAULT NULL::text, p_contact_addr2 text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text, p_contact_mobile text DEFAULT NULL::text, p_father_name text DEFAULT NULL::text, p_mother_name text DEFAULT NULL::text, p_spouse_name text DEFAULT NULL::text, p_spouse_addr1 text DEFAULT NULL::text, p_spouse_addr2 text DEFAULT NULL::text, p_spouse_ssn text DEFAULT NULL::text, p_spouse_dob date DEFAULT NULL::date, p_beneficiary_name text DEFAULT NULL::text, p_ben_addr1 text DEFAULT NULL::text, p_ben_addr2 text DEFAULT NULL::text, p_occupation text DEFAULT NULL::text, p_citizenship text DEFAULT NULL::text, p_npf text DEFAULT NULL::text, p_date_of_residency date DEFAULT NULL::date, p_has_work_permit text DEFAULT NULL::text, p_work_permit_expiry date DEFAULT NULL::date, p_witness_name text DEFAULT NULL::text, p_witness_date date DEFAULT NULL::date, p_application_date date DEFAULT NULL::date, p_remarks text DEFAULT NULL::text, p_approved_by uuid DEFAULT NULL::uuid, p_source_route text DEFAULT NULL::text, p_dependants jsonb DEFAULT NULL::jsonb, p_employer_name text DEFAULT NULL::text, p_employer_address text DEFAULT NULL::text, p_employer_phone text DEFAULT NULL::text, p_employer_town text DEFAULT NULL::text, p_submitted_by text DEFAULT NULL::text, p_submitted_at text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_id            UUID;
  v_new_uuid          UUID;
  v_application_id    TEXT;
  v_dep               JSONB;
  v_dep_seq           INT := 1;
  v_dep_count         INT := 0;
  v_firstname         TEXT;
  v_surname           TEXT;
  v_sex               CHAR(1);
  v_nationality       VARCHAR(3);
  v_marital_status    VARCHAR(20);
  v_dob               DATE;
  v_phone             VARCHAR(10);
  v_phone_mobile      VARCHAR(10);
  v_contact_phone     VARCHAR(10);
  v_contact_mobile    VARCHAR(10);
  v_employer_phone    VARCHAR(10);
  v_telephone         VARCHAR(15);
  v_mobile            VARCHAR(15);
  v_citizenship_flag  CHAR(1);
  v_citizenship       VARCHAR(30);
  v_npf               CHAR(1);
  v_work_permit       CHAR(1);
  v_occupation        VARCHAR(4);
  v_relation_code     VARCHAR(3);
  v_dep_dob           DATE;
  v_dep_school        CHAR(1);
  v_dep_sex           CHAR(1);
  v_staging_note      TEXT;
  -- submitted_by: try to parse as UUID, fall back to NULL
  v_submitted_by_uuid UUID;
BEGIN
  -- ── Duplicate check ──────────────────────────────────────────────────────────
  IF EXISTS (SELECT 1 FROM ip_master WHERE application_reference_number = p_reference_number) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'DUPLICATE_CONVERSION',
      'message', format('An IP record already exists for application reference %s', p_reference_number)
    );
  END IF;

  -- ── Mandatory field guards ────────────────────────────────────────────────────
  IF p_first_name IS NULL OR TRIM(p_first_name) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'MISSING_FIELD',
      'message', 'First name is required for IP conversion.');
  END IF;
  IF p_last_name IS NULL OR TRIM(p_last_name) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'MISSING_FIELD',
      'message', 'Last name is required for IP conversion.');
  END IF;
  IF p_date_of_birth IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'MISSING_FIELD',
      'message', 'Date of birth is required for IP conversion.');
  END IF;
  IF p_gender IS NULL OR TRIM(p_gender) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'MISSING_FIELD',
      'message', 'Gender is required for IP conversion.');
  END IF;

  -- ── Field sanitization ────────────────────────────────────────────────────────
  v_firstname        := LEFT(TRIM(COALESCE(p_first_name, '')), 25);
  v_surname          := LEFT(TRIM(COALESCE(p_last_name, '')), 25);
  v_sex              := LEFT(COALESCE(NULLIF(TRIM(p_gender), ''), 'N'), 1);
  v_dob              := p_date_of_birth;
  v_nationality      := COALESCE(NULLIF(LEFT(TRIM(COALESCE(p_nationality, '')), 3), ''), 'UNK');
  v_marital_status   := LEFT(COALESCE(NULLIF(TRIM(p_marital_status), ''), 'S'), 20);
  v_phone            := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_phone, ''), '[^0-9]', '', 'g'), 10), '');
  v_phone_mobile     := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_phone_mobile, ''), '[^0-9]', '', 'g'), 10), '');
  v_contact_phone    := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_contact_phone, ''), '[^0-9]', '', 'g'), 10), '');
  v_contact_mobile   := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_contact_mobile, ''), '[^0-9]', '', 'g'), 10), '');
  v_employer_phone   := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_employer_phone, ''), '[^0-9]', '', 'g'), 10), '');
  v_telephone        := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_phone, ''), '[^0-9]', '', 'g'), 15), '');
  v_mobile           := NULLIF(LEFT(REGEXP_REPLACE(COALESCE(p_phone_mobile, ''), '[^0-9]', '', 'g'), 15), '');
  v_citizenship_flag := LEFT(COALESCE(NULLIF(TRIM(p_citizenship), ''), 'N'), 1);
  v_citizenship      := v_citizenship_flag;
  v_npf              := LEFT(COALESCE(NULLIF(TRIM(p_npf), ''), 'N'), 1);
  v_work_permit      := LEFT(COALESCE(NULLIF(TRIM(p_has_work_permit), ''), 'N'), 1);
  v_occupation       := NULLIF(LEFT(TRIM(COALESCE(p_occupation, '')), 4), '');

  -- Try to parse submitted_by as UUID; if not valid UUID, set to NULL
  BEGIN
    v_submitted_by_uuid := p_submitted_by::UUID;
  EXCEPTION WHEN OTHERS THEN
    v_submitted_by_uuid := NULL;
  END;

  -- Generate IDs
  v_new_id         := gen_random_uuid();
  v_new_uuid       := gen_random_uuid();
  v_application_id := 'APP-' || substring(v_new_id::text FROM 1 FOR 8);

  -- ── Main ip_master INSERT ─────────────────────────────────────────────────────
  BEGIN
    INSERT INTO ip_master (
      id, unique_uuid, application_id, status,
      surname, firstname, middle_name, second_middle_name, previous_name, name_prefix, name_suffix, alias,
      sex, dob, nationality, marital_status, date_married, birth_place, eyecolor, heightfeet, heightinches,
      resident_addr1, resident_addr2, district, mail_addr1, mail_addr2,
      email_addr, telephone, mobile, phone, phone_mobile,
      contact, contact_relation, contact_addr1, contact_addr2, contact_email, contact_phone, contact_mobile,
      father_name, mother_name, spouse_name, spouse_addr1, spouse_addr2, spouse_ssn, spouse_dob,
      beneficiary, ben_addr1, ben_addr2,
      primary_occup, citizenship, citizenship_flag, npf,
      date_of_residency, place_of_residence, work_permit, work_permit_expiration,
      employer_name, employer_address, employer_phone, employer_town,
      witness_name, date_witnessed,
      application_date, application_reference_number, application_remarks,
      submitted_by, submitted_at, photo_location,
      created_by, created_at, date_of_entry, entered_by
    ) VALUES (
      v_new_id, v_new_uuid, v_application_id, 'P',
      v_surname, v_firstname,
      NULLIF(LEFT(TRIM(COALESCE(p_middle_name, '')), 25), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_second_middle_name, '')), 25), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_maiden_name, '')), 25), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_title, '')), 6), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_suffix, '')), 6), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_alias, '')), 25), ''),
      v_sex, v_dob, v_nationality, v_marital_status, p_date_married,
      NULLIF(LEFT(TRIM(COALESCE(p_birth_place, '')), 3), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_eye_color, '')), 10), ''),
      p_height_feet, p_height_inches,
      NULLIF(LEFT(TRIM(COALESCE(p_address_line1, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_address_line2, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_postal_district, '')), 3), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_mailing_addr1, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_mailing_addr2, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_email, '')), 40), ''),
      v_telephone, v_mobile, v_phone, v_phone_mobile,
      NULLIF(LEFT(TRIM(COALESCE(p_contact_name, '')), 35), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_contact_relation, '')), 20), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_contact_addr1, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_contact_addr2, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_contact_email, '')), 40), ''),
      v_contact_phone, v_contact_mobile,
      NULLIF(LEFT(TRIM(COALESCE(p_father_name, '')), 35), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_mother_name, '')), 35), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_spouse_name, '')), 35), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_spouse_addr1, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_spouse_addr2, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_spouse_ssn, '')), 6), ''),
      p_spouse_dob,
      NULLIF(LEFT(TRIM(COALESCE(p_beneficiary_name, '')), 35), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_ben_addr1, '')), 30), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_ben_addr2, '')), 30), ''),
      v_occupation, v_citizenship, v_citizenship_flag, v_npf,
      p_date_of_residency,
      NULLIF(LEFT(TRIM(COALESCE(p_nationality, '')), 30), ''),
      v_work_permit, p_work_permit_expiry,
      NULLIF(LEFT(TRIM(COALESCE(p_employer_name, '')), 50), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_employer_address, '')), 200), ''),
      v_employer_phone,
      NULLIF(LEFT(TRIM(COALESCE(p_employer_town, '')), 50), ''),
      NULLIF(LEFT(TRIM(COALESCE(p_witness_name, '')), 35), ''),
      p_witness_date,
      COALESCE(p_application_date, CURRENT_DATE),
      p_reference_number,
      NULLIF(LEFT(TRIM(COALESCE(p_remarks, '')), 250), ''),
      -- submitted_by: UUID type — try parsed UUID, fall back to NULL
      v_submitted_by_uuid,
      -- submitted_at: parse safely from text
      CASE WHEN p_submitted_at IS NOT NULL AND p_submitted_at != ''
           THEN p_submitted_at::timestamptz ELSE NULL END,
      -- photo_location: VARCHAR(255)
      NULLIF(LEFT(TRIM(COALESCE(p_photo_url, '')), 255), ''),
      -- created_by: UUID of the approving user
      p_approved_by,
      NOW(),
      CURRENT_DATE,
      -- entered_by: VARCHAR(5) — use fixed system code for online conversions
      'CONV'
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'INSERT_FAILED',
      'message', 'Failed to insert IP master record: ' || SQLERRM,
      'detail',  SQLSTATE
    );
  END;

  -- ── Dependants: Stage (cannot insert into ip_depend until SSN is assigned) ───
  IF p_dependants IS NOT NULL AND jsonb_array_length(p_dependants) > 0 THEN
    FOR v_dep IN SELECT * FROM jsonb_array_elements(p_dependants) LOOP
      BEGIN
        -- Resolve relation code
        v_relation_code := NULL;
        IF (v_dep->>'relationship') IS NOT NULL AND LENGTH(TRIM(v_dep->>'relationship')) > 0 THEN
          SELECT code INTO v_relation_code FROM tb_relation
          WHERE UPPER(TRIM(code)) = UPPER(LEFT(TRIM(v_dep->>'relationship'), 3)) LIMIT 1;
          IF v_relation_code IS NULL THEN
            SELECT code INTO v_relation_code FROM tb_relation
            WHERE UPPER(TRIM(description)) = UPPER(TRIM(v_dep->>'relationship')) LIMIT 1;
          END IF;
        END IF;

        -- Parse DOB safely
        BEGIN
          v_dep_dob := CASE
            WHEN (v_dep->>'dateOfBirth') IS NOT NULL AND (v_dep->>'dateOfBirth') != ''
            THEN (v_dep->>'dateOfBirth')::date ELSE NULL END;
        EXCEPTION WHEN OTHERS THEN v_dep_dob := NULL; END;

        -- School child flag
        v_dep_school := CASE
          WHEN (v_dep->>'isInSchool') IN ('true','Y','Yes') THEN 'Y' ELSE 'N' END;

        -- Sex
        v_dep_sex := NULLIF(LEFT(TRIM(COALESCE(v_dep->>'gender', '')), 1), '');

        v_staging_note := CASE
          WHEN v_relation_code IS NULL AND (v_dep->>'relationship') IS NOT NULL
          THEN 'Relation "' || (v_dep->>'relationship') || '" not matched in tb_relation'
          ELSE NULL END;

        INSERT INTO ip_depend_staging (
          ip_master_id, application_ref, firstname, surname, dob, sex,
          relation_raw, relation, depend_addr1, school_child, dep_ssn, status, notes
        ) VALUES (
          v_new_id, p_reference_number,
          NULLIF(LEFT(TRIM(COALESCE(v_dep->>'firstName', '')), 25), ''),
          NULLIF(LEFT(TRIM(COALESCE(v_dep->>'lastName', '')), 25), ''),
          v_dep_dob, v_dep_sex,
          NULLIF(TRIM(COALESCE(v_dep->>'relationship', '')), ''),
          v_relation_code,
          NULLIF(LEFT(TRIM(COALESCE(v_dep->>'address', '')), 50), ''),
          v_dep_school,
          NULLIF(LEFT(TRIM(COALESCE(v_dep->>'ssn', '')), 6), ''),
          'Pending', v_staging_note
        );
        v_dep_count := v_dep_count + 1;
      EXCEPTION WHEN OTHERS THEN
        INSERT INTO ip_depend_staging (ip_master_id, application_ref, firstname, status, notes)
        VALUES (v_new_id, p_reference_number,
          NULLIF(LEFT(TRIM(COALESCE(v_dep->>'firstName', '')), 25), ''),
          'Error', 'Staging error: ' || SQLERRM);
      END;
      v_dep_seq := v_dep_seq + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success',           true,
    'ip_master_id',      v_new_id,
    'application_id',    v_application_id,
    'dependants_staged', v_dep_count,
    'dependants_note',   CASE WHEN v_dep_count > 0
      THEN v_dep_count || ' dependant(s) staged pending SSN assignment.'
      ELSE NULL END,
    'message', format('Application %s successfully converted to IP record.', p_reference_number)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false, 'error', 'UNEXPECTED_ERROR',
    'message', 'Unexpected error during IP conversion: ' || SQLERRM,
    'detail',  SQLSTATE
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_allocate_document_reference(p_module_code text, p_doc_type_code text, p_prefix text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entity_type TEXT;
  v_ref TEXT;
  v_year INT := EXTRACT(YEAR FROM now())::INT;
  v_next BIGINT;
  v_padding INT;
  v_prefix TEXT;
BEGIN
  IF upper(coalesce(p_module_code, '')) = 'LEGAL' THEN
    SELECT g.generated_number INTO v_ref
    FROM public.core_generate_number('LEGAL', 'LEGAL_DOCUMENT', 'SKN', NULL, NULL, NULL) g
    LIMIT 1;
    RETURN v_ref;
  END IF;

  v_entity_type := upper(coalesce(p_module_code, 'COMMON')) || '_DOCUMENT';
  BEGIN
    SELECT g.generated_number INTO v_ref
    FROM public.core_generate_number(p_module_code, v_entity_type, 'SKN', NULL, NULL, NULL) g
    LIMIT 1;
    IF v_ref IS NOT NULL THEN
      RETURN v_ref;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Non-Legal legacy callers may not yet have central sequences configured.
    -- Preserve their old behavior, but include doc type in the emitted reference
    -- so two document types sharing a prefix cannot collide.
  END;

  INSERT INTO public.core_document_sequence(module_code, doc_type_code, prefix, year, last_number, padding)
  VALUES (p_module_code, p_doc_type_code, coalesce(nullif(p_prefix, ''), p_module_code), v_year, 0, 6)
  ON CONFLICT (module_code, doc_type_code, year) DO NOTHING;

  UPDATE public.core_document_sequence cds
     SET last_number = cds.last_number + 1,
         updated_at = now()
   WHERE cds.module_code = p_module_code
     AND cds.doc_type_code = p_doc_type_code
     AND cds.year = v_year
  RETURNING cds.last_number, cds.padding, cds.prefix INTO v_next, v_padding, v_prefix;

  RETURN v_prefix || '-' || p_doc_type_code || '-' || v_year::TEXT || '-' || lpad(v_next::TEXT, v_padding, '0');
END $function$;
CREATE OR REPLACE FUNCTION public.core_comm_asset_get(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  SELECT jsonb_build_object(
    'asset', to_jsonb(a.*),
    'active_version', (SELECT to_jsonb(v.*) FROM public.core_comm_asset_version v WHERE v.id = a.active_version_id)
  ) INTO v FROM public.core_comm_asset a WHERE a.id = p_id;
  IF v IS NULL THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='asset_not_found'; END IF;
  RETURN v;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_asset_list_active(p_organization_id uuid, p_asset_type text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, code text, name text, asset_type text, department_id uuid, active_version_id uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  RETURN QUERY
    SELECT a.id, a.code, a.name, a.asset_type, a.department_id, a.active_version_id, a.updated_at
    FROM public.core_comm_asset a
    WHERE a.organization_id = p_organization_id
      AND a.status = 'active'
      AND (p_asset_type IS NULL OR a.asset_type = p_asset_type)
    ORDER BY a.asset_type, a.code;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_assignment_list(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_output_channel text DEFAULT 'email'::text)
 RETURNS TABLE(id uuid, organization_id uuid, department_id uuid, output_channel text, assignment_kind text, slot_code text, layout_id uuid, asset_id uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_department_id IS NOT NULL THEN
    PERFORM public.core_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;
  RETURN QUERY
    SELECT a.id,a.organization_id,a.department_id,a.output_channel,a.assignment_kind,a.slot_code,a.layout_id,a.asset_id,a.updated_at
    FROM public.core_comm_assignment a
    WHERE a.organization_id = p_organization_id
      AND a.output_channel = p_output_channel
      AND (a.department_id IS NULL OR p_department_id IS NULL OR a.department_id = p_department_id)
    ORDER BY a.assignment_kind, a.slot_code NULLS FIRST, a.department_id NULLS FIRST;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_assignment_reset_dept_override(p_organization_id uuid, p_department_id uuid, p_output_channel text, p_assignment_kind text, p_slot_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_rows int;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  PERFORM public.core_priv_verify_department_ownership(p_department_id, p_organization_id);
  DELETE FROM public.core_comm_assignment
    WHERE organization_id = p_organization_id
      AND department_id = p_department_id
      AND output_channel = p_output_channel
      AND assignment_kind = p_assignment_kind
      AND (p_assignment_kind = 'layout_default' OR slot_code = p_slot_code);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows > 0;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_assignment_upsert_dept_override(p_organization_id uuid, p_department_id uuid, p_output_channel text, p_assignment_kind text, p_slot_code text, p_layout_id uuid, p_asset_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_id uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_department_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='department_required';
  END IF;
  IF p_assignment_kind = 'layout_default' THEN
    INSERT INTO public.core_comm_assignment(organization_id, department_id, output_channel, assignment_kind, layout_id, created_by, updated_by)
    VALUES (p_organization_id, p_department_id, p_output_channel, 'layout_default', p_layout_id, v_uid, v_uid)
    ON CONFLICT (organization_id, department_id, output_channel) WHERE assignment_kind='layout_default' AND department_id IS NOT NULL
    DO UPDATE SET layout_id = EXCLUDED.layout_id, updated_by = v_uid, updated_at = now()
    RETURNING id INTO v_id;
  ELSIF p_assignment_kind = 'asset_slot' THEN
    INSERT INTO public.core_comm_assignment(organization_id, department_id, output_channel, assignment_kind, slot_code, asset_id, created_by, updated_by)
    VALUES (p_organization_id, p_department_id, p_output_channel, 'asset_slot', p_slot_code, p_asset_id, v_uid, v_uid)
    ON CONFLICT (organization_id, department_id, output_channel, slot_code) WHERE assignment_kind='asset_slot' AND department_id IS NOT NULL
    DO UPDATE SET asset_id = EXCLUDED.asset_id, updated_by = v_uid, updated_at = now()
    RETURNING id INTO v_id;
  ELSE
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_assignment_kind';
  END IF;
  RETURN v_id;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_assignment_upsert_org_default(p_organization_id uuid, p_output_channel text, p_assignment_kind text, p_slot_code text, p_layout_id uuid, p_asset_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_id uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_assignment_kind = 'layout_default' THEN
    INSERT INTO public.core_comm_assignment(organization_id, output_channel, assignment_kind, layout_id, created_by, updated_by)
    VALUES (p_organization_id, p_output_channel, 'layout_default', p_layout_id, v_uid, v_uid)
    ON CONFLICT (organization_id, output_channel) WHERE assignment_kind='layout_default' AND department_id IS NULL
    DO UPDATE SET layout_id = EXCLUDED.layout_id, updated_by = v_uid, updated_at = now()
    RETURNING id INTO v_id;
  ELSIF p_assignment_kind = 'asset_slot' THEN
    INSERT INTO public.core_comm_assignment(organization_id, output_channel, assignment_kind, slot_code, asset_id, created_by, updated_by)
    VALUES (p_organization_id, p_output_channel, 'asset_slot', p_slot_code, p_asset_id, v_uid, v_uid)
    ON CONFLICT (organization_id, output_channel, slot_code) WHERE assignment_kind='asset_slot' AND department_id IS NULL
    DO UPDATE SET asset_id = EXCLUDED.asset_id, updated_by = v_uid, updated_at = now()
    RETURNING id INTO v_id;
  ELSE
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_assignment_kind';
  END IF;
  RETURN v_id;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_pilot_migration_apply(p_organization_id uuid, p_department_id uuid, p_letterhead_id uuid, p_signature_id uuid, p_footer_id uuid, p_dept_signature_id uuid, p_email_layout_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid;
  v_lh record; v_sig record; v_ft record; v_dsig record; v_lay record;
  v_asset_hdr uuid; v_asset_ftr uuid; v_asset_sig uuid; v_asset_dsig uuid;
  v_ver_hdr uuid; v_ver_ftr uuid; v_ver_sig uuid; v_ver_dsig uuid;
  v_layv uuid;
  v_hdr_html text; v_ftr_html text; v_sig_html text; v_dsig_html text;
  v_slots jsonb;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  PERFORM public.core_priv_verify_department_ownership(p_department_id, p_organization_id);
  SELECT id, header_html, footer_html INTO v_lh FROM public.comm_letterhead WHERE id = p_letterhead_id;
  SELECT id, html_signature INTO v_sig FROM public.comm_email_signature WHERE id = p_signature_id;
  SELECT id, footer_html INTO v_ft FROM public.comm_print_footer WHERE id = p_footer_id;
  IF p_dept_signature_id IS NOT NULL THEN
    SELECT id, html_signature INTO v_dsig FROM public.comm_email_signature WHERE id = p_dept_signature_id;
  END IF;
  SELECT id INTO v_lay FROM public.core_template_layout WHERE id = p_email_layout_id;
  IF v_lh.id IS NULL OR v_sig.id IS NULL OR v_ft.id IS NULL OR v_lay.id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='pilot_source_missing';
  END IF;
  v_hdr_html := COALESCE(v_lh.header_html, '<div>Header</div>');
  v_ftr_html := COALESCE(v_ft.footer_html, '<div>Footer</div>');
  v_sig_html := COALESCE(v_sig.html_signature, '<div>Signature</div>');
  IF v_dsig.id IS NOT NULL THEN
    v_dsig_html := COALESCE(v_dsig.html_signature, '<div>Dept Signature</div>');
  END IF;

  INSERT INTO public.core_comm_asset(organization_id, asset_type, code, name, status, created_by, updated_by)
    VALUES (p_organization_id, 'email_header', 'PILOT.ORG.EMAIL_HEADER', 'Pilot organisation email header', 'draft', v_uid, v_uid)
    ON CONFLICT (organization_id, asset_type, code) DO UPDATE SET updated_by=v_uid, updated_at=now()
    RETURNING id INTO v_asset_hdr;
  INSERT INTO public.core_comm_asset(organization_id, asset_type, code, name, status, created_by, updated_by)
    VALUES (p_organization_id, 'email_footer', 'PILOT.ORG.EMAIL_FOOTER', 'Pilot organisation email footer', 'draft', v_uid, v_uid)
    ON CONFLICT (organization_id, asset_type, code) DO UPDATE SET updated_by=v_uid, updated_at=now()
    RETURNING id INTO v_asset_ftr;
  INSERT INTO public.core_comm_asset(organization_id, asset_type, code, name, status, created_by, updated_by)
    VALUES (p_organization_id, 'email_signature', 'PILOT.ORG.EMAIL_SIGNATURE', 'Pilot organisation email signature', 'draft', v_uid, v_uid)
    ON CONFLICT (organization_id, asset_type, code) DO UPDATE SET updated_by=v_uid, updated_at=now()
    RETURNING id INTO v_asset_sig;
  IF v_dsig.id IS NOT NULL THEN
    INSERT INTO public.core_comm_asset(organization_id, department_id, asset_type, code, name, status, created_by, updated_by)
      VALUES (p_organization_id, p_department_id, 'email_signature', 'PILOT.DEPT.EMAIL_SIGNATURE', 'Pilot department email signature', 'draft', v_uid, v_uid)
      ON CONFLICT (organization_id, asset_type, code) DO UPDATE SET updated_by=v_uid, updated_at=now()
      RETURNING id INTO v_asset_dsig;
  END IF;

  INSERT INTO public.core_comm_asset_version(asset_id, version_number, content_html, checksum, published_by)
    VALUES (v_asset_hdr, 1, v_hdr_html, encode(extensions.digest(v_hdr_html,'sha256'),'hex'), v_uid)
    ON CONFLICT (asset_id, version_number) DO NOTHING RETURNING id INTO v_ver_hdr;
  IF v_ver_hdr IS NULL THEN SELECT id INTO v_ver_hdr FROM public.core_comm_asset_version WHERE asset_id=v_asset_hdr AND version_number=1; END IF;
  INSERT INTO public.core_comm_asset_version(asset_id, version_number, content_html, checksum, published_by)
    VALUES (v_asset_ftr, 1, v_ftr_html, encode(extensions.digest(v_ftr_html,'sha256'),'hex'), v_uid)
    ON CONFLICT (asset_id, version_number) DO NOTHING RETURNING id INTO v_ver_ftr;
  IF v_ver_ftr IS NULL THEN SELECT id INTO v_ver_ftr FROM public.core_comm_asset_version WHERE asset_id=v_asset_ftr AND version_number=1; END IF;
  INSERT INTO public.core_comm_asset_version(asset_id, version_number, content_html, checksum, published_by)
    VALUES (v_asset_sig, 1, v_sig_html, encode(extensions.digest(v_sig_html,'sha256'),'hex'), v_uid)
    ON CONFLICT (asset_id, version_number) DO NOTHING RETURNING id INTO v_ver_sig;
  IF v_ver_sig IS NULL THEN SELECT id INTO v_ver_sig FROM public.core_comm_asset_version WHERE asset_id=v_asset_sig AND version_number=1; END IF;
  IF v_asset_dsig IS NOT NULL THEN
    INSERT INTO public.core_comm_asset_version(asset_id, version_number, content_html, checksum, published_by)
      VALUES (v_asset_dsig, 1, v_dsig_html, encode(extensions.digest(v_dsig_html,'sha256'),'hex'), v_uid)
      ON CONFLICT (asset_id, version_number) DO NOTHING RETURNING id INTO v_ver_dsig;
    IF v_ver_dsig IS NULL THEN SELECT id INTO v_ver_dsig FROM public.core_comm_asset_version WHERE asset_id=v_asset_dsig AND version_number=1; END IF;
  END IF;

  UPDATE public.core_comm_asset SET status='active', active_version_id=v_ver_hdr, activated_at=COALESCE(activated_at,now()), activated_by=COALESCE(activated_by,v_uid) WHERE id=v_asset_hdr AND status<>'retired';
  UPDATE public.core_comm_asset SET status='active', active_version_id=v_ver_ftr, activated_at=COALESCE(activated_at,now()), activated_by=COALESCE(activated_by,v_uid) WHERE id=v_asset_ftr AND status<>'retired';
  UPDATE public.core_comm_asset SET status='active', active_version_id=v_ver_sig, activated_at=COALESCE(activated_at,now()), activated_by=COALESCE(activated_by,v_uid) WHERE id=v_asset_sig AND status<>'retired';
  IF v_asset_dsig IS NOT NULL THEN
    UPDATE public.core_comm_asset SET status='active', active_version_id=v_ver_dsig, activated_at=COALESCE(activated_at,now()), activated_by=COALESCE(activated_by,v_uid) WHERE id=v_asset_dsig AND status<>'retired';
  END IF;

  v_slots := jsonb_build_array(
    jsonb_build_object('code','email_header','order',10,'required',false,'allowed_asset_types', jsonb_build_array('email_header')),
    jsonb_build_object('code','content_body','order',20,'required',true),
    jsonb_build_object('code','email_signature','order',30,'required',false,'allowed_asset_types', jsonb_build_array('email_signature')),
    jsonb_build_object('code','disclaimer','order',40,'required',false,'allowed_asset_types', jsonb_build_array('disclaimer')),
    jsonb_build_object('code','email_footer','order',50,'required',false,'allowed_asset_types', jsonb_build_array('email_footer'))
  );
  INSERT INTO public.core_template_layout_version(layout_id, version_number, slots, checksum, published_by)
    VALUES (p_email_layout_id, 1, v_slots, encode(extensions.digest(v_slots::text,'sha256'),'hex'), v_uid)
    ON CONFLICT (layout_id, version_number) DO NOTHING RETURNING id INTO v_layv;
  IF v_layv IS NULL THEN SELECT id INTO v_layv FROM public.core_template_layout_version WHERE layout_id=p_email_layout_id AND version_number=1; END IF;

  PERFORM public.core_comm_assignment_upsert_org_default(p_organization_id,'email','layout_default',NULL,p_email_layout_id,NULL);
  PERFORM public.core_comm_assignment_upsert_org_default(p_organization_id,'email','asset_slot','email_header',NULL,v_asset_hdr);
  PERFORM public.core_comm_assignment_upsert_org_default(p_organization_id,'email','asset_slot','email_footer',NULL,v_asset_ftr);
  PERFORM public.core_comm_assignment_upsert_org_default(p_organization_id,'email','asset_slot','email_signature',NULL,v_asset_sig);
  IF v_asset_dsig IS NOT NULL THEN
    PERFORM public.core_comm_assignment_upsert_dept_override(p_organization_id, p_department_id,'email','asset_slot','email_signature',NULL,v_asset_dsig);
  END IF;

  RETURN jsonb_build_object('ok', true, 'organization_id', p_organization_id, 'department_id', p_department_id,
    'assets', jsonb_build_object('email_header', v_asset_hdr, 'email_footer', v_asset_ftr, 'email_signature', v_asset_sig, 'dept_email_signature', v_asset_dsig),
    'versions', jsonb_build_object('email_header', v_ver_hdr, 'email_footer', v_ver_ftr, 'email_signature', v_ver_sig, 'dept_email_signature', v_ver_dsig),
    'layout_version_id', v_layv);
END;$function$;
CREATE OR REPLACE FUNCTION public.core_comm_pilot_migration_dry_run(p_organization_id uuid, p_department_id uuid, p_letterhead_id uuid, p_signature_id uuid, p_footer_id uuid, p_dept_signature_id uuid, p_email_layout_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_lh record; v_sig record; v_ft record; v_dsig record; v_lay record;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  PERFORM public.core_priv_verify_department_ownership(p_department_id, p_organization_id);
  SELECT id, name, header_html, footer_html INTO v_lh FROM public.comm_letterhead WHERE id = p_letterhead_id;
  SELECT id, name, html_signature INTO v_sig FROM public.comm_email_signature WHERE id = p_signature_id;
  SELECT id, name, footer_html INTO v_ft FROM public.comm_print_footer WHERE id = p_footer_id;
  IF p_dept_signature_id IS NOT NULL THEN
    SELECT id, name, html_signature INTO v_dsig FROM public.comm_email_signature WHERE id = p_dept_signature_id;
  END IF;
  SELECT id, name, layout_kind INTO v_lay FROM public.core_template_layout WHERE id = p_email_layout_id;
  RETURN jsonb_build_object(
    'organization_id', p_organization_id, 'department_id', p_department_id,
    'sources', jsonb_build_object('letterhead', to_jsonb(v_lh), 'org_signature', to_jsonb(v_sig),
      'footer', to_jsonb(v_ft), 'dept_signature', to_jsonb(v_dsig), 'email_layout', to_jsonb(v_lay)),
    'destination_codes', jsonb_build_object(
      'org_email_header', 'PILOT.ORG.EMAIL_HEADER', 'org_email_footer', 'PILOT.ORG.EMAIL_FOOTER',
      'org_email_signature', 'PILOT.ORG.EMAIL_SIGNATURE', 'dept_email_signature', 'PILOT.DEPT.EMAIL_SIGNATURE'),
    'ambiguity', CASE
      WHEN v_lh.id IS NULL OR v_sig.id IS NULL OR v_ft.id IS NULL OR v_lay.id IS NULL THEN 'source_missing'
      ELSE 'none' END,
    'storage_bucket_check', true, 'dry_run', true);
END;$function$;
CREATE OR REPLACE FUNCTION public.core_gen_doc_legal_ref_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'Generated document legal reference snapshots are write-once';
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_generate_number(p_module_code text, p_entity_type text, p_country_code text DEFAULT 'SKN'::text, p_branch_code text DEFAULT NULL::text, p_department_code text DEFAULT NULL::text, p_user_code text DEFAULT NULL::text)
 RETURNS TABLE(sequence_id uuid, sequence_value bigint, generated_number text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seq      public.core_number_sequence%ROWTYPE;
  v_rule     public.core_number_sequence_rule%ROWTYPE;
  v_pattern  TEXT;
  v_padding  INT;
  v_freq     TEXT;
  v_period   TEXT;
  v_next     BIGINT;
  v_out      TEXT;
  v_today    DATE := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  IF p_module_code IS NULL OR p_entity_type IS NULL THEN
    RAISE EXCEPTION 'module_code and entity_type are required';
  END IF;

  SELECT * INTO v_seq
  FROM public.core_number_sequence cns
  WHERE cns.module_code = upper(p_module_code)
    AND cns.entity_type = upper(p_entity_type)
    AND cns.country_code = upper(coalesce(p_country_code,'SKN'))
    AND cns.is_active = TRUE
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No active numbering sequence configured for %/%/%',
      p_module_code, p_entity_type, coalesce(p_country_code,'SKN')
      USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_rule
  FROM public.core_number_sequence_rule r
  WHERE r.sequence_id = v_seq.id
    AND r.is_active = TRUE
    AND (r.branch_code IS NULL OR r.branch_code = p_branch_code)
    AND (r.department_code IS NULL OR r.department_code = p_department_code)
  ORDER BY (r.branch_code IS NOT NULL)::int + (r.department_code IS NOT NULL)::int DESC
  LIMIT 1;

  v_pattern := COALESCE(v_rule.number_pattern, v_seq.number_pattern);
  v_padding := COALESCE(v_rule.padding_length,  v_seq.padding_length);
  v_freq    := COALESCE(v_rule.reset_frequency, v_seq.reset_frequency);

  v_period := CASE v_freq
    WHEN 'NEVER'   THEN 'ALL'
    WHEN 'YEARLY'  THEN to_char(v_today,'YYYY')
    WHEN 'MONTHLY' THEN to_char(v_today,'YYYY-MM')
    WHEN 'DAILY'   THEN to_char(v_today,'YYYY-MM-DD')
    ELSE 'ALL'
  END;

  IF v_seq.last_period_key IS DISTINCT FROM v_period THEN
    v_next := 1;
  ELSE
    v_next := v_seq.current_number + 1;
  END IF;

  v_out := v_pattern;
  v_out := replace(v_out, '{MODULE}',     v_seq.module_code);
  v_out := replace(v_out, '{ENTITY}',     v_seq.entity_type);
  v_out := replace(v_out, '{COUNTRY}',    v_seq.country_code);
  v_out := replace(v_out, '{YYYY}',       to_char(v_today,'YYYY'));
  v_out := replace(v_out, '{YY}',         to_char(v_today,'YY'));
  v_out := replace(v_out, '{MM}',         to_char(v_today,'MM'));
  v_out := replace(v_out, '{DD}',         to_char(v_today,'DD'));
  v_out := replace(v_out, '{BRANCH}',     COALESCE(p_branch_code,''));
  v_out := replace(v_out, '{DEPARTMENT}', COALESCE(p_department_code,''));
  v_out := replace(v_out, '{SEQ}',        lpad(v_next::text, v_padding, '0'));

  UPDATE public.core_number_sequence cns
     SET current_number = v_next,
         last_period_key = v_period,
         updated_at = now(),
         updated_by = COALESCE(p_user_code, cns.updated_by)
   WHERE cns.id = v_seq.id;

  INSERT INTO public.core_number_sequence_audit(
    sequence_id, module_code, entity_type, country_code,
    branch_code, department_code, generated_number, sequence_value,
    pattern_used, is_override, generated_by
  ) VALUES (
    v_seq.id, v_seq.module_code, v_seq.entity_type, v_seq.country_code,
    p_branch_code, p_department_code, v_out, v_next,
    v_pattern, FALSE, p_user_code
  );

  core_generate_number.sequence_id := v_seq.id;
  core_generate_number.sequence_value := v_next;
  core_generate_number.generated_number := v_out;
  RETURN NEXT;
END $function$;
CREATE OR REPLACE FUNCTION public.core_generated_document_enforce_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.is_immutable IS TRUE THEN
    IF NEW.generated_html      IS DISTINCT FROM OLD.generated_html      OR
       NEW.subject             IS DISTINCT FROM OLD.subject             OR
       NEW.template_version_id IS DISTINCT FROM OLD.template_version_id OR
       NEW.template_id         IS DISTINCT FROM OLD.template_id         OR
       NEW.resolved_tokens     IS DISTINCT FROM OLD.resolved_tokens     OR
       NEW.resolved_context    IS DISTINCT FROM OLD.resolved_context    OR
       NEW.resolved_letterhead_id      IS DISTINCT FROM OLD.resolved_letterhead_id      OR
       NEW.resolved_signature_id       IS DISTINCT FROM OLD.resolved_signature_id       OR
       NEW.resolved_seal_asset_id      IS DISTINCT FROM OLD.resolved_seal_asset_id      OR
       NEW.resolved_watermark_asset_id IS DISTINCT FROM OLD.resolved_watermark_asset_id OR
       NEW.resolved_footer_id          IS DISTINCT FROM OLD.resolved_footer_id          OR
       NEW.resolved_disclaimer_id      IS DISTINCT FROM OLD.resolved_disclaimer_id      OR
       NEW.legal_references_snapshot   IS DISTINCT FROM OLD.legal_references_snapshot   OR
       NEW.content_hash        IS DISTINCT FROM OLD.content_hash        OR
       NEW.issued_at           IS DISTINCT FROM OLD.issued_at           OR
       NEW.issued_by           IS DISTINCT FROM OLD.issued_by
    THEN
      RAISE EXCEPTION
        'core_generated_document % is immutable (issued at %); only delivery/storage fields may be updated',
        OLD.id, OLD.issued_at;
    END IF;
    -- Prevent flipping the lock off
    IF NEW.is_immutable IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'Cannot clear is_immutable on issued document %', OLD.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_ledger_txn_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.posting_status = 'POSTED' THEN
      RAISE EXCEPTION 'Cannot delete POSTED ledger transaction %; create a reversal instead.', OLD.transaction_no;
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.posting_status = 'POSTED' THEN
      IF NEW.posting_status NOT IN ('REVERSED','ADJUSTED') THEN
        RAISE EXCEPTION 'POSTED ledger transaction % is immutable; only status change to REVERSED/ADJUSTED allowed.', OLD.transaction_no;
      END IF;
      IF NEW.debit_amount <> OLD.debit_amount
         OR NEW.credit_amount <> OLD.credit_amount
         OR NEW.head_code <> OLD.head_code
         OR NEW.posting_period <> OLD.posting_period
         OR NEW.employer_id <> OLD.employer_id THEN
        RAISE EXCEPTION 'Amount/head/period/employer of POSTED transaction % cannot change.', OLD.transaction_no;
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.core_legacy_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.core_legal_ref_audit(p_entity_id uuid, p_action text, p_user_code text, p_before jsonb, p_after jsonb, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.legal_admin_audit(entity_type, entity_id, action, user_name, before_data, after_data, changes)
  VALUES ('core_legal_reference_version', p_entity_id, p_action, COALESCE(p_user_code,'system'),
          p_before, p_after, jsonb_build_object('reason', p_reason));
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_legal_ref_create_version(p_master_id uuid, p_user_code text, p_effective_from date, p_change_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_next INT;
  v_id UUID;
  v_src public.core_legal_reference_version%ROWTYPE;
BEGIN
  SELECT COALESCE(MAX(version_number),0)+1 INTO v_next
  FROM public.core_legal_reference_version WHERE legal_reference_id = p_master_id;

  SELECT * INTO v_src FROM public.core_legal_reference_version
   WHERE legal_reference_id = p_master_id
   ORDER BY version_number DESC LIMIT 1;

  INSERT INTO public.core_legal_reference_version(
    legal_reference_id, version_number, section, subsection, regulation,
    citation_text, full_reference_text, official_text, summary, source_url,
    gazette_number, effective_from, version_status, change_reason, created_by, updated_by
  ) VALUES (
    p_master_id, v_next, v_src.section, v_src.subsection, v_src.regulation,
    v_src.citation_text, v_src.full_reference_text, v_src.official_text, v_src.summary, v_src.source_url,
    v_src.gazette_number, p_effective_from, 'DRAFT', p_change_reason, p_user_code, p_user_code
  ) RETURNING id INTO v_id;

  PERFORM public.core_legal_ref_audit(v_id, 'CREATE_VERSION', p_user_code, NULL,
    jsonb_build_object('version_number', v_next, 'effective_from', p_effective_from), p_change_reason);
  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_legal_ref_transition(p_version_id uuid, p_to_status text, p_user_code text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old public.core_legal_reference_version%ROWTYPE;
  v_allowed BOOLEAN := false;
BEGIN
  SELECT * INTO v_old FROM public.core_legal_reference_version WHERE id = p_version_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Version % not found', p_version_id; END IF;

  v_allowed := (v_old.version_status, p_to_status) IN (
    ('DRAFT','SUBMITTED'),('SUBMITTED','REVIEWED'),('REVIEWED','APPROVED'),
    ('APPROVED','PUBLISHED'),('SUBMITTED','DRAFT'),('REVIEWED','DRAFT'),
    ('PUBLISHED','SUPERSEDED'),('PUBLISHED','ARCHIVED'),('SUPERSEDED','ARCHIVED')
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Illegal transition % -> %', v_old.version_status, p_to_status;
  END IF;

  PERFORM set_config('app.legal_ref_lifecycle','on', true);

  UPDATE public.core_legal_reference_version
     SET version_status = p_to_status,
         approved_by    = CASE WHEN p_to_status='APPROVED' THEN p_user_code ELSE approved_by END,
         approved_at    = CASE WHEN p_to_status='APPROVED' THEN now() ELSE approved_at END,
         published_by   = CASE WHEN p_to_status='PUBLISHED' THEN p_user_code ELSE published_by END,
         published_at   = CASE WHEN p_to_status='PUBLISHED' THEN now() ELSE published_at END,
         updated_by     = p_user_code
   WHERE id = p_version_id;

  IF p_to_status = 'PUBLISHED' THEN
    -- Supersede any other published version for same master
    UPDATE public.core_legal_reference_version
       SET version_status = 'SUPERSEDED',
           effective_to   = COALESCE(effective_to, v_old.effective_from - 1),
           updated_by     = p_user_code
     WHERE legal_reference_id = v_old.legal_reference_id
       AND id <> p_version_id
       AND version_status = 'PUBLISHED';

    UPDATE public.core_legal_reference
       SET current_version_id = p_version_id,
           status = 'ACTIVE',
           section = v_old.section,
           subsection = v_old.subsection,
           regulation = v_old.regulation,
           full_reference_text = v_old.full_reference_text,
           effective_from = v_old.effective_from,
           effective_to = v_old.effective_to,
           version_number = v_old.version_number,
           updated_by = p_user_code,
           updated_at = now()
     WHERE id = v_old.legal_reference_id;
  END IF;

  PERFORM set_config('app.legal_ref_lifecycle','off', true);

  PERFORM public.core_legal_ref_audit(p_version_id, 'TRANSITION_'||p_to_status, p_user_code,
    to_jsonb(v_old), (SELECT to_jsonb(x) FROM public.core_legal_reference_version x WHERE x.id = p_version_id),
    p_reason);
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_legal_ref_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  bypass BOOLEAN := COALESCE(current_setting('app.legal_ref_lifecycle', true) = 'on', false);
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.version_status IN ('PUBLISHED','SUPERSEDED','ARCHIVED') AND NOT bypass THEN
      RAISE EXCEPTION 'Cannot delete legal reference version % in status %', OLD.id, OLD.version_status;
    END IF;
    RETURN OLD;
  END IF;

  -- UPDATE
  IF OLD.version_status = 'PUBLISHED' AND NOT bypass THEN
    -- Only effective_to, version_status (to SUPERSEDED/ARCHIVED), updated_by/at may change
    IF NEW.version_number     IS DISTINCT FROM OLD.version_number
    OR NEW.section            IS DISTINCT FROM OLD.section
    OR NEW.subsection         IS DISTINCT FROM OLD.subsection
    OR NEW.regulation         IS DISTINCT FROM OLD.regulation
    OR NEW.citation_text      IS DISTINCT FROM OLD.citation_text
    OR NEW.full_reference_text IS DISTINCT FROM OLD.full_reference_text
    OR NEW.official_text      IS DISTINCT FROM OLD.official_text
    OR NEW.summary            IS DISTINCT FROM OLD.summary
    OR NEW.source_url         IS DISTINCT FROM OLD.source_url
    OR NEW.gazette_number     IS DISTINCT FROM OLD.gazette_number
    OR NEW.effective_from     IS DISTINCT FROM OLD.effective_from
    OR NEW.legal_reference_id IS DISTINCT FROM OLD.legal_reference_id
    THEN
      RAISE EXCEPTION 'Published legal reference version % is immutable (use a new version)', OLD.id;
    END IF;
    IF NEW.version_status NOT IN ('PUBLISHED','SUPERSEDED','ARCHIVED') THEN
      RAISE EXCEPTION 'Published version % can only transition to SUPERSEDED or ARCHIVED', OLD.id;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_legal_ref_version_overlap_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.version_status <> 'PUBLISHED' THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.core_legal_reference_version v
    WHERE v.legal_reference_id = NEW.legal_reference_id
      AND v.id <> NEW.id
      AND v.version_status = 'PUBLISHED'
      AND daterange(v.effective_from, COALESCE(v.effective_to,'infinity'::date), '[)')
        && daterange(NEW.effective_from, COALESCE(NEW.effective_to,'infinity'::date), '[)')
  ) THEN
    RAISE EXCEPTION 'Overlapping PUBLISHED effective period for legal_reference_id=%', NEW.legal_reference_id;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_lrd_sync_header_counts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_ref UUID;
  v_mod TEXT;
  v_count INTEGER;
BEGIN
  v_ref := COALESCE(NEW.referral_id, OLD.referral_id);
  v_mod := COALESCE(NEW.source_module, OLD.source_module);
  SELECT COUNT(*) INTO v_count FROM public.core_legal_referral_document
   WHERE referral_id = v_ref;
  IF v_mod = 'COMPLIANCE' THEN
    UPDATE public.ce_legal_referrals SET documents_count = v_count WHERE id = v_ref;
  ELSIF v_mod = 'BENEFITS' THEN
    UPDATE public.bn_legal_referral SET documents_count = v_count WHERE id = v_ref;
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.core_lrd_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.core_lri_block_duplicate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.source_record_id IS NULL OR NEW.source_record_type IS NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.core_legal_referral_item
     WHERE source_module = NEW.source_module
       AND source_record_type = NEW.source_record_type
       AND source_record_id = NEW.source_record_id
       AND id <> COALESCE(NEW.id,'00000000-0000-0000-0000-000000000000'::uuid)
       AND status NOT IN ('REJECTED','CLOSED','RETURNED')
  ) THEN
    RAISE EXCEPTION 'A live legal referral item already exists for % % %', NEW.source_module, NEW.source_record_type, NEW.source_record_id
      USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_lri_compute_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.total_amount IS NULL OR NEW.total_amount = 0 THEN
    NEW.total_amount := COALESCE(NEW.principal_amount,0)+COALESCE(NEW.penalty_amount,0)
                        +COALESCE(NEW.interest_amount,0)+COALESCE(NEW.cost_amount,0);
  END IF;
  IF NEW.amount_referred IS NULL OR NEW.amount_referred = 0 THEN
    NEW.amount_referred := NEW.total_amount;
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_lri_sync_header_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module TEXT;
  v_ref    UUID;
  v_total  NUMERIC(18,2);
  v_count  INTEGER;
BEGIN
  v_ref := COALESCE(NEW.referral_id, OLD.referral_id);
  v_module := COALESCE(NEW.source_module, OLD.source_module);

  SELECT COALESCE(SUM(amount_referred),0), COUNT(*)
    INTO v_total, v_count
    FROM public.core_legal_referral_item
   WHERE referral_id = v_ref;

  IF v_module = 'COMPLIANCE' THEN
    UPDATE public.ce_legal_referrals
       SET total_referred_amount = v_total, items_count = v_count, updated_at = now()
     WHERE id = v_ref;
  ELSIF v_module = 'BENEFITS' THEN
    UPDATE public.bn_legal_referral
       SET total_referred_amount = v_total, items_count = v_count, updated_at = now()
     WHERE id = v_ref;
  END IF;

  RETURN NULL;
END;$function$;
