$function$;
CREATE OR REPLACE FUNCTION public.core_preview_next_number(p_module_code text, p_entity_type text, p_country_code text DEFAULT 'SKN'::text, p_branch_code text DEFAULT NULL::text, p_department_code text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seq      public.core_number_sequence%ROWTYPE;
  v_rule     public.core_number_sequence_rule%ROWTYPE;
  v_pattern  TEXT;
  v_padding  INT;
  v_freq     TEXT;
  v_period   TEXT;
  v_next     BIGINT;
  v_out      TEXT;
  v_today    DATE := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  SELECT * INTO v_seq
  FROM public.core_number_sequence cns
  WHERE cns.module_code = upper(p_module_code)
    AND cns.entity_type = upper(p_entity_type)
    AND cns.country_code = upper(coalesce(p_country_code,'SKN'))
    AND cns.is_active = TRUE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT * INTO v_rule
  FROM public.core_number_sequence_rule r
  WHERE r.sequence_id = v_seq.id
    AND r.is_active = TRUE
    AND (r.branch_code IS NULL OR r.branch_code = p_branch_code)
    AND (r.department_code IS NULL OR r.department_code = p_department_code)
  ORDER BY (r.branch_code IS NOT NULL)::int + (r.department_code IS NOT NULL)::int DESC
  LIMIT 1;

  v_pattern := COALESCE(v_rule.number_pattern, v_seq.number_pattern);
  v_padding := COALESCE(v_rule.padding_length,  v_seq.padding_length);
  v_freq    := COALESCE(v_rule.reset_frequency, v_seq.reset_frequency);
  v_period := CASE v_freq
    WHEN 'NEVER'   THEN 'ALL'
    WHEN 'YEARLY'  THEN to_char(v_today,'YYYY')
    WHEN 'MONTHLY' THEN to_char(v_today,'YYYY-MM')
    WHEN 'DAILY'   THEN to_char(v_today,'YYYY-MM-DD')
    ELSE 'ALL'
  END;
  v_next := CASE WHEN v_seq.last_period_key IS DISTINCT FROM v_period THEN 1 ELSE v_seq.current_number + 1 END;

  v_out := v_pattern;
  v_out := replace(v_out,'{MODULE}',v_seq.module_code);
  v_out := replace(v_out,'{ENTITY}',v_seq.entity_type);
  v_out := replace(v_out,'{COUNTRY}',v_seq.country_code);
  v_out := replace(v_out,'{YYYY}',to_char(v_today,'YYYY'));
  v_out := replace(v_out,'{YY}',to_char(v_today,'YY'));
  v_out := replace(v_out,'{MM}',to_char(v_today,'MM'));
  v_out := replace(v_out,'{DD}',to_char(v_today,'DD'));
  v_out := replace(v_out,'{BRANCH}',COALESCE(p_branch_code,''));
  v_out := replace(v_out,'{DEPARTMENT}',COALESCE(p_department_code,''));
  v_out := replace(v_out,'{SEQ}',lpad(v_next::text,v_padding,'0'));
  RETURN v_out;
END $function$;
CREATE OR REPLACE FUNCTION public.core_priv_asset_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='asset_must_start_draft';
    END IF;
    IF NEW.department_id IS NOT NULL THEN
      PERFORM public.core_priv_verify_department_ownership(NEW.department_id, NEW.organization_id);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.asset_type IS DISTINCT FROM OLD.asset_type
       OR NEW.code IS DISTINCT FROM OLD.code THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='asset_identity_immutable';
    END IF;
    IF OLD.status = 'retired' AND NEW.status <> 'retired' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='asset_terminal_retired';
    END IF;
    IF NEW.department_id IS NOT NULL THEN
      PERFORM public.core_priv_verify_department_ownership(NEW.department_id, NEW.organization_id);
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='asset_not_deletable';
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_priv_asset_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_bucket_ok bool;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.storage_bucket IS NOT NULL THEN
      SELECT EXISTS(SELECT 1 FROM storage.buckets WHERE id = NEW.storage_bucket) INTO v_bucket_ok;
      IF NOT v_bucket_ok THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='storage_bucket_not_registered';
      END IF;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.status = 'retired' AND OLD.status = 'published'
        AND NEW.asset_id = OLD.asset_id AND NEW.version_number = OLD.version_number
        AND NEW.checksum = OLD.checksum
        AND NEW.content_html IS NOT DISTINCT FROM OLD.content_html
        AND NEW.content_text IS NOT DISTINCT FROM OLD.content_text
        AND NEW.content_json IS NOT DISTINCT FROM OLD.content_json
        AND NEW.storage_object_path IS NOT DISTINCT FROM OLD.storage_object_path) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='asset_version_immutable';
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='asset_version_not_deletable';
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_priv_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_asset_org uuid;
BEGIN
  IF TG_OP IN ('INSERT','UPDATE') THEN
    IF NEW.department_id IS NOT NULL THEN
      PERFORM public.core_priv_verify_department_ownership(NEW.department_id, NEW.organization_id);
    END IF;
    IF NEW.asset_id IS NOT NULL THEN
      SELECT organization_id INTO v_asset_org FROM public.core_comm_asset WHERE id = NEW.asset_id;
      IF v_asset_org IS DISTINCT FROM NEW.organization_id THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='asset_organization_mismatch';
      END IF;
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_priv_layout_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_slot jsonb; v_codes text[]; v_orders int[]; v_code text; v_order int; v_required bool;
  v_allowed jsonb; v_extra text[]; k text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF jsonb_typeof(NEW.slots) <> 'array' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='slots_must_be_array';
    END IF;
    v_codes := ARRAY[]::text[]; v_orders := ARRAY[]::int[];
    FOR v_slot IN SELECT * FROM jsonb_array_elements(NEW.slots) LOOP
      -- reject unknown keys
      FOR k IN SELECT jsonb_object_keys(v_slot) LOOP
        IF k NOT IN ('code','order','required','allowed_asset_types','wrapper','fallback_policy') THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_slot_key:'||k;
        END IF;
      END LOOP;
      v_code := v_slot->>'code';
      IF v_code IS NULL OR v_code = '' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='slot_code_required';
      END IF;
      IF v_code = ANY(v_codes) THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='slot_code_duplicate:'||v_code;
      END IF;
      v_codes := v_codes || v_code;
      v_order := (v_slot->>'order')::int;
      IF v_order IS NULL THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='slot_order_required';
      END IF;
      IF v_order = ANY(v_orders) THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='slot_order_duplicate';
      END IF;
      v_orders := v_orders || v_order;
      v_required := COALESCE((v_slot->>'required')::bool, false);
      v_allowed := v_slot->'allowed_asset_types';
      IF v_allowed IS NULL OR jsonb_typeof(v_allowed) <> 'array' THEN
        IF v_code <> 'content_body' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='slot_allowed_types_required:'||v_code;
        END IF;
      END IF;
    END LOOP;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'retired' AND OLD.status = 'published'
       AND NEW.layout_id = OLD.layout_id
       AND NEW.version_number = OLD.version_number
       AND NEW.slots = OLD.slots
       AND NEW.checksum = OLD.checksum
       AND NEW.wrapper_html IS NOT DISTINCT FROM OLD.wrapper_html THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='layout_version_immutable';
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='layout_version_not_deletable';
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_priv_verify_department_ownership(p_department_id uuid, p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  IF p_department_id IS NULL THEN RETURN; END IF;
  SELECT organization_id INTO v_org FROM public.core_department WHERE id = p_department_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='department_not_found';
  END IF;
  IF v_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='department_organization_mismatch';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_record_number_override(p_module_code text, p_entity_type text, p_country_code text, p_manual_number text, p_override_reason text, p_user_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_seq_id UUID;
  v_id     UUID;
BEGIN
  SELECT id INTO v_seq_id FROM public.core_number_sequence
   WHERE module_code=upper(p_module_code) AND entity_type=upper(p_entity_type)
     AND country_code=upper(coalesce(p_country_code,'SKN'));
  INSERT INTO public.core_number_sequence_audit(
    sequence_id, module_code, entity_type, country_code,
    generated_number, sequence_value, pattern_used, is_override, override_reason, generated_by
  ) VALUES (
    v_seq_id, upper(p_module_code), upper(p_entity_type), upper(coalesce(p_country_code,'SKN')),
    p_manual_number, 0, 'MANUAL_OVERRIDE', TRUE, p_override_reason, p_user_code
  ) RETURNING id INTO v_id;
  RETURN v_id;
END $function$;
CREATE OR REPLACE FUNCTION public.core_reference_value_sync_description()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.value_description IS DISTINCT FROM OLD.value_description
     AND NEW.value_description IS NOT NULL
     AND (NEW.description IS NULL OR NEW.description = OLD.description) THEN
    NEW.description := NEW.value_description;
  ELSIF NEW.description IS DISTINCT FROM OLD.description
     AND NEW.description IS NOT NULL
     AND (NEW.value_description IS NULL OR NEW.value_description = OLD.value_description) THEN
    NEW.value_description := NEW.description;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.core_reset_number_sequence(p_sequence_id uuid, p_new_current bigint, p_reason text, p_user_code character varying DEFAULT NULL::character varying)
 RETURNS core_number_sequence
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.core_number_sequence;
  v_old bigint;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'A reason (min 3 chars) is required to adjust a numbering sequence';
  END IF;
  IF p_new_current IS NULL OR p_new_current < 0 THEN
    RAISE EXCEPTION 'New current number must be >= 0';
  END IF;

  SELECT * INTO v_row FROM public.core_number_sequence WHERE id = p_sequence_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sequence % not found', p_sequence_id; END IF;
  v_old := v_row.current_number;

  UPDATE public.core_number_sequence
     SET current_number = p_new_current,
         updated_by     = COALESCE(p_user_code, updated_by),
         updated_at     = now()
   WHERE id = p_sequence_id
   RETURNING * INTO v_row;

  INSERT INTO public.core_number_sequence_audit(
    sequence_id, module_code, entity_type, country_code,
    generated_number, sequence_value, pattern_used,
    is_override, override_reason, generated_by, context
  ) VALUES (
    v_row.id, v_row.module_code, v_row.entity_type, v_row.country_code,
    format('ADJUST: %s -> %s', v_old, p_new_current),
    p_new_current,
    v_row.number_pattern,
    true,
    p_reason,
    p_user_code,
    jsonb_build_object('action','RESET_OR_ADJUST','previous', v_old, 'new', p_new_current)
  );

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_resolve_template(p_code text, p_country text DEFAULT 'KN'::text)
 RETURNS core_template
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT t.*
  FROM public.core_template t
  WHERE t.code = p_code
    AND t.is_active = true
    AND (
      (t.scope = 'COUNTRY' AND t.country_code = p_country)
      OR t.scope = 'GLOBAL'
    )
  ORDER BY CASE WHEN t.scope = 'COUNTRY' THEN 0 ELSE 1 END
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.core_resolve_template_version(p_code text, p_country text DEFAULT 'KN'::text)
 RETURNS core_template_version
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tpl public.core_template;
  v_ver public.core_template_version;
BEGIN
  SELECT * INTO v_tpl FROM public.core_resolve_template(p_code, p_country);
  IF v_tpl.id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Try chosen template's active version
  IF v_tpl.active_version_id IS NOT NULL THEN
    SELECT * INTO v_ver FROM public.core_template_version
      WHERE id = v_tpl.active_version_id;
    IF v_ver.id IS NOT NULL THEN
      RETURN v_ver;
    END IF;
  END IF;

  -- Fall back to parent GLOBAL template's active version
  IF v_tpl.parent_template_id IS NOT NULL THEN
    SELECT v.* INTO v_ver
      FROM public.core_template_version v
      JOIN public.core_template p ON p.id = v_tpl.parent_template_id
     WHERE v.id = p.active_version_id;
    RETURN v_ver;
  END IF;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_table_registry_validate_naming()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  n text := lower(coalesce(NEW.table_name,''));
BEGIN
  IF NEW.table_prefix IS NULL OR NEW.table_prefix = '' THEN
    IF position('_' IN n) > 0 THEN
      NEW.table_prefix := split_part(n,'_',1) || '_';
    ELSE
      NEW.table_prefix := 'none';
    END IF;
  END IF;

  IF n LIKE 'core\_%' ESCAPE '\' AND NEW.ownership_type <> 'PLATFORM' THEN
    RAISE EXCEPTION 'core_ tables must have ownership_type = PLATFORM (got %)', NEW.ownership_type;
  END IF;
  IF n LIKE 'bn\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'BN' THEN
    RAISE EXCEPTION 'bn_ tables must have module_code = BN';
  END IF;
  IF n LIKE 'er\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'ER' THEN
    RAISE EXCEPTION 'er_ tables must have module_code = ER';
  END IF;
  IF n LIKE 'ip\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'IP' THEN
    RAISE EXCEPTION 'ip_ tables must have module_code = IP';
  END IF;
  IF n LIKE 'c3\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'C3' THEN
    RAISE EXCEPTION 'c3_ tables must have module_code = C3';
  END IF;
  IF n LIKE 'ce\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'CE' THEN
    RAISE EXCEPTION 'ce_ tables must have module_code = CE';
  END IF;
  IF n LIKE 'fin\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'FIN' THEN
    RAISE EXCEPTION 'fin_ tables must have module_code = FIN';
  END IF;
  IF n LIKE 'lg\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'LG' THEN
    RAISE EXCEPTION 'lg_ tables must have module_code = LG';
  END IF;
  IF n LIKE 'rpt\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'RPT' AND NEW.ownership_type <> 'REPORTING' THEN
    RAISE EXCEPTION 'rpt_ tables must have module_code = RPT or ownership_type = REPORTING';
  END IF;
  IF n LIKE 'mig\_%' ESCAPE '\' AND coalesce(NEW.module_code,'') <> 'MIG' AND NEW.ownership_type <> 'MIGRATION' THEN
    RAISE EXCEPTION 'mig_ tables must have module_code = MIG or ownership_type = MIGRATION';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.core_template_layout_list_active(p_layout_kind text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, code text, name text, layout_kind text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  RETURN QUERY SELECT l.id, l.code, l.name, l.layout_kind
    FROM public.core_template_layout l
    WHERE l.is_active = true
      AND (p_layout_kind IS NULL OR l.layout_kind = p_layout_kind)
    ORDER BY l.name;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_template_layout_version_get(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  SELECT to_jsonb(x.*) INTO v FROM public.core_template_layout_version x WHERE x.id = p_id;
  IF v IS NULL THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='layout_version_not_found'; END IF;
  RETURN v;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_template_layout_version_list_published(p_layout_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, layout_id uuid, version_number integer, status text, checksum text, published_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_limit int; v_offset int;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_layout_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_required';
  END IF;
  v_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);
  RETURN QUERY
    SELECT lv.id, lv.layout_id, lv.version_number, lv.status, lv.checksum, lv.published_at
      FROM public.core_template_layout_version lv
     WHERE lv.layout_id = p_layout_id AND lv.status = 'published'
     ORDER BY lv.version_number DESC
     LIMIT v_limit OFFSET v_offset;
END;$function$;
CREATE OR REPLACE FUNCTION public.core_template_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.correct_comm_hub_legacy_baseline_attestation(p_module_code text, p_event_code text, p_channel text, p_reason text, p_typed_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_ore public.communication_controlled_live_certification%ROWTYPE;
  v_prev public.communication_hub_legacy_evidence_attestation%ROWTYPE;
  v_snap jsonb; v_core jsonb; v_fp text; v_new_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF coalesce(p_typed_confirmation,'') <> 'CORRECT LEGACY BASELINE ATTESTATION' THEN
    RETURN jsonb_build_object('ok',false,'phase','TYPED_CONFIRMATION_MISMATCH');
  END IF;
  IF coalesce(trim(p_reason),'')='' THEN
    RETURN jsonb_build_object('ok',false,'phase','REASON_REQUIRED');
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=coalesce(p_channel,'email')
   FOR UPDATE;
  IF NOT FOUND OR v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    RETURN jsonb_build_object('ok',false,'phase','EVENT_NOT_LIVE');
  END IF;

  SELECT * INTO v_ore FROM public.communication_controlled_live_certification
   WHERE id=v_ec.one_real_email_certification_id;

  SELECT * INTO v_prev FROM public.communication_hub_legacy_evidence_attestation
   WHERE production_lineage_id=v_ec.production_lineage_id AND status='ACTIVE'
   ORDER BY attested_at DESC, id DESC LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'phase','NO_ACTIVE_ATTESTATION');
  END IF;

  v_snap := public.get_comm_hub_current_evidence_snapshot(p_module_code,p_event_code,coalesce(p_channel,'email'));
  IF coalesce((v_snap->>'ok')::boolean,false)=false THEN
    RETURN jsonb_build_object('ok',false,'phase','CURRENT_SNAPSHOT_INCOMPLETE','snapshot',v_snap);
  END IF;
  v_core := v_snap->'evidence_core_v2';
  v_fp := public._comm_hub_fingerprint_evidence_core_v2(v_core);

  UPDATE public.communication_hub_legacy_evidence_attestation
     SET status='SUPERSEDED', superseded_at=now()
   WHERE id=v_prev.id;

  INSERT INTO public.communication_hub_legacy_evidence_attestation(
    production_lineage_id, event_certification_id, one_real_email_certification_id,
    current_evidence_snapshot_v2, current_evidence_fingerprint_v2,
    historically_proven_components, historically_unavailable_components,
    attestation_reason, typed_confirmation, attested_by, status,
    supersedes_attestation_id
  ) VALUES (
    v_ec.production_lineage_id, v_ec.id, v_ore.id,
    v_core, v_fp,
    coalesce(v_prev.historically_proven_components,'[]'::jsonb),
    coalesce(v_prev.historically_unavailable_components,'[]'::jsonb),
    p_reason, p_typed_confirmation, v_uid, 'ACTIVE',
    v_prev.id
  ) RETURNING id INTO v_new_id;

  RETURN jsonb_build_object(
    'ok',true,'phase','CORRECTED',
    'previous_attestation_id',v_prev.id,
    'new_attestation_id',v_new_id,
    'current_evidence_fingerprint_v2',v_fp
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_c3_config_period(p_start_date text, p_end_date text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_details_json jsonb DEFAULT '{}'::jsonb, p_user_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start DATE;
  v_end DATE;
  v_first_of_month DATE;
  v_period_id UUID;
  v_detail_id UUID;
  v_existing RECORD;
  v_now TIMESTAMPTZ := now();
  k TEXT;
  v TEXT;
  v_cols TEXT;
  v_vals TEXT;
BEGIN
  v_start := p_start_date::DATE;
  v_end := CASE WHEN p_end_date IS NOT NULL AND p_end_date != '' THEN p_end_date::DATE ELSE NULL END;
  v_first_of_month := date_trunc('month', CURRENT_DATE)::DATE;

  -- Validate dates
  IF v_end IS NOT NULL AND v_end < v_start THEN
    RETURN jsonb_build_object('error', 'End date cannot be before start date.');
  END IF;

  IF v_start < v_first_of_month THEN
    RETURN jsonb_build_object('error', format('Start date cannot be before %s.', to_char(v_first_of_month, 'DD Mon YYYY')));
  END IF;

  -- Check overlap
  SELECT id INTO v_existing FROM c3_config_periods
  WHERE start_date <= COALESCE(v_end, '9999-12-31'::DATE)
    AND COALESCE(end_date, '9999-12-31'::DATE) >= v_start
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'The date range overlaps with an existing configuration period.');
  END IF;

  -- Create period
  v_period_id := gen_random_uuid();
  INSERT INTO c3_config_periods (id, start_date, end_date, description, is_active, created_by, created_on, modified_by, modified_on)
  VALUES (v_period_id, v_start, v_end, p_description, TRUE, p_user_code, v_now, p_user_code, v_now);

  -- Create details
  v_detail_id := gen_random_uuid();
  v_cols := 'id, config_period_id, created_by, created_on, modified_by, modified_on';
  v_vals := format('%L::UUID, %L::UUID, %L, %L::TIMESTAMPTZ, %L, %L::TIMESTAMPTZ',
    v_detail_id, v_period_id, p_user_code, v_now, p_user_code, v_now
  );

  FOR k, v IN SELECT * FROM jsonb_each_text(p_details_json)
  LOOP
    v_cols := v_cols || ', ' || quote_ident(k);
    v_vals := v_vals || ', ' || quote_literal(v);
  END LOOP;

  EXECUTE format('INSERT INTO c3_config_details (%s) VALUES (%s)', v_cols, v_vals);

  -- Audit trail
  INSERT INTO system_audit_trail (action, entity_type, entity_id, module, user_name, after_value, payload_json, timestamp, severity)
  VALUES (
    'create', 'c3_config_periods', v_period_id::TEXT, 'C3 Configuration',
    COALESCE(p_user_code, 'SYSTEM'),
    jsonb_build_object('start_date', p_start_date, 'end_date', p_end_date, 'description', p_description),
    p_details_json,
    v_now, 'info'
  );

  RETURN jsonb_build_object('success', true, 'period_id', v_period_id::TEXT, 'detail_id', v_detail_id::TEXT);
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_c3_payment_with_receipt(p_batch_number text, p_payer_type text, p_payer_id text, p_date_received text, p_remarks text DEFAULT NULL::text, p_components jsonb DEFAULT '[]'::jsonb, p_methods jsonb DEFAULT '[]'::jsonb, p_receipt_total numeric DEFAULT 0, p_user_code text DEFAULT 'SYSTEM'::text, p_is_for_director boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id INTEGER;
  v_receipt_id INTEGER;
  v_comp JSONB;
  v_meth JSONB;
  v_comp_arr JSONB[];
  v_meth_arr JSONB[];
  v_comp_idx INTEGER;
  v_meth_idx INTEGER;
  v_comp_remaining NUMERIC;
  v_meth_remaining NUMERIC;
  v_alloc NUMERIC;
  v_detail_count INTEGER := 0;
  v_exp_date TEXT;
  v_exp_normalized TEXT;
  v_exp_parts TEXT[];
  v_period_text TEXT;
  v_period_ts TIMESTAMP;
  v_period_parts TEXT[];
  v_base_currency TEXT;
  v_method_currency TEXT;
  v_method_rate NUMERIC;
  v_card_machine_id UUID;
  v_mop_code TEXT;
  -- Overpayment guard variables
  v_guard_code TEXT;
  v_guard_original NUMERIC;
  v_guard_paid NUMERIC;
  v_guard_balance NUMERIC;
  v_guard_requested NUMERIC;
  v_guard_period TEXT;
  v_guard_period_ts TIMESTAMP;
  v_guard_seq INTEGER;
BEGIN
  -- === VALIDATION ===
  IF p_batch_number IS NULL OR p_batch_number = '' THEN
    RAISE EXCEPTION 'batch_number is required';
  END IF;
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF jsonb_array_length(p_components) = 0 THEN
    RAISE EXCEPTION 'At least one payment component is required';
  END IF;
  IF jsonb_array_length(p_methods) = 0 THEN
    RAISE EXCEPTION 'At least one payment method is required';
  END IF;
  IF p_receipt_total <= 0 THEN
    RAISE EXCEPTION 'receipt_total must be greater than zero';
  END IF;

  -- === OVERPAYMENT GUARD (sequence_no + period aware) ===
  FOR v_comp IN SELECT * FROM jsonb_array_elements(p_components)
  LOOP
    v_guard_code := v_comp->>'payment_code';
    v_guard_requested := (v_comp->>'amount')::numeric;
    v_guard_period := v_comp->>'period';
    v_guard_seq := (v_comp->>'sequence_no')::integer;

    v_guard_period_ts := NULL;
    IF v_guard_period IS NOT NULL AND v_guard_period != '' THEN
      v_period_parts := string_to_array(v_guard_period, '/');
      IF array_length(v_period_parts, 1) = 2 THEN
        v_guard_period_ts := (v_period_parts[2] || '-' || lpad(v_period_parts[1], 2, '0') || '-01')::timestamp;
      END IF;
    END IF;

    IF v_guard_period_ts IS NOT NULL AND v_guard_seq IS NOT NULL THEN
      SELECT
        CASE v_guard_code
          WHEN 'SSC' THEN COALESCE(emp_ss_amt_calc, 0)
          WHEN 'LVC' THEN COALESCE(emp_levy_amt_calc, 0)
          WHEN 'PEC' THEN COALESCE(emp_pe_amt_calc, 0)
          WHEN 'SSF' THEN COALESCE(emp_ss_fines_due, 0)
          WHEN 'LVF' THEN COALESCE(emp_levy_penalty_amt, 0)
          WHEN 'PEF' THEN COALESCE(emp_pe_penalty_amt, 0)
          WHEN 'SSE' THEN COALESCE(emp_ss_amt_calc, 0)
          WHEN 'SEF' THEN COALESCE(emp_ss_fines_due, 0)
          WHEN 'VOC' THEN COALESCE(emp_ss_amt_calc, 0)
          ELSE 0
        END
      INTO v_guard_original
      FROM cn_c3_reported
      WHERE payer_id = p_payer_id
        AND payer_type = p_payer_type
        AND period = v_guard_period_ts
        AND sequence_no = v_guard_seq
        AND COALESCE(is_for_director, FALSE) = COALESCE(p_is_for_director, FALSE)
      LIMIT 1;

      IF v_guard_original IS NULL THEN
        v_guard_original := 0;
      END IF;

      -- FIX: Added cpc.period = v_guard_period to prevent cross-period sum inflation
      SELECT COALESCE(SUM(cpc.component_amount), 0)
      INTO v_guard_paid
      FROM c3_payment_components cpc
      INNER JOIN cn_payment_header h ON h.payment_id = cpc.payment_id
      INNER JOIN cn_receipt r ON r.payment_id = cpc.payment_id
      WHERE h.payer_id = p_payer_id
        AND h.payer_type = p_payer_type
        AND h.status IS DISTINCT FROM 'deleted'
        AND r.status != 'C'
        AND COALESCE(h.is_for_director, FALSE) = COALESCE(p_is_for_director, FALSE)
        AND cpc.payment_code = v_guard_code
        AND cpc.sequence_no = v_guard_seq
        AND cpc.period = v_guard_period;

      v_guard_balance := GREATEST(v_guard_original - v_guard_paid, 0);

      IF v_guard_requested > v_guard_balance + 0.01 THEN
        RAISE EXCEPTION 'Overpayment detected for component %: requested=%, balance=% (original=%, paid=%)',
          v_guard_code, v_guard_requested, v_guard_balance, v_guard_original, v_guard_paid;
      END IF;
    END IF;
  END LOOP;
  -- === END OVERPAYMENT GUARD ===

  -- === CURRENCY VALIDATION ===
  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;

  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured in tb_currencies. Cannot create receipt.';
  END IF;

  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;
    IF v_method_rate IS NULL THEN
      RAISE EXCEPTION 'Currency "%" not found or inactive in tb_currencies. Cannot create receipt.', v_method_currency;
    END IF;

    v_mop_code := v_meth->>'mop_code';
    IF v_mop_code IN ('CRD', 'DRD') AND (v_meth->>'card_machine_id' IS NULL OR v_meth->>'card_machine_id' = '') THEN
      RAISE EXCEPTION 'card_machine_id is required for payment method %', v_mop_code;
    END IF;
  END LOOP;

  -- === ADVISORY LOCK & PAYMENT ID ===
  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  -- === INSERT PAYMENT HEADER ===
  INSERT INTO public.cn_payment_header (
    payment_id, batch_number, payer_type, payer_id, date_received, remarks, is_for_director
  ) VALUES (
    v_payment_id, p_batch_number, p_payer_type, p_payer_id, p_date_received::timestamp, p_remarks,
    COALESCE(p_is_for_director, FALSE)
  );

  -- === INSERT C3 PAYMENT COMPONENTS ===
  FOR v_comp IN SELECT * FROM jsonb_array_elements(p_components)
  LOOP
    INSERT INTO public.c3_payment_components (
      payment_id, payment_code, fund_code, component_amount, period, sort_order, sequence_no
    ) VALUES (
      v_payment_id,
      v_comp->>'payment_code',
      v_comp->>'fund_code',
      (v_comp->>'amount')::numeric,
      v_comp->>'period',
      COALESCE((v_comp->>'sort_order')::integer, 0),
      (v_comp->>'sequence_no')::integer
    );
  END LOOP;

  -- === INSERT C3 PAYMENT METHODS ===
  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_exp_normalized := NULL;
    v_exp_date := v_meth->>'expiration_date';
    IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
      v_exp_parts := string_to_array(v_exp_date, '/');
      IF array_length(v_exp_parts, 1) = 2 THEN
        v_exp_normalized := '20' || lpad(v_exp_parts[2], 2, '0') || '-' || lpad(v_exp_parts[1], 2, '0') || '-01';
      END IF;
    END IF;

    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;

    v_card_machine_id := NULL;
    IF v_meth->>'card_machine_id' IS NOT NULL AND v_meth->>'card_machine_id' != '' THEN
      v_card_machine_id := (v_meth->>'card_machine_id')::uuid;
    END IF;

    INSERT INTO public.c3_payment_methods (
      payment_id, mop_code, currency_code, original_amount, exchange_rate, base_amount,
      base_currency, bank_code, mop_number, cheque_date, mop_account_number, mop_notes1,
      credit_card_code, expiration_date, sort_order
    ) VALUES (
      v_payment_id,
      v_meth->>'mop_code',
      v_method_currency,
      (v_meth->>'original_amount')::numeric,
      v_method_rate,
      ROUND((v_meth->>'original_amount')::numeric / v_method_rate, 2),
      v_base_currency,
      v_meth->>'bank_code',
      v_meth->>'mop_number',
      CASE WHEN v_meth->>'cheque_date' IS NOT NULL AND v_meth->>'cheque_date' != ''
           THEN (v_meth->>'cheque_date')::date ELSE NULL END,
      v_meth->>'mop_account_number',
      v_meth->>'mop_notes1',
      v_meth->>'credit_card_code',
      CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END,
      COALESCE((v_meth->>'sort_order')::integer, 0)
    );
  END LOOP;

  -- === CROSS-PRODUCT ALLOCATION: cn_payment rows ===
  SELECT array_agg(value ORDER BY (value->>'sort_order')::int)
  INTO v_comp_arr
  FROM jsonb_array_elements(p_components) AS t(value);

  SELECT array_agg(value ORDER BY (value->>'sort_order')::int)
  INTO v_meth_arr
  FROM jsonb_array_elements(p_methods) AS t(value);

  v_comp_idx := 1;
  v_meth_idx := 1;
  v_comp_remaining := (v_comp_arr[1]->>'amount')::numeric;

  v_method_currency := COALESCE(v_meth_arr[1]->>'currency_code', v_base_currency);
  SELECT exchange_rate INTO v_method_rate
  FROM public.tb_currencies
  WHERE currency_code = v_method_currency AND is_active = true
  LIMIT 1;
  v_meth_remaining := ROUND((v_meth_arr[1]->>'original_amount')::numeric / v_method_rate, 2);

  WHILE v_comp_idx <= array_length(v_comp_arr, 1)
    AND v_meth_idx <= array_length(v_meth_arr, 1)
  LOOP
    v_alloc := LEAST(v_comp_remaining, v_meth_remaining);
    IF v_alloc <= 0 THEN
      v_alloc := 0;
    END IF;

    v_period_text := v_comp_arr[v_comp_idx]->>'period';
    v_period_ts := NULL;
    IF v_period_text IS NOT NULL AND v_period_text != '' THEN
      v_period_parts := string_to_array(v_period_text, '/');
      IF array_length(v_period_parts, 1) = 2 THEN
        v_period_ts := (v_period_parts[2] || '-' || lpad(v_period_parts[1], 2, '0') || '-01')::timestamp;
      END IF;
    END IF;

    v_exp_normalized := NULL;
    v_exp_date := v_meth_arr[v_meth_idx]->>'expiration_date';
    IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
      v_exp_parts := string_to_array(v_exp_date, '/');
      IF array_length(v_exp_parts, 1) = 2 THEN
        v_exp_normalized := '20' || lpad(v_exp_parts[2], 2, '0') || '-' || lpad(v_exp_parts[1], 2, '0') || '-01';
      END IF;
    END IF;

    v_card_machine_id := NULL;
    IF v_meth_arr[v_meth_idx]->>'card_machine_id' IS NOT NULL AND v_meth_arr[v_meth_idx]->>'card_machine_id' != '' THEN
      v_card_machine_id := (v_meth_arr[v_meth_idx]->>'card_machine_id')::uuid;
    END IF;

    INSERT INTO public.cn_payment (
      payment_id, payment_code, fund_code, payment_amount, period,
      mop_code, bank_code, bank_lodgement_code,
      mop_number, cheque_date, mop_account_number, mop_transit_number,
      mop_notes1, credit_card_code, expiration_date
    ) VALUES (
      v_payment_id,
      v_comp_arr[v_comp_idx]->>'payment_code',
      v_comp_arr[v_comp_idx]->>'fund_code',
      v_alloc,
      v_period_ts,
      v_meth_arr[v_meth_idx]->>'mop_code',
      v_meth_arr[v_meth_idx]->>'bank_code',
      NULL,
      v_meth_arr[v_meth_idx]->>'mop_number',
      CASE WHEN v_meth_arr[v_meth_idx]->>'cheque_date' IS NOT NULL AND v_meth_arr[v_meth_idx]->>'cheque_date' != ''
           THEN (v_meth_arr[v_meth_idx]->>'cheque_date')::date ELSE NULL END,
      v_meth_arr[v_meth_idx]->>'mop_account_number',
      NULL,
      v_meth_arr[v_meth_idx]->>'mop_notes1',
      v_meth_arr[v_meth_idx]->>'credit_card_code',
      CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END
    );
    v_detail_count := v_detail_count + 1;

    v_comp_remaining := v_comp_remaining - v_alloc;
    v_meth_remaining := v_meth_remaining - v_alloc;

    IF v_comp_remaining <= 0.001 THEN
      v_comp_idx := v_comp_idx + 1;
      IF v_comp_idx <= array_length(v_comp_arr, 1) THEN
        v_comp_remaining := (v_comp_arr[v_comp_idx]->>'amount')::numeric;
      END IF;
    END IF;

    IF v_meth_remaining <= 0.001 THEN
      v_meth_idx := v_meth_idx + 1;
      IF v_meth_idx <= array_length(v_meth_arr, 1) THEN
        v_method_currency := COALESCE(v_meth_arr[v_meth_idx]->>'currency_code', v_base_currency);
        SELECT exchange_rate INTO v_method_rate
        FROM public.tb_currencies
        WHERE currency_code = v_method_currency AND is_active = true
        LIMIT 1;
        v_meth_remaining := ROUND((v_meth_arr[v_meth_idx]->>'original_amount')::numeric / v_method_rate, 2);
      END IF;
    END IF;
  END LOOP;

  -- === CREATE RECEIPT ===
  INSERT INTO public.cn_receipt (
    payment_id, receipt_total, status, total_number_of_payments, created_by
  ) VALUES (
    v_payment_id, p_receipt_total, 'A', v_detail_count, p_user_code
  )
  RETURNING receipt_id INTO v_receipt_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'detail_count', v_detail_count,
    'receipt_total', p_receipt_total
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_c3_payment_with_receipt_v1(p_batch_number text, p_payer_type text, p_payer_id text, p_date_received date, p_remarks text DEFAULT NULL::text, p_components jsonb DEFAULT '[]'::jsonb, p_methods jsonb DEFAULT '[]'::jsonb, p_receipt_total numeric DEFAULT 0, p_user_code text DEFAULT 'SYS'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id INTEGER;
  v_receipt_id INTEGER;
  v_comp JSONB;
  v_meth JSONB;
  v_comp_arr JSONB[];
  v_meth_arr JSONB[];
  v_comp_idx INTEGER;
  v_meth_idx INTEGER;
  v_comp_remaining NUMERIC;
  v_meth_remaining NUMERIC;
  v_alloc NUMERIC;
  v_detail_count INTEGER := 0;
  v_exp_date TEXT;
  v_exp_normalized TEXT;
  v_exp_parts TEXT[];
  v_period_text TEXT;
  v_period_ts TIMESTAMP;
  v_period_parts TEXT[];
  v_base_currency TEXT;
  v_method_currency TEXT;
  v_method_rate NUMERIC;
BEGIN
  IF p_batch_number IS NULL OR p_batch_number = '' THEN
    RAISE EXCEPTION 'batch_number is required';
  END IF;
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF jsonb_array_length(p_components) = 0 THEN
    RAISE EXCEPTION 'At least one payment component is required';
  END IF;
  IF jsonb_array_length(p_methods) = 0 THEN
    RAISE EXCEPTION 'At least one payment method is required';
  END IF;
  IF p_receipt_total <= 0 THEN
    RAISE EXCEPTION 'receipt_total must be greater than zero';
  END IF;

  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;

  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured in tb_currencies. Cannot create receipt.';
  END IF;

  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;
    IF v_method_rate IS NULL THEN
      RAISE EXCEPTION 'Currency "%" not found or inactive in tb_currencies. Cannot create receipt.', v_method_currency;
    END IF;
  END LOOP;

  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  INSERT INTO public.cn_payment_header (
    payment_id, batch_number, payer_type, payer_id, date_received, remarks
  ) VALUES (
    v_payment_id, p_batch_number, p_payer_type, p_payer_id, p_date_received, p_remarks
  );

  FOR v_comp IN SELECT * FROM jsonb_array_elements(p_components)
  LOOP
    INSERT INTO public.c3_payment_components (
      payment_id, payment_code, fund_code, component_amount, period, sort_order, sequence_no
    ) VALUES (
      v_payment_id,
      v_comp->>'payment_code',
      v_comp->>'fund_code',
      (v_comp->>'amount')::numeric,
      v_comp->>'period',
      COALESCE((v_comp->>'sort_order')::integer, 0),
      (v_comp->>'sequence_no')::integer
    );
  END LOOP;

  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_exp_normalized := NULL;
    v_exp_date := v_meth->>'expiration_date';
    IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
      v_exp_parts := string_to_array(v_exp_date, '/');
      IF array_length(v_exp_parts, 1) = 2 THEN
        v_exp_normalized := '20' || lpad(v_exp_parts[2], 2, '0') || '-' || lpad(v_exp_parts[1], 2, '0') || '-01';
      END IF;
    END IF;

    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;

    INSERT INTO public.c3_payment_methods (
      payment_id, mop_code, currency_code, original_amount, exchange_rate, base_amount,
      base_currency, bank_code, mop_number, cheque_date, mop_account_number, mop_notes1,
      credit_card_code, expiration_date, sort_order
    ) VALUES (
      v_payment_id,
      v_meth->>'mop_code',
      v_method_currency,
      (v_meth->>'original_amount')::numeric,
      v_method_rate,
      ROUND((v_meth->>'original_amount')::numeric / v_method_rate, 2),
      v_base_currency,
      v_meth->>'bank_code',
      v_meth->>'mop_number',
      CASE WHEN v_meth->>'cheque_date' IS NOT NULL AND v_meth->>'cheque_date' != ''
           THEN (v_meth->>'cheque_date')::date ELSE NULL END,
      v_meth->>'mop_account_number',
      v_meth->>'mop_notes1',
      v_meth->>'credit_card_code',
      CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END,
      COALESCE((v_meth->>'sort_order')::integer, 0)
    );
  END LOOP;

  SELECT array_agg(value ORDER BY (value->>'sort_order')::int)
  INTO v_comp_arr
  FROM jsonb_array_elements(p_components) AS t(value);

  SELECT array_agg(value ORDER BY (value->>'sort_order')::int)
  INTO v_meth_arr
  FROM jsonb_array_elements(p_methods) AS t(value);

  v_comp_idx := 1;
  v_meth_idx := 1;
  v_comp_remaining := (v_comp_arr[1]->>'amount')::numeric;

  v_method_currency := COALESCE(v_meth_arr[1]->>'currency_code', v_base_currency);
  SELECT exchange_rate INTO v_method_rate
  FROM public.tb_currencies
  WHERE currency_code = v_method_currency AND is_active = true
  LIMIT 1;
  v_meth_remaining := ROUND((v_meth_arr[1]->>'original_amount')::numeric / v_method_rate, 2);

  WHILE v_comp_idx <= array_length(v_comp_arr, 1) AND v_meth_idx <= array_length(v_meth_arr, 1)
  LOOP
    v_alloc := LEAST(v_comp_remaining, v_meth_remaining);

    IF v_alloc > 0 THEN
      v_period_text := v_comp_arr[v_comp_idx]->>'period';
      v_period_ts := NULL;
      IF v_period_text IS NOT NULL AND v_period_text != '' THEN
        v_period_parts := string_to_array(v_period_text, '/');
        IF array_length(v_period_parts, 1) = 2 THEN
          v_period_ts := (v_period_parts[2] || '-' || lpad(v_period_parts[1], 2, '0') || '-01')::timestamp;
        END IF;
      END IF;

      INSERT INTO public.cn_payment (
        payment_id, payment_code, fund_code, period, payment_amount,
        mop_code, base_currency, currency_conversion_rate, currency_code
      ) VALUES (
        v_payment_id,
        v_comp_arr[v_comp_idx]->>'payment_code',
        v_comp_arr[v_comp_idx]->>'fund_code',
        v_period_ts,
        v_alloc,
        v_meth_arr[v_meth_idx]->>'mop_code',
        v_base_currency,
        v_method_rate,
        v_method_currency
      );
      v_detail_count := v_detail_count + 1;
    END IF;

    v_comp_remaining := v_comp_remaining - v_alloc;
    v_meth_remaining := v_meth_remaining - v_alloc;

    IF v_comp_remaining <= 0 THEN
      v_comp_idx := v_comp_idx + 1;
      IF v_comp_idx <= array_length(v_comp_arr, 1) THEN
        v_comp_remaining := (v_comp_arr[v_comp_idx]->>'amount')::numeric;
      END IF;
    END IF;

    IF v_meth_remaining <= 0 THEN
      v_meth_idx := v_meth_idx + 1;
      IF v_meth_idx <= array_length(v_meth_arr, 1) THEN
        v_method_currency := COALESCE(v_meth_arr[v_meth_idx]->>'currency_code', v_base_currency);
        SELECT exchange_rate INTO v_method_rate
        FROM public.tb_currencies
        WHERE currency_code = v_method_currency AND is_active = true
        LIMIT 1;
        v_meth_remaining := ROUND((v_meth_arr[v_meth_idx]->>'original_amount')::numeric / v_method_rate, 2);
      END IF;
    END IF;
  END LOOP;

  INSERT INTO public.cn_receipt (
    payment_id, receipt_total, status,
    created_by, created_at
  ) VALUES (
    v_payment_id, p_receipt_total, 'O',
    p_user_code, NOW()
  )
  RETURNING receipt_id INTO v_receipt_id;

  INSERT INTO public.cn_receipt_prints (
    receipt_id, printed_by, print_type
  ) VALUES (
    v_receipt_id, p_user_code, 'ORIGINAL'
  );

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'detail_count', v_detail_count,
    'base_currency', v_base_currency
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_c3_payment_with_receipt_v2(p_batch_number text, p_payer_type text, p_payer_id text, p_date_received text, p_remarks text DEFAULT NULL::text, p_components jsonb DEFAULT '[]'::jsonb, p_methods jsonb DEFAULT '[]'::jsonb, p_receipt_total numeric DEFAULT 0, p_user_code text DEFAULT 'SYSTEM'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id INTEGER;
  v_receipt_id INTEGER;
  v_comp JSONB;
  v_meth JSONB;
  v_comp_arr JSONB[];
  v_meth_arr JSONB[];
  v_comp_idx INTEGER;
  v_meth_idx INTEGER;
  v_comp_remaining NUMERIC;
  v_meth_remaining NUMERIC;
  v_alloc NUMERIC;
  v_detail_count INTEGER := 0;
  v_exp_date TEXT;
  v_exp_normalized TEXT;
  v_exp_parts TEXT[];
  v_period_text TEXT;
  v_period_ts TIMESTAMP;
  v_period_parts TEXT[];
  v_base_currency TEXT;
  v_method_currency TEXT;
  v_method_rate NUMERIC;
  v_card_machine_id UUID;
  v_mop_code TEXT;
BEGIN
  IF p_batch_number IS NULL OR p_batch_number = '' THEN
    RAISE EXCEPTION 'batch_number is required';
  END IF;
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF jsonb_array_length(p_components) = 0 THEN
    RAISE EXCEPTION 'At least one payment component is required';
  END IF;
  IF jsonb_array_length(p_methods) = 0 THEN
    RAISE EXCEPTION 'At least one payment method is required';
  END IF;
  IF p_receipt_total <= 0 THEN
    RAISE EXCEPTION 'receipt_total must be greater than zero';
  END IF;

  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;

  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured in tb_currencies. Cannot create receipt.';
  END IF;

  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;
    IF v_method_rate IS NULL THEN
      RAISE EXCEPTION 'Currency "%" not found or inactive in tb_currencies. Cannot create receipt.', v_method_currency;
    END IF;

    -- Server-side validation: CRD/DRD requires card_machine_id
    v_mop_code := v_meth->>'mop_code';
    IF v_mop_code IN ('CRD', 'DRD') AND (v_meth->>'card_machine_id' IS NULL OR v_meth->>'card_machine_id' = '') THEN
      RAISE EXCEPTION 'card_machine_id is required for payment method %', v_mop_code;
    END IF;
  END LOOP;

  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  INSERT INTO public.cn_payment_header (
    payment_id, batch_number, payer_type, payer_id, date_received, remarks
  ) VALUES (
    v_payment_id, p_batch_number, p_payer_type, p_payer_id, p_date_received, p_remarks
  );

  FOR v_comp IN SELECT * FROM jsonb_array_elements(p_components)
  LOOP
    INSERT INTO public.c3_payment_components (
      payment_id, payment_code, fund_code, component_amount, period, sort_order, sequence_no
    ) VALUES (
      v_payment_id,
      v_comp->>'payment_code',
      v_comp->>'fund_code',
      (v_comp->>'amount')::numeric,
      v_comp->>'period',
      COALESCE((v_comp->>'sort_order')::integer, 0),
      (v_comp->>'sequence_no')::integer
    );
  END LOOP;

  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_exp_normalized := NULL;
    v_exp_date := v_meth->>'expiration_date';
    IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
      v_exp_parts := string_to_array(v_exp_date, '/');
      IF array_length(v_exp_parts, 1) = 2 THEN
        v_exp_normalized := '20' || lpad(v_exp_parts[2], 2, '0') || '-' || lpad(v_exp_parts[1], 2, '0') || '-01';
      END IF;
    END IF;

    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;

    v_card_machine_id := NULL;
    IF v_meth->>'card_machine_id' IS NOT NULL AND v_meth->>'card_machine_id' != '' THEN
      v_card_machine_id := (v_meth->>'card_machine_id')::uuid;
    END IF;

    INSERT INTO public.c3_payment_methods (
      payment_id, mop_code, currency_code, original_amount, exchange_rate, base_amount,
      base_currency, bank_code, mop_number, cheque_date, mop_account_number, mop_notes1,
      credit_card_code, expiration_date, sort_order
    ) VALUES (
      v_payment_id,
      v_meth->>'mop_code',
      v_method_currency,
      (v_meth->>'original_amount')::numeric,
      v_method_rate,
      ROUND((v_meth->>'original_amount')::numeric / v_method_rate, 2),
      v_base_currency,
      v_meth->>'bank_code',
      v_meth->>'mop_number',
      CASE WHEN v_meth->>'cheque_date' IS NOT NULL AND v_meth->>'cheque_date' != ''
           THEN (v_meth->>'cheque_date')::date ELSE NULL END,
      v_meth->>'mop_account_number',
      v_meth->>'mop_notes1',
      v_meth->>'credit_card_code',
      CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END,
      COALESCE((v_meth->>'sort_order')::integer, 0)
    );
  END LOOP;

  SELECT array_agg(value ORDER BY (value->>'sort_order')::int)
  INTO v_comp_arr
  FROM jsonb_array_elements(p_components) AS t(value);

  SELECT array_agg(value ORDER BY (value->>'sort_order')::int)
  INTO v_meth_arr
  FROM jsonb_array_elements(p_methods) AS t(value);

  v_comp_idx := 1;
  v_meth_idx := 1;
  v_comp_remaining := (v_comp_arr[1]->>'amount')::numeric;

  v_method_currency := COALESCE(v_meth_arr[1]->>'currency_code', v_base_currency);
  SELECT exchange_rate INTO v_method_rate
  FROM public.tb_currencies
  WHERE currency_code = v_method_currency AND is_active = true
  LIMIT 1;
  v_meth_remaining := ROUND((v_meth_arr[1]->>'original_amount')::numeric / v_method_rate, 2);

  WHILE v_comp_idx <= array_length(v_comp_arr, 1) AND v_meth_idx <= array_length(v_meth_arr, 1)
  LOOP
    v_alloc := LEAST(v_comp_remaining, v_meth_remaining);

    IF v_alloc > 0 THEN
      v_period_text := v_comp_arr[v_comp_idx]->>'period';
      v_period_ts := NULL;
      IF v_period_text IS NOT NULL AND v_period_text != '' THEN
        v_period_parts := string_to_array(v_period_text, '/');
        IF array_length(v_period_parts, 1) = 2 THEN
          v_period_ts := (v_period_parts[2] || '-' || lpad(v_period_parts[1], 2, '0') || '-01')::timestamp;
        END IF;
      END IF;

      v_card_machine_id := NULL;
      IF v_meth_arr[v_meth_idx]->>'card_machine_id' IS NOT NULL AND v_meth_arr[v_meth_idx]->>'card_machine_id' != '' THEN
        v_card_machine_id := (v_meth_arr[v_meth_idx]->>'card_machine_id')::uuid;
      END IF;

      INSERT INTO public.cn_payment (
        payment_id, payment_code, fund_code, period, payment_amount,
        mop_code, base_currency, currency_conversion_rate, currency_code,
        card_machine_id
      ) VALUES (
        v_payment_id,
        v_comp_arr[v_comp_idx]->>'payment_code',
        v_comp_arr[v_comp_idx]->>'fund_code',
        v_period_ts,
        v_alloc,
        v_meth_arr[v_meth_idx]->>'mop_code',
        v_base_currency,
        v_method_rate,
        v_method_currency,
        v_card_machine_id
      );
      v_detail_count := v_detail_count + 1;
    END IF;

    v_comp_remaining := v_comp_remaining - v_alloc;
    v_meth_remaining := v_meth_remaining - v_alloc;

    IF v_comp_remaining <= 0 THEN
      v_comp_idx := v_comp_idx + 1;
      IF v_comp_idx <= array_length(v_comp_arr, 1) THEN
        v_comp_remaining := (v_comp_arr[v_comp_idx]->>'amount')::numeric;
      END IF;
    END IF;

    IF v_meth_remaining <= 0 THEN
      v_meth_idx := v_meth_idx + 1;
      IF v_meth_idx <= array_length(v_meth_arr, 1) THEN
        v_method_currency := COALESCE(v_meth_arr[v_meth_idx]->>'currency_code', v_base_currency);
        SELECT exchange_rate INTO v_method_rate
        FROM public.tb_currencies
        WHERE currency_code = v_method_currency AND is_active = true
        LIMIT 1;
        v_meth_remaining := ROUND((v_meth_arr[v_meth_idx]->>'original_amount')::numeric / v_method_rate, 2);
      END IF;
    END IF;
  END LOOP;

  INSERT INTO public.cn_receipt (
    payment_id, receipt_total, status,
    created_by, created_at
  ) VALUES (
    v_payment_id, p_receipt_total, 'A',
    p_user_code, NOW()
  )
  RETURNING receipt_id INTO v_receipt_id;

  INSERT INTO public.cn_receipt_prints (
    receipt_id, printed_by, print_type
  ) VALUES (
    v_receipt_id, p_user_code, 'ORIGINAL'
  );

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'detail_count', v_detail_count,
    'base_currency', v_base_currency
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_comm_hub_controlled_stub_message(p_execution_id uuid, p_grant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_execution  public.communication_controlled_live_execution%ROWTYPE;
  v_grant      public.communication_controlled_live_grant%ROWTYPE;
  v_approval   public.communication_preview_approval%ROWTYPE;
  v_snapshot   public.communication_preview_snapshot%ROWTYPE;
  v_dry_run    public.communication_dry_run_certification%ROWTYPE;
  v_governance public.comm_hub_certification;
  v_governance_id uuid; v_dep_hash text;
  v_first jsonb; v_first_type text;
  v_to_email   text; v_to_name text;
  v_to_count   int; v_cc_count int; v_bcc_count int;
  v_sender     public.communication_hub_sender_profile%ROWTYPE;
  v_sender_from  text;
  v_sender_name  text;
  v_sender_reply text;
  v_action     text := 'RUN_CONTROLLED_STUB';
  v_idem_key   text;
  v_request_id uuid; v_request_no text;
  v_recipient_id uuid; v_message_id uuid; v_existing_msg uuid;
  v_exec_recipient text;
  v_recomputed_hash text; v_norm jsonb;
BEGIN
  IF p_execution_id IS NULL OR p_grant_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'input_invalid',
      'message', 'execution_id and grant_id are required');
  END IF;

  SELECT * INTO v_execution FROM public.communication_controlled_live_execution
   WHERE id = p_execution_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'execution_not_found');
  END IF;

  SELECT * INTO v_grant FROM public.communication_controlled_live_grant
   WHERE id = p_grant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'grant_not_found'); END IF;
  IF v_grant.execution_id <> v_execution.id THEN
    RETURN jsonb_build_object('ok', false, 'code', 'grant_execution_mismatch');
  END IF;
  IF v_grant.status NOT IN ('ISSUED','RESERVED') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'grant_not_dispatchable',
      'grant_status', v_grant.status);
  END IF;
  IF v_grant.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'grant_expired');
  END IF;

  v_idem_key := 'controlled-stub:request:' || v_execution.id::text || ':' || v_action;

  SELECT id INTO v_request_id FROM public.communication_request WHERE idempotency_key = v_idem_key;
  IF FOUND THEN
    SELECT id INTO v_existing_msg FROM public.communication_message
     WHERE request_id = v_request_id AND targeted_dispatch_only = true
       AND controlled_live_execution_id = v_execution.id
       AND controlled_live_grant_id = v_grant.id
       AND controlled_action = v_action;
    IF v_existing_msg IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'idempotency_conflict_incomplete',
        'message', 'request exists but authoritative message does not match');
    END IF;
    SELECT id INTO v_recipient_id FROM public.communication_recipient
     WHERE request_id = v_request_id AND role='to' LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'idempotent_replay', true, 'action', v_action,
      'request_id', v_request_id, 'message_id', v_existing_msg,
      'recipient_id', v_recipient_id,
      'execution_id', v_execution.id, 'grant_id', v_grant.id);
  END IF;

  SELECT * INTO v_approval FROM public.communication_preview_approval
   WHERE id = v_execution.preview_approval_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'preview_approval_missing'); END IF;
  IF v_approval.status NOT IN ('ACTIVE','RESERVED') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'preview_approval_not_usable',
      'approval_status', v_approval.status);
  END IF;
  IF v_approval.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'preview_approval_expired');
  END IF;
  IF v_grant.preview_approval_id <> v_approval.id THEN
    RETURN jsonb_build_object('ok', false, 'code', 'grant_preview_mismatch');
  END IF;

  SELECT * INTO v_snapshot FROM public.communication_preview_snapshot WHERE id = v_approval.snapshot_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'preview_snapshot_missing'); END IF;
  IF v_snapshot.status <> 'PREPARED' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'preview_snapshot_not_prepared',
      'snapshot_status', v_snapshot.status);
  END IF;
  IF v_snapshot.expires_at IS NOT NULL AND v_snapshot.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'preview_snapshot_expired');
  END IF;
  IF v_snapshot.content_hash IS DISTINCT FROM v_approval.content_hash_at_approval THEN
    RETURN jsonb_build_object('ok', false, 'code', 'preview_content_hash_mismatch');
  END IF;

  SELECT * INTO v_dry_run FROM public.communication_dry_run_certification
   WHERE id = v_execution.dry_run_certification_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'dry_run_certification_missing'); END IF;
  IF v_dry_run.status <> 'ACTIVE' OR v_dry_run.result <> 'DRY_RUN_PASSED' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'dry_run_certification_not_valid',
      'status', v_dry_run.status, 'result', v_dry_run.result);
  END IF;
  IF v_dry_run.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'dry_run_certification_expired');
  END IF;
  IF v_dry_run.preview_approval_id IS DISTINCT FROM v_approval.id THEN
    RETURN jsonb_build_object('ok', false, 'code', 'dry_run_approval_mismatch');
  END IF;

  IF v_snapshot.template_version_id IS NOT NULL THEN
    SELECT * INTO v_governance FROM public.comm_hub_certification
     WHERE entity_type = 'TEMPLATE_VERSION' AND entity_id = v_snapshot.template_version_id
       AND result = 'PASSED' AND is_stale = false
     ORDER BY certified_at DESC LIMIT 1;
    IF FOUND THEN v_governance_id := v_governance.id; v_dep_hash := v_governance.dependency_hash; END IF;
  END IF;

  v_to_count := COALESCE(jsonb_array_length(v_snapshot.to_recipients), 0);
  v_cc_count := COALESCE(jsonb_array_length(v_snapshot.cc_recipients), 0);
  v_bcc_count := COALESCE(jsonb_array_length(v_snapshot.bcc_recipients), 0);
  IF v_to_count <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'recipient_count_invalid', 'to_count', v_to_count);
  END IF;
  IF v_cc_count > 0 THEN RETURN jsonb_build_object('ok', false, 'code', 'cc_not_allowed'); END IF;
  IF v_bcc_count > 0 THEN RETURN jsonb_build_object('ok', false, 'code', 'bcc_not_allowed'); END IF;

  v_first := v_snapshot.to_recipients->0;
  v_first_type := jsonb_typeof(v_first);
  IF v_first_type = 'string' THEN
    v_to_email := lower(btrim(v_snapshot.to_recipients->>0));
    v_to_name  := NULL;
  ELSIF v_first_type = 'object' THEN
    v_to_email := lower(btrim(COALESCE(v_first->>'email','')));
    v_to_name  := v_first->>'name';
  ELSE
    RETURN jsonb_build_object('ok', false, 'code', 'recipient_shape_invalid',
      'message', 'to_recipients[0] must be a string or object', 'jsonb_type', v_first_type);
  END IF;
  IF v_to_email IS NULL OR v_to_email = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'recipient_email_missing');
  END IF;

  v_exec_recipient := lower(btrim(COALESCE(v_execution.recipient,'')));
  IF v_exec_recipient <> '' AND v_exec_recipient <> v_to_email THEN
    RETURN jsonb_build_object('ok', false, 'code', 'recipient_execution_mismatch',
      'detail', jsonb_build_object('snapshot_email', v_to_email, 'execution_recipient', v_exec_recipient));
  END IF;

  v_norm := public.comm_hub_normalize_recipient_set(
    jsonb_build_array(v_to_email), '[]'::jsonb, '[]'::jsonb);
  v_recomputed_hash := v_norm->>'recipient_set_hash';
  IF v_recomputed_hash IS DISTINCT FROM v_snapshot.recipient_set_hash THEN
    RETURN jsonb_build_object('ok', false, 'code', 'recipient_hash_snapshot_mismatch',
      'detail', jsonb_build_object('recomputed', v_recomputed_hash, 'snapshot', v_snapshot.recipient_set_hash));
  END IF;
  IF v_recomputed_hash IS DISTINCT FROM v_grant.recipient_set_hash THEN
    RETURN jsonb_build_object('ok', false, 'code', 'recipient_hash_grant_mismatch',
      'detail', jsonb_build_object('recomputed', v_recomputed_hash, 'grant', v_grant.recipient_set_hash));
  END IF;

  IF v_snapshot.template_version_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'template_version_missing');
  END IF;
  IF v_snapshot.sender_profile_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'sender_profile_missing');
  END IF;
  IF v_snapshot.rendered_subject IS NULL OR btrim(v_snapshot.rendered_subject) = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'rendered_subject_missing');
  END IF;
  IF (v_snapshot.rendered_body_html IS NULL OR btrim(v_snapshot.rendered_body_html) = '')
     AND (v_snapshot.rendered_body_text IS NULL OR btrim(v_snapshot.rendered_body_text) = '') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'rendered_body_missing');
  END IF;
  IF v_snapshot.subject_hash IS NULL OR v_snapshot.body_hash IS NULL
     OR v_snapshot.content_hash IS NULL OR v_snapshot.recipient_set_hash IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'snapshot_hashes_missing');
  END IF;

  SELECT * INTO v_sender FROM public.communication_hub_sender_profile WHERE id = v_snapshot.sender_profile_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'sender_profile_not_found'); END IF;

  v_sender_from  := btrim(COALESCE(v_sender.from_email, ''));
  v_sender_name  := btrim(COALESCE(v_sender.display_name, ''));
  v_sender_reply := btrim(COALESCE(v_sender.reply_to_email, ''));
  IF v_sender_from = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'sender_from_email_missing',
      'detail', jsonb_build_object('sender_profile_id', v_sender.id));
  END IF;
  IF v_sender_name = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'sender_display_name_missing',
      'detail', jsonb_build_object('sender_profile_id', v_sender.id));
  END IF;
  IF v_sender_reply = '' THEN v_sender_reply := v_sender_from; END IF;

  PERFORM set_config('comm_hub.allow_targeted_update', 'true', true);

  v_request_no := 'CS-' || to_char(now() AT TIME ZONE 'UTC','YYYYMMDDHH24MISS')
                        || '-' || upper(substr(md5(random()::text),1,6));

  BEGIN
    INSERT INTO public.communication_request(
      request_no, module_code, department_code, event_code,
      channels, priority, status, payload, context, idempotency_key, requested_by,
      original_decision_id, decision_send_context,
      configuration_version, recipient_policy_version,
      targeted_dispatch_only, controlled_action,
      controlled_live_execution_id, controlled_live_grant_id
    ) VALUES (
      v_request_no, v_execution.module_code, NULL, v_execution.event_code,
      ARRAY['email'], 'high', 'approved',
      COALESCE(v_snapshot.context_data, '{}'::jsonb),
      jsonb_build_object(
        'correlation_id', v_execution.id::text, 'origin', 'comm_hub',
        'send_context', 'controlled_live',
        'source', 'create_comm_hub_controlled_stub_message'),
      v_idem_key, v_execution.requested_by,
      v_execution.original_decision_id, 'controlled_live',
      v_execution.configuration_version, v_execution.recipient_policy_version::integer,
      true, v_action, v_execution.id, v_grant.id
    ) RETURNING id INTO v_request_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_request_id FROM public.communication_request WHERE idempotency_key = v_idem_key;
    SELECT id INTO v_message_id FROM public.communication_message
     WHERE request_id = v_request_id AND targeted_dispatch_only = true;
    SELECT id INTO v_recipient_id FROM public.communication_recipient WHERE request_id = v_request_id AND role='to' LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'idempotent_replay', true, 'action', v_action,
      'request_id', v_request_id, 'message_id', v_message_id,
      'recipient_id', v_recipient_id,
      'execution_id', v_execution.id, 'grant_id', v_grant.id);
  END;

  INSERT INTO public.communication_recipient(request_id, role, recipient_type, name, email)
  VALUES (v_request_id, 'to', 'email', v_to_name, v_to_email)
  RETURNING id INTO v_recipient_id;

  INSERT INTO public.communication_message(
    request_id, recipient_id, channel, template_version_id,
    subject, body_text, body_html, status,
    origin, sender_profile_id, from_email, from_display_name, reply_to_email,
    original_decision_id, send_context, test_mode,
    targeted_dispatch_only, controlled_action,
    controlled_live_execution_id, controlled_live_grant_id,
    preview_snapshot_id, preview_approval_id, dry_run_certification_id,
    governance_certification_id, certified_dependency_hash,
    recipient_set_hash, subject_hash, body_hash, content_hash
  ) VALUES (
    v_request_id, v_recipient_id, 'email', v_snapshot.template_version_id,
    v_snapshot.rendered_subject, v_snapshot.rendered_body_text, v_snapshot.rendered_body_html,
    'queued', 'comm_hub', v_snapshot.sender_profile_id,
    v_sender_from,
    v_sender_name, v_sender_reply,
    v_execution.original_decision_id, 'controlled_live', false,
    true, v_action, v_execution.id, v_grant.id,
    v_snapshot.id, v_approval.id, v_dry_run.id,
    v_governance_id, v_dep_hash,
    v_snapshot.recipient_set_hash, v_snapshot.subject_hash,
    v_snapshot.body_hash, v_snapshot.content_hash
  ) RETURNING id INTO v_message_id;

  UPDATE public.communication_controlled_live_execution
     SET request_id = v_request_id, message_id = v_message_id, updated_at = now()
   WHERE id = v_execution.id AND (request_id IS NULL OR request_id = v_request_id);

  RETURN jsonb_build_object(
    'ok', true, 'idempotent_replay', false, 'action', v_action,
    'request_id', v_request_id, 'request_no', v_request_no,
    'message_id', v_message_id, 'recipient_id', v_recipient_id,
    'execution_id', v_execution.id, 'grant_id', v_grant.id,
    'preview_snapshot_id', v_snapshot.id,
    'preview_approval_id', v_approval.id,
    'dry_run_certification_id', v_dry_run.id,
    'governance_certification_id', v_governance_id,
    'certified_dependency_hash', v_dep_hash,
    'recipient_set_hash', v_snapshot.recipient_set_hash,
    'subject_hash', v_snapshot.subject_hash,
    'body_hash', v_snapshot.body_hash,
    'content_hash', v_snapshot.content_hash,
    'template_version_id', v_snapshot.template_version_id,
    'sender_profile_id', v_snapshot.sender_profile_id,
    'from_email', v_sender_from,
    'from_display_name', v_sender_name);
END; $function$;
CREATE OR REPLACE FUNCTION public.create_comm_hub_one_real_email_message(p_execution_id uuid, p_grant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_execution  public.communication_controlled_live_execution%ROWTYPE;
  v_grant      public.communication_controlled_live_grant%ROWTYPE;
  v_approval   public.communication_preview_approval%ROWTYPE;
  v_snapshot   public.communication_preview_snapshot%ROWTYPE;
  v_dry_run    public.communication_dry_run_certification%ROWTYPE;
  v_sender     public.communication_hub_sender_profile%ROWTYPE;
  v_provider   public.notification_providers%ROWTYPE;
  v_first jsonb; v_first_type text;
  v_to_email text; v_to_name text;
  v_to_count int; v_cc_count int; v_bcc_count int;
  v_action text := 'SEND_ONE_REAL_EMAIL';
  v_idem_key text;
  v_request_id uuid; v_request_no text;
  v_recipient_id uuid; v_message_id uuid; v_existing_msg uuid;
  v_exec_recipient text;
  v_recomputed_hash text; v_norm jsonb;
  v_sender_from text; v_sender_name text; v_sender_reply text;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF p_execution_id IS NULL OR p_grant_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'input_invalid');
  END IF;

  SELECT * INTO v_execution FROM public.communication_controlled_live_execution
   WHERE id = p_execution_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','execution_not_found'); END IF;

  IF v_execution.send_context <> 'REAL_EMAIL' THEN
    RETURN jsonb_build_object('ok', false, 'code','execution_not_real_email');
  END IF;
  IF coalesce(v_execution.provider_mode,'') <> 'real' THEN
    RETURN jsonb_build_object('ok', false, 'code','execution_not_provider_real');
  END IF;
  IF v_execution.real_email_authorised IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'code','execution_not_real_email_authorised');
  END IF;
  IF v_execution.completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code','execution_terminal');
  END IF;

  SELECT * INTO v_grant FROM public.communication_controlled_live_grant
   WHERE id = p_grant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','grant_not_found'); END IF;
  IF v_grant.execution_id <> v_execution.id THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_execution_mismatch');
  END IF;
  IF v_grant.send_context <> 'REAL_EMAIL' THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_not_real_email');
  END IF;
  IF v_grant.status NOT IN ('ISSUED','RESERVED') THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_not_dispatchable',
      'grant_status', v_grant.status);
  END IF;
  IF v_grant.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_expired');
  END IF;
  IF v_grant.scope_hash <> v_execution.scope_hash THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_scope_hash_mismatch');
  END IF;
  IF v_grant.recipient_set_hash <> v_execution.recipient_set_hash THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_recipient_hash_mismatch');
  END IF;
  IF v_grant.preview_approval_id <> v_execution.preview_approval_id THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_preview_mismatch');
  END IF;
  IF v_grant.dry_run_certification_id <> v_execution.dry_run_certification_id THEN
    RETURN jsonb_build_object('ok', false, 'code','grant_dry_run_mismatch');
  END IF;

  -- Idempotent request replay (per-execution/action).
  v_idem_key := 'one-real-email:request:' || v_execution.id::text || ':' || v_action;
  SELECT id INTO v_request_id FROM public.communication_request WHERE idempotency_key = v_idem_key;
  IF FOUND THEN
    SELECT id INTO v_existing_msg FROM public.communication_message
     WHERE request_id = v_request_id AND targeted_dispatch_only = true
       AND controlled_live_execution_id = v_execution.id
       AND controlled_live_grant_id = v_grant.id
       AND controlled_action = v_action;
    IF v_existing_msg IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code','idempotency_conflict_incomplete');
    END IF;
    SELECT id INTO v_recipient_id FROM public.communication_recipient
     WHERE request_id = v_request_id AND role='to' LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'idempotent_replay', true, 'action', v_action,
      'request_id', v_request_id, 'message_id', v_existing_msg,
      'recipient_id', v_recipient_id,
      'execution_id', v_execution.id, 'grant_id', v_grant.id);
  END IF;

  -- Approval / snapshot / dry-run alignment
  SELECT * INTO v_approval FROM public.communication_preview_approval
    WHERE id = v_execution.preview_approval_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','preview_approval_missing'); END IF;
  IF v_approval.status NOT IN ('ACTIVE','RESERVED') THEN
    RETURN jsonb_build_object('ok', false, 'code','preview_approval_not_usable', 'approval_status', v_approval.status);
  END IF;
  IF v_approval.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code','preview_approval_expired');
  END IF;

  SELECT * INTO v_snapshot FROM public.communication_preview_snapshot WHERE id = v_approval.snapshot_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','preview_snapshot_missing'); END IF;
  IF v_snapshot.status <> 'PREPARED' THEN
    RETURN jsonb_build_object('ok', false, 'code','preview_snapshot_not_prepared','snapshot_status',v_snapshot.status);
  END IF;
  IF v_snapshot.content_hash IS DISTINCT FROM v_approval.content_hash_at_approval THEN
    RETURN jsonb_build_object('ok', false, 'code','preview_content_hash_mismatch');
  END IF;

  SELECT * INTO v_dry_run FROM public.communication_dry_run_certification
   WHERE id = v_execution.dry_run_certification_id;
  IF NOT FOUND OR v_dry_run.status <> 'ACTIVE' OR v_dry_run.result <> 'DRY_RUN_PASSED' THEN
    RETURN jsonb_build_object('ok', false, 'code','dry_run_certification_not_valid');
  END IF;
  IF v_dry_run.expires_at <= now() THEN
    RETURN jsonb_build_object('ok', false, 'code','dry_run_certification_expired');
  END IF;
  IF v_dry_run.preview_approval_id IS DISTINCT FROM v_approval.id THEN
    RETURN jsonb_build_object('ok', false, 'code','dry_run_approval_mismatch');
  END IF;

  v_to_count  := coalesce(jsonb_array_length(v_snapshot.to_recipients), 0);
  v_cc_count  := coalesce(jsonb_array_length(v_snapshot.cc_recipients), 0);
  v_bcc_count := coalesce(jsonb_array_length(v_snapshot.bcc_recipients), 0);
  IF v_to_count <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'code','recipient_count_invalid','to_count',v_to_count);
  END IF;
  IF v_cc_count > 0  THEN RETURN jsonb_build_object('ok', false, 'code','cc_not_allowed'); END IF;
  IF v_bcc_count > 0 THEN RETURN jsonb_build_object('ok', false, 'code','bcc_not_allowed'); END IF;

  v_first := v_snapshot.to_recipients->0;
  v_first_type := jsonb_typeof(v_first);
  IF v_first_type = 'string' THEN
    v_to_email := lower(btrim(v_snapshot.to_recipients->>0));
    v_to_name  := NULL;
  ELSIF v_first_type = 'object' THEN
    v_to_email := lower(btrim(coalesce(v_first->>'email','')));
    v_to_name  := v_first->>'name';
  ELSE
    RETURN jsonb_build_object('ok', false, 'code','recipient_shape_invalid');
  END IF;
  IF v_to_email IS NULL OR v_to_email = '' THEN
    RETURN jsonb_build_object('ok', false, 'code','recipient_email_missing');
  END IF;

  v_exec_recipient := lower(btrim(coalesce(v_execution.recipient,'')));
  IF v_exec_recipient <> '' AND v_exec_recipient <> v_to_email THEN
    RETURN jsonb_build_object('ok', false, 'code','recipient_execution_mismatch');
  END IF;

  v_norm := public.comm_hub_normalize_recipient_set(
    jsonb_build_array(v_to_email), '[]'::jsonb, '[]'::jsonb);
  v_recomputed_hash := v_norm->>'recipient_set_hash';
  IF v_recomputed_hash IS DISTINCT FROM v_snapshot.recipient_set_hash THEN
    RETURN jsonb_build_object('ok', false, 'code','recipient_hash_snapshot_mismatch');
  END IF;
  IF v_recomputed_hash IS DISTINCT FROM v_grant.recipient_set_hash THEN
    RETURN jsonb_build_object('ok', false, 'code','recipient_hash_grant_mismatch');
  END IF;

  IF v_snapshot.template_version_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code','template_version_missing');
  END IF;
  IF v_snapshot.sender_profile_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code','sender_profile_missing');
  END IF;
  IF v_snapshot.rendered_subject IS NULL OR btrim(v_snapshot.rendered_subject) = '' THEN
    RETURN jsonb_build_object('ok', false, 'code','rendered_subject_missing');
  END IF;
  IF (v_snapshot.rendered_body_html IS NULL OR btrim(v_snapshot.rendered_body_html) = '')
     AND (v_snapshot.rendered_body_text IS NULL OR btrim(v_snapshot.rendered_body_text) = '') THEN
    RETURN jsonb_build_object('ok', false, 'code','rendered_body_missing');
  END IF;

  SELECT * INTO v_sender FROM public.communication_hub_sender_profile
    WHERE id = v_snapshot.sender_profile_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','sender_profile_not_found'); END IF;
  v_sender_from  := btrim(coalesce(v_sender.from_email,''));
  v_sender_name  := btrim(coalesce(v_sender.display_name,''));
  v_sender_reply := btrim(coalesce(v_sender.reply_to_email,''));
  IF v_sender_from = '' OR v_sender_name = '' THEN
    RETURN jsonb_build_object('ok', false, 'code','sender_profile_not_verified');
  END IF;
  IF v_sender_reply = '' THEN v_sender_reply := v_sender_from; END IF;

  SELECT * INTO v_provider FROM public.notification_providers
   WHERE channel = 'email'::notification_channel
     AND is_active = true AND is_default = true
   ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','no_active_real_provider'); END IF;

  -- Explicit pre-insert contract guard for every targeted-message field.
  IF v_action IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','controlled_action_missing','field','controlled_action');
  END IF;
  IF v_execution.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','controlled_live_execution_id_missing','field','controlled_live_execution_id');
  END IF;
  IF v_grant.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','controlled_live_grant_id_missing','field','controlled_live_grant_id');
  END IF;
  IF v_snapshot.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','preview_snapshot_id_missing','field','preview_snapshot_id');
  END IF;
  IF v_approval.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','preview_approval_id_missing','field','preview_approval_id');
  END IF;
  IF v_dry_run.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','dry_run_certification_id_missing','field','dry_run_certification_id');
  END IF;
  IF v_snapshot.template_version_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','template_version_id_missing','field','template_version_id');
  END IF;
  IF v_snapshot.sender_profile_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','sender_profile_id_missing','field','sender_profile_id');
  END IF;
  IF v_snapshot.recipient_set_hash IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','recipient_set_hash_missing','field','recipient_set_hash');
  END IF;
  IF v_snapshot.subject_hash IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','subject_hash_missing','field','subject_hash');
  END IF;
  IF v_snapshot.body_hash IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','body_hash_missing','field','body_hash');
  END IF;
  IF v_snapshot.content_hash IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','content_hash_missing','field','content_hash');
  END IF;
  IF jsonb_array_length(v_blockers) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'code','targeted_message_field_missing',
      'blockers', v_blockers);
  END IF;

  PERFORM set_config('comm_hub.allow_targeted_update', 'true', true);

  v_request_no := 'ORE-' || to_char(now() AT TIME ZONE 'UTC','YYYYMMDDHH24MISS')
                        || '-' || upper(substr(md5(random()::text),1,6));

  BEGIN
    INSERT INTO public.communication_request(
      request_no, module_code, department_code, event_code,
      channels, priority, status, payload, context, idempotency_key, requested_by,
      original_decision_id, decision_send_context,
      configuration_version, recipient_policy_version,
      targeted_dispatch_only, controlled_action,
      controlled_live_execution_id, controlled_live_grant_id
    ) VALUES (
      v_request_no, v_execution.module_code, NULL, v_execution.event_code,
      ARRAY['email'], 'high', 'approved',
      coalesce(v_snapshot.context_data, '{}'::jsonb),
      jsonb_build_object(
        'correlation_id', v_execution.id::text, 'origin', 'comm_hub',
        'send_context','controlled_live',
        'stage','ONE_REAL_EMAIL',
        'controlled_action', v_action,
        'source','create_comm_hub_one_real_email_message'),
      v_idem_key, v_execution.requested_by,
      v_execution.original_decision_id, 'controlled_live',
      v_execution.configuration_version, v_execution.recipient_policy_version::integer,
      true, v_action, v_execution.id, v_grant.id
    ) RETURNING id INTO v_request_id;
  EXCEPTION
    WHEN unique_violation THEN
      SELECT id INTO v_request_id FROM public.communication_request WHERE idempotency_key = v_idem_key;
      SELECT id INTO v_message_id FROM public.communication_message
       WHERE request_id = v_request_id AND targeted_dispatch_only = true;
      SELECT id INTO v_recipient_id FROM public.communication_recipient
       WHERE request_id = v_request_id AND role='to' LIMIT 1;
      RETURN jsonb_build_object('ok', true, 'idempotent_replay', true, 'action', v_action,
        'request_id', v_request_id, 'message_id', v_message_id,
        'recipient_id', v_recipient_id,
        'execution_id', v_execution.id, 'grant_id', v_grant.id);
    WHEN check_violation THEN
      RETURN jsonb_build_object('ok', false, 'code','request_check_violation',
        'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM);
    WHEN foreign_key_violation THEN
      RETURN jsonb_build_object('ok', false, 'code','request_foreign_key_violation',
        'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM);
  END;

  INSERT INTO public.communication_recipient(request_id, role, recipient_type, name, email)
  VALUES (v_request_id, 'to', 'email', v_to_name, v_to_email)
  RETURNING id INTO v_recipient_id;

  BEGIN
    INSERT INTO public.communication_message(
      request_id, recipient_id, channel, template_version_id,
      subject, body_text, body_html, status,
      origin, sender_profile_id, from_email, from_display_name, reply_to_email,
      original_decision_id, send_context, test_mode,
      targeted_dispatch_only, controlled_action,
      controlled_live_execution_id, controlled_live_grant_id,
      preview_snapshot_id, preview_approval_id, dry_run_certification_id,
      recipient_set_hash, subject_hash, body_hash, content_hash,
      provider_id
    ) VALUES (
      v_request_id, v_recipient_id, 'email', v_snapshot.template_version_id,
      v_snapshot.rendered_subject, v_snapshot.rendered_body_text, v_snapshot.rendered_body_html,
      'queued', 'comm_hub', v_snapshot.sender_profile_id,
      v_sender_from, v_sender_name, v_sender_reply,
      v_execution.original_decision_id, 'controlled_live', false,
      true, v_action, v_execution.id, v_grant.id,
      v_snapshot.id, v_approval.id, v_dry_run.id,
      v_snapshot.recipient_set_hash, v_snapshot.subject_hash,
      v_snapshot.body_hash, v_snapshot.content_hash,
      v_provider.id
    ) RETURNING id INTO v_message_id;
  EXCEPTION
    WHEN check_violation THEN
      RETURN jsonb_build_object('ok', false, 'code','message_check_violation',
        'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM,
        'request_id', v_request_id);
    WHEN foreign_key_violation THEN
      RETURN jsonb_build_object('ok', false, 'code','message_foreign_key_violation',
        'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM,
        'request_id', v_request_id);
  END;

  UPDATE public.communication_controlled_live_execution
     SET request_id = v_request_id, message_id = v_message_id, updated_at = now()
   WHERE id = v_execution.id AND (request_id IS NULL OR request_id = v_request_id);

  RETURN jsonb_build_object(
    'ok', true, 'idempotent_replay', false, 'action', v_action,
    'request_id', v_request_id, 'request_no', v_request_no,
    'message_id', v_message_id, 'recipient_id', v_recipient_id,
    'execution_id', v_execution.id, 'grant_id', v_grant.id,
    'preview_snapshot_id', v_snapshot.id,
    'preview_approval_id', v_approval.id,
    'dry_run_certification_id', v_dry_run.id,
    'template_version_id', v_snapshot.template_version_id,
    'sender_profile_id', v_snapshot.sender_profile_id,
    'from_email', v_sender_from,
    'provider_id', v_provider.id,
    'provider_name', v_provider.provider_name,
    'original_decision_id', v_execution.original_decision_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.create_comm_hub_synthetic_failed_test_message(p_module_code text, p_event_code text, p_template_code text, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tpl_id uuid; v_tpl_ver uuid;
  v_req_id uuid := gen_random_uuid();
  v_req_no text;
  v_recipient_id uuid := gen_random_uuid();
  v_msg_id uuid := gen_random_uuid();
BEGIN
  IF NOT has_role(p_actor_user_id, 'Admin'::app_role) THEN RAISE EXCEPTION 'forbidden_admin_only'; END IF;
  IF coalesce(trim(p_reason),'') = '' THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT id, active_version_id INTO v_tpl_id, v_tpl_ver
    FROM public.core_template WHERE code=p_template_code AND is_active=true LIMIT 1;
  IF v_tpl_id IS NULL OR v_tpl_ver IS NULL THEN RAISE EXCEPTION 'template_not_ready:%', p_template_code; END IF;

  v_req_no := 'CR-SYN-' || to_char(now() AT TIME ZONE 'UTC','YYYYMMDDHH24MISS') || '-' || upper(substr(md5(random()::text),1,6));

  INSERT INTO public.communication_request(
    id, request_no, module_code, event_code, status, priority,
    requested_by, payload, context, channels, created_at, updated_at
  ) VALUES (
    v_req_id, v_req_no, p_module_code, p_event_code, 'failed', 'normal',
    p_actor_user_id,
    jsonb_build_object('synthetic', true, 'reason', p_reason),
    jsonb_build_object('synthetic', true, 'origin','comm_hub', 'test_mode', true,
                      'source','create_comm_hub_synthetic_failed_test_message'),
    ARRAY['email']::text[],
    now(), now()
  );

  INSERT INTO public.communication_recipient(
    id, request_id, role, recipient_type, email, name, channel_hint, created_at, updated_at
  ) VALUES (
    v_recipient_id, v_req_id, 'to', 'ADMIN_USER', 'rohit@mishainfotech.com', 'Rohit Wadhwa (synthetic)', 'email', now(), now()
  );

  INSERT INTO public.communication_message(
    id, request_id, recipient_id, channel, template_version_id,
    subject, body_text, status, attempt_count, provider_message_id,
    error_code, error_message, test_mode, origin, created_at, updated_at
  ) VALUES (
    v_msg_id, v_req_id, v_recipient_id, 'email', v_tpl_ver,
    'SYNTHETIC — operator action rehearsal',
    'This is a synthetic failed dry-run message for admin operator action rehearsal. No provider was called.',
    'failed', 1, NULL,
    'SYNTHETIC_OPERATOR_ACTION_TEST',
    'Synthetic failed dry-run message for operator action rehearsal',
    true, 'comm_hub', now(), now()
  );

  INSERT INTO public.communication_event_log(message_id, request_id, event_type, source, payload, actor_user_id)
  VALUES (v_msg_id, v_req_id, 'failed', 'create_comm_hub_synthetic_failed_test_message',
          jsonb_build_object('synthetic', true, 'stage','SYNTHETIC_FAILED_TEST_MESSAGE_CREATED', 'reason', p_reason),
          p_actor_user_id);

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('synthetic_failed_test_message_created:'||v_msg_id::text, NULL,
          jsonb_build_object('request_id',v_req_id,'request_no',v_req_no,'message_id',v_msg_id,'module_code',p_module_code,'event_code',p_event_code,'template_code',p_template_code),
          p_reason, p_actor_user_id, 'create_comm_hub_synthetic_failed_test_message');

  RETURN jsonb_build_object('ok', true, 'request_id', v_req_id, 'request_no', v_req_no, 'message_id', v_msg_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_comm_hub_synthetic_stale_locked_test_message(p_module_code text, p_event_code text, p_template_code text, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tpl_id uuid;
  v_tpl_ver uuid;
  v_req_id uuid := gen_random_uuid();
  v_req_no text;
  v_recipient_id uuid := gen_random_uuid();
  v_msg_id uuid := gen_random_uuid();
  v_locked_at timestamptz := now() - interval '16 minutes';
BEGIN
  IF NOT has_role(p_actor_user_id, 'Admin'::app_role) THEN RAISE EXCEPTION 'forbidden_admin_only'; END IF;
  IF coalesce(trim(p_reason),'') = '' THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT id, active_version_id INTO v_tpl_id, v_tpl_ver
    FROM public.core_template
   WHERE code=p_template_code
     AND is_active=true
   LIMIT 1;
  IF v_tpl_id IS NULL OR v_tpl_ver IS NULL THEN RAISE EXCEPTION 'template_not_ready:%', p_template_code; END IF;

  v_req_no := 'CR-SYN-' || to_char(now() AT TIME ZONE 'UTC','YYYYMMDDHH24MISS') || '-' || upper(substr(md5(random()::text),1,6));

  INSERT INTO public.communication_request(
    id, request_no, module_code, event_code, status, priority,
