    p_actor_user_id,
    jsonb_build_object('synthetic', true, 'reason', p_reason),
    jsonb_build_object('synthetic', true, 'origin','comm_hub', 'test_mode', true,
                      'source','create_comm_hub_synthetic_stale_locked_test_message'),
    ARRAY['email']::text[],
    now(), now()
  );

  INSERT INTO public.communication_recipient(
    id, request_id, role, recipient_type, email, name, channel_hint, created_at, updated_at
  ) VALUES (
    v_recipient_id, v_req_id, 'to', 'ADMIN_USER', 'rohit@mishainfotech.com', 'Rohit Wadhwa (synthetic)', 'email', now(), now()
  );

  INSERT INTO public.communication_message(
    id, request_id, recipient_id, channel, template_version_id,
    subject, body_text, status, attempt_count, provider_message_id,
    error_code, error_message, test_mode, origin,
    locked_at, locked_by, created_at, updated_at
  ) VALUES (
    v_msg_id, v_req_id, v_recipient_id, 'email', v_tpl_ver,
    'SYNTHETIC — stale lock rehearsal',
    'Synthetic stale-locked dry-run message for clear-lock rehearsal. No provider was called.',
    'sending', 0, NULL,
    'SYNTHETIC_STALE_LOCK_TEST',
    'Synthetic stale-locked dry-run message for operator clear-lock rehearsal',
    true, 'comm_hub',
    v_locked_at, 'synthetic-operator-rehearsal',
    now(), now()
  );

  INSERT INTO public.communication_event_log(message_id, request_id, event_type, source, payload, actor_user_id)
  VALUES (
    v_msg_id,
    v_req_id,
    'created',
    'create_comm_hub_synthetic_stale_locked_test_message',
    jsonb_build_object(
      'synthetic', true,
      'stage','SYNTHETIC_STALE_LOCK_TEST_MESSAGE_CREATED',
      'logical_message_status','sending',
      'locked_at', v_locked_at,
      'reason', p_reason
    ),
    p_actor_user_id
  );

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('synthetic_stale_lock_test_message_created:'||v_msg_id::text, NULL,
          jsonb_build_object('request_id',v_req_id,'request_no',v_req_no,'message_id',v_msg_id,'module_code',p_module_code,'event_code',p_event_code,'template_code',p_template_code,'locked_at',v_locked_at),
          p_reason, p_actor_user_id, 'create_comm_hub_synthetic_stale_locked_test_message');

  RETURN jsonb_build_object('ok', true, 'request_id', v_req_id, 'request_no', v_req_no, 'message_id', v_msg_id, 'locked_at', v_locked_at);
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_comm_hub_template_with_version(p_template jsonb, p_version jsonb, p_reason text, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_code text := p_template->>'template_code';
  v_tid uuid;
  v_ver_no integer;
  v_ver_id uuid;
  v_existing_active uuid;
  v_actor text := COALESCE(auth.uid()::text, 'system');
BEGIN
  PERFORM public._chub_assert_admin();
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 THEN
    RAISE EXCEPTION 'reason required';
  END IF;
  IF v_code IS NULL OR v_code !~ '^[A-Z][A-Z0-9_]*$' THEN
    RAISE EXCEPTION 'template_code must be UPPER_SNAKE_CASE';
  END IF;
  IF COALESCE(p_version->>'subject','') = '' THEN
    RAISE EXCEPTION 'subject required';
  END IF;
  IF COALESCE(p_version->>'body_html','') = '' AND COALESCE(p_version->>'body_text','') = '' THEN
    RAISE EXCEPTION 'body required (html or text)';
  END IF;

  SELECT id, active_version_id INTO v_tid, v_existing_active
  FROM public.core_template WHERE code = v_code;

  IF v_tid IS NULL THEN
    INSERT INTO public.core_template(
      code, name, description, module_code, module_name, template_type,
      template_category, status, source_system, tags, is_active, created_by, updated_by
    )
    VALUES(
      v_code,
      COALESCE(p_template->>'template_name', v_code),
      p_template->>'description',
      COALESCE(p_template->>'module_code','COMM_HUB'),
      p_template->>'module_name',
      COALESCE(p_template->>'template_type','EMAIL'),
      p_template->>'template_category',
      'ACTIVE',
      'CORE',
      ARRAY['comm-hub-wizard']::text[],
      true,
      v_actor,
      v_actor
    )
    RETURNING id INTO v_tid;
  ELSE
    IF v_existing_active IS NOT NULL AND p_confirm <> 'CREATE NEW TEMPLATE VERSION' THEN
      RAISE EXCEPTION 'template % already has active version; typed confirmation required', v_code;
    END IF;
  END IF;

  SELECT COALESCE(MAX(version_no),0) + 1 INTO v_ver_no
  FROM public.core_template_version WHERE template_id = v_tid;

  INSERT INTO public.core_template_version(
    template_id, version_no, status, subject, body_html, body_text,
    change_summary, published_at, published_by, body_metadata, created_by, updated_by
  )
  VALUES(
    v_tid, v_ver_no, 'PUBLISHED',
    p_version->>'subject',
    p_version->>'body_html',
    COALESCE(p_version->>'body_text', regexp_replace(p_version->>'body_html', '<[^>]+>', '', 'g')),
    COALESCE(p_version->>'change_summary','Created via Event & Template Onboarding Wizard'),
    now(), v_actor,
    COALESCE(p_version->'body_metadata', '{}'::jsonb) || jsonb_build_object('required_tokens', COALESCE(p_version->'required_tokens', '[]'::jsonb)),
    v_actor, v_actor
  )
  RETURNING id INTO v_ver_id;

  UPDATE public.core_template
     SET active_version_id = v_ver_id, status = 'ACTIVE', updated_by = v_actor
   WHERE id = v_tid;

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('template.' || v_code, jsonb_build_object('previous_active', v_existing_active),
          jsonb_build_object('template_id', v_tid, 'version_id', v_ver_id, 'version_no', v_ver_no),
          p_reason, auth.uid(), 'event-template-onboarding-wizard');

  RETURN jsonb_build_object('template_id', v_tid, 'template_code', v_code, 'version_id', v_ver_id, 'version_no', v_ver_no);
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_head_cashier_override(p_office_code character varying, p_user_id uuid, p_user_code character varying, p_full_name character varying DEFAULT NULL::character varying, p_start date DEFAULT CURRENT_DATE, p_end date DEFAULT CURRENT_DATE, p_reason text DEFAULT NULL::text, p_assigned_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_overlap RECORD;
  v_new_id UUID;
BEGIN
  IF p_end < p_start THEN
    RETURN json_build_object('success', false, 'message', 'End date must be on or after start date');
  END IF;

  -- Check for overlapping active overrides
  SELECT id, user_code, override_start, override_end INTO v_overlap
  FROM cn_head_cashier_override
  WHERE office_code = p_office_code
    AND is_active = true
    AND override_start <= p_end
    AND override_end >= p_start
  LIMIT 1;

  IF FOUND THEN
    RETURN json_build_object('success', false, 'message',
      format('Overlapping override exists for %s (%s to %s)', v_overlap.user_code, v_overlap.override_start, v_overlap.override_end));
  END IF;

  INSERT INTO cn_head_cashier_override (office_code, user_id, user_code, full_name, override_start, override_end, reason, assigned_by)
  VALUES (p_office_code, p_user_id, p_user_code, p_full_name, p_start, p_end, p_reason, p_assigned_by)
  RETURNING id INTO v_new_id;

  -- Audit log
  INSERT INTO system_audit_trail (action, entity_type, entity_id, module, user_id, user_name, after_value, payload_json)
  VALUES ('create_override', 'cn_head_cashier_override', v_new_id::TEXT, 'Payment Module', p_user_id, p_assigned_by,
    jsonb_build_object('user_code', p_user_code, 'office_code', p_office_code, 'start', p_start, 'end', p_end),
    jsonb_build_object('reason', p_reason));

  RETURN json_build_object('success', true, 'id', v_new_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_invoice_with_lines(p_invoice_type text, p_payment_source text, p_payer_type text, p_payer_id text, p_payer_name text, p_currency_code text, p_exchange_rate numeric, p_total_amount numeric, p_total_amount_base numeric, p_due_date date, p_public_notes text, p_internal_notes text, p_is_recurring boolean, p_created_by text, p_lines jsonb, p_recurring jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_id INTEGER;
  v_invoice_number TEXT;
  v_max_seq INTEGER;
  v_line JSONB;
  v_month_prefix TEXT;
  v_base_currency TEXT;
  v_header_rate NUMERIC;
  v_line_currency TEXT;
  v_line_rate NUMERIC;
BEGIN
  -- Resolve base (main) currency
  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;

  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured in the system';
  END IF;

  -- Resolve header currency exchange rate
  SELECT exchange_rate INTO v_header_rate
  FROM public.tb_currencies
  WHERE currency_code = p_currency_code AND is_active = true
  LIMIT 1;

  IF v_header_rate IS NULL THEN
    RAISE EXCEPTION 'Currency % is not active or does not exist', p_currency_code;
  END IF;

  -- Generate invoice number with advisory lock
  PERFORM pg_advisory_xact_lock(8675310);

  v_month_prefix := 'INV-' || to_char(now(), 'YYYYMM') || '-';

  SELECT COALESCE(
    MAX(CAST(SUBSTRING(invoice_number FROM LENGTH(v_month_prefix) + 1) AS INTEGER)),
    0
  ) INTO v_max_seq
  FROM public.cn_invoices
  WHERE invoice_number LIKE v_month_prefix || '%';

  v_invoice_number := v_month_prefix || LPAD((v_max_seq + 1)::TEXT, 3, '0');

  -- Insert invoice header with status = 'O' (Original)
  INSERT INTO public.cn_invoices (
    invoice_number, invoice_type, payment_source,
    payer_type, payer_id, payer_name,
    currency_code, exchange_rate, base_currency,
    total_amount, total_amount_base,
    due_date, public_notes, internal_notes,
    is_recurring, status, created_by
  ) VALUES (
    v_invoice_number, p_invoice_type, p_payment_source,
    p_payer_type, p_payer_id, p_payer_name,
    p_currency_code, v_header_rate, v_base_currency,
    p_total_amount, p_total_amount_base,
    p_due_date, p_public_notes, p_internal_notes,
    p_is_recurring, 'O', p_created_by
  ) RETURNING id INTO v_invoice_id;

  -- Insert line items
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_currency := v_line->>'currency_code';

    SELECT exchange_rate INTO v_line_rate
    FROM public.tb_currencies
    WHERE currency_code = v_line_currency AND is_active = true
    LIMIT 1;

    IF v_line_rate IS NULL THEN
      RAISE EXCEPTION 'Currency % on line item is not active or does not exist', v_line_currency;
    END IF;

    INSERT INTO public.cn_invoice_lines (
      invoice_id, payment_code, currency_code,
      amount, exchange_rate, amount_base, base_currency, sort_order
    ) VALUES (
      v_invoice_id,
      v_line->>'payment_code',
      v_line_currency,
      (v_line->>'amount')::NUMERIC,
      v_line_rate,
      ROUND((v_line->>'amount')::NUMERIC * v_line_rate, 2),
      v_base_currency,
      COALESCE((v_line->>'sort_order')::INTEGER, 0)
    );
  END LOOP;

  -- Insert recurring config if enabled
  IF p_is_recurring AND p_recurring IS NOT NULL THEN
    INSERT INTO public.cn_invoice_recurring (
      invoice_id, frequency, start_date, end_date, next_run_date
    ) VALUES (
      v_invoice_id,
      p_recurring->>'frequency',
      (p_recurring->>'start_date')::DATE,
      CASE WHEN p_recurring->>'end_date' IS NOT NULL AND p_recurring->>'end_date' != ''
           THEN (p_recurring->>'end_date')::DATE ELSE NULL END,
      (p_recurring->>'start_date')::DATE
    );
  END IF;

  RETURN jsonb_build_object(
    'invoice_id', v_invoice_id,
    'invoice_number', v_invoice_number
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_invoice_with_lines(p_invoice_type text, p_payment_source text, p_payer_type text, p_payer_id text, p_payer_name text, p_currency_code text, p_exchange_rate numeric, p_total_amount numeric, p_total_amount_base numeric, p_due_date date, p_public_notes text, p_internal_notes text, p_is_recurring boolean, p_created_by text, p_lines jsonb, p_recurring jsonb DEFAULT NULL::jsonb, p_payer_email text DEFAULT NULL::text, p_payer_phone text DEFAULT NULL::text, p_payer_address text DEFAULT NULL::text, p_create_new_payer boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_id INTEGER;
  v_invoice_number TEXT;
  v_max_seq INTEGER;
  v_line JSONB;
  v_month_prefix TEXT;
  v_base_currency TEXT;
  v_header_rate NUMERIC;
  v_line_currency TEXT;
  v_line_rate NUMERIC;
  v_new_payer_id INTEGER;
  v_actual_payer_id TEXT;
  v_config_val JSONB;
  v_segments JSONB;
  v_seq_min_length INT;
  v_prefix TEXT;
  v_suffix TEXT;
  v_seg JSONB;
  v_has_seq BOOLEAN := FALSE;
BEGIN
  -- Resolve base (main) currency
  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;

  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured in the system';
  END IF;

  -- Resolve header currency exchange rate
  SELECT exchange_rate INTO v_header_rate
  FROM public.tb_currencies
  WHERE currency_code = p_currency_code AND is_active = true
  LIMIT 1;

  IF v_header_rate IS NULL THEN
    RAISE EXCEPTION 'Currency % is not active or does not exist', p_currency_code;
  END IF;

  -- Handle AP new payer creation
  IF p_create_new_payer AND p_payer_type = 'AP' THEN
    IF TRIM(COALESCE(p_payer_name, '')) = '' THEN
      RAISE EXCEPTION 'Payer name is required for new AP payer';
    END IF;
    PERFORM pg_advisory_xact_lock(8675311);
    SELECT COALESCE(MAX(payer_id::INTEGER), 0) + 1 INTO v_new_payer_id
    FROM public.cn_payer WHERE payer_type = 'AP' AND payer_id ~ '^\d+$';
    IF v_new_payer_id IS NULL THEN v_new_payer_id := 1; END IF;
    v_actual_payer_id := LPAD(v_new_payer_id::TEXT, 6, '0');
    INSERT INTO public.cn_payer (payer_id, payer_type, payer_name, email, phone, address, created_by)
    VALUES (v_actual_payer_id, 'AP', TRIM(p_payer_name), NULLIF(TRIM(p_payer_email), ''), NULLIF(TRIM(p_payer_phone), ''), NULLIF(TRIM(p_payer_address), ''), p_created_by);
  ELSE
    v_actual_payer_id := p_payer_id;
    IF p_payer_type = 'AP' THEN
      UPDATE public.cn_payer
      SET email = COALESCE(NULLIF(TRIM(p_payer_email), ''), email),
          phone = COALESCE(NULLIF(TRIM(p_payer_phone), ''), phone),
          address = COALESCE(NULLIF(TRIM(p_payer_address), ''), address)
      WHERE payer_id = v_actual_payer_id AND payer_type = 'AP';
    END IF;
  END IF;

  IF p_payer_type = 'AP' THEN
    IF NOT EXISTS (SELECT 1 FROM public.cn_payer WHERE payer_id = v_actual_payer_id AND payer_type = 'AP') THEN
      RAISE EXCEPTION 'AP Payer with ID % not found', v_actual_payer_id;
    END IF;
  END IF;

  -- Read invoice number format config
  SELECT config_value INTO v_config_val
  FROM public.payment_module_config
  WHERE config_key = 'invoice_number_format';

  -- Generate invoice number with advisory lock
  PERFORM pg_advisory_xact_lock(8675310);

  -- Check for segments-based config (new format)
  IF v_config_val IS NOT NULL AND v_config_val ? 'segments' THEN
    v_segments := v_config_val->'segments';

    -- Check if SEQ placeholder exists
    FOR v_seg IN SELECT * FROM jsonb_array_elements(v_segments)
    LOOP
      IF v_seg->>'type' = 'placeholder' AND v_seg->>'value' = 'SEQ' THEN
        v_has_seq := TRUE;
        v_seq_min_length := COALESCE((v_seg->>'min_length')::INT, 3);
      END IF;
    END LOOP;

    IF v_has_seq THEN
      -- Build prefix (everything before SEQ) and suffix (everything after SEQ)
      DECLARE
        v_context JSONB;
        v_before_seq TEXT := '';
        v_after_seq TEXT := '';
        v_found_seq BOOLEAN := FALSE;
        v_s JSONB;
        v_s_type TEXT;
        v_s_value TEXT;
        v_s_min INT;
        v_resolved TEXT;
        v_ts TIMESTAMPTZ := now();
      BEGIN
        v_context := jsonb_build_object(
          'PAYER_ID', COALESCE(v_actual_payer_id, ''),
          'PAYER_TYPE', COALESCE(p_payer_type, ''),
          'USER_CODE', COALESCE(p_created_by, ''),
          'OFFICE_CODE', COALESCE(p_created_by, ''),
          'ts', v_ts::TEXT
        );

        FOR v_s IN SELECT * FROM jsonb_array_elements(v_segments)
        LOOP
          v_s_type := v_s->>'type';
          v_s_value := v_s->>'value';
          v_s_min := COALESCE((v_s->>'min_length')::INT, 0);

          IF v_s_type = 'placeholder' AND v_s_value = 'SEQ' THEN
            v_found_seq := TRUE;
            CONTINUE;
          END IF;

          -- Resolve this segment
          IF v_s_type = 'static' THEN
            v_resolved := COALESCE(v_s_value, '');
          ELSE
            CASE v_s_value
              WHEN 'YYYY' THEN v_resolved := to_char(v_ts, 'YYYY');
              WHEN 'YY' THEN v_resolved := to_char(v_ts, 'YY');
              WHEN 'MM' THEN v_resolved := to_char(v_ts, 'MM');
              WHEN 'DD' THEN v_resolved := to_char(v_ts, 'DD');
              WHEN 'YYYYMM' THEN v_resolved := to_char(v_ts, 'YYYYMM');
              WHEN 'YYYYMMDD' THEN v_resolved := to_char(v_ts, 'YYYYMMDD');
              WHEN 'DDMMYYYY' THEN v_resolved := to_char(v_ts, 'DDMMYYYY');
              WHEN 'DDMMYYYYHHMM' THEN v_resolved := to_char(v_ts, 'DDMMYYYYHH24MI');
              WHEN 'HH' THEN v_resolved := to_char(v_ts, 'HH24');
              WHEN 'MI' THEN v_resolved := to_char(v_ts, 'MI');
              WHEN 'SS' THEN v_resolved := to_char(v_ts, 'SS');
              WHEN 'HHMM' THEN v_resolved := to_char(v_ts, 'HH24MI');
              WHEN 'HHMMSS' THEN v_resolved := to_char(v_ts, 'HH24MISS');
              WHEN 'PAYER_ID' THEN v_resolved := COALESCE(v_actual_payer_id, '');
              WHEN 'PAYER_TYPE' THEN v_resolved := COALESCE(p_payer_type, '');
              WHEN 'USER_CODE' THEN v_resolved := COALESCE(p_created_by, '');
              WHEN 'OFFICE_CODE' THEN v_resolved := COALESCE(p_created_by, '');
              ELSE v_resolved := v_s_value;
            END CASE;
            IF v_s_min > 0 THEN
              v_resolved := LPAD(v_resolved, v_s_min, '0');
            END IF;
          END IF;

          IF v_found_seq THEN
            v_after_seq := v_after_seq || v_resolved;
          ELSE
            v_before_seq := v_before_seq || v_resolved;
          END IF;
        END LOOP;

        v_month_prefix := v_before_seq;

        SELECT COALESCE(
          MAX(
            CASE
              WHEN LENGTH(v_after_seq) > 0 THEN
                CAST(SUBSTRING(invoice_number FROM LENGTH(v_month_prefix) + 1 FOR LENGTH(invoice_number) - LENGTH(v_month_prefix) - LENGTH(v_after_seq)) AS INTEGER)
              ELSE
                CAST(SUBSTRING(invoice_number FROM LENGTH(v_month_prefix) + 1) AS INTEGER)
            END
          ), 0
        ) INTO v_max_seq
        FROM public.cn_invoices
        WHERE invoice_number LIKE v_month_prefix || '%';

        v_invoice_number := v_month_prefix || LPAD((v_max_seq + 1)::TEXT, v_seq_min_length, '0') || v_after_seq;
      END;
    ELSE
      -- No SEQ placeholder, just resolve all segments
      DECLARE
        v_context JSONB := jsonb_build_object(
          'PAYER_ID', COALESCE(v_actual_payer_id, ''),
          'PAYER_TYPE', COALESCE(p_payer_type, ''),
          'USER_CODE', COALESCE(p_created_by, ''),
          'OFFICE_CODE', COALESCE(p_created_by, ''),
          'ts', now()::TEXT
        );
      BEGIN
        v_invoice_number := public.resolve_number_segments(v_segments, v_context);
      END;
    END IF;

  -- Legacy format string fallback
  ELSIF v_config_val IS NOT NULL AND v_config_val ? 'format' THEN
    DECLARE
      v_format TEXT := v_config_val->>'format';
      v_legacy_seq_min INT := COALESCE((v_config_val->>'seq_min_length')::INT, 3);
    BEGIN
      IF v_format IS NOT NULL AND v_format != '' AND POSITION('{SEQ}' IN v_format) > 0 THEN
        v_month_prefix := SPLIT_PART(v_format, '{SEQ}', 1);
        v_month_prefix := REPLACE(v_month_prefix, '{YYYY}', to_char(now(), 'YYYY'));
        v_month_prefix := REPLACE(v_month_prefix, '{YY}', to_char(now(), 'YY'));
        v_month_prefix := REPLACE(v_month_prefix, '{YYYYMM}', to_char(now(), 'YYYYMM'));
        v_month_prefix := REPLACE(v_month_prefix, '{YYYYMMDD}', to_char(now(), 'YYYYMMDD'));
        v_month_prefix := REPLACE(v_month_prefix, '{DDMMYYYY}', to_char(now(), 'DDMMYYYY'));
        v_month_prefix := REPLACE(v_month_prefix, '{MM}', to_char(now(), 'MM'));
        v_month_prefix := REPLACE(v_month_prefix, '{DD}', to_char(now(), 'DD'));
        v_month_prefix := REPLACE(v_month_prefix, '{OFFICE_CODE}', COALESCE(p_created_by, ''));
        v_month_prefix := REPLACE(v_month_prefix, '{USER_CODE}', COALESCE(p_created_by, ''));
        v_month_prefix := REPLACE(v_month_prefix, '{PAYER_ID}', COALESCE(v_actual_payer_id, ''));
        v_month_prefix := REPLACE(v_month_prefix, '{PAYER_TYPE}', COALESCE(p_payer_type, ''));

        SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM LENGTH(v_month_prefix) + 1) AS INTEGER)), 0) INTO v_max_seq
        FROM public.cn_invoices WHERE invoice_number LIKE v_month_prefix || '%';

        v_invoice_number := v_month_prefix || LPAD((v_max_seq + 1)::TEXT, v_legacy_seq_min, '0');
      ELSE
        v_month_prefix := 'INV-' || to_char(now(), 'YYYYMM') || '-';
        SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM LENGTH(v_month_prefix) + 1) AS INTEGER)), 0) INTO v_max_seq
        FROM public.cn_invoices WHERE invoice_number LIKE v_month_prefix || '%';
        v_invoice_number := v_month_prefix || LPAD((v_max_seq + 1)::TEXT, 3, '0');
      END IF;
    END;

  ELSE
    -- Default fallback
    v_month_prefix := 'INV-' || to_char(now(), 'YYYYMM') || '-';
    SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM LENGTH(v_month_prefix) + 1) AS INTEGER)), 0) INTO v_max_seq
    FROM public.cn_invoices WHERE invoice_number LIKE v_month_prefix || '%';
    v_invoice_number := v_month_prefix || LPAD((v_max_seq + 1)::TEXT, 3, '0');
  END IF;

  -- Insert invoice header
  INSERT INTO public.cn_invoices (
    invoice_number, invoice_type, payment_source,
    payer_type, payer_id, payer_name,
    currency_code, exchange_rate, base_currency,
    total_amount, total_amount_base,
    due_date, public_notes, internal_notes,
    is_recurring, status, created_by,
    payer_email, payer_phone, payer_address
  ) VALUES (
    v_invoice_number, p_invoice_type, p_payment_source,
    p_payer_type, v_actual_payer_id, p_payer_name,
    p_currency_code, v_header_rate, v_base_currency,
    p_total_amount, p_total_amount_base,
    p_due_date, p_public_notes, p_internal_notes,
    p_is_recurring, 'O', p_created_by,
    p_payer_email, p_payer_phone, p_payer_address
  ) RETURNING id INTO v_invoice_id;

  -- Insert line items
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_currency := v_line->>'currency_code';
    SELECT exchange_rate INTO v_line_rate
    FROM public.tb_currencies
    WHERE currency_code = v_line_currency AND is_active = true
    LIMIT 1;
    IF v_line_rate IS NULL THEN
      RAISE EXCEPTION 'Currency % on line item is not active or does not exist', v_line_currency;
    END IF;
    INSERT INTO public.cn_invoice_lines (
      invoice_id, payment_code, currency_code,
      amount, exchange_rate, amount_base, base_currency, sort_order
    ) VALUES (
      v_invoice_id, v_line->>'payment_code', v_line_currency,
      (v_line->>'amount')::NUMERIC, v_line_rate,
      ROUND((v_line->>'amount')::NUMERIC * v_line_rate, 2),
      v_base_currency, COALESCE((v_line->>'sort_order')::INTEGER, 0)
    );
  END LOOP;

  -- Insert recurring config if enabled
  IF p_is_recurring AND p_recurring IS NOT NULL THEN
    INSERT INTO public.cn_invoice_recurring (
      invoice_id, frequency, start_date, end_date, next_run_date
    ) VALUES (
      v_invoice_id, p_recurring->>'frequency',
      (p_recurring->>'start_date')::DATE,
      CASE WHEN p_recurring->>'end_date' IS NOT NULL AND p_recurring->>'end_date' != '' THEN (p_recurring->>'end_date')::DATE ELSE NULL END,
      (p_recurring->>'start_date')::DATE
    );
  END IF;

  RETURN jsonb_build_object('invoice_id', v_invoice_id, 'invoice_number', v_invoice_number);
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_legal_info_request(p_legal_referral_id uuid, p_requested_by text, p_request_reason text, p_requested_items jsonb DEFAULT '[]'::jsonb, p_due_date date DEFAULT NULL::date, p_workbasket_code text DEFAULT NULL::text, p_team_code text DEFAULT NULL::text, p_user text DEFAULT NULL::text)
 RETURNS TABLE(info_request_id uuid, request_no text, source_task_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referral legal_referral%ROWTYPE;
  v_request_no text;
  v_ir_id uuid;
  v_task_id uuid;
  v_workbasket text;
  v_team text;
  v_user text;
BEGIN
  -- Lock referral
  SELECT * INTO v_referral FROM legal_referral WHERE id = p_legal_referral_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Legal referral % not found', p_legal_referral_id; END IF;

  IF coalesce(trim(p_request_reason), '') = '' THEN
    RAISE EXCEPTION 'request_reason is required';
  END IF;

  -- Resolve routing: explicit > submitter > module default
  v_workbasket := COALESCE(NULLIF(p_workbasket_code, ''), v_referral.submitted_workbasket_code);
  v_team       := COALESCE(NULLIF(p_team_code, ''), v_referral.submitted_team_code);
  v_user       := COALESCE(NULLIF(p_user, ''), v_referral.submitted_by);

  IF v_workbasket IS NULL THEN
    IF v_referral.source_module = 'BENEFITS' THEN
      SELECT basket_code INTO v_workbasket FROM bn_workbasket WHERE is_active = true LIMIT 1;
      v_workbasket := COALESCE(v_workbasket, 'BN_LEGAL_FOLLOWUP');
    ELSE
      SELECT queue_code INTO v_workbasket FROM ce_assignment_routing_rules WHERE is_active = true LIMIT 1;
      v_workbasket := COALESCE(v_workbasket, 'CE_LEGAL_FOLLOWUP');
    END IF;
  END IF;

  -- Next request_no
  SELECT public.next_info_request_no() INTO v_request_no;
  IF v_request_no IS NULL THEN
    v_request_no := 'LIR-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text,1,6);
  END IF;

  -- 1. Info request
  INSERT INTO legal_referral_info_request(
    legal_referral_id, request_no, requested_by, requested_to_module,
    requested_to_workbasket_code, requested_to_team_code, requested_to_user,
    request_reason, requested_items, due_date, status
  ) VALUES (
    p_legal_referral_id, v_request_no, p_requested_by, v_referral.source_module,
    v_workbasket, v_team, v_user,
    p_request_reason, COALESCE(p_requested_items, '[]'::jsonb), p_due_date, 'PENDING_SOURCE_RESPONSE'
  ) RETURNING id INTO v_ir_id;

  -- 2. Source task
  INSERT INTO legal_referral_source_task(
    legal_referral_id, info_request_id, task_type, source_module,
    assigned_workbasket_code, assigned_team_code, assigned_user,
    priority, due_date, status,
    employer_id, insured_person_id
  ) VALUES (
    p_legal_referral_id, v_ir_id, 'LEGAL_INFO_REQUEST', v_referral.source_module,
    v_workbasket, v_team, v_user,
    COALESCE(v_referral.priority_code, 'MEDIUM'), p_due_date, 'OPEN',
    CASE WHEN v_referral.primary_entity_type = 'EMPLOYER' THEN v_referral.primary_entity_id ELSE NULL END,
    CASE WHEN v_referral.primary_entity_type = 'INSURED_PERSON' THEN v_referral.primary_entity_id ELSE NULL END
  ) RETURNING id INTO v_task_id;

  -- 3. Update referral status
  UPDATE legal_referral
     SET status = 'INFO_REQUESTED', last_status_at = now()
   WHERE id = p_legal_referral_id;

  -- 4. Audit (Legal side)
  INSERT INTO legal_referral_audit(legal_referral_id, info_request_id, event_code, event_module, actor, notes)
  VALUES (p_legal_referral_id, v_ir_id, 'INFO_REQUESTED', 'LEGAL', p_requested_by, p_request_reason);

  -- 5. Audit (Source side)
  INSERT INTO legal_referral_audit(legal_referral_id, info_request_id, event_code, event_module, actor, notes)
  VALUES (p_legal_referral_id, v_ir_id, 'SOURCE_TASK_CREATED', v_referral.source_module, p_requested_by,
          'Info request task assigned to ' || COALESCE(v_workbasket,'?'));

  -- 6. Mirror to legacy intake row (so existing screens reflect status)
  IF v_referral.lg_intake_id IS NOT NULL THEN
    UPDATE lg_case_intake
       SET intake_status = 'INFO_REQUESTED',
           info_request_notes = p_request_reason
     WHERE id = v_referral.lg_intake_id;
  END IF;

  RETURN QUERY SELECT v_ir_id, v_request_no, v_task_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_payment_header_with_next_id(p_batch_number text, p_payer_type text, p_payer_id text, p_date_received date, p_remarks text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id integer;
BEGIN
  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  INSERT INTO public.cn_payment_header (
    payment_id,
    batch_number,
    payer_type,
    payer_id,
    date_received,
    remarks
  ) VALUES (
    v_payment_id,
    p_batch_number,
    p_payer_type,
    p_payer_id,
    p_date_received,
    p_remarks
  );

  RETURN v_payment_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_payment_with_receipt(p_batch_number text, p_payer_type text, p_payer_id text, p_date_received text, p_remarks text DEFAULT NULL::text, p_detail_lines jsonb DEFAULT '[]'::jsonb, p_receipt_total numeric DEFAULT 0, p_total_payments integer DEFAULT 0, p_user_code text DEFAULT 'SYSTEM'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id integer;
  v_receipt_id integer;
  v_detail jsonb;
  v_exp_date text;
  v_exp_normalized text;
  v_parts text[];
  v_period_text text;
  v_period_ts timestamp;
  v_date_received_ts timestamp;
  v_card_machine_id uuid;
  v_mop_code text;
BEGIN
  IF p_batch_number IS NULL OR p_batch_number = '' THEN
    RAISE EXCEPTION 'batch_number is required';
  END IF;
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF jsonb_array_length(p_detail_lines) = 0 THEN
    RAISE EXCEPTION 'At least one detail line is required';
  END IF;
  IF p_receipt_total <= 0 THEN
    RAISE EXCEPTION 'receipt_total must be greater than zero';
  END IF;

  BEGIN
    v_date_received_ts := p_date_received::timestamp;
  EXCEPTION WHEN OTHERS THEN
    v_date_received_ts := now();
  END;

  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  INSERT INTO public.cn_payment_header (
    payment_id, batch_number, payer_type, payer_id, date_received, remarks
  ) VALUES (
    v_payment_id, p_batch_number, p_payer_type, p_payer_id, v_date_received_ts, p_remarks
  );

  FOR v_detail IN SELECT * FROM jsonb_array_elements(p_detail_lines)
  LOOP
    v_exp_normalized := NULL;
    v_exp_date := v_detail->>'expiration_date';
    IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
      v_parts := string_to_array(v_exp_date, '/');
      IF array_length(v_parts, 1) = 2 THEN
        v_exp_normalized := '20' || lpad(v_parts[2], 2, '0') || '-' || lpad(v_parts[1], 2, '0') || '-01';
      ELSE
        v_exp_normalized := v_exp_date;
      END IF;
    END IF;

    v_period_ts := NULL;
    v_period_text := v_detail->>'period';
    IF v_period_text IS NOT NULL AND v_period_text != '' THEN
      BEGIN
        v_period_ts := v_period_text::timestamp;
      EXCEPTION WHEN OTHERS THEN
        v_period_ts := NULL;
      END;
    END IF;

    -- Resolve card_machine_id
    v_card_machine_id := NULL;
    v_mop_code := v_detail->>'mop_code';
    IF v_detail->>'card_machine_id' IS NOT NULL AND v_detail->>'card_machine_id' != '' THEN
      v_card_machine_id := (v_detail->>'card_machine_id')::uuid;
    END IF;

    -- Server-side validation: CRD/DRD requires card_machine_id
    IF v_mop_code IN ('CRD', 'DRD') AND v_card_machine_id IS NULL THEN
      RAISE EXCEPTION 'card_machine_id is required for payment method %', v_mop_code;
    END IF;

    INSERT INTO public.cn_payment (
      payment_id, payment_code, fund_code, payment_amount,
      mop_code, period, payment_date, bank_code,
      mop_number, cheque_date, mop_account_number, mop_notes1,
      credit_card_code, expiration_date, card_machine_id
    ) VALUES (
      v_payment_id,
      v_detail->>'payment_code',
      v_detail->>'fund_code',
      (v_detail->>'payment_amount')::numeric,
      v_mop_code,
      v_period_ts,
      CASE WHEN v_detail->>'payment_date' IS NOT NULL AND v_detail->>'payment_date' != ''
           THEN (v_detail->>'payment_date')::date ELSE NULL END,
      NULLIF(v_detail->>'bank_code', ''),
      NULLIF(v_detail->>'mop_number', ''),
      CASE WHEN v_detail->>'cheque_date' IS NOT NULL AND v_detail->>'cheque_date' != ''
           THEN (v_detail->>'cheque_date')::date ELSE NULL END,
      NULLIF(v_detail->>'mop_account_number', ''),
      NULLIF(v_detail->>'mop_notes1', ''),
      NULLIF(v_detail->>'credit_card_code', ''),
      CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END,
      v_card_machine_id
    );
  END LOOP;

  INSERT INTO public.cn_receipt (
    payment_id, status, receipt_total, total_number_of_payments,
    reprint_times, created_by, updated_by
  ) VALUES (
    v_payment_id, 'O', p_receipt_total, p_total_payments,
    0, p_user_code, p_user_code
  )
  RETURNING receipt_id INTO v_receipt_id;

  INSERT INTO public.cn_receipt_prints (
    receipt_id, printed_by, print_type
  ) VALUES (
    v_receipt_id, p_user_code, 'ORIGINAL'
  );

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'status', 'success'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_pending_holiday_pay(p_ssn text, p_amount numeric, p_source_c3_period text, p_target_year integer, p_target_month integer, p_holiday_date_from date DEFAULT NULL::date, p_holiday_date_to date DEFAULT NULL::date, p_created_by text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  INSERT INTO public.c3_pending_holiday_pay (
    ssn, amount, source_c3_period, target_year, target_month,
    holiday_date_from, holiday_date_to, status, created_by
  ) VALUES (
    p_ssn, p_amount, p_source_c3_period, p_target_year, p_target_month,
    p_holiday_date_from, p_holiday_date_to, 'pending', p_created_by
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.delete_c3_config_period(p_period_id uuid, p_user_code character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period RECORD;
  v_current_month_start DATE := date_trunc('month', CURRENT_DATE)::DATE;
  v_submission_count INT;
  v_active_count INT;
  v_old_values JSONB;
BEGIN
  SELECT * INTO v_period FROM c3_config_periods WHERE id = p_period_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Period not found');
  END IF;

  IF v_period.last_published_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'Period has already been published to C3-Wizard and cannot be deleted');
  END IF;

  IF v_period.start_date < v_current_month_start THEN
    RETURN jsonb_build_object('error', 'Period is in the past and is already used in C3 generation');
  END IF;

  SELECT count(*) INTO v_submission_count
    FROM c3_submissions
   WHERE filing_period IS NOT NULL
     AND to_date(filing_period || '-01', 'YYYY-MM-DD') BETWEEN v_period.start_date
         AND COALESCE(v_period.end_date, DATE '9999-12-31');
  IF v_submission_count > 0 THEN
    RETURN jsonb_build_object('error', 'Period has C3 submissions and cannot be deleted');
  END IF;

  SELECT count(*) INTO v_active_count FROM c3_config_periods WHERE is_active = true;
  IF v_period.is_active AND v_active_count <= 1 THEN
    RETURN jsonb_build_object('error', 'At least one active configuration period must remain');
  END IF;

  SELECT jsonb_build_object(
    'period', to_jsonb(v_period),
    'details', COALESCE((SELECT jsonb_agg(to_jsonb(d)) FROM c3_config_details d WHERE d.config_period_id = p_period_id), '[]'::jsonb)
  ) INTO v_old_values;

  INSERT INTO c3_config_audit (config_period_id, action, changed_by, old_values, new_values)
  VALUES (p_period_id, 'DELETE', p_user_code, v_old_values, NULL);

  DELETE FROM c3_config_details WHERE config_period_id = p_period_id;
  DELETE FROM c3_config_periods WHERE id = p_period_id;

  RETURN jsonb_build_object('success', true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.delete_email(queue_name text, message_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN pgmq.delete(queue_name, message_id);
EXCEPTION WHEN undefined_table THEN
  RETURN FALSE;
END;
$function$;
CREATE OR REPLACE FUNCTION public.delete_head_cashier_override(p_override_id uuid, p_deleted_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec RECORD;
BEGIN
  SELECT id, office_code, user_code, override_start, override_end INTO v_rec
  FROM cn_head_cashier_override
  WHERE id = p_override_id AND is_active = true;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'message', 'Override not found or already deleted');
  END IF;

  UPDATE cn_head_cashier_override SET is_active = false WHERE id = p_override_id;

  INSERT INTO system_audit_trail (action, entity_type, entity_id, module, user_id, user_name, after_value)
  VALUES ('delete_override', 'cn_head_cashier_override', p_override_id::TEXT, 'Payment Module', NULL, p_deleted_by,
    jsonb_build_object('office_code', v_rec.office_code, 'user_code', v_rec.user_code, 'start', v_rec.override_start, 'end', v_rec.override_end));

  RETURN json_build_object('success', true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.diagnose_comm_hub_legacy_attestation_fingerprint(p_module_code text, p_event_code text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_att public.communication_hub_legacy_evidence_attestation%ROWTYPE;
  v_snap jsonb; v_current_core jsonb; v_current_fp_recompute text;
  v_att_core jsonb; v_att_fp_recompute text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=coalesce(p_channel,'email');
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'phase','EVENT_NOT_FOUND'); END IF;

  SELECT * INTO v_att FROM public.communication_hub_legacy_evidence_attestation
   WHERE event_certification_id=v_ec.id AND status='ACTIVE'
   ORDER BY attested_at DESC, id DESC LIMIT 1;

  v_snap := public.get_comm_hub_current_evidence_snapshot(p_module_code,p_event_code,coalesce(p_channel,'email'));
  IF coalesce((v_snap->>'ok')::boolean,false)=false THEN
    RETURN jsonb_build_object('ok',false,'phase','CURRENT_SNAPSHOT_INCOMPLETE','snapshot',v_snap);
  END IF;

  v_current_core := v_snap->'evidence_core_v2';
  v_current_fp_recompute := public._comm_hub_fingerprint_evidence_core_v2(v_current_core);

  IF v_att.id IS NOT NULL THEN
    IF v_att.current_evidence_snapshot_v2 ? 'template_version_id' THEN
      v_att_core := public._comm_hub_evidence_core_v2(v_att.current_evidence_snapshot_v2);
    ELSIF v_att.current_evidence_snapshot_v2 ? 'snapshot' THEN
      v_att_core := public._comm_hub_evidence_core_v2(v_att.current_evidence_snapshot_v2->'snapshot');
    ELSE
      v_att_core := v_att.current_evidence_snapshot_v2;
    END IF;
    v_att_fp_recompute := public._comm_hub_fingerprint_evidence_core_v2(v_att_core);
  END IF;

  RETURN jsonb_build_object(
    'ok',true,
    'event_certification_id',v_ec.id,
    'production_lineage_id',v_ec.production_lineage_id,
    'current_fingerprint_stored',v_snap->>'evidence_fingerprint_v2',
    'current_fingerprint_recomputed',v_current_fp_recompute,
    'attestation_id',v_att.id,
    'attestation_fingerprint_stored',v_att.current_evidence_fingerprint_v2,
    'attestation_fingerprint_recomputed',v_att_fp_recompute,
    'current_core',v_current_core,
    'attestation_core',v_att_core,
    'current_rpc_matches_current_core_rehash',
      (v_snap->>'evidence_fingerprint_v2') = v_current_fp_recompute,
    'attestation_stored_matches_attestation_core_rehash',
      v_att.current_evidence_fingerprint_v2 = v_att_fp_recompute,
    'current_core_matches_attestation_core',
      v_current_core = v_att_core,
    'current_fingerprint_matches_attestation_fingerprint',
      (v_snap->>'evidence_fingerprint_v2') = v_att.current_evidence_fingerprint_v2
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.disable_comm_hub_event_template_mapping(p_module_code text, p_event_code text, p_channel text, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_hub_event_template_map%ROWTYPE;
  v_old jsonb;
BEGIN
  IF NOT has_role(p_actor_user_id, 'Admin'::app_role) THEN RAISE EXCEPTION 'forbidden_admin_only'; END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT * INTO v_row FROM public.communication_hub_event_template_map
    WHERE module_code=p_module_code AND event_code=p_event_code AND channel=lower(p_channel);
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'mapping_not_found'; END IF;
  v_old := to_jsonb(v_row);

  UPDATE public.communication_hub_event_template_map
    SET active=false, reason=p_reason, updated_by=p_actor_user_id, updated_at=now()
    WHERE id=v_row.id RETURNING * INTO v_row;

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('event_template_mapping_disable:'||p_module_code||'/'||p_event_code||'/'||lower(p_channel), v_old, to_jsonb(v_row), p_reason, p_actor_user_id, 'disable_comm_hub_event_template_mapping');

  RETURN jsonb_build_object('ok', true, 'mapping', to_jsonb(v_row));
END;
$function$;
CREATE OR REPLACE FUNCTION public.disarm_comm_hub_automation(p_reason text, p_suspend boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_row public.communication_hub_control_settings%ROWTYPE;
  v_now timestamptz := now();
  v_new_ver bigint;
  v_target text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  BEGIN v_is_admin := public.is_comm_hub_operator_admin(v_uid);
  EXCEPTION WHEN undefined_function THEN
    SELECT public.has_role(v_uid,'Admin'::public.app_role) INTO v_is_admin; END;
  IF NOT v_is_admin THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF coalesce(p_reason,'')='' THEN RAISE EXCEPTION 'reason_required' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_row FROM public.communication_hub_control_settings
    WHERE singleton_guard='primary' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'settings_singleton_missing' USING ERRCODE='P0002'; END IF;

  v_target := CASE WHEN p_suspend THEN 'SUSPENDED' ELSE 'STANDBY' END;
  v_new_ver := v_row.configuration_version + 1;

  PERFORM set_config('comm_hub.automation_op','on',true);
  UPDATE public.communication_hub_control_settings
     SET automation_state=v_target,
         automation_state_changed_at=v_now,
         automation_state_changed_by=v_uid,
         automation_armed_at=NULL, automation_armed_by=NULL, automation_arm_reason=NULL,
         automation_suspended_at=CASE WHEN v_target='SUSPENDED' THEN v_now ELSE NULL END,
         automation_suspension_reason=CASE WHEN v_target='SUSPENDED' THEN p_reason ELSE NULL END,
         scheduler_enabled=false, automatic_triggers_enabled=false, retry_worker_enabled=false,
         batch_enabled=false, bulk_enabled=false,
         configuration_version=v_new_ver, updated_at=v_now, updated_by=v_uid
   WHERE singleton_guard='primary';

  INSERT INTO public.communication_hub_arm_audit(action,actor,reason,configuration_version,
    automation_state_before,automation_state_after,snapshot)
  VALUES (CASE WHEN p_suspend THEN 'SUSPENDED' ELSE 'DISARMED' END,
          v_uid, p_reason, v_new_ver, v_row.automation_state, v_target,
          jsonb_build_object('reason',p_reason));

  RETURN jsonb_build_object('ok',true,'automation_state',v_target,'configuration_version',v_new_ver);
END $function$;
CREATE OR REPLACE FUNCTION public.dms_queue_claim_batch(p_limit integer DEFAULT 10)
 RETURNS SETOF dms_transfer_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.dms_transfer_queue q
     SET status          = 'Processing',
         attempts        = attempts + 1,
         updated_at      = now()
   WHERE q.id IN (
     SELECT id FROM public.dms_transfer_queue
      WHERE status = 'Pending'
        AND next_attempt_at <= now()
        AND attempts < max_attempts
      ORDER BY next_attempt_at
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
   )
  RETURNING q.*;
END;
$function$;
CREATE OR REPLACE FUNCTION public.dms_queue_mark_result(p_queue_id uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.dms_transfer_queue%ROWTYPE;
  v_backoff_seconds int;
BEGIN
  SELECT * INTO v_row FROM public.dms_transfer_queue WHERE id = p_queue_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  IF p_success THEN
    UPDATE public.dms_transfer_queue
       SET status = 'Transferred', last_error = NULL, updated_at = now()
     WHERE id = p_queue_id;

    IF v_row.scope = 'ip' THEN
      UPDATE public.ip_documents
         SET transfer_status = 'Transferred', dms_uploaded_at = now()
       WHERE id = v_row.document_id;
    ELSIF v_row.scope = 'er' THEN
      UPDATE public.er_documents
         SET transfer_status = 'Transferred', dms_uploaded_at = now()
       WHERE id = v_row.document_id;
    END IF;
  ELSE
    -- Exponential backoff: 60s * 2^attempts (capped at 1 hour)
    v_backoff_seconds := LEAST(3600, 60 * POWER(2, GREATEST(v_row.attempts, 1)))::int;
    UPDATE public.dms_transfer_queue
       SET status          = CASE WHEN attempts >= max_attempts THEN 'Failed' ELSE 'Pending' END,
           last_error      = p_error,
           next_attempt_at = now() + make_interval(secs => v_backoff_seconds),
           updated_at      = now()
     WHERE id = p_queue_id;

    IF v_row.scope = 'ip' THEN
      UPDATE public.ip_documents
         SET transfer_status = CASE WHEN v_row.attempts >= v_row.max_attempts THEN 'Failed' ELSE 'Pending' END,
             transfer_error  = p_error
       WHERE id = v_row.document_id;
    ELSIF v_row.scope = 'er' THEN
      UPDATE public.er_documents
         SET transfer_status = CASE WHEN v_row.attempts >= v_row.max_attempts THEN 'Failed' ELSE 'Pending' END,
             transfer_error  = p_error
       WHERE id = v_row.document_id;
    END IF;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ecr_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.edit_and_verify_batch_cheque(p_batch_number text, p_source_table text, p_source_record_id text, p_source_payment_id bigint, p_override_cheque_number text DEFAULT NULL::text, p_override_bank_code text DEFAULT NULL::text, p_override_amount numeric DEFAULT NULL::numeric, p_override_cheque_date text DEFAULT NULL::text, p_edit_reason text DEFAULT NULL::text, p_user_code text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_cheque_date DATE;
BEGIN
  -- Validate
  IF p_override_amount IS NOT NULL AND p_override_amount <= 0 THEN
    RAISE EXCEPTION 'Override amount must be greater than zero.';
  END IF;

  -- Cast date
  v_cheque_date := CASE WHEN p_override_cheque_date IS NOT NULL AND p_override_cheque_date <> '' 
                        THEN p_override_cheque_date::DATE ELSE NULL END;

  -- Upsert verification record
  INSERT INTO public.cn_batch_cheque_verification (
    batch_number, source_table, source_record_id, source_payment_id,
    override_cheque_number, override_bank_code, override_amount, override_cheque_date,
    edit_reason, edited_by, edited_at,
    is_verified, verified_by, verified_at
  ) VALUES (
    p_batch_number, p_source_table, p_source_record_id, p_source_payment_id,
    p_override_cheque_number, p_override_bank_code, p_override_amount, v_cheque_date,
    p_edit_reason, p_user_code, now(),
    true, p_user_code, now()
  )
  ON CONFLICT (batch_number, source_table, source_record_id)
  DO UPDATE SET
    override_cheque_number = COALESCE(p_override_cheque_number, cn_batch_cheque_verification.override_cheque_number),
    override_bank_code = COALESCE(p_override_bank_code, cn_batch_cheque_verification.override_bank_code),
    override_amount = COALESCE(p_override_amount, cn_batch_cheque_verification.override_amount),
    override_cheque_date = COALESCE(v_cheque_date, cn_batch_cheque_verification.override_cheque_date),
    edit_reason = p_edit_reason,
    edited_by = p_user_code,
    edited_at = now(),
    is_verified = true,
    verified_by = p_user_code,
    verified_at = now();

  -- Propagate to source
  IF p_source_table = 'cn_payment' THEN
    UPDATE public.cn_payment SET
      mop_number = COALESCE(p_override_cheque_number, mop_number),
      bank_code = COALESCE(p_override_bank_code, bank_code),
      payment_amount = COALESCE(p_override_amount, payment_amount),
      cheque_date = COALESCE(v_cheque_date::TIMESTAMP, cheque_date)
    WHERE payment_sequence_no::TEXT = p_source_record_id;
  ELSIF p_source_table = 'c3_payment_methods' THEN
    UPDATE public.c3_payment_methods SET
      mop_number = COALESCE(p_override_cheque_number, mop_number),
      bank_code = COALESCE(p_override_bank_code, bank_code),
      original_amount = COALESCE(p_override_amount, original_amount),
      cheque_date = COALESCE(v_cheque_date, cheque_date)
    WHERE id::TEXT = p_source_record_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_c3_edit_restriction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Allow if old status is DFT or PEN (record is editable)
  IF OLD.posting_status IN ('DFT', 'PEN') THEN
    RETURN NEW;
  END IF;

  -- Allow workflow-driven status transitions (only posting_status and audit fields change)
  -- This permits approve/reject/query actions that change posting_status from VAC/REJ etc.
  IF NEW.posting_status IS DISTINCT FROM OLD.posting_status THEN
    RETURN NEW;
  END IF;

  -- Allow soft-delete (status change to DEL)
  IF NEW.posting_status = 'DEL' THEN
    RETURN NEW;
  END IF;

  -- Block all other updates when posting_status is not DFT or PEN
  RAISE EXCEPTION 'C3 cannot be edited when posting_status is %', OLD.posting_status;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_chrsr_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'communication_hub_revalidation_stage_result rows are immutable';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status <> 'PENDING' THEN
      RAISE EXCEPTION 'stage result % is terminal (%), no updates allowed', OLD.id, OLD.status;
    END IF;
    IF NEW.cycle_id <> OLD.cycle_id OR NEW.stage_code <> OLD.stage_code THEN
      RAISE EXCEPTION 'cannot change cycle_id or stage_code';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.enforce_message_dry_run_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_bypass text := current_setting('communication_hub.dry_run_immutability_bypass', true);
BEGIN
  IF v_bypass = 'migration' THEN
    RETURN NEW;
  END IF;

  -- Once dry_run_locked = true, it may never be cleared at runtime.
  IF OLD.dry_run_locked IS TRUE AND (NEW.dry_run_locked IS DISTINCT FROM TRUE) THEN
    RAISE EXCEPTION 'dry_run_classification_is_immutable: dry_run_locked cannot be cleared'
      USING ERRCODE = '42501';
  END IF;

  -- Once classified as dry_run, send_context may not be changed away from it.
  IF OLD.send_context = 'dry_run' AND (NEW.send_context IS DISTINCT FROM 'dry_run') THEN
    RAISE EXCEPTION 'dry_run_classification_is_immutable: send_context cannot be changed from dry_run'
      USING ERRCODE = '42501';
  END IF;

  -- If already dry-run-locked, send_context must remain 'dry_run'.
  IF OLD.dry_run_locked IS TRUE AND NEW.send_context IS DISTINCT FROM 'dry_run' THEN
    RAISE EXCEPTION 'dry_run_classification_is_immutable: locked message must remain dry_run'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_message_dry_run_insert_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_bypass text := current_setting('communication_hub.dry_run_immutability_bypass', true);
  v_req_ctx text;
BEGIN
  IF v_bypass = 'migration' THEN
    RETURN NEW;
  END IF;

  IF NEW.dry_run_locked IS TRUE AND NEW.send_context IS DISTINCT FROM 'dry_run' THEN
    RAISE EXCEPTION 'dry_run_classification_is_immutable: locked message must have send_context=dry_run'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.send_context = 'dry_run' THEN
    SELECT decision_send_context INTO v_req_ctx
      FROM public.communication_request WHERE id = NEW.request_id;
    IF v_req_ctx IS NOT NULL AND v_req_ctx IS DISTINCT FROM 'dry_run' THEN
      RAISE EXCEPTION 'dry_run_classification_is_immutable: parent request is not dry_run (got %)', v_req_ctx
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_mode_derived_controls()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_mode_flag TEXT := current_setting('comm_hub.mode_transition', true);
  v_auto_flag TEXT := current_setting('comm_hub.automation_op',   true);
BEGIN
  IF v_mode_flag = 'on' OR v_auto_flag = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.dispatch_enabled           IS DISTINCT FROM OLD.dispatch_enabled
     OR NEW.dry_run_only            IS DISTINCT FROM OLD.dry_run_only
     OR NEW.email_live_enabled      IS DISTINCT FROM OLD.email_live_enabled
     OR NEW.sms_live_enabled        IS DISTINCT FROM OLD.sms_live_enabled
     OR NEW.whatsapp_live_enabled   IS DISTINCT FROM OLD.whatsapp_live_enabled
     OR NEW.scheduler_enabled       IS DISTINCT FROM OLD.scheduler_enabled
     OR NEW.automatic_triggers_enabled IS DISTINCT FROM OLD.automatic_triggers_enabled
     OR NEW.retry_worker_enabled    IS DISTINCT FROM OLD.retry_worker_enabled
     OR NEW.batch_enabled           IS DISTINCT FROM OLD.batch_enabled
     OR NEW.bulk_enabled            IS DISTINCT FROM OLD.bulk_enabled
     OR NEW.operating_mode          IS DISTINCT FROM OLD.operating_mode
     OR NEW.automation_state        IS DISTINCT FROM OLD.automation_state
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'mode_derived_field_direct_write',
      HINT = 'This setting is managed by the Communication Hub operating mode and automation controls.';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_receipt_cancel_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'C' AND OLD.status <> 'O' THEN
    RAISE EXCEPTION 'Receipt can only be cancelled when status is O (Original). Current status: %', OLD.status;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_request_dry_run_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_bypass text := current_setting('communication_hub.dry_run_immutability_bypass', true);
BEGIN
  IF v_bypass = 'migration' THEN
    RETURN NEW;
  END IF;

  IF OLD.decision_send_context = 'dry_run'
     AND NEW.decision_send_context IS DISTINCT FROM 'dry_run' THEN
    RAISE EXCEPTION 'dry_run_classification_is_immutable: request decision_send_context cannot be changed from dry_run'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enqueue_email(queue_name text, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ensure_comm_hub_event_live_control(p_module_code text, p_event_code text, p_channel text, p_risk_level text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_hub_event_live_control%ROWTYPE;
BEGIN
  PERFORM public._chub_assert_admin();
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 THEN
    RAISE EXCEPTION 'reason required';
  END IF;
  IF p_risk_level NOT IN ('low','medium','high','sensitive') THEN
    RAISE EXCEPTION 'invalid risk';
  END IF;

  INSERT INTO public.communication_hub_event_live_control(
    module_code, event_code, status, risk_level, reason, changed_by
  )
  VALUES (p_module_code, p_event_code, 'dry_run_only', p_risk_level, p_reason, auth.uid())
  ON CONFLICT (module_code, event_code) DO UPDATE
    SET risk_level = EXCLUDED.risk_level,
        reason = EXCLUDED.reason,
        changed_by = EXCLUDED.changed_by,
        changed_at = now()
        -- deliberately NOT touching status: wizard never promotes live
  RETURNING * INTO v_row;

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('live_control.' || p_module_code || '.' || p_event_code, NULL, to_jsonb(v_row), p_reason, auth.uid(), 'event-template-onboarding-wizard');

  RETURN to_jsonb(v_row);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ensure_module_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.core_module_profile (module_id, module_code)
  VALUES (NEW.id, NEW.name)
  ON CONFLICT (module_id) DO NOTHING;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.er_app_doc_delete(p_source_application_reference text, p_doc_id_or_source_id text, p_user_id uuid, p_user_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing uuid;
  v_regno varchar(20);
BEGIN
  BEGIN
    SELECT id INTO v_existing FROM public.er_application_documents
     WHERE id = p_doc_id_or_source_id::uuid
       AND source_application_reference = p_source_application_reference
     LIMIT 1;
  EXCEPTION WHEN invalid_text_representation THEN
    v_existing := NULL;
  END;

  IF v_existing IS NOT NULL THEN
    UPDATE public.er_application_documents
       SET is_active = false, is_deleted = true, updated_at = now()
     WHERE id = v_existing;
  ELSE
    SELECT m.regno INTO v_regno FROM public.er_master m
     WHERE m.regno = p_source_application_reference LIMIT 1;
    IF v_regno IS NULL THEN
      v_regno := UPPER(LPAD(RIGHT(regexp_replace(p_source_application_reference, '[^A-Za-z0-9]', '', 'g'), 6), 6, '0'));
    END IF;

    INSERT INTO public.er_application_documents (
      regno, source_application_reference, file_name, file_path, storage_url,
      is_active, is_deleted, source_document_id, uploaded_by, uploaded_by_code
    ) VALUES (
      v_regno, p_source_application_reference, '', '', '', false, true,
      p_doc_id_or_source_id, p_user_id::text, p_user_code
    );
  END IF;

  INSERT INTO public.er_audit_log (table_name, record_id, source_application_reference, action, changed_by, changed_by_code, field_name, new_value)
  VALUES ('er_application_documents', p_doc_id_or_source_id, p_source_application_reference, 'DOC_DELETE', p_user_id, p_user_code, 'is_deleted', 'true');
END;
$function$;
CREATE OR REPLACE FUNCTION public.er_app_doc_upsert(p_source_application_reference text, p_source_document_id text, p_file_meta jsonb, p_user_id uuid, p_user_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_regno varchar(20);
BEGIN
  IF p_source_application_reference IS NULL THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: source_application_reference is required';
  END IF;

  -- Resolve regno if already converted; otherwise use a placeholder derived from the app reference
  SELECT m.regno INTO v_regno
    FROM public.er_master m
   WHERE m.regno = p_source_application_reference
   LIMIT 1;

  IF v_regno IS NULL THEN
    v_regno := UPPER(LPAD(RIGHT(regexp_replace(p_source_application_reference, '[^A-Za-z0-9]', '', 'g'), 6), 6, '0'));
  END IF;

  IF p_source_document_id IS NOT NULL THEN
    UPDATE public.er_application_documents
       SET is_active = false, is_deleted = true, updated_at = now()
     WHERE source_application_reference = p_source_application_reference
       AND source_document_id = p_source_document_id
       AND is_active = true;
  END IF;

  INSERT INTO public.er_application_documents (
    regno, source_application_reference, doc_code, document_type, document_description,
    file_name, file_path, storage_url, file_size, mime_type, is_active,
    uploaded_by, uploaded_by_code, metadata, source_document_id, is_deleted
  ) VALUES (
    v_regno,
    p_source_application_reference,
    NULLIF(p_file_meta->>'doc_code',''),
    NULLIF(p_file_meta->>'document_type',''),
    NULLIF(p_file_meta->>'document_description',''),
    COALESCE(NULLIF(p_file_meta->>'file_name',''), 'unknown'),
    COALESCE(NULLIF(p_file_meta->>'file_path',''), ''),
    COALESCE(NULLIF(p_file_meta->>'storage_url', p_file_meta->>'url'), ''),
    NULLIF(p_file_meta->>'file_size','')::bigint,
    NULLIF(p_file_meta->>'mime_type',''),
    true,
    p_user_id::text,
    p_user_code,
    CASE WHEN p_file_meta ? 'metadata' THEN p_file_meta->'metadata' ELSE NULL END,
    p_source_document_id,
    false
  )
  RETURNING id INTO v_id;

  INSERT INTO public.er_audit_log (table_name, record_id, source_application_reference, action, changed_by, changed_by_code, new_value, field_name)
  VALUES ('er_application_documents', v_id::text, p_source_application_reference,
          CASE WHEN p_source_document_id IS NULL THEN 'DOC_UPLOAD' ELSE 'DOC_REPLACE' END,
          p_user_id, p_user_code, p_file_meta->>'file_name', 'file_name');

  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.er_app_docs_resolve(p_source_application_reference text, p_external_docs jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_replaced_or_deleted_ids text[];
  v_filtered_external jsonb;
  v_active_overrides jsonb;
BEGIN
  SELECT COALESCE(array_agg(DISTINCT source_document_id), ARRAY[]::text[])
    INTO v_replaced_or_deleted_ids
    FROM public.er_application_documents
   WHERE source_application_reference = p_source_application_reference
     AND source_document_id IS NOT NULL;

  SELECT COALESCE(jsonb_agg(d), '[]'::jsonb) INTO v_filtered_external
  FROM jsonb_array_elements(COALESCE(p_external_docs, '[]'::jsonb)) d
  WHERE NOT ( (d->>'id') = ANY(v_replaced_or_deleted_ids) );

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', id,
           'source_document_id', source_document_id,
           'document_name', file_name,
           'document_type', document_type,
           'document_description', document_description,
           'doc_code', doc_code,
           'file_name', file_name,
           'file_path', file_path,
           'url', storage_url,
           'storage_url', storage_url,
           'mime_type', mime_type,
           'file_size', file_size,
           'metadata', metadata,
           'source', 'override'
         )), '[]'::jsonb)
    INTO v_active_overrides
    FROM public.er_application_documents
   WHERE source_application_reference = p_source_application_reference
     AND is_active = true
     AND COALESCE(is_deleted, false) = false
     AND COALESCE(file_path, '') <> '';

  RETURN jsonb_build_object(
    'external', v_filtered_external,
    'overrides', v_active_overrides,
    'merged', v_filtered_external || v_active_overrides
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.er_documents_enqueue_dms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_active = true
     AND COALESCE(NEW.transfer_status, 'Pending') = 'Pending'
     AND COALESCE(NEW.file_path, '') <> '' THEN
    INSERT INTO public.dms_transfer_queue (scope, document_id, regno)
    VALUES ('er', NEW.id, NEW.regno)
    ON CONFLICT (scope, document_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.establish_comm_hub_forward_baseline_policies(p_module_code text, p_event_code text, p_channel text, p_expected_event_certification_id uuid, p_expected_template_version_id uuid, p_reason text, p_typed_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_module text := upper(p_module_code);
  v_event  text := upper(p_event_code);
  v_channel text := lower(coalesce(p_channel,'email'));
  v_evt_cert record; v_ctrl record; v_map record;
  v_sp_id uuid; v_rev_id uuid; v_sp record; v_rev record;
  v_send_hash text; v_review_hash text;
  v_send_version bigint; v_review_version bigint;
  v_send_created boolean := false; v_review_created boolean := false;
  v_audit_id uuid; v_production_lineage_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF coalesce(p_typed_confirmation,'') <> 'ESTABLISH FORWARD BASELINE' THEN
    RETURN jsonb_build_object('ok',false,'phase','TYPED_CONFIRMATION_MISMATCH');
  END IF;

  SELECT * INTO v_evt_cert FROM public.communication_hub_event_certification
   WHERE module_code=v_module AND event_code=v_event AND channel=v_channel FOR UPDATE;
  IF NOT FOUND OR v_evt_cert.id <> p_expected_event_certification_id THEN
    RETURN jsonb_build_object('ok',false,'phase','EVENT_CERT_MISMATCH');
  END IF;
  IF v_evt_cert.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    RETURN jsonb_build_object('ok',false,'phase','EVENT_NOT_LIVE');
  END IF;
  v_production_lineage_id := v_evt_cert.production_lineage_id;

  SELECT * INTO v_map FROM public.communication_hub_event_template_map
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel AND active=true LIMIT 1;

  SELECT * INTO v_sp FROM public.communication_hub_event_send_policy
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel LIMIT 1;

  IF v_sp.id IS NULL THEN
    v_send_version := 1;
    v_send_hash := encode(extensions.digest(jsonb_build_object(
      'send_mode','manual_live','environment','production','destination_scope','internal_only',
      'require_operator_reason', true,'require_typed_confirmation', true,
      'require_operator_role', true,'operator_role_required', true,'allow_operator_override', false,
      'approved_domains', ARRAY['mishainfotech.com']::text[], 'approved_recipients', ARRAY[]::text[],
      'max_recipients_per_send',1,'max_sends_per_day_per_recipient',1,'idle_seconds_between_sends',1440,
      'log_operator_reason', true,'auto_live_internal', false,'auto_live_recipient_portal', true,'auto_live_external', true,
      'policy_version',1
    )::text::bytea, 'sha256'::text),'hex');
    INSERT INTO public.communication_hub_event_send_policy(
      module_code,event_code,channel,send_mode,environment,destination_scope,
      require_operator_reason,require_typed_confirmation,require_operator_role,operator_role_required,allow_operator_override,
      approved_domains,approved_recipients,max_recipients_per_send,max_sends_per_day_per_recipient,idle_seconds_between_sends,
      log_operator_reason,auto_live_internal,auto_live_recipient_portal,auto_live_external,
      created_by,updated_at,notes,policy_version,policy_content_hash
    ) VALUES (
      v_module,v_event,v_channel,'manual_live','production','internal_only',
      true,true,true,true,false,
      ARRAY['mishainfotech.com']::text[], ARRAY[]::text[],
      1,1,1440,true,false,true,true,
      v_uid, now(),
      'Forward baseline established after LIVE_MANUAL confirmation.',
      v_send_version, v_send_hash
    ) RETURNING id INTO v_sp_id;
    v_send_created := true;
  ELSE
    v_sp_id := v_sp.id; v_send_version := v_sp.policy_version; v_send_hash := v_sp.policy_content_hash;
  END IF;

  SELECT * INTO v_rev FROM public.communication_hub_event_review_policy
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel LIMIT 1;

  IF v_rev.id IS NULL THEN
    v_review_version := 1;
    v_review_hash := encode(extensions.digest(jsonb_build_object(
      'review_mode','preview_required','preview_required', true,
      'allow_operator_edit_tokens', false,'allow_operator_edit_body', false,'allow_operator_change_recipient', false,
      'show_template_to_operator', true,'show_template_to_recipient_portal', false,
      'require_template_approval', true,'require_legal_approval', false,'require_business_approval', false,
      'approval_status','approved_internal','approved_template_version_id', p_expected_template_version_id
    )::text::bytea,'sha256'::text),'hex');
    INSERT INTO public.communication_hub_event_review_policy(
      module_code,event_code,channel,review_mode,preview_required,
      allow_operator_edit_tokens,allow_operator_edit_body,allow_operator_change_recipient,
      show_template_to_operator,show_template_to_recipient_portal,
      require_template_approval,require_legal_approval,require_business_approval,
      approval_status,approved_template_version_id,approved_by,approved_at,notes,
      policy_version,policy_content_hash
    ) VALUES (
      v_module,v_event,v_channel,'preview_required',true,
      false,false,false,true,false,true,false,false,
      'approved_internal', p_expected_template_version_id, v_uid, now(),
      'Forward review baseline established after LIVE_MANUAL confirmation.',
      v_review_version, v_review_hash
    ) RETURNING id INTO v_rev_id;
    v_review_created := true;
  ELSE
    v_rev_id := v_rev.id; v_review_version := v_rev.policy_version; v_review_hash := v_rev.policy_content_hash;
  END IF;

  IF v_send_created OR v_review_created THEN
    INSERT INTO public.communication_hub_forward_baseline_audit(
      module_code,event_code,channel,production_lineage_id,event_certification_id,
      send_policy_id,send_policy_version,send_policy_hash,
      review_policy_id,review_policy_version,review_policy_hash,
      actor,reason,effective_from,established_at,forward_baseline_only,typed_confirmation
    ) VALUES (
      v_module,v_event,v_channel,v_production_lineage_id,v_evt_cert.id,
      v_sp_id,v_send_version,v_send_hash,v_rev_id,v_review_version,v_review_hash,
      v_uid,p_reason,now(),now(),true,p_typed_confirmation
    ) RETURNING id INTO v_audit_id;
  ELSE
    SELECT id INTO v_audit_id FROM public.communication_hub_forward_baseline_audit
     WHERE event_certification_id=v_evt_cert.id
     ORDER BY established_at DESC LIMIT 1;
  END IF;

  RETURN jsonb_build_object(
    'ok',true,
    'idempotent', NOT (v_send_created OR v_review_created),
    'send_policy_created', v_send_created,'review_policy_created', v_review_created,
    'send_policy_id', v_sp_id,'send_policy_version', v_send_version,'send_policy_hash', v_send_hash,
    'review_policy_id', v_rev_id,'review_policy_version', v_review_version,'review_policy_hash', v_review_hash,
    'event_certification_id', v_evt_cert.id,'production_lineage_id', v_production_lineage_id,
    'audit_id', v_audit_id,'effective_from', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_live_gate(p_module_code text, p_event_code text, p_recipient_email text, p_mode text DEFAULT 'manual'::text, p_template_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reasons text[] := ARRAY[]::text[];
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_event_status text;
  v_event_risk text;
  v_tpl_id uuid;
  v_tpl_code text;
  v_tpl_active_flag boolean := false;
  v_tpl_active boolean := false;
  v_tpl_ver uuid;
  v_tpl_source text := 'missing';
  v_map_row public.communication_hub_event_template_map%ROWTYPE;
  v_queued_live integer;
  v_expires_at timestamptz;
  v_window_expired boolean := false;
  v_recipient text := lower(coalesce(p_recipient_email,''));
  v_mode text := lower(coalesce(p_mode,'manual'));
  v_sender public.communication_hub_sender_profile%ROWTYPE;
  v_sender_source text := 'none';
  v_recipient_internal boolean := (v_recipient LIKE '%@mishainfotech.com');
  v_expected_category text;
BEGIN
  SELECT * INTO v_settings FROM public.communication_hub_control_settings ORDER BY created_at ASC LIMIT 1;
  IF v_settings.id IS NULL THEN
    v_reasons := array_append(v_reasons, 'control_settings_missing');
  ELSE
    IF v_settings.dispatch_enabled IS DISTINCT FROM true THEN v_reasons := array_append(v_reasons, 'db_dispatch_disabled'); END IF;
    IF v_settings.dry_run_only THEN v_reasons := array_append(v_reasons, 'db_dry_run_only'); END IF;
    IF v_settings.email_live_enabled IS DISTINCT FROM true THEN v_reasons := array_append(v_reasons, 'db_email_live_disabled'); END IF;
    IF v_settings.live_eligible_after IS NULL THEN
      v_reasons := array_append(v_reasons, 'live_eligible_after_missing');
    ELSE
      v_expires_at := v_settings.live_eligible_after + make_interval(mins => greatest(1, least(1440, coalesce(v_settings.live_eligible_max_age_minutes,30))));
      IF now() > v_expires_at THEN
        v_window_expired := true;
        v_reasons := array_append(v_reasons, 'live_window_expired');
      END IF;
    END IF;
    IF NOT (coalesce(array_length(v_settings.allowed_email_addresses,1),0) = 1
       AND lower(v_settings.allowed_email_addresses[1]) = 'rohit@mishainfotech.com') THEN
      v_reasons := array_append(v_reasons, 'db_allowlist_not_pilot_only');
    END IF;
    IF coalesce(array_length(v_settings.allowed_email_domains,1),0) <> 0 THEN
      v_reasons := array_append(v_reasons, 'db_allowed_domains_not_empty');
    END IF;
  END IF;

  SELECT status, risk_level INTO v_event_status, v_event_risk
    FROM public.communication_hub_event_live_control
    WHERE module_code = p_module_code AND event_code = p_event_code;
  IF v_event_status IS NULL THEN
    v_reasons := array_append(v_reasons, 'event_live_control_missing');
  ELSIF v_mode IN ('cron','batch') THEN
    IF v_event_status <> 'live_cron_allowed' THEN v_reasons := array_append(v_reasons, 'event_not_live_cron_allowed'); END IF;
  ELSE
    IF v_event_status NOT IN ('live_manual_only','live_cron_allowed') THEN v_reasons := array_append(v_reasons, 'event_not_live'); END IF;
  END IF;

  -- Always load the mapping row (sender resolution needs it regardless of
  -- whether the caller pinned an explicit template code).
  SELECT * INTO v_map_row FROM public.communication_hub_event_template_map
    WHERE module_code=p_module_code AND event_code=p_event_code AND channel='email' AND active=true;

  -- Template resolution
  IF p_template_code IS NOT NULL AND length(trim(p_template_code)) > 0 THEN
    v_tpl_code := trim(p_template_code); v_tpl_source := 'explicit';
  ELSIF v_map_row.id IS NOT NULL THEN
    v_tpl_code := v_map_row.template_code; v_tpl_source := 'mapping_table';
  ELSE
    v_tpl_code := NULL; v_tpl_source := 'missing';
  END IF;

  IF v_tpl_code IS NULL THEN
    v_reasons := array_append(v_reasons, 'template_code_unresolved_for_event');
  ELSE
    SELECT id, (is_active AND active_version_id IS NOT NULL), active_version_id, is_active
      INTO v_tpl_id, v_tpl_active, v_tpl_ver, v_tpl_active_flag
      FROM public.core_template WHERE code = v_tpl_code LIMIT 1;
    IF v_tpl_id IS NULL THEN v_reasons := array_append(v_reasons, 'template_not_found');
    ELSIF v_tpl_active IS NOT TRUE THEN v_reasons := array_append(v_reasons, 'template_inactive_or_missing_active_version');
    END IF;
  END IF;

  IF v_recipient <> 'rohit@mishainfotech.com' THEN
    v_reasons := array_append(v_reasons, 'recipient_not_pilot_allowlist');
  END IF;

  SELECT count(*) INTO v_queued_live FROM public.communication_message
    WHERE test_mode = false AND status IN ('queued','sending');
  IF v_queued_live > 0 THEN
    v_reasons := array_append(v_reasons, format('other_live_messages_queued:%s', v_queued_live));
  END IF;

  -- Sender resolution
  IF v_map_row.id IS NOT NULL AND v_map_row.sender_profile_id IS NOT NULL THEN
    SELECT * INTO v_sender FROM public.communication_hub_sender_profile WHERE id = v_map_row.sender_profile_id;
    v_sender_source := 'event_mapping';
  END IF;
  IF v_sender.id IS NULL THEN
    SELECT * INTO v_sender FROM public.communication_hub_sender_profile
      WHERE is_default = true AND is_enabled = true LIMIT 1;
    IF v_sender.id IS NOT NULL THEN v_sender_source := 'system_default'; END IF;
  END IF;

  IF v_sender.id IS NULL THEN
    v_reasons := array_append(v_reasons, 'sender_profile_missing');
  ELSE
    IF v_sender.is_enabled IS NOT TRUE THEN
      v_reasons := array_append(v_reasons, 'sender_disabled');
    END IF;
    IF NOT v_recipient_internal THEN
      IF v_sender.provider_identity_status <> 'verified' THEN
        v_reasons := array_append(v_reasons, 'sender_not_verified');
      END IF;
      IF v_sender.domain_verified IS NOT TRUE THEN
        v_reasons := array_append(v_reasons, 'sender_domain_not_verified');
      END IF;
    END IF;
    v_expected_category := CASE
      WHEN p_module_code = 'LEGAL'                 THEN 'legal'
      WHEN p_module_code = 'BENEFITS' AND p_event_code IN ('CLAIM_APPROVAL_NOTICE','CLAIM_REJECTION_NOTICE') THEN 'benefits'
      WHEN p_module_code = 'BENEFITS'              THEN 'claims'
      WHEN p_module_code = 'COMPLIANCE'            THEN 'compliance'
      WHEN p_module_code = 'EMPLOYER_REGISTRATION' THEN 'registration'
      ELSE NULL
    END;
    -- Only complain when a specific category is expected AND the resolved
    -- sender does not match it (previously the check also required the
    -- resolved category to be 'notifications', so a correctly bound legal
    -- sender was still reported as a mismatch when the fallback kicked in).
    IF v_expected_category IS NOT NULL
       AND coalesce(v_sender.sender_category,'') <> v_expected_category THEN
      v_reasons := array_append(v_reasons, 'sender_category_mismatch');
    END IF;
    IF coalesce(v_event_risk,'low') IN ('high','sensitive')
       AND v_sender.sender_category = 'notifications' THEN
      IF NOT ('sender_category_mismatch' = ANY(v_reasons)) THEN
        v_reasons := array_append(v_reasons, 'sender_category_mismatch');
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ready', array_length(v_reasons,1) IS NULL,
    'reasons', to_jsonb(v_reasons),
    'gates', jsonb_build_object(
      'dispatch_enabled', v_settings.dispatch_enabled,
      'dry_run_only', v_settings.dry_run_only,
      'email_live_enabled', v_settings.email_live_enabled,
      'live_eligible_after', v_settings.live_eligible_after,
      'live_eligible_max_age_minutes', v_settings.live_eligible_max_age_minutes,
      'live_window_expires_at', v_expires_at,
      'live_window_expired', v_window_expired,
      'event_status', v_event_status,
      'event_risk_level', v_event_risk,
      'template', jsonb_build_object(
        'template_code', v_tpl_code, 'template_id', v_tpl_id,
        'active_version_id', v_tpl_ver, 'is_active', coalesce(v_tpl_active_flag, false),
        'resolution_source', v_tpl_source
      ),
      'template_active', v_tpl_active,
      'template_active_version_id', v_tpl_ver,
      'other_live_queued', v_queued_live,
      'allowlist_addresses', to_jsonb(coalesce(v_settings.allowed_email_addresses, ARRAY[]::text[])),
      'allowlist_domains',   to_jsonb(coalesce(v_settings.allowed_email_domains,   ARRAY[]::text[])),
      'recipient', v_recipient, 'mode', v_mode,
      'sender', CASE WHEN v_sender.id IS NULL THEN
        jsonb_build_object('resolution_source','none')
      ELSE jsonb_build_object(
        'sender_profile_id', v_sender.id,
        'profile_code', v_sender.profile_code,
        'profile_name', v_sender.profile_name,
        'from_email', v_sender.from_email,
        'display_name', v_sender.display_name,
        'reply_to_email', v_sender.reply_to_email,
        'sender_category', v_sender.sender_category,
        'audience_type', v_sender.audience_type,
        'risk_level', v_sender.risk_level,
        'provider_code', v_sender.provider_code,
        'provider_identity_status', v_sender.provider_identity_status,
        'domain_verified', v_sender.domain_verified,
        'is_enabled', v_sender.is_enabled,
        'spf_status', v_sender.spf_status,
        'dkim_status', v_sender.dkim_status,
        'dmarc_status', v_sender.dmarc_status,
        'resolution_source', v_sender_source
      ) END
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_recipient_policy(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy   public.communication_hub_recipient_policy%ROWTYPE;
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_to       text[] := ARRAY[]::text[];
  v_cc       text[] := ARRAY[]::text[];
  v_bcc      text[] := ARRAY[]::text[];
  v_matched  jsonb := '[]'::jsonb;
  v_blocked  jsonb := '[]'::jsonb;
  v_matched_by jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_norm text; v_dom text;
  v_ok boolean; v_reason text;
  e text; seen jsonb := '{}'::jsonb;
  total integer; event_max integer; effective_max integer;
BEGIN
  SELECT * INTO v_policy FROM public.communication_hub_recipient_policy WHERE singleton_guard = 'primary';
  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard = 'primary';

  IF jsonb_typeof(p_payload -> 'to') = 'array' THEN
    SELECT COALESCE(array_agg(lower(btrim(x))), ARRAY[]::text[])
      INTO v_to FROM jsonb_array_elements_text(p_payload -> 'to') AS x;
  END IF;
  IF jsonb_typeof(p_payload -> 'cc') = 'array' THEN
    SELECT COALESCE(array_agg(lower(btrim(x))), ARRAY[]::text[])
      INTO v_cc FROM jsonb_array_elements_text(p_payload -> 'cc') AS x;
  END IF;
  IF jsonb_typeof(p_payload -> 'bcc') = 'array' THEN
    SELECT COALESCE(array_agg(lower(btrim(x))), ARRAY[]::text[])
      INTO v_bcc FROM jsonb_array_elements_text(p_payload -> 'bcc') AS x;
  END IF;

  IF NOT v_policy.cc_allowed AND COALESCE(array_length(v_cc,1),0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','cc_not_allowed','message','CC recipients are not permitted');
  END IF;
  IF NOT v_policy.bcc_allowed AND COALESCE(array_length(v_bcc,1),0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_object('code','bcc_not_allowed','message','BCC recipients are not permitted');
  END IF;

  IF COALESCE(array_length(v_to,1),0) > v_policy.max_to_recipients THEN
    v_blockers := v_blockers || jsonb_build_object('code','to_limit_exceeded','limit',v_policy.max_to_recipients);
  END IF;
  IF v_policy.cc_allowed AND COALESCE(array_length(v_cc,1),0) > v_policy.max_cc_recipients THEN
    v_blockers := v_blockers || jsonb_build_object('code','cc_limit_exceeded','limit',v_policy.max_cc_recipients);
  END IF;
  IF v_policy.bcc_allowed AND COALESCE(array_length(v_bcc,1),0) > v_policy.max_bcc_recipients THEN
    v_blockers := v_blockers || jsonb_build_object('code','bcc_limit_exceeded','limit',v_policy.max_bcc_recipients);
  END IF;

  total := COALESCE(array_length(v_to,1),0) + COALESCE(array_length(v_cc,1),0) + COALESCE(array_length(v_bcc,1),0);
  event_max := NULLIF((p_payload ->> 'event_max_recipients'), '')::int;
  effective_max := LEAST(v_policy.max_recipients_per_request, COALESCE(event_max, 200), 200);
  IF total > effective_max THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','total_recipient_limit_exceeded','limit',effective_max,
      'source', CASE
        WHEN effective_max = v_policy.max_recipients_per_request THEN 'recipient_policy'
        WHEN effective_max = event_max THEN 'event_policy'
        ELSE 'technical_ceiling' END);
  END IF;

  FOR e IN SELECT unnest(v_to || v_cc || v_bcc) LOOP
    IF (seen ? e) THEN
      v_warnings := v_warnings || jsonb_build_object('code','duplicate_recipient','address',e);
    ELSE
      seen := seen || jsonb_build_object(e, true);
    END IF;
  END LOOP;

  IF v_settings.operating_mode = 'EMERGENCY_STOP' THEN
    v_blockers := v_blockers || jsonb_build_object('code','emergency_stop_active');
  END IF;

  IF v_policy.active_mode = 'CONTROLLED_EXTERNAL_RECIPIENTS' THEN
    v_blockers := v_blockers || jsonb_build_object('code','controlled_external_recipients_not_certified');
  END IF;

  FOR e IN SELECT DISTINCT unnest(v_to || v_cc || v_bcc) LOOP
    v_norm := e; v_ok := false; v_reason := NULL;
    IF v_norm IS NULL OR v_norm = '' OR v_norm NOT LIKE '_%@_%._%' THEN
      v_blocked := v_blocked || to_jsonb(v_norm);
      v_blockers := v_blockers || jsonb_build_object('code','invalid_address','address',v_norm);
      CONTINUE;
    END IF;
    v_dom := split_part(v_norm, '@', 2);

    IF v_policy.active_mode = 'DISABLED' THEN
      v_reason := 'disabled_mode';
    ELSIF v_policy.active_mode = 'SINGLE_CONFIGURED_RECIPIENT' THEN
      IF v_policy.single_configured_address IS NOT NULL
         AND lower(btrim(v_policy.single_configured_address)) = v_norm THEN
        v_ok := true; v_matched_by := v_matched_by || jsonb_build_object(v_norm,'single_configured_address');
      ELSE v_reason := 'not_single_configured_address'; END IF;
    ELSIF v_policy.active_mode = 'APPROVED_NAMED_RECIPIENTS' THEN
      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_policy.approved_named_addresses) x
        WHERE COALESCE((x->>'active')::boolean, true)
          AND lower(btrim(x->>'address')) = v_norm
      ) THEN v_ok := true; v_matched_by := v_matched_by || jsonb_build_object(v_norm,'approved_named_address');
      ELSE v_reason := 'not_in_approved_named_addresses'; END IF;
    ELSIF v_policy.active_mode = 'APPROVED_DOMAINS' THEN
      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_policy.approved_domains) x
        WHERE COALESCE((x->>'active')::boolean, true)
          AND ( lower(btrim(x->>'domain')) = v_dom
             OR (v_policy.subdomains_permitted AND v_dom LIKE ('%.' || lower(btrim(x->>'domain')))))
      ) THEN v_ok := true; v_matched_by := v_matched_by || jsonb_build_object(v_norm,'approved_domain');
      ELSE v_reason := 'domain_not_approved'; END IF;
    END IF;

    IF v_ok THEN v_matched := v_matched || to_jsonb(v_norm);
    ELSE
      v_blocked := v_blocked || to_jsonb(v_norm);
      v_blockers := v_blockers || jsonb_build_object('code','recipient_not_authorised','address',v_norm,'reason',v_reason);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'allowed', jsonb_array_length(v_blockers) = 0,
    'release_mode', v_policy.active_mode,
    'matched_recipients', v_matched,
    'blocked_recipients', v_blocked,
    'matched_by', v_matched_by,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'evaluated_at', now(),
    'configuration_version', v_policy.configuration_version,
    'policy_version', v_policy.policy_version
  );
END $function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_review_policy(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text := p_payload->>'module_code';
  v_event  text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_tpl_ver uuid := nullif(p_payload->>'template_version_id','')::uuid;
  v_test_mode boolean := coalesce((p_payload->>'test_mode')::boolean, false);
  v_send_mode text := coalesce(p_payload->>'send_mode','live'); -- 'dry_run'|'live'|'auto_live_internal'
  v_preview_confirmed boolean := coalesce((p_payload->>'preview_confirmed')::boolean, false);
  v_subject text := coalesce(p_payload->>'rendered_subject','');
  v_body    text := coalesce(p_payload->>'rendered_body','');
  v_unresolved jsonb := coalesce(p_payload->'unresolved_tokens','[]'::jsonb);
  v_policy communication_hub_event_review_policy%ROWTYPE;
  v_blockers text[] := ARRAY[]::text[];
  v_warnings text[] := ARRAY[]::text[];
  v_composite text;
  v_required_action text := null;
BEGIN
  IF v_module IS NULL OR v_event IS NULL THEN
    RETURN jsonb_build_object('allowed', false,
      'blockers', jsonb_build_array('missing_module_or_event'),
      'warnings','[]'::jsonb,'review_policy',null,'required_action',null);
  END IF;

  SELECT * INTO v_policy
    FROM communication_hub_event_review_policy
   WHERE module_code = v_module AND event_code = v_event AND channel = v_channel
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'blockers', jsonb_build_array('review_policy_missing'),
      'warnings','[]'::jsonb,
      'review_policy', null,
      'required_action','configure_review_policy');
  END IF;

  IF v_policy.preview_required AND v_send_mode = 'live' AND NOT v_preview_confirmed THEN
    v_blockers := array_append(v_blockers,'preview_required');
    v_required_action := coalesce(v_required_action,'operator_must_confirm_preview');
  END IF;

  IF v_policy.require_template_approval THEN
    IF v_policy.approval_status NOT IN ('approved_internal','approved_external') THEN
      v_blockers := array_append(v_blockers,'template_not_approved_for_internal');
      v_required_action := coalesce(v_required_action,'approve_template');
    END IF;
    IF v_policy.approved_template_version_id IS NOT NULL
       AND v_tpl_ver IS NOT NULL
       AND v_policy.approved_template_version_id <> v_tpl_ver THEN
      v_blockers := array_append(v_blockers,'template_version_not_approved');
    END IF;
  END IF;

  IF v_policy.require_legal_approval AND v_policy.approval_status NOT IN ('approved_external','approved_internal') THEN
    v_blockers := array_append(v_blockers,'legal_approval_required');
  END IF;

  IF jsonb_typeof(v_unresolved) = 'array' AND jsonb_array_length(v_unresolved) > 0 THEN
    v_blockers := array_append(v_blockers,'unresolved_tokens_present');
  END IF;

  v_composite := lower(coalesce(v_subject,'') || ' ' || coalesce(v_body,''));
  IF v_composite ~ '\{\{[^}]+\}\}' OR v_composite ~ '\ydummy\y' OR v_composite ~ '\yplaceholder\y' THEN
    IF v_send_mode = 'live' THEN
      v_blockers := array_append(v_blockers,'dummy_template_wording_detected');
    ELSE
      v_warnings := array_append(v_warnings,'dummy_template_wording_detected');
    END IF;
  END IF;

  -- Dry-run relaxation: keep only review_policy_missing as blocker
  IF v_send_mode = 'dry_run' OR v_test_mode THEN
    v_warnings := array_cat(v_warnings, v_blockers);
    v_blockers := ARRAY[]::text[];
  END IF;

  RETURN jsonb_build_object(
    'allowed', (array_length(v_blockers,1) IS NULL),
    'blockers', to_jsonb(v_blockers),
    'warnings', to_jsonb(v_warnings),
    'review_policy', to_jsonb(v_policy),
    'required_action', v_required_action
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_runtime_gate_status(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module    text := p_payload->>'module_code';
  v_event     text := p_payload->>'event_code';
  v_channel   text := COALESCE(p_payload->>'channel','email');
  v_send_mode text := COALESCE(p_payload->>'send_mode', p_payload->>'mode','dry_run');
  v_recipient text := LOWER(COALESCE(p_payload->>'recipient_email',''));
  v_rec_count int  := COALESCE((p_payload->>'recipient_count')::int,
                              CASE WHEN v_recipient <> '' THEN 1 ELSE 0 END);
  v_tpl_ver   text := NULLIF(p_payload->>'template_version_id','');
  v_preview_ok boolean := COALESCE((p_payload->>'preview_confirmed')::boolean, false);
  v_to_recipients jsonb;
  v_canon jsonb;
  v_send_ctx text;
BEGIN
  IF v_recipient <> '' THEN v_to_recipients := jsonb_build_array(v_recipient);
  ELSE v_to_recipients := COALESCE(p_payload->'to_recipients','[]'::jsonb); END IF;

  v_send_ctx := CASE v_send_mode
    WHEN 'live' THEN 'manual_live' WHEN 'manual_live' THEN 'manual_live'
    WHEN 'auto_live_internal' THEN 'auto_live_internal'
    WHEN 'cron' THEN 'cron' WHEN 'batch' THEN 'batch'
    WHEN 'controlled_live' THEN 'controlled_live' WHEN 'preview' THEN 'preview'
    ELSE 'dry_run' END;

  v_canon := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code', v_module, 'event_code', v_event, 'channel', v_channel,
    'send_context', v_send_ctx, 'to_recipients', v_to_recipients,
    'preview_confirmed', v_preview_ok, 'template_version_id', v_tpl_ver));

  RETURN jsonb_build_object(
    'allowed',                     COALESCE((v_canon->>'allowed')::boolean, false),
    'source',                      'evaluate_comm_hub_runtime_gate_status(compat_wrapper_v2)',
    'delegates_to',                'evaluate_comm_hub_send_decision',
    'legacy_authorization_allowed', COALESCE((v_canon->>'allowed')::boolean, false),
    'send_mode', v_send_mode, 'module_code', v_module, 'event_code', v_event,
    'channel', v_channel, 'recipient_count', v_rec_count,
    'preview_confirmed', v_preview_ok, 'template_version_id', v_tpl_ver,
    'blockers',      COALESCE(v_canon->'blockers','[]'::jsonb),
    'warnings',      COALESCE(v_canon->'warnings','[]'::jsonb),
    'gate_results',  COALESCE(v_canon->'gate_results','[]'::jsonb),
    'needs_review',  '[]'::jsonb,
    'trace_context', COALESCE(v_canon->'trace_context', jsonb_build_object(
                       'current_stage','unknown','blocked_stage', NULL,'blocker_codes','[]'::jsonb)),
    'canonical_decision_id',      v_canon->>'decision_id',
    'configuration_version',      v_canon->'configuration_version',
    'recipient_policy_version',   v_canon->'recipient_policy_version',
    'evaluated_at',               v_canon->>'evaluated_at'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_send_authorization(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module     text := p_payload->>'module_code';
  v_event      text := p_payload->>'event_code';
  v_channel    text := COALESCE(p_payload->>'channel','email');
  v_env        text := COALESCE(p_payload->>'environment_scope','production');
  v_recipients jsonb := COALESCE(p_payload->'recipients', '[]'::jsonb);
  v_entity_id  text := p_payload->>'entity_id';
  v_send_ctx   text := COALESCE(p_payload->>'send_context','manual_live');
  v_canon      jsonb;
  v_policy     jsonb;
  v_blocker_codes jsonb := '[]'::jsonb;
  v_required_action text := NULL;
  v_recipient_count int := 0;
BEGIN
  IF jsonb_typeof(v_recipients) = 'array' THEN
    v_recipient_count := jsonb_array_length(v_recipients);
  END IF;

  v_canon := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code',       v_module,
    'event_code',        v_event,
    'channel',           v_channel,
    'environment_scope', v_env,
    'send_context',      v_send_ctx,
    'to_recipients',     v_recipients,
    'entity_id',         v_entity_id,
    'business_event_id', NULLIF(p_payload->>'business_event_id',''),
    'dedupe_key',        NULLIF(p_payload->>'dedupe_key','')
  ));

  SELECT COALESCE(jsonb_agg(b->>'code'), '[]'::jsonb) INTO v_blocker_codes
    FROM jsonb_array_elements(COALESCE(v_canon->'blockers','[]'::jsonb)) AS b
   WHERE b ? 'code';

  SELECT b->>'fix_action' INTO v_required_action
    FROM jsonb_array_elements(COALESCE(v_canon->'blockers','[]'::jsonb)) AS b
   WHERE b ? 'fix_action' AND (b->>'fix_action') IS NOT NULL LIMIT 1;

  BEGIN
    v_policy := public.resolve_comm_hub_send_policy(v_module, v_event, v_channel, v_env);
  EXCEPTION WHEN OTHERS THEN v_policy := '{}'::jsonb;
  END;

  RETURN jsonb_build_object(
    'authorized',       COALESCE((v_canon->>'allowed')::boolean, false),
    'mode',             v_policy->>'send_policy',
    'blockers',         v_blocker_codes,
    'required_action',  v_required_action,
    'policy',           v_policy,
    'sender_verified',  COALESCE((v_policy->>'sender_verified')::boolean, false),
    'template_mapped',  COALESCE((v_policy->>'template_mapped')::boolean, false),
    'recipient_count',  v_recipient_count,
    'duplicate_count',  0,
    'duplicate_scope',  COALESCE(v_policy->>'duplicate_scope','entity'),
    'duplicate_match',  NULL,
    'canonical_decision_id',   v_canon->>'decision_id',
    'canonical_status',        v_canon->>'status',
    'configuration_version',   v_canon->'configuration_version',
    'recipient_policy_version', v_canon->'recipient_policy_version',
    'send_policy_version',     v_canon->'send_policy_version',
    'review_policy_version',   v_canon->'review_policy_version',
    'canonical_blockers',      v_canon->'blockers',
    'source',                  'evaluate_comm_hub_send_authorization(compat_wrapper_v2)',
    'delegates_to',            'evaluate_comm_hub_send_decision'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_send_decision(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev_result jsonb;
  v_result jsonb;
  v_legacy_flag boolean := coalesce((p_payload->>'preview_confirmed')::boolean, false)
                          OR coalesce((p_payload->>'preview_shown')::boolean, false)
                          OR coalesce(((p_payload->'review_context')->>'preview_confirmed')::boolean, false)
                          OR coalesce(((p_payload->'metadata')->>'preview_confirmed')::boolean, false)
                          OR coalesce(((p_payload->'context')->>'preview_confirmed')::boolean, false);
  v_ctx text := coalesce(p_payload->>'send_context', p_payload->>'send_mode','dry_run');
  v_appr_id uuid := nullif(p_payload->>'preview_approval_id','')::uuid;
  v_cert_id uuid := nullif(p_payload->>'dry_run_certification_id','')::uuid;
  v_validator jsonb;
  v_cert_validator jsonb;
  v_blockers jsonb;
  v_warnings jsonb;
  v_allowed boolean;
  v_needs_preview boolean;
BEGIN
  v_prev_result := public._evaluate_comm_hub_send_decision_core(p_payload);
  v_result := v_prev_result;
  v_blockers := coalesce(v_result->'blockers','[]'::jsonb);
  v_warnings := coalesce(v_result->'warnings','[]'::jsonb);
  v_allowed  := coalesce((v_result->>'allowed')::boolean, false);

  IF v_legacy_flag THEN
    v_warnings := v_warnings || jsonb_build_object('code','legacy_preview_confirmation_ignored','stage','preview_approval',
      'message','Legacy preview_confirmed/preview_shown flags are ignored; require a preview_approval_id.');
  END IF;

  v_needs_preview := v_ctx IN ('controlled_live','manual_live','manual_production');
  IF v_needs_preview THEN
    IF v_appr_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object('code','preview_approval_missing','stage','preview_approval','severity','critical',
        'message','A valid preview_approval_id is required for this send context.','fix_route','/admin/communication-hub/pilots');
      v_allowed := false;
    ELSE
      v_validator := public.validate_comm_hub_preview_approval(jsonb_build_object(
        'approval_id', v_appr_id,
        'module_code', p_payload->>'module_code',
        'event_code',  p_payload->>'event_code',
        'channel',     coalesce(p_payload->>'channel','email'),
        'send_context', v_ctx,
        'to_recipients', coalesce(p_payload->'to_recipients','[]'::jsonb),
        'cc_recipients', coalesce(p_payload->'cc_recipients','[]'::jsonb),
        'bcc_recipients', coalesce(p_payload->'bcc_recipients','[]'::jsonb),
        'expected_template_version_id', p_payload->>'template_version_id',
        'expected_sender_profile_id',   p_payload->>'sender_profile_id',
        'expected_content_hash',        p_payload->>'expected_content_hash'));
      IF NOT coalesce((v_validator->>'valid')::boolean,false) THEN
        v_blockers := v_blockers || coalesce(v_validator->'blockers','[]'::jsonb);
        v_allowed := false;
      END IF;
      v_result := jsonb_set(v_result, '{preview_validator}', v_validator, true);
    END IF;
  END IF;

  IF v_ctx = 'controlled_live' THEN
    IF v_cert_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object('code','dry_run_certification_missing','stage','dry_run','severity','high',
        'message','A valid dry_run_certification_id is required for controlled_live.',
        'fix_route','/admin/communication-hub/pilots');
      v_allowed := false;
    ELSE
      v_cert_validator := public.validate_comm_hub_dry_run_certification(jsonb_build_object(
        'certification_id', v_cert_id,
        'module_code', p_payload->>'module_code',
        'event_code',  p_payload->>'event_code',
        'channel',     coalesce(p_payload->>'channel','email'),
        'to_recipients', coalesce(p_payload->'to_recipients','[]'::jsonb),
        'cc_recipients', coalesce(p_payload->'cc_recipients','[]'::jsonb),
        'bcc_recipients', coalesce(p_payload->'bcc_recipients','[]'::jsonb),
        'expected_template_version_id', p_payload->>'template_version_id',
        'expected_sender_profile_id',   p_payload->>'sender_profile_id',
        'expected_content_hash',        p_payload->>'expected_content_hash'));
      IF NOT coalesce((v_cert_validator->>'valid')::boolean,false) THEN
        v_blockers := v_blockers || coalesce(v_cert_validator->'blockers','[]'::jsonb);
        v_allowed := false;
      END IF;
      v_result := jsonb_set(v_result, '{dry_run_certification_validator}', v_cert_validator, true);
    END IF;
  END IF;

  v_result := jsonb_set(v_result, '{blockers}', v_blockers, true);
  v_result := jsonb_set(v_result, '{warnings}', v_warnings, true);
  v_result := jsonb_set(v_result, '{allowed}', to_jsonb(v_allowed), true);
  v_result := jsonb_set(v_result, '{status}',  to_jsonb(CASE WHEN v_allowed THEN 'allowed' ELSE 'blocked' END), true);
  RETURN v_result;
END; $function$;
CREATE OR REPLACE FUNCTION public.evaluate_comm_hub_stage_readiness(p_module_code text, p_event_code text, p_target_stage text DEFAULT 'PREVIEW_READY'::text, p_channel text DEFAULT 'email'::text, p_auto_compute_sender_readiness boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stage text := public.normalize_comm_hub_go_live_stage_strict(p_target_stage);
  v_module text := upper(coalesce(p_module_code,''));
  v_event  text := upper(coalesce(p_event_code,''));
  v_reqs jsonb := public.get_comm_hub_stage_requirements(v_stage);
  v_map communication_hub_event_template_map%ROWTYPE;
  v_tv_id uuid;
  v_fixture jsonb; v_sender_id uuid; v_sender_result jsonb;
  v_runner jsonb; v_blockers jsonb; v_warnings jsonb; v_ready boolean;
  v_runner_stage text := CASE
    WHEN v_stage IN ('READINESS_ONLY','PREVIEW_READY','DRY_RUN_READY','CONTROLLED_STUB_READY') THEN v_stage
    ELSE 'CONTROLLED_STUB_READY' END;
BEGIN
  v_runner := public.run_comm_hub_go_live_certification(v_module, v_event, p_channel, v_runner_stage, false);
  v_blockers := COALESCE(v_runner->'blockers','[]'::jsonb);
  v_warnings := COALESCE(v_runner->'warnings','[]'::jsonb);
  SELECT * INTO v_map FROM communication_hub_event_template_map
    WHERE module_code=v_module AND event_code=v_event AND channel=p_channel AND active=true LIMIT 1;
  IF v_map.id IS NOT NULL THEN
    SELECT tv.id INTO v_tv_id FROM core_template_version tv
      WHERE tv.template_id = v_map.template_id ORDER BY tv.version_no DESC LIMIT 1;
  END IF;
  IF (v_reqs->>'fixture_compatibility_required')::boolean THEN
    v_fixture := public.check_comm_hub_event_fixture_compatibility_v2(v_module,v_event,p_channel,v_tv_id,NULL,NULL);
    IF NOT COALESCE((v_fixture->>'is_compatible')::boolean,false) THEN
      v_blockers := v_blockers || jsonb_build_object('code','fixture_incompatible_with_contract_v2',
        'severity','BLOCKER','stage',v_stage,'detail',v_fixture);
    END IF;
  END IF;
  IF (v_reqs->>'sender_test_ready_required')::boolean OR (v_reqs->>'sender_real_email_ready_required')::boolean THEN
    SELECT sp.id INTO v_sender_id FROM communication_hub_sender_profile sp
      WHERE sp.is_enabled=true
      ORDER BY (sp.profile_code='SENDER_'||v_module) DESC,(sp.profile_code='SENDER_LEGAL') DESC, sp.updated_at DESC LIMIT 1;
    IF v_sender_id IS NOT NULL AND p_auto_compute_sender_readiness THEN
      v_sender_result := public.compute_comm_hub_sender_readiness(v_sender_id,
        CASE WHEN (v_reqs->>'sender_real_email_ready_required')::boolean THEN 'REAL_EMAIL_READY' ELSE 'TEST_READY' END);
    END IF;
  END IF;
  v_ready := (jsonb_array_length(v_blockers)=0);
  RETURN jsonb_build_object(
    'ok',v_ready,'schema_version','stage-readiness/2',
    'module_code',v_module,'event_code',v_event,'channel',p_channel,
    'requested_stage',v_stage,'ready_for_requested_stage',v_ready,
    'requirements',v_reqs,'blockers',v_blockers,'warnings',v_warnings,'advisories','[]'::jsonb,
    'runner_result',v_runner,'fixture_result',v_fixture,
    'sender_result',v_sender_result,'sender_profile_id',v_sender_id,
    'resolved_template_version_id',v_tv_id,'evaluated_at',now());
END; $function$;
CREATE OR REPLACE FUNCTION public.evaluate_levy_amounts(p_amounts numeric[], p_slab_id uuid, p_pay_period_code character varying)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eval_amounts NUMERIC[];
  v_total_levy NUMERIC := 0;
  v_slab RECORD;
  v_amount NUMERIC;
  v_levy NUMERIC;
  v_i INTEGER;
  v_arr_len INTEGER;
BEGIN
  v_arr_len := COALESCE(array_length(p_amounts, 1), 0);
  IF v_arr_len = 0 THEN RETURN 0; END IF;

  -- Build evaluation array based on pay period
  IF p_pay_period_code IN ('E2W', '2M') THEN
    -- Pair weeks: [wk1+wk2, wk3+wk4]
    v_eval_amounts := ARRAY[
      COALESCE(p_amounts[1], 0) + COALESCE(p_amounts[2], 0),
      COALESCE(p_amounts[3], 0) + COALESCE(p_amounts[4], 0)
    ];
    -- Add wk5 if present and non-zero
    IF v_arr_len >= 5 AND COALESCE(p_amounts[5], 0) > 0 THEN
      v_eval_amounts := v_eval_amounts || p_amounts[5];
    END IF;
    -- Handle 6th element (bonus/holiday fallback) if present
    IF v_arr_len >= 6 AND COALESCE(p_amounts[6], 0) > 0 THEN
      v_eval_amounts := v_eval_amounts || p_amounts[6];
    END IF;
  ELSE
    -- Weekly: keep individual elements as-is
    v_eval_amounts := p_amounts;
  END IF;

  -- Evaluate each element against slabs
  FOR v_i IN 1..COALESCE(array_length(v_eval_amounts, 1), 0) LOOP
    v_amount := COALESCE(v_eval_amounts[v_i], 0);
    v_levy := 0;
    IF v_amount > 0 THEN
      SELECT * INTO v_slab FROM public.tb_levy_slab_details
      WHERE slab_id = p_slab_id AND pay_period = p_pay_period_code
        AND is_active = true AND v_amount > over_amt
      ORDER BY over_amt DESC LIMIT 1;
      IF v_slab IS NOT NULL THEN
        v_levy := ROUND(v_slab.base_amt + ((v_amount - v_slab.over_amt + 0.01) * v_slab.tax_rate), 2);
      END IF;
    END IF;
    v_total_levy := v_total_levy + v_levy;
  END LOOP;

  RETURN v_total_levy;
END;
$function$;
CREATE OR REPLACE FUNCTION public.execute_comm_hub_dry_run(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := coalesce(nullif(p_payload->>'requested_by','')::uuid, auth.uid());
  v_module text := p_payload->>'module_code';
  v_event  text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_to  jsonb := coalesce(p_payload->'to_recipients','[]'::jsonb);
  v_cc  jsonb := coalesce(p_payload->'cc_recipients','[]'::jsonb);
  v_bcc jsonb := coalesce(p_payload->'bcc_recipients','[]'::jsonb);
  v_snap_id uuid := nullif(p_payload->>'preview_snapshot_id','')::uuid;
  v_appr_id uuid := nullif(p_payload->>'preview_approval_id','')::uuid;
  v_idem text := nullif(p_payload->>'idempotency_key','');
  v_reason text := coalesce(p_payload->>'operator_reason','');
  v_started timestamptz := now();
  v_snap public.communication_preview_snapshot%ROWTYPE;
  v_norm jsonb;
  v_recipient_hash text;
  v_decision jsonb;
  v_allowed boolean;
  v_request_id uuid;
  v_request_no text;
  v_message_id uuid;
  v_attempt_id uuid;
  v_trace_id uuid;
  v_trace_no text;
  v_cert_id uuid;
  v_cert_no text;
  v_existing public.communication_dry_run_certification%ROWTYPE;
  v_blockers jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_final_status text;
  v_orig_decision_id uuid;
  v_reval_decision_id uuid;
  v_cfg_ver bigint; v_recip_ver bigint; v_send_ver bigint; v_review_ver bigint;
  v_expires_at timestamptz;
  v_expiry_days integer := 7;
  v_operating_mode text;
BEGIN
  -- Part 4.1 — authentication
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','not_authenticated','stage','auth','severity','critical')));
  END IF;

  -- Part 4.3 — idempotency key required
  IF v_idem IS NULL OR length(v_idem) < 8 THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','idempotency_key_required','stage','idempotency','severity','critical')));
  END IF;

  -- Part 4.4/4.5 — idempotency lookup: return existing certification if scope matches
  SELECT * INTO v_existing FROM public.communication_dry_run_certification WHERE idempotency_key = v_idem;
  IF FOUND THEN
    IF v_existing.module_code <> coalesce(v_module,v_existing.module_code)
       OR v_existing.event_code <> coalesce(v_event,v_existing.event_code)
       OR v_existing.channel     <> coalesce(v_channel,v_existing.channel)
    THEN
      RETURN jsonb_build_object('status','BLOCKED','passed',false,
        'blockers', jsonb_build_array(jsonb_build_object('code','idempotency_key_scope_mismatch','stage','idempotency','severity','critical')));
    END IF;
    v_final_status := CASE WHEN v_existing.status='ACTIVE' AND v_existing.result='DRY_RUN_PASSED' THEN 'DRY_RUN_PASSED'
                          WHEN v_existing.result='BLOCKED' THEN 'BLOCKED'
                          ELSE 'DRY_RUN_FAILED' END;
    RETURN jsonb_build_object(
      'status', v_final_status,
      'passed', v_final_status='DRY_RUN_PASSED',
      'idempotent_replay', true,
      'dry_run_certification_id', v_existing.id,
      'request_id', v_existing.communication_request_id,
      'message_id', v_existing.communication_message_id,
      'delivery_attempt_id', v_existing.communication_delivery_attempt_id,
      'trace_id', v_existing.trace_id,
      'original_decision_id', v_existing.original_decision_id,
      'dispatcher_revalidation_decision_id', v_existing.dispatcher_revalidation_decision_id,
      'preview_snapshot_id', v_existing.preview_snapshot_id,
      'preview_approval_id', v_existing.preview_approval_id,
      'provider_call_attempted', v_existing.provider_call_attempted,
      'provider_message_id', NULL,
      'certification_expires_at', v_existing.expires_at,
      'started_at', v_existing.certified_at,
      'completed_at', v_existing.certified_at,
      'message','Dry test passed — no real email was sent.'
    );
  END IF;

  -- Snapshot load + scope match
  IF v_snap_id IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','preview_snapshot_required','stage','preview','severity','critical')));
  END IF;
  SELECT * INTO v_snap FROM public.communication_preview_snapshot WHERE id = v_snap_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','preview_snapshot_missing','stage','preview','severity','critical')));
  END IF;
  IF v_snap.module_code <> v_module OR v_snap.event_code <> v_event OR v_snap.channel <> v_channel THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','preview_snapshot_scope_mismatch','stage','preview','severity','critical')));
  END IF;

  v_norm := public.comm_hub_normalize_recipient_set(v_to, v_cc, v_bcc);
  v_recipient_hash := v_norm->>'recipient_set_hash';
  IF v_snap.recipient_set_hash IS NOT NULL AND v_snap.recipient_set_hash <> v_recipient_hash THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','preview_snapshot_recipient_mismatch','stage','preview','severity','critical')));
  END IF;

  -- Canonical send decision (dry_run context)
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code', v_module,
    'event_code',  v_event,
    'channel',     v_channel,
    'send_context','dry_run',
    'to_recipients', v_to,
    'cc_recipients', v_cc,
    'bcc_recipients', v_bcc,
    'template_version_id', v_snap.template_version_id,
    'sender_profile_id',   v_snap.sender_profile_id,
    'expected_content_hash', v_snap.content_hash,
    'preview_approval_id', v_appr_id,
    'idempotency_key', v_idem,
    'requested_by', v_actor));

  v_allowed := coalesce((v_decision->>'allowed')::boolean,false);
  v_blockers := coalesce(v_decision->'blockers','[]'::jsonb);
  v_warnings := v_warnings || coalesce(v_decision->'warnings','[]'::jsonb);
  v_orig_decision_id := nullif(v_decision->>'decision_id','')::uuid;
  v_cfg_ver    := nullif(v_decision->>'configuration_version','')::bigint;
  v_recip_ver  := nullif(v_decision->>'recipient_policy_version','')::bigint;
  v_send_ver   := nullif(v_decision->>'send_policy_version','')::bigint;
  v_review_ver := nullif(v_decision->>'review_policy_version','')::bigint;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object(
      'status','BLOCKED','passed',false,
      'idempotent_replay', false,
      'original_decision_id', v_orig_decision_id,
      'preview_snapshot_id', v_snap_id,
      'preview_approval_id', v_appr_id,
      'blockers', v_blockers, 'warnings', v_warnings,
      'started_at', v_started, 'completed_at', now(),
      'provider_call_attempted', false, 'provider_message_id', NULL,
      'message','Dry run blocked by canonical send decision.');
  END IF;

  -- Create request
  INSERT INTO public.communication_request(
    request_no, module_code, event_code, channels, status, payload, context,
    idempotency_key, requested_by,
    original_decision_id, decision_send_context,
    configuration_version, recipient_policy_version, send_policy_version, review_policy_version,
    decision_expires_at, decision_blocker_snapshot,
    template_id, core_template_id)
  VALUES (
    'DRYRUN-' || to_char(v_started at time zone 'utc','YYYYMMDDHH24MISS') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,8),
    v_module, v_event, ARRAY[v_channel], 'dry_run',
    jsonb_build_object('preview_snapshot_id',v_snap_id,'operator_reason',v_reason),
    jsonb_build_object('send_context','dry_run','preview_approval_id',v_appr_id,'idempotency_key',v_idem),
    v_idem, v_actor,
    v_orig_decision_id, 'dry_run',
    v_cfg_ver, v_recip_ver, v_send_ver, v_review_ver,
    nullif(v_decision->>'expires_at','')::timestamptz, v_blockers,
    v_snap.template_id, v_snap.template_id)
  RETURNING id, request_no INTO v_request_id, v_request_no;

  -- Recipients
  INSERT INTO public.communication_recipient(request_id, role, email, name)
  SELECT v_request_id, 'to', r->>'email', r->>'name' FROM jsonb_array_elements(v_to) r;
  INSERT INTO public.communication_recipient(request_id, role, email, name)
  SELECT v_request_id, 'cc', r->>'email', r->>'name' FROM jsonb_array_elements(v_cc) r;
  INSERT INTO public.communication_recipient(request_id, role, email, name)
  SELECT v_request_id, 'bcc', r->>'email', r->>'name' FROM jsonb_array_elements(v_bcc) r;

  -- Single dry-run message with permanent classification
  INSERT INTO public.communication_message(
    request_id, channel, template_version_id, sender_profile_id,
    subject, body_text, body_html, status, test_mode, origin,
    send_context, dry_run_locked)
  VALUES (
    v_request_id, v_channel, v_snap.template_version_id, v_snap.sender_profile_id,
    v_snap.rendered_subject, v_snap.rendered_body_text, v_snap.rendered_body_html,
    'dry_run', true, 'comm-hub-dry-run',
    'dry_run', true)
  RETURNING id INTO v_message_id;

  -- Trace (best-effort)
  BEGIN
    SELECT (r->>'trace_id')::uuid, r->>'trace_no' INTO v_trace_id, v_trace_no
      FROM public.start_comm_hub_trace(jsonb_build_object(
        'module_code', v_module, 'event_code', v_event, 'channel', v_channel,
        'source_action','dry_run', 'correlation_id', v_idem,
        'current_stage','DRY_RUN_STARTED')) r;
  EXCEPTION WHEN OTHERS THEN
    v_warnings := v_warnings || jsonb_build_object('code','trace_unavailable','message',SQLERRM);
  END;

  -- Delivery attempt (dry-run, provider NOT called)
  v_reval_decision_id := v_orig_decision_id; -- best-effort in B.1; dispatcher revalidates in B.2
  INSERT INTO public.communication_delivery_attempt(
    message_id, attempt_no, started_at, finished_at, status,
    original_decision_id, revalidation_decision_id, revalidation_result,
    send_context, attempt_type, provider_call_attempted,
    recipient_set_hash, subject_hash, body_hash, blockers, warnings)
  VALUES (
    v_message_id, 1, v_started, now(), 'success',
    v_orig_decision_id, v_reval_decision_id, 'allowed',
    'dry_run', 'dry_run', false,
    v_recipient_hash, v_snap.rendered_subject_hash, v_snap.rendered_body_hash,
    NULL, v_warnings)
  RETURNING id INTO v_attempt_id;

  -- Operating mode snapshot
  BEGIN
    SELECT operating_mode INTO v_operating_mode FROM public.communication_hub_control_settings WHERE singleton_guard = true;
  EXCEPTION WHEN OTHERS THEN v_operating_mode := NULL; END;

  -- Certification: create ACTIVE and supersede any prior ACTIVE for the same scope
  v_expires_at := now() + make_interval(days => v_expiry_days);
  INSERT INTO public.communication_dry_run_certification(
    certification_no, module_code, event_code, channel,
    preview_snapshot_id, preview_approval_id,
    communication_request_id, communication_message_id, communication_delivery_attempt_id, trace_id,
    recipient_set_hash, template_id, template_version_id, sender_profile_id,
    rendered_subject_hash, rendered_body_hash, content_hash,
    configuration_version, recipient_policy_version, send_policy_version, review_policy_version,
    original_decision_id, dispatcher_revalidation_decision_id,
    result, status, provider_call_attempted,
    certified_by, certified_at, expires_at,
    idempotency_key, audit_metadata)
  VALUES (
    'DRC-' || to_char(now() at time zone 'utc','YYYYMMDDHH24MISS') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,8),
    v_module, v_event, v_channel,
    v_snap_id, v_appr_id,
    v_request_id, v_message_id, v_attempt_id, v_trace_id,
    v_recipient_hash, v_snap.template_id, v_snap.template_version_id, v_snap.sender_profile_id,
    v_snap.rendered_subject_hash, v_snap.rendered_body_hash, v_snap.content_hash,
    v_cfg_ver, v_recip_ver, v_send_ver, v_review_ver,
    v_orig_decision_id, v_reval_decision_id,
    'DRY_RUN_PASSED','ACTIVE', false,
    v_actor, now(), v_expires_at,
    v_idem, jsonb_build_object('operator_reason', v_reason, 'operating_mode', v_operating_mode))
  RETURNING id, certification_no INTO v_cert_id, v_cert_no;

  -- Supersede prior ACTIVE certifications for the same scope
  UPDATE public.communication_dry_run_certification
     SET status = 'SUPERSEDED', superseded_by = v_cert_id
   WHERE id <> v_cert_id
     AND module_code = v_module AND event_code = v_event AND channel = v_channel
     AND status = 'ACTIVE';

  RETURN jsonb_build_object(
    'status','DRY_RUN_PASSED','passed', true,
    'idempotent_replay', false,
    'dry_run_certification_id', v_cert_id,
    'certification_no', v_cert_no,
    'request_id', v_request_id, 'request_number', v_request_no,
    'message_id', v_message_id,
    'delivery_attempt_id', v_attempt_id,
    'trace_id', v_trace_id,
    'original_decision_id', v_orig_decision_id,
    'dispatcher_revalidation_decision_id', v_reval_decision_id,
    'preview_snapshot_id', v_snap_id,
    'preview_approval_id', v_appr_id,
    'blockers', '[]'::jsonb, 'warnings', v_warnings,
    'started_at', v_started, 'completed_at', now(),
    'certification_expires_at', v_expires_at,
    'provider_call_attempted', false,
    'provider_message_id', NULL,
    'final_operating_mode', v_operating_mode,
    'message','Dry test passed — no real email was sent.');
EXCEPTION WHEN unique_violation THEN
  -- Concurrent same-key: reload and return existing
  SELECT * INTO v_existing FROM public.communication_dry_run_certification WHERE idempotency_key = v_idem;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'status', CASE WHEN v_existing.result='DRY_RUN_PASSED' THEN 'DRY_RUN_PASSED' ELSE 'DRY_RUN_FAILED' END,
      'passed', v_existing.result='DRY_RUN_PASSED',
      'idempotent_replay', true,
      'dry_run_certification_id', v_existing.id,
      'request_id', v_existing.communication_request_id,
      'message_id', v_existing.communication_message_id,
      'delivery_attempt_id', v_existing.communication_delivery_attempt_id,
      'trace_id', v_existing.trace_id,
      'certification_expires_at', v_existing.expires_at,
      'provider_call_attempted', v_existing.provider_call_attempted,
      'message','Dry test passed — no real email was sent.');
  END IF;
  RAISE;
END; $function$;
CREATE OR REPLACE FUNCTION public.explorer_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fail_comm_hub_dry_run(p_execution_id uuid, p_state text, p_failure_stage text, p_blockers jsonb DEFAULT '[]'::jsonb, p_warnings jsonb DEFAULT '[]'::jsonb, p_technical_summary text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_exec public.communication_dry_run_execution%ROWTYPE;
BEGIN
  IF p_state NOT IN ('BLOCKED','FAILED') THEN
    RETURN jsonb_build_object('ok', false, 'code','invalid_terminal_state');
  END IF;
  IF p_failure_stage NOT IN ('BEGIN','MARK_DISPATCHING','TARGETED_DISPATCH',
                              'DISPATCH_RESPONSE_VALIDATION','FINALIZE','UNEXPECTED',
                              'SERVICE_IDENTITY','PREVIEW_EVIDENCE','PARTIAL_RECONCILIATION') THEN
    RETURN jsonb_build_object('ok', false, 'code','invalid_failure_stage');
  END IF;

  SELECT * INTO v_exec FROM public.communication_dry_run_execution
    WHERE id = p_execution_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','execution_not_found'); END IF;

  IF v_exec.state IN ('CERTIFIED','BLOCKED','FAILED') THEN
    RETURN jsonb_build_object('ok', true, 'code','already_terminal', 'state', v_exec.state);
  END IF;

  UPDATE public.communication_dry_run_execution
     SET state = p_state,
         failure_stage = p_failure_stage,
         blockers = coalesce(p_blockers,'[]'::jsonb),
         warnings = warnings || coalesce(p_warnings,'[]'::jsonb),
         audit_metadata = audit_metadata
           || jsonb_build_object('failure_summary', coalesce(p_technical_summary, ''))
   WHERE id = p_execution_id;

  RETURN jsonb_build_object('ok', true, 'state', p_state, 'failure_stage', p_failure_stage);
END; $function$;
CREATE OR REPLACE FUNCTION public.fetch_comm_hub_dry_run_certification(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cert_id uuid := nullif(p_payload->>'certification_id','')::uuid;
  v_module text := p_payload->>'module_code';
  v_event text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_row public.communication_dry_run_certification%ROWTYPE;
BEGIN
  IF v_cert_id IS NOT NULL THEN
    SELECT * INTO v_row FROM public.communication_dry_run_certification WHERE id = v_cert_id;
  ELSIF v_module IS NOT NULL AND v_event IS NOT NULL THEN
    SELECT * INTO v_row FROM public.communication_dry_run_certification
      WHERE module_code = v_module AND event_code = v_event AND channel = v_channel AND status = 'ACTIVE'
      ORDER BY certified_at DESC LIMIT 1;
  END IF;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN to_jsonb(v_row) || jsonb_build_object('found', true);
END; $function$;
CREATE OR REPLACE FUNCTION public.finalize_comm_hub_controlled_live(p_execution_id uuid, p_state text, p_final_operating_mode communication_operating_mode, p_cleanup_succeeded boolean, p_cleanup_state text, p_cleanup_error text DEFAULT NULL::text, p_warnings jsonb DEFAULT '[]'::jsonb, p_failure_stage text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update communication_controlled_live_execution
     set state = p_state::communication_controlled_live_state,
         final_operating_mode = p_final_operating_mode,
         cleanup_succeeded = p_cleanup_succeeded,
         cleanup_state = p_cleanup_state,
         cleanup_error = p_cleanup_error,
         failure_stage = coalesce(p_failure_stage, failure_stage),
         warnings = coalesce(warnings,'[]'::jsonb) || coalesce(p_warnings,'[]'::jsonb),
         completed_at = coalesce(completed_at, now()),
         updated_at = now()
   where id = p_execution_id;
  return jsonb_build_object('ok', true);
end $function$;
CREATE OR REPLACE FUNCTION public.finalize_comm_hub_dry_run(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := coalesce(nullif(p_payload->>'requested_by','')::uuid, auth.uid());
  v_exec_id uuid := nullif(p_payload->>'dry_run_execution_id','')::uuid;
  v_exec public.communication_dry_run_execution%ROWTYPE;
  v_msg  public.communication_message%ROWTYPE;
  v_req  public.communication_request%ROWTYPE;
  v_snap public.communication_preview_snapshot%ROWTYPE;
  v_att  public.communication_delivery_attempt%ROWTYPE;
  v_cert public.communication_dry_run_certification%ROWTYPE;
  v_cert_id uuid; v_cert_no text;
  v_expires_at timestamptz; v_expiry_days integer := 7;
  v_operating_mode text;
  v_warnings jsonb := '[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','not_authenticated','stage','auth','severity','critical'))); END IF;
  IF v_exec_id IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_id_required','stage','finalize_input','severity','critical'))); END IF;

  SELECT * INTO v_exec FROM public.communication_dry_run_execution WHERE id = v_exec_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_not_found','stage','finalize_input','severity','critical'))); END IF;
  IF v_exec.requested_by <> v_actor THEN
    RETURN jsonb_build_object('status','BLOCKED','passed',false,
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_operator_mismatch','stage','finalize_input','severity','critical'))); END IF;

  IF v_exec.state = 'CERTIFIED' AND v_exec.certification_id IS NOT NULL THEN
    SELECT * INTO v_cert FROM public.communication_dry_run_certification WHERE id = v_exec.certification_id;
    RETURN jsonb_build_object(
      'status','DRY_RUN_PASSED','passed', true, 'idempotent_replay', true,
      'dry_run_execution_id', v_exec.id, 'dry_run_certification_id', v_cert.id,
      'request_id', v_exec.request_id, 'message_id', v_exec.message_id,
      'delivery_attempt_id', v_exec.delivery_attempt_id, 'trace_id', v_exec.trace_id,
      'original_decision_id', v_exec.original_decision_id,
      'dispatcher_revalidation_decision_id', v_exec.dispatcher_revalidation_decision_id,
      'preview_snapshot_id', v_exec.preview_snapshot_id, 'preview_approval_id', v_exec.preview_approval_id,
      'started_at', v_exec.started_at, 'completed_at', v_exec.completed_at,
      'certification_expires_at', v_cert.expires_at,
      'provider_call_attempted', false, 'provider_message_id', NULL,
      'blockers','[]'::jsonb,'warnings',v_exec.warnings,
      'message','Dry test passed — no real email was sent.');
  END IF;

  IF v_exec.state IN ('BLOCKED','FAILED') THEN
    RETURN jsonb_build_object('status', CASE v_exec.state WHEN 'BLOCKED' THEN 'BLOCKED' ELSE 'DRY_RUN_FAILED' END,
      'passed', false, 'dry_run_execution_id', v_exec.id,
      'failure_stage', v_exec.failure_stage, 'blockers', v_exec.blockers, 'warnings', v_exec.warnings);
  END IF;

  IF v_exec.state NOT IN ('DISPATCHING','PROCESSED') THEN
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,
      'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_not_ready_for_finalize','stage','state_check','state',v_exec.state))); END IF;

  SELECT * INTO v_msg  FROM public.communication_message WHERE id = v_exec.message_id;
  SELECT * INTO v_req  FROM public.communication_request WHERE id = v_exec.request_id;
  SELECT * INTO v_snap FROM public.communication_preview_snapshot WHERE id = v_exec.preview_snapshot_id;

  IF v_msg.dry_run_locked IS DISTINCT FROM true OR v_msg.send_context <> 'dry_run' THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='message_classification_invalid' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','message_classification_invalid','stage','finalize_evidence'))); END IF;

  SELECT * INTO v_att FROM public.communication_delivery_attempt
   WHERE message_id = v_msg.id AND attempt_type = 'dry_run'
   ORDER BY attempt_no DESC LIMIT 1;
  IF NOT FOUND THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='attempt_missing' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','attempt_missing','stage','finalize_evidence','severity','critical'))); END IF;

  IF v_att.provider_call_attempted IS DISTINCT FROM false THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='provider_call_attempted_true' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','provider_call_attempted_true','stage','finalize_evidence','severity','critical'))); END IF;
  IF v_att.provider_message_id IS NOT NULL THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='provider_message_id_present' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','provider_message_id_present','stage','finalize_evidence','severity','critical'))); END IF;
  IF coalesce(v_att.provider_response#>>'{response,result}','') <> 'DRY_RUN_PROCESSED' THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='attempt_result_not_processed' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','attempt_result_not_processed','stage','finalize_evidence','severity','critical'))); END IF;
  IF v_att.recipient_set_hash IS DISTINCT FROM v_exec.recipient_set_hash THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='recipient_hash_mismatch' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','recipient_hash_mismatch','stage','finalize_evidence','severity','critical'))); END IF;
  IF v_att.revalidation_decision_id IS NULL THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='revalidation_decision_missing' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','revalidation_decision_missing','stage','finalize_evidence','severity','critical'))); END IF;
  IF v_att.original_decision_id IS NULL THEN
    UPDATE public.communication_dry_run_execution SET state='FAILED', failure_stage='original_decision_missing' WHERE id = v_exec.id;
    RETURN jsonb_build_object('status','DRY_RUN_FAILED','passed',false,'dry_run_execution_id', v_exec.id,
      'blockers', jsonb_build_array(jsonb_build_object('code','original_decision_missing','stage','finalize_evidence','severity','critical'))); END IF;

  IF NOT EXISTS (SELECT 1 FROM public.communication_event_log
                  WHERE message_id = v_msg.id AND payload->>'stage'='DRY_RUN_PROCESSED') THEN
    v_warnings := v_warnings || jsonb_build_object('code','dry_run_event_log_missing');
  END IF;

  UPDATE public.communication_dry_run_execution
     SET state='PROCESSED', delivery_attempt_id = v_att.id,
         dispatcher_revalidation_decision_id = v_att.revalidation_decision_id, warnings = v_warnings
   WHERE id = v_exec.id AND state = 'DISPATCHING';

  BEGIN
    SELECT operating_mode INTO v_operating_mode FROM public.communication_hub_control_settings WHERE singleton_guard = 'primary';
  EXCEPTION WHEN OTHERS THEN v_operating_mode := NULL; END;

  v_expires_at := now() + make_interval(days => v_expiry_days);

  INSERT INTO public.communication_dry_run_certification(
    certification_no, module_code, event_code, channel,
    preview_snapshot_id, preview_approval_id,
    communication_request_id, communication_message_id, communication_delivery_attempt_id, trace_id,
    recipient_set_hash, template_id, template_version_id, sender_profile_id,
    rendered_subject_hash, rendered_body_hash, content_hash,
    configuration_version, recipient_policy_version, send_policy_version, review_policy_version,
    original_decision_id, dispatcher_revalidation_decision_id,
    result, status, provider_call_attempted,
    certified_by, certified_at, expires_at,
    idempotency_key, audit_metadata)
  VALUES (
    'DRC-' || to_char(now() at time zone 'utc','YYYYMMDDHH24MISS') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,8),
    v_exec.module_code, v_exec.event_code, v_exec.channel,
    v_exec.preview_snapshot_id, v_exec.preview_approval_id,
    v_exec.request_id, v_exec.message_id, v_att.id, v_exec.trace_id,
    v_exec.recipient_set_hash, v_snap.template_id, v_snap.template_version_id, v_snap.sender_profile_id,
    v_att.subject_hash, v_att.body_hash, v_snap.content_hash,
    v_req.configuration_version, v_req.recipient_policy_version, v_req.send_policy_version, v_req.review_policy_version,
    v_att.original_decision_id, v_att.revalidation_decision_id,
    'DRY_RUN_PASSED','ACTIVE', false,
    v_actor, now(), v_expires_at,
    v_exec.idempotency_key || '::' || v_exec.scope_hash,
    jsonb_build_object('operating_mode', v_operating_mode, 'dry_run_execution_id', v_exec.id))
  RETURNING id, certification_no INTO v_cert_id, v_cert_no;

  UPDATE public.communication_dry_run_certification
     SET status = 'SUPERSEDED', superseded_by = v_cert_id
   WHERE id <> v_cert_id
     AND module_code = v_exec.module_code AND event_code = v_exec.event_code AND channel = v_exec.channel
     AND recipient_set_hash = v_exec.recipient_set_hash
     AND status = 'ACTIVE' AND result = 'DRY_RUN_PASSED';

  UPDATE public.communication_dry_run_execution SET state='CERTIFIED', certification_id = v_cert_id WHERE id = v_exec.id;

  RETURN jsonb_build_object(
    'status','DRY_RUN_PASSED','passed', true, 'idempotent_replay', false,
    'dry_run_execution_id', v_exec.id, 'dry_run_certification_id', v_cert_id, 'certification_no', v_cert_no,
    'request_id', v_exec.request_id, 'message_id', v_exec.message_id,
    'delivery_attempt_id', v_att.id, 'trace_id', v_exec.trace_id,
    'original_decision_id', v_att.original_decision_id,
    'dispatcher_revalidation_decision_id', v_att.revalidation_decision_id,
    'preview_snapshot_id', v_exec.preview_snapshot_id, 'preview_approval_id', v_exec.preview_approval_id,
    'blockers','[]'::jsonb, 'warnings', v_warnings,
    'started_at', v_exec.started_at, 'completed_at', now(),
    'certification_expires_at', v_expires_at,
    'provider_call_attempted', false, 'provider_message_id', NULL,
    'final_operating_mode', v_operating_mode,
    'message','Dry test passed — no real email was sent.');
END; $function$;
CREATE OR REPLACE FUNCTION public.finalize_comm_hub_manual_production_observation(p_message_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_msg record; v_req record; v_att record; v_ec record;
  v_settings record; v_provider record;
  v_trace_id uuid; v_recipient text;
  v_existing_row record; v_id uuid;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF p_message_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'phase','FAILED','blockers',
      jsonb_build_array(jsonb_build_object('code','message_id_required')));
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key)=0 THEN
    RETURN jsonb_build_object('ok',false,'phase','FAILED','blockers',
      jsonb_build_array(jsonb_build_object('code','idempotency_key_required')));
  END IF;

  SELECT * INTO v_existing_row FROM public.communication_manual_production_observation
    WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true, 'idempotent', true,
      'observation_id', v_existing_row.id,
      'message_id', v_existing_row.message_id,
      'phase', CASE
        WHEN v_existing_row.inbox_confirmation_status = 'CONFIRMED' THEN 'CONFIRMED'
        WHEN v_existing_row.inbox_confirmation_status = 'NOT_RECEIVED' THEN 'NOT_RECEIVED'
        WHEN v_existing_row.status IN ('DISPATCHED','CONFIRMED') THEN 'AWAITING_INBOX_CONFIRMATION'
        ELSE v_existing_row.status
      END,
      'status', v_existing_row.status,
      'inbox_confirmation_status', v_existing_row.inbox_confirmation_status);
  END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id = p_message_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'phase','FAILED','blockers',
      jsonb_build_array(jsonb_build_object('code','message_not_found')));
  END IF;

  IF coalesce(v_msg.send_context,'') <> 'manual_production' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','send_context_not_manual_production','detail',v_msg.send_context));
  END IF;
  IF v_msg.test_mode = true THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','message_is_test_mode'));
  END IF;
  IF v_msg.status NOT IN ('sent','delivered') THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','message_status_not_sent_or_delivered','detail',v_msg.status));
  END IF;

  SELECT * INTO v_req FROM public.communication_request WHERE id = v_msg.request_id;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','request_not_found'));
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
    WHERE module_code = coalesce(v_req.module_code, v_msg.module_code)
      AND event_code  = coalesce(v_req.event_code,  v_msg.event_code)
      AND channel     = v_msg.channel;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','event_certification_missing'));
  ELSIF v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','event_not_manually_certified','detail',v_ec.status));
  ELSIF v_msg.created_at < v_ec.approved_at THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','message_predates_certification'));
  END IF;

  SELECT * INTO v_att FROM public.communication_delivery_attempt
    WHERE message_id = v_msg.id AND status IN ('success','delivered','sent')
    ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','no_successful_delivery_attempt'));
  ELSE
    IF v_att.provider_message_id IS NULL OR length(v_att.provider_message_id)=0 THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','provider_message_id_missing'));
    END IF;
    IF v_att.provider_id IS NOT NULL THEN
      SELECT * INTO v_provider FROM public.notification_providers WHERE id = v_att.provider_id;
      IF FOUND AND lower(coalesce(v_provider.mode,'')) IN ('stub','dry_run','dryrun','test') THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','provider_is_stub_or_dry_run','detail',v_provider.mode));
      END IF;
    END IF;
  END IF;

  SELECT trace_id INTO v_trace_id FROM public.communication_hub_trace_link
    WHERE message_id = v_msg.id LIMIT 1;
  IF v_trace_id IS NULL THEN v_trace_id := v_msg.trace_id; END IF;
  IF v_trace_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','trace_missing'));
  END IF;

  SELECT lower(email) INTO v_recipient FROM public.communication_message_recipient
    WHERE message_id = v_msg.id AND lower(coalesce(role,'to'))='to' LIMIT 1;
  IF v_recipient IS NULL THEN v_recipient := lower(coalesce(v_msg.recipient_email,'')); END IF;
  IF v_recipient IS NULL OR length(v_recipient)=0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','recipient_missing'));
  END IF;

  IF jsonb_array_length(v_blockers) > 0 THEN
    RETURN jsonb_build_object('ok',false,'phase','AWAITING_PROVIDER','blockers',v_blockers);
  END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';

  INSERT INTO public.communication_manual_production_observation
    (module_code,event_code,channel,event_certification_id,
     request_id,message_id,delivery_attempt_id,trace_id,
     provider_id,provider_name,provider_message_id,
     provider_call_attempted,provider_outcome,
     recipient_email,recipient_set_hash,configuration_version,
     sender_profile_id,template_version_id,idempotency_key,
     status,inbox_confirmation_status,dispatched_by)
  VALUES
    (v_ec.module_code, v_ec.event_code, v_ec.channel, v_ec.id,
     v_req.id, v_msg.id, v_att.id, v_trace_id,
     v_att.provider_id, coalesce(v_provider.name, v_att.provider_name), v_att.provider_message_id,
     true, v_att.status,
     v_recipient, v_msg.recipient_set_hash, v_settings.configuration_version,
     v_msg.sender_profile_id, v_msg.template_version_id, p_idempotency_key,
     'DISPATCHED', NULL, v_msg.created_by)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'ok', true,
    'phase','AWAITING_INBOX_CONFIRMATION',
    'observation_id', v_id,
    'status','DISPATCHED',
    'inbox_confirmation_status', NULL,
    'request_id', v_req.id, 'message_id', v_msg.id,
    'delivery_attempt_id', v_att.id, 'trace_id', v_trace_id,
    'provider_id', v_att.provider_id,
    'provider_name', coalesce(v_provider.name, v_att.provider_name),
    'provider_message_id', v_att.provider_message_id,
    'provider_call_attempted', true, 'provider_outcome', v_att.status,
    'message_status', v_msg.status, 'attempt_status', v_att.status,
    'recipient', v_recipient, 'event_certification_id', v_ec.id
  );
END $function$;
CREATE OR REPLACE FUNCTION public.finalize_comm_hub_one_real_email(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc jsonb;
  v_exec_id uuid := (p_payload->>'execution_id')::uuid;
  v_exec public.communication_controlled_live_execution%ROWTYPE;
  v_grant public.communication_controlled_live_grant%ROWTYPE;
  v_msg_status text;
  v_attempt record;
  v_attempt_count int := 0;
  v_provider_outcome text;
  v_cert_status text;
  v_derived_provider_status text;
  v_existing_cert record;
  v_cert_id uuid;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-send-one-real-email','FINALIZE_ONE_REAL_EMAIL');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'blockers', v_svc->'blockers');
  END IF;

  IF v_exec_id IS NULL THEN RAISE EXCEPTION 'execution_id_required'; END IF;

  SELECT * INTO v_exec FROM public.communication_controlled_live_execution WHERE id=v_exec_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'execution_not_found'; END IF;

  IF v_exec.send_context <> 'REAL_EMAIL' THEN RAISE EXCEPTION 'execution_not_real_email'; END IF;
  IF coalesce(v_exec.provider_mode,'') <> 'real' THEN RAISE EXCEPTION 'execution_not_provider_real'; END IF;
  IF v_exec.real_email_authorised IS NOT TRUE THEN RAISE EXCEPTION 'execution_not_real_email_authorised'; END IF;
  IF v_exec.provider_call_attempted IS NOT TRUE THEN RAISE EXCEPTION 'provider_not_invoked'; END IF;
  IF v_exec.trace_id IS NULL THEN RAISE EXCEPTION 'execution_trace_missing'; END IF;
  IF v_exec.message_id IS NULL THEN RAISE EXCEPTION 'execution_message_missing'; END IF;

  -- Idempotency: return existing certification untouched.
  SELECT * INTO v_existing_cert
    FROM public.communication_controlled_live_certification
   WHERE execution_id = v_exec_id AND certification_kind = 'ONE_REAL_EMAIL';
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true, 'idempotent_replay', true,
      'certification_id', v_existing_cert.id,
      'certification_kind', 'ONE_REAL_EMAIL',
      'certification_status', v_existing_cert.status,
      'provider_outcome', v_existing_cert.provider_outcome,
      'provider_status', v_existing_cert.provider_status,
      'provider_mode', 'real', 'real_email_authorised', true,
      'provider_call_attempted', true,
      'retry_safe', false,
      'automatic_retry_allowed', false);
  END IF;

  SELECT * INTO v_grant FROM public.communication_controlled_live_grant
   WHERE execution_id = v_exec_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'grant_not_found'; END IF;
  IF v_grant.send_context <> 'REAL_EMAIL' THEN RAISE EXCEPTION 'grant_not_real_email'; END IF;
  IF v_grant.status NOT IN ('CONSUMED') THEN
    RAISE EXCEPTION 'grant_not_consumed' USING DETAIL = 'grant_status=' || v_grant.status;
  END IF;

  SELECT status::text INTO v_msg_status FROM public.communication_message WHERE id = v_exec.message_id;
  IF v_msg_status IS NULL THEN RAISE EXCEPTION 'message_not_found'; END IF;
  IF v_msg_status NOT IN ('sent','failed') THEN
    RAISE EXCEPTION 'message_not_terminal' USING DETAIL = 'status=' || v_msg_status;
  END IF;

  SELECT count(*) INTO v_attempt_count FROM public.communication_delivery_attempt
   WHERE message_id = v_exec.message_id;
  IF v_attempt_count <> 1 THEN
    RAISE EXCEPTION 'delivery_attempt_count_invalid' USING DETAIL = 'count=' || v_attempt_count;
  END IF;
  SELECT * INTO v_attempt FROM public.communication_delivery_attempt
   WHERE message_id = v_exec.message_id LIMIT 1;
  IF v_attempt.provider_id IS NULL THEN RAISE EXCEPTION 'attempt_provider_missing'; END IF;
  IF v_attempt.provider_call_attempted IS NOT TRUE THEN
    RAISE EXCEPTION 'attempt_provider_call_not_attempted';
  END IF;

  v_derived_provider_status := coalesce(v_attempt.status::text, '');
  IF v_derived_provider_status = 'success' THEN
    IF v_attempt.provider_message_id IS NULL AND v_exec.provider_message_id IS NULL THEN
      RAISE EXCEPTION 'provider_message_id_missing';
    END IF;
    v_provider_outcome := 'PROVIDER_ACCEPTED';
    v_cert_status := 'PROVIDER_ACCEPTED';
  ELSIF v_derived_provider_status = 'delivered' THEN
    v_provider_outcome := 'DELIVERED';
    v_cert_status := 'DELIVERY_CONFIRMED';
  ELSIF v_derived_provider_status IN ('pending') THEN
    v_provider_outcome := 'DELIVERY_PENDING';
    v_cert_status := 'PROVIDER_ACCEPTED';
  ELSIF v_derived_provider_status IN ('failure','timeout','throttled','skipped') THEN
    v_provider_outcome := 'PROVIDER_REJECTED';
    v_cert_status := 'PROVIDER_REJECTED';
  ELSE
    RAISE EXCEPTION 'attempt_outcome_not_certifiable' USING DETAIL = 'status=' || v_derived_provider_status;
  END IF;

  INSERT INTO public.communication_controlled_live_certification(
    execution_id, module_code, event_code, channel, recipient_set_hash,
    preview_snapshot_id, preview_approval_id, dry_run_certification_id,
    request_id, message_id, delivery_attempt_id, trace_id,
    provider_name, provider_message_id, provider_outcome, provider_status,
    status, recipient_policy_version, configuration_version,
    operating_mode_prior, operating_mode_final, cleanup_succeeded,
    certified_at, certified_by, certification_kind)
  VALUES (
    v_exec_id, v_exec.module_code, v_exec.event_code, v_exec.channel,
    v_exec.recipient_set_hash,
    v_exec.preview_snapshot_id, v_exec.preview_approval_id, v_exec.dry_run_certification_id,
    v_exec.request_id, v_exec.message_id, v_attempt.id, v_exec.trace_id,
    v_exec.provider_name,
    coalesce(v_attempt.provider_message_id, v_exec.provider_message_id),
    v_provider_outcome,
    coalesce(v_exec.provider_status, v_derived_provider_status),
    v_cert_status,
    v_exec.recipient_policy_version::integer, v_exec.configuration_version::integer,
    v_exec.prior_operating_mode::text, v_exec.final_operating_mode::text,
    coalesce(v_exec.cleanup_succeeded, true),
    now(), v_exec.requested_by, 'ONE_REAL_EMAIL')
  RETURNING id INTO v_cert_id;

  UPDATE public.communication_controlled_live_execution
     SET state = CASE v_provider_outcome
                   WHEN 'DELIVERED' THEN 'DELIVERED'::communication_controlled_live_state
                   WHEN 'DELIVERY_PENDING' THEN 'DELIVERY_PENDING'::communication_controlled_live_state
                   WHEN 'PROVIDER_REJECTED' THEN 'PROVIDER_REJECTED'::communication_controlled_live_state
                   ELSE 'PROVIDER_ACCEPTED'::communication_controlled_live_state
                 END,
         delivery_attempt_id = coalesce(delivery_attempt_id, v_attempt.id),
         completed_at = now(), updated_at = now()
   WHERE id = v_exec_id;

  RETURN jsonb_build_object(
    'ok', true, 'idempotent_replay', false,
    'certification_id', v_cert_id,
    'certification_kind', 'ONE_REAL_EMAIL',
    'certification_status', v_cert_status,
    'provider_outcome', v_provider_outcome,
    'provider_status', coalesce(v_exec.provider_status, v_derived_provider_status),
    'provider_mode', 'real', 'real_email_authorised', true,
    'provider_call_attempted', true,
    'retry_safe', false,
    'automatic_retry_allowed', false);
END $function$;
CREATE OR REPLACE FUNCTION public.find_eligible_approver(_workflow_instance_id uuid, _step_id uuid, _exclude_users uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(user_id uuid, user_name text, has_data_access boolean, access_details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_step workflow_steps;
  v_workflow workflow_instances;
  v_definition workflow_definitions;
BEGIN
  -- Get the step configuration
  SELECT * INTO v_step FROM workflow_steps WHERE id = _step_id;
  SELECT * INTO v_workflow FROM workflow_instances WHERE id = _workflow_instance_id;
  SELECT * INTO v_definition FROM workflow_definitions WHERE id = v_workflow.workflow_id;
  
  -- Find users matching the step assignment criteria
  RETURN QUERY
  WITH potential_approvers AS (
    SELECT DISTINCT p.id as uid, p.full_name as uname
    FROM profiles p
    LEFT JOIN user_roles ur ON ur.user_id = p.id
    LEFT JOIN roles r ON r.id = ur.role_id
    WHERE p.is_active = true
    AND NOT (p.id = ANY(_exclude_users))
    AND (
      -- Match by role
      (v_step.assigned_role IS NOT NULL AND r.name = v_step.assigned_role)
      -- Match by designation
      OR (v_step.assigned_designation IS NOT NULL AND p.designation_id IN (
        SELECT d.id FROM designations d WHERE d.name = v_step.assigned_designation
      ))
    )
  )
  SELECT 
    pa.uid as user_id,
    pa.uname as user_name,
    COALESCE((check_workflow_task_access(pa.uid, _workflow_instance_id, 'edit')->>'allowed')::boolean, false) as has_data_access,
    check_workflow_task_access(pa.uid, _workflow_instance_id, 'edit') as access_details
  FROM potential_approvers pa
  WHERE COALESCE((check_workflow_task_access(pa.uid, _workflow_instance_id, 'edit')->>'allowed')::boolean, false) = true
  ORDER BY pa.uname;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_audit_ip_last_self_emp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
