CREATE OR REPLACE FUNCTION public.fn_ce_audit_run_reminder_escalation()
 RETURNS TABLE(reminders_created integer, escalations_created integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reminders int := 0;
  v_escalations int := 0;
  v_reminder_window_hours int := 24;     -- escalate if no response 24h after reminder
  v_reminder_template uuid;
  v_escalation_template uuid;
  r record;
BEGIN
  SELECT id INTO v_reminder_template
  FROM public.ce_audit_communication_templates
  WHERE template_code = 'AUD_DUE_REM' AND is_active = true LIMIT 1;

  SELECT id INTO v_escalation_template
  FROM public.ce_audit_communication_templates
  WHERE template_code = 'AUD_ESC' AND is_active = true LIMIT 1;

  -- ---- Reminders (level 0 -> 1) ----------------------------------------
  IF v_reminder_template IS NOT NULL THEN
    FOR r IN
      SELECT c.*
      FROM public.ce_audit_communications c
      WHERE c.status IN ('sent','partial')
        AND c.response_due_at IS NOT NULL
        AND c.response_due_at < now()
        AND c.acknowledged_at IS NULL
        AND c.responded_at IS NULL
        AND COALESCE(c.escalation_level, 0) = 0
        -- don't re-reminder a reminder
        AND c.comm_type NOT IN ('due_date_reminder','escalation_notice')
        -- skip if a reminder for this visit+source already exists in last 24h
        AND NOT EXISTS (
          SELECT 1 FROM public.ce_audit_communications x
          WHERE x.inspection_id = c.inspection_id
            AND x.comm_type = 'due_date_reminder'
            AND x.created_at > now() - interval '24 hours'
        )
    LOOP
      INSERT INTO public.ce_audit_communications
        (inspection_id, visit_id, case_id, employer_id, template_id,
         comm_type, status, stage_key, trigger_type, created_by,
         response_due_at, escalation_level)
      VALUES
        (r.inspection_id, r.visit_id, r.case_id, r.employer_id, v_reminder_template,
         'due_date_reminder', 'draft', 'reminder_stage', 'automatic',
         'SYSTEM_REMINDER',
         now() + (v_reminder_window_hours || ' hours')::interval,
         1);

      UPDATE public.ce_audit_communications
      SET escalation_level = 1
      WHERE id = r.id;

      v_reminders := v_reminders + 1;
    END LOOP;
  END IF;

  -- ---- Escalations (level 1 -> 2) --------------------------------------
  IF v_escalation_template IS NOT NULL THEN
    FOR r IN
      SELECT c.*
      FROM public.ce_audit_communications c
      WHERE c.status IN ('sent','partial')
        AND c.acknowledged_at IS NULL
        AND c.responded_at IS NULL
        AND COALESCE(c.escalation_level, 0) = 1
        AND c.comm_type NOT IN ('escalation_notice')
        -- the reminder itself must be overdue (response_due_at + window passed)
        AND (c.response_due_at IS NULL OR c.response_due_at < now() - (v_reminder_window_hours || ' hours')::interval)
        AND NOT EXISTS (
          SELECT 1 FROM public.ce_audit_communications x
          WHERE x.inspection_id = c.inspection_id
            AND x.comm_type = 'escalation_notice'
            AND x.created_at > now() - interval '48 hours'
        )
    LOOP
      INSERT INTO public.ce_audit_communications
        (inspection_id, visit_id, case_id, employer_id, template_id,
         comm_type, status, stage_key, trigger_type, created_by,
         response_due_at, escalation_level)
      VALUES
        (r.inspection_id, r.visit_id, r.case_id, r.employer_id, v_escalation_template,
         'escalation_notice', 'draft', 'escalation_stage', 'automatic',
         'SYSTEM_ESCALATION',
         now() + interval '48 hours',
         2);

      UPDATE public.ce_audit_communications
      SET escalation_level = 2
      WHERE id = r.id;

      v_escalations := v_escalations + 1;
    END LOOP;
  END IF;

  RETURN QUERY SELECT v_reminders, v_escalations;
END$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_auto_create_follow_up()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action_type VARCHAR(50);
  v_description TEXT;
  v_source VARCHAR(30);
  v_priority VARCHAR(20);
BEGIN
  -- Determine action type based on violation status
  IF NEW.status = 'OPEN' THEN
    v_action_type := 'VISIT';
    v_description := 'Initial operational follow-up for violation ' || NEW.violation_number;
    v_source := 'AUTO_OPEN';
    v_priority := CASE
      WHEN NEW.priority IN ('Critical','High') THEN 'URGENT'
      WHEN NEW.priority = 'Medium' THEN 'HIGH'
      ELSE 'NORMAL'
    END;
  ELSIF NEW.status = 'UNDER_REVIEW' THEN
    v_action_type := 'REVIEW';
    v_description := 'Review follow-up for violation ' || NEW.violation_number;
    v_source := 'AUTO_REVIEW';
    v_priority := 'HIGH';
  ELSE
    RETURN NEW;
  END IF;

  -- Dedupe check: skip if active follow-up already exists
  IF NOT EXISTS (
    SELECT 1 FROM public.ce_follow_up_actions
    WHERE violation_id = NEW.id
      AND action_type = v_action_type
      AND is_deleted = false
      AND status NOT IN ('COMPLETED', 'CANCELLED')
  ) THEN
    INSERT INTO public.ce_follow_up_actions (
      violation_id, employer_id, employer_name,
      action_type, description, priority, status,
      assigned_to_user_id, assigned_to_name, assigned_queue_id,
      due_date, source, created_by
    ) VALUES (
      NEW.id, NEW.employer_id, NEW.employer_name,
      v_action_type, v_description, v_priority, 'PLANNED',
      NEW.assigned_to_user_id, NEW.assigned_to_name, NEW.assigned_queue_id,
      COALESCE(NEW.due_date::date, (now() + interval '7 days')::date),
      v_source, 'SYSTEM-AUTO'
    );
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_backfill_unassigned_violations()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row RECORD;
  v_result JSONB;
  v_total INT := 0;
  v_assigned_queue INT := 0;
  v_assigned_officer INT := 0;
  v_failed INT := 0;
BEGIN
  FOR v_row IN
    SELECT id FROM ce_violations
    WHERE is_deleted = false
      AND assigned_queue_id IS NULL
      AND status IN ('OPEN', 'UNDER_REVIEW', 'ESCALATED')
    ORDER BY created_at
  LOOP
    v_total := v_total + 1;
    v_result := fn_ce_route_violation(v_row.id);
    
    IF (v_result->>'ok')::boolean THEN
      IF v_result->>'inspector_id' IS NOT NULL THEN
        v_assigned_officer := v_assigned_officer + 1;
      ELSE
        v_assigned_queue := v_assigned_queue + 1;
      END IF;
    ELSE
      v_failed := v_failed + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'total_processed', v_total,
    'assigned_to_officer', v_assigned_officer,
    'assigned_to_queue_only', v_assigned_queue,
    'failed', v_failed
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_case_status_change_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO ce_case_history (case_id, action, from_status, to_status, notes, performed_by)
    VALUES (NEW.id, 'STATUS_CHANGED', OLD.status, NEW.status,
            'Status changed from ' || COALESCE(OLD.status, 'NULL') || ' to ' || NEW.status,
            COALESCE(NEW.updated_by, 'SYSTEM'));
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_compare_plan_versions(p_base_id uuid, p_revised_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_added jsonb;
  v_removed jsonb;
  v_changed jsonb;
  v_coverage jsonb;
  v_summary jsonb;
BEGIN
  -- Items uniquely in revised (added)
  WITH base AS (SELECT * FROM public.ce_weekly_plan_items WHERE plan_id = p_base_id),
       rev  AS (SELECT * FROM public.ce_weekly_plan_items WHERE plan_id = p_revised_id)
  SELECT COALESCE(jsonb_agg(to_jsonb(r) - 'plan_id'), '[]'::jsonb)
    INTO v_added
    FROM rev r
   WHERE r.source_item_id IS NULL
      OR r.source_item_id NOT IN (SELECT id FROM base);

  -- Items in base but not preserved in revised (removed)
  WITH base AS (SELECT * FROM public.ce_weekly_plan_items WHERE plan_id = p_base_id),
       rev  AS (SELECT * FROM public.ce_weekly_plan_items WHERE plan_id = p_revised_id)
  SELECT COALESCE(jsonb_agg(to_jsonb(b) - 'plan_id'), '[]'::jsonb)
    INTO v_removed
    FROM base b
   WHERE b.id NOT IN (SELECT source_item_id FROM rev WHERE source_item_id IS NOT NULL);

  -- Changed items (preserved but with modifications)
  WITH base AS (SELECT * FROM public.ce_weekly_plan_items WHERE plan_id = p_base_id),
       rev  AS (SELECT * FROM public.ce_weekly_plan_items WHERE plan_id = p_revised_id)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id',            r.id,
      'source_item_id',r.source_item_id,
      'employer_name', r.employer_name,
      'changes', jsonb_strip_nulls(jsonb_build_object(
        'day_of_week',   CASE WHEN r.day_of_week IS DISTINCT FROM b.day_of_week
                              THEN jsonb_build_object('old', b.day_of_week, 'new', r.day_of_week) END,
        'scheduled_date',CASE WHEN r.scheduled_date IS DISTINCT FROM b.scheduled_date
                              THEN jsonb_build_object('old', b.scheduled_date, 'new', r.scheduled_date) END,
        'start_time',    CASE WHEN r.scheduled_start_time IS DISTINCT FROM b.scheduled_start_time
                              THEN jsonb_build_object('old', b.scheduled_start_time, 'new', r.scheduled_start_time) END,
        'end_time',      CASE WHEN r.scheduled_end_time IS DISTINCT FROM b.scheduled_end_time
                              THEN jsonb_build_object('old', b.scheduled_end_time, 'new', r.scheduled_end_time) END,
        'priority',      CASE WHEN r.priority IS DISTINCT FROM b.priority
                              THEN jsonb_build_object('old', b.priority, 'new', r.priority) END,
        'purpose',       CASE WHEN COALESCE(r.purpose,'') IS DISTINCT FROM COALESCE(b.purpose,'')
                              THEN jsonb_build_object('old', b.purpose, 'new', r.purpose) END,
        'is_mandatory',  CASE WHEN r.is_mandatory IS DISTINCT FROM b.is_mandatory
                              THEN jsonb_build_object('old', b.is_mandatory, 'new', r.is_mandatory) END,
        'item_type',     CASE WHEN r.item_type IS DISTINCT FROM b.item_type
                              THEN jsonb_build_object('old', b.item_type, 'new', r.item_type) END
      ))
  )), '[]'::jsonb)
    INTO v_changed
    FROM rev r
    JOIN base b ON b.id = r.source_item_id
   WHERE r.day_of_week         IS DISTINCT FROM b.day_of_week
      OR r.scheduled_date      IS DISTINCT FROM b.scheduled_date
      OR r.scheduled_start_time IS DISTINCT FROM b.scheduled_start_time
      OR r.scheduled_end_time   IS DISTINCT FROM b.scheduled_end_time
      OR r.priority            IS DISTINCT FROM b.priority
      OR COALESCE(r.purpose,'') IS DISTINCT FROM COALESCE(b.purpose,'')
      OR r.is_mandatory        IS DISTINCT FROM b.is_mandatory
      OR r.item_type           IS DISTINCT FROM b.item_type;

  -- Coverage impact
  WITH bcounts AS (
    SELECT
      COUNT(*)                                              AS total,
      COUNT(*) FILTER (WHERE is_mandatory)                  AS mandatory,
      COUNT(*) FILTER (WHERE priority IN ('CRITICAL','HIGH')) AS high_risk,
      COUNT(DISTINCT territory)                              AS zones
    FROM public.ce_weekly_plan_items WHERE plan_id = p_base_id
  ),
  rcounts AS (
    SELECT
      COUNT(*)                                              AS total,
      COUNT(*) FILTER (WHERE is_mandatory)                  AS mandatory,
      COUNT(*) FILTER (WHERE priority IN ('CRITICAL','HIGH')) AS high_risk,
      COUNT(DISTINCT territory)                              AS zones
    FROM public.ce_weekly_plan_items WHERE plan_id = p_revised_id
  )
  SELECT jsonb_build_object(
    'workload',    jsonb_build_object('old', b.total,     'new', r.total),
    'mandatory',   jsonb_build_object('old', b.mandatory, 'new', r.mandatory),
    'high_risk',   jsonb_build_object('old', b.high_risk, 'new', r.high_risk),
    'zone_spread', jsonb_build_object('old', b.zones,     'new', r.zones)
  ) INTO v_coverage FROM bcounts b, rcounts r;

  v_summary := jsonb_build_object(
    'added_count',    jsonb_array_length(v_added),
    'removed_count',  jsonb_array_length(v_removed),
    'changed_count',  jsonb_array_length(v_changed)
  );

  RETURN jsonb_build_object(
    'summary',  v_summary,
    'added',    v_added,
    'removed',  v_removed,
    'changed',  v_changed,
    'coverage', v_coverage
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_consolidate_violation_to_case(p_violation_id uuid, p_performed_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_violation RECORD;
  v_family_id UUID;
  v_family_code VARCHAR;
  v_case_id UUID;
  v_case_number VARCHAR;
  v_is_new_case BOOLEAN := false;
  v_lock_key BIGINT;
  v_result JSONB;
  v_reopen_window INTEGER;
  v_reopenable_case_id UUID;
BEGIN
  -- 1. Fetch the violation
  SELECT v.*, vt.category
  INTO v_violation
  FROM ce_violations v
  LEFT JOIN ce_violation_types vt ON vt.id = v.violation_type_id
  WHERE v.id = p_violation_id;

  IF v_violation.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Violation not found');
  END IF;

  IF v_violation.case_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'case_id', v_violation.case_id, 'action', 'ALREADY_LINKED');
  END IF;

  -- 2. Resolve case family
  SELECT family_id, family_code INTO v_family_id, v_family_code
  FROM fn_ce_resolve_case_family(v_violation.violation_type_id);

  v_family_code := COALESCE(v_family_code, 'GENERAL');

  -- 3. Advisory lock on employer+family to prevent race conditions
  v_lock_key := abs(hashtext(COALESCE(v_violation.employer_id, '') || '|' || v_family_code));
  PERFORM pg_advisory_xact_lock(v_lock_key);

  -- 4. Search for existing active case
  SELECT id INTO v_case_id
  FROM ce_cases
  WHERE employer_id = v_violation.employer_id
    AND case_family = v_family_code
    AND status NOT IN ('CLOSED', 'RESOLVED', 'MERGED', 'CANCELLED')
    AND (is_deleted IS NULL OR is_deleted = false)
  ORDER BY opened_date DESC
  LIMIT 1;

  -- 5. If no active case, check for reopenable closed case
  IF v_case_id IS NULL THEN
    SELECT COALESCE(cf.reopen_window_days, 30) INTO v_reopen_window
    FROM ce_case_families cf WHERE cf.code = v_family_code;

    v_reopen_window := COALESCE(v_reopen_window, 30);

    SELECT id INTO v_reopenable_case_id
    FROM ce_cases
    WHERE employer_id = v_violation.employer_id
      AND case_family = v_family_code
      AND status IN ('CLOSED', 'RESOLVED')
      AND closed_date IS NOT NULL
      AND closed_date >= (CURRENT_DATE - v_reopen_window)
      AND (is_deleted IS NULL OR is_deleted = false)
    ORDER BY closed_date DESC
    LIMIT 1;

    IF v_reopenable_case_id IS NOT NULL THEN
      -- Reopen the case
      UPDATE ce_cases SET
        status = 'ACTIVE',
        reopened_count = COALESCE(reopened_count, 0) + 1,
        closed_date = NULL,
        closure_reason = NULL,
        updated_by = p_performed_by,
        updated_at = now()
      WHERE id = v_reopenable_case_id;

      INSERT INTO ce_case_history (case_id, action, from_status, to_status, notes, performed_by)
      VALUES (v_reopenable_case_id, 'REOPENED', 'CLOSED', 'ACTIVE',
              'Auto-reopened due to new violation ' || v_violation.violation_number,
              p_performed_by);

      v_case_id := v_reopenable_case_id;
    END IF;
  END IF;

  -- 6. If still no case, create new one
  IF v_case_id IS NULL THEN
    -- Generate case number
    v_case_number := 'CC-' || to_char(now(), 'YYYY') || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);

    INSERT INTO ce_cases (
      case_number, employer_id, employer_name, territory,
      status, priority, case_type, case_family, case_family_id,
      summary, opened_date, violation_count,
      created_by, updated_by
    ) VALUES (
      v_case_number,
      v_violation.employer_id,
      v_violation.employer_name,
      v_violation.territory,
      'OPEN',
      COALESCE(v_violation.priority, 'MEDIUM'),
      v_family_code,
      v_family_code,
      v_family_id,
      'Auto-created from violation ' || v_violation.violation_number,
      CURRENT_DATE,
      0,
      p_performed_by,
      p_performed_by
    ) RETURNING id INTO v_case_id;

    v_is_new_case := true;

    INSERT INTO ce_case_history (case_id, action, to_status, notes, performed_by)
    VALUES (v_case_id, 'CASE_CREATED', 'OPEN',
            'Auto-created from violation ' || v_violation.violation_number || ' (Family: ' || v_family_code || ')',
            p_performed_by);
  END IF;

  -- 7. Link violation to case (junction + direct FK)
  INSERT INTO ce_case_violations (case_id, violation_id, linked_by)
  VALUES (v_case_id, p_violation_id, p_performed_by)
  ON CONFLICT (case_id, violation_id) DO NOTHING;

  UPDATE ce_violations SET
    case_id = v_case_id,
    case_family = v_family_code,
    updated_by = p_performed_by,
    updated_at = now()
  WHERE id = p_violation_id;

  -- 8. Log the linking action
  INSERT INTO ce_case_history (case_id, action, notes, performed_by)
  VALUES (v_case_id, 'VIOLATION_LINKED',
          'Linked violation ' || v_violation.violation_number || ' (type: ' || COALESCE(v_violation.category, 'UNKNOWN') || ')',
          p_performed_by);

  -- 9. Recalculate severity
  PERFORM fn_ce_recalculate_case_severity(v_case_id);

  v_result := jsonb_build_object(
    'ok', true,
    'case_id', v_case_id,
    'action', CASE WHEN v_is_new_case THEN 'CASE_CREATED' 
                   WHEN v_reopenable_case_id IS NOT NULL THEN 'CASE_REOPENED'
                   ELSE 'VIOLATION_LINKED' END,
    'case_family', v_family_code,
    'violation_id', p_violation_id
  );

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_create_plan_revision(p_plan_id uuid, p_reason_code text, p_reason_text text, p_actor character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_id uuid; v_orig public.ce_weekly_plans%ROWTYPE;
  v_next_version int; v_root_id uuid; v_open_rev RECORD;
BEGIN
  SELECT * INTO v_orig FROM public.ce_weekly_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Plan % not found', p_plan_id; END IF;
  IF v_orig.status NOT IN ('APPROVED','IN_EXECUTION') THEN
    RAISE EXCEPTION 'Only APPROVED or IN_EXECUTION plans can be revised (current: %)', v_orig.status;
  END IF;
  IF v_orig.superseded_at IS NOT NULL THEN
    RAISE EXCEPTION 'Plan % is already superseded', v_orig.plan_number;
  END IF;
  IF p_reason_code IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.ce_plan_revision_reasons WHERE reason_code = p_reason_code AND enabled
  ) THEN
    RAISE EXCEPTION 'Invalid revision reason code: %', p_reason_code;
  END IF;

  v_root_id := COALESCE(v_orig.parent_plan_id, v_orig.id);

  SELECT id, plan_number, status INTO v_open_rev
    FROM public.ce_weekly_plans
   WHERE COALESCE(parent_plan_id, id) = v_root_id
     AND status IN ('DRAFT','REVISION_DRAFT','SUBMITTED','REVISION_SUBMITTED','QUERIED','REVISION_QUERIED','PENDING_APPROVAL')
   ORDER BY version_no DESC LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'A revision is already in progress (% — status %). Please complete or withdraw it before requesting a new revision.',
      v_open_rev.plan_number, v_open_rev.status;
  END IF;

  -- Backfill: supersede any stranded older APPROVED siblings (keep the one being revised)
  PERFORM public.fn_ce_supersede_stranded_approved(v_root_id, p_plan_id, p_actor);

  SELECT COALESCE(MAX(version_no),1) + 1 INTO v_next_version
    FROM public.ce_weekly_plans
   WHERE COALESCE(parent_plan_id, id) = v_root_id;

  UPDATE public.ce_weekly_plans
     SET is_current_version = false,
         updated_by = p_actor, updated_at = now()
   WHERE id = p_plan_id;

  INSERT INTO public.ce_weekly_plans (
    plan_number, inspector_id, inspector_name, week_start_date, week_end_date,
    status, total_planned_visits, completed_visits, narrative, zone_id,
    parent_plan_id, version_no, base_version_no, is_revision,
    revision_reason, revision_reason_code, revision_reason_text,
    supersedes_plan_id, is_current_version,
    created_by, created_at, updated_by, updated_at
  ) VALUES (
    v_orig.plan_number || '-R' || v_next_version,
    v_orig.inspector_id, v_orig.inspector_name, v_orig.week_start_date, v_orig.week_end_date,
    'REVISION_DRAFT', v_orig.total_planned_visits, 0, v_orig.narrative, v_orig.zone_id,
    v_root_id, v_next_version, v_orig.version_no, true,
    p_reason_text, p_reason_code, p_reason_text,
    p_plan_id, true,
    p_actor, now(), p_actor, now()
  ) RETURNING id INTO v_new_id;

  INSERT INTO public.ce_weekly_plan_items (
    plan_id, item_type, day_of_week, scheduled_date, scheduled_start_time, scheduled_end_time,
    duration, source_type, source_id, source_ref, employer_id, employer_name,
    area_name, territory, scouting_type, scouting_confidence, visit_type, purpose,
    priority, recommendation_score, is_mandatory, execution_status,
    zone_id, recommendation_reasons, recommendation_source, audit_cycle_due_date,
    is_locked_by_execution, source_item_id,
    created_by, created_at, updated_by, updated_at
  )
  SELECT v_new_id, item_type, day_of_week, scheduled_date, scheduled_start_time, scheduled_end_time,
    duration, source_type, source_id, source_ref, employer_id, employer_name,
    area_name, territory, scouting_type, scouting_confidence, visit_type, purpose,
    priority, recommendation_score, is_mandatory,
    CASE WHEN execution_status IN ('COMPLETED','IN_PROGRESS') THEN execution_status ELSE 'PLANNED' END,
    zone_id, recommendation_reasons, COALESCE(recommendation_source,'CARRY_FORWARD'), audit_cycle_due_date,
    (execution_status IN ('COMPLETED','IN_PROGRESS')), id,
    p_actor, now(), p_actor, now()
  FROM public.ce_weekly_plan_items WHERE plan_id = p_plan_id;

  INSERT INTO public.ce_weekly_plan_reviews (plan_id, action, comments, performed_by, performed_at)
  VALUES (p_plan_id, 'REVISION_REQUESTED',
          COALESCE(p_reason_text,'') || ' [code:' || p_reason_code || ']', p_actor, now());

  RETURN v_new_id;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ce_decide_violation_grouping(p_violation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_violation        record;
  v_family           record;
  v_rule             jsonb;
  v_candidate        record;
  v_candidate_ids    uuid[] := '{}';
  v_matched          jsonb;
  v_decision         varchar(30);
  v_target           uuid;
  v_reason           text;
  v_max_age          int;
  v_date_range_days  int;
BEGIN
  SELECT v.id, v.employer_id, v.fund_type, v.period_from, v.period_to,
         v.violation_type_id, vt.category AS violation_category
  INTO v_violation
  FROM ce_violations v
  LEFT JOIN ce_violation_types vt ON vt.id = v.violation_type_id
  WHERE v.id = p_violation_id;

  IF v_violation.id IS NULL THEN
    RETURN jsonb_build_object('decision','SEND_TO_INTAKE','reason','Violation not found');
  END IF;

  -- Resolve case family — prefer allowed_violation_type_ids, fall back to violation_categories
  SELECT * INTO v_family
  FROM ce_case_families
  WHERE is_active = true
    AND (
      (v_violation.violation_type_id = ANY (allowed_violation_type_ids))
      OR (v_violation.violation_category IS NOT NULL
          AND v_violation.violation_category = ANY (violation_categories))
    )
  ORDER BY sort_order, name
  LIMIT 1;

  IF v_family.id IS NULL THEN
    RETURN jsonb_build_object(
      'decision','SEND_TO_INTAKE',
      'reason','No active case family configured for this violation type or category'
    );
  END IF;

  v_rule := v_family.grouping_rule;
  v_max_age := COALESCE((v_rule->>'maxOpenCaseAgeDays')::int, 0);
  v_date_range_days := COALESCE((v_rule->>'dateRangeDays')::int, 0);

  -- Find candidate open cases obeying grouping configuration
  FOR v_candidate IN
    SELECT c.*
    FROM ce_cases c
    WHERE (c.is_deleted IS NULL OR c.is_deleted = false)
      AND ( NOT COALESCE((v_rule->>'openCaseOnly')::boolean, true)
            OR c.status NOT IN ('CLOSED','RESOLVED','MERGED','CANCELLED') )
      AND ( NOT COALESCE((v_rule->>'sameEmployer')::boolean, true)
            OR c.employer_id = v_violation.employer_id )
      AND ( NOT COALESCE((v_rule->>'sameCaseFamily')::boolean, true)
            OR c.case_family_id = v_family.id )
      AND ( NOT COALESCE((v_rule->>'sameFund')::boolean, false)
            OR c.fund_type = v_violation.fund_type )
      AND ( v_max_age = 0
            OR c.opened_date >= CURRENT_DATE - v_max_age )
    ORDER BY c.opened_date DESC
  LOOP
    v_candidate_ids := array_append(v_candidate_ids, v_candidate.id);
  END LOOP;

  IF array_length(v_candidate_ids, 1) IS NULL THEN
    IF COALESCE(v_family.auto_create_case, true) THEN
      v_decision := 'CREATE_NEW';
      v_reason := 'No matching open case — auto-create per family configuration';
    ELSIF COALESCE(v_family.manual_intake_on_no_match, true) THEN
      v_decision := 'SEND_TO_INTAKE';
      v_reason := 'No matching case and auto-create disabled — sent to manual intake';
    ELSE
      v_decision := 'SEND_TO_INTAKE';
      v_reason := 'No matching case';
    END IF;
    v_target := NULL;
  ELSE
    v_decision := 'ATTACH_EXISTING';
    v_target := v_candidate_ids[1];
    v_reason := 'Matched existing open case by grouping rule';
  END IF;

  v_matched := jsonb_build_object(
    'caseFamilyId', v_family.id,
    'caseFamilyCode', v_family.code,
    'rule', v_rule,
    'violationTypeId', v_violation.violation_type_id,
    'violationCategory', v_violation.violation_category,
    'employerId', v_violation.employer_id,
    'fundType', v_violation.fund_type
  );

  RETURN jsonb_build_object(
    'decision', v_decision,
    'caseFamilyId', v_family.id,
    'caseFamilyCode', v_family.code,
    'targetCaseId', v_target,
    'candidateCaseIds', to_jsonb(v_candidate_ids),
    'matched', v_matched,
    'reason', v_reason
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_follow_up_action_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
