CREATE OR REPLACE FUNCTION public.fn_ce_promote_plan_revision(p_revision_id uuid, p_actor character varying)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rev    public.ce_weekly_plans%ROWTYPE;
  v_parent uuid;
BEGIN
  SELECT * INTO v_rev FROM public.ce_weekly_plans WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Revision % not found', p_revision_id; END IF;
  IF v_rev.status <> 'APPROVED' THEN
    RAISE EXCEPTION 'Only APPROVED revisions can be promoted (current: %)', v_rev.status;
  END IF;

  v_parent := COALESCE(v_rev.parent_plan_id, v_rev.id);

  -- Mark the prior current version as superseded
  UPDATE public.ce_weekly_plans
     SET superseded_at = now(),
         superseded_by_plan_id = p_revision_id,
         is_current_version = false,
         status = 'SUPERSEDED',
         updated_by = p_actor,
         updated_at = now()
   WHERE COALESCE(parent_plan_id, id) = v_parent
     AND id <> p_revision_id
     AND is_current_version = true;

  -- Mark this revision as current
  UPDATE public.ce_weekly_plans
     SET is_current_version = true,
         updated_by = p_actor,
         updated_at = now()
   WHERE id = p_revision_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_query_plan_revision(p_revision_id uuid, p_query_notes text, p_actor character varying)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_rev public.ce_weekly_plans%ROWTYPE;
BEGIN
  SELECT * INTO v_rev FROM public.ce_weekly_plans WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Revision % not found', p_revision_id; END IF;
  IF v_rev.status <> 'REVISION_SUBMITTED' THEN
    RAISE EXCEPTION 'Only REVISION_SUBMITTED can be queried (current: %)', v_rev.status;
  END IF;

  UPDATE public.ce_weekly_plans
     SET status = 'REVISION_QUERIED',
         reviewer_comments = p_query_notes,
         updated_by = p_actor, updated_at = now()
   WHERE id = p_revision_id;

  INSERT INTO public.ce_weekly_plan_reviews (plan_id, action, comments, performed_by, performed_at)
  VALUES (p_revision_id, 'REVISION_QUERIED', p_query_notes, p_actor, now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_recalc_audit_priority_for_employer(p_employer_id character varying, p_policy_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row RECORD;
  v_band varchar(20);
BEGIN
  -- Pull the v3 row for this employer
  SELECT *
    INTO v_row
    FROM public.fn_ce_score_candidates_v3(NULL, NULL, 5000)
   WHERE employer_id = p_employer_id
   LIMIT 1;

  IF v_row IS NULL THEN
    -- No live signals — clear the audit-priority snapshot but keep timestamp
    UPDATE public.ce_risk_profiles
       SET audit_priority_score = 0,
           audit_priority_band  = 'Low',
           audit_priority_reasons = '[]'::jsonb,
           audit_priority_why = 'No active triggers',
           last_audit_priority_calculated_at = now(),
           last_recalc_policy_id = p_policy_id
     WHERE employer_id = p_employer_id;
    RETURN jsonb_build_object('employer_id', p_employer_id, 'audit_priority_score', 0);
  END IF;

  v_band := CASE
              WHEN v_row.audit_priority_score >= 75 THEN 'Critical'
              WHEN v_row.audit_priority_score >= 50 THEN 'High'
              WHEN v_row.audit_priority_score >= 25 THEN 'Medium'
              ELSE 'Low'
            END;

  UPDATE public.ce_risk_profiles
     SET audit_priority_score = v_row.audit_priority_score,
         audit_priority_band  = v_band,
         audit_priority_reasons = v_row.recommendation_reasons,
         audit_priority_why     = v_row.why_selected,
         last_audit_priority_calculated_at = now(),
         last_recalc_policy_id = p_policy_id
   WHERE employer_id = p_employer_id;

  RETURN jsonb_build_object(
    'employer_id', p_employer_id,
    'audit_priority_score', v_row.audit_priority_score,
    'audit_priority_band',  v_band
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_recalculate_case_severity(p_case_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB;
  v_count INTEGER;
  v_principal NUMERIC := 0;
  v_penalties NUMERIC := 0;
  v_interest NUMERIC := 0;
  v_total NUMERIC := 0;
  v_score NUMERIC := 0;
  v_last_date DATE;
  v_priority VARCHAR;
  v_escalation_rec BOOLEAN := false;
  v_case_family VARCHAR;
  v_thresh_days INTEGER;
  v_thresh_amount NUMERIC;
  v_opened_date DATE;
  v_days_open INTEGER;
  rec RECORD;
BEGIN
  -- Get case metadata
  SELECT case_family, opened_date INTO v_case_family, v_opened_date
  FROM ce_cases WHERE id = p_case_id;

  -- Get family thresholds
  SELECT escalation_threshold_days, escalation_threshold_amount
  INTO v_thresh_days, v_thresh_amount
  FROM ce_case_families
  WHERE code = v_case_family AND is_active = true;

  v_thresh_days := COALESCE(v_thresh_days, 90);
  v_thresh_amount := COALESCE(v_thresh_amount, 50000);

  -- Aggregate from violations
  SELECT 
    COUNT(*),
    COALESCE(SUM(principal_amount), 0),
    COALESCE(SUM(penalty_amount), 0),
    COALESCE(SUM(interest_amount), 0),
    COALESCE(SUM(total_amount), 0),
    MAX(discovered_date)
  INTO v_count, v_principal, v_penalties, v_interest, v_total, v_last_date
  FROM ce_violations v
  INNER JOIN ce_case_violations cv ON cv.violation_id = v.id
  WHERE cv.case_id = p_case_id
    AND v.status NOT IN ('CANCELLED', 'MERGED')
    AND (v.is_deleted IS NULL OR v.is_deleted = false);

  -- Score each violation
  FOR rec IN
    SELECT v.priority, v.total_amount as viol_amount, v.discovered_date
    FROM ce_violations v
    INNER JOIN ce_case_violations cv ON cv.violation_id = v.id
    WHERE cv.case_id = p_case_id
      AND v.status NOT IN ('CANCELLED', 'MERGED')
      AND (v.is_deleted IS NULL OR v.is_deleted = false)
  LOOP
    DECLARE
      v_age_mult NUMERIC;
      v_amt_factor NUMERIC;
      v_pri_boost NUMERIC;
    BEGIN
      v_age_mult := LEAST((CURRENT_DATE - rec.discovered_date)::NUMERIC / 30.0, 5.0);
      v_amt_factor := CASE WHEN COALESCE(rec.viol_amount, 0) > 0 THEN log(10, rec.viol_amount + 1) ELSE 1 END;
      v_pri_boost := CASE rec.priority
        WHEN 'CRITICAL' THEN 4.0
        WHEN 'HIGH' THEN 3.0
        WHEN 'MEDIUM' THEN 2.0
        ELSE 1.0
      END;
      v_score := v_score + (1.0 * GREATEST(v_age_mult, 0.5) * v_amt_factor * v_pri_boost);
    END;
  END LOOP;

  -- Determine priority from score
  v_priority := CASE
    WHEN v_score > 80 THEN 'CRITICAL'
    WHEN v_score > 50 THEN 'HIGH'
    WHEN v_score > 20 THEN 'MEDIUM'
    ELSE 'LOW'
  END;

  -- Check escalation thresholds
  v_days_open := COALESCE(CURRENT_DATE - v_opened_date, 0);
  IF v_days_open > v_thresh_days OR v_total > v_thresh_amount THEN
    v_escalation_rec := true;
  END IF;

  -- Update the case
  UPDATE ce_cases SET
    violation_count = v_count,
    total_principal = v_principal,
    total_penalties = v_penalties,
    total_interest = v_interest,
    total_amount = v_total,
    severity_score = v_score,
    priority = v_priority,
    last_violation_date = v_last_date,
    escalation_recommended = v_escalation_rec,
    updated_at = now()
  WHERE id = p_case_id;

  v_result := jsonb_build_object(
    'case_id', p_case_id,
    'violation_count', v_count,
    'severity_score', v_score,
    'priority', v_priority,
    'total_amount', v_total,
    'escalation_recommended', v_escalation_rec,
    'days_open', v_days_open
  );

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_recommendation_status_change_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
