$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_reject_plan_revision(p_revision_id uuid, p_decision_notes text, p_actor character varying)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_rev public.ce_weekly_plans%ROWTYPE; v_root uuid; v_other_approved int;
BEGIN
  SELECT * INTO v_rev FROM public.ce_weekly_plans WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Revision % not found', p_revision_id; END IF;
  IF v_rev.status NOT IN ('REVISION_SUBMITTED','REVISION_DRAFT','REVISION_QUERIED') THEN
    RAISE EXCEPTION 'Cannot reject revision in status %', v_rev.status;
  END IF;
  v_root := COALESCE(v_rev.parent_plan_id, v_rev.id);

  UPDATE public.ce_weekly_plans
     SET status = 'REVISION_REJECTED',
         is_current_version = false,
         approval_decision_notes = p_decision_notes,
         updated_by = p_actor, updated_at = now()
   WHERE id = p_revision_id;

  -- Only restore prior version as current if no other approved exists in family
  SELECT COUNT(*) INTO v_other_approved
    FROM public.ce_weekly_plans
   WHERE COALESCE(parent_plan_id, id) = v_root
     AND id <> p_revision_id
     AND status = 'APPROVED';

  IF v_other_approved = 0 AND v_rev.supersedes_plan_id IS NOT NULL THEN
    UPDATE public.ce_weekly_plans
       SET is_current_version = true,
           status = CASE WHEN status = 'SUPERSEDED' THEN 'APPROVED' ELSE status END,
           approved_version_flag = true,
           superseded_at = NULL,
           superseded_by_plan_id = NULL,
           updated_by = p_actor, updated_at = now()
     WHERE id = v_rev.supersedes_plan_id;
  END IF;

  -- Backfill any stranded older approved (keep only one)
  PERFORM public.fn_ce_supersede_stranded_approved(v_root, v_rev.supersedes_plan_id, p_actor);

  INSERT INTO public.ce_weekly_plan_reviews (plan_id, action, comments, performed_by, performed_at)
  VALUES (p_revision_id, 'REVISION_REJECTED', p_decision_notes, p_actor, now());
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ce_resolve_case_family(p_violation_type_id uuid)
 RETURNS TABLE(family_id uuid, family_code character varying)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_category VARCHAR;
BEGIN
  -- Get category from violation type
  SELECT category INTO v_category
  FROM ce_violation_types
  WHERE id = p_violation_type_id;

  IF v_category IS NULL THEN
    RETURN QUERY SELECT NULL::UUID, 'GENERAL'::VARCHAR;
    RETURN;
  END IF;

  -- Find the case family whose violation_categories array contains this category
  RETURN QUERY
  SELECT cf.id, cf.code
  FROM ce_case_families cf
  WHERE v_category = ANY(cf.violation_categories)
    AND cf.is_active = true
  ORDER BY cf.sort_order
  LIMIT 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_resolve_zone(p_village_code character varying DEFAULT NULL::character varying, p_office_code character varying DEFAULT NULL::character varying)
 RETURNS TABLE(zone_id uuid, zone_code character varying, zone_name character varying, resolution_method character varying)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Priority 1: Village-level mapping
  IF p_village_code IS NOT NULL THEN
    RETURN QUERY
    SELECT z.id, z.zone_code, z.zone_name, 'VILLAGE'::VARCHAR
    FROM ce_village_zone_mapping vzm
    JOIN ce_zones z ON z.id = vzm.zone_id
    WHERE vzm.village_code = p_village_code
      AND vzm.is_active = true
      AND z.is_active = true
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
  END IF;

  -- Priority 2: Office-level default
  IF p_office_code IS NOT NULL THEN
    RETURN QUERY
    SELECT z.id, z.zone_code, z.zone_name, 'OFFICE'::VARCHAR
    FROM ce_zone_office_mapping zom
    JOIN ce_zones z ON z.id = zom.zone_id
    WHERE zom.office_code = p_office_code
      AND zom.is_default = true
      AND zom.is_active = true
      AND z.is_active = true
    LIMIT 1;
    
    IF FOUND THEN RETURN; END IF;
  END IF;

  -- Priority 3: Fallback to first active zone
  RETURN QUERY
  SELECT z.id, z.zone_code, z.zone_name, 'FALLBACK'::VARCHAR
  FROM ce_zones z
  WHERE z.is_active = true
  ORDER BY z.zone_code
  LIMIT 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_route_violation(p_violation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec RECORD;
  v_zone_id UUID;
  v_zone_code VARCHAR;
  v_resolution_method VARCHAR;
  v_queue_type VARCHAR;
  v_queue_id UUID;
  v_queue_code VARCHAR;
  v_inspector_id UUID;
  v_inspector_name VARCHAR;
  v_village_code VARCHAR;
  v_office_code VARCHAR;
BEGIN
  -- Get violation + employer context
  SELECT v.id, v.status, v.employer_id, v.territory,
         e.village_code, e.office_code
  INTO v_rec
  FROM ce_violations v
  LEFT JOIN er_master e ON e.regno = v.employer_id
  WHERE v.id = p_violation_id AND v.is_deleted = false;

  IF v_rec IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Violation not found');
  END IF;

  v_village_code := v_rec.village_code;
  v_office_code := v_rec.office_code;

  -- Resolve zone
  SELECT rz.zone_id, rz.zone_code, rz.resolution_method
  INTO v_zone_id, v_zone_code, v_resolution_method
  FROM fn_ce_resolve_zone(v_village_code, v_office_code) rz
  LIMIT 1;

  IF v_zone_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No zone resolved');
  END IF;

  -- Determine queue type from status
  v_queue_type := CASE
    WHEN v_rec.status = 'OPEN' THEN 'OPS'
    WHEN v_rec.status = 'UNDER_REVIEW' THEN 'REV'
    WHEN v_rec.status IN ('ESCALATED', 'LEGAL') THEN 'LEG'
    ELSE 'FLB'
  END;

  -- Resolve queue
  SELECT q.id, q.queue_code INTO v_queue_id, v_queue_code
  FROM ce_assignment_queues q
  WHERE q.zone_id = v_zone_id AND q.queue_type = v_queue_type AND q.is_active = true
  LIMIT 1;

  -- Fallback to FLB if specific queue not found
  IF v_queue_id IS NULL THEN
    SELECT q.id, q.queue_code INTO v_queue_id, v_queue_code
    FROM ce_assignment_queues q
    WHERE q.zone_id = v_zone_id AND q.queue_type = 'FLB' AND q.is_active = true
    LIMIT 1;
    v_queue_type := 'FLB';
  END IF;

  -- Try direct officer: only if exactly 1 active LEAD in this queue
  IF v_queue_id IS NOT NULL THEN
    SELECT qm.inspector_id INTO v_inspector_id
    FROM ce_queue_members qm
    WHERE qm.queue_id = v_queue_id AND qm.role = 'LEAD' AND qm.is_active = true;
    
    -- Only assign if exactly one lead (GET DIAGNOSTICS not needed, use count check)
    IF (SELECT COUNT(*) FROM ce_queue_members WHERE queue_id = v_queue_id AND role = 'LEAD' AND is_active = true) = 1 THEN
      SELECT ci.name INTO v_inspector_name FROM ce_inspectors ci WHERE ci.id = v_inspector_id;
    ELSE
      v_inspector_id := NULL;
      v_inspector_name := NULL;
    END IF;
  END IF;

  -- Mark previous assignments as superseded
  UPDATE ce_violation_assignments
  SET is_current = false, superseded_at = now()
  WHERE violation_id = p_violation_id AND is_current = true;

  -- Write assignment record
  INSERT INTO ce_violation_assignments (
    violation_id, assigned_to_inspector_id, assigned_to_queue_id,
    assignment_type, assigned_by, zone_resolved_from, resolution_method, notes
  ) VALUES (
    p_violation_id, v_inspector_id, v_queue_id,
    'AUTO', 'SYSTEM-ROUTER', v_zone_code, v_resolution_method,
    'Auto-routed: ' || COALESCE(v_resolution_method, 'UNKNOWN') || ' → ' || COALESCE(v_queue_code, 'NONE')
  );

  -- Update violation record
  UPDATE ce_violations SET
    zone_id = v_zone_id,
    assigned_queue_id = v_queue_id,
    assigned_to_user_id = CASE WHEN v_inspector_id IS NOT NULL THEN v_inspector_id::TEXT ELSE NULL END,
    assigned_to_name = v_inspector_name,
    assigned_at = now(),
    assignment_method = v_resolution_method,
    updated_at = now(),
    updated_by = 'SYSTEM-ROUTER'
  WHERE id = p_violation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'violation_id', p_violation_id,
    'zone_code', v_zone_code,
    'queue_code', v_queue_code,
    'queue_type', v_queue_type,
    'resolution_method', v_resolution_method,
    'inspector_id', v_inspector_id,
    'inspector_name', v_inspector_name
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_route_violations_bulk(p_violation_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_ok integer := 0;
BEGIN
  IF p_violation_ids IS NULL THEN
    RETURN 0;
  END IF;

  FOREACH v_id IN ARRAY p_violation_ids LOOP
    BEGIN
      PERFORM public.fn_ce_route_violation(v_id);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      -- routing is best-effort; a single failure must not abort the batch
      NULL;
    END;
  END LOOP;

  RETURN v_ok;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_run_audit_priority_refresh(p_dry_run boolean DEFAULT false, p_zone_id uuid DEFAULT NULL::uuid, p_changed_only boolean DEFAULT false, p_batch_size integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_processed int := 0;
  v_affected  int := 0;
  v_errors    int := 0;
  v_emp RECORD;
  v_policy_id uuid;
  v_started timestamptz := now();
BEGIN
  SELECT id INTO v_policy_id
    FROM public.ce_risk_policies
   WHERE status = 'ACTIVE'
   ORDER BY updated_at DESC NULLS LAST, created_at DESC
   LIMIT 1;

  FOR v_emp IN
    SELECT rp.employer_id
      FROM public.ce_risk_profiles rp
     WHERE (p_zone_id IS NULL OR rp.zone_id = p_zone_id)
       AND (p_changed_only = false
            OR rp.last_calculated_at IS NULL
            OR rp.last_audit_priority_calculated_at IS NULL
            OR rp.last_calculated_at > rp.last_audit_priority_calculated_at)
     LIMIT p_batch_size
  LOOP
    v_processed := v_processed + 1;
    BEGIN
      IF NOT p_dry_run THEN
        PERFORM public.fn_ce_recalc_audit_priority_for_employer(v_emp.employer_id, v_policy_id);
        v_affected := v_affected + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'dry_run', p_dry_run, 'policy_id', v_policy_id,
    'processed', v_processed, 'affected', v_affected, 'errors', v_errors,
    'started_at', v_started, 'completed_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_score_candidates_batch(p_limit integer DEFAULT 200)
 RETURNS TABLE(employer_id text, employer_name text, territory text, candidate_source text, candidate_reason text, derived_priority text, risk_band text, risk_score numeric, days_since_last_inspection integer, open_violation_count bigint, escalated_violation_count bigint, overdue_followup_count bigint, financial_exposure numeric, notice_days_remaining integer, any_breach_detected boolean, carry_forward_count bigint, recommendation_score numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    c.employer_id::text,
    c.employer_name::text,
    c.territory::text,
    c.candidate_source::text,
    c.candidate_reason::text,
    c.derived_priority::text,
    c.risk_band::text,
    c.risk_score,
    c.days_since_last_inspection,
    c.open_violation_count,
    c.escalated_violation_count,
    c.overdue_followup_count,
    c.financial_exposure,
    c.notice_days_remaining,
    c.any_breach_detected,
    c.carry_forward_count,
    public.fn_ce_score_plan_candidate(
      p_source_type           := c.candidate_source,
      p_priority              := c.derived_priority,
      p_risk_band             := c.risk_band,
      p_days_overdue          := GREATEST(0, COALESCE(c.days_since_last_inspection, 0)),
      p_overdue_followup_count := COALESCE(c.overdue_followup_count, 0)::int,
      p_notice_days_remaining := c.notice_days_remaining,
      p_financial_exposure    := COALESCE(c.financial_exposure, 0),
      p_prior_violation_count := COALESCE(c.open_violation_count, 0)::int,
      p_days_since_last_visit := c.days_since_last_inspection,
      p_is_same_zone          := false,
      p_is_manager_flagged    := false,
      p_scouting_confidence   := CASE
                                   WHEN c.candidate_source = 'SCOUTING_LEAD'
                                   THEN c.derived_priority
                                   ELSE NULL
                                 END
    ) AS recommendation_score
  FROM public.ce_v_plan_candidates_v2 c
  ORDER BY public.fn_ce_score_plan_candidate(
    c.candidate_source, c.derived_priority, c.risk_band,
    GREATEST(0, COALESCE(c.days_since_last_inspection, 0)),
    COALESCE(c.overdue_followup_count, 0)::int,
    c.notice_days_remaining,
    COALESCE(c.financial_exposure, 0),
    COALESCE(c.open_violation_count, 0)::int,
    c.days_since_last_inspection,
    false, false,
    CASE WHEN c.candidate_source = 'SCOUTING_LEAD' THEN c.derived_priority ELSE NULL END
  ) DESC
  LIMIT p_limit;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_score_candidates_v3(p_zone_id uuid DEFAULT NULL::uuid, p_inspector_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200)
 RETURNS TABLE(employer_id text, employer_name text, territory text, zone_id uuid, audit_program text, candidate_source text, candidate_reason text, derived_priority text, risk_band text, risk_score numeric, inherent_risk_score numeric, audit_priority_score numeric, days_since_last_inspection integer, last_audit_date date, next_due_date date, overdue_days integer, open_violation_count bigint, escalated_violation_count bigint, overdue_followup_count bigint, violation_count bigint, case_count bigint, financial_exposure numeric, notice_days_remaining integer, any_breach_detected boolean, carry_forward_count bigint, audit_cycle_due_date date, cycle_overdue_days integer, is_cycle_overdue boolean, recommendation_score numeric, recommendation_reasons jsonb, why_selected text, mandatory_class text, bucket text, estimated_effort numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inspector_zone uuid;
  w_inherent      numeric := 25;
  w_trigger       numeric := 25;
  w_dueness       numeric := 20;
  w_enforcement   numeric := 15;
  w_followup      numeric := 10;
  w_opfit         numeric := 5;
BEGIN
  IF p_zone_id IS NULL AND p_inspector_id IS NOT NULL THEN
    SELECT primary_zone_id INTO v_inspector_zone
      FROM public.ce_inspectors WHERE id = p_inspector_id;
  END IF;

  SELECT COALESCE(MAX(CASE WHEN weight_key='INHERENT_RISK'     THEN weight_pct END), w_inherent),
         COALESCE(MAX(CASE WHEN weight_key='TRIGGER_URGENCY'   THEN weight_pct END), w_trigger),
         COALESCE(MAX(CASE WHEN weight_key='AUDIT_DUENESS'     THEN weight_pct END), w_dueness),
         COALESCE(MAX(CASE WHEN weight_key='ENFORCEMENT_STAGE' THEN weight_pct END), w_enforcement),
         COALESCE(MAX(CASE WHEN weight_key='FOLLOW_UP_AGING'   THEN weight_pct END), w_followup),
         COALESCE(MAX(CASE WHEN weight_key='OPERATIONAL_FIT'   THEN weight_pct END), w_opfit)
    INTO w_inherent, w_trigger, w_dueness, w_enforcement, w_followup, w_opfit
    FROM public.ce_audit_priority_weights
   WHERE enabled = true;

  RETURN QUERY
  WITH base AS (
    SELECT
      c.*,
      rp.zone_id              AS rp_zone_id,
      rp.next_review_date     AS rp_next_review,
      rp.last_inspected_at    AS rp_last_inspected,
      rp.last_audit_date      AS rp_last_audit_date,
      rp.next_audit_due_date  AS rp_next_audit_due,
      rp.overdue_audit_days   AS rp_overdue_audit_days,
      rp.audit_program        AS rp_audit_program,
      rp.consecutive_cycles_skipped AS rp_skipped,
      CASE
        WHEN rp.next_audit_due_date IS NOT NULL
          THEN GREATEST(0, (CURRENT_DATE - rp.next_audit_due_date))
        WHEN rp.next_review_date IS NOT NULL
          THEN GREATEST(0, (CURRENT_DATE - rp.next_review_date))
        ELSE 0
      END AS rp_overdue_days,
      (SELECT COUNT(*) FROM public.ce_cases cs
        WHERE cs.employer_id = c.employer_id
          AND COALESCE(cs.status,'') NOT IN ('CLOSED','RESOLVED','WITHDRAWN')) AS case_cnt
    FROM public.ce_v_plan_candidates_v2 c
    LEFT JOIN public.ce_risk_profiles rp ON rp.employer_id = c.employer_id
  ),
  filtered AS (
    SELECT * FROM base
     WHERE (p_zone_id IS NULL AND v_inspector_zone IS NULL)
        OR (p_zone_id IS NOT NULL AND rp_zone_id = p_zone_id)
        OR (v_inspector_zone IS NOT NULL AND rp_zone_id = v_inspector_zone)
  ),
  deduped AS (
    SELECT DISTINCT ON (f.employer_id, COALESCE(f.rp_audit_program,'_'))
           f.*
      FROM filtered f
     ORDER BY f.employer_id, COALESCE(f.rp_audit_program,'_'),
              COALESCE(f.escalated_violation_count,0) DESC,
              COALESCE(f.open_violation_count,0) DESC
  ),
  scored AS (
    SELECT
      d.*,
      LEAST(100, COALESCE(d.risk_score, 0)) AS s_inherent,
      LEAST(100,
        (COALESCE(d.escalated_violation_count,0) * 25)
      + (COALESCE(d.open_violation_count,0) * 6)
      + (CASE WHEN d.any_breach_detected THEN 20 ELSE 0 END)
      + (CASE WHEN COALESCE(d.notice_days_remaining,99) <= 3 THEN 25
              WHEN COALESCE(d.notice_days_remaining,99) <= 7 THEN 15 ELSE 0 END)
      ) AS s_trigger,
      LEAST(100,
        (CASE WHEN d.rp_overdue_days > 0
              THEN LEAST(60, d.rp_overdue_days)
              ELSE 0 END)
      + (COALESCE(d.rp_skipped,0) * 20)
      + (CASE WHEN d.rp_next_audit_due IS NOT NULL
                AND d.rp_next_audit_due <= (CURRENT_DATE + INTERVAL '14 day')
              THEN 20 ELSE 0 END)
      ) AS s_dueness,
      LEAST(100,
        (d.case_cnt * 20)
      + (CASE WHEN COALESCE(d.financial_exposure,0) > 50000 THEN 30
              WHEN COALESCE(d.financial_exposure,0) > 10000 THEN 15
              WHEN COALESCE(d.financial_exposure,0) > 0     THEN 5 ELSE 0 END)
      ) AS s_enforcement,
      LEAST(100,
        (COALESCE(d.overdue_followup_count,0) * 15)
      + (COALESCE(d.carry_forward_count,0) * 10)
      ) AS s_followup,
      CASE
        WHEN p_zone_id IS NOT NULL AND d.rp_zone_id = p_zone_id THEN 100
        WHEN v_inspector_zone IS NOT NULL AND d.rp_zone_id = v_inspector_zone THEN 100
        WHEN d.rp_zone_id IS NOT NULL THEN 40
        ELSE 0
      END AS s_opfit
    FROM deduped d
  ),
  ranked AS (
    SELECT
      s.*,
      ROUND(
          (s.s_inherent    * w_inherent
         + s.s_trigger     * w_trigger
         + s.s_dueness     * w_dueness
         + s.s_enforcement * w_enforcement
         + s.s_followup    * w_followup
         + s.s_opfit       * w_opfit) / NULLIF(w_inherent+w_trigger+w_dueness+w_enforcement+w_followup+w_opfit, 0)
      , 2) AS audit_priority,
      CASE
        WHEN s.any_breach_detected
             OR (s.candidate_reason IN ('ARRANGEMENT_DEFAULT','ARRANGEMENT_AT_RISK'))
          THEN 'ARRANGEMENT_BREACH'
        WHEN s.case_cnt > 0 AND s.escalated_violation_count > 0
          THEN 'LEGAL_STAGE_TRIGGER'
        WHEN s.case_cnt > 0
          THEN 'POST_ENFORCEMENT_RECHECK'
        WHEN s.rp_overdue_days > 0 OR COALESCE(s.rp_skipped,0) > 0
          THEN 'ROUTINE_CYCLE_DUE'
        WHEN s.risk_band IN ('HIGH','CRITICAL') AND COALESCE(s.days_since_last_inspection, 9999) > 180
          THEN 'MANDATORY_HIGH_RISK_REVIEW'
        ELSE s.candidate_reason
      END AS reason_v3
    FROM scored s
  ),
  classified AS (
    SELECT
      r.*,
      CASE
        WHEN r.reason_v3 IN ('LEGAL_STAGE_TRIGGER','MANDATORY_HIGH_RISK_REVIEW','ARRANGEMENT_BREACH')
             OR (r.rp_overdue_days > 30 AND COALESCE(r.rp_skipped,0) >= 1)
             OR (r.escalated_violation_count > 0 AND r.case_cnt > 0)
          THEN 'MANDATORY'
        WHEN r.audit_priority >= 50
             OR r.escalated_violation_count > 0
             OR r.rp_overdue_days > 14
             OR COALESCE(r.notice_days_remaining,99) <= 7
          THEN 'PRIORITY'
        ELSE 'WATCHLIST'
      END AS mandatory_class_v,
      CASE
        WHEN r.reason_v3 IN ('LEGAL_STAGE_TRIGGER','MANDATORY_HIGH_RISK_REVIEW','ARRANGEMENT_BREACH')
          THEN 'MUST_SCHEDULE'
        WHEN r.case_cnt > 0
             OR r.escalated_violation_count > 0
             OR r.reason_v3 IN ('POST_ENFORCEMENT_RECHECK','OVERDUE_FOLLOW_UP')
          THEN 'REACTIVE_ENFORCEMENT'
        WHEN r.risk_band IN ('HIGH','CRITICAL')
             OR (COALESCE(r.days_since_last_inspection, 9999) > 180)
          THEN 'RISK_MONITORING'
        WHEN r.reason_v3 IN ('ROUTINE_CYCLE_DUE')
             OR r.rp_overdue_days > 0
          THEN 'ROUTINE_COVERAGE'
        ELSE 'CAMPAIGN_INTEL'
      END AS bucket_v,
      ROUND(
        CASE COALESCE(r.rp_audit_program,'')
          WHEN 'FULL_AUDIT'   THEN 6.0
          WHEN 'DESK_REVIEW'  THEN 2.0
          WHEN 'FOLLOW_UP'    THEN 1.5
          WHEN 'SPOT_CHECK'   THEN 1.0
          ELSE 3.0
        END
        + LEAST(2.0, COALESCE(r.open_violation_count,0) * 0.25)
      , 2) AS effort_hours
    FROM ranked r
  ),
  with_reasons AS (
    SELECT
      c.*,
      jsonb_strip_nulls(jsonb_build_array(
        CASE WHEN c.s_inherent    > 0 THEN jsonb_build_object('code','INHERENT_RISK','label','Inherent risk',           'weight', c.s_inherent)    END,
        CASE WHEN c.s_trigger     > 0 THEN jsonb_build_object('code','TRIGGER_URGENCY','label','Active triggers',       'weight', c.s_trigger)     END,
        CASE WHEN c.s_dueness     > 0 THEN jsonb_build_object('code','AUDIT_DUENESS','label','Audit due / overdue',     'weight', c.s_dueness)     END,
        CASE WHEN c.s_enforcement > 0 THEN jsonb_build_object('code','ENFORCEMENT_STAGE','label','Enforcement / cases', 'weight', c.s_enforcement) END,
        CASE WHEN c.s_followup    > 0 THEN jsonb_build_object('code','FOLLOW_UP_AGING','label','Follow-up / carry fwd', 'weight', c.s_followup)    END,
        CASE WHEN c.s_opfit       > 0 THEN jsonb_build_object('code','OPERATIONAL_FIT','label','Zone fit',              'weight', c.s_opfit)       END,
        CASE WHEN c.mandatory_class_v = 'MANDATORY' THEN jsonb_build_object('code','MANDATORY','label','Mandatory class','weight', 100) END
      )) AS reasons_json,
      CONCAT_WS(' • ',
        NULLIF(CASE WHEN c.mandatory_class_v = 'MANDATORY' THEN 'Mandatory' END,''),
        NULLIF(CASE WHEN c.risk_band IS NOT NULL THEN c.risk_band || ' risk' END,''),
        NULLIF(CASE WHEN c.rp_overdue_days > 0 THEN c.rp_overdue_days || 'd overdue' END,''),
        NULLIF(CASE WHEN c.open_violation_count > 0 THEN c.open_violation_count || ' open viol.' END,''),
        NULLIF(CASE WHEN c.case_cnt > 0 THEN c.case_cnt || ' active case(s)' END,''),
        NULLIF(CASE WHEN c.any_breach_detected THEN 'arrangement breach' END,''),
        NULLIF(CASE WHEN c.notice_days_remaining IS NOT NULL AND c.notice_days_remaining <= 7 THEN 'notice in ' || c.notice_days_remaining || 'd' END,'')
      ) AS why_line
    FROM classified c
  )
  SELECT
    w.employer_id::text,
    w.employer_name::text,
    w.territory::text,
    w.rp_zone_id,
    w.rp_audit_program::text,
    w.candidate_source::text,
    w.reason_v3::text,
    w.derived_priority::text,
    w.risk_band::text,
    w.risk_score,
    w.s_inherent      AS inherent_risk_score,
    w.audit_priority  AS audit_priority_score,
    w.days_since_last_inspection,
    w.rp_last_audit_date,
    w.rp_next_audit_due,
    w.rp_overdue_days::int,
    w.open_violation_count,
    w.escalated_violation_count,
    w.overdue_followup_count,
    w.open_violation_count AS violation_count,
    w.case_cnt::bigint     AS case_count,
    w.financial_exposure,
    w.notice_days_remaining,
    w.any_breach_detected,
    w.carry_forward_count,
    w.rp_next_review                    AS audit_cycle_due_date,
    w.rp_overdue_days::int              AS cycle_overdue_days,
    (w.rp_overdue_days > 0)             AS is_cycle_overdue,
    w.audit_priority                    AS recommendation_score,
    w.reasons_json                      AS recommendation_reasons,
    w.why_line                          AS why_selected,
    w.mandatory_class_v                 AS mandatory_class,
    w.bucket_v                          AS bucket,
    w.effort_hours                      AS estimated_effort
  FROM with_reasons w
  ORDER BY
    CASE w.mandatory_class_v WHEN 'MANDATORY' THEN 0 WHEN 'PRIORITY' THEN 1 ELSE 2 END,
    w.audit_priority DESC NULLS LAST,
    w.s_trigger DESC,
    w.s_dueness DESC
  LIMIT p_limit;
END
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_score_plan_candidate(p_source_type text, p_priority text DEFAULT 'MEDIUM'::text, p_risk_band text DEFAULT NULL::text, p_days_overdue integer DEFAULT 0, p_overdue_followup_count integer DEFAULT 0, p_notice_days_remaining integer DEFAULT NULL::integer, p_financial_exposure numeric DEFAULT 0, p_prior_violation_count integer DEFAULT 0, p_days_since_last_visit integer DEFAULT NULL::integer, p_is_same_zone boolean DEFAULT false, p_is_manager_flagged boolean DEFAULT false, p_scouting_confidence text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_score NUMERIC(5,2) := 0;
  v_sev NUMERIC; v_risk NUMERIC; v_over NUMERIC; v_fu NUMERIC;
  v_not NUMERIC; v_fin NUMERIC; v_rep NUMERIC; v_rec NUMERIC;
  v_zone NUMERIC; v_mgr NUMERIC; v_scout NUMERIC;
BEGIN
  v_sev := CASE UPPER(COALESCE(p_priority,''))
    WHEN 'CRITICAL' THEN 100 WHEN 'HIGH' THEN 75 WHEN 'MEDIUM' THEN 50 WHEN 'LOW' THEN 25 ELSE 40 END;
  v_risk := CASE UPPER(COALESCE(p_risk_band,''))
    WHEN 'CRITICAL' THEN 100 WHEN 'HIGH' THEN 75 WHEN 'MEDIUM' THEN 50 WHEN 'LOW' THEN 25 ELSE 30 END;
  v_over := CASE
    WHEN p_days_overdue > 90 THEN 100 WHEN p_days_overdue > 60 THEN 75
    WHEN p_days_overdue > 30 THEN 50 WHEN p_days_overdue > 14 THEN 25 ELSE 0 END;
  v_fu := LEAST(p_overdue_followup_count * 20, 100);
  v_not := CASE
    WHEN p_notice_days_remaining IS NULL THEN 0
    WHEN p_notice_days_remaining <= 3 THEN 100 WHEN p_notice_days_remaining <= 7 THEN 75
    WHEN p_notice_days_remaining <= 14 THEN 50 ELSE 0 END;
  v_fin := CASE
    WHEN p_financial_exposure > 50000 THEN 100 WHEN p_financial_exposure > 20000 THEN 75
    WHEN p_financial_exposure > 10000 THEN 50 WHEN p_financial_exposure > 5000 THEN 25 ELSE 0 END;
  v_rep := LEAST(p_prior_violation_count * 15, 100);
  v_rec := CASE
    WHEN p_days_since_last_visit IS NULL THEN 50
    WHEN p_days_since_last_visit > 180 THEN 100 WHEN p_days_since_last_visit > 90 THEN 75
    WHEN p_days_since_last_visit > 60 THEN 50 ELSE 0 END;
  v_zone := CASE WHEN p_is_same_zone THEN 100 ELSE 0 END;
  v_mgr := CASE WHEN p_is_manager_flagged THEN 100 ELSE 0 END;
  v_scout := CASE UPPER(COALESCE(p_scouting_confidence,''))
    WHEN 'HIGH' THEN 100 WHEN 'MEDIUM' THEN 60 WHEN 'LOW' THEN 30 ELSE 0 END;

  v_score := (v_sev*0.20)+(v_risk*0.15)+(v_over*0.15)+(v_fu*0.10)
           +(v_not*0.10)+(v_fin*0.10)+(v_rep*0.05)+(v_rec*0.05)
           +(v_zone*0.05)+(v_mgr*0.03)+(v_scout*0.02);

  RETURN ROUND(v_score, 2);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_submit_plan_revision(p_revision_id uuid, p_actor character varying)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_rev public.ce_weekly_plans%ROWTYPE; v_root uuid;
BEGIN
  SELECT * INTO v_rev FROM public.ce_weekly_plans WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Revision % not found', p_revision_id; END IF;
  IF v_rev.status NOT IN ('REVISION_DRAFT','REVISION_QUERIED') THEN
    RAISE EXCEPTION 'Only REVISION_DRAFT/REVISION_QUERIED can be submitted (current: %)', v_rev.status;
  END IF;
  v_root := COALESCE(v_rev.parent_plan_id, v_rev.id);

  -- Auto-withdraw older APPROVED / IN_EXECUTION versions in the same family
  UPDATE public.ce_weekly_plans
     SET status = 'SUPERSEDED',
         is_current_version = false,
         approved_version_flag = false,
         superseded_at = now(),
         superseded_by_plan_id = p_revision_id,
         updated_by = p_actor, updated_at = now()
   WHERE COALESCE(parent_plan_id, id) = v_root
     AND id <> p_revision_id
     AND status IN ('APPROVED','IN_EXECUTION');

  UPDATE public.ce_weekly_plans
     SET status = 'REVISION_SUBMITTED',
         submitted_date = now(),
         is_current_version = true,
         updated_by = p_actor, updated_at = now()
   WHERE id = p_revision_id;

  INSERT INTO public.ce_weekly_plan_reviews (plan_id, action, comments, performed_by, performed_at)
  VALUES (p_revision_id, 'REVISION_SUBMITTED', 'Auto-withdrew prior approved version on submit.', p_actor, now());
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ce_supersede_stranded_approved(p_root_id uuid, p_keep_id uuid, p_actor character varying)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.ce_weekly_plans
     SET status = 'SUPERSEDED',
         is_current_version = false,
         approved_version_flag = false,
         superseded_at = COALESCE(superseded_at, now()),
         superseded_by_plan_id = COALESCE(superseded_by_plan_id, p_keep_id),
         updated_by = p_actor, updated_at = now()
   WHERE COALESCE(parent_plan_id, id) = p_root_id
     AND id <> p_keep_id
     AND status IN ('APPROVED','IN_EXECUTION')
     AND is_current_version = false;
END $function$;
CREATE OR REPLACE FUNCTION public.fn_ce_touch_inherent_calc_ts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.total_score IS DISTINCT FROM OLD.total_score
     OR NEW.last_calculated_at IS DISTINCT FROM OLD.last_calculated_at THEN
    NEW.last_inherent_calculated_at := COALESCE(NEW.last_calculated_at, now());
    NEW.inherent_band := NEW.risk_band;
  END IF;
  RETURN NEW;
END;
$function$;
