AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_violation_set_zone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_village VARCHAR;
  v_office VARCHAR;
  v_zone_id UUID;
BEGIN
  IF NEW.zone_id IS NOT NULL OR NEW.employer_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT e.village_code, e.office_code
    INTO v_village, v_office
  FROM er_master e
  WHERE e.regno = NEW.employer_id;

  IF v_village IS NULL AND v_office IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT rz.zone_id INTO v_zone_id
  FROM fn_ce_resolve_zone(v_village, v_office) rz
  LIMIT 1;

  IF v_zone_id IS NOT NULL THEN
    NEW.zone_id := v_zone_id;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_ce_weekly_plan_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.status = 'APPROVED'
     AND OLD.superseded_at IS NULL THEN
    -- Only allow status transitions to SUPERSEDED/IN_EXECUTION/COMPLETED, plus controlled metadata
    IF (NEW.week_start_date IS DISTINCT FROM OLD.week_start_date)
       OR (NEW.week_end_date IS DISTINCT FROM OLD.week_end_date)
       OR (NEW.inspector_id  IS DISTINCT FROM OLD.inspector_id)
       OR (NEW.zone_id       IS DISTINCT FROM OLD.zone_id)
       OR (NEW.narrative     IS DISTINCT FROM OLD.narrative)
       OR (NEW.status NOT IN ('APPROVED','SUPERSEDED','COMPLETED','IN_EXECUTION'))
    THEN
      RAISE EXCEPTION 'Approved weekly plan % is immutable. Create a revision (new version) instead.', OLD.plan_number
        USING ERRCODE = '55006';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
