CREATE OR REPLACE FUNCTION public.generate_depend_id(p_ssn character varying)
 RETURNS character varying
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_max_id INTEGER;
    v_new_id VARCHAR(6);
BEGIN
    -- Get the maximum depend_id for this SSN
    SELECT COALESCE(MAX(CAST(depend_id AS INTEGER)), 0) + 1
    INTO v_max_id
    FROM public.ip_depend
    WHERE ssn = p_ssn;
    
    -- Format as 6-character zero-padded string
    v_new_id := LPAD(v_max_id::TEXT, 6, '0');
    
    RETURN v_new_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.generate_er_regno()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_regno TEXT;
  next_val INTEGER;
BEGIN
  -- Get next sequence value
  SELECT nextval('er_perm_regno_seq') INTO next_val;
  
  -- Format as 6-digit string with leading zeros
  new_regno := LPAD(next_val::TEXT, 6, '0');
  
  -- Record in er_last_regno for tracking
  INSERT INTO er_last_regno (regno, date_issued)
  VALUES (new_regno, NOW())
  ON CONFLICT DO NOTHING;
  
  RETURN new_regno;
END;
$function$;
