CREATE OR REPLACE FUNCTION public.generate_user_code(p_first_name text, p_last_name text)
 RETURNS character varying
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base VARCHAR(50);
  v_code VARCHAR(50);
  v_counter INT := 1;
BEGIN
  IF TRIM(COALESCE(p_last_name, '')) = '' THEN
    RAISE EXCEPTION 'Last name is required to generate user_code';
  END IF;
  IF TRIM(COALESCE(p_first_name, '')) = '' THEN
    RAISE EXCEPTION 'First name is required to generate user_code';
  END IF;
  v_base := UPPER(LEFT(TRIM(p_first_name), 1)) || INITCAP(TRIM(p_last_name));
  v_code := v_base;
  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE user_code = v_code) LOOP
    v_counter := v_counter + 1;
    v_code := v_base || v_counter::TEXT;
  END LOOP;
  RETURN v_code;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_active_head_cashier(p_date text, p_office_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date DATE;
  v_user_id UUID;
  v_user_code TEXT;
  v_assigned_by TEXT;
  v_assigned_at TIMESTAMPTZ;
  v_full_name TEXT;
  v_office_code TEXT;
BEGIN
  v_date := COALESCE(p_date::DATE, CURRENT_DATE);

  IF p_office_code IS NOT NULL THEN
    SELECT a.user_id, a.user_code, a.assigned_by, a.assigned_at,
           p.full_name, p.office_code
    INTO v_user_id, v_user_code, v_assigned_by, v_assigned_at, v_full_name, v_office_code
    FROM cn_head_cashier_assignment a
    JOIN profiles p ON p.id = a.user_id
    WHERE a.assignment_date = v_date AND a.is_active = true AND a.office_code = p_office_code
    LIMIT 1;
  ELSE
    SELECT a.user_id, a.user_code, a.assigned_by, a.assigned_at,
           p.full_name, p.office_code
    INTO v_user_id, v_user_code, v_assigned_by, v_assigned_at, v_full_name, v_office_code
    FROM cn_head_cashier_assignment a
    JOIN profiles p ON p.id = a.user_id
    WHERE a.assignment_date = v_date AND a.is_active = true
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'user_id', v_user_id,
    'user_code', v_user_code,
    'full_name', v_full_name,
    'office_code', v_office_code,
    'assigned_by', v_assigned_by,
    'assigned_at', v_assigned_at
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_active_legal_reference_version(p_ref_code text, p_country_code text, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS SETOF core_legal_reference_version
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT v.*
  FROM public.core_legal_reference m
  JOIN public.core_legal_reference_version v ON v.legal_reference_id = m.id
  WHERE m.ref_code = p_ref_code
    AND m.country_code = p_country_code
    AND v.version_status = 'PUBLISHED'
    AND v.effective_from <= p_as_of
    AND (v.effective_to IS NULL OR v.effective_to > p_as_of)
  ORDER BY v.effective_from DESC
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.get_all_public_tables()
 RETURNS TABLE(table_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT t.tablename::TEXT as table_name
  FROM pg_tables t
  WHERE t.schemaname = 'public'
  ORDER BY t.tablename;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_app_security_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _lockdown RECORD;
  _result JSONB;
BEGIN
  SELECT is_locked, locked_at, locked_reason INTO _lockdown
  FROM app_lockdown_state 
  ORDER BY created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'is_locked', COALESCE(_lockdown.is_locked, false),
    'locked_at', _lockdown.locked_at,
    'locked_reason', _lockdown.locked_reason
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_audit_trail_filter_options()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id UUID;
  v_entity_types JSONB;
  v_modules JSONB;
  v_actions JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;

  SELECT COALESCE(jsonb_agg(DISTINCT entity_type ORDER BY entity_type), '[]'::jsonb)
  INTO v_entity_types
  FROM public.system_audit_trail
  WHERE entity_type IS NOT NULL
    AND "timestamp" >= NOW() - INTERVAL '30 days';

  SELECT COALESCE(jsonb_agg(DISTINCT module ORDER BY module), '[]'::jsonb)
  INTO v_modules
  FROM public.system_audit_trail
  WHERE module IS NOT NULL
    AND "timestamp" >= NOW() - INTERVAL '30 days';

  SELECT COALESCE(jsonb_agg(DISTINCT action ORDER BY action), '[]'::jsonb)
  INTO v_actions
  FROM public.system_audit_trail
  WHERE action IS NOT NULL
    AND "timestamp" >= NOW() - INTERVAL '30 days';

  RETURN jsonb_build_object(
    'entity_types', v_entity_types,
    'modules', v_modules,
    'actions', v_actions
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_batch_cheques_for_verification(p_batch_number text)
 RETURNS TABLE(cheque_number text, bank_code text, bank_name text, amount numeric, currency_code text, cheque_date text, payer_id text, payer_type text, source_table text, source_record_id text, payment_id bigint, is_verified boolean, override_cheque_number text, override_bank_code text, override_amount numeric, override_cheque_date text, edit_reason text, verification_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    cp.mop_number::TEXT AS cheque_number,
    cp.bank_code::TEXT AS bank_code,
    tb.name::TEXT AS bank_name,
    cp.payment_amount AS amount,
    COALESCE(cp.currency_code, cp.base_currency, 'XCD')::TEXT AS currency_code,
    CASE WHEN cp.cheque_date IS NOT NULL THEN to_char(cp.cheque_date, 'YYYY-MM-DD') ELSE NULL END AS cheque_date,
    ch.payer_id::TEXT AS payer_id,
    ch.payer_type::TEXT AS payer_type,
    'cn_payment'::TEXT AS source_table,
    cp.payment_sequence_no::TEXT AS source_record_id,
    cp.payment_id AS payment_id,
    COALESCE(v.is_verified, false) AS is_verified,
    v.override_cheque_number::TEXT,
    v.override_bank_code::TEXT,
    v.override_amount,
    CASE WHEN v.override_cheque_date IS NOT NULL THEN to_char(v.override_cheque_date, 'YYYY-MM-DD') ELSE NULL END AS override_cheque_date,
    v.edit_reason::TEXT,
    v.id::TEXT AS verification_id
  FROM public.cn_payment cp
  JOIN public.cn_payment_header ch ON cp.payment_id = ch.payment_id
  JOIN public.cn_receipt r ON r.payment_id = ch.payment_id AND r.status != 'C'
  LEFT JOIN public.cn_batch_cheque_verification v
    ON v.batch_number = p_batch_number
    AND v.source_table = 'cn_payment'
    AND v.source_record_id = cp.payment_sequence_no::TEXT
  LEFT JOIN public.tb_bank_code tb ON cp.bank_code = tb.bank_code
  WHERE ch.batch_number = p_batch_number
    AND cp.mop_code = 'CHQ'
    AND COALESCE(ch.status, 'active') != 'cancelled';
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_biweekly_enabled_weeks(p_year integer, p_month integer)
 RETURNS boolean[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result boolean[] := ARRAY[false, false, false, false, false];
  v_first_target_of_year date;
  v_first_target_of_month date;
  v_day date;
  v_target_day date;
  v_idx integer := 0;
  v_seq integer;
  v_week_start_day integer;
  v_target_dow integer;
BEGIN
  -- Read configurable week start day
  SELECT COALESCE((SELECT config_value FROM public.c3_calculation_config WHERE config_key = 'week_start_day' AND is_active = true LIMIT 1), 1)::INTEGER INTO v_week_start_day;
  v_target_dow := CASE WHEN v_week_start_day = 7 THEN 0 ELSE v_week_start_day END;

  -- Find first target weekday of the year
  v_day := make_date(p_year, 1, 1);
  WHILE EXTRACT(DOW FROM v_day)::INTEGER != v_target_dow LOOP
    v_day := v_day + 1;
  END LOOP;
  v_first_target_of_year := v_day;

  -- Find first target weekday of the month
  v_day := make_date(p_year, p_month, 1);
  WHILE EXTRACT(DOW FROM v_day)::INTEGER != v_target_dow LOOP
    v_day := v_day + 1;
  END LOOP;

  -- Iterate target weekdays in this month
  v_target_day := v_day;
  WHILE EXTRACT(month FROM v_target_day) = p_month AND v_idx < 5 LOOP
    v_seq := ((v_target_day - v_first_target_of_year) / 7) + 1;
    v_result[v_idx + 1] := (v_seq % 2 = 0);
    v_idx := v_idx + 1;
    v_target_day := v_target_day + 7;
  END LOOP;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_biweekly_valid_weeks(p_year integer)
 RETURNS TABLE(week_number integer, week_start date, week_end date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_day date;
  v_seq integer := 0;
  v_week_start_day integer;
  v_target_dow integer;
BEGIN
  -- Read configurable week start day
  SELECT COALESCE((SELECT config_value FROM public.c3_calculation_config WHERE config_key = 'week_start_day' AND is_active = true LIMIT 1), 1)::INTEGER INTO v_week_start_day;
  v_target_dow := CASE WHEN v_week_start_day = 7 THEN 0 ELSE v_week_start_day END;

  v_day := make_date(p_year, 1, 1);
  WHILE EXTRACT(DOW FROM v_day)::INTEGER != v_target_dow LOOP
    v_day := v_day + 1;
  END LOOP;

  WHILE EXTRACT(year FROM v_day) = p_year LOOP
    v_seq := v_seq + 1;
    IF v_seq % 2 = 0 THEN
      week_number := v_seq;
      week_start := v_day;
      week_end := (v_day + '6 days'::interval)::date;
      RETURN NEXT;
    END IF;
    v_day := v_day + 7;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_c3_component_balances(p_payer_id text, p_payer_type text, p_period text, p_sequence_no integer, p_is_for_director boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_components JSONB := '[]'::JSONB;
  v_paid_map JSONB := '{}'::JSONB;
  v_result JSONB := '[]'::JSONB;
  v_comp JSONB;
  v_code TEXT;
  v_original NUMERIC;
  v_paid NUMERIC;
  v_balance NUMERIC;
  v_codes TEXT[];
  v_period_mm_yyyy TEXT;
BEGIN
  SELECT
    emp_ss_amt_calc,
    emp_levy_amt_calc,
    emp_pe_amt_calc,
    emp_ss_fines_due,
    emp_levy_penalty_amt,
    emp_pe_penalty_amt
  INTO v_record
  FROM cn_c3_reported
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND period = p_period::timestamp
    AND sequence_no = p_sequence_no
    AND is_for_director = COALESCE(p_is_for_director, FALSE)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'components', '[]'::jsonb);
  END IF;

  -- Convert p_period (YYYY-MM-01) to MM/YYYY format to match c3_payment_components.period
  v_period_mm_yyyy := LPAD(EXTRACT(MONTH FROM p_period::date)::text, 2, '0') || '/' || EXTRACT(YEAR FROM p_period::date)::text;

  IF COALESCE(p_is_for_director, FALSE) THEN
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'LVC', 'original_amount', COALESCE(v_record.emp_levy_amt_calc, 0)),
      jsonb_build_object('payment_code', 'LVF', 'original_amount', COALESCE(v_record.emp_levy_penalty_amt, 0))
    );
    v_codes := ARRAY['LVC','LVF'];
  ELSIF p_payer_type = 'ER' THEN
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'SSC', 'original_amount', COALESCE(v_record.emp_ss_amt_calc, 0)),
      jsonb_build_object('payment_code', 'LVC', 'original_amount', COALESCE(v_record.emp_levy_amt_calc, 0)),
      jsonb_build_object('payment_code', 'PEC', 'original_amount', COALESCE(v_record.emp_pe_amt_calc, 0)),
      jsonb_build_object('payment_code', 'SSF', 'original_amount', COALESCE(v_record.emp_ss_fines_due, 0)),
      jsonb_build_object('payment_code', 'LVF', 'original_amount', COALESCE(v_record.emp_levy_penalty_amt, 0)),
      jsonb_build_object('payment_code', 'PEF', 'original_amount', COALESCE(v_record.emp_pe_penalty_amt, 0))
    );
    v_codes := ARRAY['SSC','LVC','PEC','SSF','LVF','PEF'];
  ELSIF p_payer_type = 'SE' THEN
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'SEF', 'original_amount', COALESCE(v_record.emp_ss_fines_due, 0)),
      jsonb_build_object('payment_code', 'SSE', 'original_amount', COALESCE(v_record.emp_ss_amt_calc, 0))
    );
    v_codes := ARRAY['SEF','SSE'];
  ELSIF p_payer_type = 'VC' THEN
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'VOC', 'original_amount', COALESCE(v_record.emp_ss_amt_calc, 0))
    );
    v_codes := ARRAY['VOC'];
  ELSE
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'SSC', 'original_amount', COALESCE(v_record.emp_ss_amt_calc, 0)),
      jsonb_build_object('payment_code', 'LVC', 'original_amount', COALESCE(v_record.emp_levy_amt_calc, 0)),
      jsonb_build_object('payment_code', 'PEC', 'original_amount', COALESCE(v_record.emp_pe_amt_calc, 0)),
      jsonb_build_object('payment_code', 'SSF', 'original_amount', COALESCE(v_record.emp_ss_fines_due, 0)),
      jsonb_build_object('payment_code', 'LVF', 'original_amount', COALESCE(v_record.emp_levy_penalty_amt, 0)),
      jsonb_build_object('payment_code', 'PEF', 'original_amount', COALESCE(v_record.emp_pe_penalty_amt, 0))
    );
    v_codes := ARRAY['SSC','LVC','PEC','SSF','LVF','PEF'];
  END IF;

  -- Use converted MM/YYYY format for matching c3_payment_components.period
  SELECT COALESCE(jsonb_object_agg(sub.payment_code, sub.total_paid), '{}'::jsonb)
  INTO v_paid_map
  FROM (
    SELECT cpc.payment_code, SUM(COALESCE(cpc.component_amount, 0)) AS total_paid
    FROM c3_payment_components cpc
    INNER JOIN cn_payment_header h ON h.payment_id = cpc.payment_id
    INNER JOIN cn_receipt r ON r.payment_id = cpc.payment_id
    WHERE h.payer_id = p_payer_id
      AND h.payer_type = p_payer_type
      AND h.status IS DISTINCT FROM 'deleted'
      AND r.status != 'C'
      AND COALESCE(h.is_for_director, FALSE) = COALESCE(p_is_for_director, FALSE)
      AND cpc.period = v_period_mm_yyyy
      AND cpc.payment_code = ANY(v_codes)
      AND cpc.sequence_no = p_sequence_no
    GROUP BY cpc.payment_code
  ) sub;

  FOR v_comp IN SELECT * FROM jsonb_array_elements(v_components)
  LOOP
    v_code := v_comp->>'payment_code';
    v_original := (v_comp->>'original_amount')::numeric;
    v_paid := COALESCE((v_paid_map->>v_code)::numeric, 0);
    v_balance := GREATEST(v_original - v_paid, 0);

    v_result := v_result || jsonb_build_array(
      jsonb_build_object(
        'payment_code', v_code,
        'original_amount', v_original,
        'paid_amount', v_paid,
        'balance_amount', v_balance,
        'fully_paid', (v_balance <= 0)
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'found',
    'components', v_result,
    'sequence_no', p_sequence_no
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_c3_config_for_period(p_period_date date)
 RETURNS TABLE(config_period_id uuid, start_date date, end_date date, min_age_ss integer, max_age_ss integer, min_age_levy integer, max_age_levy integer, employee_ss_rate numeric, employee_ss_max_wage numeric, employer_ss_rate numeric, employer_eib_rate numeric, employer_eib_max_wage numeric, employer_ss_max_wage numeric, employer_levy_rate numeric, employer_severance_rate numeric, submission_due_day integer, levy_penalty_initial_rate numeric, levy_penalty_subsequent_rate numeric, severance_penalty_initial_rate numeric, severance_penalty_subsequent_rate numeric, ss_fine_initial_rate numeric, ss_fine_subsequent_rate numeric, levy_slab_id uuid, levy_monthly_threshold numeric, levy_use_monthly_when_exceeded boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    cp.id as config_period_id,
    cp.start_date,
    cp.end_date,
    cd.min_age_ss,
    cd.max_age_ss,
    cd.min_age_levy,
    cd.max_age_levy,
    cd.employee_ss_rate,
    cd.employee_ss_max_wage,
    cd.employer_ss_rate,
    cd.employer_eib_rate,
    cd.employer_eib_max_wage,
    cd.employer_ss_max_wage,
    cd.employer_levy_rate,
    cd.employer_severance_rate,
    cd.submission_due_day,
    cd.levy_penalty_initial_rate,
    cd.levy_penalty_subsequent_rate,
    cd.severance_penalty_initial_rate,
    cd.severance_penalty_subsequent_rate,
    cd.ss_fine_initial_rate,
    cd.ss_fine_subsequent_rate,
    cd.levy_slab_id,
    cd.levy_monthly_threshold,
    cd.levy_use_monthly_when_exceeded
  FROM public.c3_config_periods cp
  JOIN public.c3_config_details cd ON cd.config_period_id = cp.id
  WHERE cp.is_active = true
    AND cp.start_date <= p_period_date
    AND (cp.end_date IS NULL OR cp.end_date >= p_period_date)
  ORDER BY cp.start_date DESC
  LIMIT 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_c3_filing_config()
 RETURNS TABLE(config_key text, config_value numeric, display_name text, description text, config_type text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT c.config_key::TEXT, c.config_value, c.display_name::TEXT, c.description::TEXT, c.config_type::TEXT
  FROM public.c3_calculation_config c
  WHERE c.category = 'filing' AND c.is_active = true
  ORDER BY c.display_order;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_c3_payment_components(p_payer_id text, p_payer_type text, p_period text, p_sequence_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_components JSONB := '[]'::JSONB;
BEGIN
  -- Fetch the C3 reported record
  SELECT 
    emp_ss_amt_calc,
    emp_levy_amt_calc,
    emp_pe_amt_calc,
    emp_ss_fines_due,
    emp_levy_penalty_amt,
    emp_pe_penalty_amt
  INTO v_record
  FROM cn_c3_reported
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND period = p_period::timestamp
    AND sequence_no = p_sequence_no
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found', 'components', '[]'::jsonb);
  END IF;

  -- Build components based on payer_type
  IF p_payer_type = 'ER' THEN
    -- Employer: SSC, LVC, PEC, SSF, LVF, PEF
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'SSC', 'amount', COALESCE(v_record.emp_ss_amt_calc, 0)),
      jsonb_build_object('payment_code', 'LVC', 'amount', COALESCE(v_record.emp_levy_amt_calc, 0)),
      jsonb_build_object('payment_code', 'PEC', 'amount', COALESCE(v_record.emp_pe_amt_calc, 0)),
      jsonb_build_object('payment_code', 'SSF', 'amount', COALESCE(v_record.emp_ss_fines_due, 0)),
      jsonb_build_object('payment_code', 'LVF', 'amount', COALESCE(v_record.emp_levy_penalty_amt, 0)),
      jsonb_build_object('payment_code', 'PEF', 'amount', COALESCE(v_record.emp_pe_penalty_amt, 0))
    );
  ELSIF p_payer_type = 'SE' THEN
    -- Self-Employed: SEF, SSE
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'SEF', 'amount', COALESCE(v_record.emp_ss_fines_due, 0)),
      jsonb_build_object('payment_code', 'SSE', 'amount', COALESCE(v_record.emp_ss_amt_calc, 0))
    );
  ELSIF p_payer_type = 'VC' THEN
    -- Voluntary Contributor: VOC
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'VOC', 'amount', COALESCE(v_record.emp_ss_amt_calc, 0))
    );
  ELSE
    -- NW Director or other: treat like ER
    v_components := jsonb_build_array(
      jsonb_build_object('payment_code', 'SSC', 'amount', COALESCE(v_record.emp_ss_amt_calc, 0)),
      jsonb_build_object('payment_code', 'LVC', 'amount', COALESCE(v_record.emp_levy_amt_calc, 0)),
      jsonb_build_object('payment_code', 'PEC', 'amount', COALESCE(v_record.emp_pe_amt_calc, 0)),
      jsonb_build_object('payment_code', 'SSF', 'amount', COALESCE(v_record.emp_ss_fines_due, 0)),
      jsonb_build_object('payment_code', 'LVF', 'amount', COALESCE(v_record.emp_levy_penalty_amt, 0)),
      jsonb_build_object('payment_code', 'PEF', 'amount', COALESCE(v_record.emp_pe_penalty_amt, 0))
    );
  END IF;

  RETURN jsonb_build_object(
    'status', 'found',
    'components', v_components,
    'sequence_no', p_sequence_no
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_c3_payment_history_by_schedule(p_payer_id text, p_payer_type text, p_period_month integer, p_period_year integer, p_sequence_no integer)
 RETURNS TABLE(payment_id bigint, payment_date text, payment_amount numeric, payment_code text, mop_code text, receipt_number text, receipt_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period_start TIMESTAMP;
  v_period_end TIMESTAMP;
  v_next_month INT;
  v_next_year INT;
BEGIN
  v_period_start := (p_period_year || '-' || LPAD(p_period_month::TEXT, 2, '0') || '-01')::TIMESTAMP;
  
  IF p_period_month = 12 THEN
    v_next_month := 1;
    v_next_year := p_period_year + 1;
  ELSE
    v_next_month := p_period_month + 1;
    v_next_year := p_period_year;
  END IF;
  v_period_end := (v_next_year || '-' || LPAD(v_next_month::TEXT, 2, '0') || '-01')::TIMESTAMP;

  RETURN QUERY
  SELECT DISTINCT
    cnp.payment_id::BIGINT,
    cnp.payment_date::TEXT,
    cnp.payment_amount::NUMERIC,
    cnp.payment_code::TEXT,
    cnp.mop_code::TEXT,
    cr.receipt_number::TEXT,
    cr.status::TEXT
  FROM c3_payment_components cpc
  JOIN cn_payment_header cph ON cph.payment_id = cpc.payment_id::BIGINT
  JOIN cn_receipt cr ON cr.payment_id = cpc.payment_id::NUMERIC
  JOIN cn_payment cnp ON cnp.payment_id = cpc.payment_id::BIGINT
  WHERE cph.payer_id = p_payer_id
    AND cph.payer_type = p_payer_type
    AND COALESCE(cph.status, '') != 'deleted'
    AND cr.status != 'C'
    AND cnp.period >= v_period_start
    AND cnp.period < v_period_end
    AND cnp.payment_code::TEXT IN ('CON','LVC','LVF','PEC','PEF','SSE','SEF','SSC','SSF','VOC','VOL')
    AND cpc.sequence_no = p_sequence_no;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_c3_records_filtered(p_payer_type text DEFAULT NULL::text, p_payer_id text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_entered_by text DEFAULT NULL::text, p_verified_by text DEFAULT NULL::text, p_period_month integer DEFAULT NULL::integer, p_period_year integer DEFAULT NULL::integer, p_date_received text DEFAULT NULL::text, p_date_entered text DEFAULT NULL::text, p_schedule_no integer DEFAULT NULL::integer, p_exclude_deleted boolean DEFAULT true, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_offset integer;
  v_result json;
  v_total bigint;
BEGIN
  v_offset := (p_page - 1) * p_page_size;

  SELECT count(*) INTO v_total
  FROM cn_c3_reported c
  WHERE
    (p_payer_type IS NULL OR c.payer_type = p_payer_type)
    AND (p_payer_id IS NULL OR c.payer_id ILIKE '%' || p_payer_id || '%')
    AND (
      (p_status IS NOT NULL AND c.posting_status = p_status)
      OR
      (p_status IS NULL AND c.posting_status IN ('DFT', 'PEN'))
    )
    AND (p_entered_by IS NULL OR c.entered_by = p_entered_by)
    AND (p_verified_by IS NULL OR c.verified_by = p_verified_by)
    AND (p_period_month IS NULL OR EXTRACT(MONTH FROM c.period) = p_period_month)
    AND (p_period_year IS NULL OR EXTRACT(YEAR FROM c.period) = p_period_year)
    AND (p_date_received IS NULL OR c.date_received::date = p_date_received::date)
    AND (p_date_entered IS NULL OR c.date_entered::date = p_date_entered::date)
    AND (p_schedule_no IS NULL OR c.sequence_no = p_schedule_no)
    AND (
      p_exclude_deleted = false
      OR (c.posting_status IS DISTINCT FROM 'DEL' AND c.posting_status IS DISTINCT FROM 'D')
    );

  SELECT json_build_object(
    'data', COALESCE((
      SELECT json_agg(row_to_json(r))
      FROM (
        SELECT c.*
        FROM cn_c3_reported c
        WHERE
          (p_payer_type IS NULL OR c.payer_type = p_payer_type)
          AND (p_payer_id IS NULL OR c.payer_id ILIKE '%' || p_payer_id || '%')
          AND (
            (p_status IS NOT NULL AND c.posting_status = p_status)
            OR
            (p_status IS NULL AND c.posting_status IN ('DFT', 'PEN'))
          )
          AND (p_entered_by IS NULL OR c.entered_by = p_entered_by)
          AND (p_verified_by IS NULL OR c.verified_by = p_verified_by)
          AND (p_period_month IS NULL OR EXTRACT(MONTH FROM c.period) = p_period_month)
          AND (p_period_year IS NULL OR EXTRACT(YEAR FROM c.period) = p_period_year)
          AND (p_date_received IS NULL OR c.date_received::date = p_date_received::date)
          AND (p_date_entered IS NULL OR c.date_entered::date = p_date_entered::date)
          AND (p_schedule_no IS NULL OR c.sequence_no = p_schedule_no)
          AND (
            p_exclude_deleted = false
            OR (c.posting_status IS DISTINCT FROM 'DEL' AND c.posting_status IS DISTINCT FROM 'D')
          )
        ORDER BY c.period DESC, c.date_entered DESC
        LIMIT p_page_size OFFSET v_offset
      ) r
    ), '[]'::json),
    'total', v_total
  ) INTO v_result;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_cashier_office_for_date(p_cashier_user_id uuid, p_date text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date DATE;
  v_override_code VARCHAR(3);
  v_profile_code VARCHAR(3);
  v_desc TEXT;
BEGIN
  v_date := COALESCE(p_date::DATE, CURRENT_DATE);

  -- Check override
  SELECT office_code INTO v_override_code
  FROM cn_cashier_office_override
  WHERE cashier_user_id = p_cashier_user_id AND override_date = v_date
  LIMIT 1;

  IF v_override_code IS NOT NULL THEN
    SELECT description INTO v_desc FROM tb_office WHERE code = v_override_code LIMIT 1;
    RETURN jsonb_build_object('office_code', v_override_code, 'office_description', COALESCE(v_desc, v_override_code), 'is_override', true);
  END IF;

  -- Fallback to profile
  SELECT p.office_code, o.description
  INTO v_profile_code, v_desc
  FROM profiles p
  LEFT JOIN tb_office o ON o.code = p.office_code
  WHERE p.id = p_cashier_user_id;

  RETURN jsonb_build_object('office_code', COALESCE(v_profile_code, 'HQ'), 'office_description', COALESCE(v_desc, v_profile_code, 'HQ'), 'is_override', false);
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_active_revalidation_authorisation(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_channel text := coalesce(p_channel, 'email');
  v_cycle   public.communication_hub_revalidation_cycle%ROWTYPE;
  v_auth    public.communication_hub_revalidation_send_authorisation%ROWTYPE;
  v_current_fp text;
  v_recipient_match boolean;
  v_reason text := NULL;
  v_usable boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_cycle
    FROM public.communication_hub_revalidation_cycle
   WHERE module_code = p_module_code
     AND event_code  = p_event_code
     AND channel     = v_channel
     AND status NOT IN ('CONFIRMED','NOT_RECEIVED','FAILED','VOIDED','PROMOTED','SUPERSEDED','VERIFIED_SUPPLEMENTAL')
   ORDER BY started_at DESC
   LIMIT 1;

  IF v_cycle.id IS NULL THEN
    RETURN jsonb_build_object(
      'authorisation', NULL,
      'unusable_reason', 'no_active_cycle'
    );
  END IF;

  SELECT * INTO v_auth
    FROM public.communication_hub_revalidation_send_authorisation
   WHERE cycle_id = v_cycle.id
   ORDER BY issued_at DESC
   LIMIT 1;

  IF v_auth.id IS NULL THEN
    RETURN jsonb_build_object(
      'authorisation', NULL,
      'unusable_reason', 'no_authorisation'
    );
  END IF;

  v_current_fp := v_cycle.current_evidence_fingerprint_v2;

  -- Determine usability
  IF v_auth.revoked_at IS NOT NULL THEN
    v_reason := 'revoked';
  ELSIF v_auth.consumed_at IS NOT NULL THEN
    v_reason := 'consumed';
  ELSIF v_auth.expires_at IS NOT NULL AND v_auth.expires_at <= now() THEN
    v_reason := 'expired';
  ELSIF coalesce(v_cycle.needs_reassessment, false) THEN
    v_reason := 'needs_reassessment';
  ELSIF v_auth.bound_current_fingerprint IS DISTINCT FROM v_current_fp THEN
    v_reason := 'stale_fingerprint';
  ELSIF v_auth.bound_event_certification_id IS DISTINCT FROM v_cycle.baseline_event_certification_id THEN
    v_reason := 'wrong_event_certification';
  ELSIF v_auth.bound_production_lineage_id IS DISTINCT FROM v_cycle.baseline_production_lineage_id THEN
    v_reason := 'wrong_production_lineage';
  ELSE
    v_recipient_match := (
      v_cycle.recipient_email IS NULL
      OR lower(v_auth.recipient_email) = lower(v_cycle.recipient_email)
    );
    IF NOT v_recipient_match THEN
      v_reason := 'recipient_mismatch';
    ELSE
      v_usable := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'authorisation', jsonb_build_object(
      'id',                            v_auth.id,
      'cycle_id',                      v_auth.cycle_id,
      'status',                        CASE
                                         WHEN v_auth.revoked_at  IS NOT NULL THEN 'REVOKED'
                                         WHEN v_auth.consumed_at IS NOT NULL THEN 'CONSUMED'
                                         WHEN v_auth.expires_at <= now()     THEN 'EXPIRED'
                                         ELSE 'ISSUED' END,
      'recipient',                     v_auth.recipient_email,
      'bound_current_fingerprint',     v_auth.bound_current_fingerprint,
      'bound_event_certification_id',  v_auth.bound_event_certification_id,
      'bound_production_lineage_id',   v_auth.bound_production_lineage_id,
      'issued_at',                     v_auth.issued_at,
      'expires_at',                    v_auth.expires_at,
      'reserved_at',                   NULL,
      'consumed_at',                   v_auth.consumed_at,
      'revoked_at',                    v_auth.revoked_at,
      'usable',                        v_usable,
      'unusable_reason',               v_reason
    ),
    'cycle_id',       v_cycle.id,
    'cycle_status',   v_cycle.status
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_active_revalidation_preparation(p_cycle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_exec public.communication_hub_revalidation_execution%ROWTYPE;
  v_classified text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF p_cycle_id IS NULL THEN
    RETURN jsonb_build_object('execution', NULL, 'unavailable_reason','no_cycle');
  END IF;

  -- Prefer an active row (PREPARING/READY/PROVIDER_INVOKED/RECONCILING),
  -- otherwise the most-recent record (COMPLETE/FAILED_PRE_PROVIDER/…).
  SELECT * INTO v_exec
    FROM public.communication_hub_revalidation_execution
   WHERE cycle_id = p_cycle_id
     AND state IN ('PREPARING','READY_FOR_PROVIDER','PROVIDER_INVOKED','RECONCILING')
   ORDER BY updated_at DESC
   LIMIT 1;

  IF v_exec.id IS NULL THEN
    SELECT * INTO v_exec
      FROM public.communication_hub_revalidation_execution
     WHERE cycle_id = p_cycle_id
     ORDER BY updated_at DESC
     LIMIT 1;
  END IF;

  IF v_exec.id IS NULL THEN
    RETURN jsonb_build_object('execution', NULL, 'unavailable_reason','no_execution');
  END IF;

  v_classified := CASE v_exec.state
    WHEN 'PREPARING'          THEN 'PREPARING'
    WHEN 'READY_FOR_PROVIDER' THEN 'READY_FOR_PROVIDER'
    WHEN 'PROVIDER_INVOKED'   THEN 'PROVIDER_RESULT_PENDING'
    WHEN 'RECONCILING'        THEN 'PROVIDER_RESULT_PENDING'
    WHEN 'COMPLETE'           THEN 'COMPLETE'
    WHEN 'FAILED_PRE_PROVIDER' THEN 'FAILED_PRE_PROVIDER'
    WHEN 'RECOVERY_REQUIRED'  THEN 'RECOVERY_REQUIRED'
    ELSE v_exec.state
  END;

  RETURN jsonb_build_object(
    'execution', jsonb_build_object(
      'execution_id',               v_exec.id,
      'preparation_version',        v_exec.preparation_version,
      'authorisation_id',           v_exec.authorisation_id,
      'state',                      v_exec.state,
      'classified_state',           v_classified,
      'canonical_idempotency_key',  v_exec.idempotency_key,
      'request_id',                 v_exec.request_id,
      'message_id',                 v_exec.message_id,
      'trace_id',                   v_exec.trace_id,
      'attempt_id',                 v_exec.delivery_attempt_id,
      'recipient_snapshot_id',      NULL,
      'provider_boundary_state',    v_exec.provider_boundary_state,
      'provider_call_attempted',    v_exec.provider_call_attempted,
      'failure_code',               v_exec.failure_code,
      'created_at',                 v_exec.created_at,
      'updated_at',                 v_exec.updated_at
    )
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_controlled_live_execution(p_execution_id uuid)
 RETURNS communication_controlled_live_execution
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row communication_controlled_live_execution%rowtype;
begin
  select * into v_row from communication_controlled_live_execution where id = p_execution_id;
  if not found then return null; end if;
  if v_row.requested_by = auth.uid() or public.is_comm_hub_admin(auth.uid()) then
    return v_row;
  end if;
  return null;
end $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_cron_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_job record;
  v_runs jsonb;
BEGIN
  IF v_uid IS NULL OR NOT (public.is_admin(v_uid) OR public.has_permission(v_uid, 'system_administration', 'view')) THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  SELECT jobid, jobname, schedule, active
    INTO v_job
    FROM cron.job
   WHERE jobname = 'comm-hub-dispatch-every-minute'
   LIMIT 1;

  IF v_job.jobid IS NULL THEN
    RETURN jsonb_build_object('exists', false);
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
           'runid', runid,
           'status', status,
           'return_message', LEFT(COALESCE(return_message,''), 200),
           'start_time', start_time,
           'end_time', end_time
         ) ORDER BY start_time DESC)
    INTO v_runs
    FROM (
      SELECT runid, status, return_message, start_time, end_time
        FROM cron.job_run_details
       WHERE jobid = v_job.jobid
       ORDER BY start_time DESC
       LIMIT 20
    ) r;

  RETURN jsonb_build_object(
    'exists', true,
    'jobid', v_job.jobid,
    'jobname', v_job.jobname,
    'schedule', v_job.schedule,
    'active', v_job.active,
    'recent_runs', COALESCE(v_runs, '[]'::jsonb)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_current_evidence_snapshot(p_module_code text, p_event_code text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_module text := _comm_hub_norm_code(p_module_code);
  v_event  text := _comm_hub_norm_code(p_event_code);
  v_channel text := _comm_hub_norm_channel(p_channel);
  v_blockers jsonb := '[]'::jsonb;
  v_map RECORD; v_ctv RECORD; v_rp RECORD; v_sp RECORD; v_rev RECORD;
  v_ps RECORD; v_provider RECORD; v_evt_cert RECORD; v_ore_cert RECORD;
  v_production_lineage_id uuid;
  v_template_manifest_hash text;
  v_recip_set_hash text;
  v_payload_hash text; v_review_hash text; v_send_hash text;
  v_snapshot jsonb; v_core jsonb; v_fingerprint text;
  v_ctrl RECORD;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','UNAUTHENTICATED','component','actor')));
  END IF;
  SELECT public.is_comm_hub_admin(v_actor) INTO v_is_admin;
  IF NOT COALESCE(v_is_admin,false) THEN
    RETURN jsonb_build_object('ok',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','NOT_ADMIN','component','actor')));
  END IF;
  IF v_module IS NULL OR v_event IS NULL OR v_channel IS NULL THEN
    RETURN jsonb_build_object('ok',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','INPUT_INVALID','component','module_event_channel')));
  END IF;

  SELECT operating_mode, runtime_mode_version, configuration_version, automation_generation
    INTO v_ctrl FROM communication_hub_control_settings LIMIT 1;

  SELECT * INTO v_map FROM communication_hub_event_template_map
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event
     AND lower(channel)=v_channel AND active=true LIMIT 1;
  IF v_map.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','TEMPLATE_MAP_UNRESOLVED','component','template_map');
  END IF;

  IF v_map.template_id IS NOT NULL THEN
    SELECT * INTO v_ctv FROM core_template_version
     WHERE template_id=v_map.template_id AND status='PUBLISHED'
     ORDER BY version_no DESC NULLS LAST LIMIT 1;
    IF v_ctv.id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object('code','TEMPLATE_VERSION_UNRESOLVED','component','template_version');
    ELSE
      v_template_manifest_hash := _comm_hub_sha256_jsonb(jsonb_build_object(
        'template_id', v_ctv.template_id, 'version_no', v_ctv.version_no,
        'subject_hash', _comm_hub_sha256_hex(coalesce(v_ctv.subject,'')),
        'body_html_hash', _comm_hub_sha256_hex(coalesce(v_ctv.body_html,'')),
        'body_text_hash', _comm_hub_sha256_hex(coalesce(v_ctv.body_text,''))
      ));
    END IF;
  END IF;

  SELECT * INTO v_rp FROM communication_hub_event_recipient_policy
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel LIMIT 1;
  IF v_rp.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','RECIPIENT_POLICY_UNRESOLVED','component','recipient_policy');
  ELSE
    v_recip_set_hash := _comm_hub_sha256_jsonb(jsonb_build_object(
      'policy_version', v_rp.policy_version,
      'policy_mode', v_rp.policy_mode,
      'destination_scope', v_rp.destination_scope,
      'approved_recipients', v_rp.approved_recipients,
      'approved_domains', v_rp.approved_domains
    ));
  END IF;

  SELECT * INTO v_sp FROM communication_hub_event_send_policy
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel LIMIT 1;
  IF v_sp.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','SEND_POLICY_UNRESOLVED','component','send_policy');
  ELSE
    v_send_hash := coalesce(v_sp.policy_content_hash, _comm_hub_sha256_jsonb(to_jsonb(v_sp)));
  END IF;

  SELECT * INTO v_rev FROM communication_hub_event_review_policy
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel LIMIT 1;
  IF v_rev.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','REVIEW_POLICY_UNRESOLVED','component','review_policy');
  ELSE
    v_review_hash := coalesce(v_rev.policy_content_hash, _comm_hub_sha256_jsonb(jsonb_build_object(
      'review_mode', v_rev.review_mode,
      'preview_required', v_rev.preview_required,
      'allow_operator_edit_tokens', v_rev.allow_operator_edit_tokens,
      'allow_operator_edit_body', v_rev.allow_operator_edit_body,
      'allow_operator_change_recipient', v_rev.allow_operator_change_recipient,
      'require_template_approval', v_rev.require_template_approval,
      'require_legal_approval', v_rev.require_legal_approval,
      'require_business_approval', v_rev.require_business_approval,
      'approval_status', v_rev.approval_status,
      'approved_template_version_id', v_rev.approved_template_version_id
    )));
  END IF;

  SELECT * INTO v_ps FROM communication_hub_event_payload_schema
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event
   ORDER BY schema_version DESC LIMIT 1;
  IF v_ps.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','PAYLOAD_SCHEMA_UNRESOLVED','component','payload_schema');
  ELSE
    v_payload_hash := _comm_hub_sha256_jsonb(jsonb_build_object(
      'schema_version', v_ps.schema_version, 'status', v_ps.status,
      'json_schema_hash', _comm_hub_sha256_jsonb(COALESCE(v_ps.json_schema,'{}'::jsonb))
    ));
  END IF;

  SELECT * INTO v_provider FROM notification_providers
   WHERE lower(channel::text)=v_channel AND is_active=true AND is_default=true
   ORDER BY updated_at DESC NULLS LAST LIMIT 1;
  IF v_provider.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','PROVIDER_UNRESOLVED','component','provider');
  END IF;

  SELECT * INTO v_evt_cert FROM communication_hub_event_certification
   WHERE upper(module_code)=v_module AND upper(event_code)=v_event AND lower(channel)=v_channel LIMIT 1;
  IF v_evt_cert.one_real_email_certification_id IS NOT NULL THEN
    SELECT * INTO v_ore_cert FROM communication_controlled_live_certification
     WHERE id=v_evt_cert.one_real_email_certification_id;
    v_production_lineage_id := v_ore_cert.production_lineage_id;
  END IF;

  IF jsonb_array_length(v_blockers) > 0 THEN
    RETURN jsonb_build_object(
      'ok',false,'snapshot_version',2,
      'production_lineage_id',v_production_lineage_id,
      'event_certification_id',v_evt_cert.id,
      'operating_mode',v_ctrl.operating_mode,
      'runtime_mode_version',v_ctrl.runtime_mode_version,
      'configuration_version',v_ctrl.configuration_version,
      'automation_generation',v_ctrl.automation_generation,
      'blockers',v_blockers
    );
  END IF;

  v_snapshot := jsonb_build_object(
    'module_code',v_module,'event_code',v_event,'channel',v_channel,
    'template_map_id',v_map.id,'template_id',v_map.template_id,'template_code',v_map.template_code,
    'template_version_id',v_ctv.id,'template_version_no',v_ctv.version_no,
    'template_manifest_hash',v_template_manifest_hash,
    'sender_profile_id',v_map.sender_profile_id,
    'recipient_policy_version',v_rp.policy_version,
    'recipient_set_hash',v_recip_set_hash,
    'provider_id',v_provider.id,'provider_key',v_provider.email_provider_type,
    'payload_schema_version',v_ps.schema_version,'payload_schema_hash',v_payload_hash,
    'review_policy_version',v_rev.policy_version,'review_policy_hash',v_review_hash,
    'send_policy_version',v_sp.policy_version,'send_policy_hash',v_send_hash
  );

  v_core := public._comm_hub_evidence_core_v2(v_snapshot);
  v_fingerprint := public._comm_hub_fingerprint_evidence_core_v2(v_core);

  RETURN jsonb_build_object(
    'ok',true,'snapshot_version',2,
    'production_lineage_id',v_production_lineage_id,
    'event_certification_id',v_evt_cert.id,
    'operating_mode',v_ctrl.operating_mode,
    'runtime_mode_version',v_ctrl.runtime_mode_version,
    'configuration_version',v_ctrl.configuration_version,
    'automation_generation',v_ctrl.automation_generation,
    'resolved_at',now(),
    'snapshot',v_snapshot,
    'evidence_core_v2',v_core,
    'evidence_fingerprint_v2',v_fingerprint,
    'evidence_fingerprint_algorithm','sha256-v2',
    'blockers','[]'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_event_go_live_stage9(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_obs public.communication_manual_production_observation%ROWTYPE;
  v_channel text := coalesce(p_channel,'email');
  v_hb_fresh boolean := false;
  v_hb_age_sec int;
  v_ready_ok int;
  v_status text;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';

  IF v_settings.operating_mode='EMERGENCY_STOP'::public.communication_operating_mode THEN
    RETURN jsonb_build_object('live_status','EMERGENCY_STOP',
      'blockers',jsonb_build_array(jsonb_build_object('code','EMERGENCY_STOP')),
      'heartbeat_fresh',false,
      'last_scheduler_heartbeat_at',v_settings.last_scheduler_heartbeat_at,
      'automation_state',v_settings.automation_state,
      'operating_mode',v_settings.operating_mode);
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
    WHERE module_code=p_module_code AND event_code=p_event_code AND channel=v_channel;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','EVENT_CERTIFICATION_MISSING'));
    RETURN jsonb_build_object('live_status','INCOMPLETE','blockers',v_blockers,
      'heartbeat_fresh',false,
      'automation_state',v_settings.automation_state,
      'operating_mode',v_settings.operating_mode,
      'configuration_version',v_settings.configuration_version);
  END IF;

  IF v_ec.drift_detected_at IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','DRIFT_DETECTED'));
  END IF;

  v_hb_age_sec := CASE WHEN v_settings.last_scheduler_heartbeat_at IS NULL THEN NULL
                       ELSE EXTRACT(EPOCH FROM (now()-v_settings.last_scheduler_heartbeat_at))::int END;
  v_hb_fresh := v_hb_age_sec IS NOT NULL AND v_hb_age_sec <= 120;

  IF v_ec.status<>'live_cron_allowed' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','EVENT_NOT_LIVE_CRON_ALLOWED'));
  END IF;
  IF v_settings.operating_mode<>'AUTOMATED_PRODUCTION'::public.communication_operating_mode THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','MODE_NOT_AUTOMATED_PRODUCTION'));
  END IF;
  IF v_settings.automation_state<>'ARMED' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','AUTOMATION_NOT_ARMED'));
  END IF;
  IF NOT coalesce(v_settings.scheduler_enabled,false)
     OR NOT coalesce(v_settings.automatic_triggers_enabled,false)
     OR NOT coalesce(v_settings.retry_worker_enabled,false) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','AUTOMATION_CONTROLS_OFF'));
  END IF;
  IF v_settings.last_scheduler_error IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','SCHEDULER_ERROR','detail',v_settings.last_scheduler_error));
  END IF;
  IF v_settings.last_scheduler_heartbeat_at IS NULL
     OR v_settings.automation_armed_at IS NULL
     OR v_settings.last_scheduler_heartbeat_at <= v_settings.automation_armed_at THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','HEARTBEAT_PREDATES_ARM'));
  END IF;
  IF v_settings.heartbeat_arm_audit_id IS NULL
     OR v_settings.current_arm_audit_id IS NULL
     OR v_settings.heartbeat_arm_audit_id <> v_settings.current_arm_audit_id THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','HEARTBEAT_OLD_ARM_GENERATION'));
  END IF;
  IF NOT v_hb_fresh THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','SCHEDULER_HEARTBEAT_STALE','detail',v_hb_age_sec));
  END IF;

  SELECT * INTO v_obs FROM public.communication_manual_production_observation
   WHERE event_certification_id=v_ec.id
     AND status='CONFIRMED' AND inbox_confirmation_status='CONFIRMED'
   ORDER BY dispatched_at DESC LIMIT 1;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','MANUAL_OBSERVATION_MISSING'));
  END IF;

  SELECT count(DISTINCT check_code) INTO v_ready_ok
    FROM public.comm_hub_automation_readiness_results
   WHERE id = ANY(coalesce(v_ec.pinned_readiness_result_ids,'{}'::uuid[]))
     AND result=true AND expires_at > now();
  IF v_ready_ok<9 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','READINESS_INCOMPLETE_OR_STALE'));
  END IF;

  IF jsonb_array_length(v_blockers)=0 THEN
    v_status := 'LIVE_AUTOMATED_ARMED';
  ELSIF v_settings.operating_mode='AUTOMATED_PRODUCTION'::public.communication_operating_mode
     AND v_settings.automation_state='STANDBY' THEN
    v_status := 'LIVE_AUTOMATED_STANDBY';
  ELSE
    v_status := 'INCOMPLETE';
  END IF;

  RETURN jsonb_build_object(
    'live_status',v_status,'blockers',v_blockers,
    'heartbeat_fresh',v_hb_fresh,'heartbeat_age_seconds',v_hb_age_sec,
    'last_scheduler_heartbeat_at',v_settings.last_scheduler_heartbeat_at,
    'scheduler_worker_version',v_settings.scheduler_worker_version,
    'last_processed_count',v_settings.last_processed_count,
    'last_scheduler_error',v_settings.last_scheduler_error,
    'current_arm_audit_id',v_settings.current_arm_audit_id,
    'heartbeat_arm_audit_id',v_settings.heartbeat_arm_audit_id,
    'automation_generation',v_settings.automation_generation,
    'automation_state',v_settings.automation_state,
    'operating_mode',v_settings.operating_mode,
    'configuration_version',v_settings.configuration_version);
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_event_go_live_status(p_module_code text, p_event_code text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_channel text := coalesce(p_channel,'email');
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_latest public.communication_controlled_live_certification%ROWTYPE;
  v_eligible public.communication_controlled_live_certification%ROWTYPE;
  v_latest_confirmed public.communication_controlled_live_certification%ROWTYPE;
  v_anchor_ore public.communication_controlled_live_certification%ROWTYPE;
  v_cand public.communication_controlled_live_certification%ROWTYPE;
  v_eligible_exec public.communication_controlled_live_execution%ROWTYPE;
  v_eligible_grant public.communication_controlled_live_grant%ROWTYPE;
  v_eligible_msg public.communication_message%ROWTYPE;
  v_eligible_att public.communication_delivery_attempt%ROWTYPE;
  v_gate public.communication_hub_real_email_gate%ROWTYPE;
  v_latest_obs public.communication_manual_production_observation%ROWTYPE;
  v_obs_count int := 0;
  v_readiness jsonb := '[]'::jsonb;
  v_ready_all boolean := false;
  v_readiness_row public.comm_hub_automation_readiness_results%ROWTYPE;
  v_r jsonb;
  v_automated_blockers jsonb := '[]'::jsonb;
  v_automated_eligible boolean := true;
  v_eligible_manual int := 0;
  v_eligible_auto int := 0;
  v_s6_blockers jsonb := '[]'::jsonb;
  v_s6_ready boolean := false;
  v_reconciliation_required boolean := false;
  v_latest_provider_call_attempted boolean;
  v_final_exec_id uuid;
  v_final_provider_call_attempted boolean;
  v_event_is_live boolean := false;
  v_production_anchor jsonb := NULL;
  v_latest_candidate jsonb := NULL;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
    WHERE module_code=p_module_code AND event_code=p_event_code AND channel=v_channel;

  v_event_is_live := (v_ec.id IS NOT NULL AND v_ec.status IN ('live_manual_only','live_cron_allowed'));

  SELECT * INTO v_latest FROM public.communication_controlled_live_certification
    WHERE certification_kind='ONE_REAL_EMAIL' AND module_code=p_module_code
      AND event_code=p_event_code AND channel=v_channel
    ORDER BY certified_at DESC NULLS LAST LIMIT 1;

  -- Latest CONFIRMED candidate ORE (independent of whether event is pinned to it).
  SELECT * INTO v_latest_confirmed FROM public.communication_controlled_live_certification
    WHERE certification_kind='ONE_REAL_EMAIL' AND module_code=p_module_code
      AND event_code=p_event_code AND channel=v_channel
      AND invalidated_at IS NULL
      AND manual_verification_status='CONFIRMED'
      AND manual_verified_at IS NOT NULL
    ORDER BY coalesce(manual_verified_at, certified_at) DESC NULLS LAST LIMIT 1;

  -- Eligible ORE (unchanged legacy semantic).
  FOR v_cand IN
    SELECT c.*
      FROM public.communication_controlled_live_certification c
     WHERE c.certification_kind='ONE_REAL_EMAIL'
       AND c.module_code=p_module_code AND c.event_code=p_event_code AND c.channel=v_channel
       AND c.invalidated_at IS NULL
       AND c.status IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY')
       AND c.manual_verification_status='CONFIRMED'
       AND c.manual_verified_at IS NOT NULL
       AND c.manual_verification_recipient IS NOT NULL
       AND c.trace_id IS NOT NULL
       AND coalesce(c.provider_message_id,'') <> ''
       AND c.execution_id IS NOT NULL
       AND c.message_id IS NOT NULL
       AND c.delivery_attempt_id IS NOT NULL
     ORDER BY coalesce(c.manual_verified_at, c.certified_at) DESC NULLS LAST
  LOOP
    SELECT * INTO v_eligible_exec FROM public.communication_controlled_live_execution
      WHERE id = v_cand.execution_id;
    IF NOT FOUND OR coalesce(v_eligible_exec.provider_call_attempted,false)=false THEN CONTINUE; END IF;
    SELECT * INTO v_eligible_grant FROM public.communication_controlled_live_grant
      WHERE execution_id = v_cand.execution_id ORDER BY issued_at DESC LIMIT 1;
    IF NOT FOUND OR v_eligible_grant.status <> 'CONSUMED' THEN CONTINUE; END IF;
    SELECT * INTO v_eligible_msg FROM public.communication_message WHERE id = v_cand.message_id;
    IF NOT FOUND OR lower(v_eligible_msg.status) NOT IN ('sent','delivered') THEN CONTINUE; END IF;
    SELECT * INTO v_eligible_att FROM public.communication_delivery_attempt
      WHERE id = v_cand.delivery_attempt_id;
    IF NOT FOUND
       OR lower(v_eligible_att.status) NOT IN ('success','delivered')
       OR coalesce(v_eligible_att.provider_call_attempted,false)=false THEN CONTINUE; END IF;
    v_eligible := v_cand;
    EXIT;
  END LOOP;

  -- Real-email gate
  SELECT * INTO v_gate FROM public.communication_hub_real_email_gate
    WHERE lower(trim(module_code))=lower(trim(p_module_code))
      AND lower(trim(event_code))=lower(trim(p_event_code))
      AND lower(trim(channel))=lower(trim(v_channel));

  -- Observations
  IF v_ec.id IS NOT NULL THEN
    SELECT count(*) INTO v_obs_count FROM public.communication_manual_production_observation
      WHERE event_certification_id=v_ec.id;
    SELECT * INTO v_latest_obs FROM public.communication_manual_production_observation
      WHERE event_certification_id=v_ec.id ORDER BY dispatched_at DESC LIMIT 1;
  END IF;

  -- Production-anchor ORE — resolved from the event certification, not from ordering.
  IF v_event_is_live AND v_ec.one_real_email_certification_id IS NOT NULL THEN
    SELECT * INTO v_anchor_ore FROM public.communication_controlled_live_certification
      WHERE id = v_ec.one_real_email_certification_id;
    IF FOUND THEN
      v_production_anchor := jsonb_build_object(
        'certification_id',            v_anchor_ore.id,
        'production_lineage_id',       v_anchor_ore.production_lineage_id,
        'status',                      v_anchor_ore.status,
        'manual_verification_status',  v_anchor_ore.manual_verification_status,
        'verified_at',                 v_anchor_ore.manual_verified_at,
        'provider_message_id',         v_anchor_ore.provider_message_id,
        'delivery_attempt_id',         v_anchor_ore.delivery_attempt_id,
        'trace_id',                    v_anchor_ore.trace_id,
        'execution_id',                v_anchor_ore.execution_id,
        'evidence_authority',          v_ec.evidence_authority
      );
    END IF;
  END IF;

  IF v_latest_confirmed.id IS NOT NULL THEN
    v_latest_candidate := jsonb_build_object(
      'certification_id',            v_latest_confirmed.id,
      'status',                      v_latest_confirmed.status,
      'manual_verification_status',  v_latest_confirmed.manual_verification_status,
      'verified_at',                 v_latest_confirmed.manual_verified_at,
      'production_lineage_id',       v_latest_confirmed.production_lineage_id,
      'bound_to_current_event_certification',
        (v_ec.one_real_email_certification_id IS NOT NULL
          AND v_ec.one_real_email_certification_id = v_latest_confirmed.id)
    );
  END IF;

  -- Readiness rows
  FOR v_readiness_row IN
    SELECT DISTINCT ON (check_code) *
      FROM public.comm_hub_automation_readiness_results
     WHERE module_code=p_module_code AND event_code=p_event_code AND channel=v_channel
       AND configuration_version = coalesce(v_settings.configuration_version,0)
     ORDER BY check_code, checked_at DESC
  LOOP
    v_readiness := v_readiness || jsonb_build_array(jsonb_build_object(
      'check_code', v_readiness_row.check_code, 'result', v_readiness_row.result,
      'source', v_readiness_row.source, 'evidence', v_readiness_row.evidence,
      'checked_at', v_readiness_row.checked_at, 'checked_by', v_readiness_row.checked_by,
      'expires_at', v_readiness_row.expires_at,
      'configuration_version', v_readiness_row.configuration_version,
      'fresh', v_readiness_row.expires_at > now()));
  END LOOP;

  IF jsonb_array_length(v_readiness) = 9 THEN
    v_ready_all := true;
    FOR v_r IN SELECT jsonb_array_elements(v_readiness) LOOP
      IF NOT coalesce((v_r->>'result')::boolean,false)
         OR NOT coalesce((v_r->>'fresh')::boolean,false) THEN
        v_ready_all := false;
      END IF;
    END LOOP;
  END IF;

  IF v_ec.id IS NULL OR v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    v_automated_eligible := false;
    v_automated_blockers := v_automated_blockers || jsonb_build_array(jsonb_build_object('code','MANUAL_CERT_MISSING'));
  END IF;
  IF v_ec.id IS NOT NULL AND v_ec.drift_detected_at IS NOT NULL THEN
    v_automated_eligible := false;
    v_automated_blockers := v_automated_blockers || jsonb_build_array(jsonb_build_object('code','DRIFT_DETECTED'));
  END IF;
  IF NOT v_ready_all THEN
    v_automated_eligible := false;
    v_automated_blockers := v_automated_blockers || jsonb_build_array(jsonb_build_object('code','READINESS_INCOMPLETE_OR_STALE'));
  END IF;
  IF v_obs_count < 1 OR v_latest_obs.inbox_confirmation_status IS DISTINCT FROM 'CONFIRMED' THEN
    v_automated_eligible := false;
    v_automated_blockers := v_automated_blockers || jsonb_build_array(jsonb_build_object('code','MANUAL_OBSERVATION_REQUIRED'));
  END IF;

  SELECT count(*) INTO v_eligible_manual FROM public.communication_hub_event_certification
    WHERE status IN ('live_manual_only','live_cron_allowed');
  SELECT count(*) INTO v_eligible_auto FROM public.communication_hub_event_certification
    WHERE status='live_cron_allowed';

  -- Stage 6 readiness & blockers (legacy path retained for pre-live behaviour)
  IF v_eligible.id IS NOT NULL THEN
    v_s6_ready := true;
    v_reconciliation_required := false;
  ELSE
    v_s6_ready := false;
    IF v_latest.id IS NULL THEN
      v_s6_blockers := v_s6_blockers || jsonb_build_array(jsonb_build_object(
        'code','CERTIFICATION_MISSING','message','No ONE_REAL_EMAIL certification exists for this event/channel.'));
    ELSE
      IF v_latest.invalidated_at IS NOT NULL THEN
        v_s6_blockers := v_s6_blockers || jsonb_build_array(jsonb_build_object(
          'code','CERTIFICATION_INVALIDATED','message','The most recent ONE_REAL_EMAIL certification has been invalidated.'));
      END IF;
      IF v_latest.status NOT IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY') THEN
        v_s6_blockers := v_s6_blockers || jsonb_build_array(jsonb_build_object(
          'code','ATTEMPT_NOT_SUCCESSFUL','message','Latest certification status is '||coalesce(v_latest.status,'unknown')||'.'));
      END IF;
      IF v_latest.trace_id IS NULL THEN
        v_s6_blockers := v_s6_blockers || jsonb_build_array(jsonb_build_object(
          'code','TRACE_MISSING','message','Trace not bound to the certification.'));
      END IF;
      IF coalesce(v_latest.provider_message_id,'') = '' THEN
        v_s6_blockers := v_s6_blockers || jsonb_build_array(jsonb_build_object(
          'code','PROVIDER_MESSAGE_ID_MISSING','message','Provider message id is missing.'));
      END IF;
      IF coalesce(v_latest.manual_verification_status,'') <> 'CONFIRMED' THEN
        v_s6_blockers := v_s6_blockers || jsonb_build_array(jsonb_build_object(
          'code','INBOX_CONFIRMATION_MISSING','message','Manual inbox confirmation is not recorded.'));
      END IF;
    END IF;
  END IF;

  -- ***** KEY RULE *****
  -- Once the event is certified live, Stage 6 is COMPLETE via the pinned
  -- production anchor. The "latest eligible" concept collapses to
  -- informational; a newer confirmed ORE never silently supersedes the
  -- production anchor and never resurfaces a Stage 6 blocker.
  IF v_event_is_live AND v_anchor_ore.id IS NOT NULL
     AND v_anchor_ore.manual_verification_status = 'CONFIRMED'
     AND v_anchor_ore.invalidated_at IS NULL
     AND v_anchor_ore.execution_id IS NOT NULL
     AND v_anchor_ore.message_id IS NOT NULL
     AND v_anchor_ore.delivery_attempt_id IS NOT NULL
     AND v_anchor_ore.trace_id IS NOT NULL
     AND coalesce(v_anchor_ore.provider_message_id,'') <> '' THEN
    v_s6_ready := true;
    v_reconciliation_required := false;
    v_s6_blockers := '[]'::jsonb;
  END IF;

  v_final_exec_id := COALESCE(v_anchor_ore.execution_id, v_eligible.execution_id, v_latest.execution_id);
  IF v_final_exec_id IS NOT NULL THEN
    SELECT provider_call_attempted INTO v_final_provider_call_attempted
      FROM public.communication_controlled_live_execution WHERE id = v_final_exec_id;
  END IF;

  RETURN jsonb_build_object(
    'module_code',p_module_code,'event_code',p_event_code,'channel',v_channel,
    'evaluated_at', now(),
    'stage6', jsonb_build_object(
       -- Legacy compatibility fields: when the event is live, these reflect
       -- the pinned production anchor, not the newest confirmed row.
       'one_real_email_execution_id', v_final_exec_id,
       'one_real_email_certification_id',
          COALESCE(v_anchor_ore.id, v_eligible.id, v_latest.id),
       'one_real_email_certification_status',
          COALESCE(v_anchor_ore.status, v_eligible.status, v_latest.status),
       'provider_call_attempted', v_final_provider_call_attempted,
       'provider_message_id',
          COALESCE(v_anchor_ore.provider_message_id, v_eligible.provider_message_id, v_latest.provider_message_id),
       'delivery_attempt_id',
          COALESCE(v_anchor_ore.delivery_attempt_id, v_eligible.delivery_attempt_id, v_latest.delivery_attempt_id),
       'trace_id',
          COALESCE(v_anchor_ore.trace_id, v_eligible.trace_id, v_latest.trace_id),
       'manual_verification_status',
          COALESCE(v_anchor_ore.manual_verification_status, v_eligible.manual_verification_status, v_latest.manual_verification_status),
       'manual_verified_recipient',
          COALESCE(v_anchor_ore.manual_verification_recipient, v_eligible.manual_verification_recipient, v_latest.manual_verification_recipient),
       'manual_verified_at',
          COALESCE(v_anchor_ore.manual_verified_at, v_eligible.manual_verified_at, v_latest.manual_verified_at),
       'reconciliation_required', v_reconciliation_required,
       'real_email_gate_enabled', coalesce(v_gate.enabled,false),
       'real_email_gate_id', v_gate.id,
       'latest_one_real_email_certification_id', v_latest.id,
       'latest_one_real_email_certification_status', v_latest.status,
       'eligible_one_real_email_certification_id', v_eligible.id,
       'eligible_one_real_email_certification_status', v_eligible.status,
       'stage6_ready_for_manual_production', v_s6_ready,
       'stage6_manual_production_blockers', v_s6_blockers,
       -- New authoritative split
       'event_is_live', v_event_is_live,
       'production_anchor', v_production_anchor,
       'latest_confirmed_candidate', v_latest_candidate
    ),
    'stage7', jsonb_build_object(
       'manual_event_certification_id', v_ec.id,
       'manual_event_status', v_ec.status,
       'manual_approved_at', v_ec.approved_at,
       'manual_approved_by', v_ec.approved_by,
       'manual_reason', v_ec.reason,
       'drift_detected', v_ec.drift_detected_at IS NOT NULL,
       'drift_reason', v_ec.drift_reason,
       'manual_observation_count', v_obs_count,
       'latest_manual_observation_id', v_latest_obs.id,
       'latest_manual_observation_message_id', v_latest_obs.message_id,
       'latest_manual_observation_attempt_id', v_latest_obs.delivery_attempt_id,
       'latest_manual_observation_trace_id', v_latest_obs.trace_id,
       'latest_manual_observation_status', v_latest_obs.status,
       'latest_manual_observation_inbox', v_latest_obs.inbox_confirmation_status,
       'real_email_gate_closed_at', v_ec.real_email_gate_closed_at
    ),
    'stage8', jsonb_build_object(
       'automation_event_certification_status', v_ec.status,
       'automation_certified_at', v_ec.automation_certified_at,
       'automation_certified_by', v_ec.automation_certified_by,
       'readiness_checks', v_readiness,
       'readiness_all_ok_and_fresh', v_ready_all,
       'automated_eligible', v_automated_eligible,
       'automated_blockers', v_automated_blockers
    ),
    'platform', jsonb_build_object(
       'current_operating_mode', v_settings.operating_mode,
       'configuration_version', v_settings.configuration_version,
       'automation_state', v_settings.automation_state,
       'scheduler_enabled', v_settings.scheduler_enabled,
       'automatic_triggers_enabled', v_settings.automatic_triggers_enabled,
       'retry_worker_enabled', v_settings.retry_worker_enabled,
       'batch_enabled', v_settings.batch_enabled,
       'bulk_enabled', v_settings.bulk_enabled,
       'dispatch_enabled', v_settings.dispatch_enabled,
       'eligible_manual_event_count', v_eligible_manual,
       'eligible_automated_event_count', v_eligible_auto
    ));
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_go_live_completion(p_module_code text, p_event_code text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_status jsonb;
  v_outcome text := 'INCOMPLETE';
  v_settings record;
  v_ec record;
  v_channel text := coalesce(p_channel,'email');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  v_status := public.get_comm_hub_event_go_live_status(p_module_code, p_event_code, v_channel);
  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';
  SELECT * INTO v_ec FROM public.communication_hub_event_certification
    WHERE module_code=p_module_code AND event_code=p_event_code AND channel=v_channel;

  IF NOT coalesce(v_settings.dispatch_enabled,false) THEN
    v_outcome := 'EMERGENCY_STOP';
  ELSIF v_ec.drift_detected_at IS NOT NULL THEN
    v_outcome := 'DRIFT_DETECTED';
  ELSIF v_ec.status = 'SUSPENDED' THEN
    v_outcome := 'SUSPENDED';
  ELSIF v_ec.status = 'live_cron_allowed' AND v_settings.operating_mode='AUTOMATED_PRODUCTION' AND v_settings.automation_state='ARMED' THEN
    v_outcome := 'LIVE_AUTOMATED_ARMED';
  ELSIF v_ec.status = 'live_cron_allowed' AND v_settings.operating_mode='AUTOMATED_PRODUCTION' THEN
    v_outcome := 'LIVE_AUTOMATED_STANDBY';
  ELSIF v_ec.status IN ('live_manual_only','live_cron_allowed') AND v_settings.operating_mode='MANUAL_PRODUCTION' THEN
    v_outcome := 'LIVE_MANUAL';
  ELSIF (v_status->'stage6'->>'one_real_email_certification_status') IS NOT NULL
        AND (v_status->'stage6'->>'manual_verification_status') = 'CONFIRMED' THEN
    v_outcome := 'STAGE_6_COMPLETE';
  END IF;

  RETURN jsonb_build_object(
    'outcome', v_outcome,
    'is_stage9_complete', v_outcome IN ('LIVE_MANUAL','LIVE_AUTOMATED_ARMED'),
    'status', v_status,
    'evaluated_at', now());
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_go_live_gate_snapshot(p_module_code text, p_event_code text, p_channel text, p_preview_snapshot_id uuid DEFAULT NULL::uuid, p_preview_approval_id uuid DEFAULT NULL::uuid, p_dry_run_execution_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_evaluator_version constant text := 'comm-hub-go-live-gates/v1';
  v_actor uuid;
  v_role text;
  v_snap communication_preview_snapshot%ROWTYPE;
  v_appr communication_preview_approval%ROWTYPE;
  v_exec communication_dry_run_execution%ROWTYPE;
  v_gates jsonb := '[]'::jsonb;
  v_passed int := 0;
  v_total int := 0;
  v_first_blocker jsonb := NULL;
  v_overall text := 'CHECKING';
  v_correlation uuid;
  v_seq int := 0;
  v_delivery_attempts int := 0;
  v_cert_exists boolean := false;
BEGIN
  BEGIN
    v_actor := auth.uid();
    v_role := current_setting('request.jwt.claims', true)::jsonb->>'role';
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL; v_role := NULL;
  END;

  IF p_preview_snapshot_id IS NOT NULL THEN
    SELECT * INTO v_snap FROM communication_preview_snapshot WHERE id = p_preview_snapshot_id;
  END IF;
  IF p_preview_approval_id IS NOT NULL THEN
    SELECT * INTO v_appr FROM communication_preview_approval WHERE id = p_preview_approval_id;
  END IF;
  IF p_dry_run_execution_id IS NOT NULL THEN
    SELECT * INTO v_exec FROM communication_dry_run_execution WHERE id = p_dry_run_execution_id;
    v_cert_exists := v_exec.certification_id IS NOT NULL;
    IF v_exec.request_id IS NOT NULL THEN
      SELECT count(*) INTO v_delivery_attempts
       FROM communication_delivery_attempt da
       JOIN communication_message m ON m.id = da.message_id
      WHERE m.request_id = v_exec.request_id;
    END IF;
  END IF;
  IF v_snap.id IS NOT NULL THEN v_correlation := v_snap.correlation_id; END IF;

  -- 1. ACCESS: browser session
  v_seq := v_seq + 1; v_total := v_total + 1;
  v_gates := v_gates || jsonb_build_array(jsonb_build_object(
    'id','access.browser_session','group','ACCESS','name','Browser session available','sequence',v_seq,
    'status', CASE WHEN v_actor IS NOT NULL THEN 'PASSED' ELSE 'NOT_STARTED' END,
    'summary', CASE WHEN v_actor IS NOT NULL THEN 'A browser session is available.' ELSE 'Sign in to begin.' END,
    'action', jsonb_build_object('kind', CASE WHEN v_actor IS NOT NULL THEN 'NO_ACTION_REQUIRED' ELSE 'SIGN_IN_AGAIN' END,'label', CASE WHEN v_actor IS NOT NULL THEN 'No action required' ELSE 'Sign in again' END,'route',NULL),
    'source', jsonb_build_object('layer','BROWSER','function','getActionReadySession','evaluator_version',v_evaluator_version,'checked_at',v_now)
  ));
  IF v_actor IS NOT NULL THEN v_passed := v_passed + 1; END IF;

  -- 1b. ACCESS: postgrest operator identity
  v_seq := v_seq + 1; v_total := v_total + 1;
  v_gates := v_gates || jsonb_build_array(jsonb_build_object(
    'id','access.postgrest_operator','group','ACCESS','name','PostgREST operator identity','sequence',v_seq,
    'status', CASE WHEN v_actor IS NOT NULL AND v_role = 'authenticated' THEN 'PASSED' ELSE 'BLOCKED' END,
    'summary', CASE WHEN v_actor IS NOT NULL AND v_role = 'authenticated' THEN 'The database identified the signed-in operator.' ELSE 'The database could not identify the signed-in operator.' END,
    'why_it_blocks','Dry Run runtime transitions require a server-derived operator.',
    'current_value', COALESCE(v_actor::text,'No actor derived'),
    'required_value','Authenticated operator identity',
    'blocker_codes', CASE WHEN v_actor IS NULL OR v_role IS DISTINCT FROM 'authenticated' THEN jsonb_build_array('OPERATOR_JWT_NOT_PROPAGATED_TO_POSTGREST') ELSE '[]'::jsonb END,
    'action', CASE WHEN v_actor IS NULL OR v_role IS DISTINCT FROM 'authenticated'
      THEN jsonb_build_object('kind','PLATFORM_FIX','label','Platform JWT propagation fix required','route',NULL)
      ELSE jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL) END,
    'retry_safe', true, 'mutation_started', false,
    'source', jsonb_build_object('layer','EDGE_OPERATOR_PROBE','function','probe_comm_hub_operator_identity','evaluator_version',v_evaluator_version,'checked_at',v_now)
  ));
  IF v_actor IS NOT NULL AND v_role = 'authenticated' THEN v_passed := v_passed + 1; END IF;

  -- 2. EVENT SETUP
  v_seq := v_seq + 1; v_total := v_total + 1;
  DECLARE v_event_registered boolean;
  BEGIN
    SELECT EXISTS (SELECT 1 FROM communication_hub_module_event_registry WHERE module_code = p_module_code AND event_code = p_event_code) INTO v_event_registered;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'id','setup.module_event_registered','group','EVENT_SETUP','name','Module/event registered','sequence',v_seq,
      'status', CASE WHEN p_module_code IS NULL OR p_event_code IS NULL THEN 'NOT_STARTED' WHEN v_event_registered THEN 'PASSED' ELSE 'BLOCKED' END,
      'summary', CASE WHEN v_event_registered THEN 'Event is registered.' ELSE 'Event is not registered.' END,
      'action', CASE WHEN v_event_registered THEN jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL) ELSE jsonb_build_object('kind','OPEN_TEMPLATE_CONTRACT','label','Register module/event','route','/admin/communication-hub/design') END,
      'blocker_codes', CASE WHEN v_event_registered THEN '[]'::jsonb ELSE jsonb_build_array('MODULE_EVENT_NOT_REGISTERED') END,
      'source', jsonb_build_object('layer','DB','function','communication_hub_module_event_registry','evaluator_version',v_evaluator_version,'checked_at',v_now)
    ));
    IF v_event_registered THEN v_passed := v_passed + 1; END IF;
  END;

  -- 3. PREVIEW
  v_seq := v_seq + 1; v_total := v_total + 1;
  DECLARE v_status text; v_summary text; v_blockers jsonb := '[]'::jsonb;
  BEGIN
    IF v_snap.id IS NULL THEN
      v_status := 'NOT_STARTED'; v_summary := 'No Preview snapshot prepared for this attempt.';
    ELSIF v_snap.status IN ('EXPIRED','SUPERSEDED','REVOKED') THEN
      v_status := v_snap.status; v_summary := 'Preview snapshot is ' || lower(v_snap.status) || '.';
      v_blockers := jsonb_build_array('PREVIEW_SNAPSHOT_' || v_snap.status);
    ELSIF v_snap.status = 'PREPARED' AND COALESCE(jsonb_array_length(v_snap.unresolved_variables),0) = 0
      AND COALESCE(v_snap.raw_placeholder_count,0) = 0 AND v_snap.content_hash IS NOT NULL AND v_snap.recipient_set_hash IS NOT NULL THEN
      v_status := 'PASSED'; v_summary := 'Preview snapshot is prepared with zero unresolved variables.';
    ELSE
      v_status := 'BLOCKED'; v_summary := 'Preview snapshot has unresolved variables or missing hashes.';
      IF COALESCE(jsonb_array_length(v_snap.unresolved_variables),0) > 0 THEN v_blockers := v_blockers || jsonb_build_array('RESOLVER_REQUIRED_UNRESOLVED'); END IF;
      IF COALESCE(v_snap.raw_placeholder_count,0) > 0 THEN v_blockers := v_blockers || jsonb_build_array('RAW_PLACEHOLDERS_PRESENT'); END IF;
    END IF;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'id','preview.snapshot','group','PREVIEW','name','Preview snapshot ready','sequence',v_seq,
      'status',v_status,'summary',v_summary,'blocker_codes',v_blockers,
      'action', CASE WHEN v_status = 'PASSED' THEN jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL)
        ELSE jsonb_build_object('kind','CREATE_FRESH_PREVIEW','label','Create a fresh Preview','route',NULL) END,
      'current_value', COALESCE(v_snap.status,'—'), 'required_value','PREPARED with zero unresolved variables, populated content and recipient hashes',
      'source', jsonb_build_object('layer','DB','function','prepare_comm_hub_preview','evaluator_version',v_evaluator_version,'checked_at',v_now,'source_record_id',v_snap.id)
    ));
    IF v_status = 'PASSED' THEN v_passed := v_passed + 1; END IF;
  END;

  -- 4. APPROVAL
  v_seq := v_seq + 1; v_total := v_total + 1;
  DECLARE v_status text; v_summary text; v_blockers jsonb := '[]'::jsonb;
  BEGIN
    IF v_appr.id IS NULL THEN
      v_status := 'NOT_STARTED'; v_summary := 'No approval recorded for this Preview.';
    ELSIF v_snap.id IS NOT NULL AND v_appr.snapshot_id <> v_snap.id THEN
      v_status := 'SUPERSEDED'; v_summary := 'Approval does not belong to the current Preview.';
      v_blockers := jsonb_build_array('APPROVAL_SNAPSHOT_MISMATCH');
    ELSIF v_appr.expires_at IS NOT NULL AND v_appr.expires_at < v_now THEN
      v_status := 'EXPIRED'; v_summary := 'Approval has expired.'; v_blockers := jsonb_build_array('APPROVAL_EXPIRED');
    ELSIF v_appr.status = 'ACTIVE' THEN
      v_status := 'PASSED'; v_summary := 'Approval is active and bound to the current Preview.';
    ELSE
      v_status := 'BLOCKED'; v_summary := 'Approval is not active (status ' || COALESCE(v_appr.status,'unknown') || ').';
      v_blockers := jsonb_build_array('APPROVAL_NOT_ACTIVE');
    END IF;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'id','approval.active','group','APPROVAL','name','Approval active and bound to Preview','sequence',v_seq,
      'status',v_status,'summary',v_summary,'blocker_codes',v_blockers,
      'action', CASE WHEN v_status = 'PASSED' THEN jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL)
        WHEN v_status IN ('EXPIRED','SUPERSEDED') THEN jsonb_build_object('kind','CREATE_FRESH_PREVIEW','label','Create a fresh Preview','route',NULL)
        WHEN v_status = 'NOT_STARTED' THEN jsonb_build_object('kind','APPROVE_PREVIEW','label','Approve the current Preview','route',NULL)
        ELSE jsonb_build_object('kind','APPROVE_PREVIEW','label','Approve the Preview','route',NULL) END,
      'current_value', COALESCE(v_appr.status,'—'), 'required_value','ACTIVE, unexpired, bound to selected Preview',
      'source', jsonb_build_object('layer','DB','function','approve_comm_hub_preview','evaluator_version',v_evaluator_version,'checked_at',v_now,'source_record_id',v_appr.id)
    ));
    IF v_status = 'PASSED' THEN v_passed := v_passed + 1; END IF;
  END;

  -- 5. DRY-RUN READINESS
  v_seq := v_seq + 1; v_total := v_total + 1;
  DECLARE v_status text; v_summary text;
  BEGIN
    IF v_appr.id IS NULL OR v_appr.status <> 'ACTIVE' THEN
      v_status := 'NOT_STARTED'; v_summary := 'Approve a Preview to enable readiness evaluation.';
    ELSIF v_snap.id IS NOT NULL AND v_snap.recipient_set_hash IS NOT NULL AND v_correlation IS NOT NULL THEN
      v_status := 'PASSED'; v_summary := 'Recipient hash and correlation available; preflight can run.';
    ELSE
      v_status := 'BLOCKED'; v_summary := 'Missing recipient hash or correlation for preflight.';
    END IF;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'id','readiness.preflight','group','DRY_RUN_READINESS','name','Dry-run preflight ready','sequence',v_seq,
      'status',v_status,'summary',v_summary,
      'action', CASE WHEN v_status = 'PASSED' THEN jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL)
        ELSE jsonb_build_object('kind','RECHECK_READINESS','label','Re-check readiness','route',NULL) END,
      'source', jsonb_build_object('layer','DB','function','inspect_comm_hub_dry_run_preflight','evaluator_version',v_evaluator_version,'checked_at',v_now)
    ));
    IF v_status = 'PASSED' THEN v_passed := v_passed + 1; END IF;
  END;

  -- 6. PLATFORM SERVICE
  v_seq := v_seq + 1; v_total := v_total + 1;
  v_gates := v_gates || jsonb_build_array(jsonb_build_object(
    'id','service.role_probe','group','PLATFORM_SERVICE','name','Service-role positive probe','sequence',v_seq,
    'status', CASE WHEN v_exec.id IS NOT NULL THEN 'PASSED' ELSE 'NOT_STARTED' END,
    'summary', CASE WHEN v_exec.id IS NOT NULL THEN 'Service-role probe passed (execution reached ' || v_exec.state || ').' ELSE 'Not yet exercised — begin a Dry Run to probe.' END,
    'action', jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL),
    'source', jsonb_build_object('layer','EDGE','function','probe_comm_hub_dry_run_service_identity','evaluator_version',v_evaluator_version,'checked_at',v_now)
  ));
  IF v_exec.id IS NOT NULL THEN v_passed := v_passed + 1; END IF;

  -- 7. DRY-RUN PROCESSING
  v_seq := v_seq + 1; v_total := v_total + 1;
  DECLARE v_status text; v_summary text;
  BEGIN
    IF v_exec.id IS NULL THEN v_status := 'NOT_STARTED'; v_summary := 'No Dry Run execution created yet.';
    ELSIF v_exec.state IN ('PROCESSED','CERTIFIED') THEN v_status := 'PASSED'; v_summary := 'Execution reached ' || v_exec.state || '.';
    ELSIF v_exec.state IN ('FAILED','BLOCKED') THEN v_status := 'BLOCKED'; v_summary := 'Execution failed at stage ' || COALESCE(v_exec.failure_stage,'unknown') || '.';
    ELSE v_status := 'CHECKING'; v_summary := 'Execution in progress (state ' || v_exec.state || ').';
    END IF;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'id','processing.execution','group','DRY_RUN_PROCESSING','name','Execution reached PROCESSED','sequence',v_seq,
      'status',v_status,'summary',v_summary,
      'current_value', COALESCE(v_exec.state,'—'), 'required_value','PROCESSED or CERTIFIED',
      'blocker_codes', COALESCE(v_exec.blockers,'[]'::jsonb),
      'action', CASE WHEN v_status = 'BLOCKED' THEN jsonb_build_object('kind','RESUME_EXISTING_EXECUTION','label','Investigate failed execution','route',NULL)
        ELSE jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL) END,
      'source', jsonb_build_object('layer','DB','function','process_comm_hub_dry_run_execution','evaluator_version',v_evaluator_version,'checked_at',v_now,'source_record_id',v_exec.id)
    ));
    IF v_status = 'PASSED' THEN v_passed := v_passed + 1; END IF;
  END;

  -- 8. CERTIFICATION
  v_seq := v_seq + 1; v_total := v_total + 1;
  DECLARE v_status text; v_summary text;
  BEGIN
    IF v_exec.id IS NULL OR v_exec.state NOT IN ('PROCESSED','CERTIFIED') THEN
      v_status := 'NOT_STARTED'; v_summary := 'Certification runs after execution is PROCESSED.';
    ELSIF v_cert_exists AND v_delivery_attempts = 0 THEN
      v_status := 'PASSED'; v_summary := 'Certification linked; zero delivery attempts, provider or simulator calls.';
    ELSIF v_delivery_attempts > 0 THEN
      v_status := 'BLOCKED'; v_summary := 'Delivery attempts detected (' || v_delivery_attempts || ') — Dry Run must remain non-sending.';
    ELSE
      v_status := 'CHECKING'; v_summary := 'Certification pending.';
    END IF;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'id','certification.completed','group','CERTIFICATION','name','Certification completed','sequence',v_seq,
      'status',v_status,'summary',v_summary,
      'action', CASE WHEN v_status = 'BLOCKED' THEN jsonb_build_object('kind','CONTACT_PLATFORM_ADMIN','label','Contact platform admin','route',NULL)
        ELSE jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL) END,
      'source', jsonb_build_object('layer','DB','function','certify_comm_hub_dry_run','evaluator_version',v_evaluator_version,'checked_at',v_now,'source_record_id',v_exec.certification_id)
    ));
    IF v_status = 'PASSED' THEN v_passed := v_passed + 1; END IF;
  END;

  SELECT to_jsonb(g) INTO v_first_blocker
  FROM jsonb_array_elements(v_gates) WITH ORDINALITY AS t(g, ord)
  WHERE (g->>'status') IN ('BLOCKED','EXPIRED','SUPERSEDED')
  ORDER BY (g->>'sequence')::int LIMIT 1;

  IF v_first_blocker IS NOT NULL THEN v_overall := 'BLOCKED';
  ELSIF v_passed = v_total THEN v_overall := 'PASSED';
  ELSIF EXISTS (SELECT 1 FROM jsonb_array_elements(v_gates) e WHERE e->>'status' = 'CHECKING') THEN v_overall := 'CHECKING';
  ELSE v_overall := 'NOT_STARTED';
  END IF;

  RETURN jsonb_build_object(
    'snapshot_version', v_evaluator_version, 'evaluated_at', v_now,
    'module_code', p_module_code, 'event_code', p_event_code, 'channel', p_channel,
    'correlation_id', v_correlation, 'current_attempt_id', p_dry_run_execution_id,
    'preview_snapshot_id', p_preview_snapshot_id, 'preview_approval_id', p_preview_approval_id,
    'dry_run_execution_id', p_dry_run_execution_id,
    'overall_status', v_overall, 'passed_gate_count', v_passed, 'total_gate_count', v_total,
    'first_blocking_gate_id', v_first_blocker->>'id',
    'recommended_action', COALESCE(v_first_blocker->'action', jsonb_build_object('kind','NO_ACTION_REQUIRED','label','No action required','route',NULL)),
    'gates', v_gates
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_live_window_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings record;
  v_outside int := 0;
  v_inside int := 0;
  v_preview jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.has_role(auth.uid(), 'Admin'::app_role) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  SELECT dispatch_enabled, dry_run_only, email_live_enabled,
         live_eligible_after, live_eligible_max_age_minutes
    INTO v_settings
    FROM public.communication_hub_control_settings
    ORDER BY created_at ASC
    LIMIT 1;

  SELECT COUNT(*) INTO v_inside
    FROM public.communication_message
    WHERE origin = 'comm_hub' AND channel = 'email' AND status = 'queued'
      AND test_mode IS FALSE
      AND v_settings.live_eligible_after IS NOT NULL
      AND created_at >= v_settings.live_eligible_after
      AND created_at >= now() - make_interval(mins => v_settings.live_eligible_max_age_minutes);

  SELECT COUNT(*) INTO v_outside
    FROM public.communication_message
    WHERE origin = 'comm_hub' AND channel = 'email' AND status = 'queued'
      AND test_mode IS FALSE
      AND (
        v_settings.live_eligible_after IS NULL
        OR created_at < v_settings.live_eligible_after
        OR created_at < now() - make_interval(mins => v_settings.live_eligible_max_age_minutes)
      );

  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_preview
  FROM (
    SELECT m.id,
           r.request_no,
           m.created_at,
           m.status,
           m.test_mode,
           m.subject,
           CASE
             WHEN rc.email IS NULL THEN NULL
             ELSE regexp_replace(rc.email, '^(.{1,2}).*(@.*)$', '\1***\2')
           END AS recipient_masked,
           'Outside current live eligibility window' AS reason
    FROM public.communication_message m
    LEFT JOIN public.communication_request r ON r.id = m.request_id
    LEFT JOIN public.communication_recipient rc ON rc.id = m.recipient_id
    WHERE m.origin = 'comm_hub' AND m.channel = 'email' AND m.status = 'queued'
      AND m.test_mode IS FALSE
      AND (
        v_settings.live_eligible_after IS NULL
        OR m.created_at < v_settings.live_eligible_after
        OR m.created_at < now() - make_interval(mins => v_settings.live_eligible_max_age_minutes)
      )
    ORDER BY m.created_at DESC
    LIMIT 50
  ) t;

  RETURN jsonb_build_object(
    'live_eligible_after', v_settings.live_eligible_after,
    'live_eligible_max_age_minutes', v_settings.live_eligible_max_age_minutes,
    'db_dispatch_enabled', v_settings.dispatch_enabled,
    'db_dry_run_only', v_settings.dry_run_only,
    'db_email_live_enabled', v_settings.email_live_enabled,
    'queued_live_inside_window', v_inside,
    'queued_live_outside_window', v_outside,
    'outside_window_preview', v_preview,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_manual_production_evidence(p_observation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.v_comm_hub_manual_production_evidence%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'authentication_required');
  END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_comm_hub_admin');
  END IF;
  SELECT * INTO v_row FROM public.v_comm_hub_manual_production_evidence
    WHERE observation_id = p_observation_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'observation_not_found');
  END IF;
  RETURN jsonb_build_object('ok', true, 'evidence', to_jsonb(v_row));
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_module_automation_setting(p_module_code text, p_setting_key text, p_environment_scope text DEFAULT 'production'::text)
 RETURNS communication_hub_module_automation_setting
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT *
  FROM public.communication_hub_module_automation_setting
  WHERE module_code = p_module_code
    AND setting_key = p_setting_key
    AND environment_scope = COALESCE(p_environment_scope, 'production')
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_observation_recovery(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_intent public.communication_manual_production_observation_intent%ROWTYPE;
  v_obs public.communication_manual_production_observation%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_intent FROM public.communication_manual_production_observation_intent
   WHERE module_code=p_module_code AND event_code=p_event_code
     AND channel=coalesce(p_channel,'email')
     AND phase IN ('ENQUEUED','AWAITING_PROVIDER','AWAITING_INBOX_CONFIRMATION')
   ORDER BY created_at DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',true,'has_pending',false);
  END IF;

  IF v_intent.finalized_observation_id IS NOT NULL THEN
    SELECT * INTO v_obs FROM public.communication_manual_production_observation
      WHERE id = v_intent.finalized_observation_id;
  END IF;

  RETURN jsonb_build_object('ok',true,'has_pending',true,
    'idempotency_key', v_intent.idempotency_key,
    'phase', v_intent.phase,
    'message_id', v_intent.message_id,
    'request_id', v_intent.request_id,
    'observation_id', v_obs.id,
    'inbox_confirmation_status', v_obs.inbox_confirmation_status,
    'recipient_email', v_intent.recipient_email,
    'created_at', v_intent.created_at);
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_one_real_email_context(p_module_code text, p_event_code text, p_channel text, p_controlled_stub_certification_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ch  text := coalesce(p_channel,'email');
  v_cert record;
  v_exec record;
  v_snap record;
  v_sender record;
  v_provider record;
  v_gate  record;
  v_settings record;
  v_blockers jsonb := '[]'::jsonb;
  v_gate_module  text := public.comm_hub_normalize_gate_key(p_module_code);
  v_gate_event   text := public.comm_hub_normalize_gate_key(p_event_code);
  v_gate_channel text := public.comm_hub_normalize_gate_key(v_ch);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF p_module_code IS NULL OR p_event_code IS NULL OR p_controlled_stub_certification_id IS NULL THEN
    RAISE EXCEPTION 'module_event_and_certification_required';
  END IF;

  SELECT * INTO v_cert
    FROM public.communication_controlled_live_certification
   WHERE id = p_controlled_stub_certification_id;

  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','certification_missing','message','Controlled Stub certification not found'));
  ELSE
    IF v_cert.certification_kind <> 'CONTROLLED_STUB' THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','wrong_certification_kind','message','Certification is not CONTROLLED_STUB'));
    END IF;
    IF v_cert.invalidated_at IS NOT NULL THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','certification_invalidated','message','Controlled Stub certification has been invalidated'));
    END IF;
    IF v_cert.module_code <> p_module_code OR v_cert.event_code <> p_event_code OR v_cert.channel <> v_ch THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','certification_lineage_mismatch','message','Certification does not match module/event/channel'));
    END IF;
  END IF;

  IF v_cert.execution_id IS NOT NULL THEN
    SELECT * INTO v_exec
      FROM public.communication_controlled_live_execution
     WHERE id = v_cert.execution_id;
    IF NOT FOUND THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','execution_missing','message','Certification execution row missing'));
    END IF;
  END IF;

  IF v_cert.preview_snapshot_id IS NOT NULL THEN
    SELECT * INTO v_snap
      FROM public.communication_preview_snapshot
     WHERE id = v_cert.preview_snapshot_id;
    IF FOUND AND v_snap.sender_profile_id IS NOT NULL THEN
      SELECT * INTO v_sender
        FROM public.communication_hub_sender_profile
       WHERE id = v_snap.sender_profile_id;
      IF NOT FOUND THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','sender_profile_missing','message','Sender profile not found'));
      ELSIF coalesce(v_sender.is_enabled, false) = false THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','sender_profile_disabled','message','Sender profile is not enabled'));
      ELSIF btrim(coalesce(v_sender.from_email,'')) = '' OR btrim(coalesce(v_sender.display_name,'')) = '' THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','sender_profile_incomplete','message','Sender profile missing display_name or from_email'));
      END IF;
    ELSE
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','sender_lineage_missing','message','Snapshot did not resolve a sender profile'));
    END IF;
  ELSE
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','preview_snapshot_missing','message','Certification has no preview snapshot'));
  END IF;

  SELECT * INTO v_provider
    FROM public.notification_providers
   WHERE channel = 'email'::notification_channel
     AND is_active = true
     AND is_default = true
   ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','no_active_real_provider','message','No active default email provider is configured'));
  ELSIF lower(coalesce(v_provider.provider_name,'')) = 'provider_stub' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code','provider_is_stub','message','Configured provider is provider_stub and cannot be used for Stage 6'));
  END IF;

  -- Gate lookup: normalised keys only
  SELECT * INTO v_gate
    FROM public.communication_hub_real_email_gate
   WHERE public.comm_hub_normalize_gate_key(module_code) = v_gate_module
     AND public.comm_hub_normalize_gate_key(event_code)  = v_gate_event
     AND public.comm_hub_normalize_gate_key(channel)     = v_gate_channel
   LIMIT 1;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings LIMIT 1;

  RETURN jsonb_build_object(
    'ok', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'module_code', p_module_code,
    'event_code', p_event_code,
    'channel', v_ch,
    'recipient', v_exec.recipient,
    'recipient_set_hash', v_cert.recipient_set_hash,
    'configuration_version', v_cert.configuration_version,
    'recipient_policy_version', v_cert.recipient_policy_version,
    'preview_snapshot_id', v_cert.preview_snapshot_id,
    'preview_approval_id', v_cert.preview_approval_id,
    'dry_run_certification_id', v_cert.dry_run_certification_id,
    'controlled_stub_certification_id', p_controlled_stub_certification_id,
    'sender_profile_id', v_snap.sender_profile_id,
    'sender_name', v_sender.display_name,
    'sender_address', v_sender.from_email,
    'provider_id', v_provider.id,
    'provider_name', v_provider.provider_name,
    'provider_health', CASE WHEN v_provider.id IS NULL THEN 'MISSING'
                            WHEN lower(coalesce(v_provider.provider_name,'')) = 'provider_stub' THEN 'STUB'
                            ELSE 'READY' END,
    'operating_mode', v_settings.operating_mode,
    'real_email_gate_enabled', coalesce(v_gate.enabled, false),
    'real_email_gate_opened_by', v_gate.opened_by,
    'real_email_gate_opened_at', v_gate.opened_at,
    -- matched gate evidence
    'gate_id', v_gate.id,
    'gate_enabled', coalesce(v_gate.enabled, false),
    'gate_module_code', v_gate.module_code,
    'gate_event_code', v_gate.event_code,
    'gate_channel', v_gate.channel,
    'gate_opened_at', v_gate.opened_at,
    'evaluated_at', now()
  );
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_one_real_email_recovery_status(p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exec public.communication_controlled_live_execution%ROWTYPE;
  v_grant public.communication_controlled_live_grant%ROWTYPE;
  v_msg_status text;
  v_attempt_id uuid;
  v_attempt_status text;
  v_cert record;
  v_blockers jsonb := '[]'::jsonb;
  v_can_resume boolean := false;
BEGIN
  IF p_execution_id IS NULL THEN
    RETURN jsonb_build_object(
      'execution_id', NULL,
      'can_resume', false,
      'blockers', jsonb_build_array(jsonb_build_object(
        'code','execution_id_required','stage','input','message','execution_id is required')));
  END IF;

  SELECT * INTO v_exec FROM public.communication_controlled_live_execution
   WHERE id = p_execution_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'execution_id', p_execution_id,
      'can_resume', false,
      'blockers', jsonb_build_array(jsonb_build_object(
        'code','execution_not_found','stage','lookup','message','no execution row found')));
  END IF;

  SELECT * INTO v_grant FROM public.communication_controlled_live_grant
   WHERE execution_id = p_execution_id
   ORDER BY created_at DESC NULLS LAST LIMIT 1;

  IF v_exec.message_id IS NOT NULL THEN
    SELECT status::text INTO v_msg_status FROM public.communication_message
     WHERE id = v_exec.message_id;
    SELECT id, status::text INTO v_attempt_id, v_attempt_status
      FROM public.communication_delivery_attempt
     WHERE message_id = v_exec.message_id
     ORDER BY created_at DESC NULLS LAST LIMIT 1;
  END IF;

  SELECT * INTO v_cert
    FROM public.communication_controlled_live_certification
   WHERE execution_id = p_execution_id
     AND certification_kind = 'ONE_REAL_EMAIL';

  -- Determine can_resume + blockers
  IF FOUND THEN
    v_can_resume := false;  -- already certified; treat as idempotent
  ELSE
    IF v_exec.provider_call_attempted IS NOT TRUE THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','provider_not_invoked','stage','precondition',
        'message','Provider was not invoked; recovery would require another send.');
    END IF;
    IF v_exec.send_context <> 'REAL_EMAIL' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','execution_not_real_email','stage','precondition',
        'message','Execution send_context is not REAL_EMAIL.');
    END IF;
    IF v_exec.message_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','message_missing','stage','precondition',
        'message','Execution has no bound message_id.');
    END IF;
    IF v_msg_status IS NOT NULL AND v_msg_status NOT IN ('sent','failed') THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','message_not_terminal','stage','precondition',
        'message','Message status must be sent or failed.',
        'detail', v_msg_status);
    END IF;
    IF v_attempt_id IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','delivery_attempt_missing','stage','precondition',
        'message','No delivery attempt exists for the message.');
    END IF;
    v_can_resume := jsonb_array_length(v_blockers) = 0;
  END IF;

  RETURN jsonb_build_object(
    'execution_id', v_exec.id,
    'provider_call_attempted', v_exec.provider_call_attempted,
    'provider_message_id', v_exec.provider_message_id,
    'grant_id', v_grant.id,
    'grant_status', v_grant.status,
    'message_id', v_exec.message_id,
    'message_status', v_msg_status,
    'delivery_attempt_id', v_attempt_id,
    'attempt_status', v_attempt_status,
    'trace_id', v_exec.trace_id,
    'certification_id', v_cert.id,
    'certification_status', v_cert.status,
    'certification_kind', v_cert.certification_kind,
    'can_resume', v_can_resume,
    'blockers', v_blockers);
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_operations_summary(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_channel text := coalesce(p_channel, 'email');
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_ore public.communication_controlled_live_certification%ROWTYPE;
  v_stub public.communication_controlled_live_certification%ROWTYPE;
  v_dry public.communication_dry_run_certification%ROWTYPE;
  v_preview public.communication_preview_approval%ROWTYPE;
  v_cycle public.communication_hub_revalidation_cycle%ROWTYPE;
  v_stages jsonb := '[]'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_auth jsonb;
  v_prep jsonb;
  v_baseline_status text;
  v_next_action jsonb := NULL;
  v_recovery_required boolean := false;
  v_inbox_required boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_settings
    FROM public.communication_hub_control_settings
   WHERE singleton_guard = 'primary';

  SELECT * INTO v_ec
    FROM public.communication_hub_event_certification
   WHERE module_code = p_module_code AND event_code = p_event_code AND channel = v_channel;

  -- Actual evidence per stage (never inferred from later stages).
  SELECT * INTO v_preview FROM public.communication_preview_approval
    WHERE module_code = p_module_code AND event_code = p_event_code AND channel = v_channel
      AND invalidated_at IS NULL
    ORDER BY certified_at DESC NULLS LAST LIMIT 1;

  SELECT * INTO v_dry FROM public.communication_dry_run_certification
    WHERE module_code = p_module_code AND event_code = p_event_code AND channel = v_channel
      AND invalidated_at IS NULL
    ORDER BY certified_at DESC NULLS LAST LIMIT 1;

  SELECT * INTO v_stub FROM public.communication_controlled_live_certification
    WHERE certification_kind = 'CONTROLLED_STUB'
      AND module_code = p_module_code AND event_code = p_event_code AND channel = v_channel
      AND invalidated_at IS NULL
    ORDER BY certified_at DESC NULLS LAST LIMIT 1;

  SELECT * INTO v_ore FROM public.communication_controlled_live_certification
    WHERE certification_kind = 'ONE_REAL_EMAIL'
      AND module_code = p_module_code AND event_code = p_event_code AND channel = v_channel
      AND invalidated_at IS NULL
    ORDER BY certified_at DESC NULLS LAST LIMIT 1;

  -- Active revalidation cycle (single latest non-terminal row).
  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle
    WHERE module_code = p_module_code AND event_code = p_event_code AND channel = v_channel
      AND status NOT IN ('CONFIRMED','NOT_RECEIVED','FAILED','VOIDED','PROMOTED','SUPERSEDED','VERIFIED_SUPPLEMENTAL')
    ORDER BY started_at DESC LIMIT 1;

  -- Baseline status projection.
  IF v_ore.id IS NULL THEN
    v_baseline_status := 'UNAVAILABLE';
  ELSIF v_ec.id IS NOT NULL AND v_ec.one_real_email_certification_id = v_ore.id THEN
    v_baseline_status := 'ANCHORED';
  ELSE
    v_baseline_status := 'CANDIDATE_UNANCHORED';
  END IF;

  -- Stage array (8 canonical stages). No fabrication.
  v_stages := jsonb_build_array(
    jsonb_build_object('code','PREVIEW_APPROVAL',
      'status', CASE WHEN v_preview.id IS NOT NULL THEN 'COMPLETED' ELSE 'UNAVAILABLE' END,
      'certification_id', v_preview.id, 'execution_id', NULL,
      'completed_at', v_preview.certified_at,
      'evidence_source', 'communication_preview_approval',
      'blocker_codes', '[]'::jsonb),
    jsonb_build_object('code','DRY_RUN',
      'status', CASE WHEN v_dry.id IS NOT NULL THEN 'COMPLETED' ELSE 'UNAVAILABLE' END,
      'certification_id', v_dry.id, 'execution_id', NULL,
      'completed_at', v_dry.certified_at,
      'evidence_source','communication_dry_run_certification',
      'blocker_codes','[]'::jsonb),
    jsonb_build_object('code','CONTROLLED_STUB',
      'status', CASE WHEN v_stub.id IS NOT NULL THEN 'COMPLETED' ELSE 'UNAVAILABLE' END,
      'certification_id', v_stub.id, 'execution_id', v_stub.execution_id,
      'completed_at', v_stub.certified_at,
      'evidence_source','communication_controlled_live_certification[CONTROLLED_STUB]',
      'blocker_codes','[]'::jsonb),
    jsonb_build_object('code','ONE_REAL_EMAIL',
      'status', CASE
        WHEN v_ore.id IS NOT NULL AND v_ore.manual_verification_status='CONFIRMED' THEN 'COMPLETED'
        WHEN v_ore.id IS NOT NULL THEN 'IN_PROGRESS'
        ELSE 'UNAVAILABLE' END,
      'certification_id', v_ore.id, 'execution_id', v_ore.execution_id,
      'completed_at', v_ore.manual_verified_at,
      'evidence_source','communication_controlled_live_certification[ONE_REAL_EMAIL]',
      'blocker_codes','[]'::jsonb),
    jsonb_build_object('code','MANUAL_PRODUCTION',
      'status', CASE
        WHEN v_ec.id IS NOT NULL AND v_ec.status IN ('live_manual_only','live_cron_allowed') THEN 'COMPLETED'
        WHEN v_ec.id IS NOT NULL THEN v_ec.status
        ELSE 'UNAVAILABLE' END,
      'certification_id', v_ec.id, 'execution_id', NULL,
      'completed_at', v_ec.approved_at,
      'evidence_source','communication_hub_event_certification',
      'blocker_codes','[]'::jsonb),
    jsonb_build_object('code','AUTOMATED_PRODUCTION',
      'status', CASE
        WHEN v_ec.id IS NOT NULL AND v_ec.status='live_cron_allowed' THEN 'COMPLETED'
        WHEN v_ec.id IS NOT NULL AND v_ec.automation_certified_at IS NOT NULL THEN 'CERTIFIED_NOT_ARMED'
        ELSE 'UNAVAILABLE' END,
      'certification_id', v_ec.id, 'execution_id', NULL,
      'completed_at', v_ec.automation_certified_at,
      'evidence_source','communication_hub_event_certification',
      'blocker_codes','[]'::jsonb),
    jsonb_build_object('code','REVALIDATION',
      'status', CASE WHEN v_cycle.id IS NOT NULL THEN v_cycle.status ELSE 'IDLE' END,
      'certification_id', NULL, 'execution_id', NULL,
      'completed_at', v_cycle.completed_at,
      'evidence_source','communication_hub_revalidation_cycle',
      'blocker_codes','[]'::jsonb),
    jsonb_build_object('code','BASELINE_PROMOTION',
      'status', CASE
        WHEN v_cycle.id IS NOT NULL AND v_cycle.promotion_status='PROMOTED' THEN 'COMPLETED'
        WHEN v_cycle.id IS NOT NULL AND v_cycle.status='READY_FOR_PROMOTION' THEN 'AVAILABLE'
        ELSE 'IDLE' END,
      'certification_id', NULL, 'execution_id', NULL,
      'completed_at', v_cycle.promoted_at,
      'evidence_source','communication_hub_revalidation_cycle',
      'blocker_codes','[]'::jsonb)
  );

  -- Authorisation hydration (server-authoritative).
  BEGIN
    v_auth := public.get_comm_hub_active_revalidation_authorisation(p_module_code, p_event_code, v_channel);
  EXCEPTION WHEN OTHERS THEN
    v_auth := jsonb_build_object('authorisation', NULL, 'unusable_reason','authorisation_unavailable');
    v_warnings := v_warnings || jsonb_build_object('code','authorisation_unavailable','detail', SQLERRM);
  END;

  -- Preparation hydration.
  IF v_cycle.id IS NOT NULL THEN
    BEGIN
      v_prep := public.get_comm_hub_active_revalidation_preparation(v_cycle.id);
    EXCEPTION WHEN OTHERS THEN
      v_prep := jsonb_build_object('execution', NULL, 'unavailable_reason','execution_unavailable');
      v_warnings := v_warnings || jsonb_build_object('code','execution_unavailable','detail', SQLERRM);
    END;
  ELSE
    v_prep := jsonb_build_object('execution', NULL, 'unavailable_reason','no_cycle');
  END IF;

  v_recovery_required := (v_prep->'execution'->>'classified_state') = 'RECOVERY_REQUIRED'
                     OR (v_prep->'execution'->>'classified_state') = 'FAILED_PRE_PROVIDER';
  v_inbox_required := v_cycle.status = 'AWAITING_INBOX_CONFIRMATION';

  -- One next-action hint (never a directive).
  IF v_cycle.id IS NULL THEN
    v_next_action := jsonb_build_object('code','START_OR_ASSESS_REVALIDATION','label','Assess or start a revalidation cycle');
  ELSIF v_cycle.status = 'READY_FOR_CONTROLLED_EMAIL' AND (v_auth->'authorisation'->>'usable')::boolean IS DISTINCT FROM true THEN
    v_next_action := jsonb_build_object('code','ISSUE_AUTHORISATION','label','Issue one-use revalidation authorisation');
  ELSIF (v_auth->'authorisation'->>'usable')::boolean AND (v_prep->'execution') IS NULL THEN
    v_next_action := jsonb_build_object('code','PREPARE_CONTROLLED_DELIVERY','label','Prepare controlled delivery (no email sent)');
  ELSIF (v_prep->'execution'->>'classified_state') = 'READY_FOR_PROVIDER' THEN
    v_next_action := jsonb_build_object('code','PROVIDER_DELIVERY_LOCKED','label','Provider delivery locked until A4.2');
  ELSIF v_inbox_required THEN
    v_next_action := jsonb_build_object('code','CONFIRM_INBOX','label','Record inbox confirmation');
  ELSIF v_recovery_required THEN
    v_next_action := jsonb_build_object('code','RECOVER_PREPARATION','label','Recover preparation');
  END IF;

  RETURN jsonb_build_object(
    'evaluated_at', now(),
    'selection', jsonb_build_object(
      'module_code', p_module_code, 'event_code', p_event_code, 'channel', v_channel),
    'platform', jsonb_build_object(
      'operating_mode', coalesce(v_settings.current_operating_mode, 'UNKNOWN'),
      'automation_state', coalesce(v_settings.automation_state, 'STANDBY'),
      'dispatch_enabled', coalesce(v_settings.dispatch_enabled, false),
      'scheduler_enabled', coalesce(v_settings.scheduler_enabled, false),
      'provider_boundary_approved', coalesce(v_settings.provider_boundary_approved, false)
    ),
    'event', jsonb_build_object(
      'event_status', v_ec.status,
      'event_certification_id', v_ec.id,
      'ore_certification_id', v_ore.id,
      'production_lineage_id', v_ore.production_lineage_id,
      'evidence_authority', 'communication_hub_event_certification+communication_controlled_live_certification'
    ),
    'baseline', jsonb_build_object(
      'status', v_baseline_status,
      'attestation_id', NULL,
      'fingerprint', v_ore.evidence_fingerprint_v2,
      'diagnosis_required', (v_baseline_status = 'CANDIDATE_UNANCHORED'),
      'correction_required', false
    ),
    'stages', v_stages,
    'revalidation', jsonb_build_object(
      'active_cycle', CASE WHEN v_cycle.id IS NULL THEN NULL ELSE
        jsonb_build_object(
          'id', v_cycle.id,
          'status', v_cycle.status,
          'purpose', v_cycle.purpose,
          'reason', v_cycle.reason,
          'required_validation_level', v_cycle.required_validation_level,
          'required_stages', v_cycle.required_stages,
          'needs_reassessment', coalesce(v_cycle.needs_reassessment, false),
          'current_evidence_fingerprint_v2', v_cycle.current_evidence_fingerprint_v2,
          'recipient_email', v_cycle.recipient_email,
          'started_at', v_cycle.started_at
        ) END,
      'usable_authorisation', v_auth->'authorisation',
      'active_preparation_execution', v_prep->'execution',
      'recovery_required', v_recovery_required,
      'inbox_confirmation_required', v_inbox_required,
      'next_action', v_next_action
    ),
    'sources', jsonb_build_object(
      'event_status',        CASE WHEN v_ec.id     IS NULL THEN 'UNAVAILABLE' ELSE 'AVAILABLE' END,
      'baseline_status',     CASE WHEN v_ore.id    IS NULL THEN 'UNAVAILABLE' ELSE 'AVAILABLE' END,
      'revalidation_status', CASE WHEN v_cycle.id  IS NULL THEN 'IDLE'        ELSE 'AVAILABLE' END,
      'execution_status',    CASE WHEN (v_prep->'execution') IS NULL THEN 'UNAVAILABLE' ELSE 'AVAILABLE' END
    ),
    'blockers', v_blockers,
    'warnings', v_warnings
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_ore_evidence_snapshot(p_one_real_email_certification_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_ore   RECORD;
  v_exec  RECORD;
  v_msg   RECORD;
  v_att   RECORD;
  v_prov  RECORD;
  v_ctv   RECORD;
  v_evt_cert RECORD;
  v_blockers jsonb := '[]'::jsonb;
  v_missing  jsonb := '[]'::jsonb;
  v_template_manifest_hash text;
  v_snapshot jsonb;
  v_fingerprint text;
  v_complete text := 'COMPLETE';
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','UNAUTHENTICATED','component','actor')));
  END IF;
  SELECT has_role(v_actor, 'admin'::app_role) INTO v_is_admin;
  IF NOT COALESCE(v_is_admin, false) THEN
    RETURN jsonb_build_object('ok', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','NOT_ADMIN','component','actor')));
  END IF;

  SELECT * INTO v_ore FROM communication_controlled_live_certification
  WHERE id = p_one_real_email_certification_id;
  IF v_ore.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','ORE_CERT_NOT_FOUND','component','ore_certification')));
  END IF;
  IF v_ore.certification_kind IS DISTINCT FROM 'ONE_REAL_EMAIL' THEN
    RETURN jsonb_build_object('ok', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','NOT_ONE_REAL_EMAIL','component','ore_certification',
        'detail', v_ore.certification_kind)));
  END IF;

  -- Lineage validation
  SELECT * INTO v_exec FROM communication_controlled_live_execution WHERE id = v_ore.execution_id;
  IF v_exec.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','EXECUTION_MISSING','component','controlled_live_execution');
  END IF;

  SELECT * INTO v_msg FROM communication_message WHERE id = v_ore.message_id;
  IF v_msg.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','MESSAGE_MISSING','component','communication_message');
  END IF;

  SELECT * INTO v_att FROM communication_delivery_attempt WHERE id = v_ore.delivery_attempt_id;
  IF v_att.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','DELIVERY_ATTEMPT_MISSING','component','communication_delivery_attempt');
  ELSIF COALESCE(v_att.provider_call_attempted, false) = false THEN
    v_blockers := v_blockers || jsonb_build_object('code','PROVIDER_CALL_NOT_ATTEMPTED','component','communication_delivery_attempt');
  END IF;

  IF v_ore.provider_message_id IS NULL AND v_att.provider_message_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','PROVIDER_MESSAGE_ID_MISSING','component','delivery_attempt.provider_message_id');
  END IF;

  IF v_ore.manual_verification_status IS DISTINCT FROM 'CONFIRMED' THEN
    v_blockers := v_blockers || jsonb_build_object('code','INBOX_NOT_CONFIRMED','component','manual_verification_status',
      'detail', v_ore.manual_verification_status);
  END IF;

  IF jsonb_array_length(v_blockers) > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'snapshot_version', 2,
      'completeness_status', 'FAILED_LINEAGE',
      'production_lineage_id', v_ore.production_lineage_id,
      'blockers', v_blockers
    );
  END IF;

  -- Template manifest from the exact template version used by the message
  IF v_msg.template_version_id IS NOT NULL THEN
    SELECT * INTO v_ctv FROM core_template_version WHERE id = v_msg.template_version_id;
    IF v_ctv.id IS NOT NULL THEN
      v_template_manifest_hash := encode(extensions.digest(
        coalesce(v_ctv.subject,'') || '|' ||
        coalesce(v_ctv.body_html,'') || '|' ||
        coalesce(v_ctv.body_text,'') || '|' ||
        coalesce(v_ctv.layout_id::text,''), 'sha256'), 'hex');
    ELSE
      v_missing := v_missing || to_jsonb('template_version_manifest'::text);
      v_complete := 'INCOMPLETE';
    END IF;
  ELSE
    v_missing := v_missing || to_jsonb('template_version_id'::text);
    v_complete := 'INCOMPLETE';
  END IF;

  -- Provider used by the actual attempt (do NOT use current active provider)
  IF v_att.provider_id IS NOT NULL THEN
    SELECT * INTO v_prov FROM notification_providers WHERE id = v_att.provider_id;
  END IF;
  IF v_prov.id IS NULL THEN
    v_missing := v_missing || to_jsonb('provider_id_historical'::text);
    v_complete := 'INCOMPLETE';
  END IF;

  -- Historical send/review/payload policy version bindings are not persisted
  -- per execution in the current schema — record them as UNAVAILABLE so the
  -- backfill correctly marks INCOMPLETE without inventing a fingerprint value.
  v_missing := v_missing
    || to_jsonb('send_policy_version_binding'::text)
    || to_jsonb('review_policy_version_binding'::text)
    || to_jsonb('payload_schema_version_binding'::text);
  IF v_complete = 'COMPLETE' THEN v_complete := 'INCOMPLETE'; END IF;

  -- Event certification for lineage cross-link
  SELECT * INTO v_evt_cert FROM communication_hub_event_certification
  WHERE one_real_email_certification_id = v_ore.id;

  v_snapshot := jsonb_build_object(
    'module_code', _comm_hub_norm_code(v_ore.module_code),
    'event_code',  _comm_hub_norm_code(v_ore.event_code),
    'channel',     _comm_hub_norm_channel(v_ore.channel),
    'template_version_id', v_msg.template_version_id,
    'template_version_no', v_ctv.version_no,
    'template_manifest_hash', v_template_manifest_hash,
    'sender_profile_id', v_msg.sender_profile_id,
    'recipient_policy_version', v_ore.recipient_policy_version,
    'recipient_set_hash', v_msg.recipient_set_hash,
    'provider_id', v_att.provider_id,
    'provider_key', v_prov.email_provider_type,
    -- Historical policy hashes intentionally omitted (not bound per execution).
    'payload_schema_hash', NULL,
    'review_policy_hash', NULL,
    'send_policy_hash', NULL
  );

  -- Only compute a v2 fingerprint when snapshot is COMPLETE.
  IF v_complete = 'COMPLETE' THEN
    v_fingerprint := _comm_hub_fingerprint_evidence_snapshot_v2(v_snapshot);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_version', 2,
    'completeness_status', v_complete,
    'production_lineage_id', v_ore.production_lineage_id,
    'event_certification_id', v_evt_cert.id,
    'controlled_live_execution_id', v_ore.execution_id,
    'message_id', v_ore.message_id,
    'delivery_attempt_id', v_ore.delivery_attempt_id,
    'trace_id', v_ore.trace_id,
    'provider_message_id', COALESCE(v_ore.provider_message_id, v_att.provider_message_id),
    'resolved_at', now(),
    'snapshot', v_snapshot,
    'evidence_fingerprint_v2', v_fingerprint,
    'evidence_fingerprint_algorithm', CASE WHEN v_fingerprint IS NULL THEN NULL ELSE 'sha256-v2' END,
    'missing_components', v_missing,
    'blockers', '[]'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_production_lineage_diagnostic(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ec  public.communication_hub_event_certification%ROWTYPE;
  v_ore_by_evt public.communication_controlled_live_certification%ROWTYPE;
  v_stage6 public.communication_controlled_live_certification%ROWTYPE;
  v_latest public.communication_controlled_live_certification%ROWTYPE;
  v_obs public.communication_manual_production_observation%ROWTYPE;
  v_exec public.communication_controlled_live_execution%ROWTYPE;
  v_msg public.communication_message%ROWTYPE;
  v_att public.communication_delivery_attempt%ROWTYPE;
  v_provider public.notification_providers%ROWTYPE;
  v_cand public.communication_controlled_live_certification%ROWTYPE;
  v_s6_ok boolean;
  v_stage6_id uuid;
  v_ore_lineage uuid;
  v_evt_lineage uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE module_code = p_module_code AND event_code = p_event_code AND channel = coalesce(p_channel,'email');

  IF v_ec.id IS NOT NULL THEN
    SELECT * INTO v_ore_by_evt FROM public.communication_controlled_live_certification
     WHERE id = v_ec.one_real_email_certification_id;
  END IF;

  -- Reproduce Stage 6 eligibility ordering (from get_comm_hub_event_go_live_status)
  FOR v_cand IN
    SELECT c.* FROM public.communication_controlled_live_certification c
     WHERE c.certification_kind = 'ONE_REAL_EMAIL'
       AND c.module_code = p_module_code
       AND c.event_code  = p_event_code
       AND c.channel     = coalesce(p_channel,'email')
       AND c.invalidated_at IS NULL
       AND c.status IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY')
       AND c.manual_verification_status = 'CONFIRMED'
       AND c.manual_verified_at IS NOT NULL
       AND c.trace_id IS NOT NULL
       AND coalesce(c.provider_message_id,'') <> ''
       AND c.execution_id IS NOT NULL
       AND c.message_id IS NOT NULL
       AND c.delivery_attempt_id IS NOT NULL
     ORDER BY coalesce(c.manual_verified_at, c.certified_at) DESC NULLS LAST
  LOOP
    SELECT * INTO v_exec FROM public.communication_controlled_live_execution WHERE id = v_cand.execution_id;
    IF NOT FOUND OR coalesce(v_exec.provider_call_attempted, false) = false THEN CONTINUE; END IF;
    SELECT * INTO v_msg FROM public.communication_message WHERE id = v_cand.message_id;
    IF NOT FOUND OR lower(v_msg.status) NOT IN ('sent','delivered') THEN CONTINUE; END IF;
    SELECT * INTO v_att FROM public.communication_delivery_attempt WHERE id = v_cand.delivery_attempt_id;
    IF NOT FOUND OR lower(v_att.status) NOT IN ('success','delivered')
       OR coalesce(v_att.provider_call_attempted, false) = false THEN CONTINUE; END IF;
    v_stage6 := v_cand;
    EXIT;
  END LOOP;

  SELECT * INTO v_latest FROM public.communication_controlled_live_certification
   WHERE certification_kind='ONE_REAL_EMAIL' AND module_code=p_module_code
     AND event_code=p_event_code AND channel=coalesce(p_channel,'email')
   ORDER BY certified_at DESC NULLS LAST LIMIT 1;

  SELECT * INTO v_obs FROM public.communication_manual_production_observation
   WHERE module_code=p_module_code AND event_code=p_event_code
   ORDER BY created_at DESC LIMIT 1;

  IF v_ore_by_evt.id IS NOT NULL AND v_ore_by_evt.execution_id IS NOT NULL THEN
    SELECT * INTO v_exec FROM public.communication_controlled_live_execution WHERE id = v_ore_by_evt.execution_id;
    SELECT * INTO v_msg  FROM public.communication_message WHERE id = v_ore_by_evt.message_id;
    SELECT * INTO v_att  FROM public.communication_delivery_attempt WHERE id = v_ore_by_evt.delivery_attempt_id;
  END IF;

  -- Resolve provider by name for the event-anchored ORE
  IF v_ore_by_evt.id IS NOT NULL THEN
    SELECT * INTO v_provider FROM public.notification_providers
     WHERE channel = coalesce(p_channel,'email') AND upper(provider_name) = upper(coalesce(v_ore_by_evt.provider_name,''))
     LIMIT 1;
  END IF;

  v_stage6_id   := v_stage6.id;
  v_ore_lineage := v_ore_by_evt.production_lineage_id;
  v_evt_lineage := v_ec.production_lineage_id;
  v_s6_ok := v_stage6_id IS NOT NULL;

  RETURN jsonb_build_object(
    'ok', v_ec.id IS NOT NULL AND v_stage6_id IS NOT NULL
          AND v_stage6_id = v_ec.one_real_email_certification_id,
    'module_code', p_module_code,
    'event_code',  p_event_code,
    'channel',     coalesce(p_channel,'email'),
    'result',
      CASE
        WHEN v_ec.id IS NULL                                THEN 'EVENT_CERTIFICATION_MISSING'
        WHEN v_stage6_id IS NULL                            THEN 'STAGE6_ELIGIBLE_ORE_MISSING'
        WHEN v_stage6_id <> v_ec.one_real_email_certification_id THEN 'LINEAGE_ANCHOR_MISMATCH'
        ELSE 'LINEAGE_OK'
      END,
    'ids', jsonb_build_object(
      'stage6_eligible_ore_certification_id', v_stage6_id,
      'stage6_latest_ore_certification_id',   v_latest.id,
      'event_certification_id',               v_ec.id,
      'event_certification_ore_id',           v_ec.one_real_email_certification_id,
      'event_certification_production_lineage_id', v_evt_lineage,
      'ore_production_lineage_id',            v_ore_lineage,
      'manual_observation_id',                v_obs.id,
      'manual_observation_event_certification_id', v_obs.event_certification_id,
      'manual_observation_status',            v_obs.status,
      'controlled_live_execution_id',         v_ore_by_evt.execution_id,
      'message_id',                           v_ore_by_evt.message_id,
      'delivery_attempt_id',                  v_ore_by_evt.delivery_attempt_id,
      'provider_id',                          v_provider.id,
      'provider_name',                        v_ore_by_evt.provider_name,
      'provider_message_id',                  v_ore_by_evt.provider_message_id,
      'trace_id',                             v_ore_by_evt.trace_id
    ),
    'comparisons', jsonb_build_object(
      'stage6_ore_matches_event_certification',
        (v_stage6_id IS NOT NULL AND v_ec.id IS NOT NULL
          AND v_stage6_id = v_ec.one_real_email_certification_id),
      'event_certification_matches_manual_observation',
        (v_ec.id IS NOT NULL AND v_obs.event_certification_id IS NOT NULL
          AND v_obs.event_certification_id = v_ec.id),
      'ore_lineage_matches_event_lineage',
        (v_ore_lineage IS NOT NULL AND v_evt_lineage IS NOT NULL
          AND v_ore_lineage = v_evt_lineage),
      'execution_message_attempt_chain_valid',
        (v_ore_by_evt.execution_id IS NOT NULL
          AND v_ore_by_evt.message_id IS NOT NULL
          AND v_ore_by_evt.delivery_attempt_id IS NOT NULL
          AND v_ore_by_evt.trace_id IS NOT NULL
          AND coalesce(v_ore_by_evt.provider_message_id,'') <> '')
    ),
    'event_certification_status', v_ec.status,
    'evidence_authority',         v_ec.evidence_authority,
    'ore_fingerprint_backfill_status', v_ore_by_evt.fingerprint_backfill_status
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_real_email_gate(p_module text, p_event text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_km text := public.comm_hub_normalize_gate_key(p_module);
  v_ke text := public.comm_hub_normalize_gate_key(p_event);
  v_kc text := public.comm_hub_normalize_gate_key(coalesce(nullif(p_channel,''),'email'));
  v_row public.communication_hub_real_email_gate%ROWTYPE;
  v_found boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF v_km = '' OR v_ke = '' THEN RAISE EXCEPTION 'module_and_event_required'; END IF;

  SELECT * INTO v_row
    FROM public.communication_hub_real_email_gate
   WHERE public.comm_hub_normalize_gate_key(module_code) = v_km
     AND public.comm_hub_normalize_gate_key(event_code)  = v_ke
     AND public.comm_hub_normalize_gate_key(channel)     = v_kc
   LIMIT 1;
  v_found := FOUND;

  RETURN jsonb_build_object(
    'ok', true,
    'present', v_found,
    'gate', CASE WHEN v_found THEN to_jsonb(v_row) ELSE NULL END,
    'requested_key', jsonb_build_object('module_code', p_module, 'event_code', p_event, 'channel', p_channel),
    'matched_key',   CASE WHEN v_found
                          THEN jsonb_build_object('module_code', v_row.module_code, 'event_code', v_row.event_code, 'channel', v_row.channel)
                          ELSE NULL END
  );
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_request_auth_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  RETURN jsonb_build_object(
    'auth_uid', v_uid,
    'authenticated', v_uid IS NOT NULL,
    'comm_hub_admin',
      CASE
        WHEN v_uid IS NULL THEN false
        ELSE public.is_comm_hub_admin(v_uid)
      END,
    'evaluated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_revalidation_send_context(p_cycle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := public._chrc_require_admin();
  v_cycle record;
  v_auth record;
BEGIN
  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle WHERE id = p_cycle_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'cycle_not_found'; END IF;

  SELECT * INTO v_auth FROM public.communication_hub_revalidation_send_authorisation
    WHERE cycle_id = p_cycle_id
    ORDER BY issued_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'ok', true,
    'cycle_id', v_cycle.id,
    'cycle_status', v_cycle.status,
    'provider_call_attempted', v_cycle.provider_call_attempted,
    'controlled_email_execution_id', v_cycle.controlled_email_execution_id,
    'authorisation', CASE WHEN v_auth.id IS NULL THEN null ELSE jsonb_build_object(
      'id', v_auth.id,
      'recipient_email', v_auth.recipient_email,
      'issued_at', v_auth.issued_at,
      'expires_at', v_auth.expires_at,
      'consumed_at', v_auth.consumed_at,
      'consumed_execution_id', v_auth.consumed_execution_id,
      'revoked_at', v_auth.revoked_at
    ) END,
    'module_code', v_cycle.module_code,
    'event_code', v_cycle.event_code,
    'channel', v_cycle.channel,
    'inbox_confirmation_status', v_cycle.inbox_confirmation_status
  );
END $function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_safety_counts(window_minutes integer DEFAULT 1440)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_since timestamptz := now() - make_interval(mins => COALESCE(window_minutes, 1440));
  v_stale_before timestamptz := now() - interval '10 minutes';
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR NOT (public.is_admin(v_uid) OR public.has_permission(v_uid, 'system_administration', 'view')) THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  SELECT jsonb_build_object(
    'queued_test', (SELECT count(*) FROM communication_message WHERE status='queued' AND test_mode=true),
    'queued_live', (SELECT count(*) FROM communication_message WHERE status='queued' AND test_mode=false),
    'sending', (SELECT count(*) FROM communication_message WHERE status='sending'),
    'stale_locks', (SELECT count(*) FROM communication_message WHERE status='sending' AND locked_at IS NOT NULL AND locked_at < v_stale_before),
    'failed_24h', (SELECT count(*) FROM communication_message WHERE status='failed' AND updated_at >= now() - interval '24 hours'),
    'suppressed_24h', (SELECT count(*) FROM communication_message WHERE status='suppressed' AND updated_at >= now() - interval '24 hours'),
    'accidental_live_sends_24h', (SELECT count(*) FROM communication_message WHERE test_mode=false AND provider_message_id IS NOT NULL AND provider_message_id NOT LIKE 'dry-run%' AND updated_at >= now() - interval '24 hours'),
    'legacy_notification_queue_window', (SELECT count(*) FROM notification_queue WHERE created_at >= v_since),
    'legacy_notification_logs_window', (SELECT count(*) FROM notification_logs WHERE created_at >= v_since),
    'window_minutes', window_minutes
  ) INTO v_result;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_comm_hub_stage_requirements(p_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE s text := public.normalize_comm_hub_go_live_stage_strict(p_stage);
BEGIN
  RETURN CASE s
  WHEN 'READINESS_ONLY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,
    'event_template_map_required',true,
    'template_version_required',true,
    'event_schema_required',true,   'event_schema_enforcement_required',false,
    'variable_contract_required',true,'variable_contract_enforcement_required',false,
    'fixture_compatibility_required',false,
    'template_structure_certification_required',false,
    'recipient_policy_required',false,
    'sender_test_ready_required',false,
    'sender_real_email_ready_required',false,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',false,
    'controlled_stub_capability_required',false,
    'live_provider_capability_required',false,
    'release_certification_required',false,
    'automation_arm_required',false)
  WHEN 'PREVIEW_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,
    'template_structure_certification_required',true,
    'recipient_policy_required',false,
    'sender_test_ready_required',false,
    'sender_real_email_ready_required',false,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',false,
    'controlled_stub_capability_required',false,
    'live_provider_capability_required',false,
    'release_certification_required',false,'automation_arm_required',false)
  WHEN 'APPROVAL_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,'template_structure_certification_required',true,
    'recipient_policy_required',true,
    'sender_test_ready_required',false,'sender_real_email_ready_required',false,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',false,'controlled_stub_capability_required',false,
    'live_provider_capability_required',false,
    'release_certification_required',false,'automation_arm_required',false)
  WHEN 'DRY_RUN_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,'template_structure_certification_required',true,
    'recipient_policy_required',true,
    'sender_test_ready_required',true,'sender_real_email_ready_required',false,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',false,'controlled_stub_capability_required',false,
    'live_provider_capability_required',false,
    'release_certification_required',false,'automation_arm_required',false)
  WHEN 'CONTROLLED_STUB_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,'template_structure_certification_required',true,
    'recipient_policy_required',true,
    'sender_test_ready_required',true,'sender_real_email_ready_required',false,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',false,
    'controlled_stub_capability_required',true,
    'live_provider_capability_required',false,
    'release_certification_required',false,'automation_arm_required',false)
  WHEN 'ONE_REAL_EMAIL_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,'template_structure_certification_required',true,
    'recipient_policy_required',true,
    'sender_test_ready_required',true,'sender_real_email_ready_required',true,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',false,
    'controlled_stub_capability_required',true,
    'live_provider_capability_required',true,
    'release_certification_required',true,'automation_arm_required',false)
  WHEN 'MANUAL_PRODUCTION_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,'template_structure_certification_required',true,
    'recipient_policy_required',true,
    'sender_test_ready_required',true,'sender_real_email_ready_required',true,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',true,
    'controlled_stub_capability_required',true,'live_provider_capability_required',true,
    'release_certification_required',true,'automation_arm_required',false)
  WHEN 'AUTOMATED_PRODUCTION_READY' THEN jsonb_build_object(
    'stage',s,
    'event_registration_required',true,'event_template_map_required',true,'template_version_required',true,
    'event_schema_required',true,'event_schema_enforcement_required',true,
    'variable_contract_required',true,'variable_contract_enforcement_required',true,
    'fixture_compatibility_required',true,'template_structure_certification_required',true,
    'recipient_policy_required',true,
    'sender_test_ready_required',true,'sender_real_email_ready_required',true,
    'preview_snapshot_required',false,'preview_approval_required',false,
    'dry_run_certification_required',true,
    'controlled_stub_capability_required',true,'live_provider_capability_required',true,
    'release_certification_required',true,'automation_arm_required',true)
  END;
END;$function$;
CREATE OR REPLACE FUNCTION public.get_communication_operating_mode()
 RETURNS TABLE(id uuid, singleton_guard text, operating_mode communication_operating_mode, previous_operating_mode communication_operating_mode, mode_changed_at timestamp with time zone, mode_changed_by uuid, mode_change_reason text, configuration_version bigint, dispatch_enabled boolean, dry_run_only boolean, email_live_enabled boolean, sms_live_enabled boolean, whatsapp_live_enabled boolean, print_enabled boolean, letter_enabled boolean, updated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT s.id, s.singleton_guard, s.operating_mode, s.previous_operating_mode,
         s.mode_changed_at, s.mode_changed_by, s.mode_change_reason,
         s.configuration_version, s.dispatch_enabled, s.dry_run_only,
         s.email_live_enabled, s.sms_live_enabled, s.whatsapp_live_enabled,
         s.print_enabled, s.letter_enabled, s.updated_at
  FROM public.communication_hub_control_settings s
  WHERE s.singleton_guard = 'primary';
$function$;
CREATE OR REPLACE FUNCTION public.get_communication_recipient_policy()
 RETURNS communication_hub_recipient_policy
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.communication_hub_recipient_policy WHERE singleton_guard = 'primary';
$function$;
CREATE OR REPLACE FUNCTION public.get_controlled_live_certification(p_certification_id uuid)
 RETURNS SETOF communication_controlled_live_certification
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_is_admin BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  v_is_admin := public.is_comm_hub_admin(v_uid);
  RETURN QUERY
  SELECT c.* FROM public.communication_controlled_live_certification c
    LEFT JOIN public.communication_controlled_live_execution e ON e.id = c.execution_id
   WHERE c.id = p_certification_id
     AND (v_is_admin OR e.requested_by = v_uid);
END; $function$;
CREATE OR REPLACE FUNCTION public.get_event_live_status(p_module_code text, p_event_code text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT status FROM public.communication_hub_event_live_control
   WHERE module_code = p_module_code AND event_code = p_event_code
   LIMIT 1
$function$;
CREATE OR REPLACE FUNCTION public.get_filing_config_for_date(p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  -- Find the active period that contains the given date
  SELECT jsonb_build_object(
    'id', id,
    'date_from', date_from,
    'date_to', date_to,
    'week_start_day', week_start_day,
    'filing_window_unit', filing_window_unit,
    'filing_window_value', filing_window_value,
    'penalty_initial_threshold', penalty_initial_threshold,
    'penalty_subsequent_threshold', penalty_subsequent_threshold,
    'is_active', is_active
  ) INTO v_result
  FROM public.c3_filing_config_periods
  WHERE is_active = true
    AND date_from <= p_date
    AND (date_to >= p_date OR date_to IS NULL)
  ORDER BY date_from DESC
  LIMIT 1;

  IF v_result IS NULL THEN
    RETURN jsonb_build_object('error', 'No active filing configuration found for date ' || p_date::TEXT);
  END IF;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_filtered_audit_trail(p_sort_key text DEFAULT 'timestamp'::text, p_sort_direction text DEFAULT 'desc'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20, p_date_from text DEFAULT NULL::text, p_date_to text DEFAULT NULL::text, p_user_filter text DEFAULT NULL::text, p_entity_type_filter text DEFAULT NULL::text, p_module_filter text DEFAULT NULL::text, p_route_filter text DEFAULT NULL::text, p_action_filter text DEFAULT NULL::text, p_source_filter text DEFAULT NULL::text, p_severity_filter text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id UUID;
  v_is_admin BOOLEAN;
  v_query TEXT;
  v_count_query TEXT;
  v_where TEXT := 'WHERE 1=1';
  v_order TEXT;
  v_rows JSONB;
  v_total BIGINT;
  v_allowed_sort_keys TEXT[] := ARRAY['timestamp','user_name','action','module','route','entity_type','entity_id','severity'];
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_caller_id AND LOWER(role) = 'admin'
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    v_where := v_where || ' AND (sat.user_id IS NULL OR sat.user_id NOT IN (SELECT ur.user_id FROM public.user_roles ur WHERE LOWER(ur.role) = ''admin''))';
  END IF;

  IF p_date_from IS NOT NULL AND p_date_from != '' THEN
    v_where := v_where || ' AND sat."timestamp" >= ' || quote_literal(p_date_from::TIMESTAMPTZ);
  END IF;
  IF p_date_to IS NOT NULL AND p_date_to != '' THEN
    v_where := v_where || ' AND sat."timestamp" <= ' || quote_literal((p_date_to || 'T23:59:59')::TIMESTAMPTZ);
  END IF;
  IF p_user_filter IS NOT NULL AND p_user_filter != '' THEN
    v_where := v_where || ' AND sat.user_name ILIKE ' || quote_literal('%' || p_user_filter || '%');
  END IF;
  IF p_entity_type_filter IS NOT NULL AND p_entity_type_filter != '' THEN
    v_where := v_where || ' AND sat.entity_type ILIKE ' || quote_literal('%' || p_entity_type_filter || '%');
  END IF;
  IF p_module_filter IS NOT NULL AND p_module_filter != '' THEN
    v_where := v_where || ' AND sat.module ILIKE ' || quote_literal('%' || p_module_filter || '%');
  END IF;
  IF p_route_filter IS NOT NULL AND p_route_filter != '' THEN
    v_where := v_where || ' AND sat.route ILIKE ' || quote_literal('%' || p_route_filter || '%');
  END IF;
  IF p_action_filter IS NOT NULL AND p_action_filter != '' THEN
    v_where := v_where || ' AND sat.action ILIKE ' || quote_literal('%' || p_action_filter || '%');
  END IF;
  IF p_source_filter IS NOT NULL AND p_source_filter != '' THEN
    v_where := v_where || ' AND sat.payload_json->>''source'' ILIKE ' || quote_literal('%' || p_source_filter || '%');
  END IF;
  IF p_severity_filter IS NOT NULL AND p_severity_filter != '' THEN
    v_where := v_where || ' AND sat.severity ILIKE ' || quote_literal('%' || p_severity_filter || '%');
  END IF;

  IF NOT (p_sort_key = ANY(v_allowed_sort_keys)) THEN
    p_sort_key := 'timestamp';
  END IF;
  IF p_sort_direction NOT IN ('asc', 'desc') THEN
    p_sort_direction := 'desc';
  END IF;
  v_order := ' ORDER BY sat.' || quote_ident(p_sort_key) || ' ' || p_sort_direction || ' NULLS LAST';

  v_count_query := 'SELECT count(*) FROM public.system_audit_trail sat ' || v_where;
  EXECUTE v_count_query INTO v_total;

  v_query := 'SELECT jsonb_agg(row_to_json(t)::jsonb) FROM (
    SELECT sat.id, sat."timestamp", sat.correlation_id, sat.user_id, sat.user_name,
           sat.action, sat.entity_type, sat.entity_id, sat.module, sat.route,
           sat.ip_address, sat.before_value, sat.after_value, sat.payload_json,
           sat.severity
    FROM public.system_audit_trail sat '
    || v_where || v_order
    || ' OFFSET ' || p_offset || ' LIMIT ' || p_limit
    || ') t';
  EXECUTE v_query INTO v_rows;

  RETURN jsonb_build_object(
    'entries', COALESCE(v_rows, '[]'::jsonb),
    'count', v_total
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_income_code_policy_for_period(p_income_code_id uuid, p_period_year integer, p_period_month integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period_date date;
  v_policy record;
  v_exception record;
  v_effective_calculation_method text;
  v_effective_calc_flat_enabled boolean;
  v_effective_calc_flat_percentage numeric;
  v_effective_calc_slab_enabled boolean;
  v_effective_distribution jsonb;
BEGIN
  v_period_date := make_date(p_period_year, p_period_month + 1, 1);

  SELECT * INTO v_policy
  FROM public.c3_income_code_policy_default
  WHERE income_code_id = p_income_code_id
    AND is_active = true
    AND date_from::date <= v_period_date
    AND (date_to IS NULL OR date_to::date >= v_period_date)
  ORDER BY date_from DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'found', false,
      'error', 'No active policy configured for this income code and period'
    );
  END IF;

  SELECT * INTO v_exception
  FROM public.c3_income_code_policy_exceptions
  WHERE income_code_id = p_income_code_id
    AND is_active = true
    AND date_from::date <= v_period_date
    AND (date_to IS NULL OR date_to::date >= v_period_date)
    AND exception_month = EXTRACT(MONTH FROM v_period_date)::int
    AND year_from <= EXTRACT(YEAR FROM v_period_date)::int
    AND (year_to IS NULL OR year_to >= EXTRACT(YEAR FROM v_period_date)::int)
  ORDER BY date_from DESC
  LIMIT 1;

  IF v_policy.date_entry_mode = 'no_dates' THEN
    v_effective_calculation_method := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.calculation_method::text, v_policy.calculation_method::text, 'merge')
      ELSE COALESCE(v_policy.calculation_method::text, 'merge')
    END;

    v_effective_calc_flat_enabled := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.calc_flat_enabled, v_policy.calc_flat_enabled, false)
      ELSE COALESCE(v_policy.calc_flat_enabled, false)
    END;

    v_effective_calc_flat_percentage := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.calc_flat_percentage, v_policy.calc_flat_percentage, 0)
      ELSE COALESCE(v_policy.calc_flat_percentage, 0)
    END;

    v_effective_calc_slab_enabled := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.calc_slab_enabled, v_policy.calc_slab_enabled, false)
      ELSE COALESCE(v_policy.calc_slab_enabled, false)
    END;

    v_effective_distribution := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.distribution::jsonb, v_policy.distribution::jsonb, '{}'::jsonb)
      ELSE COALESCE(v_policy.distribution::jsonb, '{}'::jsonb)
    END;
  ELSE
    v_effective_calculation_method := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.levy_calculation_method::text, v_policy.levy_calculation_method::text, 'separate')
      ELSE COALESCE(v_policy.levy_calculation_method::text, 'separate')
    END;

    v_effective_calc_flat_enabled := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.levy_calc_flat_enabled, v_policy.levy_calc_flat_enabled, false)
      ELSE COALESCE(v_policy.levy_calc_flat_enabled, false)
    END;

    v_effective_calc_flat_percentage := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.levy_calc_flat_percentage, v_policy.levy_calc_flat_percentage, 0)
      ELSE COALESCE(v_policy.levy_calc_flat_percentage, 0)
    END;

    v_effective_calc_slab_enabled := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.levy_calc_slab_enabled, v_policy.levy_calc_slab_enabled, false)
      ELSE COALESCE(v_policy.levy_calc_slab_enabled, false)
    END;

    v_effective_distribution := CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.levy_distribution::jsonb, v_policy.levy_distribution::jsonb, '{}'::jsonb)
      ELSE COALESCE(v_policy.levy_distribution::jsonb, '{}'::jsonb)
    END;
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'policy_id', v_policy.id,
    'date_entry_mode', v_policy.date_entry_mode,
    'policy_type', v_policy.policy_type,
    'has_exception', v_exception.id IS NOT NULL,
    'exception_id', v_exception.id,
    'levy_include', CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.levy_include, v_exception.include_in_levy, false)
      WHEN v_policy.date_entry_mode = 'no_dates' THEN COALESCE(v_policy.include_in_levy, false)
      ELSE COALESCE(v_policy.levy_include, false)
    END,
    'ssc_contrib_employee', CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.ssc_contrib_employee, v_exception.contrib_employee, false)
      WHEN v_policy.date_entry_mode = 'no_dates' THEN COALESCE(v_policy.contrib_employee, false)
      ELSE COALESCE(v_policy.ssc_contrib_employee, false)
    END,
    'ssc_contrib_employer', CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.ssc_contrib_employer, v_exception.contrib_employer, false)
      WHEN v_policy.date_entry_mode = 'no_dates' THEN COALESCE(v_policy.contrib_employer, false)
      ELSE COALESCE(v_policy.ssc_contrib_employer, false)
    END,
    'contrib_eib', CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.ssc_contrib_eib, v_exception.contrib_eir, false)
      WHEN v_policy.date_entry_mode = 'no_dates' THEN COALESCE(v_policy.contrib_eir, false)
      ELSE COALESCE(v_policy.ssc_contrib_eib, false)
    END,
    'include_in_severance', CASE
      WHEN v_exception.id IS NOT NULL AND v_exception.override_default
        THEN COALESCE(v_exception.include_in_severance, false)
      WHEN v_policy.date_entry_mode = 'no_dates' THEN COALESCE(v_policy.include_in_severance, false)
      ELSE false
    END,
    'calculation_method', COALESCE(v_effective_calculation_method, 'separate'),
    'calc_flat_enabled', COALESCE(v_effective_calc_flat_enabled, false),
    'calc_flat_percentage', COALESCE(v_effective_calc_flat_percentage, 0),
    'calc_slab_enabled', COALESCE(v_effective_calc_slab_enabled, false),
    'distribution', COALESCE(v_effective_distribution, '{}'::jsonb),
    'affects_last_week_payment', (
      v_policy.date_entry_mode = 'no_dates'
      AND COALESCE(v_effective_calculation_method, 'separate') = 'merge'
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_ip_status_transitions(p_current_status character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed_transitions jsonb;
BEGIN
  CASE p_current_status
    WHEN 'V' THEN
      v_allowed_transitions := '[{"code": "A", "description": "Active"}]'::jsonb;
    WHEN 'A' THEN
      v_allowed_transitions := '[{"code": "S", "description": "Suspended"}, {"code": "D", "description": "Deleted"}, {"code": "T", "description": "Terminated"}]'::jsonb;
    WHEN 'S' THEN
      v_allowed_transitions := '[{"code": "A", "description": "Active"}, {"code": "T", "description": "Terminated"}, {"code": "D", "description": "Deleted"}]'::jsonb;
    ELSE
      v_allowed_transitions := '[]'::jsonb;
  END CASE;
  
  RETURN jsonb_build_object(
    'current_status', p_current_status,
    'can_change', jsonb_array_length(v_allowed_transitions) > 0,
    'allowed_transitions', v_allowed_transitions
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_module_tables(_module_id uuid)
 RETURNS TABLE(table_name text, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT mt.table_name, COALESCE(mt.display_name, mt.table_name) as display_name
  FROM module_tables mt
  WHERE mt.module_id = _module_id
  ORDER BY mt.display_name;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_my_comm_hub_controlled_live_executions(p_limit integer DEFAULT 50)
 RETURNS SETOF communication_controlled_live_execution
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from communication_controlled_live_execution
   where requested_by = auth.uid()
   order by started_at desc
   limit greatest(1, least(coalesce(p_limit, 50), 200))
$function$;
CREATE OR REPLACE FUNCTION public.get_next_c3_schedule_no(p_payer_id character varying, p_payer_type character varying, p_period date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_max_seq INT;
BEGIN
    SELECT COALESCE(MAX(sequence_no), 0) + 1
    INTO v_max_seq
    FROM cn_c3_reported
    WHERE payer_id = p_payer_id
      AND payer_type = p_payer_type
      AND period::date = p_period::date;
    
    RETURN v_max_seq;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_next_payment_id()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  next_id integer;
BEGIN
  LOCK TABLE public.cn_payment_header IN EXCLUSIVE MODE;
  SELECT COALESCE(MAX(payment_id), 0) + 1 INTO next_id FROM public.cn_payment_header;
  RETURN next_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_pending_holiday_pay(p_ssn text, p_target_year integer, p_target_month integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_records JSONB;
  v_target_period_start DATE;
  v_target_period_end DATE;
BEGIN
  v_target_period_start := make_date(p_target_year, p_target_month, 1);
  v_target_period_end := (v_target_period_start + INTERVAL '1 month' - INTERVAL '1 day')::DATE;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', id,
    'ssn', ssn,
    'amount', amount,
    'source_c3_period', COALESCE(source_c3_id::TEXT, ''),
    'holiday_date_from', holiday_date_from,
    'holiday_date_to', holiday_date_to,
    'status', status
  )), '[]'::JSONB) INTO v_records
  FROM public.c3_pending_holiday_pay
  WHERE ssn = p_ssn
    AND target_period::DATE >= v_target_period_start
    AND target_period::DATE <= v_target_period_end
    AND status = 'pending';

  RETURN v_records;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_sep_audit_history(p_ssn character varying, p_self_ref_no character varying)
 RETURNS TABLE(audit_id bigint, action character varying, modifier character varying, modified_date timestamp without time zone, status character, activity_seq_no character varying, activity_type character varying, date_commenced timestamp without time zone, date_ceased timestamp without time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    a.audit_id::bigint,
    a.action::varchar,
    a.modifier::varchar,
    a.modified_date::timestamp,
    a.status::char,
    a.activity_seq_no::varchar,
    a.activity_type::varchar,
    a.date_commenced::timestamp,
    a.date_ceased::timestamp
  FROM au_ip_self_employ a
  WHERE a.ssn = p_ssn AND a.self_ref_no = p_self_ref_no
  ORDER BY a.audit_id DESC
  LIMIT 100;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_sep_contribution_rate(p_wage_category numeric, p_period timestamp without time zone)
 RETURNS TABLE(sep_ss_percent numeric, sep_penalty_percent numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT r.sep_ss_percent, r.sep_penalty_percent
  FROM tb_self_emp_contrib_rate r
  WHERE r.wage_cat = p_wage_category
    AND p_period BETWEEN r.effstart AND r.effend
  LIMIT 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_sep_contribution_summary(p_ssn character varying)
 RETURNS TABLE(total_contributions bigint, total_ss_amount numeric, latest_period timestamp without time zone, earliest_period timestamp without time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::bigint as total_contributions,
    COALESCE(SUM(w.sep_ss_amt), 0)::numeric as total_ss_amount,
    MAX(w.period) as latest_period,
    MIN(w.period) as earliest_period
  FROM ip_self_weeks_paid w
  WHERE w.ssn = p_ssn AND w.payer_type = 'SE';
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_sep_weeks_paid(p_ssn character varying, p_payer_id character varying)
 RETURNS SETOF ip_self_weeks_paid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT * FROM ip_self_weeks_paid
  WHERE ssn = p_ssn
    AND payer_id = p_payer_id
    AND payer_type = 'SE'
  ORDER BY period DESC, sequence_no;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_system_setting(p_setting_key character varying)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_value TEXT;
BEGIN
  SELECT setting_value INTO v_value
  FROM public.system_settings
  WHERE setting_key = p_setting_key;
  
  RETURN v_value;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_table_columns(p_table_name text)
 RETURNS TABLE(column_name text, data_type text, is_nullable boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    c.column_name::text,
    c.data_type::text,
    (c.is_nullable = 'YES')::boolean
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name = p_table_name
  ORDER BY c.ordinal_position;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_table_ddl_info(p_table_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = p_table_name
  ) THEN
    RETURN jsonb_build_object('error', 'Table does not exist');
  END IF;

  SELECT jsonb_build_object(
    'table_name', p_table_name,
    'columns', (
      SELECT jsonb_agg(
        jsonb_build_object(
          'column_name', c.column_name,
          'data_type', c.data_type,
          'udt_name', c.udt_name,
          'character_maximum_length', c.character_maximum_length,
          'numeric_precision', c.numeric_precision,
          'numeric_scale', c.numeric_scale,
          'is_nullable', c.is_nullable,
          'column_default', c.column_default
        ) ORDER BY c.ordinal_position
      )
      FROM information_schema.columns c
      WHERE c.table_schema = 'public' AND c.table_name = p_table_name
    ),
    'primary_key_columns', (
      SELECT jsonb_agg(kcu.column_name ORDER BY kcu.ordinal_position)
      FROM information_schema.table_constraints tc
      JOIN information_schema.key_column_usage kcu
        ON tc.constraint_name = kcu.constraint_name
        AND tc.table_schema = kcu.table_schema
      WHERE tc.table_schema = 'public'
        AND tc.table_name = p_table_name
        AND tc.constraint_type = 'PRIMARY KEY'
    ),
    'enums', (
      SELECT jsonb_agg(DISTINCT jsonb_build_object(
        'enum_name', t.typname,
        'enum_values', (
          SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder)
          FROM pg_enum e WHERE e.enumtypid = t.oid
        )
      ))
      FROM information_schema.columns c
      JOIN pg_type t ON t.typname = c.udt_name AND t.typnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public')
      WHERE c.table_schema = 'public'
        AND c.table_name = p_table_name
        AND c.data_type = 'USER-DEFINED'
        AND t.typtype = 'e'
    )
  ) INTO v_result;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_table_foreign_keys()
 RETURNS TABLE(source_table text, source_column text, target_table text, target_column text, constraint_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    tc.table_name::text AS source_table,
    kcu.column_name::text AS source_column,
    ccu.table_name::text AS target_table,
    ccu.column_name::text AS target_column,
    tc.constraint_name::text
  FROM information_schema.table_constraints AS tc
  JOIN information_schema.key_column_usage AS kcu
    ON tc.constraint_name = kcu.constraint_name
    AND tc.table_schema = kcu.table_schema
  JOIN information_schema.constraint_column_usage AS ccu
    ON ccu.constraint_name = tc.constraint_name
    AND ccu.table_schema = tc.table_schema
  WHERE tc.constraint_type = 'FOREIGN KEY'
    AND tc.table_schema = 'public';
$function$;
CREATE OR REPLACE FUNCTION public.get_user_accessible_modules(_user_id uuid)
 RETURNS TABLE(id uuid, name text, display_name text, icon text, route text, parent_id uuid, sort_order integer, description text, base_url text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.is_admin(_user_id) THEN
    RETURN QUERY
    SELECT 
      m.id, m.name, m.display_name, m.icon, m.route, m.parent_id, 
      m.sort_order, m.description, m.base_url
    FROM app_modules m
    WHERE m.is_enabled = true
      AND m.show_in_menu = true
      AND m.routes_enabled = true
      AND public.check_module_rollout_access(
        _user_id, m.rollout_state, m.internal_only, 
        m.pilot_user_ids, m.pilot_role_ids
      )
    ORDER BY m.sort_order NULLS LAST, m.display_name;
  ELSE
    RETURN QUERY
    WITH RECURSIVE permitted_modules AS (
      SELECT DISTINCT m2.id AS module_id
      FROM app_modules m2
      INNER JOIN module_actions ma ON ma.module_id = m2.id
      INNER JOIN role_permissions rp ON rp.module_id = m2.id AND rp.action_id = ma.id
      INNER JOIN roles r ON r.id = rp.role_id
      INNER JOIN user_roles ur ON ur.role::text = r.role_name
      WHERE ur.user_id = _user_id
        AND m2.is_enabled = true
        AND m2.show_in_menu = true
        AND m2.routes_enabled = true
        AND ma.action_name = 'view'
        AND ma.is_enabled = true
        AND rp.is_granted = true
        AND public.check_module_rollout_access(
          _user_id, m2.rollout_state, m2.internal_only,
          m2.pilot_user_ids, m2.pilot_role_ids
        )
    ),
    -- Recursively walk up the parent chain so 3+ level trees survive
    ancestor_chain AS (
      SELECT m.id AS module_id, m.parent_id
      FROM app_modules m
      INNER JOIN permitted_modules pm ON pm.module_id = m.id
      UNION
      SELECT m.id, m.parent_id
      FROM app_modules m
      INNER JOIN ancestor_chain ac ON ac.parent_id = m.id
    ),
    all_visible AS (
      SELECT module_id FROM ancestor_chain
    )
    SELECT 
      m.id, m.name, m.display_name, m.icon, m.route, m.parent_id, 
      m.sort_order, m.description, m.base_url
    FROM app_modules m
    INNER JOIN all_visible av ON av.module_id = m.id
    WHERE m.is_enabled = true
      AND m.show_in_menu = true
      AND m.routes_enabled = true
    ORDER BY m.sort_order NULLS LAST, m.display_name;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_user_meetings_for_date(p_user_id uuid, p_date date)
 RETURNS TABLE(id uuid, meeting_reference character varying, application_reference character varying, meeting_time time without time zone, meeting_end_time time without time zone, status character varying, meeting_type character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_code TEXT;
BEGIN
  -- Get the user_code for backward compatibility with older meetings
  SELECT p.user_code INTO v_user_code
  FROM public.profiles p
  WHERE p.id = p_user_id;

  RETURN QUERY
  SELECT 
    m.id,
    m.meeting_reference,
    m.application_reference,
    m.meeting_time,
    m.meeting_end_time,
    m.status::VARCHAR,
    m.meeting_type::VARCHAR
  FROM public.meetings m
  WHERE m.meeting_date = p_date
    -- Only show ACTIVE meetings: Scheduled and InProgress.
    -- Rescheduled meetings are closed/superseded — their slot is free unless a
    -- phantom meeting_slot_reservation was created (releasePreviousSlot=false).
    AND m.status IN ('Scheduled', 'InProgress')
    AND (
      m.assigned_user_id = p_user_id
      OR (m.assigned_user_id IS NULL AND v_user_code IS NOT NULL AND m.contact_person = v_user_code)
    )
  ORDER BY m.meeting_time;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_user_permissions(_user_id uuid)
 RETURNS TABLE(module_name text, action_name text, is_granted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- If admin, return all module actions as granted
  IF public.is_admin(_user_id) THEN
    RETURN QUERY
    SELECT 
      m.name::text as module_name,
      ma.action_name::text as action_name,
      true as is_granted
    FROM app_modules m
    INNER JOIN module_actions ma ON ma.module_id = m.id
    WHERE m.is_enabled = true
      AND ma.is_enabled = true
    ORDER BY m.name, ma.action_name;
  ELSE
    -- Return granted permissions through user_roles
    RETURN QUERY
    SELECT DISTINCT
      m.name::text as module_name,
      ma.action_name::text as action_name,
      rp.is_granted
    FROM app_modules m
    INNER JOIN module_actions ma ON ma.module_id = m.id
    INNER JOIN role_permissions rp ON rp.module_id = m.id AND rp.action_id = ma.id
    INNER JOIN roles r ON r.id = rp.role_id
    INNER JOIN user_roles ur ON ur.role::text = r.role_name
    WHERE ur.user_id = _user_id
      AND m.is_enabled = true
      AND ma.is_enabled = true
      AND rp.is_granted = true
    ORDER BY m.name, ma.action_name;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_visible_fields(_user_id uuid, _module_name text, _table_name text)
 RETURNS TABLE(field_name text, can_view boolean, can_edit boolean, masking_type text, rule_source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  user_roles TEXT[];
BEGIN
  IF public.is_admin(_user_id) THEN
    RETURN QUERY SELECT fsr.field_name, true, true, 'none'::TEXT, 'admin_bypass'::TEXT
    FROM field_security_rules fsr WHERE fsr.target_table = _table_name GROUP BY fsr.field_name;
    RETURN;
  END IF;

  SELECT array_agg(ur.role::TEXT) INTO user_roles FROM user_roles ur WHERE ur.user_id = _user_id;

  RETURN QUERY
  SELECT fsr.field_name, bool_or(fsr.can_view), bool_or(fsr.can_edit), 
         (array_agg(fsr.masking_type::TEXT ORDER BY fsr.priority))[1], 'role_rule'::TEXT
  FROM field_security_rules fsr
  JOIN roles r ON r.id = fsr.role_id
  WHERE fsr.target_table = _table_name AND fsr.is_active = true AND r.role_name = ANY(user_roles)
  GROUP BY fsr.field_name;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_comm_asset_category_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer;
BEGIN
  IF OLD.is_system_default THEN
    RAISE EXCEPTION 'System default category "%" cannot be deleted. Deactivate it instead.', OLD.category_code;
  END IF;
  SELECT count(*) INTO v_count FROM public.comm_media_asset WHERE category = OLD.category_code;
  IF v_count > 0 THEN
    RAISE EXCEPTION 'Category "%" is in use by % asset(s). Deactivate it instead.', OLD.category_code, v_count;
  END IF;
  RETURN OLD;
END;
$function$;
CREATE OR REPLACE FUNCTION public.handle_er_status_to_verified()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_regno TEXT;
  v_old_regno TEXT;
  v_attempts INT := 0;
  v_max_attempts INT := 10;
BEGIN
  -- Only act when status just changed to 'V'
  IF NEW.status = 'V' AND (OLD.status IS DISTINCT FROM 'V') THEN

    v_old_regno := NEW.regno;

    -- Only convert if current regno is temporary (starts with 'T')
    IF v_old_regno IS NOT NULL AND LEFT(v_old_regno, 1) = 'T' THEN

      -- Generate permanent regno with retry logic
      LOOP
        v_attempts := v_attempts + 1;
        IF v_attempts > v_max_attempts THEN
          RAISE WARNING 'handle_er_status_to_verified: failed to generate unique regno after % attempts for old_regno=%', v_max_attempts, v_old_regno;
          RETURN NEW; -- Don't block the status update
        END IF;

        v_new_regno := generate_er_regno();

        -- Check uniqueness
        IF NOT EXISTS (SELECT 1 FROM er_master WHERE regno = v_new_regno AND regno <> v_old_regno) THEN
          EXIT; -- unique, proceed
        END IF;
      END LOOP;

      -- Update related tables first (they reference the old regno)
      UPDATE er_owner SET regno = v_new_regno WHERE regno = v_old_regno;
      UPDATE er_locations SET regno = v_new_regno WHERE regno = v_old_regno;
      UPDATE er_notes SET regno = v_new_regno WHERE regno = v_old_regno;
      UPDATE er_commence SET regno = v_new_regno WHERE regno = v_old_regno;
      UPDATE er_visit SET regno = v_new_regno WHERE regno = v_old_regno;
      UPDATE er_suit SET regno = v_new_regno WHERE regno = v_old_regno;

      -- Update the master record's regno
      NEW.regno := v_new_regno;

      RAISE NOTICE 'handle_er_status_to_verified: converted % -> %', v_old_regno, v_new_regno;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, full_name, email)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'full_name', ''),
    NEW.email
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.has_any_role(_user_id uuid, _roles app_role[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = _user_id AND role = ANY(_roles)
  )
$function$;
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid, _module_name text, _action_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Admins have all permissions
  IF public.is_admin(_user_id) THEN
    RETURN true;
  END IF;

  -- Check if user has the specific permission through any role in user_roles
  RETURN EXISTS(
    SELECT 1
    FROM app_modules m
    INNER JOIN module_actions ma ON ma.module_id = m.id
    INNER JOIN role_permissions rp ON rp.module_id = m.id AND rp.action_id = ma.id
    INNER JOIN roles r ON r.id = rp.role_id
    INNER JOIN user_roles ur ON ur.role::text = r.role_name
    WHERE ur.user_id = _user_id
      AND m.name = _module_name
      AND m.is_enabled = true
      AND ma.action_name = _action_name
      AND ma.is_enabled = true
      AND rp.is_granted = true
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = _user_id
      AND role = _role::text
  )
$function$;
CREATE OR REPLACE FUNCTION public.has_valid_controlled_stub_certification(p_module_code text, p_event_code text, p_recipient_set_hash text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.communication_controlled_live_certification c
     WHERE c.certification_kind = 'CONTROLLED_STUB'
       AND c.status IN ('PROVIDER_ACCEPTED','DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY')
       AND c.module_code = p_module_code
       AND c.event_code = p_event_code
       AND c.recipient_set_hash = p_recipient_set_hash
       AND c.invalidated_at IS NULL
  );
$function$;
CREATE OR REPLACE FUNCTION public.ia_apply_manual_override(p_plan_id uuid, p_override_type text, p_engagement_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_changes jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT ''::text, p_changed_by text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_before jsonb;
  v_after jsonb;
BEGIN
  -- Capture before state
  IF p_candidate_id IS NOT NULL THEN
    SELECT jsonb_build_object('status', c.status, 'accepted', c.accepted, 'rejection_reason', c.rejection_reason,
      'suggested_lead_auditor_id', c.suggested_lead_auditor_id, 'suggested_start_date', c.suggested_start_date)
    INTO v_before FROM ia_auto_plan_candidates c WHERE c.id = p_candidate_id;
  ELSIF p_engagement_id IS NOT NULL THEN
    SELECT jsonb_build_object('status', e.status, 'is_active', e.is_active, 'lead_auditor_id', e.lead_auditor_id,
      'planned_start_date', e.planned_start_date, 'planned_end_date', e.planned_end_date)
    INTO v_before FROM ia_audit_engagements e WHERE e.id = p_engagement_id;
  END IF;

  -- Execute override
  IF p_override_type = 'accept_candidate' AND p_candidate_id IS NOT NULL THEN
    UPDATE ia_auto_plan_candidates SET accepted = true, status = 'Accepted' WHERE id = p_candidate_id;
  ELSIF p_override_type = 'reject_candidate' AND p_candidate_id IS NOT NULL THEN
    UPDATE ia_auto_plan_candidates SET accepted = false, status = 'Rejected', rejection_reason = p_reason WHERE id = p_candidate_id;
  ELSIF p_override_type = 'remove_engagement' AND p_engagement_id IS NOT NULL THEN
    UPDATE ia_audit_engagements SET is_active = false, updated_by = p_changed_by, updated_at = now()
    WHERE id = p_engagement_id;
  ELSIF p_override_type = 'reschedule_candidate' AND p_candidate_id IS NOT NULL THEN
    UPDATE ia_auto_plan_candidates SET
      suggested_start_date = COALESCE((p_changes->>'start_date')::date, suggested_start_date),
      suggested_end_date = COALESCE((p_changes->>'end_date')::date, suggested_end_date)
    WHERE id = p_candidate_id;
  ELSIF p_override_type = 'reassign_candidate' AND p_candidate_id IS NOT NULL THEN
    UPDATE ia_auto_plan_candidates SET
      suggested_lead_auditor_id = COALESCE((p_changes->>'auditor_id')::uuid, suggested_lead_auditor_id)
    WHERE id = p_candidate_id;
  END IF;

  -- Capture after state
  IF p_candidate_id IS NOT NULL THEN
    SELECT jsonb_build_object('status', c.status, 'accepted', c.accepted, 'rejection_reason', c.rejection_reason,
      'suggested_lead_auditor_id', c.suggested_lead_auditor_id, 'suggested_start_date', c.suggested_start_date)
    INTO v_after FROM ia_auto_plan_candidates c WHERE c.id = p_candidate_id;
  ELSIF p_engagement_id IS NOT NULL THEN
    SELECT jsonb_build_object('status', e.status, 'is_active', e.is_active, 'lead_auditor_id', e.lead_auditor_id,
      'planned_start_date', e.planned_start_date, 'planned_end_date', e.planned_end_date)
    INTO v_after FROM ia_audit_engagements e WHERE e.id = p_engagement_id;
  END IF;

  -- Log with full governance
  INSERT INTO ia_plan_change_log (plan_id, change_type, description, changed_by, change_date, before_state, after_state, change_classification, entity_type, entity_id)
  VALUES (
    p_plan_id,
    'Manual Override: ' || p_override_type,
    p_reason || CASE WHEN p_changes != '{}'::jsonb THEN ' | Changes: ' || p_changes::text ELSE '' END,
    p_changed_by,
    now(),
    v_before,
    v_after,
    'manual_override',
    CASE WHEN p_candidate_id IS NOT NULL THEN 'candidate' ELSE 'engagement' END,
    COALESCE(p_candidate_id, p_engagement_id)
  );

  RETURN jsonb_build_object('success', true, 'override_type', p_override_type, 'before', v_before, 'after', v_after);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_apply_plan_revision(p_plan_id uuid, p_changes jsonb, p_requested_by text DEFAULT 'SYSTEM'::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan record;
  v_key text;
  v_old_value text;
  v_new_value text;
  v_has_material_change boolean := false;
  v_material_fields text[] := ARRAY['planned_start_date','planned_end_date','assigned_auditor','department_id','function_id','scope','objective'];
BEGIN
  SELECT * INTO v_plan FROM ia_annual_plans WHERE id = p_plan_id;
  IF v_plan IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan not found');
  END IF;

  IF v_plan.status NOT IN ('Approved', 'In Progress') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only revise an Approved or In Progress plan');
  END IF;

  -- Log each change
  FOR v_key IN SELECT jsonb_object_keys(p_changes) LOOP
    v_new_value := p_changes->>v_key;
    v_old_value := to_jsonb(v_plan)->>v_key;

    IF v_old_value IS DISTINCT FROM v_new_value THEN
      -- Check if material
      IF v_key = ANY(v_material_fields) THEN
        v_has_material_change := true;
      END IF;

      INSERT INTO ia_plan_change_log (plan_id, change_type, description, changed_by, change_date,
        version_number, entity_type, entity_id, requires_reapproval)
      VALUES (p_plan_id, 'field_change',
        v_key || ': "' || COALESCE(v_old_value, 'NULL') || '" → "' || COALESCE(v_new_value, 'NULL') || '"',
        p_requested_by, now(), v_plan.current_version_number, 'plan', p_plan_id, v_key = ANY(v_material_fields));

      -- Record amendment
      INSERT INTO ia_plan_amendments (plan_id, field_name, old_value, new_value, amendment_reason, amended_by, amended_at)
      VALUES (p_plan_id, v_key, v_old_value, v_new_value, p_reason, p_requested_by, now());
    END IF;
  END LOOP;

  -- If material change detected, trigger revision workflow
  IF v_has_material_change THEN
    RETURN ia_start_plan_approval_workflow(p_plan_id, p_requested_by, true);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'requires_reapproval', false,
    'message', 'Minor changes logged; no re-approval required'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_build_followup_carry_forward(p_source_fiscal_year text, p_target_fiscal_year text, p_carried_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count INT := 0; v_finding RECORD;
BEGIN
  FOR v_finding IN
    SELECT f.id AS finding_id, f.description, f.priority, e.id AS engagement_id, e.annual_plan_id
    FROM ia_findings f
    JOIN ia_activities a ON a.id = f.activity_id
    JOIN ia_audit_engagements e ON e.id = a.engagement_id
    JOIN ia_annual_plans p ON p.id = e.annual_plan_id
    WHERE p.fiscal_year = p_source_fiscal_year AND f.status NOT IN ('Closed', 'Resolved', 'Verified')
      AND NOT EXISTS (SELECT 1 FROM ia_plan_carry_forward cf WHERE cf.source_id = f.id::text AND cf.target_fiscal_year = p_target_fiscal_year)
  LOOP
    INSERT INTO ia_plan_carry_forward (annual_plan_id, source_type, source_id, source_reference, description, priority, status, carried_by, target_fiscal_year, original_finding_id, original_engagement_id)
    VALUES (v_finding.annual_plan_id, 'finding', v_finding.finding_id::text, 'FY-' || p_source_fiscal_year || ' Finding', v_finding.description, v_finding.priority, 'Carried Forward', p_carried_by, p_target_fiscal_year, v_finding.finding_id, v_finding.engagement_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'carried_forward_count', v_count, 'source_year', p_source_fiscal_year, 'target_year', p_target_fiscal_year);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_can_close_engagement(p_engagement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_reasons TEXT[] := '{}'; v_report_count INT; v_open_no_action INT; v_open_no_followup INT; v_exit_done BOOLEAN;
BEGIN
  SELECT COUNT(*) INTO v_report_count FROM ia_audit_reports WHERE engagement_id = p_engagement_id AND status = 'Issued';
  IF v_report_count = 0 THEN v_reasons := array_append(v_reasons, 'No issued report found'); END IF;

  SELECT COUNT(*) INTO v_open_no_action FROM ia_findings f JOIN ia_activities a ON a.id = f.activity_id
  WHERE a.engagement_id = p_engagement_id AND f.status NOT IN ('Closed','Resolved') AND NOT EXISTS (SELECT 1 FROM ia_action_tracking act WHERE act.finding_id = f.id);
  IF v_open_no_action > 0 THEN v_reasons := array_append(v_reasons, format('%s open finding(s) without action plans', v_open_no_action)); END IF;

  SELECT COUNT(*) INTO v_open_no_followup FROM ia_findings f JOIN ia_activities a ON a.id = f.activity_id
  WHERE a.engagement_id = p_engagement_id AND f.status NOT IN ('Closed','Resolved') AND NOT EXISTS (SELECT 1 FROM ia_follow_ups fu WHERE fu.finding_id = f.id);
  IF v_open_no_followup > 0 THEN v_reasons := array_append(v_reasons, format('%s open finding(s) without follow-up structure', v_open_no_followup)); END IF;

  SELECT EXISTS (SELECT 1 FROM ia_communication_stages cs WHERE cs.engagement_id = p_engagement_id AND cs.stage_code = 'EXIT_MEETING' AND cs.delivery_status IN ('Sent','Delivered','Acknowledged')) INTO v_exit_done;
  IF NOT v_exit_done THEN v_reasons := array_append(v_reasons, 'Exit meeting communication not completed'); END IF;

  RETURN jsonb_build_object('can_close', array_length(v_reasons, 1) IS NULL, 'reasons', v_reasons);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_can_issue_report(p_report_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_report record;
  v_eng_id uuid;
  v_gate record;
  v_evidence_count integer;
  v_wp_count integer;
  v_findings_count integer;
  v_responses_pending integer;
  v_reasons text[] := '{}';
  v_exit_meeting_done boolean;
  v_draft_discussion_done boolean;
BEGIN
  SELECT * INTO v_report FROM ia_audit_reports WHERE id = p_report_id;
  IF v_report IS NULL THEN
    RETURN jsonb_build_object('can_issue', false, 'reasons', ARRAY['Report not found']);
  END IF;

  v_eng_id := v_report.engagement_id;

  -- Load gate config
  SELECT * INTO v_gate FROM ia_execution_gate_config WHERE gate_type = 'report_issuance' AND is_active = true LIMIT 1;

  IF v_gate IS NOT NULL AND v_eng_id IS NOT NULL THEN
    -- Count artefacts
    SELECT count(*) INTO v_evidence_count FROM ia_evidence WHERE engagement_id = v_eng_id;
    SELECT count(*) INTO v_wp_count FROM ia_working_papers WHERE engagement_id = v_eng_id;
    SELECT count(*) INTO v_findings_count FROM ia_findings WHERE engagement_id = v_eng_id;

    IF v_evidence_count < v_gate.min_evidence_count THEN
      v_reasons := v_reasons || ('Minimum ' || v_gate.min_evidence_count || ' evidence item(s) required, found ' || v_evidence_count);
    END IF;

    IF v_wp_count < v_gate.min_working_papers_count THEN
      v_reasons := v_reasons || ('Minimum ' || v_gate.min_working_papers_count || ' working paper(s) required, found ' || v_wp_count);
    END IF;

    IF v_gate.min_findings_documented AND v_findings_count = 0 THEN
      v_reasons := v_reasons || 'At least one finding must be documented (or mark engagement as no-findings)';
    END IF;

    -- Management responses check (enhanced: always check, not just when config flag set)
    SELECT count(*) INTO v_responses_pending
    FROM ia_findings f
    LEFT JOIN ia_management_responses mr ON mr.finding_id = f.id
    WHERE f.engagement_id = v_eng_id AND mr.id IS NULL;
    IF v_responses_pending > 0 THEN
      v_reasons := v_reasons || (v_responses_pending || ' finding(s) missing management response');
    END IF;
  END IF;

  -- Gate (NEW): Draft Finding Discussion communication must be completed
  IF v_eng_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM ia_communication_stages cs
      WHERE cs.engagement_id = v_eng_id
        AND cs.stage_code = 'DRAFT_FINDING_DISCUSSION'
        AND cs.delivery_status IN ('Sent','Delivered','Acknowledged')
    ) INTO v_draft_discussion_done;
    IF NOT v_draft_discussion_done THEN
      v_reasons := v_reasons || 'Draft finding discussion must be completed with auditee before report issuance';
    END IF;

    -- Gate (NEW): Exit Meeting communication must be completed
    SELECT EXISTS (
      SELECT 1 FROM ia_communication_stages cs
      WHERE cs.engagement_id = v_eng_id
        AND cs.stage_code = 'EXIT_MEETING'
        AND cs.delivery_status IN ('Sent','Delivered','Acknowledged')
    ) INTO v_exit_meeting_done;
    IF NOT v_exit_meeting_done THEN
      v_reasons := v_reasons || 'Exit meeting must be completed before report issuance';
    END IF;
  END IF;

  -- Store gate status on report
  UPDATE ia_audit_reports SET issuance_gate_status = jsonb_build_object(
    'checked_at', now(),
    'passed', array_length(v_reasons, 1) IS NULL,
    'evidence_count', COALESCE(v_evidence_count, 0),
    'working_papers_count', COALESCE(v_wp_count, 0),
    'findings_count', COALESCE(v_findings_count, 0),
    'reasons', v_reasons
  ) WHERE id = p_report_id;

  RETURN jsonb_build_object(
    'can_issue', array_length(v_reasons, 1) IS NULL,
    'reasons', v_reasons,
    'evidence_count', COALESCE(v_evidence_count, 0),
    'working_papers_count', COALESCE(v_wp_count, 0),
    'findings_count', COALESCE(v_findings_count, 0)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_can_start_engagement(p_engagement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eng record;
  v_plan_status text;
  v_plan_version_number integer;
  v_reasons text[] := '{}';
  v_intimation_done boolean;
  v_team_notice_done boolean;
  v_version_approved boolean;
BEGIN
  SELECT e.*, ap.status AS plan_status, ap.current_version_number AS plan_current_version
  INTO v_eng
  FROM ia_audit_engagements e
  LEFT JOIN ia_annual_plans ap ON ap.id = e.annual_plan_id
  WHERE e.id = p_engagement_id;

  IF v_eng IS NULL THEN
    RETURN jsonb_build_object('can_start', false, 'reasons', ARRAY['Engagement not found']);
  END IF;

  -- Gate 1: Parent plan must be Approved or In Progress
  IF v_eng.plan_status IS NOT NULL AND v_eng.plan_status NOT IN ('Approved', 'In Progress') THEN
    v_reasons := v_reasons || ('Parent plan status is "' || COALESCE(v_eng.plan_status, 'NULL') || '" — must be Approved or In Progress');
  END IF;

  -- Gate 1b (NEW): Engagement must be part of the current approved plan version
  IF v_eng.annual_plan_id IS NOT NULL AND v_eng.plan_status IN ('Approved', 'In Progress') THEN
    SELECT EXISTS (
      SELECT 1 FROM ia_plan_version_engagements pve
      JOIN ia_plan_versions pv ON pv.id = pve.plan_version_id
      WHERE pve.engagement_id = p_engagement_id
        AND pv.plan_id = v_eng.annual_plan_id
        AND pv.version_number = v_eng.plan_current_version
        AND pve.change_type != 'removed'
    ) INTO v_version_approved;
    
    IF NOT v_version_approved THEN
      v_reasons := v_reasons || 'Engagement is not included in the current approved plan version (v' || COALESCE(v_eng.plan_current_version::text, '?') || ')';
    END IF;
  END IF;

  -- Gate 2: Engagement must have planned dates
  IF v_eng.planned_start_date IS NULL OR v_eng.planned_end_date IS NULL THEN
    v_reasons := v_reasons || 'Engagement must have planned start and end dates';
  END IF;

  -- Gate 3: Must have a lead auditor
  IF v_eng.lead_auditor_id IS NULL THEN
    v_reasons := v_reasons || 'A lead auditor must be assigned';
  END IF;

  -- Gate 4: Audit Intimation communication must be sent
  SELECT EXISTS (
    SELECT 1 FROM ia_communication_stages cs
    WHERE cs.engagement_id = p_engagement_id
      AND cs.stage_code = 'PLAN_INTIMATION'
      AND cs.delivery_status IN ('Sent','Delivered','Acknowledged')
  ) INTO v_intimation_done;
  IF NOT v_intimation_done THEN
    v_reasons := v_reasons || 'Audit intimation notice must be sent to auditee before execution';
  END IF;

  -- Gate 5: Team & scope notice must be sent
  SELECT EXISTS (
    SELECT 1 FROM ia_communication_stages cs
    WHERE cs.engagement_id = p_engagement_id
      AND cs.stage_code = 'TEAM_AND_SCOPE_NOTICE'
      AND cs.delivery_status IN ('Sent','Delivered','Acknowledged')
  ) INTO v_team_notice_done;
  IF NOT v_team_notice_done THEN
    v_reasons := v_reasons || 'Team and scope disclosure must be sent to auditee before execution';
  END IF;

  RETURN jsonb_build_object(
    'can_start', array_length(v_reasons, 1) IS NULL,
    'reasons', v_reasons,
    'engagement_status', v_eng.status,
    'plan_status', v_eng.plan_status,
    'plan_version', v_eng.plan_current_version,
    'is_in_current_version', COALESCE(v_version_approved, false)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_capacity_schedule_candidates(p_plan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate RECORD;
  v_auditor RECORD;
  v_plan_start date;
  v_plan_end date;
  v_slot_start date;
  v_assigned integer := 0;
  v_conflicts integer := 0;
BEGIN
  -- Get plan date range
  SELECT planned_start_date, planned_end_date INTO v_plan_start, v_plan_end
  FROM ia_annual_plans WHERE id = p_plan_id;
  
  v_plan_start := COALESCE(v_plan_start, CURRENT_DATE);
  v_plan_end := COALESCE(v_plan_end, v_plan_start + INTERVAL '12 months');

  -- Clear previous conflicts for this plan
  DELETE FROM ia_availability_conflicts WHERE plan_id = p_plan_id;

  v_slot_start := v_plan_start;

  -- For each accepted candidate (ordered by score), try to assign an available auditor
  FOR v_candidate IN
    SELECT c.* FROM ia_auto_plan_candidates c
    WHERE c.plan_id = p_plan_id AND c.accepted = true
    ORDER BY c.composite_score DESC
  LOOP
    -- Find least-loaded active auditor not on leave during the slot
    FOR v_auditor IN
      SELECT a.id, a.name,
        COALESCE((SELECT SUM(COALESCE(e.estimated_hours,0)) FROM ia_audit_engagements e 
          WHERE e.lead_auditor_id = a.id AND e.status NOT IN ('Completed','Closed','Cancelled')
          AND (e.is_active = true OR e.is_active IS NULL)), 0) AS current_load
      FROM ia_auditors a
      WHERE a.employment_status = 'Active' AND a.is_active = true
        AND NOT EXISTS (
          SELECT 1 FROM ia_leave_requests lr
          WHERE lr.auditor_id = a.id AND lr.status = 'Approved'
            AND lr.start_date <= v_slot_start + INTERVAL '14 days'
            AND lr.end_date >= v_slot_start
        )
      ORDER BY current_load ASC
      LIMIT 1
    LOOP
      UPDATE ia_auto_plan_candidates SET
        suggested_lead_auditor_id = v_auditor.id,
        suggested_start_date = v_slot_start,
        suggested_end_date = v_slot_start + INTERVAL '14 days',
        suggested_hours = CASE 
          WHEN composite_score >= 75 THEN 80
          WHEN composite_score >= 50 THEN 60
          WHEN composite_score >= 25 THEN 40
          ELSE 30
        END
      WHERE id = v_candidate.id;
      
      v_assigned := v_assigned + 1;
    END LOOP;

    -- Check for holiday conflicts
    IF EXISTS (
      SELECT 1 FROM ia_holidays h
      WHERE h.holiday_date BETWEEN v_slot_start AND v_slot_start + INTERVAL '14 days'
    ) THEN
      INSERT INTO ia_availability_conflicts (plan_id, engagement_id, conflict_type, conflict_details, detected_at)
      VALUES (p_plan_id, NULL, 'Holiday Overlap',
        jsonb_build_object('candidate_id', v_candidate.id, 'entity', v_candidate.entity_name, 'slot_start', v_slot_start),
        now());
      v_conflicts := v_conflicts + 1;
    END IF;

    -- Stagger slots (2 weeks apart)
    v_slot_start := v_slot_start + INTERVAL '14 days';
    IF v_slot_start > v_plan_end THEN
      v_slot_start := v_plan_start; -- wrap around
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'assigned', v_assigned,
    'conflicts_detected', v_conflicts
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_check_data_readiness(p_plan_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dept_count integer;
  v_func_count integer;
  v_assessed_count integer;
  v_stale_count integer;
  v_weights_total numeric;
  v_freq_policy_count integer;
  v_auditor_count integer;
  v_warnings jsonb := '[]'::jsonb;
BEGIN
  -- Count departments
  SELECT COUNT(*) INTO v_dept_count FROM ia_departments WHERE is_active = true;
  IF v_dept_count = 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('type','error','area','departments','message','No active departments found'));
  END IF;

  -- Count functions
  SELECT COUNT(*) INTO v_func_count FROM ia_department_functions WHERE is_active = true;
  IF v_func_count = 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('type','error','area','functions','message','No active functions defined'));
  END IF;

  -- Risk assessments coverage
  SELECT COUNT(DISTINCT ra.function_id) INTO v_assessed_count
  FROM ia_risk_assessments ra WHERE ra.is_active = true;

  IF v_assessed_count < v_func_count AND v_func_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'type','warning','area','risk_assessments',
      'message', (v_func_count - v_assessed_count) || ' of ' || v_func_count || ' functions have no risk assessment'
    ));
  END IF;

  -- Stale assessments (> 12 months old)
  SELECT COUNT(DISTINCT ra.function_id) INTO v_stale_count
  FROM ia_risk_assessments ra
  WHERE ra.is_active = true AND ra.assessment_date < (CURRENT_DATE - interval '12 months');
  IF v_stale_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'type','warning','area','stale_assessments',
      'message', v_stale_count || ' risk assessments are older than 12 months'
    ));
  END IF;

  -- Weights validation
  SELECT COALESCE(SUM(weight), 0) INTO v_weights_total
  FROM ia_planning_scoring_weights WHERE is_active = true;
  IF ABS(v_weights_total - 1.0) > 0.01 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'type','warning','area','scoring_weights',
      'message', 'Scoring weights total ' || ROUND(v_weights_total, 2) || ' (should be 1.0)'
    ));
  END IF;

  -- Frequency policies
  SELECT COUNT(*) INTO v_freq_policy_count FROM ia_risk_band_frequency_policy WHERE is_active = true;
  IF v_freq_policy_count = 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('type','error','area','frequency_policy','message','No frequency policies configured'));
  END IF;

  -- Active auditors
  SELECT COUNT(*) INTO v_auditor_count FROM ia_auditors WHERE employment_status = 'Active';
  IF v_auditor_count = 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('type','warning','area','auditors','message','No active auditors available'));
  END IF;

  RETURN jsonb_build_object(
    'ready', NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_warnings) w WHERE w->>'type' = 'error'),
    'departments', v_dept_count,
    'functions', v_func_count,
    'assessed_functions', v_assessed_count,
    'stale_assessments', v_stale_count,
    'weights_valid', ABS(v_weights_total - 1.0) < 0.01,
    'frequency_policies', v_freq_policy_count,
    'active_auditors', v_auditor_count,
    'warnings', v_warnings
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_check_engagement_completeness(p_engagement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eng record;
  v_gate record;
  v_evidence_count integer;
  v_wp_count integer;
  v_findings_count integer;
  v_responses_pending integer;
  v_actions_pending integer;
  v_reasons text[] := '{}';
  v_result jsonb;
BEGIN
  SELECT * INTO v_eng FROM ia_audit_engagements WHERE id = p_engagement_id;
  IF v_eng IS NULL THEN
    RETURN jsonb_build_object('passed', false, 'reasons', ARRAY['Engagement not found']);
  END IF;

  SELECT * INTO v_gate FROM ia_execution_gate_config
  WHERE gate_type = 'engagement_closure' AND is_active = true LIMIT 1;

  -- Count artefacts
  SELECT count(*) INTO v_evidence_count FROM ia_evidence WHERE engagement_id = p_engagement_id;
  SELECT count(*) INTO v_wp_count FROM ia_working_papers WHERE engagement_id = p_engagement_id;
  SELECT count(*) INTO v_findings_count FROM ia_findings WHERE engagement_id = p_engagement_id;

  IF v_gate IS NOT NULL THEN
    IF v_evidence_count < v_gate.min_evidence_count THEN
      v_reasons := v_reasons || ('Minimum ' || v_gate.min_evidence_count || ' evidence item(s) required, found ' || v_evidence_count);
    END IF;
    IF v_wp_count < v_gate.min_working_papers_count THEN
      v_reasons := v_reasons || ('Minimum ' || v_gate.min_working_papers_count || ' working paper(s) required, found ' || v_wp_count);
    END IF;
    IF v_gate.min_findings_documented AND v_findings_count = 0 THEN
      v_reasons := v_reasons || 'At least one finding must be documented';
    END IF;
    IF v_gate.require_management_responses THEN
      SELECT count(*) INTO v_responses_pending
      FROM ia_findings f LEFT JOIN ia_management_responses mr ON mr.finding_id = f.id
      WHERE f.engagement_id = p_engagement_id AND mr.id IS NULL;
      IF v_responses_pending > 0 THEN
        v_reasons := v_reasons || (v_responses_pending || ' finding(s) missing management response');
      END IF;
    END IF;
    IF v_gate.require_action_plans THEN
      SELECT count(*) INTO v_actions_pending
      FROM ia_findings f LEFT JOIN ia_action_tracking at ON at.finding_id = f.id
      WHERE f.engagement_id = p_engagement_id AND at.id IS NULL;
      IF v_actions_pending > 0 THEN
        v_reasons := v_reasons || (v_actions_pending || ' finding(s) missing action plan');
      END IF;
    END IF;
  END IF;

  v_result := jsonb_build_object(
    'passed', array_length(v_reasons, 1) IS NULL,
    'evidence_count', v_evidence_count,
    'working_papers_count', v_wp_count,
    'findings_count', v_findings_count,
    'reasons', v_reasons,
    'checked_at', now()
  );

  -- Store result on engagement
  UPDATE ia_audit_engagements SET execution_gate_status = v_result WHERE id = p_engagement_id;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_check_launch_readiness(p_engagement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eng_name text;
  v_eng_status text;
  v_eng_approved_by text;
  v_eng_approved_at timestamptz;
  v_eng_annual_plan_id uuid;
  v_eng_department_id uuid;
  v_eng_function_id uuid;
  v_eng_lead_auditor_id uuid;
  v_eng_start date;
  v_eng_end date;
  v_eng_objectives text;
  v_eng_scope text;
  v_eng_auditee_contact text;
  v_eng_primary_auditee uuid;
  v_plan_status text;
  v_checks jsonb := '[]'::jsonb;
  v_all_passed boolean := true;
BEGIN
  SELECT engagement_name, status, approved_by, approved_at, annual_plan_id,
         department_id, function_id, lead_auditor_id, planned_start_date, planned_end_date,
         objectives, scope, auditee_contact, primary_auditee_contact_id
  INTO v_eng_name, v_eng_status, v_eng_approved_by, v_eng_approved_at, v_eng_annual_plan_id,
       v_eng_department_id, v_eng_function_id, v_eng_lead_auditor_id, v_eng_start, v_eng_end,
       v_eng_objectives, v_eng_scope, v_eng_auditee_contact, v_eng_primary_auditee
  FROM ia_audit_engagements WHERE id = p_engagement_id AND is_active = true;

  IF v_eng_name IS NULL AND v_eng_status IS NULL THEN
    RETURN jsonb_build_object('ready', false, 'checks', '[]'::jsonb, 'error', 'Engagement not found');
  END IF;

  -- 1. Engagement approved
  IF (v_eng_approved_by IS NOT NULL AND v_eng_approved_at IS NOT NULL) OR v_eng_status = 'Approved' THEN
    v_checks := v_checks || jsonb_build_object('item', 'Engagement approved', 'passed', true,
      'detail', 'Approved by ' || COALESCE(v_eng_approved_by, '-'));
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Engagement approved', 'passed', false,
      'detail', 'Status: ' || COALESCE(v_eng_status, 'Draft'));
    v_all_passed := false;
  END IF;

  -- 2. Parent plan approved
  IF v_eng_annual_plan_id IS NOT NULL THEN
    SELECT status INTO v_plan_status FROM ia_annual_plans WHERE id = v_eng_annual_plan_id;
    IF v_plan_status = 'Approved' THEN
      v_checks := v_checks || jsonb_build_object('item', 'Parent plan approved', 'passed', true);
    ELSE
      v_checks := v_checks || jsonb_build_object('item', 'Parent plan approved', 'passed', false,
        'detail', 'Plan status: ' || COALESCE(v_plan_status, 'N/A'));
      v_all_passed := false;
    END IF;
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Parent plan approved', 'passed', true, 'detail', 'Ad-hoc engagement');
  END IF;

  -- 3. Title
  IF v_eng_name IS NOT NULL AND v_eng_name != '' THEN
    v_checks := v_checks || jsonb_build_object('item', 'Engagement title defined', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Engagement title defined', 'passed', false);
    v_all_passed := false;
  END IF;

  -- 4. Department
  IF v_eng_department_id IS NOT NULL THEN
    v_checks := v_checks || jsonb_build_object('item', 'Department assigned', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Department assigned', 'passed', false);
    v_all_passed := false;
  END IF;

  -- 5. Function
  IF v_eng_function_id IS NOT NULL THEN
    v_checks := v_checks || jsonb_build_object('item', 'Business function assigned', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Business function assigned', 'passed', false);
    v_all_passed := false;
  END IF;

  -- 6. Lead auditor
  IF v_eng_lead_auditor_id IS NOT NULL THEN
    v_checks := v_checks || jsonb_build_object('item', 'Lead auditor assigned', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Lead auditor assigned', 'passed', false);
    v_all_passed := false;
  END IF;

  -- 7. Dates
  IF v_eng_start IS NOT NULL AND v_eng_end IS NOT NULL THEN
    v_checks := v_checks || jsonb_build_object('item', 'Planned dates entered', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Planned dates entered', 'passed', false,
      'detail', CASE
        WHEN v_eng_start IS NULL AND v_eng_end IS NULL THEN 'Start and end dates missing'
        WHEN v_eng_end IS NULL THEN 'End date missing'
        ELSE 'Start date missing'
      END);
    v_all_passed := false;
  END IF;

  -- 8. Objectives
  IF v_eng_objectives IS NOT NULL AND v_eng_objectives != '' THEN
    v_checks := v_checks || jsonb_build_object('item', 'Objectives defined', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Objectives defined', 'passed', false);
    v_all_passed := false;
  END IF;

  -- 9. Scope
  IF v_eng_scope IS NOT NULL AND v_eng_scope != '' THEN
    v_checks := v_checks || jsonb_build_object('item', 'Scope defined', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Scope defined', 'passed', false);
    v_all_passed := false;
  END IF;

  -- 10. Auditee contact
  IF v_eng_primary_auditee IS NOT NULL OR (v_eng_auditee_contact IS NOT NULL AND v_eng_auditee_contact != '') THEN
    v_checks := v_checks || jsonb_build_object('item', 'Auditee contact defined', 'passed', true);
  ELSE
    v_checks := v_checks || jsonb_build_object('item', 'Auditee contact defined', 'passed', false);
    v_all_passed := false;
  END IF;

  RETURN jsonb_build_object('ready', v_all_passed, 'checks', v_checks);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_check_overdue_actions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_overdue_count INT := 0; v_action RECORD;
BEGIN
  FOR v_action IN SELECT id, description, due_date FROM ia_action_tracking WHERE status NOT IN ('Completed','Closed','Verified') AND due_date < CURRENT_DATE
  LOOP
    INSERT INTO system_business_events (action, module, entity_type, entity_id, description)
    VALUES ('ia_action_overdue', 'internal_audit', 'audit_action', v_action.id, format('Action overdue: %s (due %s)', COALESCE(v_action.description, v_action.id::text), v_action.due_date));
    v_overdue_count := v_overdue_count + 1;
  END LOOP;
  FOR v_action IN SELECT id, description, target_resolution_date FROM ia_plan_carry_forward WHERE status NOT IN ('Resolved','Closed') AND target_resolution_date IS NOT NULL AND target_resolution_date < CURRENT_DATE
  LOOP
    UPDATE ia_plan_carry_forward SET escalation_count = escalation_count + 1, last_escalated_at = now() WHERE id = v_action.id;
    v_overdue_count := v_overdue_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'overdue_count', v_overdue_count);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_compute_engagement_priority_score(p_function_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_plan_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_risk_score numeric := 0;
  v_recency_score numeric := 0;
  v_findings_score numeric := 0;
  v_followup_score numeric := 0;
  v_compliance_score numeric := 0;
  v_change_score numeric := 0;
  v_total numeric := 0;
  v_weights jsonb;
  v_last_audit jsonb;
  v_months_since numeric;
  v_freq_months numeric := 24;
  v_reasons jsonb := '[]'::jsonb;
  v_is_overdue boolean := false;
  w_risk numeric := 0.35;
  w_recency numeric := 0.20;
  w_findings numeric := 0.15;
  w_followup numeric := 0.10;
  w_compliance numeric := 0.10;
  w_change numeric := 0.10;
  v_function_ids uuid[];
  v_risk_level text;
BEGIN
  SELECT jsonb_object_agg(factor_key, weight) INTO v_weights
  FROM ia_planning_scoring_weights
  WHERE is_active = true;

  IF v_weights IS NOT NULL THEN
    w_risk := COALESCE((v_weights->>'risk')::numeric, 0.35);
    w_recency := COALESCE((v_weights->>'recency')::numeric, 0.20);
    w_findings := COALESCE((v_weights->>'findings')::numeric, 0.15);
    w_followup := COALESCE((v_weights->>'followup')::numeric, 0.10);
    w_compliance := COALESCE((v_weights->>'compliance')::numeric, 0.10);
    w_change := COALESCE((v_weights->>'change')::numeric, 0.10);
  END IF;

  IF p_function_id IS NOT NULL THEN
    v_function_ids := ARRAY[p_function_id];
  ELSIF p_department_id IS NOT NULL THEN
    SELECT ARRAY_AGG(df.id) INTO v_function_ids
    FROM ia_department_functions df
    WHERE df.department_id = p_department_id
      AND df.is_active = true;
  END IF;

  IF v_function_ids IS NOT NULL AND array_length(v_function_ids, 1) > 0 THEN
    SELECT COALESCE(AVG(
      CASE ra.risk_level
        WHEN 'Critical' THEN 100
        WHEN 'High' THEN 80
        WHEN 'Medium' THEN 50
        WHEN 'Low' THEN 20
        ELSE 30
      END
    ), 30)
    INTO v_risk_score
    FROM ia_risk_assessments ra
    WHERE ra.is_active = true
      AND ra.function_id = ANY(v_function_ids);
  ELSE
    v_risk_score := 30;
  END IF;

  v_risk_level := CASE
    WHEN v_risk_score >= 80 THEN 'Critical'
    WHEN v_risk_score >= 50 THEN 'High'
    WHEN v_risk_score >= 25 THEN 'Medium'
    ELSE 'Low'
  END;

  v_last_audit := ia_resolve_last_audit_date(p_function_id, p_department_id);
  v_months_since := NULLIF(v_last_audit->>'months_since', '')::numeric;

  SELECT COALESCE(MIN(fp.max_months_between_audits), 24)
  INTO v_freq_months
  FROM ia_risk_band_frequency_policy fp
  WHERE fp.is_active = true
    AND fp.risk_level = v_risk_level;

  IF v_months_since IS NULL THEN
    v_recency_score := 100;
    v_reasons := v_reasons || '"NEVER_AUDITED"'::jsonb;
  ELSIF v_months_since >= 36 THEN
    v_recency_score := 100;
  ELSIF v_months_since >= 24 THEN
    v_recency_score := 80;
  ELSIF v_months_since >= 12 THEN
    v_recency_score := 50;
  ELSE
    v_recency_score := 20;
  END IF;

  SELECT LEAST(100, COUNT(*) * 20)
  INTO v_findings_score
  FROM ia_findings f
  JOIN ia_audit_engagements e ON e.id = f.engagement_id
  WHERE f.status NOT IN ('Closed', 'Resolved', 'Accepted')
    AND f.risk_rating IN ('High', 'Critical')
    AND (
      (p_department_id IS NOT NULL AND e.department_id = p_department_id)
      OR (p_function_id IS NOT NULL AND e.function_id = p_function_id)
    );

  IF v_findings_score > 0 THEN
    v_reasons := v_reasons || '"OPEN_FINDINGS"'::jsonb;
  END IF;

  SELECT LEAST(100, COUNT(*) * 25)
  INTO v_followup_score
  FROM ia_action_tracking a
  JOIN ia_audit_engagements e ON e.id = a.engagement_id
  WHERE a.status NOT IN ('Completed', 'Closed', 'Verified')
    AND a.target_date < CURRENT_DATE
    AND (
      (p_department_id IS NOT NULL AND e.department_id = p_department_id)
      OR (p_function_id IS NOT NULL AND e.function_id = p_function_id)
    );

  IF v_followup_score > 0 THEN
    v_reasons := v_reasons || '"OVERDUE_ACTIONS"'::jsonb;
  END IF;

  IF v_months_since IS NOT NULL AND v_months_since >= v_freq_months THEN
    v_compliance_score := 100;
    v_is_overdue := true;
  ELSIF v_months_since IS NOT NULL AND v_freq_months > 0 THEN
    v_compliance_score := ROUND((v_months_since / v_freq_months) * 100, 2);
  ELSE
    v_compliance_score := 100;
    v_is_overdue := true;
  END IF;

  SELECT LEAST(100, COUNT(*) * 33)
  INTO v_change_score
  FROM ia_change_events ce
  WHERE ce.is_active = true
    AND ce.event_date >= (CURRENT_DATE - interval '12 months')
    AND (
      (p_department_id IS NOT NULL AND ce.department_id = p_department_id)
      OR (p_function_id IS NOT NULL AND ce.function_id = p_function_id)
    );

  IF v_change_score > 0 THEN
    v_reasons := v_reasons || '"RECENT_CHANGES"'::jsonb;
  END IF;

  v_total := (w_risk * v_risk_score)
           + (w_recency * v_recency_score)
           + (w_findings * v_findings_score)
           + (w_followup * v_followup_score)
           + (w_compliance * v_compliance_score)
           + (w_change * v_change_score);

  RETURN jsonb_build_object(
    'total_score', ROUND(v_total, 2),
    'composite_score', ROUND(v_total, 2),
    'risk_score', ROUND(v_risk_score, 2),
    'risk_level', v_risk_level,
    'recency_score', ROUND(v_recency_score, 2),
    'findings_score', ROUND(v_findings_score, 2),
    'followup_score', ROUND(v_followup_score, 2),
    'compliance_score', ROUND(v_compliance_score, 2),
    'change_score', ROUND(v_change_score, 2),
    'weights', jsonb_build_object(
      'risk', w_risk,
      'recency', w_recency,
      'findings', w_findings,
      'followup', w_followup,
      'compliance', w_compliance,
      'change', w_change
    ),
    'last_audit', v_last_audit,
    'last_audit_date', v_last_audit->>'last_audit_date',
    'frequency_months', v_freq_months,
    'is_overdue', v_is_overdue,
    'reasons', v_reasons,
    'reason_codes', v_reasons
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_convert_candidates_to_engagements(p_plan_id uuid, p_created_by text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate RECORD;
  v_count integer := 0;
  v_eng_code text;
  v_fiscal_year text;
  v_quarter text;
  v_month text;
  v_est_days numeric;
  v_risk_label text;
  v_scope text;
  v_objectives text;
  v_rationale text;
  v_coverage text;
  v_deliverable text;
BEGIN
  SELECT fiscal_year INTO v_fiscal_year FROM ia_annual_plans WHERE id = p_plan_id;

  FOR v_candidate IN
    SELECT c.*, df.function_name, df.risk_rating AS func_risk_rating, 
           df.description AS func_description,
           d.name AS dept_name, d.head AS dept_head
    FROM ia_auto_plan_candidates c
    LEFT JOIN ia_department_functions df ON df.id = c.function_id
    LEFT JOIN ia_departments d ON d.id = c.department_id
    WHERE c.plan_id = p_plan_id AND c.accepted = true
      AND c.status = 'Accepted'
      AND NOT EXISTS (
        SELECT 1 FROM ia_audit_engagements e
        WHERE e.annual_plan_id = p_plan_id
          AND e.function_id = c.function_id
          AND (e.is_active = true OR e.is_active IS NULL)
      )
    ORDER BY c.rank_position ASC
  LOOP
    v_count := v_count + 1;
    v_eng_code := 'ENG-' || COALESCE(v_fiscal_year, EXTRACT(YEAR FROM CURRENT_DATE)::text) || '-' || LPAD(v_count::text, 3, '0');

    v_risk_label := CASE
      WHEN v_candidate.risk_score >= 75 THEN 'Critical'
      WHEN v_candidate.risk_score >= 50 THEN 'High'
      WHEN v_candidate.risk_score >= 25 THEN 'Medium'
      ELSE 'Low'
    END;

    v_quarter := COALESCE(v_candidate.suggested_quarter, 
      CASE EXTRACT(QUARTER FROM COALESCE(v_candidate.suggested_start_date, CURRENT_DATE))
        WHEN 1 THEN 'Q1' WHEN 2 THEN 'Q2' WHEN 3 THEN 'Q3' WHEN 4 THEN 'Q4'
      END);
    v_month := COALESCE(v_candidate.suggested_month,
      TO_CHAR(COALESCE(v_candidate.suggested_start_date, CURRENT_DATE), 'Month'));

    v_est_days := COALESCE(v_candidate.suggested_days,
      CASE v_risk_label
        WHEN 'Critical' THEN 20
        WHEN 'High' THEN 15
        WHEN 'Medium' THEN 10
        ELSE 5
      END);

    v_scope := COALESCE(v_candidate.suggested_scope,
      'Review and evaluate the ' || COALESCE(v_candidate.function_name, 'function') ||
      ' within the ' || COALESCE(v_candidate.dept_name, 'department') ||
      ' to assess adequacy and effectiveness of internal controls.');

    v_objectives := COALESCE(v_candidate.suggested_objectives,
      'Assess compliance with policies and procedures. Evaluate effectiveness of internal controls. ' ||
      'Identify risks and areas for improvement. Provide recommendations for management action.');

    v_rationale := '';
    IF v_candidate.reason_codes IS NOT NULL AND jsonb_array_length(v_candidate.reason_codes) > 0 THEN
      SELECT string_agg(val::text, ', ')
      INTO v_rationale
      FROM jsonb_array_elements_text(v_candidate.reason_codes) AS val;
      v_rationale := 'Included based on: ' || REPLACE(REPLACE(v_rationale, '_', ' '), '"', '');
    END IF;

    v_coverage := COALESCE(v_candidate.coverage_category, 'Operational');
    v_deliverable := 'Audit Report with findings and recommendations';

    INSERT INTO ia_audit_engagements (
      annual_plan_id, department_id, function_id,
      engagement_name, engagement_code, engagement_type,
      engagement_risk_rating, lead_auditor_id, reviewer_id,
      estimated_hours, estimated_days,
      planned_start_date, planned_end_date,
      quarter, month, sequence_no,
      scope, objectives, inclusion_rationale,
      coverage_category, expected_deliverable,
      auditable_area_summary, auditee_contact,
      status, is_active, created_by, created_at
    ) VALUES (
      p_plan_id, v_candidate.department_id, v_candidate.function_id,
      COALESCE(v_candidate.dept_name, '') || ' - ' || COALESCE(v_candidate.function_name, 'Audit'),
      v_eng_code, 'Planned Audit',
      v_risk_label, v_candidate.suggested_lead_auditor_id, v_candidate.suggested_reviewer_id,
      COALESCE(v_candidate.suggested_hours, CEIL(v_est_days / 5.0)), v_est_days,
      v_candidate.suggested_start_date, v_candidate.suggested_end_date,
      v_quarter, TRIM(v_month), v_count,
      v_scope, v_objectives, v_rationale,
      v_coverage, v_deliverable,
      COALESCE(v_candidate.func_description, v_candidate.function_name),
      COALESCE(v_candidate.dept_head, ''),
      'Planned', true, p_created_by, now()
    );

    UPDATE ia_auto_plan_candidates SET status = 'Converted' WHERE id = v_candidate.id;
  END LOOP;

  UPDATE ia_annual_plans SET total_department_audits = (
    SELECT COUNT(*) FROM ia_audit_engagements WHERE annual_plan_id = p_plan_id AND (is_active = true OR is_active IS NULL)
  ) WHERE id = p_plan_id;

  RETURN jsonb_build_object('success', true, 'engagements_created', v_count);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_create_plan_header(p_fiscal_year text, p_title text, p_objective text DEFAULT NULL::text, p_scope text DEFAULT NULL::text, p_methodology text DEFAULT NULL::text, p_created_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan_id uuid;
  v_existing uuid;
BEGIN
  -- Check if a plan already exists for this fiscal year
  SELECT id INTO v_existing FROM ia_annual_plans WHERE fiscal_year = p_fiscal_year LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'An annual plan already exists for fiscal year ' || p_fiscal_year, 'existing_plan_id', v_existing);
  END IF;

  INSERT INTO ia_annual_plans (fiscal_year, title, objective, scope, methodology, status, created_by, created_date)
  VALUES (p_fiscal_year, p_title, p_objective, p_scope, p_methodology, 'Draft', p_created_by, now())
  RETURNING id INTO v_plan_id;

  RETURN jsonb_build_object('success', true, 'plan_id', v_plan_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_departments_sync_from_master()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.source_department_id IS NOT NULL THEN
    SELECT m.name, m.office_code
      INTO NEW.name, NEW.office_code
      FROM public.tb_office_departments m
     WHERE m.id = NEW.source_department_id;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_detect_material_plan_changes(p_plan_id uuid, p_proposed_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan record;
  v_key text;
  v_old_value text;
  v_new_value text;
  v_material_fields text[] := ARRAY['title','fiscal_year','risk_level','assigned_auditor','department_id','function_id','scope','objective','planned_start_date','planned_end_date','budget_hours'];
  v_material_changes jsonb := '[]'::jsonb;
  v_minor_changes jsonb := '[]'::jsonb;
  v_has_material boolean := false;
BEGIN
  SELECT * INTO v_plan FROM ia_annual_plans WHERE id = p_plan_id;
  IF v_plan IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan not found');
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_proposed_changes) LOOP
    v_new_value := p_proposed_changes->>v_key;
    v_old_value := to_jsonb(v_plan)->>v_key;

    IF v_old_value IS DISTINCT FROM v_new_value THEN
      IF v_key = ANY(v_material_fields) THEN
        v_has_material := true;
        v_material_changes := v_material_changes || jsonb_build_object(
          'field', v_key,
          'old_value', COALESCE(v_old_value, ''),
          'new_value', COALESCE(v_new_value, ''),
          'is_material', true
        );
      ELSE
        v_minor_changes := v_minor_changes || jsonb_build_object(
          'field', v_key,
          'old_value', COALESCE(v_old_value, ''),
          'new_value', COALESCE(v_new_value, ''),
          'is_material', false
        );
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'has_material_changes', v_has_material,
    'material_changes', v_material_changes,
    'minor_changes', v_minor_changes,
    'total_changes', jsonb_array_length(v_material_changes) + jsonb_array_length(v_minor_changes),
    'requires_reapproval', v_has_material,
    'plan_status', v_plan.status
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_enforce_engagement_execution_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan_status text;
  v_gate_result jsonb;
  v_in_version boolean;
  v_plan_version integer;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  -- Gate 1: Moving to execution states requires approved plan + version membership
  IF NEW.status IN ('In Progress', 'Execution', 'Fieldwork') THEN
    IF NEW.annual_plan_id IS NOT NULL THEN
      SELECT status, current_version_number INTO v_plan_status, v_plan_version FROM ia_annual_plans WHERE id = NEW.annual_plan_id;
      IF v_plan_status IS NOT NULL AND v_plan_status NOT IN ('Approved', 'In Progress') THEN
        RAISE EXCEPTION 'Cannot start engagement: parent audit plan status is "%" — must be Approved or In Progress', v_plan_status;
      END IF;

      -- Check version membership
      SELECT EXISTS (
        SELECT 1 FROM ia_plan_version_engagements pve
        JOIN ia_plan_versions pv ON pv.id = pve.plan_version_id
        WHERE pve.engagement_id = NEW.id
          AND pv.plan_id = NEW.annual_plan_id
          AND pv.version_number = v_plan_version
          AND pve.change_type != 'removed'
      ) INTO v_in_version;
      
      IF NOT v_in_version THEN
        RAISE EXCEPTION 'Cannot start engagement: not included in current approved plan version (v%)', v_plan_version;
      END IF;
    END IF;

    IF NEW.lead_auditor_id IS NULL THEN
      RAISE EXCEPTION 'Cannot start engagement: a lead auditor must be assigned';
    END IF;

    IF NEW.planned_start_date IS NULL OR NEW.planned_end_date IS NULL THEN
      RAISE EXCEPTION 'Cannot start engagement: planned start and end dates are required';
    END IF;
  END IF;

  -- Gate 2: Moving to closure requires artefact completeness
  IF NEW.status IN ('Completed', 'Closed') AND OLD.status NOT IN ('Completed', 'Closed') THEN
    v_gate_result := ia_check_engagement_completeness(NEW.id);
    IF NOT (v_gate_result->>'passed')::boolean THEN
      RAISE EXCEPTION 'Cannot close engagement: completeness check failed — %', v_gate_result->>'reasons';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_fire_notification(p_event_code text, p_engagement_id uuid DEFAULT NULL::uuid, p_plan_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_recipient_user_id uuid DEFAULT NULL::uuid, p_recipient_email text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trigger record;
  v_log_id uuid;
BEGIN
  -- Check trigger is enabled
  SELECT * INTO v_trigger FROM ia_notification_triggers WHERE event_code = p_event_code AND is_enabled = true LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Notification trigger not found or disabled: ' || p_event_code);
  END IF;
  
  INSERT INTO ia_auto_notification_log (
    event_code, engagement_id, plan_id, entity_type, entity_id,
    recipient_user_id, recipient_email, subject, body, channel,
    delivery_status, metadata
  ) VALUES (
    p_event_code, p_engagement_id, p_plan_id, p_entity_type, p_entity_id,
    p_recipient_user_id, p_recipient_email, 
    COALESCE(p_subject, v_trigger.event_label),
    p_body, 'in_app', 'Queued', p_metadata
  ) RETURNING id INTO v_log_id;
  
  RETURN jsonb_build_object('success', true, 'notification_log_id', v_log_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_generate_auto_plan_candidates(p_plan_id uuid, p_fiscal_year text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_func RECORD;
  v_score jsonb;
  v_count integer := 0;
  v_run_id uuid := gen_random_uuid();
  v_candidate_id uuid;
  v_raw_findings integer := 0;
  v_raw_overdue integer := 0;
  v_raw_changes integer := 0;
  v_risk_assessment_id uuid;
  v_risk_assessment_date date;
  v_findings_mult numeric := 20;
  v_overdue_mult numeric := 25;
  v_change_mult numeric := 33;
  v_change_lookback numeric := 12;
  v_never_audited_default numeric := 100;
  v_param jsonb;
  v_risk_label text;
  v_est_days numeric;
  v_suggested_quarter text;
  v_slot_start date;
  v_slot_end date;
  v_scope text;
  v_objectives text;
  v_coverage text;
BEGIN
  v_param := ia_resolve_planning_parameter('findings_multiplier', p_plan_id);
  v_findings_mult := COALESCE(NULLIF(v_param->>'value', '')::numeric, 20);

  v_param := ia_resolve_planning_parameter('overdue_actions_multiplier', p_plan_id);
  v_overdue_mult := COALESCE(NULLIF(v_param->>'value', '')::numeric, 25);

  v_param := ia_resolve_planning_parameter('change_events_multiplier', p_plan_id);
  v_change_mult := COALESCE(NULLIF(v_param->>'value', '')::numeric, 33);

  v_param := ia_resolve_planning_parameter('change_lookback_months', p_plan_id);
  v_change_lookback := COALESCE(NULLIF(v_param->>'value', '')::numeric, 12);

  v_param := ia_resolve_planning_parameter('never_audited_recency_default', p_plan_id);
  v_never_audited_default := COALESCE(NULLIF(v_param->>'value', '')::numeric, 100);

  DELETE FROM public.ia_planning_score_explanations WHERE plan_id = p_plan_id;
  DELETE FROM public.ia_auto_plan_candidates WHERE plan_id = p_plan_id;

  FOR v_func IN
    SELECT
      df.id AS function_id,
      df.department_id,
      df.function_name,
      df.description AS func_desc,
      df.risk_rating AS func_risk,
      d.name AS dept_name,
      d.head AS dept_head
    FROM public.ia_department_functions df
    JOIN public.ia_departments d ON d.id = df.department_id
    WHERE df.is_active = true
      AND d.is_active = true
    ORDER BY df.department_id, df.function_name
  LOOP
    v_score := public.ia_compute_engagement_priority_score(v_func.function_id, v_func.department_id, p_plan_id);
    v_candidate_id := gen_random_uuid();

    v_risk_label := COALESCE(v_score->>'risk_level', CASE
      WHEN COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0) >= 80 THEN 'Critical'
      WHEN COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0) >= 50 THEN 'High'
      WHEN COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0) >= 25 THEN 'Medium'
      ELSE 'Low'
    END);

    v_est_days := CASE v_risk_label
      WHEN 'Critical' THEN 20
      WHEN 'High' THEN 15
      WHEN 'Medium' THEN 10
      ELSE 5
    END;

    v_suggested_quarter := CASE
      WHEN COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0) >= 50 THEN 'Q' || (1 + (v_count % 2))
      WHEN COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0) >= 25 THEN 'Q' || (2 + (v_count % 2))
      ELSE 'Q' || (3 + (v_count % 2))
    END;

    v_slot_start := CASE v_suggested_quarter
      WHEN 'Q1' THEN (EXTRACT(YEAR FROM CURRENT_DATE)::text || '-01-01')::date + ((v_count * 14 % 90) * INTERVAL '1 day')
      WHEN 'Q2' THEN (EXTRACT(YEAR FROM CURRENT_DATE)::text || '-04-01')::date + ((v_count * 14 % 90) * INTERVAL '1 day')
      WHEN 'Q3' THEN (EXTRACT(YEAR FROM CURRENT_DATE)::text || '-07-01')::date + ((v_count * 14 % 90) * INTERVAL '1 day')
      ELSE (EXTRACT(YEAR FROM CURRENT_DATE)::text || '-10-01')::date + ((v_count * 14 % 90) * INTERVAL '1 day')
    END;
    v_slot_end := v_slot_start + (v_est_days * INTERVAL '1 day');

    v_scope := 'Review and evaluate ' || COALESCE(v_func.function_name, 'function') ||
      ' within ' || COALESCE(v_func.dept_name, 'department') ||
      ' to assess internal controls adequacy and effectiveness.';

    v_objectives := 'Assess compliance with policies. Evaluate control effectiveness. Identify risks. Provide recommendations.';
    v_coverage := COALESCE(v_func.func_risk, 'Operational');

    INSERT INTO public.ia_auto_plan_candidates (
      id, plan_id, department_id, function_id, entity_name,
      risk_score, recency_score, findings_score, followup_score,
      compliance_score, change_score, composite_score,
      reason_codes, last_audit_date, frequency_policy_months, is_overdue,
      suggested_start_date, suggested_end_date, suggested_hours, suggested_days,
      suggested_quarter, suggested_month, coverage_category,
      suggested_scope, suggested_objectives,
      status, accepted
    ) VALUES (
      v_candidate_id, p_plan_id, v_func.department_id, v_func.function_id,
      COALESCE(v_func.dept_name, '') || ' → ' || COALESCE(v_func.function_name, ''),
      COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'recency_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'findings_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'followup_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'compliance_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'change_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'composite_score', '')::numeric, 0),
      COALESCE(v_score->'reason_codes', '[]'::jsonb),
      NULLIF(v_score->>'last_audit_date', '')::date,
      COALESCE(NULLIF(v_score->>'frequency_months', '')::integer, 24),
      COALESCE(NULLIF(v_score->>'is_overdue', '')::boolean, false),
      v_slot_start,
      v_slot_end,
      CEIL(v_est_days / 5.0),
      v_est_days,
      v_suggested_quarter,
      TO_CHAR(v_slot_start, 'Month'),
      v_coverage,
      v_scope,
      v_objectives,
      'Suggested',
      NULL
    );

    SELECT COUNT(*) INTO v_raw_findings
    FROM public.ia_findings f
    JOIN public.ia_audit_engagements e ON e.id = f.engagement_id
    WHERE f.status NOT IN ('Closed', 'Resolved', 'Accepted')
      AND f.risk_rating IN ('High', 'Critical')
      AND (e.department_id = v_func.department_id OR e.function_id = v_func.function_id);

    SELECT COUNT(*) INTO v_raw_overdue
    FROM public.ia_action_tracking a
    JOIN public.ia_audit_engagements e ON e.id = a.engagement_id
    WHERE a.status NOT IN ('Completed', 'Closed', 'Verified')
      AND a.target_date < CURRENT_DATE
      AND (e.department_id = v_func.department_id OR e.function_id = v_func.function_id);

    SELECT COUNT(*) INTO v_raw_changes
    FROM public.ia_change_events ce
    WHERE ce.is_active = true
      AND ce.event_date >= (CURRENT_DATE - ((v_change_lookback || ' months')::interval))
      AND (ce.department_id = v_func.department_id OR ce.function_id = v_func.function_id);

    SELECT ra.id, ra.assessment_date
    INTO v_risk_assessment_id, v_risk_assessment_date
    FROM public.ia_risk_assessments ra
    WHERE ra.function_id = v_func.function_id
      AND ra.is_active = true
    ORDER BY ra.assessment_date DESC
    LIMIT 1;

    INSERT INTO public.ia_planning_score_explanations (
      plan_id, candidate_id, function_id, department_id, generation_run_id,
      raw_risk_score, raw_recency_months, raw_findings_count, raw_overdue_actions_count, raw_change_events_count,
      norm_risk_score, norm_recency_score, norm_findings_score, norm_followup_score, norm_compliance_score, norm_change_score,
      weight_risk, weight_recency, weight_findings, weight_followup, weight_compliance, weight_change,
      contrib_risk, contrib_recency, contrib_findings, contrib_followup, contrib_compliance, contrib_change,
      final_composite_score, reason_codes,
      risk_assessment_id, risk_assessment_date,
      last_audit_source, last_audit_date, frequency_policy_months,
      parameter_versions, resolved_scope, generated_at
    ) VALUES (
      p_plan_id, v_candidate_id, v_func.function_id, v_func.department_id, v_run_id,
      COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0),
      NULLIF(v_score->'last_audit'->>'months_since', '')::numeric,
      v_raw_findings, v_raw_overdue, v_raw_changes,
      COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'recency_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'findings_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'followup_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'compliance_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->>'change_score', '')::numeric, 0),
      COALESCE(NULLIF(v_score->'weights'->>'risk', '')::numeric, 0.35),
      COALESCE(NULLIF(v_score->'weights'->>'recency', '')::numeric, 0.20),
      COALESCE(NULLIF(v_score->'weights'->>'findings', '')::numeric, 0.15),
      COALESCE(NULLIF(v_score->'weights'->>'followup', '')::numeric, 0.10),
      COALESCE(NULLIF(v_score->'weights'->>'compliance', '')::numeric, 0.10),
      COALESCE(NULLIF(v_score->'weights'->>'change', '')::numeric, 0.10),
      ROUND(COALESCE(NULLIF(v_score->'weights'->>'risk', '')::numeric, 0.35) * COALESCE(NULLIF(v_score->>'risk_score', '')::numeric, 0), 2),
      ROUND(COALESCE(NULLIF(v_score->'weights'->>'recency', '')::numeric, 0.20) * COALESCE(NULLIF(v_score->>'recency_score', '')::numeric, 0), 2),
      ROUND(COALESCE(NULLIF(v_score->'weights'->>'findings', '')::numeric, 0.15) * COALESCE(NULLIF(v_score->>'findings_score', '')::numeric, 0), 2),
      ROUND(COALESCE(NULLIF(v_score->'weights'->>'followup', '')::numeric, 0.10) * COALESCE(NULLIF(v_score->>'followup_score', '')::numeric, 0), 2),
      ROUND(COALESCE(NULLIF(v_score->'weights'->>'compliance', '')::numeric, 0.10) * COALESCE(NULLIF(v_score->>'compliance_score', '')::numeric, 0), 2),
      ROUND(COALESCE(NULLIF(v_score->'weights'->>'change', '')::numeric, 0.10) * COALESCE(NULLIF(v_score->>'change_score', '')::numeric, 0), 2),
      COALESCE(NULLIF(v_score->>'composite_score', '')::numeric, 0),
      COALESCE(v_score->'reason_codes', '[]'::jsonb),
      v_risk_assessment_id,
      v_risk_assessment_date,
      v_score->'last_audit'->>'source',
      NULLIF(v_score->>'last_audit_date', '')::date,
      COALESCE(NULLIF(v_score->>'frequency_months', '')::integer, 24),
      jsonb_build_object(
        'findings_multiplier', v_findings_mult,
        'overdue_actions_multiplier', v_overdue_mult,
        'change_events_multiplier', v_change_mult,
        'change_lookback_months', v_change_lookback,
        'never_audited_recency_default', v_never_audited_default
      ),
      v_scope,
      now()
    );

    v_count := v_count + 1;
  END LOOP;

  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY composite_score DESC, entity_name ASC) AS rn
    FROM public.ia_auto_plan_candidates
    WHERE plan_id = p_plan_id
  )
  UPDATE public.ia_auto_plan_candidates c
  SET rank_position = ranked.rn
  FROM ranked
  WHERE c.id = ranked.id;

  RETURN jsonb_build_object(
    'success', true,
    'candidates_generated', v_count,
    'run_id', v_run_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_generate_resource_recommendations(p_plan_id uuid, p_candidate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_candidate RECORD;
  v_auditor RECORD;
  v_fit_score numeric;
  v_avail_score numeric;
  v_skill_score numeric;
  v_prior_score numeric;
  v_rotation_score numeric;
  v_conflicts jsonb;
  v_workload_current numeric;
  v_rank integer;
  v_count integer := 0;
BEGIN
  -- Clear previous recommendations for this scope
  IF p_candidate_id IS NOT NULL THEN
    DELETE FROM ia_resource_recommendations WHERE plan_id = p_plan_id AND candidate_id = p_candidate_id;
  ELSE
    DELETE FROM ia_resource_recommendations WHERE plan_id = p_plan_id;
  END IF;

  -- For each candidate (or specific one)
  FOR v_candidate IN
    SELECT c.* FROM ia_auto_plan_candidates c
    WHERE c.plan_id = p_plan_id
      AND c.status IN ('Suggested', 'Accepted')
      AND (p_candidate_id IS NULL OR c.id = p_candidate_id)
  LOOP
    v_rank := 0;

    FOR v_auditor IN
      SELECT a.id, a.name, a.role, a.skills, a.certifications
      FROM ia_auditors a
      WHERE a.employment_status = 'Active'
    LOOP
      v_rank := v_rank + 1;

      -- Availability: check existing assigned hours
      SELECT COALESCE(SUM(c2.suggested_hours), 0) INTO v_workload_current
      FROM ia_auto_plan_candidates c2
      WHERE c2.plan_id = p_plan_id
        AND c2.suggested_lead_auditor_id = v_auditor.id
        AND c2.status IN ('Accepted', 'Suggested');

      v_avail_score := GREATEST(0, 100 - (v_workload_current / 2));

      -- Skill match: simple heuristic
      v_skill_score := 50; -- baseline

      -- Prior involvement: bonus if audited same department before
      SELECT CASE WHEN COUNT(*) > 0 THEN 30 ELSE 0 END INTO v_prior_score
      FROM ia_audit_engagements e
      WHERE e.lead_auditor_id = v_auditor.id
        AND e.department_id = v_candidate.department_id
        AND e.status IN ('Completed', 'Closed');

      -- Rotation: penalty if just audited same function
      SELECT CASE WHEN COUNT(*) > 0 THEN -20 ELSE 10 END INTO v_rotation_score
      FROM ia_audit_engagements e
      WHERE e.lead_auditor_id = v_auditor.id
        AND e.function_id = v_candidate.function_id
        AND e.status IN ('Completed', 'Closed')
        AND e.actual_end_date >= (CURRENT_DATE - interval '12 months');

      -- Conflicts
      v_conflicts := '[]'::jsonb;
      -- Check date overlap with existing assignments
      IF v_candidate.suggested_start_date IS NOT NULL THEN
        PERFORM 1 FROM ia_auto_plan_candidates c3
        WHERE c3.plan_id = p_plan_id
          AND c3.suggested_lead_auditor_id = v_auditor.id
          AND c3.id != v_candidate.id
          AND c3.suggested_start_date IS NOT NULL
          AND c3.suggested_start_date < COALESCE(v_candidate.suggested_end_date, v_candidate.suggested_start_date + 30)
          AND COALESCE(c3.suggested_end_date, c3.suggested_start_date + 30) > v_candidate.suggested_start_date;
        IF FOUND THEN
          v_conflicts := v_conflicts || jsonb_build_array('Schedule overlap with another assignment');
        END IF;
      END IF;

      v_fit_score := ROUND((v_avail_score * 0.35 + v_skill_score * 0.25 + v_prior_score * 0.20 + v_rotation_score * 0.20), 2);

      INSERT INTO ia_resource_recommendations (
        plan_id, candidate_id, auditor_id,
        fit_score, availability_score, skill_match_score, prior_involvement_score, rotation_score,
        reason_text, workload_hours_current,
        workload_hours_if_assigned, conflict_indicators, recommendation_rank
      ) VALUES (
        p_plan_id, v_candidate.id, v_auditor.id,
        v_fit_score, v_avail_score, v_skill_score, v_prior_score, v_rotation_score,
        'Availability: ' || ROUND(v_avail_score) || '%, Skill: ' || v_skill_score || ', Prior: ' || v_prior_score || ', Rotation: ' || v_rotation_score,
        v_workload_current,
        v_workload_current + COALESCE(v_candidate.suggested_hours, 60),
        v_conflicts,
        v_rank
      );
      v_count := v_count + 1;
    END LOOP;

    -- Re-rank by fit score
    WITH reranked AS (
      SELECT rr.id, ROW_NUMBER() OVER (PARTITION BY rr.candidate_id ORDER BY rr.fit_score DESC) AS rn
      FROM ia_resource_recommendations rr
      WHERE rr.plan_id = p_plan_id AND rr.candidate_id = v_candidate.id
    )
    UPDATE ia_resource_recommendations r SET recommendation_rank = reranked.rn
    FROM reranked WHERE r.id = reranked.id;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'recommendations_generated', v_count);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_get_communication_timeline(p_engagement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_all_stages TEXT[] := ARRAY['PLAN_INTIMATION','TEAM_AND_SCOPE_NOTICE','DOC_REQUEST','ENTRANCE_MEETING','QUERY_CYCLE','DRAFT_FINDING_DISCUSSION','EXIT_MEETING','FINAL_REPORT_ISSUE','ACTION_PLAN_REMINDER'];
  v_stage TEXT;
  v_result JSONB := '[]'::jsonb;
  v_stage_obj JSONB;
BEGIN
  FOREACH v_stage IN ARRAY v_all_stages LOOP
    v_stage_obj := jsonb_build_object(
      'stage_code', v_stage,
      'stage_order', CASE v_stage
        WHEN 'PLAN_INTIMATION' THEN 1 WHEN 'TEAM_AND_SCOPE_NOTICE' THEN 2
        WHEN 'DOC_REQUEST' THEN 3 WHEN 'ENTRANCE_MEETING' THEN 4
        WHEN 'QUERY_CYCLE' THEN 5 WHEN 'DRAFT_FINDING_DISCUSSION' THEN 6
        WHEN 'EXIT_MEETING' THEN 7 WHEN 'FINAL_REPORT_ISSUE' THEN 8
        WHEN 'ACTION_PLAN_REMINDER' THEN 9
      END,
      'is_mandatory', COALESCE((SELECT tpm.is_mandatory FROM ia_template_policy_matrix tpm WHERE tpm.stage_code = v_stage AND tpm.is_active LIMIT 1), false),
      'completed', EXISTS (SELECT 1 FROM ia_communication_stages cs WHERE cs.engagement_id = p_engagement_id AND cs.stage_code = v_stage AND cs.delivery_status IN ('Sent','Delivered','Acknowledged')),
      'acknowledged', EXISTS (SELECT 1 FROM ia_communication_stages cs WHERE cs.engagement_id = p_engagement_id AND cs.stage_code = v_stage AND cs.acknowledged_at IS NOT NULL),
      'entries', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', cs.id, 'sent_at', cs.sent_at, 'recipient_name', cs.recipient_name,
          'recipient_email', cs.recipient_email, 'template_name', cs.template_name,
          'delivery_status', cs.delivery_status, 'acknowledged_at', cs.acknowledged_at,
          'acknowledgment_required', cs.acknowledgment_required, 'notes', cs.notes
        ) ORDER BY cs.sent_at)
        FROM ia_communication_stages cs WHERE cs.engagement_id = p_engagement_id AND cs.stage_code = v_stage
      ), '[]'::jsonb)
    );
    v_result := v_result || v_stage_obj;
  END LOOP;
  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_get_notification_log(p_engagement_id uuid DEFAULT NULL::uuid, p_plan_id uuid DEFAULT NULL::uuid, p_event_code text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_agg(row_to_json(n.*) ORDER BY n.created_at DESC)
  INTO v_result
  FROM (
    SELECT * FROM ia_auto_notification_log nl
    WHERE (p_engagement_id IS NULL OR nl.engagement_id = p_engagement_id)
      AND (p_plan_id IS NULL OR nl.plan_id = p_plan_id)
      AND (p_event_code IS NULL OR nl.event_code = p_event_code)
    ORDER BY nl.created_at DESC
    LIMIT p_limit
  ) n;
  
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_launch_engagement(p_engagement_id uuid, p_launched_by text DEFAULT 'SYSTEM'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eng_name text;
  v_eng_status text;
  v_eng_exec_status text;
  v_eng_approved_by text;
  v_eng_approved_at timestamptz;
  v_eng_annual_plan_id uuid;
  v_eng_department_id uuid;
  v_eng_function_id uuid;
  v_eng_lead_auditor_id uuid;
  v_eng_start date;
  v_eng_end date;
  v_eng_actual_start date;
  v_eng_objectives text;
  v_eng_scope text;
  v_eng_auditee_contact text;
  v_eng_primary_auditee uuid;
  v_plan_status text;
  v_errors text[] := '{}';
BEGIN
  SELECT engagement_name, status, execution_status, approved_by, approved_at, annual_plan_id,
         department_id, function_id, lead_auditor_id, planned_start_date, planned_end_date,
         actual_start_date, objectives, scope, auditee_contact, primary_auditee_contact_id
  INTO v_eng_name, v_eng_status, v_eng_exec_status, v_eng_approved_by, v_eng_approved_at, v_eng_annual_plan_id,
       v_eng_department_id, v_eng_function_id, v_eng_lead_auditor_id, v_eng_start, v_eng_end,
       v_eng_actual_start, v_eng_objectives, v_eng_scope, v_eng_auditee_contact, v_eng_primary_auditee
  FROM ia_audit_engagements WHERE id = p_engagement_id AND is_active = true;

  IF v_eng_name IS NULL AND v_eng_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Engagement not found');
  END IF;

  IF v_eng_exec_status NOT IN ('Planned', 'Ready for Launch') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Engagement already launched (current: ' || COALESCE(v_eng_exec_status, 'NULL') || ')');
  END IF;

  -- Check parent plan
  IF v_eng_annual_plan_id IS NOT NULL THEN
    SELECT status INTO v_plan_status FROM ia_annual_plans WHERE id = v_eng_annual_plan_id;
    IF v_plan_status IS NULL OR v_plan_status != 'Approved' THEN
      v_errors := array_append(v_errors, 'Parent plan not approved (status: ' || COALESCE(v_plan_status, 'N/A') || ')');
    END IF;
  END IF;

  IF v_eng_name IS NULL OR v_eng_name = '' THEN v_errors := array_append(v_errors, 'Title missing'); END IF;
  IF v_eng_department_id IS NULL THEN v_errors := array_append(v_errors, 'Department not assigned'); END IF;
  IF v_eng_function_id IS NULL THEN v_errors := array_append(v_errors, 'Function not assigned'); END IF;
  IF v_eng_lead_auditor_id IS NULL THEN v_errors := array_append(v_errors, 'Lead auditor not assigned'); END IF;
  IF v_eng_start IS NULL OR v_eng_end IS NULL THEN v_errors := array_append(v_errors, 'Planned dates missing'); END IF;
  IF v_eng_objectives IS NULL OR v_eng_objectives = '' THEN v_errors := array_append(v_errors, 'Objectives missing'); END IF;
  IF v_eng_scope IS NULL OR v_eng_scope = '' THEN v_errors := array_append(v_errors, 'Scope missing'); END IF;
  IF v_eng_primary_auditee IS NULL AND (v_eng_auditee_contact IS NULL OR v_eng_auditee_contact = '') THEN
    v_errors := array_append(v_errors, 'Auditee contact missing');
  END IF;

  IF array_length(v_errors, 1) > 0 THEN
    RETURN jsonb_build_object('success', false, 'errors', to_jsonb(v_errors),
      'error', 'Launch readiness failed: ' || array_to_string(v_errors, '; '));
  END IF;

  -- Launch
  UPDATE ia_audit_engagements SET
    execution_status = 'Notification Sent',
    status = CASE WHEN status IN ('Planned', 'Approved') THEN 'In Progress' ELSE status END,
    launched_at = now(),
    launched_by = COALESCE(p_launched_by, 'SYSTEM'),
    actual_start_date = COALESCE(v_eng_actual_start, now()::date),
    updated_at = now(),
    updated_by = COALESCE(p_launched_by, 'SYSTEM')
  WHERE id = p_engagement_id;

  INSERT INTO ia_engagement_execution_log (engagement_id, event_type, event_description, old_status, new_status, performed_by)
  VALUES (p_engagement_id, 'ENGAGEMENT_LAUNCHED', 'Engagement launched for execution',
    COALESCE(v_eng_exec_status, 'Planned'), 'Notification Sent', COALESCE(p_launched_by, 'SYSTEM'));

  RETURN jsonb_build_object('success', true, 'message', 'Engagement launched successfully', 'new_execution_status', 'Notification Sent');
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_persist_plan_engagements(p_plan_id uuid, p_engagements jsonb, p_created_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan_status text;
  v_eng jsonb;
  v_eng_id uuid;
  v_inserted int := 0;
  v_updated int := 0;
  v_code text;
BEGIN
  -- Verify plan exists and is Draft
  SELECT status INTO v_plan_status FROM ia_annual_plans WHERE id = p_plan_id;
  IF v_plan_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan not found');
  END IF;
  IF v_plan_status NOT IN ('Draft', 'Revision') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Engagements can only be modified on Draft or Revision plans. Current status: ' || v_plan_status);
  END IF;

  FOR v_eng IN SELECT * FROM jsonb_array_elements(p_engagements)
  LOOP
    v_eng_id := (v_eng->>'id')::uuid;
    
    IF v_eng_id IS NOT NULL THEN
      -- Update existing engagement
      UPDATE ia_audit_engagements SET
        engagement_name = COALESCE(v_eng->>'engagement_name', engagement_name),
        department_id = (v_eng->>'department_id')::uuid,
        function_id = (v_eng->>'function_id')::uuid,
        engagement_type = COALESCE(v_eng->>'engagement_type', engagement_type),
        engagement_risk_rating = COALESCE(v_eng->>'engagement_risk_rating', engagement_risk_rating),
        planned_start_date = (v_eng->>'planned_start_date')::date,
        planned_end_date = (v_eng->>'planned_end_date')::date,
        lead_auditor_id = (v_eng->>'lead_auditor_id')::uuid,
        supportive_auditor_ids = COALESCE(v_eng->'supportive_auditor_ids', '[]'::jsonb),
        scope = v_eng->>'scope',
        updated_by = p_created_by,
        updated_at = now()
      WHERE id = v_eng_id AND annual_plan_id = p_plan_id;
      v_updated := v_updated + 1;
    ELSE
      -- Generate engagement code
      v_code := 'ENG-' || to_char(now(), 'YYYYMMDD') || '-' || lpad((floor(random() * 9000 + 1000))::text, 4, '0');
      
      INSERT INTO ia_audit_engagements (
        annual_plan_id, engagement_name, engagement_code, department_id, function_id,
        engagement_type, engagement_risk_rating, planned_start_date, planned_end_date,
        lead_auditor_id, supportive_auditor_ids, scope, status, created_by, created_at
      ) VALUES (
        p_plan_id,
        v_eng->>'engagement_name',
        COALESCE(v_eng->>'engagement_code', v_code),
        (v_eng->>'department_id')::uuid,
        (v_eng->>'function_id')::uuid,
        COALESCE(v_eng->>'engagement_type', 'Planned Audit'),
        COALESCE(v_eng->>'engagement_risk_rating', 'Medium'),
        (v_eng->>'planned_start_date')::date,
        (v_eng->>'planned_end_date')::date,
        (v_eng->>'lead_auditor_id')::uuid,
        COALESCE(v_eng->'supportive_auditor_ids', '[]'::jsonb),
        v_eng->>'scope',
        'Planned',
        p_created_by,
        now()
      );
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  -- Update plan engagement count
  UPDATE ia_annual_plans 
  SET total_department_audits = (SELECT count(*) FROM ia_audit_engagements WHERE annual_plan_id = p_plan_id AND is_active = true),
      updated_at = now(), updated_by = p_created_by
  WHERE id = p_plan_id;

  RETURN jsonb_build_object('success', true, 'inserted', v_inserted, 'updated', v_updated);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_recalculate_all_risks(p_reason text DEFAULT 'config_changed'::text, p_triggered_by text DEFAULT 'SYSTEM'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_formula_type TEXT;
  v_count INTEGER := 0;
  v_risk RECORD;
  v_new_inherent_score NUMERIC;
  v_new_residual_score NUMERIC;
  v_new_inherent_level TEXT;
  v_new_residual_level TEXT;
  v_band RECORD;
BEGIN
  SELECT formula_type INTO v_formula_type
  FROM ia_risk_config_master
  WHERE is_active = true
  ORDER BY version DESC
  LIMIT 1;

  IF v_formula_type IS NULL THEN
    v_formula_type := 'likelihood_x_impact';
  END IF;

  FOR v_risk IN
    SELECT id, inherent_likelihood, inherent_impact, residual_likelihood, residual_impact,
           inherent_risk_score, inherent_risk_level, residual_risk_score, residual_risk_level,
           is_score_overridden
    FROM ia_risk_register
    WHERE is_active = true
  LOOP
    -- Skip manually overridden risks — log but do not change
    IF v_risk.is_score_overridden THEN
      INSERT INTO ia_risk_recalc_log (
        risk_id, trigger_reason,
        old_inherent_score, new_inherent_score, old_inherent_level, new_inherent_level,
        old_residual_score, new_residual_score, old_residual_level, new_residual_level,
        recalculated_by
      ) VALUES (
        v_risk.id, 'skipped_override: ' || p_reason,
        v_risk.inherent_risk_score, v_risk.inherent_risk_score, v_risk.inherent_risk_level, v_risk.inherent_risk_level,
        v_risk.residual_risk_score, v_risk.residual_risk_score, v_risk.residual_risk_level, v_risk.residual_risk_level,
        p_triggered_by
      );
      CONTINUE;
    END IF;

    CASE v_formula_type
      WHEN 'likelihood_x_impact' THEN
        v_new_inherent_score := COALESCE(v_risk.inherent_likelihood, 0) * COALESCE(v_risk.inherent_impact, 0);
        v_new_residual_score := COALESCE(v_risk.residual_likelihood, 0) * COALESCE(v_risk.residual_impact, 0);
      WHEN 'likelihood_plus_impact' THEN
        v_new_inherent_score := COALESCE(v_risk.inherent_likelihood, 0) + COALESCE(v_risk.inherent_impact, 0);
        v_new_residual_score := COALESCE(v_risk.residual_likelihood, 0) + COALESCE(v_risk.residual_impact, 0);
      WHEN 'weighted_average' THEN
        v_new_inherent_score := ROUND((COALESCE(v_risk.inherent_likelihood, 0) + COALESCE(v_risk.inherent_impact, 0)) / 2.0);
        v_new_residual_score := ROUND((COALESCE(v_risk.residual_likelihood, 0) + COALESCE(v_risk.residual_impact, 0)) / 2.0);
      ELSE
        v_new_inherent_score := COALESCE(v_risk.inherent_likelihood, 0) * COALESCE(v_risk.inherent_impact, 0);
        v_new_residual_score := COALESCE(v_risk.residual_likelihood, 0) * COALESCE(v_risk.residual_impact, 0);
    END CASE;

    v_new_inherent_level := 'Unknown';
    FOR v_band IN
      SELECT label, min_score, max_score FROM ia_risk_classification_thresholds WHERE is_active = true ORDER BY sort_order
    LOOP
      IF v_new_inherent_score >= v_band.min_score AND v_new_inherent_score <= v_band.max_score THEN
        v_new_inherent_level := v_band.label; EXIT;
      END IF;
    END LOOP;

    v_new_residual_level := 'Unknown';
    FOR v_band IN
      SELECT label, min_score, max_score FROM ia_risk_classification_thresholds WHERE is_active = true ORDER BY sort_order
    LOOP
      IF v_new_residual_score >= v_band.min_score AND v_new_residual_score <= v_band.max_score THEN
        v_new_residual_level := v_band.label; EXIT;
      END IF;
    END LOOP;

    IF v_new_inherent_score IS DISTINCT FROM v_risk.inherent_risk_score
       OR v_new_inherent_level IS DISTINCT FROM v_risk.inherent_risk_level
       OR v_new_residual_score IS DISTINCT FROM v_risk.residual_risk_score
       OR v_new_residual_level IS DISTINCT FROM v_risk.residual_risk_level
    THEN
      INSERT INTO ia_risk_recalc_log (
        risk_id, trigger_reason,
        old_inherent_score, new_inherent_score, old_inherent_level, new_inherent_level,
        old_residual_score, new_residual_score, old_residual_level, new_residual_level,
        recalculated_by
      ) VALUES (
        v_risk.id, p_reason,
        v_risk.inherent_risk_score, v_new_inherent_score, v_risk.inherent_risk_level, v_new_inherent_level,
        v_risk.residual_risk_score, v_new_residual_score, v_risk.residual_risk_level, v_new_residual_level,
        p_triggered_by
      );

      UPDATE ia_risk_register SET
        inherent_risk_score = v_new_inherent_score,
        inherent_risk_level = v_new_inherent_level,
        residual_risk_score = v_new_residual_score,
        residual_risk_level = v_new_residual_level,
        updated_at = now(),
        updated_by = p_triggered_by
      WHERE id = v_risk.id;

      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_record_communication_stage(p_engagement_id uuid, p_stage_code text, p_template_id uuid DEFAULT NULL::uuid, p_recipient_name text DEFAULT NULL::text, p_recipient_email text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_created_by text DEFAULT NULL::text, p_acknowledgment_required boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stage_order INT;
  v_template_name TEXT;
  v_policy RECORD;
  v_stage_id UUID;
BEGIN
  v_stage_order := CASE p_stage_code
    WHEN 'PLAN_INTIMATION' THEN 1 WHEN 'TEAM_AND_SCOPE_NOTICE' THEN 2
    WHEN 'DOC_REQUEST' THEN 3 WHEN 'ENTRANCE_MEETING' THEN 4
    WHEN 'QUERY_CYCLE' THEN 5 WHEN 'DRAFT_FINDING_DISCUSSION' THEN 6
    WHEN 'EXIT_MEETING' THEN 7 WHEN 'FINAL_REPORT_ISSUE' THEN 8
    WHEN 'ACTION_PLAN_REMINDER' THEN 9 ELSE 99
  END;

  IF p_template_id IS NOT NULL THEN
    SELECT name INTO v_template_name FROM ia_document_templates WHERE id = p_template_id;
    SELECT * INTO v_policy FROM ia_template_policy_matrix WHERE stage_code = p_stage_code AND is_active = true LIMIT 1;
    IF v_policy IS NOT NULL AND v_policy.is_mandatory THEN
      IF NOT EXISTS (SELECT 1 FROM ia_document_templates WHERE id = p_template_id AND category = v_policy.required_template_category AND is_active = true) THEN
        RETURN jsonb_build_object('success', false, 'error', format('Template must be of category "%s" for stage %s', v_policy.required_template_category, p_stage_code));
      END IF;
    END IF;
  END IF;

  IF p_stage_code != 'QUERY_CYCLE' THEN
    IF EXISTS (SELECT 1 FROM ia_communication_stages WHERE engagement_id = p_engagement_id AND stage_code = p_stage_code AND delivery_status IN ('Sent','Delivered','Acknowledged')) THEN
      RETURN jsonb_build_object('success', false, 'error', format('Stage %s already completed for this engagement', p_stage_code));
    END IF;
  END IF;

  INSERT INTO ia_communication_stages (engagement_id, stage_code, stage_order, template_id, template_name, recipient_name, recipient_email, sent_at, acknowledgment_required, delivery_status, notes, created_by)
  VALUES (p_engagement_id, p_stage_code, v_stage_order, p_template_id, v_template_name, p_recipient_name, p_recipient_email, now(), p_acknowledgment_required, 'Sent', p_notes, p_created_by)
  RETURNING id INTO v_stage_id;

  RETURN jsonb_build_object('success', true, 'stage_id', v_stage_id, 'stage_code', p_stage_code, 'stage_order', v_stage_order);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_record_communication_stage(p_engagement_id uuid, p_stage_code text, p_template_id uuid DEFAULT NULL::uuid, p_recipient_name text DEFAULT NULL::text, p_recipient_email text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_created_by text DEFAULT NULL::text, p_acknowledgment_required boolean DEFAULT false, p_mode text DEFAULT 'send'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_stage_order INT;
  v_template_name TEXT;
  v_policy RECORD;
  v_stage_id UUID;
  v_delivery_status TEXT;
BEGIN
  v_stage_order := CASE p_stage_code
    WHEN 'PLAN_INTIMATION' THEN 1 WHEN 'TEAM_AND_SCOPE_NOTICE' THEN 2
    WHEN 'DOC_REQUEST' THEN 3 WHEN 'ENTRANCE_MEETING' THEN 4
    WHEN 'QUERY_CYCLE' THEN 5 WHEN 'DRAFT_FINDING_DISCUSSION' THEN 6
    WHEN 'EXIT_MEETING' THEN 7 WHEN 'FINAL_REPORT_ISSUE' THEN 8
    WHEN 'ACTION_PLAN_REMINDER' THEN 9 ELSE 99
  END;

  IF p_template_id IS NOT NULL THEN
    SELECT name INTO v_template_name FROM ia_document_templates WHERE id = p_template_id;
    SELECT * INTO v_policy FROM ia_template_policy_matrix WHERE stage_code = p_stage_code AND is_active = true LIMIT 1;
    IF v_policy IS NOT NULL AND v_policy.is_mandatory AND p_mode = 'send' THEN
      IF NOT EXISTS (SELECT 1 FROM ia_document_templates WHERE id = p_template_id AND category = v_policy.required_template_category AND is_active = true) THEN
        RETURN jsonb_build_object('success', false, 'error', format('Template must be of category "%s" for stage %s', v_policy.required_template_category, p_stage_code));
      END IF;
    END IF;
  END IF;

  -- Only block duplicate for initial 'send' mode, not resend/reminder
  IF p_mode = 'send' AND p_stage_code != 'QUERY_CYCLE' THEN
    IF EXISTS (SELECT 1 FROM ia_communication_stages WHERE engagement_id = p_engagement_id AND stage_code = p_stage_code AND delivery_status IN ('Sent','Delivered','Acknowledged')) THEN
      RETURN jsonb_build_object('success', false, 'error', format('Stage %s already completed for this engagement', p_stage_code));
    END IF;
  END IF;

  v_delivery_status := CASE p_mode
    WHEN 'resend' THEN 'Resent'
    WHEN 'reminder' THEN 'Reminder Sent'
    ELSE 'Sent'
  END;

  INSERT INTO ia_communication_stages (engagement_id, stage_code, stage_order, template_id, template_name, recipient_name, recipient_email, sent_at, acknowledgment_required, delivery_status, notes, created_by)
  VALUES (p_engagement_id, p_stage_code, v_stage_order, p_template_id, v_template_name, p_recipient_name, p_recipient_email, now(), p_acknowledgment_required, v_delivery_status, p_notes, p_created_by)
  RETURNING id INTO v_stage_id;

  RETURN jsonb_build_object('success', true, 'stage_id', v_stage_id, 'stage_code', p_stage_code, 'mode', p_mode, 'delivery_status', v_delivery_status);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_resolve_engagement_risk(p_department_id uuid DEFAULT NULL::uuid, p_function_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_risk TEXT;
  v_source TEXT;
  v_risk_score NUMERIC;
BEGIN
  -- Priority 1: Check risk assessments on the function
  IF p_function_id IS NOT NULL THEN
    SELECT ra.risk_level, ra.overall_risk_score
    INTO v_risk, v_risk_score
    FROM ia_risk_assessments ra
    WHERE ra.function_id = p_function_id
      AND ra.is_active = true
    ORDER BY ra.assessment_date DESC NULLS LAST
    LIMIT 1;

    IF v_risk IS NOT NULL THEN
      RETURN jsonb_build_object(
        'risk_rating', v_risk,
        'risk_score', v_risk_score,
        'source', 'risk_assessment_function',
        'source_id', p_function_id
      );
    END IF;

    -- Priority 2: Function-level risk_rating column
    SELECT df.risk_rating INTO v_risk
    FROM ia_department_functions df
    WHERE df.id = p_function_id AND df.is_active = true;

    IF v_risk IS NOT NULL THEN
      RETURN jsonb_build_object(
        'risk_rating', v_risk,
        'risk_score', NULL,
        'source', 'function_risk_rating',
        'source_id', p_function_id
      );
    END IF;
  END IF;

  -- Priority 3: Department-level risk_rating
  IF p_department_id IS NOT NULL THEN
    SELECT d.risk_rating INTO v_risk
    FROM ia_departments d
    WHERE d.id = p_department_id AND d.is_active = true;

    IF v_risk IS NOT NULL THEN
      RETURN jsonb_build_object(
        'risk_rating', v_risk,
        'risk_score', NULL,
        'source', 'department_risk_rating',
        'source_id', p_department_id
      );
    END IF;
  END IF;

  -- Fallback
  RETURN jsonb_build_object(
    'risk_rating', 'Medium',
    'risk_score', NULL,
    'source', 'default',
    'source_id', NULL
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_resolve_last_audit_date(p_function_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_date date;
  v_source text;
  v_months numeric;
BEGIN
  -- Try from completed engagements first
  IF p_function_id IS NOT NULL THEN
    SELECT MAX(e.actual_end_date) INTO v_last_date
    FROM ia_audit_engagements e
    WHERE e.function_id = p_function_id
      AND e.status IN ('Completed', 'Closed')
      AND e.actual_end_date IS NOT NULL
      AND (e.is_active = true OR e.is_active IS NULL);
    IF v_last_date IS NOT NULL THEN v_source := 'engagement_actual'; END IF;
  END IF;

  IF v_last_date IS NULL AND p_department_id IS NOT NULL THEN
    SELECT MAX(e.actual_end_date) INTO v_last_date
    FROM ia_audit_engagements e
    WHERE e.department_id = p_department_id
      AND e.status IN ('Completed', 'Closed')
      AND e.actual_end_date IS NOT NULL
      AND (e.is_active = true OR e.is_active IS NULL);
    IF v_last_date IS NOT NULL THEN v_source := 'department_engagement'; END IF;
  END IF;

  IF v_last_date IS NULL AND p_function_id IS NOT NULL THEN
    SELECT df.last_audit_date INTO v_last_date
    FROM ia_department_functions df WHERE df.id = p_function_id AND df.is_active = true;
    IF v_last_date IS NOT NULL THEN v_source := 'function_stored'; END IF;
  END IF;

  IF v_last_date IS NULL THEN
    SELECT au.last_audit_date INTO v_last_date
    FROM ia_audit_universe au
    WHERE (p_function_id IS NOT NULL AND au.function_id = p_function_id)
       OR (p_department_id IS NOT NULL AND au.department_id = p_department_id)
    LIMIT 1;
    IF v_last_date IS NOT NULL THEN v_source := 'audit_universe'; END IF;
  END IF;

  -- Calculate months using age() to get a proper interval
  IF v_last_date IS NOT NULL THEN
    v_months := EXTRACT(EPOCH FROM age(CURRENT_DATE, v_last_date)) / 2592000.0;
  ELSE
    v_months := NULL;
  END IF;

  RETURN jsonb_build_object(
    'last_audit_date', v_last_date,
    'source', COALESCE(v_source, 'none'),
    'months_since', v_months
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_resolve_planning_parameter(p_parameter_key text, p_plan_id uuid DEFAULT NULL::uuid, p_function_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_scenario_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result RECORD;
  v_value jsonb;
  v_scope text;
BEGIN
  -- Precedence: scenario > plan > function > department > global
  SELECT pp.value_json, pp.scope_type, pp.version_no, pp.effective_from, pp.approved_by
  INTO v_result
  FROM ia_planning_parameters pp
  WHERE pp.parameter_key = p_parameter_key
    AND pp.is_active = true
    AND (pp.effective_from IS NULL OR pp.effective_from <= CURRENT_DATE)
    AND (pp.effective_to IS NULL OR pp.effective_to >= CURRENT_DATE)
    AND (
      (pp.scope_type = 'scenario' AND pp.scope_id = p_scenario_id AND p_scenario_id IS NOT NULL)
      OR (pp.scope_type = 'plan' AND pp.scope_id = p_plan_id AND p_plan_id IS NOT NULL)
      OR (pp.scope_type = 'function' AND pp.scope_id = p_function_id AND p_function_id IS NOT NULL)
      OR (pp.scope_type = 'department' AND pp.scope_id = p_department_id AND p_department_id IS NOT NULL)
      OR (pp.scope_type = 'global' AND pp.scope_id IS NULL)
    )
  ORDER BY
    CASE pp.scope_type
      WHEN 'scenario' THEN 1
      WHEN 'plan' THEN 2
      WHEN 'function' THEN 3
      WHEN 'department' THEN 4
      WHEN 'global' THEN 5
    END
  LIMIT 1;

  IF v_result IS NULL THEN
    RETURN jsonb_build_object('value', NULL, 'resolved_scope', 'default', 'found', false);
  END IF;

  RETURN jsonb_build_object(
    'value', v_result.value_json->'value',
    'resolved_scope', v_result.scope_type,
    'version_no', v_result.version_no,
    'effective_from', v_result.effective_from,
    'approved_by', v_result.approved_by,
    'found', true
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_seed_ssb_audit_reference_data(p_created_by text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dept_id UUID;
  v_results JSONB := '{}'::jsonb;
  v_dept_count INT := 0;
  v_fn_count INT := 0;
  v_risk_count INT := 0;
BEGIN
  -- ===== DEPARTMENTS =====
  -- 1. Office of the Director
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Office of the Director', 'Director', 'High', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Strategic Planning & Policy', 'High', 'Organizational strategy, policy development, and board governance', p_created_by),
      (v_dept_id, 'Public Relations & Communications', 'Medium', 'External communications, media relations, stakeholder engagement', p_created_by),
      (v_dept_id, 'Legal & Compliance Advisory', 'High', 'Legal counsel, regulatory compliance, legislative interpretation', p_created_by);
    v_fn_count := v_fn_count + 3;
  END IF;

  -- 2. Finance & Accounts
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Finance & Accounts', 'Finance Manager', 'Critical', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Budgeting & Financial Planning', 'High', 'Annual budget preparation, variance analysis, forecasting', p_created_by),
      (v_dept_id, 'Accounts Payable', 'Critical', 'Vendor payments, expense processing, payment authorization', p_created_by),
      (v_dept_id, 'Accounts Receivable & Collections', 'High', 'Contribution collections, arrears tracking, revenue reconciliation', p_created_by),
      (v_dept_id, 'Treasury & Cash Management', 'Critical', 'Cash flow, bank reconciliation, investment management', p_created_by),
      (v_dept_id, 'General Ledger & Reporting', 'High', 'Financial statements, month-end close, audit support', p_created_by),
      (v_dept_id, 'Payroll Processing', 'Critical', 'Staff payroll, statutory deductions, payroll reconciliation', p_created_by);
    v_fn_count := v_fn_count + 6;
  END IF;

  -- 3. Contributions & Compliance
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Contributions & Compliance', 'Compliance Manager', 'Critical', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Employer Registration & Monitoring', 'High', 'New employer onboarding, compliance monitoring, field visits', p_created_by),
      (v_dept_id, 'Contribution Processing (C3)', 'Critical', 'C3 form processing, payment reconciliation, posting', p_created_by),
      (v_dept_id, 'Arrears Management', 'Critical', 'Outstanding balance tracking, payment arrangements, escalation', p_created_by),
      (v_dept_id, 'Field Inspections', 'High', 'On-site employer audits, wage verification, compliance checks', p_created_by),
      (v_dept_id, 'Self-Employed Contributions', 'Medium', 'Voluntary contributor management, voucher generation', p_created_by);
    v_fn_count := v_fn_count + 5;
  END IF;

  -- 4. Benefits & Claims
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Benefits & Claims', 'Benefits Manager', 'Critical', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Short-Term Benefits Processing', 'Critical', 'Sickness, maternity, funeral grant claims processing', p_created_by),
      (v_dept_id, 'Long-Term Benefits (Pensions)', 'Critical', 'Age, invalidity, survivors pension processing', p_created_by),
      (v_dept_id, 'Employment Injury Benefits', 'High', 'Work injury claims, medical board referrals', p_created_by),
      (v_dept_id, 'Medical Board Administration', 'High', 'Medical assessments, disability determinations', p_created_by),
      (v_dept_id, 'Benefits Payment Processing', 'Critical', 'Payment runs, direct deposits, cheque issuance', p_created_by),
      (v_dept_id, 'Overpayment Recovery', 'High', 'Detection, recovery plans, write-off approvals', p_created_by);
    v_fn_count := v_fn_count + 6;
  END IF;

  -- 5. Information Technology
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Information Technology', 'IT Manager', 'High', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Application Development & Maintenance', 'High', 'Core system development, change management, testing', p_created_by),
      (v_dept_id, 'IT Security & Access Control', 'Critical', 'Cybersecurity, access management, incident response', p_created_by),
      (v_dept_id, 'Infrastructure & Network', 'High', 'Servers, network, backup, disaster recovery', p_created_by),
      (v_dept_id, 'Data Management & Reporting', 'Medium', 'Database administration, data quality, BI reporting', p_created_by),
      (v_dept_id, 'IT Governance & Compliance', 'High', 'IT policies, vendor management, license compliance', p_created_by);
    v_fn_count := v_fn_count + 5;
  END IF;

  -- 6. Human Resources
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Human Resources', 'HR Manager', 'Medium', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Recruitment & Onboarding', 'Medium', 'Hiring process, background checks, onboarding', p_created_by),
      (v_dept_id, 'Performance Management', 'Medium', 'Appraisals, KPIs, disciplinary procedures', p_created_by),
      (v_dept_id, 'Training & Development', 'Low', 'Staff training, professional development, certifications', p_created_by),
      (v_dept_id, 'Leave & Attendance Management', 'Low', 'Leave tracking, attendance records, overtime', p_created_by);
    v_fn_count := v_fn_count + 4;
  END IF;

  -- 7. Registration & Records
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Registration & Records', 'Records Manager', 'High', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Insured Person Registration', 'High', 'SSN issuance, identity verification, record creation', p_created_by),
      (v_dept_id, 'Records Management & Archives', 'Medium', 'Document storage, retrieval, retention policies', p_created_by),
      (v_dept_id, 'Data Quality & Deduplication', 'High', 'Duplicate detection, data cleansing, merge operations', p_created_by);
    v_fn_count := v_fn_count + 3;
  END IF;

  -- 8. Procurement & Administration
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Procurement & Administration', 'Admin Manager', 'High', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Procurement & Purchasing', 'Critical', 'Vendor selection, purchase orders, contract management', p_created_by),
      (v_dept_id, 'Asset Management', 'High', 'Fixed asset register, depreciation, disposal', p_created_by),
      (v_dept_id, 'Facilities Management', 'Medium', 'Building maintenance, fleet management, utilities', p_created_by),
      (v_dept_id, 'Inventory & Stores', 'Medium', 'Stock control, issuance, physical counts', p_created_by);
    v_fn_count := v_fn_count + 4;
  END IF;

  -- 9. Internal Audit
  INSERT INTO ia_departments (name, head, risk_rating, created_by) 
  VALUES ('Internal Audit', 'Chief Audit Executive', 'Medium', p_created_by)
  ON CONFLICT DO NOTHING RETURNING id INTO v_dept_id;
  IF v_dept_id IS NOT NULL THEN
    v_dept_count := v_dept_count + 1;
    INSERT INTO ia_department_functions (department_id, function_name, risk_rating, description, created_by) VALUES
      (v_dept_id, 'Audit Planning & Execution', 'Medium', 'Annual plan, engagement management, fieldwork', p_created_by),
      (v_dept_id, 'Quality Assurance & Improvement', 'Medium', 'QA reviews, methodology updates, standards compliance', p_created_by);
    v_fn_count := v_fn_count + 2;
  END IF;

  v_results := jsonb_build_object(
    'success', true,
    'departments_created', v_dept_count,
    'functions_created', v_fn_count,
    'message', format('Seeded %s departments and %s functions', v_dept_count, v_fn_count)
  );

  RETURN v_results;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_start_annual_plan_approval_workflow(p_plan_id uuid, p_submitted_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN ia_start_plan_approval_workflow(p_plan_id, p_submitted_by, false);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_start_annual_plan_revision_workflow(p_plan_id uuid, p_submitted_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN ia_start_plan_approval_workflow(p_plan_id, p_submitted_by, true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_start_plan_approval_workflow(p_plan_id uuid, p_submitted_by text DEFAULT 'SYSTEM'::text, p_is_revision boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan record;
  v_event_type text;
  v_binding record;
  v_workflow_def record;
  v_first_step record;
  v_instance_id uuid;
  v_task_id uuid;
  v_version_number integer;
  v_version_id uuid;
  v_conflict_result jsonb;
  v_eng record;
  v_user_id uuid;
BEGIN
  BEGIN
    v_user_id := p_submitted_by::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    SELECT id INTO v_user_id FROM profiles WHERE user_code = p_submitted_by LIMIT 1;
  END;
  IF v_user_id IS NULL THEN
    v_user_id := auth.uid();
  END IF;

  SELECT * INTO v_plan FROM ia_annual_plans WHERE id = p_plan_id;
  IF v_plan IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan not found');
  END IF;

  v_event_type := CASE WHEN p_is_revision THEN 'plan_revision' ELSE 'plan_approval' END;

  IF NOT p_is_revision AND v_plan.status NOT IN ('Draft', 'Rejected', 'Changes Requested', 'Amendment Pending') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan must be in Draft, Rejected, Changes Requested, or Amendment Pending status to submit');
  END IF;
  IF p_is_revision AND v_plan.status NOT IN ('Approved', 'In Progress') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan must be Approved or In Progress to submit a revision');
  END IF;

  v_conflict_result := ia_validate_team_availability(p_plan_id := p_plan_id);
  IF (v_conflict_result->>'has_blocking')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', 'Blocking team availability conflicts detected', 'conflicts', v_conflict_result->'conflicts');
  END IF;

  SELECT * INTO v_binding FROM ia_plan_workflow_bindings WHERE event_type = v_event_type AND is_active = true;
  IF v_binding IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active workflow binding found for ' || v_event_type);
  END IF;

  SELECT * INTO v_workflow_def FROM workflow_definitions WHERE id = v_binding.workflow_definition_id AND is_active = true;
  IF v_workflow_def IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Workflow definition is inactive or missing');
  END IF;

  SELECT * INTO v_first_step FROM workflow_steps WHERE workflow_id = v_workflow_def.id ORDER BY step_number LIMIT 1;
  IF v_first_step IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Workflow has no steps configured');
  END IF;

  v_version_number := COALESCE(v_plan.current_version_number, 0) + 1;

  INSERT INTO ia_plan_versions (plan_id, version_number, snapshot_data, status_at_snapshot, change_summary, created_by)
  VALUES (
    p_plan_id, v_version_number,
    to_jsonb(v_plan),
    v_plan.status,
    CASE WHEN p_is_revision THEN 'Revision submitted' ELSE 'Initial submission' END,
    p_submitted_by
  )
  RETURNING id INTO v_version_id;

  FOR v_eng IN 
    SELECT * FROM ia_audit_engagements 
    WHERE annual_plan_id = p_plan_id AND (is_active = true OR is_active IS NULL)
  LOOP
    INSERT INTO ia_plan_version_engagements (plan_version_id, engagement_id, engagement_snapshot, change_type)
    VALUES (
      v_version_id,
      v_eng.id,
      to_jsonb(v_eng),
      CASE WHEN v_version_number = 1 THEN 'added' ELSE 'inherited' END
    );
  END LOOP;

  INSERT INTO workflow_instances (
    workflow_id, workflow_name, source_module, source_record_id, source_record_name,
    current_step_id, status, started_by, started_by_name, metadata
  )
  VALUES (
    v_workflow_def.id, v_workflow_def.name,
    'ia_annual_plan', p_plan_id::text, v_plan.title,
    v_first_step.id, 'InProgress', v_user_id, p_submitted_by,
    jsonb_build_object('version_number', v_version_number, 'is_revision', p_is_revision, 'plan_version_id', v_version_id)
  )
  RETURNING id INTO v_instance_id;

  INSERT INTO workflow_tasks (instance_id, step_id, step_name, status)
  VALUES (v_instance_id, v_first_step.id, v_first_step.step_name, 'Pending')
  RETURNING id INTO v_task_id;

  INSERT INTO workflow_logs (instance_id, step_id, step_name, action, user_id, user_name, comments)
  VALUES (v_instance_id, v_first_step.id, v_first_step.step_name, 'workflow_started', v_user_id, p_submitted_by,
    'Plan ' || CASE WHEN p_is_revision THEN 'revision' ELSE 'approval' END || ' workflow started (v' || v_version_number || ')');

  UPDATE ia_annual_plans
  SET status = CASE WHEN p_is_revision THEN 'Pending Revision Approval' ELSE 'Submitted' END,
      current_version_number = v_version_number,
      workflow_instance_id = v_instance_id,
      updated_at = now(),
      updated_by = p_submitted_by
  WHERE id = p_plan_id;

  RETURN jsonb_build_object(
    'success', true,
    'workflow_instance_id', v_instance_id,
    'task_id', v_task_id,
    'version_number', v_version_number,
    'plan_version_id', v_version_id,
    'new_status', CASE WHEN p_is_revision THEN 'Pending Revision Approval' ELSE 'Submitted' END,
    'engagements_snapshot_count', (SELECT count(*) FROM ia_plan_version_engagements WHERE plan_version_id = v_version_id)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_transition_execution_status(p_engagement_id uuid, p_new_status text, p_performed_by text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eng record;
  v_valid_statuses text[] := ARRAY[
    'Planned', 'Ready for Launch', 'Notification Sent', 'Opening Meeting Scheduled',
    'Fieldwork In Progress', 'Findings Drafting', 'Management Response Pending',
    'Final Report Issued', 'Follow-up Monitoring', 'Closed', 'Deferred', 'Cancelled'
  ];
BEGIN
  SELECT * INTO v_eng FROM ia_audit_engagements WHERE id = p_engagement_id AND is_active = true;
  IF v_eng IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Engagement not found');
  END IF;

  IF NOT (p_new_status = ANY(v_valid_statuses)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid execution status: ' || p_new_status);
  END IF;

  -- Update status
  UPDATE ia_audit_engagements SET
    execution_status = p_new_status,
    execution_notes = COALESCE(p_notes, execution_notes),
    updated_at = now(),
    updated_by = COALESCE(p_performed_by, 'SYSTEM')
  WHERE id = p_engagement_id;

  -- Log transition
  INSERT INTO ia_engagement_execution_log (engagement_id, event_type, event_description, old_status, new_status, performed_by, metadata)
  VALUES (
    p_engagement_id,
    'STATUS_TRANSITION',
    'Execution status changed from ' || COALESCE(v_eng.execution_status, 'Planned') || ' to ' || p_new_status,
    COALESCE(v_eng.execution_status, 'Planned'),
    p_new_status,
    COALESCE(p_performed_by, 'SYSTEM'),
    CASE WHEN p_notes IS NOT NULL THEN jsonb_build_object('notes', p_notes) ELSE NULL END
  );

  RETURN jsonb_build_object('success', true, 'message', 'Status transitioned to ' || p_new_status);
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_validate_audit_team_user_mapping(p_lead_auditor_id uuid DEFAULT NULL::uuid, p_supportive_auditor_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_errors JSONB := '[]'::jsonb;
  v_auditor RECORD;
  v_id UUID;
BEGIN
  -- Validate lead auditor
  IF p_lead_auditor_id IS NOT NULL THEN
    SELECT id, name, profile_id, user_id INTO v_auditor
    FROM ia_auditors WHERE id = p_lead_auditor_id;

    IF v_auditor.id IS NULL THEN
      v_errors := v_errors || jsonb_build_object('auditor_id', p_lead_auditor_id, 'error', 'Lead auditor not found');
    ELSIF v_auditor.profile_id IS NULL AND v_auditor.user_id IS NULL THEN
      v_errors := v_errors || jsonb_build_object('auditor_id', p_lead_auditor_id, 'name', v_auditor.name, 'error', 'Lead auditor is not linked to a system user');
    END IF;
  END IF;

  -- Validate supportive auditors
  IF p_supportive_auditor_ids IS NOT NULL THEN
    FOREACH v_id IN ARRAY p_supportive_auditor_ids LOOP
      SELECT id, name, profile_id, user_id INTO v_auditor
      FROM ia_auditors WHERE id = v_id;

      IF v_auditor.id IS NULL THEN
        v_errors := v_errors || jsonb_build_object('auditor_id', v_id, 'error', 'Auditor not found');
      ELSIF v_auditor.profile_id IS NULL AND v_auditor.user_id IS NULL THEN
        v_errors := v_errors || jsonb_build_object('auditor_id', v_id, 'name', v_auditor.name, 'error', 'Auditor is not linked to a system user');
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'valid', jsonb_array_length(v_errors) = 0,
    'errors', v_errors
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_validate_team_availability(p_plan_id uuid DEFAULT NULL::uuid, p_engagement_id uuid DEFAULT NULL::uuid, p_auditor_ids uuid[] DEFAULT NULL::uuid[], p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conflicts jsonb := '[]'::jsonb;
  v_auditor uuid;
  v_start date;
  v_end date;
  v_team uuid[];
  rec record;
BEGIN
  -- Resolve dates and team from engagement or plan if not explicitly provided
  IF p_engagement_id IS NOT NULL THEN
    SELECT planned_start_date, planned_end_date,
           COALESCE(
             ARRAY(SELECT unnest(COALESCE(team_member_ids, '[]'::jsonb)::text[])::uuid) || ARRAY[lead_auditor_id],
             ARRAY[lead_auditor_id]
           )
    INTO v_start, v_end, v_team
    FROM ia_audit_engagements WHERE id = p_engagement_id;
  ELSIF p_plan_id IS NOT NULL THEN
    SELECT MIN(e.planned_start_date), MAX(e.planned_end_date)
    INTO v_start, v_end
    FROM ia_audit_engagements e WHERE e.annual_plan_id = p_plan_id;

    SELECT ARRAY(
      SELECT DISTINCT x::uuid FROM (
        SELECT jsonb_array_elements_text(COALESCE(e.team_member_ids, '[]'::jsonb)) AS x
        FROM ia_audit_engagements e WHERE e.annual_plan_id = p_plan_id
        UNION
        SELECT e.lead_auditor_id::text FROM ia_audit_engagements e
        WHERE e.annual_plan_id = p_plan_id AND e.lead_auditor_id IS NOT NULL
      ) sub WHERE x IS NOT NULL
    ) INTO v_team;
  END IF;

  -- Override with explicit params
  v_start := COALESCE(p_date_from, v_start);
  v_end := COALESCE(p_date_to, v_end);
  v_team := COALESCE(p_auditor_ids, v_team);

  IF v_start IS NULL OR v_end IS NULL OR v_team IS NULL OR array_length(v_team, 1) IS NULL THEN
    RETURN jsonb_build_object('valid', true, 'conflicts', '[]'::jsonb, 'total_conflicts', 0, 'has_blocking', false, 'message', 'No dates or team to check');
  END IF;

  -- Check holidays
  FOR rec IN
    SELECT h.name, h.date AS conflict_date
    FROM ia_holidays h
    WHERE h.is_active = true AND h.date BETWEEN v_start AND v_end
  LOOP
    v_conflicts := v_conflicts || jsonb_build_object(
      'type', 'holiday', 'date', rec.conflict_date, 'reference', rec.name,
      'severity', 'warning', 'affects_all', true
    );
  END LOOP;

  -- Check leave requests and overlapping engagements per auditor
  FOREACH v_auditor IN ARRAY v_team LOOP
    -- Leave conflicts (fixed: use a.name instead of a.full_name)
    FOR rec IN
      SELECT lr.id, lr.start_date, lr.end_date, lr.leave_type, a.name AS auditor_name
      FROM ia_leave_requests lr
      JOIN ia_auditors a ON a.id = lr.auditor_id
      WHERE lr.auditor_id = v_auditor
        AND lr.status IN ('Approved', 'Pending')
        AND lr.start_date <= v_end AND lr.end_date >= v_start
    LOOP
      v_conflicts := v_conflicts || jsonb_build_object(
        'type', 'leave', 'auditor_id', v_auditor, 'auditor_name', rec.auditor_name,
        'date_start', rec.start_date, 'date_end', rec.end_date,
        'leave_type', rec.leave_type, 'reference', rec.id::text,
        'severity', CASE WHEN rec.leave_type IN ('Annual','Sick') THEN 'blocking' ELSE 'warning' END
      );
    END LOOP;

    -- Engagement overlap
    FOR rec IN
      SELECT e.id, e.engagement_name, e.planned_start_date, e.planned_end_date
      FROM ia_audit_engagements e
      WHERE (e.lead_auditor_id = v_auditor
             OR v_auditor::text IN (SELECT jsonb_array_elements_text(COALESCE(e.team_member_ids, '[]'::jsonb))))
        AND e.status NOT IN ('Completed', 'Cancelled')
        AND e.planned_start_date <= v_end AND e.planned_end_date >= v_start
        AND e.id IS DISTINCT FROM p_engagement_id
    LOOP
      v_conflicts := v_conflicts || jsonb_build_object(
        'type', 'engagement_overlap', 'auditor_id', v_auditor,
        'date_start', rec.planned_start_date, 'date_end', rec.planned_end_date,
        'reference', rec.engagement_name, 'severity', 'warning'
      );
    END LOOP;
  END LOOP;

  -- Store conflicts if context provided
  IF p_plan_id IS NOT NULL OR p_engagement_id IS NOT NULL THEN
    DELETE FROM ia_availability_conflicts
    WHERE (plan_id IS NOT DISTINCT FROM p_plan_id AND p_plan_id IS NOT NULL)
       OR (engagement_id IS NOT DISTINCT FROM p_engagement_id AND p_engagement_id IS NOT NULL);

    INSERT INTO ia_availability_conflicts (plan_id, engagement_id, auditor_id, conflict_type,
      conflict_date_start, conflict_date_end, conflict_reference, severity)
    SELECT p_plan_id, p_engagement_id,
      (c->>'auditor_id')::uuid, c->>'type',
      COALESCE((c->>'date_start')::date, (c->>'date')::date),
      COALESCE((c->>'date_end')::date, (c->>'date')::date),
      c->>'reference', c->>'severity'
    FROM jsonb_array_elements(v_conflicts) c
    WHERE c->>'auditor_id' IS NOT NULL;
  END IF;

  RETURN jsonb_build_object(
    'valid', jsonb_array_length(v_conflicts) = 0,
    'conflicts', v_conflicts,
    'total_conflicts', jsonb_array_length(v_conflicts),
    'has_blocking', EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_conflicts) c WHERE c->>'severity' = 'blocking'
    ),
    'checked_at', now()::text,
    'plan_id', p_plan_id,
    'engagement_id', p_engagement_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ia_validate_template_policy(p_stage_code text, p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy record;
  v_template record;
BEGIN
  SELECT * INTO v_policy FROM ia_template_policy_matrix
  WHERE stage_code = p_stage_code AND is_active = true
  LIMIT 1;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', true, 'warning', 'No template policy defined for this stage');
  END IF;
  
  SELECT id, name, category, is_active, version_number
  INTO v_template FROM ia_document_templates WHERE id = p_template_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Template not found');
  END IF;
  
  IF NOT v_template.is_active THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Template is not active. Only active templates may be used.');
  END IF;
  
  IF v_policy.required_template_category IS NOT NULL AND v_template.category != v_policy.required_template_category THEN
    RETURN jsonb_build_object('valid', false, 'error', 
      format('Template category "%s" does not match required category "%s" for stage %s', 
             v_template.category, v_policy.required_template_category, p_stage_code));
  END IF;
  
  IF v_policy.min_version IS NOT NULL AND COALESCE(v_template.version_number, 1) < v_policy.min_version THEN
    RETURN jsonb_build_object('valid', false, 'error',
      format('Template version %s is below minimum required version %s', v_template.version_number, v_policy.min_version));
  END IF;
  
  RETURN jsonb_build_object('valid', true, 'template_name', v_template.name, 'template_version', v_template.version_number);
END;
$function$;
CREATE OR REPLACE FUNCTION public.initiate_ip_registration_workflow(p_unique_uuid uuid, p_ssn text, p_record_name text, p_user_id uuid DEFAULT NULL::uuid, p_user_code text DEFAULT 'SYSTEM'::text, p_source_context text DEFAULT 'direct_submission'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module_id UUID;
  v_trigger RECORD;
  v_workflow RECORD;
  v_first_step RECORD;
  v_instance_id UUID;
  v_task_id UUID;
  v_due_at TIMESTAMPTZ;
  v_task_due_at TIMESTAMPTZ;
  v_profile_name TEXT;
  v_assigned_role TEXT;
  v_existing_instance_id UUID;
BEGIN
  SELECT id INTO v_existing_instance_id
  FROM workflow_instances
  WHERE source_record_id = p_unique_uuid::TEXT
    AND source_module = 'insured_person_registration'
  LIMIT 1;

  IF v_existing_instance_id IS NOT NULL THEN
    INSERT INTO system_audit_trail (
      entity_type, entity_id, action, after_value, user_id, user_name, module
    ) VALUES (
      'workflow_instance', v_existing_instance_id::TEXT, 'workflow_initiation_skipped_duplicate',
      jsonb_build_object('reason', 'instance_already_exists', 'source_record_id', p_unique_uuid),
      p_user_id, p_user_code, p_source_context
    );
    RETURN v_existing_instance_id;
  END IF;

  SELECT id INTO v_module_id FROM app_modules WHERE name = 'insured_person_registration' LIMIT 1;
  IF v_module_id IS NULL THEN
    v_module_id := '305eaff7-8446-47e0-a7ac-186da08b91ee'::UUID;
  END IF;

  SELECT wt.id AS trigger_id, wt.workflow_id INTO v_trigger
  FROM workflow_triggers wt
  WHERE wt.module_id = v_module_id AND wt.action_name = 'submit' AND wt.is_active = TRUE
  LIMIT 1;

  IF v_trigger IS NULL THEN
    INSERT INTO system_audit_trail (
      entity_type, entity_id, action, after_value, user_id, user_name, module
    ) VALUES (
      'ip_registration', p_unique_uuid::TEXT, 'no_workflow_trigger_found',
      jsonb_build_object('module_id', v_module_id, 'action', 'submit'),
      p_user_id, p_user_code, p_source_context
    );
    RETURN NULL;
  END IF;

  SELECT id, name, default_sla_hours INTO v_workflow FROM workflow_definitions WHERE id = v_trigger.workflow_id;
  IF v_workflow IS NULL THEN RETURN NULL; END IF;

  SELECT id, step_name, step_number, sla_hours, approver_type, approver_role_ids INTO v_first_step
  FROM workflow_steps WHERE workflow_id = v_workflow.id ORDER BY step_number ASC LIMIT 1;
  IF v_first_step IS NULL THEN RETURN NULL; END IF;

  SELECT full_name INTO v_profile_name FROM profiles WHERE id = p_user_id;
  v_profile_name := COALESCE(v_profile_name, p_user_code, 'System');

  v_due_at := NOW() + MAKE_INTERVAL(hours => COALESCE(v_workflow.default_sla_hours, 24));
  v_task_due_at := NOW() + MAKE_INTERVAL(hours => COALESCE(v_first_step.sla_hours, 24));

  IF v_first_step.approver_type = 'role' AND v_first_step.approver_role_ids IS NOT NULL AND array_length(v_first_step.approver_role_ids, 1) = 1 THEN
    SELECT role_name INTO v_assigned_role FROM roles WHERE id = v_first_step.approver_role_ids[1];
  END IF;

  INSERT INTO workflow_instances (
    workflow_id, workflow_name, source_module, source_record_id, source_record_name,
    current_step_id, status, started_by, started_by_name, due_at, metadata
  ) VALUES (
    v_workflow.id, v_workflow.name, 'insured_person_registration', p_unique_uuid::TEXT, p_record_name,
    v_first_step.id, 'InProgress', p_user_id, v_profile_name, v_due_at,
    jsonb_build_object('ssn', p_ssn, 'applicant_name', p_record_name, 'source_context', p_source_context)
  ) RETURNING id INTO v_instance_id;

  INSERT INTO workflow_tasks (
    instance_id, step_id, step_name, assigned_role, status, due_at
  ) VALUES (
    v_instance_id, v_first_step.id, v_first_step.step_name, v_assigned_role, 'Pending', v_task_due_at
  ) RETURNING id INTO v_task_id;

  INSERT INTO workflow_logs (
    instance_id, step_id, step_name, action, user_id, user_name, comments
  ) VALUES (
    v_instance_id, v_first_step.id, v_first_step.step_name, 'workflow_started',
    p_user_id, v_profile_name,
    'Workflow started for IP Registration: ' || p_record_name || ' (source: ' || p_source_context || ')'
  );

  INSERT INTO system_audit_trail (
    entity_type, entity_id, action, after_value, user_id, user_name, module
  ) VALUES (
    'workflow_instance', v_instance_id::TEXT, 'workflow_initiated',
    jsonb_build_object(
      'workflow_name', v_workflow.name, 'source_record_id', p_unique_uuid,
      'ssn', p_ssn, 'first_step', v_first_step.step_name, 'task_id', v_task_id
    ),
    p_user_id, p_user_code, p_source_context
  );

  RETURN v_instance_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.insert_ip_employer_if_not_consecutive_duplicate(p_ssn character varying, p_employer_id character varying, p_occupation character varying, p_source character varying DEFAULT 'MANUAL'::character varying, p_posting_status character varying DEFAULT 'VAC'::character varying, p_entered_by character varying DEFAULT 'SYSTEM'::character varying, p_term_start_date date DEFAULT NULL::date, p_term_end_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_latest_employer RECORD;
  v_new_id UUID;
BEGIN
  -- Get the LATEST (most recent) employer record for this SSN
  SELECT * INTO v_latest_employer
  FROM public.ip_employer
  WHERE ssn = p_ssn
  ORDER BY date_entered DESC, created_at DESC
  LIMIT 1;
  
  -- Check if this would be a consecutive duplicate
  IF v_latest_employer.id IS NOT NULL AND
     v_latest_employer.employer_id = p_employer_id AND
     COALESCE(v_latest_employer.occupation, '') = COALESCE(p_occupation, '') THEN
    -- Consecutive duplicate - do not insert
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'consecutive_duplicate',
      'message', 'Record not inserted: same employer and occupation as the most recent record',
      'existing_record_id', v_latest_employer.id
    );
  END IF;
  
  -- Not a consecutive duplicate - insert the new record
  INSERT INTO public.ip_employer (
    ssn,
    employer_id,
    occupation,
    source,
    posting_status,
    entered_by,
    date_entered,
    term_start_date,
    term_end_date
  ) VALUES (
    p_ssn,
    p_employer_id,
    p_occupation,
    p_source,
    p_posting_status,
    p_entered_by,
    NOW() AT TIME ZONE 'UTC',
    p_term_start_date,
    p_term_end_date
  )
  RETURNING id INTO v_new_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'reason', 'inserted',
    'message', 'New employment record created',
    'new_record_id', v_new_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.inspect_comm_hub_dry_run_preflight(p_preview_snapshot_id uuid, p_preview_approval_id uuid, p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_snap public.communication_preview_snapshot%ROWTYPE;
  v_appr public.communication_preview_approval%ROWTYPE;
  v_blockers jsonb := '[]'::jsonb;
  v_evidence jsonb := '{}'::jsonb;
  v_correlation uuid := null;
  v_ready boolean;
  v_status text;
  v_state text;
  v_recipient_count int := null;
  v_to_len int := 0;
  v_cc_len int := 0;
  v_bcc_len int := 0;
  v_placeholder_count int := null;
  v_malformed_count int := null;
  v_unresolved_count int := null;
  v_required_unresolved_count int := null;
  v_ge jsonb;
  v_uid uuid := auth.uid();
  v_is_service boolean := (auth.role() = 'service_role');
  v_is_admin boolean := false;
  v_recipients_valid boolean := true;
  v_module_norm text := btrim(coalesce(p_module_code,''));
  v_event_norm  text := btrim(coalesce(p_event_code,''));
  v_channel_norm text := btrim(coalesce(nullif(p_channel,''),'email'));
  v_r jsonb;
  v_addr text;
  v_expected_canonical text;
  v_canonical_valid boolean := false;
  v_recomputed_hash text;
  v_hash_match boolean := false;
  v_recip_norm jsonb := null;
  v_recip_recompute_ok boolean := false;
  v_containers_valid boolean := true;
  v_all_entries_valid boolean := true;
  v_duplicate_ok boolean := true;
  v_evidence_complete boolean := false;
  v_mb jsonb;
  v_seen text[] := ARRAY[]::text[];
  v_role text;
  v_arr jsonb;
  v_i int;
  v_entry jsonb;
BEGIN
  -- ============= AUTH =============
  IF NOT v_is_service THEN
    IF v_uid IS NULL THEN
      RETURN jsonb_build_object(
        'contract_version','comm-hub-dry-run-contract/v1',
        'status','BLOCKED','state','BLOCKED',
        'passed', false,'stage_succeeded', false,'terminal', true,
        'idempotent_replay', false,'failure_stage','PREFLIGHT',
        'message','Authentication required to inspect preflight.',
        'validated_at', now(),'execution_deadline_at', null,
        'correlation_id', null,'preview_snapshot_id', null,'preview_approval_id', null,
        'dry_run_execution_id', null,'execution_no', null,
        'request_id', null,'request_number', null,'message_id', null,'trace_id', null,
        'dry_run_certification_id', null,'certification_expires_at', null,
        'recipient_count', null,
        'blockers', jsonb_build_array(jsonb_build_object('code','PREFLIGHT_AUTHENTICATION_REQUIRED')),
        'warnings','[]'::jsonb,'transition_log_ids','[]'::jsonb,
        'mutation_started', false,'execution_created', false,'request_created', false,
        'message_created', false,'created_this_call', false,'cleanup_proven', true,
        'provider_call_attempted', false,'simulator_call_attempted', false,'ambiguous_outcome', false,
        'retry_safe', true,'retry_reason','PRE_MUTATION_AUTH_FAILURE',
        'evidence', jsonb_build_object('authenticated', false,'authorized', false),
        'evaluator_version','comm-hub-dry-run-preflight/v1');
    END IF;
    BEGIN v_is_admin := public.is_comm_hub_operator_admin(v_uid);
    EXCEPTION WHEN OTHERS THEN v_is_admin := false; END;
    IF NOT v_is_admin THEN
      RETURN jsonb_build_object(
        'contract_version','comm-hub-dry-run-contract/v1',
        'status','BLOCKED','state','BLOCKED',
        'passed', false,'stage_succeeded', false,'terminal', true,
        'idempotent_replay', false,'failure_stage','PREFLIGHT',
        'message','Communication Hub operator role required.',
        'validated_at', now(),'execution_deadline_at', null,
        'correlation_id', null,'preview_snapshot_id', null,'preview_approval_id', null,
        'dry_run_execution_id', null,'execution_no', null,
        'request_id', null,'request_number', null,'message_id', null,'trace_id', null,
        'dry_run_certification_id', null,'certification_expires_at', null,
        'recipient_count', null,
        'blockers', jsonb_build_array(jsonb_build_object('code','PREFLIGHT_PERMISSION_REQUIRED')),
        'warnings','[]'::jsonb,'transition_log_ids','[]'::jsonb,
        'mutation_started', false,'execution_created', false,'request_created', false,
        'message_created', false,'created_this_call', false,'cleanup_proven', true,
        'provider_call_attempted', false,'simulator_call_attempted', false,'ambiguous_outcome', false,
        'retry_safe', true,'retry_reason','PRE_MUTATION_AUTH_FAILURE',
        'evidence', jsonb_build_object('authenticated', true,'authorized', false),
        'evaluator_version','comm-hub-dry-run-preflight/v1');
    END IF;
  END IF;

  -- ============= PREVIEW =============
  IF p_preview_snapshot_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_NOT_FOUND','message','preview_snapshot_id required');
  ELSE
    SELECT * INTO v_snap FROM public.communication_preview_snapshot WHERE id = p_preview_snapshot_id;
    IF NOT FOUND THEN
      v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_NOT_FOUND');
    ELSE
      IF v_snap.status IS DISTINCT FROM 'PREPARED' THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SNAPSHOT_NOT_PREPARED','detail', jsonb_build_object('status', v_snap.status));
      END IF;
      IF v_snap.expires_at IS NOT NULL AND v_snap.expires_at <= now() THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_EXPIRED_BEFORE_BEGIN');
      END IF;
      IF v_snap.module_code IS DISTINCT FROM v_module_norm
         OR v_snap.event_code IS DISTINCT FROM v_event_norm
         OR v_snap.channel   IS DISTINCT FROM v_channel_norm THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_SCOPE_MISMATCH',
          'detail', jsonb_build_object('module_code',v_snap.module_code,'event_code',v_snap.event_code,'channel',v_snap.channel));
      END IF;
      IF v_snap.correlation_id IS NULL THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_CORRELATION_MISSING');
      END IF;
      IF v_snap.content_hash IS NULL OR v_snap.content_hash = '' THEN
        v_blockers := v_blockers || jsonb_build_object('code','CONTENT_HASH_MISSING');
      END IF;
      IF v_snap.template_version_id IS NULL THEN
        v_blockers := v_blockers || jsonb_build_object('code','TEMPLATE_VERSION_MISSING');
      END IF;
      IF v_snap.certified_dependency_hash IS NULL OR v_snap.certified_dependency_hash = '' THEN
        v_blockers := v_blockers || jsonb_build_object('code','CONFIGURATION_HASH_MISSING');
      END IF;

      -- (A) Recipient hash recomputation must succeed as an object with a
      -- non-empty recipient_set_hash.
      BEGIN
        v_recip_norm := public.comm_hub_normalize_recipient_set(
          coalesce(v_snap.to_recipients,'[]'::jsonb),
          coalesce(v_snap.cc_recipients,'[]'::jsonb),
          coalesce(v_snap.bcc_recipients,'[]'::jsonb));
        IF v_recip_norm IS NULL OR jsonb_typeof(v_recip_norm) <> 'object' THEN
          v_recip_recompute_ok := false;
        ELSIF coalesce(v_recip_norm->>'recipient_set_hash','') = '' THEN
          v_recip_recompute_ok := false;
        ELSE
          v_recip_recompute_ok := true;
          v_recomputed_hash := v_recip_norm->>'recipient_set_hash';
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_recip_recompute_ok := false;
        v_recip_norm := null;
        v_recomputed_hash := null;
      END;

      IF NOT v_recip_recompute_ok THEN
        v_blockers := v_blockers || jsonb_build_object(
          'code','PREVIEW_RECIPIENT_HASH_RECOMPUTE_FAILED',
          'message','Recipient normalization did not return a usable hash.');
        v_recipients_valid := false;
      ELSIF COALESCE(v_snap.recipient_set_hash,'') <> ''
            AND v_recomputed_hash <> v_snap.recipient_set_hash THEN
        v_blockers := v_blockers || jsonb_build_object(
          'code','PREVIEW_RECIPIENT_HASH_RECOMPUTE_MISMATCH',
          'detail', jsonb_build_object(
            'stored_short', left(v_snap.recipient_set_hash,12),
            'recomputed_short', left(v_recomputed_hash,12)));
      END IF;
      v_hash_match := v_recip_recompute_ok
        AND v_recomputed_hash = v_snap.recipient_set_hash;
    END IF;
  END IF;

  -- ============= APPROVAL =============
  IF p_preview_approval_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_NOT_FOUND','message','preview_approval_id required');
  ELSE
    SELECT * INTO v_appr FROM public.communication_preview_approval WHERE id = p_preview_approval_id;
    IF NOT FOUND THEN
      v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_NOT_FOUND');
    ELSE
      IF v_snap.id IS NOT NULL AND v_appr.snapshot_id IS DISTINCT FROM v_snap.id THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_SNAPSHOT_MISMATCH');
      END IF;
      IF v_appr.status IS DISTINCT FROM 'ACTIVE' THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_APPROVAL_NOT_ACTIVE','detail', jsonb_build_object('status', v_appr.status));
        IF v_appr.status = 'REVOKED' THEN
          v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_REVOKED_BEFORE_BEGIN');
        ELSIF v_appr.status = 'RESERVED' THEN
          v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_RESERVED_BEFORE_BEGIN');
        ELSIF v_appr.status = 'CONSUMED' THEN
          v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_CONSUMED_BEFORE_BEGIN');
        END IF;
      END IF;
      IF v_appr.expires_at IS NOT NULL AND v_appr.expires_at <= now() THEN
        v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_EXPIRED_BEFORE_BEGIN');
      END IF;
      IF v_appr.approved_by IS NULL OR v_appr.approved_at IS NULL THEN
        v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_ACTOR_MISSING');
      END IF;
      IF v_appr.correlation_id_at_approval IS NULL THEN
        v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_CORRELATION_MISSING');
      END IF;

      -- (B) Approval evidence completeness — every canonical input required.
      v_evidence_complete :=
        v_appr.snapshot_id_at_approval IS NOT NULL
        AND v_appr.correlation_id_at_approval IS NOT NULL
        AND v_appr.content_hash_at_approval IS NOT NULL AND v_appr.content_hash_at_approval <> ''
        AND v_appr.recipient_set_hash_at_approval IS NOT NULL AND v_appr.recipient_set_hash_at_approval <> ''
        AND v_appr.template_version_id_at_approval IS NOT NULL
        AND v_appr.configuration_hash_at_approval IS NOT NULL AND v_appr.configuration_hash_at_approval <> ''
        AND v_appr.scanner_version_at_approval IS NOT NULL AND v_appr.scanner_version_at_approval <> ''
        AND v_appr.placeholder_evidence_hash_at_approval IS NOT NULL AND v_appr.placeholder_evidence_hash_at_approval <> ''
        AND v_appr.approved_by IS NOT NULL
        AND v_appr.approved_at IS NOT NULL
        AND v_appr.expires_at IS NOT NULL
        AND v_appr.canonical_approval_evidence_hash IS NOT NULL AND v_appr.canonical_approval_evidence_hash <> ''
        AND v_appr.evidence_version = 'comm-hub-approval-evidence/v1';

      IF NOT v_evidence_complete THEN
        v_blockers := v_blockers || jsonb_build_object(
          'code','APPROVAL_EVIDENCE_MISSING_OR_LEGACY',
          'evidence_version', v_appr.evidence_version,
          'detail', jsonb_build_object(
            'snapshot_id_present', v_appr.snapshot_id_at_approval IS NOT NULL,
            'correlation_id_present', v_appr.correlation_id_at_approval IS NOT NULL,
            'content_hash_present', coalesce(v_appr.content_hash_at_approval,'') <> '',
            'recipient_set_hash_present', coalesce(v_appr.recipient_set_hash_at_approval,'') <> '',
            'template_version_id_present', v_appr.template_version_id_at_approval IS NOT NULL,
            'configuration_hash_present', coalesce(v_appr.configuration_hash_at_approval,'') <> '',
            'scanner_version_present', coalesce(v_appr.scanner_version_at_approval,'') <> '',
            'placeholder_evidence_hash_present', coalesce(v_appr.placeholder_evidence_hash_at_approval,'') <> '',
            'approved_by_present', v_appr.approved_by IS NOT NULL,
            'approved_at_present', v_appr.approved_at IS NOT NULL,
            'expires_at_present', v_appr.expires_at IS NOT NULL,
            'canonical_hash_present', coalesce(v_appr.canonical_approval_evidence_hash,'') <> '',
            'evidence_version', v_appr.evidence_version));
      ELSE
        BEGIN
          v_expected_canonical := public._comm_hub_compute_canonical_approval_evidence_v1(
            v_appr.snapshot_id_at_approval,
            v_appr.correlation_id_at_approval,
            v_appr.content_hash_at_approval,
            v_appr.recipient_set_hash_at_approval,
            v_appr.template_version_id_at_approval,
            v_appr.configuration_hash_at_approval,
            v_appr.scanner_version_at_approval,
            v_appr.placeholder_evidence_hash_at_approval,
            v_appr.approved_by,
            v_appr.approved_at,
            v_appr.expires_at);
        EXCEPTION WHEN OTHERS THEN
          v_expected_canonical := null;
        END;
        v_canonical_valid := (v_expected_canonical IS NOT NULL
          AND v_expected_canonical = v_appr.canonical_approval_evidence_hash);
        IF NOT v_canonical_valid THEN
          v_blockers := v_blockers || jsonb_build_object(
            'code','APPROVAL_CANONICAL_EVIDENCE_HASH_MISMATCH',
            'detail', jsonb_build_object(
              'stored_short', left(coalesce(v_appr.canonical_approval_evidence_hash,''),12),
              'recomputed_short', left(coalesce(v_expected_canonical,''),12)));
        END IF;
      END IF;
    END IF;
  END IF;

  -- ============= CROSS-CHECKS =============
  IF v_snap.id IS NOT NULL AND v_appr.id IS NOT NULL THEN
    IF v_snap.correlation_id IS NOT NULL
       AND v_appr.correlation_id_at_approval IS NOT NULL
       AND v_snap.correlation_id <> v_appr.correlation_id_at_approval THEN
      v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_PREVIEW_CORRELATION_MISMATCH');
    END IF;
    IF v_snap.content_hash IS DISTINCT FROM v_appr.content_hash_at_approval THEN
      v_blockers := v_blockers || jsonb_build_object('code','CONTENT_HASH_MISMATCH');
    END IF;
    IF v_snap.recipient_set_hash IS DISTINCT FROM v_appr.recipient_set_hash_at_approval THEN
      v_blockers := v_blockers || jsonb_build_object('code','APPROVAL_RECIPIENT_HASH_MISMATCH');
    END IF;
    IF v_snap.template_version_id IS DISTINCT FROM v_appr.template_version_id_at_approval THEN
      v_blockers := v_blockers || jsonb_build_object('code','TEMPLATE_VERSION_MISMATCH');
    END IF;
    IF v_snap.certified_dependency_hash IS NOT NULL
       AND v_appr.configuration_hash_at_approval IS NOT NULL
       AND v_snap.certified_dependency_hash <> v_appr.configuration_hash_at_approval THEN
      v_blockers := v_blockers || jsonb_build_object('code','CONFIGURATION_HASH_MISMATCH');
    END IF;
    IF v_snap.certified_dependency_hash IS DISTINCT FROM v_snap.current_dependency_hash THEN
      v_blockers := v_blockers || jsonb_build_object('code','DEPENDENCY_HASH_DRIFT');
    END IF;
    v_correlation := v_snap.correlation_id;
  END IF;

  -- ============= GOVERNANCE EVIDENCE =============
  IF v_snap.id IS NOT NULL THEN
    v_ge := COALESCE(v_snap.governance_evidence,'{}'::jsonb);
    IF v_snap.placeholder_scanner_version IS DISTINCT FROM 'comm-hub-raw-placeholder-scanner/v2' THEN
      v_blockers := v_blockers || jsonb_build_object('code','SCANNER_VERSION_MISMATCH','detail', jsonb_build_object('scanner_version', v_snap.placeholder_scanner_version));
    END IF;
    v_placeholder_count := COALESCE(v_snap.raw_placeholder_count, -1);
    IF v_placeholder_count < 0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','RAW_PLACEHOLDER_EVIDENCE_MISSING');
    ELSIF v_placeholder_count > 0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','RAW_PLACEHOLDER_RESIDUE','detail', jsonb_build_object('count', v_placeholder_count));
    END IF;

    -- (C) Malformed brace evidence — strict shape.
    v_mb := v_ge->'malformed_braces';
    IF v_mb IS NULL OR jsonb_typeof(v_mb) = 'null' THEN
      v_blockers := v_blockers || jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_MISSING');
    ELSIF jsonb_typeof(v_mb) = 'object' THEN
      IF jsonb_typeof(v_mb->'count') = 'number'
         AND (v_mb->>'count')::numeric = floor((v_mb->>'count')::numeric)
         AND (v_mb->>'count')::int >= 0 THEN
        v_malformed_count := (v_mb->>'count')::int;
      ELSE
        v_blockers := v_blockers || jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_INVALID');
      END IF;
    ELSIF jsonb_typeof(v_mb) = 'array' THEN
      -- documented legacy array representation
      v_malformed_count := jsonb_array_length(v_mb);
    ELSE
      v_blockers := v_blockers || jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_INVALID',
        'detail', jsonb_build_object('typeof', jsonb_typeof(v_mb)));
    END IF;
    IF v_malformed_count IS NOT NULL AND v_malformed_count > 0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','MALFORMED_BRACES_PRESENT','detail', jsonb_build_object('count', v_malformed_count));
    END IF;

    -- (E) Renderer evidence — strict shape.
    IF v_snap.renderer_unresolved_variables IS NULL OR jsonb_typeof(v_snap.renderer_unresolved_variables) = 'null' THEN
      v_blockers := v_blockers || jsonb_build_object('code','RENDERER_EVIDENCE_MISSING');
    ELSIF jsonb_typeof(v_snap.renderer_unresolved_variables) <> 'array' THEN
      v_blockers := v_blockers || jsonb_build_object('code','RENDERER_EVIDENCE_INVALID',
        'detail', jsonb_build_object('typeof', jsonb_typeof(v_snap.renderer_unresolved_variables)));
    ELSE
      v_unresolved_count := jsonb_array_length(v_snap.renderer_unresolved_variables);
      IF v_unresolved_count > 0 THEN
        v_blockers := v_blockers || jsonb_build_object('code','RENDERER_UNRESOLVED_PRESENT','detail', jsonb_build_object('count', v_unresolved_count));
      END IF;
    END IF;

    -- (D) Resolver evidence — strict per-element validation.
    IF v_snap.unresolved_variables_normalised IS NULL OR jsonb_typeof(v_snap.unresolved_variables_normalised) = 'null' THEN
      v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_EVIDENCE_MISSING');
    ELSIF jsonb_typeof(v_snap.unresolved_variables_normalised) <> 'array' THEN
      v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
        'detail', jsonb_build_object('typeof', jsonb_typeof(v_snap.unresolved_variables_normalised)));
    ELSE
      v_required_unresolved_count := 0;
      FOR v_r IN SELECT jsonb_array_elements(v_snap.unresolved_variables_normalised) LOOP
        IF jsonb_typeof(v_r) <> 'object' THEN
          v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
            'detail', jsonb_build_object('reason','non_object_entry','typeof', jsonb_typeof(v_r)));
          EXIT;
        END IF;
        IF v_r ? 'required' AND jsonb_typeof(v_r->'required') <> 'boolean' THEN
          v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
            'detail', jsonb_build_object('reason','required_not_boolean','typeof', jsonb_typeof(v_r->'required')));
          EXIT;
        END IF;
        IF (v_r->'required')::jsonb = 'true'::jsonb THEN
          v_required_unresolved_count := v_required_unresolved_count + 1;
        END IF;
      END LOOP;
      IF v_required_unresolved_count IS NOT NULL AND v_required_unresolved_count > 0 THEN
        v_blockers := v_blockers || jsonb_build_object('code','RESOLVER_REQUIRED_UNRESOLVED','detail', jsonb_build_object('count', v_required_unresolved_count));
      END IF;
    END IF;

    -- (G) Recipient container structural validation.
    v_to_len  := CASE WHEN jsonb_typeof(v_snap.to_recipients)  = 'array' THEN jsonb_array_length(v_snap.to_recipients)  ELSE -1 END;
    v_cc_len  := CASE WHEN jsonb_typeof(v_snap.cc_recipients)  = 'array' THEN jsonb_array_length(v_snap.cc_recipients)  ELSE -1 END;
    v_bcc_len := CASE WHEN jsonb_typeof(v_snap.bcc_recipients) = 'array' THEN jsonb_array_length(v_snap.bcc_recipients) ELSE -1 END;
    IF v_to_len < 0 OR v_cc_len < 0 OR v_bcc_len < 0 THEN
      v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_FROZEN_RECIPIENT_EVIDENCE_INVALID');
      v_containers_valid := false;
      v_recipients_valid := false;
    ELSE
      v_recipient_count := v_to_len + v_cc_len + v_bcc_len;
      IF v_recipient_count = 0 OR COALESCE(v_snap.recipient_set_hash,'') = '' THEN
        v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_FROZEN_RECIPIENT_EVIDENCE_MISSING');
        v_recipients_valid := false;
      ELSE
        -- (F/G) Per-role entry validation and duplicate detection.
        FOR v_role IN SELECT unnest(ARRAY['to','cc','bcc']) LOOP
          v_arr := CASE v_role
                     WHEN 'to' THEN v_snap.to_recipients
                     WHEN 'cc' THEN v_snap.cc_recipients
                     ELSE v_snap.bcc_recipients
                   END;
          FOR v_i IN 0 .. (jsonb_array_length(v_arr) - 1) LOOP
            v_entry := v_arr -> v_i;
            IF jsonb_typeof(v_entry) = 'string' THEN
              v_addr := lower(btrim(v_entry #>> '{}'));
            ELSIF jsonb_typeof(v_entry) = 'object' THEN
              -- Optional display/source fields must be strings when present.
              IF v_entry ? 'display_name' AND jsonb_typeof(v_entry->'display_name') <> 'string' THEN
                v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_RECIPIENT_FIELD_INVALID',
                  'detail', jsonb_build_object('field','display_name','role',v_role,'index',v_i));
                v_all_entries_valid := false;
              END IF;
              IF v_entry ? 'source_ref' AND jsonb_typeof(v_entry->'source_ref') <> 'string' THEN
                v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_RECIPIENT_FIELD_INVALID',
                  'detail', jsonb_build_object('field','source_ref','role',v_role,'index',v_i));
                v_all_entries_valid := false;
              END IF;
              v_addr := lower(btrim(coalesce(v_entry->>'address_normalized', v_entry->>'address','')));
            ELSE
              v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_FROZEN_RECIPIENT_EVIDENCE_INVALID',
                'detail', jsonb_build_object('role',v_role,'index',v_i,'typeof', jsonb_typeof(v_entry)));
              v_all_entries_valid := false;
              CONTINUE;
            END IF;
            IF v_addr = '' OR position('@' in v_addr) = 0 OR position('.' in split_part(v_addr,'@',2)) = 0 THEN
              v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_RECIPIENT_ADDRESS_INVALID',
                'detail', jsonb_build_object('role',v_role,'index',v_i));
              v_all_entries_valid := false;
              CONTINUE;
            END IF;
            IF v_addr = ANY(v_seen) THEN
              v_duplicate_ok := false;
              v_blockers := v_blockers || jsonb_build_object('code','PREVIEW_RECIPIENT_DUPLICATE_INVALID',
                'detail', jsonb_build_object('address_short', left(v_addr,64),'role',v_role,'index',v_i));
            ELSE
              v_seen := v_seen || v_addr;
            END IF;
          END LOOP;
        END LOOP;
        IF NOT v_all_entries_valid OR NOT v_duplicate_ok THEN
          v_recipients_valid := false;
        END IF;
      END IF;
    END IF;
  END IF;

  -- ============= READY? =============
  v_ready := jsonb_array_length(v_blockers) = 0;
  IF v_ready THEN
    v_status := 'PREFLIGHT_READY';
    v_state  := 'PREFLIGHT';
  ELSE
    v_status := 'BLOCKED';
    v_state  := 'BLOCKED';
  END IF;

  -- (H) Internally consistent evidence flags.
  v_evidence := jsonb_build_object(
    'authenticated', v_uid IS NOT NULL OR v_is_service,
    'authorized', v_is_service OR v_is_admin,
    'preview_snapshot_id', v_snap.id,
    'preview_snapshot_status', v_snap.status,
    'preview_expires_at', v_snap.expires_at,
    'preview_approval_id', v_appr.id,
    'preview_approval_status', v_appr.status,
    'approval_expires_at', v_appr.expires_at,
    'module_code', v_snap.module_code,'event_code', v_snap.event_code,'channel', v_snap.channel,
    'scope_module_code', v_module_norm,'scope_event_code', v_event_norm,'scope_channel', v_channel_norm,
    'preview_correlation_id', v_snap.correlation_id,
    'approval_correlation_id_at_approval', v_appr.correlation_id_at_approval,
    'authoritative_correlation_id', v_correlation,
    'correlation_match', (v_snap.correlation_id IS NOT NULL
                          AND v_appr.correlation_id_at_approval IS NOT NULL
                          AND v_snap.correlation_id = v_appr.correlation_id_at_approval),
    'content_hash_match', (v_snap.content_hash IS NOT DISTINCT FROM v_appr.content_hash_at_approval),
    'recipient_hash_match', (v_snap.recipient_set_hash IS NOT DISTINCT FROM v_appr.recipient_set_hash_at_approval),
    'template_version_match', (v_snap.template_version_id IS NOT DISTINCT FROM v_appr.template_version_id_at_approval),
    'configuration_hash_present', (COALESCE(v_snap.certified_dependency_hash,'')<>'' AND COALESCE(v_appr.configuration_hash_at_approval,'')<>''),
    'configuration_hash_match', (v_snap.certified_dependency_hash IS NOT DISTINCT FROM v_appr.configuration_hash_at_approval),
    'dependency_hash_drift', (v_snap.certified_dependency_hash IS DISTINCT FROM v_snap.current_dependency_hash),
    'scanner_version', v_snap.placeholder_scanner_version,
    'raw_placeholder_count', v_placeholder_count,
    'malformed_brace_count', v_malformed_count,
    'renderer_unresolved_count', v_unresolved_count,
    'resolver_required_unresolved_count', v_required_unresolved_count,
    'approval_evidence_version', v_appr.evidence_version,
    'approval_evidence_complete', v_evidence_complete,
    'approval_canonical_hash_present', v_appr.canonical_approval_evidence_hash IS NOT NULL,
    'approval_canonical_hash_valid', v_canonical_valid,
    'stored_canonical_hash_short', left(coalesce(v_appr.canonical_approval_evidence_hash,''), 12),
    'approval_canonical_hash_expected_short', left(coalesce(v_expected_canonical,''), 12),
    'recipient_recompute_ok', v_recip_recompute_ok,
    'recipient_snapshot_recomputed_hash_short', left(coalesce(v_recomputed_hash,''),12),
    'recipient_snapshot_hash_match', v_hash_match AND v_recip_recompute_ok,
    'recipient_containers_valid', v_containers_valid,
    'recipient_entries_valid', v_all_entries_valid,
    'recipient_duplicate_policy_ok', v_duplicate_ok,
    'recipient_snapshot_valid',
       v_containers_valid AND v_all_entries_valid AND v_duplicate_ok
       AND v_recip_recompute_ok AND v_hash_match
       AND coalesce(v_recipient_count,0) > 0,
    'frozen_recipient_snapshot_available',
       v_containers_valid AND v_all_entries_valid AND v_duplicate_ok
       AND v_recip_recompute_ok AND v_hash_match
       AND coalesce(v_recipient_count,0) > 0
       AND (v_snap.recipient_set_hash IS NOT DISTINCT FROM v_appr.recipient_set_hash_at_approval),
    'recipient_count', v_recipient_count,
    'recipient_to_count', v_to_len,
    'recipient_cc_count', v_cc_len,
    'recipient_bcc_count', v_bcc_len,
    'predicted_start_dry_run_blockers', v_blockers
  );

  RETURN jsonb_build_object(
    'contract_version','comm-hub-dry-run-contract/v1',
    'status', v_status,'state',  v_state,
    'passed', false,'stage_succeeded', v_ready,'terminal', NOT v_ready,
    'idempotent_replay', false,
    'failure_stage', CASE WHEN v_ready THEN null ELSE 'PREFLIGHT' END,
    'message', CASE WHEN v_ready THEN 'Preflight ready — safe to begin.' ELSE 'Preflight blocked before mutation.' END,
    'validated_at', now(),'execution_deadline_at', null,
    'correlation_id', v_correlation,
    'preview_snapshot_id', v_snap.id,'preview_approval_id', v_appr.id,
    'dry_run_execution_id', null,'execution_no', null,
    'request_id', null,'request_number', null,'message_id', null,'trace_id', null,
    'dry_run_certification_id', null,'certification_expires_at', null,
    'recipient_count', v_recipient_count,
    'blockers', v_blockers,'warnings','[]'::jsonb,'transition_log_ids','[]'::jsonb,
    'mutation_started', false,'execution_created', false,
    'request_created', false,'message_created', false,
    'created_this_call', false,'cleanup_proven', true,
    'provider_call_attempted', false,'simulator_call_attempted', false,
    'ambiguous_outcome', false,
    'retry_safe', true,
    'retry_reason', CASE WHEN v_ready THEN 'SAFE_TO_PROCEED' ELSE 'PRE_MUTATION_VALIDATION_FAILURE' END,
    'evidence', v_evidence,
    'evaluator_version','comm-hub-dry-run-preflight/v1');
END $function$;
CREATE OR REPLACE FUNCTION public.ip_app_doc_delete(p_application_reference text, p_doc_id_or_source_id text, p_user_id uuid, p_user_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing uuid;
  v_ssn varchar(6);
BEGIN
  IF p_application_reference IS NULL THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: application_reference is required';
  END IF;

  -- Try as override row id first
  BEGIN
    SELECT id INTO v_existing FROM public.ip_application_documents
     WHERE id = p_doc_id_or_source_id::uuid
       AND application_reference_number = p_application_reference
     LIMIT 1;
  EXCEPTION WHEN invalid_text_representation THEN
    v_existing := NULL;
  END;

  IF v_existing IS NOT NULL THEN
    UPDATE public.ip_application_documents
       SET is_deleted = true
     WHERE id = v_existing;
  ELSE
    -- Treat as tombstone for an external document
    SELECT ssn INTO v_ssn FROM public.ip_master
     WHERE application_id = p_application_reference LIMIT 1;
    IF v_ssn IS NULL THEN
      v_ssn := UPPER(LPAD(RIGHT(regexp_replace(p_application_reference, '[^A-Za-z0-9]', '', 'g'), 6), 6, '0'));
    END IF;

    INSERT INTO public.ip_application_documents (
      ssn, application_reference_number, source_document_id, is_deleted, created_by, uploaded_by
    ) VALUES (
      v_ssn, p_application_reference, p_doc_id_or_source_id, true, p_user_id, p_user_id
    );
  END IF;

  INSERT INTO public.ip_audit_log (table_name, record_id, action, changed_by, field_name, new_value)
  VALUES ('ip_application_documents', p_doc_id_or_source_id, 'DOC_DELETE', p_user_id, 'is_deleted', 'true');
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_app_doc_upsert(p_application_reference text, p_source_document_id text, p_file_meta jsonb, p_user_id uuid, p_user_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id      uuid;
  v_ssn     varchar(6);
  v_version int := 1;
BEGIN
  IF p_application_reference IS NULL OR length(trim(p_application_reference)) = 0 THEN
    RAISE EXCEPTION 'VALIDATION_FAILED: application_reference is required';
  END IF;
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: p_user_id is required';
  END IF;

  SELECT ssn INTO v_ssn FROM public.ip_master
   WHERE application_id = p_application_reference OR application_id::text = p_application_reference
   LIMIT 1;

  IF v_ssn IS NULL THEN
    v_ssn := UPPER(LPAD(RIGHT(regexp_replace(p_application_reference, '[^A-Za-z0-9]', '', 'g'), 6), 6, '0'));
  END IF;

  -- Compute next version and deactivate previous active row(s) for the same source_document_id
  IF p_source_document_id IS NOT NULL THEN
    SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
      FROM public.ip_application_documents
     WHERE application_reference_number = p_application_reference
       AND source_document_id = p_source_document_id;

    UPDATE public.ip_application_documents
       SET is_active = false
     WHERE application_reference_number = p_application_reference
       AND source_document_id = p_source_document_id
       AND is_active = true;
  END IF;

  INSERT INTO public.ip_application_documents (
    ssn, application_reference_number, document_name, document_type, file_name,
    file_path, url, mime_type, file_size, uploaded_at, source_document_id,
    verification_category, supportive_doc_type, is_supportive, metadata,
    created_by, uploaded_by, is_deleted, version, is_active
  ) VALUES (
    v_ssn,
    p_application_reference,
    NULLIF(p_file_meta->>'document_name',''),
    NULLIF(p_file_meta->>'document_type',''),
    NULLIF(p_file_meta->>'file_name',''),
    NULLIF(p_file_meta->>'file_path',''),
    NULLIF(p_file_meta->>'url',''),
    NULLIF(p_file_meta->>'mime_type',''),
    NULLIF(p_file_meta->>'file_size','')::bigint,
    now(),
    p_source_document_id,
    NULLIF(p_file_meta->>'verification_category',''),
    NULLIF(p_file_meta->>'supportive_doc_type',''),
    COALESCE((p_file_meta->>'is_supportive')::boolean, false),
    CASE WHEN p_file_meta ? 'metadata' THEN p_file_meta->'metadata' ELSE NULL END,
    p_user_id, p_user_id, false, v_version, true
  )
  RETURNING id INTO v_id;

  INSERT INTO public.ip_audit_log (table_name, record_id, action, changed_by, new_value, field_name)
  VALUES ('ip_application_documents', v_id::text,
          CASE WHEN p_source_document_id IS NULL THEN 'DOC_UPLOAD' ELSE 'DOC_REPLACE' END,
          p_user_id, p_file_meta->>'file_name', 'file_name');

  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_app_docs_resolve(p_application_reference text, p_external_docs jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_replaced_or_deleted_ids text[];
  v_filtered_external jsonb;
  v_active_overrides jsonb;
BEGIN
  SELECT COALESCE(array_agg(DISTINCT source_document_id), ARRAY[]::text[])
    INTO v_replaced_or_deleted_ids
    FROM public.ip_application_documents
   WHERE application_reference_number = p_application_reference
     AND source_document_id IS NOT NULL
     AND (is_active = true OR is_deleted = true);

  SELECT COALESCE(jsonb_agg(d), '[]'::jsonb) INTO v_filtered_external
  FROM jsonb_array_elements(COALESCE(p_external_docs, '[]'::jsonb)) d
  WHERE NOT ( (d->>'id') = ANY(v_replaced_or_deleted_ids) );

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', id,
           'source_document_id', source_document_id,
           'document_name', document_name,
           'document_type', document_type,
           'doc_code', metadata->>'doc_code',
           'file_name', file_name,
           'file_path', file_path,
           'url', url,
           'mime_type', mime_type,
           'file_size', file_size,
           'uploaded_at', uploaded_at,
           'verification_category', verification_category,
           'supportive_doc_type', supportive_doc_type,
           'is_supportive', is_supportive,
           'metadata', metadata,
           'version', version,
           'source', 'override'
         )), '[]'::jsonb)
    INTO v_active_overrides
    FROM public.ip_application_documents
   WHERE application_reference_number = p_application_reference
     AND is_active = true
     AND is_deleted = false
     AND COALESCE(file_path, url, '') <> '';

  RETURN jsonb_build_object(
    'external',  v_filtered_external,
    'overrides', v_active_overrides,
    'merged',    v_filtered_external || v_active_overrides
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_app_docs_resolve_for_conversion(p_application_reference text, p_external_docs jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_decisions      jsonb := '[]'::jsonb;
  v_merged         jsonb := '[]'::jsonb;
  v_missing        text[] := ARRAY[]::text[];
  v_ext            jsonb;
  v_ovr            RECORD;
  v_match          RECORD;
  v_present_cats   text[] := ARRAY[]::text[];
  v_mandatory_cats text[] := ARRAY['birth_status','name_status'];
  v_doc_id         text;
  v_used_override_ids uuid[] := ARRAY[]::uuid[];
  v_norm           jsonb;
  v_is_supportive  boolean;
  v_v_cat          text;
  v_doc_code       text;
BEGIN
  -- Iterate external docs first
  IF p_external_docs IS NOT NULL THEN
    FOR v_ext IN SELECT * FROM jsonb_array_elements(COALESCE(p_external_docs, '[]'::jsonb))
    LOOP
      v_doc_id := COALESCE(v_ext->>'id', v_ext->>'documentId', v_ext->>'document_id');

      -- Find a matching reviewer override (active OR deleted) by source_document_id
      SELECT * INTO v_match
        FROM public.ip_application_documents
       WHERE application_reference_number = p_application_reference
         AND source_document_id IS NOT NULL
         AND source_document_id = v_doc_id
       ORDER BY (CASE WHEN is_deleted THEN 1 ELSE 0 END), version DESC
       LIMIT 1;

      IF FOUND AND COALESCE(v_match.is_deleted, FALSE) = TRUE THEN
        -- Reviewer deleted this external doc → exclude from merged
        v_decisions := v_decisions || jsonb_build_object(
          'source_document_id', v_doc_id,
          'decision',           'deleted_by_reviewer',
          'before_snapshot',    v_ext,
          'after_snapshot',     NULL
        );
        v_used_override_ids := v_used_override_ids || v_match.id;
        CONTINUE;
      ELSIF FOUND THEN
        -- Reviewer replaced → use the override row, normalized
        v_v_cat         := COALESCE(v_match.verification_category, '');
        v_is_supportive := COALESCE(v_match.is_supportive, FALSE)
                           OR v_v_cat = 'supportive'
                           OR v_match.supportive_doc_type IS NOT NULL;
        v_doc_code      := COALESCE(v_match.metadata->>'doc_code', NULL);
        IF v_doc_code IS NULL AND v_match.document_type IS NOT NULL
           AND char_length(v_match.document_type) = 1 THEN
          v_doc_code := upper(v_match.document_type);
        END IF;

        v_norm := jsonb_build_object(
          'id',                v_match.id::text,
          'name',              COALESCE(v_match.document_name, v_match.file_name),
          'fileName',          COALESCE(v_match.file_name, v_match.document_name),
          'documentType',      v_match.document_type,
          'type',              v_match.document_type,
          'verificationType',  NULLIF(v_v_cat, ''),
          'filePath',          v_match.file_path,
          'url',               v_match.url,
          'signedUrl',         v_match.signed_url,
          'mimeType',          v_match.mime_type,
          'fileSize',          CASE WHEN v_match.file_size IS NOT NULL THEN v_match.file_size::text ELSE NULL END,
          'uploadedAt',        v_match.uploaded_at,
          'isSupportive',      v_is_supportive,
          'supportiveDocType', v_match.supportive_doc_type,
          'docCode',           v_doc_code,
          'metadata',          COALESCE(v_match.metadata, '{}'::jsonb)
                                || jsonb_build_object('doc_code', v_doc_code)
        );

        v_merged    := v_merged || v_norm;
        v_decisions := v_decisions || jsonb_build_object(
          'source_document_id', v_doc_id,
          'decision',           'replaced_by_reviewer',
          'before_snapshot',    v_ext,
          'after_snapshot',     v_norm
        );
        v_used_override_ids := v_used_override_ids || v_match.id;
        IF NULLIF(v_v_cat, '') IS NOT NULL THEN
          v_present_cats := v_present_cats || v_v_cat;
        END IF;
        CONTINUE;
      END IF;

      -- Kept external as-is (already in canonical RPC shape from the client)
      v_merged    := v_merged || v_ext;
      v_decisions := v_decisions || jsonb_build_object(
        'source_document_id', v_doc_id,
        'decision',           'kept_external',
        'before_snapshot',    v_ext,
        'after_snapshot',     v_ext
      );
      IF v_ext ? 'verificationType' AND NULLIF(v_ext->>'verificationType','') IS NOT NULL THEN
        v_present_cats := v_present_cats || (v_ext->>'verificationType');
      END IF;
    END LOOP;
  END IF;

  -- Reviewer-added docs (active overrides not already consumed above)
  FOR v_ovr IN
    SELECT *
      FROM public.ip_application_documents
     WHERE application_reference_number = p_application_reference
       AND COALESCE(is_active, TRUE) = TRUE
       AND COALESCE(is_deleted, FALSE) = FALSE
       AND COALESCE(file_path, url, '') <> ''
       AND NOT (id = ANY(v_used_override_ids))
  LOOP
    v_v_cat         := COALESCE(v_ovr.verification_category, '');
    v_is_supportive := COALESCE(v_ovr.is_supportive, FALSE)
                       OR v_v_cat = 'supportive'
                       OR v_ovr.supportive_doc_type IS NOT NULL;
    v_doc_code      := COALESCE(v_ovr.metadata->>'doc_code', NULL);
    IF v_doc_code IS NULL AND v_ovr.document_type IS NOT NULL
       AND char_length(v_ovr.document_type) = 1 THEN
      v_doc_code := upper(v_ovr.document_type);
    END IF;

    v_norm := jsonb_build_object(
      'id',                v_ovr.id::text,
      'name',              COALESCE(v_ovr.document_name, v_ovr.file_name),
      'fileName',          COALESCE(v_ovr.file_name, v_ovr.document_name),
      'documentType',      v_ovr.document_type,
      'type',              v_ovr.document_type,
      'verificationType',  NULLIF(v_v_cat, ''),
      'filePath',          v_ovr.file_path,
      'url',               v_ovr.url,
      'signedUrl',         v_ovr.signed_url,
      'mimeType',          v_ovr.mime_type,
      'fileSize',          CASE WHEN v_ovr.file_size IS NOT NULL THEN v_ovr.file_size::text ELSE NULL END,
      'uploadedAt',        v_ovr.uploaded_at,
      'isSupportive',      v_is_supportive,
      'supportiveDocType', v_ovr.supportive_doc_type,
      'docCode',           v_doc_code,
      'metadata',          COALESCE(v_ovr.metadata, '{}'::jsonb)
                            || jsonb_build_object('doc_code', v_doc_code)
    );

    v_merged    := v_merged || v_norm;
    v_decisions := v_decisions || jsonb_build_object(
      'source_document_id', v_ovr.source_document_id,
      'decision',           'reviewer_added',
      'before_snapshot',    NULL,
      'after_snapshot',     v_norm
    );
    IF NULLIF(v_v_cat, '') IS NOT NULL THEN
      v_present_cats := v_present_cats || v_v_cat;
    END IF;
  END LOOP;

  -- Mandatory document check (mandatory categories minus 'supportive')
  SELECT COALESCE(array_agg(c), ARRAY[]::text[])
    INTO v_missing
    FROM unnest(v_mandatory_cats) c
   WHERE NOT (c = ANY(v_present_cats));

  RETURN jsonb_build_object(
    'merged',            v_merged,
    'decisions',         v_decisions,
    'missing_mandatory', to_jsonb(v_missing)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_documents_enqueue_dms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_active = true
     AND COALESCE(NEW.transfer_status, 'Pending') = 'Pending'
     AND COALESCE(NEW.file_path, '') <> '' THEN
    INSERT INTO public.dms_transfer_queue (scope, document_id, ssn)
    VALUES ('ip', NEW.id, NEW.ssn)
    ON CONFLICT (scope, document_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_master_post_insert_mirror_docs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Mirror any pending overrides for this application_id into ip_documents.
  IF NEW.application_id IS NOT NULL THEN
    PERFORM public.ip_mirror_app_docs_to_master(
      NEW.unique_uuid,
      NEW.ssn,
      NEW.application_id::text,
      NEW.created_by
    );
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_master_ssn_cascade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ssn IS DISTINCT FROM OLD.ssn AND NEW.ssn IS NOT NULL THEN
    UPDATE public.ip_documents
       SET ssn = NEW.ssn
     WHERE unique_uuid = NEW.unique_uuid;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ip_mirror_app_docs_to_master(p_unique_uuid uuid, p_ssn character varying, p_application_reference text, p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer := 0;
BEGIN
  INSERT INTO public.ip_documents (
    unique_uuid, ssn, document_type, document_name, file_path, file_size, mime_type,
    uploaded_at, uploaded_by, is_temp, verification_category, supportive_doc_type, is_supportive
  )
  SELECT
    p_unique_uuid,
    p_ssn,
    COALESCE(d.document_type, 'unknown'),
    COALESCE(d.document_name, d.file_name, 'unknown'),
    COALESCE(d.file_path, d.url, ''),
    d.file_size::int,
    d.mime_type,
    COALESCE(d.uploaded_at, now()),
    p_user_id,
    true,
    d.verification_category,
    d.supportive_doc_type,
    COALESCE(d.is_supportive, false)
  FROM public.ip_application_documents d
  WHERE d.application_reference_number = p_application_reference
    AND COALESCE(d.is_deleted, false) = false
    AND COALESCE(d.file_path, d.url, '') <> '';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;
