CREATE OR REPLACE FUNCTION public.legal_referral_guard_info_requested()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'INFO_REQUESTED' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    IF NOT EXISTS (
      SELECT 1 FROM legal_referral_info_request
      WHERE legal_referral_id = NEW.id AND status = 'PENDING_SOURCE_RESPONSE'
    ) THEN
      RAISE EXCEPTION 'Cannot set legal_referral.status=INFO_REQUESTED without an open info request (referral %)', NEW.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.legal_referral_process_sla()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_due_soon int := 0;
  v_overdue  int := 0;
  v_escalated int := 0;
  r record;
BEGIN
  -- DUE_SOON: reminder_at <= now < due_date and currently ON_TIME
  UPDATE public.legal_referral_info_request
     SET sla_status = 'DUE_SOON'
   WHERE status = 'PENDING_SOURCE_RESPONSE'
     AND sla_status = 'ON_TIME'
     AND reminder_at IS NOT NULL
     AND reminder_at <= now()
     AND (due_date IS NULL OR due_date >= now()::date);
  GET DIAGNOSTICS v_due_soon = ROW_COUNT;

  -- OVERDUE: past due_date, not yet escalated
  UPDATE public.legal_referral_info_request
     SET sla_status = 'OVERDUE'
   WHERE status = 'PENDING_SOURCE_RESPONSE'
     AND sla_status IN ('ON_TIME','DUE_SOON')
     AND due_date IS NOT NULL
     AND due_date < now()::date;
  GET DIAGNOSTICS v_overdue = ROW_COUNT;

  -- ESCALATE: past escalation_at
  FOR r IN
    SELECT ir.*, sr.escalation_workbasket, sr.escalation_team
      FROM public.legal_referral_info_request ir
      LEFT JOIN public.legal_referral_sla_rule sr ON sr.id = ir.sla_rule_id
     WHERE ir.status = 'PENDING_SOURCE_RESPONSE'
       AND ir.sla_status <> 'ESCALATED'
       AND ir.escalation_at IS NOT NULL
       AND ir.escalation_at <= now()
  LOOP
    UPDATE public.legal_referral_info_request
       SET sla_status='ESCALATED',
           escalated_at = now(),
           escalated_to_workbasket = COALESCE(r.escalation_workbasket, escalated_to_workbasket),
           escalated_to_team       = COALESCE(r.escalation_team, escalated_to_team)
     WHERE id = r.id;

    INSERT INTO public.legal_referral_sla_event(info_request_id, legal_referral_id, event_type, prior_status, new_status, actor, payload)
    VALUES (r.id, r.legal_referral_id, 'ESCALATED', r.sla_status, 'ESCALATED', 'SYSTEM',
            jsonb_build_object('escalation_workbasket', r.escalation_workbasket, 'escalation_team', r.escalation_team));

    v_escalated := v_escalated + 1;
  END LOOP;

  RETURN jsonb_build_object('due_soon', v_due_soon, 'overdue', v_overdue, 'escalated', v_escalated, 'ran_at', now());
END $function$;
CREATE OR REPLACE FUNCTION public.legal_referral_sync_from_bn()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE new_status TEXT;
BEGIN
  new_status := CASE NEW.status
    WHEN 'ACCEPTED_BY_LEGAL' THEN 'ACCEPTED'
    WHEN 'IN_LEGAL_PROCEEDINGS' THEN 'LEGAL_CASE_CREATED'
    ELSE NEW.status END;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.legal_referral (
      referral_no, source_module, source_record_type, source_record_id, source_reference_no,
      primary_entity_type, primary_entity_id, submitted_by, status, legal_case_id,
      source_bn_referral_id, lg_intake_id, summary, priority_code, exposure_amount
    ) VALUES (
      NEW.referral_number, 'BENEFITS',
      CASE WHEN NEW.source_claim_id IS NOT NULL THEN 'CLAIM' WHEN NEW.source_award_id IS NOT NULL THEN 'AWARD' ELSE 'OTHER' END,
      COALESCE(NEW.source_record_id, NEW.source_claim_id::text, NEW.source_award_id::text),
      COALESCE(NEW.source_reference_no, NEW.referral_number),
      CASE WHEN NEW.insured_person_id IS NOT NULL THEN 'INSURED_PERSON' WHEN NEW.employer_id IS NOT NULL THEN 'EMPLOYER' ELSE NULL END,
      COALESCE(NEW.insured_person_id, NEW.employer_id),
      COALESCE(NEW.submitted_by, NEW.referred_by, NEW.created_by),
      new_status, NEW.lg_case_id, NEW.id, NEW.lg_intake_id, NEW.referral_reason,
      NEW.priority_code, NEW.exposure_amount
    ) ON CONFLICT (referral_no) DO NOTHING;
  ELSE
    UPDATE public.legal_referral SET
      status = new_status, legal_case_id = NEW.lg_case_id, lg_intake_id = NEW.lg_intake_id,
      last_status_at = now()
    WHERE source_bn_referral_id = NEW.id;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_referral_sync_from_ce()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE new_status TEXT;
BEGIN
  new_status := CASE NEW.status
    WHEN 'ACCEPTED_BY_LEGAL' THEN 'ACCEPTED'
    WHEN 'IN_LEGAL_PROCEEDINGS' THEN 'LEGAL_CASE_CREATED'
    ELSE NEW.status END;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.legal_referral (
      referral_no, source_module, source_record_type, source_record_id, source_reference_no,
      primary_entity_type, primary_entity_id, submitted_by, status, legal_case_id,
      source_ce_referral_id, lg_intake_id, summary, exposure_amount
    ) VALUES (
      NEW.referral_number, 'COMPLIANCE', 'CASE',
      COALESCE(NEW.source_record_id, NEW.source_case_id::text),
      COALESCE(NEW.source_reference_no, NEW.referral_number),
      'EMPLOYER', NEW.employer_id,
      COALESCE(NEW.referred_by, NEW.created_by),
      new_status, NEW.legal_case_id, NEW.id, NEW.lg_intake_id,
      NEW.referral_reason_text, NEW.grand_total
    ) ON CONFLICT (referral_no) DO NOTHING;
  ELSE
    UPDATE public.legal_referral SET
      status = new_status, legal_case_id = NEW.legal_case_id, lg_intake_id = NEW.lg_intake_id,
      last_status_at = now()
    WHERE source_ce_referral_id = NEW.id;
