CREATE OR REPLACE FUNCTION public.legal_stage_template_completeness()
 RETURNS TABLE(stage_code text, total_required bigint, total_mapped bigint, missing_required text[])
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH stages AS (
    SELECT UNNEST(ARRAY[
      'REFERRAL_RECEIVED','LEGAL_REVIEW','DEMAND_NOTICE','SETTLEMENT_NEGOTIATION',
      'COURT_FILING','HEARING','JUDGMENT','ENFORCEMENT','FEES_AND_WAIVERS','CLOSED'
    ]) AS stage_code
  ),
  mapped AS (
    SELECT u.stage_code,
           COUNT(*) FILTER (WHERE u.is_required) AS req,
           COUNT(*) AS total,
           ARRAY_AGG(t.code) FILTER (WHERE u.is_required AND t.active_version_id IS NULL) AS missing
      FROM public.core_template_usage u
      JOIN public.core_template t ON t.id = u.template_id
     WHERE u.module_code = 'LEGAL' AND u.is_active
     GROUP BY u.stage_code
  )
  SELECT s.stage_code,
         COALESCE(m.req, 0)   AS total_required,
         COALESCE(m.total, 0) AS total_mapped,
         COALESCE(m.missing, ARRAY[]::TEXT[]) AS missing_required
    FROM stages s
    LEFT JOIN mapped m ON m.stage_code = s.stage_code
    ORDER BY s.stage_code;
$function$;
CREATE OR REPLACE FUNCTION public.lg_assign_case(p_case_id uuid, p_actor_user_code text, p_reason text DEFAULT 'intake'::text, p_override_user_id uuid DEFAULT NULL::uuid, p_override_team text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case   public.lg_case%ROWTYPE;
  v_route  jsonb;
  v_pick   jsonb;
  v_team   text;
  v_team_id uuid;
  v_wb     text;
  v_strat  text;
  v_skill  text;
  v_user   uuid;
  v_code   text;
  v_prev   uuid;
  v_esc    text;
  v_pickReason text;
  v_manager uuid;
BEGIN
  SELECT * INTO v_case FROM public.lg_case WHERE id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'lg_case % not found', p_case_id;
  END IF;

  IF p_override_user_id IS NOT NULL OR p_override_team IS NOT NULL THEN
    v_team := COALESCE(p_override_team, v_case.assigned_team_code);
    v_user := p_override_user_id;
    v_pickReason := 'manual_override';
  ELSE
    v_route := public.lg_resolve_route(
      v_case.case_source_code,
      v_case.case_type_code,
      v_case.current_stage_code,
      v_case.priority_code,
      NULL, NULL
    );

    IF v_route->>'validation_status' = 'ERROR' THEN
      RETURN jsonb_build_object('ok', false, 'route', v_route);
    END IF;

    v_team  := v_route->>'team_code';
    v_wb    := v_route->>'workbasket_code';
    v_strat := COALESCE(v_route->>'assignment_strategy','LEAST_ACTIVE');
    v_skill := v_route->>'required_skill';
    v_esc   := v_route->>'escalation_team_code';

    v_pick := public.lg_pick_assignee(v_team, v_strat, v_case.priority_code, v_skill);
    v_user := NULLIF(v_pick->>'assigned_to_user_id','')::uuid;
    v_code := v_pick->>'assigned_user_code';
    v_pickReason := v_pick->>'reason';

    IF v_user IS NULL AND v_esc IS NOT NULL THEN
      v_team := v_esc;
      v_pick := public.lg_pick_assignee(v_team, v_strat, v_case.priority_code, v_skill);
      v_user := NULLIF(v_pick->>'assigned_to_user_id','')::uuid;
      v_code := v_pick->>'assigned_user_code';
      v_pickReason := COALESCE(v_pick->>'reason','escalated');
    END IF;
  END IF;

  UPDATE public.lg_case_assignment
     SET is_current = false, unassigned_at = now()
   WHERE lg_case_id = p_case_id AND is_current = true
  RETURNING assigned_to_user_id INTO v_prev;

  INSERT INTO public.lg_case_assignment
    (lg_case_id, assigned_to_user_id, assigned_team_code, assigned_by, reason, is_current)
  VALUES
    (p_case_id, v_user, v_team, p_actor_user_code,
     COALESCE(v_pickReason, p_reason), true);

  INSERT INTO public.lg_case_assignment_history
    (lg_case_id, assigned_from_user_id, assigned_to_user_id, assigned_team_code,
     workbasket_code, strategy, reason, assigned_by, notes)
  VALUES
    (p_case_id, v_prev, v_user, v_team, v_wb, v_strat,
     p_reason, p_actor_user_code,
     CASE WHEN v_user IS NULL THEN 'Queued: ' || COALESCE(v_pickReason,'no_eligible_staff') END);

  UPDATE public.lg_case
     SET assigned_team_code = v_team,
         assigned_legal_officer_id = v_user,
         updated_by = p_actor_user_code,
         updated_at = now()
   WHERE id = p_case_id;

  -- Notifications
  IF v_user IS NOT NULL THEN
    BEGIN
      INSERT INTO public.in_app_notifications
        (user_id, title, body, link, notification_type, priority, module, related_record_id, metadata)
      VALUES (
        v_user,
        'New case assigned: ' || v_case.lg_case_no,
        'You have been assigned to ' || v_case.lg_case_no ||
          ' (' || COALESCE(v_case.case_type_code,'') || ', priority ' || v_case.priority_code || ').',
        '/legal/lg/cases/' || p_case_id::text,
        'legal_assignment',
        CASE WHEN v_case.priority_code IN ('HIGH','URGENT','CRITICAL') THEN 'high' ELSE 'normal' END,
        'LEGAL',
        p_case_id::text,
        jsonb_build_object('team_code', v_team, 'workbasket_code', v_wb,
                           'strategy', v_strat, 'reason', COALESCE(v_pickReason, p_reason))
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  ELSE
    -- Queued: notify team manager
    SELECT manager_user_id INTO v_manager FROM public.lg_team WHERE team_code = v_team;
    IF v_manager IS NOT NULL THEN
      BEGIN
        INSERT INTO public.in_app_notifications
          (user_id, title, body, link, notification_type, priority, module, related_record_id, metadata)
        VALUES (
          v_manager,
          'Case queued: ' || v_case.lg_case_no,
          'No staff in team ' || v_team || ' has capacity. ' || v_case.lg_case_no || ' is held in the team queue.',
          '/legal/lg/cases/' || p_case_id::text,
          'legal_capacity_alert',
          'high',
          'LEGAL',
          p_case_id::text,
          jsonb_build_object('team_code', v_team, 'reason', v_pickReason)
        );
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'team_code',           v_team,
    'workbasket_code',     v_wb,
    'strategy',            v_strat,
    'assigned_to_user_id', v_user,
    'assigned_user_code',  v_code,
    'reason',              v_pickReason,
    'queued',              (v_user IS NULL)
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.lg_assign_next_owner(p_workbasket_code text, p_country_code text DEFAULT 'SKN'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_team_code text; v_team_id uuid; v_strategy text; v_owner uuid;
BEGIN
  SELECT owning_team_code INTO v_team_code FROM public.lg_workbasket_role WHERE workbasket_code=p_workbasket_code AND is_active=true LIMIT 1;
  IF v_team_code IS NULL THEN RETURN NULL; END IF;
  SELECT id INTO v_team_id FROM public.lg_team WHERE team_code=v_team_code AND is_active=true AND country_code=p_country_code LIMIT 1;
  IF v_team_id IS NULL THEN RETURN NULL; END IF;
  SELECT assignment_strategy INTO v_strategy FROM public.lg_routing_source_map WHERE workbasket_code=p_workbasket_code AND is_active=true ORDER BY updated_at DESC NULLS LAST LIMIT 1;
  v_strategy := COALESCE(v_strategy,'BY_WORKLOAD');
  IF v_strategy='WORKBASKET_ONLY' THEN RETURN NULL; END IF;
  IF v_strategy='ROUND_ROBIN' THEN
    SELECT tm.user_id INTO v_owner FROM public.lg_team_member tm
    LEFT JOIN (SELECT assigned_to_user_id, MAX(assigned_at) last_at FROM public.lg_case_assignment WHERE is_current=true GROUP BY 1) la ON la.assigned_to_user_id=tm.user_id
    WHERE tm.team_id=v_team_id AND tm.is_active=true AND tm.can_own_case=true AND tm.role_code IN ('LEGAL_OFFICER','SENIOR_LEGAL_OFFICER')
    ORDER BY la.last_at NULLS FIRST LIMIT 1;
  ELSE
    SELECT tm.user_id INTO v_owner FROM public.lg_team_member tm
    LEFT JOIN (SELECT assigned_to_user_id, COUNT(*) open_cnt FROM public.lg_case_assignment WHERE is_current=true GROUP BY 1) wl ON wl.assigned_to_user_id=tm.user_id
    WHERE tm.team_id=v_team_id AND tm.is_active=true AND tm.can_own_case=true AND tm.role_code IN ('LEGAL_OFFICER','SENIOR_LEGAL_OFFICER')
    ORDER BY COALESCE(wl.open_cnt,0), random() LIMIT 1;
  END IF;
  RETURN v_owner;
END; $function$;
CREATE OR REPLACE FUNCTION public.lg_assignment_integrity_report()
 RETURNS TABLE(case_id uuid, lg_case_no text, source_module text, workbasket_code text, team_code text, assigned_owner_email text, assignment_strategy text, issue_code text, issue_message text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH base AS (
    SELECT c.id AS case_id, c.lg_case_no, c.source_module,
           ca.assigned_team_code AS team_code, ca.assigned_to_user_id AS owner_id,
           rsm.workbasket_code, rsm.assignment_strategy, p.email AS owner_email
    FROM public.lg_case c
    LEFT JOIN public.lg_case_assignment ca ON ca.lg_case_id=c.id AND ca.is_current=true
    LEFT JOIN public.lg_routing_source_map rsm ON rsm.source_code=c.source_module AND rsm.is_active=true
    LEFT JOIN public.profiles p ON p.id=ca.assigned_to_user_id
  )
  SELECT case_id, lg_case_no, source_module, workbasket_code, team_code, owner_email, assignment_strategy, 'NO_WORKBASKET'::text, 'Case is not mapped to any workbasket'::text FROM base WHERE workbasket_code IS NULL
  UNION ALL SELECT case_id, lg_case_no, source_module, workbasket_code, team_code, owner_email, assignment_strategy, 'NO_TEAM','Case has no team assignment' FROM base WHERE team_code IS NULL AND workbasket_code IS NOT NULL
  UNION ALL SELECT case_id, lg_case_no, source_module, workbasket_code, team_code, owner_email, assignment_strategy, 'NO_ELIGIBLE_OWNER','Workbasket has no eligible owner assigned' FROM base WHERE owner_id IS NULL AND assignment_strategy IN ('BY_WORKLOAD','ROUND_ROBIN')
  UNION ALL SELECT b.case_id,b.lg_case_no,b.source_module,b.workbasket_code,b.team_code,b.owner_email,b.assignment_strategy,'OWNER_NOT_IN_TEAM','Assigned user is not an active member of the owning team'
    FROM base b LEFT JOIN public.lg_team t ON t.team_code=b.team_code LEFT JOIN public.lg_team_member tm ON tm.user_id=b.owner_id AND tm.team_id=t.id AND tm.is_active=true
    WHERE b.owner_id IS NOT NULL AND tm.id IS NULL
  UNION ALL SELECT b.case_id,b.lg_case_no,b.source_module,b.workbasket_code,b.team_code,b.owner_email,b.assignment_strategy,'READ_ONLY_OWNER','Read-only user is assigned as case owner'
    FROM base b JOIN public.user_roles ur ON ur.user_id=b.owner_id AND ur.role='LEGAL_READ_ONLY' WHERE b.owner_id IS NOT NULL
  UNION ALL SELECT b.case_id,b.lg_case_no,b.source_module,b.workbasket_code,b.team_code,b.owner_email,b.assignment_strategy,'WORKBASKET_NO_TEAM','Workbasket has no owning team mapped'
    FROM base b LEFT JOIN public.lg_workbasket_role wr ON wr.workbasket_code=b.workbasket_code AND wr.is_active=true
    WHERE b.workbasket_code IS NOT NULL AND wr.owning_team_code IS NULL;
$function$;
CREATE OR REPLACE FUNCTION public.lg_build_standard_body(p_subject text, p_intro text, p_action text, p_consequences text DEFAULT 'Failure to comply with this notice within the stated deadline may result in further legal proceedings, additional penalties, garnishment, judgment enforcement and/or referral to court without further notice. All costs of enforcement may be charged to you.'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
SELECT format($html$
<div class="lg-doc">
  <header class="lg-doc__header">
    <div class="lg-doc__brand">
      <strong>SOCIAL SECURITY BOARD</strong><br/>
      Saint Kitts and Nevis
    </div>
    <div class="lg-doc__ref">
      <div><strong>Reference No:</strong> {{document.reference_no}}</div>
      <div><strong>Date:</strong> {{document.generated_date}}</div>
      <div><strong>Case No:</strong> {{legal.case_no}}</div>
    </div>
  </header>

  <section class="lg-doc__recipient">
    <div>{{recipient.name}}</div>
    <div>{{recipient.address_line1}}</div>
    <div>{{recipient.address_line2}}</div>
    <div>{{recipient.city}}, {{recipient.country}}</div>
  </section>

  <h1 class="lg-doc__subject">%1$s</h1>

  <section class="lg-doc__body">
    <p>Dear {{recipient.salutation}} {{recipient.name}},</p>
    <p>%2$s</p>
  </section>

  <section class="lg-doc__legal-refs">
    <h3>Legal References</h3>
    <div data-block="legal_references">{{legal_references.list}}</div>
  </section>

  <section class="lg-doc__action">
    <h3>Action Required</h3>
    <p>%3$s</p>
    <p><strong>Deadline:</strong> {{legal.action_deadline}}</p>
  </section>

  <section class="lg-doc__consequences">
    <h3>Consequences of Non-Compliance</h3>
    <p>%4$s</p>
  </section>

  <section class="lg-doc__contact">
    <h3>Contact Details</h3>
    <p>
      Legal Department, Social Security Board<br/>
      Bay Road, Basseterre, St. Kitts<br/>
      Telephone: (869) 465-2535 &nbsp;|&nbsp; Email: legal@socialsecurity.kn<br/>
      Office Hours: Monday – Friday, 8:00 AM – 4:00 PM
    </p>
  </section>

  <section class="lg-doc__signature">
    <p>Yours faithfully,</p>
    <br/><br/>
    <div><strong>{{officer.name}}</strong></div>
    <div>{{officer.title}}</div>
    <div>Legal Department, Social Security Board</div>
  </section>

  <footer class="lg-doc__footer">
    This is an official communication of the Social Security Board of Saint Kitts and Nevis.
    Document Ref {{document.reference_no}} generated on {{document.generated_date}}.
    For verification, contact legal@socialsecurity.kn quoting the reference number above.
  </footer>
</div>
$html$, p_subject, p_intro, p_action, p_consequences);
$function$;
CREATE OR REPLACE FUNCTION public.lg_build_standard_structure(p_subject text, p_intro text, p_action text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
SELECT jsonb_build_array(
  jsonb_build_object('id','blk-header','type','header','props', jsonb_build_object('brand','Social Security Board','country','Saint Kitts and Nevis')),
  jsonb_build_object('id','blk-ref','type','reference_no','props', jsonb_build_object()),
  jsonb_build_object('id','blk-recipient','type','recipient','props', jsonb_build_object()),
  jsonb_build_object('id','blk-subject','type','heading','props', jsonb_build_object('level',1,'text',p_subject)),
  jsonb_build_object('id','blk-body','type','paragraph','props', jsonb_build_object('text',p_intro)),
  jsonb_build_object('id','blk-legal','type','legal_reference','props', jsonb_build_object()),
  jsonb_build_object('id','blk-action','type','heading','props', jsonb_build_object('level',3,'text','Action Required')),
  jsonb_build_object('id','blk-action-body','type','paragraph','props', jsonb_build_object('text', p_action)),
  jsonb_build_object('id','blk-deadline','type','paragraph','props', jsonb_build_object('text','Deadline: {{legal.action_deadline}}')),
  jsonb_build_object('id','blk-consequences','type','disclaimer','props', jsonb_build_object('text','Failure to comply may result in further legal proceedings, additional penalties, garnishment or court referral.')),
  jsonb_build_object('id','blk-contact','type','contact_details','props', jsonb_build_object()),
  jsonb_build_object('id','blk-signature','type','signature','props', jsonb_build_object()),
  jsonb_build_object('id','blk-footer','type','disclaimer','props', jsonb_build_object('text','This is an official communication of the Social Security Board. Ref {{document.reference_no}}.'))
);
$function$;
CREATE OR REPLACE FUNCTION public.lg_case_action_autoclose_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case_id uuid := COALESCE(NEW.case_id, OLD.case_id);
  v_open_count integer;
BEGIN
  IF v_case_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT COUNT(*) INTO v_open_count
  FROM public.lg_case_action
  WHERE case_id = v_case_id
    AND status NOT IN ('CLOSED','WITHDRAWN');

  IF v_open_count = 0 THEN
    UPDATE public.lg_case
       SET status_code = 'CLOSED',
           closed_date = COALESCE(closed_date, CURRENT_DATE),
           updated_at = now()
     WHERE id = v_case_id
       AND status_code <> 'CLOSED';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_case_intake_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status varchar(40);
BEGIN
  IF NEW.source_intake_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT qualification_status INTO v_status
    FROM public.lg_case_intake
   WHERE id = NEW.source_intake_id;
  IF v_status IS NULL THEN
    RETURN NEW;
  END IF;
  IF v_status NOT IN ('APPROVED','CONVERTED_TO_CASE') THEN
    RAISE EXCEPTION 'Legal Case cannot be created — intake % is % (must be APPROVED).', NEW.source_intake_id, v_status;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_case_intake_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;$function$;
CREATE OR REPLACE FUNCTION public.lg_case_sync_court_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name TEXT;
BEGIN
  IF NEW.court_code IS NOT NULL AND (NEW.court_name IS NULL OR NEW.court_name = '' OR
      (TG_OP = 'UPDATE' AND NEW.court_code IS DISTINCT FROM OLD.court_code)) THEN
    SELECT court_name INTO v_name FROM public.lg_court WHERE court_code = NEW.court_code;
    IF v_name IS NOT NULL THEN
      NEW.court_name := v_name;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
