 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_court_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_create_case_from_intake(p_intake_id uuid, p_actor character varying)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_intake   public.lg_case_intake%ROWTYPE;
  v_missing  int;
  v_case_id  uuid;
  v_case_no  text;
BEGIN
  SELECT * INTO v_intake FROM public.lg_case_intake WHERE id = p_intake_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Intake % not found', p_intake_id; END IF;

  IF v_intake.qualification_status <> 'APPROVED' THEN
    RAISE EXCEPTION 'Intake must be APPROVED before case creation (current: %)', v_intake.qualification_status;
  END IF;

  -- Mandatory checklist gate
  SELECT count(*) INTO v_missing
    FROM public.lg_intake_checklist_template t
    LEFT JOIN public.lg_intake_checklist_response r
      ON r.template_item_id = t.id AND r.intake_id = p_intake_id
   WHERE t.mandatory = true AND t.active = true
     AND (r.status IS NULL OR r.status NOT IN ('COMPLETE','NA'));
  IF v_missing > 0 THEN
    RAISE EXCEPTION 'Cannot create case: % mandatory checklist items outstanding', v_missing;
  END IF;

  -- Assessments gate
  IF v_intake.financial_exposure IS NULL AND v_intake.financial_outstanding IS NULL THEN
    RAISE EXCEPTION 'Financial assessment incomplete';
  END IF;
  IF v_intake.legal_issue IS NULL OR v_intake.recovery_type IS NULL THEN
    RAISE EXCEPTION 'Legal assessment incomplete';
  END IF;

  -- Supervisor approval
  IF v_intake.supervisor_required AND coalesce(v_intake.supervisor_status,'') <> 'APPROVED' THEN
    RAISE EXCEPTION 'Supervisor approval required and not granted';
  END IF;

  v_case_no := 'LC-' || to_char(now(),'YYYY') || '-' || substr(replace(gen_random_uuid()::text,'-',''),1,8);

  INSERT INTO public.lg_case(
    case_no, country_code, matter_type_code, case_type_code,
    primary_entity_type, primary_entity_id,
    legal_status, case_stage, priority_code,
    exposure_amount, source_intake_id, source_module,
    opened_date, created_at, updated_at, created_by
  ) VALUES (
    v_case_no, coalesce(v_intake.country_code,'SKN'),
    v_intake.matter_type_code, coalesce(v_intake.recommended_case_type_code, v_intake.matter_type_code),
    v_intake.primary_entity_type, v_intake.primary_entity_id,
    'OPEN','INTAKE', coalesce(v_intake.priority_code,'MEDIUM'),
    coalesce(v_intake.financial_exposure, v_intake.exposure_amount),
    p_intake_id, v_intake.source_module,
    current_date, now(), now(), p_actor
  ) RETURNING id INTO v_case_id;

  UPDATE public.lg_case_intake
     SET qualification_status = 'CONVERTED_TO_CASE',
         qualification_result = 'CONVERTED',
         lg_case_id = v_case_id,
         qualification_completed_at = now(),
         updated_at = now()
   WHERE id = p_intake_id;

  IF v_intake.legal_referral_id IS NOT NULL THEN
    UPDATE public.legal_referral
       SET status = 'LEGAL_CASE_CREATED', legal_case_id = v_case_id, last_status_at = now(), updated_at = now()
     WHERE id = v_intake.legal_referral_id;
  END IF;

  INSERT INTO public.lg_intake_decision_audit(intake_id, actor, action, new_value)
  VALUES (p_intake_id, p_actor, 'CONVERTED_TO_CASE', jsonb_build_object('case_id', v_case_id, 'case_no', v_case_no));

  RETURN v_case_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_fee_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.lg_flag_breached_orders()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_cnt integer := 0;
BEGIN
  UPDATE public.lg_order
     SET compliance_status = 'BREACHED', updated_at = now()
   WHERE compliance_date IS NOT NULL
     AND compliance_date < CURRENT_DATE
     AND compliance_status NOT IN ('COMPLIED','BREACHED')
     AND status NOT IN ('CLOSED','CANCELLED');
  GET DIAGNOSTICS v_cnt = ROW_COUNT;
  RETURN v_cnt;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_generate_case_no()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE seq_no BIGINT; yr TEXT;
BEGIN
  yr := to_char(now(), 'YYYY');
  SELECT COALESCE(MAX(NULLIF(regexp_replace(lg_case_no, '^LG-\d{4}-', ''), '')::BIGINT), 0) + 1
    INTO seq_no FROM public.lg_case WHERE lg_case_no LIKE 'LG-' || yr || '-%';
  RETURN 'LG-' || yr || '-' || lpad(seq_no::TEXT, 6, '0');
END; $function$;
CREATE OR REPLACE FUNCTION public.lg_hearing_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_next_date DATE;
  v_next_time TIME;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.lg_case_activity(lg_case_id, activity_type, description, payload, performed_by)
    VALUES (NEW.lg_case_id, 'HEARING_SCHEDULED',
            'Hearing scheduled on ' || COALESCE(NEW.hearing_date::text, NEW.scheduled_at::text),
            jsonb_build_object('hearing_id', NEW.id, 'hearing_type_code', NEW.hearing_type_code),
            NEW.created_by);
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.outcome_code IS DISTINCT FROM OLD.outcome_code OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.lg_case_activity(lg_case_id, activity_type, description, payload, performed_by)
    VALUES (NEW.lg_case_id, 'HEARING_UPDATED',
            'Hearing ' || COALESCE(NEW.status, '') || COALESCE(' / ' || NEW.outcome_code, ''),
            jsonb_build_object('hearing_id', NEW.id, 'outcome_code', NEW.outcome_code,
                               'next_hearing_date', NEW.next_hearing_date),
            NEW.created_by);
  END IF;

  -- Auto follow-up when this hearing has a recorded outcome AND a future date and we haven't already created one
  IF NEW.outcome_code IS NOT NULL
     AND NEW.next_hearing_date IS NOT NULL
     AND (OLD.outcome_code IS NULL OR OLD.next_hearing_date IS DISTINCT FROM NEW.next_hearing_date)
  THEN
    v_next_date := NEW.next_hearing_date;
    v_next_time := COALESCE(NEW.next_hearing_time, NEW.hearing_time, TIME '09:00');

    IF NOT EXISTS (
      SELECT 1 FROM public.lg_hearing h
       WHERE h.lg_case_id = NEW.lg_case_id
         AND h.status = 'SCHEDULED'
         AND COALESCE(h.hearing_date, (h.scheduled_at AT TIME ZONE 'UTC')::date) = v_next_date
    ) THEN
      INSERT INTO public.lg_hearing(
        lg_case_id, hearing_type_code, hearing_date, hearing_time,
        scheduled_at, court_name, court_room, location, status, created_by)
      VALUES (
        NEW.lg_case_id, COALESCE(NEW.hearing_type_code, 'MENTION'),
        v_next_date, v_next_time,
        (v_next_date::text || ' ' || v_next_time::text)::timestamptz,
        NEW.court_name, NEW.court_room, NEW.location, 'SCHEDULED', NEW.created_by);

      INSERT INTO public.lg_case_task(
        lg_case_id, task_type_code, title, description, due_date, status, priority_code, created_by)
      VALUES (
        NEW.lg_case_id, 'ATTEND_HEARING',
        'Attend hearing on ' || v_next_date::text,
        'Follow-up hearing scheduled after outcome ' || NEW.outcome_code,
        v_next_date, 'OPEN', 'HIGH', NEW.created_by);

      INSERT INTO public.lg_case_deadline(
        lg_case_id, deadline_type, due_date, description,
        status_code, reminder_required, reminder_days_json)
      VALUES (
        NEW.lg_case_id, 'HEARING', v_next_date,
        'Hearing on ' || v_next_date::text,
        'PENDING', TRUE, '[7,3,1]'::jsonb);
    END IF;
  END IF;

  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.lg_liab_recompute_paid(_liability_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE _paid NUMERIC(18,2);
BEGIN
  SELECT COALESCE(SUM(allocated_amount),0) INTO _paid
  FROM public.lg_payment_allocation WHERE liability_id = _liability_id;
  UPDATE public.lg_recoverable_liability
     SET paid = _paid,
         outstanding = GREATEST(total_assessed - _paid, 0),
         recovery_status = CASE
           WHEN total_assessed > 0 AND _paid >= total_assessed - 0.005 THEN 'RECOVERED'
           WHEN _paid > 0 THEN 'PARTIAL'
           ELSE recovery_status
         END,
         updated_at = now()
   WHERE id = _liability_id;
END $function$;
CREATE OR REPLACE FUNCTION public.lg_liab_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.principal < 0 OR NEW.interest < 0 OR NEW.penalty < 0
     OR NEW.court_cost < 0 OR NEW.legal_cost < 0 OR NEW.other_cost < 0
     OR NEW.paid < 0 THEN
    RAISE EXCEPTION 'Liability amounts cannot be negative';
  END IF;
  IF NEW.contribution_period_from IS NOT NULL
     AND NEW.contribution_period_to IS NOT NULL
     AND NEW.contribution_period_from > NEW.contribution_period_to THEN
    RAISE EXCEPTION 'contribution_period_from must be <= contribution_period_to';
  END IF;
  NEW.total_assessed := COALESCE(NEW.principal,0) + COALESCE(NEW.interest,0)
                      + COALESCE(NEW.penalty,0) + COALESCE(NEW.court_cost,0)
                      + COALESCE(NEW.legal_cost,0) + COALESCE(NEW.other_cost,0);
  NEW.outstanding    := GREATEST(NEW.total_assessed - COALESCE(NEW.paid,0), 0);
  IF NEW.paid > NEW.total_assessed + 0.005 THEN
    RAISE EXCEPTION 'paid (%) cannot exceed total_assessed (%)', NEW.paid, NEW.total_assessed;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.lg_list_unmapped_reference_values(p_table_name text, p_column_name text, p_group_code text, p_limit integer DEFAULT 200)
 RETURNS TABLE(stored_value text, occurrences bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sql text;
BEGIN
  IF p_table_name  !~ '^[a-z_][a-z0-9_]*$' THEN RAISE EXCEPTION 'invalid table name'; END IF;
  IF p_column_name !~ '^[a-z_][a-z0-9_]*$' THEN RAISE EXCEPTION 'invalid column name'; END IF;

  v_sql := format($f$
    WITH src AS (
      SELECT %I::text AS v FROM %I WHERE %I IS NOT NULL AND btrim(%I::text) <> ''
    )
    SELECT v AS stored_value, count(*) AS occurrences
    FROM src
    WHERE NOT public.lg_validate_reference(%L, v)
    GROUP BY v
    ORDER BY count(*) DESC, v ASC
    LIMIT %s
  $f$, p_column_name, p_table_name, p_column_name, p_column_name, p_group_code, p_limit);

  RETURN QUERY EXECUTE v_sql;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_pay_alloc_after_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.lg_liab_recompute_paid(COALESCE(NEW.liability_id, OLD.liability_id));
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.lg_pick_assignee(p_team_code text, p_strategy text DEFAULT 'LEAST_ACTIVE'::text, p_priority text DEFAULT 'MEDIUM'::text, p_required_skill text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_team_id uuid;
  v_user    uuid;
  v_code    varchar(50);
  v_reason  text;
  v_hi      boolean := p_priority IN ('HIGH','URGENT','CRITICAL');
BEGIN
  SELECT id INTO v_team_id FROM public.lg_team WHERE team_code = p_team_code AND is_active = true;
  IF v_team_id IS NULL THEN
    RETURN jsonb_build_object('assigned_to_user_id', NULL, 'reason', 'team_not_found');
  END IF;

  WITH eligible AS (
    SELECT w.*
      FROM public.lg_staff_workload w
      JOIN public.lg_staff s ON s.id = w.staff_id
     WHERE s.team_id = v_team_id
       AND s.is_active = true
       AND s.availability = 'available'
       AND w.active_cases       < w.max_active_cases
       AND (NOT v_hi OR w.high_priority_cases < w.max_high_priority_cases)
       AND (p_required_skill IS NULL OR p_required_skill = ANY(s.skills))
  )
  SELECT user_id, user_code
    INTO v_user, v_code
    FROM eligible
   ORDER BY
     CASE p_strategy
       WHEN 'LEAST_ACTIVE'    THEN active_cases
       WHEN 'PRIORITY_BASED'  THEN active_cases
       WHEN 'ROUND_ROBIN'     THEN extract(epoch from now())::int % GREATEST(1, (SELECT COUNT(*) FROM eligible))
       ELSE active_cases
     END ASC,
     capacity_pct ASC,
     random()
   LIMIT 1;

  IF v_user IS NULL THEN
    RETURN jsonb_build_object(
      'assigned_to_user_id', NULL,
      'assigned_user_code',  NULL,
      'team_id',             v_team_id,
      'reason',              'no_eligible_staff'
    );
  END IF;

  RETURN jsonb_build_object(
    'assigned_to_user_id', v_user,
    'assigned_user_code',  v_code,
    'team_id',             v_team_id,
    'reason',              'matched_' || lower(p_strategy)
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.lg_recompute_assignment_rollup(p_assignment uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_liab_count INT := 0;
  v_principal NUMERIC := 0;
  v_interest NUMERIC := 0;
  v_penalty NUMERIC := 0;
  v_assessed NUMERIC := 0;
  v_paid NUMERIC := 0;
  v_outstanding NUMERIC := 0;
  v_order_count INT := 0;
  v_appeal_count INT := 0;
  v_enforce_count INT := 0;
  v_recovery_pct NUMERIC := 0;
BEGIN
  SELECT COUNT(*),
         COALESCE(SUM(l.principal),0),
         COALESCE(SUM(l.interest),0),
         COALESCE(SUM(l.penalty),0),
         COALESCE(SUM(l.total_assessed),0),
         COALESCE(SUM(l.paid),0),
         COALESCE(SUM(l.outstanding),0)
  INTO v_liab_count, v_principal, v_interest, v_penalty, v_assessed, v_paid, v_outstanding
  FROM public.lg_recovery_assignment_liability j
  JOIN public.lg_recoverable_liability l ON l.id = j.liability_id
  WHERE j.assignment_id = p_assignment;

  SELECT COUNT(DISTINCT ol.order_id) INTO v_order_count
    FROM public.lg_recovery_assignment_liability j
    JOIN public.lg_order_liability ol ON ol.liability_id = j.liability_id
    WHERE j.assignment_id = p_assignment;

  SELECT COUNT(DISTINCT al.appeal_id) INTO v_appeal_count
    FROM public.lg_recovery_assignment_liability j
    JOIN public.lg_appeal_liability al ON al.liability_id = j.liability_id
    WHERE j.assignment_id = p_assignment;

  SELECT COUNT(DISTINCT el.enforcement_id) INTO v_enforce_count
    FROM public.lg_recovery_assignment_liability j
    JOIN public.lg_enforcement_liability el ON el.liability_id = j.liability_id
    WHERE j.assignment_id = p_assignment;

  IF v_assessed > 0 THEN
    v_recovery_pct := ROUND((v_paid / v_assessed) * 100, 2);
  END IF;

  UPDATE public.lg_recovery_assignment
     SET liability_count = v_liab_count,
         total_principal = v_principal,
         total_interest = v_interest,
         total_penalty = v_penalty,
         total_assessed = v_assessed,
         total_paid = v_paid,
         total_outstanding = v_outstanding,
         order_count = v_order_count,
         appeal_count = v_appeal_count,
         enforcement_count = v_enforce_count,
         recovery_pct = v_recovery_pct,
         updated_at = now()
   WHERE id = p_assignment;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_recompute_order_compliance(_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case          uuid;
  v_ordered       numeric;
  v_paid          numeric;
  v_outstanding   numeric;
  v_due           date;
  v_new_status    varchar(30);
BEGIN
  SELECT lg_case_id, COALESCE(ordered_amount,0), compliance_date
    INTO v_case, v_ordered, v_due
    FROM public.lg_order WHERE id = _order_id;

  -- Sum paid & outstanding from linked liabilities
  SELECT COALESCE(SUM(l.paid),0), COALESCE(SUM(l.outstanding),0)
    INTO v_paid, v_outstanding
    FROM public.lg_order_liability ol
    JOIN public.lg_recoverable_liability l ON l.id = ol.liability_id
    WHERE ol.order_id = _order_id;

  IF v_paid = 0 AND NOT EXISTS (SELECT 1 FROM public.lg_order_compliance_event WHERE order_id = _order_id) THEN
    v_new_status := 'NOT_STARTED';
  ELSIF v_outstanding = 0 AND v_paid > 0 THEN
    v_new_status := 'COMPLIED';
  ELSIF v_paid > 0 AND v_outstanding > 0 THEN
    v_new_status := 'PARTIALLY_COMPLIED';
  ELSE
    v_new_status := 'IN_PROGRESS';
  END IF;

  -- Breach: past due date and not fully complied
  IF v_due IS NOT NULL AND v_due < CURRENT_DATE AND v_new_status <> 'COMPLIED' THEN
    v_new_status := 'BREACHED';
  END IF;

  UPDATE public.lg_order SET compliance_status = v_new_status, updated_at = now() WHERE id = _order_id;
END;
$function$;
