CREATE OR REPLACE FUNCTION public.lg_sync_case_next_hearing()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_case UUID; v_next DATE;
BEGIN
  v_case := COALESCE(NEW.lg_case_id, OLD.lg_case_id);
  SELECT MIN(COALESCE(hearing_date, (scheduled_at AT TIME ZONE 'UTC')::date))
    INTO v_next
    FROM public.lg_hearing
   WHERE lg_case_id = v_case
     AND status = 'SCHEDULED'
     AND COALESCE(hearing_date, (scheduled_at AT TIME ZONE 'UTC')::date) >= CURRENT_DATE;
  UPDATE public.lg_case SET next_hearing_date = v_next WHERE id = v_case;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.lg_task_audit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action TEXT;
  v_actor  TEXT;
  v_from   JSONB;
  v_to     JSONB;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATED';
    v_actor  := NEW.created_by;
    v_to     := jsonb_build_object(
      'status', NEW.status, 'priority_code', NEW.priority_code,
      'assigned_to_user_id', NEW.assigned_to_user_id,
      'assigned_team_code', NEW.assigned_team_code,
      'due_date', NEW.due_date
    );
    INSERT INTO public.lg_case_task_audit(task_id, lg_case_id, action, to_value, performed_by)
    VALUES (NEW.id, NEW.lg_case_id, v_action, v_to, v_actor);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Skip trivial updates (only updated_at / sla_status recompute)
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NEW.status IN ('COMPLETED','DONE') THEN v_action := 'COMPLETED';
      ELSIF NEW.status IN ('CLOSED') THEN v_action := 'CLOSED';
      ELSIF NEW.status = 'CANCELLED' THEN v_action := 'CANCELLED';
      ELSIF NEW.status IN ('OPEN','IN_PROGRESS') AND OLD.status IN ('COMPLETED','DONE','CLOSED','CANCELLED') THEN v_action := 'REOPENED';
      ELSE v_action := 'STATUS_CHANGED';
      END IF;
      v_actor := COALESCE(NEW.completed_by, NEW.closed_by, NEW.escalated_by, NEW.created_by);
      INSERT INTO public.lg_case_task_audit(task_id, lg_case_id, action, from_value, to_value, performed_by)
      VALUES (NEW.id, NEW.lg_case_id, v_action,
              jsonb_build_object('status', OLD.status),
              jsonb_build_object('status', NEW.status),
              v_actor);
    END IF;

    IF NEW.assigned_to_user_id IS DISTINCT FROM OLD.assigned_to_user_id
       OR NEW.assigned_team_code IS DISTINCT FROM OLD.assigned_team_code THEN
      INSERT INTO public.lg_case_task_audit(task_id, lg_case_id, action, from_value, to_value, performed_by)
      VALUES (NEW.id, NEW.lg_case_id, 'ASSIGNED',
              jsonb_build_object('assigned_to_user_id', OLD.assigned_to_user_id, 'assigned_team_code', OLD.assigned_team_code),
              jsonb_build_object('assigned_to_user_id', NEW.assigned_to_user_id, 'assigned_team_code', NEW.assigned_team_code),
              COALESCE(NEW.created_by, NEW.escalated_by));
    END IF;

    IF NEW.escalation_level IS DISTINCT FROM OLD.escalation_level
       AND COALESCE(NEW.escalation_level,0) > COALESCE(OLD.escalation_level,0) THEN
      INSERT INTO public.lg_case_task_audit(task_id, lg_case_id, action, from_value, to_value, note, performed_by)
      VALUES (NEW.id, NEW.lg_case_id, 'ESCALATED',
              jsonb_build_object('escalation_level', OLD.escalation_level),
              jsonb_build_object('escalation_level', NEW.escalation_level),
              NEW.escalation_reason,
              NEW.escalated_by);
    END IF;

    IF NEW.due_date IS DISTINCT FROM OLD.due_date
       OR NEW.priority_code IS DISTINCT FROM OLD.priority_code
       OR NEW.title IS DISTINCT FROM OLD.title
       OR NEW.description IS DISTINCT FROM OLD.description THEN
      INSERT INTO public.lg_case_task_audit(task_id, lg_case_id, action, from_value, to_value, performed_by)
      VALUES (NEW.id, NEW.lg_case_id, 'UPDATED',
              jsonb_build_object('due_date', OLD.due_date, 'priority_code', OLD.priority_code, 'title', OLD.title),
              jsonb_build_object('due_date', NEW.due_date, 'priority_code', NEW.priority_code, 'title', NEW.title),
              COALESCE(NEW.created_by, NEW.escalated_by));
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_task_compute_sla(p_status text, p_due_date date, p_escalation_level smallint, p_at_risk_hours integer)
 RETURNS character varying
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p_status IN ('COMPLETED','DONE','CLOSED','CANCELLED') THEN
    RETURN 'CLOSED';
  END IF;
  IF COALESCE(p_escalation_level,0) > 0 THEN
    RETURN 'ESCALATED';
  END IF;
  IF p_due_date IS NULL THEN
    RETURN 'ON_TIME';
  END IF;
  IF p_due_date < CURRENT_DATE THEN
    RETURN 'OVERDUE';
  END IF;
  IF (p_due_date - CURRENT_DATE) * 24 <= COALESCE(p_at_risk_hours, 24) THEN
    RETURN 'AT_RISK';
  END IF;
  RETURN 'ON_TIME';
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_task_set_sla_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.sla_status := public.lg_task_compute_sla(
    NEW.status, NEW.due_date, NEW.escalation_level, NEW.at_risk_hours
  );
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_template_completeness(p_module_code text DEFAULT 'LEGAL'::text, p_country text DEFAULT 'KN'::text)
 RETURNS TABLE(template_id uuid, code text, name text, status text, has_subject boolean, has_body boolean, has_structure boolean, has_legal_refs boolean, has_signature boolean, has_footer boolean, channel_count integer, completion_pct integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT t.id AS template_id, t.code, t.name, t.status,
  (v.subject IS NOT NULL AND length(v.subject) > 0) AS has_subject,
  (v.body_html IS NOT NULL AND length(v.body_html) > 200) AS has_body,
  (v.template_structure IS NOT NULL AND jsonb_array_length(v.template_structure) > 0) AS has_structure,
  EXISTS(SELECT 1 FROM core_template_legal_reference lr WHERE lr.template_id = t.id) AS has_legal_refs,
  (v.body_html ILIKE '%signature%' OR v.body_html ILIKE '%Yours faithfully%') AS has_signature,
  (v.body_html ILIKE '%footer%' OR v.body_html ILIKE '%official communication%') AS has_footer,
  COALESCE((SELECT count(*)::int FROM core_template_channel_variant cv WHERE cv.template_version_id = v.id AND cv.is_active),0) AS channel_count,
  (
    (CASE WHEN v.subject IS NOT NULL AND length(v.subject)>0 THEN 1 ELSE 0 END) +
    (CASE WHEN v.body_html IS NOT NULL AND length(v.body_html)>200 THEN 1 ELSE 0 END) +
    (CASE WHEN v.template_structure IS NOT NULL AND jsonb_array_length(v.template_structure)>0 THEN 1 ELSE 0 END) +
    (CASE WHEN EXISTS(SELECT 1 FROM core_template_legal_reference lr WHERE lr.template_id = t.id) THEN 1 ELSE 0 END) +
    (CASE WHEN v.body_html ILIKE '%Yours faithfully%' THEN 1 ELSE 0 END) +
    (CASE WHEN v.body_html ILIKE '%official communication%' THEN 1 ELSE 0 END) +
    (CASE WHEN COALESCE((SELECT count(*) FROM core_template_channel_variant cv WHERE cv.template_version_id = v.id AND cv.is_active),0) >= 5 THEN 4 ELSE 0 END)
  ) * 10 AS completion_pct
FROM public.core_template t
LEFT JOIN public.core_template_version v ON v.id = t.active_version_id
WHERE t.module_code = p_module_code
  AND t.country_code = p_country
  AND t.scope = 'COUNTRY'
ORDER BY t.code;
$function$;
CREATE OR REPLACE FUNCTION public.lg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.lg_validate_reference(p_group_code text, p_value_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_group_id uuid;
  v_exists boolean;
BEGIN
  IF p_value_code IS NULL OR btrim(p_value_code) = '' THEN
    RETURN TRUE;
  END IF;

  SELECT id INTO v_group_id
  FROM core_reference_group
  WHERE group_code = p_group_code
    AND (module_code = 'LEGAL' OR module_code = 'COMMON')
  ORDER BY CASE WHEN module_code = 'LEGAL' THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_group_id IS NULL THEN
    RETURN TRUE;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM core_reference_value
    WHERE group_id = v_group_id
      AND value_code = p_value_code
  ) INTO v_exists;

  RETURN v_exists;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lg_validate_stage_transition(p_case_id uuid, p_target_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case RECORD;
  v_rule RECORD;
  v_missing_tpls TEXT[] := '{}';
  v_missing_docs TEXT[] := '{}';
  v_missing_refs TEXT[] := '{}';
  v_severity TEXT := 'WARN';
  v_blocked BOOLEAN := false;
BEGIN
  SELECT * INTO v_case FROM public.lg_case WHERE id = p_case_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'case_not_found');
  END IF;

  SELECT * INTO v_rule FROM public.lg_stage_transition_rule
    WHERE country_code = 'KN' AND case_type_code IN ('ANY', COALESCE(v_case.case_type_code,'ANY'))
      AND from_stage_code = COALESCE(v_case.stage_code, 'ANY')
      AND to_stage_code = p_target_stage AND is_active
    ORDER BY (case_type_code='ANY') ASC LIMIT 1;

  IF FOUND THEN v_severity := v_rule.rule_severity; END IF;

  -- Required templates not yet generated at current stage
  SELECT COALESCE(array_agg(ct.code), '{}') INTO v_missing_tpls
  FROM public.lg_stage_template_mapping m
  JOIN public.core_template ct ON ct.id = m.template_id
  WHERE m.country_code='KN' AND m.is_active AND m.is_required
    AND m.stage_code = COALESCE(v_case.stage_code,'')
    AND m.case_type_code IN ('ANY', COALESCE(v_case.case_type_code,'ANY'))
    AND NOT EXISTS (
      SELECT 1 FROM public.core_generated_document g
      WHERE g.entity_type='lg_case' AND g.entity_id = p_case_id
        AND g.template_id = m.template_id
        AND g.case_stage_code = v_case.stage_code
    );

  -- Required documents not linked
  SELECT COALESCE(array_agg(d.doc_type_code), '{}') INTO v_missing_docs
  FROM public.lg_stage_document_rule d
  WHERE d.country_code='KN' AND d.is_active AND d.is_required
    AND d.stage_code = COALESCE(v_case.stage_code,'')
    AND d.case_type_code IN ('ANY', COALESCE(v_case.case_type_code,'ANY'))
    AND NOT EXISTS (
      SELECT 1 FROM public.lg_document_link l
      WHERE l.case_id = p_case_id AND l.doc_type_code = d.doc_type_code
    );

  -- Required references missing for current stage
  SELECT COALESCE(array_agg(r.legal_reference_id::text), '{}') INTO v_missing_refs
  FROM public.lg_stage_reference_mapping r
  WHERE r.country_code='KN' AND r.is_active AND r.is_required
    AND r.stage_code = COALESCE(v_case.stage_code,'')
    AND r.case_type_code IN ('ANY', COALESCE(v_case.case_type_code,'ANY'));

  v_blocked := v_severity = 'BLOCK' AND (
    (COALESCE(v_rule.require_all_required_templates, true) AND array_length(v_missing_tpls,1) IS NOT NULL) OR
    (COALESCE(v_rule.require_all_required_documents, true) AND array_length(v_missing_docs,1) IS NOT NULL) OR
    (COALESCE(v_rule.require_all_required_references, false) AND array_length(v_missing_refs,1) IS NOT NULL)
  );

  RETURN jsonb_build_object(
    'ok', NOT v_blocked,
    'severity', v_severity,
    'from_stage', v_case.stage_code,
    'to_stage', p_target_stage,
    'missing_templates', to_jsonb(v_missing_tpls),
    'missing_documents', to_jsonb(v_missing_docs),
    'missing_references', to_jsonb(v_missing_refs)
  );
END $function$;
CREATE OR REPLACE FUNCTION public.link_comm_hub_trace_message(p_trace_id uuid, p_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.communication_hub_trace
     SET message_id = COALESCE(message_id, p_message_id), updated_at = now()
   WHERE id = p_trace_id;
  RETURN jsonb_build_object('ok', true);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END; $function$;
CREATE OR REPLACE FUNCTION public.link_comm_hub_trace_request(p_trace_id uuid, p_request_id uuid, p_request_no text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.communication_hub_trace
     SET request_id = COALESCE(request_id, p_request_id),
         request_no = COALESCE(request_no, p_request_no),
         updated_at = now()
   WHERE id = p_trace_id;
  RETURN jsonb_build_object('ok', true);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END; $function$;
CREATE OR REPLACE FUNCTION public.list_comm_hub_approved_recipients(p_module_code text, p_event_code text, p_channel text)
 RETURNS TABLE(email text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT lower(email) AS email FROM (
    SELECT p.single_configured_address AS email
      FROM public.communication_hub_recipient_policy p
     WHERE p.singleton_guard='primary' AND p.single_configured_address IS NOT NULL
    UNION ALL
    SELECT jsonb_array_elements_text(coalesce(p.approved_named_addresses,'[]'::jsonb))
      FROM public.communication_hub_recipient_policy p
     WHERE p.singleton_guard='primary'
  ) s WHERE email IS NOT NULL AND length(email) > 0
$function$;
CREATE OR REPLACE FUNCTION public.list_comm_hub_revalidation_cycles(p_module_code text DEFAULT NULL::text, p_event_code text DEFAULT NULL::text, p_channel text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS SETOF communication_hub_revalidation_cycle
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._chrc_require_admin();
  RETURN QUERY SELECT * FROM public.communication_hub_revalidation_cycle
   WHERE (p_module_code IS NULL OR module_code = p_module_code)
     AND (p_event_code IS NULL OR event_code = p_event_code)
     AND (p_channel IS NULL OR channel = p_channel)
   ORDER BY started_at DESC LIMIT p_limit;
END $function$;
CREATE OR REPLACE FUNCTION public.list_comm_hub_transition_log(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_correlation_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, action text, allowed boolean, actor_id uuid, module_code text, event_code text, channel text, correlation_id uuid, denied_reasons jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'Admin'::app_role) THEN
    RAISE EXCEPTION 'admin_required';
  END IF;
  RETURN QUERY
    SELECT l.id, l.action, l.allowed, l.actor_id,
           l.module_code, l.event_code, l.channel,
           l.correlation_id, l.denied_reasons, l.created_at
      FROM public.comm_hub_runtime_transition_log l
     WHERE (p_correlation_id IS NULL OR l.correlation_id = p_correlation_id)
     ORDER BY l.created_at DESC
     LIMIT GREATEST(1, LEAST(p_limit, 500)) OFFSET GREATEST(0, p_offset);
END; $function$;
CREATE OR REPLACE FUNCTION public.log_audit_event(_action_type text, _module_name text DEFAULT NULL::text, _entity_type text DEFAULT NULL::text, _entity_id text DEFAULT NULL::text, _field_name text DEFAULT NULL::text, _old_value text DEFAULT NULL::text, _new_value text DEFAULT NULL::text, _metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _audit_id UUID; _user_email TEXT; _user_name TEXT;
BEGIN
  SELECT email, full_name INTO _user_email, _user_name FROM profiles WHERE id = auth.uid();
  INSERT INTO audit_logs (user_id, user_email, user_name, action_type, module_name, entity_type, entity_id, field_name, old_value, new_value, metadata)
  VALUES (auth.uid(), _user_email, _user_name, _action_type, _module_name, _entity_type, _entity_id, _field_name, _old_value, _new_value, _metadata)
  RETURNING id INTO _audit_id;
  RETURN _audit_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_c3_config_change(p_config_type character varying, p_record_id uuid, p_action character varying, p_entity_name character varying, p_field_name character varying DEFAULT NULL::character varying, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_changed_by character varying DEFAULT NULL::character varying, p_changed_by_name character varying DEFAULT NULL::character varying, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log_id UUID;
BEGIN
  INSERT INTO public.c3_unified_audit_log (
    config_type,
    record_id,
    action,
    entity_name,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_by_name,
    reason,
    metadata
  ) VALUES (
    p_config_type,
    p_record_id,
    p_action,
    p_entity_name,
    p_field_name,
    p_old_value,
    p_new_value,
    p_changed_by,
    p_changed_by_name,
    p_reason,
    p_metadata
  )
  RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_c3_config_change(p_config_type text, p_record_id text, p_action text, p_entity_name text, p_field_name text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_changed_by text DEFAULT NULL::text, p_changed_by_name text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_metadata text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log_id UUID;
  v_changed_by TEXT;
  v_changed_by_name TEXT;
  v_auth_uid UUID;
BEGIN
  v_changed_by := p_changed_by;
  v_changed_by_name := p_changed_by_name;
  
  -- Auto-detect user from auth context if not provided
  IF v_changed_by IS NULL OR v_changed_by = '' THEN
    v_auth_uid := auth.uid();
    IF v_auth_uid IS NOT NULL THEN
      SELECT user_code, full_name INTO v_changed_by, v_changed_by_name
      FROM public.profiles
      WHERE id = v_auth_uid;
    END IF;
  END IF;
  
  -- If changed_by_name still null but changed_by exists, try to look it up
  IF v_changed_by_name IS NULL AND v_changed_by IS NOT NULL THEN
    SELECT full_name INTO v_changed_by_name
    FROM public.profiles
    WHERE user_code = v_changed_by
    LIMIT 1;
  END IF;

  INSERT INTO public.c3_unified_audit_log (
    config_type,
    record_id,
    action,
    entity_name,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_by_name,
    reason,
    metadata
  ) VALUES (
    p_config_type,
    p_record_id,
    p_action,
    p_entity_name,
    p_field_name,
    p_old_value,
    p_new_value,
    v_changed_by,
    v_changed_by_name,
    p_reason,
    p_metadata
  )
  RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_document_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO legal_timeline_events (case_id, type, actor_id, actor_name, description)
    VALUES (
      NEW.case_id,
      'Document',
      NEW.uploaded_by,
      (SELECT full_name FROM profiles WHERE id = NEW.uploaded_by),
      'Uploaded document: ' || NEW.name || ' (' || NEW.type || ')'
    );
  ELSIF TG_OP = 'UPDATE' AND NEW.version > OLD.version THEN
    INSERT INTO legal_timeline_events (case_id, type, actor_id, actor_name, description)
    VALUES (
      NEW.case_id,
      'Document',
      auth.uid(),
      (SELECT full_name FROM profiles WHERE id = auth.uid()),
      'New version of document: ' || NEW.name || ' (v' || NEW.version || ')'
    );
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_workflow_security_event(_workflow_instance_id uuid, _user_id uuid, _action text, _record_id uuid DEFAULT NULL::uuid, _fields_viewed text[] DEFAULT NULL::text[], _fields_edited text[] DEFAULT NULL::text[], _rules_applied jsonb DEFAULT NULL::jsonb, _access_granted boolean DEFAULT true, _denial_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log_id uuid;
  v_workflow workflow_instances;
  v_user profiles;
BEGIN
  SELECT * INTO v_workflow FROM workflow_instances WHERE id = _workflow_instance_id;
  SELECT * INTO v_user FROM profiles WHERE id = _user_id;
  
  INSERT INTO workflow_security_audit_log (
    workflow_instance_id,
    workflow_definition_id,
    user_id,
    user_name,
    action,
    record_id,
    record_table,
    fields_viewed,
    fields_edited,
    rules_applied,
    access_granted,
    denial_reason
  ) VALUES (
    _workflow_instance_id,
    v_workflow.workflow_id,
    _user_id,
    v_user.full_name,
    _action,
    COALESCE(_record_id, v_workflow.source_record_id::uuid),
    (SELECT secured_table FROM workflow_definitions WHERE id = v_workflow.workflow_id),
    _fields_viewed,
    _fields_edited,
    _rules_applied,
    _access_granted,
    _denial_reason
  ) RETURNING id INTO v_log_id;
  
  RETURN v_log_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lr_request_info_atomic(p_legal_referral_id uuid, p_requested_by text, p_requested_to_module text, p_request_reason text, p_requested_items jsonb DEFAULT '[]'::jsonb, p_requested_to_workbasket text DEFAULT NULL::text, p_requested_to_team text DEFAULT NULL::text, p_requested_to_user text DEFAULT NULL::text, p_request_type text DEFAULT 'INFO_REQUEST'::text, p_due_date_override date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referral public.legal_referral;
  v_rule     public.legal_referral_sla_rule;
  v_request_no text;
  v_request_id uuid;
  v_task_id    uuid;
  v_due_date   date;
  v_reminder_at timestamptz;
  v_escalation_at timestamptz;
BEGIN
  SELECT * INTO v_referral FROM public.legal_referral WHERE id = p_legal_referral_id FOR UPDATE;
  IF v_referral.id IS NULL THEN
    RAISE EXCEPTION 'Legal referral % not found', p_legal_referral_id;
  END IF;

  v_rule := public.legal_resolve_sla_rule(p_requested_to_module, p_request_type);

  IF p_due_date_override IS NOT NULL THEN
    v_due_date := p_due_date_override;
  ELSIF v_rule.id IS NOT NULL THEN
    v_due_date := (now()::date + (v_rule.default_due_days || ' days')::interval)::date;
  ELSE
    v_due_date := (now()::date + INTERVAL '5 days')::date;
  END IF;

  IF v_rule.id IS NOT NULL THEN
    v_reminder_at   := (v_due_date::timestamptz - (v_rule.reminder_before_days || ' days')::interval);
    v_escalation_at := (v_due_date::timestamptz + (v_rule.escalation_after_days || ' days')::interval);
  END IF;

  v_request_no := 'IR-' || to_char(now(),'YYYYMMDD') || '-' || lpad(floor(random()*100000)::text,5,'0');

  INSERT INTO public.legal_referral_info_request(
    legal_referral_id, request_no, requested_by, requested_to_module,
    requested_to_workbasket_code, requested_to_team_code, requested_to_user,
    request_reason, requested_items, due_date, status,
    request_type, sla_rule_id, reminder_at, escalation_at, sla_status
  ) VALUES (
    p_legal_referral_id, v_request_no, p_requested_by, p_requested_to_module,
    p_requested_to_workbasket, p_requested_to_team, p_requested_to_user,
    p_request_reason, COALESCE(p_requested_items,'[]'::jsonb), v_due_date, 'PENDING_SOURCE_RESPONSE',
    p_request_type, v_rule.id, v_reminder_at, v_escalation_at, 'ON_TIME'
  ) RETURNING id INTO v_request_id;

  -- Source task
  INSERT INTO public.legal_referral_source_task(
    legal_referral_id, info_request_id, task_type, source_module,
    assigned_workbasket_code, assigned_team_code, assigned_user,
    due_date, status
  ) VALUES (
    p_legal_referral_id, v_request_id, 'LEGAL_INFO_REQUEST', p_requested_to_module,
    p_requested_to_workbasket, p_requested_to_team, p_requested_to_user,
    v_due_date, 'OPEN'
  ) RETURNING id INTO v_task_id;

  -- Referral status
  UPDATE public.legal_referral
     SET status = 'INFO_REQUESTED', last_status_at = now(), updated_at = now()
   WHERE id = p_legal_referral_id;

  -- Audit
  INSERT INTO public.legal_referral_audit(legal_referral_id, info_request_id, event_type, actor, payload)
  VALUES (p_legal_referral_id, v_request_id, 'INFO_REQUESTED', p_requested_by,
          jsonb_build_object('request_no', v_request_no, 'due_date', v_due_date, 'task_id', v_task_id));

  -- Notification (best effort)
  BEGIN
    INSERT INTO public.in_app_notifications(user_id, title, message, type, link, metadata)
    VALUES (
      p_requested_to_user,
      'New Legal Information Request',
      'Legal has requested information for referral ' || v_referral.referral_no,
      'LEGAL_INFO_REQUEST',
      '/legal/referrals-workbench?tab=info-requested&id=' || v_request_id::text,
      jsonb_build_object('referral_id', p_legal_referral_id, 'request_id', v_request_id, 'due_date', v_due_date)
    );
  EXCEPTION WHEN OTHERS THEN
    -- non-blocking
    NULL;
  END;

  RETURN jsonb_build_object(
    'info_request_id', v_request_id,
    'source_task_id',  v_task_id,
    'request_no',      v_request_no,
    'due_date',        v_due_date,
    'sla_rule_id',     v_rule.id
  );
END $function$;
CREATE OR REPLACE FUNCTION public.mark_comm_hub_certifications_possibly_stale(p_entity_type text, p_entity_id uuid, p_category text DEFAULT 'DEPENDENCY_CHANGED'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer := 0; v_cert_id uuid;
BEGIN
  FOR v_cert_id IN
    SELECT c.id FROM public.comm_hub_certification c
     WHERE c.entity_type::text = p_entity_type AND c.entity_id = p_entity_id AND c.superseded_by IS NULL
  LOOP
    INSERT INTO public.comm_hub_certification_freshness(
      certification_id, freshness_status, certified_dependency_hash,
      changed_dependency_categories, stale_reason_codes,
      last_evaluated_source, stale_detected_at, updated_at)
    SELECT v_cert_id, 'POSSIBLY_STALE', c.dependency_hash,
           ARRAY[p_category], ARRAY[p_category], 'trigger_invalidation', now(), now()
      FROM public.comm_hub_certification c WHERE c.id = v_cert_id
    ON CONFLICT (certification_id) DO UPDATE
      SET freshness_status = CASE WHEN public.comm_hub_certification_freshness.freshness_status='CURRENT'
                                  THEN 'POSSIBLY_STALE'
                                  ELSE public.comm_hub_certification_freshness.freshness_status END,
          changed_dependency_categories =
            (SELECT array_agg(DISTINCT c) FROM unnest(public.comm_hub_certification_freshness.changed_dependency_categories || ARRAY[p_category]) c),
          stale_reason_codes =
            (SELECT array_agg(DISTINCT c) FROM unnest(public.comm_hub_certification_freshness.stale_reason_codes || ARRAY[p_category]) c),
          stale_detected_at = COALESCE(public.comm_hub_certification_freshness.stale_detected_at, now()),
          updated_at = now();
    v_count := v_count + 1;
  END LOOP;

  IF p_entity_type IN ('CORE_TEMPLATE','CORE_TEMPLATE_SECTION','CORE_TEMPLATE_LAYOUT',
                       'EVENT_TEMPLATE_MAP','EVENT_PAYLOAD_SCHEMA','EVENT_PAYLOAD_FIELD',
                       'EVENT_TEST_SCENARIO','SENDER_PROFILE','EVENT_SEND_POLICY',
                       'EVENT_REVIEW_POLICY','TEMPLATE_VARIABLE_CONTRACT','SENDER_READINESS') THEN
    FOR v_cert_id IN
      SELECT c.id FROM public.comm_hub_certification c
       WHERE c.entity_type = 'TEMPLATE_VERSION' AND c.superseded_by IS NULL
         AND (
           c.dependency_manifest #>> '{dependencies,template_id}' = p_entity_id::text
           OR c.dependency_manifest #>> '{dependencies,layout_id}' = p_entity_id::text
           OR c.dependency_manifest #>> '{dependencies,event_mapping,id}' = p_entity_id::text
           OR c.dependency_manifest #>> '{dependencies,event_mapping,sender_profile_id}' = p_entity_id::text
           OR c.dependency_manifest -> 'dependencies' -> 'sections' @> jsonb_build_array(jsonb_build_object('id', p_entity_id))
           OR c.dependency_manifest -> 'dependencies' -> 'variable_bindings' @> jsonb_build_array(jsonb_build_object('id', p_entity_id))
         )
    LOOP
      INSERT INTO public.comm_hub_certification_freshness(
        certification_id, freshness_status, certified_dependency_hash,
        changed_dependency_categories, stale_reason_codes,
        last_evaluated_source, stale_detected_at, updated_at)
      SELECT v_cert_id, 'POSSIBLY_STALE', c.dependency_hash,
             ARRAY[p_category], ARRAY[p_category], 'trigger_invalidation', now(), now()
        FROM public.comm_hub_certification c WHERE c.id = v_cert_id
      ON CONFLICT (certification_id) DO UPDATE
        SET freshness_status = CASE WHEN public.comm_hub_certification_freshness.freshness_status='CURRENT'
                                    THEN 'POSSIBLY_STALE'
                                    ELSE public.comm_hub_certification_freshness.freshness_status END,
            changed_dependency_categories =
              (SELECT array_agg(DISTINCT c) FROM unnest(public.comm_hub_certification_freshness.changed_dependency_categories || ARRAY[p_category]) c),
            stale_reason_codes =
              (SELECT array_agg(DISTINCT c) FROM unnest(public.comm_hub_certification_freshness.stale_reason_codes || ARRAY[p_category]) c),
            stale_detected_at = COALESCE(public.comm_hub_certification_freshness.stale_detected_at, now()),
            updated_at = now();
      v_count := v_count + 1;
    END LOOP;
  END IF;
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.mark_comm_hub_dry_run_dispatching(p_execution_id uuid, p_requested_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_exec public.communication_dry_run_execution%ROWTYPE;
BEGIN
  SELECT * INTO v_exec FROM public.communication_dry_run_execution WHERE id = p_execution_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','execution_not_found'); END IF;
  IF v_exec.requested_by <> p_requested_by THEN
    RETURN jsonb_build_object('ok',false,'code','execution_operator_mismatch');
  END IF;
  IF v_exec.state = 'DISPATCHING' THEN RETURN jsonb_build_object('ok',true,'code','already_dispatching'); END IF;
  IF v_exec.state <> 'REQUEST_CREATED' THEN
    RETURN jsonb_build_object('ok',false,'code','invalid_state','state',v_exec.state);
  END IF;
  UPDATE public.communication_dry_run_execution SET state='DISPATCHING' WHERE id = p_execution_id;
  RETURN jsonb_build_object('ok',true);
END; $function$;
CREATE OR REPLACE FUNCTION public.mark_comm_hub_revalidation_cycle_supplemental(p_cycle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := public._chrc_require_admin(); v_cycle record;
BEGIN
  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle
    WHERE id = p_cycle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'cycle_not_found'; END IF;
  IF v_cycle.status <> 'CONFIRMED' THEN RAISE EXCEPTION 'cycle_not_confirmed'; END IF;
  IF v_cycle.inbox_confirmation_status <> 'CONFIRMED' THEN RAISE EXCEPTION 'inbox_not_confirmed'; END IF;

  UPDATE public.communication_hub_revalidation_cycle
     SET status = 'VERIFIED_SUPPLEMENTAL', promotion_status = 'SUPPLEMENTAL'
   WHERE id = p_cycle_id;
  RETURN jsonb_build_object('ok',true);
END $function$;
CREATE OR REPLACE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.next_info_request_no()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE n BIGINT;
BEGIN
  SELECT COUNT(*) + 1 INTO n FROM public.legal_referral_info_request
    WHERE created_at >= date_trunc('year', now());
  RETURN 'LIR-' || to_char(now(), 'YYYY') || '-' || lpad(n::text, 6, '0');
END $function$;
CREATE OR REPLACE FUNCTION public.next_reference_number(p_module_code character varying, p_department_code character varying, p_document_type character varying, p_financial_year integer DEFAULT NULL::integer)
 RETURNS TABLE(reference_number text, sequence_id uuid, current_number bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fy integer := COALESCE(p_financial_year, EXTRACT(YEAR FROM now())::int);
  v_row public.system_reference_sequence%ROWTYPE;
  v_seq text;
  v_ref text;
BEGIN
  UPDATE public.system_reference_sequence s
     SET current_number = s.current_number + 1,
         updated_at = now()
   WHERE s.module_code = p_module_code
     AND s.department_code = p_department_code
     AND s.document_type = p_document_type
     AND s.financial_year = v_fy
     AND s.active = true
  RETURNING s.* INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No active reference sequence configured for %/%/% (FY %)',
      p_module_code, p_department_code, p_document_type, v_fy;
  END IF;

  v_seq := lpad(v_row.current_number::text, COALESCE(v_row.padding, 6), '0');
  v_ref := COALESCE(v_row.prefix_pattern, '{MODULE}/{DOC_TYPE}/{YYYY}/{SEQ}');
  v_ref := replace(v_ref, '{MODULE}', p_module_code);
  v_ref := replace(v_ref, '{DEPT}', p_department_code);
  v_ref := replace(v_ref, '{DOC_TYPE}', p_document_type);
  v_ref := replace(v_ref, '{YYYY}', v_fy::text);
  v_ref := replace(v_ref, '{SEQ}', v_seq);

  reference_number := v_ref;
  sequence_id := v_row.id;
  current_number := v_row.current_number;
  RETURN NEXT;
END;
$function$;
CREATE OR REPLACE FUNCTION public.normalize_comm_hub_go_live_stage(p_stage text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v text := upper(coalesce(trim(p_stage),''));
BEGIN
  IF v = '' THEN RAISE EXCEPTION 'GO_LIVE_STAGE_UNSUPPORTED: empty stage'; END IF;
  RETURN CASE v
    WHEN 'READINESS_ONLY'             THEN 'READINESS_ONLY'
    WHEN 'PREVIEW'                    THEN 'PREVIEW_READY'
    WHEN 'PREVIEW_TEST'               THEN 'PREVIEW_READY'
    WHEN 'PREVIEW_READY'              THEN 'PREVIEW_READY'
    WHEN 'APPROVAL'                   THEN 'APPROVAL_READY'
    WHEN 'PREVIEW_APPROVAL'           THEN 'APPROVAL_READY'
    WHEN 'APPROVAL_READY'             THEN 'APPROVAL_READY'
    WHEN 'DRY_RUN'                    THEN 'DRY_RUN_READY'
    WHEN 'DRY_RUN_TEST'               THEN 'DRY_RUN_READY'
    WHEN 'DRY_RUN_READY'              THEN 'DRY_RUN_READY'
    WHEN 'CONTROLLED_STUB'            THEN 'CONTROLLED_STUB_READY'
    WHEN 'CONTROLLED_STUB_READY'      THEN 'CONTROLLED_STUB_READY'
    WHEN 'ONE_REAL_EMAIL'             THEN 'ONE_REAL_EMAIL_READY'
    WHEN 'ONE_REAL_EMAIL_READY'       THEN 'ONE_REAL_EMAIL_READY'
    -- CONTROLLED_LIVE intentionally omitted; use normalize_comm_hub_go_live_stage_for_action.
    WHEN 'MANUAL_PRODUCTION'          THEN 'MANUAL_PRODUCTION_READY'
    WHEN 'MANUAL_PRODUCTION_READY'    THEN 'MANUAL_PRODUCTION_READY'
    WHEN 'AUTOMATED_PRODUCTION'       THEN 'AUTOMATED_PRODUCTION_READY'
    WHEN 'AUTOMATED_PRODUCTION_READY' THEN 'AUTOMATED_PRODUCTION_READY'
    ELSE NULL
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.normalize_comm_hub_go_live_stage_for_action(p_stage text, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stage  text := upper(coalesce(trim(p_stage),''));
  v_action text := upper(coalesce(trim(p_action),''));
BEGIN
  IF v_stage = '' THEN
    RAISE EXCEPTION 'GO_LIVE_STAGE_UNSUPPORTED: empty stage';
  END IF;
  IF v_stage = 'CONTROLLED_LIVE' THEN
    IF v_action = 'RUN_CONTROLLED_STUB' THEN
      RETURN 'CONTROLLED_STUB_READY';
    ELSIF v_action = 'SEND_ONE_REAL_EMAIL' THEN
      RETURN 'ONE_REAL_EMAIL_READY';
    ELSE
      RAISE EXCEPTION 'GO_LIVE_STAGE_ACTION_REQUIRED: CONTROLLED_LIVE requires action RUN_CONTROLLED_STUB or SEND_ONE_REAL_EMAIL (got %)', coalesce(p_action,'<null>');
    END IF;
  END IF;
  RETURN public.normalize_comm_hub_go_live_stage(p_stage);
END;
$function$;
CREATE OR REPLACE FUNCTION public.normalize_comm_hub_go_live_stage_strict(p_stage text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v text := public.normalize_comm_hub_go_live_stage(p_stage);
BEGIN
  IF v IS NULL THEN RAISE EXCEPTION 'GO_LIVE_STAGE_UNSUPPORTED: %', p_stage; END IF;
  RETURN v;
END;$function$;
