CREATE OR REPLACE FUNCTION public.omni_comms_binding_upsert_draft(p_id uuid, p_expected_updated_at timestamp with time zone, p_sender_identity_id uuid, p_provider_account_id uuid, p_priority integer, p_external_sender_ref text, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; i public.omni_comms_sender_identity%ROWTYPE;
  v_endpoint uuid; v_count integer; v_dept uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  SELECT * INTO i FROM public.omni_comms_sender_identity WHERE id = p_sender_identity_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='sender_identity'; END IF;
  v_dept := COALESCE(
    (SELECT b.department_id FROM public.omni_comms_sender_provider_binding b WHERE b.id = p_id),
    i.department_id);

  IF public.omni_comms_priv_binding_endpoint_requirement(i.channel) = 'required' THEN
    SELECT count(*), min(e.id) INTO v_count, v_endpoint
      FROM public.omni_comms_channel_endpoint e
     WHERE e.organization_id = i.organization_id
       AND e.channel = i.channel
       AND e.status = 'active'
       AND e.data_origin <> 'reference_seed'
       AND e.provider_account_id IS NOT DISTINCT FROM p_provider_account_id
       AND (i.channel <> 'email' OR (e.endpoint_type = 'sending_domain'
            AND lower(coalesce(e.endpoint_config->>'domain_name','')) =
                lower(split_part(coalesce(i.identity_config->>'from_address', i.from_address,''),'@',2))));
    IF v_count <> 1 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001',
        DETAIL='legacy_binding_endpoint_ambiguous'; END IF;
  END IF;

  RETURN public.omni_comms_priv_channel_binding_upsert(
    v_uid, p_id, p_expected_updated_at, i.organization_id, v_dept, i.channel,
    p_sender_identity_id, p_provider_account_id, v_endpoint, p_priority,
    p_external_sender_ref, p_correlation_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_bootstrap_employer_registration_pilot(p_organization_code text DEFAULT 'SKN-SSB'::text, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_org   uuid;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');

  IF p_organization_code IS NULL OR btrim(p_organization_code) = '' THEN
    RAISE EXCEPTION 'OC400 organization_required'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;

  SELECT id INTO v_org FROM public.core_organization
   WHERE org_code = btrim(p_organization_code);
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found'
      USING ERRCODE = 'P0001', DETAIL = 'organization_not_found';
  END IF;

  -- Caller must be entitled to act for THIS organisation.
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_org, NULL);

  RETURN public.omni_comms_priv_bootstrap_employer_registration_pilot(
    v_actor, btrim(p_organization_code), coalesce(p_apply, false));
END;
$function$;
