CREATE OR REPLACE FUNCTION public.omni_comms_channel_provider_admin_summary(p_channel text, p_include_reference boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_channel text; v_include boolean; v_providers jsonb;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');
  v_channel := btrim(COALESCE(p_channel,''));
  IF v_channel NOT IN ('email','sms','whatsapp','push','in_app','webhook','print','voice') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_channel';
  END IF;
  v_include := COALESCE(p_include_reference,false)
               AND public.has_permission(v_uid,'omni_comms','configure');

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id',p.id,'code',p.code,'display_name',p.display_name,'channel',p.channel,
      'adapter_key',p.adapter_key,'status',p.status,'data_origin',p.data_origin,
      'updated_at',p.updated_at,'activated_at',p.activated_at,
      'retired_at',p.retired_at,'retirement_reason',p.retirement_reason,
      'credential_requirements', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
                 'id',r.id,'provider_id',r.provider_id,'purpose',r.purpose,
                 'display_name',r.display_name,'description',r.description,
                 'required',r.required,'secret_ref_pattern',r.secret_ref_pattern,
                 'sort_order',r.sort_order) ORDER BY r.sort_order, r.purpose)
          FROM public.omni_comms_provider_credential_requirement r
         WHERE r.provider_id=p.id),'[]'::jsonb),
      'account_count', (SELECT count(*) FROM public.omni_comms_provider_account a
                         WHERE a.provider_id=p.id)
    ) ORDER BY p.code),'[]'::jsonb)
    INTO v_providers
    FROM public.omni_comms_provider p
   WHERE p.channel=v_channel
     AND (p.data_origin <> 'reference_seed' OR v_include);

  RETURN jsonb_build_object(
    'channel',v_channel,
    'providers',v_providers,
    'reference_included',v_include,
    'generated_at',now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_provider_set_lifecycle(p_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_reason text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_row public.omni_comms_provider%ROWTYPE; v_before jsonb; v_action text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_action := lower(btrim(COALESCE(p_action,'')));
  IF v_action NOT IN ('activate','retire') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_action'; END IF;

  SELECT * INTO v_row FROM public.omni_comms_provider WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_not_found'; END IF;
  IF v_row.data_origin <> 'user' THEN
    RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='seeded_provider_read_only'; END IF;
  IF p_expected_updated_at IS NULL OR v_row.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC409 stale_write' USING ERRCODE='P0001', DETAIL='concurrent_modification'; END IF;
  v_before := to_jsonb(v_row) - 'created_by' - 'updated_by';

  IF v_action = 'activate' THEN
    IF v_row.status <> 'draft' THEN
      RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='only_draft_can_activate'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.omni_comms_provider_credential_requirement r
                    WHERE r.provider_id=p_id) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001',
        DETAIL='credential_requirements_required_before_activation'; END IF;
    UPDATE public.omni_comms_provider
       SET status='active', activated_at=now(), activated_by=v_uid, updated_by=v_uid
     WHERE id=p_id;
  ELSE
    IF char_length(btrim(COALESCE(p_reason,''))) < 1 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retirement_reason_required'; END IF;
    IF EXISTS (SELECT 1 FROM public.omni_comms_provider_account a
                WHERE a.provider_id=p_id AND a.status IN ('draft','active')) THEN
      RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='provider_has_live_accounts'; END IF;
    UPDATE public.omni_comms_provider
       SET status='retired', retired_at=now(), retired_by=v_uid,
           retirement_reason=btrim(p_reason), updated_by=v_uid
     WHERE id=p_id;
  END IF;

  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid, v_action, 'provider', p_id, v_row.code, v_before,
    (SELECT to_jsonb(p) - 'created_by' - 'updated_by' FROM public.omni_comms_provider p WHERE p.id=p_id),
    p_correlation_id);

  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_provider_upsert_draft(p_id uuid, p_expected_updated_at timestamp with time zone, p_channel text, p_code text, p_display_name text, p_adapter_key text, p_credential_requirements jsonb DEFAULT '[]'::jsonb, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_id uuid; v_channel text; v_code text; v_name text;
        v_adapter text; v_before jsonb; v_req jsonb; v_purposes text[] := '{}';
        v_row public.omni_comms_provider%ROWTYPE; v_i int := 0;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_channel := btrim(COALESCE(p_channel,''));
  v_code := lower(btrim(COALESCE(p_code,'')));
  v_name := btrim(COALESCE(p_display_name,''));
  v_adapter := lower(btrim(COALESCE(p_adapter_key,'')));

  IF v_channel NOT IN ('email','sms','in_app','push','whatsapp','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_not_supported_by_schema';
  END IF;
  IF v_code !~ '^[a-z0-9]+(_[a-z0-9]+)*$' OR char_length(v_code) < 3 OR char_length(v_code) > 64 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_code';
  END IF;
  IF v_adapter !~ '^[a-z0-9]+(_[a-z0-9]+)*$' OR char_length(v_adapter) < 3 OR char_length(v_adapter) > 64 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_adapter_key';
  END IF;
  IF char_length(v_name) < 2 OR char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_display_name';
  END IF;
  IF p_credential_requirements IS NULL OR jsonb_typeof(p_credential_requirements) <> 'array' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_credential_requirements';
  END IF;
  IF jsonb_array_length(p_credential_requirements) > 10 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='too_many_credential_requirements';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.omni_comms_provider(
      code, display_name, channel, adapter_key, status, data_origin, created_by, updated_by)
    VALUES (v_code, v_name, v_channel, v_adapter, 'draft', 'user', v_uid, v_uid)
    RETURNING id INTO v_id;
    v_before := NULL;
  ELSE
    SELECT * INTO v_row FROM public.omni_comms_provider WHERE id=p_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_not_found'; END IF;
    IF v_row.data_origin <> 'user' THEN
      RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='seeded_provider_read_only'; END IF;
    IF v_row.status <> 'draft' THEN
      RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='only_draft_provider_editable'; END IF;
    IF p_expected_updated_at IS NULL OR v_row.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'OC409 stale_write' USING ERRCODE='P0001', DETAIL='concurrent_modification'; END IF;
    v_before := to_jsonb(v_row) - 'created_by' - 'updated_by';
    UPDATE public.omni_comms_provider
       SET code=v_code, display_name=v_name, channel=v_channel,
           adapter_key=v_adapter, updated_by=v_uid
     WHERE id=p_id
     RETURNING id INTO v_id;
  END IF;

  -- replace credential requirements for the draft provider
  FOR v_req IN SELECT * FROM jsonb_array_elements(p_credential_requirements) LOOP
    v_i := v_i + 1;
    IF COALESCE(v_req->>'purpose','') !~ '^[a-z0-9]+(_[a-z0-9]+)*$' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_purpose'; END IF;
    IF char_length(btrim(COALESCE(v_req->>'display_name',''))) < 2 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_requirement_display_name'; END IF;
    IF char_length(COALESCE(v_req->>'secret_ref_pattern','')) < 3 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_secret_ref_pattern'; END IF;
    v_purposes := v_purposes || (v_req->>'purpose');

    INSERT INTO public.omni_comms_provider_credential_requirement(
      provider_id, purpose, display_name, description, required, secret_ref_pattern, sort_order)
    VALUES (v_id, v_req->>'purpose', btrim(v_req->>'display_name'),
            NULLIF(btrim(COALESCE(v_req->>'description','')),''),
            COALESCE((v_req->>'required')::boolean, true),
            v_req->>'secret_ref_pattern', v_i)
    ON CONFLICT (provider_id, purpose) DO UPDATE
      SET display_name=EXCLUDED.display_name,
          description=EXCLUDED.description,
          required=EXCLUDED.required,
          secret_ref_pattern=EXCLUDED.secret_ref_pattern,
          sort_order=EXCLUDED.sort_order;
  END LOOP;

  DELETE FROM public.omni_comms_provider_credential_requirement
   WHERE provider_id=v_id AND NOT (purpose = ANY(v_purposes));

  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid, CASE WHEN p_id IS NULL THEN 'create' ELSE 'update' END,
    'provider', v_id, v_code, v_before,
    (SELECT to_jsonb(p) - 'created_by' - 'updated_by' FROM public.omni_comms_provider p WHERE p.id=v_id),
    p_correlation_id);

  RETURN v_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_release_control_cancel_proposal(p_id uuid, p_expected_updated_at timestamp with time zone, p_reason text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rel public.omni_comms_channel_release_control;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');
  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_id FOR UPDATE;
  IF v_rel.id IS NULL THEN RAISE EXCEPTION 'release_control_missing' USING ERRCODE='42704'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_rel.organization_id, v_rel.department_id);
  IF v_rel.updated_at <> p_expected_updated_at THEN RAISE EXCEPTION 'concurrent_modification' USING ERRCODE='40001'; END IF;
  IF v_rel.proposed_state IS NULL THEN RAISE EXCEPTION 'release_proposal_missing' USING ERRCODE='22023'; END IF;

  UPDATE public.omni_comms_channel_release_control SET
    proposed_state = NULL, proposal_reason = NULL, proposed_by = NULL,
    proposed_at = NULL, proposal_expires_at = NULL, updated_by = v_actor
  WHERE id = v_rel.id RETURNING * INTO v_rel;

  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, 'proposal_cancelled', v_rel.release_state, NULL, p_reason, v_actor, p_correlation_id, NULL, '{}'::jsonb);
  RETURN public.omni_comms_priv_channel_release_json(v_rel);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_release_control_propose_pilot(p_id uuid, p_expected_updated_at timestamp with time zone, p_reason text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rel public.omni_comms_channel_release_control;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');
  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_id FOR UPDATE;
  IF v_rel.id IS NULL THEN RAISE EXCEPTION 'release_control_missing' USING ERRCODE='42704'; END IF;
  IF v_rel.data_origin = 'reference_seed' THEN RAISE EXCEPTION 'reference_release_non_operational' USING ERRCODE='42501'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_rel.organization_id, v_rel.department_id);
  IF v_rel.updated_at <> p_expected_updated_at THEN RAISE EXCEPTION 'concurrent_modification' USING ERRCODE='40001'; END IF;
  IF v_rel.release_state NOT IN ('test_only','suspended') THEN
    RAISE EXCEPTION 'release_transition_not_allowed' USING ERRCODE='22023';
  END IF;

  UPDATE public.omni_comms_channel_release_control SET
    proposed_state = 'controlled_pilot',
    proposal_reason = public.omni_comms_priv_normalize_reason(p_reason, true),
    proposed_by = v_actor,
    proposed_at = now(),
    proposal_expires_at = now() + interval '24 hours',
    approved_by = NULL, approved_at = NULL, approval_note = NULL,
    updated_by = v_actor
  WHERE id = v_rel.id RETURNING * INTO v_rel;

  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, 'transition_proposed', v_rel.release_state, 'controlled_pilot',
    v_rel.proposal_reason, v_actor, p_correlation_id, NULL, '{}'::jsonb);

  RETURN public.omni_comms_priv_channel_release_json(v_rel);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_release_control_set_basic_state(p_id uuid, p_expected_updated_at timestamp with time zone, p_target_state text, p_reason text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rel public.omni_comms_channel_release_control;
  v_from text;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');
  IF p_target_state = 'live' THEN
    RAISE EXCEPTION 'live_activation_not_available_until_business_pilot_certified' USING ERRCODE='22023';
  END IF;
  IF p_target_state NOT IN ('disabled','configuration','test_only') THEN
    RAISE EXCEPTION 'release_transition_not_allowed' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_id FOR UPDATE;
  IF v_rel.id IS NULL THEN RAISE EXCEPTION 'release_control_missing' USING ERRCODE='42704'; END IF;
  IF v_rel.data_origin = 'reference_seed' THEN RAISE EXCEPTION 'reference_release_non_operational' USING ERRCODE='42501'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_rel.organization_id, v_rel.department_id);
  IF v_rel.updated_at <> p_expected_updated_at THEN RAISE EXCEPTION 'concurrent_modification' USING ERRCODE='40001'; END IF;

  v_from := v_rel.release_state;
  IF NOT (
       (v_from='disabled' AND p_target_state='configuration')
    OR (v_from='configuration' AND p_target_state IN ('disabled','test_only'))
    OR (v_from='test_only' AND p_target_state IN ('configuration','disabled'))
    OR (v_from='suspended' AND p_target_state IN ('test_only','disabled'))
  ) THEN
    RAISE EXCEPTION 'release_transition_not_allowed' USING ERRCODE='22023';
  END IF;

  UPDATE public.omni_comms_channel_release_control SET
    release_state = p_target_state,
    release_version = release_version + 1,
    proposed_state = NULL, proposal_reason = NULL, proposed_by = NULL,
    proposed_at = NULL, proposal_expires_at = NULL,
    approved_by = NULL, approved_at = NULL, approval_note = NULL,
    suspended_by = NULL, suspended_at = NULL, suspension_reason = NULL,
    updated_by = v_actor
  WHERE id = v_rel.id RETURNING * INTO v_rel;

  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, CASE WHEN v_from='suspended' THEN 'release_resumed' ELSE 'release_updated' END,
    v_from, p_target_state, p_reason, v_actor, p_correlation_id, NULL, '{}'::jsonb);

  RETURN public.omni_comms_priv_channel_release_json(v_rel);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_release_control_summary(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_history_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rel public.omni_comms_channel_release_control;
  v_can_configure boolean := false;
  v_can_operate boolean := false;
  v_cert jsonb;
  v_policy public.omni_comms_channel_setting;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('view');
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, p_organization_id, p_department_id);
  IF p_channel <> 'email' THEN RAISE EXCEPTION 'release_channel_not_supported' USING ERRCODE='22023'; END IF;

  BEGIN PERFORM public.omni_comms_priv_require_capability('configure'); v_can_configure := true;
  EXCEPTION WHEN OTHERS THEN v_can_configure := false; END;
  BEGIN PERFORM public.omni_comms_priv_require_capability('operate'); v_can_operate := true;
  EXCEPTION WHEN OTHERS THEN v_can_operate := false; END;

  v_rel := public.omni_comms_priv_channel_release_effective(p_organization_id, p_department_id, p_channel);
  v_cert := public.omni_comms_priv_runtime_certification();
  v_policy := public.omni_comms_priv_channel_test_effective_policy(p_organization_id, p_department_id, p_channel);

  RETURN jsonb_build_object(
    'release', CASE WHEN v_rel.id IS NULL THEN NULL
                    ELSE public.omni_comms_priv_channel_release_json(v_rel) END,
    'scope', jsonb_build_object('organization_id', p_organization_id,
                                'department_id', p_department_id,
                                'channel', p_channel),
    'certification', v_cert,
    'runtime_environment', public.omni_comms_priv_runtime_environment(),
    'live_delivery_enabled', coalesce(v_policy.live_delivery_enabled, false),
    'prerequisites', CASE WHEN v_rel.id IS NULL THEN '[]'::jsonb
      ELSE public.omni_comms_priv_channel_release_prerequisites(
        p_organization_id, p_department_id, p_channel, v_rel.id, NULL) END,
    'usage', CASE WHEN v_rel.id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object(
        'hourly', (SELECT count(*) FROM public.omni_comms_dispatch_job j WHERE j.release_control_id=v_rel.id AND j.created_at > now() - interval '1 hour'),
        'daily', (SELECT count(*) FROM public.omni_comms_dispatch_job j WHERE j.release_control_id=v_rel.id AND j.created_at > now() - interval '1 day'),
        'total', (SELECT count(*) FROM public.omni_comms_dispatch_job j WHERE j.release_control_id=v_rel.id)) END,
    'history', CASE WHEN v_rel.id IS NULL THEN '[]'::jsonb ELSE (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'event_type', e.event_type, 'from_state', e.from_state,
        'to_state', e.to_state, 'reason', e.reason, 'actor_id', e.actor_id,
        'release_version', e.release_version,
        'release_fingerprint', left(e.release_fingerprint, 12),
        'certified_commit', e.certified_commit,
        'occurred_at', e.occurred_at) ORDER BY e.occurred_at DESC), '[]'::jsonb)
      FROM (SELECT * FROM public.omni_comms_channel_release_event
            WHERE release_control_id = v_rel.id
            ORDER BY occurred_at DESC
            LIMIT greatest(1, least(coalesce(p_history_limit,25), 200))) e) END,
    'capabilities', jsonb_build_object(
      'can_configure', v_can_configure,
      'can_approve', v_can_operate AND v_rel.id IS NOT NULL
                     AND v_rel.proposed_state = 'controlled_pilot'
                     AND v_rel.proposed_by IS DISTINCT FROM v_actor,
      'can_suspend', v_can_operate AND v_rel.release_state = 'controlled_pilot'),
    'actor_id', v_actor,
    'business_dispatch_implemented', false,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_release_control_suspend(p_id uuid, p_expected_updated_at timestamp with time zone, p_reason text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rel public.omni_comms_channel_release_control;
  v_from text;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('operate');
  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_id FOR UPDATE;
  IF v_rel.id IS NULL THEN RAISE EXCEPTION 'release_control_missing' USING ERRCODE='42704'; END IF;
  IF v_rel.data_origin = 'reference_seed' THEN RAISE EXCEPTION 'reference_release_non_operational' USING ERRCODE='42501'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_rel.organization_id, v_rel.department_id);
  IF v_rel.updated_at <> p_expected_updated_at THEN RAISE EXCEPTION 'concurrent_modification' USING ERRCODE='40001'; END IF;

  v_from := v_rel.release_state;
  UPDATE public.omni_comms_channel_release_control SET
    release_state = 'suspended',
    release_version = release_version + 1,
    proposed_state = NULL, proposal_reason = NULL, proposed_by = NULL,
    proposed_at = NULL, proposal_expires_at = NULL,
    suspended_by = v_actor, suspended_at = now(),
    suspension_reason = public.omni_comms_priv_normalize_reason(p_reason, true),
    updated_by = v_actor
  WHERE id = v_rel.id RETURNING * INTO v_rel;

  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, 'release_suspended', v_from, 'suspended', v_rel.suspension_reason,
    v_actor, p_correlation_id, NULL, '{}'::jsonb);
  RETURN public.omni_comms_priv_channel_release_json(v_rel);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_release_control_upsert_configuration(p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_channel text, p_permitted_event_codes text[], p_permitted_caller_modules text[], p_permitted_modes text[], p_recipient_input jsonb, p_max_recipients_per_request integer, p_max_messages_per_hour integer, p_max_messages_per_day integer, p_max_messages_total integer, p_release_starts_at timestamp with time zone, p_release_expires_at timestamp with time zone, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rel public.omni_comms_channel_release_control;
  v_rules jsonb;
  v_created boolean := false;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');
  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, p_organization_id, p_department_id);
  IF p_channel <> 'email' THEN RAISE EXCEPTION 'release_channel_not_supported' USING ERRCODE='22023'; END IF;

  v_rules := public.omni_comms_priv_channel_release_recipient_rules(p_channel, p_recipient_input);

  IF p_id IS NULL THEN
    INSERT INTO public.omni_comms_channel_release_control (
      organization_id, department_id, channel, data_origin, release_state,
      permitted_event_codes, permitted_caller_modules, permitted_modes,
      pilot_recipient_rules, max_recipients_per_request, max_messages_per_hour,
      max_messages_per_day, max_messages_total, release_starts_at, release_expires_at,
      created_by, updated_by)
    VALUES (
      p_organization_id, p_department_id, p_channel, 'user', 'configuration',
      coalesce(p_permitted_event_codes,'{}'), coalesce(p_permitted_caller_modules,'{}'),
      coalesce(p_permitted_modes,'{}'), v_rules,
      coalesce(p_max_recipients_per_request,1), coalesce(p_max_messages_per_hour,5),
      coalesce(p_max_messages_per_day,20), coalesce(p_max_messages_total,50),
      p_release_starts_at, p_release_expires_at, v_actor, v_actor)
    RETURNING * INTO v_rel;
    v_created := true;
  ELSE
    SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_id FOR UPDATE;
    IF v_rel.id IS NULL THEN RAISE EXCEPTION 'release_control_missing' USING ERRCODE='42704'; END IF;
    IF v_rel.data_origin = 'reference_seed' THEN RAISE EXCEPTION 'reference_release_read_only' USING ERRCODE='42501'; END IF;
    IF v_rel.updated_at <> p_expected_updated_at THEN RAISE EXCEPTION 'concurrent_modification' USING ERRCODE='40001'; END IF;
    IF v_rel.release_state = 'controlled_pilot' THEN RAISE EXCEPTION 'release_locked_during_controlled_pilot' USING ERRCODE='42501'; END IF;

    UPDATE public.omni_comms_channel_release_control SET
      permitted_event_codes = coalesce(p_permitted_event_codes,'{}'),
      permitted_caller_modules = coalesce(p_permitted_caller_modules,'{}'),
      permitted_modes = coalesce(p_permitted_modes,'{}'),
      pilot_recipient_rules = v_rules,
      max_recipients_per_request = coalesce(p_max_recipients_per_request,1),
      max_messages_per_hour = coalesce(p_max_messages_per_hour,5),
      max_messages_per_day = coalesce(p_max_messages_per_day,20),
      max_messages_total = coalesce(p_max_messages_total,50),
      release_starts_at = p_release_starts_at,
      release_expires_at = p_release_expires_at,
      release_version = release_version + 1,
      proposed_state = NULL, proposal_reason = NULL, proposed_by = NULL,
      proposed_at = NULL, proposal_expires_at = NULL,
      approved_by = NULL, approved_at = NULL, approval_note = NULL,
      updated_by = v_actor
    WHERE id = v_rel.id RETURNING * INTO v_rel;
  END IF;

  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, CASE WHEN v_created THEN 'release_created' ELSE 'release_updated' END,
    v_rel.release_state, v_rel.release_state, NULL, v_actor, p_correlation_id, NULL, '{}'::jsonb);
  PERFORM public.omni_comms_priv_write_channel_audit(
    v_actor, CASE WHEN v_created THEN 'omni_comms.release_control.create' ELSE 'omni_comms.release_control.update' END,
    'omni_comms_channel_release_control', v_rel.id, v_rel.channel, NULL,
    jsonb_build_object('release_state', v_rel.release_state, 'release_version', v_rel.release_version),
    p_correlation_id);

  RETURN public.omni_comms_priv_channel_release_json(v_rel);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_setting_upsert(p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_channel text, p_enabled boolean, p_live_delivery_enabled boolean, p_quiet_hours_start time without time zone, p_quiet_hours_end time without time zone, p_quiet_hours_timezone text, p_per_minute_limit integer, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_common jsonb; v_existing public.omni_comms_channel_setting%ROWTYPE;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_channel IS NULL OR p_channel <> 'email' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='email_channel_only_in_build2'; END IF;
  IF COALESCE(p_live_delivery_enabled,false) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='live_delivery_governed_by_release_control'; END IF;

  v_common := jsonb_build_object(
    'operational_state', CASE WHEN COALESCE(p_enabled,false) THEN 'configuration' ELSE 'disabled' END,
    'department_override_enabled', true,
    'per_minute_limit', to_jsonb(p_per_minute_limit),
    'quiet_hours_start', to_jsonb(to_char(p_quiet_hours_start,'HH24:MI')),
    'quiet_hours_end', to_jsonb(to_char(p_quiet_hours_end,'HH24:MI')),
    'quiet_hours_timezone', to_jsonb(p_quiet_hours_timezone)
  );

  IF p_id IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.omni_comms_channel_setting WHERE id = p_id;
    IF FOUND THEN
      v_common := v_common
        || jsonb_build_object(
             'per_day_limit', to_jsonb(v_existing.per_day_limit),
             'max_recipients_per_request', to_jsonb(v_existing.max_recipients_per_request),
             'retry_profile', v_existing.retry_profile,
             'request_timeout_seconds', to_jsonb(v_existing.request_timeout_seconds),
             'retention_days', to_jsonb(v_existing.retention_days),
             'cost_currency', to_jsonb(v_existing.cost_currency),
             'daily_cost_limit_minor', to_jsonb(v_existing.daily_cost_limit_minor),
             'per_message_cost_limit_minor', to_jsonb(v_existing.per_message_cost_limit_minor),
             'department_override_enabled', to_jsonb(v_existing.department_override_enabled));
      RETURN public.omni_comms_priv_channel_policy_upsert(
        v_uid, p_id, p_expected_updated_at, p_organization_id, p_department_id,
        'email', v_common, v_existing.channel_policy_config, p_correlation_id);
    END IF;
  END IF;

  RETURN public.omni_comms_priv_channel_policy_upsert(
    v_uid, p_id, p_expected_updated_at, p_organization_id, p_department_id,
    'email', v_common, '{}'::jsonb, p_correlation_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_test_centre_summary(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_binding_id uuid DEFAULT NULL::uuid, p_history_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_ch text := btrim(coalesce(p_channel,''));
  v_limit integer := least(greatest(coalesce(p_history_limit,20),1),100);
  v_can_configure boolean;
  v_candidates jsonb := '[]'::jsonb;
  v_binding uuid := p_binding_id;
  v_cfg_fp text := NULL;
  v_latest public.omni_comms_channel_test_run%ROWTYPE;
  v_latest_json jsonb := 'null'::jsonb;
  v_stale boolean := false;
  v_history jsonb := '[]'::jsonb;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required'; END IF;
  IF v_ch NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unsupported_channel'; END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, p_organization_id, p_department_id);
  IF p_department_id IS NOT NULL
     AND NOT public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='department_organization_mismatch'; END IF;

  v_can_configure := public.has_permission(v_uid, 'omni_comms', 'configure');

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'binding_id', b.id,
           'priority', b.priority,
           'status', b.status,
           'verification_status', b.verification_status,
           'department_id', b.department_id,
           'identity_code', i.code,
           'identity_display', coalesce(
             i.identity_config->>'email_address',
             i.identity_config->>'from_address',
             i.identity_config->>'sender_id',
             i.identity_config->>'phone_number',
             i.identity_config->>'display_name',
             i.from_address, i.display_name, i.code),
           'identity_status', i.status,
           'identity_data_origin', i.data_origin,
           'provider_account_code', a.code,
           'provider_account_status', a.status,
           'provider_account_verification_status', a.verification_status,
           'provider_environment', a.environment,
           'provider_id', a.provider_id,
           'endpoint_code', e.code,
           'endpoint_status', e.status,
           'endpoint_verification_status', e.verification_status,
           'data_origin', b.data_origin
         ) ORDER BY b.priority NULLS LAST, b.created_at), '[]'::jsonb)
    INTO v_candidates
    FROM public.omni_comms_sender_provider_binding b
    LEFT JOIN public.omni_comms_sender_identity i  ON i.id = b.sender_identity_id
    LEFT JOIN public.omni_comms_provider_account a ON a.id = b.provider_account_id
    LEFT JOIN public.omni_comms_channel_endpoint e ON e.id = b.channel_endpoint_id
   WHERE b.organization_id = p_organization_id
     AND b.channel = v_ch
     AND coalesce(b.data_origin,'') <> 'reference_seed'
     AND (p_department_id IS NULL OR b.department_id IS NULL OR b.department_id = p_department_id);

  IF v_binding IS NULL THEN
    SELECT (v_candidates->0->>'binding_id')::uuid INTO v_binding;
  END IF;

  IF v_binding IS NOT NULL THEN
    v_cfg_fp := public.omni_comms_priv_channel_test_config_fingerprint(
      p_organization_id, p_department_id, v_ch, v_binding);

    SELECT * INTO v_latest FROM public.omni_comms_channel_test_run
     WHERE organization_id = p_organization_id
       AND channel = v_ch
       AND binding_id = v_binding
       AND department_id IS NOT DISTINCT FROM p_department_id
     ORDER BY requested_at DESC LIMIT 1;

    IF FOUND THEN
      v_latest_json := public.omni_comms_priv_channel_test_run_json(v_latest, v_can_configure);
      v_stale := (v_latest.configuration_fingerprint IS DISTINCT FROM v_cfg_fp);
    END IF;

    SELECT coalesce(jsonb_agg(public.omni_comms_priv_channel_test_run_json(r, false)
             ORDER BY r.requested_at DESC), '[]'::jsonb)
      INTO v_history
      FROM (
        SELECT * FROM public.omni_comms_channel_test_run
         WHERE organization_id = p_organization_id
           AND channel = v_ch
           AND binding_id = v_binding
         ORDER BY requested_at DESC
         LIMIT v_limit
      ) r;
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'channel', v_ch,
    'can_configure', v_can_configure,
    'selected_binding_id', v_binding,
    'candidate_bindings', v_candidates,
    'configuration_fingerprint', v_cfg_fp,
    'latest_run', v_latest_json,
    'latest_run_is_stale', v_stale,
    'history', v_history,
    'sends_message', false);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_test_delivery_diagnostics(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_binding_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_ch text := btrim(coalesce(p_channel,''));
  v_limit integer := least(greatest(coalesce(p_limit,20),1),100);
  v_can_configure boolean;
  v_can_execute boolean;
  v_policy public.omni_comms_channel_setting%ROWTYPE;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, p_organization_id, p_department_id);
  v_can_configure := public.has_permission(v_uid, 'omni_comms', 'configure');
  v_can_execute := public.has_permission(v_uid, 'omni_comms', 'operate');

  v_policy := public.omni_comms_priv_channel_test_effective_policy(
    p_organization_id, p_department_id, v_ch);

  SELECT coalesce(jsonb_agg(public.omni_comms_priv_channel_test_delivery_json(d, v_can_configure)
           ORDER BY d.requested_at DESC), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT * FROM public.omni_comms_channel_test_delivery
       WHERE organization_id = p_organization_id
         AND channel = v_ch
         AND (p_binding_id IS NULL OR binding_id = p_binding_id)
       ORDER BY requested_at DESC LIMIT v_limit
    ) d;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'channel', v_ch,
    'binding_id', p_binding_id,
    'can_configure', v_can_configure,
    'can_execute', v_can_execute,
    'controlled_test_delivery_enabled',
      coalesce(v_policy.controlled_test_delivery_enabled,false),
    'controlled_test_recipients',
      to_jsonb(coalesce(v_policy.controlled_test_recipients,'{}'::text[])),
    'controlled_test_approved_at', v_policy.controlled_test_approved_at,
    'controlled_test_approval_expires_at', v_policy.controlled_test_approval_expires_at,
    'controlled_test_approval_active',
      (coalesce(v_policy.controlled_test_delivery_enabled,false)
       AND v_policy.controlled_test_approval_expires_at IS NOT NULL
       AND v_policy.controlled_test_approval_expires_at > now()),
    'controlled_test_max_deliveries', coalesce(v_policy.controlled_test_max_deliveries,5),
    'controlled_test_min_interval_seconds', coalesce(v_policy.controlled_test_min_interval_seconds,60),
    'live_delivery_enabled', coalesce(v_policy.live_delivery_enabled,false),
    'policy_id', v_policy.id,
    'deliveries', v_rows);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_test_delivery_prepare(p_test_run_id uuid, p_target text, p_idempotency_key text, p_subject text, p_body_text text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_run public.omni_comms_channel_test_run%ROWTYPE;
  v_binding public.omni_comms_sender_provider_binding%ROWTYPE;
  v_account public.omni_comms_provider_account%ROWTYPE;
  v_identity public.omni_comms_sender_identity%ROWTYPE;
  v_policy public.omni_comms_channel_setting%ROWTYPE;
  v_provider_code text;
  v_target text := lower(btrim(coalesce(p_target,'')));
  v_tnorm jsonb;
  v_pnorm jsonb;
  v_target_hash text;
  v_cfg_fp text;
  v_fp text;
  v_secret text;
  v_prov_subject text;
  v_prov_body text;
  v_prov_hash text;
  v_row public.omni_comms_channel_test_delivery%ROWTYPE;
  v_claim uuid;
  v_attempt integer;
  v_recent integer;
  v_last timestamptz;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('operate');
  IF p_test_run_id IS NULL OR coalesce(btrim(p_idempotency_key),'') = '' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_input'; END IF;

  SELECT * INTO v_run FROM public.omni_comms_channel_test_run WHERE id = p_test_run_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='test_run_not_found'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, v_run.organization_id, v_run.department_id);

  IF v_run.channel <> 'email' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='controlled_delivery_email_only'; END IF;
  IF v_run.status <> 'passed' THEN
    RAISE EXCEPTION 'OC409 preflight_required' USING ERRCODE='P0001', DETAIL='preflight_not_passed'; END IF;

  v_cfg_fp := public.omni_comms_priv_channel_test_config_fingerprint(
    v_run.organization_id, v_run.department_id, v_run.channel, v_run.binding_id);
  IF v_cfg_fp IS DISTINCT FROM v_run.configuration_fingerprint THEN
    RAISE EXCEPTION 'OC409 preflight_required' USING ERRCODE='P0001', DETAIL='preflight_stale'; END IF;

  -- Canonical target normalisation (identical rules to the preflight).
  v_tnorm := public.omni_comms_priv_channel_test_normalize_target('email', v_target);
  IF (v_tnorm->>'valid')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_target'; END IF;
  v_target_hash := v_tnorm->>'target_hash';
  IF v_target_hash IS DISTINCT FROM v_run.target_hash THEN
    RAISE EXCEPTION 'OC409 preflight_required' USING ERRCODE='P0001', DETAIL='target_differs_from_preflight'; END IF;

  -- Actual provider content must be the content that passed the preflight.
  v_pnorm := public.omni_comms_priv_channel_test_normalize_payload(
    'email', jsonb_build_object('subject', coalesce(p_subject,''), 'body', coalesce(p_body_text,'')));
  IF (v_pnorm->>'valid')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=coalesce(v_pnorm->>'code','payload_invalid'); END IF;
  IF (v_pnorm->>'payload_hash') IS DISTINCT FROM v_run.payload_hash THEN
    RAISE EXCEPTION 'OC409 preflight_required' USING ERRCODE='P0001', DETAIL='payload_differs_from_preflight'; END IF;

  v_prov_subject := '[TEST] ' || btrim(coalesce(p_subject,''));
  v_prov_body := coalesce(p_body_text,'')
    || E'\n\n--\nThis is a technical Omni-Comms channel test message. '
    || 'It contains no personal or case information and was not produced by the live sending path.';
  v_prov_hash := public.omni_comms_priv_channel_test_sha256(
    'email|' || jsonb_build_object('subject', v_prov_subject, 'body', v_prov_body)::text);

  SELECT * INTO v_binding FROM public.omni_comms_sender_provider_binding WHERE id = v_run.binding_id;
  IF NOT FOUND OR v_binding.status <> 'active'
     OR coalesce(v_binding.data_origin,'') = 'reference_seed' THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='binding_not_operational'; END IF;

  SELECT * INTO v_account FROM public.omni_comms_provider_account WHERE id = v_binding.provider_account_id;
  IF NOT FOUND OR v_account.status <> 'active'
     OR coalesce(v_account.data_origin,'') = 'reference_seed'
     OR v_account.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='provider_account_not_verified'; END IF;

  SELECT code INTO v_provider_code FROM public.omni_comms_provider WHERE id = v_account.provider_id;
  IF coalesce(v_provider_code,'') <> 'resend_email' THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='provider_not_supported'; END IF;

  -- Canonical credential: the api_key secret reference for the account.
  SELECT s.secret_ref INTO v_secret
    FROM public.omni_comms_provider_account_secret_ref s
   WHERE s.provider_account_id = v_account.id AND s.purpose = 'api_key'
   LIMIT 1;
  IF coalesce(v_secret,'') !~ '^OMNI_COMMS_RESEND_[A-Z0-9]+(_[A-Z0-9]+)*$' THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='secret_reference_invalid'; END IF;

  SELECT * INTO v_identity FROM public.omni_comms_sender_identity WHERE id = v_binding.sender_identity_id;
  IF NOT FOUND OR v_identity.status <> 'active'
     OR coalesce(v_identity.data_origin,'') = 'reference_seed' THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='identity_not_operational'; END IF;

  -- C4B effective policy (department override preference).
  v_policy := public.omni_comms_priv_channel_test_effective_policy(
    v_run.organization_id, v_run.department_id, 'email');
  IF v_policy.id IS NULL THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='effective_policy_missing'; END IF;
  IF v_policy.operational_state NOT IN ('test_only','pilot_ready') THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='policy_state_forbids_test_delivery'; END IF;
  IF coalesce(v_policy.live_delivery_enabled,false) IS TRUE THEN
    RAISE EXCEPTION 'OC409 configuration_incomplete' USING ERRCODE='P0001', DETAIL='live_delivery_must_be_disabled'; END IF;
  IF coalesce(v_policy.controlled_test_delivery_enabled,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'OC403 approval_required' USING ERRCODE='P0001', DETAIL='controlled_test_delivery_not_approved'; END IF;
  IF v_policy.controlled_test_approval_expires_at IS NULL
     OR v_policy.controlled_test_approval_expires_at <= now() THEN
    RAISE EXCEPTION 'OC403 approval_required' USING ERRCODE='P0001', DETAIL='controlled_test_approval_expired'; END IF;
  IF NOT (v_target = ANY(coalesce(v_policy.controlled_test_recipients,'{}'::text[]))) THEN
    RAISE EXCEPTION 'OC403 approval_required' USING ERRCODE='P0001', DETAIL='recipient_not_approved'; END IF;

  v_fp := public.omni_comms_priv_channel_test_sha256(
    v_run.id::text || '|' || v_target_hash || '|' || v_run.payload_hash || '|'
    || v_prov_hash || '|' || v_cfg_fp);

  SELECT * INTO v_row FROM public.omni_comms_channel_test_delivery
   WHERE organization_id = v_run.organization_id
     AND idempotency_key = btrim(p_idempotency_key)
   FOR UPDATE;

  IF FOUND THEN
    IF v_row.request_fingerprint IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'OC409 idempotency_conflict'
        USING ERRCODE='P0001', DETAIL='idempotency_payload_mismatch'; END IF;
  ELSE
    -- Volume and pacing controls apply only to genuinely new deliveries.
    SELECT count(*), max(requested_at) INTO v_recent, v_last
      FROM public.omni_comms_channel_test_delivery d
     WHERE d.policy_id = v_policy.id
       AND d.requested_at >= coalesce(v_policy.controlled_test_approved_at, now() - interval '24 hours');
    IF v_recent >= coalesce(v_policy.controlled_test_max_deliveries,5) THEN
      RAISE EXCEPTION 'OC429 rate_limited'
        USING ERRCODE='P0001', DETAIL='approved_delivery_volume_exhausted'; END IF;
    IF v_last IS NOT NULL
       AND v_last > now() - make_interval(secs => coalesce(v_policy.controlled_test_min_interval_seconds,60)) THEN
      RAISE EXCEPTION 'OC429 rate_limited'
        USING ERRCODE='P0001', DETAIL='minimum_interval_not_elapsed'; END IF;

    INSERT INTO public.omni_comms_channel_test_delivery (
      test_run_id, organization_id, department_id, channel, binding_id,
      provider_id, provider_code, provider_account_id, sender_identity_id,
      channel_endpoint_id, policy_id, from_address, idempotency_key,
      request_fingerprint, configuration_fingerprint, target_type, target_masked,
      target_hash, payload_summary, payload_hash, provider_payload_hash,
      status, correlation_id, requested_by)
    VALUES (
      v_run.id, v_run.organization_id, v_run.department_id, 'email', v_run.binding_id,
      v_account.provider_id, v_provider_code, v_account.id, v_identity.id,
      v_binding.channel_endpoint_id, v_policy.id, v_identity.from_address,
      btrim(p_idempotency_key), v_fp, v_cfg_fp,
      v_tnorm->>'target_type', v_tnorm->>'target_masked',
      v_target_hash, v_pnorm->'payload_summary', v_run.payload_hash, v_prov_hash,
      'pending', nullif(btrim(coalesce(p_correlation_id,'')),''), v_uid)
    RETURNING * INTO v_row;

    UPDATE public.omni_comms_channel_test_delivery
       SET provider_idempotency_key = 'omni-test/' || v_row.id::text
     WHERE id = v_row.id RETURNING * INTO v_row;
  END IF;

  -- Atomic claim. A stale worker can never take a claimed, still-live attempt.
  v_claim := gen_random_uuid();
  UPDATE public.omni_comms_channel_test_delivery d
     SET status = 'dispatching',
         active_claim_token = v_claim,
         claimed_at = now(),
         attempt_count = d.attempt_count + 1
   WHERE d.id = v_row.id
     AND d.attempt_count < 3
     AND (
       d.status = 'pending'
       OR d.status = 'outcome_unknown'
       OR (d.status = 'dispatching' AND d.claimed_at < now() - interval '2 minutes')
     )
     AND (d.status = 'pending' OR d.requested_at > now() - interval '24 hours')
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    SELECT * INTO v_row FROM public.omni_comms_channel_test_delivery
     WHERE organization_id = v_run.organization_id
       AND idempotency_key = btrim(p_idempotency_key);
    RETURN jsonb_build_object(
      'replayed', true,
      'dispatch_required', false,
      'delivery_id', v_row.id,
      'delivery', public.omni_comms_priv_channel_test_delivery_json(v_row, true));
  END IF;

  v_attempt := v_row.attempt_count;
  INSERT INTO public.omni_comms_channel_test_delivery_attempt (
    delivery_id, organization_id, attempt_number, claim_token,
    provider_idempotency_key, state, claimed_by)
  VALUES (
    v_row.id, v_row.organization_id, v_attempt, v_claim,
    v_row.provider_idempotency_key, 'claimed', v_uid);

  RETURN jsonb_build_object(
    'replayed', (v_attempt > 1),
    'dispatch_required', true,
    'delivery_id', v_row.id,
    'claim_token', v_claim,
    'attempt_number', v_attempt,
    'provider_idempotency_key', v_row.provider_idempotency_key,
    'secret_ref', v_secret,
    'from_address', v_identity.from_address,
    'from_name', v_identity.from_name,
    'reply_to_address', v_identity.reply_to_address,
    'provider_subject', v_prov_subject,
    'provider_body_text', v_prov_body,
    'delivery', public.omni_comms_priv_channel_test_delivery_json(v_row, true));
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_test_delivery_set_approval(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_enabled boolean DEFAULT false, p_recipients text[] DEFAULT '{}'::text[], p_expires_in_hours integer DEFAULT 4, p_max_deliveries integer DEFAULT 5, p_min_interval_seconds integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_ch text := btrim(coalesce(p_channel,''));
  v_clean text[] := '{}'::text[];
  v_item text;
  v_norm jsonb;
  v_policy public.omni_comms_channel_setting%ROWTYPE;
  v_before jsonb;
  v_hours integer := coalesce(p_expires_in_hours,4);
  v_max integer := coalesce(p_max_deliveries,5);
  v_interval integer := coalesce(p_min_interval_seconds,60);
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required'; END IF;
  IF v_ch <> 'email' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='controlled_delivery_email_only'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, p_organization_id, p_department_id);

  IF v_hours < 1 OR v_hours > 24 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='approval_window_out_of_range'; END IF;
  IF v_max < 1 OR v_max > 20 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_deliveries_out_of_range'; END IF;
  IF v_interval < 30 OR v_interval > 3600 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='min_interval_out_of_range'; END IF;

  FOREACH v_item IN ARRAY coalesce(p_recipients, '{}'::text[]) LOOP
    CONTINUE WHEN btrim(coalesce(v_item,'')) = '';
    v_norm := public.omni_comms_priv_channel_test_normalize_target(v_ch, v_item);
    IF (v_norm->>'valid')::boolean IS NOT TRUE THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_test_recipient'; END IF;
    v_item := lower(btrim(v_item));
    IF NOT (v_item = ANY(v_clean)) THEN v_clean := array_append(v_clean, v_item); END IF;
  END LOOP;

  IF coalesce(array_length(v_clean,1),0) > 5 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='too_many_test_recipients'; END IF;
  IF p_enabled AND coalesce(array_length(v_clean,1),0) = 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='approved_recipient_required'; END IF;

  SELECT * INTO v_policy FROM public.omni_comms_channel_setting
   WHERE organization_id = p_organization_id AND channel = v_ch
     AND department_id IS NOT DISTINCT FROM p_department_id
     AND coalesce(data_origin,'') <> 'reference_seed' LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='effective_policy_missing'; END IF;

  v_before := jsonb_build_object(
    'controlled_test_delivery_enabled', v_policy.controlled_test_delivery_enabled,
    'controlled_test_recipients', to_jsonb(coalesce(v_policy.controlled_test_recipients,'{}'::text[])),
    'controlled_test_approval_expires_at', v_policy.controlled_test_approval_expires_at,
    'controlled_test_max_deliveries', v_policy.controlled_test_max_deliveries,
    'controlled_test_min_interval_seconds', v_policy.controlled_test_min_interval_seconds);

  UPDATE public.omni_comms_channel_setting
     SET controlled_test_delivery_enabled = coalesce(p_enabled,false),
         controlled_test_recipients = v_clean,
         controlled_test_approved_at = CASE WHEN coalesce(p_enabled,false) THEN now() ELSE NULL END,
         controlled_test_approved_by = CASE WHEN coalesce(p_enabled,false) THEN v_uid ELSE NULL END,
         controlled_test_approval_expires_at =
           CASE WHEN coalesce(p_enabled,false) THEN now() + make_interval(hours => v_hours) ELSE NULL END,
         controlled_test_max_deliveries = v_max,
         controlled_test_min_interval_seconds = v_interval,
         live_delivery_enabled = false,
         updated_at = now(),
         updated_by = v_uid
   WHERE id = v_policy.id
   RETURNING * INTO v_policy;

  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid, 'set_controlled_test_approval', 'channel_test_delivery_approval',
    v_policy.id, v_ch, v_before,
    jsonb_build_object(
      'controlled_test_delivery_enabled', v_policy.controlled_test_delivery_enabled,
      'controlled_test_recipients', to_jsonb(coalesce(v_policy.controlled_test_recipients,'{}'::text[])),
      'controlled_test_approval_expires_at', v_policy.controlled_test_approval_expires_at,
      'controlled_test_max_deliveries', v_policy.controlled_test_max_deliveries,
      'controlled_test_min_interval_seconds', v_policy.controlled_test_min_interval_seconds),
    NULL);

  RETURN jsonb_build_object(
    'policy_id', v_policy.id,
    'controlled_test_delivery_enabled', v_policy.controlled_test_delivery_enabled,
    'controlled_test_recipients', to_jsonb(coalesce(v_policy.controlled_test_recipients,'{}'::text[])),
    'controlled_test_approved_at', v_policy.controlled_test_approved_at,
    'controlled_test_approval_expires_at', v_policy.controlled_test_approval_expires_at,
    'controlled_test_max_deliveries', v_policy.controlled_test_max_deliveries,
    'controlled_test_min_interval_seconds', v_policy.controlled_test_min_interval_seconds,
    'live_delivery_enabled', v_policy.live_delivery_enabled);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_channel_test_run_preflight(p_organization_id uuid, p_department_id uuid, p_channel text, p_binding_id uuid, p_target text, p_payload jsonb, p_idempotency_key text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_ch text := btrim(coalesce(p_channel,''));
  v_key text := btrim(coalesce(p_idempotency_key,''));
  v_snapshot jsonb;
  v_cfg_fp text;
  v_target jsonb;
  v_payload jsonb;
  v_checks jsonb;
  v_blockers text[];
  v_status text;
  v_req_fp text;
  v_existing public.omni_comms_channel_test_run%ROWTYPE;
  v_row public.omni_comms_channel_test_run%ROWTYPE;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required'; END IF;
  IF v_ch NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unsupported_channel'; END IF;
  IF p_binding_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='binding_required'; END IF;
  IF v_key !~ '^[A-Za-z0-9._:-]{8,128}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_idempotency_key'; END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, p_organization_id, p_department_id);
  IF p_department_id IS NOT NULL
     AND NOT public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='department_organization_mismatch'; END IF;

  v_snapshot := public.omni_comms_priv_channel_test_config_snapshot(
    p_organization_id, p_department_id, v_ch, p_binding_id);
  v_cfg_fp := public.omni_comms_priv_channel_test_sha256(v_snapshot::text);

  v_target  := public.omni_comms_priv_channel_test_normalize_target(v_ch, p_target);
  v_payload := public.omni_comms_priv_channel_test_normalize_payload(v_ch, p_payload);

  v_req_fp := public.omni_comms_priv_channel_test_sha256(
    jsonb_build_object(
      'organization_id', p_organization_id,
      'department_id', p_department_id,
      'channel', v_ch,
      'binding_id', p_binding_id,
      'configuration_fingerprint', v_cfg_fp,
      'target_type', coalesce(v_target->>'target_type', 'invalid'),
      'target_hash', coalesce(v_target->>'target_hash', v_target->>'code'),
      'payload_hash', coalesce(v_payload->>'payload_hash', v_payload->>'code')
    )::text);

  SELECT * INTO v_existing FROM public.omni_comms_channel_test_run
   WHERE organization_id = p_organization_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_existing.request_fingerprint IS DISTINCT FROM v_req_fp THEN
      RAISE EXCEPTION 'OC409 conflict'
        USING ERRCODE='P0001', DETAIL='test_idempotency_payload_mismatch';
    END IF;
    RETURN jsonb_build_object('replayed', true,
      'run', public.omni_comms_priv_channel_test_run_json(v_existing, true));
  END IF;

  IF NOT coalesce((v_target->>'valid')::boolean, false) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL = coalesce(v_target->>'code','target_invalid');
  END IF;
  IF NOT coalesce((v_payload->>'valid')::boolean, false) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL = coalesce(v_payload->>'code','payload_invalid');
  END IF;

  v_checks := public.omni_comms_priv_channel_test_checklist(v_ch, v_snapshot, v_target, v_payload);

  SELECT coalesce(array_agg(c->>'code' ORDER BY c->>'code'), ARRAY[]::text[])
    INTO v_blockers
    FROM jsonb_array_elements(v_checks) c
   WHERE c->>'state' = 'failed';

  v_status := CASE WHEN array_length(v_blockers,1) IS NULL THEN 'passed' ELSE 'failed' END;

  INSERT INTO public.omni_comms_channel_test_run (
    organization_id, department_id, channel, binding_id, test_kind,
    idempotency_key, request_fingerprint, configuration_fingerprint,
    configuration_snapshot, target_type, target_masked, target_hash,
    payload_summary, payload_hash, status, result_code, checks, blocker_codes,
    correlation_id, requested_by,
    provider_account_id, sender_identity_id, channel_endpoint_id, policy_id, completed_at)
  VALUES (
    p_organization_id, p_department_id, v_ch, p_binding_id, 'configuration_preflight',
    v_key, v_req_fp, v_cfg_fp,
    v_snapshot, v_target->>'target_type', v_target->>'target_masked', v_target->>'target_hash',
    v_payload->'payload_summary', v_payload->>'payload_hash',
    v_status,
    CASE WHEN v_status = 'passed' THEN 'preflight_passed' ELSE 'preflight_failed' END,
    v_checks, v_blockers,
    nullif(btrim(coalesce(p_correlation_id,'')), ''), v_uid,
    nullif(v_snapshot->'provider_account'->>'id','')::uuid,
    nullif(v_snapshot->'identity'->>'id','')::uuid,
    nullif(v_snapshot->'endpoint'->>'id','')::uuid,
    nullif(v_snapshot->>'policy_id','')::uuid,
    now())
  RETURNING * INTO v_row;

  RETURN jsonb_build_object('replayed', false,
    'run', public.omni_comms_priv_channel_test_run_json(v_row, true));
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_controlled_dry_run_gate()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_state text;
  v_posture jsonb;
  v_cert text;
  v_env text;
  v_commit_valid boolean;
  v_effective boolean;
  v_operate boolean;
  v_permitted boolean;
  v_blocked text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');
  v_state := public.omni_comms_priv_dry_run_gate_state();
  v_posture := public.omni_comms_priv_certification_posture();
  v_cert := v_posture ->> 'certification_state';
  v_env := v_posture ->> 'environment';
  v_commit_valid := coalesce((v_posture ->> 'certified_commit_valid')::boolean, false);
  v_effective := coalesce((v_posture ->> 'effective_certified')::boolean, false);
  v_operate := public.has_permission(v_uid, 'omni_comms', 'operate');

  v_permitted := false;
  IF v_state <> 'enabled' THEN
    v_blocked := 'admin_dry_run_disabled';
  ELSIF NOT v_operate THEN
    v_blocked := 'permission_denied';
  ELSIF v_env <> 'non_production' THEN
    v_blocked := 'non_production_environment_required';
  ELSIF v_cert = 'failed' THEN
    v_blocked := 'runtime_certification_failed';
  ELSIF v_cert <> 'certified' THEN
    v_blocked := 'runtime_certification_required';
  ELSIF NOT v_commit_valid THEN
    v_blocked := 'runtime_certified_commit_invalid';
  ELSIF NOT v_effective THEN
    v_blocked := 'runtime_certification_record_incomplete';
  ELSE
    v_permitted := true;
    v_blocked := NULL;
  END IF;

  RETURN jsonb_build_object(
    'state', v_state,
    'reason', CASE v_state
                WHEN 'enabled' THEN 'controlled_dry_run_enabled'
                WHEN 'disabled' THEN 'controlled_dry_run_disabled'
                ELSE 'controlled_dry_run_not_configured' END,
    'source', 'server_configuration',
    'caller_module_code', 'OMNI_COMMS_ADMIN_DRY_RUN',
    'allowed_mode', 'dry_run',
    'allowed_channels', jsonb_build_array('email'),
    'recipient_limit', 1,
    'required_recipient_domain', 'example.com',
    'live_delivery_enabled', false,
    'can_view', true,
    'can_operate', v_operate,
    'can_view_sensitive_content', public.has_permission(v_uid, 'omni_comms', 'view_sensitive_content'),
    'certification_state', v_cert,
    'certified_commit', v_posture -> 'certified_commit',
    'certified_commit_valid', v_commit_valid,
    'effective_certified', v_effective,
    'environment', v_env,
    'execution_permitted', v_permitted,
    'execution_blocked_reason', v_blocked,
    'checked_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_diagnostics(p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_catalogue jsonb; v_content jsonb; v_channels jsonb; v_runtime jsonb; v_checks jsonb;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');

  SELECT jsonb_build_object(
    'event_definitions_total', (SELECT count(*) FROM public.omni_comms_event_definition),
    'event_definitions_active', (SELECT count(*) FROM public.omni_comms_event_definition WHERE status='active'),
    'event_contracts_total', (SELECT count(*) FROM public.omni_comms_event_contract),
    'event_contracts_published', (SELECT count(*) FROM public.omni_comms_event_contract WHERE status='published')
  ) INTO v_catalogue;

  SELECT jsonb_build_object(
    'template_families', (SELECT count(*) FROM public.omni_comms_template_family
                           WHERE p_organization_id IS NULL OR organization_id = p_organization_id),
    'template_versions', (SELECT count(*) FROM public.omni_comms_template_version v
                           JOIN public.omni_comms_template_family f ON f.id = v.template_family_id
                          WHERE p_organization_id IS NULL OR f.organization_id = p_organization_id),
    'template_versions_published', (SELECT count(*) FROM public.omni_comms_template_version v
                           JOIN public.omni_comms_template_family f ON f.id = v.template_family_id
                          WHERE v.status='published'
                            AND (p_organization_id IS NULL OR f.organization_id = p_organization_id))
  ) INTO v_content;

  SELECT jsonb_build_object(
    'providers_active', (SELECT count(*) FROM public.omni_comms_provider WHERE status='active'),
    'provider_accounts_active', (SELECT count(*) FROM public.omni_comms_provider_account
                                  WHERE status='active' AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'sender_identities_active', (SELECT count(*) FROM public.omni_comms_sender_identity
                                  WHERE status='active' AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'bindings_verified', (SELECT count(*) FROM public.omni_comms_sender_provider_binding b
                            JOIN public.omni_comms_sender_identity s ON s.id = b.sender_identity_id
                           WHERE b.status='active' AND b.verification_status='verified'
                             AND (p_organization_id IS NULL OR s.organization_id = p_organization_id)),
    'channel_settings_enabled', (SELECT count(*) FROM public.omni_comms_channel_setting
                                  WHERE enabled = true AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'event_routes_active', (SELECT count(*) FROM public.omni_comms_event_route
                             WHERE lifecycle_state='active'
                               AND (p_organization_id IS NULL OR organization_id = p_organization_id))
  ) INTO v_channels;

  SELECT jsonb_build_object(
    'requests_24h', (SELECT count(*) FROM public.omni_comms_request WHERE created_at >= now() - interval '24 hours'
                      AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'requests_blocked_24h', (SELECT count(*) FROM public.omni_comms_request WHERE created_at >= now() - interval '24 hours'
                      AND status IN ('blocked','failed')
                      AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'messages_24h', (SELECT count(*) FROM public.omni_comms_message WHERE created_at >= now() - interval '24 hours'
                      AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'jobs_held', (SELECT count(*) FROM public.omni_comms_dispatch_job WHERE status='held'
                      AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'jobs_pending', (SELECT count(*) FROM public.omni_comms_dispatch_job WHERE status IN ('pending','ready','retry_wait')
                      AND (p_organization_id IS NULL OR organization_id = p_organization_id)),
    'last_request_at', (SELECT max(created_at) FROM public.omni_comms_request
                      WHERE p_organization_id IS NULL OR organization_id = p_organization_id)
  ) INTO v_runtime;

  v_checks := jsonb_build_array(
    jsonb_build_object('id','event_catalogue','label','At least one active event definition',
      'ok', (v_catalogue->>'event_definitions_active')::int > 0),
    jsonb_build_object('id','published_contract','label','At least one published event contract',
      'ok', (v_catalogue->>'event_contracts_published')::int > 0),
    jsonb_build_object('id','published_template','label','At least one published template version',
      'ok', (v_content->>'template_versions_published')::int > 0),
    jsonb_build_object('id','active_sender','label','At least one verified sender binding',
      'ok', (v_channels->>'bindings_verified')::int > 0),
    jsonb_build_object('id','channel_enabled','label','At least one enabled channel setting',
      'ok', (v_channels->>'channel_settings_enabled')::int > 0),
    jsonb_build_object('id','active_route','label','At least one active event route',
      'ok', (v_channels->>'event_routes_active')::int > 0)
  );

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'catalogue', v_catalogue,
    'content', v_content,
    'channels', v_channels,
    'runtime', v_runtime,
    'checks', v_checks,
    'generated_at', now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_dispatch_diagnostics(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_rel public.omni_comms_channel_release_control;
  v_queued_bindings integer := 0;
BEGIN
  IF v_uid IS NULL OR NOT public.has_permission(v_uid, 'omni_comms', 'operate') THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001';
  END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, p_organization_id, p_department_id);

  v_rel := public.omni_comms_priv_channel_release_effective(
             p_organization_id, p_department_id, 'email');

  -- Exact department compatibility: an organisation-level release is cleared
  -- ONLY by an organisation-level binding. A department-only binding can
  -- never clear pilot_business_producer_not_selected for the organisation.
  SELECT count(*) INTO v_queued_bindings
    FROM public.omni_comms_producer_event_binding b
    JOIN public.omni_comms_event_definition ed ON ed.id = b.event_definition_id
   WHERE b.status = 'active'
     AND 'queued' = ANY (b.allowed_modes)
     AND b.organization_id = p_organization_id
     AND (
       (p_department_id IS NULL AND b.department_id IS NULL)
       OR (p_department_id IS NOT NULL
           AND (b.department_id IS NULL OR b.department_id = p_department_id))
     )
     AND v_rel.id IS NOT NULL
     AND (v_rel.permitted_event_codes IS NOT NULL
          AND ed.event_code = ANY (v_rel.permitted_event_codes))
     AND (v_rel.permitted_caller_modules IS NOT NULL
          AND b.caller_module_code = ANY (v_rel.permitted_caller_modules));

  RETURN jsonb_build_object(
    'dispatcher_implemented', true,
    'live_delivery_enabled', false,
    'release_live_state_available', false,
    'dispatchable_channels', jsonb_build_array('email'),
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'eligible_jobs', (
      SELECT count(*) FROM public.omni_comms_dispatch_job j
        JOIN public.omni_comms_message m ON m.id = j.message_id
       WHERE j.channel='email' AND j.mode='queued'
         AND j.status IN ('held','retry_wait')
         AND j.organization_id = p_organization_id
         AND (p_department_id IS NULL OR m.department_id = p_department_id)),
    'in_flight_attempts', (
      SELECT count(*) FROM public.omni_comms_delivery_attempt a
        JOIN public.omni_comms_message m ON m.id = a.message_id
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR m.department_id = p_department_id)
         AND a.status IN ('started','dispatching')),
    'reconciliation_required_count', (
      SELECT count(*) FROM public.omni_comms_delivery_attempt a
        JOIN public.omni_comms_message m ON m.id = a.message_id
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR m.department_id = p_department_id)
         AND a.reconciliation_state = 'required'),
    'business_attempts_total', (
      SELECT count(*) FROM public.omni_comms_delivery_attempt a
        JOIN public.omni_comms_message m ON m.id = a.message_id
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR m.department_id = p_department_id)),
    'business_accepted_total', (
      SELECT count(*) FROM public.omni_comms_delivery_attempt a
        JOIN public.omni_comms_message m ON m.id = a.message_id
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR m.department_id = p_department_id)
         AND a.status = 'accepted'),
    'business_delivered_total', (
      SELECT count(*) FROM public.omni_comms_webhook_event w
        JOIN public.omni_comms_message m ON m.id = w.message_id
       WHERE w.organization_id = p_organization_id
         AND m.organization_id = p_organization_id
         AND (p_department_id IS NULL OR m.department_id = p_department_id)
         AND w.normalized_event_type = 'delivered'),
    'ambiguous_callback_count', (
      SELECT count(*) FROM public.omni_comms_webhook_event w
       WHERE w.processing_result = 'ambiguous'
         AND EXISTS (
           SELECT 1 FROM public.omni_comms_delivery_attempt a
             JOIN public.omni_comms_message m2 ON m2.id = a.message_id
            WHERE a.provider_message_id = w.provider_message_id
              AND a.organization_id = p_organization_id
              AND (p_department_id IS NULL OR m2.department_id = p_department_id))),
    'queued_producer_binding_count', v_queued_bindings,
    'release_state', v_rel.release_state,
    'release_control_id', v_rel.id,
    'blocker', CASE WHEN v_queued_bindings = 0
      THEN 'pilot_business_producer_not_selected' ELSE NULL END);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_dispatch_tick_authorize()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_scopes jsonb;
BEGIN
  v_scopes := public.omni_comms_priv_dispatch_operator_scopes(v_uid);
  IF coalesce((v_scopes->>'allowed')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object('allowed', false, 'code', v_scopes->>'code',
                              'scopes', '[]'::jsonb, 'max_batch_limit', 0);
  END IF;
  RETURN jsonb_build_object(
    'allowed', true,
    'code', 'authorized',
    'execution_context', 'operator',
    'max_batch_limit', 10,
    'scopes', v_scopes->'scopes');
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_email_config_summary(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_pid uuid; v_provider jsonb; v_accounts jsonb; v_senders jsonb;
        v_bindings jsonb; v_setting jsonb; v_ready boolean; v_endpoints jsonb;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001',DETAIL='organization_required'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, p_organization_id, NULL);
  v_pid := public.omni_comms_priv_email_provider_id();
  IF v_pid IS NULL THEN v_provider := NULL;
  ELSE
    SELECT jsonb_build_object('id',id,'code',code,'status',status,'updated_at',updated_at,'activated_at',activated_at)
      INTO v_provider FROM public.omni_comms_provider WHERE id=v_pid;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id',a.id,'code',a.code,'display_name',a.display_name,'secret_ref',a.secret_ref,
      'region',a.region,'sandbox_mode',a.sandbox_mode,'status',a.status,
      'environment',a.environment,'data_origin',a.data_origin,
      'provider_account_reference',a.provider_account_reference,
      'health_state',a.health_state,'health_checked_at',a.health_checked_at,'updated_at',a.updated_at,
      'verification_status',a.verification_status,
      'verification_result_code',a.verification_result_code,
      'verification_detail',a.verification_detail,
      'verification_checked_at',a.verification_checked_at
    ) ORDER BY a.created_at),'[]'::jsonb) INTO v_accounts
    FROM public.omni_comms_provider_account a
   WHERE a.organization_id=p_organization_id AND a.provider_id=v_pid;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id',id,'code',code,'display_name',display_name,
      'from_address',from_address,'from_name',from_name,'reply_to_address',reply_to_address,
      'status',status,'department_id',department_id,'event_definition_id',event_definition_id,
      'data_origin',data_origin,'identity_type',identity_type,'identity_config',identity_config,
      'updated_at',updated_at
    ) ORDER BY created_at),'[]'::jsonb) INTO v_senders
    FROM public.omni_comms_sender_identity
   WHERE organization_id=p_organization_id AND channel='email';
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id',b.id,'sender_identity_id',b.sender_identity_id,
      'provider_account_id',b.provider_account_id,'priority',b.priority,
      'external_sender_ref',b.external_sender_ref,
      'verification_status',b.verification_status,'verified_at',b.verified_at,
      'verification_source',b.verification_source,
      'verification_result_code',b.verification_result_code,
      'verification_checked_at',b.verification_checked_at,
      'channel_endpoint_id',b.channel_endpoint_id,
      'department_id',b.department_id,
      'data_origin',b.data_origin,
      'status',b.status,'updated_at',b.updated_at
    ) ORDER BY b.created_at),'[]'::jsonb) INTO v_bindings
    FROM public.omni_comms_sender_provider_binding b
    JOIN public.omni_comms_sender_identity s ON s.id=b.sender_identity_id
   WHERE s.organization_id=p_organization_id AND s.channel='email';
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id',e.id,'code',e.code,'display_name',e.display_name,'channel',e.channel,
      'endpoint_type',e.endpoint_type,'endpoint_config',e.endpoint_config,
      'provider_account_id',e.provider_account_id,
      'department_id',e.department_id,
      'status',e.status,'data_origin',e.data_origin,
      'verification_status',e.verification_status,
      'secret_refs', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('purpose',s2.purpose,'secret_ref',s2.secret_ref)
                         ORDER BY s2.purpose)
          FROM public.omni_comms_channel_endpoint_secret_ref s2
         WHERE s2.channel_endpoint_id=e.id),'[]'::jsonb),
      'updated_at',e.updated_at
    ) ORDER BY e.created_at),'[]'::jsonb) INTO v_endpoints
    FROM public.omni_comms_channel_endpoint e
   WHERE e.organization_id=p_organization_id AND e.channel='email';
  SELECT jsonb_build_object(
      'id',id,'department_id',department_id,'enabled',enabled,
      'live_delivery_enabled',live_delivery_enabled,
      'quiet_hours_start',quiet_hours_start,'quiet_hours_end',quiet_hours_end,
      'quiet_hours_timezone',quiet_hours_timezone,'per_minute_limit',per_minute_limit,
      'updated_at',updated_at) INTO v_setting
    FROM public.omni_comms_channel_setting
   WHERE organization_id=p_organization_id AND department_id IS NULL AND channel='email' LIMIT 1;
  v_ready :=
      v_provider IS NOT NULL AND (v_provider->>'status')='active'
      AND EXISTS(SELECT 1 FROM public.omni_comms_provider_account
                  WHERE organization_id=p_organization_id AND provider_id=v_pid
                    AND status='active' AND verification_status='verified'
                    AND data_origin <> 'reference_seed')
      AND EXISTS(SELECT 1 FROM public.omni_comms_sender_identity
                  WHERE organization_id=p_organization_id AND channel='email' AND status='active'
                    AND data_origin <> 'reference_seed')
      AND EXISTS(SELECT 1 FROM public.omni_comms_sender_provider_binding b
                  JOIN public.omni_comms_sender_identity s ON s.id=b.sender_identity_id
                 WHERE s.organization_id=p_organization_id AND s.channel='email'
                   AND b.status='active' AND b.verification_status='verified')
      AND v_setting IS NOT NULL AND (v_setting->>'enabled')::boolean=true;
  RETURN jsonb_build_object(
    'organization_id',p_organization_id,'provider',v_provider,
    'provider_accounts',v_accounts,'sender_identities',v_senders,
    'bindings',v_bindings,'channel_setting',v_setting,
    'endpoints',v_endpoints,
    'email_send_ready',v_ready,'generated_at',now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_email_provider_activate(p_id uuid, p_expected_updated_at timestamp with time zone, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_uid uuid; v_before public.omni_comms_provider%ROWTYPE; v_after public.omni_comms_provider%ROWTYPE;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  SELECT * INTO v_before FROM public.omni_comms_provider WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001',DETAIL='provider'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001',DETAIL='updated_at_mismatch'; END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001',DETAIL='must_be_draft'; END IF;
  UPDATE public.omni_comms_provider
     SET status='active',activated_at=now(),activated_by=v_uid,updated_by=v_uid,updated_at=now()
   WHERE id=p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid,'activate','provider',p_id,v_after.code,to_jsonb(v_before),to_jsonb(v_after),p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_email_provider_ensure(p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_uid uuid; v_id uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_id := public.omni_comms_priv_email_provider_id();
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  INSERT INTO public.omni_comms_provider(code,display_name,channel,adapter_key,status,created_by,updated_by)
  VALUES('resend_email','Resend (Email)','email','resend','draft',v_uid,v_uid)
  RETURNING id INTO v_id;
  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid,'ensure','provider',v_id,'resend_email',NULL,
    jsonb_build_object('code','resend_email','channel','email','adapter_key','resend','status','draft'),
    p_correlation_id);
  RETURN v_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_enforce_event_contract_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('published','retired') THEN
      RAISE EXCEPTION 'omni_comms_event_contract cannot delete % contract', OLD.status
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_event_contract may only be inserted with status=draft (got %)', NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  -- Retired: fully immutable
  IF OLD.status = 'retired' THEN
    RAISE EXCEPTION 'omni_comms_event_contract retired contracts are immutable'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Status transition rules
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'draft' AND NEW.status = 'published' THEN
      IF NEW.checksum IS NULL OR NEW.published_at IS NULL OR NEW.published_by IS NULL THEN
        RAISE EXCEPTION 'omni_comms_event_contract publish requires checksum, published_at, published_by'
          USING ERRCODE = 'check_violation';
      END IF;
      SELECT status INTO v_owner_status
        FROM public.omni_comms_event_definition
        WHERE id = NEW.event_definition_id;
      IF v_owner_status = 'retired' THEN
        RAISE EXCEPTION 'omni_comms_event_contract cannot publish against a retired event'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSIF OLD.status = 'published' AND NEW.status = 'retired' THEN
      IF NEW.retired_at IS NULL OR NEW.retired_by IS NULL THEN
        RAISE EXCEPTION 'omni_comms_event_contract retire requires retired_at, retired_by'
          USING ERRCODE = 'check_violation';
      END IF;
      -- Preserve identity/content/publication fields on retirement
      IF NEW.event_definition_id IS DISTINCT FROM OLD.event_definition_id
         OR NEW.version_number   IS DISTINCT FROM OLD.version_number
         OR NEW.json_schema      IS DISTINCT FROM OLD.json_schema
         OR NEW.sample_payload   IS DISTINCT FROM OLD.sample_payload
         OR NEW.checksum         IS DISTINCT FROM OLD.checksum
         OR NEW.published_at     IS DISTINCT FROM OLD.published_at
         OR NEW.published_by     IS DISTINCT FROM OLD.published_by
         OR NEW.created_at       IS DISTINCT FROM OLD.created_at
         OR NEW.created_by       IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'omni_comms_event_contract retirement must preserve identity, content, checksum, publication and creation fields'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      RAISE EXCEPTION 'omni_comms_event_contract disallowed status transition % -> %', OLD.status, NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    -- No status change
    IF OLD.status = 'published' THEN
      -- Published contracts are immutable except retire
      IF NEW.event_definition_id IS DISTINCT FROM OLD.event_definition_id
         OR NEW.version_number   IS DISTINCT FROM OLD.version_number
         OR NEW.json_schema      IS DISTINCT FROM OLD.json_schema
         OR NEW.sample_payload   IS DISTINCT FROM OLD.sample_payload
         OR NEW.checksum         IS DISTINCT FROM OLD.checksum
         OR NEW.published_at     IS DISTINCT FROM OLD.published_at
         OR NEW.published_by     IS DISTINCT FROM OLD.published_by
         OR NEW.created_at       IS DISTINCT FROM OLD.created_at
         OR NEW.created_by       IS DISTINCT FROM OLD.created_by
         OR NEW.retired_at       IS DISTINCT FROM OLD.retired_at
         OR NEW.retired_by       IS DISTINCT FROM OLD.retired_by THEN
        RAISE EXCEPTION 'omni_comms_event_contract published contracts are immutable except retirement'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_enforce_event_definition_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_event_definition may only be inserted with status=draft (got %)', NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  -- Allowed transitions
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
      (OLD.status = 'draft'     AND NEW.status IN ('active','retired'))
      OR (OLD.status = 'active'    AND NEW.status IN ('suspended','retired'))
      OR (OLD.status = 'suspended' AND NEW.status IN ('active','retired'))
    ) THEN
      RAISE EXCEPTION 'omni_comms_event_definition disallowed status transition % -> %', OLD.status, NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Retired terminal
  IF OLD.status = 'retired' AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'omni_comms_event_definition retired events cannot be reactivated'
      USING ERRCODE = 'check_violation';
  END IF;

  -- code editable only while draft->draft; not in same update that leaves draft
  IF NEW.code IS DISTINCT FROM OLD.code THEN
    IF NOT (OLD.status = 'draft' AND NEW.status = 'draft') THEN
      RAISE EXCEPTION 'omni_comms_event_definition code is immutable once event leaves draft'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_enforce_template_family_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_dept_org uuid;
  v_version_count integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_template_family may only be inserted with status=draft (got %)', NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.scope_type = 'department' THEN
      SELECT organization_id INTO v_dept_org
        FROM public.core_department WHERE id = NEW.department_id;
      IF v_dept_org IS NULL THEN
        RAISE EXCEPTION 'omni_comms_template_family department_id % not found', NEW.department_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      IF v_dept_org <> NEW.organization_id THEN
        RAISE EXCEPTION 'omni_comms_template_family department_id % does not belong to organization_id %',
          NEW.department_id, NEW.organization_id
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    -- Allowed transitions
    IF NEW.status <> OLD.status THEN
      IF NOT (
        (OLD.status = 'draft'  AND NEW.status = 'active')
        OR (OLD.status = 'draft'  AND NEW.status = 'retired')
        OR (OLD.status = 'active' AND NEW.status = 'retired')
      ) THEN
        RAISE EXCEPTION 'omni_comms_template_family invalid status transition % -> %', OLD.status, NEW.status
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    -- Immutability once leaving draft
    IF OLD.status <> 'draft' THEN
      IF NEW.code               IS DISTINCT FROM OLD.code
         OR NEW.scope_type          IS DISTINCT FROM OLD.scope_type
         OR NEW.organization_id     IS DISTINCT FROM OLD.organization_id
         OR NEW.department_id       IS DISTINCT FROM OLD.department_id
         OR NEW.event_definition_id IS DISTINCT FROM OLD.event_definition_id
         OR NEW.created_at          IS DISTINCT FROM OLD.created_at
         OR NEW.created_by          IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'omni_comms_template_family identity fields are immutable after leaving draft'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    -- Re-verify department ownership if changed (only possible while draft)
    IF NEW.scope_type = 'department'
       AND NEW.department_id IS DISTINCT FROM OLD.department_id THEN
      SELECT organization_id INTO v_dept_org
        FROM public.core_department WHERE id = NEW.department_id;
      IF v_dept_org IS NULL OR v_dept_org <> NEW.organization_id THEN
        RAISE EXCEPTION 'omni_comms_template_family department_id % does not belong to organization_id %',
          NEW.department_id, NEW.organization_id
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    NEW.updated_at := now();
    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_template_family may only be deleted while status=draft (got %)', OLD.status
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT count(*) INTO v_version_count
      FROM public.omni_comms_template_version WHERE template_family_id = OLD.id;
    IF v_version_count > 0 THEN
      RAISE EXCEPTION 'omni_comms_template_family cannot be deleted while % version(s) exist', v_version_count
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_enforce_template_version_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_family_status text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_template_version may only be inserted with status=draft (got %)', NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT status INTO v_family_status
      FROM public.omni_comms_template_family WHERE id = NEW.template_family_id;
    IF v_family_status IS NULL THEN
      RAISE EXCEPTION 'omni_comms_template_version template_family_id % not found', NEW.template_family_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_family_status = 'retired' THEN
      RAISE EXCEPTION 'omni_comms_template_version cannot be created under retired family %', NEW.template_family_id
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    -- Allowed transitions
    IF NEW.status <> OLD.status THEN
      IF NOT (
        (OLD.status = 'draft'    AND NEW.status = 'approved')
        OR (OLD.status = 'approved' AND NEW.status = 'published')
        OR (OLD.status = 'approved' AND NEW.status = 'retired')
        OR (OLD.status = 'published' AND NEW.status = 'retired')
      ) THEN
        RAISE EXCEPTION 'omni_comms_template_version invalid status transition % -> %', OLD.status, NEW.status
          USING ERRCODE = 'check_violation';
      END IF;

      -- On approval, family must not be retired
      IF NEW.status = 'approved' THEN
        SELECT status INTO v_family_status
          FROM public.omni_comms_template_family WHERE id = NEW.template_family_id;
        IF v_family_status = 'retired' THEN
          RAISE EXCEPTION 'omni_comms_template_version cannot be approved under retired family'
            USING ERRCODE = 'check_violation';
        END IF;
      END IF;

      -- On publish, family must be active
      IF NEW.status = 'published' THEN
        SELECT status INTO v_family_status
          FROM public.omni_comms_template_family WHERE id = NEW.template_family_id;
        IF v_family_status <> 'active' THEN
          RAISE EXCEPTION 'omni_comms_template_version can only be published when family is active (family status=%)', v_family_status
            USING ERRCODE = 'check_violation';
        END IF;
      END IF;
    END IF;

    -- Immutability once leaving draft
    IF OLD.status <> 'draft' THEN
      IF NEW.template_family_id IS DISTINCT FROM OLD.template_family_id
         OR NEW.version_number  IS DISTINCT FROM OLD.version_number
         OR NEW.channel         IS DISTINCT FROM OLD.channel
         OR NEW.locale          IS DISTINCT FROM OLD.locale
         OR NEW.content         IS DISTINCT FROM OLD.content
         OR NEW.checksum        IS DISTINCT FROM OLD.checksum
         OR NEW.approved_at     IS DISTINCT FROM OLD.approved_at
         OR NEW.approved_by     IS DISTINCT FROM OLD.approved_by
         OR NEW.created_at      IS DISTINCT FROM OLD.created_at
         OR NEW.created_by      IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'omni_comms_template_version approved fields are immutable'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    -- Publication metadata immutable once published
    IF OLD.status IN ('published','retired') AND OLD.published_at IS NOT NULL THEN
      IF NEW.published_at IS DISTINCT FROM OLD.published_at
         OR NEW.published_by IS DISTINCT FROM OLD.published_by THEN
        RAISE EXCEPTION 'omni_comms_template_version publication metadata is immutable'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    -- Retired terminal
    IF OLD.status = 'retired' THEN
      IF NEW.retired_at        IS DISTINCT FROM OLD.retired_at
         OR NEW.retired_by     IS DISTINCT FROM OLD.retired_by
         OR NEW.retirement_reason IS DISTINCT FROM OLD.retirement_reason THEN
        RAISE EXCEPTION 'omni_comms_template_version retirement fields are immutable once retired'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    NEW.updated_at := now();
    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_template_version may only be deleted while status=draft (got %)', OLD.status
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_event_contract_create(p_event_definition_id uuid, p_version_number integer, p_json_schema jsonb, p_sample_payload jsonb, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_uid uuid;
  v_id  uuid;
  v_owner_status text;
  v_cons text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  SELECT status INTO v_owner_status FROM public.omni_comms_event_definition WHERE id = p_event_definition_id;
  IF v_owner_status IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='event_definition';
  END IF;
  IF v_owner_status = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='event_retired';
  END IF;
  PERFORM public.omni_comms_priv_validate_schema(p_json_schema, p_sample_payload);
  BEGIN
    INSERT INTO public.omni_comms_event_contract
      (event_definition_id, version_number, json_schema, sample_payload, status, created_by, updated_by)
    VALUES
      (p_event_definition_id, p_version_number, p_json_schema, COALESCE(p_sample_payload,'{}'::jsonb),
       'draft', v_uid, v_uid)
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS v_cons = CONSTRAINT_NAME;
      IF v_cons = 'omni_comms_event_contract_event_version_key' THEN
        RAISE EXCEPTION 'OC410 duplicate_contract_version' USING ERRCODE='P0001', DETAIL=p_version_number::text;
      END IF;
      RAISE;
    WHEN check_violation THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;

  PERFORM public.omni_comms_priv_write_audit(
    v_uid, 'create', 'event_contract', v_id,
    p_event_definition_id::text || '#' || p_version_number::text,
    NULL,
    jsonb_build_object('event_definition_id', p_event_definition_id,
                       'version_number', p_version_number, 'status','draft'),
    p_correlation_id
  );
  RETURN v_id;
END;$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_event_contract_get(p_id uuid)
 RETURNS TABLE(id uuid, event_definition_id uuid, version_number integer, json_schema jsonb, sample_payload jsonb, sample_payload_redacted boolean, status text, checksum text, published_at timestamp with time zone, published_by uuid, retired_at timestamp with time zone, retired_by uuid, created_at timestamp with time zone, created_by uuid, updated_at timestamp with time zone, updated_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_uid uuid;
  v_can_see boolean;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');
  v_can_see := public.has_permission(v_uid, 'omni_comms', 'view_sensitive_content');
  RETURN QUERY
    SELECT c.id, c.event_definition_id, c.version_number, c.json_schema,
           CASE WHEN v_can_see THEN c.sample_payload ELSE NULL::jsonb END AS sample_payload,
           NOT v_can_see AS sample_payload_redacted,
           c.status, c.checksum,
           c.published_at, c.published_by, c.retired_at, c.retired_by,
           c.created_at, c.created_by, c.updated_at, c.updated_by
      FROM public.omni_comms_event_contract c
     WHERE c.id = p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_event_contract_list(p_event_definition_id uuid, p_limit integer, p_offset integer, p_status text)
 RETURNS TABLE(id uuid, event_definition_id uuid, version_number integer, status text, checksum text, published_at timestamp with time zone, retired_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_limit int; v_offset int;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  v_limit := p_limit; v_offset := p_offset;
  IF v_limit IS NULL OR v_limit < 1 OR v_limit > 100 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='limit_out_of_range';
  END IF;
  IF v_offset IS NULL OR v_offset < 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='offset_out_of_range';
  END IF;
  RETURN QUERY
    SELECT c.id, c.event_definition_id, c.version_number, c.status,
           c.checksum, c.published_at, c.retired_at, c.updated_at
      FROM public.omni_comms_event_contract c
     WHERE c.event_definition_id = p_event_definition_id
       AND (p_status IS NULL OR c.status = p_status)
     ORDER BY c.version_number DESC, c.id ASC
     LIMIT v_limit OFFSET v_offset;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_event_contract_publish(p_id uuid, p_expected_updated_at timestamp with time zone, p_reason text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_uid uuid;
  v_before public.omni_comms_event_contract%ROWTYPE;
  v_after  public.omni_comms_event_contract%ROWTYPE;
  v_event_code text;
  v_checksum   text;
  v_reason text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_reason := public.omni_comms_priv_normalize_reason(p_reason, false);
  SELECT * INTO v_before FROM public.omni_comms_event_contract WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='event_contract'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch';
  END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft';
  END IF;
  PERFORM public.omni_comms_priv_validate_schema(v_before.json_schema, v_before.sample_payload);
  SELECT code INTO v_event_code FROM public.omni_comms_event_definition WHERE id=v_before.event_definition_id;
  v_checksum := public.omni_comms_priv_compute_checksum(v_event_code, v_before.version_number, v_before.json_schema);
  UPDATE public.omni_comms_event_contract
     SET status='published', checksum=v_checksum,
         published_at=now(), published_by=v_uid,
         updated_by=v_uid, updated_at=now()
   WHERE id=p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_lifecycle_audit(
    v_uid, 'publish', 'event_contract', p_id,
    v_after.event_definition_id::text || '#' || v_after.version_number::text,
    to_jsonb(v_before), to_jsonb(v_after), v_reason, p_correlation_id
  );
  RETURN p_id;
END; $function$;
