BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required';
  END IF;
  v_limit := LEAST(GREATEST(COALESCE(p_limit,100),1),500);
  v_offset := GREATEST(COALESCE(p_offset,0),0);

  SELECT COALESCE(jsonb_agg(x), '[]'::jsonb) INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'id', r.id,
      'organization_id', r.organization_id,
      'department_id', r.department_id,
      'event_definition_id', r.event_definition_id,
      'event_code', d.code,
      'event_name', d.name,
      'channel', r.channel,
      'is_required', r.is_required,
      'is_enabled', r.is_enabled,
      'priority', r.priority,
      'template_family_id', r.template_family_id,
      'template_family_code', tf.code,
      'sender_identity_id', r.sender_identity_id,
      'sender_identity_code', si.code,
      'sender_resolution_policy', r.sender_resolution_policy,
      'preference_policy', r.preference_policy,
      'lifecycle_state', r.lifecycle_state,
      'created_at', r.created_at,
      'updated_at', r.updated_at
    ) AS x
    FROM public.omni_comms_event_route r
    JOIN public.omni_comms_event_definition d ON d.id = r.event_definition_id
    LEFT JOIN public.omni_comms_template_family tf ON tf.id = r.template_family_id
    LEFT JOIN public.omni_comms_sender_identity si ON si.id = r.sender_identity_id
    WHERE r.organization_id = p_organization_id
      AND (p_department_id IS NULL OR r.department_id IS NOT DISTINCT FROM p_department_id)
      AND (p_event_definition_id IS NULL OR r.event_definition_id = p_event_definition_id)
      AND (p_channel IS NULL OR r.channel = p_channel)
      AND (p_lifecycle_state IS NULL OR r.lifecycle_state = p_lifecycle_state)
    ORDER BY r.created_at
    LIMIT v_limit OFFSET v_offset
  ) s;

  RETURN v_rows;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_event_route_set_lifecycle(p_id uuid, p_expected_updated_at timestamp with time zone, p_target_state text, p_reason text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_uid uuid;
  v_before public.omni_comms_event_route%ROWTYPE;
  v_after  public.omni_comms_event_route%ROWTYPE;
  v_reason text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_target_state NOT IN ('active','suspended','retired') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unsupported_target_state';
  END IF;
  v_reason := NULLIF(btrim(COALESCE(p_reason,'')),'');
  IF p_target_state IN ('suspended','retired') AND v_reason IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reason_required';
  END IF;
  IF v_reason IS NOT NULL AND length(v_reason) > 2000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reason_too_long';
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_event_route WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='event_route'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch';
  END IF;
  IF v_before.lifecycle_state = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='already_retired';
  END IF;
  IF p_target_state = 'active' AND v_before.lifecycle_state NOT IN ('draft','suspended') THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='not_activatable';
  END IF;
  IF p_target_state = 'suspended' AND v_before.lifecycle_state <> 'active' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='not_suspendable';
  END IF;

  UPDATE public.omni_comms_event_route
     SET lifecycle_state = p_target_state,
         is_enabled = CASE WHEN p_target_state = 'active' THEN true
                           WHEN p_target_state IN ('suspended','retired') THEN false
                           ELSE is_enabled END,
         activated_at = CASE WHEN p_target_state='active' THEN now() ELSE activated_at END,
         activated_by = CASE WHEN p_target_state='active' THEN v_uid ELSE activated_by END,
         retired_at = CASE WHEN p_target_state='retired' THEN now() ELSE retired_at END,
         retired_by = CASE WHEN p_target_state='retired' THEN v_uid ELSE retired_by END,
         updated_by = v_uid, updated_at = now()
   WHERE id = p_id RETURNING * INTO v_after;

  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid, p_target_state, 'event_route', p_id, v_after.channel,
    to_jsonb(v_before), to_jsonb(v_after) || jsonb_build_object('reason', v_reason), p_correlation_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_event_route_upsert_draft(p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_event_definition_id uuid, p_channel text, p_is_required boolean, p_is_enabled boolean, p_priority integer, p_template_family_id uuid, p_sender_identity_id uuid, p_sender_resolution_policy text, p_preference_policy text, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_uid uuid;
  v_before public.omni_comms_event_route%ROWTYPE;
  v_after  public.omni_comms_event_route%ROWTYPE;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');

  IF p_id IS NULL THEN
    IF p_organization_id IS NULL OR p_event_definition_id IS NULL OR p_channel IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_event_channel_required';
    END IF;
    BEGIN
      INSERT INTO public.omni_comms_event_route(
        organization_id, department_id, event_definition_id, channel,
        is_required, is_enabled, priority, template_family_id, sender_identity_id,
        sender_resolution_policy, preference_policy, lifecycle_state,
        created_by, updated_by)
      VALUES (p_organization_id, p_department_id, p_event_definition_id, p_channel,
        COALESCE(p_is_required,false), COALESCE(p_is_enabled,false),
        COALESCE(p_priority,100), p_template_family_id, p_sender_identity_id,
        COALESCE(p_sender_resolution_policy,'organisation_default'),
        COALESCE(p_preference_policy,'honour'), 'draft', v_uid, v_uid)
      RETURNING * INTO v_after;
    EXCEPTION
      WHEN unique_violation THEN
        RAISE EXCEPTION 'OC409 duplicate_event_route' USING ERRCODE='P0001', DETAIL='org_dept_event_channel_exists';
      WHEN check_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    END;
    PERFORM public.omni_comms_priv_write_channel_audit(
      v_uid,'create','event_route',v_after.id,v_after.channel,NULL,to_jsonb(v_after),p_correlation_id);
    RETURN v_after.id;
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_event_route WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='event_route'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch';
  END IF;
  IF v_before.lifecycle_state = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='retired_route_immutable';
  END IF;

  BEGIN
    UPDATE public.omni_comms_event_route
       SET is_required = COALESCE(p_is_required, is_required),
           is_enabled = COALESCE(p_is_enabled, is_enabled),
           priority = COALESCE(p_priority, priority),
           template_family_id = p_template_family_id,
           sender_identity_id = p_sender_identity_id,
           sender_resolution_policy = COALESCE(p_sender_resolution_policy, sender_resolution_policy),
           preference_policy = COALESCE(p_preference_policy, preference_policy),
           updated_by = v_uid, updated_at = now()
     WHERE id = p_id RETURNING * INTO v_after;
  EXCEPTION WHEN check_violation THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;

  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid,'update','event_route',p_id,v_after.channel,to_jsonb(v_before),to_jsonb(v_after),p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_get_producer_event_binding(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_row   public.omni_comms_producer_event_binding%ROWTYPE;
  v_evt   public.omni_comms_event_definition%ROWTYPE;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('view');
  v_row := public.omni_comms_priv_peb_load(p_id);

  IF v_row.department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(v_row.department_id, v_row.organization_id);
  END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_row.organization_id, v_row.department_id);

  SELECT * INTO v_evt FROM public.omni_comms_event_definition WHERE id = v_row.event_definition_id;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'organization_id', v_row.organization_id,
    'department_id', v_row.department_id,
    'caller_module_code', v_row.caller_module_code,
    'event_definition_id', v_row.event_definition_id,
    'event_code', v_evt.code,
    'event_name', v_evt.name,
    'event_module_code', v_evt.module_code,
    'event_status', v_evt.status,
    'allowed_modes', to_jsonb(v_row.allowed_modes),
    'status', v_row.status,
    'integration_reference', v_row.integration_reference,
    'lifecycle_reason', v_row.lifecycle_reason,
    'created_at', v_row.created_at,
    'updated_at', v_row.updated_at,
    'activated_at', v_row.activated_at,
    'suspended_at', v_row.suspended_at,
    'retired_at', v_row.retired_at
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_health_catalogue(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_events jsonb;
  v_templates jsonb;
  v_assembly jsonb;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  SELECT jsonb_build_object(
    'event_definitions', (SELECT count(*) FROM public.omni_comms_event_definition),
    'event_definitions_active', (SELECT count(*) FROM public.omni_comms_event_definition WHERE status = 'active'),
    'published_contracts', (SELECT count(*) FROM public.omni_comms_event_contract WHERE status = 'published'),
    'events_without_published_contract', (
      SELECT count(*) FROM public.omni_comms_event_definition d
       WHERE d.status = 'active'
         AND NOT EXISTS (SELECT 1 FROM public.omni_comms_event_contract c
                          WHERE c.event_definition_id = d.id AND c.status = 'published')),
    'active_event_routes', (
      SELECT count(*) FROM public.omni_comms_event_route r
       WHERE r.organization_id = p_organization_id
         AND r.lifecycle_state = 'active' AND r.is_enabled IS TRUE
         AND (p_department_id IS NULL OR r.department_id IS NOT DISTINCT FROM p_department_id)),
    'events_without_active_route', (
      SELECT count(*) FROM public.omni_comms_event_definition d
       WHERE d.status = 'active'
         AND NOT EXISTS (SELECT 1 FROM public.omni_comms_event_route r
                          WHERE r.event_definition_id = d.id
                            AND r.organization_id = p_organization_id
                            AND r.lifecycle_state = 'active' AND r.is_enabled IS TRUE)),
    'department_route_overrides', (
      SELECT count(*) FROM public.omni_comms_event_route r
       WHERE r.organization_id = p_organization_id AND r.department_id IS NOT NULL),
    'routes_with_unavailable_template', (
      SELECT count(*) FROM public.omni_comms_event_route r
       LEFT JOIN public.omni_comms_template_family f ON f.id = r.template_family_id
       WHERE r.organization_id = p_organization_id
         AND r.lifecycle_state = 'active'
         AND (r.template_family_id IS NULL OR f.id IS NULL OR f.status <> 'active'))
  ) INTO v_events;

  SELECT jsonb_build_object(
    'template_families', (
      SELECT count(*) FROM public.omni_comms_template_family f
       WHERE f.organization_id IS NOT DISTINCT FROM p_organization_id
          OR f.organization_id IS NULL),
    'template_families_active', (
      SELECT count(*) FROM public.omni_comms_template_family f
       WHERE f.status = 'active'
         AND (f.organization_id IS NOT DISTINCT FROM p_organization_id OR f.organization_id IS NULL)),
    'published_template_versions', (
      SELECT count(*) FROM public.omni_comms_template_version v
       JOIN public.omni_comms_template_family f ON f.id = v.template_family_id
       WHERE v.status = 'published'
         AND (f.organization_id IS NOT DISTINCT FROM p_organization_id OR f.organization_id IS NULL)),
    'families_without_published_version', (
      SELECT count(*) FROM public.omni_comms_template_family f
       WHERE f.status = 'active'
         AND (f.organization_id IS NOT DISTINCT FROM p_organization_id OR f.organization_id IS NULL)
         AND NOT EXISTS (SELECT 1 FROM public.omni_comms_template_version v
                          WHERE v.template_family_id = f.id AND v.status = 'published')),
    'templates_without_layout_selection', (
      SELECT count(*) FROM public.omni_comms_template_version v
       JOIN public.omni_comms_template_family f ON f.id = v.template_family_id
       WHERE v.status = 'published'
         AND (f.organization_id IS NOT DISTINCT FROM p_organization_id OR f.organization_id IS NULL)
         AND v.layout_id IS NULL
         AND coalesce(v.layout_selection_mode, 'none') <> 'inherit')
  ) INTO v_templates;

  SELECT jsonb_build_object(
    'layouts', (SELECT count(*) FROM public.core_template_layout WHERE is_active IS TRUE),
    'published_layout_versions', (
      SELECT count(*) FROM public.core_template_layout_version WHERE status = 'published'),
    'required_slots', (
      SELECT count(*) FROM public.core_comm_assignment a
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR a.department_id IS NOT DISTINCT FROM p_department_id)),
    'resolved_assets', (
      SELECT count(*) FROM public.core_comm_assignment a
       JOIN public.core_comm_asset s ON s.id = a.asset_id
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR a.department_id IS NOT DISTINCT FROM p_department_id)
         AND s.status = 'active' AND s.active_version_id IS NOT NULL),
    'unresolved_required_assets', (
      SELECT count(*) FROM public.core_comm_assignment a
       LEFT JOIN public.core_comm_asset s ON s.id = a.asset_id
       WHERE a.organization_id = p_organization_id
         AND (p_department_id IS NULL OR a.department_id IS NOT DISTINCT FROM p_department_id)
         AND (a.asset_id IS NULL OR s.id IS NULL OR s.status <> 'active' OR s.active_version_id IS NULL))
  ) INTO v_assembly;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'events', v_events,
    'templates', v_templates,
    'assembly', v_assembly,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_health_permissions(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_caps jsonb := '{}'::jsonb;
  v_action text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  FOREACH v_action IN ARRAY ARRAY[
    'view','operate','configure','author_templates','approve_templates','view_sensitive_content'
  ] LOOP
    v_caps := v_caps || jsonb_build_object(
      'omni_comms.' || v_action,
      CASE WHEN public.has_permission(v_uid, 'omni_comms', v_action)
           THEN 'granted' ELSE 'not_granted' END
    );
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'department_scope', CASE WHEN p_department_id IS NULL THEN 'organization_wide' ELSE 'department' END,
    'tenant_lookup_available', true,
    'capabilities', v_caps,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_health_runtime(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_since_hours integer DEFAULT 720)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_tables jsonb := '{}'::jsonb;
  v_functions jsonb := '{}'::jsonb;
  v_name text;
  v_counters jsonb;
  v_live boolean;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  FOREACH v_name IN ARRAY ARRAY[
    'omni_comms_request','omni_comms_recipient','omni_comms_message',
    'omni_comms_dispatch_job','omni_comms_delivery_attempt','omni_comms_message_event'
  ] LOOP
    v_tables := v_tables || jsonb_build_object(
      v_name, to_regclass('public.' || v_name) IS NOT NULL);
  END LOOP;

  FOREACH v_name IN ARRAY ARRAY[
    'omni_comms_priv_send_communication',
    'omni_comms_priv_runtime_resolution_snapshot',
    'omni_comms_priv_finalize_resolution',
    'omni_comms_priv_load_render_context',
    'omni_comms_priv_persist_rendered_messages',
    'omni_comms_ops_summary'
  ] LOOP
    v_functions := v_functions || jsonb_build_object(
      v_name,
      EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
               WHERE n.nspname = 'public' AND p.proname = v_name));
  END LOOP;

  v_counters := public.omni_comms_ops_summary(p_organization_id, p_department_id, p_since_hours);

  SELECT bool_or(coalesce(live_delivery_enabled, false)) INTO v_live
    FROM public.omni_comms_channel_setting
   WHERE organization_id = p_organization_id;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'runtime_tables', v_tables,
    'runtime_functions', v_functions,
    'counters', v_counters,
    'live_delivery_enabled', coalesce(v_live, false),
    'runnable_queue_enabled', false,
    'certification', jsonb_build_object(
      'resolution', 'not_certified',
      'rendering', 'not_certified',
      'overall', 'not_certified'
    ),
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_health_summary(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_since_hours integer DEFAULT 720)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_email jsonb;
  v_channels jsonb;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  v_email := public.omni_comms_email_config_summary(p_organization_id);

  -- Safe projection: counts and status only. secret_ref is never returned.
  v_channels := jsonb_build_object(
    'email_provider_registered', (v_email->'provider') IS NOT NULL AND (v_email->'provider') <> 'null'::jsonb,
    'email_provider_active', coalesce(v_email#>>'{provider,status}', '') = 'active',
    'provider_accounts', jsonb_array_length(coalesce(v_email->'provider_accounts', '[]'::jsonb)),
    'provider_accounts_active', (
      SELECT count(*) FROM jsonb_array_elements(coalesce(v_email->'provider_accounts','[]'::jsonb)) e
       WHERE e->>'status' = 'active'),
    'provider_accounts_credentials_configured', (
      SELECT count(*) FROM jsonb_array_elements(coalesce(v_email->'provider_accounts','[]'::jsonb)) e
       WHERE coalesce(e->>'secret_ref','') <> ''),
    'provider_accounts_healthy', (
      SELECT count(*) FROM jsonb_array_elements(coalesce(v_email->'provider_accounts','[]'::jsonb)) e
       WHERE e->>'health_state' = 'healthy'),
    'sender_identities', jsonb_array_length(coalesce(v_email->'sender_identities','[]'::jsonb)),
    'sender_identities_active', (
      SELECT count(*) FROM jsonb_array_elements(coalesce(v_email->'sender_identities','[]'::jsonb)) e
       WHERE e->>'status' = 'active'),
    'bindings', jsonb_array_length(coalesce(v_email->'bindings','[]'::jsonb)),
    'bindings_active', (
      SELECT count(*) FROM jsonb_array_elements(coalesce(v_email->'bindings','[]'::jsonb)) e
       WHERE e->>'status' = 'active'),
    'bindings_verified', (
      SELECT count(*) FROM jsonb_array_elements(coalesce(v_email->'bindings','[]'::jsonb)) e
       WHERE e->>'verification_status' = 'verified'),
    'email_channel_setting_present', (v_email->'channel_setting') IS NOT NULL
                                     AND (v_email->'channel_setting') <> 'null'::jsonb,
    'email_channel_enabled', coalesce((v_email#>>'{channel_setting,enabled}')::boolean, false),
    'email_send_ready', coalesce((v_email->>'email_send_ready')::boolean, false)
  );

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'permissions', public.omni_comms_health_permissions(p_organization_id, p_department_id),
    'catalogue', public.omni_comms_health_catalogue(p_organization_id, p_department_id),
    'runtime', public.omni_comms_health_runtime(p_organization_id, p_department_id, p_since_hours),
    'channels', v_channels,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_list_producer_event_bindings(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_rows  jsonb;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('view');

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC400 organization_required'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;

  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, p_organization_id, p_department_id);

  SELECT coalesce(jsonb_agg(x ORDER BY x ->> 'event_code'), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
             'id', b.id,
             'organization_id', b.organization_id,
             'department_id', b.department_id,
             'caller_module_code', b.caller_module_code,
             'event_definition_id', b.event_definition_id,
             'event_code', e.code,
             'event_name', e.name,
             'event_module_code', e.module_code,
             'event_status', e.status,
             'allowed_modes', to_jsonb(b.allowed_modes),
             'status', b.status,
             'integration_reference', b.integration_reference,
             'lifecycle_reason', b.lifecycle_reason,
             'updated_at', b.updated_at,
             'activated_at', b.activated_at
           ) AS x
    FROM public.omni_comms_producer_event_binding b
    JOIN public.omni_comms_event_definition e ON e.id = b.event_definition_id
    WHERE b.organization_id = p_organization_id
      AND (p_department_id IS NULL OR b.department_id = p_department_id)
      AND (p_status IS NULL OR b.status = p_status)
  ) s;

  RETURN jsonb_build_object('bindings', v_rows);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_ops_message_content(p_message_id uuid, p_organization_id uuid, p_reveal_sensitive boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_uid uuid; v_can boolean; v_reveal boolean; v_m record;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('operate');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 organisation_required' USING ERRCODE='P0001', DETAIL='organization_id';
  END IF;
  v_can := public.has_permission(v_uid, 'omni_comms', 'view_sensitive_content');
  v_reveal := v_can AND COALESCE(p_reveal_sensitive,false);

  SELECT * INTO v_m FROM public.omni_comms_message
   WHERE id = p_message_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='message';
  END IF;

  IF NOT v_reveal THEN
    IF NOT v_can THEN
      RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='view_sensitive_content';
    END IF;
    RAISE EXCEPTION 'OC412 reveal_not_requested' USING ERRCODE='P0001', DETAIL='reveal_sensitive';
  END IF;

  RETURN jsonb_build_object(
    'id', v_m.id,
    'channel', v_m.channel,
    'rendered_subject', v_m.rendered_subject,
    'rendered_text', v_m.rendered_text,
    'rendered_html', v_m.rendered_html,
    'rendered_checksum', v_m.rendered_checksum,
    'resolved_asset_manifest', v_m.resolved_asset_manifest,
    'channel_setting_snapshot', v_m.channel_setting_snapshot,
    'destination_snapshot', v_m.destination_snapshot,
    'blockers', v_m.blockers,
    'generated_at', now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_ops_request_detail(p_request_id uuid, p_organization_id uuid, p_reveal_sensitive boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_uid uuid; v_can_sensitive boolean; v_reveal boolean; v_req record;
  v_recipients jsonb; v_messages jsonb; v_jobs jsonb; v_attempts jsonb;
  v_timeline jsonb; v_warnings jsonb := '[]'::jsonb;
  v_seq_count bigint; v_seq_distinct bigint; v_seq_min bigint; v_seq_max bigint;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('operate');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 organisation_required' USING ERRCODE='P0001', DETAIL='organization_id';
  END IF;
  v_can_sensitive := public.has_permission(v_uid, 'omni_comms', 'view_sensitive_content');
  v_reveal := v_can_sensitive AND COALESCE(p_reveal_sensitive,false);

  SELECT * INTO v_req FROM public.omni_comms_request
   WHERE id = p_request_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='request';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', c.id,
      'recipient_type', c.recipient_type,
      'recipient_reference', CASE WHEN v_reveal THEN c.recipient_reference
                                  ELSE public.omni_comms_priv_mask_reference(c.recipient_reference) END,
      'display_name', CASE WHEN v_reveal THEN c.display_name
                           ELSE public.omni_comms_priv_mask_reference(c.display_name) END,
      'email_destination', CASE WHEN v_reveal THEN c.email_destination
                                ELSE public.omni_comms_priv_mask_email(c.email_destination) END,
      'phone_destination', CASE WHEN v_reveal THEN c.phone_destination
                                ELSE public.omni_comms_priv_mask_phone(c.phone_destination) END,
      'push_destination', CASE WHEN v_reveal THEN c.push_destination
                               WHEN c.push_destination IS NULL THEN NULL ELSE 'masked' END,
      'locale', c.locale,
      'eligibility_status', c.eligibility_status,
      'resolved_channels', c.resolved_channels,
      'blockers', c.blockers,
      'resolution_snapshot', CASE WHEN v_reveal THEN c.resolution_snapshot ELSE NULL END,
      'destinations_masked', NOT v_reveal,
      'created_at', c.created_at
    ) ORDER BY c.created_at, c.id), '[]'::jsonb) INTO v_recipients
    FROM public.omni_comms_recipient c WHERE c.request_id = p_request_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', m.id, 'recipient_id', m.recipient_id, 'channel', m.channel, 'status', m.status,
      'event_route_id', m.event_route_id,
      'template_family_id', m.template_family_id,
      'template_version_id', m.template_version_id,
      'template_family_code', tf.code,
      'template_version_number', tv.version_number,
      'layout_id', m.layout_id, 'layout_version_id', m.layout_version_id,
      'sender_identity_id', m.sender_identity_id,
      'sender_identity_code', si.code,
      'provider_id', m.provider_id, 'provider_account_id', m.provider_account_id,
      'resolved_asset_manifest', m.resolved_asset_manifest,
      'channel_setting_snapshot', m.channel_setting_snapshot,
      'destination_snapshot', CASE WHEN v_reveal THEN m.destination_snapshot ELSE NULL END,
      'rendered_checksum', m.rendered_checksum,
      'unresolved_tokens', m.unresolved_tokens,
      'unresolved_required_slots', m.unresolved_required_slots,
      'blockers', m.blockers,
      'dispatch_job_id', (SELECT j.id FROM public.omni_comms_dispatch_job j
                           WHERE j.message_id = m.id ORDER BY j.created_at LIMIT 1),
      'content_available', v_can_sensitive,
      'rendered_at', m.rendered_at,
      'created_at', m.created_at
    ) ORDER BY m.created_at, m.id), '[]'::jsonb) INTO v_messages
    FROM public.omni_comms_message m
    LEFT JOIN public.omni_comms_template_family tf ON tf.id = m.template_family_id
    LEFT JOIN public.omni_comms_template_version tv ON tv.id = m.template_version_id
    LEFT JOIN public.omni_comms_sender_identity si ON si.id = m.sender_identity_id
   WHERE m.request_id = p_request_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', j.id, 'message_id', j.message_id, 'channel', j.channel, 'mode', j.mode,
      'status', j.status, 'priority', j.priority, 'is_runnable', j.is_runnable,
      'hold_reason', j.hold_reason, 'scheduled_at', j.scheduled_at,
      'next_attempt_at', j.next_attempt_at, 'attempt_count', j.attempt_count,
      'max_attempts', j.max_attempts,
      'lease_state', CASE WHEN j.lease_expires_at IS NULL THEN 'unleased'
                          WHEN j.lease_expires_at > now() THEN 'leased'
                          ELSE 'lease_expired' END,
      'locked_at', j.locked_at,
      'created_at', j.created_at, 'updated_at', j.updated_at,
      'completed_at', j.completed_at, 'cancelled_at', j.cancelled_at
    ) ORDER BY j.created_at, j.id), '[]'::jsonb) INTO v_jobs
    FROM public.omni_comms_dispatch_job j WHERE j.request_id = p_request_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', a.id, 'dispatch_job_id', a.dispatch_job_id, 'message_id', a.message_id,
      'attempt_number', a.attempt_number, 'status', a.status,
      'provider_id', a.provider_id, 'provider_code', pr.code,
      'started_at', a.started_at, 'completed_at', a.completed_at,
      'latency_ms', a.latency_ms, 'response_code', a.response_code,
      'response_category', a.response_category, 'failure_category', a.failure_category,
      'is_retriable', a.is_retriable
    ) ORDER BY a.attempt_number, a.id), '[]'::jsonb) INTO v_attempts
    FROM public.omni_comms_delivery_attempt a
    LEFT JOIN public.omni_comms_provider pr ON pr.id = a.provider_id
   WHERE a.message_id IN (SELECT m.id FROM public.omni_comms_message m WHERE m.request_id = p_request_id)
      OR a.dispatch_job_id IN (SELECT j.id FROM public.omni_comms_dispatch_job j WHERE j.request_id = p_request_id);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', e.id, 'event_sequence', e.event_sequence, 'event_type', e.event_type,
      'message_id', e.message_id, 'status_before', e.status_before,
      'status_after', e.status_after, 'summary', e.summary,
      'safe_metadata', e.safe_metadata, 'actor_type', e.actor_type,
      'actor_id', CASE WHEN v_reveal THEN e.actor_id
                       ELSE public.omni_comms_priv_mask_reference(e.actor_id) END,
      'correlation_id', e.correlation_id,
      'created_at', e.created_at
    ) ORDER BY e.event_sequence, e.created_at), '[]'::jsonb) INTO v_timeline
    FROM public.omni_comms_message_event e WHERE e.request_id = p_request_id;

  SELECT count(*), count(DISTINCT e.event_sequence), min(e.event_sequence), max(e.event_sequence)
    INTO v_seq_count, v_seq_distinct, v_seq_min, v_seq_max
    FROM public.omni_comms_message_event e WHERE e.request_id = p_request_id;

  IF COALESCE(v_seq_count,0) > 0 THEN
    IF v_seq_distinct < v_seq_count THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
        'code','duplicate_sequence','message','Duplicate timeline sequence values were recorded.'));
    END IF;
    IF (v_seq_max - v_seq_min + 1) <> v_seq_distinct THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
        'code','sequence_gap','message','The timeline sequence contains gaps.'));
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM public.omni_comms_message_event e
              WHERE e.request_id = p_request_id AND e.message_id IS NOT NULL
                AND NOT EXISTS (SELECT 1 FROM public.omni_comms_message m WHERE m.id = e.message_id)) THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code','missing_reference','message','Timeline entries reference messages that no longer exist.'));
  END IF;

  IF EXISTS (SELECT 1 FROM public.omni_comms_dispatch_job j
              WHERE j.request_id = p_request_id AND j.is_runnable = true) THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code','runnable_job_present',
      'message','A runnable dispatch job exists while runtime certification is pending.'));
  END IF;

  RETURN jsonb_build_object(
    'request', jsonb_build_object(
      'id', v_req.id, 'organization_id', v_req.organization_id,
      'department_id', v_req.department_id, 'status', v_req.status, 'mode', v_req.mode,
      'event_definition_id', v_req.event_definition_id,
      'event_code', (SELECT code FROM public.omni_comms_event_definition WHERE id = v_req.event_definition_id),
      'event_name', (SELECT name FROM public.omni_comms_event_definition WHERE id = v_req.event_definition_id),
      'caller_module_code', v_req.caller_module_code,
      'caller_entity_type', v_req.caller_entity_type,
      'caller_entity_id', CASE WHEN v_reveal THEN v_req.caller_entity_id
                               ELSE public.omni_comms_priv_mask_reference(v_req.caller_entity_id) END,
      'correlation_id', v_req.correlation_id,
      'idempotency_key', v_req.idempotency_key,
      'idempotency_scope', v_req.idempotency_scope,
      'request_fingerprint', v_req.request_fingerprint,
      'requested_channels', v_req.requested_channels,
      'blockers', v_req.blockers,
      'payload_snapshot', CASE WHEN v_reveal THEN v_req.payload_snapshot ELSE NULL END,
      'payload_redacted', NOT v_reveal,
      'created_at', v_req.created_at, 'accepted_at', v_req.accepted_at,
      'completed_at', v_req.completed_at, 'failed_at', v_req.failed_at),
    'recipients', v_recipients,
    'messages', v_messages,
    'dispatch_jobs', v_jobs,
    'delivery_attempts', v_attempts,
    'timeline', v_timeline,
    'timeline_warnings', v_warnings,
    'can_view_sensitive', v_can_sensitive,
    'sensitive_visible', v_reveal,
    'generated_at', now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_ops_request_list(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_event_code text DEFAULT NULL::text, p_caller_module_code text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_has_blockers boolean DEFAULT NULL::boolean, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_limit integer; v_offset integer; v_q text; v_uuid uuid; v_rows jsonb; v_total bigint;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('operate');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 organisation_required' USING ERRCODE='P0001', DETAIL='organization_id';
  END IF;

  v_limit := LEAST(GREATEST(COALESCE(p_limit,25),1),100);
  v_offset := GREATEST(COALESCE(p_offset,0),0);
  v_q := NULLIF(btrim(COALESCE(p_search,'')),'');
  IF v_q IS NOT NULL AND length(v_q) > 200 THEN
    RAISE EXCEPTION 'OC422 search_too_long' USING ERRCODE='P0001', DETAIL='search';
  END IF;
  BEGIN
    v_uuid := v_q::uuid;
  EXCEPTION WHEN others THEN v_uuid := NULL;
  END;
  IF v_q IS NOT NULL THEN v_q := '%' || public.omni_comms_priv_escape_ilike(v_q) || '%'; END IF;

  WITH base AS (
    SELECT r.id
      FROM public.omni_comms_request r
      LEFT JOIN public.omni_comms_event_definition d ON d.id = r.event_definition_id
     WHERE r.organization_id = p_organization_id
       AND (p_department_id IS NULL OR r.department_id = p_department_id)
       AND (p_mode IS NULL OR r.mode = p_mode)
       AND (p_status IS NULL OR r.status = p_status)
       AND (p_event_code IS NULL OR d.code = p_event_code)
       AND (p_caller_module_code IS NULL OR r.caller_module_code = p_caller_module_code)
       AND (p_date_from IS NULL OR r.created_at >= p_date_from)
       AND (p_date_to IS NULL OR r.created_at <= p_date_to)
       AND (p_has_blockers IS NULL
            OR (p_has_blockers AND COALESCE(jsonb_array_length(r.blockers),0) > 0)
            OR (NOT p_has_blockers AND COALESCE(jsonb_array_length(r.blockers),0) = 0))
       AND (v_q IS NULL
            OR d.code ILIKE v_q
            OR r.caller_module_code ILIKE v_q
            OR r.correlation_id ILIKE v_q
            OR r.idempotency_key ILIKE v_q
            OR r.caller_entity_id ILIKE v_q
            OR (v_uuid IS NOT NULL AND r.id = v_uuid))
  )
  SELECT count(*) INTO v_total FROM base;

  WITH base AS (
    SELECT r.*, d.code AS event_code
      FROM public.omni_comms_request r
      LEFT JOIN public.omni_comms_event_definition d ON d.id = r.event_definition_id
     WHERE r.organization_id = p_organization_id
       AND (p_department_id IS NULL OR r.department_id = p_department_id)
       AND (p_mode IS NULL OR r.mode = p_mode)
       AND (p_status IS NULL OR r.status = p_status)
       AND (p_event_code IS NULL OR d.code = p_event_code)
       AND (p_caller_module_code IS NULL OR r.caller_module_code = p_caller_module_code)
       AND (p_date_from IS NULL OR r.created_at >= p_date_from)
       AND (p_date_to IS NULL OR r.created_at <= p_date_to)
       AND (p_has_blockers IS NULL
            OR (p_has_blockers AND COALESCE(jsonb_array_length(r.blockers),0) > 0)
            OR (NOT p_has_blockers AND COALESCE(jsonb_array_length(r.blockers),0) = 0))
       AND (v_q IS NULL
            OR d.code ILIKE v_q
            OR r.caller_module_code ILIKE v_q
            OR r.correlation_id ILIKE v_q
            OR r.idempotency_key ILIKE v_q
            OR r.caller_entity_id ILIKE v_q
            OR (v_uuid IS NOT NULL AND r.id = v_uuid))
     ORDER BY r.created_at DESC, r.id DESC
     LIMIT v_limit OFFSET v_offset
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', b.id,
      'created_at', b.created_at,
      'event_code', b.event_code,
      'mode', b.mode,
      'status', b.status,
      'caller_module_code', b.caller_module_code,
      'caller_entity_type', b.caller_entity_type,
      'department_id', b.department_id,
      'correlation_id', b.correlation_id,
      'recipient_count', (SELECT count(*) FROM public.omni_comms_recipient c WHERE c.request_id = b.id),
      'message_count', (SELECT count(*) FROM public.omni_comms_message m WHERE m.request_id = b.id),
      'held_job_count', (SELECT count(*) FROM public.omni_comms_dispatch_job j
                          WHERE j.request_id = b.id AND j.is_runnable = false),
      'blocker_count', COALESCE(jsonb_array_length(b.blockers),0)
    ) ORDER BY b.created_at DESC, b.id DESC), '[]'::jsonb)
    INTO v_rows FROM base b;

  RETURN jsonb_build_object(
    'items', v_rows,
    'total', COALESCE(v_total,0),
    'limit', v_limit,
    'offset', v_offset,
    'generated_at', now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_ops_summary(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_since_hours integer DEFAULT 720)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_since timestamptz;
  v_requests bigint; v_recipients bigint; v_messages bigint;
  v_held bigint; v_runnable bigint; v_attempts bigint;
  v_blocked bigint; v_dry bigint; v_processing bigint; v_failed bigint;
  v_by_status jsonb; v_by_mode jsonb; v_last timestamptz;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('operate');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 organisation_required' USING ERRCODE='P0001', DETAIL='organization_id';
  END IF;
  v_since := now() - make_interval(hours => LEAST(GREATEST(COALESCE(p_since_hours,720),1), 8760));

  SELECT count(*),
         count(*) FILTER (WHERE r.status IN ('blocked','completed_with_blockers')),
         count(*) FILTER (WHERE r.mode = 'dry_run' AND r.status IN ('completed','completed_with_blockers')),
         count(*) FILTER (WHERE r.status IN ('accepted','processing')),
         count(*) FILTER (WHERE r.status = 'failed'),
         max(r.created_at)
    INTO v_requests, v_blocked, v_dry, v_processing, v_failed, v_last
    FROM public.omni_comms_request r
   WHERE r.organization_id = p_organization_id
     AND r.created_at >= v_since
     AND (p_department_id IS NULL OR r.department_id = p_department_id);

  SELECT count(*) INTO v_recipients
    FROM public.omni_comms_recipient c
    JOIN public.omni_comms_request r ON r.id = c.request_id
   WHERE r.organization_id = p_organization_id
     AND r.created_at >= v_since
     AND (p_department_id IS NULL OR r.department_id = p_department_id);

  SELECT count(*) INTO v_messages
    FROM public.omni_comms_message m
   WHERE m.organization_id = p_organization_id
     AND m.created_at >= v_since
     AND (p_department_id IS NULL OR m.department_id = p_department_id);

  SELECT count(*) FILTER (WHERE j.is_runnable = false),
         count(*) FILTER (WHERE j.is_runnable = true)
    INTO v_held, v_runnable
    FROM public.omni_comms_dispatch_job j
    JOIN public.omni_comms_request r ON r.id = j.request_id
   WHERE j.organization_id = p_organization_id
     AND j.created_at >= v_since
     AND (p_department_id IS NULL OR r.department_id = p_department_id);

  SELECT count(*) INTO v_attempts
    FROM public.omni_comms_delivery_attempt a
   WHERE a.organization_id = p_organization_id
     AND a.created_at >= v_since;

  SELECT COALESCE(jsonb_object_agg(status, n), '{}'::jsonb) INTO v_by_status
    FROM (SELECT r.status, count(*) n FROM public.omni_comms_request r
           WHERE r.organization_id = p_organization_id AND r.created_at >= v_since
             AND (p_department_id IS NULL OR r.department_id = p_department_id)
           GROUP BY r.status) s;

  SELECT COALESCE(jsonb_object_agg(mode, n), '{}'::jsonb) INTO v_by_mode
    FROM (SELECT r.mode, count(*) n FROM public.omni_comms_request r
           WHERE r.organization_id = p_organization_id AND r.created_at >= v_since
             AND (p_department_id IS NULL OR r.department_id = p_department_id)
           GROUP BY r.mode) s;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'since', v_since,
    'requests', COALESCE(v_requests,0),
    'recipients', COALESCE(v_recipients,0),
    'messages', COALESCE(v_messages,0),
    'held_jobs', COALESCE(v_held,0),
    'runnable_jobs', COALESCE(v_runnable,0),
    'delivery_attempts', COALESCE(v_attempts,0),
    'blocked_requests', COALESCE(v_blocked,0),
    'completed_dry_runs', COALESCE(v_dry,0),
    'processing_requests', COALESCE(v_processing,0),
    'failed_requests', COALESCE(v_failed,0),
    'requests_by_status', v_by_status,
    'requests_by_mode', v_by_mode,
    'last_request_at', v_last,
    'generated_at', now());
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_peb_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_admin_dry_run_guard(p_actor_id uuid, p_mode text, p_channels text[], p_recipients jsonb, p_deployed_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_state text;
  v_posture jsonb;
  v_cert text;
  v_env text;
  v_commit text;
  v_commit_valid boolean;
  v_effective boolean;
  v_rev text;
  v_r jsonb;
  v_email text;
BEGIN
  IF p_actor_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'authentication_required');
  END IF;
  IF NOT public.has_permission(p_actor_id, 'omni_comms', 'operate') THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'permission_denied');
  END IF;

  v_state := public.omni_comms_priv_dry_run_gate_state();
  IF v_state <> 'enabled' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_disabled');
  END IF;

  v_posture := public.omni_comms_priv_certification_posture();
  v_cert := v_posture ->> 'certification_state';
  v_env := v_posture ->> 'environment';
  v_commit := lower(btrim(coalesce(v_posture ->> 'certified_commit', '')));
  v_commit_valid := coalesce((v_posture ->> 'certified_commit_valid')::boolean, false);
  v_effective := coalesce((v_posture ->> 'effective_certified')::boolean, false);
  v_rev := lower(btrim(coalesce(p_deployed_revision, '')));

  -- Environment must be exactly non_production.
  IF v_env <> 'non_production' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'non_production_environment_required');
  END IF;
  -- Certification must be exactly certified. Pending/unknown/failed block.
  IF v_cert = 'failed' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'runtime_certification_failed');
  END IF;
  IF v_cert <> 'certified' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'runtime_certification_required');
  END IF;
  -- Certified commit must be exactly 40 hexadecimal characters.
  IF NOT v_commit_valid OR v_commit !~ '^[0-9a-f]{40}$' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'runtime_certified_commit_invalid');
  END IF;
  -- The certification record must be complete: workflow run id and timestamp.
  IF NOT v_effective THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'runtime_certification_record_incomplete');
  END IF;
  -- Deployed revision must be exactly 40 hexadecimal characters.
  IF v_rev !~ '^[0-9a-f]{40}$' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'runtime_revision_unverified');
  END IF;
  -- Exact full-SHA equality. No prefix matching.
  IF v_rev <> v_commit THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'runtime_revision_mismatch');
  END IF;

  IF coalesce(p_mode, '') <> 'dry_run' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_mode_required');
  END IF;

  IF p_channels IS NULL OR array_length(p_channels, 1) IS DISTINCT FROM 1
     OR p_channels[1] <> 'email' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_channel_invalid');
  END IF;

  IF p_recipients IS NULL OR jsonb_typeof(p_recipients) <> 'array'
     OR jsonb_array_length(p_recipients) <> 1 THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_recipient_limit');
  END IF;

  v_r := p_recipients -> 0;
  IF jsonb_typeof(v_r) <> 'object' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_recipient_invalid');
  END IF;
  IF coalesce(v_r ->> 'recipientType', '') <> 'synthetic_test' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_recipient_invalid');
  END IF;

  v_email := lower(btrim(coalesce(v_r ->> 'email', '')));
  IF v_email = '' OR v_email !~ '^[^@[:space:]]+@example\.com$' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'admin_dry_run_domain_required');
  END IF;

  RETURN jsonb_build_object('allowed', true, 'code', NULL);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_apply_account_secret_refs(p_actor_id uuid, p_account_id uuid, p_provider_id uuid, p_refs jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_item jsonb; v_purpose text; v_ref text; v_pattern text; v_req boolean;
        v_before jsonb; v_after jsonb; v_seen text[] := ARRAY[]::text[];
BEGIN
  IF p_refs IS NULL OR jsonb_typeof(p_refs) <> 'array' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_refs_array_required';
  END IF;

  SELECT COALESCE(jsonb_object_agg(purpose, secret_ref), '{}'::jsonb) INTO v_before
    FROM public.omni_comms_provider_account_secret_ref WHERE provider_account_id=p_account_id;

  FOR v_item IN SELECT jsonb_array_elements(p_refs) LOOP
    v_purpose := btrim(COALESCE(v_item->>'purpose',''));
    v_ref     := btrim(COALESCE(v_item->>'secret_ref',''));
    IF v_purpose = '' OR v_ref = '' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_ref_empty';
    END IF;
    IF v_purpose = ANY(v_seen) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='duplicate_credential_purpose';
    END IF;
    v_seen := v_seen || v_purpose;

    SELECT secret_ref_pattern, required INTO v_pattern, v_req
      FROM public.omni_comms_provider_credential_requirement
     WHERE provider_id=p_provider_id AND purpose=v_purpose;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_credential_purpose';
    END IF;
    IF NOT public.omni_comms_priv_is_secret_ref_name(v_ref) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_ref_pattern';
    END IF;
    IF v_ref !~ v_pattern THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_ref_pattern';
    END IF;
  END LOOP;

  -- every required purpose must be supplied
  IF EXISTS (SELECT 1 FROM public.omni_comms_provider_credential_requirement r
              WHERE r.provider_id=p_provider_id AND r.required
                AND NOT (r.purpose = ANY(v_seen))) THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='missing_required_credential';
  END IF;

  DELETE FROM public.omni_comms_provider_account_secret_ref
   WHERE provider_account_id=p_account_id
     AND NOT (purpose = ANY(v_seen));

  FOR v_item IN SELECT jsonb_array_elements(p_refs) LOOP
    INSERT INTO public.omni_comms_provider_account_secret_ref
      (provider_account_id, purpose, secret_ref, created_by, updated_by)
    VALUES (p_account_id, btrim(v_item->>'purpose'), btrim(v_item->>'secret_ref'), p_actor_id, p_actor_id)
    ON CONFLICT (provider_account_id, purpose) DO UPDATE
      SET secret_ref=EXCLUDED.secret_ref, updated_by=p_actor_id, updated_at=now()
      WHERE public.omni_comms_provider_account_secret_ref.secret_ref IS DISTINCT FROM EXCLUDED.secret_ref;
  END LOOP;

  SELECT COALESCE(jsonb_object_agg(purpose, secret_ref), '{}'::jsonb) INTO v_after
    FROM public.omni_comms_provider_account_secret_ref WHERE provider_account_id=p_account_id;

  RETURN v_before IS DISTINCT FROM v_after;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_authorize_producer_event(p_actor_id uuid, p_organization_id uuid, p_department_id uuid, p_caller_module_code text, p_event_code text, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_auth jsonb;
  v_module     text;
  v_mode       text;
  v_event      public.omni_comms_event_definition%ROWTYPE;
  v_binding    public.omni_comms_producer_event_binding%ROWTYPE;
BEGIN
  v_actor_auth := public.omni_comms_priv_authorize_runtime_actor(
    p_actor_id, p_organization_id, p_department_id, p_caller_module_code
  );

  IF coalesce((v_actor_auth ->> 'allowed')::boolean, false) IS NOT TRUE THEN
    RETURN v_actor_auth;
  END IF;

  v_module := upper(btrim(coalesce(p_caller_module_code, '')));
  v_mode   := lower(btrim(coalesce(p_mode, '')));

  IF v_mode NOT IN ('dry_run', 'shadow', 'queued') THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'mode_invalid');
  END IF;

  SELECT * INTO v_event
  FROM public.omni_comms_event_definition
  WHERE code = btrim(coalesce(p_event_code, ''));

  IF v_event.id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'event_not_found');
  END IF;

  IF v_event.status <> 'active' THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'event_not_active');
  END IF;

  -- The bounded administration dry-run caller keeps its own synthetic guard
  -- and is intentionally exempt from the business producer binding.
  IF v_module = 'OMNI_COMMS_ADMIN_DRY_RUN' THEN
    IF v_mode <> 'dry_run' THEN
      RETURN jsonb_build_object('allowed', false, 'code', 'producer_mode_not_authorized');
    END IF;
    RETURN jsonb_build_object('allowed', true, 'code', 'admin_dry_run_caller', 'binding_id', NULL);
  END IF;

  -- Every other caller (including OMNI_COMMS_DIRECT and PLATFORM) requires an
  -- explicit active producer-event binding. Department-scoped bindings win
  -- over organisation-wide bindings; no wildcard or cross-module allowance.
  SELECT * INTO v_binding
  FROM public.omni_comms_producer_event_binding b
  WHERE b.status = 'active'
    AND b.organization_id = p_organization_id
    AND b.caller_module_code = v_module
    AND b.event_definition_id = v_event.id
    AND (b.department_id IS NULL OR b.department_id = p_department_id)
  ORDER BY (b.department_id IS NOT NULL) DESC
  LIMIT 1;

  IF v_binding.id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'producer_event_not_authorized');
  END IF;

  IF v_binding.department_id IS NOT NULL AND v_binding.department_id IS DISTINCT FROM p_department_id THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'producer_event_not_authorized');
  END IF;

  IF NOT (v_mode = ANY (v_binding.allowed_modes)) THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'producer_mode_not_authorized');
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'code', 'authorized',
    'binding_id', v_binding.id,
    'event_definition_id', v_event.id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_authorize_runtime_actor(p_actor_id uuid, p_organization_id uuid, p_department_id uuid, p_caller_module_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_module      text;
  v_reg         public.omni_comms_caller_module_registry%ROWTYPE;
  v_org_ok      boolean := false;
  v_privileged  boolean := false;
  v_dept_org    uuid;
  v_dept_active boolean;
BEGIN
  IF p_actor_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'authentication_required');
  END IF;

  IF p_organization_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'organization_required');
  END IF;

  IF NOT public.has_permission(p_actor_id, 'omni_comms', 'operate') THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'permission_denied');
  END IF;

  v_module := upper(btrim(coalesce(p_caller_module_code, '')));
  SELECT * INTO v_reg
  FROM public.omni_comms_caller_module_registry
  WHERE module_code = v_module
    AND is_active = true;

  IF v_module = '' OR v_reg.module_code IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'caller_module_not_registered');
  END IF;

  IF NOT public.has_permission(p_actor_id, v_reg.permission_module, v_reg.permission_action) THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'permission_denied');
  END IF;

  v_privileged := public.is_admin(p_actor_id)
                  OR public.has_permission(p_actor_id, 'omni_comms', 'administer');

  SELECT true INTO v_org_ok
  FROM public.core_organization o
  WHERE o.id = p_organization_id
    AND coalesce(lower(o.status), 'active') NOT IN ('retired', 'archived', 'deleted')
  LIMIT 1;

  IF NOT coalesce(v_org_ok, false) THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'organization_access_denied');
  END IF;

  IF NOT v_privileged THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.core_staff_assignments a
      JOIN public.core_department d ON d.id = a.department_id
      WHERE a.user_id = p_actor_id
        AND a.is_active = true
        AND a.assignment_status = 'ACTIVE'
        AND (a.effective_to IS NULL OR a.effective_to >= CURRENT_DATE)
        AND d.organization_id = p_organization_id
    ) THEN
      RETURN jsonb_build_object('allowed', false, 'code', 'organization_access_denied');
    END IF;
  END IF;

  IF p_department_id IS NOT NULL THEN
    SELECT d.organization_id, coalesce(d.is_active, true)
      INTO v_dept_org, v_dept_active
    FROM public.core_department d
    WHERE d.id = p_department_id;

    IF v_dept_org IS NULL THEN
      RETURN jsonb_build_object('allowed', false, 'code', 'department_access_denied');
    END IF;

    IF v_dept_org <> p_organization_id THEN
      RETURN jsonb_build_object('allowed', false, 'code', 'department_organization_mismatch');
    END IF;

    IF NOT v_dept_active THEN
      RETURN jsonb_build_object('allowed', false, 'code', 'department_access_denied');
    END IF;

    IF NOT v_privileged THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.core_staff_assignments a
        WHERE a.user_id = p_actor_id
          AND a.department_id = p_department_id
          AND a.is_active = true
          AND a.assignment_status = 'ACTIVE'
          AND (a.effective_to IS NULL OR a.effective_to >= CURRENT_DATE)
      ) THEN
        RETURN jsonb_build_object('allowed', false, 'code', 'department_access_denied');
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object('allowed', true, 'code', 'ok');
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_binding_endpoint_requirement(p_channel text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT CASE p_channel
    WHEN 'email'    THEN 'required'
    WHEN 'sms'      THEN 'optional'
    WHEN 'whatsapp' THEN 'required'
    WHEN 'push'     THEN 'forbidden'
    WHEN 'in_app'   THEN 'required'
    WHEN 'print'    THEN 'required'
    ELSE 'forbidden' END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_binding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_sender_org uuid; v_sender_channel text;
  v_account_org uuid; v_provider_id uuid; v_provider_channel text;
BEGIN
  SELECT organization_id, channel INTO v_sender_org, v_sender_channel
    FROM public.omni_comms_sender_identity WHERE id = NEW.sender_identity_id;
  SELECT pa.organization_id, pa.provider_id, p.channel
    INTO v_account_org, v_provider_id, v_provider_channel
    FROM public.omni_comms_provider_account pa
    JOIN public.omni_comms_provider p ON p.id = pa.provider_id
    WHERE pa.id = NEW.provider_account_id;

  IF v_sender_org IS NULL OR v_account_org IS NULL THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding referenced rows missing' USING ERRCODE = 'P0001';
  END IF;
  IF v_sender_org <> v_account_org THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding organisation mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF v_sender_channel <> v_provider_channel THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding channel mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.channel IS DISTINCT FROM v_sender_channel THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding channel mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_sender_org THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding organisation mismatch' USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_sender_provider_binding must be inserted in draft status'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('draft','active','disabled','retired') THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding invalid status %', NEW.status USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status = 'retired' AND NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding retired status is terminal' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status = 'draft' AND OLD.status <> 'draft' THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding cannot revert to draft' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status = 'draft' AND NEW.status = 'disabled' THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding draft cannot be disabled' USING ERRCODE = 'P0001';
  END IF;

  IF NEW.status = 'active' AND OLD.status = 'draft' AND NEW.activated_at IS NULL THEN
    NEW.activated_at := now();
  END IF;
  IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS NULL THEN
    RAISE EXCEPTION 'omni_comms_sender_provider_binding activated_at cannot be cleared' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status = 'retired' AND OLD.status <> 'retired' THEN
    IF NEW.retired_at IS NULL THEN NEW.retired_at := now(); END IF;
    IF NEW.retirement_reason IS NULL OR char_length(btrim(NEW.retirement_reason)) < 1 THEN
      RAISE EXCEPTION 'omni_comms_sender_provider_binding retirement requires a reason' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF OLD.status = 'retired' THEN
    IF OLD.retired_at IS DISTINCT FROM NEW.retired_at
       OR OLD.retired_by IS DISTINCT FROM NEW.retired_by
       OR OLD.retirement_reason IS DISTINCT FROM NEW.retirement_reason THEN
      RAISE EXCEPTION 'omni_comms_sender_provider_binding retirement metadata is immutable' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF OLD.status IN ('active','disabled','retired') THEN
    IF OLD.sender_identity_id <> NEW.sender_identity_id
       OR OLD.provider_account_id <> NEW.provider_account_id
       OR OLD.channel_endpoint_id IS DISTINCT FROM NEW.channel_endpoint_id THEN
      RAISE EXCEPTION 'omni_comms_sender_provider_binding identity is immutable after activation'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_binding_verified_at_default()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.verification_status = 'verified' AND NEW.verified_at IS NULL THEN
    NEW.verified_at := now();
  END IF;
  IF NEW.verification_status IN ('unverified', 'pending') THEN
    NEW.verified_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_bootstrap_employer_registration_pilot(p_actor_id uuid, p_organization_code text DEFAULT 'SKN-SSB'::text, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  k_event_code    CONSTANT text := 'REGISTRATION.EMPLOYER.APPLICATION_SUBMITTED';
  k_module_code   CONSTANT text := 'EMPLOYER_REGISTRATION';
  k_family_code   CONSTANT text := 'pilot_registration_employer_application_submitted';
  k_locale        CONSTANT text := 'en-US';
  v_actions  jsonb := '[]'::jsonb;
  v_org      uuid;
  v_dept     uuid;
  v_event    uuid;
  v_family   uuid;
  v_version  uuid;
  v_layout   uuid;
  v_layout_version uuid;
  v_sender   uuid;
  v_route    uuid;
  v_binding  uuid;
  v_actor    uuid := p_actor_id;
  v_schema   jsonb;
  v_sample   jsonb;
  v_content  jsonb;
  v_checksum text;
  v_id       uuid;
  v_module_ok boolean;
BEGIN
  PERFORM public.omni_comms_priv_pilot_assert_non_production();

  SELECT id INTO v_org FROM public.core_organization WHERE org_code = p_organization_code;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found'
      USING ERRCODE = 'P0001', DETAIL = 'organization_not_found';
  END IF;

  IF v_actor IS NULL THEN
    SELECT created_by INTO v_actor FROM public.omni_comms_event_definition
     WHERE created_by IS NOT NULL ORDER BY created_at LIMIT 1;
  END IF;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input'
      USING ERRCODE = 'P0001', DETAIL = 'bootstrap_actor_required';
  END IF;

  SELECT id INTO v_dept FROM public.core_department
   WHERE organization_id = v_org AND code = 'REGISTRATION';
  SELECT id INTO v_sender FROM public.omni_comms_sender_identity
   WHERE organization_id = v_org AND code = 'ref_sender_registration';
  SELECT l.id, v.id
    INTO v_layout, v_layout_version
  FROM public.core_template_layout l
  JOIN public.core_template_layout_version v ON v.layout_id = l.id
 WHERE l.code = 'OMNI_REF_EMAIL'
   AND l.is_active
   AND v.status = 'published'
 ORDER BY v.version_number DESC
 LIMIT 1;

  SELECT EXISTS (
    SELECT 1 FROM public.omni_comms_caller_module_registry
     WHERE module_code = k_module_code AND is_active = true
  ) INTO v_module_ok;

  -- Prerequisite gate: apply mode is all-or-nothing. A missing prerequisite
  -- must abort BEFORE any object is created, so the pilot can never be left
  -- partially active.
  IF p_apply THEN
    IF v_dept IS NULL THEN
      RAISE EXCEPTION 'OC412 invalid_state'
        USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_department_missing';
    END IF;
    IF NOT v_module_ok THEN
      RAISE EXCEPTION 'OC412 invalid_state'
        USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_caller_module_inactive';
    END IF;
    IF v_sender IS NULL THEN
      RAISE EXCEPTION 'OC412 invalid_state'
        USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_sender_identity_missing';
    END IF;
    IF v_layout IS NULL OR v_layout_version IS NULL THEN
      RAISE EXCEPTION 'OC412 invalid_state'
        USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_layout_missing';
    END IF;
  END IF;

  v_schema := jsonb_build_object(
    '$schema', 'https://json-schema.org/draft/2020-12/schema',
    'type', 'object',
    'additionalProperties', false,
    'required', jsonb_build_array('reference', 'subjectName', 'submissionStatus', 'submittedAt'),
    'properties', jsonb_build_object(
      'reference',        jsonb_build_object('type', 'string', 'maxLength', 64),
      'subjectName',      jsonb_build_object('type', 'string', 'maxLength', 160),
      'submissionStatus', jsonb_build_object('type', 'string', 'maxLength', 64),
      'submittedAt',      jsonb_build_object('type', 'string', 'maxLength', 40)
    )
  );
  v_sample := jsonb_build_object(
    'reference', 'ER-004512',
    'subjectName', 'Frigate Bay Retail Ltd',
    'submissionStatus', 'Pending review',
    'submittedAt', '2026-08-01T08:00:00.000Z'
  );
  v_content := jsonb_build_object(
    'subject', 'Application received - employer registration {{payload.reference}}',
    'html', '<p>{{payload.subjectName}},</p><p>We have received your employer registration application. Reference <strong>{{payload.reference}}</strong>, submitted on {{payload.submittedAt}}.</p><p>Current status: {{payload.submissionStatus}}. This message confirms receipt of your application only. Your application has not been assessed, no registration decision has been made, and no effective date has been set.</p><p>Social Security Board</p>',
    'text', '{{payload.subjectName}}: we have received your employer registration application {{payload.reference}}, submitted on {{payload.submittedAt}}. Current status: {{payload.submissionStatus}}. This confirms receipt of your application only; it has not been assessed, no decision has been made and no effective date has been set.'
  );

  -- event definition ---------------------------------------------------
  SELECT id INTO v_event FROM public.omni_comms_event_definition WHERE code = k_event_code;
  IF v_event IS NOT NULL THEN
    v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',k_event_code,'action','existing');
  ELSIF NOT p_apply THEN
    v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',k_event_code,'action','planned');
  ELSE
    INSERT INTO public.omni_comms_event_definition
      (code, module_code, entity_type, name, description, communication_class, default_priority, status, created_by, updated_by)
    VALUES (k_event_code, 'REGISTRATION', 'EMPLOYER',
            'Employer Registration Application Submitted',
            'Acknowledges receipt of an employer registration application. Receipt only: no assessment, decision, activation or effective date is implied.',
            'transactional', 'normal', 'draft', v_actor, v_actor)
    RETURNING id INTO v_event;
    UPDATE public.omni_comms_event_definition
       SET status = 'active', updated_at = now(), updated_by = v_actor
     WHERE id = v_event;
    v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',k_event_code,'action','created');
  END IF;

  IF v_event IS NULL THEN
    RETURN jsonb_build_object('applied', p_apply, 'organization_id', v_org, 'actions', v_actions);
  END IF;

  -- published contract v1 ----------------------------------------------
  IF EXISTS (SELECT 1 FROM public.omni_comms_event_contract
              WHERE event_definition_id = v_event AND version_number = 1) THEN
    v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',k_event_code || ':v1','action','existing');
  ELSIF NOT p_apply THEN
    v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',k_event_code || ':v1','action','planned');
  ELSE
    PERFORM public.omni_comms_priv_validate_schema(v_schema, v_sample);
    INSERT INTO public.omni_comms_event_contract
      (event_definition_id, version_number, json_schema, sample_payload, status, created_by, updated_by)
    VALUES (v_event, 1, v_schema, v_sample, 'draft', v_actor, v_actor)
    RETURNING id INTO v_id;
    v_checksum := public.omni_comms_priv_compute_checksum(k_event_code, 1, v_schema);
    UPDATE public.omni_comms_event_contract
       SET status = 'published', checksum = v_checksum, published_at = now(), published_by = v_actor,
           updated_at = now(), updated_by = v_actor
     WHERE id = v_id;
    v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',k_event_code || ':v1','action','created');
  END IF;

  -- active template family ---------------------------------------------
  SELECT id INTO v_family FROM public.omni_comms_template_family WHERE code = k_family_code;
  IF v_family IS NOT NULL THEN
    v_actions := v_actions || jsonb_build_object('object_type','template_family','key',k_family_code,'action','existing');
  ELSIF NOT p_apply THEN
    v_actions := v_actions || jsonb_build_object('object_type','template_family','key',k_family_code,'action','planned');
  ELSE
    INSERT INTO public.omni_comms_template_family
      (code, name, description, scope_type, organization_id, department_id, event_definition_id, status, created_by, updated_by)
    VALUES (k_family_code, 'Employer Registration Application Submitted Templates',
            'Pilot templates for ' || k_event_code, 'event', v_org, NULL, v_event, 'draft', v_actor, v_actor)
    RETURNING id INTO v_family;
    UPDATE public.omni_comms_template_family
       SET status = 'active', activated_at = now(), activated_by = v_actor,
           updated_at = now(), updated_by = v_actor
     WHERE id = v_family;
    v_actions := v_actions || jsonb_build_object('object_type','template_family','key',k_family_code,'action','created');
  END IF;

  -- published email template version ------------------------------------
  IF v_family IS NOT NULL THEN
    SELECT id INTO v_version FROM public.omni_comms_template_version
     WHERE template_family_id = v_family AND channel = 'email'
       AND locale = k_locale AND version_number = 1;
  END IF;

  IF v_version IS NOT NULL THEN
    v_actions := v_actions || jsonb_build_object('object_type','template_version','key',k_family_code || ':email','action','existing');
  ELSIF NOT p_apply THEN
    v_actions := v_actions || jsonb_build_object('object_type','template_version','key',k_family_code || ':email','action','planned');
  ELSE
    PERFORM public.omni_comms_priv_validate_channel_content('email', v_content);
    INSERT INTO public.omni_comms_template_version
      (template_family_id, version_number, channel, locale, content, status,
       layout_selection_mode, layout_id, pinned_layout_version_id, created_by, updated_by)
    VALUES (v_family, 1, 'email', k_locale, v_content, 'draft',
            'pinned', v_layout, v_layout_version, NULL, v_actor)
    RETURNING id INTO v_version;

    v_checksum := public.omni_comms_priv_compute_template_checksum(
      k_family_code, 1, 'email', k_locale, v_content);

    UPDATE public.omni_comms_template_version
       SET status = 'approved', checksum = v_checksum, approved_at = now(), approved_by = v_actor,
           updated_at = now(), updated_by = v_actor
     WHERE id = v_version;
    UPDATE public.omni_comms_template_version
       SET status = 'published', published_at = now(), published_by = v_actor,
           updated_at = now(), updated_by = v_actor
     WHERE id = v_version;

    v_actions := v_actions || jsonb_build_object('object_type','template_version','key',k_family_code || ':email','action','created');
  END IF;

  -- active email route ---------------------------------------------------
  SELECT id INTO v_route FROM public.omni_comms_event_route
   WHERE organization_id = v_org
     AND department_id IS NOT DISTINCT FROM v_dept
     AND event_definition_id = v_event
     AND channel = 'email';

  IF v_route IS NOT NULL THEN
    v_actions := v_actions || jsonb_build_object('object_type','event_route','key',k_event_code || ':email','action','existing');
  ELSIF NOT p_apply THEN
    v_actions := v_actions || jsonb_build_object('object_type','event_route','key',k_event_code || ':email','action','planned');
  ELSE
    INSERT INTO public.omni_comms_event_route
      (organization_id, department_id, event_definition_id, channel, is_required, is_enabled, priority,
       template_family_id, sender_identity_id, sender_resolution_policy, preference_policy, lifecycle_state,
       created_by, updated_by)
    VALUES (v_org, v_dept, v_event, 'email', false, true, 100,
            v_family, v_sender, 'explicit', 'honour', 'draft', v_actor, v_actor)
    RETURNING id INTO v_route;
    UPDATE public.omni_comms_event_route
       SET lifecycle_state = 'active', activated_at = now(), activated_by = v_actor,
           updated_at = now(), updated_by = v_actor
     WHERE id = v_route;
    v_actions := v_actions || jsonb_build_object('object_type','event_route','key',k_event_code || ':email','action','created');
  END IF;

  -- caller module registration -------------------------------------------
  v_actions := v_actions || jsonb_build_object(
    'object_type','caller_module','key',k_module_code,
    'action', CASE WHEN v_module_ok THEN 'existing' ELSE 'missing' END);

  -- producer binding (dry_run + shadow only) ------------------------------
  SELECT id INTO v_binding FROM public.omni_comms_producer_event_binding
   WHERE organization_id = v_org
     AND caller_module_code = k_module_code
     AND event_definition_id = v_event
     AND status <> 'retired'
   LIMIT 1;

  IF v_binding IS NOT NULL THEN
    v_actions := v_actions || jsonb_build_object('object_type','producer_binding','key',k_event_code,'action','existing');
  ELSIF NOT p_apply THEN
    v_actions := v_actions || jsonb_build_object('object_type','producer_binding','key',k_event_code,'action','planned');
  ELSE
    INSERT INTO public.omni_comms_producer_event_binding
      (organization_id, department_id, caller_module_code, event_definition_id,
       allowed_modes, status, integration_reference, created_by, updated_by,
       activated_at, activated_by)
    VALUES (v_org, NULL, k_module_code, v_event,
            ARRAY['dry_run','shadow']::text[], 'active',
            'build4a_pilot_employer_registration_application_submitted', v_actor, v_actor,
            now(), v_actor)
    RETURNING id INTO v_binding;
    v_actions := v_actions || jsonb_build_object('object_type','producer_binding','key',k_event_code,'action','created');
  END IF;

  -- Completion gate: in apply mode the pilot must be whole, or nothing at
  -- all. Any missing piece aborts and rolls the whole bootstrap back.
  IF p_apply THEN
    IF v_event IS NULL
       OR v_family IS NULL
       OR v_version IS NULL
       OR v_route IS NULL
       OR v_binding IS NULL
       OR NOT EXISTS (SELECT 1 FROM public.omni_comms_event_contract
                       WHERE event_definition_id = v_event
                         AND version_number = 1 AND status = 'published')
       OR NOT EXISTS (SELECT 1 FROM public.omni_comms_template_version
                       WHERE id = v_version AND status = 'published')
       OR NOT EXISTS (SELECT 1 FROM public.omni_comms_event_route
                       WHERE id = v_route AND lifecycle_state = 'active' AND is_enabled)
       OR NOT EXISTS (SELECT 1 FROM public.omni_comms_producer_event_binding
                       WHERE id = v_binding AND status = 'active')
    THEN
      RAISE EXCEPTION 'OC412 invalid_state'
        USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_incomplete_configuration';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'applied', p_apply,
    'organization_code', p_organization_code,
    'organization_id', v_org,
    'event_code', k_event_code,
    'event_definition_id', v_event,
    'caller_module_code', k_module_code,
    'template_family_id', v_family,
    'template_version_id', v_version,
    'layout_id', v_layout,
    'layout_version_id', v_layout_version,
    'event_route_id', v_route,
    'producer_event_binding_id', v_binding,
    'actions', v_actions
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_certification_posture()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_cert jsonb;
  v_state text;
  v_commit text;
  v_env text;
  v_commit_valid boolean;
BEGIN
  -- Certification state and certified commit have EXACTLY ONE authoritative
  -- source: the protected singleton certification record. No GUC, no fallback.
  v_cert := public.omni_comms_priv_runtime_certification();
  v_state := coalesce(v_cert->>'certification_state', 'pending');
  v_commit := lower(btrim(coalesce(v_cert->>'certified_commit', '')));

  -- Environment has EXACTLY ONE authoritative source: the protected
  -- singleton configuration record. There is no GUC and no fallback.
  v_env := public.omni_comms_priv_runtime_environment();

  IF v_state NOT IN ('certified', 'pending', 'failed') THEN
    v_state := 'pending';
  END IF;

  IF v_env NOT IN ('production', 'non_production') THEN
    v_env := 'unknown';
  END IF;

  v_commit_valid := v_commit ~ '^[0-9a-f]{40}$';
  IF NOT v_commit_valid THEN
    v_commit := NULL;
  END IF;

  RETURN jsonb_build_object(
    'certification_state', v_state,
    'certified_commit', v_commit,
    'certified_commit_valid', v_commit_valid,
    'workflow_run_id', v_cert->>'workflow_run_id',
    'certified_at', v_cert->>'certified_at',
    'environment', v_env,
    'effective_certified', (v_state = 'certified' AND v_commit_valid AND coalesce((v_cert->>'effective_certified')::boolean, false))
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_account_lifecycle(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_reason text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_before public.omni_comms_provider_account%ROWTYPE;
        v_after  public.omni_comms_provider_account%ROWTYPE;
        v_prov public.omni_comms_provider%ROWTYPE; v_action text; v_reason text;
BEGIN
  v_action := btrim(COALESCE(p_action,''));
  IF v_action NOT IN ('activate','disable','retire') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_lifecycle_action'; END IF;

  SELECT * INTO v_before FROM public.omni_comms_provider_account WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_account'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_before.organization_id, NULL);
  IF v_before.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='reference_account_non_operational'; END IF;
  IF p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;
  IF v_before.status = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='retired_is_terminal'; END IF;

  SELECT * INTO v_prov FROM public.omni_comms_provider WHERE id=v_before.provider_id;

  IF v_action='activate' THEN
    IF v_before.status NOT IN ('draft','disabled') THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft_or_disabled'; END IF;
    IF v_prov.status <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='provider_not_active'; END IF;
    IF EXISTS (SELECT 1 FROM public.omni_comms_provider_credential_requirement r
                WHERE r.provider_id=v_before.provider_id AND r.required
                  AND NOT EXISTS (SELECT 1 FROM public.omni_comms_provider_account_secret_ref s
                                   WHERE s.provider_account_id=v_before.id AND s.purpose=r.purpose)) THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='missing_required_credential'; END IF;
    IF v_prov.adapter_key='resend' AND v_before.verification_status IS DISTINCT FROM 'verified' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='provider_verification_required'; END IF;
    -- verification state is preserved on reactivation
    UPDATE public.omni_comms_provider_account
       SET status='active', activated_at=now(), activated_by=p_actor_id,
           updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSIF v_action='disable' THEN
    IF v_before.status <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_active'; END IF;
    UPDATE public.omni_comms_provider_account
       SET status='disabled', updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSE
    v_reason := NULLIF(btrim(COALESCE(p_reason,'')),'');
    IF v_reason IS NULL OR char_length(v_reason) > 2000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retirement_reason_required'; END IF;
    UPDATE public.omni_comms_provider_account
       SET status='retired', retired_at=now(), retired_by=p_actor_id,
           retirement_reason=v_reason, updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;
  END IF;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id, v_action, 'provider_account', p_id, v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_account_upsert(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_channel text, p_provider_id uuid, p_code text, p_display_name text, p_environment text, p_region text, p_account_reference text, p_secret_refs jsonb, p_allow_reference_provider boolean, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_prov public.omni_comms_provider%ROWTYPE;
        v_before public.omni_comms_provider_account%ROWTYPE;
        v_after  public.omni_comms_provider_account%ROWTYPE;
        v_region text; v_ref text; v_env text; v_sandbox boolean;
        v_id uuid; v_refs_changed boolean; v_reset boolean;
BEGIN
  v_env := btrim(COALESCE(p_environment,''));
  IF v_env NOT IN ('sandbox','staging','production') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_environment'; END IF;
  v_sandbox := (v_env <> 'production');
  v_region := NULLIF(btrim(COALESCE(p_region,'')),'');
  v_ref    := NULLIF(btrim(COALESCE(p_account_reference,'')),'');

  SELECT * INTO v_prov FROM public.omni_comms_provider WHERE id=p_provider_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider'; END IF;
  IF v_prov.status <> 'active' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='provider_not_active'; END IF;
  IF v_prov.channel IS DISTINCT FROM btrim(COALESCE(p_channel,'')) THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='provider_channel_mismatch'; END IF;
  IF v_prov.data_origin='reference_seed' AND NOT COALESCE(p_allow_reference_provider,false) THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_provider_not_selectable'; END IF;

  IF p_id IS NULL THEN
    PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, p_organization_id, NULL);
    BEGIN
      INSERT INTO public.omni_comms_provider_account(
        organization_id, provider_id, code, display_name, secret_ref, region,
        sandbox_mode, environment, provider_account_reference, data_origin,
        status, created_by, updated_by,
        verification_status, verification_result_code, verification_detail, verification_checked_at)
      VALUES(p_organization_id, p_provider_id, btrim(p_code), btrim(p_display_name),
        -- canonical credential model is the child reference table; the legacy
        -- column is populated only by the Resend compatibility synchroniser.
        NULL,
        v_region, v_sandbox, v_env, v_ref, 'user',
        'draft', p_actor_id, p_actor_id, 'unverified', NULL, NULL, NULL)
      RETURNING * INTO v_after;
    EXCEPTION
      WHEN unique_violation THEN
        RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='account_code_exists';
      WHEN check_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    END;
    v_id := v_after.id;
    PERFORM public.omni_comms_priv_apply_account_secret_refs(p_actor_id, v_id, p_provider_id, p_secret_refs);
    PERFORM public.omni_comms_priv_sync_legacy_secret_ref(v_id);
    SELECT * INTO v_after FROM public.omni_comms_provider_account WHERE id=v_id;
    PERFORM public.omni_comms_priv_write_channel_audit(
      p_actor_id,'create','provider_account',v_id,v_after.code,NULL,to_jsonb(v_after),p_correlation_id);
    RETURN v_id;
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_provider_account WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_account'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_before.organization_id, NULL);
  IF v_before.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='reference_account_read_only'; END IF;
  IF p_organization_id IS NOT NULL AND v_before.organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='organization_mismatch'; END IF;
  IF p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft'; END IF;

  v_refs_changed := public.omni_comms_priv_apply_account_secret_refs(
    p_actor_id, p_id, p_provider_id, p_secret_refs);

  v_reset := v_refs_changed
          OR (v_before.provider_id  IS DISTINCT FROM p_provider_id)
          OR (v_before.environment  IS DISTINCT FROM v_env)
          OR (v_before.sandbox_mode IS DISTINCT FROM v_sandbox)
          OR (v_before.region       IS DISTINCT FROM v_region)
          OR (v_before.provider_account_reference IS DISTINCT FROM v_ref);

  BEGIN
    UPDATE public.omni_comms_provider_account
       SET code=btrim(p_code), display_name=btrim(p_display_name),
           provider_id=p_provider_id, region=v_region,
           sandbox_mode=v_sandbox, environment=v_env,
           provider_account_reference=v_ref,
           updated_by=p_actor_id, updated_at=now(),
           health_state             = CASE WHEN v_reset THEN 'unknown'    ELSE health_state END,
           health_checked_at        = CASE WHEN v_reset THEN NULL         ELSE health_checked_at END,
           verification_status      = CASE WHEN v_reset THEN 'unverified' ELSE verification_status END,
           verification_result_code = CASE WHEN v_reset THEN NULL         ELSE verification_result_code END,
           verification_detail      = CASE WHEN v_reset THEN NULL         ELSE verification_detail END,
           verification_checked_at  = CASE WHEN v_reset THEN NULL         ELSE verification_checked_at END
     WHERE id=p_id RETURNING * INTO v_after;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='account_code_exists';
    WHEN check_violation THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;

  -- recalculated after any provider change: Resend mirrors api_key, others NULL
  PERFORM public.omni_comms_priv_sync_legacy_secret_ref(p_id);
  SELECT * INTO v_after FROM public.omni_comms_provider_account WHERE id=p_id;
  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id,'update_draft','provider_account',p_id,v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_binding_lifecycle(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_reason text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_before public.omni_comms_sender_provider_binding%ROWTYPE;
  v_after  public.omni_comms_sender_provider_binding%ROWTYPE;
  v_reason text; v_istatus text; v_astatus text; v_estatus text;
BEGIN
  IF p_action NOT IN ('activate','disable','retire') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_action'; END IF;
  SELECT * INTO v_before FROM public.omni_comms_sender_provider_binding
   WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='binding'; END IF;
  IF v_before.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_binding_non_operational'; END IF;
  IF p_expected_updated_at IS NULL
     OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;
  IF v_before.status = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='binding_retired'; END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(
    p_actor_id, v_before.organization_id, v_before.department_id);

  IF p_action = 'activate' THEN
    IF v_before.status NOT IN ('draft','disabled') THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft_or_disabled'; END IF;
    PERFORM public.omni_comms_priv_validate_binding(
      p_actor_id, v_before.organization_id, v_before.department_id, v_before.channel,
      v_before.sender_identity_id, v_before.provider_account_id, v_before.channel_endpoint_id);
    SELECT status INTO v_istatus FROM public.omni_comms_sender_identity
      WHERE id = v_before.sender_identity_id;
    IF v_istatus <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='identity_not_active'; END IF;
    SELECT status INTO v_astatus FROM public.omni_comms_provider_account
      WHERE id = v_before.provider_account_id;
    IF v_astatus <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='provider_account_not_active'; END IF;
    IF v_before.channel_endpoint_id IS NOT NULL THEN
      SELECT status INTO v_estatus FROM public.omni_comms_channel_endpoint
        WHERE id = v_before.channel_endpoint_id;
      IF v_estatus <> 'active' THEN
        RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='channel_endpoint_not_active'; END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.omni_comms_sender_provider_binding b
       WHERE b.id <> v_before.id AND b.status IN ('draft','active')
         AND b.organization_id = v_before.organization_id
         AND b.channel = v_before.channel
         AND b.sender_identity_id = v_before.sender_identity_id
         AND b.department_id IS NOT DISTINCT FROM v_before.department_id
         AND b.priority = v_before.priority) THEN
      RAISE EXCEPTION 'OC409 duplicate_priority' USING ERRCODE='P0001', DETAIL='duplicate_scope_priority'; END IF;

    UPDATE public.omni_comms_sender_provider_binding
       SET status='active', activated_at=COALESCE(activated_at, now()),
           activated_by=COALESCE(activated_by, p_actor_id),
           disabled_at=NULL, disabled_by=NULL,
           updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSIF p_action = 'disable' THEN
    IF v_before.status <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_active'; END IF;
    UPDATE public.omni_comms_sender_provider_binding
       SET status='disabled', disabled_at=now(), disabled_by=p_actor_id,
           updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSE
    v_reason := NULLIF(btrim(coalesce(p_reason,'')),'');
    IF v_reason IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retirement_reason_required'; END IF;
    UPDATE public.omni_comms_sender_provider_binding
       SET status='retired', retired_at=now(), retired_by=p_actor_id,
           retirement_reason=v_reason, updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;
  END IF;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id, p_action, 'binding', p_id, p_id::text,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_binding_upsert(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_channel text, p_sender_identity_id uuid, p_provider_account_id uuid, p_channel_endpoint_id uuid, p_priority integer, p_external_sender_ref text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_before public.omni_comms_sender_provider_binding%ROWTYPE;
  v_after  public.omni_comms_sender_provider_binding%ROWTYPE;
  v_prio integer; v_ref text; v_reset boolean := false; v_dept uuid;
BEGIN
  v_prio := COALESCE(p_priority, 100);
  IF v_prio < 1 OR v_prio > 1000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='priority_out_of_range'; END IF;
  v_ref := NULLIF(btrim(coalesce(p_external_sender_ref,'')),'');
  IF v_ref IS NOT NULL AND (char_length(v_ref) > 128
     OR v_ref !~ '^[A-Za-z0-9][A-Za-z0-9 ._:@+/-]{0,127}$') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_provider_identity_reference'; END IF;
  v_dept := p_department_id;

  PERFORM public.omni_comms_priv_validate_binding(
    p_actor_id, p_organization_id, v_dept, p_channel,
    p_sender_identity_id, p_provider_account_id, p_channel_endpoint_id);

  IF EXISTS (
    SELECT 1 FROM public.omni_comms_sender_provider_binding b
     WHERE b.status <> 'retired'
       AND b.sender_identity_id = p_sender_identity_id
       AND b.provider_account_id = p_provider_account_id
       AND b.channel_endpoint_id IS NOT DISTINCT FROM p_channel_endpoint_id
       AND (p_id IS NULL OR b.id <> p_id)) THEN
    RAISE EXCEPTION 'OC409 duplicate_binding' USING ERRCODE='P0001', DETAIL='duplicate_binding_combination'; END IF;

  IF EXISTS (
    SELECT 1 FROM public.omni_comms_sender_provider_binding b
     WHERE b.status IN ('draft','active')
       AND b.organization_id = p_organization_id
       AND b.channel = p_channel
       AND b.sender_identity_id = p_sender_identity_id
       AND b.department_id IS NOT DISTINCT FROM v_dept
       AND b.priority = v_prio
       AND (p_id IS NULL OR b.id <> p_id)) THEN
    RAISE EXCEPTION 'OC409 duplicate_priority' USING ERRCODE='P0001', DETAIL='duplicate_scope_priority'; END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.omni_comms_sender_provider_binding(
      organization_id, department_id, channel, sender_identity_id,
      provider_account_id, channel_endpoint_id, priority, external_sender_ref,
      status, data_origin, verification_status, verification_source,
      created_by, updated_by)
    VALUES(p_organization_id, v_dept, p_channel, p_sender_identity_id,
      p_provider_account_id, p_channel_endpoint_id, v_prio, v_ref,
      'draft','user','unverified','none', p_actor_id, p_actor_id)
    RETURNING * INTO v_after;
    PERFORM public.omni_comms_priv_write_channel_audit(
      p_actor_id,'create','binding',v_after.id,v_after.id::text,NULL,
      to_jsonb(v_after),p_correlation_id);
    RETURN v_after.id;
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_sender_provider_binding
   WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='binding'; END IF;
  IF v_before.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_binding_read_only'; END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='expected_updated_at_required'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft'; END IF;

  v_reset := (v_before.sender_identity_id IS DISTINCT FROM p_sender_identity_id)
          OR (v_before.provider_account_id IS DISTINCT FROM p_provider_account_id)
          OR (v_before.channel_endpoint_id IS DISTINCT FROM p_channel_endpoint_id)
          OR (v_before.department_id IS DISTINCT FROM v_dept)
          OR (v_before.external_sender_ref IS DISTINCT FROM v_ref);

  UPDATE public.omni_comms_sender_provider_binding
     SET organization_id = p_organization_id,
         department_id = v_dept,
         channel = p_channel,
         sender_identity_id = p_sender_identity_id,
         provider_account_id = p_provider_account_id,
         channel_endpoint_id = p_channel_endpoint_id,
         priority = v_prio,
         external_sender_ref = v_ref,
         verification_status = CASE WHEN v_reset THEN 'unverified' ELSE verification_status END,
         verification_source = CASE WHEN v_reset THEN 'none' ELSE verification_source END,
         verification_result_code = CASE WHEN v_reset THEN NULL ELSE verification_result_code END,
         verification_detail = CASE WHEN v_reset THEN NULL ELSE verification_detail END,
         verification_checked_at = CASE WHEN v_reset THEN NULL ELSE verification_checked_at END,
         verified_at = CASE WHEN v_reset THEN NULL ELSE verified_at END,
         updated_by = p_actor_id, updated_at = now()
   WHERE id = p_id RETURNING * INTO v_after;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id,'update','binding',p_id,p_id::text,to_jsonb(v_before),
    to_jsonb(v_after),p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_endpoint_lifecycle(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_reason text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_action text; v_reason text; v_secrets jsonb;
        v_before public.omni_comms_channel_endpoint%ROWTYPE;
        v_after  public.omni_comms_channel_endpoint%ROWTYPE;
BEGIN
  v_action := btrim(lower(coalesce(p_action,'')));
  IF v_action NOT IN ('activate','disable','retire') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_action'; END IF;

  SELECT * INTO v_before FROM public.omni_comms_channel_endpoint WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='channel_endpoint'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_before.organization_id, NULL);
  IF v_before.data_origin='reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_endpoint_non_operational'; END IF;
  IF p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;

  IF v_action='activate' THEN
    IF v_before.status NOT IN ('draft','disabled') THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft_or_disabled'; END IF;
    SELECT COALESCE(jsonb_object_agg(purpose, secret_ref),'{}'::jsonb) INTO v_secrets
      FROM public.omni_comms_channel_endpoint_secret_ref WHERE channel_endpoint_id=p_id;
    PERFORM public.omni_comms_priv_normalize_channel_endpoint(
      v_before.channel, v_before.endpoint_type, v_before.endpoint_config, v_secrets);
    PERFORM public.omni_comms_priv_validate_endpoint_account(
      v_before.provider_account_id, v_before.organization_id, v_before.channel,
      public.omni_comms_priv_endpoint_requires_account(
        v_before.channel, v_before.endpoint_type, v_before.endpoint_config),
      public.omni_comms_priv_endpoint_requires_account(
        v_before.channel, v_before.endpoint_type, v_before.endpoint_config));
    UPDATE public.omni_comms_channel_endpoint
       SET status='active',
           activated_at=COALESCE(activated_at, now()), activated_by=COALESCE(activated_by, p_actor_id),
           updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSIF v_action='disable' THEN
    IF v_before.status <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_active'; END IF;
    UPDATE public.omni_comms_channel_endpoint
       SET status='disabled', updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSE
    v_reason := NULLIF(btrim(coalesce(p_reason,'')),'');
    IF v_reason IS NULL OR char_length(v_reason) > 2000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retirement_reason_required'; END IF;
    IF v_before.status='retired' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='already_retired'; END IF;
    UPDATE public.omni_comms_channel_endpoint
       SET status='retired', retired_at=now(), retired_by=p_actor_id,
           retirement_reason=v_reason, updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;
  END IF;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id, v_action, 'channel_endpoint', p_id, v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_endpoint_upsert(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_channel text, p_provider_account_id uuid, p_code text, p_display_name text, p_endpoint_type text, p_endpoint_config jsonb, p_secret_refs jsonb, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_ch text; v_type text; v_norm jsonb; v_cfg jsonb; v_secrets jsonb;
        v_before public.omni_comms_channel_endpoint%ROWTYPE;
        v_after  public.omni_comms_channel_endpoint%ROWTYPE;
        v_before_secrets jsonb; v_material boolean; v_key text; v_val text;
BEGIN
  v_ch := btrim(coalesce(p_channel,''));
  v_type := btrim(coalesce(p_endpoint_type,''));
  v_norm := public.omni_comms_priv_normalize_channel_endpoint(v_ch, v_type, p_endpoint_config, p_secret_refs);
  v_cfg := v_norm->'endpoint_config';
  v_secrets := v_norm->'secret_refs';

  PERFORM public.omni_comms_priv_validate_endpoint_account(
    p_provider_account_id, p_organization_id, v_ch,
    public.omni_comms_priv_endpoint_requires_account(v_ch, v_type, v_cfg), false);

  IF p_id IS NULL THEN
    PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, p_organization_id, p_department_id);
    BEGIN
      INSERT INTO public.omni_comms_channel_endpoint(
        organization_id, department_id, channel, provider_account_id, code, display_name,
        endpoint_type, endpoint_config, data_origin, status, verification_status,
        created_by, updated_by)
      VALUES(p_organization_id, p_department_id, v_ch, p_provider_account_id,
        lower(btrim(coalesce(p_code,''))), btrim(coalesce(p_display_name,'')),
        v_type, v_cfg, 'user', 'draft', 'unverified', p_actor_id, p_actor_id)
      RETURNING * INTO v_after;
    EXCEPTION
      WHEN unique_violation THEN
        RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='endpoint_code_exists';
      WHEN check_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    END;
  ELSE
    SELECT * INTO v_before FROM public.omni_comms_channel_endpoint WHERE id=p_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='channel_endpoint'; END IF;
    PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_before.organization_id, p_department_id);
    IF p_organization_id IS NOT NULL AND v_before.organization_id IS DISTINCT FROM p_organization_id THEN
      RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='organization_mismatch'; END IF;
    IF v_before.data_origin='reference_seed' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_endpoint_read_only'; END IF;
    IF p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;
    IF v_before.status <> 'draft' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft'; END IF;
    IF v_before.channel IS DISTINCT FROM v_ch THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_immutable'; END IF;

    SELECT COALESCE(jsonb_object_agg(purpose, secret_ref),'{}'::jsonb) INTO v_before_secrets
      FROM public.omni_comms_channel_endpoint_secret_ref WHERE channel_endpoint_id=p_id;

    v_material :=
      v_before.provider_account_id IS DISTINCT FROM p_provider_account_id
      OR v_before.endpoint_type IS DISTINCT FROM v_type
      OR v_before.endpoint_config IS DISTINCT FROM v_cfg
      OR v_before_secrets IS DISTINCT FROM v_secrets;

    BEGIN
      UPDATE public.omni_comms_channel_endpoint
         SET department_id=p_department_id,
             provider_account_id=p_provider_account_id,
             code=lower(btrim(coalesce(p_code,''))),
             display_name=btrim(coalesce(p_display_name,'')),
             endpoint_type=v_type, endpoint_config=v_cfg,
             verification_status = CASE WHEN v_material THEN 'unverified' ELSE verification_status END,
             verification_result_code = CASE WHEN v_material THEN NULL ELSE verification_result_code END,
             verification_detail = CASE WHEN v_material THEN NULL ELSE verification_detail END,
             verification_checked_at = CASE WHEN v_material THEN NULL ELSE verification_checked_at END,
             updated_by=p_actor_id, updated_at=now()
       WHERE id=p_id RETURNING * INTO v_after;
    EXCEPTION
      WHEN unique_violation THEN
        RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='endpoint_code_exists';
      WHEN check_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    END;
  END IF;

  -- secret references: names only, replaced atomically inside this transaction
  DELETE FROM public.omni_comms_channel_endpoint_secret_ref
   WHERE channel_endpoint_id = v_after.id
     AND purpose NOT IN (SELECT jsonb_object_keys(v_secrets));
  FOR v_key, v_val IN SELECT key, value #>> '{}' FROM jsonb_each(v_secrets) LOOP
    INSERT INTO public.omni_comms_channel_endpoint_secret_ref(
      channel_endpoint_id, purpose, secret_ref, created_by, updated_by)
    VALUES(v_after.id, v_key, v_val, p_actor_id, p_actor_id)
    ON CONFLICT (channel_endpoint_id, purpose)
      DO UPDATE SET secret_ref=EXCLUDED.secret_ref, updated_by=p_actor_id, updated_at=now();
  END LOOP;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id, CASE WHEN p_id IS NULL THEN 'create' ELSE 'update_draft' END,
    'channel_endpoint', v_after.id, v_after.code,
    CASE WHEN p_id IS NULL THEN NULL
         ELSE to_jsonb(v_before) || jsonb_build_object('secret_refs', v_before_secrets) END,
    to_jsonb(v_after) || jsonb_build_object('secret_refs', v_secrets),
    p_correlation_id);

  RETURN v_after.id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_identity_lifecycle(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_action text, p_reason text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_action text; v_reason text;
        v_before public.omni_comms_sender_identity%ROWTYPE;
        v_after  public.omni_comms_sender_identity%ROWTYPE;
BEGIN
  v_action := btrim(lower(coalesce(p_action,'')));
  IF v_action NOT IN ('activate','disable','retire') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_action'; END IF;

  SELECT * INTO v_before FROM public.omni_comms_sender_identity WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='sender_identity'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_before.organization_id, NULL);
  IF v_before.data_origin='reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_identity_non_operational'; END IF;
  IF p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;

  IF v_action='activate' THEN
    IF v_before.status NOT IN ('draft','disabled') THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft_or_disabled'; END IF;
    IF v_before.channel NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_channel'; END IF;
    PERFORM public.omni_comms_priv_normalize_identity_config(
      v_before.channel, v_before.identity_type, v_before.identity_config);
    UPDATE public.omni_comms_sender_identity
       SET status='active',
           activated_at=COALESCE(activated_at, now()), activated_by=COALESCE(activated_by, p_actor_id),
           updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSIF v_action='disable' THEN
    IF v_before.status <> 'active' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_active'; END IF;
    UPDATE public.omni_comms_sender_identity
       SET status='disabled', updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;

  ELSE
    v_reason := NULLIF(btrim(coalesce(p_reason,'')),'');
    IF v_reason IS NULL OR char_length(v_reason) > 2000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retirement_reason_required'; END IF;
    IF v_before.status='retired' THEN
      RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='already_retired'; END IF;
    UPDATE public.omni_comms_sender_identity
       SET status='retired', retired_at=now(), retired_by=p_actor_id,
           retirement_reason=v_reason, updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;
  END IF;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id, v_action, 'sender_identity', p_id, v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_identity_upsert(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_channel text, p_code text, p_display_name text, p_identity_type text, p_identity_config jsonb, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_ch text; v_cfg jsonb;
        v_before public.omni_comms_sender_identity%ROWTYPE;
        v_after  public.omni_comms_sender_identity%ROWTYPE;
        v_from text; v_fname text; v_reply text; v_print jsonb; v_org uuid; v_dept uuid;
BEGIN
  v_ch := btrim(coalesce(p_channel,''));
  IF v_ch NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_channel'; END IF;

  v_cfg := public.omni_comms_priv_normalize_identity_config(v_ch, p_identity_type, p_identity_config);

  v_from  := CASE WHEN v_ch='email' THEN v_cfg->>'from_address' END;
  v_fname := CASE WHEN v_ch='email' THEN v_cfg->>'from_name' END;
  v_reply := CASE WHEN v_ch='email' THEN v_cfg->>'reply_to_address' END;
  v_print := CASE WHEN v_ch='print' THEN v_cfg END;

  IF p_id IS NULL THEN
    v_org := p_organization_id; v_dept := p_department_id;
    PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_org, v_dept);
    BEGIN
      INSERT INTO public.omni_comms_sender_identity(
        organization_id, department_id, event_definition_id, code, display_name,
        channel, identity_type, identity_config,
        from_address, from_name, reply_to_address, print_config,
        data_origin, status, created_by, updated_by)
      VALUES(v_org, v_dept, NULL, btrim(coalesce(p_code,'')), btrim(coalesce(p_display_name,'')),
        v_ch, btrim(coalesce(p_identity_type,'')), v_cfg,
        v_from, v_fname, v_reply, v_print,
        'user','draft', p_actor_id, p_actor_id)
      RETURNING * INTO v_after;
    EXCEPTION
      WHEN unique_violation THEN
        RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='identity_code_exists';
      WHEN check_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
      WHEN foreign_key_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_or_department';
    END;
    PERFORM public.omni_comms_priv_write_channel_audit(
      p_actor_id,'create','sender_identity',v_after.id,v_after.code,NULL,to_jsonb(v_after),p_correlation_id);
    RETURN v_after.id;
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_sender_identity WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='sender_identity'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, v_before.organization_id, p_department_id);
  IF p_organization_id IS NOT NULL AND v_before.organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='organization_mismatch'; END IF;
  IF v_before.data_origin='reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_identity_read_only'; END IF;
  IF p_expected_updated_at IS NULL OR v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='must_be_draft'; END IF;
  IF v_before.channel IS DISTINCT FROM v_ch THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_immutable'; END IF;

  BEGIN
    UPDATE public.omni_comms_sender_identity
       SET department_id=p_department_id,
           code=btrim(coalesce(p_code,'')), display_name=btrim(coalesce(p_display_name,'')),
           identity_type=btrim(coalesce(p_identity_type,'')), identity_config=v_cfg,
           from_address=v_from, from_name=v_fname, reply_to_address=v_reply,
           print_config=v_print,
           updated_by=p_actor_id, updated_at=now()
     WHERE id=p_id RETURNING * INTO v_after;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'OC409 conflict' USING ERRCODE='P0001', DETAIL='identity_code_exists';
    WHEN check_violation THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    WHEN foreign_key_violation THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_or_department';
  END;
  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id,'update_draft','sender_identity',p_id,v_after.code,
    to_jsonb(v_before),to_jsonb(v_after),p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_policy_json(p_row omni_comms_channel_setting)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT jsonb_build_object(
    'id', p_row.id,
    'organization_id', p_row.organization_id,
    'department_id', p_row.department_id,
    'department_name', (SELECT d.name FROM public.core_department d WHERE d.id = p_row.department_id),
    'channel', p_row.channel,
    'operational_state', p_row.operational_state,
    'department_override_enabled', p_row.department_override_enabled,
    'enabled', p_row.enabled,
    'live_delivery_enabled', p_row.live_delivery_enabled,
    'per_minute_limit', p_row.per_minute_limit,
    'per_day_limit', p_row.per_day_limit,
    'max_recipients_per_request', p_row.max_recipients_per_request,
    'quiet_hours_start', to_char(p_row.quiet_hours_start,'HH24:MI'),
    'quiet_hours_end', to_char(p_row.quiet_hours_end,'HH24:MI'),
    'quiet_hours_timezone', p_row.quiet_hours_timezone,
    'retry_profile', p_row.retry_profile,
    'request_timeout_seconds', p_row.request_timeout_seconds,
    'retention_days', p_row.retention_days,
    'cost_currency', p_row.cost_currency,
    'daily_cost_limit_minor', p_row.daily_cost_limit_minor,
    'per_message_cost_limit_minor', p_row.per_message_cost_limit_minor,
    'channel_policy_config', p_row.channel_policy_config,
    'data_origin', p_row.data_origin,
    'created_at', p_row.created_at,
    'created_by', p_row.created_by,
    'updated_at', p_row.updated_at,
    'updated_by', p_row.updated_by
  );
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_policy_upsert(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_channel text, p_common_policy jsonb, p_channel_policy_config jsonb, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_norm jsonb; v_c jsonb; v_cfg jsonb;
  v_before public.omni_comms_channel_setting%ROWTYPE;
  v_after  public.omni_comms_channel_setting%ROWTYPE;
  v_override boolean; v_action text;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, p_organization_id, p_department_id);
  IF p_department_id IS NOT NULL
     AND NOT public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id) THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='department_organization_mismatch'; END IF;

  v_norm := public.omni_comms_priv_normalize_channel_policy(p_channel, p_common_policy, p_channel_policy_config);
  v_c := v_norm->'common';
  v_cfg := v_norm->'channel_policy_config';
  v_override := CASE WHEN p_department_id IS NULL THEN true
                     ELSE COALESCE((v_c->>'department_override_enabled')::boolean, true) END;

  IF p_id IS NULL THEN
    BEGIN
      INSERT INTO public.omni_comms_channel_setting(
        organization_id, department_id, channel, enabled, live_delivery_enabled,
        operational_state, department_override_enabled, data_origin,
        per_minute_limit, per_day_limit, max_recipients_per_request,
        quiet_hours_start, quiet_hours_end, quiet_hours_timezone,
        retry_profile, request_timeout_seconds, retention_days,
        cost_currency, daily_cost_limit_minor, per_message_cost_limit_minor,
        channel_policy_config, created_by, updated_by)
      VALUES(
        p_organization_id, p_department_id, v_norm->>'channel',
        (v_c->>'operational_state') <> 'disabled', false,
        v_c->>'operational_state', v_override, 'user',
        (v_c->>'per_minute_limit')::int, (v_c->>'per_day_limit')::int,
        (v_c->>'max_recipients_per_request')::int,
        (v_c->>'quiet_hours_start')::time, (v_c->>'quiet_hours_end')::time,
        v_c->>'quiet_hours_timezone',
        v_c->>'retry_profile', (v_c->>'request_timeout_seconds')::int,
        (v_c->>'retention_days')::int, v_c->>'cost_currency',
        (v_c->>'daily_cost_limit_minor')::bigint,
        (v_c->>'per_message_cost_limit_minor')::bigint,
        v_cfg, p_actor_id, p_actor_id)
      RETURNING * INTO v_after;
    EXCEPTION
      WHEN unique_violation THEN
        RAISE EXCEPTION 'OC409 duplicate_channel_policy' USING ERRCODE='P0001', DETAIL='genuine_policy_scope_exists';
      WHEN check_violation THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    END;
    PERFORM public.omni_comms_priv_write_channel_audit(
      p_actor_id,
      CASE WHEN p_department_id IS NULL THEN 'create_organisation_policy' ELSE 'create_department_override' END,
      'channel_setting', v_after.id, v_after.channel, NULL, to_jsonb(v_after), p_correlation_id);
    RETURN v_after.id;
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_channel_setting WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='channel_policy'; END IF;
  IF v_before.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='reference_policy_read_only'; END IF;
  IF v_before.organization_id <> p_organization_id
     OR v_before.department_id IS DISTINCT FROM p_department_id
     OR v_before.channel <> (v_norm->>'channel') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='policy_scope_immutable'; END IF;
  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='expected_updated_at_required'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;

  BEGIN
    UPDATE public.omni_comms_channel_setting
       SET operational_state = v_c->>'operational_state',
           enabled = (v_c->>'operational_state') <> 'disabled',
           live_delivery_enabled = false,
           department_override_enabled = v_override,
           per_minute_limit = (v_c->>'per_minute_limit')::int,
           per_day_limit = (v_c->>'per_day_limit')::int,
           max_recipients_per_request = (v_c->>'max_recipients_per_request')::int,
           quiet_hours_start = (v_c->>'quiet_hours_start')::time,
           quiet_hours_end = (v_c->>'quiet_hours_end')::time,
           quiet_hours_timezone = v_c->>'quiet_hours_timezone',
           retry_profile = v_c->>'retry_profile',
           request_timeout_seconds = (v_c->>'request_timeout_seconds')::int,
           retention_days = (v_c->>'retention_days')::int,
           cost_currency = v_c->>'cost_currency',
           daily_cost_limit_minor = (v_c->>'daily_cost_limit_minor')::bigint,
           per_message_cost_limit_minor = (v_c->>'per_message_cost_limit_minor')::bigint,
           channel_policy_config = v_cfg,
           updated_by = p_actor_id, updated_at = now()
     WHERE id = p_id RETURNING * INTO v_after;
  EXCEPTION WHEN check_violation THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;

  v_action := CASE
    WHEN p_department_id IS NULL THEN 'update_organisation_policy'
    WHEN v_before.department_override_enabled AND NOT v_after.department_override_enabled THEN 'disable_department_override'
    WHEN NOT v_before.department_override_enabled AND v_after.department_override_enabled THEN 'enable_department_override'
    ELSE 'update_department_override' END;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id, v_action, 'channel_setting', p_id, v_after.channel,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_approve_activate(p_actor_id uuid, p_release_control_id uuid, p_expected_updated_at timestamp with time zone, p_expected_fingerprint text, p_deployed_revision text, p_approval_note text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rel public.omni_comms_channel_release_control;
  v_checks jsonb;
  v_blockers integer;
  v_cert jsonb;
BEGIN
  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control
   WHERE id = p_release_control_id FOR UPDATE;
  IF v_rel.id IS NULL THEN RAISE EXCEPTION 'release_control_missing' USING ERRCODE='42704'; END IF;
  IF v_rel.data_origin = 'reference_seed' THEN RAISE EXCEPTION 'reference_release_non_operational' USING ERRCODE='42501'; END IF;
  IF v_rel.updated_at <> p_expected_updated_at THEN RAISE EXCEPTION 'concurrent_modification' USING ERRCODE='40001'; END IF;
  IF v_rel.proposed_state IS DISTINCT FROM 'controlled_pilot' THEN RAISE EXCEPTION 'release_proposal_missing' USING ERRCODE='22023'; END IF;
  IF v_rel.release_fingerprint <> coalesce(p_expected_fingerprint,'') THEN RAISE EXCEPTION 'release_proposal_fingerprint_changed' USING ERRCODE='22023'; END IF;
  IF v_rel.proposal_expires_at IS NULL OR v_rel.proposal_expires_at <= now() THEN RAISE EXCEPTION 'release_proposal_expired' USING ERRCODE='22023'; END IF;
  IF v_rel.proposed_by = p_actor_id THEN RAISE EXCEPTION 'segregation_of_duties_violation' USING ERRCODE='42501'; END IF;
  IF v_rel.release_state NOT IN ('test_only','suspended') THEN RAISE EXCEPTION 'release_transition_not_allowed' USING ERRCODE='22023'; END IF;

  v_checks := public.omni_comms_priv_channel_release_prerequisites(
    v_rel.organization_id, v_rel.department_id, v_rel.channel, v_rel.id, p_deployed_revision);
  SELECT count(*) INTO v_blockers FROM jsonb_array_elements(v_checks) c
   WHERE (c->>'sequence')::int <= 31 AND c->>'state' <> 'passed';
  IF v_blockers > 0 THEN
    PERFORM public.omni_comms_priv_channel_release_record_event(
      v_rel, 'release_gate_denied', v_rel.release_state, 'controlled_pilot',
      'prerequisites_failed', p_actor_id, p_correlation_id, p_deployed_revision,
      jsonb_build_object('blocker_count', v_blockers));
    RAISE EXCEPTION 'release_prerequisites_failed' USING ERRCODE='22023';
  END IF;

  v_cert := public.omni_comms_priv_runtime_certification();

  UPDATE public.omni_comms_channel_release_control SET
    release_state = 'controlled_pilot',
    release_version = release_version + 1,
    proposed_state = NULL,
    approved_by = p_actor_id,
    approved_at = now(),
    approval_note = left(coalesce(p_approval_note,''), 500),
    activated_by = p_actor_id,
    activated_at = now(),
    suspended_by = NULL, suspended_at = NULL, suspension_reason = NULL,
    approved_commit = v_cert->>'certified_commit',
    certification_workflow_run_id = v_cert->>'workflow_run_id',
    certification_recorded_at = (v_cert->>'certified_at')::timestamptz,
    updated_by = p_actor_id
  WHERE id = v_rel.id RETURNING * INTO v_rel;

  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, 'transition_approved', 'test_only', 'controlled_pilot',
    p_approval_note, p_actor_id, p_correlation_id, p_deployed_revision, '{}'::jsonb);
  PERFORM public.omni_comms_priv_channel_release_record_event(
    v_rel, 'release_activated', 'test_only', 'controlled_pilot',
    NULL, p_actor_id, p_correlation_id, p_deployed_revision, '{}'::jsonb);

  RETURN public.omni_comms_priv_channel_release_json(v_rel);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_control_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item jsonb;
BEGIN
  IF NEW.release_state = 'live' THEN
    RAISE EXCEPTION 'live_activation_not_available_until_business_pilot_certified'
      USING ERRCODE = '22023';
  END IF;
  IF NEW.proposed_state = 'live' THEN
    RAISE EXCEPTION 'live_activation_not_available_until_business_pilot_certified'
      USING ERRCODE = '22023';
  END IF;

  IF NEW.data_origin = 'reference_seed'
     AND NEW.release_state NOT IN ('disabled','configuration') THEN
    RAISE EXCEPTION 'reference_release_non_operational' USING ERRCODE = '42501';
  END IF;

  IF NEW.release_state = 'controlled_pilot' THEN
    IF NEW.release_expires_at IS NULL THEN
      RAISE EXCEPTION 'release_expiry_required_for_controlled_pilot' USING ERRCODE = '22023';
    END IF;
    IF NEW.release_expires_at
       > coalesce(NEW.release_starts_at, NEW.activated_at, now()) + interval '7 days' THEN
      RAISE EXCEPTION 'release_window_exceeds_seven_days' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(NEW.pilot_recipient_rules) = 0 THEN
      RAISE EXCEPTION 'release_recipient_rules_required' USING ERRCODE = '22023';
    END IF;
    IF coalesce(array_length(NEW.permitted_event_codes,1),0) = 0
       OR coalesce(array_length(NEW.permitted_caller_modules,1),0) = 0
       OR coalesce(array_length(NEW.permitted_modes,1),0) = 0 THEN
      RAISE EXCEPTION 'release_restrictions_required' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM unnest(coalesce(NEW.permitted_modes,'{}')) m WHERE m <> 'queued') THEN
    RAISE EXCEPTION 'release_mode_not_permitted' USING ERRCODE = '22023';
  END IF;
  IF 'OMNI_COMMS_ADMIN_DRY_RUN' = ANY (coalesce(NEW.permitted_caller_modules,'{}')) THEN
    RAISE EXCEPTION 'release_caller_not_permitted' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(NEW.pilot_recipient_rules) LOOP
    IF (v_item->>'target_hash') !~ '^[0-9a-f]{64}$'
       OR coalesce(v_item->>'target_masked','') = ''
       OR (v_item ? 'target') THEN
      RAISE EXCEPTION 'release_recipient_rule_malformed' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  NEW.updated_at := now();
  NEW.release_fingerprint := public.omni_comms_priv_channel_release_fingerprint(NEW);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_decision(p_organization_id uuid, p_department_id uuid, p_channel text, p_event_code text, p_caller_module_code text, p_mode text, p_recipient_hashes text[], p_requested_message_count integer, p_deployed_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rel public.omni_comms_channel_release_control;
  v_allowed boolean := false;
  v_code text := 'release_control_missing';
  v_hour integer := 0; v_day integer := 0; v_total integer := 0;
  v_perm_event boolean := false; v_perm_caller boolean := false;
  v_mode_ok boolean := false; v_rules_ok boolean := false;
  v_match_count integer := 0;
  v_revision_match boolean := false;
  v_prereq jsonb := '[]'::jsonb;
  v_prereq_codes jsonb := '[]'::jsonb;
BEGIN
  v_rel := public.omni_comms_priv_channel_release_effective(p_organization_id, p_department_id, p_channel);

  IF v_rel.id IS NOT NULL THEN
    v_perm_event := p_event_code = ANY (coalesce(v_rel.permitted_event_codes,'{}'));
    v_perm_caller := p_caller_module_code = ANY (coalesce(v_rel.permitted_caller_modules,'{}'))
                     AND p_caller_module_code <> 'OMNI_COMMS_ADMIN_DRY_RUN';
    v_mode_ok := p_mode = ANY (coalesce(v_rel.permitted_modes,'{}')) AND p_mode = 'queued';

    SELECT count(*) INTO v_match_count
    FROM unnest(coalesce(p_recipient_hashes,'{}')) h
    WHERE EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_rel.pilot_recipient_rules) r
      WHERE r->>'target_hash' = lower(h));

    v_rules_ok := coalesce(array_length(p_recipient_hashes,1),0) > 0
      AND coalesce(array_length(p_recipient_hashes,1),0) <= v_rel.max_recipients_per_request
      AND v_match_count = coalesce(array_length(p_recipient_hashes,1),0);

    SELECT count(*) INTO v_hour FROM public.omni_comms_dispatch_job j
      WHERE j.release_control_id = v_rel.id AND j.created_at > now() - interval '1 hour';
    SELECT count(*) INTO v_day FROM public.omni_comms_dispatch_job j
      WHERE j.release_control_id = v_rel.id AND j.created_at > now() - interval '1 day';
    SELECT count(*) INTO v_total FROM public.omni_comms_dispatch_job j
      WHERE j.release_control_id = v_rel.id;

    v_revision_match := lower(coalesce(p_deployed_revision,'')) = lower(coalesce(v_rel.approved_commit,'x'));

    v_prereq := public.omni_comms_priv_channel_release_prerequisites(
      p_organization_id, p_department_id, p_channel, v_rel.id, p_deployed_revision);
    SELECT coalesce(jsonb_agg(jsonb_build_object('code', e->>'code', 'state', e->>'state')
                              ORDER BY (e->>'sequence')::int), '[]'::jsonb)
      INTO v_prereq_codes
    FROM jsonb_array_elements(v_prereq) e;

    IF v_rel.release_state = 'suspended' THEN v_code := 'release_not_active';
    ELSIF v_rel.release_state <> 'controlled_pilot' THEN v_code := 'release_not_active';
    ELSIF v_rel.release_expires_at IS NULL OR v_rel.release_expires_at <= now() THEN v_code := 'release_expired';
    ELSIF v_rel.release_starts_at IS NOT NULL AND v_rel.release_starts_at > now() THEN v_code := 'release_not_active';
    ELSIF NOT v_perm_event OR NOT v_perm_caller OR NOT v_mode_ok OR NOT v_rules_ok THEN v_code := 'release_scope_denied';
    ELSIF v_hour + coalesce(p_requested_message_count,1) > v_rel.max_messages_per_hour
       OR v_day + coalesce(p_requested_message_count,1) > v_rel.max_messages_per_day
       OR v_total + coalesce(p_requested_message_count,1) > v_rel.max_messages_total THEN v_code := 'release_limit_exceeded';
    ELSIF NOT v_revision_match THEN v_code := 'release_scope_denied';
    ELSIF EXISTS (SELECT 1 FROM jsonb_array_elements(v_prereq) e WHERE e->>'state' = 'failed')
      THEN v_code := 'release_prerequisites_failed';
    ELSE v_allowed := true; v_code := 'release_allowed';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_allowed,
    'code', v_code,
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'channel', p_channel,
    'release_control_id', v_rel.id,
    'release_version', v_rel.release_version,
    'release_state', v_rel.release_state,
    'release_fingerprint', v_rel.release_fingerprint,
    'release_expires_at', v_rel.release_expires_at,
    'permitted_event', v_perm_event,
    'permitted_caller', v_perm_caller,
    'mode_allowed', v_mode_ok,
    'recipient_rules_satisfied', v_rules_ok,
    'recipient_rule_match_count', v_match_count,
    'requested_message_count', coalesce(p_requested_message_count, 1),
    'current_hourly_count', v_hour,
    'current_daily_count', v_day,
    'current_total_count', v_total,
    'max_messages_per_hour', v_rel.max_messages_per_hour,
    'max_messages_per_day', v_rel.max_messages_per_day,
    'max_messages_total', v_rel.max_messages_total,
    'certified_commit', v_rel.approved_commit,
    'deployed_revision_match', v_revision_match,
    'prerequisite_codes', v_prereq_codes,
    'business_dispatch_enabled', (v_allowed AND to_regprocedure('public.omni_comms_priv_dispatch_claim_email(text,integer,text,text,jsonb,text)') IS NOT NULL)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_effective(p_organization_id uuid, p_department_id uuid, p_channel text)
 RETURNS omni_comms_channel_release_control
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.omni_comms_channel_release_control
  WHERE organization_id = p_organization_id
    AND channel = p_channel
    AND data_origin <> 'reference_seed'
    AND (department_id = p_department_id OR department_id IS NULL)
  ORDER BY (department_id IS NOT NULL) DESC
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_expire_if_due(p_release_control_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rel public.omni_comms_channel_release_control;
BEGIN
  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_release_control_id FOR UPDATE;
  IF v_rel.id IS NULL THEN RETURN false; END IF;

  IF v_rel.proposed_state IS NOT NULL AND v_rel.proposal_expires_at IS NOT NULL
     AND v_rel.proposal_expires_at <= now() THEN
    UPDATE public.omni_comms_channel_release_control
      SET proposed_state = NULL, proposal_reason = NULL, proposal_expires_at = NULL
      WHERE id = v_rel.id RETURNING * INTO v_rel;
    PERFORM public.omni_comms_priv_channel_release_record_event(
      v_rel, 'proposal_expired', v_rel.release_state, NULL, 'proposal_window_elapsed', NULL, NULL, NULL, '{}'::jsonb);
  END IF;

  IF v_rel.release_state = 'controlled_pilot' AND v_rel.release_expires_at IS NOT NULL
     AND v_rel.release_expires_at <= now() THEN
    UPDATE public.omni_comms_channel_release_control
      SET release_state = 'test_only', release_version = release_version + 1
      WHERE id = v_rel.id RETURNING * INTO v_rel;
    PERFORM public.omni_comms_priv_channel_release_record_event(
      v_rel, 'release_expired', 'controlled_pilot', 'test_only', 'release_window_elapsed', NULL, NULL, NULL, '{}'::jsonb);
    RETURN true;
  END IF;
  RETURN false;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_fingerprint(p_row omni_comms_channel_release_control)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT public.omni_comms_priv_channel_test_sha256(
    jsonb_build_object(
      'organization_id', p_row.organization_id,
      'department_id', p_row.department_id,
      'channel', p_row.channel,
      'release_state', p_row.release_state,
      'permitted_event_codes', to_jsonb(coalesce(p_row.permitted_event_codes,'{}')),
      'permitted_caller_modules', to_jsonb(coalesce(p_row.permitted_caller_modules,'{}')),
      'permitted_modes', to_jsonb(coalesce(p_row.permitted_modes,'{}')),
      'pilot_recipient_rules', p_row.pilot_recipient_rules,
      'max_recipients_per_request', p_row.max_recipients_per_request,
      'max_messages_per_hour', p_row.max_messages_per_hour,
      'max_messages_per_day', p_row.max_messages_per_day,
      'max_messages_total', p_row.max_messages_total,
      'release_starts_at', p_row.release_starts_at,
      'release_expires_at', p_row.release_expires_at
    )::text
  );
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_json(p_row omni_comms_channel_release_control)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'id', p_row.id,
    'organization_id', p_row.organization_id,
    'department_id', p_row.department_id,
    'channel', p_row.channel,
    'data_origin', p_row.data_origin,
    'release_state', p_row.release_state,
    'release_version', p_row.release_version,
    'permitted_event_codes', to_jsonb(coalesce(p_row.permitted_event_codes,'{}')),
    'permitted_caller_modules', to_jsonb(coalesce(p_row.permitted_caller_modules,'{}')),
    'permitted_modes', to_jsonb(coalesce(p_row.permitted_modes,'{}')),
    'pilot_recipient_rules', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'target_type', r->>'target_type',
        'target_masked', r->>'target_masked',
        'target_hash_prefix', left(r->>'target_hash', 12)
      )), '[]'::jsonb)
      FROM jsonb_array_elements(p_row.pilot_recipient_rules) r
    ),
    'max_recipients_per_request', p_row.max_recipients_per_request,
    'max_messages_per_hour', p_row.max_messages_per_hour,
    'max_messages_per_day', p_row.max_messages_per_day,
    'max_messages_total', p_row.max_messages_total,
    'release_starts_at', p_row.release_starts_at,
    'release_expires_at', p_row.release_expires_at,
    'proposed_state', p_row.proposed_state,
    'proposal_reason', p_row.proposal_reason,
    'proposed_by', p_row.proposed_by,
    'proposed_at', p_row.proposed_at,
    'proposal_expires_at', p_row.proposal_expires_at,
    'approved_by', p_row.approved_by,
    'approved_at', p_row.approved_at,
    'approval_note', p_row.approval_note,
    'activated_by', p_row.activated_by,
    'activated_at', p_row.activated_at,
    'suspended_by', p_row.suspended_by,
    'suspended_at', p_row.suspended_at,
    'suspension_reason', p_row.suspension_reason,
    'approved_commit', p_row.approved_commit,
    'certification_workflow_run_id', p_row.certification_workflow_run_id,
    'certification_recorded_at', p_row.certification_recorded_at,
    'release_fingerprint', p_row.release_fingerprint,
    'created_at', p_row.created_at,
    'updated_at', p_row.updated_at
  );
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_prerequisites(p_organization_id uuid, p_department_id uuid, p_channel text, p_release_control_id uuid, p_deployed_revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rel public.omni_comms_channel_release_control;
  v_policy public.omni_comms_channel_setting;
  v_cert jsonb;
  v_env text;
  v_provider_account uuid;
  v_run public.omni_comms_channel_test_run;
  v_delivery public.omni_comms_channel_test_delivery;
  v_delivered boolean := false;
  v_bad boolean := false;
  v_dep_ok boolean;
  v_events text[];
  v_callers text[];

  FUNCTION_BODY_MARKER text;
BEGIN
  SELECT * INTO v_rel FROM public.omni_comms_channel_release_control WHERE id = p_release_control_id;
  v_policy := public.omni_comms_priv_channel_test_effective_policy(p_organization_id, p_department_id, p_channel);
  v_cert := public.omni_comms_priv_runtime_certification();
  v_env := public.omni_comms_priv_runtime_environment();
  v_dep_ok := p_department_id IS NULL
    OR public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  v_events := coalesce(v_rel.permitted_event_codes, '{}');
  v_callers := coalesce(v_rel.permitted_caller_modules, '{}');

  SELECT pa.id INTO v_provider_account
  FROM public.omni_comms_provider_account pa
  WHERE pa.organization_id = p_organization_id
    AND pa.status = 'active' AND pa.data_origin <> 'reference_seed'
  ORDER BY (pa.verification_status = 'verified') DESC
  LIMIT 1;

  SELECT * INTO v_run FROM public.omni_comms_channel_test_run r
  WHERE r.organization_id = p_organization_id AND r.channel = p_channel AND r.status = 'passed'
  ORDER BY r.created_at DESC LIMIT 1;

  SELECT * INTO v_delivery FROM public.omni_comms_channel_test_delivery d
  WHERE d.organization_id = p_organization_id AND d.channel = p_channel AND d.status = 'accepted'
  ORDER BY d.created_at DESC LIMIT 1;

  IF v_delivery.id IS NOT NULL THEN
    SELECT EXISTS (SELECT 1 FROM public.omni_comms_channel_test_delivery_event e
      WHERE e.delivery_id = v_delivery.id AND e.signature_verified AND e.event_type = 'delivered')
      INTO v_delivered;
    SELECT EXISTS (SELECT 1 FROM public.omni_comms_channel_test_delivery_event e
      WHERE e.delivery_id = v_delivery.id AND e.signature_verified
        AND e.event_type IN ('bounced','complained'))
      INTO v_bad;
  END IF;

  RETURN jsonb_build_array(
    jsonb_build_object('sequence',1,'code','tenant_access','state',CASE WHEN p_organization_id IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','Organisation scope resolved.'),
    jsonb_build_object('sequence',2,'code','department_access','state',CASE WHEN v_dep_ok THEN 'passed' ELSE 'failed' END,'detail','Department belongs to the organisation.'),
    jsonb_build_object('sequence',3,'code','channel_supported','state',CASE WHEN p_channel = 'email' THEN 'passed' ELSE 'failed' END,'detail','Release Control supports Email only in C6.'),
    jsonb_build_object('sequence',4,'code','release_not_reference','state',CASE WHEN v_rel.id IS NOT NULL AND v_rel.data_origin <> 'reference_seed' THEN 'passed' ELSE 'failed' END,'detail','Genuine (non-reference) release record required.'),
    jsonb_build_object('sequence',5,'code','effective_policy_present','state',CASE WHEN v_policy.id IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','Effective genuine Email policy resolved.'),
    jsonb_build_object('sequence',6,'code','policy_test_or_pilot_state','state',CASE WHEN v_policy.operational_state IN ('test_only','pilot_ready') THEN 'passed' ELSE 'failed' END,'detail','Policy operational state must be test_only or pilot_ready.'),
    jsonb_build_object('sequence',7,'code','provider_present','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_provider p WHERE p.channel='email' AND p.status='active') THEN 'passed' ELSE 'failed' END,'detail','Active Email provider adapter present.'),
    jsonb_build_object('sequence',8,'code','provider_account_active','state',CASE WHEN v_provider_account IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','Active genuine provider account present.'),
    jsonb_build_object('sequence',9,'code','provider_credentials_complete','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_provider_account_secret_ref s WHERE s.provider_account_id = v_provider_account AND s.purpose='api_key') THEN 'passed' ELSE 'failed' END,'detail','Canonical api_key secret reference present.'),
    jsonb_build_object('sequence',10,'code','provider_credentials_verified','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_provider_account pa WHERE pa.id=v_provider_account AND pa.verification_status='verified') THEN 'passed' ELSE 'failed' END,'detail','Provider credentials verified.'),
    jsonb_build_object('sequence',11,'code','sender_identity_active','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_sender_identity i WHERE i.organization_id=p_organization_id AND i.channel='email' AND i.status='active' AND i.data_origin <> 'reference_seed') THEN 'passed' ELSE 'failed' END,'detail','Active genuine sender identity present.'),
    jsonb_build_object('sequence',12,'code','sending_domain_active','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_channel_endpoint e WHERE e.organization_id=p_organization_id AND e.channel='email' AND e.endpoint_type='sending_domain' AND e.status='active' AND e.data_origin <> 'reference_seed') THEN 'passed' ELSE 'failed' END,'detail','Active sending domain configured.'),
    jsonb_build_object('sequence',13,'code','sending_domain_verified','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_channel_endpoint e WHERE e.organization_id=p_organization_id AND e.channel='email' AND e.endpoint_type='sending_domain' AND e.status='active' AND e.verification_status='verified') THEN 'passed' ELSE 'failed' END,'detail','Sending domain verified with the provider.'),
    jsonb_build_object('sequence',14,'code','callback_endpoint_active','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_channel_endpoint e WHERE e.organization_id=p_organization_id AND e.channel='email' AND e.endpoint_type='event_callback' AND e.status='active') THEN 'passed' ELSE 'failed' END,'detail','Event callback endpoint configured.'),
    jsonb_build_object('sequence',15,'code','binding_active','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_sender_provider_binding b WHERE b.organization_id=p_organization_id AND b.channel='email' AND b.status='active' AND b.data_origin <> 'reference_seed') THEN 'passed' ELSE 'failed' END,'detail','Active identity-to-provider binding present.'),
    jsonb_build_object('sequence',16,'code','binding_provider_verified','state',CASE WHEN EXISTS (SELECT 1 FROM public.omni_comms_sender_provider_binding b WHERE b.organization_id=p_organization_id AND b.channel='email' AND b.status='active' AND b.verification_status='verified') THEN 'passed' ELSE 'failed' END,'detail','Binding verified by the provider.'),
    jsonb_build_object('sequence',17,'code','current_preflight_passed','state',CASE WHEN v_run.id IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','Current configuration preflight passed.'),
    jsonb_build_object('sequence',18,'code','technical_provider_delivery_accepted','state',CASE WHEN v_delivery.id IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','C5B technical provider delivery accepted.'),
    jsonb_build_object('sequence',19,'code','signed_delivery_callback_received','state',CASE WHEN v_delivered THEN 'passed' ELSE 'failed' END,'detail','Signature-verified delivered callback received. Provider acceptance alone is not recipient delivery.'),
    jsonb_build_object('sequence',20,'code','no_bounce_or_complaint_evidence','state',CASE WHEN v_bad THEN 'failed' ELSE 'passed' END,'detail','No bounced or complained outcome on the current technical delivery.'),
    jsonb_build_object('sequence',21,'code','producer_binding_active','state',CASE WHEN coalesce(array_length(v_events,1),0) > 0 AND NOT EXISTS (
        SELECT 1 FROM unnest(v_events) ec CROSS JOIN unnest(v_callers) cm
        WHERE NOT EXISTS (
          SELECT 1 FROM public.omni_comms_producer_event_binding pb
          JOIN public.omni_comms_event_definition ed ON ed.id = pb.event_definition_id
          WHERE pb.organization_id = p_organization_id AND pb.status='active'
            AND 'queued' = ANY (pb.allowed_modes)
            AND ed.code = ec AND ed.status = 'active'
            AND pb.caller_module_code = cm)
      ) THEN 'passed' ELSE 'failed' END,'detail','Active producer-event binding permitting queued mode for every permitted event/caller pair.'),
    jsonb_build_object('sequence',22,'code','event_route_active','state',CASE WHEN coalesce(array_length(v_events,1),0) > 0 AND NOT EXISTS (
        SELECT 1 FROM unnest(v_events) ec WHERE NOT EXISTS (
          SELECT 1 FROM public.omni_comms_event_route r
          JOIN public.omni_comms_event_definition ed ON ed.id = r.event_definition_id
          WHERE r.organization_id = p_organization_id AND r.channel='email'
            AND r.is_enabled AND r.lifecycle_state='active' AND ed.code = ec)
      ) THEN 'passed' ELSE 'failed' END,'detail','Enabled active Email event route present for every permitted event.'),
    jsonb_build_object('sequence',23,'code','template_family_active','state',CASE WHEN coalesce(array_length(v_events,1),0) > 0 AND NOT EXISTS (
        SELECT 1 FROM unnest(v_events) ec WHERE NOT EXISTS (
          SELECT 1 FROM public.omni_comms_event_route r
          JOIN public.omni_comms_template_family tf ON tf.id = r.template_family_id
          JOIN public.omni_comms_event_definition ed ON ed.id = r.event_definition_id
          WHERE r.organization_id = p_organization_id AND r.channel='email'
            AND tf.status='active' AND ed.code = ec)
      ) THEN 'passed' ELSE 'failed' END,'detail','Route resolves an active template family.'),
    jsonb_build_object('sequence',24,'code','published_template_version_present','state',CASE WHEN coalesce(array_length(v_events,1),0) > 0 AND NOT EXISTS (
        SELECT 1 FROM unnest(v_events) ec WHERE NOT EXISTS (
          SELECT 1 FROM public.omni_comms_event_route r
          JOIN public.omni_comms_template_version tv ON tv.template_family_id = r.template_family_id
          JOIN public.omni_comms_event_definition ed ON ed.id = r.event_definition_id
          WHERE r.organization_id = p_organization_id AND r.channel='email'
            AND tv.channel='email' AND tv.status='published' AND ed.code = ec)
      ) THEN 'passed' ELSE 'failed' END,'detail','Published Email template version present.'),
    jsonb_build_object('sequence',25,'code','runtime_environment_known','state',CASE WHEN coalesce(v_env,'') <> '' THEN 'passed' ELSE 'failed' END,'detail','Runtime environment is authoritative.'),
    jsonb_build_object('sequence',26,'code','runtime_certification_effective','state',CASE WHEN v_cert->>'certification_state' = 'certified' AND coalesce(v_cert->>'certified_commit','') ~ '^[0-9a-f]{40}$' AND coalesce(v_cert->>'workflow_run_id','') <> '' AND (v_cert->>'certified_at') IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','Protected runtime certification record is effective.'),
    jsonb_build_object('sequence',27,'code','deployed_revision_matches_certification','state',CASE WHEN lower(coalesce(p_deployed_revision,'')) ~ '^[0-9a-f]{40}$' AND lower(coalesce(p_deployed_revision,'')) = lower(coalesce(v_cert->>'certified_commit','x')) THEN 'passed' ELSE 'failed' END,'detail','Deployed Edge revision equals the certified commit (full 40-character SHA).'),
    jsonb_build_object('sequence',28,'code','release_time_window_valid','state',CASE WHEN v_rel.release_expires_at IS NOT NULL AND v_rel.release_expires_at > now() AND v_rel.release_expires_at <= coalesce(v_rel.release_starts_at, now()) + interval '7 days' THEN 'passed' ELSE 'failed' END,'detail','Expiry is in the future and the pilot window does not exceed seven days.'),
    jsonb_build_object('sequence',29,'code','release_volume_limits_valid','state',CASE WHEN v_rel.id IS NOT NULL AND v_rel.max_recipients_per_request BETWEEN 1 AND 10 AND v_rel.max_messages_per_hour <= v_rel.max_messages_per_day AND v_rel.max_messages_per_day <= v_rel.max_messages_total THEN 'passed' ELSE 'failed' END,'detail','Volume limits are within bounds and correctly laddered.'),
    jsonb_build_object('sequence',30,'code','pilot_recipient_rules_present','state',CASE WHEN v_rel.id IS NOT NULL AND jsonb_array_length(v_rel.pilot_recipient_rules) BETWEEN 1 AND 20 THEN 'passed' ELSE 'failed' END,'detail','Masked/hashed pilot recipient rules present.'),
    jsonb_build_object('sequence',31,'code','live_delivery_legacy_flag_false','state',CASE WHEN coalesce(v_policy.live_delivery_enabled,false) = false THEN 'passed' ELSE 'failed' END,'detail','Legacy live_delivery_enabled flag remains false.'),
    jsonb_build_object('sequence',32,'code','business_dispatch_dispatcher_installed','state',CASE WHEN to_regprocedure('public.omni_comms_priv_dispatch_claim_email(text,integer,text,text,jsonb,text)') IS NOT NULL AND to_regprocedure('public.omni_comms_priv_dispatch_attempt_complete(uuid,text,text,text,integer,jsonb,text,text)') IS NOT NULL THEN 'passed' ELSE 'failed' END,'detail','Controlled business dispatch RPCs are installed; without them dispatch fails closed.')
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_recipient_rules(p_channel text, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_out jsonb := '[]'::jsonb;
  v_item jsonb;
  v_keys text[];
  v_norm jsonb;
  v_hash text;
  v_masked text;
  v_seen text[] := '{}';
BEGIN
  IF p_input IS NULL THEN RETURN '[]'::jsonb; END IF;
  IF jsonb_typeof(p_input) <> 'array' THEN
    RAISE EXCEPTION 'release_recipient_rules_invalid' USING ERRCODE = '22023';
  END IF;
  IF length(p_input::text) > 12000 THEN
    RAISE EXCEPTION 'release_recipient_rules_oversized' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_input) > 20 THEN
    RAISE EXCEPTION 'release_recipient_rules_limit_exceeded' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_input) LOOP
    IF jsonb_typeof(v_item) <> 'object' THEN
      RAISE EXCEPTION 'release_recipient_rule_malformed' USING ERRCODE = '22023';
    END IF;
    SELECT array_agg(k) INTO v_keys FROM jsonb_object_keys(v_item) k;
    IF EXISTS (
      SELECT 1 FROM unnest(v_keys) k
      WHERE k NOT IN ('target_type','target','target_masked','target_hash')
    ) THEN
      RAISE EXCEPTION 'release_recipient_rule_unknown_key' USING ERRCODE = '22023';
    END IF;

    IF v_item ? 'target' AND nullif(trim(v_item->>'target'),'') IS NOT NULL THEN
      v_norm := public.omni_comms_priv_channel_test_normalize_target(p_channel, v_item->>'target');
      v_hash := v_norm->>'target_hash';
      v_masked := v_norm->>'target_masked';
    ELSE
      v_hash := lower(coalesce(v_item->>'target_hash',''));
      v_masked := coalesce(v_item->>'target_masked','');
      IF v_hash !~ '^[0-9a-f]{64}$' OR v_masked = '' THEN
        RAISE EXCEPTION 'release_recipient_rule_malformed' USING ERRCODE = '22023';
      END IF;
      IF v_masked ~ '^[^@]+@' AND v_masked !~ '\*' THEN
        RAISE EXCEPTION 'release_recipient_rule_raw_value_rejected' USING ERRCODE = '22023';
      END IF;
    END IF;

    IF v_hash = ANY (v_seen) THEN
      RAISE EXCEPTION 'release_recipient_rule_duplicate' USING ERRCODE = '22023';
    END IF;
    v_seen := v_seen || v_hash;

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'target_type', 'email_address',
      'target_masked', v_masked,
      'target_hash', v_hash
    ));
  END LOOP;

  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_release_record_event(p_row omni_comms_channel_release_control, p_event_type text, p_from_state text, p_to_state text, p_reason text, p_actor_id uuid, p_correlation_id text, p_deployed_revision text DEFAULT NULL::text, p_snapshot jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.omni_comms_channel_release_event (
    release_control_id, organization_id, department_id, channel, release_version,
    event_type, from_state, to_state, reason, actor_id, correlation_id,
    release_fingerprint, deployed_revision, certified_commit,
    certification_workflow_run_id, bounded_snapshot
  ) VALUES (
    p_row.id, p_row.organization_id, p_row.department_id, p_row.channel, p_row.release_version,
    p_event_type, p_from_state, p_to_state, left(coalesce(p_reason,''), 500), p_actor_id,
    left(coalesce(p_correlation_id,''), 120),
    p_row.release_fingerprint, p_deployed_revision, p_row.approved_commit,
    p_row.certification_workflow_run_id, coalesce(p_snapshot,'{}'::jsonb)
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_setting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.department_id IS NOT NULL THEN
    IF NOT public.omni_comms_priv_verify_department_ownership(NEW.department_id, NEW.organization_id) THEN
      RAISE EXCEPTION 'omni_comms_channel_setting department does not belong to organization'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.quiet_hours_timezone IS NOT NULL THEN
    IF NOT public.omni_comms_priv_validate_timezone(NEW.quiet_hours_timezone) THEN
      RAISE EXCEPTION 'omni_comms_channel_setting invalid timezone %', NEW.quiet_hours_timezone
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Live delivery is governed by future Release Control; never settable here.
  IF COALESCE(NEW.live_delivery_enabled,false) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='live_delivery_governed_by_release_control';
  END IF;
  NEW.live_delivery_enabled := false;

  -- Organisation-scope policies always allow department overrides conceptually.
  IF NEW.department_id IS NULL THEN NEW.department_override_enabled := true; END IF;

  -- enabled is a compatibility mirror owned by the policy worker.
  NEW.enabled := (NEW.operational_state <> 'disabled');

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_checklist(p_channel text, p_snapshot jsonb, p_target jsonb, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  b jsonb   := coalesce(p_snapshot->'binding', 'null'::jsonb);
  a jsonb   := coalesce(p_snapshot->'provider_account', 'null'::jsonb);
  i jsonb   := coalesce(p_snapshot->'identity', 'null'::jsonb);
  e jsonb   := coalesce(p_snapshot->'endpoint', 'null'::jsonb);
  pol jsonb := coalesce(p_snapshot->'policy', 'null'::jsonb);
  v_req text := coalesce(p_snapshot->>'endpoint_requirement','forbidden');
  v_state text := coalesce(pol->>'operational_state','');
  v_dept uuid := nullif(p_snapshot->>'department_id','')::uuid;
  v_bdept uuid := nullif(b->>'department_id','')::uuid;
  v_checks jsonb := '[]'::jsonb;
  v_ok boolean;
BEGIN
  -- 1 tenant_access
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','tenant_access','label','Tenant access','state','passed',
    'detail','The caller holds Omni-Comms access to this organisation and scope.'));

  -- 2 channel_supported
  v_ok := p_channel IN ('email','sms','whatsapp','push','in_app','print');
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','channel_supported','label','Channel supported',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','The channel supports a configuration preflight.'));

  -- 3 effective_policy_present
  v_ok := (pol <> 'null'::jsonb) AND coalesce(pol->>'data_origin','') <> 'reference_seed';
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','effective_policy_present','label','Effective policy present',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','A genuine effective channel policy must resolve for this scope.'));

  -- 4 policy_test_state
  v_ok := v_state IN ('test_only','pilot_ready');
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','policy_test_state','label','Policy permits testing',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','Effective policy must be in test_only or pilot_ready state.'));

  -- 5 binding_selected
  v_ok := (b <> 'null'::jsonb);
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','binding_selected','label','Binding selected',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','A candidate binding must be selected.'));

  -- 6 binding_active
  v_ok := (b->>'status' = 'active');
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','binding_active','label','Binding active',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','Binding lifecycle status must be active.'));

  -- 7 binding_scope_valid
  v_ok := (b <> 'null'::jsonb)
          AND (v_bdept IS NULL OR v_dept IS NOT DISTINCT FROM v_bdept);
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','binding_scope_valid','label','Binding scope valid',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','Binding scope must match the organisation or the selected department.'));

  -- 8 provider_account_active
  v_ok := (a <> 'null'::jsonb) AND (a->>'status' = 'active');
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','provider_account_active','label','Provider account active',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','The bound provider account must exist and be active.'));

  -- 9 provider_credentials_complete
  v_ok := (a <> 'null'::jsonb)
          AND coalesce((a->>'satisfied_credential_count')::int, 0)
              >= coalesce((a->>'required_credential_count')::int, 0);
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','provider_credentials_complete','label','Credential references complete',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','All required credential references must be configured.'));

  -- 10 provider_credentials_verified
  v_ok := coalesce(a->>'verification_status','') = 'verified';
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','provider_credentials_verified','label','Credentials verified',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','The provider account must carry a provider-confirmed verified state.'));

  -- 11 identity_active
  v_ok := (i <> 'null'::jsonb) AND (i->>'status' = 'active')
          AND coalesce(i->>'identity_type','') <> ''
          AND coalesce(i->'identity_config','{}'::jsonb) <> '{}'::jsonb;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','identity_active','label','Channel identity active',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','The bound channel identity must be active and fully configured.'));

  -- 12 endpoint_requirement
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','endpoint_requirement','label','Endpoint requirement',
    'state', CASE
      WHEN v_req = 'required'  THEN CASE WHEN e <> 'null'::jsonb THEN 'passed' ELSE 'failed' END
      WHEN v_req = 'forbidden' THEN CASE WHEN e = 'null'::jsonb THEN 'not_applicable' ELSE 'failed' END
      ELSE CASE WHEN e = 'null'::jsonb THEN 'not_applicable' ELSE 'passed' END END,
    'detail','Endpoint presence must match the channel requirement (' || v_req || ').'));

  -- 13 endpoint_active
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','endpoint_active','label','Endpoint active and verified',
    'state', CASE
      WHEN e = 'null'::jsonb THEN CASE WHEN v_req = 'required' THEN 'failed' ELSE 'not_applicable' END
      WHEN e->>'status' = 'active' AND coalesce(e->>'verification_status','') = 'verified' THEN 'passed'
      WHEN e->>'status' = 'active' THEN 'warning'
      ELSE 'failed' END,
    'detail','A present channel endpoint must be active and verified.'));

  -- 14 binding_verification
  v_ok := coalesce(b->>'verification_status','') = 'verified';
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','binding_verification','label','Binding verification',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','Binding must carry a provider-confirmed verified state.'));

  -- 15 target_valid
  v_ok := coalesce((p_target->>'valid')::boolean, false);
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','target_valid','label','Test target valid',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail', coalesce(p_target->>'code','target_missing')));

  -- 16 payload_valid
  v_ok := coalesce((p_payload->>'valid')::boolean, false);
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','payload_valid','label','Test content valid',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail', coalesce(p_payload->>'code','payload_missing')));

  -- 17 reference_configuration
  v_ok := coalesce(b->>'data_origin','') <> 'reference_seed'
      AND coalesce(a->>'data_origin','') <> 'reference_seed'
      AND coalesce(i->>'data_origin','') <> 'reference_seed'
      AND coalesce(e->>'data_origin','') <> 'reference_seed';
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','reference_configuration','label','No reference configuration',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','Illustrative reference records are non-operational and cannot be tested.'));

  -- 18 live_delivery_disabled (fail-closed safety)
  v_ok := (pol <> 'null'::jsonb)
          AND coalesce((pol->>'live_delivery_enabled')::boolean, false) = false;
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'code','live_delivery_disabled','label','Live delivery disabled',
    'state', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END,
    'detail','Live delivery must remain disabled for technical testing.'));

  -- 19-21 delivery points: not implemented in C5A.1 (never a pass)
  v_checks := v_checks || jsonb_build_array(
    jsonb_build_object('code','provider_dispatch','label','Provider dispatch',
      'state','not_implemented',
      'detail','No provider is contacted. Controlled test delivery is not implemented in this release.'),
    jsonb_build_object('code','delivery_callback','label','Delivery callback',
      'state','not_implemented',
      'detail','No delivery callback is received. Callback handling is not implemented in this release.'),
    jsonb_build_object('code','technical_delivery_result','label','Technical delivery result',
      'state','not_implemented',
      'detail','No delivery result exists. A passed preflight confirms configuration only.'));

  RETURN v_checks;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_checks_valid(p_checks jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT jsonb_typeof(p_checks) = 'array'
     AND jsonb_array_length(p_checks) = 21
     AND (
       SELECT coalesce(array_agg(c->>'code' ORDER BY ord), ARRAY[]::text[])
         FROM jsonb_array_elements(p_checks) WITH ORDINALITY AS t(c, ord)
     ) = ARRAY[
       'tenant_access','channel_supported','effective_policy_present','policy_test_state',
       'binding_selected','binding_active','binding_scope_valid','provider_account_active',
       'provider_credentials_complete','provider_credentials_verified','identity_active',
       'endpoint_requirement','endpoint_active','binding_verification','target_valid',
       'payload_valid','reference_configuration','live_delivery_disabled',
       'provider_dispatch','delivery_callback','technical_delivery_result']
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_checks) c
        WHERE coalesce(c->>'state','') NOT IN
              ('passed','failed','warning','not_applicable','not_implemented')
           OR coalesce(btrim(c->>'label'), '') = ''
           OR coalesce(btrim(c->>'detail'), '') = ''
     );
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_config_fingerprint(p_organization_id uuid, p_department_id uuid, p_channel text, p_binding_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT public.omni_comms_priv_channel_test_sha256(
    public.omni_comms_priv_channel_test_config_snapshot(
      p_organization_id, p_department_id, p_channel, p_binding_id)::text);
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_config_snapshot(p_organization_id uuid, p_department_id uuid, p_channel text, p_binding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  b public.omni_comms_sender_provider_binding%ROWTYPE;
  a public.omni_comms_provider_account%ROWTYPE;
  i public.omni_comms_sender_identity%ROWTYPE;
  e public.omni_comms_channel_endpoint%ROWTYPE;
  s_org public.omni_comms_channel_setting%ROWTYPE;
  s_dept public.omni_comms_channel_setting%ROWTYPE;
  s_eff public.omni_comms_channel_setting%ROWTYPE;
  v_policy jsonb := 'null'::jsonb;
  v_policy_source text := 'none';
  v_dept_found boolean := false;
  v_req_total integer := 0;
  v_req_met integer := 0;
  v_acct_ref_count integer := 0;
  v_acct_ref_digest text := public.omni_comms_priv_channel_test_sha256('');
  v_ep_ref_count integer := 0;
  v_ep_ref_digest text := public.omni_comms_priv_channel_test_sha256('');
BEGIN
  IF p_binding_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='binding_required';
  END IF;

  SELECT * INTO b FROM public.omni_comms_sender_provider_binding WHERE id = p_binding_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='binding_not_found';
  END IF;
  IF b.organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied'
      USING ERRCODE='P0001', DETAIL='binding_organization_mismatch';
  END IF;
  IF b.channel IS DISTINCT FROM p_channel THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='binding_channel_mismatch';
  END IF;

  SELECT * INTO a FROM public.omni_comms_provider_account WHERE id = b.provider_account_id;
  SELECT * INTO i FROM public.omni_comms_sender_identity   WHERE id = b.sender_identity_id;
  IF b.channel_endpoint_id IS NOT NULL THEN
    SELECT * INTO e FROM public.omni_comms_channel_endpoint WHERE id = b.channel_endpoint_id;
  END IF;

  SELECT * INTO s_org FROM public.omni_comms_channel_setting
   WHERE organization_id = p_organization_id AND department_id IS NULL
     AND channel = p_channel AND data_origin <> 'reference_seed';

  IF p_department_id IS NOT NULL THEN
    SELECT * INTO s_dept FROM public.omni_comms_channel_setting
     WHERE organization_id = p_organization_id AND department_id = p_department_id
       AND channel = p_channel AND data_origin <> 'reference_seed';
    v_dept_found := FOUND;
  END IF;

  IF v_dept_found AND coalesce(s_dept.department_override_enabled,false) THEN
    s_eff := s_dept;
    v_policy := public.omni_comms_priv_channel_policy_json(s_dept);
    v_policy_source := 'department_override';
  ELSIF s_org.id IS NOT NULL THEN
    s_eff := s_org;
    v_policy := public.omni_comms_priv_channel_policy_json(s_org);
    v_policy_source := 'organisation_baseline';
  END IF;

  IF a.id IS NOT NULL THEN
    SELECT count(*) INTO v_req_total
      FROM public.omni_comms_provider_credential_requirement r
     WHERE r.provider_id = a.provider_id AND r.required = true;

    SELECT count(*) INTO v_req_met
      FROM public.omni_comms_provider_credential_requirement r
      JOIN public.omni_comms_provider_account_secret_ref sr
        ON sr.provider_account_id = a.id AND sr.purpose = r.purpose
       AND btrim(coalesce(sr.secret_ref,'')) <> ''
     WHERE r.provider_id = a.provider_id AND r.required = true;

    -- Safe canonical credential-reference metadata: a one-way digest over
    -- purpose + secret NAME + last-updated time. Never a credential value,
    -- and the names themselves are never returned.
    SELECT count(*),
           public.omni_comms_priv_channel_test_sha256(
             coalesce(string_agg(
               sr.purpose || '|' || coalesce(sr.secret_ref,'') || '|' ||
               coalesce(to_char(sr.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.USZ'),''),
               String_agg_sep ORDER BY sr.purpose, sr.id), ''))
      INTO v_acct_ref_count, v_acct_ref_digest
      FROM public.omni_comms_provider_account_secret_ref sr,
           LATERAL (SELECT E'\n' AS String_agg_sep) sep
     WHERE sr.provider_account_id = a.id;
  END IF;

  IF e.id IS NOT NULL THEN
    SELECT count(*),
           public.omni_comms_priv_channel_test_sha256(
             coalesce(string_agg(
               sr.purpose || '|' || coalesce(sr.secret_ref,'') || '|' ||
               coalesce(to_char(sr.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.USZ'),''),
               String_agg_sep ORDER BY sr.purpose, sr.id), ''))
      INTO v_ep_ref_count, v_ep_ref_digest
      FROM public.omni_comms_channel_endpoint_secret_ref sr,
           LATERAL (SELECT E'\n' AS String_agg_sep) sep
     WHERE sr.channel_endpoint_id = e.id;
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'schema_version', 2,
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'channel', p_channel,
    'endpoint_requirement', public.omni_comms_priv_binding_endpoint_requirement(p_channel),
    'binding', jsonb_build_object(
      'id', b.id,
      'status', b.status,
      'priority', b.priority,
      'verification_status', b.verification_status,
      'verification_source', b.verification_source,
      'verification_result_code', b.verification_result_code,
      'data_origin', b.data_origin,
      'department_id', b.department_id,
      'updated_at', b.updated_at
    ),
    'provider_account', CASE WHEN a.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
      'id', a.id,
      'provider_id', a.provider_id,
      'code', a.code,
      'status', a.status,
      'environment', a.environment,
      'region', a.region,
      'verification_status', a.verification_status,
      'verification_result_code', a.verification_result_code,
      'data_origin', a.data_origin,
      'credential_reference_count', v_acct_ref_count,
      'credential_reference_digest', v_acct_ref_digest,
      'required_credential_count', v_req_total,
      'satisfied_credential_count', v_req_met,
      'updated_at', a.updated_at
    ) END,
    'identity', CASE WHEN i.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
      'id', i.id,
      'code', i.code,
      'status', i.status,
      'identity_type', i.identity_type,
      'identity_config', coalesce(i.identity_config, '{}'::jsonb),
      'data_origin', i.data_origin,
      'department_id', i.department_id,
      'updated_at', i.updated_at
    ) END,
    'endpoint', CASE WHEN e.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
      'id', e.id,
      'code', e.code,
      'status', e.status,
      'endpoint_type', e.endpoint_type,
      'endpoint_config', coalesce(e.endpoint_config, '{}'::jsonb),
      'verification_status', e.verification_status,
      'data_origin', e.data_origin,
      'secret_reference_count', v_ep_ref_count,
      'secret_reference_digest', v_ep_ref_digest,
      'department_id', e.department_id,
      'updated_at', e.updated_at
    ) END,
    'policy', v_policy,
    'policy_id', s_eff.id,
    'policy_updated_at', s_eff.updated_at,
    'policy_source', v_policy_source
  ));
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_delivery_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'OC409 immutable_evidence'
      USING ERRCODE='P0001', DETAIL='test_delivery_attempt_delete_forbidden';
  END IF;
  IF OLD.state <> 'claimed' THEN
    RAISE EXCEPTION 'OC409 immutable_evidence'
      USING ERRCODE='P0001', DETAIL='test_delivery_attempt_terminal_immutable';
  END IF;
  IF NEW.id <> OLD.id OR NEW.delivery_id <> OLD.delivery_id
     OR NEW.attempt_number <> OLD.attempt_number
     OR NEW.claim_token <> OLD.claim_token
     OR NEW.provider_idempotency_key <> OLD.provider_idempotency_key THEN
    RAISE EXCEPTION 'OC409 immutable_evidence'
      USING ERRCODE='P0001', DETAIL='test_delivery_attempt_identity_immutable';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_delivery_complete(p_delivery_id uuid, p_claim_token uuid, p_status text, p_result_code text, p_provider_message_id text DEFAULT NULL::text, p_provider_status_code integer DEFAULT NULL::integer, p_provider_response jsonb DEFAULT NULL::jsonb, p_error_code text DEFAULT NULL::text, p_error_detail text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_row public.omni_comms_channel_test_delivery%ROWTYPE;
BEGIN
  IF p_status NOT IN ('accepted','failed','outcome_unknown') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_status'; END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='claim_token_required'; END IF;

  UPDATE public.omni_comms_channel_test_delivery
     SET status = p_status,
         result_code = p_result_code,
         provider_message_id = coalesce(p_provider_message_id, provider_message_id),
         provider_status_code = p_provider_status_code,
         provider_response = p_provider_response,
         error_code = p_error_code,
         error_detail = left(coalesce(p_error_detail,''), 500),
         active_claim_token = NULL,
         completed_at = CASE WHEN p_status = 'outcome_unknown' THEN NULL ELSE now() END
   WHERE id = p_delivery_id
     AND status = 'dispatching'
     AND active_claim_token = p_claim_token
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC409 stale_worker'
      USING ERRCODE='P0001', DETAIL='delivery_claim_no_longer_valid'; END IF;

  UPDATE public.omni_comms_channel_test_delivery_attempt
     SET state = p_status,
         result_code = p_result_code,
         provider_message_id = p_provider_message_id,
         provider_status_code = p_provider_status_code,
         response_summary = coalesce(p_provider_response,'{}'::jsonb),
         error_code = p_error_code,
         error_detail = left(coalesce(p_error_detail,''), 500),
         completed_at = now()
   WHERE delivery_id = p_delivery_id AND claim_token = p_claim_token AND state = 'claimed';

  RETURN public.omni_comms_priv_channel_test_delivery_json(v_row, true);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_delivery_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'OC409 immutable_evidence'
    USING ERRCODE='P0001', DETAIL='test_delivery_event_immutable';
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_delivery_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'OC409 immutable_evidence'
      USING ERRCODE='P0001', DETAIL='test_delivery_delete_forbidden';
  END IF;
  IF OLD.status NOT IN ('pending','dispatching','outcome_unknown') THEN
    RAISE EXCEPTION 'OC409 immutable_evidence'
      USING ERRCODE='P0001', DETAIL='test_delivery_result_immutable';
  END IF;
  IF NEW.id <> OLD.id
     OR NEW.test_run_id <> OLD.test_run_id
     OR NEW.organization_id <> OLD.organization_id
     OR NEW.binding_id <> OLD.binding_id
     OR NEW.idempotency_key <> OLD.idempotency_key
     OR NEW.request_fingerprint <> OLD.request_fingerprint
     OR NEW.target_hash <> OLD.target_hash
     OR NEW.payload_hash <> OLD.payload_hash
     OR NEW.provider_idempotency_key IS DISTINCT FROM OLD.provider_idempotency_key
     OR NEW.provider_payload_hash IS DISTINCT FROM OLD.provider_payload_hash THEN
    RAISE EXCEPTION 'OC409 immutable_evidence'
      USING ERRCODE='P0001', DETAIL='test_delivery_identity_immutable';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_delivery_json(r omni_comms_channel_test_delivery, p_include_detail boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT jsonb_build_object(
    'id', r.id,
    'test_run_id', r.test_run_id,
    'organization_id', r.organization_id,
    'department_id', r.department_id,
    'channel', r.channel,
    'binding_id', r.binding_id,
    'provider_code', r.provider_code,
    'provider_account_id', r.provider_account_id,
    'sender_identity_id', r.sender_identity_id,
    'channel_endpoint_id', r.channel_endpoint_id,
    'policy_id', r.policy_id,
    'from_address', r.from_address,
    'idempotency_key', r.idempotency_key,
    'request_fingerprint', r.request_fingerprint,
    'configuration_fingerprint', r.configuration_fingerprint,
    'provider_payload_hash', r.provider_payload_hash,
    'provider_idempotency_key', r.provider_idempotency_key,
    'attempt_count', r.attempt_count,
    'target_type', r.target_type,
    'target_masked', r.target_masked,
    'payload_summary', r.payload_summary,
    'status', r.status,
    'result_code', r.result_code,
    'provider_message_id', r.provider_message_id,
    'provider_status_code', r.provider_status_code,
    'provider_response', CASE WHEN p_include_detail THEN r.provider_response ELSE NULL END,
    'error_code', r.error_code,
    'error_detail', CASE WHEN p_include_detail THEN r.error_detail ELSE NULL END,
    'correlation_id', r.correlation_id,
    'requested_by', r.requested_by,
    'requested_at', r.requested_at,
    'completed_at', r.completed_at,
    'attempts', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', a.id,
               'attempt_number', a.attempt_number,
               'state', a.state,
               'result_code', a.result_code,
               'provider_message_id', a.provider_message_id,
               'provider_status_code', a.provider_status_code,
               'error_code', a.error_code,
               'started_at', a.started_at,
               'completed_at', a.completed_at)
             ORDER BY a.attempt_number)
        FROM public.omni_comms_channel_test_delivery_attempt a
       WHERE a.delivery_id = r.id), '[]'::jsonb),
    'events', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', e.id,
               'event_type', e.event_type,
               'provider_event_id', e.provider_event_id,
               'signature_verified', e.signature_verified,
               'occurred_at', e.occurred_at,
               'received_at', e.received_at,
               'payload_summary', e.payload_summary)
             ORDER BY e.received_at)
        FROM public.omni_comms_channel_test_delivery_event e
       WHERE e.delivery_id = r.id), '[]'::jsonb));
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_delivery_record_event(p_provider_message_id text, p_event_type text, p_provider_event_id text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_payload_summary jsonb DEFAULT '{}'::jsonb, p_signature_verified boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_delivery public.omni_comms_channel_test_delivery%ROWTYPE;
  v_id uuid;
  v_type text := btrim(coalesce(p_event_type,''));
BEGIN
  IF coalesce(btrim(p_provider_message_id),'') = '' OR v_type = '' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_input'; END IF;
  IF coalesce(p_signature_verified,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'OC403 signature_invalid'
      USING ERRCODE='P0001', DETAIL='callback_signature_not_verified'; END IF;
  IF v_type NOT IN ('sent','delivered','delivery_delayed','bounced','complained',
                    'opened','clicked','failed') THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE='P0001', DETAIL='callback_event_type_unsupported'; END IF;

  SELECT * INTO v_delivery FROM public.omni_comms_channel_test_delivery
   WHERE provider_message_id = btrim(p_provider_message_id) LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('matched', false); END IF;

  IF p_provider_event_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.omni_comms_channel_test_delivery_event
        WHERE provider_event_id = btrim(p_provider_event_id)) THEN
    RETURN jsonb_build_object(
      'matched', true, 'delivery_id', v_delivery.id, 'event_id', NULL, 'duplicate', true);
  END IF;

  INSERT INTO public.omni_comms_channel_test_delivery_event (
    delivery_id, organization_id, channel, event_type, provider_event_id,
    provider_message_id, signature_verified, occurred_at, payload_summary)
  VALUES (
    v_delivery.id, v_delivery.organization_id, v_delivery.channel,
    v_type, nullif(btrim(coalesce(p_provider_event_id,'')),''),
    btrim(p_provider_message_id), true,
    p_occurred_at, coalesce(p_payload_summary,'{}'::jsonb))
  ON CONFLICT (delivery_id, event_type, coalesce(provider_event_id,'')) DO NOTHING
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'matched', true, 'delivery_id', v_delivery.id,
    'event_id', v_id, 'duplicate', (v_id IS NULL));
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_effective_policy(p_organization_id uuid, p_department_id uuid, p_channel text)
 RETURNS omni_comms_channel_setting
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org public.omni_comms_channel_setting%ROWTYPE;
  v_dept public.omni_comms_channel_setting%ROWTYPE;
BEGIN
  IF p_department_id IS NOT NULL THEN
    SELECT * INTO v_dept FROM public.omni_comms_channel_setting
     WHERE organization_id = p_organization_id AND channel = p_channel
       AND department_id = p_department_id
       AND coalesce(data_origin,'') <> 'reference_seed' LIMIT 1;
    IF FOUND AND coalesce(v_dept.department_override_enabled,false) THEN
      RETURN v_dept;
    END IF;
  END IF;
  SELECT * INTO v_org FROM public.omni_comms_channel_setting
   WHERE organization_id = p_organization_id AND channel = p_channel
     AND department_id IS NULL
     AND coalesce(data_origin,'') <> 'reference_seed' LIMIT 1;
  RETURN v_org;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_normalize_payload(p_channel text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v jsonb := coalesce(p_payload, '{}'::jsonb);
  v_allowed text[];
  v_key text;
  v_bytes integer;
  v_summary jsonb;
  v_s text; v_b text; v_t text; v_d text; v_lang text; v_vars jsonb;
BEGIN
  IF jsonb_typeof(v) <> 'object' THEN
    RETURN jsonb_build_object('valid', false, 'code', 'payload_not_object');
  END IF;

  v_bytes := octet_length(v::text);
  IF v_bytes > 20000 THEN
    RETURN jsonb_build_object('valid', false, 'code', 'payload_too_large');
  END IF;

  v_allowed := CASE p_channel
    WHEN 'email'    THEN ARRAY['subject','body']
    WHEN 'sms'      THEN ARRAY['text']
    WHEN 'whatsapp' THEN ARRAY['template_code','language_code','variables']
    WHEN 'push'     THEN ARRAY['title','body']
    WHEN 'in_app'   THEN ARRAY['title','body','deep_link']
    WHEN 'print'    THEN ARRAY['document_title','sample_text']
    ELSE ARRAY[]::text[] END;

  IF array_length(v_allowed, 1) IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'code', 'payload_channel_unsupported');
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(v) LOOP
    IF NOT (v_key = ANY (v_allowed)) THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_unknown_key');
    END IF;
  END LOOP;

  IF p_channel = 'email' THEN
    v_s := btrim(coalesce(v->>'subject',''));
    v_b := coalesce(v->>'body','');
    IF v_s = '' OR length(v_s) > 200 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_subject'); END IF;
    IF btrim(v_b) = '' OR length(v_b) > 10000 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_body'); END IF;
    IF v_b ~ '<\s*[A-Za-z/!]' OR v_s ~ '<\s*[A-Za-z/!]' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_markup_not_allowed'); END IF;
    v_summary := jsonb_build_object(
      'subject', v_s,
      'body_character_count', length(v_b),
      'attachment_count', 0,
      'payload_byte_count', v_bytes);

  ELSIF p_channel = 'sms' THEN
    v_b := coalesce(v->>'text','');
    IF btrim(v_b) = '' OR length(v_b) > 1600 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_text'); END IF;
    v_summary := jsonb_build_object(
      'message_character_count', length(v_b),
      'payload_byte_count', v_bytes);

  ELSIF p_channel = 'whatsapp' THEN
    v_t := btrim(coalesce(v->>'template_code',''));
    v_lang := btrim(coalesce(v->>'language_code',''));
    v_vars := coalesce(v->'variables', '[]'::jsonb);
    IF v_t !~ '^[a-z][a-z0-9_]{2,63}$' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_template_code'); END IF;
    IF v_lang !~ '^[a-z]{2}(_[A-Z]{2})?$' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_language_code'); END IF;
    IF jsonb_typeof(v_vars) <> 'array' OR jsonb_array_length(v_vars) > 20 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_variables'); END IF;
    v_summary := jsonb_build_object(
      'template_code', v_t,
      'language_code', v_lang,
      'variable_count', jsonb_array_length(v_vars),
      'payload_byte_count', v_bytes);

  ELSIF p_channel = 'push' THEN
    v_t := btrim(coalesce(v->>'title',''));
    v_b := coalesce(v->>'body','');
    IF v_t = '' OR length(v_t) > 120 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_title'); END IF;
    IF btrim(v_b) = '' OR length(v_b) > 1000 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_body'); END IF;
    v_summary := jsonb_build_object(
      'title', v_t,
      'body_character_count', length(v_b),
      'payload_byte_count', v_bytes);

  ELSIF p_channel = 'in_app' THEN
    v_t := btrim(coalesce(v->>'title',''));
    v_b := coalesce(v->>'body','');
    v_d := btrim(coalesce(v->>'deep_link',''));
    IF v_t = '' OR length(v_t) > 160 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_title'); END IF;
    IF btrim(v_b) = '' OR length(v_b) > 4000 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_body'); END IF;
    IF length(v_d) > 500 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_deep_link'); END IF;
    v_summary := jsonb_build_object(
      'title', v_t,
      'body_character_count', length(v_b),
      'deep_link_present', (v_d <> ''),
      'payload_byte_count', v_bytes);

  ELSE
    v_t := btrim(coalesce(v->>'document_title',''));
    v_b := coalesce(v->>'sample_text','');
    IF v_t = '' OR length(v_t) > 200 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_document_title'); END IF;
    IF btrim(v_b) = '' OR length(v_b) > 10000 THEN
      RETURN jsonb_build_object('valid', false, 'code', 'payload_invalid_sample_text'); END IF;
    v_summary := jsonb_build_object(
      'document_title', v_t,
      'sample_character_count', length(v_b),
      'payload_byte_count', v_bytes);
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'code', 'payload_valid',
    'payload_summary', v_summary,
    'payload_hash', public.omni_comms_priv_channel_test_sha256(p_channel || '|' || v::text)
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_normalize_target(p_channel text, p_target text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v text := btrim(coalesce(p_target,''));
  v_digits text;
  v_type text;
  v_masked text;
BEGIN
  IF v = '' THEN
    RETURN jsonb_build_object('valid', false, 'code', 'target_missing');
  END IF;

  IF p_channel = 'email' THEN
    v_type := 'email_address';
    v := lower(v);
    IF length(v) > 254 OR v !~ '^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'target_invalid_email');
    END IF;
    v_masked := public.omni_comms_priv_mask_email(v);

  ELSIF p_channel IN ('sms','whatsapp') THEN
    v_type := CASE WHEN p_channel = 'sms' THEN 'phone_number' ELSE 'whatsapp_number' END;
    v := regexp_replace(v, '[\s()\-\.]', '', 'g');
    IF v !~ '^\+[1-9][0-9]{6,14}$' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'target_invalid_phone');
    END IF;
    v_digits := regexp_replace(v, '\D', '', 'g');
    v_masked := '+' || left(v_digits, 1)
                || repeat('*', greatest(length(v_digits) - 5, 1))
                || right(v_digits, 4);

  ELSIF p_channel = 'push' THEN
    v_type := 'device_token';
    IF length(v) < 8 OR length(v) > 512 OR v ~ '\s' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'target_invalid_device_token');
    END IF;
    v_masked := 'tok_' || repeat('*', 6) || right(v, 4);

  ELSIF p_channel = 'in_app' THEN
    v_type := 'user_reference';
    IF length(v) < 3 OR length(v) > 128 OR v !~ '^[A-Za-z0-9._:@-]+$' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'target_invalid_user_reference');
    END IF;
    v_masked := public.omni_comms_priv_mask_reference(v);

  ELSIF p_channel = 'print' THEN
    v_type := 'recipient_reference';
    IF length(v) < 3 OR length(v) > 160 OR v !~ '^[A-Za-z0-9 .,''\-/#&()]+$' THEN
      RETURN jsonb_build_object('valid', false, 'code', 'target_invalid_recipient_reference');
    END IF;
    v_masked := public.omni_comms_priv_mask_reference(v);

  ELSE
    RETURN jsonb_build_object('valid', false, 'code', 'target_channel_unsupported');
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'code', 'target_valid',
    'target_type', v_type,
    'target_masked', coalesce(v_masked, 'masked'),
    'target_hash', public.omni_comms_priv_channel_test_sha256(p_channel || '|' || v)
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_channel_test_run_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
