 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
  SELECT replace(replace(replace(COALESCE(p_input, ''), '\', '\\'), '%', '\%'), '_', '\_');
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_event_route_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_tf record; v_si record;
BEGIN
  PERFORM public.omni_comms_priv_validate_channel(NEW.channel);
  IF NEW.department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(NEW.department_id, NEW.organization_id);
  END IF;
  IF NEW.template_family_id IS NOT NULL THEN
    SELECT organization_id INTO v_tf FROM public.omni_comms_template_family WHERE id = NEW.template_family_id;
    IF v_tf.organization_id IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'OC422 template_family_org_mismatch' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF NEW.sender_identity_id IS NOT NULL THEN
    SELECT organization_id, channel INTO v_si FROM public.omni_comms_sender_identity WHERE id = NEW.sender_identity_id;
    IF v_si.organization_id IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'OC422 sender_identity_org_mismatch' USING ERRCODE = 'P0001';
    END IF;
    IF v_si.channel <> NEW.channel THEN
      RAISE EXCEPTION 'OC422 sender_identity_channel_mismatch' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.lifecycle_state = 'retired' AND NEW.lifecycle_state <> 'retired' THEN
      RAISE EXCEPTION 'OC422 route_retired_immutable' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_extract_tokens(p_source text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_len integer;
  v_i integer := 1;
  v_ch text;
  v_next text;
  v_end integer;
  v_body text;
  v_close integer;
  v_tokens text[] := ARRAY[]::text[];
BEGIN
  IF p_source IS NULL OR p_source = '' THEN
    RETURN v_tokens;
  END IF;
  v_len := length(p_source);
  WHILE v_i <= v_len LOOP
    v_ch := substr(p_source, v_i, 1);
    IF v_ch = '{' THEN
      IF v_i + 1 > v_len THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_unmatched_open';
      END IF;
      v_next := substr(p_source, v_i + 1, 1);
      IF v_next <> '{' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_unmatched_open';
      END IF;
      -- reject triple brace
      IF v_i + 2 <= v_len AND substr(p_source, v_i + 2, 1) = '{' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_triple_brace';
      END IF;
      v_close := position('}}' in substr(p_source, v_i + 2));
      IF v_close = 0 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_unmatched_open';
      END IF;
      v_body := substr(p_source, v_i + 2, v_close - 1);
      -- reject nested braces / control chars inside body
      IF v_body ~ '[{}#/^!>@=]' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_disallowed_syntax';
      END IF;
      v_body := btrim(v_body);
      IF v_body = '' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_empty';
      END IF;
      IF NOT (v_body ~ '^[a-zA-Z_][a-zA-Z0-9_]*(\.[a-zA-Z_][a-zA-Z0-9_]*)*$') THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_path_invalid';
      END IF;
      IF NOT (v_body = ANY(v_tokens)) THEN
        v_tokens := array_append(v_tokens, v_body);
      END IF;
      v_i := v_i + 2 + v_close + 1;
    ELSIF v_ch = '}' THEN
      IF v_i + 1 <= v_len AND substr(p_source, v_i + 1, 1) = '}' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_token_unmatched_close';
      END IF;
      v_i := v_i + 1;
    ELSE
      v_i := v_i + 1;
    END IF;
  END LOOP;
  RETURN v_tokens;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_finalize_resolution(p_actor_id uuid, p_request_id uuid, p_organization_id uuid, p_resolution_snapshot jsonb, p_recipients jsonb, p_request_blockers text[], p_final_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req                record;
  v_recipient          jsonb;
  v_recipient_id       uuid;
  v_existing_count     int;
  v_persisted          jsonb := '[]'::jsonb;
  v_event_type         text;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_request_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF p_final_status NOT IN ('processing','blocked') THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF jsonb_typeof(p_recipients) <> 'array' THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF jsonb_typeof(p_resolution_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF octet_length(p_resolution_snapshot::text) > 524288 THEN
    RAISE EXCEPTION 'OC422 payload_too_large' USING ERRCODE='P0001';
  END IF;

  SELECT * INTO v_req
  FROM public.omni_comms_request
  WHERE id = p_request_id AND organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 request_not_found' USING ERRCODE='P0001';
  END IF;

  -- Replay guard: if recipients already exist, return them without new writes.
  SELECT count(*) INTO v_existing_count
  FROM public.omni_comms_recipient WHERE request_id = p_request_id;

  IF v_existing_count > 0 THEN
    SELECT jsonb_agg(to_jsonb(rc.*) ORDER BY rc.created_at, rc.id)
      INTO v_persisted
    FROM public.omni_comms_recipient rc WHERE rc.request_id = p_request_id;
    RETURN jsonb_build_object(
      'request_id', v_req.id,
      'status',     v_req.status,
      'replayed',   true,
      'recipients', coalesce(v_persisted,'[]'::jsonb),
      'blockers',   v_req.blockers
    );
  END IF;

  IF v_req.status <> 'accepted' THEN
    RAISE EXCEPTION 'OC409 request_already_resolved' USING ERRCODE='P0001';
  END IF;

  -- Transition accepted -> processing.
  UPDATE public.omni_comms_request
     SET status = 'processing', updated_at = now()
   WHERE id = p_request_id;

  INSERT INTO public.omni_comms_message_event (
    request_id, message_id, organization_id, event_type, event_sequence,
    status_before, status_after, safe_metadata,
    correlation_id, actor_type, actor_id
  ) VALUES (
    p_request_id, NULL, p_organization_id, 'request_processing',
    public.omni_comms_priv_next_event_sequence(p_request_id),
    'accepted', 'processing',
    jsonb_build_object(
      'snapshot_at',       p_resolution_snapshot->>'snapshot_at',
      'recipient_count',   jsonb_array_length(p_recipients)
    ),
    v_req.correlation_id, 'system', p_actor_id::text
  );

  -- Insert recipients + per-recipient events.
  FOR v_recipient IN SELECT * FROM jsonb_array_elements(p_recipients) LOOP
    INSERT INTO public.omni_comms_recipient (
      request_id, organization_id, recipient_type, recipient_reference,
      display_name, locale, email_destination, phone_destination,
      push_destination, destination_snapshot, eligibility_status,
      resolved_channels, blockers, resolution_snapshot
    ) VALUES (
      p_request_id, p_organization_id,
      coalesce(v_recipient->>'recipient_type','person'),
      v_recipient->>'recipient_reference',
      v_recipient->>'display_name',
      v_recipient->>'locale',
      v_recipient->>'email_destination',
      v_recipient->>'phone_destination',
      v_recipient->>'push_destination',
      coalesce(v_recipient->'destination_snapshot','{}'::jsonb),
      coalesce(v_recipient->>'eligibility_status','pending'),
      COALESCE(
        (SELECT array_agg(x)::text[]
           FROM jsonb_array_elements_text(v_recipient->'resolved_channels') AS t(x)),
        ARRAY[]::text[]
      ),
      coalesce(v_recipient->'blockers','[]'::jsonb),
      coalesce(v_recipient->'per_recipient_snapshot','{}'::jsonb)
    ) RETURNING id INTO v_recipient_id;

    v_event_type := CASE
      WHEN (v_recipient->>'eligibility_status') IN ('eligible','partially_eligible')
        THEN 'recipient_resolved'
      ELSE 'recipient_blocked'
    END;

    INSERT INTO public.omni_comms_message_event (
      request_id, message_id, organization_id, event_type, event_sequence,
      status_before, status_after, safe_metadata,
      correlation_id, actor_type, actor_id
    ) VALUES (
      p_request_id, NULL, p_organization_id, v_event_type,
      public.omni_comms_priv_next_event_sequence(p_request_id),
      NULL, NULL,
      jsonb_build_object(
        'recipient_id',       v_recipient_id,
        'eligibility_status', v_recipient->>'eligibility_status',
        'resolved_channels',  coalesce(v_recipient->'resolved_channels','[]'::jsonb),
        'blocker_count',      coalesce(jsonb_array_length(v_recipient->'blockers'),0)
      ),
      v_req.correlation_id, 'system', p_actor_id::text
    );
  END LOOP;

  -- Persist request-level blockers.
  UPDATE public.omni_comms_request
     SET blockers = coalesce(
           (SELECT jsonb_agg(to_jsonb(b))
              FROM unnest(coalesce(p_request_blockers, ARRAY[]::text[])) AS b),
           '[]'::jsonb),
         updated_at = now()
   WHERE id = p_request_id;

  IF p_final_status = 'blocked' THEN
    UPDATE public.omni_comms_request
       SET status = 'blocked', failed_at = now(), updated_at = now()
     WHERE id = p_request_id;

    INSERT INTO public.omni_comms_message_event (
      request_id, message_id, organization_id, event_type, event_sequence,
      status_before, status_after, safe_metadata,
      correlation_id, actor_type, actor_id
    ) VALUES (
      p_request_id, NULL, p_organization_id, 'request_failed',
      public.omni_comms_priv_next_event_sequence(p_request_id),
      'processing', 'blocked',
      jsonb_build_object(
        'blockers',
        coalesce(to_jsonb(p_request_blockers), '[]'::jsonb)
      ),
      v_req.correlation_id, 'system', p_actor_id::text
    );
  END IF;

  SELECT jsonb_agg(to_jsonb(rc.*) ORDER BY rc.created_at, rc.id)
    INTO v_persisted
  FROM public.omni_comms_recipient rc WHERE rc.request_id = p_request_id;

  SELECT * INTO v_req FROM public.omni_comms_request WHERE id = p_request_id;

  RETURN jsonb_build_object(
    'request_id', v_req.id,
    'status',     v_req.status,
    'replayed',   false,
    'recipients', coalesce(v_persisted,'[]'::jsonb),
    'blockers',   v_req.blockers
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_is_resend_secret_ref(p_ref text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT p_ref IS NOT NULL
     AND p_ref ~ '^OMNI_COMMS_RESEND_[A-Z0-9]+(_[A-Z0-9]+)*$';
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_is_secret_ref_name(p_ref text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT p_ref IS NOT NULL
     AND p_ref ~ '^OMNI_COMMS_[A-Z0-9]+(_[A-Z0-9]+)*$'
     AND char_length(p_ref) BETWEEN 16 AND 96;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_layout_kind_matches_channel(p_layout_kind text, p_channel text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT CASE
    WHEN p_layout_kind IS NULL THEN true
    WHEN upper(p_layout_kind) = upper(p_channel) THEN true
    WHEN upper(p_channel) = 'PRINT' AND upper(p_layout_kind) IN ('LETTER','LETTERHEAD','NOTICE','STATEMENT','CERTIFICATE','REPORT','RECEIPT') THEN true
    ELSE false
  END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_layout_selection_valid(p_mode text, p_layout_id uuid, p_pinned_layout_version_id uuid, p_channel text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_kind text; v_active boolean; v_pv_layout uuid; v_pv_status text;
BEGIN
  IF p_mode IS NULL OR p_layout_id IS NULL THEN RETURN false; END IF;
  IF p_mode NOT IN ('resolved_default','pinned') THEN RETURN false; END IF;
  SELECT l.layout_kind, l.is_active INTO v_kind, v_active
    FROM public.core_template_layout l WHERE l.id = p_layout_id;
  IF NOT FOUND OR COALESCE(v_active,false) = false THEN RETURN false; END IF;
  IF NOT public.omni_comms_priv_layout_kind_matches_channel(v_kind, p_channel) THEN RETURN false; END IF;
  IF p_mode = 'pinned' THEN
    IF p_pinned_layout_version_id IS NULL THEN RETURN false; END IF;
    SELECT lv.layout_id, lv.status INTO v_pv_layout, v_pv_status
      FROM public.core_template_layout_version lv WHERE lv.id = p_pinned_layout_version_id;
    IF NOT FOUND THEN RETURN false; END IF;
    IF v_pv_layout IS DISTINCT FROM p_layout_id THEN RETURN false; END IF;
    IF v_pv_status <> 'published' THEN RETURN false; END IF;
  END IF;
  RETURN true;
END;$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_load_persisted_messages(p_actor_id uuid, p_request_id uuid, p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req record;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_request_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;

  SELECT id, status, mode INTO v_req
  FROM public.omni_comms_request
  WHERE id = p_request_id AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 request_not_found' USING ERRCODE='P0001';
  END IF;

  RETURN jsonb_build_object(
    'request_id', v_req.id,
    'status',     v_req.status,
    'mode',       v_req.mode,
    'messages', coalesce((
      SELECT jsonb_agg(
               jsonb_build_object(
                 'message_id',        m.id,
                 'recipient_id',      m.recipient_id,
                 'channel',           m.channel,
                 'status',            m.status,
                 'rendered_checksum', m.rendered_checksum,
                 'dispatch_job_id',   j.id,
                 'blockers',          coalesce(m.blockers, '[]'::jsonb)
               )
               ORDER BY m.created_at, m.id
             )
      FROM public.omni_comms_message m
      LEFT JOIN LATERAL (
        SELECT dj.id
        FROM public.omni_comms_dispatch_job dj
        WHERE dj.message_id = m.id
        ORDER BY dj.created_at, dj.id
        LIMIT 1
      ) j ON true
      WHERE m.request_id = p_request_id
        AND m.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_load_persisted_recipients(p_actor_id uuid, p_request_id uuid, p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req record;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_request_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;

  SELECT id, status, mode INTO v_req
  FROM public.omni_comms_request
  WHERE id = p_request_id AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 request_not_found' USING ERRCODE='P0001';
  END IF;

  RETURN jsonb_build_object(
    'request_id', v_req.id,
    'status',     v_req.status,
    'mode',       v_req.mode,
    'recipients', coalesce((
      SELECT jsonb_agg(
               jsonb_build_object(
                 'recipient_id',        rc.id,
                 'input_index',         nullif(
                                          coalesce(
                                            rc.resolution_snapshot->>'input_index',
                                            rc.resolution_snapshot->'per_recipient_snapshot'->>'input_index'
                                          ), '')::int,
                 'recipient_reference', rc.recipient_reference,
                 'resolved_channels',   to_jsonb(coalesce(rc.resolved_channels, ARRAY[]::text[])),
                 'eligibility_status',  rc.eligibility_status,
                 'blockers',            coalesce(rc.blockers, '[]'::jsonb)
               )
               ORDER BY nullif(
                          coalesce(
                            rc.resolution_snapshot->>'input_index',
                            rc.resolution_snapshot->'per_recipient_snapshot'->>'input_index'
                          ), '')::int NULLS LAST,
                        rc.created_at, rc.id
             )
      FROM public.omni_comms_recipient rc
      WHERE rc.request_id = p_request_id
        AND rc.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_load_persisted_resolution(p_actor_id uuid, p_request_id uuid, p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req        record;
  v_recipients jsonb;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_request_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;

  SELECT * INTO v_req
  FROM public.omni_comms_request
  WHERE id = p_request_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 request_not_found' USING ERRCODE='P0001';
  END IF;

  SELECT jsonb_agg(to_jsonb(rc.*) ORDER BY rc.created_at, rc.id)
    INTO v_recipients
  FROM public.omni_comms_recipient rc WHERE rc.request_id = p_request_id;

  RETURN jsonb_build_object(
    'request_id', v_req.id,
    'status',     v_req.status,
    'replayed',   true,
    'recipients', coalesce(v_recipients,'[]'::jsonb),
    'blockers',   v_req.blockers
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_load_render_context(p_actor_id uuid, p_request_id uuid, p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req            record;
  v_template_ids   uuid[];
  v_layout_ids     uuid[];
  v_asset_ids      uuid[];
  v_sender_ids     uuid[];
  v_result         jsonb;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_request_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;

  SELECT * INTO v_req
  FROM public.omni_comms_request
  WHERE id = p_request_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 request_not_found' USING ERRCODE='P0001';
  END IF;

  WITH res AS (
    SELECT jsonb_array_elements(
             coalesce(rc.resolution_snapshot->'channel_resolutions','[]'::jsonb)
           ) AS r
    FROM public.omni_comms_recipient rc
    WHERE rc.request_id = p_request_id
  )
  SELECT
    coalesce(array_agg(DISTINCT (r->>'template_version_id')::uuid)
             FILTER (WHERE r->>'template_version_id' IS NOT NULL), '{}'),
    coalesce(array_agg(DISTINCT (r->>'layout_version_id')::uuid)
             FILTER (WHERE r->>'layout_version_id' IS NOT NULL), '{}'),
    coalesce(array_agg(DISTINCT (r->>'sender_identity_id')::uuid)
             FILTER (WHERE r->>'sender_identity_id' IS NOT NULL), '{}')
  INTO v_template_ids, v_layout_ids, v_sender_ids
  FROM res;

  WITH res AS (
    SELECT jsonb_array_elements(
             coalesce(rc.resolution_snapshot->'channel_resolutions','[]'::jsonb)
           ) AS r
    FROM public.omni_comms_recipient rc
    WHERE rc.request_id = p_request_id
  ), av AS (
    SELECT jsonb_array_elements(coalesce(r->'assets','[]'::jsonb)) AS a FROM res
  )
  SELECT coalesce(array_agg(DISTINCT (a->>'asset_version_id')::uuid)
                  FILTER (WHERE a->>'asset_version_id' IS NOT NULL), '{}')
  INTO v_asset_ids
  FROM av;

  SELECT jsonb_build_object(
    'request', jsonb_build_object(
      'id',                  v_req.id,
      'organization_id',     v_req.organization_id,
      'department_id',       v_req.department_id,
      'event_definition_id', v_req.event_definition_id,
      'mode',                v_req.mode,
      'status',              v_req.status,
      'payload_snapshot',    v_req.payload_snapshot,
      'correlation_id',      v_req.correlation_id
    ),
    'recipients', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id',                   rc.id,
               'recipient_type',       rc.recipient_type,
               'recipient_reference',  rc.recipient_reference,
               'display_name',         rc.display_name,
               'locale',               rc.locale,
               'destination_snapshot', rc.destination_snapshot,
               'eligibility_status',   rc.eligibility_status,
               'resolved_channels',    to_jsonb(rc.resolved_channels),
               'blockers',             rc.blockers,
               'resolution_snapshot',  rc.resolution_snapshot
             ) ORDER BY rc.created_at, rc.id)
      FROM public.omni_comms_recipient rc
      WHERE rc.request_id = p_request_id
    ), '[]'::jsonb),
    'template_versions', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', tv.id, 'template_family_id', tv.template_family_id,
               'version_number', tv.version_number, 'channel', tv.channel,
               'locale', tv.locale, 'checksum', tv.checksum,
               'status', tv.status, 'content', tv.content
             ) ORDER BY tv.id)
      FROM public.omni_comms_template_version tv
      WHERE tv.id = ANY(v_template_ids)
    ), '[]'::jsonb),
    'layout_versions', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', lv.id, 'layout_id', lv.layout_id,
               'version_number', lv.version_number, 'checksum', lv.checksum,
               'status', lv.status, 'wrapper_html', lv.wrapper_html,
               'slots', lv.slots
             ) ORDER BY lv.id)
      FROM public.core_template_layout_version lv
      WHERE lv.id = ANY(v_layout_ids)
    ), '[]'::jsonb),
    'asset_versions', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', av.id, 'asset_id', av.asset_id,
               'version_number', av.version_number, 'checksum', av.checksum,
               'status', av.status
             ) ORDER BY av.id)
      FROM public.core_comm_asset_version av
      WHERE av.id = ANY(v_asset_ids)
    ), '[]'::jsonb),
    'senders', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', s.id, 'code', s.code, 'channel', s.channel,
               'from_address', s.from_address, 'from_name', s.from_name,
               'reply_to_address', s.reply_to_address, 'status', s.status,
               'organization_id', s.organization_id,
               'department_id', s.department_id
             ) ORDER BY s.id)
      FROM public.omni_comms_sender_identity s
      WHERE s.id = ANY(v_sender_ids)
    ), '[]'::jsonb),
    'channel_settings', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'id', cs.id, 'channel', cs.channel, 'enabled', cs.enabled,
               'live_delivery_enabled', cs.live_delivery_enabled,
               'organization_id', cs.organization_id,
               'department_id', cs.department_id
             ) ORDER BY cs.channel, cs.id)
      FROM public.omni_comms_channel_setting cs
      WHERE cs.organization_id = p_organization_id
        AND (cs.department_id IS NULL OR cs.department_id = v_req.department_id)
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_mask_email(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT CASE
    WHEN p_value IS NULL OR btrim(p_value) = '' THEN NULL
    WHEN position('@' in p_value) < 2 THEN 'masked'
    ELSE left(p_value, 1) || '***@' || split_part(p_value, '@', 2)
  END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_mask_phone(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT CASE
    WHEN p_value IS NULL OR btrim(p_value) = '' THEN NULL
    WHEN length(regexp_replace(p_value, '\D', '', 'g')) < 4 THEN '******'
    ELSE '******' || right(regexp_replace(p_value, '\D', '', 'g'), 4)
  END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_mask_reference(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT CASE
    WHEN p_value IS NULL OR btrim(p_value) = '' THEN NULL
    WHEN length(p_value) <= 4 THEN '****'
    ELSE left(p_value, 2) || repeat('*', 4) || right(p_value, 2)
  END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_message_event_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN RAISE EXCEPTION 'OC409 message_event_append_only' USING ERRCODE = 'P0001'; END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_message_event_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_req_org uuid; v_msg record;
BEGIN
  SELECT organization_id INTO v_req_org FROM public.omni_comms_request WHERE id = NEW.request_id;
  IF v_req_org IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'OC422 event_request_org_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.message_id IS NOT NULL THEN
    SELECT organization_id, request_id INTO v_msg FROM public.omni_comms_message WHERE id = NEW.message_id;
    IF v_msg.request_id IS DISTINCT FROM NEW.request_id THEN
      RAISE EXCEPTION 'OC422 event_message_request_mismatch' USING ERRCODE = 'P0001';
    END IF;
    IF v_msg.organization_id IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'OC422 event_message_org_mismatch' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  PERFORM public.omni_comms_priv_require_json_object(NEW.safe_metadata, 8192);
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_message_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req_org uuid; v_rcp_org uuid; v_rcp_req uuid;
  v_verified boolean := coalesce(current_setting('omni_comms.verified_callback', true), '') = 'on';
BEGIN
  SELECT organization_id INTO v_req_org FROM public.omni_comms_request WHERE id = NEW.request_id;
  IF v_req_org IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'OC422 message_request_org_mismatch' USING ERRCODE = 'P0001';
  END IF;
  SELECT organization_id, request_id INTO v_rcp_org, v_rcp_req FROM public.omni_comms_recipient WHERE id = NEW.recipient_id;
  IF v_rcp_org IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'OC422 message_recipient_org_mismatch' USING ERRCODE = 'P0001';
  END IF;
  IF v_rcp_req IS DISTINCT FROM NEW.request_id THEN
    RAISE EXCEPTION 'OC422 message_recipient_request_mismatch' USING ERRCODE = 'P0001';
  END IF;
  PERFORM public.omni_comms_priv_require_json_object(NEW.resolved_asset_manifest, 262144);
  PERFORM public.omni_comms_priv_require_json_object(NEW.channel_setting_snapshot, 32768);
  PERFORM public.omni_comms_priv_require_json_object(NEW.destination_snapshot, 32768);
  IF jsonb_typeof(NEW.unresolved_tokens) <> 'array' THEN RAISE EXCEPTION 'OC422 unresolved_tokens_must_be_array' USING ERRCODE='P0001'; END IF;
  IF jsonb_typeof(NEW.unresolved_required_slots) <> 'array' THEN RAISE EXCEPTION 'OC422 unresolved_required_slots_must_be_array' USING ERRCODE='P0001'; END IF;
  IF jsonb_typeof(NEW.blockers) <> 'array' THEN RAISE EXCEPTION 'OC422 blockers_must_be_array' USING ERRCODE='P0001'; END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.status NOT IN ('pending','blocked') THEN
      IF NEW.template_family_id IS DISTINCT FROM OLD.template_family_id
         OR NEW.template_version_id IS DISTINCT FROM OLD.template_version_id
         OR NEW.layout_id IS DISTINCT FROM OLD.layout_id
         OR NEW.layout_version_id IS DISTINCT FROM OLD.layout_version_id
         OR NEW.resolved_asset_manifest IS DISTINCT FROM OLD.resolved_asset_manifest
         OR NEW.rendered_subject IS DISTINCT FROM OLD.rendered_subject
         OR NEW.rendered_html IS DISTINCT FROM OLD.rendered_html
         OR NEW.rendered_text IS DISTINCT FROM OLD.rendered_text
         OR NEW.rendered_checksum IS DISTINCT FROM OLD.rendered_checksum
         OR NEW.channel IS DISTINCT FROM OLD.channel
         OR NEW.sender_identity_id IS DISTINCT FROM OLD.sender_identity_id
         OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
         OR NEW.provider_account_id IS DISTINCT FROM OLD.provider_account_id
         OR NEW.destination_snapshot IS DISTINCT FROM OLD.destination_snapshot THEN
        RAISE EXCEPTION 'OC409 message_snapshot_immutable' USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF NEW.status <> OLD.status THEN
      -- Ordinary lifecycle transitions.
      IF (
        (OLD.status = 'pending'     AND NEW.status IN ('rendered','blocked','cancelled')) OR
        (OLD.status = 'rendered'    AND NEW.status IN ('dry_run_completed','shadow_completed','queued','held','cancelled','blocked')) OR
        (OLD.status = 'queued'      AND NEW.status IN ('dispatching','cancelled','held')) OR
        (OLD.status = 'held'        AND NEW.status IN ('queued','cancelled')) OR
        (OLD.status = 'dispatching' AND NEW.status IN ('accepted','failed','reconciliation_required')) OR
        (OLD.status = 'accepted'    AND NEW.status IN ('delivered','failed','reconciliation_required'))
      ) THEN
        NULL;

      -- Exceptional transitions: verified provider callback / reconciliation
      -- path ONLY. A plain UPDATE, an authenticated RPC or a browser call can
      -- never reach these because the transaction-local trusted flag is set
      -- exclusively inside the service-role callback worker.
      ELSIF (
        (OLD.status = 'delivered' AND NEW.status = 'failed') OR
        (OLD.status = 'reconciliation_required' AND NEW.status IN ('accepted','delivered','failed'))
      ) THEN
        IF NOT v_verified THEN
          RAISE EXCEPTION 'OC403 verified_callback_context_required' USING ERRCODE = 'P0001';
        END IF;

      ELSE
        RAISE EXCEPTION 'OC422 invalid_message_transition' USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_next_event_sequence(p_request_id uuid)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT coalesce(max(event_sequence), 0) + 1
  FROM public.omni_comms_message_event
  WHERE request_id = p_request_id;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_channel_endpoint(p_channel text, p_endpoint_type text, p_endpoint_config jsonb, p_secret_refs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_ch text; v_type text;
  v_allowed text[]; v_required text[]; v_arrays text[];
  v_secret_allowed text[]; v_secret_required text[];
  v_key text; v_raw jsonb; v_val text; v_req text;
  v_out jsonb := '{}'::jsonb; v_secrets jsonb := '{}'::jsonb;
  v_elem text; v_arr jsonb; v_norm jsonb;
  v_allowed_events text[] := ARRAY['delivered','delayed','bounced','complained','failed'];
  v_allowed_fields text[] := ARRAY['messages','message_template_status_update','account_update'];
BEGIN
  v_ch   := btrim(coalesce(p_channel,''));
  v_type := btrim(coalesce(p_endpoint_type,''));

  IF v_ch NOT IN ('email','sms','whatsapp','in_app','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unsupported_channel'; END IF;
  IF p_endpoint_config IS NULL OR jsonb_typeof(p_endpoint_config) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_config_object_required'; END IF;
  IF char_length(p_endpoint_config::text) > 4000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_config_too_large'; END IF;
  IF p_secret_refs IS NOT NULL AND jsonb_typeof(p_secret_refs) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_refs_object_required'; END IF;
  IF p_secret_refs IS NOT NULL AND char_length(p_secret_refs::text) > 2000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_refs_too_large'; END IF;

  -- channel → endpoint-type mapping (single server-side source of truth)
  IF v_ch='email' AND v_type='sending_domain' THEN
    v_allowed := ARRAY['domain_name','return_path_domain'];
    v_required := ARRAY['domain_name'];
    v_secret_allowed := ARRAY[]::text[]; v_secret_required := ARRAY[]::text[];
  ELSIF v_ch='email' AND v_type='event_callback' THEN
    v_allowed := ARRAY['callback_url','event_types']; v_arrays := ARRAY['event_types'];
    v_required := ARRAY['callback_url','event_types'];
    v_secret_allowed := ARRAY['signing_secret']; v_secret_required := ARRAY['signing_secret'];
  ELSIF v_ch='sms' AND v_type IN ('delivery_callback','inbound_callback') THEN
    v_allowed := ARRAY['callback_url']; v_required := ARRAY['callback_url'];
    v_secret_allowed := ARRAY['signature_secret']; v_secret_required := ARRAY[]::text[];
  ELSIF v_ch='whatsapp' AND v_type='business_webhook' THEN
    v_allowed := ARRAY['callback_url','subscribed_fields']; v_arrays := ARRAY['subscribed_fields'];
    v_required := ARRAY['callback_url','subscribed_fields'];
    v_secret_allowed := ARRAY['verify_token']; v_secret_required := ARRAY['verify_token'];
  ELSIF v_ch='in_app' AND v_type='realtime_endpoint' THEN
    v_allowed := ARRAY['transport','topic_prefix']; v_required := ARRAY['transport','topic_prefix'];
    v_secret_allowed := ARRAY[]::text[]; v_secret_required := ARRAY[]::text[];
  ELSIF v_ch='print' AND v_type='render_service' THEN
    v_allowed := ARRAY['service_mode','service_reference','health_path'];
    v_required := ARRAY['service_mode','service_reference'];
    v_secret_allowed := ARRAY['auth_token']; v_secret_required := ARRAY[]::text[];
  ELSE
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_endpoint_type';
  END IF;

  v_arrays := coalesce(v_arrays, ARRAY[]::text[]);

  -- generic key/shape validation
  FOR v_key, v_raw IN SELECT key, value FROM jsonb_each(p_endpoint_config) LOOP
    IF NOT (v_key = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_config_key:'||v_key; END IF;
    IF v_key = ANY(v_arrays) THEN
      IF jsonb_typeof(v_raw) <> 'array' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_must_be_array:'||v_key; END IF;
      IF jsonb_array_length(v_raw) = 0 OR jsonb_array_length(v_raw) > 10 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_array_out_of_bounds:'||v_key; END IF;
      v_arr := '[]'::jsonb;
      FOR v_elem IN SELECT jsonb_array_elements_text(v_raw) LOOP
        IF char_length(coalesce(v_elem,'')) > 64 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_too_long:'||v_key; END IF;
        v_elem := lower(btrim(v_elem));
        IF v_key='event_types' AND NOT (v_elem = ANY(v_allowed_events)) THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_event_type:'||v_elem; END IF;
        IF v_key='subscribed_fields' AND NOT (v_elem = ANY(v_allowed_fields)) THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_subscribed_field:'||v_elem; END IF;
        IF NOT (v_arr @> to_jsonb(ARRAY[v_elem])) THEN
          v_arr := v_arr || to_jsonb(ARRAY[v_elem]); END IF;
      END LOOP;
      v_out := v_out || jsonb_build_object(v_key, v_arr);
    ELSE
      IF jsonb_typeof(v_raw) NOT IN ('string','null') THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_must_be_string:'||v_key; END IF;
      v_val := NULLIF(btrim(coalesce(v_raw #>> '{}','')),'');
      IF v_val IS NULL THEN CONTINUE; END IF;
      IF char_length(v_val) > 512 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_too_long:'||v_key; END IF;
      v_out := v_out || jsonb_build_object(v_key, v_val);
    END IF;
  END LOOP;

  FOREACH v_req IN ARRAY v_required LOOP
    IF (v_out ? v_req) IS NOT TRUE THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='missing_required_field:'||v_req; END IF;
  END LOOP;

  -- field-specific normalisation
  IF v_out ? 'domain_name' THEN
    v_out := jsonb_set(v_out,'{domain_name}',
      to_jsonb(public.omni_comms_priv_normalize_endpoint_domain(v_out->>'domain_name','domain_name'))); END IF;
  IF v_out ? 'return_path_domain' THEN
    v_out := jsonb_set(v_out,'{return_path_domain}',
      to_jsonb(public.omni_comms_priv_normalize_endpoint_domain(v_out->>'return_path_domain','return_path_domain'))); END IF;
  IF v_out ? 'callback_url' THEN
    v_out := jsonb_set(v_out,'{callback_url}',
      to_jsonb(public.omni_comms_priv_normalize_endpoint_url(v_out->>'callback_url','callback_url'))); END IF;

  IF v_type='realtime_endpoint' THEN
    IF (v_out->>'transport') NOT IN ('database','realtime') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_transport'; END IF;
    IF (v_out->>'topic_prefix') !~ '^[a-z][a-z0-9]*([._-][a-z0-9]+)*$'
       OR char_length(v_out->>'topic_prefix') > 64 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_topic_prefix'; END IF;
  END IF;

  IF v_type='render_service' THEN
    IF (v_out->>'service_mode') NOT IN ('internal','https') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_service_mode'; END IF;
    IF (v_out->>'service_mode')='internal' THEN
      IF (v_out->>'service_reference') !~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'
         OR char_length(v_out->>'service_reference') > 64 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_internal_service_reference'; END IF;
    ELSE
      v_out := jsonb_set(v_out,'{service_reference}',
        to_jsonb(public.omni_comms_priv_normalize_endpoint_url(v_out->>'service_reference','service_reference')));
    END IF;
    IF v_out ? 'health_path' THEN
      IF (v_out->>'health_path') !~ '^/[A-Za-z0-9._~/-]{0,128}$' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_health_path'; END IF;
    END IF;
  END IF;

  -- secret references (names only, never values)
  IF p_secret_refs IS NOT NULL THEN
    FOR v_key, v_raw IN SELECT key, value FROM jsonb_each(p_secret_refs) LOOP
      IF NOT (v_key = ANY(v_secret_allowed)) THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_secret_purpose:'||v_key; END IF;
      IF v_secrets ? v_key THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='duplicate_secret_purpose:'||v_key; END IF;
      IF jsonb_typeof(v_raw) NOT IN ('string','null') THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_ref_must_be_string:'||v_key; END IF;
      v_val := NULLIF(btrim(coalesce(v_raw #>> '{}','')),'');
      IF v_val IS NULL THEN CONTINUE; END IF;
      IF char_length(v_val) > 128 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='secret_ref_too_long:'||v_key; END IF;
      IF v_val !~ '^OMNI_COMMS_[A-Z0-9]+(_[A-Z0-9]+)*$' THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='raw_secret_value_rejected:'||v_key; END IF;
      v_secrets := v_secrets || jsonb_build_object(v_key, v_val);
    END LOOP;
  END IF;

  FOREACH v_req IN ARRAY v_secret_required LOOP
    IF (v_secrets ->> v_req) IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='missing_required_secret_ref:'||v_req; END IF;
  END LOOP;

  v_norm := jsonb_build_object('endpoint_config', v_out, 'secret_refs', v_secrets);
  RETURN v_norm;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_channel_policy(p_channel text, p_common_policy jsonb, p_channel_policy_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_ch text; v_common jsonb; v_cfg jsonb; v_out jsonb := '{}'::jsonb;
  v_allowed text[]; v_key text; v_k text;
  v_state text; v_retry text; v_cur text;
  v_pm int; v_pd int; v_mr int; v_to int; v_rd int;
  v_dc bigint; v_mc bigint;
  v_qs text; v_qe text; v_tz text;
  v_arr text[]; v_e text; v_i int; v_mode text; v_codes text[];
BEGIN
  v_ch := btrim(coalesce(p_channel,''));
  IF v_ch NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_channel';
  END IF;
  v_common := coalesce(p_common_policy, '{}'::jsonb);
  v_cfg := coalesce(p_channel_policy_config, '{}'::jsonb);
  IF jsonb_typeof(v_common) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='common_policy_not_object'; END IF;
  IF jsonb_typeof(v_cfg) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_policy_config_not_object'; END IF;

  -- ---- common keys allowlist
  v_allowed := ARRAY['operational_state','department_override_enabled','per_minute_limit','per_day_limit',
    'max_recipients_per_request','quiet_hours_start','quiet_hours_end','quiet_hours_timezone',
    'retry_profile','request_timeout_seconds','retention_days','cost_currency',
    'daily_cost_limit_minor','per_message_cost_limit_minor'];
  FOR v_key IN SELECT jsonb_object_keys(v_common) LOOP
    IF NOT (v_key = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_common_field:'||v_key;
    END IF;
  END LOOP;

  v_state := coalesce(v_common->>'operational_state','disabled');
  IF v_state NOT IN ('disabled','configuration','test_only','pilot_ready') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_operational_state'; END IF;

  v_retry := coalesce(v_common->>'retry_profile','none');
  IF v_retry NOT IN ('none','conservative','standard') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_retry_profile'; END IF;

  IF v_common ? 'per_minute_limit' AND jsonb_typeof(v_common->'per_minute_limit') <> 'null' THEN
    IF jsonb_typeof(v_common->'per_minute_limit') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_minute_limit_not_integer'; END IF;
    v_pm := (v_common->>'per_minute_limit')::numeric::int;
    IF v_pm < 1 OR v_pm > 100000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_minute_limit_out_of_range'; END IF;
  END IF;
  IF v_common ? 'per_day_limit' AND jsonb_typeof(v_common->'per_day_limit') <> 'null' THEN
    IF jsonb_typeof(v_common->'per_day_limit') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_day_limit_not_integer'; END IF;
    v_pd := (v_common->>'per_day_limit')::numeric::int;
    IF v_pd < 1 OR v_pd > 10000000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_day_limit_out_of_range'; END IF;
  END IF;
  IF v_pd IS NOT NULL AND v_pm IS NOT NULL AND v_pd < v_pm THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_day_limit_below_per_minute_limit'; END IF;

  IF v_common ? 'max_recipients_per_request' AND jsonb_typeof(v_common->'max_recipients_per_request') <> 'null' THEN
    IF jsonb_typeof(v_common->'max_recipients_per_request') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_recipients_not_integer'; END IF;
    v_mr := (v_common->>'max_recipients_per_request')::numeric::int;
    IF v_mr < 1 OR v_mr > 100000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_recipients_out_of_range'; END IF;
  END IF;

  v_qs := nullif(btrim(coalesce(v_common->>'quiet_hours_start','')),'');
  v_qe := nullif(btrim(coalesce(v_common->>'quiet_hours_end','')),'');
  v_tz := nullif(btrim(coalesce(v_common->>'quiet_hours_timezone','')),'');
  IF (v_qs IS NULL) <> (v_qe IS NULL) THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='quiet_hours_pair_required'; END IF;
  IF v_qs IS NOT NULL THEN
    IF v_qs !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' OR v_qe !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='quiet_hours_invalid_time'; END IF;
    IF v_qs = v_qe THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='quiet_hours_must_differ'; END IF;
    IF v_tz IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='quiet_hours_timezone_required'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = v_tz) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='quiet_hours_timezone_unknown'; END IF;
  ELSE
    v_tz := NULL;
  END IF;

  IF v_common ? 'request_timeout_seconds' AND jsonb_typeof(v_common->'request_timeout_seconds') <> 'null' THEN
    IF jsonb_typeof(v_common->'request_timeout_seconds') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='request_timeout_not_integer'; END IF;
    v_to := (v_common->>'request_timeout_seconds')::numeric::int;
    IF v_to < 1 OR v_to > 300 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='request_timeout_out_of_range'; END IF;
  END IF;
  IF v_common ? 'retention_days' AND jsonb_typeof(v_common->'retention_days') <> 'null' THEN
    IF jsonb_typeof(v_common->'retention_days') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retention_days_not_integer'; END IF;
    v_rd := (v_common->>'retention_days')::numeric::int;
    IF v_rd < 1 OR v_rd > 3650 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='retention_days_out_of_range'; END IF;
  END IF;

  v_cur := nullif(btrim(upper(coalesce(v_common->>'cost_currency',''))),'');
  IF v_cur IS NOT NULL AND v_cur !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='cost_currency_invalid'; END IF;

  IF v_common ? 'daily_cost_limit_minor' AND jsonb_typeof(v_common->'daily_cost_limit_minor') <> 'null' THEN
    IF jsonb_typeof(v_common->'daily_cost_limit_minor') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='daily_cost_limit_not_integer'; END IF;
    v_dc := (v_common->>'daily_cost_limit_minor')::numeric::bigint;
    IF v_dc < 0 OR v_dc > 1000000000000000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='daily_cost_limit_out_of_range'; END IF;
  END IF;
  IF v_common ? 'per_message_cost_limit_minor' AND jsonb_typeof(v_common->'per_message_cost_limit_minor') <> 'null' THEN
    IF jsonb_typeof(v_common->'per_message_cost_limit_minor') <> 'number' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_message_cost_limit_not_integer'; END IF;
    v_mc := (v_common->>'per_message_cost_limit_minor')::numeric::bigint;
    IF v_mc < 0 OR v_mc > 1000000000000000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_message_cost_limit_out_of_range'; END IF;
  END IF;
  IF (v_dc IS NOT NULL OR v_mc IS NOT NULL) AND v_cur IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='cost_currency_required'; END IF;
  IF v_dc IS NOT NULL AND v_mc IS NOT NULL AND v_mc > v_dc THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='per_message_cost_exceeds_daily'; END IF;

  -- ---- channel-specific configuration
  DECLARE v_norm jsonb := '{}'::jsonb;
  BEGIN
    IF v_ch = 'email' THEN
      v_allowed := ARRAY['max_attachment_bytes','allowed_attachment_extensions'];
    ELSIF v_ch = 'sms' THEN
      v_allowed := ARRAY['country_mode','country_codes','max_segments','unicode_allowed'];
    ELSIF v_ch = 'whatsapp' THEN
      v_allowed := ARRAY['country_mode','country_codes','max_media_bytes','inbound_enabled'];
    ELSIF v_ch = 'push' THEN
      v_allowed := ARRAY['max_ttl_seconds','max_data_payload_bytes'];
    ELSIF v_ch = 'in_app' THEN
      v_allowed := ARRAY['expiry_hours','acknowledgement_mode','max_visible_per_user'];
    ELSE
      v_allowed := ARRAY['max_document_bytes','batch_size_limit','archive_retention_days'];
    END IF;
    FOR v_key IN SELECT jsonb_object_keys(v_cfg) LOOP
      IF NOT (v_key = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_channel_policy_key:'||v_key;
      END IF;
    END LOOP;

    -- integer helper inline per key
    FOR v_key IN SELECT unnest(v_allowed) LOOP
      IF v_cfg ? v_key AND jsonb_typeof(v_cfg->v_key) = 'null' THEN
        v_cfg := v_cfg - v_key;
      END IF;
    END LOOP;

    IF v_ch = 'email' THEN
      IF v_cfg ? 'max_attachment_bytes' THEN
        IF jsonb_typeof(v_cfg->'max_attachment_bytes') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_attachment_bytes_not_integer'; END IF;
        v_i := (v_cfg->>'max_attachment_bytes')::numeric::int;
        IF v_i < 0 OR v_i > 26214400 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_attachment_bytes_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('max_attachment_bytes', v_i);
      END IF;
      IF v_cfg ? 'allowed_attachment_extensions' THEN
        IF jsonb_typeof(v_cfg->'allowed_attachment_extensions') <> 'array' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='allowed_attachment_extensions_not_array'; END IF;
        SELECT array_agg(DISTINCT lower(btrim(ltrim(x,'.'))) ORDER BY lower(btrim(ltrim(x,'.'))))
          INTO v_arr
          FROM jsonb_array_elements_text(v_cfg->'allowed_attachment_extensions') AS t(x);
        v_arr := coalesce(v_arr, ARRAY[]::text[]);
        IF array_length(v_arr,1) > 20 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='allowed_attachment_extensions_too_many'; END IF;
        FOREACH v_e IN ARRAY v_arr LOOP
          IF v_e !~ '^[a-z0-9]{1,10}$' THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='allowed_attachment_extension_invalid:'||v_e; END IF;
        END LOOP;
        v_norm := v_norm || jsonb_build_object('allowed_attachment_extensions', to_jsonb(v_arr));
      END IF;

    ELSIF v_ch IN ('sms','whatsapp') THEN
      v_mode := coalesce(v_cfg->>'country_mode','unrestricted');
      IF v_mode NOT IN ('unrestricted','allowlist','denylist') THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_country_mode'; END IF;
      IF v_cfg ? 'country_codes' THEN
        IF jsonb_typeof(v_cfg->'country_codes') <> 'array' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='country_codes_not_array'; END IF;
        SELECT array_agg(DISTINCT upper(btrim(x)) ORDER BY upper(btrim(x))) INTO v_codes
          FROM jsonb_array_elements_text(v_cfg->'country_codes') AS t(x);
      END IF;
      v_codes := coalesce(v_codes, ARRAY[]::text[]);
      IF coalesce(array_length(v_codes,1),0) > 50 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='country_codes_too_many'; END IF;
      FOREACH v_e IN ARRAY v_codes LOOP
        IF v_e !~ '^[A-Z]{2}$' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_country_code:'||v_e; END IF;
      END LOOP;
      IF v_mode = 'unrestricted' AND coalesce(array_length(v_codes,1),0) > 0 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unrestricted_requires_empty_country_codes'; END IF;
      IF v_mode <> 'unrestricted' AND coalesce(array_length(v_codes,1),0) = 0 THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='country_codes_required'; END IF;
      v_norm := v_norm || jsonb_build_object('country_mode', v_mode, 'country_codes', to_jsonb(v_codes));

      IF v_ch = 'sms' THEN
        IF v_cfg ? 'max_segments' THEN
          IF jsonb_typeof(v_cfg->'max_segments') <> 'number' THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_segments_not_integer'; END IF;
          v_i := (v_cfg->>'max_segments')::numeric::int;
          IF v_i < 1 OR v_i > 10 THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_segments_out_of_range'; END IF;
          v_norm := v_norm || jsonb_build_object('max_segments', v_i);
        END IF;
        IF v_cfg ? 'unicode_allowed' THEN
          IF jsonb_typeof(v_cfg->'unicode_allowed') <> 'boolean' THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unicode_allowed_not_boolean'; END IF;
          v_norm := v_norm || jsonb_build_object('unicode_allowed', (v_cfg->>'unicode_allowed')::boolean);
        END IF;
      ELSE
        IF v_cfg ? 'max_media_bytes' THEN
          IF jsonb_typeof(v_cfg->'max_media_bytes') <> 'number' THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_media_bytes_not_integer'; END IF;
          v_i := (v_cfg->>'max_media_bytes')::numeric::int;
          IF v_i < 0 OR v_i > 16777216 THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_media_bytes_out_of_range'; END IF;
          v_norm := v_norm || jsonb_build_object('max_media_bytes', v_i);
        END IF;
        IF v_cfg ? 'inbound_enabled' THEN
          IF jsonb_typeof(v_cfg->'inbound_enabled') <> 'boolean' THEN
            RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='inbound_enabled_not_boolean'; END IF;
          v_norm := v_norm || jsonb_build_object('inbound_enabled', (v_cfg->>'inbound_enabled')::boolean);
        END IF;
      END IF;

    ELSIF v_ch = 'push' THEN
      IF v_cfg ? 'max_ttl_seconds' THEN
        IF jsonb_typeof(v_cfg->'max_ttl_seconds') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_ttl_seconds_not_integer'; END IF;
        v_i := (v_cfg->>'max_ttl_seconds')::numeric::int;
        IF v_i < 0 OR v_i > 2419200 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_ttl_seconds_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('max_ttl_seconds', v_i);
      END IF;
      IF v_cfg ? 'max_data_payload_bytes' THEN
        IF jsonb_typeof(v_cfg->'max_data_payload_bytes') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_data_payload_bytes_not_integer'; END IF;
        v_i := (v_cfg->>'max_data_payload_bytes')::numeric::int;
        IF v_i < 0 OR v_i > 4096 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_data_payload_bytes_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('max_data_payload_bytes', v_i);
      END IF;

    ELSIF v_ch = 'in_app' THEN
      IF v_cfg ? 'expiry_hours' THEN
        IF jsonb_typeof(v_cfg->'expiry_hours') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='expiry_hours_not_integer'; END IF;
        v_i := (v_cfg->>'expiry_hours')::numeric::int;
        IF v_i < 1 OR v_i > 8760 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='expiry_hours_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('expiry_hours', v_i);
      END IF;
      IF v_cfg ? 'acknowledgement_mode' THEN
        IF (v_cfg->>'acknowledgement_mode') NOT IN ('none','read','explicit') THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_acknowledgement_mode'; END IF;
        v_norm := v_norm || jsonb_build_object('acknowledgement_mode', v_cfg->>'acknowledgement_mode');
      END IF;
      IF v_cfg ? 'max_visible_per_user' THEN
        IF jsonb_typeof(v_cfg->'max_visible_per_user') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_visible_per_user_not_integer'; END IF;
        v_i := (v_cfg->>'max_visible_per_user')::numeric::int;
        IF v_i < 1 OR v_i > 500 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_visible_per_user_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('max_visible_per_user', v_i);
      END IF;

    ELSE -- print
      IF v_cfg ? 'max_document_bytes' THEN
        IF jsonb_typeof(v_cfg->'max_document_bytes') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_document_bytes_not_integer'; END IF;
        v_i := (v_cfg->>'max_document_bytes')::numeric::int;
        IF v_i < 1 OR v_i > 52428800 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='max_document_bytes_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('max_document_bytes', v_i);
      END IF;
      IF v_cfg ? 'batch_size_limit' THEN
        IF jsonb_typeof(v_cfg->'batch_size_limit') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='batch_size_limit_not_integer'; END IF;
        v_i := (v_cfg->>'batch_size_limit')::numeric::int;
        IF v_i < 1 OR v_i > 10000 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='batch_size_limit_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('batch_size_limit', v_i);
      END IF;
      IF v_cfg ? 'archive_retention_days' THEN
        IF jsonb_typeof(v_cfg->'archive_retention_days') <> 'number' THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='archive_retention_days_not_integer'; END IF;
        v_i := (v_cfg->>'archive_retention_days')::numeric::int;
        IF v_i < 1 OR v_i > 3650 THEN
          RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='archive_retention_days_out_of_range'; END IF;
        v_norm := v_norm || jsonb_build_object('archive_retention_days', v_i);
      END IF;
    END IF;

    IF length(v_norm::text) > 4000 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_policy_config_too_large'; END IF;

    v_out := jsonb_build_object(
      'channel', v_ch,
      'common', jsonb_build_object(
        'operational_state', v_state,
        'department_override_enabled', coalesce((v_common->>'department_override_enabled')::boolean, true),
        'per_minute_limit', to_jsonb(v_pm),
        'per_day_limit', to_jsonb(v_pd),
        'max_recipients_per_request', to_jsonb(v_mr),
        'quiet_hours_start', to_jsonb(v_qs),
        'quiet_hours_end', to_jsonb(v_qe),
        'quiet_hours_timezone', to_jsonb(v_tz),
        'retry_profile', v_retry,
        'request_timeout_seconds', to_jsonb(v_to),
        'retention_days', to_jsonb(v_rd),
        'cost_currency', to_jsonb(v_cur),
        'daily_cost_limit_minor', to_jsonb(v_dc),
        'per_message_cost_limit_minor', to_jsonb(v_mc)
      ),
      'channel_policy_config', v_norm
    );
  END;
  RETURN v_out;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_endpoint_domain(p_domain text, p_field text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v text;
BEGIN
  v := lower(btrim(coalesce(p_domain,'')));
  IF v = '' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='missing_required_field:'||p_field; END IF;
  IF char_length(v) > 253 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='domain_too_long:'||p_field; END IF;
  IF v ~ '\s' OR position('://' in v) > 0 OR position('/' in v) > 0
     OR position('?' in v) > 0 OR position('#' in v) > 0 OR position('@' in v) > 0
     OR position(':' in v) > 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_domain:'||p_field; END IF;
  IF position('*' in v) > 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='wildcard_domain_not_allowed:'||p_field; END IF;
  IF left(v,1)='.' OR right(v,1)='.' OR position('..' in v) > 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_domain:'||p_field; END IF;
  IF v ~ '^[0-9.]+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='ip_domain_not_allowed:'||p_field; END IF;
  IF v !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_domain:'||p_field; END IF;
  IF split_part(reverse(v),'.',1) ~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_domain:'||p_field; END IF;
  RETURN v;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_endpoint_url(p_url text, p_field text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v text; v_rest text; v_authority text; v_host text; v_query text;
BEGIN
  v := btrim(coalesce(p_url,''));
  IF v = '' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='missing_required_field:'||p_field; END IF;
  IF char_length(v) > 512 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='url_too_long:'||p_field; END IF;
  IF v ~ '\s' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_url:'||p_field; END IF;
  IF position('#' in v) > 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='url_fragment_not_allowed:'||p_field; END IF;
  IF lower(left(v,8)) <> 'https://' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='https_required:'||p_field; END IF;

  v_rest := substring(v from 9);
  v_authority := split_part(split_part(v_rest,'/',1),'?',1);
  IF position('@' in v_authority) > 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='url_credentials_not_allowed:'||p_field; END IF;
  v_host := lower(split_part(v_authority,':',1));
  IF v_host = '' OR v_host !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_url_host:'||p_field; END IF;
  IF v_host ~ '^[0-9.]+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='ip_host_not_allowed:'||p_field; END IF;
  IF v_host IN ('localhost','localhost.localdomain') OR v_host LIKE '%.local'
     OR v_host LIKE '%.internal' OR v_host LIKE '%.localhost' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='loopback_host_not_allowed:'||p_field; END IF;

  v_query := split_part(v_rest,'?',2);
  IF char_length(v_query) > 200 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='url_query_too_long:'||p_field; END IF;

  RETURN 'https://' || v_host
       || CASE WHEN split_part(v_authority,':',2) <> '' THEN ':'||split_part(v_authority,':',2) ELSE '' END
       || CASE WHEN position('/' in v_rest) > 0 THEN substring(v_rest from position('/' in v_rest)) ELSE '' END;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_identity_config(p_channel text, p_identity_type text, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_ch text; v_type text; v_allowed text[]; v_required text[];
  v_key text; v_raw jsonb; v_val text; v_out jsonb := '{}'::jsonb; v_req text;
BEGIN
  v_ch   := btrim(coalesce(p_channel,''));
  v_type := btrim(coalesce(p_identity_type,''));

  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='identity_config_object_required'; END IF;
  IF char_length(p_config::text) > 4000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='identity_config_too_large'; END IF;

  IF v_ch='email' AND v_type='email_sender' THEN
    v_allowed := ARRAY['from_address','from_name','reply_to_address'];
    v_required := ARRAY['from_address'];
  ELSIF v_ch='sms' AND v_type IN ('sender_id','originating_number') THEN
    v_allowed := ARRAY['sender_value','default_country_code','message_class'];
    v_required := ARRAY['sender_value'];
  ELSIF v_ch='whatsapp' AND v_type='business_number' THEN
    v_allowed := ARRAY['display_number','phone_number_id','business_account_id','display_name'];
    v_required := ARRAY['display_number','phone_number_id'];
  ELSIF v_ch='push' AND v_type='application' THEN
    v_allowed := ARRAY['application_code','platform','package_or_bundle_id','display_name'];
    v_required := ARRAY['application_code','platform'];
  ELSIF v_ch='in_app' AND v_type='application' THEN
    v_allowed := ARRAY['application_code','display_name','icon_key','default_category'];
    v_required := ARRAY['application_code','display_name'];
  ELSIF v_ch='print' AND v_type='issuing_authority' THEN
    v_allowed := ARRAY['issuing_authority','letterhead_code','document_profile','return_address'];
    v_required := ARRAY['issuing_authority'];
  ELSE
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_identity_type';
  END IF;

  FOR v_key, v_raw IN SELECT key, value FROM jsonb_each(p_config) LOOP
    IF NOT (v_key = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='unknown_config_key:'||v_key; END IF;
    IF jsonb_typeof(v_raw) NOT IN ('string','null') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_must_be_string:'||v_key; END IF;
    v_val := NULLIF(btrim(coalesce(v_raw #>> '{}','')),'');
    IF v_val IS NULL THEN CONTINUE; END IF;
    IF char_length(v_val) > 254 THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_too_long:'||v_key; END IF;
    v_out := v_out || jsonb_build_object(v_key, v_val);
  END LOOP;

  FOREACH v_req IN ARRAY v_required LOOP
    IF (v_out ->> v_req) IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='missing_required_field:'||v_req; END IF;
  END LOOP;

  IF (v_out ? 'from_address') AND (v_out->>'from_address') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_email:from_address'; END IF;
  IF (v_out ? 'reply_to_address') AND (v_out->>'reply_to_address') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_email:reply_to_address'; END IF;
  IF (v_out ? 'from_name') AND char_length(v_out->>'from_name') > 120 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_too_long:from_name'; END IF;

  IF v_type='sender_id' AND (v_out->>'sender_value') !~ '^[A-Za-z0-9][A-Za-z0-9 ._-]{2,10}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_sender_id'; END IF;
  IF v_type='originating_number' AND (v_out->>'sender_value') !~ '^\+[1-9][0-9]{7,14}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_e164:sender_value'; END IF;
  IF (v_out ? 'default_country_code') AND (v_out->>'default_country_code') !~ '^\+?[0-9]{1,4}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_country_code'; END IF;
  IF (v_out ? 'message_class') AND (v_out->>'message_class') NOT IN ('transactional','promotional','mixed') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_message_class'; END IF;

  IF (v_out ? 'display_number') AND (v_out->>'display_number') !~ '^\+[1-9][0-9]{7,14}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_e164:display_number'; END IF;
  IF (v_out ? 'phone_number_id') AND (v_out->>'phone_number_id') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_phone_number_id'; END IF;
  IF (v_out ? 'business_account_id') AND (v_out->>'business_account_id') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_business_account_id'; END IF;

  IF (v_out ? 'application_code') AND (v_out->>'application_code') !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_application_code'; END IF;
  IF (v_out ? 'application_code') AND char_length(v_out->>'application_code') > 64 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_too_long:application_code'; END IF;
  IF v_ch='push' AND (v_out->>'platform') NOT IN ('android','ios','web','cross_platform') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_platform'; END IF;
  IF (v_out ? 'package_or_bundle_id') AND (v_out->>'package_or_bundle_id') !~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_package_or_bundle_id'; END IF;
  IF (v_out ? 'icon_key') AND (v_out->>'icon_key') !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_icon_key'; END IF;
  IF (v_out ? 'default_category') AND (v_out->>'default_category') !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_default_category'; END IF;

  IF (v_out ? 'issuing_authority') AND char_length(v_out->>'issuing_authority') NOT BETWEEN 2 AND 160 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_issuing_authority'; END IF;
  IF (v_out ? 'letterhead_code') AND (v_out->>'letterhead_code') !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_letterhead_code'; END IF;
  IF (v_out ? 'document_profile') AND (v_out->>'document_profile') !~ '^[a-z0-9]+([._-][a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_document_profile'; END IF;

  IF (v_out ? 'display_name') AND char_length(v_out->>'display_name') > 160 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='config_value_too_long:display_name'; END IF;

  RETURN v_out;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_locale(p_locale text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_trim text;
  v_lang text;
  v_region text;
  v_dash integer;
BEGIN
  IF p_locale IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='locale_required';
  END IF;
  v_trim := btrim(p_locale);
  IF v_trim = '' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='locale_required';
  END IF;
  v_dash := position('-' in v_trim);
  IF v_dash = 0 THEN
    v_lang := lower(v_trim);
    v_region := NULL;
  ELSE
    v_lang := lower(substring(v_trim FROM 1 FOR v_dash - 1));
    v_region := upper(substring(v_trim FROM v_dash + 1));
  END IF;
  IF v_region IS NULL THEN
    IF NOT (v_lang ~ '^[a-z]{2,3}$') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='locale_format_invalid';
    END IF;
    RETURN v_lang;
  ELSE
    IF NOT (v_lang ~ '^[a-z]{2,3}$' AND v_region ~ '^[A-Z]{2}$') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='locale_format_invalid';
    END IF;
    RETURN v_lang || '-' || v_region;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_normalize_reason(p_reason text, p_required boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_trimmed text;
BEGIN
  v_trimmed := btrim(COALESCE(p_reason, ''));
  IF p_required AND v_trimmed = '' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reason_required';
  END IF;
  IF char_length(v_trimmed) > 2000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reason_too_long';
  END IF;
  IF v_trimmed = '' THEN RETURN NULL; END IF;
  RETURN v_trimmed;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_peb_load(p_id uuid)
 RETURNS omni_comms_producer_event_binding
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_row public.omni_comms_producer_event_binding%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM public.omni_comms_producer_event_binding
  WHERE id = p_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'OC404 producer_binding_not_found'
      USING ERRCODE = 'P0001', DETAIL = 'producer_binding_not_found';
  END IF;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_persist_rendered_messages(p_actor_id uuid, p_request_id uuid, p_organization_id uuid, p_messages jsonb, p_jobs jsonb, p_success_status text, p_request_blockers text[], p_final_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_req           record;
  v_existing      int;
  v_msg           jsonb;
  v_job           jsonb;
  v_message_id    uuid;
  v_message_ids   uuid[] := '{}';
  v_idx           int;
  v_status        text;
  v_event_type    text;
  v_rendered      int := 0;
  v_blocked       int := 0;
  v_jobs_created  int := 0;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_request_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF jsonb_typeof(p_messages) <> 'array' OR jsonb_typeof(p_jobs) <> 'array' THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF p_success_status NOT IN ('dry_run_completed','shadow_completed','held') THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF p_final_status NOT IN ('completed','completed_with_blockers','blocked') THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;

  SELECT * INTO v_req
  FROM public.omni_comms_request
  WHERE id = p_request_id AND organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 request_not_found' USING ERRCODE='P0001';
  END IF;

  IF v_req.mode = 'dry_run' AND jsonb_array_length(p_jobs) > 0 THEN
    RAISE EXCEPTION 'OC422 dry_run_jobs_forbidden' USING ERRCODE='P0001';
  END IF;
  IF v_req.mode = 'dry_run' AND p_success_status <> 'dry_run_completed' THEN
    RAISE EXCEPTION 'OC422 mode_status_mismatch' USING ERRCODE='P0001';
  END IF;
  IF v_req.mode = 'shadow' AND p_success_status <> 'shadow_completed' THEN
    RAISE EXCEPTION 'OC422 mode_status_mismatch' USING ERRCODE='P0001';
  END IF;
  IF v_req.mode = 'queued' AND p_success_status <> 'held' THEN
    RAISE EXCEPTION 'OC422 mode_status_mismatch' USING ERRCODE='P0001';
  END IF;

  SELECT count(*) INTO v_existing
  FROM public.omni_comms_message WHERE request_id = p_request_id;

  IF v_existing > 0 THEN
    RETURN jsonb_build_object(
      'request_id', v_req.id,
      'status',     v_req.status,
      'replayed',   true,
      'messages',   coalesce((
        SELECT jsonb_agg(jsonb_build_object(
                 'id', m.id, 'recipient_id', m.recipient_id,
                 'channel', m.channel, 'status', m.status,
                 'rendered_checksum', m.rendered_checksum,
                 'blockers', m.blockers)
               ORDER BY m.created_at, m.id)
        FROM public.omni_comms_message m WHERE m.request_id = p_request_id
      ), '[]'::jsonb)
    );
  END IF;

  IF v_req.status <> 'processing' THEN
    RAISE EXCEPTION 'OC409 request_not_processing' USING ERRCODE='P0001';
  END IF;

  FOR v_msg IN SELECT * FROM jsonb_array_elements(p_messages) LOOP
    v_status := coalesce(v_msg->>'status','blocked');
    IF v_status NOT IN ('rendered','blocked') THEN
      RAISE EXCEPTION 'OC422 invalid_message_status' USING ERRCODE='P0001';
    END IF;

    INSERT INTO public.omni_comms_message (
      request_id, recipient_id, organization_id, department_id,
      event_definition_id, event_route_id, channel,
      template_family_id, template_version_id, layout_id, layout_version_id,
      resolved_asset_manifest, sender_identity_id, provider_id,
      provider_account_id, channel_setting_snapshot, destination_snapshot,
      rendered_subject, rendered_html, rendered_text,
      unresolved_tokens, unresolved_required_slots, rendered_checksum,
      status, blockers, rendered_at
    ) VALUES (
      p_request_id,
      (v_msg->>'recipient_id')::uuid,
      p_organization_id,
      v_req.department_id,
      v_req.event_definition_id,
      nullif(v_msg->>'event_route_id','')::uuid,
      v_msg->>'channel',
      nullif(v_msg->>'template_family_id','')::uuid,
      nullif(v_msg->>'template_version_id','')::uuid,
      nullif(v_msg->>'layout_id','')::uuid,
      nullif(v_msg->>'layout_version_id','')::uuid,
      coalesce(v_msg->'resolved_asset_manifest','{}'::jsonb),
      nullif(v_msg->>'sender_identity_id','')::uuid,
      nullif(v_msg->>'provider_id','')::uuid,
      nullif(v_msg->>'provider_account_id','')::uuid,
      coalesce(v_msg->'channel_setting_snapshot','{}'::jsonb),
      coalesce(v_msg->'destination_snapshot','{}'::jsonb),
      v_msg->>'rendered_subject',
      v_msg->>'rendered_html',
      v_msg->>'rendered_text',
      coalesce(v_msg->'unresolved_tokens','[]'::jsonb),
      coalesce(v_msg->'unresolved_required_slots','[]'::jsonb),
      nullif(v_msg->>'rendered_checksum',''),
      v_status,
      coalesce(v_msg->'blockers','[]'::jsonb),
      CASE WHEN v_status = 'rendered' THEN now() ELSE NULL END
    ) RETURNING id INTO v_message_id;

    v_message_ids := v_message_ids || v_message_id;

    IF v_status = 'rendered' THEN
      v_rendered := v_rendered + 1;
      v_event_type := 'message_rendered';
    ELSE
      v_blocked := v_blocked + 1;
      v_event_type := 'message_blocked';
    END IF;

    INSERT INTO public.omni_comms_message_event (
      request_id, message_id, organization_id, event_type, event_sequence,
      status_before, status_after, safe_metadata, correlation_id,
      actor_type, actor_id
    ) VALUES (
      p_request_id, v_message_id, p_organization_id, v_event_type,
      public.omni_comms_priv_next_event_sequence(p_request_id),
      NULL, v_status,
      jsonb_build_object(
        'channel',                    v_msg->>'channel',
        'template_version_id',        v_msg->>'template_version_id',
        'layout_version_id',          v_msg->>'layout_version_id',
        'rendered_checksum',          v_msg->>'rendered_checksum',
        'unresolved_token_count',     coalesce(jsonb_array_length(v_msg->'unresolved_tokens'),0),
        'unresolved_slot_count',      coalesce(jsonb_array_length(v_msg->'unresolved_required_slots'),0),
        'blockers',                   coalesce(v_msg->'blockers','[]'::jsonb)
      ),
      v_req.correlation_id, 'system', p_actor_id::text
    );
  END LOOP;

  IF v_rendered > 0 THEN
    UPDATE public.omni_comms_message
       SET status = p_success_status,
           queued_at = CASE WHEN p_success_status = 'held' THEN now() ELSE queued_at END,
           completed_at = CASE
             WHEN p_success_status IN ('dry_run_completed','shadow_completed')
             THEN now() ELSE completed_at END,
           updated_at = now()
     WHERE request_id = p_request_id AND status = 'rendered';

    IF p_success_status IN ('dry_run_completed','shadow_completed') THEN
      INSERT INTO public.omni_comms_message_event (
        request_id, message_id, organization_id, event_type, event_sequence,
        status_before, status_after, safe_metadata, correlation_id,
        actor_type, actor_id
      )
      SELECT p_request_id, m.id, p_organization_id,
             CASE WHEN p_success_status = 'dry_run_completed'
                  THEN 'dry_run_completed' ELSE 'shadow_completed' END,
             public.omni_comms_priv_next_event_sequence(p_request_id),
             'rendered', p_success_status,
             jsonb_build_object('channel', m.channel, 'mode', v_req.mode),
             v_req.correlation_id, 'system', p_actor_id::text
        FROM public.omni_comms_message m
       WHERE m.request_id = p_request_id AND m.status = p_success_status
       ORDER BY m.created_at, m.id;
    END IF;
  END IF;

  FOR v_job IN SELECT * FROM jsonb_array_elements(p_jobs) LOOP
    IF coalesce(v_job->>'status','') <> 'held'
       OR coalesce((v_job->>'is_runnable')::boolean, true) <> false THEN
      RAISE EXCEPTION 'OC422 runnable_job_forbidden' USING ERRCODE='P0001';
    END IF;

    v_idx := (v_job->>'message_index')::int;
    IF v_idx IS NULL OR v_idx < 0 OR v_idx >= coalesce(array_length(v_message_ids,1),0) THEN
      RAISE EXCEPTION 'OC422 invalid_job_message_index' USING ERRCODE='P0001';
    END IF;
    v_message_id := v_message_ids[v_idx + 1];

    INSERT INTO public.omni_comms_dispatch_job (
      request_id, message_id, organization_id, channel, mode, status,
      priority, scheduled_at, next_attempt_at, attempt_count, max_attempts,
      correlation_id, is_runnable, hold_reason
    ) VALUES (
      p_request_id, v_message_id, p_organization_id,
      v_job->>'channel', v_req.mode, 'held',
      100, NULL, NULL, 0, 5,
      v_req.correlation_id, false,
      left(coalesce(v_job->>'hold_reason','runtime_hold'), 200)
    );
    v_jobs_created := v_jobs_created + 1;

    INSERT INTO public.omni_comms_message_event (
      request_id, message_id, organization_id, event_type, event_sequence,
      status_before, status_after, safe_metadata, correlation_id,
      actor_type, actor_id
    ) VALUES (
      p_request_id, v_message_id, p_organization_id, 'dispatch_held',
      public.omni_comms_priv_next_event_sequence(p_request_id),
      'rendered', 'held',
      jsonb_build_object(
        'channel',     v_job->>'channel',
        'mode',        v_req.mode,
        'hold_reason', v_job->>'hold_reason',
        'is_runnable', false
      ),
      v_req.correlation_id, 'system', p_actor_id::text
    );
  END LOOP;

  UPDATE public.omni_comms_request
     SET status = p_final_status,
         blockers = coalesce(
           (SELECT jsonb_agg(to_jsonb(b))
              FROM unnest(coalesce(p_request_blockers, ARRAY[]::text[])) AS b),
           '[]'::jsonb),
         completed_at = CASE WHEN p_final_status <> 'blocked' THEN now() ELSE completed_at END,
         failed_at    = CASE WHEN p_final_status = 'blocked' THEN now() ELSE failed_at END,
         updated_at = now()
   WHERE id = p_request_id;

  INSERT INTO public.omni_comms_message_event (
    request_id, message_id, organization_id, event_type, event_sequence,
    status_before, status_after, safe_metadata, correlation_id,
    actor_type, actor_id
  ) VALUES (
    p_request_id, NULL, p_organization_id, 'request_completed',
    public.omni_comms_priv_next_event_sequence(p_request_id),
    'processing', p_final_status,
    jsonb_build_object(
      'mode',            v_req.mode,
      'message_count',   coalesce(array_length(v_message_ids,1),0),
      'rendered_count',  v_rendered,
      'blocked_count',   v_blocked,
      'held_job_count',  v_jobs_created,
      'runnable_jobs',   0
    ),
    v_req.correlation_id, 'system', p_actor_id::text
  );

  RETURN jsonb_build_object(
    'request_id',     p_request_id,
    'status',         p_final_status,
    'replayed',       false,
    'message_count',  coalesce(array_length(v_message_ids,1),0),
    'rendered_count', v_rendered,
    'blocked_count',  v_blocked,
    'held_job_count', v_jobs_created
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_pilot_assert_non_production()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_env text;
BEGIN
  -- Authoritative reader ONLY. Any failure is treated as unknown.
  BEGIN
    v_env := public.omni_comms_priv_runtime_environment();
  EXCEPTION WHEN OTHERS THEN
    v_env := 'unknown';
  END;

  IF v_env IS NULL OR v_env <> 'non_production' THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_non_production_required';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.omni_comms_channel_setting WHERE live_delivery_enabled
  ) THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'pilot_bootstrap_live_delivery_enabled';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_provider_account_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_provider_account must be inserted in draft status'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'retired' AND NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'omni_comms_provider_account retired status is terminal' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status = 'draft' AND OLD.status <> 'draft' THEN
    RAISE EXCEPTION 'omni_comms_provider_account cannot revert to draft' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status NOT IN ('draft','active','disabled','retired') THEN
    RAISE EXCEPTION 'omni_comms_provider_account invalid status %', NEW.status USING ERRCODE = 'P0001';
  END IF;

  IF NEW.status IN ('active','disabled') AND OLD.status = 'draft' AND NEW.status = 'active' THEN
    IF NEW.activated_at IS NULL THEN NEW.activated_at := now(); END IF;
  END IF;
  IF NEW.status = 'disabled' AND OLD.status = 'draft' THEN
    RAISE EXCEPTION 'omni_comms_provider_account cannot go draft to disabled' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS NULL THEN
    RAISE EXCEPTION 'omni_comms_provider_account activated_at cannot be cleared' USING ERRCODE = 'P0001';
  END IF;

  IF NEW.status = 'retired' AND OLD.status <> 'retired' THEN
    IF NEW.retired_at IS NULL THEN NEW.retired_at := now(); END IF;
    IF NEW.retirement_reason IS NULL OR char_length(btrim(NEW.retirement_reason)) < 1 THEN
      RAISE EXCEPTION 'omni_comms_provider_account retirement requires a non-empty reason' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF OLD.status = 'retired' THEN
    IF OLD.retired_at IS DISTINCT FROM NEW.retired_at
       OR OLD.retired_by IS DISTINCT FROM NEW.retired_by
       OR OLD.retirement_reason IS DISTINCT FROM NEW.retirement_reason THEN
      RAISE EXCEPTION 'omni_comms_provider_account retirement metadata is immutable' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF OLD.status IN ('active','disabled','retired') THEN
    IF OLD.code <> NEW.code
       OR OLD.organization_id <> NEW.organization_id
       OR OLD.provider_id <> NEW.provider_id THEN
      RAISE EXCEPTION 'omni_comms_provider_account identity fields are immutable after activation'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_provider_account_verification_context(p_actor_id uuid, p_organization_id uuid, p_provider_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_row public.omni_comms_provider_account%ROWTYPE;
        v_adapter text; v_channel text; v_secret_ref text; v_pattern text;
BEGIN
  IF p_actor_id IS NULL THEN
    RETURN jsonb_build_object('allowed',false,'code','authentication_required'); END IF;
  IF NOT public.has_permission(p_actor_id,'omni_comms','configure') THEN
    RETURN jsonb_build_object('allowed',false,'code','permission_denied'); END IF;
  BEGIN
    PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, p_organization_id, NULL);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('allowed',false,'code','organization_access_denied');
  END;
  SELECT * INTO v_row FROM public.omni_comms_provider_account
   WHERE id=p_provider_account_id AND organization_id=p_organization_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed',false,'code','not_found'); END IF;
  SELECT adapter_key, channel INTO v_adapter, v_channel
    FROM public.omni_comms_provider WHERE id=v_row.provider_id;
  IF v_adapter IS DISTINCT FROM 'resend' OR v_channel IS DISTINCT FROM 'email' THEN
    RETURN jsonb_build_object('allowed',false,'code','configuration_incomplete'); END IF;

  -- canonical source: the child api_key credential reference
  SELECT s.secret_ref INTO v_secret_ref
    FROM public.omni_comms_provider_account_secret_ref s
   WHERE s.provider_account_id=v_row.id AND s.purpose='api_key';
  SELECT r.secret_ref_pattern INTO v_pattern
    FROM public.omni_comms_provider_credential_requirement r
   WHERE r.provider_id=v_row.provider_id AND r.purpose='api_key';

  IF v_secret_ref IS NULL OR v_pattern IS NULL OR v_secret_ref !~ v_pattern
     OR NOT public.omni_comms_priv_is_secret_ref_name(v_secret_ref) THEN
    RETURN jsonb_build_object('allowed',false,'code','configuration_incomplete'); END IF;

  RETURN jsonb_build_object(
    'allowed', true, 'code','ok',
    'account_id', v_row.id, 'account_code', v_row.code,
    'secret_ref', v_secret_ref,
    'status', v_row.status, 'sandbox_mode', v_row.sandbox_mode,
    'environment', v_row.environment,
    'updated_at', v_row.updated_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_provider_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_provider must be inserted in draft status'
        USING ERRCODE = 'P0001';
    END IF;
    IF NEW.retired_at IS NOT NULL OR NEW.activated_at IS NOT NULL THEN
      RAISE EXCEPTION 'omni_comms_provider draft insert cannot set lifecycle timestamps'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'retired' AND NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'omni_comms_provider retired status is terminal' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status = 'active' AND NEW.status = 'draft' THEN
    RAISE EXCEPTION 'omni_comms_provider cannot revert active to draft' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status NOT IN ('draft','active','retired') THEN
    RAISE EXCEPTION 'omni_comms_provider invalid status %', NEW.status USING ERRCODE = 'P0001';
  END IF;

  -- activation metadata
  IF NEW.status = 'active' AND OLD.status = 'draft' THEN
    IF NEW.activated_at IS NULL THEN NEW.activated_at := now(); END IF;
  END IF;
  IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS NULL THEN
    RAISE EXCEPTION 'omni_comms_provider activated_at cannot be cleared' USING ERRCODE = 'P0001';
  END IF;

  -- retirement metadata
  IF NEW.status = 'retired' AND OLD.status <> 'retired' THEN
    IF NEW.retired_at IS NULL THEN NEW.retired_at := now(); END IF;
    IF NEW.retirement_reason IS NULL OR char_length(btrim(NEW.retirement_reason)) < 1 THEN
      RAISE EXCEPTION 'omni_comms_provider retirement requires a non-empty reason' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF OLD.status = 'retired' THEN
    IF OLD.retired_at IS DISTINCT FROM NEW.retired_at
       OR OLD.retired_by IS DISTINCT FROM NEW.retired_by
       OR OLD.retirement_reason IS DISTINCT FROM NEW.retirement_reason THEN
      RAISE EXCEPTION 'omni_comms_provider retirement metadata is immutable' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- business identity immutability after activation
  IF OLD.status IN ('active','retired') THEN
    IF OLD.code <> NEW.code OR OLD.adapter_key <> NEW.adapter_key OR OLD.channel <> NEW.channel THEN
      RAISE EXCEPTION 'omni_comms_provider identity fields are immutable after activation'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_recipient_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_req_org uuid; v_c text;
BEGIN
  SELECT organization_id INTO v_req_org FROM public.omni_comms_request WHERE id = NEW.request_id;
  IF v_req_org IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'OC422 recipient_request_org_mismatch' USING ERRCODE = 'P0001';
  END IF;
  PERFORM public.omni_comms_priv_require_json_object(NEW.destination_snapshot, 32768);
  PERFORM public.omni_comms_priv_require_json_object(NEW.resolution_snapshot, 32768);
  IF jsonb_typeof(NEW.blockers) <> 'array' THEN
    RAISE EXCEPTION 'OC422 blockers_must_be_array' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.resolved_channels IS NOT NULL AND array_length(NEW.resolved_channels,1) IS NOT NULL THEN
    FOREACH v_c IN ARRAY NEW.resolved_channels LOOP
      PERFORM public.omni_comms_priv_validate_channel(v_c);
    END LOOP;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.request_id IS DISTINCT FROM OLD.request_id
       OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.recipient_type IS DISTINCT FROM OLD.recipient_type THEN
      RAISE EXCEPTION 'OC422 recipient_immutable_fields' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_record_binding_verification(p_actor_id uuid, p_id uuid, p_expected_updated_at timestamp with time zone, p_verification_status text, p_verification_source text, p_result_code text, p_detail text, p_correlation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_before public.omni_comms_sender_provider_binding%ROWTYPE;
  v_after  public.omni_comms_sender_provider_binding%ROWTYPE;
  v_code text; v_detail text;
BEGIN
  IF p_verification_source NOT IN ('provider','service') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='untrusted_verification_source'; END IF;
  IF p_verification_status NOT IN ('unverified','pending','verified','failed') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_verification_status'; END IF;
  v_code := NULLIF(btrim(coalesce(p_result_code,'')),'');
  IF v_code IS NOT NULL AND (char_length(v_code) > 64
     OR v_code !~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_result_code'; END IF;
  v_detail := NULLIF(btrim(coalesce(p_detail,'')),'');
  IF v_detail IS NOT NULL AND char_length(v_detail) > 500 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='detail_too_long'; END IF;

  SELECT * INTO v_before FROM public.omni_comms_sender_provider_binding
   WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='binding'; END IF;
  IF v_before.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_binding_non_operational'; END IF;
  IF p_expected_updated_at IS NOT NULL
     AND v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch'; END IF;

  UPDATE public.omni_comms_sender_provider_binding
     SET verification_status = p_verification_status,
         verification_source = CASE WHEN p_verification_status IN ('unverified','pending')
                                    THEN 'none' ELSE p_verification_source END,
         verification_result_code = v_code,
         verification_detail = v_detail,
         verification_checked_at = now(),
         verified_at = CASE WHEN p_verification_status = 'verified' THEN now() ELSE NULL END,
         updated_at = now()
   WHERE id = p_id RETURNING * INTO v_after;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id,'verification_'||p_verification_status,'binding',p_id,p_id::text,
    to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_record_provider_verification(p_actor_id uuid, p_organization_id uuid, p_provider_account_id uuid, p_expected_updated_at timestamp with time zone, p_status text, p_result_code text, p_detail text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_before public.omni_comms_provider_account%ROWTYPE;
  v_after  public.omni_comms_provider_account%ROWTYPE;
BEGIN
  IF p_actor_id IS NULL THEN
    RETURN jsonb_build_object('allowed',false,'code','authentication_required');
  END IF;
  IF NOT public.has_permission(p_actor_id,'omni_comms','configure') THEN
    RETURN jsonb_build_object('allowed',false,'code','permission_denied');
  END IF;
  BEGIN
    PERFORM public.omni_comms_priv_require_tenant_access(p_actor_id, p_organization_id, NULL);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('allowed',false,'code','organization_access_denied');
  END;
  IF p_status IS NULL OR p_status NOT IN ('pending','verified','failed') THEN
    RETURN jsonb_build_object('allowed',false,'code','invalid_input');
  END IF;
  IF p_result_code IS NULL OR p_result_code NOT IN (
      'verified','invalid_credentials','secret_missing','provider_unavailable',
      'rate_limited','configuration_incomplete') THEN
    RETURN jsonb_build_object('allowed',false,'code','invalid_input');
  END IF;
  IF p_expected_updated_at IS NULL THEN
    RETURN jsonb_build_object('allowed',false,'code','invalid_input');
  END IF;

  SELECT * INTO v_before FROM public.omni_comms_provider_account
   WHERE id = p_provider_account_id AND organization_id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed',false,'code','not_found');
  END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('allowed',false,'code','concurrent_update');
  END IF;

  UPDATE public.omni_comms_provider_account
     SET verification_status      = p_status,
         verification_result_code = p_result_code,
         verification_detail      = left(coalesce(p_detail,''), 200),
         verification_checked_at  = now(),
         updated_by               = p_actor_id,
         updated_at               = now()
   WHERE id = p_provider_account_id
   RETURNING * INTO v_after;

  PERFORM public.omni_comms_priv_write_channel_audit(
    p_actor_id,'provider_credential_verification','provider_account',
    v_after.id, v_after.code, to_jsonb(v_before), to_jsonb(v_after), p_correlation_id);

  RETURN jsonb_build_object(
    'allowed', true,
    'code','ok',
    'verification_status', v_after.verification_status,
    'verification_result_code', v_after.verification_result_code,
    'verification_detail', v_after.verification_detail,
    'verification_checked_at', v_after.verification_checked_at,
    'updated_at', v_after.updated_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_record_runtime_certification(p_certification_state text, p_certified_commit text DEFAULT NULL::text, p_workflow_run_id text DEFAULT NULL::text, p_certified_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_deployed_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_state text;
  v_commit text;
  v_deployed text;
  v_run text;
  v_at timestamptz;
  v_env text;
BEGIN
  v_state := lower(btrim(coalesce(p_certification_state, '')));
  v_commit := lower(btrim(coalesce(p_certified_commit, '')));
  v_deployed := lower(btrim(coalesce(p_deployed_revision, '')));
  v_run := nullif(btrim(coalesce(p_workflow_run_id, '')), '');
  v_at := p_certified_at;

  IF v_state NOT IN ('pending', 'certified', 'failed') THEN
    RAISE EXCEPTION 'omni_comms: invalid certification state' USING ERRCODE = '22023';
  END IF;

  IF v_run IS NOT NULL AND length(v_run) > 200 THEN
    RAISE EXCEPTION 'omni_comms: workflow run id exceeds bounded length' USING ERRCODE = '22023';
  END IF;

  IF v_state = 'pending' THEN
    IF v_commit <> '' OR v_at IS NOT NULL THEN
      RAISE EXCEPTION 'omni_comms: pending certification must not carry a commit or timestamp'
        USING ERRCODE = '22023';
    END IF;
    v_commit := NULL;
  ELSIF v_state = 'failed' THEN
    IF v_commit <> '' AND v_commit !~ '^[0-9a-f]{40}$' THEN
      RAISE EXCEPTION 'omni_comms: attempted commit must be a full 40-character sha'
        USING ERRCODE = '22023';
    END IF;
    v_commit := nullif(v_commit, '');
  ELSE
    IF v_commit !~ '^[0-9a-f]{40}$' THEN
      RAISE EXCEPTION 'omni_comms: certified commit must be a full 40-character sha'
        USING ERRCODE = '22023';
    END IF;
    IF v_run IS NULL THEN
      RAISE EXCEPTION 'omni_comms: certified record requires a workflow run id'
        USING ERRCODE = '22023';
    END IF;
    IF v_at IS NULL THEN
      RAISE EXCEPTION 'omni_comms: certified record requires a certification timestamp'
        USING ERRCODE = '22023';
    END IF;
    IF v_deployed !~ '^[0-9a-f]{40}$' OR v_deployed <> v_commit THEN
      RAISE EXCEPTION 'omni_comms: certified commit must equal the deployed revision'
        USING ERRCODE = '22023';
    END IF;
    v_env := public.omni_comms_priv_runtime_environment();
    IF v_env IS DISTINCT FROM 'non_production' THEN
      RAISE EXCEPTION 'omni_comms: certification may only be recorded in a non_production environment'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.omni_comms_runtime_certification
    (singleton, certification_state, certified_commit, workflow_run_id, certified_at, updated_at)
  VALUES (true, v_state, v_commit, v_run, CASE WHEN v_state = 'certified' THEN v_at ELSE NULL END, now())
  ON CONFLICT (singleton) DO UPDATE
    SET certification_state = EXCLUDED.certification_state,
        certified_commit = EXCLUDED.certified_commit,
        workflow_run_id = EXCLUDED.workflow_run_id,
        certified_at = EXCLUDED.certified_at,
        updated_at = now();

  DELETE FROM public.omni_comms_runtime_certification WHERE singleton IS DISTINCT FROM true;

  RETURN public.omni_comms_priv_runtime_certification();
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_reference_seed_assert_safe(p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_live_requests bigint;
  v_live_channels bigint;
BEGIN
  SELECT count(*) INTO v_live_requests
    FROM public.omni_comms_request r
   WHERE r.organization_id = p_organization_id
     AND r.mode IS DISTINCT FROM 'dry_run';
  IF v_live_requests > 0 THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'reference_seed_live_traffic_detected';
  END IF;

  SELECT count(*) INTO v_live_channels
    FROM public.omni_comms_channel_setting cs
   WHERE cs.organization_id = p_organization_id
     AND cs.live_delivery_enabled;
  IF v_live_channels > 0 THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'reference_seed_live_delivery_enabled';
  END IF;
END;
$function$;
