CREATE OR REPLACE FUNCTION public.omni_comms_priv_reference_seed_catalogue_v2()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT jsonb_set(
           jsonb_set(
             public.omni_comms_priv_reference_seed_catalogue(),
             '{catalogue_version}', '2'::jsonb, true),
           '{layouts}',
           jsonb_build_object(
             'email',  'OMNI_REF_EMAIL',
             'sms',    'OMNI_REF_SMS',
             'in_app', 'OMNI_REF_IN_APP'),
           true)
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_reference_seed_run(p_actor_id uuid, p_organization_id uuid, p_apply boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  c              jsonb := public.omni_comms_priv_reference_seed_catalogue();
  v_locale       text  := c ->> 'locale';
  v_actions      jsonb := '[]'::jsonb;
  v_created      integer := 0;
  v_planned      integer := 0;
  v_existing     integer := 0;
  v_skipped      integer := 0;
  it             jsonb;
  ch             jsonb;
  v_id           uuid;
  v_dept_id      uuid;
  v_provider_id  uuid;
  v_account_id   uuid;
  v_sender_id    uuid;
  v_event_id     uuid;
  v_family_id    uuid;
  v_version_id   uuid;
  v_layout_id    uuid;
  v_code         text;
  v_extra        text;
  v_schema       jsonb;
  v_sample       jsonb;
  v_checksum     text;
  v_family_code  text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.core_organization WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'OC404 not_found'
      USING ERRCODE = 'P0001', DETAIL = 'organization_not_found';
  END IF;

  -- ---- providers (global) -------------------------------------------------
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'providers') LOOP
    v_code := it ->> 'code';
    SELECT id INTO v_provider_id FROM public.omni_comms_provider WHERE code = v_code;
    IF v_provider_id IS NOT NULL THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_provider (code, display_name, channel, adapter_key, status, created_by, updated_by)
      VALUES (v_code, it ->> 'display_name', it ->> 'channel', it ->> 'adapter_key', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_provider_id;
      UPDATE public.omni_comms_provider
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_provider_id;
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','created');
    END IF;
  END LOOP;

  -- ---- provider accounts (org scoped, simulation only) --------------------
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'accounts') LOOP
    v_code := it ->> 'code';
    SELECT id INTO v_account_id
      FROM public.omni_comms_provider_account
     WHERE organization_id = p_organization_id AND code = v_code;
    IF v_account_id IS NOT NULL THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','existing');
      CONTINUE;
    END IF;
    SELECT id INTO v_provider_id FROM public.omni_comms_provider WHERE code = it ->> 'provider_code';
    IF v_provider_id IS NULL OR NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','planned');
      CONTINUE;
    END IF;
    INSERT INTO public.omni_comms_provider_account
      (organization_id, provider_id, code, display_name, secret_ref, sandbox_mode, status, created_by, updated_by)
    VALUES
      (p_organization_id, v_provider_id, v_code, it ->> 'display_name', it ->> 'secret_ref', true, 'draft', p_actor_id, p_actor_id)
    RETURNING id INTO v_account_id;
    UPDATE public.omni_comms_provider_account
       SET status = 'active', activated_at = now(), activated_by = p_actor_id,
           updated_at = now(), updated_by = p_actor_id
     WHERE id = v_account_id;
    v_created := v_created + 1;
    v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','created');
  END LOOP;

  -- ---- sender identities + bindings ---------------------------------------
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'senders') LOOP
    v_code := it ->> 'code';
    v_dept_id := NULL;
    IF it ->> 'department_code' IS NOT NULL THEN
      SELECT id INTO v_dept_id FROM public.core_department
       WHERE organization_id = p_organization_id AND code = it ->> 'department_code';
    END IF;

    SELECT id INTO v_sender_id
      FROM public.omni_comms_sender_identity
     WHERE organization_id = p_organization_id AND code = v_code;

    IF v_sender_id IS NOT NULL THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_identity','key',v_code,'action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 2;
      v_actions := v_actions
        || jsonb_build_object('object_type','sender_identity','key',v_code,'action','planned')
        || jsonb_build_object('object_type','sender_binding','key',v_code,'action','planned');
      CONTINUE;
    ELSE
      INSERT INTO public.omni_comms_sender_identity
        (organization_id, department_id, code, display_name, channel, from_address, from_name, reply_to_address, status, created_by, updated_by)
      VALUES
        (p_organization_id, v_dept_id, v_code, it ->> 'display_name', it ->> 'channel',
         it ->> 'from_address', it ->> 'from_name', it ->> 'reply_to_address', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_sender_id;
      UPDATE public.omni_comms_sender_identity
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_sender_id;
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_identity','key',v_code,'action','created');
    END IF;

    SELECT id INTO v_account_id
      FROM public.omni_comms_provider_account
     WHERE organization_id = p_organization_id AND code = it ->> 'account_code';

    IF v_sender_id IS NULL OR v_account_id IS NULL THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','planned');
      CONTINUE;
    END IF;

    IF EXISTS (SELECT 1 FROM public.omni_comms_sender_provider_binding
                WHERE sender_identity_id = v_sender_id AND provider_account_id = v_account_id) THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_sender_provider_binding
        (sender_identity_id, provider_account_id, priority, verification_status, verified_at, status, created_by, updated_by)
      VALUES (v_sender_id, v_account_id, 100, 'verified', now(), 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_id;
      UPDATE public.omni_comms_sender_provider_binding
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_id;
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','created');
    END IF;
  END LOOP;

  -- ---- channel settings (enabled, live delivery OFF) ----------------------
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'channel_settings') LOOP
    v_code := it ->> 'channel';
    IF EXISTS (SELECT 1 FROM public.omni_comms_channel_setting
                WHERE organization_id = p_organization_id AND department_id IS NULL AND channel = v_code) THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_channel_setting
        (organization_id, department_id, channel, enabled, live_delivery_enabled, created_by, updated_by)
      VALUES (p_organization_id, NULL, v_code, true, false, p_actor_id, p_actor_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','created');
    END IF;
  END LOOP;

  -- ---- events, contracts, families, versions, routes ----------------------
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'events') LOOP
    v_code  := it ->> 'code';
    v_extra := it ->> 'extra_field';

    v_schema := jsonb_build_object(
      '$schema', 'https://json-schema.org/draft/2020-12/schema',
      'type', 'object',
      'additionalProperties', false,
      'required', jsonb_build_array('reference', 'subjectName', v_extra),
      'properties', jsonb_build_object(
        'reference',   jsonb_build_object('type','string','maxLength',64),
        'subjectName', jsonb_build_object('type','string','maxLength',160)
      ) || jsonb_build_object(v_extra, jsonb_build_object('type','string','maxLength',240))
    );
    v_sample := (it -> 'sample') || jsonb_build_object(v_extra, it ->> 'extra_sample');

    v_dept_id := NULL;
    IF it ->> 'department_code' IS NOT NULL THEN
      SELECT id INTO v_dept_id FROM public.core_department
       WHERE organization_id = p_organization_id AND code = it ->> 'department_code';
    END IF;

    SELECT id INTO v_event_id FROM public.omni_comms_event_definition WHERE code = v_code;
    IF v_event_id IS NOT NULL THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_event_definition
        (code, module_code, entity_type, name, description, communication_class, default_priority, status, created_by, updated_by)
      VALUES (v_code, it ->> 'module_code', it ->> 'entity_type', it ->> 'name', it ->> 'description',
              it ->> 'communication_class', it ->> 'default_priority', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_event_id;
      UPDATE public.omni_comms_event_definition
         SET status = 'active', updated_at = now(), updated_by = p_actor_id
       WHERE id = v_event_id;
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','created');
    END IF;

    -- During apply a missing event blocks its children; during preview the
    -- dependent objects are still reported as planned.
    IF v_event_id IS NULL AND p_apply THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- event contract v1 (published)
    IF v_event_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.omni_comms_event_contract
       WHERE event_definition_id = v_event_id AND version_number = 1) THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','planned');
    ELSE
      PERFORM public.omni_comms_priv_validate_schema(v_schema, v_sample);
      INSERT INTO public.omni_comms_event_contract
        (event_definition_id, version_number, json_schema, sample_payload, status, created_by, updated_by)
      VALUES (v_event_id, 1, v_schema, v_sample, 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_id;
      v_checksum := public.omni_comms_priv_compute_checksum(v_code, 1, v_schema);
      UPDATE public.omni_comms_event_contract
         SET status = 'published', checksum = v_checksum, published_at = now(), published_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_id;
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','created');
    END IF;

    -- template family (event scoped)
    v_family_code := it ->> 'family_code';
    SELECT id INTO v_family_id FROM public.omni_comms_template_family WHERE code = v_family_code;
    IF v_family_id IS NOT NULL THEN
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','existing');
    ELSIF NOT p_apply THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_template_family
        (code, name, description, scope_type, organization_id, department_id, event_definition_id, status, created_by, updated_by)
      VALUES (v_family_code, (it ->> 'name') || ' Templates', 'Reference seed templates for ' || v_code,
              'event', p_organization_id, NULL, v_event_id, 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_family_id;
      UPDATE public.omni_comms_template_family
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_family_id;
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','created');
    END IF;

    FOR ch IN SELECT * FROM jsonb_array_elements(it -> 'channels') LOOP
      SELECT id INTO v_layout_id FROM public.core_template_layout
       WHERE code = (c -> 'layouts' ->> (ch ->> 'channel')) AND is_active LIMIT 1;

      v_version_id := NULL;
      IF v_family_id IS NOT NULL THEN
        SELECT id INTO v_version_id FROM public.omni_comms_template_version
         WHERE template_family_id = v_family_id AND channel = ch ->> 'channel'
           AND locale = v_locale AND version_number = 1;
      END IF;

      IF v_version_id IS NOT NULL THEN
        v_existing := v_existing + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_family_code || ':' || (ch ->> 'channel'),'action','existing');
      ELSIF NOT p_apply OR v_family_id IS NULL OR v_layout_id IS NULL THEN
        v_planned := v_planned + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_family_code || ':' || (ch ->> 'channel'),'action','planned');
      ELSE
        PERFORM public.omni_comms_priv_validate_channel_content(ch ->> 'channel', ch -> 'content');
        -- Author is the system seed principal (NULL); approver is the operator,
        -- which satisfies the independent-approver rule by construction.
        INSERT INTO public.omni_comms_template_version
          (template_family_id, version_number, channel, locale, content, status,
           layout_selection_mode, layout_id, created_by, updated_by)
        VALUES (v_family_id, 1, ch ->> 'channel', v_locale, ch -> 'content', 'draft',
                'resolved_default', v_layout_id, NULL, p_actor_id)
        RETURNING id INTO v_version_id;

        v_checksum := public.omni_comms_priv_compute_template_checksum(
          v_family_code, 1, ch ->> 'channel', v_locale, ch -> 'content');

        UPDATE public.omni_comms_template_version
           SET status = 'approved', checksum = v_checksum, approved_at = now(), approved_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_version_id;

        UPDATE public.omni_comms_template_version
           SET status = 'published', published_at = now(), published_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_version_id;

        v_created := v_created + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_family_code || ':' || (ch ->> 'channel'),'action','created');
      END IF;

      v_id := NULL;
      IF v_event_id IS NOT NULL THEN
        SELECT id INTO v_id FROM public.omni_comms_event_route
         WHERE organization_id = p_organization_id
           AND department_id IS NOT DISTINCT FROM v_dept_id
           AND event_definition_id = v_event_id
           AND channel = ch ->> 'channel';
      END IF;

      IF v_id IS NOT NULL THEN
        v_existing := v_existing + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_code || ':' || (ch ->> 'channel'),'action','existing');
        CONTINUE;
      END IF;

      SELECT id INTO v_sender_id FROM public.omni_comms_sender_identity
       WHERE organization_id = p_organization_id AND code = ch ->> 'sender_code';

      IF NOT p_apply OR v_family_id IS NULL OR v_sender_id IS NULL THEN
        v_planned := v_planned + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_code || ':' || (ch ->> 'channel'),'action','planned');
        CONTINUE;
      END IF;

      INSERT INTO public.omni_comms_event_route
        (organization_id, department_id, event_definition_id, channel, is_required, is_enabled, priority,
         template_family_id, sender_identity_id, sender_resolution_policy, preference_policy, lifecycle_state,
         created_by, updated_by)
      VALUES
        (p_organization_id, v_dept_id, v_event_id, ch ->> 'channel',
         COALESCE((ch ->> 'is_required')::boolean, false), true,
         COALESCE((ch ->> 'priority')::integer, 100),
         v_family_id, v_sender_id, 'explicit', 'honour', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_id;

      UPDATE public.omni_comms_event_route
         SET lifecycle_state = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_id;

      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_code || ':' || (ch ->> 'channel'),'action','created');
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'catalogue_version', (c ->> 'catalogue_version')::int,
    'mode', CASE WHEN p_apply THEN 'apply' ELSE 'preview' END,
    'created', v_created,
    'planned', v_planned,
    'existing', v_existing,
    'skipped', v_skipped,
    'actions', v_actions,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_reference_seed_run_v2(p_actor_id uuid, p_organization_id uuid, p_mode text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  c              jsonb := public.omni_comms_priv_reference_seed_catalogue_v2();
  v_locale       text  := c ->> 'locale';
  v_actions      jsonb := '[]'::jsonb;
  v_created      integer := 0;
  v_planned      integer := 0;
  v_existing     integer := 0;
  v_conflicts    integer := 0;
  v_blocked      integer := 0;
  v_skipped      integer := 0;
  v_write        boolean := p_mode IN ('apply', 'reconcile');
  v_repair       boolean := p_mode = 'reconcile';
  v_found        boolean;
  it             jsonb;
  ch             jsonb;
  rec            record;
  v_id           uuid;
  v_dept_id      uuid;
  v_provider_id  uuid;
  v_account_id   uuid;
  v_sender_id    uuid;
  v_event_id     uuid;
  v_family_id    uuid;
  v_version_id   uuid;
  v_layout_id    uuid;
  v_layout_ver   uuid;
  v_contract_id  uuid;
  v_code         text;
  v_extra        text;
  v_schema       jsonb;
  v_sample       jsonb;
  v_checksum     text;
  v_family_code  text;
  v_key          text;
  v_note_reason  text;
BEGIN
  IF p_mode NOT IN ('preview', 'apply', 'reconcile') THEN
    RAISE EXCEPTION 'OC400 invalid_mode' USING ERRCODE = 'P0001', DETAIL = 'invalid_seed_mode';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.core_organization WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE = 'P0001', DETAIL = 'organization_not_found';
  END IF;

  -- =========================== PROVIDERS ===================================
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'providers') LOOP
    v_code := it ->> 'code';
    SELECT * INTO rec FROM public.omni_comms_provider WHERE code = v_code;
    IF FOUND THEN
      v_note_reason := NULL;
      IF rec.adapter_key IS DISTINCT FROM (it ->> 'adapter_key') THEN
        v_note_reason := 'adapter_key_mismatch';
      ELSIF rec.channel IS DISTINCT FROM (it ->> 'channel') THEN
        v_note_reason := 'channel_mismatch';
      ELSIF rec.status NOT IN ('draft', 'active') THEN
        v_note_reason := 'unexpected_status:' || rec.status;
      ELSIF rec.adapter_key NOT LIKE 'simulation%' THEN
        v_note_reason := 'not_simulation_adapter';
      END IF;

      IF v_note_reason IS NOT NULL THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','conflict','reason',v_note_reason);
        CONTINUE;
      END IF;

      v_provider_id := rec.id;
      IF rec.status = 'draft' AND v_repair THEN
        UPDATE public.omni_comms_provider
           SET status = 'active', activated_at = now(), activated_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_provider_id;
        PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_repair', 'provider', v_provider_id, v_code, NULL, jsonb_build_object('status','active'), p_correlation_id);
      END IF;
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','existing_compatible');
    ELSIF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_provider (code, display_name, channel, adapter_key, status, created_by, updated_by)
      VALUES (v_code, it ->> 'display_name', it ->> 'channel', it ->> 'adapter_key', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_provider_id;
      UPDATE public.omni_comms_provider
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_provider_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create', 'provider', v_provider_id, v_code, NULL, to_jsonb(it), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider','key',v_code,'action','created');
    END IF;
  END LOOP;

  -- ======================= PROVIDER ACCOUNTS ===============================
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'accounts') LOOP
    v_code := it ->> 'code';
    SELECT id INTO v_provider_id FROM public.omni_comms_provider WHERE code = it ->> 'provider_code';

    SELECT * INTO rec FROM public.omni_comms_provider_account
     WHERE organization_id = p_organization_id AND code = v_code;

    IF FOUND THEN
      v_note_reason := NULL;
      IF v_provider_id IS NOT NULL AND rec.provider_id IS DISTINCT FROM v_provider_id THEN
        v_note_reason := 'provider_mismatch';
      ELSIF COALESCE(rec.sandbox_mode, false) = false THEN
        v_note_reason := 'account_not_sandbox';
      ELSIF rec.status NOT IN ('draft', 'active') THEN
        v_note_reason := 'unexpected_status:' || rec.status;
      END IF;
      IF v_note_reason IS NOT NULL THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','conflict','reason',v_note_reason);
        CONTINUE;
      END IF;
      IF rec.status = 'draft' AND v_repair THEN
        UPDATE public.omni_comms_provider_account
           SET status = 'active', activated_at = now(), activated_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = rec.id;
        PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_repair', 'provider_account', rec.id, v_code, NULL, jsonb_build_object('status','active'), p_correlation_id);
      END IF;
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','existing_compatible');
      CONTINUE;
    END IF;

    IF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','planned');
      CONTINUE;
    END IF;

    IF v_provider_id IS NULL THEN
      v_blocked := v_blocked + 1;
      v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','blocked','reason','provider_unavailable');
      CONTINUE;
    END IF;

    INSERT INTO public.omni_comms_provider_account
      (organization_id, provider_id, code, display_name, secret_ref, sandbox_mode, status, created_by, updated_by)
    VALUES
      (p_organization_id, v_provider_id, v_code, it ->> 'display_name', it ->> 'secret_ref', true, 'draft', p_actor_id, p_actor_id)
    RETURNING id INTO v_account_id;
    UPDATE public.omni_comms_provider_account
       SET status = 'active', activated_at = now(), activated_by = p_actor_id,
           updated_at = now(), updated_by = p_actor_id
     WHERE id = v_account_id;
    PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create', 'provider_account', v_account_id, v_code, NULL, to_jsonb(it), p_correlation_id);
    v_created := v_created + 1;
    v_actions := v_actions || jsonb_build_object('object_type','provider_account','key',v_code,'action','created');
  END LOOP;

  -- ==================== SENDER IDENTITIES + BINDINGS =======================
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'senders') LOOP
    v_code := it ->> 'code';
    v_dept_id := NULL;
    IF it ->> 'department_code' IS NOT NULL THEN
      SELECT id INTO v_dept_id FROM public.core_department
       WHERE organization_id = p_organization_id AND code = it ->> 'department_code';
    END IF;

    v_sender_id := NULL;
    SELECT * INTO rec FROM public.omni_comms_sender_identity
     WHERE organization_id = p_organization_id AND code = v_code;

    IF FOUND THEN
      v_note_reason := NULL;
      IF rec.channel IS DISTINCT FROM (it ->> 'channel') THEN
        v_note_reason := 'channel_mismatch';
      ELSIF rec.from_address IS DISTINCT FROM (it ->> 'from_address') THEN
        v_note_reason := 'from_address_mismatch';
      ELSIF rec.status NOT IN ('draft', 'active') THEN
        v_note_reason := 'unexpected_status:' || rec.status;
      ELSIF (it ->> 'channel') = 'email'
            AND rec.from_address NOT LIKE ('%@' || (c ->> 'recipient_domain')) THEN
        v_note_reason := 'non_reference_sender_domain';
      END IF;
      IF v_note_reason IS NOT NULL THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','sender_identity','key',v_code,'action','conflict','reason',v_note_reason);
        CONTINUE;
      END IF;
      v_sender_id := rec.id;
      IF rec.status = 'draft' AND v_repair THEN
        UPDATE public.omni_comms_sender_identity
           SET status = 'active', activated_at = now(), activated_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_sender_id;
        PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_repair', 'sender_identity', v_sender_id, v_code, NULL, jsonb_build_object('status','active'), p_correlation_id);
      END IF;
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_identity','key',v_code,'action','existing_compatible');
    ELSIF NOT v_write THEN
      v_planned := v_planned + 2;
      v_actions := v_actions
        || jsonb_build_object('object_type','sender_identity','key',v_code,'action','planned')
        || jsonb_build_object('object_type','sender_binding','key',v_code,'action','planned');
      CONTINUE;
    ELSE
      INSERT INTO public.omni_comms_sender_identity
        (organization_id, department_id, code, display_name, channel, from_address, from_name, reply_to_address, status, created_by, updated_by)
      VALUES
        (p_organization_id, v_dept_id, v_code, it ->> 'display_name', it ->> 'channel',
         it ->> 'from_address', it ->> 'from_name', it ->> 'reply_to_address', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_sender_id;
      UPDATE public.omni_comms_sender_identity
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_sender_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create', 'sender_identity', v_sender_id, v_code, NULL, to_jsonb(it), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_identity','key',v_code,'action','created');
    END IF;

    SELECT id INTO v_account_id FROM public.omni_comms_provider_account
     WHERE organization_id = p_organization_id AND code = it ->> 'account_code';

    IF v_sender_id IS NULL OR v_account_id IS NULL THEN
      IF NOT v_write THEN
        v_planned := v_planned + 1;
        v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','planned');
      ELSE
        v_blocked := v_blocked + 1;
        v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','blocked','reason','sender_or_account_unavailable');
      END IF;
      CONTINUE;
    END IF;

    SELECT * INTO rec FROM public.omni_comms_sender_provider_binding
     WHERE sender_identity_id = v_sender_id AND provider_account_id = v_account_id;

    IF FOUND THEN
      IF rec.status NOT IN ('draft', 'active') THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','conflict','reason','unexpected_status:' || rec.status);
      ELSE
        IF rec.status = 'draft' AND v_repair THEN
          UPDATE public.omni_comms_sender_provider_binding
             SET status = 'active', activated_at = now(), activated_by = p_actor_id,
                 updated_at = now(), updated_by = p_actor_id
           WHERE id = rec.id;
        END IF;
        v_existing := v_existing + 1;
        v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','existing_compatible');
      END IF;
    ELSIF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_sender_provider_binding
        (sender_identity_id, provider_account_id, priority, verification_status, status, created_by, updated_by)
      VALUES (v_sender_id, v_account_id, 100, 'verified', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_id;
      UPDATE public.omni_comms_sender_provider_binding
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create', 'sender_binding', v_id, v_code, NULL, jsonb_build_object('simulation_only', true, 'external_delivery', false), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','sender_binding','key',v_code,'action','created');
    END IF;
  END LOOP;

  -- ========================= CHANNEL SETTINGS ==============================
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'channel_settings') LOOP
    v_code := it ->> 'channel';
    SELECT * INTO rec FROM public.omni_comms_channel_setting
     WHERE organization_id = p_organization_id AND department_id IS NULL AND channel = v_code;
    IF FOUND THEN
      IF COALESCE(rec.live_delivery_enabled, false) THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','conflict','reason','live_delivery_enabled');
      ELSE
        v_existing := v_existing + 1;
        v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','existing_compatible');
      END IF;
    ELSIF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_channel_setting
        (organization_id, department_id, channel, enabled, live_delivery_enabled, created_by, updated_by)
      VALUES (p_organization_id, NULL, v_code, true, false, p_actor_id, p_actor_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','channel_setting','key',v_code,'action','created');
    END IF;
  END LOOP;

  -- ============ EVENTS / CONTRACTS / FAMILIES / VERSIONS / ROUTES ==========
  FOR it IN SELECT * FROM jsonb_array_elements(c -> 'events') LOOP
    v_code  := it ->> 'code';
    v_extra := it ->> 'extra_field';

    v_schema := jsonb_build_object(
      '$schema', 'https://json-schema.org/draft/2020-12/schema',
      'type', 'object',
      'additionalProperties', false,
      'required', jsonb_build_array('reference', 'subjectName', v_extra),
      'properties', jsonb_build_object(
        'reference',   jsonb_build_object('type','string','maxLength',64),
        'subjectName', jsonb_build_object('type','string','maxLength',160)
      ) || jsonb_build_object(v_extra, jsonb_build_object('type','string','maxLength',240))
    );
    v_sample := (it -> 'sample') || jsonb_build_object(v_extra, it ->> 'extra_sample');

    v_dept_id := NULL;
    IF it ->> 'department_code' IS NOT NULL THEN
      SELECT id INTO v_dept_id FROM public.core_department
       WHERE organization_id = p_organization_id AND code = it ->> 'department_code';
    END IF;

    -- ---- 1. event definition (draft first) --------------------------------
    v_event_id := NULL;
    SELECT * INTO rec FROM public.omni_comms_event_definition WHERE code = v_code;
    IF FOUND THEN
      v_note_reason := NULL;
      IF rec.module_code IS DISTINCT FROM (it ->> 'module_code') THEN
        v_note_reason := 'module_code_mismatch';
      ELSIF rec.entity_type IS DISTINCT FROM (it ->> 'entity_type') THEN
        v_note_reason := 'entity_type_mismatch';
      ELSIF rec.communication_class IS DISTINCT FROM (it ->> 'communication_class') THEN
        v_note_reason := 'communication_class_mismatch';
      ELSIF rec.status NOT IN ('draft', 'active') THEN
        v_note_reason := 'unexpected_status:' || rec.status;
      END IF;
      IF v_note_reason IS NOT NULL THEN
        v_conflicts := v_conflicts + 1;
        v_skipped := v_skipped + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','conflict','reason',v_note_reason);
        CONTINUE;
      END IF;
      v_event_id := rec.id;
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','existing_compatible');
    ELSIF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_event_definition
        (code, module_code, entity_type, name, description, communication_class, default_priority, status, created_by, updated_by)
      VALUES (v_code, it ->> 'module_code', it ->> 'entity_type', it ->> 'name',
              'reference_seed(v2): ' || (it ->> 'description'),
              it ->> 'communication_class', it ->> 'default_priority', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_event_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create_draft', 'event_definition', v_event_id, v_code, NULL, jsonb_build_object('status','draft'), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','created');
    END IF;

    IF v_write AND v_event_id IS NULL THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- ---- 2/3/4. contract draft -> validate -> publish ---------------------
    v_contract_id := NULL;
    v_found := false;
    IF v_event_id IS NOT NULL THEN
      SELECT * INTO rec FROM public.omni_comms_event_contract
       WHERE event_definition_id = v_event_id AND version_number = 1;
      v_found := FOUND;
    END IF;

    IF v_found THEN
      v_checksum := public.omni_comms_priv_compute_checksum(v_code, 1, rec.json_schema);
      v_note_reason := NULL;
      IF rec.status <> 'published' THEN
        IF v_repair THEN
          PERFORM public.omni_comms_priv_validate_schema(rec.json_schema, rec.sample_payload);
          UPDATE public.omni_comms_event_contract
             SET status = 'published', checksum = v_checksum, published_at = now(), published_by = p_actor_id,
                 updated_at = now(), updated_by = p_actor_id
           WHERE id = rec.id;
          PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_publish', 'event_contract', rec.id, v_code || ':v1', jsonb_build_object('status',rec.status), jsonb_build_object('status','published'), p_correlation_id);
          v_contract_id := rec.id;
          v_existing := v_existing + 1;
          v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','existing_compatible','reason','repaired_to_published');
        ELSE
          v_note_reason := 'contract_not_published:' || rec.status;
        END IF;
      ELSIF rec.checksum IS DISTINCT FROM v_checksum THEN
        v_note_reason := 'contract_checksum_mismatch';
      ELSE
        v_contract_id := rec.id;
        v_existing := v_existing + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','existing_compatible');
      END IF;

      IF v_note_reason IS NOT NULL THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','conflict','reason',v_note_reason);
      END IF;
    ELSIF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','planned');
    ELSE
      PERFORM public.omni_comms_priv_validate_schema(v_schema, v_sample);
      INSERT INTO public.omni_comms_event_contract
        (event_definition_id, version_number, json_schema, sample_payload, status, created_by, updated_by)
      VALUES (v_event_id, 1, v_schema, v_sample, 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_contract_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create_draft', 'event_contract', v_contract_id, v_code || ':v1', NULL, jsonb_build_object('status','draft'), p_correlation_id);
      v_checksum := public.omni_comms_priv_compute_checksum(v_code, 1, v_schema);
      UPDATE public.omni_comms_event_contract
         SET status = 'published', checksum = v_checksum, published_at = now(), published_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_contract_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_publish', 'event_contract', v_contract_id, v_code || ':v1', jsonb_build_object('status','draft'), jsonb_build_object('status','published'), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_contract','key',v_code || ':v1','action','created');
    END IF;

    -- ---- 5. activate event ONLY after a published contract ----------------
    IF v_write THEN
      IF v_contract_id IS NULL THEN
        v_blocked := v_blocked + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_definition','key',v_code,'action','blocked','reason','published_contract_required_before_activation');
        CONTINUE;
      END IF;
      IF EXISTS (SELECT 1 FROM public.omni_comms_event_definition WHERE id = v_event_id AND status = 'draft') THEN
        UPDATE public.omni_comms_event_definition
           SET status = 'active', updated_at = now(), updated_by = p_actor_id
         WHERE id = v_event_id;
        PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_activate', 'event_definition', v_event_id, v_code, jsonb_build_object('status','draft'), jsonb_build_object('status','active'), p_correlation_id);
      END IF;
    END IF;

    -- ---- 6. template family ------------------------------------------------
    v_family_code := it ->> 'family_code';
    v_family_id := NULL;
    SELECT * INTO rec FROM public.omni_comms_template_family WHERE code = v_family_code;
    IF FOUND THEN
      v_note_reason := NULL;
      IF rec.organization_id IS DISTINCT FROM p_organization_id THEN
        v_note_reason := 'family_belongs_to_other_organization';
      ELSIF rec.scope_type IS DISTINCT FROM 'event' THEN
        v_note_reason := 'family_scope_mismatch';
      ELSIF v_event_id IS NOT NULL AND rec.event_definition_id IS DISTINCT FROM v_event_id THEN
        v_note_reason := 'family_event_mismatch';
      ELSIF rec.status NOT IN ('draft', 'active') THEN
        v_note_reason := 'unexpected_status:' || rec.status;
      END IF;
      IF v_note_reason IS NOT NULL THEN
        v_conflicts := v_conflicts + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','conflict','reason',v_note_reason);
        CONTINUE;
      END IF;
      v_family_id := rec.id;
      IF rec.status = 'draft' AND v_repair THEN
        UPDATE public.omni_comms_template_family
           SET status = 'active', activated_at = now(), activated_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_family_id;
        PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_repair', 'template_family', v_family_id, v_family_code, NULL, jsonb_build_object('status','active'), p_correlation_id);
      END IF;
      v_existing := v_existing + 1;
      v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','existing_compatible');
    ELSIF NOT v_write THEN
      v_planned := v_planned + 1;
      v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','planned');
    ELSE
      INSERT INTO public.omni_comms_template_family
        (code, name, description, scope_type, organization_id, department_id, event_definition_id, status, created_by, updated_by)
      VALUES (v_family_code, (it ->> 'name') || ' Templates',
              'reference_seed(v2): reference templates for ' || v_code,
              'event', p_organization_id, NULL, v_event_id, 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_family_id;
      UPDATE public.omni_comms_template_family
         SET status = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_family_id;
      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create', 'template_family', v_family_id, v_family_code, NULL, jsonb_build_object('status','active'), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','template_family','key',v_family_code,'action','created');
    END IF;

    -- ---- per channel: template version + route ----------------------------
    FOR ch IN SELECT * FROM jsonb_array_elements(it -> 'channels') LOOP
      v_key := v_family_code || ':' || (ch ->> 'channel');

      SELECT id INTO v_layout_id FROM public.core_template_layout
       WHERE code = (c -> 'layouts' ->> (ch ->> 'channel')) AND is_active LIMIT 1;

      v_layout_ver := NULL;
      IF v_layout_id IS NOT NULL THEN
        SELECT id INTO v_layout_ver FROM public.core_template_layout_version
         WHERE layout_id = v_layout_id AND status = 'published'
         ORDER BY version_number DESC LIMIT 1;
      END IF;

      v_version_id := NULL;
      v_found := false;
      IF v_family_id IS NOT NULL THEN
        SELECT * INTO rec FROM public.omni_comms_template_version
         WHERE template_family_id = v_family_id AND channel = ch ->> 'channel'
           AND locale = v_locale AND version_number = 1;
        v_found := FOUND;
      END IF;

      IF v_found THEN
        v_checksum := public.omni_comms_priv_compute_template_checksum(
          v_family_code, 1, ch ->> 'channel', v_locale, rec.content);
        v_note_reason := NULL;
        IF rec.status = 'published' AND rec.checksum IS DISTINCT FROM v_checksum THEN
          v_note_reason := 'template_checksum_mismatch';
        ELSIF NOT public.omni_comms_priv_layout_selection_valid(
                rec.layout_selection_mode, rec.layout_id, rec.pinned_layout_version_id, rec.channel) THEN
          IF v_repair AND v_layout_id IS NOT NULL AND v_layout_ver IS NOT NULL THEN
            UPDATE public.omni_comms_template_version
               SET layout_selection_mode = 'pinned', layout_id = v_layout_id,
                   pinned_layout_version_id = v_layout_ver,
                   updated_at = now(), updated_by = p_actor_id
             WHERE id = rec.id;
            PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_repair', 'template_version', rec.id, v_key, NULL, jsonb_build_object('layout_selection_mode','pinned'), p_correlation_id);
          ELSE
            v_note_reason := 'invalid_layout_selection';
          END IF;
        END IF;

        IF v_note_reason IS NULL AND rec.status <> 'published' THEN
          IF v_repair THEN
            UPDATE public.omni_comms_template_version
               SET status = 'approved', checksum = v_checksum, approved_at = now(), approved_by = p_actor_id,
                   updated_at = now(), updated_by = p_actor_id
             WHERE id = rec.id AND status = 'draft';
            UPDATE public.omni_comms_template_version
               SET status = 'published', published_at = now(), published_by = p_actor_id,
                   updated_at = now(), updated_by = p_actor_id
             WHERE id = rec.id;
            PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_publish', 'template_version', rec.id, v_key, jsonb_build_object('status',rec.status), jsonb_build_object('status','published'), p_correlation_id);
          ELSE
            v_note_reason := 'template_not_published:' || rec.status;
          END IF;
        END IF;

        IF v_note_reason IS NOT NULL THEN
          v_conflicts := v_conflicts + 1;
          v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_key,'action','conflict','reason',v_note_reason);
        ELSE
          v_version_id := rec.id;
          v_existing := v_existing + 1;
          v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_key,'action','existing_compatible');
        END IF;
      ELSIF v_layout_id IS NULL OR v_layout_ver IS NULL THEN
        v_blocked := v_blocked + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_key,'action','blocked','reason','no_published_layout_version');
      ELSIF NOT v_write THEN
        v_planned := v_planned + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_key,'action','planned');
      ELSIF v_family_id IS NULL THEN
        v_blocked := v_blocked + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_key,'action','blocked','reason','family_unavailable');
      ELSE
        PERFORM public.omni_comms_priv_validate_channel_content(ch ->> 'channel', ch -> 'content');
        INSERT INTO public.omni_comms_template_version
          (template_family_id, version_number, channel, locale, content, status,
           layout_selection_mode, layout_id, pinned_layout_version_id, created_by, updated_by)
        VALUES (v_family_id, 1, ch ->> 'channel', v_locale, ch -> 'content', 'draft',
                'pinned', v_layout_id, v_layout_ver, NULL, p_actor_id)
        RETURNING id INTO v_version_id;

        v_checksum := public.omni_comms_priv_compute_template_checksum(
          v_family_code, 1, ch ->> 'channel', v_locale, ch -> 'content');

        UPDATE public.omni_comms_template_version
           SET status = 'approved', checksum = v_checksum, approved_at = now(), approved_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_version_id;
        UPDATE public.omni_comms_template_version
           SET status = 'published', published_at = now(), published_by = p_actor_id,
               updated_at = now(), updated_by = p_actor_id
         WHERE id = v_version_id;

        PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_publish', 'template_version', v_version_id, v_key, NULL, jsonb_build_object('status','published','checksum',v_checksum,'layout_selection_mode','pinned'), p_correlation_id);
        v_created := v_created + 1;
        v_actions := v_actions || jsonb_build_object('object_type','template_version','key',v_key,'action','created');
      END IF;

      -- ---- route ----------------------------------------------------------
      v_key := v_code || ':' || (ch ->> 'channel');
      SELECT id INTO v_sender_id FROM public.omni_comms_sender_identity
       WHERE organization_id = p_organization_id AND code = ch ->> 'sender_code';

      v_found := false;
      IF v_event_id IS NOT NULL THEN
        SELECT * INTO rec FROM public.omni_comms_event_route
         WHERE organization_id = p_organization_id
           AND department_id IS NOT DISTINCT FROM v_dept_id
           AND event_definition_id = v_event_id
           AND channel = ch ->> 'channel';
        v_found := FOUND;
      END IF;

      IF v_found THEN
        v_note_reason := NULL;
        IF v_family_id IS NOT NULL AND rec.template_family_id IS DISTINCT FROM v_family_id THEN
          v_note_reason := 'route_family_mismatch';
        ELSIF v_sender_id IS NOT NULL AND rec.sender_identity_id IS DISTINCT FROM v_sender_id THEN
          v_note_reason := 'route_sender_mismatch';
        ELSIF rec.lifecycle_state NOT IN ('draft', 'active') THEN
          v_note_reason := 'unexpected_lifecycle:' || rec.lifecycle_state;
        END IF;
        IF v_note_reason IS NOT NULL THEN
          v_conflicts := v_conflicts + 1;
          v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_key,'action','conflict','reason',v_note_reason);
          CONTINUE;
        END IF;
        IF v_repair AND (rec.lifecycle_state = 'draft' OR COALESCE(rec.is_enabled,false) = false) THEN
          UPDATE public.omni_comms_event_route
             SET lifecycle_state = 'active', is_enabled = true,
                 activated_at = COALESCE(activated_at, now()), activated_by = COALESCE(activated_by, p_actor_id),
                 updated_at = now(), updated_by = p_actor_id
           WHERE id = rec.id;
          PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_repair', 'event_route', rec.id, v_key, NULL, jsonb_build_object('lifecycle_state','active'), p_correlation_id);
        END IF;
        v_existing := v_existing + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_key,'action','existing_compatible');
        CONTINUE;
      END IF;

      IF NOT v_write THEN
        v_planned := v_planned + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_key,'action','planned');
        CONTINUE;
      END IF;

      IF v_family_id IS NULL OR v_sender_id IS NULL OR v_version_id IS NULL THEN
        v_blocked := v_blocked + 1;
        v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_key,'action','blocked','reason','template_or_sender_unavailable');
        CONTINUE;
      END IF;

      INSERT INTO public.omni_comms_event_route
        (organization_id, department_id, event_definition_id, channel, is_required, is_enabled, priority,
         template_family_id, sender_identity_id, sender_resolution_policy, preference_policy, lifecycle_state,
         created_by, updated_by)
      VALUES
        (p_organization_id, v_dept_id, v_event_id, ch ->> 'channel',
         COALESCE((ch ->> 'is_required')::boolean, false), true,
         COALESCE((ch ->> 'priority')::integer, 100),
         v_family_id, v_sender_id, 'explicit', 'honour', 'draft', p_actor_id, p_actor_id)
      RETURNING id INTO v_id;

      UPDATE public.omni_comms_event_route
         SET lifecycle_state = 'active', activated_at = now(), activated_by = p_actor_id,
             updated_at = now(), updated_by = p_actor_id
       WHERE id = v_id;

      PERFORM public.omni_comms_priv_write_audit(p_actor_id, 'reference_seed_create', 'event_route', v_id, v_key, NULL, jsonb_build_object('lifecycle_state','active'), p_correlation_id);
      v_created := v_created + 1;
      v_actions := v_actions || jsonb_build_object('object_type','event_route','key',v_key,'action','created');
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'catalogue_version', (c ->> 'catalogue_version')::int,
    'mode', p_mode,
    'created', v_created,
    'planned', v_planned,
    'existing', v_existing,
    'conflicts', v_conflicts,
    'blocked', v_blocked,
    'skipped', v_skipped,
    'actions', v_actions,
    'generated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_reject_nonlocal_refs(p_schema jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_node jsonb;
  v_val  jsonb;
  v_ref  text;
BEGIN
  IF p_schema IS NULL OR jsonb_typeof(p_schema) <> 'object' THEN
    RETURN;
  END IF;

  FOR v_node IN
    WITH RECURSIVE walk(node) AS (
      SELECT p_schema
      UNION ALL
      SELECT CASE
               WHEN jsonb_typeof(w.node) = 'object' THEN kv.value
               WHEN jsonb_typeof(w.node) = 'array'  THEN elem.value
             END
      FROM walk w
      LEFT JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(w.node) = 'object' THEN w.node ELSE '{}'::jsonb END) kv  ON jsonb_typeof(w.node) = 'object'
      LEFT JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(w.node) = 'array' THEN w.node ELSE '[]'::jsonb END) elem ON jsonb_typeof(w.node) = 'array'
      WHERE w.node IS NOT NULL
        AND jsonb_typeof(w.node) IN ('object','array')
    )
    SELECT node FROM walk WHERE node IS NOT NULL AND jsonb_typeof(node) = 'object'
  LOOP
    IF v_node ? '$ref' THEN
      v_val := v_node -> '$ref';
      -- A JSON Schema $ref keyword MUST be a string. If it is an object /
      -- array / other type it is a property named "$ref", not a reference,
      -- and must not be inspected. Only string-valued $refs are enforced.
      IF jsonb_typeof(v_val) = 'string' THEN
        v_ref := trim(both '"' from v_val::text);
        IF v_ref = '' OR left(v_ref, 1) <> '#' THEN
          RAISE EXCEPTION 'OC422 validation_error'
            USING ERRCODE = 'P0001', DETAIL = 'non_local_ref';
        END IF;
      END IF;
    END IF;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_release_decision_snapshot_bounded(p_snapshot jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT p_snapshot IS NULL
     OR (
       jsonb_typeof(p_snapshot) = 'object'
       AND length(p_snapshot::text) <= 8192
       -- no raw email address, no rendered content, no credential material
       AND p_snapshot::text !~* '[A-Za-z0-9._%%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}'
       AND p_snapshot::text !~* '(secret_ref|secret_name|api_key|authorization|bearer |password|rendered_|body_html|body_text)'
     );
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_release_event_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'OC412 immutable_release_event'
    USING ERRCODE = '42501',
          DETAIL = 'omni_comms_channel_release_event is append-only; update and delete are rejected for every role, including service_role.';
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_request_binding_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.producer_event_binding_id IS DISTINCT FROM OLD.producer_event_binding_id THEN
    RAISE EXCEPTION 'OC409 producer_binding_immutable'
      USING ERRCODE = 'P0001', DETAIL = 'producer_binding_immutable';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_request_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(NEW.department_id, NEW.organization_id);
  END IF;
  PERFORM public.omni_comms_priv_require_json_object(NEW.payload_snapshot, 262144);
  PERFORM public.omni_comms_priv_validate_channel_array(NEW.requested_channels);
  IF jsonb_typeof(NEW.blockers) <> 'array' THEN
    RAISE EXCEPTION 'OC422 blockers_must_be_array' USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.event_definition_id IS DISTINCT FROM OLD.event_definition_id
       OR NEW.mode IS DISTINCT FROM OLD.mode
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint
       OR NEW.caller_module_code IS DISTINCT FROM OLD.caller_module_code
       OR NEW.payload_snapshot IS DISTINCT FROM OLD.payload_snapshot THEN
      RAISE EXCEPTION 'OC422 request_immutable_fields' USING ERRCODE = 'P0001';
    END IF;
    IF NEW.status <> OLD.status THEN
      IF NOT (
        (OLD.status = 'accepted'   AND NEW.status IN ('processing','failed','blocked')) OR
        (OLD.status = 'processing' AND NEW.status IN ('completed','completed_with_blockers','blocked','failed'))
      ) THEN
        RAISE EXCEPTION 'OC422 invalid_request_transition' USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_require_capability(p_action text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required'
      USING ERRCODE = 'P0001', DETAIL = 'authentication_required';
  END IF;
  IF NOT public.has_permission(v_uid, 'omni_comms', p_action) THEN
    RAISE EXCEPTION 'OC403 permission_denied'
      USING ERRCODE = 'P0001', DETAIL = p_action;
  END IF;
  RETURN v_uid;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_require_json_object(p_value jsonb, p_max_bytes integer)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF p_value IS NULL OR jsonb_typeof(p_value) <> 'object' THEN
    RAISE EXCEPTION 'OC422 json_object_required' USING ERRCODE = 'P0001';
  END IF;
  IF p_max_bytes IS NOT NULL AND octet_length(p_value::text) > p_max_bytes THEN
    RAISE EXCEPTION 'OC422 json_too_large' USING ERRCODE = 'P0001';
  END IF;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_require_tenant_access(p_actor_id uuid, p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_privileged  boolean;
  v_dept_org    uuid;
  v_dept_active boolean;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required'
      USING ERRCODE = 'P0001', DETAIL = 'authentication_required';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC400 organization_required'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.core_organization o
    WHERE o.id = p_organization_id
      AND coalesce(lower(o.status), 'active') NOT IN ('retired', 'archived', 'deleted')
  ) THEN
    RAISE EXCEPTION 'OC403 organization_access_denied'
      USING ERRCODE = 'P0001', DETAIL = 'organization_access_denied';
  END IF;

  v_privileged := public.is_admin(p_actor_id)
                  OR public.has_permission(p_actor_id, 'omni_comms', 'administer');

  IF NOT v_privileged THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.core_staff_assignments a
      JOIN public.core_department d ON d.id = a.department_id
      WHERE a.user_id = p_actor_id
        AND a.is_active = true
        AND a.assignment_status = 'ACTIVE'
        AND (a.effective_to IS NULL OR a.effective_to >= CURRENT_DATE)
        AND d.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION 'OC403 organization_access_denied'
        USING ERRCODE = 'P0001', DETAIL = 'organization_access_denied';
    END IF;
  END IF;

  IF p_department_id IS NOT NULL THEN
    SELECT d.organization_id, coalesce(d.is_active, true)
      INTO v_dept_org, v_dept_active
    FROM public.core_department d
    WHERE d.id = p_department_id;

    IF v_dept_org IS NULL OR NOT v_dept_active THEN
      RAISE EXCEPTION 'OC403 department_access_denied'
        USING ERRCODE = 'P0001', DETAIL = 'department_access_denied';
    END IF;
    IF v_dept_org <> p_organization_id THEN
      RAISE EXCEPTION 'OC403 department_organization_mismatch'
        USING ERRCODE = 'P0001', DETAIL = 'department_organization_mismatch';
    END IF;

    IF NOT v_privileged THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.core_staff_assignments a
        WHERE a.user_id = p_actor_id
          AND a.department_id = p_department_id
          AND a.is_active = true
          AND a.assignment_status = 'ACTIVE'
          AND (a.effective_to IS NULL OR a.effective_to >= CURRENT_DATE)
      ) THEN
        RAISE EXCEPTION 'OC403 department_access_denied'
          USING ERRCODE = 'P0001', DETAIL = 'department_access_denied';
      END IF;
    END IF;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_runtime_certification()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_count integer;
  v_state text;
  v_commit text;
  v_run text;
  v_at timestamptz;
  v_commit_valid boolean;
BEGIN
  BEGIN
    SELECT count(*) INTO v_count FROM public.omni_comms_runtime_certification;
    IF v_count <> 1 THEN
      RETURN jsonb_build_object(
        'certification_state', 'pending',
        'certified_commit', NULL,
        'certified_commit_valid', false,
        'workflow_run_id', NULL,
        'certified_at', NULL,
        'effective_certified', false
      );
    END IF;
    SELECT lower(btrim(coalesce(certification_state, ''))),
           lower(btrim(coalesce(certified_commit, ''))),
           workflow_run_id,
           certified_at
      INTO v_state, v_commit, v_run, v_at
      FROM public.omni_comms_runtime_certification
     WHERE singleton;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'certification_state', 'pending',
      'certified_commit', NULL,
      'certified_commit_valid', false,
      'workflow_run_id', NULL,
      'certified_at', NULL,
      'effective_certified', false
    );
  END;

  IF v_state IS NULL OR v_state NOT IN ('pending', 'certified', 'failed') THEN
    v_state := 'pending';
  END IF;

  v_commit_valid := v_commit ~ '^[0-9a-f]{40}$';
  IF NOT v_commit_valid THEN
    v_commit := NULL;
  END IF;

  RETURN jsonb_build_object(
    'certification_state', v_state,
    'certified_commit', v_commit,
    'certified_commit_valid', v_commit_valid,
    'workflow_run_id', v_run,
    'certified_at', v_at,
    'effective_certified', (v_state = 'certified' AND v_commit_valid AND v_run IS NOT NULL AND v_at IS NOT NULL)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_runtime_environment()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_env text;
  v_count integer;
BEGIN
  BEGIN
    SELECT count(*) INTO v_count FROM public.omni_comms_runtime_environment;
    IF v_count <> 1 THEN
      RETURN 'unknown';
    END IF;
    SELECT lower(btrim(coalesce(environment, '')))
      INTO v_env
      FROM public.omni_comms_runtime_environment
     WHERE singleton;
  EXCEPTION WHEN OTHERS THEN
    RETURN 'unknown';
  END;

  IF v_env IS NULL OR v_env NOT IN ('non_production', 'production') THEN
    RETURN 'unknown';
  END IF;
  RETURN v_env;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_runtime_health_posture(p_deployed_revision text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_posture jsonb;
  v_cert text;
  v_env text;
  v_commit text;
  v_commit_valid boolean;
  v_effective boolean;
  v_rev text;
  v_rev_verified boolean;
  v_match text;
  v_permitted boolean;
  v_reason text;
  v_gate text;
BEGIN
  v_posture := public.omni_comms_priv_certification_posture();
  v_cert := v_posture ->> 'certification_state';
  v_env := v_posture ->> 'environment';
  v_commit := v_posture ->> 'certified_commit';
  v_commit_valid := coalesce((v_posture ->> 'certified_commit_valid')::boolean, false);
  v_effective := coalesce((v_posture ->> 'effective_certified')::boolean, false);
  v_rev := lower(btrim(coalesce(p_deployed_revision, '')));
  v_rev_verified := v_rev ~ '^[0-9a-f]{40}$';
  v_gate := public.omni_comms_priv_dry_run_gate_state();

  IF NOT v_rev_verified OR NOT v_commit_valid THEN
    v_match := 'unknown';
  ELSIF v_rev = lower(v_commit) THEN
    v_match := 'match';
  ELSE
    v_match := 'mismatch';
  END IF;

  v_permitted := false;
  IF v_gate <> 'enabled' THEN
    v_reason := 'admin_dry_run_disabled';
  ELSIF v_env <> 'non_production' THEN
    v_reason := 'non_production_environment_required';
  ELSIF v_cert = 'failed' THEN
    v_reason := 'runtime_certification_failed';
  ELSIF v_cert <> 'certified' THEN
    v_reason := 'runtime_certification_required';
  ELSIF NOT v_commit_valid THEN
    v_reason := 'runtime_certified_commit_invalid';
  ELSIF NOT v_effective THEN
    v_reason := 'runtime_certification_record_incomplete';
  ELSIF NOT v_rev_verified THEN
    v_reason := 'runtime_revision_unverified';
  ELSIF v_match <> 'match' THEN
    v_reason := 'runtime_revision_mismatch';
  ELSE
    v_permitted := true;
    v_reason := NULL;
  END IF;

  RETURN jsonb_build_object(
    'certificationState', v_cert,
    'certifiedCommit', v_commit,
    'environment', v_env,
    'revision', nullif(v_rev, ''),
    'revisionVerified', v_rev_verified,
    'revisionMatch', v_match,
    'effectiveCertified', v_effective,
    'safeTestPermitted', v_permitted,
    'safeTestBlockedReason', v_reason
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_runtime_resolution_snapshot(p_actor_id uuid, p_organization_id uuid, p_department_id uuid, p_event_code text, p_requested_channels text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_normalized_code text := btrim(coalesce(p_event_code,''));
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 organization_required' USING ERRCODE='P0001';
  END IF;
  IF v_normalized_code = '' OR length(v_normalized_code) > 128 THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;

  WITH
    ev AS (
      SELECT id, code, status, module_code, entity_type, communication_class,
             default_priority
      FROM public.omni_comms_event_definition
      WHERE code = v_normalized_code
    ),
    contracts AS (
      SELECT c.id, c.event_definition_id, c.version_number, c.checksum,
             c.status, c.json_schema, c.published_at
      FROM public.omni_comms_event_contract c
      WHERE c.event_definition_id IN (SELECT id FROM ev)
        AND c.status = 'published'
    ),
    routes AS (
      SELECT r.id, r.organization_id, r.department_id, r.event_definition_id,
             r.channel, r.is_required, r.is_enabled, r.priority,
             r.template_family_id, r.sender_identity_id,
             r.sender_resolution_policy, r.preference_policy,
             r.lifecycle_state, r.created_at
      FROM public.omni_comms_event_route r
      WHERE r.event_definition_id IN (SELECT id FROM ev)
        AND r.organization_id = p_organization_id
        AND r.is_enabled = true
        AND r.lifecycle_state = 'active'
        AND (r.department_id IS NULL OR r.department_id = p_department_id)
    ),
    routes_ranked AS (
      SELECT r.*,
        ROW_NUMBER() OVER (
          PARTITION BY channel
          ORDER BY
            CASE WHEN r.department_id IS NOT NULL AND r.department_id = p_department_id
                 THEN 0 ELSE 1 END,
            r.priority ASC,
            r.created_at DESC,
            r.id
        ) AS rk
      FROM routes r
    ),
    winning_routes AS (
      SELECT * FROM routes_ranked WHERE rk = 1
    ),
    filtered_routes AS (
      SELECT wr.*
      FROM winning_routes wr
      WHERE coalesce(array_length(p_requested_channels,1),0) = 0
         OR wr.channel = ANY(p_requested_channels)
    ),
    channel_settings AS (
      SELECT cs.id, cs.organization_id, cs.department_id, cs.channel,
             cs.enabled, cs.live_delivery_enabled
      FROM public.omni_comms_channel_setting cs
      WHERE cs.organization_id = p_organization_id
        AND (cs.department_id IS NULL OR cs.department_id = p_department_id)
    ),
    template_families AS (
      SELECT tf.id, tf.code, tf.scope_type, tf.organization_id,
             tf.department_id, tf.event_definition_id, tf.status
      FROM public.omni_comms_template_family tf
      WHERE tf.organization_id = p_organization_id
        AND tf.status = 'active'
        AND (tf.department_id IS NULL OR tf.department_id = p_department_id)
        AND (tf.event_definition_id IS NULL
             OR tf.event_definition_id IN (SELECT id FROM ev))
    ),
    template_versions AS (
      SELECT tv.id, tv.template_family_id, tv.version_number, tv.channel,
             tv.locale, tv.content, tv.checksum, tv.status,
             tv.layout_selection_mode, tv.layout_id, tv.pinned_layout_version_id
      FROM public.omni_comms_template_version tv
      WHERE tv.status = 'published'
        AND tv.template_family_id IN (SELECT id FROM template_families)
    ),
    layouts AS (
      SELECT l.id, l.code, l.name, l.is_active, l.layout_kind
      FROM public.core_template_layout l
      WHERE l.is_active = true
    ),
    layout_versions AS (
      SELECT lv.id, lv.layout_id, lv.version_number, lv.slots,
             lv.wrapper_html, lv.checksum, lv.status
      FROM public.core_template_layout_version lv
      WHERE lv.status = 'published'
    ),
    layout_assignments AS (
      SELECT ca.id, ca.organization_id, ca.department_id, ca.output_channel,
             ca.layout_id
      FROM public.core_comm_assignment ca
      WHERE ca.assignment_kind = 'layout_default'
        AND ca.organization_id = p_organization_id
        AND (ca.department_id IS NULL OR ca.department_id = p_department_id)
    ),
    asset_assignments AS (
      SELECT ca.id, ca.organization_id, ca.department_id, ca.output_channel,
             ca.slot_code, ca.asset_id
      FROM public.core_comm_assignment ca
      WHERE ca.assignment_kind = 'asset_slot'
        AND ca.organization_id = p_organization_id
        AND (ca.department_id IS NULL OR ca.department_id = p_department_id)
    ),
    assets AS (
      SELECT a.id, a.organization_id, a.department_id, a.asset_type,
             a.code, a.status, a.active_version_id
      FROM public.core_comm_asset a
      WHERE a.organization_id = p_organization_id
        AND a.status = 'active'
    ),
    asset_versions AS (
      SELECT av.id, av.asset_id, av.version_number, av.checksum, av.status,
             av.content_html, av.content_text, av.content_json,
             av.storage_bucket, av.storage_object_path
      FROM public.core_comm_asset_version av
      WHERE av.status = 'published'
        AND av.asset_id IN (SELECT id FROM assets)
    ),
    senders AS (
      SELECT s.id, s.organization_id, s.department_id, s.event_definition_id,
             s.code, s.channel, s.from_address, s.from_name,
             s.reply_to_address, s.status
      FROM public.omni_comms_sender_identity s
      WHERE s.organization_id = p_organization_id
        AND s.status = 'active'
        AND (s.department_id IS NULL OR s.department_id = p_department_id)
        AND (s.event_definition_id IS NULL
             OR s.event_definition_id IN (SELECT id FROM ev))
    ),
    bindings AS (
      SELECT b.id, b.sender_identity_id, b.provider_account_id, b.priority,
             b.verification_status, b.status
      FROM public.omni_comms_sender_provider_binding b
      WHERE b.status = 'active'
        AND b.sender_identity_id IN (SELECT id FROM senders)
    ),
    provider_accounts AS (
      SELECT pa.id, pa.organization_id, pa.provider_id, pa.code, pa.status,
             pa.health_state, pa.sandbox_mode,
             (pa.secret_ref IS NOT NULL AND length(pa.secret_ref) > 0)
               AS secret_reference_configured
      FROM public.omni_comms_provider_account pa
      WHERE pa.organization_id = p_organization_id
        AND pa.status = 'active'
        AND pa.id IN (SELECT provider_account_id FROM bindings)
    ),
    providers AS (
      SELECT p.id, p.code, p.display_name, p.channel, p.adapter_key, p.status
      FROM public.omni_comms_provider p
      WHERE p.status = 'active'
        AND p.id IN (SELECT provider_id FROM provider_accounts)
    )
  SELECT jsonb_build_object(
    'snapshot_at',        now(),
    'organization_id',    p_organization_id,
    'department_id',      p_department_id,
    'requested_channels', coalesce(to_jsonb(p_requested_channels), '[]'::jsonb),
    'event',              (SELECT to_jsonb(ev.*) FROM ev),
    'event_contracts',
      coalesce((SELECT jsonb_agg(to_jsonb(c.*) ORDER BY c.version_number DESC)
                  FROM contracts c), '[]'::jsonb),
    'routes',
      coalesce((SELECT jsonb_agg(to_jsonb(fr.*) ORDER BY fr.channel)
                  FROM filtered_routes fr), '[]'::jsonb),
    'channel_settings',
      coalesce((SELECT jsonb_agg(to_jsonb(cs.*)) FROM channel_settings cs), '[]'::jsonb),
    'template_families',
      coalesce((SELECT jsonb_agg(to_jsonb(tf.*)) FROM template_families tf), '[]'::jsonb),
    'template_versions',
      coalesce((SELECT jsonb_agg(to_jsonb(tv.*)) FROM template_versions tv), '[]'::jsonb),
    'layouts',
      coalesce((SELECT jsonb_agg(to_jsonb(l.*)) FROM layouts l), '[]'::jsonb),
    'layout_versions',
      coalesce((SELECT jsonb_agg(to_jsonb(lv.*)) FROM layout_versions lv), '[]'::jsonb),
    'layout_assignments',
      coalesce((SELECT jsonb_agg(to_jsonb(la.*)) FROM layout_assignments la), '[]'::jsonb),
    'asset_assignments',
      coalesce((SELECT jsonb_agg(to_jsonb(aa.*)) FROM asset_assignments aa), '[]'::jsonb),
    'assets',
      coalesce((SELECT jsonb_agg(to_jsonb(a.*)) FROM assets a), '[]'::jsonb),
    'asset_versions',
      coalesce((SELECT jsonb_agg(to_jsonb(av.*)) FROM asset_versions av), '[]'::jsonb),
    'senders',
      coalesce((SELECT jsonb_agg(to_jsonb(s.*)) FROM senders s), '[]'::jsonb),
    'bindings',
      coalesce((SELECT jsonb_agg(to_jsonb(b.*)) FROM bindings b), '[]'::jsonb),
    'providers',
      coalesce((SELECT jsonb_agg(to_jsonb(p.*)) FROM providers p), '[]'::jsonb),
    'provider_accounts',
      coalesce((SELECT jsonb_agg(to_jsonb(pa.*)) FROM provider_accounts pa), '[]'::jsonb)
  )
  INTO v_result;

  RETURN v_result;
END
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_send_communication(p_actor_id uuid, p_organization_id uuid, p_department_id uuid, p_event_code text, p_mode text, p_idempotency_key text, p_caller_module_code text, p_caller_entity_type text, p_caller_entity_id text, p_correlation_id text, p_request_fingerprint text, p_payload jsonb, p_requested_channels text[], p_producer_event_binding_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id  uuid;
  v_caller    text := coalesce(nullif(btrim(p_caller_module_code), ''), 'OMNI_COMMS_DIRECT');
  v_existing  record;
  v_chan      text;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'OC401 authentication_required' USING ERRCODE='P0001';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 organization_required' USING ERRCODE='P0001';
  END IF;
  IF p_event_code IS NULL OR btrim(p_event_code) = '' OR length(p_event_code) > 128 THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('dry_run','shadow','queued') THEN
    RAISE EXCEPTION 'OC422 mode_invalid' USING ERRCODE='P0001';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) < 8 THEN
    RAISE EXCEPTION 'OC422 idempotency_key_required' USING ERRCODE='P0001';
  END IF;
  IF length(p_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'OC422 idempotency_key_too_long' USING ERRCODE='P0001';
  END IF;
  IF p_request_fingerprint IS NULL OR p_request_fingerprint !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'OC422 payload_invalid' USING ERRCODE='P0001';
  END IF;
  IF octet_length(p_payload::text) > 262144 THEN
    RAISE EXCEPTION 'OC422 payload_too_large' USING ERRCODE='P0001';
  END IF;
  IF length(v_caller) > 64 THEN
    RAISE EXCEPTION 'OC422 invalid_input' USING ERRCODE='P0001';
  END IF;
  IF p_requested_channels IS NOT NULL THEN
    IF array_length(p_requested_channels, 1) > 8 THEN
      RAISE EXCEPTION 'OC422 channel_invalid' USING ERRCODE='P0001';
    END IF;
    FOREACH v_chan IN ARRAY p_requested_channels LOOP
      IF v_chan IS NULL
         OR v_chan NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
        RAISE EXCEPTION 'OC422 channel_invalid' USING ERRCODE='P0001';
      END IF;
    END LOOP;
  END IF;

  -- The binding is supplied by the TRUSTED runtime only (this function is
  -- service_role-only). It must exist, be active and belong to this
  -- organisation and caller module.
  IF p_producer_event_binding_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.omni_comms_producer_event_binding b
      WHERE b.id = p_producer_event_binding_id
        AND b.organization_id = p_organization_id
        AND b.caller_module_code = upper(v_caller)
        AND b.status = 'active'
    ) THEN
      RAISE EXCEPTION 'OC403 producer_event_not_authorized' USING ERRCODE='P0001';
    END IF;
  END IF;

  SELECT id INTO v_event_id
  FROM public.omni_comms_event_definition
  WHERE code = btrim(p_event_code);
  IF v_event_id IS NULL THEN
    RAISE EXCEPTION 'OC404 event_code_not_found' USING ERRCODE='P0001';
  END IF;

  SELECT r.id, r.request_fingerprint, r.mode, r.status, r.created_at,
         r.idempotency_key, r.producer_event_binding_id
    INTO v_existing
  FROM public.omni_comms_request r
  WHERE r.organization_id    = p_organization_id
    AND r.caller_module_code = v_caller
    AND r.idempotency_key    = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
      RAISE EXCEPTION 'OC409 idempotency_payload_mismatch' USING ERRCODE='P0001';
    END IF;
    RETURN jsonb_build_object(
      'request_id',      v_existing.id,
      'idempotency_key', v_existing.idempotency_key,
      'mode',            v_existing.mode,
      'status',          v_existing.status,
      'created_at',      v_existing.created_at,
      'producer_event_binding_id', v_existing.producer_event_binding_id,
      'replayed',        true
    );
  END IF;

  BEGIN
    INSERT INTO public.omni_comms_request (
      organization_id, department_id, event_definition_id, mode, status,
      idempotency_key, idempotency_scope, request_fingerprint, correlation_id,
      caller_module_code, caller_entity_type, caller_entity_id,
      payload_snapshot, requested_channels, requested_by, accepted_at,
      producer_event_binding_id
    ) VALUES (
      p_organization_id, p_department_id, v_event_id, p_mode, 'accepted',
      p_idempotency_key,
      'caller_module',
      p_request_fingerprint,
      nullif(btrim(coalesce(p_correlation_id, '')), ''),
      v_caller,
      nullif(btrim(coalesce(p_caller_entity_type, '')), ''),
      nullif(btrim(coalesce(p_caller_entity_id, '')), ''),
      p_payload,
      coalesce(p_requested_channels, ARRAY[]::text[]),
      p_actor_id,
      now(),
      p_producer_event_binding_id
    );
  EXCEPTION WHEN unique_violation THEN
    SELECT r.id, r.request_fingerprint, r.mode, r.status, r.created_at,
           r.idempotency_key, r.producer_event_binding_id
      INTO v_existing
    FROM public.omni_comms_request r
    WHERE r.organization_id    = p_organization_id
      AND r.caller_module_code = v_caller
      AND r.idempotency_key    = p_idempotency_key;
    IF v_existing.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
      RAISE EXCEPTION 'OC409 idempotency_payload_mismatch' USING ERRCODE='P0001';
    END IF;
    RETURN jsonb_build_object(
      'request_id',      v_existing.id,
      'idempotency_key', v_existing.idempotency_key,
      'mode',            v_existing.mode,
      'status',          v_existing.status,
      'created_at',      v_existing.created_at,
      'producer_event_binding_id', v_existing.producer_event_binding_id,
      'replayed',        true
    );
  END;

  SELECT r.id, r.created_at, r.mode, r.status, r.idempotency_key,
         r.correlation_id, r.producer_event_binding_id
    INTO v_existing
  FROM public.omni_comms_request r
  WHERE r.organization_id    = p_organization_id
    AND r.caller_module_code = v_caller
    AND r.idempotency_key    = p_idempotency_key;

  INSERT INTO public.omni_comms_message_event (
    request_id, message_id, organization_id, event_type, event_sequence,
    status_before, status_after, safe_metadata,
    correlation_id, actor_type, actor_id
  ) VALUES (
    v_existing.id, NULL, p_organization_id, 'request_accepted',
    public.omni_comms_priv_next_event_sequence(v_existing.id),
    NULL, 'accepted',
    jsonb_build_object('mode', v_existing.mode),
    v_existing.correlation_id, 'user', p_actor_id::text
  );

  RETURN jsonb_build_object(
    'request_id',      v_existing.id,
    'idempotency_key', v_existing.idempotency_key,
    'mode',            v_existing.mode,
    'status',          v_existing.status,
    'created_at',      v_existing.created_at,
    'producer_event_binding_id', v_existing.producer_event_binding_id,
    'replayed',        false
  );
END
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_sender_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_event_org uuid;
BEGIN
  -- Ownership: department belongs to organization
  IF NEW.department_id IS NOT NULL THEN
    IF NOT public.omni_comms_priv_verify_department_ownership(NEW.department_id, NEW.organization_id) THEN
      RAISE EXCEPTION 'omni_comms_sender_identity department does not belong to organization'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  -- Ownership: event belongs to organization (event has no org column; enforce via existence in same org context)
  IF NEW.event_definition_id IS NOT NULL THEN
    SELECT organization_id INTO v_event_org
      FROM public.omni_comms_event_definition WHERE id = NEW.event_definition_id;
    IF v_event_org IS NULL OR v_event_org <> NEW.organization_id THEN
      RAISE EXCEPTION 'omni_comms_sender_identity event does not belong to organization'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'omni_comms_sender_identity must be inserted in draft status'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'retired' AND NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'omni_comms_sender_identity retired status is terminal' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status = 'active' AND NEW.status = 'draft' THEN
    RAISE EXCEPTION 'omni_comms_sender_identity cannot revert active to draft' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status NOT IN ('draft','active','retired') THEN
    RAISE EXCEPTION 'omni_comms_sender_identity invalid status %', NEW.status USING ERRCODE = 'P0001';
  END IF;

  IF NEW.status = 'active' AND OLD.status = 'draft' AND NEW.activated_at IS NULL THEN
    NEW.activated_at := now();
  END IF;
  IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS NULL THEN
    RAISE EXCEPTION 'omni_comms_sender_identity activated_at cannot be cleared' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status = 'retired' AND OLD.status <> 'retired' THEN
    IF NEW.retired_at IS NULL THEN NEW.retired_at := now(); END IF;
    IF NEW.retirement_reason IS NULL OR char_length(btrim(NEW.retirement_reason)) < 1 THEN
      RAISE EXCEPTION 'omni_comms_sender_identity retirement requires a reason' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF OLD.status = 'retired' THEN
    IF OLD.retired_at IS DISTINCT FROM NEW.retired_at
       OR OLD.retired_by IS DISTINCT FROM NEW.retired_by
       OR OLD.retirement_reason IS DISTINCT FROM NEW.retirement_reason THEN
      RAISE EXCEPTION 'omni_comms_sender_identity retirement metadata is immutable' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF OLD.status IN ('active','retired') THEN
    IF OLD.code <> NEW.code
       OR OLD.organization_id <> NEW.organization_id
       OR OLD.channel <> NEW.channel THEN
      RAISE EXCEPTION 'omni_comms_sender_identity identity fields are immutable after activation'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_set_runtime_environment(p_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_env text;
BEGIN
  v_env := lower(btrim(coalesce(p_environment, '')));
  IF v_env NOT IN ('unknown', 'non_production', 'production') THEN
    RAISE EXCEPTION 'omni_comms: invalid runtime environment value'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.omni_comms_runtime_environment (singleton, environment, updated_at)
  VALUES (true, v_env, now())
  ON CONFLICT (singleton) DO UPDATE
    SET environment = EXCLUDED.environment,
        updated_at = now();

  DELETE FROM public.omni_comms_runtime_environment WHERE singleton IS DISTINCT FROM true;

  RETURN jsonb_build_object(
    'environment', v_env,
    'updated_at', (SELECT updated_at FROM public.omni_comms_runtime_environment WHERE singleton)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_slice1_verify()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org uuid := gen_random_uuid();
  v_other_org uuid := gen_random_uuid();
  v_event uuid;
  v_req uuid;
  v_rcp uuid;
  v_msg uuid;
  v_job uuid;
BEGIN
  -- All fixture work happens inside a savepoint that we always roll back.
  BEGIN
    INSERT INTO public.omni_comms_event_definition (code, module_code, entity_type, name, communication_class, status)
    VALUES ('MOD.PROBE.EVENT', 'MOD', 'PROBE', 'slice1 probe', 'operational', 'draft')
    RETURNING id INTO v_event;

    -- Channel validation
    BEGIN
      INSERT INTO public.omni_comms_event_route (organization_id, event_definition_id, channel)
      VALUES (v_org, v_event, 'telepathy');
      RAISE EXCEPTION 'FAIL route channel not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; WHEN check_violation THEN NULL; END;

    -- Org-default uniqueness
    INSERT INTO public.omni_comms_event_route (organization_id, event_definition_id, channel, lifecycle_state)
    VALUES (v_org, v_event, 'email', 'active');
    BEGIN
      INSERT INTO public.omni_comms_event_route (organization_id, event_definition_id, channel, lifecycle_state)
      VALUES (v_org, v_event, 'email', 'active');
      RAISE EXCEPTION 'FAIL duplicate route not rejected';
    EXCEPTION WHEN unique_violation THEN NULL; END;

    -- Request bounds and JSON object shape
    BEGIN
      INSERT INTO public.omni_comms_request(organization_id, event_definition_id, mode,
        idempotency_key, request_fingerprint, caller_module_code, payload_snapshot, requested_channels)
      VALUES (v_org, v_event, 'dry_run', 'k', repeat('a',16), 'MOD', '{}'::jsonb, ARRAY['email']);
      RAISE EXCEPTION 'FAIL idempotency length not rejected';
    EXCEPTION WHEN check_violation THEN NULL; END;

    BEGIN
      INSERT INTO public.omni_comms_request(organization_id, event_definition_id, mode,
        idempotency_key, request_fingerprint, caller_module_code, payload_snapshot, requested_channels)
      VALUES (v_org, v_event, 'dry_run', repeat('k',16), repeat('a',16), 'MOD', '[]'::jsonb, ARRAY['email']);
      RAISE EXCEPTION 'FAIL non-object payload not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    BEGIN
      INSERT INTO public.omni_comms_request(organization_id, event_definition_id, mode,
        idempotency_key, request_fingerprint, caller_module_code, payload_snapshot, requested_channels)
      VALUES (v_org, v_event, 'dry_run', repeat('k',16), repeat('a',16), 'MOD', '{}'::jsonb, ARRAY['carrier_pigeon']);
      RAISE EXCEPTION 'FAIL invalid requested channel not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    INSERT INTO public.omni_comms_request(organization_id, event_definition_id, mode,
      idempotency_key, request_fingerprint, caller_module_code, payload_snapshot, requested_channels)
    VALUES (v_org, v_event, 'dry_run', 'idem-key-slice1', repeat('a',16), 'MOD', '{"a":1}'::jsonb, ARRAY['email'])
    RETURNING id INTO v_req;

    BEGIN
      INSERT INTO public.omni_comms_request(organization_id, event_definition_id, mode,
        idempotency_key, request_fingerprint, caller_module_code, payload_snapshot, requested_channels)
      VALUES (v_org, v_event, 'dry_run', 'idem-key-slice1', repeat('a',16), 'MOD', '{"a":2}'::jsonb, ARRAY['email']);
      RAISE EXCEPTION 'FAIL idempotency uniqueness not enforced';
    EXCEPTION WHEN unique_violation THEN NULL; END;

    -- Recipient org mismatch
    BEGIN
      INSERT INTO public.omni_comms_recipient(request_id, organization_id, recipient_type)
      VALUES (v_req, v_other_org, 'user');
      RAISE EXCEPTION 'FAIL recipient org mismatch not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    INSERT INTO public.omni_comms_recipient(request_id, organization_id, recipient_type)
    VALUES (v_req, v_org, 'user') RETURNING id INTO v_rcp;

    -- Message org mismatch and channel validation
    BEGIN
      INSERT INTO public.omni_comms_message(request_id, recipient_id, organization_id, event_definition_id, channel)
      VALUES (v_req, v_rcp, v_other_org, v_event, 'email');
      RAISE EXCEPTION 'FAIL message org mismatch not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    BEGIN
      INSERT INTO public.omni_comms_message(request_id, recipient_id, organization_id, event_definition_id, channel)
      VALUES (v_req, v_rcp, v_org, v_event, 'nope');
      RAISE EXCEPTION 'FAIL message channel not rejected';
    EXCEPTION WHEN check_violation THEN NULL; END;

    INSERT INTO public.omni_comms_message(request_id, recipient_id, organization_id, event_definition_id, channel)
    VALUES (v_req, v_rcp, v_org, v_event, 'email') RETURNING id INTO v_msg;

    -- Checksum format
    BEGIN
      UPDATE public.omni_comms_message SET rendered_checksum='not-a-checksum' WHERE id = v_msg;
      RAISE EXCEPTION 'FAIL checksum format not rejected';
    EXCEPTION WHEN check_violation THEN NULL; END;

    -- Move to rendered and try snapshot mutation
    UPDATE public.omni_comms_message
       SET status='rendered', rendered_at=now(), rendered_html='<p>x</p>',
           rendered_checksum='sha256:'||repeat('a',64)
     WHERE id = v_msg;

    BEGIN
      UPDATE public.omni_comms_message SET rendered_html='<p>tampered</p>' WHERE id = v_msg;
      RAISE EXCEPTION 'FAIL message snapshot mutable';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    -- Dispatch dry-run runnable
    BEGIN
      INSERT INTO public.omni_comms_dispatch_job(request_id, message_id, organization_id, channel, mode, is_runnable)
      VALUES (v_req, v_msg, v_org, 'email', 'dry_run', true);
      RAISE EXCEPTION 'FAIL dry_run runnable not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    INSERT INTO public.omni_comms_dispatch_job(request_id, message_id, organization_id, channel, mode)
    VALUES (v_req, v_msg, v_org, 'email', 'dry_run') RETURNING id INTO v_job;

    BEGIN
      INSERT INTO public.omni_comms_dispatch_job(request_id, message_id, organization_id, channel, mode)
      VALUES (v_req, v_msg, v_org, 'email', 'dry_run');
      RAISE EXCEPTION 'FAIL one-active-job not enforced';
    EXCEPTION WHEN unique_violation THEN NULL; END;

    BEGIN
      UPDATE public.omni_comms_dispatch_job
         SET lock_token='t', locked_at=now(), locked_by='w', lease_expires_at=now() - interval '1 minute'
       WHERE id = v_job;
      RAISE EXCEPTION 'FAIL lease shape not rejected';
    EXCEPTION WHEN check_violation THEN NULL; END;

    -- Delivery attempt uniqueness
    INSERT INTO public.omni_comms_delivery_attempt(dispatch_job_id, message_id, organization_id, attempt_number)
    VALUES (v_job, v_msg, v_org, 1);
    BEGIN
      INSERT INTO public.omni_comms_delivery_attempt(dispatch_job_id, message_id, organization_id, attempt_number)
      VALUES (v_job, v_msg, v_org, 1);
      RAISE EXCEPTION 'FAIL attempt uniqueness not enforced';
    EXCEPTION WHEN unique_violation THEN NULL; END;

    -- Message event sequence and append-only
    INSERT INTO public.omni_comms_message_event(request_id, organization_id, event_type, event_sequence)
    VALUES (v_req, v_org, 'request_accepted', 1);
    BEGIN
      INSERT INTO public.omni_comms_message_event(request_id, organization_id, event_type, event_sequence)
      VALUES (v_req, v_org, 'request_processing', 1);
      RAISE EXCEPTION 'FAIL event sequence not unique';
    EXCEPTION WHEN unique_violation THEN NULL; END;

    BEGIN
      UPDATE public.omni_comms_message_event SET summary='x' WHERE request_id=v_req;
      RAISE EXCEPTION 'FAIL event UPDATE not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    BEGIN
      DELETE FROM public.omni_comms_message_event WHERE request_id=v_req;
      RAISE EXCEPTION 'FAIL event DELETE not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    -- Invalid request transition
    BEGIN
      UPDATE public.omni_comms_request SET status='completed' WHERE id=v_req;
      RAISE EXCEPTION 'FAIL invalid request transition not rejected';
    EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL; END;

    -- Always roll back the fixture work
    RAISE EXCEPTION 'SLICE1_PROBE_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM = 'SLICE1_PROBE_ROLLBACK' THEN
      RETURN 'BUILD 3 SLICE 1 RUNTIME DATABASE VERIFY OK';
    END IF;
    RAISE;
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_sync_legacy_secret_ref(p_account_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_ref text; v_is_resend boolean;
BEGIN
  SELECT (p.adapter_key = 'resend' AND p.channel = 'email')
    INTO v_is_resend
    FROM public.omni_comms_provider_account a
    JOIN public.omni_comms_provider p ON p.id = a.provider_id
   WHERE a.id = p_account_id;

  IF NOT COALESCE(v_is_resend, false) THEN
    UPDATE public.omni_comms_provider_account
       SET secret_ref = NULL
     WHERE id = p_account_id AND secret_ref IS NOT NULL;
    RETURN;
  END IF;

  SELECT s.secret_ref INTO v_ref
    FROM public.omni_comms_provider_account_secret_ref s
   WHERE s.provider_account_id = p_account_id
     AND s.purpose = 'api_key'
     AND public.omni_comms_priv_is_secret_ref_name(s.secret_ref);

  UPDATE public.omni_comms_provider_account
     SET secret_ref = v_ref
   WHERE id = p_account_id AND secret_ref IS DISTINCT FROM v_ref;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_template_version_layout_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_pinned_layout uuid;
BEGIN
  -- Editable only while draft
  IF TG_OP = 'UPDATE' AND OLD.status <> 'draft'
     AND (NEW.layout_selection_mode IS DISTINCT FROM OLD.layout_selection_mode
          OR NEW.layout_id IS DISTINCT FROM OLD.layout_id
          OR NEW.pinned_layout_version_id IS DISTINCT FROM OLD.pinned_layout_version_id) THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='layout_selection_locked_after_draft';
  END IF;
  -- Approval/publication requires selection set
  IF (NEW.status IN ('approved','published')) AND (OLD.status = 'draft' OR TG_OP='INSERT') THEN
    IF NEW.layout_selection_mode IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_selection_required';
    END IF;
    IF NEW.layout_selection_mode = 'pinned' THEN
      IF NEW.pinned_layout_version_id IS NULL OR NEW.layout_id IS NULL THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='pinned_requires_layout_and_version';
      END IF;
      SELECT layout_id INTO v_pinned_layout FROM public.core_template_layout_version WHERE id = NEW.pinned_layout_version_id;
      IF v_pinned_layout IS DISTINCT FROM NEW.layout_id THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='pinned_version_layout_mismatch';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_touch_runtime_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_binding(p_actor_id uuid, p_organization_id uuid, p_department_id uuid, p_channel text, p_sender_identity_id uuid, p_provider_account_id uuid, p_channel_endpoint_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  i public.omni_comms_sender_identity%ROWTYPE;
  a public.omni_comms_provider_account%ROWTYPE;
  e public.omni_comms_channel_endpoint%ROWTYPE;
  v_acct_channel text; v_req text; v_domain text; v_sender_domain text;
BEGIN
  IF p_channel NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_channel'; END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required'; END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(
    p_actor_id, p_organization_id, p_department_id);

  SELECT * INTO i FROM public.omni_comms_sender_identity WHERE id = p_sender_identity_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='sender_identity'; END IF;
  SELECT * INTO a FROM public.omni_comms_provider_account WHERE id = p_provider_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_account'; END IF;
  SELECT p.channel INTO v_acct_channel FROM public.omni_comms_provider p WHERE p.id = a.provider_id;

  IF i.organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='identity_organization_mismatch'; END IF;
  IF a.organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='account_organization_mismatch'; END IF;
  IF i.channel IS DISTINCT FROM p_channel THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='identity_channel_mismatch'; END IF;
  IF v_acct_channel IS DISTINCT FROM p_channel THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='provider_account_channel_mismatch'; END IF;
  IF i.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_identity_not_allowed'; END IF;
  IF a.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_provider_account_not_allowed'; END IF;
  IF i.status = 'retired' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='identity_retired'; END IF;
  IF a.status = 'retired' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='provider_account_retired'; END IF;

  IF p_department_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.core_department d
                    WHERE d.id = p_department_id AND d.organization_id = p_organization_id) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='department_organization_mismatch'; END IF;
  END IF;
  IF i.department_id IS NOT NULL THEN
    IF p_department_id IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='identity_department_scope_required'; END IF;
    IF p_department_id IS DISTINCT FROM i.department_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='identity_department_scope_mismatch'; END IF;
  END IF;

  v_req := public.omni_comms_priv_binding_endpoint_requirement(p_channel);
  IF p_channel_endpoint_id IS NULL THEN
    IF v_req = 'required' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_endpoint_required'; END IF;
    RETURN;
  END IF;
  IF v_req = 'forbidden' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_endpoint_not_supported'; END IF;

  SELECT * INTO e FROM public.omni_comms_channel_endpoint WHERE id = p_channel_endpoint_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='channel_endpoint'; END IF;
  IF e.organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='endpoint_organization_mismatch'; END IF;
  IF e.channel IS DISTINCT FROM p_channel THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_channel_mismatch'; END IF;
  IF e.data_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_endpoint_not_allowed'; END IF;
  IF e.status = 'retired' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_retired'; END IF;
  IF e.department_id IS NOT NULL AND e.department_id IS DISTINCT FROM p_department_id THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_department_scope_mismatch'; END IF;

  IF p_channel = 'email' THEN
    IF e.endpoint_type <> 'sending_domain' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_type_not_allowed'; END IF;
    IF e.provider_account_id IS DISTINCT FROM p_provider_account_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_provider_account_mismatch'; END IF;
    v_domain := lower(btrim(coalesce(e.endpoint_config->>'domain_name','')));
    v_sender_domain := lower(split_part(coalesce(i.identity_config->>'from_address', i.from_address,''),'@',2));
    IF v_domain = '' OR v_sender_domain IS DISTINCT FROM v_domain THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='sender_domain_mismatch'; END IF;
  ELSIF p_channel = 'sms' THEN
    IF e.endpoint_type NOT IN ('delivery_callback','inbound_callback') THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_type_not_allowed'; END IF;
    IF e.provider_account_id IS DISTINCT FROM p_provider_account_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_provider_account_mismatch'; END IF;
  ELSIF p_channel = 'whatsapp' THEN
    IF e.endpoint_type <> 'business_webhook' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_type_not_allowed'; END IF;
    IF e.provider_account_id IS DISTINCT FROM p_provider_account_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_provider_account_mismatch'; END IF;
  ELSIF p_channel = 'in_app' THEN
    IF e.endpoint_type <> 'realtime_endpoint' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_type_not_allowed'; END IF;
    IF e.provider_account_id IS NOT NULL
       AND e.provider_account_id IS DISTINCT FROM p_provider_account_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_provider_account_mismatch'; END IF;
  ELSIF p_channel = 'print' THEN
    IF e.endpoint_type <> 'render_service' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_type_not_allowed'; END IF;
    IF coalesce(e.endpoint_config->>'service_mode','') = 'https' THEN
      IF e.provider_account_id IS DISTINCT FROM p_provider_account_id THEN
        RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_provider_account_mismatch'; END IF;
    ELSIF e.provider_account_id IS NOT NULL
          AND e.provider_account_id IS DISTINCT FROM p_provider_account_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='endpoint_provider_account_mismatch';
    END IF;
  END IF;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_channel(p_channel text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF p_channel IS NULL OR p_channel NOT IN ('email','sms','whatsapp','push','in_app','print') THEN
    RAISE EXCEPTION 'OC422 invalid_channel: %', p_channel USING ERRCODE = 'P0001';
  END IF;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_channel_array(p_channels text[])
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_c text;
BEGIN
  IF p_channels IS NULL OR array_length(p_channels,1) IS NULL THEN
    RAISE EXCEPTION 'OC422 channels_required' USING ERRCODE = 'P0001';
  END IF;
  FOREACH v_c IN ARRAY p_channels LOOP
    PERFORM public.omni_comms_priv_validate_channel(v_c);
  END LOOP;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_channel_content(p_channel text, p_content jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_allowed text[];
  v_required text[];
  v_key text;
  v_val jsonb;
  v_bytes integer;
  v_html text;
  v_text text;
BEGIN
  IF p_content IS NULL OR jsonb_typeof(p_content) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_not_object';
  END IF;
  v_bytes := octet_length(convert_to(p_content::text, 'UTF8'));
  IF v_bytes > 262144 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_too_large';
  END IF;

  CASE p_channel
    WHEN 'email'    THEN v_allowed := ARRAY['subject','html','text','preheader'];
                         v_required := ARRAY['subject'];
    WHEN 'sms'      THEN v_allowed := ARRAY['body'];                v_required := ARRAY['body'];
    WHEN 'in_app'   THEN v_allowed := ARRAY['title','body'];         v_required := ARRAY['title','body'];
    WHEN 'push'     THEN v_allowed := ARRAY['title','body'];         v_required := ARRAY['title','body'];
    WHEN 'whatsapp' THEN v_allowed := ARRAY['body'];                v_required := ARRAY['body'];
    WHEN 'print'    THEN v_allowed := ARRAY['subject','html','text'];v_required := ARRAY['subject'];
    ELSE
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_unknown';
  END CASE;

  -- reject unknown keys
  FOR v_key IN SELECT k FROM jsonb_object_keys(p_content) k LOOP
    IF NOT (v_key = ANY(v_allowed)) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_unknown_key';
    END IF;
    v_val := p_content -> v_key;
    IF v_val IS NULL OR jsonb_typeof(v_val) = 'null' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_null_value';
    END IF;
    IF jsonb_typeof(v_val) <> 'string' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_non_string_value';
    END IF;
    IF btrim(v_val #>> '{}') = '' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_empty_value';
    END IF;
    -- validate token grammar on every string field
    PERFORM public.omni_comms_priv_extract_tokens(v_val #>> '{}');
  END LOOP;

  -- required keys present
  FOR v_key IN SELECT unnest(v_required) LOOP
    IF NOT (p_content ? v_key) THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_missing_required_key';
    END IF;
  END LOOP;

  -- email requires at least one of html/text
  IF p_channel = 'email' THEN
    v_html := p_content ->> 'html';
    v_text := p_content ->> 'text';
    IF COALESCE(btrim(v_html), '') = '' AND COALESCE(btrim(v_text), '') = '' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='content_email_body_required';
    END IF;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_endpoint_account(p_account_id uuid, p_organization_id uuid, p_channel text, p_required boolean, p_require_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_org uuid; v_status text; v_origin text; v_ch text;
BEGIN
  IF p_account_id IS NULL THEN
    IF p_required THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='provider_account_required'; END IF;
    RETURN;
  END IF;
  SELECT a.organization_id, a.status, a.data_origin, p.channel
    INTO v_org, v_status, v_origin, v_ch
    FROM public.omni_comms_provider_account a
    JOIN public.omni_comms_provider p ON p.id = a.provider_id
   WHERE a.id = p_account_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_account'; END IF;
  IF v_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'OC403 permission_denied' USING ERRCODE='P0001', DETAIL='provider_account_organization_mismatch'; END IF;
  IF v_ch IS DISTINCT FROM p_channel THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='provider_account_channel_mismatch'; END IF;
  IF v_origin = 'reference_seed' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='reference_provider_account_not_allowed'; END IF;
  IF v_status = 'retired' THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='provider_account_retired'; END IF;
  IF p_require_active AND v_status <> 'active' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='provider_account_not_active'; END IF;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_schema(p_json_schema jsonb, p_sample_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_schema_bytes int;
  v_sample_bytes int;
  v_type jsonb;
BEGIN
  IF p_json_schema IS NULL OR jsonb_typeof(p_json_schema) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'root_schema_not_object';
  END IF;

  v_schema_bytes := octet_length(convert_to(p_json_schema::text, 'UTF8'));
  IF v_schema_bytes > 262144 THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'schema_too_large';
  END IF;

  IF p_sample_payload IS NOT NULL THEN
    v_sample_bytes := octet_length(convert_to(p_sample_payload::text, 'UTF8'));
    IF v_sample_bytes > 262144 THEN
      RAISE EXCEPTION 'OC422 validation_error'
        USING ERRCODE = 'P0001', DETAIL = 'sample_payload_too_large';
    END IF;
  END IF;

  PERFORM public.omni_comms_priv_reject_nonlocal_refs(p_json_schema);

  IF NOT extensions.jsonschema_is_valid(p_json_schema::text::json) THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'invalid_schema';
  END IF;

  v_type := p_json_schema -> 'type';
  IF v_type IS NULL OR jsonb_typeof(v_type) <> 'string' OR trim(both '"' from v_type::text) <> 'object' THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'root_schema_not_object';
  END IF;

  IF p_sample_payload IS NOT NULL THEN
    IF jsonb_typeof(p_sample_payload) <> 'object' THEN
      RAISE EXCEPTION 'OC422 validation_error'
        USING ERRCODE = 'P0001', DETAIL = 'sample_payload_not_object';
    END IF;
    IF NOT extensions.jsonb_matches_schema(p_json_schema::text::json, p_sample_payload) THEN
      RAISE EXCEPTION 'OC422 validation_error'
        USING ERRCODE = 'P0001', DETAIL = 'sample_payload_invalid';
    END IF;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_validate_timezone(p_tz text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = p_tz);
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_verify_department_ownership(p_department_id uuid, p_organization_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  IF p_department_id IS NULL THEN
    RETURN true;
  END IF;
  SELECT organization_id INTO v_org FROM public.core_department WHERE id = p_department_id;
  IF v_org IS NULL THEN
    RETURN false;
  END IF;
  RETURN v_org IS NOT DISTINCT FROM p_organization_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_webhook_event_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'OC409 webhook_event_immutable' USING ERRCODE='P0001';
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_write_audit(p_actor_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_entity_display text, p_before jsonb, p_after jsonb, p_correlation_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE
  v_actor_name  text;
  v_actor_email text;
  v_changed     text[];
BEGIN
  BEGIN
    SELECT p.full_name, u.email
      INTO v_actor_name, v_actor_email
      FROM public.profiles p
      LEFT JOIN auth.users u ON u.id = p.user_id
      WHERE p.user_id = p_actor_id
      LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_actor_name := NULL;
    v_actor_email := NULL;
  END;

  IF p_before IS NOT NULL AND p_after IS NOT NULL THEN
    SELECT COALESCE(array_agg(k), ARRAY[]::text[])
      INTO v_changed
      FROM (
        SELECT key AS k
          FROM jsonb_each(p_after)
         WHERE p_before -> key IS DISTINCT FROM p_after -> key
      ) diff;
  END IF;

  BEGIN
    INSERT INTO public.core_audit_log (
      event_code, event_name, event_category, severity, risk_level,
      actor_user_id, actor_name, actor_email,
      module_code, domain_code, entity_type, entity_id, entity_display_name,
      action, outcome,
      before_value, after_value, changed_fields,
      correlation_id, source, source_component
    ) VALUES (
      'OMNI_COMMS.' || upper(p_entity_type) || '.' || upper(p_action),
      p_action, 'configuration', 'info', 'low',
      p_actor_id, v_actor_name, v_actor_email,
      'OMNI_COMMS', 'events', p_entity_type, p_entity_id::text, p_entity_display,
      p_action, 'success',
      p_before, p_after, v_changed,
      p_correlation_id, 'rpc', 'omni_comms_event_catalogue'
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'OC450 audit_write_failed'
      USING ERRCODE = 'P0001', DETAIL = SQLERRM;
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_priv_write_channel_audit(p_actor_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_entity_display text, p_before jsonb, p_after jsonb, p_correlation_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_actor_name text; v_actor_email text; v_changed text[];
BEGIN
  BEGIN
    SELECT p.full_name, u.email INTO v_actor_name, v_actor_email
      FROM public.profiles p LEFT JOIN auth.users u ON u.id=p.user_id
      WHERE p.user_id=p_actor_id LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_actor_name:=NULL; v_actor_email:=NULL; END;
  IF p_before IS NOT NULL AND p_after IS NOT NULL THEN
    SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO v_changed
      FROM (SELECT key AS k FROM jsonb_each(p_after)
             WHERE p_before -> key IS DISTINCT FROM p_after -> key) diff;
  END IF;
  BEGIN
    INSERT INTO public.core_audit_log(
      event_code,event_name,event_category,severity,risk_level,
      actor_user_id,actor_name,actor_email,
      module_code,domain_code,entity_type,entity_id,entity_display_name,
      action,outcome,before_value,after_value,changed_fields,
      correlation_id,source,source_component)
    VALUES(
      'OMNI_COMMS.CHANNELS.'||upper(p_entity_type)||'.'||upper(p_action),
      p_action,'configuration','info','low',
      p_actor_id,v_actor_name,v_actor_email,
      'OMNI_COMMS','channels',p_entity_type,p_entity_id::text,p_entity_display,
      p_action,'success',p_before,p_after,v_changed,
      p_correlation_id,'rpc','omni_comms_channel_management');
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'OC450 audit_write_failed' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;
END; $function$;
