CREATE OR REPLACE FUNCTION public.omni_comms_priv_write_template_audit(p_actor_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_entity_display text, p_before jsonb, p_after jsonb, p_reason text, p_notes text, p_correlation_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_actor_name  text;
  v_actor_email text;
  v_changed     text[];
BEGIN
  BEGIN
    SELECT p.full_name, u.email INTO v_actor_name, v_actor_email
      FROM public.profiles p LEFT JOIN auth.users u ON u.id = p.user_id
     WHERE p.user_id = p_actor_id LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_actor_name := NULL; v_actor_email := NULL;
  END;
  IF p_before IS NOT NULL AND p_after IS NOT NULL THEN
    SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO v_changed
      FROM (SELECT key AS k FROM jsonb_each(p_after)
             WHERE p_before -> key IS DISTINCT FROM p_after -> key) d;
  END IF;
  BEGIN
    INSERT INTO public.core_audit_log (
      event_code, event_name, event_category, severity, risk_level,
      actor_user_id, actor_name, actor_email,
      module_code, domain_code, entity_type, entity_id, entity_display_name,
      action, outcome,
      before_value, after_value, changed_fields,
      reason, notes, correlation_id, source, source_component
    ) VALUES (
      'OMNI_COMMS.' || upper(p_entity_type) || '.' || upper(p_action),
      p_action, 'configuration', 'info', 'low',
      p_actor_id, v_actor_name, v_actor_email,
      'OMNI_COMMS', 'templates', p_entity_type, p_entity_id::text, p_entity_display,
      p_action, 'success',
      p_before, p_after, v_changed,
      p_reason, p_notes, p_correlation_id, 'rpc', 'omni_comms_template_catalogue'
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'OC450 audit_write_failed' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_provider_account_activate(p_id uuid, p_expected_updated_at timestamp with time zone, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  RETURN public.omni_comms_priv_channel_account_lifecycle(
    v_uid, p_id, p_expected_updated_at, 'activate', NULL, p_correlation_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_provider_account_record_credential_check(p_id uuid, p_expected_updated_at timestamp with time zone, p_result text, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'extensions'
AS $function$
DECLARE v_uid uuid;
  v_before public.omni_comms_provider_account%ROWTYPE;
  v_after  public.omni_comms_provider_account%ROWTYPE;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_result IS NULL OR p_result NOT IN ('healthy','degraded','failed') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001',DETAIL='invalid_health_result'; END IF;
  SELECT * INTO v_before FROM public.omni_comms_provider_account WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001',DETAIL='provider_account'; END IF;
  PERFORM public.omni_comms_priv_require_tenant_access(v_uid, v_before.organization_id, NULL);
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001',DETAIL='updated_at_mismatch'; END IF;
  UPDATE public.omni_comms_provider_account
     SET health_state=p_result, health_checked_at=now(), updated_by=v_uid, updated_at=now()
   WHERE id=p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_channel_audit(
    v_uid,'credential_check','provider_account',p_id,v_after.code,to_jsonb(v_before),to_jsonb(v_after),p_correlation_id);
  RETURN p_id;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_provider_account_upsert_draft(p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_code text, p_display_name text, p_secret_ref text, p_region text DEFAULT NULL::text, p_sandbox_mode boolean DEFAULT false, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_pid uuid; v_org uuid; v_ref text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_pid := public.omni_comms_priv_email_provider_id();
  IF v_pid IS NULL THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='email_provider_missing'; END IF;
  v_org := p_organization_id;
  IF p_id IS NOT NULL THEN
    SELECT organization_id, provider_account_reference INTO v_org, v_ref
      FROM public.omni_comms_provider_account WHERE id=p_id;
    IF v_org IS NULL THEN
      RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='provider_account'; END IF;
  END IF;
  RETURN public.omni_comms_priv_channel_account_upsert(
    v_uid, p_id, p_expected_updated_at, v_org, 'email', v_pid,
    p_code, p_display_name,
    CASE WHEN COALESCE(p_sandbox_mode,false) THEN 'sandbox' ELSE 'production' END,
    p_region, v_ref,
    jsonb_build_array(jsonb_build_object('purpose','api_key','secret_ref',btrim(COALESCE(p_secret_ref,'')))),
    false, p_correlation_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_reference_seed_apply(p_organization_id uuid, p_confirm_non_production boolean, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  IF p_confirm_non_production IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'OC400 confirmation_required'
      USING ERRCODE = 'P0001', DETAIL = 'non_production_confirmation_required';
  END IF;
  PERFORM public.omni_comms_priv_reference_seed_assert_safe(p_organization_id);
  RETURN public.omni_comms_priv_reference_seed_run_v2(v_uid, p_organization_id, 'apply', p_correlation_id);
END;
