CREATE OR REPLACE FUNCTION public.omni_comms_reference_seed_status(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  c                jsonb := public.omni_comms_priv_reference_seed_catalogue_v2();
  v_uid            uuid;
  v_dry            jsonb;
  v_codes          text[];
  v_family_codes   text[];
  v_sender_codes   text[];
  v_account_codes  text[];
  v_provider_codes text[];
  v_exp_events     integer;
  v_exp_channels   integer;
  v_providers      integer;
  v_accounts       integer;
  v_senders        integer;
  v_bindings       integer;
  v_chan_settings  integer;
  v_events         integer;
  v_contracts      integer;
  v_families       integer;
  v_versions       integer;
  v_layouts_ok     integer;
  v_routes         integer;
  v_unresolved     integer;
  v_conflicts      integer;
  v_live_channels  integer;
  v_live_requests  integer;
  v_ref_requests   integer;
  v_ref_completed  integer;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');

  IF NOT EXISTS (SELECT 1 FROM public.core_organization WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE = 'P0001', DETAIL = 'organization_not_found';
  END IF;

  SELECT array_agg(e ->> 'code'), count(*)::int
    INTO v_codes, v_exp_events
    FROM jsonb_array_elements(c -> 'events') e;

  SELECT count(*)::int INTO v_exp_channels
    FROM jsonb_array_elements(c -> 'events') e,
         jsonb_array_elements(e -> 'channels') ch;

  SELECT array_agg(e ->> 'family_code') INTO v_family_codes FROM jsonb_array_elements(c -> 'events') e;
  SELECT array_agg(s ->> 'code')        INTO v_sender_codes FROM jsonb_array_elements(c -> 'senders') s;
  SELECT array_agg(a ->> 'code')        INTO v_account_codes FROM jsonb_array_elements(c -> 'accounts') a;
  SELECT array_agg(p ->> 'code')        INTO v_provider_codes FROM jsonb_array_elements(c -> 'providers') p;

  SELECT count(*)::int INTO v_providers
    FROM public.omni_comms_provider WHERE code = ANY(v_provider_codes) AND status = 'active';

  SELECT count(*)::int INTO v_accounts
    FROM public.omni_comms_provider_account
   WHERE organization_id = p_organization_id AND code = ANY(v_account_codes)
     AND status = 'active' AND sandbox_mode = true;

  SELECT count(*)::int INTO v_senders
    FROM public.omni_comms_sender_identity
   WHERE organization_id = p_organization_id AND code = ANY(v_sender_codes) AND status = 'active';

  SELECT count(*)::int INTO v_bindings
    FROM public.omni_comms_sender_provider_binding b
    JOIN public.omni_comms_sender_identity s ON s.id = b.sender_identity_id
   WHERE s.organization_id = p_organization_id AND s.code = ANY(v_sender_codes) AND b.status = 'active';

  SELECT count(*)::int INTO v_chan_settings
    FROM public.omni_comms_channel_setting
   WHERE organization_id = p_organization_id AND department_id IS NULL;

  SELECT count(*)::int INTO v_events
    FROM public.omni_comms_event_definition WHERE code = ANY(v_codes) AND status = 'active';

  SELECT count(*)::int INTO v_contracts
    FROM public.omni_comms_event_contract ct
    JOIN public.omni_comms_event_definition d ON d.id = ct.event_definition_id
   WHERE d.code = ANY(v_codes) AND ct.status = 'published';

  SELECT count(*)::int INTO v_families
    FROM public.omni_comms_template_family
   WHERE code = ANY(v_family_codes) AND organization_id = p_organization_id AND status = 'active';

  SELECT count(*)::int INTO v_versions
    FROM public.omni_comms_template_version tv
    JOIN public.omni_comms_template_family f ON f.id = tv.template_family_id
   WHERE f.code = ANY(v_family_codes) AND f.organization_id = p_organization_id
     AND tv.status = 'published';

  SELECT count(*)::int INTO v_layouts_ok
    FROM public.omni_comms_template_version tv
    JOIN public.omni_comms_template_family f ON f.id = tv.template_family_id
   WHERE f.code = ANY(v_family_codes) AND f.organization_id = p_organization_id
     AND tv.status = 'published'
     AND public.omni_comms_priv_layout_selection_valid(
           tv.layout_selection_mode, tv.layout_id, tv.pinned_layout_version_id, tv.channel);

  SELECT COALESCE(count(*), 0)::int INTO v_unresolved
    FROM public.omni_comms_template_version tv
    JOIN public.omni_comms_template_family f ON f.id = tv.template_family_id
    JOIN public.core_template_layout_version lv ON lv.id = tv.pinned_layout_version_id
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(lv.slots, '[]'::jsonb)) slot
   WHERE f.code = ANY(v_family_codes) AND f.organization_id = p_organization_id
     AND tv.status = 'published'
     AND COALESCE((slot ->> 'required')::boolean, false) = true
     AND (slot ->> 'code') !~ '^content(_|$)';

  SELECT count(*)::int INTO v_routes
    FROM public.omni_comms_event_route r
    JOIN public.omni_comms_event_definition d ON d.id = r.event_definition_id
   WHERE r.organization_id = p_organization_id AND d.code = ANY(v_codes)
     AND r.lifecycle_state = 'active' AND r.is_enabled = true;

  SELECT count(*)::int INTO v_live_channels
    FROM public.omni_comms_channel_setting
   WHERE organization_id = p_organization_id AND live_delivery_enabled;

  SELECT count(*)::int INTO v_live_requests
    FROM public.omni_comms_request
   WHERE organization_id = p_organization_id AND mode IS DISTINCT FROM 'dry_run';

  SELECT count(*)::int,
         count(*) FILTER (WHERE rq.status = 'completed')::int
    INTO v_ref_requests, v_ref_completed
    FROM public.omni_comms_request rq
    JOIN public.omni_comms_event_definition d ON d.id = rq.event_definition_id
   WHERE rq.organization_id = p_organization_id
     AND rq.mode = 'dry_run'
     AND d.code = ANY(v_codes);

  SELECT COALESCE(sum(x), 0)::int INTO v_conflicts FROM (
    SELECT count(*)::int AS x FROM public.omni_comms_template_family
      WHERE code = ANY(v_family_codes) AND organization_id IS DISTINCT FROM p_organization_id
    UNION ALL
    SELECT count(*)::int FROM public.omni_comms_channel_setting
      WHERE organization_id = p_organization_id AND live_delivery_enabled
    UNION ALL
    SELECT count(*)::int FROM public.omni_comms_provider_account
      WHERE organization_id = p_organization_id AND code = ANY(v_account_codes)
        AND COALESCE(sandbox_mode, false) = false
    UNION ALL
    SELECT count(*)::int FROM public.omni_comms_event_contract ct
      JOIN public.omni_comms_event_definition d ON d.id = ct.event_definition_id
      WHERE d.code = ANY(v_codes) AND ct.version_number = 1 AND ct.status <> 'published'
  ) q;

  v_dry := jsonb_build_object(
    'reference_dry_run_requests', v_ref_requests,
    'completed_reference_dry_runs', v_ref_completed
  );

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'catalogue_version', (c ->> 'catalogue_version')::int,
    'expected_events', v_exp_events,
    'present_events', v_events,
    'expected_channel_bindings', v_exp_channels,
    'present_routes', v_routes,
    'present_published_versions', v_versions,
    'expected_senders', (SELECT count(*)::int FROM jsonb_array_elements(c -> 'senders')),
    'present_senders', v_senders,
    'expected_accounts', (SELECT count(*)::int FROM jsonb_array_elements(c -> 'accounts')),
    'present_accounts', v_accounts,
    'expected_providers', (SELECT count(*)::int FROM jsonb_array_elements(c -> 'providers')),
    'present_providers', v_providers,
    'expected_bindings', (SELECT count(*)::int FROM jsonb_array_elements(c -> 'senders')),
    'present_bindings', v_bindings,
    'expected_channel_settings', (SELECT count(*)::int FROM jsonb_array_elements(c -> 'channel_settings')),
    'present_channel_settings', v_chan_settings,
    'expected_contracts', v_exp_events,
    'present_published_contracts', v_contracts,
    'expected_families', v_exp_events,
    'present_families', v_families,
    'valid_layout_selections', v_layouts_ok,
    'unresolved_required_assets', v_unresolved,
    'conflicts', v_conflicts,
    'seeded', (v_events >= v_exp_events AND v_routes >= v_exp_channels),
    'catalogue_complete', (
      v_events >= v_exp_events
      AND v_contracts >= v_exp_events
      AND v_families >= v_exp_events
      AND v_versions >= v_exp_channels
      AND v_layouts_ok >= v_exp_channels
      AND v_routes >= v_exp_channels
      AND v_senders >= (SELECT count(*)::int FROM jsonb_array_elements(c -> 'senders'))
      AND v_bindings >= (SELECT count(*)::int FROM jsonb_array_elements(c -> 'senders'))
      AND v_accounts >= (SELECT count(*)::int FROM jsonb_array_elements(c -> 'accounts'))
      AND v_providers >= (SELECT count(*)::int FROM jsonb_array_elements(c -> 'providers'))
      AND v_chan_settings >= (SELECT count(*)::int FROM jsonb_array_elements(c -> 'channel_settings'))
      AND v_unresolved = 0
      AND v_conflicts = 0
      AND v_live_channels = 0
    ),
    'live_delivery_enabled_channels', v_live_channels,
    'live_requests', v_live_requests,
    'reference_dry_run_requests', v_ref_requests,
    'completed_reference_dry_runs', v_ref_completed,
    'reference_configuration_ready', (
      v_events >= v_exp_events AND v_contracts >= v_exp_events
      AND v_routes >= v_exp_channels AND v_conflicts = 0 AND v_unresolved = 0),
    'controlled_dry_run_ready', (
      v_routes >= 1 AND v_versions >= 1 AND v_layouts_ok >= 1 AND v_live_channels = 0),
    'controlled_dry_run_verified', (v_ref_completed > 0),
    'live_send_ready', false,
    'safe_to_seed', (v_live_channels = 0 AND v_live_requests = 0),
    'checked_at', now()
  ) || v_dry;
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_resolve_render_manifest(p_template_version_id uuid, p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_tv public.omni_comms_template_version;
  v_fam public.omni_comms_template_family;
  v_layout_id uuid; v_layout_version_id uuid; v_layout_source text;
  v_slots jsonb; v_slot jsonb; v_slot_code text;
  v_resolved jsonb := '[]'::jsonb;
  v_asset public.core_comm_asset;
  v_av public.core_comm_asset_version;
  v_asset_id uuid; v_inh text;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  SELECT * INTO v_tv FROM public.omni_comms_template_version WHERE id = p_template_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='version_not_found'; END IF;
  SELECT * INTO v_fam FROM public.omni_comms_template_family WHERE id = v_tv.template_family_id;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.core_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  -- layout resolution
  IF v_tv.layout_selection_mode = 'pinned' THEN
    v_layout_id := v_tv.layout_id;
    v_layout_version_id := v_tv.pinned_layout_version_id;
    v_layout_source := 'pinned';
  ELSE
    -- department override → organisation default
    SELECT layout_id INTO v_layout_id FROM public.core_comm_assignment
      WHERE organization_id = p_organization_id AND department_id = p_department_id
        AND output_channel = v_tv.channel AND assignment_kind = 'layout_default';
    IF v_layout_id IS NOT NULL THEN
      v_layout_source := 'department';
    ELSE
      SELECT layout_id INTO v_layout_id FROM public.core_comm_assignment
        WHERE organization_id = p_organization_id AND department_id IS NULL
          AND output_channel = v_tv.channel AND assignment_kind = 'layout_default';
      IF v_layout_id IS NOT NULL THEN v_layout_source := 'organization'; END IF;
    END IF;
    IF v_layout_id IS NOT NULL THEN
      SELECT id INTO v_layout_version_id FROM public.core_template_layout_version
        WHERE layout_id = v_layout_id AND status='published'
        ORDER BY version_number DESC LIMIT 1;
    END IF;
  END IF;

  -- slot resolution
  IF v_layout_version_id IS NOT NULL THEN
    SELECT slots INTO v_slots FROM public.core_template_layout_version WHERE id = v_layout_version_id;
    FOR v_slot IN SELECT * FROM jsonb_array_elements(v_slots) LOOP
      v_slot_code := v_slot->>'code';
      IF v_slot_code = 'content_body' THEN CONTINUE; END IF;
      v_asset_id := NULL; v_inh := NULL;
      IF p_department_id IS NOT NULL THEN
        SELECT asset_id INTO v_asset_id FROM public.core_comm_assignment
          WHERE organization_id=p_organization_id AND department_id=p_department_id
            AND output_channel=v_tv.channel AND assignment_kind='asset_slot' AND slot_code=v_slot_code;
        IF v_asset_id IS NOT NULL THEN v_inh := 'department'; END IF;
      END IF;
      IF v_asset_id IS NULL THEN
        SELECT asset_id INTO v_asset_id FROM public.core_comm_assignment
          WHERE organization_id=p_organization_id AND department_id IS NULL
            AND output_channel=v_tv.channel AND assignment_kind='asset_slot' AND slot_code=v_slot_code;
        IF v_asset_id IS NOT NULL THEN v_inh := 'organization'; END IF;
      END IF;
      IF v_asset_id IS NOT NULL THEN
        SELECT * INTO v_asset FROM public.core_comm_asset WHERE id = v_asset_id;
        SELECT * INTO v_av FROM public.core_comm_asset_version WHERE id = v_asset.active_version_id;
        v_resolved := v_resolved || jsonb_build_object(
          'slot', v_slot_code, 'asset_id', v_asset.id,
          'asset_version_id', v_av.id, 'asset_type', v_asset.asset_type,
          'inheritance_source', v_inh,
          'content_html', v_av.content_html, 'content_text', v_av.content_text,
          'checksum', v_av.checksum
        );
      ELSE
        v_resolved := v_resolved || jsonb_build_object(
          'slot', v_slot_code, 'asset_id', null, 'asset_version_id', null,
          'asset_type', null, 'inheritance_source', 'unresolved'
        );
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'template_family_id', v_tv.template_family_id,
    'template_version_id', v_tv.id,
    'template_content', v_tv.content,
    'template_channel', v_tv.channel,
    'template_locale', v_tv.locale,
    'layout_id', v_layout_id,
    'layout_version_id', v_layout_version_id,
    'layout_inheritance_source', v_layout_source,
    'layout_slots', v_slots,
    'resolved_assets', v_resolved
  );
END;$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_sender_identity_activate(p_id uuid, p_expected_updated_at timestamp with time zone, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  RETURN public.omni_comms_priv_channel_identity_lifecycle(
    v_uid, p_id, p_expected_updated_at, 'activate', NULL, p_correlation_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_sender_identity_upsert_draft(p_id uuid, p_expected_updated_at timestamp with time zone, p_organization_id uuid, p_department_id uuid, p_event_definition_id uuid, p_code text, p_display_name text, p_from_address text, p_from_name text, p_reply_to_address text, p_correlation_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_uid uuid; v_org uuid; v_dept uuid; v_res uuid; v_evt uuid;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_org := p_organization_id; v_dept := p_department_id; v_evt := p_event_definition_id;
  IF p_id IS NOT NULL THEN
    SELECT organization_id, event_definition_id INTO v_org, v_evt
      FROM public.omni_comms_sender_identity WHERE id=p_id;
    IF v_org IS NULL THEN
      RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='sender_identity'; END IF;
  END IF;

  v_res := public.omni_comms_priv_channel_identity_upsert(
    v_uid, p_id, p_expected_updated_at, v_org, v_dept, 'email',
    p_code, p_display_name, 'email_sender',
    jsonb_strip_nulls(jsonb_build_object(
      'from_address', NULLIF(btrim(coalesce(p_from_address,'')),''),
      'from_name', NULLIF(btrim(coalesce(p_from_name,'')),''),
      'reply_to_address', NULLIF(btrim(coalesce(p_reply_to_address,'')),''))),
    p_correlation_id);

  UPDATE public.omni_comms_sender_identity
     SET event_definition_id = v_evt
   WHERE id = v_res AND event_definition_id IS DISTINCT FROM v_evt;

  RETURN v_res;
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_set_producer_event_binding_status(p_id uuid, p_target_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor  uuid;
  v_row    public.omni_comms_producer_event_binding%ROWTYPE;
  v_target text;
  v_before jsonb;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');
  v_target := lower(btrim(coalesce(p_target_status, '')));

  IF v_target NOT IN ('active', 'suspended', 'retired') THEN
    RAISE EXCEPTION 'OC400 invalid_target_status'
      USING ERRCODE = 'P0001', DETAIL = 'invalid_target_status';
  END IF;

  v_row := public.omni_comms_priv_peb_load(p_id);

  IF v_row.department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(v_row.department_id, v_row.organization_id);
  END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_row.organization_id, v_row.department_id);

  IF v_row.status = 'retired' THEN
    RAISE EXCEPTION 'OC409 producer_binding_retired'
      USING ERRCODE = 'P0001', DETAIL = 'producer_binding_retired';
  END IF;

  IF v_target IN ('suspended', 'retired')
     AND nullif(btrim(coalesce(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'OC400 lifecycle_reason_required'
      USING ERRCODE = 'P0001', DETAIL = 'lifecycle_reason_required';
  END IF;

  IF v_target = 'active' AND v_row.status NOT IN ('draft', 'suspended') THEN
    RAISE EXCEPTION 'OC409 invalid_transition'
      USING ERRCODE = 'P0001', DETAIL = 'invalid_transition';
  END IF;

  IF v_target = 'active' AND NOT EXISTS (
    SELECT 1 FROM public.omni_comms_event_definition
    WHERE id = v_row.event_definition_id AND status = 'active'
  ) THEN
    RAISE EXCEPTION 'OC409 event_not_active'
      USING ERRCODE = 'P0001', DETAIL = 'event_not_active';
  END IF;

  v_before := jsonb_build_object('status', v_row.status);

  UPDATE public.omni_comms_producer_event_binding
     SET status = v_target,
         lifecycle_reason = CASE WHEN v_target = 'active' THEN NULL
                                 ELSE nullif(btrim(coalesce(p_reason, '')), '') END,
         activated_at = CASE WHEN v_target = 'active' THEN now() ELSE activated_at END,
         activated_by = CASE WHEN v_target = 'active' THEN v_actor ELSE activated_by END,
         suspended_at = CASE WHEN v_target = 'suspended' THEN now() ELSE suspended_at END,
         suspended_by = CASE WHEN v_target = 'suspended' THEN v_actor ELSE suspended_by END,
         retired_at   = CASE WHEN v_target = 'retired' THEN now() ELSE retired_at END,
         retired_by   = CASE WHEN v_target = 'retired' THEN v_actor ELSE retired_by END,
         updated_by   = v_actor
   WHERE id = p_id
   RETURNING * INTO v_row;

  PERFORM public.omni_comms_priv_write_audit(
    v_actor, v_target, 'producer_event_binding', v_row.id,
    v_row.caller_module_code, v_before,
    jsonb_build_object('status', v_row.status), NULL
  );

  RETURN jsonb_build_object('id', v_row.id, 'status', v_row.status);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_setup_readiness(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_event_definition_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'email'::text, p_locale text DEFAULT 'en'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_sensitive boolean := false;
  v_channel text;
  v_locale text;
  v_ed public.omni_comms_event_definition;
  v_ct public.omni_comms_event_contract;
  v_rt public.omni_comms_event_route;
  v_route_source text := 'unresolved';
  v_fam public.omni_comms_template_family;
  v_tv public.omni_comms_template_version;
  v_manifest jsonb;
  v_layout_version public.core_template_layout_version;
  v_layout_code text;
  v_prov public.omni_comms_provider;
  v_acct public.omni_comms_provider_account;
  v_sender public.omni_comms_sender_identity;
  v_bind public.omni_comms_sender_provider_binding;
  v_cs public.omni_comms_channel_setting;
  v_required_fields text[] := ARRAY[]::text[];
  v_slots jsonb := '[]'::jsonb;
  v_unresolved_required int := 0;
  v_assets jsonb := '[]'::jsonb;
  v_caps jsonb := '{}'::jsonb;
  v_action text;
  v_blockers jsonb := '[]'::jsonb;
  v_runtime_tables jsonb := '{}'::jsonb;
  v_runtime_functions jsonb := '{}'::jsonb;
  v_name text;
  v_runtime_ready boolean;
  v_dry_run_ready boolean;
  v_from_masked text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('view');

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  v_channel := lower(coalesce(nullif(btrim(p_channel), ''), 'email'));
  IF v_channel <> 'email' THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'unsupported_channel';
  END IF;

  v_locale := coalesce(nullif(btrim(p_locale), ''), 'en');
  IF length(v_locale) > 10 OR v_locale !~ '^[A-Za-z]{2}([-_][A-Za-z]{2})?$' THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'invalid_locale';
  END IF;

  v_sensitive := public.has_permission(v_uid, 'omni_comms', 'view_sensitive_content');

  FOREACH v_action IN ARRAY ARRAY[
    'view','operate','configure','author_templates','approve_templates','view_sensitive_content'
  ] LOOP
    v_caps := v_caps || jsonb_build_object(
      'omni_comms.' || v_action,
      CASE WHEN public.has_permission(v_uid, 'omni_comms', v_action)
           THEN 'granted' ELSE 'not_granted' END);
  END LOOP;

  IF p_event_definition_id IS NOT NULL THEN
    SELECT * INTO v_ed FROM public.omni_comms_event_definition
     WHERE id = p_event_definition_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OC404 not_found'
        USING ERRCODE = 'P0001', DETAIL = 'event_definition_not_found';
    END IF;

    SELECT * INTO v_ct FROM public.omni_comms_event_contract
     WHERE event_definition_id = v_ed.id AND status = 'published'
     ORDER BY version_number DESC LIMIT 1;

    IF v_ct.id IS NOT NULL AND jsonb_typeof(v_ct.json_schema -> 'required') = 'array' THEN
      SELECT coalesce(array_agg(s.x ORDER BY s.x), ARRAY[]::text[]) INTO v_required_fields
        FROM (SELECT jsonb_array_elements_text(v_ct.json_schema -> 'required') AS x
               LIMIT 50) s;
    END IF;

    IF p_department_id IS NOT NULL THEN
      SELECT * INTO v_rt FROM public.omni_comms_event_route
       WHERE organization_id = p_organization_id
         AND department_id = p_department_id
         AND event_definition_id = v_ed.id
         AND channel = v_channel
       ORDER BY priority ASC, updated_at DESC LIMIT 1;
      IF v_rt.id IS NOT NULL THEN v_route_source := 'department'; END IF;
    END IF;
    IF v_rt.id IS NULL THEN
      SELECT * INTO v_rt FROM public.omni_comms_event_route
       WHERE organization_id = p_organization_id
         AND department_id IS NULL
         AND event_definition_id = v_ed.id
         AND channel = v_channel
       ORDER BY priority ASC, updated_at DESC LIMIT 1;
      IF v_rt.id IS NOT NULL THEN v_route_source := 'organization'; END IF;
    END IF;

    IF v_rt.template_family_id IS NOT NULL THEN
      SELECT * INTO v_fam FROM public.omni_comms_template_family
       WHERE id = v_rt.template_family_id;
    END IF;

    IF v_fam.id IS NOT NULL THEN
      SELECT * INTO v_tv FROM public.omni_comms_template_version
       WHERE template_family_id = v_fam.id
         AND status = 'published'
         AND channel = v_channel
         AND lower(locale) = lower(v_locale)
       ORDER BY version_number DESC LIMIT 1;
    END IF;
  END IF;

  IF v_tv.id IS NOT NULL THEN
    v_manifest := public.omni_comms_resolve_render_manifest(
      v_tv.id, p_organization_id, p_department_id);

    v_slots := coalesce(v_manifest -> 'layout_slots', '[]'::jsonb);

    IF (v_manifest ->> 'layout_version_id') IS NOT NULL THEN
      SELECT * INTO v_layout_version FROM public.core_template_layout_version
       WHERE id = (v_manifest ->> 'layout_version_id')::uuid;
      SELECT code INTO v_layout_code FROM public.core_template_layout
       WHERE id = (v_manifest ->> 'layout_id')::uuid;
    END IF;

    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'slot_code', e ->> 'slot',
             'asset_id', e -> 'asset_id',
             'asset_version_id', e -> 'asset_version_id',
             'asset_type', e -> 'asset_type',
             'checksum', e -> 'checksum',
             'inheritance_source', e ->> 'inheritance_source',
             'state', CASE WHEN (e ->> 'asset_version_id') IS NULL
                           THEN 'unresolved' ELSE 'resolved' END
           ) ORDER BY e ->> 'slot'), '[]'::jsonb)
      INTO v_assets
      FROM jsonb_array_elements(coalesce(v_manifest -> 'resolved_assets', '[]'::jsonb)) e;

    SELECT count(*) INTO v_unresolved_required
      FROM jsonb_array_elements(v_assets) a
      JOIN jsonb_array_elements(v_slots) s
        ON s ->> 'code' = a ->> 'slot_code'
     WHERE a ->> 'state' = 'unresolved'
       AND coalesce((s ->> 'required')::boolean, false) IS TRUE;
  END IF;

  SELECT * INTO v_prov FROM public.omni_comms_provider
   WHERE channel = v_channel AND status = 'active'
   ORDER BY updated_at DESC LIMIT 1;
  IF v_prov.id IS NULL THEN
    SELECT * INTO v_prov FROM public.omni_comms_provider
     WHERE channel = v_channel ORDER BY updated_at DESC LIMIT 1;
  END IF;

  IF v_prov.id IS NOT NULL THEN
    SELECT * INTO v_acct FROM public.omni_comms_provider_account
     WHERE organization_id = p_organization_id
       AND provider_id = v_prov.id
       AND status = 'active'
     ORDER BY updated_at DESC LIMIT 1;
    IF v_acct.id IS NULL THEN
      SELECT * INTO v_acct FROM public.omni_comms_provider_account
       WHERE organization_id = p_organization_id AND provider_id = v_prov.id
       ORDER BY updated_at DESC LIMIT 1;
    END IF;
  END IF;

  IF v_rt.sender_identity_id IS NOT NULL THEN
    SELECT * INTO v_sender FROM public.omni_comms_sender_identity
     WHERE id = v_rt.sender_identity_id;
  END IF;
  IF v_sender.id IS NULL AND v_ed.id IS NOT NULL THEN
    SELECT * INTO v_sender FROM public.omni_comms_sender_identity
     WHERE organization_id = p_organization_id AND channel = v_channel
       AND event_definition_id = v_ed.id AND status = 'active'
     ORDER BY updated_at DESC LIMIT 1;
  END IF;
  IF v_sender.id IS NULL AND p_department_id IS NOT NULL THEN
    SELECT * INTO v_sender FROM public.omni_comms_sender_identity
     WHERE organization_id = p_organization_id AND channel = v_channel
       AND department_id = p_department_id AND event_definition_id IS NULL
       AND status = 'active'
     ORDER BY updated_at DESC LIMIT 1;
  END IF;
  IF v_sender.id IS NULL THEN
    SELECT * INTO v_sender FROM public.omni_comms_sender_identity
     WHERE organization_id = p_organization_id AND channel = v_channel
       AND department_id IS NULL AND event_definition_id IS NULL
       AND status = 'active'
     ORDER BY updated_at DESC LIMIT 1;
  END IF;

  -- Sender-first provider precedence: the account/provider reported by
  -- readiness MUST be the one bound to the resolved sender identity, not the
  -- most recently updated global account.
  IF v_sender.id IS NOT NULL THEN
    SELECT * INTO v_bind FROM public.omni_comms_sender_provider_binding
     WHERE sender_identity_id = v_sender.id
     ORDER BY (status = 'active') DESC,
              (verification_status = 'verified') DESC,
              priority ASC,
              updated_at DESC
     LIMIT 1;
  END IF;

  IF v_bind.id IS NOT NULL THEN
    SELECT * INTO v_acct
      FROM public.omni_comms_provider_account
     WHERE id = v_bind.provider_account_id;

    IF v_acct.id IS NOT NULL THEN
      SELECT * INTO v_prov
        FROM public.omni_comms_provider
       WHERE id = v_acct.provider_id;
    END IF;
  END IF;

  IF p_department_id IS NOT NULL THEN
    SELECT * INTO v_cs FROM public.omni_comms_channel_setting
     WHERE organization_id = p_organization_id
       AND department_id = p_department_id AND channel = v_channel LIMIT 1;
  END IF;
  IF v_cs.id IS NULL THEN
    SELECT * INTO v_cs FROM public.omni_comms_channel_setting
     WHERE organization_id = p_organization_id
       AND department_id IS NULL AND channel = v_channel LIMIT 1;
  END IF;

  IF v_sender.from_address IS NOT NULL THEN
    v_from_masked := CASE
      WHEN v_sensitive THEN v_sender.from_address
      WHEN position('@' IN v_sender.from_address) > 1 THEN
        left(v_sender.from_address, 1) || '***' ||
        substring(v_sender.from_address FROM position('@' IN v_sender.from_address))
      ELSE '***'
    END;
  END IF;

  FOREACH v_name IN ARRAY ARRAY[
    'omni_comms_request','omni_comms_recipient','omni_comms_message',
    'omni_comms_dispatch_job','omni_comms_delivery_attempt','omni_comms_message_event'
  ] LOOP
    v_runtime_tables := v_runtime_tables || jsonb_build_object(
      v_name, to_regclass('public.' || v_name) IS NOT NULL);
  END LOOP;

  FOREACH v_name IN ARRAY ARRAY[
    'omni_comms_priv_send_communication',
    'omni_comms_priv_runtime_resolution_snapshot',
    'omni_comms_priv_finalize_resolution',
    'omni_comms_priv_load_render_context',
    'omni_comms_priv_persist_rendered_messages',
    'omni_comms_priv_authorize_runtime_actor',
    'omni_comms_priv_load_persisted_messages'
  ] LOOP
    v_runtime_functions := v_runtime_functions || jsonb_build_object(
      v_name,
      EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
               WHERE n.nspname = 'public' AND p.proname = v_name));
  END LOOP;

  SELECT bool_and(value::boolean) INTO v_runtime_ready
    FROM jsonb_each_text(v_runtime_tables || v_runtime_functions);

  IF p_event_definition_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','event_not_selected','step','event','severity','blocker',
      'message','Select a pilot event definition.');
  ELSIF v_ed.status <> 'active' THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','event_not_active','step','event','severity','blocker',
      'message','The selected event definition is not active.');
  END IF;

  IF p_event_definition_id IS NOT NULL AND v_ct.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','contract_not_published','step','contract','severity','blocker',
      'message','Publish an event contract version for this event.');
  END IF;

  IF p_event_definition_id IS NOT NULL AND v_rt.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','route_missing','step','route','severity','blocker',
      'message','Create an email event route for this event.');
  ELSIF v_rt.id IS NOT NULL AND (v_rt.lifecycle_state <> 'active' OR v_rt.is_enabled IS NOT TRUE) THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','route_not_active','step','route','severity','blocker',
      'message','Activate and enable the email event route.');
  END IF;

  IF v_rt.id IS NOT NULL AND v_fam.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','template_family_missing','step','template_family','severity','blocker',
      'message','Attach an active template family to the route.');
  ELSIF v_fam.id IS NOT NULL AND v_fam.status <> 'active' THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','template_family_not_active','step','template_family','severity','blocker',
      'message','Activate the template family bound to the route.');
  END IF;

  IF v_fam.id IS NOT NULL AND v_tv.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','template_version_not_published','step','template_version','severity','blocker',
      'message','Publish an email template version for the selected locale.');
  END IF;

  IF v_tv.id IS NOT NULL AND (v_manifest ->> 'layout_version_id') IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','layout_unresolved','step','layout','severity','blocker',
      'message','No published layout version resolves for this template.');
  END IF;

  IF v_unresolved_required > 0 THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','required_assets_unresolved','step','assets','severity','blocker',
      'message','Required layout slots have no resolved active asset.');
  END IF;

  IF v_prov.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','provider_not_registered','step','provider','severity','blocker',
      'message','No email provider is registered.');
  ELSIF v_prov.status <> 'active' THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','provider_not_active','step','provider','severity','blocker',
      'message','The email provider is registered but not active.');
  END IF;

  IF v_acct.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','provider_account_missing','step','provider_account','severity','blocker',
      'message','Create a provider account for this organisation.');
  ELSE
    IF v_acct.status <> 'active' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','provider_account_not_active','step','provider_account','severity','blocker',
        'message','Activate the provider account.');
    END IF;
    IF v_acct.health_checked_at IS NULL THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','provider_account_health_unknown','step','provider_account','severity','warning',
        'message','No credential health check has been recorded for this account.');
    ELSIF v_acct.health_state <> 'healthy' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','provider_account_unhealthy','step','provider_account','severity','warning',
        'message','The last recorded credential health check was not healthy.');
    END IF;
  END IF;

  IF v_sender.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','sender_missing','step','sender','severity','blocker',
      'message','Create an email sender identity in scope.');
  ELSIF v_sender.status <> 'active' THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','sender_not_active','step','sender','severity','blocker',
      'message','Activate the resolved sender identity.');
  END IF;

  IF v_sender.id IS NOT NULL AND v_bind.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','binding_missing','step','binding','severity','blocker',
      'message','Bind the sender identity to the provider account.');
  ELSIF v_bind.id IS NOT NULL THEN
    IF v_bind.status <> 'active' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','binding_not_active','step','binding','severity','blocker',
        'message','Activate the sender-to-provider binding.');
    END IF;
    IF v_bind.verification_status <> 'verified' THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','binding_not_verified','step','binding','severity','warning',
        'message','The sender binding is not verified. Live delivery stays blocked.');
    END IF;
  END IF;

  IF v_cs.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','channel_setting_missing','step','channel_setting','severity','blocker',
      'message','Create an email channel setting for this scope.');
  ELSE
    IF v_cs.enabled IS NOT TRUE THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','channel_disabled','step','channel_setting','severity','blocker',
        'message','Enable the email channel for this scope.');
    END IF;
    IF v_cs.live_delivery_enabled IS TRUE AND v_cs.enabled IS NOT TRUE THEN
      v_blockers := v_blockers || jsonb_build_object(
        'code','live_without_channel_enabled','step','channel_setting','severity','blocker',
        'message','Live delivery is enabled while the channel itself is disabled.');
    END IF;
  END IF;

  IF coalesce(v_runtime_ready, false) IS NOT TRUE THEN
    v_blockers := v_blockers || jsonb_build_object(
      'code','runtime_incomplete','step','runtime','severity','blocker',
      'message','Runtime implementation objects are not fully present.');
  END IF;

  v_blockers := v_blockers || jsonb_build_object(
    'code','live_dispatch_not_implemented','step','runtime','severity','warning',
    'message','Live provider dispatch is not implemented yet. Configuration only.');

  SELECT NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_blockers) b
     WHERE b ->> 'severity' = 'blocker'
  ) INTO v_dry_run_ready;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'channel', v_channel,
    'locale', v_locale,
    'generated_at', now(),
    'tenant', jsonb_build_object(
      'organization_id', p_organization_id,
      'department_id', p_department_id,
      'scope', CASE WHEN p_department_id IS NULL THEN 'organization_wide' ELSE 'department' END,
      'capabilities', v_caps,
      'sensitive_content_visible', v_sensitive),
    'event', CASE WHEN v_ed.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_ed.id, 'code', v_ed.code, 'name', v_ed.name,
        'module_code', v_ed.module_code, 'entity_type', v_ed.entity_type,
        'communication_class', v_ed.communication_class,
        'default_priority', v_ed.default_priority, 'status', v_ed.status) END,
    'contract', CASE WHEN v_ct.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_ct.id, 'version_number', v_ct.version_number,
        'status', v_ct.status, 'checksum', v_ct.checksum,
        'published_at', v_ct.published_at,
        'sample_payload_present', v_ct.sample_payload IS NOT NULL,
        'required_fields', to_jsonb(v_required_fields)) END,
    'route', CASE WHEN v_rt.id IS NULL THEN jsonb_build_object('present', false, 'source', 'unresolved')
      ELSE jsonb_build_object(
        'present', true, 'id', v_rt.id, 'source', v_route_source,
        'lifecycle_state', v_rt.lifecycle_state, 'is_enabled', v_rt.is_enabled,
        'is_required', v_rt.is_required, 'priority', v_rt.priority,
        'preference_policy', v_rt.preference_policy,
        'sender_resolution_policy', v_rt.sender_resolution_policy,
        'template_family_id', v_rt.template_family_id,
        'sender_identity_id', v_rt.sender_identity_id) END,
    'template_family', CASE WHEN v_fam.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_fam.id, 'code', v_fam.code, 'name', v_fam.name,
        'scope_type', v_fam.scope_type, 'status', v_fam.status) END,
    'template_version', CASE WHEN v_tv.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_tv.id, 'version_number', v_tv.version_number,
        'status', v_tv.status, 'channel', v_tv.channel, 'locale', v_tv.locale,
        'checksum', v_tv.checksum, 'published_at', v_tv.published_at,
        'layout_selection_mode', v_tv.layout_selection_mode) END,
    'layout', CASE WHEN v_tv.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', (v_manifest ->> 'layout_version_id') IS NOT NULL,
        'layout_id', v_manifest -> 'layout_id',
        'layout_code', v_layout_code,
        'layout_version_id', v_manifest -> 'layout_version_id',
        'layout_version_number', v_layout_version.version_number,
        'layout_checksum', v_layout_version.checksum,
        'inheritance_source', v_manifest ->> 'layout_inheritance_source',
        'slot_count', jsonb_array_length(v_slots)) END,
    'assets', jsonb_build_object(
      'slots', v_assets,
      'unresolved_required', v_unresolved_required),
    'provider', CASE WHEN v_prov.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_prov.id, 'code', v_prov.code,
        'display_name', v_prov.display_name, 'adapter_key', v_prov.adapter_key,
        'status', v_prov.status) END,
    'provider_account', CASE WHEN v_acct.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_acct.id, 'code', v_acct.code,
        'display_name', v_acct.display_name, 'status', v_acct.status,
        'region', v_acct.region, 'sandbox_mode', v_acct.sandbox_mode,
        'health_state', v_acct.health_state,
        'health_checked_at', v_acct.health_checked_at,
        'credential_check_recorded', v_acct.health_checked_at IS NOT NULL) END,
    'sender', CASE WHEN v_sender.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_sender.id, 'code', v_sender.code,
        'display_name', v_sender.display_name, 'status', v_sender.status,
        'from_address_display', v_from_masked,
        'from_address_masked', NOT v_sensitive,
        'scope', CASE
          WHEN v_sender.event_definition_id IS NOT NULL THEN 'event'
          WHEN v_sender.department_id IS NOT NULL THEN 'department'
          ELSE 'organization' END) END,
    'binding', CASE WHEN v_bind.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_bind.id, 'status', v_bind.status,
        'verification_status', v_bind.verification_status,
        'verified_at', v_bind.verified_at, 'priority', v_bind.priority,
        'provider_account_id', v_bind.provider_account_id) END,
    'channel_setting', CASE WHEN v_cs.id IS NULL THEN jsonb_build_object('present', false)
      ELSE jsonb_build_object(
        'present', true, 'id', v_cs.id,
        'scope', CASE WHEN v_cs.department_id IS NULL THEN 'organization' ELSE 'department' END,
        'enabled', v_cs.enabled,
        'live_delivery_enabled', v_cs.live_delivery_enabled,
        'quiet_hours_start', v_cs.quiet_hours_start,
        'quiet_hours_end', v_cs.quiet_hours_end,
        'quiet_hours_timezone', v_cs.quiet_hours_timezone,
        'per_minute_limit', v_cs.per_minute_limit) END,
    'runtime', jsonb_build_object(
      'tables', v_runtime_tables,
      'functions', v_runtime_functions,
      'implementation_complete', coalesce(v_runtime_ready, false),
      'live_dispatch_implemented', false,
      'certification', jsonb_build_object(
        'resolution', 'not_certified',
        'rendering', 'not_certified',
        'overall', 'not_certified')),
    'blockers', v_blockers,
    'dry_run_ready', coalesce(v_dry_run_ready, false),
    'live_send_ready', false
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_family_activate(p_id uuid, p_reason text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_reason text;
  v_before public.omni_comms_template_family;
  v_after  public.omni_comms_template_family;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_reason := public.omni_comms_priv_normalize_reason(p_reason, false);
  SELECT * INTO v_before FROM public.omni_comms_template_family WHERE id = p_id FOR UPDATE;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_family_not_found';
  END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='family_not_draft';
  END IF;
  UPDATE public.omni_comms_template_family
     SET status = 'active', activated_at = now(), activated_by = v_uid,
         updated_at = now(), updated_by = v_uid
   WHERE id = p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'activate', 'template_family', p_id, v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), v_reason, NULL, p_correlation_id);
  RETURN jsonb_build_object('id', v_after.id, 'status', v_after.status, 'activated_at', v_after.activated_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_family_create(p_code text, p_name text, p_description text, p_scope_type text, p_organization_id uuid, p_department_id uuid, p_event_definition_id uuid, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_id  uuid;
  v_row public.omni_comms_template_family;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('author_templates');
  IF p_scope_type IS NULL OR p_scope_type NOT IN ('organization','department','event') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='scope_type_invalid';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required';
  END IF;
  IF p_scope_type = 'department' THEN
    IF p_department_id IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='department_required';
    END IF;
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;
  IF p_scope_type = 'event' AND p_event_definition_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='event_definition_required';
  END IF;

  BEGIN
    INSERT INTO public.omni_comms_template_family
      (code, name, description, scope_type, organization_id, department_id, event_definition_id,
       status, created_by, updated_by)
    VALUES (p_code, p_name, p_description, p_scope_type, p_organization_id,
      CASE p_scope_type WHEN 'department' THEN p_department_id ELSE NULL END,
      CASE p_scope_type WHEN 'event' THEN p_event_definition_id ELSE NULL END,
      'draft', v_uid, v_uid)
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'OC409 duplicate_template_family_code' USING ERRCODE='P0001', DETAIL='duplicate_family_code';
    WHEN check_violation THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
    WHEN foreign_key_violation THEN
      RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;

  SELECT * INTO v_row FROM public.omni_comms_template_family WHERE id = v_id;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'create', 'template_family', v_id, v_row.code,
    NULL, to_jsonb(v_row), NULL, NULL, p_correlation_id);

  RETURN jsonb_build_object(
    'id', v_row.id, 'code', v_row.code, 'name', v_row.name,
    'description', v_row.description, 'scope_type', v_row.scope_type,
    'organization_id', v_row.organization_id, 'department_id', v_row.department_id,
    'event_definition_id', v_row.event_definition_id, 'status', v_row.status,
    'created_at', v_row.created_at, 'updated_at', v_row.updated_at);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_family_get(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.omni_comms_template_family;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  SELECT * INTO r FROM public.omni_comms_template_family WHERE id = p_id;
  IF r.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_family_not_found';
  END IF;
  RETURN jsonb_build_object(
    'id', r.id, 'code', r.code, 'name', r.name, 'description', r.description,
    'scope_type', r.scope_type, 'status', r.status,
    'organization_id', r.organization_id, 'department_id', r.department_id,
    'event_definition_id', r.event_definition_id,
    'activated_at', r.activated_at, 'retired_at', r.retired_at,
    'retirement_reason', r.retirement_reason,
    'created_at', r.created_at, 'updated_at', r.updated_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_family_list(p_search text, p_status text, p_scope_type text, p_organization_id uuid, p_limit integer, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_limit int; v_offset int; v_pattern text; v_items jsonb; v_total bigint;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  v_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);
  v_pattern := CASE WHEN p_search IS NULL OR btrim(p_search) = '' THEN NULL
                    ELSE '%' || public.omni_comms_priv_escape_ilike(btrim(p_search)) || '%' END;

  WITH filtered AS (
    SELECT f.* FROM public.omni_comms_template_family f
     WHERE (p_status IS NULL OR f.status = p_status)
       AND (p_scope_type IS NULL OR f.scope_type = p_scope_type)
       AND (p_organization_id IS NULL OR f.organization_id = p_organization_id)
       AND (v_pattern IS NULL OR f.code ILIKE v_pattern ESCAPE '\' OR f.name ILIKE v_pattern ESCAPE '\')
  ), page AS (
    SELECT * FROM filtered ORDER BY updated_at DESC, id ASC LIMIT v_limit OFFSET v_offset
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', p.id, 'code', p.code, 'name', p.name, 'scope_type', p.scope_type,
      'status', p.status, 'organization_id', p.organization_id,
      'department_id', p.department_id, 'event_definition_id', p.event_definition_id,
      'updated_at', p.updated_at)), '[]'::jsonb),
      (SELECT count(*) FROM filtered)
    INTO v_items, v_total FROM page p;

  RETURN jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_family_retire(p_id uuid, p_reason text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_reason text;
  v_before public.omni_comms_template_family;
  v_after  public.omni_comms_template_family;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_reason := public.omni_comms_priv_normalize_reason(p_reason, true);
  SELECT * INTO v_before FROM public.omni_comms_template_family WHERE id = p_id FOR UPDATE;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_family_not_found';
  END IF;
  IF v_before.status = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='family_already_retired';
  END IF;
  UPDATE public.omni_comms_template_family
     SET status='retired', retired_at=now(), retired_by=v_uid,
         retirement_reason=v_reason,
         updated_at=now(), updated_by=v_uid
   WHERE id = p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'retire', 'template_family', p_id, v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), v_reason, NULL, p_correlation_id);
  RETURN jsonb_build_object('id', v_after.id, 'status', v_after.status, 'retired_at', v_after.retired_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_family_update(p_id uuid, p_name text, p_description text, p_expected_updated_at timestamp with time zone, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_before public.omni_comms_template_family;
  v_after  public.omni_comms_template_family;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('author_templates');
  SELECT * INTO v_before FROM public.omni_comms_template_family WHERE id = p_id FOR UPDATE;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_family_not_found';
  END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='family_not_draft';
  END IF;
  IF p_expected_updated_at IS DISTINCT FROM v_before.updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch';
  END IF;
  UPDATE public.omni_comms_template_family
     SET name = COALESCE(p_name, name),
         description = p_description,
         updated_at = now(), updated_by = v_uid
   WHERE id = p_id
   RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'update', 'template_family', p_id, v_after.code,
    to_jsonb(v_before), to_jsonb(v_after), NULL, NULL, p_correlation_id);
  RETURN jsonb_build_object(
    'id', v_after.id, 'code', v_after.code, 'name', v_after.name,
    'description', v_after.description, 'status', v_after.status,
    'updated_at', v_after.updated_at);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_resolve_published(p_event_definition_id uuid, p_organization_id uuid, p_department_id uuid, p_channel text, p_locale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_locale text;
  v_family_id uuid; v_version_id uuid; v_scope text;
  v_family public.omni_comms_template_family;
  v_version public.omni_comms_template_version;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='organization_required';
  END IF;
  IF p_channel NOT IN ('email','sms','in_app','push','whatsapp','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_unknown';
  END IF;
  v_locale := public.omni_comms_priv_normalize_locale(p_locale);
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  -- Precedence: event (3) > department (2) > organization (1)
  SELECT f.id, v.id,
         CASE f.scope_type WHEN 'event' THEN 3 WHEN 'department' THEN 2 ELSE 1 END
    INTO v_family_id, v_version_id, v_scope
    FROM public.omni_comms_template_family f
    JOIN public.omni_comms_template_version v ON v.template_family_id = f.id
   WHERE f.status = 'active'
     AND f.organization_id = p_organization_id
     AND v.status = 'published'
     AND v.channel = p_channel
     AND v.locale  = v_locale
     AND (
       (f.scope_type = 'event' AND p_event_definition_id IS NOT NULL
          AND f.event_definition_id = p_event_definition_id)
       OR (f.scope_type = 'department' AND p_department_id IS NOT NULL
          AND f.department_id = p_department_id)
       OR (f.scope_type = 'organization')
     )
   ORDER BY CASE f.scope_type WHEN 'event' THEN 3 WHEN 'department' THEN 2 ELSE 1 END DESC,
            v.version_number DESC
   LIMIT 1;

  IF v_family_id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='no_published_template';
  END IF;

  SELECT * INTO v_family  FROM public.omni_comms_template_family  WHERE id = v_family_id;
  SELECT * INTO v_version FROM public.omni_comms_template_version WHERE id = v_version_id;

  RETURN jsonb_build_object(
    'template_family_id', v_family.id,
    'family_code',        v_family.code,
    'scope_type',         v_family.scope_type,
    'template_version_id', v_version.id,
    'version_number',     v_version.version_number,
    'channel',            v_version.channel,
    'locale',             v_version.locale,
    'checksum',           v_version.checksum,
    'content',            v_version.content);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_approve(p_id uuid, p_approval_note text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_before public.omni_comms_template_version; v_after public.omni_comms_template_version;
  v_family public.omni_comms_template_family; v_checksum text; v_note text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('approve_templates');
  v_note := btrim(COALESCE(p_approval_note, ''));
  IF length(v_note) > 2000 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='approval_note_too_long';
  END IF;
  IF v_note = '' THEN v_note := NULL; END IF;
  SELECT * INTO v_before FROM public.omni_comms_template_version WHERE id = p_id FOR UPDATE;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_version_not_found';
  END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='version_not_draft';
  END IF;
  IF v_before.created_by IS NOT NULL AND v_before.created_by = v_uid THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='approver_must_differ_from_author';
  END IF;
  SELECT * INTO v_family FROM public.omni_comms_template_family WHERE id = v_before.template_family_id;
  PERFORM public.omni_comms_priv_validate_channel_content(v_before.channel, v_before.content);
  v_checksum := public.omni_comms_priv_compute_template_checksum(
    v_family.code, v_before.version_number, v_before.channel, v_before.locale, v_before.content);
  UPDATE public.omni_comms_template_version
     SET status='approved', approved_at=now(), approved_by=v_uid,
         checksum=v_checksum, updated_at=now(), updated_by=v_uid
   WHERE id = p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'approve', 'template_version', p_id,
    v_family.code || ':' || v_after.channel || ':' || v_after.locale || ':v' || v_after.version_number,
    jsonb_build_object('status', v_before.status),
    jsonb_build_object('status', v_after.status, 'checksum', v_after.checksum),
    NULL, v_note, p_correlation_id);
  RETURN jsonb_build_object('id', v_after.id, 'status', v_after.status, 'checksum', v_after.checksum, 'approved_at', v_after.approved_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_create(p_template_family_id uuid, p_channel text, p_locale text, p_version_number integer, p_content jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_locale text; v_family public.omni_comms_template_family;
  v_id uuid; v_row public.omni_comms_template_version;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('author_templates');
  IF p_channel NOT IN ('email','sms','in_app','push','whatsapp','print') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='channel_unknown';
  END IF;
  v_locale := public.omni_comms_priv_normalize_locale(p_locale);
  PERFORM public.omni_comms_priv_validate_channel_content(p_channel, p_content);
  SELECT * INTO v_family FROM public.omni_comms_template_family WHERE id = p_template_family_id;
  IF v_family.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_family_not_found';
  END IF;
  IF v_family.status = 'retired' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='family_retired';
  END IF;
  IF p_version_number IS NULL OR p_version_number <= 0 THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='version_number_invalid';
  END IF;
  BEGIN
    INSERT INTO public.omni_comms_template_version
      (template_family_id, version_number, channel, locale, content, status,
       created_by, updated_by)
    VALUES (p_template_family_id, p_version_number, p_channel, v_locale, p_content, 'draft', v_uid, v_uid)
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'OC409 duplicate_template_version' USING ERRCODE='P0001', DETAIL='duplicate_version';
    WHEN check_violation THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL=SQLERRM;
  END;
  SELECT * INTO v_row FROM public.omni_comms_template_version WHERE id = v_id;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'create', 'template_version', v_id,
    v_family.code || ':' || v_row.channel || ':' || v_row.locale || ':v' || v_row.version_number,
    NULL,
    jsonb_build_object('id', v_row.id, 'template_family_id', v_row.template_family_id,
      'channel', v_row.channel, 'locale', v_row.locale, 'version_number', v_row.version_number,
      'status', v_row.status),
    NULL, NULL, p_correlation_id);
  RETURN jsonb_build_object(
    'id', v_row.id, 'template_family_id', v_row.template_family_id,
    'version_number', v_row.version_number, 'channel', v_row.channel,
    'locale', v_row.locale, 'status', v_row.status,
    'created_at', v_row.created_at, 'updated_at', v_row.updated_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_get(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.omni_comms_template_version; v_layout_name text; v_layout_code text; v_pv_num int;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  SELECT * INTO r FROM public.omni_comms_template_version WHERE id = p_id;
  IF r.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_version_not_found';
  END IF;
  SELECT l.name, l.code INTO v_layout_name, v_layout_code
    FROM public.core_template_layout l WHERE l.id = r.layout_id;
  SELECT lv.version_number INTO v_pv_num
    FROM public.core_template_layout_version lv WHERE lv.id = r.pinned_layout_version_id;
  RETURN jsonb_build_object(
    'id', r.id, 'template_family_id', r.template_family_id,
    'version_number', r.version_number, 'channel', r.channel, 'locale', r.locale,
    'status', r.status, 'checksum', r.checksum, 'content', r.content,
    'approved_at', r.approved_at, 'published_at', r.published_at,
    'retired_at', r.retired_at, 'retirement_reason', r.retirement_reason,
    'created_at', r.created_at, 'updated_at', r.updated_at,
    'layout_selection_mode', r.layout_selection_mode,
    'layout_id', r.layout_id,
    'pinned_layout_version_id', r.pinned_layout_version_id,
    'layout_name', v_layout_name,
    'layout_code', v_layout_code,
    'pinned_layout_version_number', v_pv_num,
    'layout_selection_valid', public.omni_comms_priv_layout_selection_valid(
      r.layout_selection_mode, r.layout_id, r.pinned_layout_version_id, r.channel));
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_list(p_template_family_id uuid, p_channel text, p_locale text, p_status text, p_limit integer, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_limit int; v_offset int; v_items jsonb; v_total bigint;
BEGIN
  PERFORM public.omni_comms_priv_require_capability('view');
  IF p_template_family_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='template_family_id_required';
  END IF;
  v_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_offset := GREATEST(COALESCE(p_offset, 0), 0);
  WITH filtered AS (
    SELECT v.* FROM public.omni_comms_template_version v
     WHERE v.template_family_id = p_template_family_id
       AND (p_channel IS NULL OR v.channel = p_channel)
       AND (p_locale  IS NULL OR v.locale  = p_locale)
       AND (p_status  IS NULL OR v.status  = p_status)
  ), page AS (
    SELECT * FROM filtered ORDER BY version_number DESC, id ASC LIMIT v_limit OFFSET v_offset
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', p.id, 'template_family_id', p.template_family_id,
      'version_number', p.version_number, 'channel', p.channel, 'locale', p.locale,
      'status', p.status, 'checksum', p.checksum,
      'approved_at', p.approved_at, 'published_at', p.published_at,
      'retired_at', p.retired_at, 'updated_at', p.updated_at,
      'layout_selection_mode', p.layout_selection_mode,
      'layout_id', p.layout_id,
      'pinned_layout_version_id', p.pinned_layout_version_id,
      'layout_name', l.name,
      'layout_code', l.code,
      'pinned_layout_version_number', lv.version_number,
      'layout_selection_valid', public.omni_comms_priv_layout_selection_valid(
        p.layout_selection_mode, p.layout_id, p.pinned_layout_version_id, p.channel))
      ORDER BY p.version_number DESC, p.id ASC), '[]'::jsonb),
    (SELECT count(*) FROM filtered) INTO v_items, v_total
  FROM page p
  LEFT JOIN public.core_template_layout l ON l.id = p.layout_id
  LEFT JOIN public.core_template_layout_version lv ON lv.id = p.pinned_layout_version_id;
  RETURN jsonb_build_object('items', v_items, 'total', v_total, 'limit', v_limit, 'offset', v_offset);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_publish(p_id uuid, p_expected_updated_at timestamp with time zone, p_confirm_replacement boolean, p_replacement_reason text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid          uuid;
  v_reason       text;
  v_before       public.omni_comms_template_version;
  v_after        public.omni_comms_template_version;
  v_family       public.omni_comms_template_family;
  v_prev         public.omni_comms_template_version;
  v_replaced_id  uuid;
  v_confirm      boolean := COALESCE(p_confirm_replacement, false);
BEGIN
  -- Capability + actor.
  v_uid := public.omni_comms_priv_require_capability('approve_templates');

  IF p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'expected_updated_at_required';
  END IF;

  -- Step 1 — resolve family from target row (unlocked read to identify),
  -- then lock family first to establish deterministic lock order.
  SELECT * INTO v_before
    FROM public.omni_comms_template_version
   WHERE id = p_id;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found'
      USING ERRCODE = 'P0001', DETAIL = 'template_version_not_found';
  END IF;

  PERFORM 1 FROM public.omni_comms_template_family
    WHERE id = v_before.template_family_id FOR UPDATE;
  SELECT * INTO v_family
    FROM public.omni_comms_template_family
   WHERE id = v_before.template_family_id;

  -- Step 2 — lock the target approved version.
  SELECT * INTO v_before
    FROM public.omni_comms_template_version
   WHERE id = p_id FOR UPDATE;

  -- Step 3 — optimistic-concurrency guard on the target version.
  IF p_expected_updated_at IS DISTINCT FROM v_before.updated_at THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'updated_at_mismatch';
  END IF;

  IF v_before.status <> 'approved' THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'version_not_approved';
  END IF;

  -- Step 4 — lock any currently published sibling for exact (family, channel, locale).
  SELECT * INTO v_prev
    FROM public.omni_comms_template_version
   WHERE template_family_id = v_before.template_family_id
     AND channel = v_before.channel
     AND locale  = v_before.locale
     AND status  = 'published'
   FOR UPDATE;

  IF v_prev.id IS NOT NULL AND v_prev.id = v_before.id THEN
    -- The target itself is already the published row.
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'already_published';
  END IF;

  -- Step 5 — apply initial-publication, conflict, or replacement policy.
  IF v_prev.id IS NULL THEN
    -- No existing published version.
    IF v_confirm THEN
      RAISE EXCEPTION 'OC422 validation_error'
        USING ERRCODE = 'P0001', DETAIL = 'replacement_not_applicable';
    END IF;
    v_reason := NULL;  -- reason not accepted on initial publication
    v_replaced_id := NULL;
  ELSE
    -- Existing published version present.
    IF NOT v_confirm THEN
      RAISE EXCEPTION 'OC409 conflict'
        USING ERRCODE = 'P0001', DETAIL = 'replacement_confirmation_required';
    END IF;
    -- Confirmed replacement — require a non-blank reason, then apply length rule.
    IF btrim(COALESCE(p_replacement_reason, '')) = '' THEN
      RAISE EXCEPTION 'OC422 validation_error'
        USING ERRCODE = 'P0001', DETAIL = 'replacement_reason_required';
    END IF;
    -- Length + trim via the shared normalizer (raises reason_too_long / reason_required).
    v_reason := public.omni_comms_priv_normalize_reason(p_replacement_reason, true);

    -- Retire the existing published version.
    UPDATE public.omni_comms_template_version
       SET status            = 'retired',
           retired_at        = now(),
           retired_by        = v_uid,
           retirement_reason = v_reason,
           updated_at        = now(),
           updated_by        = v_uid
     WHERE id = v_prev.id;
    v_replaced_id := v_prev.id;

    PERFORM public.omni_comms_priv_write_template_audit(
      v_uid, 'retire', 'template_version', v_prev.id,
      v_family.code || ':' || v_prev.channel || ':' || v_prev.locale || ':v' || v_prev.version_number,
      jsonb_build_object('status', v_prev.status),
      jsonb_build_object('status', 'retired', 'replaced_by', v_before.id),
      v_reason, NULL, p_correlation_id
    );
  END IF;

  -- Step 6 — publish the target and write its audit row.
  UPDATE public.omni_comms_template_version
     SET status        = 'published',
         published_at  = now(),
         published_by  = v_uid,
         updated_at    = now(),
         updated_by    = v_uid
   WHERE id = p_id
   RETURNING * INTO v_after;

  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'publish', 'template_version', p_id,
    v_family.code || ':' || v_after.channel || ':' || v_after.locale || ':v' || v_after.version_number,
    jsonb_build_object('status', v_before.status),
    jsonb_build_object('status', v_after.status, 'replaced', v_replaced_id),
    v_reason, NULL, p_correlation_id
  );

  RETURN jsonb_build_object(
    'id', v_after.id,
    'status', v_after.status,
    'published_at', v_after.published_at,
    'replaced_version_id', v_replaced_id
  );
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'OC409 conflict'
      USING ERRCODE = 'P0001', DETAIL = 'publication_conflict';
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_retire(p_id uuid, p_reason text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_reason text; v_before public.omni_comms_template_version; v_after public.omni_comms_template_version;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('configure');
  v_reason := public.omni_comms_priv_normalize_reason(p_reason, true);
  SELECT * INTO v_before FROM public.omni_comms_template_version WHERE id = p_id FOR UPDATE;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_version_not_found';
  END IF;
  IF v_before.status NOT IN ('approved','published') THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='version_cannot_be_retired';
  END IF;
  UPDATE public.omni_comms_template_version
     SET status='retired', retired_at=now(), retired_by=v_uid,
         retirement_reason=v_reason, updated_at=now(), updated_by=v_uid
   WHERE id = p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'retire', 'template_version', p_id, v_after.channel || ':' || v_after.locale || ':v' || v_after.version_number,
    jsonb_build_object('status', v_before.status),
    jsonb_build_object('status', v_after.status),
    v_reason, NULL, p_correlation_id);
  RETURN jsonb_build_object('id', v_after.id, 'status', v_after.status, 'retired_at', v_after.retired_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_set_layout_selection(p_version_id uuid, p_mode text, p_layout_id uuid, p_pinned_layout_version_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_row public.omni_comms_template_version;
  v_kind text; v_active boolean; v_pv_layout uuid; v_pv_status text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('author_templates');
  SELECT * INTO v_row FROM public.omni_comms_template_version WHERE id = p_version_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='version_not_found'; END IF;
  IF v_row.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='not_draft';
  END IF;
  IF v_row.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OC413 concurrency_conflict' USING ERRCODE='P0001', DETAIL='stale_template_version';
  END IF;
  IF p_mode NOT IN ('resolved_default','pinned') THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='invalid_mode';
  END IF;
  IF p_layout_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_required';
  END IF;

  SELECT l.layout_kind, l.is_active INTO v_kind, v_active
    FROM public.core_template_layout l WHERE l.id = p_layout_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='layout_not_found';
  END IF;
  IF COALESCE(v_active, false) = false THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_not_active';
  END IF;
  IF NOT public.omni_comms_priv_layout_kind_matches_channel(v_kind, v_row.channel) THEN
    RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_channel_mismatch';
  END IF;

  IF p_mode = 'pinned' THEN
    IF p_pinned_layout_version_id IS NULL THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_version_required';
    END IF;
    SELECT lv.layout_id, lv.status INTO v_pv_layout, v_pv_status
      FROM public.core_template_layout_version lv WHERE lv.id = p_pinned_layout_version_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='layout_version_not_found';
    END IF;
    IF v_pv_layout IS DISTINCT FROM p_layout_id THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_version_mismatch';
    END IF;
    IF v_pv_status <> 'published' THEN
      RAISE EXCEPTION 'OC422 validation_error' USING ERRCODE='P0001', DETAIL='layout_version_not_published';
    END IF;
  END IF;

  UPDATE public.omni_comms_template_version
    SET layout_selection_mode = p_mode,
        layout_id = p_layout_id,
        pinned_layout_version_id = CASE WHEN p_mode = 'pinned' THEN p_pinned_layout_version_id ELSE NULL END,
        updated_at = now(), updated_by = v_uid
    WHERE id = p_version_id;
  RETURN jsonb_build_object('id', p_version_id, 'ok', true);
END;$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_template_version_update(p_id uuid, p_content jsonb, p_expected_updated_at timestamp with time zone, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid; v_before public.omni_comms_template_version; v_after public.omni_comms_template_version;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('author_templates');
  SELECT * INTO v_before FROM public.omni_comms_template_version WHERE id = p_id FOR UPDATE;
  IF v_before.id IS NULL THEN
    RAISE EXCEPTION 'OC404 not_found' USING ERRCODE='P0001', DETAIL='template_version_not_found';
  END IF;
  IF v_before.status <> 'draft' THEN
    RAISE EXCEPTION 'OC412 invalid_state' USING ERRCODE='P0001', DETAIL='version_not_draft';
  END IF;
  IF p_expected_updated_at IS DISTINCT FROM v_before.updated_at THEN
    RAISE EXCEPTION 'OC413 concurrent_update' USING ERRCODE='P0001', DETAIL='updated_at_mismatch';
  END IF;
  PERFORM public.omni_comms_priv_validate_channel_content(v_before.channel, p_content);
  UPDATE public.omni_comms_template_version
     SET content = p_content, updated_at = now(), updated_by = v_uid
   WHERE id = p_id RETURNING * INTO v_after;
  PERFORM public.omni_comms_priv_write_template_audit(
    v_uid, 'update', 'template_version', p_id, v_after.channel || ':' || v_after.locale || ':v' || v_after.version_number,
    jsonb_build_object('id', v_before.id, 'status', v_before.status),
    jsonb_build_object('id', v_after.id,  'status', v_after.status),
    NULL, NULL, p_correlation_id);
  RETURN jsonb_build_object('id', v_after.id, 'status', v_after.status, 'updated_at', v_after.updated_at);
END; $function$;
CREATE OR REPLACE FUNCTION public.omni_comms_upsert_producer_event_binding_draft(p_id uuid, p_organization_id uuid, p_department_id uuid, p_caller_module_code text, p_event_definition_id uuid, p_allowed_modes text[], p_integration_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor  uuid;
  v_module text;
  v_before jsonb;
  v_row    public.omni_comms_producer_event_binding%ROWTYPE;
BEGIN
  v_actor := public.omni_comms_priv_require_capability('configure');

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC400 organization_required'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;

  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;

  PERFORM public.omni_comms_priv_require_tenant_access(v_actor, p_organization_id, p_department_id);

  v_module := upper(btrim(coalesce(p_caller_module_code, '')));
  IF NOT EXISTS (
    SELECT 1 FROM public.omni_comms_caller_module_registry
    WHERE module_code = v_module AND is_active = true
  ) THEN
    RAISE EXCEPTION 'OC400 caller_module_not_registered'
      USING ERRCODE = 'P0001', DETAIL = 'caller_module_not_registered';
  END IF;

  IF p_event_definition_id IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.omni_comms_event_definition WHERE id = p_event_definition_id) THEN
    RAISE EXCEPTION 'OC404 event_not_found'
      USING ERRCODE = 'P0001', DETAIL = 'event_not_found';
  END IF;

  IF p_allowed_modes IS NULL OR array_length(p_allowed_modes, 1) IS NULL THEN
    RAISE EXCEPTION 'OC400 allowed_modes_required'
      USING ERRCODE = 'P0001', DETAIL = 'allowed_modes_required';
  END IF;

  IF 'queued' = ANY (p_allowed_modes) THEN
    RAISE EXCEPTION 'OC400 producer_mode_not_available'
      USING ERRCODE = 'P0001', DETAIL = 'queued_mode_requires_certified_delivery_release';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.omni_comms_producer_event_binding (
      organization_id, department_id, caller_module_code, event_definition_id,
      allowed_modes, status, integration_reference, created_by, updated_by
    ) VALUES (
      p_organization_id, p_department_id, v_module, p_event_definition_id,
      p_allowed_modes, 'draft', nullif(btrim(coalesce(p_integration_reference, '')), ''), v_actor, v_actor
    )
    RETURNING * INTO v_row;
    v_before := NULL;
  ELSE
    v_row := public.omni_comms_priv_peb_load(p_id);
    IF v_row.organization_id <> p_organization_id THEN
      RAISE EXCEPTION 'OC403 organization_mismatch'
        USING ERRCODE = 'P0001', DETAIL = 'organization_mismatch';
    END IF;
    PERFORM public.omni_comms_priv_require_tenant_access(v_actor, v_row.organization_id, v_row.department_id);
    IF v_row.status <> 'draft' THEN
      RAISE EXCEPTION 'OC409 producer_binding_not_draft'
        USING ERRCODE = 'P0001', DETAIL = 'producer_binding_not_draft';
    END IF;
    v_before := jsonb_build_object(
      'caller_module_code', v_row.caller_module_code,
      'event_definition_id', v_row.event_definition_id,
      'allowed_modes', to_jsonb(v_row.allowed_modes),
      'department_id', v_row.department_id,
      'integration_reference', v_row.integration_reference,
      'status', v_row.status
    );
    UPDATE public.omni_comms_producer_event_binding
       SET department_id = p_department_id,
           caller_module_code = v_module,
           event_definition_id = p_event_definition_id,
           allowed_modes = p_allowed_modes,
           integration_reference = nullif(btrim(coalesce(p_integration_reference, '')), ''),
           updated_by = v_actor
     WHERE id = p_id
     RETURNING * INTO v_row;
  END IF;

  PERFORM public.omni_comms_priv_write_audit(
    v_actor, 'upsert_draft', 'producer_event_binding', v_row.id,
    v_row.caller_module_code,
    v_before,
    jsonb_build_object(
      'caller_module_code', v_row.caller_module_code,
      'event_definition_id', v_row.event_definition_id,
      'allowed_modes', to_jsonb(v_row.allowed_modes),
      'department_id', v_row.department_id,
      'integration_reference', v_row.integration_reference,
      'status', v_row.status
    ),
    NULL
  );

  RETURN jsonb_build_object('id', v_row.id, 'status', v_row.status);
END;
$function$;
CREATE OR REPLACE FUNCTION public.omni_comms_validate_dry_run_payload(p_organization_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_event_definition_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_ed public.omni_comms_event_definition;
  v_ct public.omni_comms_event_contract;
  v_errors jsonb := '[]'::jsonb;
  v_size int;
  v_valid boolean := false;
  v_missing text;
BEGIN
  v_uid := public.omni_comms_priv_require_capability('operate');

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'organization_required';
  END IF;
  IF p_department_id IS NOT NULL THEN
    PERFORM public.omni_comms_priv_verify_department_ownership(p_department_id, p_organization_id);
  END IF;
  IF p_event_definition_id IS NULL THEN
    RAISE EXCEPTION 'OC422 validation_error'
      USING ERRCODE = 'P0001', DETAIL = 'event_definition_required';
  END IF;

  SELECT * INTO v_ed FROM public.omni_comms_event_definition WHERE id = p_event_definition_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OC404 not_found'
      USING ERRCODE = 'P0001', DETAIL = 'event_definition_not_found';
  END IF;
  IF v_ed.status <> 'active' THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'event_not_active';
  END IF;

  SELECT * INTO v_ct FROM public.omni_comms_event_contract
   WHERE event_definition_id = v_ed.id AND status = 'published'
   ORDER BY version_number DESC LIMIT 1;
  IF v_ct.id IS NULL THEN
    RAISE EXCEPTION 'OC412 invalid_state'
      USING ERRCODE = 'P0001', DETAIL = 'no_published_contract';
  END IF;

  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code', 'payload_not_object',
      'message', 'The synthetic payload must be a JSON object.'));
  ELSE
    v_size := octet_length(p_payload::text);
    IF v_size > 262144 THEN
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'code', 'payload_too_large',
        'message', 'The synthetic payload exceeds the 256 KiB limit.'));
    ELSE
      FOR v_missing IN
        SELECT x FROM jsonb_array_elements_text(
                        CASE WHEN jsonb_typeof(v_ct.json_schema -> 'required') = 'array'
                             THEN v_ct.json_schema -> 'required' ELSE '[]'::jsonb END) AS t(x)
         WHERE NOT (p_payload ? x)
         LIMIT 25
      LOOP
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'code', 'required_field_missing',
          'field', v_missing,
          'message', format('Required contract field "%s" is missing.', v_missing)));
      END LOOP;

      BEGIN
        v_valid := extensions.jsonb_matches_schema(v_ct.json_schema::text::json, p_payload);
      EXCEPTION WHEN OTHERS THEN
        v_valid := false;
      END;

      IF NOT v_valid THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'code', 'schema_validation_failed',
          'message', 'The synthetic payload does not satisfy the published event contract.'));
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'valid', jsonb_array_length(v_errors) = 0,
    'event_definition_id', v_ed.id,
    'event_code', v_ed.code,
    'contract_id', v_ct.id,
    'contract_version', v_ct.version_number,
    'contract_checksum', v_ct.checksum,
    'organization_id', p_organization_id,
    'department_id', p_department_id,
    'payload_bytes', coalesce(octet_length(p_payload::text), 0),
    'errors', v_errors,
    'validated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.open_comm_hub_live_window(p_module_code text, p_event_code text, p_duration_minutes integer, p_reason text, p_typed_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_event_status text;
  v_queued_live integer;
  v_expected_confirm text;
  v_now timestamptz := now();
  v_new_after timestamptz;
  v_max_duration int;
  v_validator jsonb;
  v_blockers text;
BEGIN
  IF v_uid IS NULL OR NOT public.has_role(v_uid, 'Admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    (p_module_code = 'COMM_HUB'   AND p_event_code = 'ADMIN_TEST_NOTICE') OR
    (p_module_code = 'COMPLIANCE' AND p_event_code = 'INTERNAL_CASE_STATUS_NOTICE') OR
    (p_module_code = 'LEGAL'      AND p_event_code = 'INTERNAL_CASE_ASSIGNMENT_NOTICE')
  ) THEN
    RAISE EXCEPTION 'unsupported event: %/% not permitted in this phase', p_module_code, p_event_code;
  END IF;

  v_expected_confirm := 'OPEN LIVE WINDOW FOR ' || p_module_code || '/' || p_event_code;
  IF p_typed_confirmation IS DISTINCT FROM v_expected_confirm THEN
    RAISE EXCEPTION 'typed confirmation mismatch: expected exact phrase';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'reason is required';
  END IF;

  v_max_duration := CASE WHEN p_module_code IN ('COMPLIANCE','LEGAL') THEN 5 ELSE 30 END;
  IF p_duration_minutes IS NULL OR p_duration_minutes < 1 OR p_duration_minutes > v_max_duration THEN
    RAISE EXCEPTION 'duration must be between 1 and % minutes (got %)', v_max_duration, p_duration_minutes;
  END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings ORDER BY created_at ASC LIMIT 1;
  IF v_settings.id IS NULL THEN RAISE EXCEPTION 'control settings row missing'; END IF;

  -- NEW: recipient release mode validation (replaces hardcoded Rohit-only rule)
  v_validator := public.validate_comm_hub_recipient_release_mode(
    v_settings.recipient_release_mode,
    v_settings.allowed_email_addresses,
    v_settings.allowed_email_domains
  );
  IF (v_validator->>'ok')::boolean IS DISTINCT FROM true THEN
    v_blockers := (
      SELECT string_agg(b->>'code' || ': ' || (b->>'message'), ' | ')
      FROM jsonb_array_elements(v_validator->'blockers') b
    );
    INSERT INTO public.communication_hub_control_audit
      (setting_key, old_value, new_value, reason, changed_by, source)
    VALUES
      ('recipient_release_mode', to_jsonb(v_settings.recipient_release_mode), v_validator,
       'live-window open refused: ' || COALESCE(v_blockers, 'unknown blockers'),
       v_uid, 'open_comm_hub_live_window');
    RAISE EXCEPTION 'recipient release mode blocks live window: %', COALESCE(v_blockers, 'unknown');
  END IF;

  SELECT status INTO v_event_status FROM public.communication_hub_event_live_control
    WHERE module_code = p_module_code AND event_code = p_event_code;
  IF v_event_status IS DISTINCT FROM 'live_manual_only' THEN
    RAISE EXCEPTION 'event status must be live_manual_only (got %)', COALESCE(v_event_status,'null');
  END IF;

  SELECT count(*) INTO v_queued_live FROM public.communication_message
    WHERE test_mode = false AND status IN ('queued','sending');
  IF v_queued_live > 0 THEN
    RAISE EXCEPTION 'refusing to open: % queued/sending live messages exist', v_queued_live;
  END IF;

  v_new_after := v_now;
  INSERT INTO public.communication_hub_control_audit
    (setting_key, old_value, new_value, reason, changed_by, source)
  VALUES
    ('dry_run_only', to_jsonb(v_settings.dry_run_only), to_jsonb(false),
      'live-window RPC open (' || p_module_code || '/' || p_event_code || ', ' || p_duration_minutes || 'm): ' || p_reason, v_uid, 'open_comm_hub_live_window'),
    ('email_live_enabled', to_jsonb(v_settings.email_live_enabled), to_jsonb(true),
      'live-window RPC open', v_uid, 'open_comm_hub_live_window'),
    ('live_eligible_after', to_jsonb(v_settings.live_eligible_after), to_jsonb(v_new_after),
      'live-window RPC open', v_uid, 'open_comm_hub_live_window'),
    ('live_eligible_max_age_minutes', to_jsonb(v_settings.live_eligible_max_age_minutes), to_jsonb(p_duration_minutes),
      'live-window RPC open', v_uid, 'open_comm_hub_live_window');

  UPDATE public.communication_hub_control_settings
     SET dry_run_only = false, email_live_enabled = true, dispatch_enabled = true,
         live_eligible_after = v_new_after, live_eligible_max_age_minutes = p_duration_minutes, updated_by = v_uid
   WHERE id = v_settings.id;

  RETURN jsonb_build_object('ok', true, 'opened_at', v_new_after,
    'expires_at', v_new_after + make_interval(mins => p_duration_minutes),
    'duration_minutes', p_duration_minutes, 'module_code', p_module_code, 'event_code', p_event_code,
    'recipient_release_mode', v_settings.recipient_release_mode);
END;
$function$;
CREATE OR REPLACE FUNCTION public.pay_invoices_with_receipt(p_batch_number text, p_payer_type text, p_payer_id text, p_payer_name text, p_date_received date, p_remarks text, p_detail_lines jsonb, p_invoice_ids integer[], p_receipt_total numeric, p_total_payments integer, p_user_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_payment_id INTEGER;
  v_receipt_id INTEGER;
  v_detail JSONB;
  v_inv_id INTEGER;
  v_inv RECORD;
  v_total_outstanding NUMERIC := 0;
  v_exp_date TEXT;
  v_exp_normalized TEXT;
  v_parts TEXT[];
BEGIN
  -- Validate inputs
  IF p_batch_number IS NULL OR p_batch_number = '' THEN
    RAISE EXCEPTION 'batch_number is required';
  END IF;
  IF array_length(p_invoice_ids, 1) IS NULL OR array_length(p_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'At least one invoice must be selected';
  END IF;
  IF jsonb_array_length(p_detail_lines) = 0 THEN
    RAISE EXCEPTION 'At least one payment detail line is required';
  END IF;
  IF p_receipt_total <= 0 THEN
    RAISE EXCEPTION 'receipt_total must be greater than zero';
  END IF;

  -- Validate batch is open
  IF NOT EXISTS (
    SELECT 1 FROM public.cn_batch WHERE batch_number = p_batch_number AND batch_status = 'O'
  ) THEN
    RAISE EXCEPTION 'Batch % is not open', p_batch_number;
  END IF;

  -- Validate all invoices are payable and compute total outstanding
  FOR v_inv_id IN SELECT unnest(p_invoice_ids)
  LOOP
    SELECT id, status, total_amount, paid_amount, (total_amount - paid_amount) AS outstanding
    INTO v_inv
    FROM public.cn_invoices
    WHERE id = v_inv_id
    FOR UPDATE; -- lock row

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice ID % not found', v_inv_id;
    END IF;

    IF v_inv.status NOT IN ('O', 'pending') THEN
      RAISE EXCEPTION 'Invoice ID % has status %, which is not payable', v_inv_id, v_inv.status;
    END IF;

    IF v_inv.outstanding <= 0 THEN
      RAISE EXCEPTION 'Invoice ID % has no outstanding balance', v_inv_id;
    END IF;

    v_total_outstanding := v_total_outstanding + v_inv.outstanding;
  END LOOP;

  -- Validate total matches
  IF p_receipt_total != v_total_outstanding THEN
    RAISE EXCEPTION 'Payment total (%) does not match invoice outstanding total (%)', p_receipt_total, v_total_outstanding;
  END IF;

  -- Step 1: Create payment header with advisory lock
  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  INSERT INTO public.cn_payment_header (
    payment_id, batch_number, payer_type, payer_id, date_received, remarks
  ) VALUES (
    v_payment_id, p_batch_number, p_payer_type, p_payer_id, p_date_received, p_remarks
  );

  -- Step 2: Insert detail lines
  FOR v_detail IN SELECT * FROM jsonb_array_elements(p_detail_lines)
  LOOP
    v_exp_normalized := NULL;
    v_exp_date := v_detail->>'expiration_date';
    IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
      v_parts := string_to_array(v_exp_date, '/');
      IF array_length(v_parts, 1) = 2 THEN
        v_exp_normalized := '20' || lpad(v_parts[2], 2, '0') || '-' || lpad(v_parts[1], 2, '0') || '-01';
      ELSE
        v_exp_normalized := v_exp_date;
      END IF;
    END IF;

    INSERT INTO public.cn_payment (
      payment_id, payment_code, fund_code, payment_amount,
      mop_code, period, payment_date, bank_code,
      mop_number, cheque_date, mop_account_number, mop_notes1,
      credit_card_code, expiration_date
    ) VALUES (
      v_payment_id,
      v_detail->>'payment_code',
      v_detail->>'fund_code',
      (v_detail->>'payment_amount')::numeric,
      v_detail->>'mop_code',
      v_detail->>'period',
      (v_detail->>'payment_date')::date,
      v_detail->>'bank_code',
      v_detail->>'mop_number',
      CASE WHEN v_detail->>'cheque_date' IS NOT NULL AND v_detail->>'cheque_date' != '' 
           THEN (v_detail->>'cheque_date')::date ELSE NULL END,
      v_detail->>'mop_account_number',
      v_detail->>'mop_notes1',
      v_detail->>'credit_card_code',
      CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END
    );
  END LOOP;

  -- Step 3: Insert cn_invoice_payment rows and update invoices
  FOREACH v_inv_id IN ARRAY p_invoice_ids
  LOOP
    SELECT id, total_amount, paid_amount, (total_amount - paid_amount) AS outstanding
    INTO v_inv
    FROM public.cn_invoices
    WHERE id = v_inv_id;

    INSERT INTO public.cn_invoice_payment (payment_id, invoice_id, amount_applied)
    VALUES (v_payment_id, v_inv_id, v_inv.outstanding);

    UPDATE public.cn_invoices
    SET paid_amount = paid_amount + v_inv.outstanding,
        status = 'P',
        payment_reference = 'PMT-' || v_payment_id::TEXT,
        updated_by = p_user_code,
        updated_at = now()
    WHERE id = v_inv_id;
  END LOOP;

  -- Step 4: Create receipt
  INSERT INTO public.cn_receipt (
    payment_id, status, receipt_total, total_number_of_payments,
    reprint_times, created_by, updated_by
  ) VALUES (
    v_payment_id, 'O', p_receipt_total, p_total_payments,
    0, p_user_code, p_user_code
  )
  RETURNING receipt_id INTO v_receipt_id;

  -- Step 5: Log original print
  INSERT INTO public.cn_receipt_prints (
    receipt_id, printed_by, print_type
  ) VALUES (
    v_receipt_id, p_user_code, 'ORIGINAL'
  );

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'status', 'success'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.pay_invoices_with_receipt(p_batch_number text, p_payer_type text, p_payer_id text, p_payer_name text, p_date_received date, p_remarks text, p_methods jsonb, p_invoice_ids integer[], p_receipt_total numeric, p_user_code text DEFAULT 'SYSTEM'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id INTEGER;
  v_receipt_id INTEGER;
  v_inv_id INTEGER;
  v_inv RECORD;
  v_total_outstanding NUMERIC := 0;
  v_base_currency TEXT;
  v_method_currency TEXT;
  v_method_rate NUMERIC;
  v_comp_arr JSONB[];
  v_meth_arr JSONB[];
  v_comp_idx INTEGER;
  v_meth_idx INTEGER;
  v_comp_remaining NUMERIC;
  v_meth_remaining NUMERIC;
  v_alloc NUMERIC;
  v_detail_count INTEGER := 0;
  v_meth JSONB;
  v_line RECORD;
  v_exp_date TEXT;
  v_exp_normalized TEXT;
  v_exp_parts TEXT[];
  v_fund_code TEXT;
  v_card_machine_id UUID;
  v_mop_code TEXT;
BEGIN
  IF p_batch_number IS NULL OR p_batch_number = '' THEN
    RAISE EXCEPTION 'batch_number is required';
  END IF;
  IF array_length(p_invoice_ids, 1) IS NULL OR array_length(p_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'At least one invoice must be selected';
  END IF;
  IF jsonb_array_length(p_methods) = 0 THEN
    RAISE EXCEPTION 'At least one payment method is required';
  END IF;
  IF p_receipt_total <= 0 THEN
    RAISE EXCEPTION 'receipt_total must be greater than zero';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.cn_batch WHERE batch_number = p_batch_number AND batch_status = 'O'
  ) THEN
    RAISE EXCEPTION 'Batch % is not open', p_batch_number;
  END IF;

  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;

  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured in tb_currencies';
  END IF;

  FOR v_inv_id IN SELECT unnest(p_invoice_ids)
  LOOP
    SELECT id, status, total_amount, paid_amount, (total_amount - paid_amount) AS outstanding
    INTO v_inv
    FROM public.cn_invoices
    WHERE id = v_inv_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice ID % not found', v_inv_id;
    END IF;

    IF v_inv.status NOT IN ('O', 'pending') THEN
      RAISE EXCEPTION 'Invoice ID % has status %, which is not payable', v_inv_id, v_inv.status;
    END IF;

    IF v_inv.outstanding <= 0 THEN
      RAISE EXCEPTION 'Invoice ID % has no outstanding balance', v_inv_id;
    END IF;

    v_total_outstanding := v_total_outstanding + v_inv.outstanding;
  END LOOP;

  IF ABS(p_receipt_total - v_total_outstanding) > 0.01 THEN
    RAISE EXCEPTION 'Payment total (%) does not match invoice outstanding total (%)', p_receipt_total, v_total_outstanding;
  END IF;

  PERFORM pg_advisory_xact_lock(7839201);

  SELECT COALESCE(MAX(payment_id), 0) + 1
  INTO v_payment_id
  FROM public.cn_payment_header;

  INSERT INTO public.cn_payment_header (
    payment_id, batch_number, payer_type, payer_id, date_received, remarks
  ) VALUES (
    v_payment_id, p_batch_number, p_payer_type, p_payer_id, p_date_received, p_remarks
  );

  v_comp_arr := ARRAY[]::jsonb[];
  FOR v_line IN
    SELECT il.invoice_id, il.payment_code, il.amount_base, il.sort_order,
           COALESCE(pt.fund_code, '') AS fund_code
    FROM public.cn_invoice_lines il
    LEFT JOIN public.tb_payment_type pt ON pt.payment_code = il.payment_code
    WHERE il.invoice_id = ANY(p_invoice_ids)
    ORDER BY il.invoice_id, COALESCE(il.sort_order, 0)
  LOOP
    v_comp_arr := v_comp_arr || jsonb_build_object(
      'payment_code', v_line.payment_code,
      'fund_code', v_line.fund_code,
      'amount', v_line.amount_base
    );
  END LOOP;

  IF array_length(v_comp_arr, 1) IS NULL OR array_length(v_comp_arr, 1) = 0 THEN
    RAISE EXCEPTION 'No invoice lines found for the selected invoices';
  END IF;

  v_meth_arr := ARRAY[]::jsonb[];
  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;

    IF v_method_rate IS NULL THEN
      RAISE EXCEPTION 'Currency "%" not found or inactive', v_method_currency;
    END IF;

    -- Server-side validation: CRD/DRD requires card_machine_id
    v_mop_code := v_meth->>'mop_code';
    IF v_mop_code IN ('CRD', 'DRD') AND (v_meth->>'card_machine_id' IS NULL OR v_meth->>'card_machine_id' = '') THEN
      RAISE EXCEPTION 'card_machine_id is required for payment method %', v_mop_code;
    END IF;

    v_meth_arr := v_meth_arr || jsonb_build_object(
      'mop_code', v_mop_code,
      'currency_code', v_method_currency,
      'original_amount', (v_meth->>'original_amount')::numeric,
      'exchange_rate', v_method_rate,
      'base_amount', ROUND((v_meth->>'original_amount')::numeric * v_method_rate, 2),
      'bank_code', v_meth->>'bank_code',
      'mop_number', v_meth->>'mop_number',
      'cheque_date', v_meth->>'cheque_date',
      'mop_account_number', v_meth->>'mop_account_number',
      'mop_notes1', v_meth->>'mop_notes1',
      'credit_card_code', v_meth->>'credit_card_code',
      'expiration_date', v_meth->>'expiration_date',
      'card_machine_id', v_meth->>'card_machine_id'
    );
  END LOOP;

  v_comp_idx := 1;
  v_meth_idx := 1;
  v_comp_remaining := (v_comp_arr[1]->>'amount')::numeric;
  v_meth_remaining := (v_meth_arr[1]->>'base_amount')::numeric;

  WHILE v_comp_idx <= array_length(v_comp_arr, 1) AND v_meth_idx <= array_length(v_meth_arr, 1)
  LOOP
    v_alloc := LEAST(v_comp_remaining, v_meth_remaining);

    IF v_alloc > 0 THEN
      v_exp_normalized := NULL;
      v_exp_date := v_meth_arr[v_meth_idx]->>'expiration_date';
      IF v_exp_date IS NOT NULL AND v_exp_date != '' THEN
        v_exp_parts := string_to_array(v_exp_date, '/');
        IF array_length(v_exp_parts, 1) = 2 THEN
          v_exp_normalized := '20' || lpad(v_exp_parts[2], 2, '0') || '-' || lpad(v_exp_parts[1], 2, '0') || '-01';
        END IF;
      END IF;

      v_method_currency := v_meth_arr[v_meth_idx]->>'currency_code';
      v_method_rate := (v_meth_arr[v_meth_idx]->>'exchange_rate')::numeric;

      v_card_machine_id := NULL;
      IF v_meth_arr[v_meth_idx]->>'card_machine_id' IS NOT NULL AND v_meth_arr[v_meth_idx]->>'card_machine_id' != '' THEN
        v_card_machine_id := (v_meth_arr[v_meth_idx]->>'card_machine_id')::uuid;
      END IF;

      INSERT INTO public.cn_payment (
        payment_id, payment_code, fund_code, payment_amount,
        mop_code, payment_date, bank_code,
        mop_number, cheque_date, mop_account_number, mop_notes1,
        credit_card_code, expiration_date,
        base_currency, currency_conversion_rate, currency_code,
        card_machine_id
      ) VALUES (
        v_payment_id,
        v_comp_arr[v_comp_idx]->>'payment_code',
        v_comp_arr[v_comp_idx]->>'fund_code',
        v_alloc,
        v_meth_arr[v_meth_idx]->>'mop_code',
        p_date_received,
        v_meth_arr[v_meth_idx]->>'bank_code',
        v_meth_arr[v_meth_idx]->>'mop_number',
        CASE WHEN v_meth_arr[v_meth_idx]->>'cheque_date' IS NOT NULL AND v_meth_arr[v_meth_idx]->>'cheque_date' != ''
             THEN (v_meth_arr[v_meth_idx]->>'cheque_date')::date ELSE NULL END,
        v_meth_arr[v_meth_idx]->>'mop_account_number',
        v_meth_arr[v_meth_idx]->>'mop_notes1',
        v_meth_arr[v_meth_idx]->>'credit_card_code',
        CASE WHEN v_exp_normalized IS NOT NULL THEN v_exp_normalized::date ELSE NULL END,
        v_base_currency,
        v_method_rate,
        v_method_currency,
        v_card_machine_id
      );

      v_detail_count := v_detail_count + 1;
    END IF;

    v_comp_remaining := v_comp_remaining - v_alloc;
    v_meth_remaining := v_meth_remaining - v_alloc;

    IF v_comp_remaining <= 0 THEN
      v_comp_idx := v_comp_idx + 1;
      IF v_comp_idx <= array_length(v_comp_arr, 1) THEN
        v_comp_remaining := (v_comp_arr[v_comp_idx]->>'amount')::numeric;
      END IF;
    END IF;

    IF v_meth_remaining <= 0 THEN
      v_meth_idx := v_meth_idx + 1;
      IF v_meth_idx <= array_length(v_meth_arr, 1) THEN
        v_meth_remaining := (v_meth_arr[v_meth_idx]->>'base_amount')::numeric;
      END IF;
    END IF;
  END LOOP;

  FOREACH v_inv_id IN ARRAY p_invoice_ids
  LOOP
    SELECT id, total_amount, paid_amount, (total_amount - paid_amount) AS outstanding
    INTO v_inv
    FROM public.cn_invoices
    WHERE id = v_inv_id;

    INSERT INTO public.cn_invoice_payment (payment_id, invoice_id, amount_applied)
    VALUES (v_payment_id, v_inv_id, v_inv.outstanding);

    UPDATE public.cn_invoices
    SET paid_amount = paid_amount + v_inv.outstanding,
        status = 'P',
        payment_reference = 'PMT-' || v_payment_id::TEXT,
        updated_by = p_user_code,
        updated_at = now()
    WHERE id = v_inv_id;
  END LOOP;

  INSERT INTO public.cn_receipt (
    payment_id, status, receipt_total, total_number_of_payments,
    reprint_times, created_by, updated_by
  ) VALUES (
    v_payment_id, 'O', p_receipt_total, v_detail_count,
    0, p_user_code, p_user_code
  )
  RETURNING receipt_id INTO v_receipt_id;

  INSERT INTO public.cn_receipt_prints (
    receipt_id, printed_by, print_type
  ) VALUES (
    v_receipt_id, p_user_code, 'ORIGINAL'
  );

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'status', 'success',
    'detail_count', v_detail_count
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.prepare_comm_hub_preview(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_module_code text := p_payload->>'module_code';
  v_event_code  text := p_payload->>'event_code';
  v_channel     text := COALESCE(p_payload->>'channel','email');
  v_send_ctx    text := COALESCE(p_payload->>'send_context','preview');
  v_to  jsonb := COALESCE(p_payload->'to_recipients','[]'::jsonb);
  v_cc  jsonb := COALESCE(p_payload->'cc_recipients','[]'::jsonb);
  v_bcc jsonb := COALESCE(p_payload->'bcc_recipients','[]'::jsonb);
  v_sender_id uuid := NULLIF(p_payload->>'sender_profile_id','')::uuid;
  v_sender RECORD;
  v_ctx_in jsonb := public.comm_hub_scrub_protected_keys(COALESCE(p_payload->'context_data','{}'::jsonb));
  v_map RECORD; v_tpl RECORD; v_ver RECORD; v_policy RECORD; v_scenario RECORD;
  v_scenario_found boolean := false;
  v_recipient_name text; v_recipient_name_confirmed boolean := false;
  v_request_no text;
  v_generated_at timestamptz := now();
  v_tokens jsonb;
  v_system_tokens jsonb; v_request_tokens jsonb; v_recipient_tokens jsonb := '{}'::jsonb;
  v_resolver jsonb;
  v_render jsonb;
  v_snapshot_id uuid;
  v_recipient_norm jsonb;
  v_recipient_hash text;
  v_recipient_count int;
  v_first_to text;
  v_correlation uuid := COALESCE(NULLIF(p_payload->>'correlation_id','')::uuid, gen_random_uuid());
  v_scan jsonb; v_raw_count int; v_malformed_count int; v_gate jsonb;
  v_resolver_unresolved jsonb; v_renderer_unresolved jsonb;
  v_resolver_total_unresolved int := 0;
  v_resolver_required_unresolved int := 0;
  v_entry jsonb; v_req_val jsonb;
  v_current_dep_hash text;
  v_certified_dep_hash text;
  v_cert RECORD;
  v_governance_evidence jsonb;
  v_content_hash text;
  v_norm_to jsonb; v_norm_cc jsonb; v_norm_bcc jsonb;
  v_dup_count int;
BEGIN
  IF v_module_code IS NULL OR v_event_code IS NULL THEN
    RAISE EXCEPTION 'module_code and event_code are required';
  END IF;

  v_gate := public.assert_comm_hub_runtime_transition('PREPARE_PREVIEW', jsonb_build_object(
    'module_code', v_module_code, 'event_code', v_event_code, 'channel', v_channel,
    'correlation_id', v_correlation, 'invoked_from', 'prepare_comm_hub_preview'
  ));
  IF (v_gate->>'allowed')::boolean = false THEN
    RAISE EXCEPTION 'runtime_transition_denied: %', v_gate->'denied_reasons';
  END IF;

  SELECT * INTO v_map FROM public.communication_hub_event_template_map
    WHERE module_code = v_module_code AND event_code = v_event_code AND active = true LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'no active template mapped for %/%', v_module_code, v_event_code; END IF;
  SELECT * INTO v_tpl FROM public.core_template WHERE id = v_map.template_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','TEMPLATE_MISSING')));
  END IF;
  SELECT * INTO v_ver FROM public.core_template_version WHERE id = v_tpl.active_version_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','TEMPLATE_VERSION_MISSING')));
  END IF;
  SELECT * INTO v_policy FROM public.communication_hub_recipient_policy LIMIT 1;

  IF v_sender_id IS NULL THEN v_sender_id := NULLIF(v_map.sender_profile_id::text,'')::uuid; END IF;
  IF v_sender_id IS NULL THEN
    SELECT id INTO v_sender_id FROM public.communication_hub_sender_profile
     WHERE is_enabled=true AND is_default=true AND (channel IS NULL OR channel = v_channel)
     ORDER BY updated_at DESC LIMIT 1;
  END IF;
  IF v_sender_id IS NULL THEN
    SELECT id INTO v_sender_id FROM public.communication_hub_sender_profile
     WHERE is_enabled=true AND (channel IS NULL OR channel = v_channel)
     ORDER BY is_default DESC NULLS LAST, updated_at DESC LIMIT 1;
  END IF;
  IF v_sender_id IS NULL THEN
    RAISE EXCEPTION 'sender_profile_missing: no active sender profile is configured for channel %', v_channel;
  END IF;
  SELECT * INTO v_sender FROM public.communication_hub_sender_profile WHERE id = v_sender_id;
  IF NOT FOUND OR COALESCE(v_sender.is_enabled,false)=false
     OR NULLIF(trim(COALESCE(v_sender.from_email,'')),'') IS NULL THEN
    RAISE EXCEPTION 'sender_profile_invalid: sender profile % is unusable', v_sender_id;
  END IF;

  v_recipient_norm := public.comm_hub_normalize_recipient_set(v_to, v_cc, v_bcc);
  IF v_recipient_norm IS NULL OR jsonb_typeof(v_recipient_norm) <> 'object' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_RECIPIENT_HASH_RECOMPUTE_FAILED',
        'detail','normalizer_returned_non_object')));
  END IF;
  v_recipient_hash := v_recipient_norm->>'recipient_set_hash';
  IF v_recipient_hash IS NULL OR length(trim(v_recipient_hash)) = 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_RECIPIENT_HASH_RECOMPUTE_FAILED',
        'detail','recipient_set_hash_missing')));
  END IF;
  v_norm_to  := COALESCE(v_recipient_norm->'to',  '[]'::jsonb);
  v_norm_cc  := COALESCE(v_recipient_norm->'cc',  '[]'::jsonb);
  v_norm_bcc := COALESCE(v_recipient_norm->'bcc', '[]'::jsonb);
  v_recipient_count :=
      COALESCE(jsonb_array_length(v_norm_to),0)
    + COALESCE(jsonb_array_length(v_norm_cc),0)
    + COALESCE(jsonb_array_length(v_norm_bcc),0);
  IF v_recipient_count = 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_FROZEN_RECIPIENT_EVIDENCE_MISSING',
        'detail','recipient_count_zero')));
  END IF;
  SELECT COUNT(*) INTO v_dup_count FROM (
    SELECT x FROM jsonb_array_elements_text(v_norm_to) t(x)
    UNION ALL SELECT x FROM jsonb_array_elements_text(v_norm_cc) t(x)
    UNION ALL SELECT x FROM jsonb_array_elements_text(v_norm_bcc) t(x)
  ) all_addr GROUP BY x HAVING COUNT(*) > 1;
  IF v_dup_count IS NOT NULL AND v_dup_count > 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_RECIPIENT_DUPLICATE_INVALID',
        'detail','address_present_in_multiple_buckets')));
  END IF;

  v_first_to := CASE WHEN jsonb_array_length(v_norm_to) > 0 THEN v_norm_to->>0 ELSE NULL END;

  IF v_policy.active_mode = 'SINGLE_CONFIGURED_RECIPIENT'
     AND v_policy.single_configured_display_name IS NOT NULL
     AND v_policy.single_configured_display_name_confirmed = true THEN
    v_recipient_name := v_policy.single_configured_display_name;
    v_recipient_name_confirmed := true;
  END IF;

  v_request_no := 'TEST-COMM-' || to_char(v_generated_at,'YYYYMMDD') || '-' ||
                  substr(replace(gen_random_uuid()::text,'-',''),1,8);

  v_system_tokens := jsonb_build_object(
    'module_code', v_module_code, 'event_code', v_event_code, 'channel', v_channel,
    'generated_at', to_char(v_generated_at,'YYYY-MM-DD HH24:MI:SS TZ'),
    'current_date', to_char(v_generated_at,'YYYY-MM-DD'),
    'correlation_id', v_correlation::text);
  v_request_tokens := jsonb_build_object(
    'request_no', v_request_no,
    'request_id', gen_random_uuid()::text,
    'requested_at', to_char(v_generated_at,'YYYY-MM-DD HH24:MI:SS TZ'));
  IF v_recipient_name IS NOT NULL THEN
    v_recipient_tokens := v_recipient_tokens || jsonb_build_object('display_name', v_recipient_name);
  END IF;
  IF v_first_to IS NOT NULL THEN
    v_recipient_tokens := v_recipient_tokens || jsonb_build_object('email', v_first_to);
  END IF;

  SELECT * INTO v_scenario FROM public.communication_hub_event_test_scenario
    WHERE module_code=v_module_code AND event_code=v_event_code
      AND channel=v_channel AND is_active=true
    ORDER BY (scenario_key='default') DESC, updated_at DESC LIMIT 1;
  v_scenario_found := FOUND;
  IF NOT v_scenario_found THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','GOVERNED_TEST_SCENARIO_MISSING',
        'detail', jsonb_build_object('module_code',v_module_code,'event_code',v_event_code,'channel',v_channel))));
  END IF;

  BEGIN
    v_resolver := public.resolve_comm_hub_template_variables(
      v_ver.id, v_module_code, v_event_code, v_channel, 'PREVIEW_TEST',
      v_scenario.id, COALESCE(v_scenario.tokens,'{}'::jsonb),
      v_recipient_tokens, v_request_tokens, v_system_tokens);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
        'detail','resolver_raised_exception','sqlstate',SQLSTATE)));
  END;
  IF v_resolver IS NULL OR jsonb_typeof(v_resolver) <> 'object'
     OR jsonb_typeof(COALESCE(v_resolver->'tokens','{}'::jsonb)) <> 'object'
     OR NULLIF(v_resolver->>'resolver_version','') IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
        'detail','resolver_result_shape_invalid')));
  END IF;
  v_resolver_unresolved := COALESCE(v_resolver->'unresolved_variables', '[]'::jsonb);
  IF jsonb_typeof(v_resolver_unresolved) <> 'array' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
        'detail','unresolved_variables_not_array')));
  END IF;

  v_resolver_total_unresolved := jsonb_array_length(v_resolver_unresolved);
  FOR v_entry IN SELECT * FROM jsonb_array_elements(v_resolver_unresolved) LOOP
    IF jsonb_typeof(v_entry) <> 'object' THEN
      RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
        'blockers', jsonb_build_array(jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
          'detail','unresolved_entry_not_object')));
    END IF;
    v_req_val := v_entry->'required';
    IF v_req_val IS NOT NULL THEN
      IF jsonb_typeof(v_req_val) <> 'boolean' THEN
        RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
          'blockers', jsonb_build_array(jsonb_build_object('code','RESOLVER_EVIDENCE_INVALID',
            'detail','required_flag_not_boolean')));
      END IF;
      IF (v_req_val)::text = 'true' THEN
        v_resolver_required_unresolved := v_resolver_required_unresolved + 1;
      END IF;
    END IF;
  END LOOP;
  IF v_resolver_required_unresolved > 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RESOLVER_REQUIRED_UNRESOLVED',
        'detail', jsonb_build_object('required_unresolved_count', v_resolver_required_unresolved))));
  END IF;

  v_tokens := (v_resolver->'tokens') || v_ctx_in || v_recipient_tokens || v_system_tokens || v_request_tokens;

  BEGIN
    v_render := public.render_comm_hub_template_version(v_ver.id, v_tokens, v_channel, 'PREVIEW_TEST');
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RENDERER_EVIDENCE_INVALID',
        'detail','renderer_raised_exception','sqlstate',SQLSTATE)));
  END;
  IF v_render IS NULL OR jsonb_typeof(v_render) <> 'object' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RENDERER_EVIDENCE_INVALID',
        'detail','render_result_not_object')));
  END IF;
  v_content_hash := v_render->>'content_hash';
  IF v_content_hash IS NULL OR length(trim(v_content_hash)) = 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RENDERER_EVIDENCE_INVALID',
        'detail','content_hash_missing')));
  END IF;
  v_renderer_unresolved := COALESCE(v_render->'unresolved_variables', '[]'::jsonb);
  IF jsonb_typeof(v_renderer_unresolved) <> 'array' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RENDERER_EVIDENCE_INVALID',
        'detail','renderer_unresolved_not_array')));
  END IF;
  IF jsonb_array_length(v_renderer_unresolved) > 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RENDERER_UNRESOLVED_PRESENT',
        'detail', jsonb_build_object('count', jsonb_array_length(v_renderer_unresolved)))));
  END IF;

  v_scan := public.scan_comm_hub_raw_placeholders(
    v_render->>'rendered_subject', v_render->>'rendered_body_html', v_render->>'rendered_body_text');
  IF v_scan IS NULL OR jsonb_typeof(v_scan) <> 'object' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RAW_PLACEHOLDER_EVIDENCE_MISSING',
        'detail','scanner_returned_null_or_non_object')));
  END IF;
  IF NULLIF(v_scan->>'scanner_version','') IS DISTINCT FROM 'comm-hub-raw-placeholder-scanner/v2' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','SCANNER_VERSION_MISMATCH',
        'detail', jsonb_build_object('expected','comm-hub-raw-placeholder-scanner/v2',
                                     'actual', v_scan->>'scanner_version'))));
  END IF;
  IF v_scan->'total_occurrences' IS NULL OR jsonb_typeof(v_scan->'total_occurrences') <> 'number' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RAW_PLACEHOLDER_EVIDENCE_MISSING',
        'detail','total_occurrences_missing_or_not_number')));
  END IF;
  IF v_scan->'malformed_brace_count' IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_MISSING')));
  END IF;
  IF jsonb_typeof(v_scan->'malformed_brace_count') <> 'number' THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_INVALID',
        'detail','malformed_brace_count_not_number')));
  END IF;
  v_raw_count       := (v_scan->>'total_occurrences')::int;
  v_malformed_count := (v_scan->>'malformed_brace_count')::int;
  IF v_raw_count < 0 OR v_malformed_count < 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','MALFORMED_BRACE_EVIDENCE_INVALID','detail','negative_count')));
  END IF;
  IF v_malformed_count > 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','MALFORMED_BRACES_PRESENT',
        'detail', jsonb_build_object('count', v_malformed_count))));
  END IF;
  IF v_raw_count > 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','RAW_PLACEHOLDER_RESIDUE',
        'detail', jsonb_build_object('count', v_raw_count))));
  END IF;

  SELECT dependency_hash INTO v_current_dep_hash
    FROM public.build_comm_hub_certification_dependency_hash(v_ver.id);
  IF v_current_dep_hash IS NULL OR length(trim(v_current_dep_hash)) = 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_DEPENDENCY_HASH_UNAVAILABLE',
        'detail','current_dependency_hash_builder_returned_null',
        'template_version_id', v_ver.id::text)));
  END IF;

  SELECT * INTO v_cert FROM public.comm_hub_certification
   WHERE entity_type = 'TEMPLATE_VERSION' AND entity_id = v_ver.id
     AND certification_layer = 'TEMPLATE_STRUCTURE_CERTIFICATION'
     AND certification_kind = 'STANDARD' AND provenance_state = 'AUTHORITATIVE'
     AND result IN ('PASS','CERTIFIED') AND is_stale = false AND superseded_by IS NULL
   ORDER BY certified_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','TEMPLATE_STRUCTURE_CERTIFICATION_REQUIRED',
        'detail', jsonb_build_object('template_version_id', v_ver.id::text))));
  END IF;
  v_certified_dep_hash := v_cert.dependency_hash;
  IF v_certified_dep_hash IS NULL OR length(trim(v_certified_dep_hash)) = 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','CERTIFIED_DEPENDENCY_HASH_MISSING',
        'detail', jsonb_build_object('certification_id', v_cert.id::text))));
  END IF;
  IF v_certified_dep_hash <> v_current_dep_hash THEN
    RETURN jsonb_build_object('status','BLOCKED','correlation_id',v_correlation,
      'blockers', jsonb_build_array(jsonb_build_object('code','PREVIEW_DEPENDENCY_HASH_DRIFT',
        'detail', jsonb_build_object('certified_dependency_hash', v_certified_dep_hash,
          'current_dependency_hash', v_current_dep_hash, 'certification_id', v_cert.id::text))));
  END IF;

  v_governance_evidence := jsonb_build_object(
    'evidence_version','comm-hub-preview-governance-evidence/v1',
    'template_certification', jsonb_build_object(
      'certification_id', v_cert.id::text,
      'certified_dependency_hash', v_certified_dep_hash,
      'current_dependency_hash', v_current_dep_hash, 'hash_match', true,
      'template_version_id', v_ver.id::text, 'template_id', v_tpl.id::text,
      'schema_version', 'comm-hub-template-dependency-manifest/v1'),
    'raw_placeholders',   jsonb_build_object('count', v_raw_count),
    'malformed_braces',   jsonb_build_object('count', v_malformed_count),
    'renderer',           jsonb_build_object('unresolved_count', jsonb_array_length(v_renderer_unresolved)),
    'resolver',           jsonb_build_object(
      'total_unresolved_count', v_resolver_total_unresolved,
      'required_unresolved_count', v_resolver_required_unresolved),
    'recipients',         jsonb_build_object(
      'recipient_set_hash', v_recipient_hash,
      'recipient_count', v_recipient_count, 'duplicates_valid', true),
    'scanner',            jsonb_build_object('version', v_scan->>'scanner_version'),
    'built_at',           to_char(v_generated_at,'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));

  UPDATE public.communication_preview_snapshot
     SET status = 'SUPERSEDED'
   WHERE module_code = v_module_code AND event_code = v_event_code
     AND channel = v_channel AND status = 'PREPARED';

  INSERT INTO public.communication_preview_snapshot(
    id, module_code, event_code, channel, send_context,
    to_recipients, cc_recipients, bcc_recipients, recipient_set_hash,
    template_id, template_version_id, sender_profile_id,
    rendered_subject, rendered_body_html, rendered_body_text,
    subject_hash, body_hash, content_hash, context_hash,
    unresolved_variables, context_data, status, expires_at, created_at,
    resolver_version, resolved_token_bundle, variable_evidence,
    unresolved_variables_normalised, test_scenario_id, test_scenario_hash,
    request_context_values, correlation_id, renderer_unresolved_variables,
    raw_placeholders, raw_placeholder_count, placeholder_scanner_version,
    certified_dependency_hash, current_dependency_hash,
    governance_evidence, event_template_map_id, governance_certification_id
  ) VALUES (
    gen_random_uuid(), v_module_code, v_event_code, v_channel, v_send_ctx,
    -- FIX: store the NORMALIZED recipient arrays instead of raw input
    v_norm_to, v_norm_cc, v_norm_bcc, v_recipient_hash,
    v_tpl.id, v_ver.id, v_sender_id,
    v_render->>'rendered_subject', v_render->>'rendered_body_html', v_render->>'rendered_body_text',
    v_render->>'subject_hash', v_render->>'body_hash', v_content_hash,
    encode(extensions.digest(v_tokens::text,'sha256'),'hex'),
    v_resolver_unresolved,
    v_tokens || jsonb_build_object(
      'request_no', v_request_no,
      'recipient_name_confirmed', v_recipient_name_confirmed,
      'scenario_id',  v_scenario.id::text,
      'scenario_key', v_scenario.scenario_key,
      'template_purpose', v_render->>'template_purpose',
      'canonical_renderer_version', v_render->>'canonical_renderer_version'),
    'PREPARED', now() + interval '24 hours', now(),
    v_resolver->>'resolver_version',
    v_resolver->'tokens',
    v_resolver->'evidence',
    v_resolver_unresolved,
    (v_resolver->>'test_scenario_id')::uuid,
    v_resolver->>'test_scenario_hash',
    v_request_tokens, v_correlation, v_renderer_unresolved,
    v_scan->'placeholders', v_raw_count, v_scan->>'scanner_version',
    v_certified_dep_hash, v_current_dep_hash,
    v_governance_evidence, v_map.id, v_cert.id
  ) RETURNING id INTO v_snapshot_id;

  RETURN (SELECT to_jsonb(s.*) || jsonb_build_object(
            'status','PREPARED', 'correlation_id', v_correlation,
            'raw_placeholder_scan', v_scan,
            'governance_certification_id', v_cert.id)
          FROM public.communication_preview_snapshot s WHERE s.id = v_snapshot_id);
END; $function$;
CREATE OR REPLACE FUNCTION public.prevent_audit_modification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'Audit logs cannot be modified or deleted';
END;
$function$;
CREATE OR REPLACE FUNCTION public.preview_payment_allocation(p_mode text, p_components jsonb, p_methods jsonb, p_invoice_ids integer[] DEFAULT NULL::integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_comp_arr JSONB[];
  v_meth_arr JSONB[];
  v_base_currency TEXT;
  v_method_currency TEXT;
  v_method_rate NUMERIC;
  v_meth JSONB;
  v_line RECORD;
  v_comp_idx INTEGER;
  v_meth_idx INTEGER;
  v_comp_remaining NUMERIC;
  v_meth_remaining NUMERIC;
  v_alloc NUMERIC;
  v_result JSONB := '[]'::jsonb;
BEGIN
  -- Resolve base currency
  SELECT currency_code INTO v_base_currency
  FROM public.tb_currencies
  WHERE is_main_currency = true AND is_active = true
  LIMIT 1;
  IF v_base_currency IS NULL THEN
    RAISE EXCEPTION 'No active main currency configured';
  END IF;

  -- Build component array
  v_comp_arr := ARRAY[]::jsonb[];

  IF p_mode = 'c3' THEN
    -- Use provided components directly
    FOR v_line IN SELECT * FROM jsonb_to_recordset(p_components)
      AS x(payment_code text, fund_code text, amount numeric, sort_order int)
      ORDER BY COALESCE(sort_order, 0)
    LOOP
      v_comp_arr := v_comp_arr || jsonb_build_object(
        'payment_code', v_line.payment_code,
        'fund_code', COALESCE(v_line.fund_code, ''),
        'amount', v_line.amount,
        'description', COALESCE(
          (SELECT payment_type_description FROM public.tb_payment_type WHERE payment_code = v_line.payment_code LIMIT 1),
          v_line.payment_code
        )
      );
    END LOOP;
  ELSIF p_mode = 'invoice' THEN
    -- Fetch from invoice lines
    IF p_invoice_ids IS NULL OR array_length(p_invoice_ids, 1) IS NULL THEN
      RAISE EXCEPTION 'invoice_ids required for invoice mode';
    END IF;
    FOR v_line IN
      SELECT il.payment_code, COALESCE(pt.fund_code, '') AS fund_code,
             il.amount_base AS amount,
             COALESCE(pt.payment_type_description, il.payment_code) AS description
      FROM public.cn_invoice_lines il
      LEFT JOIN public.tb_payment_type pt ON pt.payment_code = il.payment_code
      WHERE il.invoice_id = ANY(p_invoice_ids)
      ORDER BY il.invoice_id, COALESCE(il.sort_order, 0)
    LOOP
      v_comp_arr := v_comp_arr || jsonb_build_object(
        'payment_code', v_line.payment_code,
        'fund_code', v_line.fund_code,
        'amount', v_line.amount,
        'description', v_line.description
      );
    END LOOP;
  ELSE
    RAISE EXCEPTION 'Invalid mode: %. Use c3 or invoice.', p_mode;
  END IF;

  IF array_length(v_comp_arr, 1) IS NULL OR array_length(v_comp_arr, 1) = 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Build method array with server-side rates
  v_meth_arr := ARRAY[]::jsonb[];
  FOR v_meth IN SELECT * FROM jsonb_array_elements(p_methods)
  LOOP
    v_method_currency := COALESCE(v_meth->>'currency_code', v_base_currency);
    SELECT exchange_rate INTO v_method_rate
    FROM public.tb_currencies
    WHERE currency_code = v_method_currency AND is_active = true
    LIMIT 1;
    IF v_method_rate IS NULL THEN
      RAISE EXCEPTION 'Currency "%" not found or inactive', v_method_currency;
    END IF;

    v_meth_arr := v_meth_arr || jsonb_build_object(
      'mop_code', v_meth->>'mop_code',
      'mop_desc', COALESCE(
        (SELECT short_description FROM public.tb_method_of_payment WHERE mop_code = v_meth->>'mop_code' LIMIT 1),
        v_meth->>'mop_code'
      ),
      'currency_code', v_method_currency,
      'original_amount', (v_meth->>'original_amount')::numeric,
      'exchange_rate', v_method_rate,
      'base_amount', ROUND((v_meth->>'original_amount')::numeric * v_method_rate, 2)
    );
  END LOOP;

  IF array_length(v_meth_arr, 1) IS NULL OR array_length(v_meth_arr, 1) = 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Sequential allocation (identical to create_c3_payment_with_receipt / pay_invoices_with_receipt)
  v_comp_idx := 1;
  v_meth_idx := 1;
  v_comp_remaining := (v_comp_arr[1]->>'amount')::numeric;
  v_meth_remaining := (v_meth_arr[1]->>'base_amount')::numeric;

  WHILE v_comp_idx <= array_length(v_comp_arr, 1) AND v_meth_idx <= array_length(v_meth_arr, 1)
  LOOP
    v_alloc := LEAST(v_comp_remaining, v_meth_remaining);

    IF v_alloc > 0 THEN
      v_result := v_result || jsonb_build_object(
        'component', v_comp_arr[v_comp_idx]->>'description',
        'payment_code', v_comp_arr[v_comp_idx]->>'payment_code',
        'fund_code', v_comp_arr[v_comp_idx]->>'fund_code',
        'method', v_meth_arr[v_meth_idx]->>'mop_desc',
        'mop_code', v_meth_arr[v_meth_idx]->>'mop_code',
        'allocated_amount', v_alloc,
        'currency', v_base_currency
      );
    END IF;

    v_comp_remaining := v_comp_remaining - v_alloc;
    v_meth_remaining := v_meth_remaining - v_alloc;

    IF v_comp_remaining <= 0 THEN
      v_comp_idx := v_comp_idx + 1;
      IF v_comp_idx <= array_length(v_comp_arr, 1) THEN
        v_comp_remaining := (v_comp_arr[v_comp_idx]->>'amount')::numeric;
      END IF;
    END IF;

    IF v_meth_remaining <= 0 THEN
      v_meth_idx := v_meth_idx + 1;
      IF v_meth_idx <= array_length(v_meth_arr, 1) THEN
        v_meth_remaining := (v_meth_arr[v_meth_idx]->>'base_amount')::numeric;
      END IF;
    END IF;
  END LOOP;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.probe_comm_hub_dry_run_service_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id jsonb;
  v_role text;
  v_source text;
  v_process boolean := false;
  v_certify boolean := false;
BEGIN
  v_id := public._comm_hub_get_request_role();
  v_role := COALESCE(v_id->>'resolved_role','');
  v_source := COALESCE(v_id->>'role_source','none');

  IF v_role <> 'service_role' THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'probe','comm-hub-dry-run-service-identity/v1',
      'resolved_role', v_role,
      'role_source', v_source,
      'claims_present', COALESCE((v_id->>'claims_present')::boolean, false),
      'service_role_confirmed', false,
      'process_allowlist_match', false,
      'certify_allowlist_match', false,
      'blockers', jsonb_build_array(jsonb_build_object(
        'code','SERVICE_ROLE_REQUIRED','stage','service_identity',
        'resolved_role', v_role,'role_source', v_source)));
  END IF;

  SELECT true INTO v_process FROM public.comm_hub_service_operation_allowlist
    WHERE service_account='comm-hub-dry-run' AND operation='PROCESS_DRY_RUN'
      AND COALESCE(active,true)=true LIMIT 1;
  SELECT true INTO v_certify FROM public.comm_hub_service_operation_allowlist
    WHERE service_account='comm-hub-dry-run' AND operation='CERTIFY_DRY_RUN'
      AND COALESCE(active,true)=true LIMIT 1;

  RETURN jsonb_build_object(
    'allowed', (COALESCE(v_process,false) AND COALESCE(v_certify,false)),
    'probe','comm-hub-dry-run-service-identity/v1',
    'resolved_role', v_role,
    'role_source', v_source,
    'claims_present', COALESCE((v_id->>'claims_present')::boolean, false),
    'service_role_confirmed', true,
    'process_allowlist_match', COALESCE(v_process,false),
    'certify_allowlist_match', COALESCE(v_certify,false),
    'service','comm-hub-dry-run',
    'operations', jsonb_build_array('PROCESS_DRY_RUN','CERTIFY_DRY_RUN')
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.probe_comm_hub_one_real_email_contracts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_checks jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised'; END IF;

  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','begin_comm_hub_one_real_email',
    'signature','public.begin_comm_hub_one_real_email(jsonb)',
    'present', to_regprocedure('public.begin_comm_hub_one_real_email(jsonb)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','create_comm_hub_one_real_email_message',
    'signature','public.create_comm_hub_one_real_email_message(uuid,uuid)',
    'present', to_regprocedure('public.create_comm_hub_one_real_email_message(uuid,uuid)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','reserve_comm_hub_one_real_email_grant',
    'signature','public.reserve_comm_hub_one_real_email_grant(uuid,uuid)',
    'present', to_regprocedure('public.reserve_comm_hub_one_real_email_grant(uuid,uuid)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','consume_comm_hub_one_real_email_grant',
    'signature','public.consume_comm_hub_one_real_email_grant(uuid,uuid,uuid)',
    'present', to_regprocedure('public.consume_comm_hub_one_real_email_grant(uuid,uuid,uuid)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','revoke_comm_hub_one_real_email_grant',
    'signature','public.revoke_comm_hub_one_real_email_grant(uuid,uuid,text)',
    'present', to_regprocedure('public.revoke_comm_hub_one_real_email_grant(uuid,uuid,text)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','reconcile_comm_hub_one_real_email_pre_provider',
    'signature','public.reconcile_comm_hub_one_real_email_pre_provider(uuid,uuid,text)',
    'present', to_regprocedure('public.reconcile_comm_hub_one_real_email_pre_provider(uuid,uuid,text)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','finalize_comm_hub_one_real_email',
    'signature','public.finalize_comm_hub_one_real_email(jsonb)',
    'present', to_regprocedure('public.finalize_comm_hub_one_real_email(jsonb)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','set_comm_hub_real_email_gate',
    'signature','public.set_comm_hub_real_email_gate(text,text,text,boolean,text)',
    'present', to_regprocedure('public.set_comm_hub_real_email_gate(text,text,text,boolean,text)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','record_controlled_live_manual_verification',
    'signature','public.record_controlled_live_manual_verification(jsonb)',
    'present', to_regprocedure('public.record_controlled_live_manual_verification(jsonb)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','check_comm_hub_readiness',
    'signature','public.check_comm_hub_readiness(jsonb)',
    'present', to_regprocedure('public.check_comm_hub_readiness(jsonb)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','get_controlled_live_certification',
    'signature','public.get_controlled_live_certification(uuid)',
    'present', to_regprocedure('public.get_controlled_live_certification(uuid)') IS NOT NULL));
  v_checks := v_checks || jsonb_build_array(jsonb_build_object(
    'id','get_comm_hub_one_real_email_context',
    'signature','public.get_comm_hub_one_real_email_context(text,text,text,uuid)',
    'present', to_regprocedure('public.get_comm_hub_one_real_email_context(text,text,text,uuid)') IS NOT NULL));

  RETURN jsonb_build_object(
    'ok', NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_checks) c WHERE (c->>'present')::boolean = false),
    'checks', v_checks,
    'evaluated_at', now(),
    'note','Signature-only probe. Uses to_regprocedure; creates no execution/grant/request/message/attempt and invokes no provider.'
  );
END $function$;
CREATE OR REPLACE FUNCTION public.probe_comm_hub_one_real_email_runtime()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'evaluated_at', now(),
    'constraints', (
      SELECT jsonb_object_agg(conname, pg_get_constraintdef(oid))
      FROM pg_constraint
      WHERE conname IN (
        'comm_msg_targeted_completeness_chk',
        'comm_msg_targeted_action_chk',
        'communication_message_status_chk',
        'communication_delivery_attempt_status_chk',
        'clc_status_check','clc_provider_outcome_check')),
    'rpcs', (
      SELECT jsonb_object_agg(proname, pg_get_function_identity_arguments(oid))
      FROM pg_proc
      WHERE proname IN (
        'begin_comm_hub_one_real_email',
        'create_comm_hub_one_real_email_message',
        'reserve_comm_hub_one_real_email_grant',
        'consume_comm_hub_one_real_email_grant',
        'revoke_comm_hub_one_real_email_grant',
        'reconcile_comm_hub_one_real_email_pre_provider',
        'finalize_comm_hub_one_real_email',
        'set_comm_hub_one_real_email_message_status',
        'get_comm_hub_one_real_email_context',
        'get_comm_hub_request_auth_context')),
    'allowlist', (
      SELECT jsonb_object_agg(operation, active)
      FROM public.comm_hub_service_operation_allowlist
      WHERE service_account='comm-hub-send-one-real-email'),
    'attempt_columns', (
      SELECT jsonb_agg(column_name ORDER BY ordinal_position)
      FROM information_schema.columns
      WHERE table_schema='public' AND table_name='communication_delivery_attempt')
  );
$function$;
CREATE OR REPLACE FUNCTION public.probe_comm_hub_operator_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor jsonb := public._comm_hub_get_request_actor();
  v_actor_id uuid := NULLIF(v_actor->>'actor_id','')::uuid;
  v_role text := v_actor->>'resolved_role';
BEGIN
  RETURN jsonb_build_object(
    'allowed', v_actor_id IS NOT NULL AND v_role = 'authenticated',
    'actor_id', v_actor_id,
    'actor_source', v_actor->>'actor_source',
    'resolved_role', v_role,
    'role_source', v_actor->>'role_source',
    'claims_present', COALESCE((v_actor->>'claims_present')::boolean,false),
    'token_expires_at', v_actor->'token_expires_at',
    'token_remaining_seconds', v_actor->'token_remaining_seconds'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_c3_employer_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wage_row RECORD;
  v_verifier_code VARCHAR(50);
BEGIN
  IF NEW.posting_status = 'VAC' AND (OLD.posting_status IS NULL OR OLD.posting_status != 'VAC') THEN
    v_verifier_code := COALESCE(NEW.verified_by, 'SYSTEM');

    FOR v_wage_row IN
      SELECT iw.id
      FROM ip_wages iw
      WHERE iw.c3_id = NEW.id
    LOOP
      UPDATE ip_wages
      SET posting_status = 'VAC',
          verified_by = v_verifier_code,
          date_verified = NOW()
      WHERE id = v_wage_row.id;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_c3_voluntary_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_verifier_code VARCHAR(10);
BEGIN
  -- Only process when posting_status changes to 'VAC' and payer_type is 'VC'
  IF NEW.posting_status = 'VAC' AND NEW.payer_type = 'VC' AND 
     (OLD.posting_status IS NULL OR OLD.posting_status != 'VAC') THEN
    
    -- Get the verifier's user code
    v_verifier_code := COALESCE(NEW.verified_by, 'SYSTEM');
    
    -- Insert into ip_vol_contrib_wages
    INSERT INTO public.ip_vol_contrib_wages (
      ssn,
      payment_sequence_no,
      period,
      contrib_amt,
      entered_by,
      date_entered,
      created_at,
      updated_at
    ) VALUES (
      NEW.payer_id,
      NEW.sequence_no,
      NEW.period,
      NEW.emp_ss_amt_calc,
      v_verifier_code,
      NOW() AT TIME ZONE 'UTC',
      NOW() AT TIME ZONE 'UTC',
      NOW() AT TIME ZONE 'UTC'
    )
    ON CONFLICT (ssn, payment_sequence_no, period) 
    DO UPDATE SET
      contrib_amt = EXCLUDED.contrib_amt,
      modified_by = v_verifier_code,
      date_modified = NOW() AT TIME ZONE 'UTC',
      updated_at = NOW() AT TIME ZONE 'UTC';
    
  END IF;
  
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_comm_hub_dry_run_execution(p_execution_id uuid, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc jsonb;
  v_exec public.communication_dry_run_execution%ROWTYPE;
  v_snap public.communication_preview_snapshot%ROWTYPE;
  v_appr public.communication_preview_approval%ROWTYPE;
  v_tr jsonb; v_ev jsonb; v_bind jsonb;
  v_updated int;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation('comm-hub-dry-run','PROCESS_DRY_RUN');
  IF NOT COALESCE((v_svc->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','service_identity',
      'failure_stage','SERVICE_IDENTITY',
      'resolved_role', v_svc->>'resolved_role',
      'role_source', v_svc->>'role_source',
      'blockers', COALESCE(v_svc->'blockers','[]'::jsonb));
  END IF;
  IF p_execution_id IS NULL THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','input',
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_id_required')));
  END IF;

  SELECT * INTO v_exec FROM public.communication_dry_run_execution WHERE id=p_execution_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','execution',
      'blockers', jsonb_build_array(jsonb_build_object('code','execution_not_found')));
  END IF;

  IF v_exec.state IN ('PROCESSED','CERTIFIED') THEN
    RETURN jsonb_build_object('status','PROCESSED','dry_run_execution_id',v_exec.id,
      'state','PROCESSED','idempotent_replay',true,
      'request_id',v_exec.request_id,'message_id',v_exec.message_id,'trace_id',v_exec.trace_id,
      'provider_call_attempted',false);
  END IF;

  SELECT * INTO v_snap FROM public.communication_preview_snapshot WHERE id=v_exec.preview_snapshot_id;
  SELECT * INTO v_appr FROM public.communication_preview_approval  WHERE id=v_exec.preview_approval_id;

  v_tr := public.check_comm_hub_runtime_transition_safe('PROCESS_DRY_RUN',
    jsonb_build_object(
      'module_code', v_exec.module_code, 'event_code', v_exec.event_code, 'channel', v_exec.channel,
      'preview_snapshot_id', v_exec.preview_snapshot_id, 'preview_approval_id', v_exec.preview_approval_id,
      'correlation_id', COALESCE(p_correlation_id, v_snap.correlation_id),
      'service_operation','PROCESS_DRY_RUN','execution_id', v_exec.id,
      'invoked_from','process_comm_hub_dry_run_execution'));
  IF NOT COALESCE((v_tr->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','runtime_transition',
      'blockers', COALESCE(v_tr->'blockers','[]'::jsonb),
      'transition_log_id', v_tr->>'transition_log_id',
      'request_id',v_exec.request_id,'message_id',v_exec.message_id,'trace_id',v_exec.trace_id);
  END IF;

  v_bind := public.check_comm_hub_preview_approval_binding(
    v_exec.preview_approval_id, v_exec.preview_snapshot_id,
    COALESCE(p_correlation_id, v_snap.correlation_id),
    v_appr.content_hash_at_approval, v_appr.recipient_set_hash_at_approval,
    v_appr.configuration_hash_at_approval);
  IF NOT COALESCE((v_bind->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','approval_binding',
      'blockers', COALESCE(v_bind->'blockers','[]'::jsonb),
      'request_id',v_exec.request_id,'message_id',v_exec.message_id,'trace_id',v_exec.trace_id);
  END IF;

  -- Preview evidence must be validated under PROCESS_DRY_RUN,
  -- matching the service operation and runtime transition.
  v_ev := public.check_comm_hub_preview_runtime_evidence(
    v_exec.preview_snapshot_id, v_exec.module_code, v_exec.event_code, v_exec.channel,
    COALESCE(p_correlation_id, v_snap.correlation_id),
    v_appr.content_hash_at_approval, v_appr.recipient_set_hash_at_approval,
    v_appr.template_version_id_at_approval, v_appr.configuration_hash_at_approval,
    'PROCESS_DRY_RUN');
  IF NOT COALESCE((v_ev->>'allowed')::boolean,false) THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','preview_evidence',
      'failure_stage','PREVIEW_EVIDENCE',
      'blockers', COALESCE(v_ev->'blockers','[]'::jsonb),
      'request_id',v_exec.request_id,'message_id',v_exec.message_id,'trace_id',v_exec.trace_id);
  END IF;

  UPDATE public.communication_dry_run_execution
    SET state='DISPATCHING', updated_at=now()
    WHERE id=v_exec.id AND state IN ('STARTED','REQUEST_CREATED');
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RETURN jsonb_build_object('status','BLOCKED','stage','claim',
      'blockers', jsonb_build_array(jsonb_build_object(
        'code','DUPLICATE_OR_INVALID_CLAIM','current_state',v_exec.state)),
      'request_id',v_exec.request_id,'message_id',v_exec.message_id,'trace_id',v_exec.trace_id);
  END IF;

  UPDATE public.communication_dry_run_execution
    SET state='PROCESSED', updated_at=now(), completed_at=now()
    WHERE id=v_exec.id;

  RETURN jsonb_build_object('status','PROCESSED','dry_run_execution_id', v_exec.id,
    'state','PROCESSED','provider_call_attempted', false,
    'request_id',v_exec.request_id,'message_id',v_exec.message_id,'trace_id',v_exec.trace_id,
    'evidence', jsonb_build_object(
      'service_operation','PROCESS_DRY_RUN',
      'runtime_transition','PROCESS_DRY_RUN',
      'preview_evidence_stage','PROCESS_DRY_RUN',
      'transition_log_id', v_tr->>'transition_log_id',
      'approval_evidence_hash', v_appr.canonical_approval_evidence_hash));
END; $function$;
CREATE OR REPLACE FUNCTION public.process_meeting_outcome(p_meeting_id uuid, p_outcome meeting_outcome, p_remarks text DEFAULT NULL::text, p_new_date date DEFAULT NULL::date, p_new_time time without time zone DEFAULT NULL::time without time zone, p_user_id uuid DEFAULT NULL::uuid, p_user_name character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_meeting RECORD;
  v_outcome_config RECORD;
  v_new_status meeting_status;
  v_new_meeting_id UUID;
  v_new_meeting_ref TEXT;
BEGIN
  -- Get meeting details
  SELECT * INTO v_meeting FROM meetings WHERE id = p_meeting_id;
  
  IF v_meeting IS NULL THEN
    RAISE EXCEPTION 'Meeting not found';
  END IF;
  
  -- Get outcome configuration
  SELECT * INTO v_outcome_config
  FROM workflow_action_outcomes
  WHERE action_config_id = v_meeting.action_config_id
    AND outcome_code = p_outcome
    AND is_active = true;
  
  -- Determine new status based on outcome
  CASE p_outcome
    WHEN 'ClosedWithApproval' THEN v_new_status := 'Closed';
    WHEN 'ClosedWithRejection' THEN v_new_status := 'Rejected';
    WHEN 'Reschedule' THEN v_new_status := 'Rescheduled';
    WHEN 'NextSchedule' THEN v_new_status := 'Closed';
    WHEN 'Cancel' THEN v_new_status := 'Cancelled';
    ELSE v_new_status := 'Closed';
  END CASE;
  
  -- Update meeting record
  UPDATE meetings
  SET status = v_new_status,
      outcome = p_outcome,
      outcome_remarks = p_remarks,
      closed_by = p_user_id,
      closed_by_name = p_user_name,
      closed_at = NOW(),
      updated_at = NOW(),
      updated_by = LEFT(p_user_name, 10)
  WHERE id = p_meeting_id;
  
  -- Create history record
  INSERT INTO meeting_history (
    meeting_id,
    old_status,
    new_status,
    action_taken,
    outcome,
    remarks,
    performed_by,
    performed_by_name
  ) VALUES (
    p_meeting_id,
    v_meeting.status,
    v_new_status,
    p_outcome::TEXT,
    p_outcome,
    p_remarks,
    p_user_id,
    p_user_name
  );
  
  -- Handle reschedule - create new meeting
  IF p_outcome = 'Reschedule' AND p_new_date IS NOT NULL THEN
    v_new_meeting_ref := generate_meeting_reference();
    
    INSERT INTO meetings (
      meeting_reference,
      application_reference,
      workflow_instance_id,
      workflow_id,
      step_id,
      action_config_id,
      meeting_type,
      status,
      meeting_date,
      meeting_time,
      contact_person,
      contact_email,
      contact_phone,
      office_address,
      remarks,
      parent_meeting_id,
      reschedule_count,
      scheduled_by,
      scheduled_by_name,
      created_by
    )
    SELECT 
      v_new_meeting_ref,
      application_reference,
      workflow_instance_id,
      workflow_id,
      step_id,
      action_config_id,
      meeting_type,
      'Scheduled',
      p_new_date,
      COALESCE(p_new_time, meeting_time),
      contact_person,
      contact_email,
      contact_phone,
      office_address,
      p_remarks,
      id,
      reschedule_count + 1,
      p_user_id,
      p_user_name,
      LEFT(p_user_name, 10)
    FROM meetings WHERE id = p_meeting_id
    RETURNING id INTO v_new_meeting_id;
    
    -- Create history for new meeting
    INSERT INTO meeting_history (
      meeting_id,
      new_status,
      action_taken,
      new_date,
      new_time,
      remarks,
      performed_by,
      performed_by_name
    ) VALUES (
      v_new_meeting_id,
      'Scheduled',
      'RESCHEDULED',
      p_new_date,
      COALESCE(p_new_time, v_meeting.meeting_time),
      'Rescheduled from ' || v_meeting.meeting_reference,
      p_user_id,
      p_user_name
    );
  END IF;
  
  -- Process workflow transition if outcome config exists
  IF v_outcome_config.id IS NOT NULL THEN
    -- Handle workflow step transition
    IF v_outcome_config.next_step_type = 'next' AND v_outcome_config.next_step_id IS NOT NULL THEN
      UPDATE workflow_instances
      SET current_step_id = v_outcome_config.next_step_id,
          status = 'InProgress',
          updated_at = NOW()
      WHERE id = v_meeting.workflow_instance_id;
    ELSIF v_outcome_config.next_step_type = 'end' AND v_outcome_config.end_state IS NOT NULL THEN
      UPDATE workflow_instances
      SET status = v_outcome_config.end_state::text::workflow_instance_status,
          completed_at = NOW(),
          updated_at = NOW()
      WHERE id = v_meeting.workflow_instance_id;
    END IF;
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'meeting_id', p_meeting_id,
    'new_status', v_new_status,
    'new_meeting_id', v_new_meeting_id,
    'new_meeting_reference', v_new_meeting_ref,
    'message', 'Meeting outcome processed successfully'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_ready_to_print_card(p_unique_uuid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_config RECORD;
  v_perm_card_date date;
  v_card_expiration date;
BEGIN
  SELECT * INTO v_record FROM ip_master WHERE unique_uuid = p_unique_uuid;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insured person not found');
  END IF;

  IF v_record.status <> 'V' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insured person status must be Verified (V) to print card. Current status: ' || v_record.status);
  END IF;

  SELECT * INTO v_config FROM ip_card_config WHERE is_active = true LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'IP Card configuration not found. Please configure card settings in Admin.');
  END IF;

  IF v_config.date_source = 'registered_date' THEN
    IF v_record.registration_date IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Registration date is not set for this insured person.');
    END IF;
    v_perm_card_date := v_record.registration_date;
  ELSE
    v_perm_card_date := CURRENT_DATE;
  END IF;

  v_card_expiration := v_perm_card_date + (v_config.card_validity_years || ' years')::interval;

  UPDATE ip_master
  SET status = 'A',
      perm_card_date = v_perm_card_date,
      card_expiration = v_card_expiration,
      date_modified = now()
  WHERE unique_uuid = p_unique_uuid;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Card ready. Status updated to Active.',
    'perm_card_date', v_perm_card_date,
    'card_expiration', v_card_expiration,
    'date_source', v_config.date_source,
    'validity_years', v_config.card_validity_years
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.promote_comm_hub_event_to_manual_production(p_module_code text, p_event_code text, p_channel text, p_reason text, p_typed_confirmation text, p_expected_runtime_mode_version bigint DEFAULT NULL::bigint, p_one_real_email_certification_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_ore_id uuid := p_one_real_email_certification_id;
  v_cert_res jsonb;
  v_mode_res jsonb;
  v_norm_res jsonb;
  v_channel text := coalesce(p_channel,'email');
  v_did_mode_transition boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;

  -- 1. Lock the singleton settings row.
  SELECT * INTO v_settings
    FROM public.communication_hub_control_settings
   WHERE singleton_guard = 'primary'
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'settings_singleton_missing' USING ERRCODE='P0002';
  END IF;

  -- 2. runtime_mode_version concurrency — compared ONLY against
  --    runtime_mode_version. Structured non-mutating return on mismatch.
  IF p_expected_runtime_mode_version IS NOT NULL
     AND p_expected_runtime_mode_version <> coalesce(v_settings.runtime_mode_version,0) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'phase', 'RUNTIME_MODE_VERSION_CONFLICT',
      'expected_runtime_mode_version', p_expected_runtime_mode_version,
      'current_runtime_mode_version', v_settings.runtime_mode_version,
      'configuration_version', v_settings.configuration_version,
      'current_operating_mode', v_settings.operating_mode::text,
      'next_action', 'REFRESH_AND_RECONCILE'
    );
  END IF;

  -- 3. Refuse Emergency Stop.
  IF lower(coalesce(v_settings.operating_mode::text,'')) = 'emergency_stop' THEN
    RAISE EXCEPTION 'emergency_stop_active' USING ERRCODE='22023';
  END IF;

  -- 4. Resolve One Real Email evidence if not supplied.
  IF v_ore_id IS NULL THEN
    SELECT id INTO v_ore_id
      FROM public.communication_controlled_live_certification
     WHERE module_code=p_module_code AND event_code=p_event_code AND channel=v_channel
       AND certification_kind='ONE_REAL_EMAIL'
       AND invalidated_at IS NULL
       AND status IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY')
       AND coalesce(manual_verification_status,'')='CONFIRMED'
     ORDER BY manual_verified_at DESC NULLS LAST, created_at DESC
     LIMIT 1;
    IF v_ore_id IS NULL THEN
      RAISE EXCEPTION 'no_valid_one_real_email_certification' USING ERRCODE='22023';
    END IF;
  END IF;

  -- 5. Certify / retain the event as live_manual_only using existing contract.
  v_cert_res := public.certify_comm_hub_event_manual_production(jsonb_build_object(
    'module_code', p_module_code,
    'event_code', p_event_code,
    'channel', v_channel,
    'one_real_email_certification_id', v_ore_id,
    'reason', p_reason,
    'typed_confirmation', p_typed_confirmation
  ));
  IF coalesce((v_cert_res->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'phase', 'certify_event',
      'error', (v_cert_res->>'error'),
      'result', v_cert_res,
      'runtime_mode_version', v_settings.runtime_mode_version,
      'configuration_version', v_settings.configuration_version
    );
  END IF;

  -- 6. Close the scoped One Real Email testing gate (best-effort).
  BEGIN
    PERFORM public.close_comm_hub_one_real_email_gate_after_stage6(
      p_module_code, p_event_code, v_channel,
      coalesce(p_reason,'promotion_to_manual_production'));
  EXCEPTION WHEN undefined_function THEN NULL;
  END;

  -- 7. Mode transition via canonical mode core using CURRENT
  --    configuration_version (never runtime_mode_version).
  IF lower(coalesce(v_settings.operating_mode::text,'')) <> 'manual_production' THEN
    v_mode_res := public.apply_communication_release_mode(
      'MANUAL_PRODUCTION',
      p_reason,
      v_settings.configuration_version::int,
      p_module_code, p_event_code, v_channel);
    v_did_mode_transition := true;
    -- Refresh locked row snapshot after mode transition.
    SELECT * INTO v_settings
      FROM public.communication_hub_control_settings
     WHERE singleton_guard='primary';
  ELSE
    v_mode_res := jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'new_mode', 'MANUAL_PRODUCTION',
      'configuration_version', v_settings.configuration_version,
      'runtime_mode_version', v_settings.runtime_mode_version
    );
  END IF;

  -- 8. Run Manual Production normalization core (also when mode was
  --    already MANUAL_PRODUCTION).
  v_norm_res := public._normalize_comm_hub_manual_production_controls(
                  v_uid,
                  coalesce(p_reason,'promotion_to_manual_production'),
                  'promote_comm_hub_event_to_manual_production');
  IF coalesce((v_norm_res->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'phase', coalesce(v_norm_res->>'phase','normalize_failed'),
      'certification', v_cert_res,
      'mode', v_mode_res,
      'normalize', v_norm_res
    );
  END IF;

  -- Refresh again to report authoritative values.
  SELECT * INTO v_settings
    FROM public.communication_hub_control_settings
   WHERE singleton_guard='primary';

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', (NOT v_did_mode_transition)
                  AND coalesce((v_norm_res->>'no_change')::boolean,false)
                  AND coalesce((v_cert_res->>'idempotent')::boolean, false),
    'no_change', (NOT v_did_mode_transition)
                 AND coalesce((v_norm_res->>'no_change')::boolean,false),
    'next_action', 'DISPATCH_MANUAL_OBSERVATION',
    'event_certification_id', v_cert_res->>'event_certification_id',
    'event_status', 'live_manual_only',
    'controls_normalized', coalesce((v_norm_res->>'controls_normalized')::boolean,false),
    'changed_fields', coalesce(v_norm_res->'changed_fields','[]'::jsonb),
    'runtime_mode_version', v_settings.runtime_mode_version,
    'configuration_version', v_settings.configuration_version,
    'automation_generation', v_settings.automation_generation,
    'operating_mode', v_settings.operating_mode::text,
    'automation_state', v_settings.automation_state,
    'certification', v_cert_res,
    'mode', v_mode_res,
    'normalize', v_norm_res
  );
END $function$;
CREATE OR REPLACE FUNCTION public.promote_comm_hub_revalidation_baseline(p_cycle_id uuid, p_typed_phrase text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := public._chrc_require_admin();
  v_cycle record;
  v_prev_cert_snapshot jsonb;
  v_missing_stages text[];
BEGIN
  IF p_typed_phrase IS DISTINCT FROM 'PROMOTE REVALIDATION BASELINE' THEN
    RAISE EXCEPTION 'typed_phrase_mismatch';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 6 THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle
    WHERE id = p_cycle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'cycle_not_found'; END IF;
  IF v_cycle.status NOT IN ('CONFIRMED','READY_FOR_PROMOTION') THEN
    RAISE EXCEPTION 'cycle_not_promotable: %', v_cycle.status;
  END IF;
  IF v_cycle.inbox_confirmation_status <> 'CONFIRMED' THEN
    RAISE EXCEPTION 'inbox_not_confirmed';
  END IF;
  IF v_cycle.controlled_email_execution_id IS NULL THEN
    RAISE EXCEPTION 'no_provider_execution';
  END IF;

  -- Verify all required stages have PASSED/ACCEPTED_UNCHANGED
  SELECT array_agg(s) INTO v_missing_stages
    FROM jsonb_array_elements_text(v_cycle.required_stages) t(s)
   WHERE s NOT IN ('BASELINE_PROMOTION')
     AND NOT EXISTS (
       SELECT 1 FROM public.communication_hub_revalidation_stage_result r
        WHERE r.cycle_id = p_cycle_id AND r.stage_code::text = s
          AND r.status IN ('PASSED','ACCEPTED_UNCHANGED')
     );
  IF v_missing_stages IS NOT NULL AND array_length(v_missing_stages,1) > 0 THEN
    RAISE EXCEPTION 'required_stages_missing: %', array_to_string(v_missing_stages,',');
  END IF;

  -- Snapshot current event certification for immutable audit
  SELECT to_jsonb(c) INTO v_prev_cert_snapshot
    FROM public.communication_hub_event_certification c
   WHERE c.id = v_cycle.baseline_event_certification_id;

  -- Record promotion stage
  INSERT INTO public.communication_hub_revalidation_stage_result(
    cycle_id, stage_code, status, evidence, completed_by
  ) VALUES (
    p_cycle_id, 'BASELINE_PROMOTION', 'PASSED',
    jsonb_build_object(
      'previous_event_certification', v_prev_cert_snapshot,
      'previous_ore_id', v_cycle.baseline_ore_certification_id,
      'previous_lineage_id', v_cycle.baseline_production_lineage_id,
      'promoted_reason', p_reason
    ), v_uid
  );

  -- Advance the cycle to PROMOTED (baseline swap performed by follow-up
  -- migration once integration with communication_hub_event_certification
  -- is agreed; refuse to silently rewrite production anchor here).
  UPDATE public.communication_hub_revalidation_cycle
     SET status = 'PROMOTED',
         promotion_status = 'PROMOTED',
         promoted_at = now(),
         promoted_by = v_uid
   WHERE id = p_cycle_id;

  RETURN jsonb_build_object(
    'ok', true,
    'previous_event_certification', v_prev_cert_snapshot,
    'requires_operator_anchor_swap', true,
    'note', 'Promotion recorded; production anchor swap requires explicit lineage-update RPC to preserve immutability.'
  );
END $function$;
CREATE OR REPLACE FUNCTION public.protect_admin_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  admin_role_id UUID;
BEGIN
  -- Get the Admin role ID
  SELECT id INTO admin_role_id FROM roles WHERE role_name = 'Admin';
  
  IF TG_OP = 'DELETE' AND OLD.role_id = admin_role_id THEN
    RAISE EXCEPTION 'Cannot delete Admin role permissions';
  END IF;
  
  IF TG_OP = 'UPDATE' AND OLD.role_id = admin_role_id THEN
    IF NEW.is_granted = false THEN
      RAISE EXCEPTION 'Cannot revoke Admin role permissions';
    END IF;
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_c3_detail(p_payer_id text, p_month text, p_year text, p_sequence_no text, p_payer_type text, p_c3_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period DATE;
  v_period_end DATE;
  v_record RECORD;
  v_wages JSONB;
  v_result JSONB;
  v_total_ip_ss NUMERIC := 0;
  v_total_er_ss NUMERIC := 0;
  v_total_ip_levy NUMERIC := 0;
  v_total_er_levy NUMERIC := 0;
  v_total_ip_pe NUMERIC := 0;
  v_total_er_pe NUMERIC := 0;
  v_is_nwd BOOLEAN;
BEGIN
  v_period := make_date(p_year::INT, p_month::INT, 1);
  v_period_end := (v_period + interval '1 month')::DATE;
  v_is_nwd := (UPPER(p_c3_type) = 'NW');

  SELECT * INTO v_record
  FROM cn_c3_reported r
  WHERE TRIM(r.payer_id) = TRIM(p_payer_id)
    AND TRIM(r.payer_type) = TRIM(p_payer_type)
    AND r.period >= v_period
    AND r.period < v_period_end
    AND r.sequence_no = p_sequence_no::INT
    AND r.posting_status = 'VAC'
    AND r.is_for_director = v_is_nwd;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'C3 not found', 'code', 'NOT_FOUND');
  END IF;

  -- Pre-aggregate contribution totals from ip_wages
  SELECT
    COALESCE(SUM(w.ip_ss_amt), 0),
    COALESCE(SUM(w.er_ss_amt), 0),
    COALESCE(SUM(w.ip_levy_amt), 0),
    COALESCE(SUM(w.er_levy_amt), 0),
    COALESCE(SUM(w.ip_pe_amt), 0),
    COALESCE(SUM(w.er_ei_amt), 0)
  INTO v_total_ip_ss, v_total_er_ss, v_total_ip_levy, v_total_er_levy, v_total_ip_pe, v_total_er_pe
  FROM ip_wages w
  WHERE TRIM(w.payer_id) = TRIM(p_payer_id)
    AND TRIM(w.payer_type) = TRIM(p_payer_type)
    AND w.period >= v_period
    AND w.period < v_period_end
    AND w.sequence_no = p_sequence_no::INT
    AND w.posting_status = 'VAC';

  -- Fallback: if all wage-level aggregates are zero, use header-level calculated fields
  IF v_total_ip_ss = 0 AND v_total_er_ss = 0 AND v_total_ip_levy = 0
     AND v_total_er_levy = 0 AND v_total_ip_pe = 0 AND v_total_er_pe = 0 THEN
    v_total_ip_ss := COALESCE(v_record.emp_ss_amt_calc, 0);
    v_total_ip_levy := COALESCE(v_record.emp_levy_amt_calc, 0);
    v_total_ip_pe := COALESCE(v_record.emp_pe_amt_calc, 0);
  END IF;

  -- Build wages array
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'ssn', TRIM(w.ssn),
      'firstName', COALESCE(
        (SELECT TRIM(m.firstname) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        SPLIT_PART(COALESCE(w.employee_name, ''), ' ', 1)
      ),
      'surName', COALESCE(
        (SELECT TRIM(m.surname) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        CASE WHEN POSITION(' ' IN COALESCE(w.employee_name, '')) > 0
             THEN SUBSTRING(w.employee_name FROM POSITION(' ' IN w.employee_name) + 1)
             ELSE '' END
      ),
      'birthDate', COALESCE(
        (SELECT TO_CHAR(m.dob, 'YYYY-MM-DD') FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        ''
      ),
      'payPeriod', COALESCE(w.pay_period, 'M'),
      'paidCode1', COALESCE(w.paid_code1, '0'),
      'paidCode2', COALESCE(w.paid_code2, '0'),
      'paidCode3', COALESCE(w.paid_code3, '0'),
      'paidCode4', COALESCE(w.paid_code4, '0'),
      'paidCode5', COALESCE(w.paid_code5, '0'),
      'paidCode6', COALESCE(w.paid_code6, '0'),
      'paidCode7', COALESCE(w.paid_code7, '0'),
      'wagesPaid1', COALESCE(w.wages_paid1, 0),
      'wagesPaid2', COALESCE(w.wages_paid2, 0),
      'wagesPaid3', COALESCE(w.wages_paid3, 0),
      'wagesPaid4', COALESCE(w.wages_paid4, 0),
      'wagesPaid5', COALESCE(w.wages_paid5, 0),
      'wagesPaid6', COALESCE(w.wages_paid6, 0),
      'wagesPaid7', COALESCE(w.wages_paid7, 0),
      'ipSsAmt', COALESCE(w.ip_ss_amt, 0),
      'erSsAmt', COALESCE(w.er_ss_amt, 0),
      'ipLevyAmt', COALESCE(w.ip_levy_amt, 0),
      'erLevyAmt', COALESCE(w.er_levy_amt, 0),
      'ipPeAmt', COALESCE(w.ip_pe_amt, 0),
      'erEiAmt', COALESCE(w.er_ei_amt, 0),
      'startDate', COALESCE(TO_CHAR(w.date_entered, 'YYYY-MM-DD'), ''),
      'endDate', COALESCE(TO_CHAR(w.date_verified, 'YYYY-MM-DD'), ''),
      'wageType', NULL
    ) ORDER BY w.input_seq_no, w.ssn
  ), '[]'::jsonb)
  INTO v_wages
  FROM ip_wages w
  WHERE TRIM(w.payer_id) = TRIM(p_payer_id)
    AND TRIM(w.payer_type) = TRIM(p_payer_type)
    AND w.period >= v_period
    AND w.period < v_period_end
    AND w.sequence_no = p_sequence_no::INT
    AND w.posting_status = 'VAC';

  v_result := jsonb_build_object(
    'c3Header', jsonb_build_object(
      'c3Status', 'S',
      'numberEmployed', COALESCE(v_record.number_employed, 0),
      'calcEmpSsAmt', COALESCE(v_record.emp_ss_amt_calc, 0),
      'calcEmpLevyAmt', COALESCE(v_record.emp_levy_amt_calc, 0),
      'calcEmpPeAmt', COALESCE(v_record.emp_pe_amt_calc, 0),
      'totalEmpSsFines', COALESCE(v_record.emp_ss_fines_due, 0),
      'totalEmpLevyPenalty', COALESCE(v_record.emp_levy_penalty_amt, 0),
      'totalEmpPePenalty', COALESCE(v_record.emp_pe_penalty_amt, 0),
      'totalEmpSsContributions', v_total_ip_ss,
      'totalErSsContributions', v_total_er_ss,
      'totalEmpLevyContributions', v_total_ip_levy,
      'totalErLevyContributions', v_total_er_levy,
      'totalEmpPeContributions', v_total_ip_pe,
      'totalErPeContributions', v_total_er_pe,
      'dateReceived', COALESCE(TO_CHAR(v_record.date_received, 'YYYY-MM-DD'), ''),
      'receivedBy', COALESCE(TRIM(v_record.received_by), 'SYSTEM'),
      'submittedByName', COALESCE(TRIM(v_record.entered_by), ''),
      'submittedByEmail', '',
      'nilReturn', CASE WHEN v_record.nil_return THEN 1 ELSE 0 END,
      'isForDirector', v_record.is_for_director
    ),
    'ipWages', v_wages
  );

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_c3_last_submitted(p_payer_id text, p_payer_type text, p_sequence_no text, p_c3_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_is_nwd BOOLEAN;
BEGIN
  v_is_nwd := (UPPER(p_c3_type) = 'NW');

  SELECT * INTO v_record
  FROM cn_c3_reported r
  WHERE TRIM(r.payer_id) = TRIM(p_payer_id)
    AND TRIM(r.payer_type) = TRIM(p_payer_type)
    AND r.sequence_no = p_sequence_no::INT
    AND r.posting_status = 'VAC'
    AND r.is_for_director = v_is_nwd
  ORDER BY r.period DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'No submitted C3 found', 'code', 'NOT_FOUND');
  END IF;

  RETURN public_api_c3_detail(
    p_payer_id,
    EXTRACT(MONTH FROM v_record.period)::TEXT,
    EXTRACT(YEAR FROM v_record.period)::TEXT,
    p_sequence_no,
    p_payer_type,
    p_c3_type
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_c3_range(p_payer_id text, p_payer_type text, p_start_period text, p_end_period text, p_c3_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start_date DATE;
  v_end_date DATE;
  v_start_month INT;
  v_start_year INT;
  v_end_month INT;
  v_end_year INT;
  v_result JSONB;
  v_is_nwd BOOLEAN;
BEGIN
  IF length(p_start_period) = 6 AND p_start_period ~ '^\d{6}$' THEN
    v_start_month := substring(p_start_period, 1, 2)::INT;
    v_start_year := substring(p_start_period, 3, 4)::INT;
  ELSE
    RETURN jsonb_build_object('error', 'Invalid startDate format. Expected MMYYYY (e.g., 012025)');
  END IF;

  IF length(p_end_period) = 6 AND p_end_period ~ '^\d{6}$' THEN
    v_end_month := substring(p_end_period, 1, 2)::INT;
    v_end_year := substring(p_end_period, 3, 4)::INT;
  ELSE
    RETURN jsonb_build_object('error', 'Invalid endDate format. Expected MMYYYY (e.g., 122025)');
  END IF;

  v_start_date := make_date(v_start_year, v_start_month, 1);
  v_end_date := (make_date(v_end_year, v_end_month, 1) + interval '1 month' - interval '1 day')::DATE;

  -- Determine NWD filter based on c3_type
  v_is_nwd := (UPPER(p_c3_type) = 'NW');

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'month', EXTRACT(MONTH FROM r.period)::INT,
      'year', EXTRACT(YEAR FROM r.period)::INT,
      'seqNo', r.sequence_no,
      'payerType', TRIM(r.payer_type),
      'c3Type', CASE WHEN TRIM(r.payer_type) = 'SE' THEN 'EE' ELSE p_c3_type END,
      'isForDirector', r.is_for_director
    ) ORDER BY r.period, r.sequence_no
  ), '[]'::jsonb)
  INTO v_result
  FROM cn_c3_reported r
  WHERE TRIM(r.payer_id) = TRIM(p_payer_id)
    AND TRIM(r.payer_type) = TRIM(p_payer_type)
    AND r.posting_status = 'VAC'
    AND r.period >= v_start_date
    AND r.period <= v_end_date
    AND r.is_for_director = v_is_nwd;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_employees_by_last_c3(p_registration_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_period DATE;
  v_last_seq INT;
  v_period_start DATE;
  v_period_end DATE;
  v_result JSONB;
BEGIN
  SELECT r.period, r.sequence_no
  INTO v_last_period, v_last_seq
  FROM cn_c3_reported r
  WHERE TRIM(r.payer_id) = TRIM(p_registration_number)
    AND TRIM(r.payer_type) = 'ER'
    AND r.posting_status = 'VAC'
  ORDER BY r.period DESC, r.sequence_no DESC
  LIMIT 1;

  IF v_last_period IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Compute month range from the header's period
  v_period_start := date_trunc('month', v_last_period)::DATE;
  v_period_end := (v_period_start + interval '1 month')::DATE;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'socialSecurityNumber', TRIM(w.ssn),
      'firstName', COALESCE(
        (SELECT TRIM(m.firstname) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        SPLIT_PART(COALESCE(w.employee_name, ''), ' ', 1)
      ),
      'surName', COALESCE(
        (SELECT TRIM(m.surname) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        CASE WHEN POSITION(' ' IN COALESCE(w.employee_name, '')) > 0 
             THEN SUBSTRING(w.employee_name FROM POSITION(' ' IN w.employee_name) + 1) 
             ELSE '' END
      ),
      'middleName', COALESCE(
        (SELECT TRIM(m.middle_name) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        ''
      ),
      'birthDate', COALESCE(
        (SELECT TO_CHAR(m.dob, 'YYYY-MM-DD') FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        ''
      ),
      'payPeriod', COALESCE(w.pay_period, 'M'),
      'startDate', COALESCE(TO_CHAR(w.date_entered, 'YYYY-MM-DD'), ''),
      'endDate', COALESCE(TO_CHAR(w.date_verified, 'YYYY-MM-DD'), ''),
      'wages', COALESCE(w.total_wages, 0)
    ) ORDER BY w.ssn
  ), '[]'::jsonb)
  INTO v_result
  FROM ip_wages w
  WHERE TRIM(w.payer_id) = TRIM(p_registration_number)
    AND TRIM(w.payer_type) = 'ER'
    AND w.period >= v_period_start
    AND w.period < v_period_end
    AND w.sequence_no = v_last_seq
    AND w.posting_status = 'VAC';

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_er_master_details(p_reg_no text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec RECORD;
  v_status_text TEXT;
BEGIN
  IF NULLIF(TRIM(p_email), '') IS NULL THEN
    RETURN jsonb_build_object('error', 'Email is required', 'code', 'BAD_REQUEST');
  END IF;

  SELECT * INTO v_rec
  FROM er_master
  WHERE TRIM(regno) = TRIM(p_reg_no);

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Employer not found', 'code', 'NOT_FOUND');
  END IF;

  IF LOWER(TRIM(COALESCE(v_rec.email, ''))) <> LOWER(TRIM(p_email)) THEN
    RETURN jsonb_build_object('error', 'Email does not match records', 'code', 'NOT_FOUND');
  END IF;

  IF UPPER(TRIM(COALESCE(v_rec.status, ''))) <> 'A' THEN
    CASE UPPER(TRIM(COALESCE(v_rec.status, '')))
      WHEN 'I' THEN v_status_text := 'Inactive';
      WHEN 'C' THEN v_status_text := 'Closed';
      WHEN 'P' THEN v_status_text := 'Pending';
      ELSE v_status_text := COALESCE(v_rec.status, 'Unknown');
    END CASE;

    RETURN jsonb_build_object(
      'error', 'Employer is not active (Status: ' || v_status_text || ')',
      'code', 'NOT_ACTIVE'
    );
  END IF;

  RETURN jsonb_build_object(
    'companyName', COALESCE(TRIM(v_rec.name), ''),
    'tradeName', COALESCE(TRIM(v_rec.trade_name), ''),
    'contactPerson', COALESCE(TRIM(v_rec.name), ''),
    'address1', COALESCE(TRIM(v_rec.hq_addr1), ''),
    'address2', COALESCE(TRIM(v_rec.hq_addr2), ''),
    'city', '',
    'postalCode', '',
    'country', 'St. Kitts and Nevis',
    'phone', COALESCE(TRIM(v_rec.phone), ''),
    'mobile', COALESCE(TRIM(v_rec.mobile), ''),
    'fax', COALESCE(TRIM(v_rec.fax), ''),
    'email', COALESCE(TRIM(v_rec.email), ''),
    'dateRegistered', COALESCE(TO_CHAR(v_rec.registration_date, 'DD/MM/YYYY'), ''),
    'officeCode', COALESCE(TRIM(v_rec.office_code), ''),
    'isLevyExempt', false,
    'c3RegnStatusCode', 'D',
    'c3RegnStatusText', 'Not Registered',
    'statusCode', 'A',
    'statusText', 'Active',
    'employerType', 'ER',
    'isActive', 'true',
    'prntRegNo', COALESCE(TRIM(v_rec.parent_regno), ''),
    'firstName', '',
    'lastName', '',
    'regNo', COALESCE(TRIM(v_rec.regno), '')
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_get_receipt(p_receipt_no text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_receipt RECORD;
  v_result JSONB;
BEGIN
  SELECT r.*, ph.payer_id, ph.payer_type, ph.batch_number, ph.date_received
  INTO v_receipt
  FROM cn_receipt r
  JOIN cn_payment_header ph ON ph.payment_id = r.payment_id
  WHERE TRIM(r.receipt_number) = TRIM(p_receipt_no)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Receipt not found', 'code', 'NOT_FOUND');
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'batchNumber', COALESCE(v_receipt.batch_number, ''),
      'batchDate', COALESCE(TO_CHAR(v_receipt.date_received, 'YYYY-MM-DD'), ''),
      'mopCode', COALESCE(TRIM(p.mop_code), ''),
      'paymentAmount', COALESCE(p.payment_amount, 0),
      'fundCode', COALESCE(TRIM(p.fund_code), ''),
      'paymentCode', COALESCE(TRIM(p.payment_code), ''),
      'payerId', COALESCE(TRIM(v_receipt.payer_id), ''),
      'payerType', COALESCE(TRIM(v_receipt.payer_type), ''),
      'periodMonth', COALESCE(EXTRACT(MONTH FROM p.period)::INT, 0),
      'periodYear', COALESCE(EXTRACT(YEAR FROM p.period)::INT, 0)
    ) ORDER BY p.payment_sequence_no
  ), '[]'::jsonb)
  INTO v_result
  FROM cn_payment p
  WHERE p.payment_id = v_receipt.payment_id;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_insert_c3_reported(p_payer_id text, p_payer_type text, p_period text, p_payer_name text DEFAULT NULL::text, p_payer_address text DEFAULT NULL::text, p_number_employed integer DEFAULT NULL::integer, p_total_wages numeric DEFAULT NULL::numeric, p_nil_return boolean DEFAULT false, p_notes text DEFAULT NULL::text, p_entered_by text DEFAULT 'API'::text, p_received_by text DEFAULT NULL::text, p_date_received text DEFAULT NULL::text, p_emp_ss_amt_calc numeric DEFAULT NULL::numeric, p_emp_levy_amt_calc numeric DEFAULT NULL::numeric, p_emp_pe_amt_calc numeric DEFAULT NULL::numeric, p_emp_ss_fines_due numeric DEFAULT NULL::numeric, p_emp_levy_penalty_amt numeric DEFAULT NULL::numeric, p_emp_pe_penalty_amt numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_seq INTEGER;
  v_id UUID;
  v_period_ts DATE;
  v_date_received TIMESTAMPTZ;
BEGIN
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF p_payer_type IS NULL OR p_payer_type = '' THEN
    RAISE EXCEPTION 'payer_type is required';
  END IF;
  IF p_period IS NULL OR p_period = '' THEN
    RAISE EXCEPTION 'period is required';
  END IF;

  v_period_ts := p_period::DATE;

  -- Parse date_received if provided
  IF p_date_received IS NOT NULL AND p_date_received != '' THEN
    v_date_received := p_date_received::TIMESTAMPTZ;
  ELSE
    v_date_received := NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_payer_id || p_payer_type || p_period));

  SELECT COALESCE(MAX(sequence_no), 0) + 1
  INTO v_seq
  FROM public.cn_c3_reported
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND period = v_period_ts;

  INSERT INTO public.cn_c3_reported (
    payer_id, payer_type, period, sequence_no, posting_status,
    payer_name, payer_address, number_employed, total_wages, nil_return,
    notes, entered_by, received_by, date_received, date_entered,
    emp_ss_amt_calc, emp_levy_amt_calc, emp_pe_amt_calc,
    emp_ss_fines_due, emp_levy_penalty_amt, emp_pe_penalty_amt
  ) VALUES (
    p_payer_id, p_payer_type, v_period_ts, v_seq, 'DEL',
    p_payer_name, p_payer_address, p_number_employed, p_total_wages, COALESCE(p_nil_return, FALSE),
    p_notes, p_entered_by, p_received_by, v_date_received, NOW(),
    p_emp_ss_amt_calc, p_emp_levy_amt_calc, p_emp_pe_amt_calc,
    p_emp_ss_fines_due, p_emp_levy_penalty_amt, p_emp_pe_penalty_amt
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'message', 'C3 reported record created successfully',
    'data', jsonb_build_object(
      'id', v_id,
      'payer_id', p_payer_id,
      'payer_type', p_payer_type,
      'sequence_no', v_seq,
      'period', v_period_ts::TEXT,
      'posting_status', 'DEL'
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_insert_c3_reported(p_payer_id text, p_payer_type text, p_period text, p_sequence_no integer, p_payer_name text DEFAULT NULL::text, p_payer_address text DEFAULT NULL::text, p_number_employed integer DEFAULT NULL::integer, p_total_wages numeric DEFAULT NULL::numeric, p_nil_return boolean DEFAULT false, p_notes text DEFAULT NULL::text, p_entered_by text DEFAULT 'API'::text, p_received_by text DEFAULT NULL::text, p_date_received text DEFAULT NULL::text, p_emp_ss_amt_calc numeric DEFAULT NULL::numeric, p_emp_levy_amt_calc numeric DEFAULT NULL::numeric, p_emp_pe_amt_calc numeric DEFAULT NULL::numeric, p_emp_ss_fines_due numeric DEFAULT NULL::numeric, p_emp_levy_penalty_amt numeric DEFAULT NULL::numeric, p_emp_pe_penalty_amt numeric DEFAULT NULL::numeric, p_is_for_director boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
  v_period_ts DATE;
  v_date_received TIMESTAMPTZ;
BEGIN
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF p_payer_type IS NULL OR p_payer_type = '' THEN
    RAISE EXCEPTION 'payer_type is required';
  END IF;
  IF p_period IS NULL OR p_period = '' THEN
    RAISE EXCEPTION 'period is required';
  END IF;
  IF p_sequence_no IS NULL THEN
    RAISE EXCEPTION 'sequence_no is required';
  END IF;

  v_period_ts := p_period::DATE;

  IF p_date_received IS NOT NULL AND p_date_received != '' THEN
    v_date_received := p_date_received::TIMESTAMPTZ;
  ELSE
    v_date_received := NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_payer_id || p_payer_type || p_period));

  IF EXISTS (
    SELECT 1 FROM public.cn_c3_reported
    WHERE payer_id = p_payer_id
      AND payer_type = p_payer_type
      AND period = v_period_ts
      AND sequence_no = p_sequence_no
      AND is_for_director = COALESCE(p_is_for_director, FALSE)
  ) THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'This schedule/sequence number has already been submitted for this payer and period.',
      'data', jsonb_build_object(
        'payer_id', p_payer_id,
        'payer_type', p_payer_type,
        'period', v_period_ts::TEXT,
        'sequence_no', p_sequence_no,
        'is_for_director', COALESCE(p_is_for_director, FALSE)
      )
    );
  END IF;

  INSERT INTO public.cn_c3_reported (
    payer_id, payer_type, period, sequence_no, posting_status,
    payer_name, payer_address, number_employed, total_wages, nil_return,
    notes, entered_by, received_by, date_received, date_entered,
    emp_ss_amt_calc, emp_levy_amt_calc, emp_pe_amt_calc,
    emp_ss_fines_due, emp_levy_penalty_amt, emp_pe_penalty_amt,
    is_for_director
  ) VALUES (
    p_payer_id, p_payer_type, v_period_ts, p_sequence_no, 'DEL',
    p_payer_name, p_payer_address, p_number_employed, p_total_wages, COALESCE(p_nil_return, FALSE),
    p_notes, p_entered_by, p_received_by, v_date_received, NOW(),
    p_emp_ss_amt_calc, p_emp_levy_amt_calc, p_emp_pe_amt_calc,
    p_emp_ss_fines_due, p_emp_levy_penalty_amt, p_emp_pe_penalty_amt,
    COALESCE(p_is_for_director, FALSE)
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'message', 'C3 reported record created successfully',
    'data', jsonb_build_object(
      'id', v_id,
      'payer_id', p_payer_id,
      'payer_type', p_payer_type,
      'sequence_no', p_sequence_no,
      'period', v_period_ts::TEXT,
      'posting_status', 'DEL',
      'is_for_director', COALESCE(p_is_for_director, FALSE)
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_insert_ip_wages(p_ssn text, p_payer_id text, p_payer_type text, p_sequence_no integer, p_period text, p_employee_name text DEFAULT NULL::text, p_pay_period text DEFAULT NULL::text, p_wages_paid1 numeric DEFAULT NULL::numeric, p_wages_paid2 numeric DEFAULT NULL::numeric, p_wages_paid3 numeric DEFAULT NULL::numeric, p_wages_paid4 numeric DEFAULT NULL::numeric, p_wages_paid5 numeric DEFAULT NULL::numeric, p_wages_paid6 numeric DEFAULT NULL::numeric, p_wages_paid7 numeric DEFAULT NULL::numeric, p_paid_code1 text DEFAULT NULL::text, p_paid_code2 text DEFAULT NULL::text, p_paid_code3 text DEFAULT NULL::text, p_paid_code4 text DEFAULT NULL::text, p_paid_code5 text DEFAULT NULL::text, p_paid_code6 text DEFAULT NULL::text, p_paid_code7 text DEFAULT NULL::text, p_er_ss_amt numeric DEFAULT NULL::numeric, p_er_ei_amt numeric DEFAULT NULL::numeric, p_er_levy_amt numeric DEFAULT NULL::numeric, p_ip_ss_amt numeric DEFAULT NULL::numeric, p_ip_levy_amt numeric DEFAULT NULL::numeric, p_ip_pe_amt numeric DEFAULT NULL::numeric, p_total_wages numeric DEFAULT NULL::numeric, p_entered_by text DEFAULT 'API'::text, p_bonus_date text DEFAULT NULL::text, p_bonus_exempt_levy boolean DEFAULT NULL::boolean, p_bonus_holiday_swapped boolean DEFAULT NULL::boolean, p_holiday_start_date text DEFAULT NULL::text, p_holiday_end_date text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_c3_id UUID;
  v_wages_id UUID;
  v_period_ts DATE;
  v_bonus_date DATE;
  v_holiday_start DATE;
  v_holiday_end DATE;
BEGIN
  IF p_ssn IS NULL OR p_ssn = '' THEN
    RAISE EXCEPTION 'ssn is required';
  END IF;
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF p_payer_type IS NULL OR p_payer_type = '' THEN
    RAISE EXCEPTION 'payer_type is required';
  END IF;
  IF p_sequence_no IS NULL THEN
    RAISE EXCEPTION 'sequence_no is required';
  END IF;
  IF p_period IS NULL OR p_period = '' THEN
    RAISE EXCEPTION 'period is required';
  END IF;

  v_period_ts := p_period::DATE;

  -- Cast optional date fields
  IF p_bonus_date IS NOT NULL AND p_bonus_date != '' THEN
    v_bonus_date := p_bonus_date::DATE;
  END IF;
  IF p_holiday_start_date IS NOT NULL AND p_holiday_start_date != '' THEN
    v_holiday_start := p_holiday_start_date::DATE;
  END IF;
  IF p_holiday_end_date IS NOT NULL AND p_holiday_end_date != '' THEN
    v_holiday_end := p_holiday_end_date::DATE;
  END IF;

  SELECT id INTO v_c3_id
  FROM public.cn_c3_reported
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND sequence_no = p_sequence_no
    AND period = v_period_ts
    AND posting_status = 'DEL'
  LIMIT 1;

  IF v_c3_id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'Cannot insert wages because no matching C3 record with status DEL exists for the given payer_id, payer_type, period, and sequence_no.'
    );
  END IF;

  INSERT INTO public.ip_wages (
    ssn, payer_id, payer_type, sequence_no, period, posting_status, c3_id,
    employee_name, pay_period,
    wages_paid1, wages_paid2, wages_paid3, wages_paid4, wages_paid5, wages_paid6, wages_paid7,
    paid_code1, paid_code2, paid_code3, paid_code4, paid_code5, paid_code6, paid_code7,
    er_ss_amt, er_ei_amt, er_levy_amt, ip_ss_amt, ip_levy_amt, ip_pe_amt,
    total_wages, entered_by, date_entered,
    bonus_date, bonus_exempt_levy, bonus_holiday_swapped,
    holiday_start_date, holiday_end_date
  ) VALUES (
    p_ssn, p_payer_id, p_payer_type, p_sequence_no, v_period_ts, 'DEL', v_c3_id,
    p_employee_name, p_pay_period,
    p_wages_paid1, p_wages_paid2, p_wages_paid3, p_wages_paid4, p_wages_paid5, p_wages_paid6, p_wages_paid7,
    p_paid_code1, p_paid_code2, p_paid_code3, p_paid_code4, p_paid_code5, p_paid_code6, p_paid_code7,
    p_er_ss_amt, p_er_ei_amt, p_er_levy_amt, p_ip_ss_amt, p_ip_levy_amt, p_ip_pe_amt,
    p_total_wages, p_entered_by, NOW(),
    v_bonus_date, p_bonus_exempt_levy, p_bonus_holiday_swapped,
    v_holiday_start, v_holiday_end
  )
  RETURNING id INTO v_wages_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'message', 'Wages record created successfully',
    'data', jsonb_build_object(
      'id', v_wages_id,
      'c3_id', v_c3_id,
      'ssn', p_ssn,
      'payer_id', p_payer_id,
      'payer_type', p_payer_type,
      'sequence_no', p_sequence_no,
      'period', v_period_ts::TEXT,
      'posting_status', 'DEL'
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_ip_details_by_query(p_ssn text, p_dob text, p_first_name text, p_last_name text, p_middle_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dob DATE;
  v_middle TEXT;
  v_result JSONB;
BEGIN
  -- Parse DOB: support dd-MM-yyyy, MM/DD/YYYY, YYYY-MM-DD
  BEGIN
    IF p_dob ~ '^\d{2}-\d{2}-\d{4}$' THEN
      -- dd-MM-yyyy
      v_dob := TO_DATE(p_dob, 'DD-MM-YYYY');
    ELSIF p_dob ~ '^\d{2}/\d{2}/\d{4}$' THEN
      -- MM/DD/YYYY
      v_dob := TO_DATE(p_dob, 'MM/DD/YYYY');
    ELSIF p_dob ~ '^\d{4}-\d{2}-\d{2}$' THEN
      v_dob := p_dob::DATE;
    ELSE
      v_dob := NULL;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_dob := NULL;
  END;

  -- Handle literal "null" middle name
  v_middle := CASE WHEN LOWER(TRIM(p_middle_name)) = 'null' OR TRIM(p_middle_name) = '' THEN NULL ELSE TRIM(p_middle_name) END;

  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'socSecNum', TRIM(m.ssn),
      'firstName', COALESCE(TRIM(m.firstname), ''),
      'surName', COALESCE(TRIM(m.surname), ''),
      'middleName', COALESCE(TRIM(m.middle_name), ''),
      'birthDate', COALESCE(TO_CHAR(m.dob, 'YYYY-MM-DD'), ''),
      'gender', COALESCE(TRIM(m.sex), ''),
      'maritalStatus', COALESCE(TRIM(m.marital_status), ''),
      'streetAddress', COALESCE(TRIM(m.resident_addr1), ''),
      'streetAddress2', COALESCE(TRIM(m.resident_addr2), ''),
      'streetName', '',
      'cityTownName', COALESCE(TRIM(m.mail_addr1), ''),
      'stateRegion', COALESCE(TRIM(m.district), ''),
      'postalCode', NULL,
      'countryCode', COALESCE(TRIM(m.nationality), 'KN'),
      'email', COALESCE(TRIM(m.email_addr), ''),
      'phone', COALESCE(TRIM(m.phone), TRIM(m.telephone), ''),
      'phoneNo', COALESCE(TRIM(m.phone), TRIM(m.telephone), ''),
      'mobile', COALESCE(TRIM(m.phone_mobile), TRIM(m.mobile), ''),
      'mobileNo', COALESCE(TRIM(m.phone_mobile), TRIM(m.mobile), ''),
      'occupation', COALESCE(
        (SELECT TRIM(ie.occupation) FROM ip_employer ie WHERE TRIM(ie.ssn) = TRIM(m.ssn) AND ie.posting_status != 'DEL' ORDER BY ie.date_entered DESC NULLS LAST LIMIT 1),
        COALESCE(TRIM(m.primary_occup), '')
      ),
      'payPeriod', COALESCE(
        (SELECT TRIM(w.pay_period) FROM ip_wages w WHERE TRIM(w.ssn) = TRIM(m.ssn) AND w.posting_status = 'VAC' ORDER BY w.period DESC LIMIT 1),
        'M'
      ),
      'salary', COALESCE(
        (SELECT w.total_wages FROM ip_wages w WHERE TRIM(w.ssn) = TRIM(m.ssn) AND w.posting_status = 'VAC' ORDER BY w.period DESC LIMIT 1),
        0
      ),
      'last_Pay_Date', COALESCE(
        (SELECT TO_CHAR(w.period, 'YYYY-MM-DD') FROM ip_wages w WHERE TRIM(w.ssn) = TRIM(m.ssn) AND w.posting_status = 'VAC' ORDER BY w.period DESC LIMIT 1),
        ''
      ),
      'startDate', COALESCE(
        (SELECT TO_CHAR(w.date_entered, 'YYYY-MM-DD') FROM ip_wages w WHERE TRIM(w.ssn) = TRIM(m.ssn) AND w.posting_status = 'VAC' ORDER BY w.period DESC LIMIT 1),
        ''
      ),
      'endDate', COALESCE(
        (SELECT TO_CHAR(w.date_verified, 'YYYY-MM-DD') FROM ip_wages w WHERE TRIM(w.ssn) = TRIM(m.ssn) AND w.posting_status = 'VAC' ORDER BY w.period DESC LIMIT 1),
        ''
      ),
      'isLevyExempt', false,
      'isActive', CASE WHEN TRIM(m.status) IN ('A', 'V') THEN true ELSE false END,
      'isdirectorOnly', false,
      'isemployeeDirector', false,
      'status', COALESCE(TRIM(m.status), 'A')
    ) AS row_data
    FROM ip_master m
    WHERE TRIM(m.ssn) = TRIM(p_ssn)
      AND (v_dob IS NULL OR m.dob = v_dob)
  ) sub;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_multiple_ip_details(p_employees jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB := '[]'::jsonb;
  v_emp JSONB;
  v_ssn TEXT;
  v_dob DATE;
  v_fname TEXT;
  v_lname TEXT;
  v_found RECORD;
BEGIN
  FOR v_emp IN SELECT * FROM jsonb_array_elements(p_employees)
  LOOP
    v_ssn := TRIM(v_emp->>'ssn');
    v_fname := TRIM(COALESCE(v_emp->>'firstName', ''));
    v_lname := TRIM(COALESCE(v_emp->>'lastName', ''));
    
    BEGIN
      v_dob := (v_emp->>'birthDate')::DATE;
    EXCEPTION WHEN OTHERS THEN
      v_dob := NULL;
    END;

    SELECT m.ssn, m.firstname, m.surname, m.dob
    INTO v_found
    FROM ip_master m
    WHERE TRIM(m.ssn) = v_ssn
    LIMIT 1;

    IF FOUND THEN
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'socSecNum', TRIM(v_found.ssn),
        'firstName', COALESCE(TRIM(v_found.firstname), ''),
        'surName', COALESCE(TRIM(v_found.surname), ''),
        'birthDate', COALESCE(TO_CHAR(v_found.dob, 'YYYY-MM-DD'), ''),
        'valid', true
      ));
    ELSE
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'socSecNum', v_ssn,
        'firstName', v_fname,
        'surName', v_lname,
        'birthDate', COALESCE(v_emp->>'birthDate', ''),
        'valid', false
      ));
    END IF;
  END LOOP;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_nwdirectors_by_last_c3(p_registration_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_period DATE;
  v_last_seq INT;
  v_result JSONB;
BEGIN
  SELECT r.period, r.sequence_no
  INTO v_last_period, v_last_seq
  FROM cn_c3_reported r
  WHERE TRIM(r.payer_id) = TRIM(p_registration_number)
    AND TRIM(r.payer_type) = 'ER'
    AND r.posting_status = 'VAC'
  ORDER BY r.period DESC, r.sequence_no DESC
  LIMIT 1;

  IF v_last_period IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- NW directors: look for payer_type that indicates NW
  -- In the system, NW wages are stored with specific identifiers
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'socialSecurityNumber', TRIM(w.ssn),
      'firstName', COALESCE(
        (SELECT TRIM(m.firstname) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        SPLIT_PART(COALESCE(w.employee_name, ''), ' ', 1)
      ),
      'surName', COALESCE(
        (SELECT TRIM(m.surname) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        CASE WHEN POSITION(' ' IN COALESCE(w.employee_name, '')) > 0 
             THEN SUBSTRING(w.employee_name FROM POSITION(' ' IN w.employee_name) + 1) 
             ELSE '' END
      ),
      'middleName', COALESCE(
        (SELECT TRIM(m.middle_name) FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        ''
      ),
      'birthDate', COALESCE(
        (SELECT TO_CHAR(m.dob, 'YYYY-MM-DD') FROM ip_master m WHERE TRIM(m.ssn) = TRIM(w.ssn) LIMIT 1),
        ''
      ),
      'payPeriod', COALESCE(w.pay_period, 'M'),
      'startDate', COALESCE(TO_CHAR(w.date_entered, 'YYYY-MM-DD'), ''),
      'endDate', COALESCE(TO_CHAR(w.date_verified, 'YYYY-MM-DD'), ''),
      'wages', COALESCE(w.total_wages, 0),
      'levyAmt', COALESCE(w.er_levy_amt, 0) + COALESCE(w.ip_levy_amt, 0)
    ) ORDER BY w.ssn
  ), '[]'::jsonb)
  INTO v_result
  FROM ip_wages w
  WHERE TRIM(w.payer_id) = TRIM(p_registration_number)
    AND TRIM(w.payer_type) = 'ER'
    AND w.period = v_last_period
    AND w.sequence_no = v_last_seq
    AND w.posting_status = 'VAC';

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_payment_save(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payer_id TEXT;
  v_payer_type TEXT;
  v_period_month INT;
  v_period_year INT;
  v_schedule_number INT;
  v_payment_id BIGINT;
  v_receipt_number TEXT;
  v_receipt_id INTEGER;
  v_mop_code TEXT;
  v_office_code TEXT;
  v_headers JSONB;
  v_header JSONB;
  v_total NUMERIC := 0;
  v_line_count INT := 0;
  v_period_date DATE;
  v_comp_period TEXT;
  v_sort_idx INT := 0;
  v_seq_no BIGINT;
  v_payment_reference_id TEXT;
  v_is_for_director BOOLEAN;
BEGIN
  v_payer_id := TRIM(p_payload->>'payerId');
  v_payer_type := TRIM(p_payload->>'payerType');

  IF v_payer_id IS NULL OR v_payer_id = '' THEN
    RETURN jsonb_build_object('error', 'payerId is required in request body');
  END IF;

  IF v_payer_type IS NULL OR v_payer_type = '' THEN
    RETURN jsonb_build_object('error', 'payerType is required in request body');
  END IF;

  v_period_month := (p_payload->>'periodMonth')::INT;
  IF v_period_month IS NULL OR v_period_month < 1 OR v_period_month > 12 THEN
    RETURN jsonb_build_object('error', 'periodMonth must be an integer between 1 and 12');
  END IF;

  v_period_year := (p_payload->>'periodYear')::INT;
  IF v_period_year IS NULL OR v_period_year < 1900 OR v_period_year > 9999 THEN
    RETURN jsonb_build_object('error', 'periodYear must be a valid 4-digit year');
  END IF;

  v_schedule_number := (p_payload->>'scheduleNumber')::INT;

  v_period_date := make_date(v_period_year, v_period_month, 1);
  v_comp_period := LPAD(v_period_month::TEXT, 2, '0') || '/' || v_period_year::TEXT;

  v_mop_code := COALESCE(TRIM(p_payload->>'mopCode'), 'ONL');
  v_office_code := COALESCE(TRIM(p_payload->>'officeCode'), '100');
  v_payment_reference_id := TRIM(p_payload->>'paymentReferenceId');
  v_is_for_director := COALESCE((p_payload->>'isForDirector')::BOOLEAN, FALSE);
  v_headers := p_payload->'paymentHeaders';

  IF v_headers IS NULL OR jsonb_array_length(v_headers) = 0 THEN
    RETURN jsonb_build_object('error', 'paymentHeaders array is required');
  END IF;

  PERFORM pg_advisory_xact_lock(7839202);

  SELECT COALESCE(MAX(payment_id), 0) + 1 INTO v_payment_id FROM cn_payment_header;

  INSERT INTO cn_payment_header (payment_id, payer_id, payer_type, batch_number, date_received, status, payment_reference_id, is_for_director)
  VALUES (v_payment_id, v_payer_id, v_payer_type, v_office_code || '-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS'), NOW(), 'P', v_payment_reference_id, v_is_for_director);

  FOR v_header IN SELECT * FROM jsonb_array_elements(v_headers)
  LOOP
    v_sort_idx := v_sort_idx + 1;
    v_line_count := v_line_count + 1;

    INSERT INTO cn_payment (
      payment_id,
      payment_amount,
      payment_code,
      mop_code,
      period,
      fund_code,
      base_currency,
      currency_conversion_rate
    ) VALUES (
      v_payment_id,
      COALESCE((v_header->>'paymentAmount')::NUMERIC, 0),
      COALESCE(v_header->>'paymentCode', 'ONL'),
      v_mop_code,
      v_period_date,
      COALESCE(v_header->>'fundCode', 'GEN'),
      'XCD',
      1.0
    ) RETURNING payment_sequence_no INTO v_seq_no;

    v_total := v_total + COALESCE((v_header->>'paymentAmount')::NUMERIC, 0);

    INSERT INTO c3_payment_components (
      payment_id,
      payment_code,
      fund_code,
      component_amount,
      period,
      sequence_no,
      sort_order
    ) VALUES (
      v_payment_id,
      COALESCE(v_header->>'paymentCode', 'ONL'),
      COALESCE(v_header->>'fundCode', 'GEN'),
      COALESCE((v_header->>'paymentAmount')::NUMERIC, 0),
      v_comp_period,
      v_schedule_number,
      v_sort_idx
    );
  END LOOP;

  INSERT INTO cn_receipt (payment_id, receipt_total, status, total_number_of_payments)
  VALUES (v_payment_id, v_total, 'A', v_line_count)
  RETURNING receipt_id INTO v_receipt_id;

  -- Fetch the trigger-generated receipt_number
  SELECT receipt_number INTO v_receipt_number
  FROM cn_receipt WHERE receipt_id = v_receipt_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'receipt_id', v_receipt_id,
    'receipt_number', v_receipt_number,
    'total', v_total,
    'line_count', v_line_count,
    'payment_reference_id', v_payment_reference_id,
    'is_for_director', v_is_for_director
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_se_master_details(p_ssn text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ip RECORD;
  v_se RECORD;
  v_wage_cat TEXT;
  v_status_text TEXT;
BEGIN
  IF NULLIF(TRIM(p_email), '') IS NULL THEN
    RETURN jsonb_build_object('error', 'Email is required', 'code', 'BAD_REQUEST');
  END IF;

  SELECT * INTO v_ip
  FROM ip_master
  WHERE TRIM(ssn) = TRIM(p_ssn);

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Person not found', 'code', 'NOT_FOUND');
  END IF;

  IF LOWER(TRIM(COALESCE(v_ip.email_addr, ''))) <> LOWER(TRIM(p_email)) THEN
    RETURN jsonb_build_object('error', 'Email does not match records', 'code', 'NOT_FOUND');
  END IF;

  SELECT * INTO v_se
  FROM ip_self_employ
  WHERE TRIM(ssn) = TRIM(p_ssn)
  ORDER BY date_commenced DESC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'error', 'Person is not registered as Self-Employed',
      'code', 'NOT_SE'
    );
  END IF;

  IF UPPER(TRIM(COALESCE(v_se.status, ''))) <> 'A' THEN
    CASE UPPER(TRIM(COALESCE(v_se.status, '')))
      WHEN 'P' THEN v_status_text := 'Pending';
      WHEN 'I' THEN v_status_text := 'Inactive';
      WHEN 'C' THEN v_status_text := 'Ceased';
      ELSE v_status_text := COALESCE(v_se.status, 'Unknown');
    END CASE;

    RETURN jsonb_build_object(
      'error', 'Self-Employed person is not active (Status: ' || v_status_text || ')',
      'code', 'NOT_ACTIVE'
    );
  END IF;

  SELECT COALESCE(TRIM(wage_category::TEXT), '') INTO v_wage_cat
  FROM ip_self_category
  WHERE TRIM(ssn) = TRIM(p_ssn)
  ORDER BY effective_start_date DESC NULLS LAST
  LIMIT 1;

  IF v_wage_cat IS NULL THEN
    v_wage_cat := '';
  END IF;

  RETURN jsonb_build_object(
    'name', TRIM(COALESCE(v_ip.firstname, '') || ' ' || COALESCE(v_ip.surname, '')),
    'firstName', COALESCE(TRIM(v_ip.firstname), ''),
    'lastName', COALESCE(TRIM(v_ip.surname), ''),
    'tradeName', COALESCE(TRIM(v_se.self_paddr1), ''),
    'selfRefNo', COALESCE(TRIM(v_se.self_ref_no), ''),
    'address1', COALESCE(TRIM(v_ip.resident_addr1), ''),
    'address2', COALESCE(TRIM(v_ip.resident_addr2), ''),
    'city', COALESCE(TRIM(v_ip.district), ''),
    'postalCode', '',
    'country', 'St. Kitts and Nevis',
    'phone', COALESCE(TRIM(v_se.phone), COALESCE(TRIM(v_ip.phone), '')),
    'mobile', COALESCE(TRIM(v_ip.phone_mobile), ''),
    'email', COALESCE(TRIM(v_ip.email_addr), ''),
    'gender', COALESCE(TRIM(v_ip.sex), ''),
    'dateOfBirth', COALESCE(TO_CHAR(v_ip.dob, 'DD/MM/YYYY'), ''),
    'dateRegistered', COALESCE(TO_CHAR(v_se.date_commenced, 'DD/MM/YYYY'), ''),
    'officeCode', COALESCE(TRIM(v_se.office_code), ''),
    'wageCategory', v_wage_cat,
    'tin', '',
    'userName', '',
    'ssn', COALESCE(TRIM(v_ip.ssn), ''),
    'statusCode', 'A',
    'statusText', 'Active',
    'isActive', 'true'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_update_user(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_employer_type TEXT;
  v_payer_id TEXT;
BEGIN
  v_employer_type := UPPER(TRIM(COALESCE(p_payload->>'employerType', p_payload->>'payerType', '')));
  v_payer_id := TRIM(COALESCE(p_payload->>'payerId', ''));

  IF v_payer_id = '' THEN
    RETURN jsonb_build_object('error', 'payerId is required');
  END IF;

  IF v_employer_type = 'ER' THEN
    UPDATE er_master SET
      name = COALESCE(NULLIF(TRIM(p_payload->>'companyName'), ''), name),
      trade_name = COALESCE(NULLIF(TRIM(p_payload->>'tradeName'), ''), trade_name),
      hq_addr1 = COALESCE(NULLIF(TRIM(p_payload->>'address1'), ''), hq_addr1),
      hq_addr2 = COALESCE(NULLIF(TRIM(p_payload->>'address2'), ''), hq_addr2),
      maddr1 = COALESCE(NULLIF(TRIM(p_payload->>'city'), ''), maddr1),
      phone = COALESCE(NULLIF(TRIM(p_payload->>'phone'), ''), phone),
      mobile = COALESCE(NULLIF(TRIM(p_payload->>'mobile'), ''), mobile),
      email = COALESCE(NULLIF(TRIM(p_payload->>'email'), ''), email),
      date_modified = NOW(),
      modified_by = COALESCE(NULLIF(TRIM(p_payload->>'userName'), ''), 'API')
    WHERE TRIM(regno) = v_payer_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'Employer not found');
    END IF;

    RETURN jsonb_build_object('message', 'Employer data Successfully Updated!');

  ELSIF v_employer_type = 'SE' THEN
    UPDATE ip_master SET
      firstname = COALESCE(NULLIF(TRIM(p_payload->>'firstName'), ''), firstname),
      surname = COALESCE(NULLIF(TRIM(p_payload->>'surName'), ''), surname),
      resident_addr1 = COALESCE(NULLIF(TRIM(p_payload->>'address1'), ''), resident_addr1),
      resident_addr2 = COALESCE(NULLIF(TRIM(p_payload->>'address2'), ''), resident_addr2),
      mail_addr1 = COALESCE(NULLIF(TRIM(p_payload->>'city'), ''), mail_addr1),
      phone = COALESCE(NULLIF(TRIM(p_payload->>'phone'), ''), phone),
      phone_mobile = COALESCE(NULLIF(TRIM(p_payload->>'mobile'), ''), phone_mobile),
      email_addr = COALESCE(NULLIF(TRIM(p_payload->>'email'), ''), email_addr),
      date_modified = NOW(),
      userid = COALESCE(NULLIF(TRIM(p_payload->>'userName'), ''), 'API')
    WHERE TRIM(ssn) = v_payer_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'Self-employed person not found');
    END IF;

    RETURN jsonb_build_object('message', 'Self Employee data Successfully Updated!');

  ELSE
    RETURN jsonb_build_object('error', 'employerType must be ER or SE');
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.public_api_verify_c3(p_payer_id text, p_payer_type text, p_sequence_no integer, p_period text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_c3_id UUID;
  v_nil_return BOOLEAN;
  v_wages_count INTEGER;
  v_total_wages NUMERIC;
  v_emp_ss_amt_calc NUMERIC;
  v_emp_levy_amt_calc NUMERIC;
  v_emp_pe_amt_calc NUMERIC;
  v_period_ts DATE;
BEGIN
  IF p_payer_id IS NULL OR p_payer_id = '' THEN
    RAISE EXCEPTION 'payer_id is required';
  END IF;
  IF p_payer_type IS NULL OR p_payer_type = '' THEN
    RAISE EXCEPTION 'payer_type is required';
  END IF;
  IF p_sequence_no IS NULL THEN
    RAISE EXCEPTION 'sequence_no is required';
  END IF;
  IF p_period IS NULL OR p_period = '' THEN
    RAISE EXCEPTION 'period is required';
  END IF;

  v_period_ts := p_period::DATE;

  SELECT id, COALESCE(nil_return, FALSE)
  INTO v_c3_id, v_nil_return
  FROM public.cn_c3_reported
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND sequence_no = p_sequence_no
    AND period = v_period_ts
  LIMIT 1;

  IF v_c3_id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'No C3 reported record found for the given payer_id, payer_type, sequence_no, and period.'
    );
  END IF;

  SELECT COUNT(*)
  INTO v_wages_count
  FROM public.ip_wages
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND sequence_no = p_sequence_no
    AND period = v_period_ts;

  IF v_nil_return THEN
    IF v_wages_count > 0 THEN
      RETURN jsonb_build_object(
        'status', 'error',
        'message', 'Cannot verify nil-return C3 because wage records exist for this payer_id, payer_type, period, and sequence_no.'
      );
    END IF;

    UPDATE public.cn_c3_reported
    SET posting_status = 'VAC',
        date_verified = NOW(),
        verified_by = 'API',
        total_wages = 0,
        number_employed = 0,
        emp_ss_amt_calc = 0,
        emp_levy_amt_calc = 0,
        emp_pe_amt_calc = 0
    WHERE id = v_c3_id;

    RETURN jsonb_build_object(
      'status', 'success',
      'message', 'Nil-return C3 verified successfully. No wages expected.',
      'data', jsonb_build_object(
        'payer_id', p_payer_id,
        'payer_type', p_payer_type,
        'sequence_no', p_sequence_no,
        'period', v_period_ts::TEXT,
        'nil_return', TRUE
      )
    );
  END IF;

  IF v_wages_count = 0 THEN
    RETURN jsonb_build_object(
      'status', 'error',
      'message', 'No wage records found for the given payer_id, payer_type, sequence_no, and period.'
    );
  END IF;

  SELECT
    COALESCE(SUM(COALESCE(wages_paid1,0) + COALESCE(wages_paid2,0) + COALESCE(wages_paid3,0) + COALESCE(wages_paid4,0) + COALESCE(wages_paid5,0) + COALESCE(wages_paid6,0)), 0),
    COALESCE(SUM(COALESCE(er_ss_amt,0) + COALESCE(er_ei_amt,0) + COALESCE(ip_ss_amt,0)), 0),
    COALESCE(SUM(COALESCE(er_levy_amt,0) + COALESCE(ip_levy_amt,0)), 0),
    COALESCE(SUM(COALESCE(ip_pe_amt,0)), 0)
  INTO v_total_wages, v_emp_ss_amt_calc, v_emp_levy_amt_calc, v_emp_pe_amt_calc
  FROM public.ip_wages
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND sequence_no = p_sequence_no
    AND period = v_period_ts;

  UPDATE public.cn_c3_reported
  SET posting_status = 'VAC',
      date_verified = NOW(),
      verified_by = 'API',
      total_wages = v_total_wages,
      number_employed = v_wages_count,
      emp_ss_amt_calc = v_emp_ss_amt_calc,
      emp_levy_amt_calc = v_emp_levy_amt_calc,
      emp_pe_amt_calc = v_emp_pe_amt_calc
  WHERE id = v_c3_id;

  UPDATE public.ip_wages
  SET is_verified = TRUE,
      verified_by = 'API',
      date_verified = NOW()
  WHERE payer_id = p_payer_id
    AND payer_type = p_payer_type
    AND sequence_no = p_sequence_no
    AND period = v_period_ts;

  RETURN jsonb_build_object(
    'status', 'success',
    'message', 'C3 verified successfully',
    'data', jsonb_build_object(
      'payer_id', p_payer_id,
      'payer_type', p_payer_type,
      'sequence_no', p_sequence_no,
      'period', v_period_ts::TEXT,
      'total_wages', v_total_wages,
      'emp_ss_amt_calc', v_emp_ss_amt_calc,
      'emp_levy_amt_calc', v_emp_levy_amt_calc,
      'emp_pe_amt_calc', v_emp_pe_amt_calc,
      'number_employed', v_wages_count,
      'wages_rows_verified', v_wages_count
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.read_email_batch(queue_name text, batch_size integer, vt integer)
 RETURNS TABLE(msg_id bigint, read_ct integer, message jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reassess_comm_hub_revalidation_cycle(p_cycle_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cycle public.communication_hub_revalidation_cycle%ROWTYPE;
  v_snapshot jsonb;
  v_current_core jsonb;
  v_current_fp text;
  v_assessment jsonb;
  v_err text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_cycle
  FROM public.communication_hub_revalidation_cycle
  WHERE id = p_cycle_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'cycle_not_found' USING ERRCODE='P0002';
  END IF;

  IF v_cycle.status IN ('CONFIRMED','NOT_RECEIVED','FAILED','VOIDED',
                        'VERIFIED_SUPPLEMENTAL','PROMOTED','SUPERSEDED') THEN
    -- Terminal cycles cannot be reassessed.
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'cycle_terminal',
      'status', v_cycle.status,
      'assessment_version', v_cycle.assessment_version
    );
  END IF;

  -- Fail closed if current evidence cannot be resolved.
  BEGIN
    v_snapshot := public.get_comm_hub_current_evidence_snapshot(
      v_cycle.module_code, v_cycle.event_code, v_cycle.channel
    );
    v_current_core := COALESCE(v_snapshot->'evidence_core_v2', v_snapshot);
    v_current_fp := public._comm_hub_fingerprint_evidence_core_v2(v_current_core);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_err = MESSAGE_TEXT;
    UPDATE public.communication_hub_revalidation_cycle
    SET last_reassessment_error = v_err,
        last_reassessment_at    = now(),
        needs_reassessment      = true,
        updated_at              = now()
    WHERE id = p_cycle_id;
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'current_evidence_unresolved',
      'error', v_err
    );
  END;

  -- Store recomputed fields (no baseline mutation, no anchor mutation).
  UPDATE public.communication_hub_revalidation_cycle
  SET current_evidence_core_v2         = v_current_core,
      current_evidence_fingerprint_v2  = v_current_fp,
      assessment_version               = COALESCE(v_cycle.assessment_version, 0) + 1,
      assessed_at                      = now(),
      assessed_runtime_contract_version = public.comm_hub_runtime_contract_version(),
      assessment_fingerprint           = v_current_fp,
      needs_reassessment               = false,
      last_reassessment_error          = NULL,
      last_reassessment_at             = now(),
      updated_at                       = now()
  WHERE id = p_cycle_id;

  RETURN jsonb_build_object(
    'ok', true,
    'cycle_id', p_cycle_id,
    'assessment_version', COALESCE(v_cycle.assessment_version, 0) + 1,
    'assessed_runtime_contract_version', public.comm_hub_runtime_contract_version(),
    'current_evidence_fingerprint_v2', v_current_fp,
    'baseline_fingerprint_v2', v_cycle.baseline_evidence_fingerprint_v2,
    'drift', (v_cycle.baseline_evidence_fingerprint_v2 IS DISTINCT FROM v_current_fp)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.recompute_communication_request_status(p_request_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total         integer;
  v_sent          integer;
  v_failed        integer;
  v_terminal      integer;
  v_in_flight     integer;
  v_current       text;
  v_new           text;
BEGIN
  SELECT status INTO v_current FROM public.communication_request WHERE id = p_request_id;
  IF v_current IS NULL OR v_current = 'cancelled' THEN
    RETURN v_current;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status IN ('sent','delivered')),
    COUNT(*) FILTER (WHERE status IN ('failed','bounced','suppressed','cancelled')),
    COUNT(*) FILTER (WHERE status IN ('sent','delivered','failed','bounced','suppressed','cancelled')),
    COUNT(*) FILTER (WHERE status IN ('queued','sending'))
  INTO v_total, v_sent, v_failed, v_terminal, v_in_flight
  FROM public.communication_message
  WHERE request_id = p_request_id;

  IF v_total = 0 THEN
    RETURN v_current;
  END IF;

  IF v_terminal = v_total AND v_failed = v_total THEN
    v_new := 'failed';
  ELSIF v_terminal = v_total AND v_sent = v_total THEN
    v_new := 'completed';
  ELSIF v_terminal = v_total THEN
    v_new := 'partial';
  ELSIF v_in_flight > 0 AND v_current <> 'pending' THEN
    v_new := 'dispatching';
  ELSE
    v_new := v_current;
  END IF;

  IF v_new IS DISTINCT FROM v_current THEN
    UPDATE public.communication_request
       SET status = v_new, updated_at = now()
     WHERE id = p_request_id;
  END IF;

  RETURN v_new;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_comm_hub_controlled_live_pre_provider(p_grant_id uuid, p_execution_id uuid, p_message_id uuid, p_failure_stage text, p_failure_code text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g record; v_msg record; v_provider_seen int; v_grant_after text;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation('comm-hub-dispatch','DISPATCH_CONTROLLED_STUB');
  IF NOT COALESCE((v_svc->>'allowed')::bool, false) THEN
    RETURN jsonb_build_object('allowed', false, 'blockers', v_svc->'blockers'); END IF;
  SELECT count(*) INTO v_provider_seen FROM public.communication_delivery_attempt
   WHERE message_id = p_message_id AND attempt_type='controlled_live' AND provider_call_attempted=true;
  IF v_provider_seen > 0 THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','PROVIDER_ALREADY_ATTEMPTED',
      'message','Cannot pre-provider reconcile after a provider call was attempted'))); END IF;
  SELECT * INTO v_g FROM public.communication_controlled_live_grant WHERE id = p_grant_id FOR UPDATE;
  IF FOUND AND v_g.execution_id = p_execution_id AND v_g.status::text IN ('ISSUED','RESERVED') THEN
    UPDATE public.communication_controlled_live_grant
       SET status='REVOKED', revoked_at=now(),
           revocation_reason=COALESCE(p_reason,'pre_provider_reconciliation'), updated_at=now()
     WHERE id = v_g.id;
    v_grant_after := 'REVOKED';
  ELSE v_grant_after := COALESCE(v_g.status::text, 'MISSING'); END IF;
  PERFORM set_config('comm_hub.allow_targeted_update', 'true', true);
  UPDATE public.communication_message
     SET status='failed', locked_at=NULL, locked_by=NULL,
         error_code=p_failure_code, error_message=LEFT(COALESCE(p_reason,''),500), updated_at=now()
   WHERE id = p_message_id RETURNING * INTO v_msg;
  RETURN jsonb_build_object('allowed', true, 'grant_status', v_grant_after,
    'message_status', COALESCE(v_msg.status,'missing'),
    'retry_safe', true, 'automatic_retry_allowed', false,
    'requires_new_execution', true, 'requires_new_grant', true,
    'failure_stage', p_failure_stage, 'failure_code', p_failure_code);
END; $function$;
CREATE OR REPLACE FUNCTION public.reconcile_comm_hub_manual_production_entry(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_settings public.communication_hub_control_settings%ROWTYPE;
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_ore public.communication_controlled_live_certification%ROWTYPE;
  v_template_version_id uuid; v_sender_profile_id uuid; v_template_hash text;
  v_payload_hash text; v_review_hash text; v_send_hash text;
  v_current_fp text; v_current_fp_v2 text;
  v_pending_intent record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  BEGIN v_is_admin := public.is_comm_hub_operator_admin(v_uid);
  EXCEPTION WHEN undefined_function THEN
    SELECT public.has_role(v_uid,'Admin'::public.app_role) INTO v_is_admin; END;
  IF NOT v_is_admin THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';
  IF NOT FOUND THEN RAISE EXCEPTION 'settings_singleton_missing' USING ERRCODE='P0002'; END IF;

  IF lower(coalesce(v_settings.operating_mode::text,'')) = 'emergency_stop' THEN
    RETURN jsonb_build_object('status','EMERGENCY_STOP_ACTIVE',
      'runtime_mode_version', v_settings.runtime_mode_version);
  END IF;

  BEGIN
    SELECT id, phase, idempotency_key INTO v_pending_intent
      FROM public.communication_manual_production_observation_intent
     WHERE module_code=p_module_code AND event_code=p_event_code AND channel=p_channel
       AND phase NOT IN ('CONFIRMED','NOT_RECEIVED','FAILED','VOIDED')
     ORDER BY created_at DESC LIMIT 1;
  EXCEPTION WHEN undefined_table THEN v_pending_intent := NULL; END;
  IF v_pending_intent.id IS NOT NULL THEN
    RETURN jsonb_build_object('status','PENDING_OBSERVATION_RECOVERY',
      'intent_id', v_pending_intent.id, 'phase', v_pending_intent.phase,
      'idempotency_key', v_pending_intent.idempotency_key,
      'runtime_mode_version', v_settings.runtime_mode_version);
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=p_channel;

  IF FOUND AND v_ec.status IN ('live_manual_only','live_cron_allowed')
     AND v_ec.drift_detected_at IS NULL AND v_ec.suspended_at IS NULL THEN
    RETURN jsonb_build_object('status','READY_TO_DISPATCH',
      'certification_row_id', v_ec.id, 'event_status', v_ec.status,
      'runtime_mode_version', v_settings.runtime_mode_version,
      'evidence_fingerprint', v_ec.evidence_fingerprint);
  END IF;

  SELECT * INTO v_ore FROM public.communication_controlled_live_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=p_channel
     AND certification_kind='ONE_REAL_EMAIL'
     AND invalidated_at IS NULL
     AND status IN ('DELIVERY_CONFIRMED','DELIVERY_CONFIRMED_MANUALLY')
     AND coalesce(manual_verification_status,'') = 'CONFIRMED'
   ORDER BY manual_verified_at DESC NULLS LAST, created_at DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status','EVENT_CERTIFICATION_REQUIRED',
      'reason','no_valid_one_real_email_certification',
      'runtime_mode_version', v_settings.runtime_mode_version);
  END IF;

  IF v_ore.message_id IS NOT NULL THEN
    SELECT template_version_id, sender_profile_id INTO v_template_version_id, v_sender_profile_id
      FROM public.communication_message WHERE id = v_ore.message_id;
  END IF;
  BEGIN
    EXECUTE 'SELECT manifest_hash FROM public.core_template_version WHERE id=$1'
      INTO v_template_hash USING v_template_version_id;
  EXCEPTION WHEN undefined_table OR undefined_column THEN v_template_hash := NULL;
  END;

  BEGIN
    EXECUTE 'SELECT md5(coalesce(payload_schema::text,'''')) FROM public.communication_hub_event_payload_schema
             WHERE module_code=$1 AND event_code=$2 ORDER BY updated_at DESC NULLS LAST LIMIT 1'
      INTO v_payload_hash USING p_module_code, p_event_code;
  EXCEPTION WHEN OTHERS THEN v_payload_hash := NULL; END;
  BEGIN
    EXECUTE 'SELECT md5(row_to_json(r)::text) FROM public.communication_hub_event_review_policy r
             WHERE module_code=$1 AND event_code=$2 LIMIT 1'
      INTO v_review_hash USING p_module_code, p_event_code;
  EXCEPTION WHEN OTHERS THEN v_review_hash := NULL; END;
  BEGIN
    EXECUTE 'SELECT md5(row_to_json(r)::text) FROM public.communication_hub_event_send_policy r
             WHERE module_code=$1 AND event_code=$2 LIMIT 1'
      INTO v_send_hash USING p_module_code, p_event_code;
  EXCEPTION WHEN OTHERS THEN v_send_hash := NULL; END;

  v_current_fp := public._comm_hub_evidence_fingerprint(
    p_module_code, p_event_code, p_channel,
    v_template_version_id, v_template_hash, v_sender_profile_id,
    v_ore.recipient_policy_version::text, v_ore.recipient_set_hash, NULL::text);
  v_current_fp_v2 := public._comm_hub_evidence_fingerprint_v2(
    p_module_code, p_event_code, p_channel,
    v_template_version_id, v_template_hash, v_sender_profile_id,
    v_ore.recipient_policy_version::text, v_ore.recipient_set_hash, NULL::text,
    v_payload_hash, v_review_hash, v_send_hash);

  IF v_ore.evidence_fingerprint IS NOT NULL
     AND v_ore.evidence_fingerprint <> v_current_fp THEN
    RETURN jsonb_build_object('status','EVIDENCE_DRIFT_REQUIRES_RETEST',
      'stored', v_ore.evidence_fingerprint,
      'current', v_current_fp,
      'current_v2', v_current_fp_v2,
      'runtime_mode_version', v_settings.runtime_mode_version);
  END IF;

  RETURN jsonb_build_object('status','EVENT_CERTIFICATION_REQUIRED',
    'one_real_email_certification_id', v_ore.id,
    'evidence_fingerprint', v_current_fp,
    'evidence_fingerprint_v2', v_current_fp_v2,
    'runtime_mode_version', v_settings.runtime_mode_version);
END $function$;
CREATE OR REPLACE FUNCTION public.reconcile_comm_hub_one_real_email_pre_provider(p_execution_id uuid, p_grant_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc jsonb;
  v_exec public.communication_controlled_live_execution%ROWTYPE;
  v_revoke jsonb;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-send-one-real-email','REVOKE_ONE_REAL_EMAIL_GRANT');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'retry_safe', false, 'blockers', v_svc->'blockers');
  END IF;

  SELECT * INTO v_exec FROM public.communication_controlled_live_execution
   WHERE id = p_execution_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'retry_safe', false,
      'blockers', jsonb_build_array(jsonb_build_object('code','EXECUTION_NOT_FOUND')));
  END IF;
  IF v_exec.provider_call_attempted THEN
    -- Post-provider — NEVER auto-reconcile.
    RETURN jsonb_build_object('ok', false, 'retry_safe', false,
      'blockers', jsonb_build_array(jsonb_build_object('code','POST_PROVIDER_NO_AUTO_RECONCILE')));
  END IF;

  -- Fail the associated queued/reserved message so it cannot be re-dispatched.
  IF v_exec.message_id IS NOT NULL THEN
    PERFORM set_config('comm_hub.allow_targeted_update','true', true);
    UPDATE public.communication_message
       SET status='failed', updated_at=now(),
           last_error = coalesce(last_error,'') || case when last_error IS NULL then '' else ' | ' end
             || 'one_real_email_pre_provider_reconciliation: ' || substr(coalesce(p_reason,''),1,160)
     WHERE id = v_exec.message_id AND status IN ('queued','pending','reserved','sending');
  END IF;

  -- Revoke grant (idempotent).
  v_revoke := public.revoke_comm_hub_one_real_email_grant(
    p_grant_id, p_execution_id, coalesce(p_reason,'pre_provider_reconciliation'));

  UPDATE public.communication_controlled_live_execution
     SET state='BLOCKED', failure_stage='pre_provider_reconciliation',
         updated_at=now(),
         warnings = warnings || jsonb_build_array(jsonb_build_object(
           'code','pre_provider_reconciliation','reason', p_reason))
   WHERE id=p_execution_id;

  RETURN jsonb_build_object(
    'ok', true, 'retry_safe', true, 'cleanup_proven', true,
    'revoke', v_revoke,
    'execution_id', p_execution_id, 'grant_id', p_grant_id);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_automation_readiness_check(p_module text, p_event text, p_channel text, p_check text, p_ok boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_sql text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF p_check NOT IN ('scheduler','automatic_triggers','retry_worker','dead_letter',
                     'rate_limits','batch_limits','provider_circuit_breaker',
                     'emergency_stop','alerting_monitoring') THEN
    RAISE EXCEPTION 'unknown_check';
  END IF;

  INSERT INTO public.communication_hub_automation_readiness (module_code,event_code,channel)
  VALUES (p_module,p_event,coalesce(p_channel,'email'))
  ON CONFLICT (module_code,event_code,channel) DO NOTHING;

  v_sql := format(
    'UPDATE public.communication_hub_automation_readiness
        SET %1$I_ok=$1, %1$I_checked_at=now(), %1$I_checked_by=$2, updated_at=now()
      WHERE module_code=$3 AND event_code=$4 AND channel=$5',
    p_check);
  EXECUTE v_sql USING p_ok, v_uid, p_module, p_event, coalesce(p_channel,'email');

  RETURN jsonb_build_object('ok',true,'check',p_check,'value',p_ok);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_controlled_live_provider_attempt(p_execution_id uuid, p_invocation_key text, p_provider_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exec communication_controlled_live_execution%rowtype;
begin
  select * into v_exec from communication_controlled_live_execution where id = p_execution_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'execution_not_found'); end if;
  if v_exec.provider_call_attempted then
    return jsonb_build_object('ok', true, 'idempotent', true, 'provider_invocation_key', v_exec.provider_invocation_key);
  end if;
  if v_exec.provider_invocation_key is not null and v_exec.provider_invocation_key <> p_invocation_key then
    return jsonb_build_object('ok', false, 'code', 'invocation_key_mismatch');
  end if;
  update communication_controlled_live_execution
     set provider_call_attempted = true,
         provider_invocation_key = p_invocation_key,
         provider_invocation_started_at = now(),
         provider_name = p_provider_name,
         state = 'DISPATCHING',
         updated_at = now()
   where id = p_execution_id;
  return jsonb_build_object('ok', true, 'provider_invocation_key', p_invocation_key);
end $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_controlled_live_provider_outcome(p_execution_id uuid, p_provider_status text, p_provider_message_id text, p_provider_response_safe jsonb, p_warnings jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_state communication_controlled_live_state;
begin
  v_state := case p_provider_status
               when 'PROVIDER_ACCEPTED' then 'PROVIDER_ACCEPTED'
               when 'DELIVERY_PENDING'  then 'DELIVERY_PENDING'
               when 'PROVIDER_REJECTED' then 'FAILED'
               else 'FAILED'
             end::communication_controlled_live_state;
  update communication_controlled_live_execution
     set provider_status = p_provider_status,
         provider_message_id = coalesce(p_provider_message_id, provider_message_id),
         provider_response_safe = p_provider_response_safe,
         provider_call_completed_at = now(),
         state = v_state,
         warnings = coalesce(warnings,'[]'::jsonb) || coalesce(p_warnings,'[]'::jsonb),
         updated_at = now()
   where id = p_execution_id;
  return jsonb_build_object('ok', true, 'state', v_state, 'provider_status', p_provider_status);
end $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_fixture_compatibility_evidence(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text, p_template_version_id uuid DEFAULT NULL::uuid, p_scenario_id uuid DEFAULT NULL::uuid, p_platform_test_context_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb; v_id uuid; v_status text; v_m jsonb;
BEGIN
  IF NOT (pg_has_role('service_role','USAGE') OR has_role(auth.uid(),'Admin'::app_role)) THEN
    RAISE EXCEPTION 'insufficient_privilege' USING ERRCODE='42501';
  END IF;
  v_result := public.check_comm_hub_event_fixture_compatibility_v2(
    p_module_code,p_event_code,p_channel,p_template_version_id,p_scenario_id,p_platform_test_context_id);
  v_m := v_result->'manifest';
  v_status := CASE WHEN COALESCE((v_result->>'is_compatible')::boolean,false) THEN 'CURRENT' ELSE 'BLOCKED' END;
  IF v_m ? 'template_version_id' AND v_m ? 'scenario_id' AND (v_m->>'template_version_id') IS NOT NULL AND (v_m->>'scenario_id') IS NOT NULL THEN
    UPDATE public.comm_hub_fixture_compatibility_evidence SET status='SUPERSEDED'
     WHERE module_code=upper(p_module_code) AND event_code=upper(p_event_code) AND channel=lower(p_channel)
       AND template_version_id=(v_m->>'template_version_id')::uuid
       AND scenario_id=(v_m->>'scenario_id')::uuid AND status='CURRENT';
    INSERT INTO public.comm_hub_fixture_compatibility_evidence(
      module_code,event_code,channel,template_version_id,scenario_id,
      platform_test_context_id,schema_id,schema_version,
      compatibility_hash,manifest,status,blockers,warnings,computed_by)
    VALUES (upper(p_module_code),upper(p_event_code),lower(p_channel),
      (v_m->>'template_version_id')::uuid,(v_m->>'scenario_id')::uuid,
      (v_m->>'platform_test_context_id')::uuid,
      NULLIF(v_m->>'schema_id','')::uuid, NULLIF(v_m->>'schema_version','')::int,
      v_result->>'compatibility_hash', v_m, v_status,
      COALESCE(v_result->'blockers','[]'::jsonb),
      COALESCE(v_result->'warnings','[]'::jsonb), auth.uid())
    ON CONFLICT (module_code,event_code,channel,template_version_id,scenario_id,compatibility_hash)
      DO UPDATE SET status=EXCLUDED.status, computed_at=now(), blockers=EXCLUDED.blockers
    RETURNING id INTO v_id;
  END IF;
  RETURN jsonb_build_object('evidence_id',v_id,'status',v_status,'result',v_result);
END; $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_manual_production_observation(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_module text := p_payload->>'module_code';
  v_event text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_ec record;
  v_settings record;
  v_msg record;
  v_id uuid;
  v_msg_id uuid := (p_payload->>'message_id')::uuid;
  v_req_id uuid := (p_payload->>'request_id')::uuid;
  v_attempt_id uuid := (p_payload->>'delivery_attempt_id')::uuid;
  v_trace_id uuid := (p_payload->>'trace_id')::uuid;
  v_provider_id uuid := (p_payload->>'provider_id')::uuid;
  v_provider_name text := p_payload->>'provider_name';
  v_provider_message_id text := p_payload->>'provider_message_id';
  v_provider_call_attempted boolean := coalesce((p_payload->>'provider_call_attempted')::boolean,false);
  v_provider_outcome text := p_payload->>'provider_outcome';
  v_recipient text := p_payload->>'recipient_email';
  v_recipient_hash text := p_payload->>'recipient_set_hash';
  v_idem text := p_payload->>'idempotency_key';
  v_sender uuid := (p_payload->>'sender_profile_id')::uuid;
  v_template uuid := (p_payload->>'template_version_id')::uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF v_module IS NULL OR v_event IS NULL OR v_recipient IS NULL OR v_idem IS NULL THEN
    RAISE EXCEPTION 'required_fields_missing' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
    WHERE module_code=v_module AND event_code=v_event AND channel=v_channel;
  IF NOT FOUND OR v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    RAISE EXCEPTION 'event_not_manually_certified' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';

  -- Idempotent replay: return existing row if the same idempotency key
  SELECT id INTO v_id FROM public.communication_manual_production_observation WHERE idempotency_key=v_idem;
  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'idempotent',true,'observation_id',v_id);
  END IF;

  -- Validate message lineage when supplied
  IF v_msg_id IS NOT NULL THEN
    SELECT * INTO v_msg FROM public.communication_message WHERE id=v_msg_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'message_not_found' USING ERRCODE='22023'; END IF;
    IF v_msg.channel <> v_channel THEN RAISE EXCEPTION 'message_channel_mismatch' USING ERRCODE='22023'; END IF;
  END IF;

  INSERT INTO public.communication_manual_production_observation
    (module_code,event_code,channel,event_certification_id,
     request_id,message_id,delivery_attempt_id,trace_id,
     provider_id,provider_name,provider_message_id,
     provider_call_attempted,provider_outcome,
     recipient_email,recipient_set_hash,configuration_version,
     sender_profile_id,template_version_id,idempotency_key,
     status,dispatched_by)
  VALUES
    (v_module,v_event,v_channel,v_ec.id,
     v_req_id,v_msg_id,v_attempt_id,v_trace_id,
     v_provider_id,v_provider_name,v_provider_message_id,
     v_provider_call_attempted,v_provider_outcome,
     v_recipient,v_recipient_hash,v_settings.configuration_version,
     v_sender,v_template,v_idem,
     CASE WHEN v_provider_outcome IN ('PROVIDER_REJECTED','FAILED') THEN 'FAILED' ELSE 'DISPATCHED' END,
     v_uid)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok',true,'observation_id',v_id,'event_certification_id',v_ec.id);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_observation_intent(p_idempotency_key text, p_module_code text, p_event_code text, p_channel text, p_recipient_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.communication_manual_production_observation_intent%ROWTYPE;
  v_ec  public.communication_hub_event_certification%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
  IF coalesce(p_idempotency_key,'')='' THEN RAISE EXCEPTION 'idempotency_key_required' USING ERRCODE='22023'; END IF;
  IF coalesce(p_recipient_email,'')='' THEN RAISE EXCEPTION 'recipient_required' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
    WHERE module_code=p_module_code AND event_code=p_event_code AND channel=coalesce(p_channel,'email');

  INSERT INTO public.communication_manual_production_observation_intent
    (idempotency_key, operator_id, module_code, event_code, channel, recipient_email, event_certification_id, phase)
  VALUES
    (p_idempotency_key, v_uid, p_module_code, p_event_code, coalesce(p_channel,'email'),
     lower(p_recipient_email), v_ec.id, 'ENQUEUED')
  ON CONFLICT (idempotency_key) DO NOTHING;

  SELECT * INTO v_row FROM public.communication_manual_production_observation_intent
    WHERE idempotency_key=p_idempotency_key;

  RETURN jsonb_build_object('ok',true,
    'idempotency_key',v_row.idempotency_key,
    'phase',v_row.phase,
    'message_id',v_row.message_id,
    'request_id',v_row.request_id,
    'finalized_observation_id',v_row.finalized_observation_id);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_revalidation_inbox_confirmation(p_cycle_id uuid, p_status text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := public._chrc_require_admin();
BEGIN
  IF p_status NOT IN ('CONFIRMED','NOT_RECEIVED') THEN RAISE EXCEPTION 'invalid_status'; END IF;

  UPDATE public.communication_hub_revalidation_cycle
     SET inbox_confirmation_status = p_status,
         status = CASE WHEN p_status='CONFIRMED' THEN 'CONFIRMED'::public.comm_hub_revalidation_status
                       ELSE 'NOT_RECEIVED'::public.comm_hub_revalidation_status END,
         completed_at = now()
   WHERE id = p_cycle_id;

  INSERT INTO public.communication_hub_revalidation_stage_result(
    cycle_id, stage_code, status, evidence, completed_by
  ) VALUES (
    p_cycle_id, 'INBOX_CONFIRMATION',
    CASE WHEN p_status='CONFIRMED' THEN 'PASSED'::public.comm_hub_stage_result_status
         ELSE 'FAILED'::public.comm_hub_stage_result_status END,
    jsonb_build_object('status',p_status,'notes',p_notes), v_uid
  );

  RETURN jsonb_build_object('ok',true);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_revalidation_provider_result(p_cycle_id uuid, p_execution_id uuid, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := public._chrc_require_admin();
BEGIN
  IF p_outcome NOT IN ('ACCEPTED','REJECTED') THEN RAISE EXCEPTION 'invalid_outcome'; END IF;

  UPDATE public.communication_hub_revalidation_cycle
     SET controlled_email_execution_id = p_execution_id,
         provider_call_attempted = true,
         status = CASE WHEN p_outcome='ACCEPTED' THEN 'AWAITING_INBOX_CONFIRMATION'::public.comm_hub_revalidation_status
                       ELSE 'FAILED'::public.comm_hub_revalidation_status END,
         inbox_confirmation_status = CASE WHEN p_outcome='ACCEPTED' THEN 'PENDING' ELSE NULL END,
         completed_at = CASE WHEN p_outcome='REJECTED' THEN now() ELSE NULL END
   WHERE id = p_cycle_id;

  UPDATE public.communication_hub_revalidation_send_authorisation
     SET consumed_at = now(), consumed_execution_id = p_execution_id
   WHERE cycle_id = p_cycle_id AND consumed_at IS NULL AND revoked_at IS NULL;

  RETURN jsonb_build_object('ok',true);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_revalidation_stage(p_cycle_id uuid, p_stage_code comm_hub_revalidation_stage_code, p_status comm_hub_stage_result_status, p_evidence jsonb DEFAULT '{}'::jsonb, p_reused_historical boolean DEFAULT false, p_preview_snapshot_id uuid DEFAULT NULL::uuid, p_preview_approval_id uuid DEFAULT NULL::uuid, p_dry_run_certification_id uuid DEFAULT NULL::uuid, p_controlled_stub_certification_id uuid DEFAULT NULL::uuid, p_one_real_email_certification_id uuid DEFAULT NULL::uuid, p_manual_observation_id uuid DEFAULT NULL::uuid, p_automated_canary_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := public._chrc_require_admin();
  v_cycle record;
  v_stage_id uuid;
BEGIN
  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle
    WHERE id = p_cycle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'cycle_not_found'; END IF;
  IF v_cycle.status IN ('PROMOTED','SUPERSEDED','VOIDED','FAILED','NOT_RECEIVED') THEN
    RAISE EXCEPTION 'cycle_terminal_%', v_cycle.status;
  END IF;

  INSERT INTO public.communication_hub_revalidation_stage_result(
    cycle_id, stage_code, status, evidence, reused_historical_evidence,
    preview_snapshot_id, preview_approval_id, dry_run_certification_id,
    controlled_stub_certification_id, one_real_email_certification_id,
    manual_observation_id, automated_canary_id, completed_by
  ) VALUES (
    p_cycle_id, p_stage_code, p_status, p_evidence, p_reused_historical,
    p_preview_snapshot_id, p_preview_approval_id, p_dry_run_certification_id,
    p_controlled_stub_certification_id, p_one_real_email_certification_id,
    p_manual_observation_id, p_automated_canary_id, v_uid
  ) RETURNING id INTO v_stage_id;

  -- Cycle status transitions on key stages
  IF p_stage_code = 'CHANGE_ASSESSMENT' AND p_status = 'PASSED' THEN
    UPDATE public.communication_hub_revalidation_cycle
       SET status = CASE WHEN required_validation_level IN ('NONE','NON_SENDING_ONLY')
                         THEN 'NON_SENDING_CHECKS'::public.comm_hub_revalidation_status
                         ELSE 'REVALIDATION_REQUIRED'::public.comm_hub_revalidation_status END
     WHERE id = p_cycle_id;
  END IF;

  -- If all non-email stages passed, mark READY_FOR_CONTROLLED_EMAIL
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(v_cycle.required_stages) s
     WHERE s.value = 'CONTROLLED_REVALIDATION_EMAIL')
  THEN
    IF NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(v_cycle.required_stages) s
       WHERE s.value NOT IN ('CONTROLLED_REVALIDATION_EMAIL','INBOX_CONFIRMATION','BASELINE_PROMOTION','MANUAL_PRODUCTION_ACCEPTANCE','AUTOMATED_CANARY')
         AND NOT EXISTS (
           SELECT 1 FROM public.communication_hub_revalidation_stage_result r
            WHERE r.cycle_id = p_cycle_id AND r.stage_code::text = s.value
              AND r.status IN ('PASSED','ACCEPTED_UNCHANGED')
         )
    ) THEN
      UPDATE public.communication_hub_revalidation_cycle
         SET status = 'READY_FOR_CONTROLLED_EMAIL'
       WHERE id = p_cycle_id
         AND status NOT IN ('EMAIL_AUTHORISED','PROVIDER_PROCESSING','AWAITING_INBOX_CONFIRMATION','CONFIRMED','NOT_RECEIVED','PROMOTED','SUPERSEDED','VERIFIED_SUPPLEMENTAL','VOIDED','FAILED');
    END IF;
  END IF;

  RETURN jsonb_build_object('ok',true,'stage_result_id',v_stage_id);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_runtime_release(p_release_reference text, p_git_commit_sha text, p_component_build_ids jsonb DEFAULT '{}'::jsonb, p_affected_surfaces text[] DEFAULT ARRAY[]::text[], p_revalidation_impact jsonb DEFAULT '{}'::jsonb, p_change_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := public._chrc_require_admin(); v_id uuid;
BEGIN
  INSERT INTO public.communication_hub_runtime_release(
    release_reference, git_commit_sha, component_build_ids,
    affected_surfaces, revalidation_impact, change_reason, deployed_by
  ) VALUES (
    p_release_reference, p_git_commit_sha, p_component_build_ids,
    p_affected_surfaces, p_revalidation_impact, p_change_reason, v_uid
  ) ON CONFLICT (release_reference) DO UPDATE
    SET git_commit_sha = EXCLUDED.git_commit_sha,
        component_build_ids = EXCLUDED.component_build_ids,
        affected_surfaces = EXCLUDED.affected_surfaces,
        revalidation_impact = EXCLUDED.revalidation_impact,
        change_reason = EXCLUDED.change_reason,
        updated_at = now()
    RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok',true,'id',v_id);
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_scheduler_heartbeat(p_worker_version text, p_arm_audit_id uuid, p_readiness_snapshot_id uuid, p_processed_count bigint DEFAULT 0, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.communication_hub_control_settings
     SET last_scheduler_heartbeat_at = now(),
         scheduler_worker_version    = p_worker_version,
         last_processed_count        = p_processed_count,
         last_scheduler_error        = p_error,
         heartbeat_arm_audit_id      = p_arm_audit_id,
         heartbeat_readiness_snapshot_id = p_readiness_snapshot_id,
         updated_at                  = now()
   WHERE singleton_guard='primary';
  RETURN jsonb_build_object('ok',true,'at',now());
END $function$;
CREATE OR REPLACE FUNCTION public.record_comm_hub_template_version_certification(p_template_version_id uuid, p_reason text DEFAULT 'canonical writer'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ver record; v_layer text := 'TEMPLATE_STRUCTURE_CERTIFICATION';
  v_kind text := 'STANDARD';
  v_producer text := 'record_comm_hub_template_version_certification';
  v_producer_version text := 'template-cert-writer/2';
  v_diagnostic text := 'certify_comm_hub_template_version';
  v_diagnostic_version text := 'template-cert-diag/1';
  v_purpose text; v_channel text := '';
  v_diag jsonb; v_diag_result text; v_blockers jsonb; v_warnings jsonb;
  v_dep_manifest jsonb; v_manifest jsonb; v_dep_hash text; v_manifest_hash text;
  v_gov_id uuid; v_new_id uuid; v_existing record;
BEGIN
  SELECT v.id, v.version_no, v.status, v.subject, v.body_html, v.body_text, v.template_id
    INTO v_ver FROM public.core_template_version v WHERE v.id = p_template_version_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code','template_version_not_found',
      'template_version_id', p_template_version_id);
  END IF;

  BEGIN v_diag := public.certify_comm_hub_template_version(p_template_version_id);
  EXCEPTION WHEN OTHERS THEN
    v_diag := jsonb_build_object('result','ERROR','blockers',
      jsonb_build_array(jsonb_build_object('code','diagnostic_error','message',SQLERRM)),
      'warnings','[]'::jsonb);
  END;
  v_diag_result := coalesce(v_diag->>'result','UNKNOWN');
  v_blockers := coalesce(v_diag->'blockers','[]'::jsonb);
  v_warnings := coalesce(v_diag->'warnings','[]'::jsonb);
  v_purpose := v_diag->>'template_purpose';

  -- Shared dependency manifest (structure-only)
  v_dep_manifest := public.build_comm_hub_template_dependency_manifest(p_template_version_id);
  v_dep_hash := public.comm_hub_evidence_hash(
    'comm-hub/template-dependency-manifest/v1', v_dep_manifest);

  -- Rich certification manifest (evidence overlay) hashed separately
  v_manifest := jsonb_build_object(
    'dependency_manifest', v_dep_manifest,
    'diagnostic', jsonb_build_object(
      'result', v_diag_result,
      'blocker_count', jsonb_array_length(v_blockers),
      'warning_count', jsonb_array_length(v_warnings)),
    'certification_policy_version','template-cert-policy/v1',
    'producer', jsonb_build_object('function',v_producer,'version',v_producer_version)
  );
  v_manifest_hash := public.comm_hub_evidence_hash(
    'comm-hub/template-certification-manifest/v1', v_manifest);

  -- Idempotent replay
  SELECT * INTO v_existing FROM public.comm_hub_certification
   WHERE entity_type='TEMPLATE_VERSION' AND entity_id=v_ver.id
     AND certification_layer=v_layer AND certification_kind=v_kind
     AND provenance_state='AUTHORITATIVE'
     AND is_stale=false AND superseded_by IS NULL
   ORDER BY certified_at DESC LIMIT 1 FOR UPDATE;
  IF FOUND AND v_existing.dependency_hash = v_dep_hash
     AND v_existing.manifest_hash = v_manifest_hash THEN
    RETURN jsonb_build_object('ok',true,'idempotent_replay',true,
      'certification_id', v_existing.id,
      'template_version_id', v_ver.id,
      'dependency_hash', v_dep_hash, 'manifest_hash', v_manifest_hash);
  END IF;

  IF jsonb_array_length(v_blockers) > 0 OR v_diag_result NOT IN ('CERTIFIED','PASS') THEN
    RETURN jsonb_build_object('ok', false, 'code','diagnostic_blocked',
      'template_version_id', v_ver.id,
      'diagnostic_result', v_diag_result,
      'blockers', v_blockers, 'warnings', v_warnings,
      'dependency_hash', v_dep_hash, 'manifest_hash', v_manifest_hash);
  END IF;

  SELECT id INTO v_gov_id FROM public.comm_hub_governance_record
   WHERE entity_type='TEMPLATE_VERSION' AND entity_id=v_ver.id
   ORDER BY updated_at DESC NULLS LAST LIMIT 1;

  UPDATE public.comm_hub_certification
     SET superseded_at   = now(),
         is_stale        = true,
         stale_reason    = coalesce(stale_reason, 'SUPERSEDED_BY_CANONICAL_WRITER'),
         stale_detected_at = coalesce(stale_detected_at, now())
   WHERE entity_type='TEMPLATE_VERSION' AND entity_id=v_ver.id
     AND certification_layer=v_layer AND certification_kind=v_kind
     AND provenance_state='AUTHORITATIVE'
     AND is_stale=false AND superseded_by IS NULL;

  INSERT INTO public.comm_hub_certification (
    governance_record_id, entity_type, entity_id, entity_version,
    certification_kind, result,
    dependency_manifest, dependency_hash,
    renderer_version, template_purpose, channel,
    validation_findings, error_count, warning_count,
    certified_by, certified_at, certification_reason, is_stale,
    certification_layer, provenance_state,
    producer_function, producer_version,
    diagnostic_function, diagnostic_version,
    canonicalization_version, hash_algorithm, manifest_hash
  ) VALUES (
    v_gov_id, 'TEMPLATE_VERSION', v_ver.id, v_ver.id::text,
    v_kind, 'PASS',
    v_manifest, v_dep_hash,
    'comm-hub-render/1', v_purpose, nullif(v_channel,''),
    jsonb_build_object('blockers',v_blockers,'warnings',v_warnings,'diagnostic_result',v_diag_result),
    jsonb_array_length(v_blockers), jsonb_array_length(v_warnings),
    auth.uid(), now(), coalesce(p_reason,'canonical writer'), false,
    v_layer, 'AUTHORITATIVE',
    v_producer, v_producer_version,
    v_diagnostic, v_diagnostic_version,
    public.comm_hub_canonicalization_version(), 'SHA-256', v_manifest_hash
  ) RETURNING id INTO v_new_id;

  UPDATE public.comm_hub_certification
     SET superseded_by = v_new_id
   WHERE entity_type='TEMPLATE_VERSION' AND entity_id=v_ver.id
     AND certification_layer=v_layer AND certification_kind=v_kind
     AND id <> v_new_id AND superseded_by IS NULL AND superseded_at IS NOT NULL;

  RETURN jsonb_build_object('ok',true,'idempotent_replay',false,
    'certification_id', v_new_id, 'template_version_id', v_ver.id,
    'dependency_hash', v_dep_hash, 'manifest_hash', v_manifest_hash);
END $function$;
CREATE OR REPLACE FUNCTION public.record_controlled_live_certification(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_execution_id UUID := (p_payload->>'execution_id')::uuid;
  v_provider_outcome TEXT := p_payload->>'provider_outcome';
  v_kind TEXT := COALESCE(NULLIF(p_payload->>'certification_kind',''), 'CONTROLLED_STUB');
  v_status TEXT;
  v_row public.communication_controlled_live_certification%ROWTYPE;
  v_recipient_policy_version INTEGER;
  v_config_version INTEGER;
BEGIN
  IF v_execution_id IS NULL THEN RAISE EXCEPTION 'execution_id required'; END IF;
  IF v_provider_outcome NOT IN ('PROVIDER_ACCEPTED','DELIVERY_PENDING','DELIVERED') THEN
    RAISE EXCEPTION 'provider_outcome invalid';
  END IF;
  IF v_kind NOT IN ('CONTROLLED_STUB','ONE_REAL_EMAIL') THEN
    RAISE EXCEPTION 'certification_kind invalid: %', v_kind;
  END IF;

  SELECT * INTO v_row FROM public.communication_controlled_live_certification
   WHERE execution_id = v_execution_id;
  IF FOUND THEN
    -- Replay guard: caller must not switch the certification kind mid-flight.
    IF v_row.certification_kind IS DISTINCT FROM v_kind THEN
      RAISE EXCEPTION
        'certification_kind mismatch on replay: existing=%, requested=%',
        v_row.certification_kind, v_kind;
    END IF;
    RETURN jsonb_build_object('ok', true, 'replayed', true,
      'certification_id', v_row.id, 'status', v_row.status,
      'provider_outcome', v_row.provider_outcome,
      'certification_kind', v_row.certification_kind);
  END IF;

  v_status := CASE WHEN v_provider_outcome = 'DELIVERED' THEN 'DELIVERY_CONFIRMED' ELSE 'PROVIDER_ACCEPTED' END;

  SELECT policy_version INTO v_recipient_policy_version
    FROM public.communication_hub_recipient_policy WHERE singleton_guard = 'primary';

  BEGIN
    SELECT configuration_version INTO v_config_version
      FROM public.communication_hub_control_settings WHERE singleton_guard = 'primary';
  EXCEPTION WHEN OTHERS THEN v_config_version := NULL; END;

  INSERT INTO public.communication_controlled_live_certification (
    execution_id, module_code, event_code, channel, recipient_set_hash,
    preview_snapshot_id, preview_approval_id, dry_run_certification_id,
    request_id, message_id, delivery_attempt_id, trace_id,
    provider_name, provider_message_id, provider_outcome, provider_status,
    status, recipient_policy_version, configuration_version,
    operating_mode_prior, operating_mode_final, cleanup_succeeded, certified_by,
    certification_kind
  ) VALUES (
    v_execution_id, p_payload->>'module_code', p_payload->>'event_code',
    COALESCE(p_payload->>'channel','email'), p_payload->>'recipient_set_hash',
    NULLIF(p_payload->>'preview_snapshot_id','')::uuid,
    (p_payload->>'preview_approval_id')::uuid,
    (p_payload->>'dry_run_certification_id')::uuid,
    NULLIF(p_payload->>'request_id','')::uuid,
    NULLIF(p_payload->>'message_id','')::uuid,
    NULLIF(p_payload->>'delivery_attempt_id','')::uuid,
    NULLIF(p_payload->>'trace_id','')::uuid,
    p_payload->>'provider_name', p_payload->>'provider_message_id',
    v_provider_outcome, p_payload->>'provider_status', v_status,
    v_recipient_policy_version, v_config_version,
    p_payload->>'operating_mode_prior', p_payload->>'operating_mode_final',
    NULLIF(p_payload->>'cleanup_succeeded','')::boolean,
    NULLIF(p_payload->>'certified_by','')::uuid,
    v_kind
  ) RETURNING * INTO v_row;

  RETURN jsonb_build_object('ok', true, 'replayed', false,
    'certification_id', v_row.id, 'status', v_row.status,
    'provider_outcome', v_row.provider_outcome,
    'certification_kind', v_row.certification_kind);
END; $function$;
CREATE OR REPLACE FUNCTION public.record_controlled_live_manual_verification(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cert_id UUID := (p_payload->>'certification_id')::uuid;
  v_decision TEXT := upper(trim(coalesce(p_payload->>'decision','')));
  v_received BOOLEAN;
  v_recipient TEXT := lower(trim(coalesce(p_payload->>'verified_recipient','')));
  v_note TEXT := p_payload->>'note';
  v_received_at TIMESTAMPTZ := COALESCE(NULLIF(p_payload->>'received_at','')::timestamptz, now());
  v_uid UUID := auth.uid();
  v_row public.communication_controlled_live_certification%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN
    RAISE EXCEPTION 'admin_role_required' USING ERRCODE='42501';
  END IF;
  IF v_cert_id IS NULL THEN
    RAISE EXCEPTION 'certification_id_required' USING ERRCODE='22023';
  END IF;

  -- Explicit decision wins; otherwise fall back to legacy `received` boolean;
  -- otherwise refuse — never interpret absence as NOT_RECEIVED.
  IF v_decision = 'CONFIRMED' THEN
    v_received := true;
  ELSIF v_decision = 'NOT_RECEIVED' THEN
    v_received := false;
  ELSIF p_payload ? 'received' THEN
    v_received := (p_payload->>'received')::boolean;
  ELSE
    RAISE EXCEPTION 'manual_verification_decision_required' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_row FROM public.communication_controlled_live_certification
    WHERE id = v_cert_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'certification_not_found' USING ERRCODE='P0002';
  END IF;

  -- Idempotent replay: already manually confirmed -> return existing row unchanged
  IF v_row.status = 'DELIVERY_CONFIRMED_MANUALLY'
     AND coalesce(v_row.manual_verification_status,'') = 'CONFIRMED' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'certification_id', v_row.id,
      'status', v_row.status,
      'manual_verification_status', v_row.manual_verification_status,
      'manual_verification_recipient', v_row.manual_verification_recipient,
      'manual_verified_at', v_row.manual_verified_at
    );
  END IF;

  IF v_row.provider_name IS NULL OR v_row.provider_name = 'stub' THEN
    RAISE EXCEPTION 'manual_verification_not_applicable_to_stub' USING ERRCODE='22023';
  END IF;

  IF v_received IS TRUE AND (v_recipient IS NULL OR length(v_recipient) = 0) THEN
    RAISE EXCEPTION 'verified_recipient_required' USING ERRCODE='22023';
  END IF;

  UPDATE public.communication_controlled_live_certification
     SET manual_verification_status  = CASE WHEN v_received THEN 'CONFIRMED' ELSE 'NOT_RECEIVED' END,
         manual_verification_received_at = CASE WHEN v_received THEN v_received_at ELSE NULL END,
         manual_verification_recipient   = CASE WHEN v_received THEN v_recipient ELSE NULL END,
         manual_verification_note = v_note,
         manual_verified_by = v_uid,
         manual_verified_at = now(),
         status = CASE WHEN v_received THEN 'DELIVERY_CONFIRMED_MANUALLY' ELSE status END
   WHERE id = v_cert_id
   RETURNING * INTO v_row;

  BEGIN
    INSERT INTO public.communication_hub_control_audit (action, actor_id, reason, payload)
    VALUES (
      'controlled_live_manual_verification', v_uid,
      COALESCE(v_note,'manual inbox verification'),
      jsonb_build_object(
        'certification_id', v_row.id,
        'execution_id', v_row.execution_id,
        'decision', CASE WHEN v_received THEN 'CONFIRMED' ELSE 'NOT_RECEIVED' END,
        'received', v_received,
        'verified_recipient', v_recipient,
        'received_at', v_received_at)
    );
  EXCEPTION WHEN undefined_table OR undefined_column THEN NULL; END;

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'certification_id', v_row.id,
    'status', v_row.status,
    'manual_verification_status', v_row.manual_verification_status,
    'manual_verification_recipient', v_row.manual_verification_recipient,
    'manual_verified_at', v_row.manual_verified_at
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.refresh_comm_hub_certification_freshness(p_certification_id uuid, p_source text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_eval jsonb; v_status text;
BEGIN
  v_eval := public.check_comm_hub_certification_freshness(p_certification_id);
  v_status := v_eval->>'freshness_status';
  INSERT INTO public.comm_hub_certification_freshness(
    certification_id, freshness_status, certified_dependency_hash,
    current_dependency_hash, current_manifest_summary,
    changed_dependency_categories, stale_reason_codes,
    last_evaluated_at, last_evaluated_source, stale_detected_at, updated_at)
  VALUES (p_certification_id, v_status,
    v_eval->>'certified_hash', v_eval->>'current_hash',
    jsonb_build_object('categories', v_eval->'changed_dependency_categories'),
    ARRAY(SELECT jsonb_array_elements_text(coalesce(v_eval->'changed_dependency_categories','[]'::jsonb))),
    ARRAY(SELECT jsonb_array_elements_text(coalesce(v_eval->'stale_reason_codes','[]'::jsonb))),
    now(), p_source,
    CASE WHEN v_status IN ('STALE','POSSIBLY_STALE') THEN now() ELSE NULL END, now())
  ON CONFLICT (certification_id) DO UPDATE
    SET freshness_status = EXCLUDED.freshness_status,
        current_dependency_hash = EXCLUDED.current_dependency_hash,
        current_manifest_summary = EXCLUDED.current_manifest_summary,
        changed_dependency_categories = EXCLUDED.changed_dependency_categories,
        stale_reason_codes = EXCLUDED.stale_reason_codes,
        last_evaluated_at = EXCLUDED.last_evaluated_at,
        last_evaluated_source = EXCLUDED.last_evaluated_source,
        stale_detected_at = CASE
          WHEN EXCLUDED.freshness_status IN ('STALE','POSSIBLY_STALE')
               AND public.comm_hub_certification_freshness.stale_detected_at IS NULL THEN now()
          WHEN EXCLUDED.freshness_status = 'CURRENT' THEN NULL
          ELSE public.comm_hub_certification_freshness.stale_detected_at
        END,
        updated_at = now();
  RETURN v_eval;
END $function$;
CREATE OR REPLACE FUNCTION public.register_voluntary_contributor(p_ssn character varying, p_date_registered date, p_date_commenced date, p_payment_interval character varying, p_due_date date, p_user_code character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eligibility JSONB;
  v_wage_calc JSONB;
  v_config RECORD;
  v_avg_weekly_wage NUMERIC(15,2);
  v_contrib_amt NUMERIC(15,2);
  v_name TEXT;
BEGIN
  v_eligibility := public.check_vc_eligibility(p_ssn);
  
  IF NOT (v_eligibility->>'eligible')::BOOLEAN THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Eligibility check failed',
      'details', v_eligibility->'errors'
    );
  END IF;

  SELECT * INTO v_config
  FROM public.tb_vc_eligibility_config
  WHERE is_active = true
    AND effstart <= p_date_registered
    AND (effend IS NULL OR effend >= p_date_registered)
  ORDER BY effstart DESC
  LIMIT 1;

  v_wage_calc := public.calculate_vc_avg_weekly_wage(p_ssn, p_date_registered);
  v_avg_weekly_wage := (v_wage_calc->>'weekly_avg')::NUMERIC;
  v_contrib_amt := ROUND(v_avg_weekly_wage * v_config.vc_contrib_pct / 100, 2);

  UPDATE public.ip_master
  SET vol_contrib = 'Y', updated_at = NOW()
  WHERE ssn = p_ssn;

  INSERT INTO public.ip_vol_contrib (
    ssn, date_registered, date_commenced, date_ceased,
    contrib_amt, payment_interval, due_date, avg_weekly_wage
  ) VALUES (
    p_ssn, p_date_registered, p_date_commenced, NULL,
    v_contrib_amt, p_payment_interval, p_due_date, v_avg_weekly_wage
  )
  ON CONFLICT (ssn, date_registered) DO UPDATE SET
    date_commenced = EXCLUDED.date_commenced,
    contrib_amt = EXCLUDED.contrib_amt,
    payment_interval = EXCLUDED.payment_interval,
    due_date = EXCLUDED.due_date,
    avg_weekly_wage = EXCLUDED.avg_weekly_wage;

  -- Auto-create cn_payer record for VC
  SELECT TRIM(BOTH FROM CONCAT(im.firstname, ' ', im.surname)) INTO v_name
  FROM public.ip_master im WHERE im.ssn = p_ssn;

  PERFORM public.upsert_cn_payer('VC', p_ssn, COALESCE(v_name, ''));

  RETURN jsonb_build_object(
    'success', true,
    'ssn', p_ssn,
    'date_registered', p_date_registered,
    'date_commenced', p_date_commenced,
    'payment_interval', p_payment_interval,
    'avg_weekly_wage', v_avg_weekly_wage,
    'contrib_amt', v_contrib_amt,
    'wage_calculation', v_wage_calc
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.reject_c3_record(p_c3_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_record RECORD;
    v_user_name TEXT;
BEGIN
    -- Get user name if user_id provided
    IF p_user_id IS NOT NULL THEN
        SELECT full_name INTO v_user_name FROM profiles WHERE id = p_user_id;
    END IF;

    -- Lock the record
    SELECT * INTO v_record
    FROM cn_c3_reported
    WHERE id = p_c3_id
    FOR UPDATE;
    
    IF v_record IS NULL THEN
        RAISE EXCEPTION 'C3 record not found';
    END IF;
    
    -- FIXED: Allow rejection from any submitted status (PEN or VAC), not just pending
    -- Rejection does NOT require verification status
    IF v_record.posting_status NOT IN ('PEN', 'P', 'VAC', 'V') THEN
        RAISE EXCEPTION 'Only submitted or verified records can be rejected. Current status: %', v_record.posting_status;
    END IF;
    
    -- Check if user is same as entered_by
    IF v_record.entered_by = v_user_name THEN
        RAISE EXCEPTION 'The user who entered the record cannot reject it. A different user must reject the C3 record.';
    END IF;
    
    -- Update C3 record status to Rejected (REJ)
    UPDATE cn_c3_reported
    SET posting_status = 'REJ',
        modified_date = NOW(),
        modified_by = v_user_name,
        notes = CASE 
            WHEN p_reason IS NOT NULL THEN COALESCE(notes || E'\n', '') || 'Rejection reason: ' || p_reason
            ELSE notes
        END,
        updated_at = NOW()
    WHERE id = p_c3_id;
    
    -- Update all associated wage records to rejected
    UPDATE ip_wages
    SET posting_status = 'REJ',
        date_modified = NOW(),
        modified_by = v_user_name
    WHERE c3_id = p_c3_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'c3_id', p_c3_id,
        'old_status', v_record.posting_status,
        'new_status', 'REJ',
        'message', 'C3 record rejected successfully'
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.reject_qa_change_request(p_request_id uuid, p_reviewer_id uuid, p_reviewer_code character varying, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_req qa_change_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_req FROM public.qa_change_requests WHERE id = p_request_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not found');
  END IF;
  IF v_req.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not pending');
  END IF;

  UPDATE public.qa_change_requests
    SET status = 'rejected',
        reviewed_by = p_reviewer_id,
        reviewed_by_code = p_reviewer_code,
        reviewed_at = now(),
        review_notes = p_notes,
        updated_at = now()
    WHERE id = p_request_id;

  INSERT INTO public.qa_enforcement_log(target_type, target_id, action, attempted_by, change_request_id, was_approved, detail)
    VALUES(v_req.target_type, COALESCE(v_req.target_id, gen_random_uuid()), v_req.change_type, p_reviewer_id, p_request_id, false, 'Rejected by ' || p_reviewer_code);

  RETURN jsonb_build_object('success', true, 'rejected', true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.release_comm_hub_preview_reservation(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_appr_id uuid := (p_payload->>'approval_id')::uuid;
  v_token uuid := nullif(p_payload->>'reservation_token','')::uuid;
BEGIN
  IF v_appr_id IS NULL OR v_token IS NULL THEN RAISE EXCEPTION 'approval_id and reservation_token required'; END IF;
  UPDATE public.communication_preview_approval
     SET status='ACTIVE', reserved_at=NULL, reserved_by=NULL, reservation_token=NULL
   WHERE id=v_appr_id AND status='RESERVED' AND reservation_token=v_token;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reservation_not_releasable';
  END IF;
  RETURN jsonb_build_object('ok',true,'approval_id',v_appr_id,'status','ACTIVE');
END;
$function$;
CREATE OR REPLACE FUNCTION public.render_comm_hub_content(p_content text, p_tokens jsonb DEFAULT '{}'::jsonb, p_output_context text DEFAULT 'text'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_out text := COALESCE(p_content, '');
  v_flat jsonb;
  v_key text;
  v_val text;
  v_ctx text := lower(COALESCE(p_output_context, 'text'));
  v_unresolved text[] := ARRAY[]::text[];
  v_match text;
  v_hash text;
  v_token_count int := 0;
BEGIN
  IF v_ctx NOT IN ('text','plain','html','sms') THEN
    v_ctx := 'text';
  END IF;
  v_flat := public.comm_hub_flatten_tokens(COALESCE(p_tokens, '{}'::jsonb), '');
  v_token_count := public.jsonb_object_keys_count(v_flat);
  IF v_flat IS NOT NULL AND jsonb_typeof(v_flat) = 'object' THEN
    FOR v_key IN SELECT jsonb_object_keys(v_flat) LOOP
      v_val := COALESCE(v_flat->>v_key, '');
      IF v_ctx = 'html' THEN
        v_val := public.comm_hub_html_escape(v_val);
      END IF;
      v_out := regexp_replace(
        v_out,
        '\{\{\s*' ||
          regexp_replace(v_key,'([\.\+\*\?\(\)\[\]\{\}\|\^\$\\])','\\\1','g') ||
        '\s*\}\}',
        v_val,
        'g'
      );
    END LOOP;
  END IF;
  FOR v_match IN
    SELECT (regexp_matches(v_out, '\{\{\s*([a-zA-Z0-9_\.]+)\s*\}\}','g'))[1]
  LOOP
    IF NOT (v_match = ANY(v_unresolved)) THEN
      v_unresolved := v_unresolved || v_match;
    END IF;
  END LOOP;
  v_hash := encode(extensions.digest(v_out, 'sha256'), 'hex');
  RETURN jsonb_build_object(
    'rendered',         v_out,
    'unresolved',       to_jsonb(v_unresolved),
    'content_hash',     v_hash,
    'output_context',   v_ctx,
    'token_count',      v_token_count,
    'unresolved_count', COALESCE(array_length(v_unresolved,1),0)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.render_comm_hub_template(p_source text, p_context jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT public.render_comm_hub_content(p_source, p_context, 'text');
$function$;
CREATE OR REPLACE FUNCTION public.render_comm_hub_template_preview(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text := p_payload->>'module_code';
  v_event  text := p_payload->>'event_code';
  v_channel text := COALESCE(p_payload->>'channel','email');
  v_tokens jsonb := public.comm_hub_scrub_protected_keys(COALESCE(p_payload->'tokens','{}'::jsonb));
  v_map RECORD; v_ver RECORD; v_render jsonb;
  v_review jsonb; v_send jsonb;
  v_blockers text[] := ARRAY[]::text[];
  v_warnings text[] := ARRAY[]::text[];
  v_unresolved text[] := ARRAY[]::text[];
  v_block_codes text[];
BEGIN
  SELECT m.*, sp.from_email, sp.display_name, sp.reply_to_email, sp.is_enabled AS sender_enabled,
         sp.provider_identity_status, sp.domain_verified
    INTO v_map FROM communication_hub_event_template_map m
    LEFT JOIN communication_hub_sender_profile sp ON sp.id = m.sender_profile_id
   WHERE m.module_code=v_module AND m.event_code=v_event AND m.channel=v_channel AND m.active=true LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'blockers',ARRAY['event_template_map_missing'],
      'module_code',v_module,'event_code',v_event,'channel',v_channel,
      'canonical_renderer_version','phase3_v1','is_compatibility_wrapper',true);
  END IF;

  SELECT tv.* INTO v_ver FROM core_template t
    LEFT JOIN core_template_version tv ON tv.id = t.active_version_id
   WHERE t.id = v_map.template_id;

  IF v_ver.id IS NULL THEN
    v_blockers := array_append(v_blockers,'template_version_missing');
  ELSE
    v_render := public.render_comm_hub_template_version(v_ver.id, v_tokens, v_channel, 'PREVIEW_TEST');
    IF jsonb_array_length(v_render->'blockers') > 0 THEN
      SELECT array_agg(x->>'code') INTO v_block_codes FROM jsonb_array_elements(v_render->'blockers') AS x;
      v_blockers := v_blockers || COALESCE(v_block_codes, ARRAY[]::text[]);
    END IF;
    v_unresolved := ARRAY(SELECT jsonb_array_elements_text(v_render->'unresolved_variables'));
  END IF;

  SELECT to_jsonb(rp.*) INTO v_review FROM communication_hub_event_review_policy rp
   WHERE rp.module_code=v_module AND rp.event_code=v_event AND rp.channel=v_channel LIMIT 1;
  BEGIN v_send := public.resolve_comm_hub_send_policy(v_module,v_event,v_channel,'production');
  EXCEPTION WHEN OTHERS THEN v_send := NULL; END;

  IF v_review IS NULL THEN v_blockers := array_append(v_blockers,'review_policy_missing'); END IF;
  IF v_review IS NOT NULL AND (v_review->>'approval_status') NOT IN ('approved_internal','approved_external') THEN
    v_blockers := array_append(v_blockers,'template_not_approved');
  END IF;
  IF COALESCE(array_length(v_unresolved,1),0) > 0 THEN
    v_blockers := array_append(v_blockers,'unresolved_tokens_present');
  END IF;

  RETURN jsonb_build_object(
    'ok', (COALESCE(array_length(v_blockers,1),0)=0),
    'module_code',v_module,'event_code',v_event,'channel',v_channel,
    'template_id',v_map.template_id,'template_version_id',v_ver.id,
    'version_no',v_ver.version_no,'version_status',v_ver.status,
    'from_email',v_map.from_email,'from_display_name',v_map.display_name,
    'reply_to_email',v_map.reply_to_email,'sender_profile_id',v_map.sender_profile_id,
    'sender_enabled',COALESCE(v_map.sender_enabled,false),
    'sender_verified',COALESCE(v_map.domain_verified,false),
    'subject_preview',v_render->>'rendered_subject',
    'html_preview',v_render->>'rendered_body_html',
    'text_preview',v_render->>'rendered_body_text',
    'template_purpose',v_render->>'template_purpose',
    'unresolved_tokens',COALESCE(v_unresolved,ARRAY[]::text[]),
    'missing_tokens',COALESCE(v_unresolved,ARRAY[]::text[]),
    'review_policy',v_review,'send_policy',v_send,
    'warnings',v_warnings,'blockers',v_blockers,
    'generated_at',now(),
    'canonical_renderer_version','phase3_v1',
    'is_compatibility_wrapper',true
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.render_comm_hub_template_version(p_template_version_id uuid, p_tokens jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT public.render_comm_hub_template_version(p_template_version_id, p_tokens, 'EMAIL','PREVIEW_TEST');
$function$;
CREATE OR REPLACE FUNCTION public.render_comm_hub_template_version(p_template_version_id uuid, p_tokens jsonb, p_channel text, p_render_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ver RECORD; v_tpl RECORD; v_purpose text;
  v_subject jsonb; v_html jsonb; v_text jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_unresolved jsonb := '[]'::jsonb;
  v_subject_hash text; v_body_hash text; v_content_hash text;
  v_channel text := upper(COALESCE(p_channel,'EMAIL'));
  v_mode    text := upper(COALESCE(p_render_mode,'PREVIEW_TEST'));
BEGIN
  IF p_template_version_id IS NULL THEN
    RETURN jsonb_build_object('blockers', jsonb_build_array(jsonb_build_object('code','template_version_missing')),
                              'canonical_renderer_version','phase3_v1');
  END IF;
  SELECT * INTO v_ver FROM public.core_template_version WHERE id = p_template_version_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('blockers', jsonb_build_array(jsonb_build_object('code','template_version_not_found','template_version_id',p_template_version_id)),
                              'canonical_renderer_version','phase3_v1');
  END IF;
  SELECT * INTO v_tpl FROM public.core_template WHERE id = v_ver.template_id;
  v_purpose := public.comm_hub_classify_template_purpose(v_ver.template_id);

  IF v_channel NOT IN ('EMAIL','SMS','LETTER','NOTICE','IN_APP','PORTAL','DOCUMENT') THEN
    v_warnings := v_warnings || jsonb_build_object('code','channel_not_recognised','channel',v_channel);
  END IF;
  IF v_mode NOT IN ('PREVIEW_TEST','DRY_RUN_TEST','CONTROLLED_LIVE_TEST','PRODUCTION_EVENT','DOCUMENT_GENERATION') THEN
    v_warnings := v_warnings || jsonb_build_object('code','render_mode_not_recognised','render_mode',v_mode);
  END IF;

  v_subject := public.render_comm_hub_content(COALESCE(v_ver.subject,''),   p_tokens, 'text');
  v_html    := public.render_comm_hub_content(COALESCE(v_ver.body_html,''), p_tokens, 'html');
  v_text    := public.render_comm_hub_content(COALESCE(v_ver.body_text,''), p_tokens, 'text');

  IF (v_subject->>'rendered') ~ E'[\\r\\n]' THEN
    v_blockers := v_blockers || jsonb_build_object('code','subject_control_chars',
      'message','Rendered subject contains CR/LF and would be rejected by SMTP.');
  END IF;

  v_unresolved := (v_subject->'unresolved') || (v_html->'unresolved') || (v_text->'unresolved');

  IF v_purpose = 'EVENT_COMMUNICATION' AND v_channel = 'EMAIL' THEN
    IF COALESCE(v_ver.subject,'')   = '' THEN v_blockers := v_blockers || jsonb_build_object('code','subject_empty'); END IF;
    IF COALESCE(v_ver.body_html,'')='' AND COALESCE(v_ver.body_text,'')='' THEN
      v_blockers := v_blockers || jsonb_build_object('code','body_missing');
    END IF;
  ELSIF v_purpose = 'DOCUMENT_GENERATION' THEN
    IF COALESCE(v_ver.body_html,'')='' AND COALESCE(v_ver.body_text,'')='' THEN
      v_blockers := v_blockers || jsonb_build_object('code','document_body_missing');
    END IF;
  ELSIF v_purpose IN ('MANUAL_CORRESPONDENCE','FORM_OUTPUT') THEN
    IF COALESCE(v_ver.body_html,'')='' AND COALESCE(v_ver.body_text,'')='' THEN
      v_warnings := v_warnings || jsonb_build_object('code','body_empty');
    END IF;
  END IF;

  v_subject_hash := encode(extensions.digest(COALESCE(v_subject->>'rendered',''),'sha256'),'hex');
  v_body_hash    := encode(extensions.digest(
    COALESCE(v_html->>'rendered','') || E'\n---\n' || COALESCE(v_text->>'rendered',''),'sha256'),'hex');
  v_content_hash := encode(extensions.digest(v_subject_hash || v_body_hash,'sha256'),'hex');

  RETURN jsonb_build_object(
    'template_id', v_tpl.id,
    'template_version_id', v_ver.id,
    'template_type', v_tpl.template_type,
    'template_purpose', v_purpose,
    'channel', v_channel,
    'render_mode', v_mode,
    'rendered_subject',   v_subject->>'rendered',
    'rendered_body_html', v_html->>'rendered',
    'rendered_body_text', v_text->>'rendered',
    'subject_hash', v_subject_hash,
    'body_hash',    v_body_hash,
    'content_hash', v_content_hash,
    'resolved_variables', COALESCE(p_tokens,'{}'::jsonb),
    'unresolved',           v_unresolved,
    'unresolved_variables', v_unresolved,
    'unresolved_count', jsonb_array_length(v_unresolved),
    'invalid_variables', '[]'::jsonb,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'canonical_renderer_version','phase3_v1'
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.render_email_template(p_template_id uuid, p_variables jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_template RECORD;
  v_header text;
  v_footer text;
  v_body text;
  v_merged text;
  v_key text;
  v_value text;
BEGIN
  -- Get template
  SELECT * INTO v_template FROM notification_templates WHERE id = p_template_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template % not found', p_template_id; END IF;

  -- Get header and footer
  SELECT html_content INTO v_header FROM email_layout_components WHERE component_type = 'header' AND is_active = true;
  SELECT html_content INTO v_footer FROM email_layout_components WHERE component_type = 'footer' AND is_active = true;

  -- Use html_body if available, else body
  v_body := COALESCE(v_template.html_body, v_template.body);

  -- Replace EMAIL_TITLE placeholder in header with subject
  v_header := replace(v_header, '{{EMAIL_TITLE}}', COALESCE(v_template.subject, v_template.name));

  -- Merge header + body + footer
  v_merged := COALESCE(v_header, '') || v_body || COALESCE(v_footer, '');

  -- Replace variables
  IF p_variables IS NOT NULL THEN
    FOR v_key, v_value IN SELECT * FROM jsonb_each_text(p_variables)
    LOOP
      v_merged := replace(v_merged, '{{' || v_key || '}}', COALESCE(v_value, ''));
    END LOOP;
  END IF;

  RETURN v_merged;
END;
$function$;
CREATE OR REPLACE FUNCTION public.repair_comm_hub_production_lineage_anchor(p_module_code text, p_event_code text, p_channel text, p_expected_event_certification_id uuid, p_expected_ore_certification_id uuid, p_reason text, p_typed_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ec public.communication_hub_event_certification%ROWTYPE;
  v_ore public.communication_controlled_live_certification%ROWTYPE;
  v_obs public.communication_manual_production_observation%ROWTYPE;
  v_diag jsonb;
  v_new_lineage uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  IF coalesce(p_typed_confirmation,'') <> 'REPAIR PRODUCTION LINEAGE' THEN
    RETURN jsonb_build_object('ok', false, 'phase', 'TYPED_CONFIRMATION_MISMATCH');
  END IF;
  IF coalesce(trim(p_reason),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'phase', 'REASON_REQUIRED');
  END IF;

  SELECT * INTO v_ec FROM public.communication_hub_event_certification
   WHERE id = p_expected_event_certification_id
     AND module_code = p_module_code AND event_code = p_event_code
     AND channel = coalesce(p_channel,'email')
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'phase','EVENT_CERTIFICATION_NOT_FOUND');
  END IF;
  IF v_ec.status NOT IN ('live_manual_only','live_cron_allowed') THEN
    RETURN jsonb_build_object('ok', false, 'phase','EVENT_NOT_LIVE');
  END IF;
  IF v_ec.one_real_email_certification_id <> p_expected_ore_certification_id THEN
    RETURN jsonb_build_object('ok', false, 'phase','ORE_NOT_ANCHORED_TO_EVENT');
  END IF;

  SELECT * INTO v_ore FROM public.communication_controlled_live_certification
   WHERE id = p_expected_ore_certification_id FOR UPDATE;
  IF v_ore.certification_kind <> 'ONE_REAL_EMAIL' THEN
    RETURN jsonb_build_object('ok', false, 'phase','NOT_ONE_REAL_EMAIL');
  END IF;
  IF v_ore.manual_verification_status <> 'CONFIRMED' THEN
    RETURN jsonb_build_object('ok', false, 'phase','ORE_NOT_CONFIRMED');
  END IF;
  IF v_ore.invalidated_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'phase','ORE_INVALIDATED');
  END IF;
  IF v_ore.execution_id IS NULL OR v_ore.message_id IS NULL OR v_ore.delivery_attempt_id IS NULL
     OR v_ore.trace_id IS NULL OR coalesce(v_ore.provider_message_id,'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'phase','AMBIGUOUS_CHAIN');
  END IF;

  SELECT * INTO v_obs FROM public.communication_manual_production_observation
   WHERE event_certification_id = v_ec.id AND status NOT IN ('CONFIRMED','VOIDED','FAILED')
   ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', false, 'phase','UNRESOLVED_OBSERVATION');
  END IF;

  SELECT * INTO v_obs FROM public.communication_manual_production_observation
   WHERE event_certification_id = v_ec.id AND status='CONFIRMED'
   ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'phase','NO_CONFIRMED_OBSERVATION');
  END IF;

  -- Assign a fresh lineage id, syncing ORE and event cert.
  v_new_lineage := gen_random_uuid();

  UPDATE public.communication_controlled_live_certification
     SET production_lineage_id = v_new_lineage,
         updated_at = now()
   WHERE id = v_ore.id;

  UPDATE public.communication_hub_event_certification
     SET production_lineage_id = v_new_lineage,
         updated_at = now()
   WHERE id = v_ec.id;

  INSERT INTO public.audit_logs(user_id, action, resource_type, resource_id, metadata, created_at)
  VALUES (v_uid, 'comm_hub.production_lineage.repair',
          'communication_hub_event_certification', v_ec.id::text,
          jsonb_build_object(
            'module_code', p_module_code,
            'event_code',  p_event_code,
            'channel',     coalesce(p_channel,'email'),
            'ore_certification_id', v_ore.id,
            'previous_ore_lineage_id', v_ore.production_lineage_id,
            'previous_event_lineage_id', v_ec.production_lineage_id,
            'new_lineage_id', v_new_lineage,
            'reason', p_reason),
          now());

  RETURN jsonb_build_object('ok', true, 'phase','REPAIRED', 'new_lineage_id', v_new_lineage);
END;
$function$;
CREATE OR REPLACE FUNCTION public.repair_legal_referral_close_stale_tasks(p_info_request_id uuid, p_actor text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ref_id uuid; v_count int;
BEGIN
  SELECT legal_referral_id INTO v_ref_id FROM legal_referral_info_request WHERE id = p_info_request_id;
  IF v_ref_id IS NULL THEN RAISE EXCEPTION 'Info request % not found', p_info_request_id; END IF;
  WITH upd AS (
    UPDATE legal_referral_source_task
       SET status='COMPLETED', completed_by=p_actor, completed_at=now()
     WHERE info_request_id = p_info_request_id AND status IN ('OPEN','IN_PROGRESS')
    RETURNING 1
  ) SELECT count(*) INTO v_count FROM upd;
  INSERT INTO legal_referral_audit (legal_referral_id, info_request_id, event_code, event_module, actor, notes, metadata)
  VALUES (v_ref_id, p_info_request_id, 'REPAIR_CLOSE_STALE_TASKS', 'ADMIN', p_actor,
          'Admin closed stale source tasks after response.', jsonb_build_object('closed_count', v_count));
  RETURN v_count;
END $function$;
CREATE OR REPLACE FUNCTION public.repair_legal_referral_create_source_task(p_info_request_id uuid, p_actor text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ir  legal_referral_info_request%ROWTYPE;
  v_ref legal_referral%ROWTYPE;
  v_task_id uuid;
BEGIN
  SELECT * INTO v_ir FROM legal_referral_info_request WHERE id = p_info_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Info request % not found', p_info_request_id; END IF;
  SELECT * INTO v_ref FROM legal_referral WHERE id = v_ir.legal_referral_id;
  IF EXISTS (SELECT 1 FROM legal_referral_source_task WHERE info_request_id = p_info_request_id) THEN
    RAISE EXCEPTION 'Source task already exists for info request %', p_info_request_id;
  END IF;

  INSERT INTO legal_referral_source_task (
    legal_referral_id, info_request_id, task_type, source_module,
    assigned_workbasket_code, assigned_team_code, assigned_user,
    priority, due_date, status
  ) VALUES (
    v_ref.id, v_ir.id, 'INFO_REQUEST_RESPONSE', v_ref.source_module,
    COALESCE(v_ir.requested_to_workbasket_code, v_ref.submitted_workbasket_code),
    COALESCE(v_ir.requested_to_team_code, v_ref.submitted_team_code),
    COALESCE(v_ir.requested_to_user, v_ref.submitted_by),
    'NORMAL', v_ir.due_date,
    CASE WHEN v_ir.status = 'PENDING_SOURCE_RESPONSE' THEN 'OPEN' ELSE 'COMPLETED' END
  ) RETURNING id INTO v_task_id;

  INSERT INTO legal_referral_audit (legal_referral_id, info_request_id, event_code, event_module, actor, notes, metadata)
  VALUES (v_ref.id, v_ir.id, 'REPAIR_CREATE_SOURCE_TASK', 'ADMIN', p_actor,
          'Admin recreated missing source task.', jsonb_build_object('task_id', v_task_id));
  RETURN v_task_id;
END $function$;
CREATE OR REPLACE FUNCTION public.repair_legal_referral_relink_case(p_referral_id uuid, p_actor text, p_lg_case_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ref legal_referral%ROWTYPE; v_case uuid;
BEGIN
  SELECT * INTO v_ref FROM legal_referral WHERE id = p_referral_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Referral % not found', p_referral_id; END IF;
  v_case := p_lg_case_id;
  IF v_case IS NULL AND v_ref.lg_intake_id IS NOT NULL THEN
    SELECT lg_case_id INTO v_case FROM lg_case_intake WHERE id = v_ref.lg_intake_id;
  END IF;
  IF v_case IS NULL THEN RAISE EXCEPTION 'No legal case id available to relink referral %', p_referral_id; END IF;
  UPDATE legal_referral
     SET legal_case_id = v_case,
         status = CASE WHEN status IN ('REJECTED','CLOSED') THEN status ELSE 'LEGAL_CASE_CREATED' END,
         last_status_at = now()
   WHERE id = p_referral_id;
  INSERT INTO legal_referral_audit (legal_referral_id, event_code, event_module, actor, notes, metadata)
  VALUES (p_referral_id, 'REPAIR_RELINK_CASE', 'ADMIN', p_actor,
          'Admin relinked legal case to referral.', jsonb_build_object('legal_case_id', v_case));
  RETURN v_case;
END $function$;
CREATE OR REPLACE FUNCTION public.repair_legal_referral_resync_status(p_referral_id uuid, p_actor text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ref legal_referral%ROWTYPE;
  v_open int; v_resp int; v_new text;
BEGIN
  SELECT * INTO v_ref FROM legal_referral WHERE id = p_referral_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Referral % not found', p_referral_id; END IF;
  SELECT count(*) INTO v_open FROM legal_referral_info_request
    WHERE legal_referral_id = p_referral_id AND status = 'PENDING_SOURCE_RESPONSE';
  SELECT count(*) INTO v_resp FROM legal_referral_info_request
    WHERE legal_referral_id = p_referral_id AND status = 'RESPONDED';
  IF v_open > 0 THEN v_new := 'INFO_REQUESTED';
  ELSIF v_resp > 0 AND v_ref.status NOT IN ('ACCEPTED','LEGAL_CASE_CREATED','REJECTED','CLOSED','UNDER_LEGAL_REVIEW')
    THEN v_new := 'INFO_RESPONDED';
  ELSE v_new := v_ref.status; END IF;

  UPDATE legal_referral SET status = v_new,
       pending_info_request_count = v_open, last_status_at = now()
   WHERE id = p_referral_id;

  INSERT INTO legal_referral_audit (legal_referral_id, event_code, event_module, actor, notes, metadata)
  VALUES (p_referral_id, 'REPAIR_RESYNC_STATUS', 'ADMIN', p_actor,
          'Admin resynced referral status from info-request state.',
          jsonb_build_object('from', v_ref.status, 'to', v_new, 'open_info_requests', v_open, 'responded', v_resp));
  RETURN v_new;
END $function$;
CREATE OR REPLACE FUNCTION public.report_comm_hub_status_normalisation()
 RETURNS TABLE(scope text, status_value text, occurrence_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT 'core_template', status, count(*)::bigint FROM public.core_template GROUP BY status
  UNION ALL
  SELECT 'core_template_version', status, count(*)::bigint FROM public.core_template_version GROUP BY status
  UNION ALL
  SELECT 'communication_hub_event_review_policy', approval_status, count(*)::bigint
    FROM public.communication_hub_event_review_policy GROUP BY approval_status
  ORDER BY 1, 2;
$function$;
CREATE OR REPLACE FUNCTION public.reserve_comm_hub_controlled_live_grant(p_grant_id uuid, p_execution_id uuid, p_expected_action text, p_expected_correlation_id uuid, p_service_operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g record;
BEGIN
  IF p_service_operation IS DISTINCT FROM 'DISPATCH_CONTROLLED_STUB' THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','SERVICE_OPERATION_INVALID',
        'message','p_service_operation must be DISPATCH_CONTROLLED_STUB',
        'detail', jsonb_build_object('supplied', p_service_operation))));
  END IF;
  v_svc := public._comm_hub_assert_bound_service_operation('comm-hub-dispatch','DISPATCH_CONTROLLED_STUB');
  IF NOT COALESCE((v_svc->>'allowed')::bool, false) THEN
    RETURN jsonb_build_object('allowed', false, 'blockers', v_svc->'blockers');
  END IF;
  SELECT g.*, s.correlation_id AS snap_correlation INTO v_g
    FROM public.communication_controlled_live_grant g
    JOIN public.communication_preview_approval a ON a.id = g.preview_approval_id
    JOIN public.communication_preview_snapshot s ON s.id = a.snapshot_id
   WHERE g.id = p_grant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_NOT_FOUND','message','Grant not found'))); END IF;
  IF v_g.execution_id IS DISTINCT FROM p_execution_id THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_EXECUTION_MISMATCH','message','Execution mismatch'))); END IF;
  IF v_g.expires_at IS NOT NULL AND v_g.expires_at < now() THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_EXPIRED','message','Expired'))); END IF;
  IF v_g.status::text = 'RESERVED' THEN RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status','RESERVED','idempotent', true); END IF;
  IF v_g.status::text = 'CONSUMED' THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_ALREADY_CONSUMED','message','Already consumed'))); END IF;
  IF v_g.status::text = 'REVOKED' THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_REVOKED','message','Revoked'))); END IF;
  IF v_g.status::text <> 'ISSUED' THEN RETURN jsonb_build_object('allowed', false, 'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_STATE_INVALID','message','Not ISSUED',
    'detail', jsonb_build_object('status', v_g.status)))); END IF;
  IF p_expected_action IS NOT NULL AND p_expected_action <> 'RUN_CONTROLLED_STUB' THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_ACTION_MISMATCH','message','Only RUN_CONTROLLED_STUB supported'))); END IF;
  IF p_expected_correlation_id IS NOT NULL AND v_g.snap_correlation IS DISTINCT FROM p_expected_correlation_id THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_CORRELATION_MISMATCH','message','Correlation mismatch'))); END IF;
  UPDATE public.communication_controlled_live_grant
     SET status='RESERVED', reserved_at=now(), updated_at=now() WHERE id = v_g.id;
  RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'RESERVED');
END; $function$;
CREATE OR REPLACE FUNCTION public.reserve_comm_hub_controlled_live_grant(p_grant_id uuid, p_execution_id uuid, p_recipient_set_hash text, p_subject_hash text, p_body_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row communication_controlled_live_grant%rowtype;
begin
  select * into v_row from communication_controlled_live_grant where id = p_grant_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'grant_not_found'); end if;
  if v_row.execution_id <> p_execution_id then
    return jsonb_build_object('ok', false, 'code', 'grant_execution_mismatch');
  end if;
  if v_row.expires_at is not null and v_row.expires_at < now() then
    update communication_controlled_live_grant set status = 'EXPIRED',
      audit_metadata = coalesce(audit_metadata,'{}'::jsonb) || jsonb_build_object('expired_at', now())
      where id = p_grant_id and status = 'ISSUED';
    return jsonb_build_object('ok', false, 'code', 'grant_expired');
  end if;
  if v_row.status = 'RESERVED' then
    if v_row.recipient_set_hash <> p_recipient_set_hash then
      return jsonb_build_object('ok', false, 'code', 'grant_recipient_mismatch');
    end if;
    return jsonb_build_object('ok', true, 'status', 'RESERVED', 'idempotent', true, 'grant_id', v_row.id);
  end if;
  if v_row.status <> 'ISSUED' then
    return jsonb_build_object('ok', false, 'code', 'grant_terminal', 'status', v_row.status);
  end if;
  if v_row.recipient_set_hash <> p_recipient_set_hash then
    return jsonb_build_object('ok', false, 'code', 'grant_recipient_mismatch');
  end if;
  update communication_controlled_live_grant
     set status = 'RESERVED', reserved_at = now(),
         audit_metadata = coalesce(audit_metadata,'{}'::jsonb)
           || jsonb_build_object('subject_hash', p_subject_hash, 'body_hash', p_body_hash, 'reserved_at', now())
   where id = p_grant_id and status = 'ISSUED';
  return jsonb_build_object('ok', true, 'status', 'RESERVED', 'grant_id', p_grant_id);
end $function$;
CREATE OR REPLACE FUNCTION public.reserve_comm_hub_controlled_live_grant(p_grant_id uuid, p_reserved_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN jsonb_build_object('allowed',false,'blockers',
    jsonb_build_array(jsonb_build_object(
      'code','LEGACY_GRANT_API_DISABLED',
      'message','Legacy reserve overload is disabled. Use hardened reserve_comm_hub_controlled_live_grant(uuid,uuid,text,uuid,text).'
    )));
END; $function$;
CREATE OR REPLACE FUNCTION public.reserve_comm_hub_one_real_email_grant(p_grant_id uuid, p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g public.communication_controlled_live_grant%ROWTYPE;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-send-one-real-email','DISPATCH_ONE_REAL_EMAIL');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('allowed', false, 'blockers', v_svc->'blockers');
  END IF;

  SELECT * INTO v_g FROM public.communication_controlled_live_grant WHERE id=p_grant_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_NOT_FOUND')));
  END IF;
  IF v_g.execution_id <> p_execution_id THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_EXECUTION_MISMATCH')));
  END IF;
  IF v_g.send_context <> 'REAL_EMAIL' THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_NOT_REAL_EMAIL')));
  END IF;
  IF v_g.status = 'RESERVED' THEN
    RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'RESERVED',
      'idempotent_replay', true);
  END IF;
  IF v_g.status <> 'ISSUED' THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_STATE_INVALID','detail',
        jsonb_build_object('status', v_g.status))));
  END IF;
  IF v_g.expires_at IS NOT NULL AND v_g.expires_at <= now() THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_EXPIRED')));
  END IF;
  UPDATE public.communication_controlled_live_grant
     SET status='RESERVED', reserved_at=now(), updated_at=now() WHERE id=v_g.id;
  RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'RESERVED');
END $function$;
CREATE OR REPLACE FUNCTION public.reserve_comm_hub_preview_approval(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appr_id uuid := (p_payload->>'approval_id')::uuid;
  v_token uuid := gen_random_uuid();
  v_now timestamptz := now();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  IF v_appr_id IS NULL THEN RAISE EXCEPTION 'approval_id is required'; END IF;

  -- Atomic transition ACTIVE -> RESERVED; will 0-rows on any other state
  UPDATE public.communication_preview_approval
     SET status='RESERVED', reserved_at=v_now, reserved_by=v_uid, reservation_token=v_token
   WHERE id=v_appr_id AND status='ACTIVE' AND expires_at > v_now;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approval_not_reservable';
  END IF;
  RETURN jsonb_build_object('ok',true,'approval_id',v_appr_id,'reservation_token',v_token,'status','RESERVED');
END;
$function$;
CREATE OR REPLACE FUNCTION public.reserve_comm_hub_revalidation_send_authorisation(p_cycle_id uuid, p_authorisation_id uuid, p_current_fingerprint text, p_recipient_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := public._chrc_require_admin();
  v_cycle record;
  v_auth record;
  v_ctrl record;
  v_event_cert record;
  v_recipient text := lower(trim(coalesce(p_recipient_email,'')));
BEGIN
  IF p_cycle_id IS NULL OR p_authorisation_id IS NULL THEN
    RAISE EXCEPTION 'cycle_and_authorisation_required';
  END IF;

  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle
    WHERE id = p_cycle_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'cycle_not_found'; END IF;

  SELECT * INTO v_auth FROM public.communication_hub_revalidation_send_authorisation
    WHERE id = p_authorisation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'authorisation_not_found'; END IF;
  IF v_auth.cycle_id <> p_cycle_id THEN RAISE EXCEPTION 'authorisation_cycle_mismatch'; END IF;
  IF v_auth.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'authorisation_revoked'; END IF;
  IF v_auth.consumed_at IS NOT NULL THEN
    -- Idempotent recovery: only accept if the same execution was already recorded
    -- against this cycle. Do not allow a second provider call.
    IF v_cycle.status = 'PROVIDER_PROCESSING'::public.comm_hub_revalidation_status
       AND v_cycle.controlled_email_execution_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', true,
        'already_reserved', true,
        'cycle_id', v_cycle.id,
        'authorisation_id', v_auth.id,
        'module_code', v_cycle.module_code,
        'event_code', v_cycle.event_code,
        'channel', v_cycle.channel,
        'recipient_email', v_auth.recipient_email,
        'current_fingerprint', v_auth.bound_current_fingerprint,
        'event_certification_id', v_auth.bound_event_certification_id,
        'production_lineage_id', v_auth.bound_production_lineage_id,
        'baseline_ore_certification_id', v_cycle.baseline_ore_certification_id,
        'controlled_email_execution_id', v_cycle.controlled_email_execution_id
      );
    END IF;
    RAISE EXCEPTION 'authorisation_already_consumed';
  END IF;
  IF v_auth.expires_at <= now() THEN RAISE EXCEPTION 'authorisation_expired'; END IF;
  IF v_auth.bound_current_fingerprint IS DISTINCT FROM p_current_fingerprint THEN
    RAISE EXCEPTION 'fingerprint_mismatch';
  END IF;
  IF lower(trim(v_auth.recipient_email)) <> v_recipient THEN
    RAISE EXCEPTION 'recipient_mismatch';
  END IF;

  -- Cycle must be in EMAIL_AUTHORISED (or already PROVIDER_PROCESSING for recovery above).
  IF v_cycle.status <> 'EMAIL_AUTHORISED'::public.comm_hub_revalidation_status THEN
    RAISE EXCEPTION 'cycle_not_email_authorised: %', v_cycle.status;
  END IF;
  IF v_cycle.provider_call_attempted THEN
    RAISE EXCEPTION 'provider_call_already_attempted';
  END IF;
  IF v_cycle.controlled_email_execution_id IS NOT NULL THEN
    RAISE EXCEPTION 'provider_execution_already_exists';
  END IF;
  IF v_cycle.current_evidence_fingerprint_v2 IS DISTINCT FROM p_current_fingerprint THEN
    RAISE EXCEPTION 'cycle_fingerprint_drifted';
  END IF;

  -- Validate anchor integrity.
  IF v_auth.bound_event_certification_id IS DISTINCT FROM v_cycle.baseline_event_certification_id
     OR v_auth.bound_production_lineage_id IS DISTINCT FROM v_cycle.baseline_production_lineage_id THEN
    RAISE EXCEPTION 'anchor_binding_mismatch';
  END IF;

  SELECT id, status INTO v_event_cert FROM public.communication_hub_event_certification
    WHERE id = v_cycle.baseline_event_certification_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'event_certification_not_found'; END IF;

  -- Mode / automation / batch / bulk gates.
  SELECT operating_mode, automation_state, batch_enabled, bulk_enabled
    INTO v_ctrl FROM public.communication_hub_control_settings LIMIT 1;
  IF v_ctrl.operating_mode = 'EMERGENCY_STOP' THEN RAISE EXCEPTION 'emergency_stop_active'; END IF;
  IF v_ctrl.automation_state = 'ARMED' THEN RAISE EXCEPTION 'automation_armed_blocks_revalidation'; END IF;
  IF v_ctrl.batch_enabled OR v_ctrl.bulk_enabled THEN RAISE EXCEPTION 'batch_or_bulk_enabled'; END IF;
  IF v_ctrl.operating_mode NOT IN ('MANUAL_PRODUCTION','AUTOMATED_PRODUCTION') THEN
    RAISE EXCEPTION 'invalid_operating_mode: %', v_ctrl.operating_mode;
  END IF;

  -- Transition cycle to PROVIDER_PROCESSING. Authorisation stays unconsumed
  -- until record_comm_hub_revalidation_provider_result marks it consumed.
  UPDATE public.communication_hub_revalidation_cycle
     SET status = 'PROVIDER_PROCESSING'::public.comm_hub_revalidation_status,
         updated_at = now()
   WHERE id = p_cycle_id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_reserved', false,
    'cycle_id', v_cycle.id,
    'authorisation_id', v_auth.id,
    'module_code', v_cycle.module_code,
    'event_code', v_cycle.event_code,
    'channel', v_cycle.channel,
    'recipient_email', v_auth.recipient_email,
    'current_fingerprint', v_auth.bound_current_fingerprint,
    'event_certification_id', v_auth.bound_event_certification_id,
    'production_lineage_id', v_auth.bound_production_lineage_id,
    'baseline_ore_certification_id', v_cycle.baseline_ore_certification_id,
    'controlled_email_execution_id', null
  );
END $function$;
CREATE OR REPLACE FUNCTION public.resolve_batch_office(p_cashier_user_id uuid, p_ip_address text DEFAULT NULL::text, p_date text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date DATE;
  v_office_code TEXT;
  v_office_desc TEXT;
  v_source TEXT;
  v_ip_result JSON;
BEGIN
  v_date := COALESCE(p_date::DATE, CURRENT_DATE);

  -- Tier 1: IP-based detection
  IF p_ip_address IS NOT NULL AND p_ip_address != '' THEN
    SELECT resolve_office_by_ip(p_ip_address) INTO v_ip_result;
    IF (v_ip_result->>'matched')::BOOLEAN = true THEN
      RETURN jsonb_build_object(
        'office_code', v_ip_result->>'office_code',
        'office_description', v_ip_result->>'office_description',
        'source', 'ip_detection'
      );
    END IF;
  END IF;

  -- Tier 2: Head Cashier office override
  SELECT office_code INTO v_office_code
  FROM cn_cashier_office_override
  WHERE cashier_user_id = p_cashier_user_id AND override_date = v_date
  LIMIT 1;

  IF v_office_code IS NOT NULL THEN
    SELECT description INTO v_office_desc FROM tb_office WHERE code = v_office_code LIMIT 1;
    RETURN jsonb_build_object(
      'office_code', v_office_code,
      'office_description', COALESCE(v_office_desc, v_office_code),
      'source', 'hc_override'
    );
  END IF;

  -- Tier 3: Profile default
  SELECT p.office_code, o.description
  INTO v_office_code, v_office_desc
  FROM profiles p
  LEFT JOIN tb_office o ON o.code = p.office_code
  WHERE p.id = p_cashier_user_id;

  RETURN jsonb_build_object(
    'office_code', COALESCE(v_office_code, 'HQ'),
    'office_description', COALESCE(v_office_desc, v_office_code, 'HQ'),
    'source', 'profile_default'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_comm_asset(p_category text, p_organization_id uuid DEFAULT NULL::uuid, p_department_code text DEFAULT NULL::text, p_module_code text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_communication_type text DEFAULT NULL::text)
 RETURNS TABLE(asset_id uuid, asset_name text, source comm_asset_source, storage_path text, external_url text, resolved_via text, is_fallback boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_communication_type IS NOT NULL THEN
    RETURN QUERY
    SELECT a.id, a.name, a.source, a.storage_path, a.external_url, 'communication_type'::text, false
    FROM public.comm_asset_mapping m
    JOIN public.comm_media_asset a ON a.id = m.asset_id
    WHERE m.category = p_category AND m.communication_type = p_communication_type
      AND m.is_active = true AND a.is_active = true AND a.approval_status = 'approved'
      AND (a.effective_from IS NULL OR a.effective_from <= CURRENT_DATE)
      AND (a.effective_to   IS NULL OR a.effective_to   >= CURRENT_DATE)
    ORDER BY m.priority ASC, a.version DESC LIMIT 1;
    IF FOUND THEN RETURN; END IF;
  END IF;

  IF p_module_code IS NOT NULL THEN
    RETURN QUERY
    SELECT a.id, a.name, a.source, a.storage_path, a.external_url, 'module'::text, false
    FROM public.comm_media_asset a
    WHERE a.category = p_category AND a.module_code = p_module_code
      AND a.is_active = true AND a.approval_status = 'approved'
      AND (a.effective_from IS NULL OR a.effective_from <= CURRENT_DATE)
      AND (a.effective_to   IS NULL OR a.effective_to   >= CURRENT_DATE)
    ORDER BY a.version DESC LIMIT 1;
    IF FOUND THEN RETURN; END IF;
  END IF;

  IF p_department_code IS NOT NULL THEN
    RETURN QUERY
    SELECT a.id, a.name, a.source, a.storage_path, a.external_url, 'department'::text, false
    FROM public.comm_media_asset a
    WHERE a.category = p_category AND a.department_code = p_department_code
      AND a.is_active = true AND a.approval_status = 'approved'
      AND (a.effective_from IS NULL OR a.effective_from <= CURRENT_DATE)
      AND (a.effective_to   IS NULL OR a.effective_to   >= CURRENT_DATE)
    ORDER BY a.version DESC LIMIT 1;
    IF FOUND THEN RETURN; END IF;
  END IF;

  IF p_organization_id IS NOT NULL THEN
    RETURN QUERY
    SELECT a.id, a.name, a.source, a.storage_path, a.external_url, 'organization'::text, false
    FROM public.comm_media_asset a
    WHERE a.category = p_category AND a.organization_id = p_organization_id
      AND a.scope = 'organization' AND a.is_active = true AND a.approval_status = 'approved'
      AND (a.effective_from IS NULL OR a.effective_from <= CURRENT_DATE)
      AND (a.effective_to   IS NULL OR a.effective_to   >= CURRENT_DATE)
    ORDER BY a.version DESC LIMIT 1;
    IF FOUND THEN RETURN; END IF;
  END IF;

  IF p_location_id IS NOT NULL THEN
    RETURN QUERY
    SELECT a.id, a.name, a.source, a.storage_path, a.external_url, 'location'::text, false
    FROM public.comm_media_asset a
    WHERE a.category = p_category AND a.location_id = p_location_id
      AND a.is_active = true AND a.approval_status = 'approved'
    ORDER BY a.version DESC LIMIT 1;
    IF FOUND THEN RETURN; END IF;
  END IF;

  RETURN QUERY
  SELECT a.id, a.name, a.source, a.storage_path, a.external_url,
         CASE WHEN a.is_system_default THEN 'system_default' ELSE 'global' END,
         a.is_system_default
  FROM public.comm_media_asset a
  WHERE a.category = p_category AND a.is_active = true AND a.approval_status = 'approved'
    AND (a.scope = 'global' OR a.is_system_default = true)
  ORDER BY a.is_system_default ASC, a.version DESC LIMIT 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_comm_hub_revalidation_preparation_context(p_cycle_id uuid, p_authorisation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role TEXT := current_setting('request.jwt.claim.role', true);
  v_cycle RECORD;
  v_auth RECORD;
  v_snapshot JSONB;
  v_current_core JSONB;
  v_current_fingerprint TEXT;
  v_attestation RECORD;
  v_template RECORD;
  v_sender RECORD;
  v_provider RECORD;
  v_control RECORD;
  v_stage_ok BOOLEAN := true;
  v_required_stages JSONB := '[]'::jsonb;
  v_authorisation_status TEXT := NULL;
  v_blockers JSONB := '[]'::jsonb;
  v_warnings JSONB := '[]'::jsonb;
  v_prep_version INTEGER := 1;
  v_canonical_key TEXT := NULL;
  v_baseline_ok BOOLEAN := true;
BEGIN
  IF v_role IS NULL OR v_role <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED'
      USING ERRCODE = '42501',
            HINT = 'Internal resolver. Call via the Edge Function service-role client.';
  END IF;

  -- A. Cycle
  SELECT * INTO v_cycle FROM public.communication_hub_revalidation_cycle
   WHERE id = p_cycle_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'blockers', jsonb_build_array(jsonb_build_object(
        'code','cycle_not_found','stage','cycle'))
    );
  END IF;

  v_required_stages := COALESCE(v_cycle.required_stages, '[]'::jsonb);

  IF COALESCE(v_cycle.needs_reassessment, true) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','cycle_needs_reassessment','stage','cycle'));
  END IF;
  IF COALESCE(v_cycle.assessment_version, 0) < 1 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','assessment_version_zero','stage','cycle'));
  END IF;
  IF v_cycle.assessed_at IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','assessed_at_missing','stage','cycle'));
  END IF;
  IF v_cycle.assessment_fingerprint IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','assessment_fingerprint_missing','stage','cycle'));
  END IF;
  IF v_cycle.last_reassessment_error IS NOT NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','last_reassessment_error_present','stage','cycle',
      'detail', v_cycle.last_reassessment_error));
  END IF;

  -- Required stages complete
  IF jsonb_typeof(v_required_stages) = 'array'
     AND jsonb_array_length(v_required_stages) > 0 THEN
    SELECT bool_and(EXISTS(
      SELECT 1 FROM public.communication_hub_revalidation_stage_result r
       WHERE r.cycle_id = p_cycle_id
         AND r.stage_code = s.stage_code
         AND r.status IN ('PASS','COMPLETED','VERIFIED')
    ))
      INTO v_stage_ok
      FROM (SELECT jsonb_array_elements_text(v_required_stages) AS stage_code) s;
    IF NOT COALESCE(v_stage_ok, false) THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','required_stage_incomplete','stage','cycle'));
    END IF;
  END IF;

  -- B. Authorisation
  SELECT * INTO v_auth
    FROM public.communication_hub_revalidation_send_authorisation
   WHERE id = p_authorisation_id
     AND cycle_id = p_cycle_id;
  IF NOT FOUND THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','authorisation_not_found','stage','authorisation'));
  ELSE
    IF v_auth.revoked_at IS NOT NULL THEN
      v_authorisation_status := 'REVOKED';
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','authorisation_revoked','stage','authorisation'));
    ELSIF v_auth.consumed_at IS NOT NULL THEN
      v_authorisation_status := 'CONSUMED';
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','authorisation_consumed','stage','authorisation'));
    ELSIF v_auth.expires_at IS NOT NULL AND v_auth.expires_at < now() THEN
      v_authorisation_status := 'EXPIRED';
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','authorisation_expired','stage','authorisation'));
    ELSE
      v_authorisation_status := 'ISSUED';
    END IF;

    IF v_cycle.recipient_email IS NOT NULL
       AND lower(v_cycle.recipient_email) IS DISTINCT FROM lower(v_auth.recipient_email) THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','recipient_mismatch','stage','authorisation'));
    END IF;
    IF v_auth.bound_event_certification_id IS DISTINCT FROM v_cycle.baseline_event_certification_id THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','event_certification_mismatch','stage','authorisation'));
    END IF;
    IF v_auth.bound_production_lineage_id IS DISTINCT FROM v_cycle.baseline_production_lineage_id THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','production_lineage_mismatch','stage','authorisation'));
    END IF;
  END IF;

  -- C. Fresh snapshot + fingerprint recompute.
  BEGIN
    v_snapshot := public.get_comm_hub_current_evidence_snapshot(
      v_cycle.module_code, v_cycle.event_code, v_cycle.channel);
    v_current_core := COALESCE(v_snapshot->'evidence_core', v_snapshot);
    v_current_fingerprint := public._comm_hub_fingerprint_evidence_core_v2(v_current_core);
  EXCEPTION WHEN OTHERS THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','current_snapshot_error','stage','current_authority',
      'detail', SQLERRM));
  END;

  IF v_current_fingerprint IS NOT NULL THEN
    IF v_cycle.current_evidence_fingerprint_v2 IS DISTINCT FROM v_current_fingerprint THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','cycle_current_fingerprint_stale','stage','current_authority'));
    END IF;
    IF v_cycle.assessment_fingerprint IS NOT NULL
       AND v_cycle.assessment_fingerprint IS DISTINCT FROM v_current_fingerprint THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','assessment_fingerprint_drift','stage','current_authority'));
    END IF;
    IF v_auth.bound_current_fingerprint IS NOT NULL
       AND v_auth.bound_current_fingerprint IS DISTINCT FROM v_current_fingerprint THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code','authorisation_fingerprint_drift','stage','authorisation'));
    END IF;
  END IF;

  -- D. Production authority — event certification + ORE + baseline attestation
  IF v_cycle.baseline_event_certification_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','baseline_event_certification_missing','stage','production_authority'));
  ELSIF NOT EXISTS(
    SELECT 1 FROM public.communication_hub_event_certification
     WHERE id = v_cycle.baseline_event_certification_id
       AND module_code = v_cycle.module_code
       AND event_code = v_cycle.event_code
       AND channel = v_cycle.channel
  ) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','event_certification_not_matched','stage','production_authority'));
  END IF;

  IF v_cycle.baseline_ore_certification_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','baseline_ore_missing','stage','production_authority'));
  END IF;

  IF v_cycle.baseline_production_lineage_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','baseline_production_lineage_missing','stage','production_authority'));
  END IF;

  SELECT * INTO v_attestation
    FROM public.communication_hub_legacy_evidence_attestation
   WHERE module_code = v_cycle.module_code
     AND event_code = v_cycle.event_code
     AND channel = v_cycle.channel
     AND (revoked_at IS NULL)
   ORDER BY attested_at DESC NULLS LAST
   LIMIT 1;
  IF v_attestation.id IS NULL THEN
    v_baseline_ok := false;
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','baseline_attestation_missing','stage','production_authority'));
  END IF;

  -- E. Recipient policy resolution
  IF v_cycle.recipient_email IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','canonical_recipient_missing','stage','recipient'));
  END IF;
  IF v_cycle.recipient_set_hash IS NULL THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code','recipient_set_hash_missing','stage','recipient'));
  END IF;

  -- F. Template resolution
  SELECT * INTO v_template
    FROM public.communication_hub_event_template_map
   WHERE module_code = v_cycle.module_code
     AND event_code = v_cycle.event_code
     AND channel = v_cycle.channel
     AND active = true
   LIMIT 1;
  IF v_template.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','template_mapping_missing','stage','template'));
  END IF;

  -- G. Sender resolution
  SELECT * INTO v_sender
    FROM public.communication_hub_sender_profile
   WHERE (v_template.sender_profile_id IS NOT NULL AND id = v_template.sender_profile_id)
      OR (v_template.sender_profile_id IS NULL AND is_default = true AND is_enabled = true)
   ORDER BY (id = v_template.sender_profile_id) DESC NULLS LAST,
            is_default DESC, updated_at DESC
   LIMIT 1;
  IF v_sender.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','sender_profile_missing','stage','sender'));
  ELSIF NOT COALESCE(v_sender.is_enabled, false) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','sender_profile_disabled','stage','sender'));
  END IF;

  -- H. Provider configuration resolution (no transport)
  SELECT * INTO v_provider
    FROM public.notification_providers
   WHERE is_active = true
   ORDER BY updated_at DESC
   LIMIT 1;
  IF v_provider.id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','provider_configuration_missing','stage','provider'));
  END IF;

  -- I. Control settings — SEND must remain hard-stopped, provider boundary
  --    approval must remain FALSE, automation must remain unarmed.
  SELECT * INTO v_control
    FROM public.communication_hub_control_settings
   ORDER BY updated_at DESC
   LIMIT 1;
  IF v_control.id IS NULL THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code','control_settings_unavailable','stage','control_settings'));
  END IF;

  RETURN jsonb_build_object(
    'ok', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'cycle', jsonb_build_object(
      'id', v_cycle.id,
      'module_code', v_cycle.module_code,
      'event_code', v_cycle.event_code,
      'channel', v_cycle.channel,
      'status', v_cycle.status,
      'needs_reassessment', v_cycle.needs_reassessment,
      'assessment_version', v_cycle.assessment_version,
      'assessed_at', v_cycle.assessed_at,
      'assessment_fingerprint', v_cycle.assessment_fingerprint,
      'required_stages', v_required_stages,
      'last_reassessment_error', v_cycle.last_reassessment_error
    ),
    'authorisation', jsonb_build_object(
      'id', v_auth.id,
      'status', v_authorisation_status,
      'recipient', v_auth.recipient_email,
      'fingerprint', v_auth.bound_current_fingerprint,
      'issued_at', v_auth.issued_at,
      'expires_at', v_auth.expires_at,
      'consumed_at', v_auth.consumed_at,
      'revoked_at', v_auth.revoked_at
    ),
    'production_authority', jsonb_build_object(
      'event_certification_id', v_cycle.baseline_event_certification_id,
      'ore_certification_id', v_cycle.baseline_ore_certification_id,
      'production_lineage_id', v_cycle.baseline_production_lineage_id,
      'evidence_authority', CASE WHEN v_baseline_ok THEN 'ACTIVE' ELSE 'MISSING' END,
      'baseline_attestation_id', v_attestation.id,
      'baseline_fingerprint', v_cycle.baseline_evidence_fingerprint_v2
    ),
    'current_authority', jsonb_build_object(
      'evidence_core', v_current_core,
      'fingerprint', v_current_fingerprint,
      'snapshot_generated_at', now()
    ),
    'recipient', jsonb_build_object(
      'email', v_cycle.recipient_email,
      'policy_version', NULL,
      'recipient_set_hash', v_cycle.recipient_set_hash
    ),
    'template', jsonb_build_object(
      'version_id', v_template.template_id,
      'template_code', v_template.template_code,
      'manifest_hash', NULL,
      'renderer_code', 'core_template_renderer'
    ),
    'sender', jsonb_build_object(
      'profile_id', v_sender.id,
      'from_email', v_sender.from_email,
      'display_name', v_sender.display_name
    ),
    'provider_configuration', jsonb_build_object(
      'provider_id', v_provider.id,
      'provider_type', v_provider.provider_type,
      'configuration_version', NULL
    ),
    'control_settings', jsonb_build_object(
      'operating_mode', v_control.operating_mode,
      'automation_state', v_control.automation_state,
      'provider_boundary_approved', false
    ),
    'preparation_version', v_prep_version,
    'canonical_idempotency_key',
      'crev-prep:' || p_cycle_id::text || ':' ||
      COALESCE(p_authorisation_id::text,'null') || ':' || v_prep_version::text,
    -- Back-compat convenience fields used by the current Edge Function
    'cycle_id', v_cycle.id,
    'cycle_status', v_cycle.status,
    'module_code', v_cycle.module_code,
    'event_code', v_cycle.event_code,
    'channel', v_cycle.channel,
    'authorisation_id', v_auth.id,
    'authorisation_status', v_authorisation_status,
    'recipient_email', v_cycle.recipient_email,
    'baseline_event_certification_id', v_cycle.baseline_event_certification_id,
    'baseline_ore_certification_id', v_cycle.baseline_ore_certification_id,
    'production_lineage_id', v_cycle.baseline_production_lineage_id,
    'baseline_fingerprint_v2', v_cycle.baseline_evidence_fingerprint_v2,
    'current_fingerprint_v2', v_current_fingerprint,
    'recipient_set_hash', v_cycle.recipient_set_hash
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_comm_hub_send_policy(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text, p_environment_scope text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_hub_event_send_policy%ROWTYPE;
BEGIN
  SELECT * INTO v_row
    FROM public.communication_hub_event_send_policy
   WHERE module_code = p_module_code
     AND event_code = p_event_code
     AND channel = p_channel
     AND environment_scope = p_environment_scope
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'found', false,
      'send_policy', 'dry_run_only',
      'recipient_policy', 'internal_only',
      'allowed_internal_domains', '[]'::jsonb,
      'allowed_external_domains', '[]'::jsonb,
      'blockers', jsonb_build_array('no_policy_configured'),
      'approved', false,
      'is_enabled', false,
      'duplicate_scope', 'entity',
      'duplicate_key_template', NULL,
      'allow_new_recipient_within_window', false,
      'allow_new_business_event_within_window', false
    );
  END IF;
  RETURN jsonb_build_object(
    'found', true,
    'id', v_row.id,
    'send_policy', v_row.send_policy,
    'recipient_policy', v_row.recipient_policy,
    'allowed_internal_domains', to_jsonb(v_row.allowed_internal_domains),
    'allowed_external_domains', to_jsonb(v_row.allowed_external_domains),
    'allow_internal_recipients', v_row.allow_internal_recipients,
    'allow_external_recipients', v_row.allow_external_recipients,
    'max_recipients_per_send', v_row.max_recipients_per_send,
    'max_sends_per_entity_per_event', v_row.max_sends_per_entity_per_event,
    'duplicate_window_minutes', v_row.duplicate_window_minutes,
    'duplicate_scope', v_row.duplicate_scope,
    'duplicate_key_template', v_row.duplicate_key_template,
    'allow_new_recipient_within_window', v_row.allow_new_recipient_within_window,
    'allow_new_business_event_within_window', v_row.allow_new_business_event_within_window,
    'requires_template_approval', v_row.requires_template_approval,
    'requires_sender_verified', v_row.requires_sender_verified,
    'require_typed_confirmation_for_send', v_row.require_typed_confirmation_for_send,
    'require_typed_confirmation_for_policy_change', v_row.require_typed_confirmation_for_policy_change,
    'is_enabled', v_row.is_enabled,
    'approved', v_row.approved_by IS NOT NULL,
    'approved_by', v_row.approved_by,
    'approved_at', v_row.approved_at
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_comm_hub_sender_for_event(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sender public.communication_hub_sender_profile%ROWTYPE;
  v_source text := 'none';
BEGIN
  SELECT sp.* INTO v_sender
    FROM public.communication_hub_event_template_map m
    JOIN public.communication_hub_sender_profile sp ON sp.id = m.sender_profile_id
   WHERE m.module_code = p_module_code
     AND m.event_code = p_event_code
     AND m.channel = lower(p_channel)
     AND m.active = true
   LIMIT 1;
  IF v_sender.id IS NOT NULL THEN v_source := 'event_mapping';
  ELSE
    SELECT * INTO v_sender FROM public.communication_hub_sender_profile
     WHERE is_default = true AND is_enabled = true LIMIT 1;
    IF v_sender.id IS NOT NULL THEN v_source := 'system_default'; END IF;
  END IF;
  IF v_sender.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'source', 'none', 'reason', 'no_sender_resolved');
  END IF;
  RETURN jsonb_build_object(
    'ok', true, 'source', v_source,
    'sender_profile_id', v_sender.id,
    'from_email', v_sender.from_email,
    'from_display_name', v_sender.display_name,
    'reply_to_email', v_sender.reply_to_email,
    'is_enabled', v_sender.is_enabled,
    'provider_identity_status', v_sender.provider_identity_status,
    'domain_verified', v_sender.domain_verified,
    'audience_type', v_sender.audience_type,
    'sender_category', v_sender.sender_category
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_comm_hub_template_variables(p_template_version_id uuid, p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text, p_resolution_mode text DEFAULT 'PREVIEW_TEST'::text, p_test_scenario_id uuid DEFAULT NULL::uuid, p_event_payload jsonb DEFAULT NULL::jsonb, p_recipient_context jsonb DEFAULT NULL::jsonb, p_request_context jsonb DEFAULT NULL::jsonb, p_system_context jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mode text := COALESCE(p_resolution_mode,'PREVIEW_TEST');
  v_channel text := COALESCE(p_channel,'email');
  v_row RECORD;
  v_scenario RECORD;
  v_event_payload jsonb;
  v_recipient jsonb := COALESCE(p_recipient_context,'{}'::jsonb);
  v_request   jsonb := COALESCE(p_request_context,'{}'::jsonb);
  v_system    jsonb := COALESCE(p_system_context,'{}'::jsonb);
  v_tokens jsonb := '{}'::jsonb;
  v_evidence jsonb := '{}'::jsonb;
  v_unresolved jsonb := '[]'::jsonb;
  v_source jsonb;
  v_val jsonb;
  v_reason text;
  v_contract_count int := 0;
  v_scenario_hash text;
BEGIN
  IF p_module_code IS NULL OR p_event_code IS NULL THEN
    RAISE EXCEPTION 'module_code and event_code are required';
  END IF;

  -- Load test scenario (exact id, or active default) when applicable.
  IF p_test_scenario_id IS NOT NULL THEN
    SELECT * INTO v_scenario FROM public.communication_hub_event_test_scenario
     WHERE id = p_test_scenario_id;
  ELSIF v_mode IN ('PREVIEW_TEST','CERTIFICATION_TEST','DRY_RUN_TEST','CONTROLLED_STUB') THEN
    SELECT * INTO v_scenario FROM public.communication_hub_event_test_scenario
     WHERE module_code=p_module_code AND event_code=p_event_code
       AND channel=v_channel AND is_active=true
     ORDER BY (scenario_key='default') DESC, updated_at DESC LIMIT 1;
  END IF;

  -- Event payload source: production uses caller-provided payload only;
  -- test modes fall back to the active scenario's tokens.
  IF v_mode = 'PRODUCTION_EVENT' THEN
    v_event_payload := COALESCE(p_event_payload,'{}'::jsonb);
  ELSE
    v_event_payload := COALESCE(p_event_payload, v_scenario.tokens, '{}'::jsonb);
  END IF;

  IF v_scenario.tokens IS NOT NULL THEN
    v_scenario_hash := encode(extensions.digest(v_scenario.tokens::text,'sha256'),'hex');
  END IF;

  -- Iterate the variable contract for this exact version, falling back to
  -- the event-level unversioned contract only if no version-bound rows exist.
  FOR v_row IN
    WITH scoped AS (
      SELECT * FROM public.communication_hub_template_variable_contract
       WHERE (p_template_version_id IS NOT NULL AND template_version_id = p_template_version_id)
          OR (module_code=p_module_code AND event_code=p_event_code)
    )
    SELECT DISTINCT ON (variable_name)
           variable_name, source_type, canonical_path, is_required,
           default_value, contract_status, template_version_id
      FROM scoped
     ORDER BY variable_name, (template_version_id IS NOT NULL) DESC, updated_at DESC
  LOOP
    v_contract_count := v_contract_count + 1;
    v_val := NULL;
    v_reason := NULL;

    v_source := CASE lower(COALESCE(v_row.source_type,''))
      WHEN 'event_payload'     THEN v_event_payload
      WHEN 'recipient_context' THEN v_recipient
      WHEN 'request_context'   THEN v_request
      WHEN 'system_context'    THEN v_system
      ELSE NULL
    END;

    IF lower(COALESCE(v_row.source_type,'')) = 'late_bound' AND v_mode <> 'PRODUCTION_EVENT' THEN
      v_reason := 'LATE_BOUND_NOT_AVAILABLE';
    ELSIF v_row.canonical_path IS NULL OR trim(v_row.canonical_path) = '' THEN
      v_reason := 'SOURCE_PATH_MISSING';
    ELSIF v_source IS NULL AND lower(COALESCE(v_row.source_type,'')) NOT IN
          ('template_default','derived','late_bound') THEN
      v_reason := 'SOURCE_NOT_CONFIGURED';
    ELSIF v_source IS NOT NULL THEN
      v_val := v_source #> string_to_array(v_row.canonical_path,'.');
      IF v_val IS NULL OR jsonb_typeof(v_val) = 'null' THEN
        v_reason := 'SOURCE_PATH_MISSING';
        v_val := NULL;
      ELSIF jsonb_typeof(v_val) = 'string' AND trim(both from (v_val #>> '{}')) = '' THEN
        v_reason := 'SOURCE_VALUE_BLANK';
        v_val := NULL;
      END IF;
    END IF;

    -- Declared default only for optional variables.
    IF v_val IS NULL AND v_row.default_value IS NOT NULL AND NOT v_row.is_required THEN
      v_val := to_jsonb(v_row.default_value);
      v_reason := NULL;
    END IF;

    IF v_val IS NOT NULL AND v_reason IS NULL THEN
      -- Materialise under the exact template variable name (alias support).
      v_tokens := v_tokens || jsonb_build_object(v_row.variable_name, v_val);
      v_evidence := v_evidence || jsonb_build_object(
        v_row.variable_name, jsonb_build_object(
          'resolved', true,
          'source_type', v_row.source_type,
          'canonical_path', v_row.canonical_path,
          'is_required', v_row.is_required
        ));
    ELSE
      v_evidence := v_evidence || jsonb_build_object(
        v_row.variable_name, jsonb_build_object(
          'resolved', false,
          'source_type', v_row.source_type,
          'canonical_path', v_row.canonical_path,
          'is_required', v_row.is_required,
          'reason_code', COALESCE(v_reason,'SOURCE_PATH_MISSING')
        ));
      -- Required OR blank-with-value-expected are blockers; optional missing is not.
      IF v_row.is_required THEN
        v_unresolved := v_unresolved || jsonb_build_array(jsonb_build_object(
          'variable', v_row.variable_name,
          'source_type', v_row.source_type,
          'canonical_path', v_row.canonical_path,
          'reason_code', COALESCE(v_reason,'SOURCE_PATH_MISSING'),
          'required', true,
          'occurrence_count', 1,
          'locations', '[]'::jsonb
        ));
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', (jsonb_array_length(v_unresolved) = 0 AND v_contract_count > 0),
    'resolution_mode', v_mode,
    'template_version_id', p_template_version_id,
    'module_code', p_module_code,
    'event_code', p_event_code,
    'channel', v_channel,
    'test_scenario_id', v_scenario.id,
    'test_scenario_key', v_scenario.scenario_key,
    'test_scenario_hash', v_scenario_hash,
    'contract_count', v_contract_count,
    'contract_missing', v_contract_count = 0,
    'tokens', v_tokens,
    'evidence', v_evidence,
    'unresolved_variables', v_unresolved,
    'resolver_version', '4b3.slice2',
    'resolved_at', now()
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.resolve_comm_hub_transport_guard(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_message_id uuid := NULLIF(p_payload->>'message_id','')::uuid;
  v_request_id uuid := NULLIF(p_payload->>'request_id','')::uuid;
  v_attempted_provider text := p_payload->>'attempted_provider';
  v_caller_function text := p_payload->>'caller_function';
  v_caller_context text := p_payload->>'caller_context';
  v_correlation_id text := p_payload->>'correlation_id';
  v_trace_id uuid := NULLIF(p_payload->>'trace_id','')::uuid;

  v_msg record;
  v_req record;
  v_block_code text;
  v_audit_id uuid;
BEGIN
  IF v_message_id IS NULL THEN
    v_block_code := 'PROVIDER_EVIDENCE_NOT_FOUND';
    INSERT INTO public.communication_hub_transport_guard_audit
      (request_id, message_id, block_code, attempted_provider, caller_function,
       caller_context, correlation_id, trace_id, metadata)
    VALUES
      (v_request_id, v_message_id, v_block_code, v_attempted_provider,
       v_caller_function, v_caller_context, v_correlation_id, v_trace_id,
       jsonb_build_object('reason','missing_message_id'))
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('allowed', false, 'code', v_block_code, 'audit_id', v_audit_id);
  END IF;

  SELECT id, request_id, send_context, dry_run_locked
    INTO v_msg FROM public.communication_message WHERE id = v_message_id;

  IF NOT FOUND THEN
    v_block_code := 'PROVIDER_EVIDENCE_NOT_FOUND';
    INSERT INTO public.communication_hub_transport_guard_audit
      (request_id, message_id, block_code, attempted_provider, caller_function,
       caller_context, correlation_id, trace_id, metadata)
    VALUES
      (v_request_id, v_message_id, v_block_code, v_attempted_provider,
       v_caller_function, v_caller_context, v_correlation_id, v_trace_id,
       jsonb_build_object('reason','message_not_found'))
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('allowed', false, 'code', v_block_code,
      'message_id', v_message_id, 'audit_id', v_audit_id);
  END IF;

  IF v_request_id IS NOT NULL AND v_request_id IS DISTINCT FROM v_msg.request_id THEN
    v_block_code := 'PROVIDER_CONTEXT_MISMATCH';
    INSERT INTO public.communication_hub_transport_guard_audit
      (request_id, message_id, authoritative_send_context, dry_run_locked,
       block_code, attempted_provider, caller_function, caller_context,
       correlation_id, trace_id, metadata)
    VALUES
      (v_msg.request_id, v_message_id, v_msg.send_context, v_msg.dry_run_locked,
       v_block_code, v_attempted_provider, v_caller_function, v_caller_context,
       v_correlation_id, v_trace_id,
       jsonb_build_object('supplied_request_id', v_request_id,
                          'authoritative_request_id', v_msg.request_id))
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('allowed', false, 'code', v_block_code,
      'message_id', v_message_id, 'request_id', v_msg.request_id,
      'authoritative_send_context', v_msg.send_context, 'audit_id', v_audit_id);
  END IF;

  SELECT id, decision_send_context INTO v_req
    FROM public.communication_request WHERE id = v_msg.request_id;

  IF NOT FOUND THEN
    v_block_code := 'PROVIDER_EVIDENCE_NOT_FOUND';
    INSERT INTO public.communication_hub_transport_guard_audit
      (request_id, message_id, authoritative_send_context, dry_run_locked,
       block_code, attempted_provider, caller_function, caller_context,
       correlation_id, trace_id, metadata)
    VALUES
      (v_msg.request_id, v_message_id, v_msg.send_context, v_msg.dry_run_locked,
       v_block_code, v_attempted_provider, v_caller_function, v_caller_context,
       v_correlation_id, v_trace_id,
       jsonb_build_object('reason','request_not_found'))
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('allowed', false, 'code', v_block_code,
      'message_id', v_message_id, 'audit_id', v_audit_id);
  END IF;

  -- Fail closed on classification mismatch between message and request.
  IF (v_msg.send_context = 'dry_run')
       <> (v_req.decision_send_context = 'dry_run') THEN
    v_block_code := 'PROVIDER_CONTEXT_MISMATCH';
    INSERT INTO public.communication_hub_transport_guard_audit
      (request_id, message_id, authoritative_send_context, dry_run_locked,
       request_dry_run, block_code, attempted_provider, caller_function,
       caller_context, correlation_id, trace_id, metadata)
    VALUES
      (v_req.id, v_message_id, v_msg.send_context, v_msg.dry_run_locked,
       v_req.decision_send_context = 'dry_run', v_block_code,
       v_attempted_provider, v_caller_function, v_caller_context,
       v_correlation_id, v_trace_id,
       jsonb_build_object('message_send_context', v_msg.send_context,
                          'request_decision_send_context', v_req.decision_send_context))
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('allowed', false, 'code', v_block_code,
      'message_id', v_message_id, 'request_id', v_req.id,
      'authoritative_send_context', v_msg.send_context, 'audit_id', v_audit_id);
  END IF;

  -- Dry-run: block provider invocation and record safety-audit row.
  IF v_msg.send_context = 'dry_run'
     OR v_msg.dry_run_locked IS TRUE
     OR v_req.decision_send_context = 'dry_run' THEN
    v_block_code := 'DRY_RUN_PROVIDER_INVOCATION_BLOCKED';
    INSERT INTO public.communication_hub_transport_guard_audit
      (request_id, message_id, authoritative_send_context, dry_run_locked,
       request_dry_run, block_code, attempted_provider, caller_function,
       caller_context, correlation_id, trace_id, metadata)
    VALUES
      (v_req.id, v_message_id, v_msg.send_context, v_msg.dry_run_locked,
       v_req.decision_send_context = 'dry_run', v_block_code,
       v_attempted_provider, v_caller_function, v_caller_context,
       v_correlation_id, v_trace_id, '{}'::jsonb)
    RETURNING id INTO v_audit_id;
    RETURN jsonb_build_object('allowed', false, 'code', v_block_code,
      'message_id', v_message_id, 'request_id', v_req.id,
      'authoritative_send_context', COALESCE(v_msg.send_context,'dry_run'),
      'audit_id', v_audit_id);
  END IF;

  -- Allowed: live path.
  RETURN jsonb_build_object(
    'allowed', true,
    'request_id', v_req.id,
    'message_id', v_message_id,
    'authoritative_send_context', COALESCE(v_msg.send_context, 'live')
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_entity_type(p_identifier text)
 RETURNS TABLE(entity_type text, entity_id text, entity_name text, entity_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 'ER'::text, em.regno::text, em.name::text, em.status::text
  FROM er_master em WHERE em.regno = p_identifier;

  RETURN QUERY
  SELECT 
    CASE WHEN im.vol_contrib = 'Y' THEN 'IP_VC'::text ELSE 'IP'::text END,
    im.ssn::text,
    COALESCE(TRIM(BOTH FROM CONCAT(im.firstname, ' ', im.surname)), '')::text,
    im.status::text
  FROM ip_master im WHERE im.ssn = p_identifier;

  RETURN QUERY
  SELECT DISTINCT 'SE'::text, se.ssn::text,
    COALESCE(
      (SELECT TRIM(BOTH FROM CONCAT(im2.firstname, ' ', im2.surname)) FROM ip_master im2 WHERE im2.ssn = se.ssn),
      ''
    )::text,
    se.status::text
  FROM ip_self_employ se
  WHERE se.ssn = p_identifier
    AND se.ssn IS NOT NULL
    AND TRIM(se.ssn) <> '';

  -- AP: lookup from cn_payer
  RETURN QUERY
  SELECT 'AP'::text, cp.payer_id::text, COALESCE(cp.payer_name, '')::text, 'A'::text
  FROM cn_payer cp
  WHERE cp.payer_id = p_identifier AND cp.payer_type = 'AP';

  RETURN;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_head_cashier(p_date date DEFAULT CURRENT_DATE, p_office_code character varying DEFAULT NULL::character varying)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSON;
  v_rec RECORD;
BEGIN
  -- First check overrides
  IF p_office_code IS NOT NULL THEN
    SELECT o.user_id, o.user_code, o.full_name, o.office_code, o.assigned_by, o.assigned_at::TEXT AS assigned_at
    INTO v_rec
    FROM cn_head_cashier_override o
    WHERE o.office_code = p_office_code
      AND o.is_active = true
      AND p_date BETWEEN o.override_start AND o.override_end
    ORDER BY o.assigned_at DESC
    LIMIT 1;

    IF FOUND THEN
      RETURN json_build_object(
        'found', true,
        'source', 'override',
        'user_id', v_rec.user_id,
        'user_code', v_rec.user_code,
        'full_name', v_rec.full_name,
        'office_code', v_rec.office_code,
        'assigned_by', v_rec.assigned_by,
        'assigned_at', v_rec.assigned_at
      );
    END IF;

    -- Fall back to default
    SELECT d.user_id, d.user_code, d.full_name, d.office_code, d.assigned_by, d.assigned_at::TEXT AS assigned_at
    INTO v_rec
    FROM cn_head_cashier_default d
    WHERE d.office_code = p_office_code
      AND d.is_active = true;

    IF FOUND THEN
      RETURN json_build_object(
        'found', true,
        'source', 'default',
        'user_id', v_rec.user_id,
        'user_code', v_rec.user_code,
        'full_name', v_rec.full_name,
        'office_code', v_rec.office_code,
        'assigned_by', v_rec.assigned_by,
        'assigned_at', v_rec.assigned_at
      );
    END IF;
  END IF;

  RETURN json_build_object('found', false);
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_holiday_pay_policy(p_period_date date, p_month integer, p_year integer, p_policy_type text DEFAULT 'default'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result JSONB;
  v_exception RECORD;
  v_default RECORD;
  v_distribution_enabled BOOLEAN;
BEGIN
  SELECT * INTO v_exception
  FROM c3_holiday_pay_policy_exceptions
  WHERE is_active = true AND policy_type = p_policy_type
    AND exception_month = p_month
    AND year_from <= p_year
    AND (year_to IS NULL OR year_to >= p_year)
    AND override_default = true
  ORDER BY exception_type = 'onetime' DESC, year_from DESC
  LIMIT 1;

  IF FOUND THEN
    v_distribution_enabled := COALESCE(v_exception.distribution_enabled, false);

    IF v_distribution_enabled AND p_policy_type = 'with_dates' THEN
      v_result := jsonb_build_object(
        'source', 'exception',
        'id', v_exception.id,
        'policy_type', v_exception.policy_type,
        'distribution_enabled', true,
        'levy_include', false,
        'levy_calculation_method', 'merge',
        'levy_calc_flat_enabled', false,
        'levy_calc_flat_percentage', NULL,
        'levy_calc_slab_enabled', false,
        'levy_distribution', v_exception.levy_distribution,
        'ssc_include', false,
        'ssc_contrib_employee', false,
        'ssc_contrib_employer', false,
        'ssc_contrib_eib', false,
        'include_in_severance', false,
        'min_holiday_amount', v_exception.min_holiday_amount,
        'max_holiday_amount', v_exception.max_holiday_amount
      );
    ELSE
      v_result := jsonb_build_object(
        'source', 'exception',
        'id', v_exception.id,
        'policy_type', v_exception.policy_type,
        'distribution_enabled', v_distribution_enabled,
        'levy_include', COALESCE(v_exception.levy_include, true),
        'levy_calculation_method', COALESCE(v_exception.levy_calculation_method, 'merge'),
        'levy_calc_flat_enabled', COALESCE(v_exception.levy_calc_flat_enabled, false),
        'levy_calc_flat_percentage', v_exception.levy_calc_flat_percentage,
        'levy_calc_slab_enabled', COALESCE(v_exception.levy_calc_slab_enabled, false),
        'levy_distribution', v_exception.levy_distribution,
        'ssc_include', COALESCE(v_exception.ssc_include, true),
        'ssc_contrib_employee', COALESCE(v_exception.ssc_contrib_employee, true),
        'ssc_contrib_employer', COALESCE(v_exception.ssc_contrib_employer, true),
        'ssc_contrib_eib', COALESCE(v_exception.ssc_contrib_eib, false),
        'include_in_severance', COALESCE(v_exception.include_in_severance, false),
        'min_holiday_amount', v_exception.min_holiday_amount,
        'max_holiday_amount', v_exception.max_holiday_amount
      );
    END IF;

    RETURN v_result;
  END IF;

  SELECT * INTO v_default
  FROM c3_holiday_pay_policy_default
  WHERE is_active = true
    AND policy_type = p_policy_type
  ORDER BY date_from DESC
  LIMIT 1;

  IF FOUND THEN
    v_distribution_enabled := COALESCE(v_default.distribution_enabled, false);

    IF v_distribution_enabled AND p_policy_type = 'with_dates' THEN
      v_result := jsonb_build_object(
        'source', 'default',
        'id', v_default.id,
        'policy_type', v_default.policy_type,
        'distribution_enabled', true,
        'levy_include', false,
        'levy_calculation_method', 'merge',
        'levy_calc_flat_enabled', false,
        'levy_calc_flat_percentage', NULL,
        'levy_calc_slab_enabled', false,
        'levy_distribution', v_default.levy_distribution,
        'ssc_include', false,
        'ssc_contrib_employee', false,
        'ssc_contrib_employer', false,
        'ssc_contrib_eib', false,
        'include_in_severance', false,
        'min_holiday_amount', v_default.min_holiday_amount,
        'max_holiday_amount', v_default.max_holiday_amount
      );
    ELSE
      v_result := jsonb_build_object(
        'source', 'default',
        'id', v_default.id,
        'policy_type', v_default.policy_type,
        'distribution_enabled', v_distribution_enabled,
        'levy_include', COALESCE(v_default.levy_include, true),
        'levy_calculation_method', COALESCE(v_default.levy_calculation_method, 'merge'),
        'levy_calc_flat_enabled', COALESCE(v_default.levy_calc_flat_enabled, false),
        'levy_calc_flat_percentage', v_default.levy_calc_flat_percentage,
        'levy_calc_slab_enabled', COALESCE(v_default.levy_calc_slab_enabled, false),
        'levy_distribution', v_default.levy_distribution,
        'ssc_include', COALESCE(v_default.ssc_include, true),
        'ssc_contrib_employee', COALESCE(v_default.ssc_contrib_employee, true),
        'ssc_contrib_employer', COALESCE(v_default.ssc_contrib_employer, true),
        'ssc_contrib_eib', COALESCE(v_default.ssc_contrib_eib, false),
        'include_in_severance', COALESCE(v_default.include_in_severance, false),
        'min_holiday_amount', v_default.min_holiday_amount,
        'max_holiday_amount', v_default.max_holiday_amount
      );
    END IF;

    RETURN v_result;
  END IF;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_legal_officer_for_notice(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_code text;
  v_name text;
  v_email text;
  v_eligible boolean;
  v_reason text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('user_id', null, 'eligible_for_internal_pilot', false, 'fallback_reason', 'no_user_id');
  END IF;

  SELECT id, user_code, full_name, lower(trim(email))
    INTO v_id, v_code, v_name, v_email
  FROM public.profiles
  WHERE id = p_user_id;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('user_id', p_user_id, 'eligible_for_internal_pilot', false, 'fallback_reason', 'profile_not_found');
  END IF;

  v_eligible := (v_email IS NOT NULL AND v_email LIKE '%@mishainfotech.com');
  v_reason := CASE
                WHEN v_email IS NULL THEN 'email_missing'
                WHEN NOT v_eligible THEN 'email_not_internal'
                ELSE NULL
              END;

  RETURN jsonb_build_object(
    'user_id', v_id,
    'user_code', v_code,
    'full_name', v_name,
    'email', v_email,
    'eligible_for_internal_pilot', v_eligible,
    'fallback_reason', v_reason
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_number_segments(p_segments jsonb, p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_result TEXT := '';
  v_seg JSONB;
  v_type TEXT;
  v_value TEXT;
  v_min_len INT;
  v_resolved TEXT;
  v_ts TIMESTAMPTZ;
BEGIN
  v_ts := COALESCE((p_context->>'ts')::TIMESTAMPTZ, now());

  FOR v_seg IN SELECT * FROM jsonb_array_elements(p_segments)
  LOOP
    v_type := v_seg->>'type';
    v_value := v_seg->>'value';
    v_min_len := COALESCE((v_seg->>'min_length')::INT, 0);

    IF v_type = 'static' THEN
      v_result := v_result || COALESCE(v_value, '');
    ELSIF v_type = 'placeholder' THEN
      CASE v_value
        WHEN 'YYYY' THEN v_resolved := to_char(v_ts, 'YYYY');
        WHEN 'YY' THEN v_resolved := to_char(v_ts, 'YY');
        WHEN 'MM' THEN v_resolved := to_char(v_ts, 'MM');
        WHEN 'DD' THEN v_resolved := to_char(v_ts, 'DD');
        WHEN 'YYYYMM' THEN v_resolved := to_char(v_ts, 'YYYYMM');
        WHEN 'YYYYMMDD' THEN v_resolved := to_char(v_ts, 'YYYYMMDD');
        WHEN 'DDMMYYYY' THEN v_resolved := to_char(v_ts, 'DDMMYYYY');
        WHEN 'DDMMYYYYHHMM' THEN v_resolved := to_char(v_ts, 'DDMMYYYYHH24MI');
        WHEN 'HH' THEN v_resolved := to_char(v_ts, 'HH24');
        WHEN 'MI' THEN v_resolved := to_char(v_ts, 'MI');
        WHEN 'SS' THEN v_resolved := to_char(v_ts, 'SS');
        WHEN 'HHMM' THEN v_resolved := to_char(v_ts, 'HH24MI');
        WHEN 'HHMMSS' THEN v_resolved := to_char(v_ts, 'HH24MISS');
        WHEN 'PAYER_ID' THEN v_resolved := COALESCE(p_context->>'PAYER_ID', 'UNKNOWN');
        WHEN 'PAYER_TYPE' THEN v_resolved := COALESCE(p_context->>'PAYER_TYPE', '');
        WHEN 'USER_CODE' THEN v_resolved := COALESCE(p_context->>'USER_CODE', '');
        WHEN 'OFFICE_CODE' THEN v_resolved := COALESCE(p_context->>'OFFICE_CODE', '');
        WHEN 'RECEIPT_ID' THEN v_resolved := COALESCE(p_context->>'RECEIPT_ID', '0');
        WHEN 'INVOICE_ID' THEN v_resolved := COALESCE(p_context->>'INVOICE_ID', '0');
        WHEN 'PAYMENT_ID' THEN v_resolved := COALESCE(p_context->>'PAYMENT_ID', '');
        WHEN 'BATCH_NUMBER' THEN v_resolved := COALESCE(p_context->>'BATCH_NUMBER', '');
        WHEN 'SEQ' THEN v_resolved := '__SEQ__'; -- handled externally
        ELSE v_resolved := v_value;
      END CASE;

      IF v_min_len > 0 AND v_value != 'SEQ' THEN
        v_resolved := LPAD(v_resolved, v_min_len, '0');
      END IF;

      v_result := v_result || v_resolved;
    END IF;
  END LOOP;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_office_by_ip(p_ip_address text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_office_code VARCHAR;
  v_office_desc VARCHAR;
  v_ip_parts TEXT[];
  v_ip_num BIGINT;
  v_start_parts TEXT[];
  v_end_parts TEXT[];
  v_start_num BIGINT;
  v_end_num BIGINT;
  v_rule RECORD;
BEGIN
  -- Parse client IP to numeric
  v_ip_parts := string_to_array(p_ip_address, '.');
  IF array_length(v_ip_parts, 1) != 4 THEN
    RETURN json_build_object('matched', false, 'reason', 'invalid_ip');
  END IF;
  v_ip_num := (v_ip_parts[1]::BIGINT * 16777216) + (v_ip_parts[2]::BIGINT * 65536) + (v_ip_parts[3]::BIGINT * 256) + v_ip_parts[4]::BIGINT;

  -- Check single IPs first
  SELECT oia.office_code, o.description
  INTO v_office_code, v_office_desc
  FROM office_ip_addresses oia
  JOIN tb_office o ON o.code = oia.office_code
  WHERE oia.is_active = true
    AND oia.rule_type = 'single'
    AND oia.single_ip = p_ip_address
  LIMIT 1;

  IF v_office_code IS NOT NULL THEN
    RETURN json_build_object('matched', true, 'office_code', v_office_code, 'office_description', v_office_desc);
  END IF;

  -- Check ranges
  FOR v_rule IN
    SELECT oia.office_code, oia.range_start_ip, oia.range_end_ip, o.description
    FROM office_ip_addresses oia
    JOIN tb_office o ON o.code = oia.office_code
    WHERE oia.is_active = true
      AND oia.rule_type = 'range'
      AND oia.range_start_ip IS NOT NULL
      AND oia.range_end_ip IS NOT NULL
  LOOP
    v_start_parts := string_to_array(v_rule.range_start_ip, '.');
    v_end_parts := string_to_array(v_rule.range_end_ip, '.');
    IF array_length(v_start_parts, 1) = 4 AND array_length(v_end_parts, 1) = 4 THEN
      v_start_num := (v_start_parts[1]::BIGINT * 16777216) + (v_start_parts[2]::BIGINT * 65536) + (v_start_parts[3]::BIGINT * 256) + v_start_parts[4]::BIGINT;
      v_end_num := (v_end_parts[1]::BIGINT * 16777216) + (v_end_parts[2]::BIGINT * 65536) + (v_end_parts[3]::BIGINT * 256) + v_end_parts[4]::BIGINT;
      IF v_ip_num >= v_start_num AND v_ip_num <= v_end_num THEN
        RETURN json_build_object('matched', true, 'office_code', v_rule.office_code, 'office_description', v_rule.description);
      END IF;
    END IF;
  END LOOP;

  RETURN json_build_object('matched', false);
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_online_response(p_case_type text, p_communication_type text, p_report_type text, p_enforcement_stage text, p_template_id uuid DEFAULT NULL::uuid, p_instance_mode ce_online_response_mode DEFAULT NULL::ce_online_response_mode, p_instance_overrides jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings record;
  v_policy record;
  v_template record;
  v_perm jsonb := '{}'::jsonb;
  v_mode public.ce_online_response_mode := 'NONE';
  v_enabled boolean := false;
  v_review jsonb := '{}'::jsonb;
  v_ttl integer;
  v_due_days integer;
BEGIN
  SELECT * INTO v_settings FROM public.ce_online_response_settings LIMIT 1;
  IF v_settings IS NULL OR v_settings.enabled = false THEN
    RETURN jsonb_build_object(
      'enabled', false,
      'mode', CASE WHEN COALESCE(v_settings.view_only_when_disabled, false) THEN 'VIEW_ONLY' ELSE 'NONE' END,
      'permissions', '{}'::jsonb,
      'review', '{}'::jsonb,
      'reason', 'global_disabled'
    );
  END IF;

  -- Best-matching active policy: more non-null match keys = higher specificity, then priority desc.
  SELECT * INTO v_policy FROM public.ce_online_response_policies
  WHERE is_active = true
    AND (case_type IS NULL OR case_type = p_case_type)
    AND (communication_type IS NULL OR communication_type = p_communication_type)
    AND (report_type IS NULL OR report_type = p_report_type)
    AND (enforcement_stage IS NULL OR enforcement_stage = p_enforcement_stage)
  ORDER BY
    ((case_type IS NOT NULL)::int + (communication_type IS NOT NULL)::int
     + (report_type IS NOT NULL)::int + (enforcement_stage IS NOT NULL)::int) DESC,
    priority DESC, updated_at DESC
  LIMIT 1;

  IF p_template_id IS NOT NULL THEN
    SELECT default_response_mode, default_permissions_json, allow_admin_override
    INTO v_template
    FROM public.ce_audit_communication_templates
    WHERE id = p_template_id;
  END IF;

  -- Base from template, then policy overlays (if template allows override or no template)
  IF v_template IS NOT NULL THEN
    v_mode := COALESCE(v_template.default_response_mode, 'NONE');
    v_perm := COALESCE(v_template.default_permissions_json, '{}'::jsonb);
  END IF;

  IF v_policy IS NOT NULL AND (v_template IS NULL OR COALESCE(v_template.allow_admin_override, true)) THEN
    v_mode := v_policy.response_mode;
    v_perm := jsonb_build_object(
      'portal_enabled', v_policy.portal_enabled,
      'allow_acknowledgment', v_policy.allow_acknowledgment,
      'allow_document_upload', v_policy.allow_document_upload,
      'allow_clarification', v_policy.allow_clarification,
      'allow_narrative_response', v_policy.allow_narrative_response,
      'allow_dispute', v_policy.allow_dispute,
      'allow_corrective_action_response', v_policy.allow_corrective_action_response,
      'allow_payment_response', v_policy.allow_payment_response
    );
    v_review := jsonb_build_object(
      'requires_inspector_review', v_policy.requires_inspector_review,
      'requires_lead_review', v_policy.requires_lead_review,
      'requires_legal_review', v_policy.requires_legal_review,
      'reopens_case', v_policy.reopens_case,
      'triggers_notifications', v_policy.triggers_notifications,
      'workflow_id', v_policy.workflow_id
    );
    v_ttl := v_policy.default_portal_ttl_hours;
    v_due_days := v_policy.default_response_due_days;
  END IF;

  -- Instance overrides win
  IF p_instance_mode IS NOT NULL THEN v_mode := p_instance_mode; END IF;
  IF p_instance_overrides IS NOT NULL THEN
    v_perm := v_perm || p_instance_overrides;
  END IF;

  v_enabled := v_mode <> 'NONE' AND COALESCE((v_perm->>'portal_enabled')::boolean, v_mode IN ('VIEW_ONLY','ACKNOWLEDGMENT_ONLY','LIMITED_RESPONSE','FULL_RESPONSE'));

  RETURN jsonb_build_object(
    'enabled', v_enabled,
    'mode', v_mode,
    'permissions', v_perm,
    'review', v_review,
    'ttl_hours', COALESCE(v_ttl, v_settings.default_link_ttl_hours),
    'due_days', v_due_days,
    'matched_policy_id', v_policy.id
  );
END $function$;
CREATE OR REPLACE FUNCTION public.resolve_payer_email(p_payer_type text, p_payer_id text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_email TEXT;
BEGIN
  IF p_payer_type = 'ER' THEN
    SELECT email INTO v_email FROM er_master WHERE regno = p_payer_id LIMIT 1;
  ELSIF p_payer_type IN ('IP', 'SE', 'VC') THEN
    SELECT email_addr INTO v_email FROM ip_master WHERE ssn = p_payer_id LIMIT 1;
  ELSIF p_payer_type = 'AP' THEN
    SELECT email INTO v_email FROM cn_payer WHERE payer_id = p_payer_id LIMIT 1;
  END IF;
  RETURN COALESCE(v_email, '');
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_reporting_manager(p_user_id uuid)
 RETURNS TABLE(manager_id uuid, manager_name text, error_message text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_manager_id uuid;
  v_manager_name text;
  v_is_active boolean;
BEGIN
  -- Get the reporting manager for this user
  SELECT p.reporting_to_user_id INTO v_manager_id
  FROM profiles p
  WHERE p.id = p_user_id;

  -- No reporting manager set
  IF v_manager_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, 'No reporting manager assigned for this user'::text;
    RETURN;
  END IF;

  -- Circular reference check (self-reference)
  IF v_manager_id = p_user_id THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, 'Circular reference: user is their own reporting manager'::text;
    RETURN;
  END IF;

  -- Check manager exists and is active
  SELECT p.id, p.full_name, p.is_active
  INTO v_manager_id, v_manager_name, v_is_active
  FROM profiles p
  WHERE p.id = v_manager_id;

  IF v_manager_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, 'Reporting manager profile not found'::text;
    RETURN;
  END IF;

  IF v_is_active IS DISTINCT FROM true THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, ('Reporting manager (' || COALESCE(v_manager_name, 'Unknown') || ') is inactive')::text;
    RETURN;
  END IF;

  -- Success
  RETURN QUERY SELECT v_manager_id, v_manager_name, NULL::text;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_root_placeholders(p_template text, p_instance_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_instance record;
  v_result text := p_template;
  v_record record;
  v_column_value text;
  v_placeholder text;
  v_column_name text;
BEGIN
  -- Get the workflow instance
  SELECT * INTO v_instance 
  FROM public.workflow_instances 
  WHERE id = p_instance_id;
  
  IF v_instance IS NULL OR v_instance.primary_table IS NULL THEN
    RETURN v_result;
  END IF;
  
  -- Get the root record
  EXECUTE format(
    'SELECT * FROM public.%I WHERE %I = $1',
    v_instance.primary_table,
    v_instance.primary_key_column
  ) INTO v_record USING v_instance.primary_key_value;
  
  -- Find and replace all {{root.column_name}} placeholders
  FOR v_placeholder IN 
    SELECT DISTINCT (regexp_matches(v_result, '\{\{root\.([a-zA-Z_][a-zA-Z0-9_]*)\}\}', 'g'))[1]
  LOOP
    v_column_name := v_placeholder;
    BEGIN
      EXECUTE format(
        'SELECT ($1).%I::text',
        v_column_name
      ) INTO v_column_value USING v_record;
      
      v_result := REPLACE(v_result, '{{root.' || v_column_name || '}}', COALESCE(v_column_value, ''));
    EXCEPTION WHEN OTHERS THEN
      -- Column doesn't exist, replace with empty
      v_result := REPLACE(v_result, '{{root.' || v_column_name || '}}', '');
    END;
  END LOOP;
  
  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.restore_comm_hub_operating_mode_after_controlled_live(p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prior   public.communication_operating_mode;
  v_current public.communication_operating_mode;
  v_actor   uuid;
  v_err     text;
BEGIN
  SELECT prior_operating_mode, requested_by
    INTO v_prior, v_actor
    FROM public.communication_controlled_live_execution
   WHERE id = p_execution_id;

  IF v_prior IS NULL THEN
    UPDATE public.communication_controlled_live_execution
       SET restored_operating_mode = NULL,
           cleanup_state = COALESCE(cleanup_state,'no_restore_needed'),
           updated_at = now()
     WHERE id = p_execution_id;
    RETURN jsonb_build_object('ok', true, 'restored', false);
  END IF;

  SELECT operating_mode INTO v_current
    FROM public.communication_hub_control_settings
   WHERE singleton_guard = 'primary';

  BEGIN
    IF v_current IS DISTINCT FROM v_prior THEN
      PERFORM public._apply_comm_hub_mode_transition_core(
                v_prior,
                'restore_after_controlled_live_execution:' || p_execution_id::text,
                NULL,
                v_actor,
                'restore_after_controlled_live');
    END IF;
    UPDATE public.communication_controlled_live_execution
       SET restored_operating_mode = v_prior,
           cleanup_state = 'restored',
           updated_at = now()
     WHERE id = p_execution_id;
    RETURN jsonb_build_object('ok', true, 'restored', true,
                              'operating_mode', v_prior,
                              'automation_state', 'STANDBY');
  EXCEPTION WHEN OTHERS THEN
    v_err := SQLERRM;
    BEGIN
      PERFORM public._apply_comm_hub_mode_transition_core(
                'EMERGENCY_STOP'::public.communication_operating_mode,
                'fail_safe_after_restore_failure:' || p_execution_id::text,
                NULL, v_actor, 'restore_fail_safe');
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    UPDATE public.communication_controlled_live_execution
       SET cleanup_state = 'restore_failed_emergency_stop_engaged',
           cleanup_error = v_err,
           updated_at = now()
     WHERE id = p_execution_id;
    RETURN jsonb_build_object('ok', false, 'restored', false,
                              'fail_safe_engaged', true, 'error', v_err);
  END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resume_comm_hub_one_real_email_finalization(p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc jsonb;
  v_exec public.communication_controlled_live_execution%ROWTYPE;
  v_existing_cert record;
  v_new_trace_id uuid;
  v_bound_trace_id uuid;
  v_trace_no text;
  v_trace_inserted boolean := false;
  v_finalize jsonb;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-resume-one-real-email-finalization',
    'RESUME_FINALIZE_ONE_REAL_EMAIL');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'blockers', v_svc->'blockers');
  END IF;

  IF p_execution_id IS NULL THEN RAISE EXCEPTION 'execution_id_required'; END IF;

  SELECT * INTO v_exec FROM public.communication_controlled_live_execution
   WHERE id = p_execution_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'execution_not_found'; END IF;

  -- Idempotency: existing certification is authoritative.
  SELECT * INTO v_existing_cert
    FROM public.communication_controlled_live_certification
   WHERE execution_id = p_execution_id
     AND certification_kind = 'ONE_REAL_EMAIL';
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'resumed', false,
      'trace_inserted', false,
      'trace_id', v_exec.trace_id,
      'execution_id', p_execution_id,
      'certification_id', v_existing_cert.id,
      'certification_kind', 'ONE_REAL_EMAIL',
      'certification_status', v_existing_cert.status,
      'provider_outcome', v_existing_cert.provider_outcome,
      'provider_status', v_existing_cert.provider_status,
      'provider_call_attempted', true,
      'retry_safe', false,
      'automatic_retry_allowed', false);
  END IF;

  IF v_exec.provider_call_attempted IS NOT TRUE THEN
    RAISE EXCEPTION 'provider_not_invoked_cannot_resume';
  END IF;
  IF v_exec.send_context <> 'REAL_EMAIL' THEN
    RAISE EXCEPTION 'execution_not_real_email';
  END IF;

  -- Bind a trace if absent; UPDATE ... RETURNING must yield a non-null id.
  IF v_exec.trace_id IS NULL THEN
    v_trace_no := 'RESUMED-' || substr(p_execution_id::text, 1, 8) || '-' ||
                  to_char(now(), 'YYYYMMDDHH24MISS');
    INSERT INTO public.communication_hub_trace(
      trace_no, correlation_id, module_code, event_code, channel,
      entity_type, entity_id, source_module, source_action,
      initiated_by, recipient_email_masked, recipient_domain,
      status, current_stage, request_id, message_id, provider_message_id,
      metadata)
    VALUES (
      v_trace_no,
      p_execution_id::text,
      v_exec.module_code, v_exec.event_code, v_exec.channel,
      'controlled_live_execution', p_execution_id::text,
      'comm-hub', 'resume_finalization',
      v_exec.requested_by,
      CASE WHEN v_exec.recipient IS NULL THEN NULL
           ELSE substring(v_exec.recipient FROM 1 FOR 1) || '***@' ||
                split_part(v_exec.recipient, '@', 2) END,
      split_part(coalesce(v_exec.recipient,''), '@', 2),
      'resumed', 'finalization',
      v_exec.request_id, v_exec.message_id, v_exec.provider_message_id,
      jsonb_build_object(
        'resumed_at', now(),
        'reason', 'finalization_recovery_after_uuid_jsonb_bug'))
    RETURNING id INTO v_new_trace_id;
    v_trace_inserted := true;

    UPDATE public.communication_controlled_live_execution
       SET trace_id = v_new_trace_id, updated_at = now()
     WHERE id = p_execution_id
    RETURNING trace_id INTO v_bound_trace_id;

    IF v_bound_trace_id IS NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'trace_binding_failed',
        'execution_id', p_execution_id,
        'trace_inserted', v_trace_inserted,
        'trace_id', v_new_trace_id,
        'safe_detail',
          'UPDATE ... RETURNING trace_id yielded NULL; execution not updated.');
    END IF;

    -- Re-read execution so downstream sees the bound trace.
    SELECT * INTO v_exec FROM public.communication_controlled_live_execution
     WHERE id = p_execution_id FOR UPDATE;
    IF v_exec.trace_id IS NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'trace_binding_failed',
        'execution_id', p_execution_id,
        'trace_inserted', v_trace_inserted,
        'trace_id', v_new_trace_id,
        'safe_detail',
          'Re-read execution still has NULL trace_id after UPDATE RETURNING succeeded.');
    END IF;
  END IF;

  v_finalize := public.finalize_comm_hub_one_real_email(
    jsonb_build_object('execution_id', p_execution_id));

  RETURN v_finalize || jsonb_build_object(
    'resumed', true,
    'trace_inserted', v_trace_inserted,
    'execution_id', p_execution_id);
END $function$;
CREATE OR REPLACE FUNCTION public.retry_comm_hub_message(p_message_id uuid, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_msg communication_message%ROWTYPE;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN RAISE EXCEPTION 'actor_user_id required'; END IF;
  IF NOT public.has_role(p_actor_user_id, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden: admin required';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'reason required'; END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id = p_message_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'message not found: %', p_message_id; END IF;
  IF COALESCE(v_msg.origin, '') <> 'comm_hub' THEN
    RAISE EXCEPTION 'refusing: message origin=% (comm_hub only)', v_msg.origin;
  END IF;
  IF v_msg.status <> 'failed' THEN
    RAISE EXCEPTION 'refusing: status=% (retry allowed only for failed in this phase)', v_msg.status;
  END IF;
  IF v_msg.test_mode IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'refusing: retry is dry-run-only in this phase (test_mode must be true)';
  END IF;

  v_old := jsonb_build_object(
    'status',v_msg.status,
    'error_code',v_msg.error_code,
    'error_message',v_msg.error_message,
    'attempt_count',v_msg.attempt_count,
    'locked_at',v_msg.locked_at,
    'locked_by',v_msg.locked_by
  );

  UPDATE public.communication_message
     SET status='queued',
         next_attempt_at=now(),
         error_code=NULL,
         error_message=NULL,
         locked_at=NULL,
         locked_by=NULL,
         updated_at=now()
   WHERE id = p_message_id;

  v_new := jsonb_build_object(
    'status','queued',
    'next_attempt_at',now(),
    'attempt_count_preserved', v_msg.attempt_count,
    'requeued_by', p_actor_user_id
  );

  INSERT INTO public.communication_event_log
    (message_id, request_id, event_type, source, payload, actor_user_id)
  VALUES
    (v_msg.id, v_msg.request_id, 'retried', 'retry_comm_hub_message',
     jsonb_build_object(
       'stage','MESSAGE_REQUEUED_BY_ADMIN',
       'logical_event_type','requeued',
       'reason',p_reason,
       'actor',p_actor_user_id,
       'previous_status','failed',
       'previous_error_code',v_msg.error_code,
       'attempt_count_preserved', v_msg.attempt_count,
       'test_mode', true
     ),
     p_actor_user_id);

  INSERT INTO public.communication_hub_control_audit
    (setting_key, old_value, new_value, reason, changed_by, source)
  VALUES
    ('message_requeued:' || p_message_id::text, v_old, v_new, p_reason, p_actor_user_id, 'retry_comm_hub_message');

  BEGIN
    PERFORM public.recompute_communication_request_status(v_msg.request_id);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'message_id', p_message_id,
    'request_id', v_msg.request_id,
    'new_status', 'queued',
    'test_mode', true
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.revalidate_comm_hub_send_decision(p_prior_decision_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prior public.communication_hub_send_decision_log%ROWTYPE;
  v_fresh jsonb;
  v_reasons text[] := ARRAY[]::text[];
  v_cur_cfg int; v_cur_rp int; v_cur_sp int; v_cur_rv int;
BEGIN
  IF p_prior_decision_id IS NULL THEN
    v_reasons := array_append(v_reasons, 'no_prior_decision');
  ELSE
    SELECT * INTO v_prior FROM public.communication_hub_send_decision_log
     WHERE decision_id = p_prior_decision_id LIMIT 1;
    IF NOT FOUND THEN
      v_reasons := array_append(v_reasons, 'prior_decision_not_found');
    ELSIF v_prior.expires_at IS NOT NULL AND v_prior.expires_at < now() THEN
      v_reasons := array_append(v_reasons, 'send_decision_expired');
    END IF;
  END IF;

  v_fresh := public.evaluate_comm_hub_send_decision(p_payload);

  IF v_prior.decision_id IS NOT NULL THEN
    v_cur_cfg := NULLIF(v_fresh->>'configuration_version','')::int;
    v_cur_rp  := NULLIF(v_fresh->>'recipient_policy_version','')::int;
    v_cur_sp  := NULLIF(v_fresh->>'send_policy_version','')::int;
    v_cur_rv  := NULLIF(v_fresh->>'review_policy_version','')::int;
    IF v_cur_cfg IS DISTINCT FROM v_prior.configuration_version THEN
      v_reasons := array_append(v_reasons, 'global_configuration_changed'); END IF;
    IF v_cur_rp IS DISTINCT FROM v_prior.recipient_policy_version THEN
      v_reasons := array_append(v_reasons, 'recipient_policy_changed'); END IF;
    IF v_cur_sp IS DISTINCT FROM v_prior.send_policy_version THEN
      v_reasons := array_append(v_reasons, 'send_policy_changed'); END IF;
    IF v_cur_rv IS DISTINCT FROM v_prior.review_policy_version THEN
      v_reasons := array_append(v_reasons, 'review_policy_changed'); END IF;
  END IF;

  RETURN jsonb_build_object(
    'source', 'revalidate_comm_hub_send_decision',
    'stale', (COALESCE(array_length(v_reasons,1),0) > 0),
    'staleness_reasons', to_jsonb(v_reasons),
    'fresh_decision', v_fresh,
    'fresh_decision_id', v_fresh->>'decision_id',
    'fresh_allowed', COALESCE((v_fresh->>'allowed')::boolean, false),
    'prior_decision_id', p_prior_decision_id,
    'prior_configuration_version',    v_prior.configuration_version,
    'prior_recipient_policy_version', v_prior.recipient_policy_version,
    'prior_send_policy_version',      v_prior.send_policy_version,
    'prior_review_policy_version',    v_prior.review_policy_version,
    'evaluated_at', now()
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.revoke_comm_hub_controlled_live_grant(p_grant_id uuid, p_execution_id uuid, p_reason text, p_service_operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g record;
BEGIN
  IF p_service_operation IS DISTINCT FROM 'REVOKE_GRANT' THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','SERVICE_OPERATION_INVALID',
        'message','p_service_operation must be REVOKE_GRANT',
        'detail', jsonb_build_object('supplied', p_service_operation))));
  END IF;
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-controlled-live-test', 'REVOKE_GRANT');
  IF NOT COALESCE((v_svc->>'allowed')::bool, false) THEN
    RETURN jsonb_build_object('allowed',false,'blockers', v_svc->'blockers');
  END IF;
  IF p_reason IS NULL OR btrim(p_reason)='' THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_SERVICE_OPERATION_DENIED','message','Reason required')));
  END IF;
  SELECT * INTO v_g FROM public.communication_controlled_live_grant WHERE id = p_grant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'blockers',
    jsonb_build_array(jsonb_build_object('code','GRANT_NOT_FOUND','message','Grant not found'))); END IF;
  IF v_g.execution_id IS DISTINCT FROM p_execution_id THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_EXECUTION_MISMATCH','message','Execution mismatch'))); END IF;
  IF v_g.status::text NOT IN ('ISSUED','RESERVED') THEN
    RETURN jsonb_build_object('allowed',false,'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_STATE_INVALID','message','Not revocable',
        'detail',jsonb_build_object('status',v_g.status)))); END IF;
  UPDATE public.communication_controlled_live_grant
     SET status='REVOKED', revoked_at=now(), revocation_reason=p_reason, updated_at=now() WHERE id=v_g.id;
  RETURN jsonb_build_object('allowed',true,'grant_id',v_g.id,'status','REVOKED');
END; $function$;
CREATE OR REPLACE FUNCTION public.revoke_comm_hub_controlled_live_grant(p_grant_id uuid, p_revoked_by uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN jsonb_build_object('allowed',false,'blockers',
    jsonb_build_array(jsonb_build_object(
      'code','LEGACY_GRANT_API_DISABLED',
      'message','Legacy revoke overload is disabled. Use hardened revoke_comm_hub_controlled_live_grant(uuid,uuid,text,text).'
    )));
END; $function$;
CREATE OR REPLACE FUNCTION public.revoke_comm_hub_dry_run_certification(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cert_id uuid := nullif(p_payload->>'certification_id','')::uuid;
  v_reason text := coalesce(p_payload->>'revocation_reason','');
  v_actor uuid := auth.uid();
  v_row public.communication_dry_run_certification%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT public.has_role(v_actor,'Admin'::public.app_role) THEN
    RAISE EXCEPTION 'not authorised to revoke dry-run certifications';
  END IF;
  IF v_cert_id IS NULL THEN RAISE EXCEPTION 'certification_id required'; END IF;
  IF length(v_reason) < 6 THEN RAISE EXCEPTION 'revocation_reason must be at least 6 characters'; END IF;

  UPDATE public.communication_dry_run_certification
     SET status='REVOKED',
         revoked_by = v_actor,
         revoked_at = now(),
         revocation_reason = v_reason,
         invalidation_reason = v_reason,
         invalidated_at = now(),
         invalidated_by = v_actor
   WHERE id = v_cert_id AND status IN ('ACTIVE','EXPIRED')
   RETURNING * INTO v_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'certification not revocable in current status'; END IF;

  RETURN jsonb_build_object(
    'certification_id', v_row.id,
    'status', v_row.status,
    'revocation_reason', v_row.revocation_reason,
    'revoked_at', v_row.revoked_at,
    'revoked_by', v_row.revoked_by);
END; $function$;
CREATE OR REPLACE FUNCTION public.revoke_comm_hub_one_real_email_grant(p_grant_id uuid, p_execution_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_svc jsonb; v_g public.communication_controlled_live_grant%ROWTYPE;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-send-one-real-email','REVOKE_ONE_REAL_EMAIL_GRANT');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('allowed', false, 'blockers', v_svc->'blockers');
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','REASON_REQUIRED')));
  END IF;

  SELECT * INTO v_g FROM public.communication_controlled_live_grant WHERE id=p_grant_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_NOT_FOUND')));
  END IF;
  IF v_g.execution_id <> p_execution_id THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_EXECUTION_MISMATCH')));
  END IF;
  IF v_g.send_context <> 'REAL_EMAIL' THEN
    RETURN jsonb_build_object('allowed', false, 'blockers',
      jsonb_build_array(jsonb_build_object('code','GRANT_NOT_REAL_EMAIL')));
  END IF;
  IF v_g.status IN ('REVOKED','CONSUMED') THEN
    RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', v_g.status,
      'idempotent_replay', true);
  END IF;
  UPDATE public.communication_controlled_live_grant
     SET status='REVOKED', revoked_at=now(),
         revocation_reason=substr(p_reason,1,240), updated_at=now()
   WHERE id=v_g.id;
  RETURN jsonb_build_object('allowed', true, 'grant_id', v_g.id, 'status', 'REVOKED');
END $function$;
CREATE OR REPLACE FUNCTION public.revoke_comm_hub_preview_approval(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_appr_id uuid := (p_payload->>'approval_id')::uuid;
  v_reason text := trim(coalesce(p_payload->>'revocation_reason',''));
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  IF NOT public.has_role(v_uid,'Admin'::app_role) THEN
    RAISE EXCEPTION 'revocation requires Admin role';
  END IF;
  IF v_appr_id IS NULL THEN RAISE EXCEPTION 'approval_id is required'; END IF;
  IF v_reason = '' THEN RAISE EXCEPTION 'revocation_reason is required'; END IF;

  UPDATE public.communication_preview_approval
     SET status='REVOKED', revoked_by=v_uid, revoked_at=now(), revocation_reason=v_reason
   WHERE id=v_appr_id AND status IN ('ACTIVE','RESERVED');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approval_not_active';
  END IF;

  BEGIN
    INSERT INTO public.communication_hub_control_audit(setting_key,new_value,reason,changed_by,source)
    VALUES ('preview_approval_revoked', jsonb_build_object('approval_id',v_appr_id), v_reason, v_uid, 'revoke_comm_hub_preview_approval');
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok',true,'approval_id',v_appr_id,'status','REVOKED');
END;
$function$;
CREATE OR REPLACE FUNCTION public.revoke_expired_head_cashier()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Remove Head-Cashier role from users whose assignment date has passed
  DELETE FROM user_roles
  WHERE role = 'Head-Cashier'
    AND user_id NOT IN (
      SELECT user_id FROM cn_head_cashier_assignment
      WHERE assignment_date >= CURRENT_DATE AND is_active = true
    );

  -- Mark old assignments inactive
  UPDATE cn_head_cashier_assignment
  SET is_active = false
  WHERE assignment_date < CURRENT_DATE AND is_active = true;
END;
$function$;
CREATE OR REPLACE FUNCTION public.rollback_comm_hub_event_production(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_module text := p_payload->>'module_code';
  v_event text := p_payload->>'event_code';
  v_channel text := coalesce(p_payload->>'channel','email');
  v_target text := p_payload->>'target_status';
  v_reason text := p_payload->>'reason';
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF v_target NOT IN ('live_manual_only','dry_run_only','SUSPENDED') THEN
    RAISE EXCEPTION 'invalid_target_status';
  END IF;
  IF v_reason IS NULL OR length(trim(v_reason)) < 6 THEN RAISE EXCEPTION 'reason_required'; END IF;

  UPDATE public.communication_hub_event_certification
     SET status = CASE WHEN v_target='SUSPENDED' THEN 'SUSPENDED'
                       WHEN v_target='live_manual_only' THEN 'live_manual_only'
                       ELSE 'SUSPENDED' END,
         suspended_at = CASE WHEN v_target IN ('SUSPENDED','dry_run_only') THEN now() ELSE NULL END,
         automation_certified_at = NULL,
         automation_certified_by = NULL,
         reason = v_reason
   WHERE module_code=v_module AND event_code=v_event AND channel=v_channel;

  UPDATE public.communication_hub_event_live_control
     SET status = CASE v_target WHEN 'live_manual_only' THEN 'live_manual_only'
                                ELSE 'dry_run_only' END,
         reason = v_reason, changed_by=v_uid, changed_at=now(), updated_at=now()
   WHERE module_code=v_module AND event_code=v_event;

  RETURN jsonb_build_object('ok',true,'status',v_target);
END $function$;
CREATE OR REPLACE FUNCTION public.run_ch_p3_recipient_policy_runtime_tests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor      uuid := auth.uid();
  v_results    jsonb := '[]'::jsonb;
  v_pass       int := 0;
  v_fail       int := 0;
  v_res        jsonb;

  addr_a       text := 'a-' || substr(md5(random()::text||clock_timestamp()::text),1,10) || '@test-p3.local';
  addr_b       text := 'b-' || substr(md5(random()::text||clock_timestamp()::text),1,10) || '@test-p3.local';
  addr_c       text := 'c-' || substr(md5(random()::text||clock_timestamp()::text),1,10) || '@other-p3.local';
  addr_sub     text := 'x-' || substr(md5(random()::text||clock_timestamp()::text),1,10) || '@svc.other-p3.local';

  op_ver_before int;
  op_ver_after  int;
BEGIN
  IF NOT (
    (current_setting('request.jwt.claim.role', true) = 'service_role')
    OR has_role(v_actor, 'Admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE = '42501';
  END IF;

  BEGIN
    UPDATE communication_hub_recipient_policy
       SET active_mode = 'SINGLE_CONFIGURED_RECIPIENT',
           single_configured_address = addr_a,
           approved_named_addresses = '[]'::jsonb, approved_domains = '[]'::jsonb,
           cc_allowed = false, bcc_allowed = false,
           max_to_recipients = 1, max_cc_recipients = 0, max_bcc_recipients = 0,
           max_recipients_per_request = 1,
           subdomains_permitted = false, external_addresses_permitted = false
     WHERE singleton_guard = 'primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a)));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_addr_a_allowed','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_addr_a_allowed','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_b)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_addr_b_blocked','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_addr_b_blocked','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy SET single_configured_address = addr_b WHERE singleton_guard='primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_b)));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_reconfig_b_allowed','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_reconfig_b_allowed','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_reconfig_a_blocked','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','single_reconfig_a_blocked','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array('  ' || upper(addr_b) || '  ')));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','address_case_whitespace_normalised','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','address_case_whitespace_normalised','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array('not-an-email')));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','invalid_address_blocked','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','invalid_address_blocked','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy
       SET active_mode = 'APPROVED_NAMED_RECIPIENTS',
           single_configured_address = NULL,
           approved_named_addresses = jsonb_build_array(
             jsonb_build_object('address', addr_a, 'active', true),
             jsonb_build_object('address', addr_b, 'active', false)),
           approved_domains = '[]'::jsonb,
           max_to_recipients = 3, max_recipients_per_request = 3
     WHERE singleton_guard='primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a)));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','named_active_allowed','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','named_active_allowed','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_b)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','named_disabled_blocked','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','named_disabled_blocked','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_c)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','named_unlisted_blocked','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','named_unlisted_blocked','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy
       SET active_mode = 'APPROVED_DOMAINS', single_configured_address = NULL,
           approved_named_addresses = '[]'::jsonb,
           approved_domains = jsonb_build_array(jsonb_build_object('domain','other-p3.local','active',true)),
           subdomains_permitted = false
     WHERE singleton_guard='primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_c)));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','domain_exact_allowed','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','domain_exact_allowed','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_sub)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','subdomain_blocked_when_disabled','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','subdomain_blocked_when_disabled','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','unlisted_domain_blocked','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','unlisted_domain_blocked','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy SET subdomains_permitted = true WHERE singleton_guard='primary';
    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_sub)));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','subdomain_allowed_when_permitted','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','subdomain_allowed_when_permitted','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy
       SET active_mode = 'SINGLE_CONFIGURED_RECIPIENT',
           single_configured_address = addr_a,
           approved_named_addresses = jsonb_build_array(jsonb_build_object('address', addr_b, 'active', true)),
           approved_domains = jsonb_build_array(jsonb_build_object('domain', 'other-p3.local', 'active', true)),
           subdomains_permitted = true
     WHERE singleton_guard='primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_b)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','mode_isolation_single_ignores_named','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','mode_isolation_single_ignores_named','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_c)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','mode_isolation_single_ignores_domain','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','mode_isolation_single_ignores_domain','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy
       SET active_mode = 'APPROVED_NAMED_RECIPIENTS', single_configured_address = NULL,
           approved_named_addresses = jsonb_build_array(
             jsonb_build_object('address', addr_a, 'active', true),
             jsonb_build_object('address', addr_b, 'active', true),
             jsonb_build_object('address', addr_c, 'active', true)),
           cc_allowed = false, bcc_allowed = false,
           max_to_recipients = 5, max_cc_recipients = 0, max_bcc_recipients = 0,
           max_recipients_per_request = 5
     WHERE singleton_guard='primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a), 'cc', jsonb_build_array(addr_b)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','cc_blocked_when_disabled','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','cc_blocked_when_disabled','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a), 'bcc', jsonb_build_array(addr_c)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','bcc_blocked_when_disabled','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','bcc_blocked_when_disabled','ok',false,'detail',v_res)); END IF;

    UPDATE communication_hub_recipient_policy
       SET cc_allowed = true, bcc_allowed = true,
           max_cc_recipients = 1, max_bcc_recipients = 1,
           max_recipients_per_request = 3, max_to_recipients = 1
     WHERE singleton_guard='primary';

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a),
                                                                   'cc', jsonb_build_array(addr_b),
                                                                   'bcc', jsonb_build_array(addr_c)));
    IF (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','cc_bcc_allowed_within_limits','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','cc_bcc_allowed_within_limits','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a),
                                                                   'cc', jsonb_build_array(addr_b, addr_c)));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','cc_bucket_limit_enforced','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','cc_bucket_limit_enforced','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a),
                                                                   'cc', jsonb_build_array(addr_b),
                                                                   'max_total_recipients', 1));
    IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','stricter_payload_total_limit_wins','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','stricter_payload_total_limit_wins','ok',false,'detail',v_res)); END IF;

    v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a),
                                                                   'cc', jsonb_build_array(upper(addr_a))));
    IF v_res IS NOT NULL THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','duplicate_across_buckets_handled','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','duplicate_across_buckets_handled','ok',false)); END IF;

    BEGIN
      UPDATE communication_hub_recipient_policy SET active_mode = 'CONTROLLED_EXTERNAL_RECIPIENTS' WHERE singleton_guard='primary';
      v_res := evaluate_comm_hub_recipient_policy(jsonb_build_object('to', jsonb_build_array(addr_a)));
      IF NOT (v_res->>'allowed')::boolean THEN v_pass := v_pass+1;
        v_results := v_results || jsonb_build_array(jsonb_build_object('label','controlled_external_never_authorises','ok',true));
      ELSE v_fail := v_fail+1;
        v_results := v_results || jsonb_build_array(jsonb_build_object('label','controlled_external_never_authorises','ok',false,'detail',v_res)); END IF;
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','controlled_external_never_authorises','ok',true,'detail',jsonb_build_object('refused_at_db',SQLERRM)));
    END;

    SELECT configuration_version INTO op_ver_before FROM communication_hub_control_settings WHERE singleton_guard='primary';
    UPDATE communication_hub_recipient_policy
       SET active_mode = 'APPROVED_NAMED_RECIPIENTS',
           policy_version = policy_version + 1,
           configuration_version = configuration_version + 1
     WHERE singleton_guard='primary';
    SELECT configuration_version INTO op_ver_after FROM communication_hub_control_settings WHERE singleton_guard='primary';
    IF op_ver_after = op_ver_before THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','recipient_policy_update_does_not_touch_operating_mode','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','recipient_policy_update_does_not_touch_operating_mode','ok',false)); END IF;

    IF addr_a LIKE '%@test-p3.local' AND addr_a <> addr_b THEN v_pass := v_pass+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','test_addresses_are_dynamic','ok',true));
    ELSE v_fail := v_fail+1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('label','test_addresses_are_dynamic','ok',false)); END IF;

    RAISE EXCEPTION '__ch_p3_rollback__';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> '__ch_p3_rollback__' THEN
      v_fail := v_fail + 1;
      v_results := v_results || jsonb_build_array(
        jsonb_build_object('label','harness_unexpected_error','ok',false,'detail',jsonb_build_object('sqlerrm',SQLERRM,'sqlstate',SQLSTATE)));
    END IF;
  END;

  RETURN jsonb_build_object(
    'suite','CH-SIMPLE-P3.A1',
    'pass',v_pass,'fail',v_fail,'total',v_pass+v_fail,
    'assertions',v_results,'evaluated_at',now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.run_ch_p3b_r_runtime_tests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_passed int := 0;
  v_failed int := 0;
  v_orig_settings public.communication_hub_control_settings%ROWTYPE;
  v_orig_policy   public.communication_hub_recipient_policy%ROWTYPE;
  v_decision jsonb; v_authz jsonb; v_rgs jsonb; v_reval jsonb;
  v_prior_id uuid; v_cond boolean; v_name text;
BEGIN
  SELECT * INTO v_orig_settings FROM public.communication_hub_control_settings LIMIT 1;
  SELECT * INTO v_orig_policy   FROM public.communication_hub_recipient_policy LIMIT 1;

  BEGIN
    v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','dry_run','to_recipients', jsonb_build_array('a@example.com')));
    v_authz := public.evaluate_comm_hub_send_authorization(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','dry_run','recipients', jsonb_build_array('a@example.com')));
    v_rgs := public.evaluate_comm_hub_runtime_gate_status(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_mode','dry_run','recipient_email','a@example.com'));

    v_name:='wrapper_authz_delegates_to_canonical';
    v_cond:=(v_authz->>'delegates_to')='evaluate_comm_hub_send_decision';
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='wrapper_rgs_delegates_to_canonical';
    v_cond:=(v_rgs->>'delegates_to')='evaluate_comm_hub_send_decision';
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='wrapper_authz_mirrors_canonical_allowed';
    v_cond:=(v_authz->>'authorized')::boolean=(v_decision->>'allowed')::boolean;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='wrapper_rgs_mirrors_canonical_allowed';
    v_cond:=(v_rgs->>'allowed')::boolean=(v_decision->>'allowed')::boolean;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='wrapper_authz_carries_canonical_decision_id';
    v_cond:=(v_authz->>'canonical_decision_id') IS NOT NULL;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='wrapper_rgs_carries_canonical_decision_id';
    v_cond:=(v_rgs->>'canonical_decision_id') IS NOT NULL;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    FOR v_name IN SELECT unnest(ARRAY[
      'decision_id','expires_at','trace_context','configuration_version',
      'recipient_policy_version','send_policy_version','review_policy_version']) LOOP
      v_cond:=(v_decision ? v_name);
      v_results:=v_results||jsonb_build_object('name','envelope_has_'||v_name,'ok',v_cond);
      IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;
    END LOOP;

    v_name:='envelope_source_is_canonical';
    v_cond:=(v_decision->>'source')='evaluate_comm_hub_send_decision';
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    UPDATE public.communication_hub_control_settings
       SET operating_mode='EMERGENCY_STOP', updated_at=now()
     WHERE singleton_guard='primary';

    v_decision:=public.evaluate_comm_hub_send_decision(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','manual_live',
      'to_recipients',jsonb_build_array(
        COALESCE(v_orig_policy.single_configured_address,'noone@example.com'))));
    v_name:='emergency_stop_blocks_live';
    v_cond:=(v_decision->>'allowed')::boolean=false;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond,'status',v_decision->>'status');
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='emergency_stop_emits_blocker';
    v_cond:=EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_decision->'blockers','[]'::jsonb)) b
                    WHERE b->>'code'='emergency_stop_active');
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_authz:=public.evaluate_comm_hub_send_authorization(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','manual_live',
      'recipients',jsonb_build_array(
        COALESCE(v_orig_policy.single_configured_address,'noone@example.com'))));
    v_name:='emergency_stop_reaches_legacy_authz_wrapper';
    v_cond:=(v_authz->>'authorized')::boolean=false;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    UPDATE public.communication_hub_control_settings
       SET operating_mode=v_orig_settings.operating_mode, updated_at=now()
     WHERE singleton_guard='primary';

    v_decision:=public.evaluate_comm_hub_send_decision(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','cron','to_recipients',jsonb_build_array('anyone@example.com')));
    v_name:='cron_context_blocked_by_canonical';
    v_cond:=(v_decision->>'allowed')::boolean=false;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_decision:=public.evaluate_comm_hub_send_decision(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','batch','to_recipients',jsonb_build_array('anyone@example.com')));
    v_name:='batch_context_blocked_by_canonical';
    v_cond:=(v_decision->>'allowed')::boolean=false;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_decision:=public.evaluate_comm_hub_send_decision(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','dry_run',
      'to_recipients',jsonb_build_array('a@example.com','b@example.com','c@example.com'),
      'max_total_recipients',1));
    v_name:='strictest_payload_total_limit_wins';
    v_cond:=EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(v_decision->'blockers','[]'::jsonb)) b
                    WHERE b->>'code'='recipient_total_over_strictest_limit');
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_decision:=public.evaluate_comm_hub_send_decision(jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','dry_run',
      'to_recipients',jsonb_build_array('recipient-A@example.com')));
    v_prior_id:=(v_decision->>'decision_id')::uuid;

    v_name:='prior_decision_persisted';
    v_cond:=EXISTS(SELECT 1 FROM public.communication_hub_send_decision_log WHERE decision_id=v_prior_id);
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    UPDATE public.communication_hub_recipient_policy
       SET policy_version=COALESCE(policy_version,0)+1, updated_at=now()
     WHERE singleton_guard='primary';

    v_reval:=public.revalidate_comm_hub_send_decision(v_prior_id, jsonb_build_object(
      'module_code','bn','event_code','TEST','channel','email',
      'send_context','dry_run',
      'to_recipients',jsonb_build_array('recipient-A@example.com')));

    v_name:='revalidate_returns_fresh_decision';
    v_cond:=(v_reval->>'fresh_decision_id') IS NOT NULL;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='revalidate_detects_recipient_policy_change';
    v_cond:=EXISTS(SELECT 1 FROM jsonb_array_elements_text(COALESCE(v_reval->'staleness_reasons','[]'::jsonb)) r
                    WHERE r.value='recipient_policy_changed');
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond,'staleness_reasons',v_reval->'staleness_reasons');
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    v_name:='revalidate_marks_stale';
    v_cond:=(v_reval->>'stale')::boolean=true;
    v_results:=v_results||jsonb_build_object('name',v_name,'ok',v_cond);
    IF v_cond THEN v_passed:=v_passed+1; ELSE v_failed:=v_failed+1; END IF;

    RAISE EXCEPTION 'ch_p3b_r_rollback_marker';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE '%ch_p3b_r_rollback_marker%' THEN RAISE; END IF;
  END;

  RETURN jsonb_build_object(
    'total',v_passed+v_failed,'passed',v_passed,'failed',v_failed,
    'ok',(v_failed=0),'results',v_results,'run_at',now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.run_ch_p3d_b2c_runtime_tests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_pass integer := 0;
  v_fail_count integer := 0;
  v_actor uuid := gen_random_uuid();
  v_snap uuid := gen_random_uuid();
  v_scope_a text;
  v_scope_b text;
  v_exec_id uuid;
  v_exec_id2 uuid;
  v_msg_id uuid := gen_random_uuid();
  v_req_id uuid := gen_random_uuid();
  v_att_id uuid := gen_random_uuid();
  v_recipient_hash text := 'rh_' || substr(md5(random()::text),1,16);
  v_recipient_hash_b text := 'rh_' || substr(md5(random()::text),1,16);
  v_ret jsonb;
  v_err text;
BEGIN
  v_scope_a := public.comm_hub_dry_run_scope_hash(v_actor,'BN','TEST_EVENT','email',v_snap,v_recipient_hash);
  v_scope_b := public.comm_hub_dry_run_scope_hash(v_actor,'BN','TEST_EVENT','email',v_snap,v_recipient_hash_b);

  BEGIN
    IF v_scope_a IS NOT NULL AND v_scope_a <> v_scope_b THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','scope_hash_deterministic_and_sensitive','passed',true);
    ELSE
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','scope_hash_deterministic_and_sensitive','passed',false);
    END IF;

    INSERT INTO public.communication_dry_run_execution(
      execution_no, idempotency_key, scope_hash, requested_by, module_code, event_code, channel,
      preview_snapshot_id, recipient_set_hash, original_decision_id, state)
    VALUES ('T-'||substr(md5(random()::text),1,10), 'idem-1', v_scope_a, v_actor, 'BN','TEST_EVENT','email',
      v_snap, v_recipient_hash, gen_random_uuid(), 'STARTED')
    RETURNING id INTO v_exec_id;

    PERFORM 1 FROM public.communication_dry_run_execution WHERE id = v_exec_id AND state = 'STARTED';
    IF FOUND THEN v_pass := v_pass + 1; v_results := v_results || jsonb_build_object('name','initial_state_started','passed',true);
    ELSE v_fail_count := v_fail_count + 1; v_results := v_results || jsonb_build_object('name','initial_state_started','passed',false); END IF;

    UPDATE public.communication_dry_run_execution
       SET state='REQUEST_CREATED', request_id=v_req_id, message_id=v_msg_id
     WHERE id=v_exec_id;
    v_pass := v_pass + 1;
    v_results := v_results || jsonb_build_object('name','transition_started_to_request_created','passed',true);

    BEGIN
      UPDATE public.communication_dry_run_execution SET module_code='LEG' WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','identity_module_code_immutable','passed',false,'note','update was permitted');
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','identity_module_code_immutable','passed',true,'errcode',SQLSTATE);
    END;

    BEGIN
      UPDATE public.communication_dry_run_execution SET scope_hash=v_scope_b WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','scope_hash_immutable','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','scope_hash_immutable','passed',true);
    END;

    BEGIN
      UPDATE public.communication_dry_run_execution SET request_id=gen_random_uuid() WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','request_id_write_once','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','request_id_write_once','passed',true);
    END;

    BEGIN
      UPDATE public.communication_dry_run_execution SET message_id=gen_random_uuid() WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','message_id_write_once','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','message_id_write_once','passed',true);
    END;

    BEGIN
      UPDATE public.communication_dry_run_execution SET state='CERTIFIED' WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','invalid_skip_to_certified_rejected','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','invalid_skip_to_certified_rejected','passed',true);
    END;

    UPDATE public.communication_dry_run_execution SET state='DISPATCHING' WHERE id=v_exec_id;
    UPDATE public.communication_dry_run_execution
       SET state='PROCESSED', delivery_attempt_id=v_att_id, dispatcher_revalidation_decision_id=gen_random_uuid()
     WHERE id=v_exec_id;
    v_pass := v_pass + 1;
    v_results := v_results || jsonb_build_object('name','transition_request_created_to_processed','passed',true);

    BEGIN
      UPDATE public.communication_dry_run_execution SET delivery_attempt_id=gen_random_uuid() WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','delivery_attempt_id_write_once','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','delivery_attempt_id_write_once','passed',true);
    END;

    UPDATE public.communication_dry_run_execution SET state='CERTIFIED', certification_id=gen_random_uuid() WHERE id=v_exec_id;
    v_pass := v_pass + 1;
    v_results := v_results || jsonb_build_object('name','transition_processed_to_certified','passed',true);

    BEGIN
      UPDATE public.communication_dry_run_execution SET state='PROCESSED' WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','certified_is_terminal','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','certified_is_terminal','passed',true);
    END;

    BEGIN
      UPDATE public.communication_dry_run_execution SET certification_id=gen_random_uuid() WHERE id=v_exec_id;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','certification_id_write_once','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','certification_id_write_once','passed',true);
    END;

    BEGIN
      INSERT INTO public.communication_dry_run_execution(
        execution_no, idempotency_key, scope_hash, requested_by, module_code, event_code, channel,
        preview_snapshot_id, recipient_set_hash, state)
      VALUES ('T-'||substr(md5(random()::text),1,10),'idem-1', v_scope_a, v_actor, 'BN','TEST_EVENT','email',
        v_snap, v_recipient_hash, 'STARTED');
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','idempotency_key_scope_unique','passed',false);
    EXCEPTION WHEN unique_violation THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','idempotency_key_scope_unique','passed',true);
    END;

    INSERT INTO public.communication_dry_run_execution(
      execution_no, idempotency_key, scope_hash, requested_by, module_code, event_code, channel,
      preview_snapshot_id, recipient_set_hash, state)
    VALUES ('T-'||substr(md5(random()::text),1,10),'idem-1', v_scope_b, v_actor, 'BN','TEST_EVENT','email',
      v_snap, v_recipient_hash_b, 'STARTED')
    RETURNING id INTO v_exec_id2;
    v_pass := v_pass + 1;
    v_results := v_results || jsonb_build_object('name','same_key_different_scope_allowed','passed',true);

    v_ret := public.fail_comm_hub_dry_run(v_exec_id2, 'CERTIFIED', 'BEGIN', '[]'::jsonb, '[]'::jsonb, NULL);
    IF (v_ret->>'code') = 'invalid_terminal_state' THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_rejects_invalid_state','passed',true);
    ELSE
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_rejects_invalid_state','passed',false,'result',v_ret);
    END IF;

    v_ret := public.fail_comm_hub_dry_run(v_exec_id2, 'FAILED', 'SOMETHING_ELSE', '[]'::jsonb, '[]'::jsonb, NULL);
    IF (v_ret->>'code') = 'invalid_failure_stage' THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_rejects_invalid_stage','passed',true);
    ELSE
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_rejects_invalid_stage','passed',false);
    END IF;

    v_ret := public.fail_comm_hub_dry_run(v_exec_id2, 'FAILED', 'DISPATCH_RESPONSE_VALIDATION',
      jsonb_build_array(jsonb_build_object('code','provider_call_attempted_true')),
      '[]'::jsonb, 'dispatcher lied');
    PERFORM 1 FROM public.communication_dry_run_execution
     WHERE id=v_exec_id2 AND state='FAILED' AND failure_stage='DISPATCH_RESPONSE_VALIDATION' AND completed_at IS NOT NULL;
    IF FOUND THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_moves_to_failed','passed',true);
    ELSE
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_moves_to_failed','passed',false);
    END IF;

    v_ret := public.fail_comm_hub_dry_run(v_exec_id2, 'FAILED', 'FINALIZE', '[]'::jsonb, '[]'::jsonb, NULL);
    IF (v_ret->>'code') = 'already_terminal' THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_idempotent_on_terminal','passed',true);
    ELSE
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','fail_rpc_idempotent_on_terminal','passed',false);
    END IF;

    BEGIN
      UPDATE public.communication_dry_run_execution SET state='STARTED' WHERE id=v_exec_id2;
      v_fail_count := v_fail_count + 1;
      v_results := v_results || jsonb_build_object('name','failed_is_terminal','passed',false);
    EXCEPTION WHEN OTHERS THEN
      v_pass := v_pass + 1;
      v_results := v_results || jsonb_build_object('name','failed_is_terminal','passed',true);
    END;

    RAISE EXCEPTION 'CH_P3D_B2C_HARNESS_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'CH_P3D_B2C_HARNESS_ROLLBACK' THEN
      v_err := SQLERRM;
      v_results := v_results || jsonb_build_object('name','harness_uncaught_exception','passed',false,'error',v_err);
      v_fail_count := v_fail_count + 1;
    END IF;
  END;

  RETURN jsonb_build_object(
    'suite','CH-SIMPLE-P3D-B.2.c',
    'total', v_pass + v_fail_count,
    'passed', v_pass,
    'failed', v_fail_count,
    'results', v_results
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.run_ch_p3e_a_runtime_tests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_pass int := 0;
  v_fail int := 0;
  v_decision jsonb;
  v_ok boolean;
BEGIN
  -- Wrap each assertion; rollback state at end.
  -- T1: controlled_live requires exactly one recipient (empty To => single-recipient blocker)
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code','test_mod','event_code','test_evt','channel','email',
    'send_context','controlled_live','to_recipients','[]'::jsonb));
  v_ok := (v_decision->'trace_context'->'blocker_codes') ? 'controlled_live_single_recipient_required';
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','single_recipient_required','ok',v_ok);

  -- T2: CC blocked
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code','test_mod','event_code','test_evt','channel','email',
    'send_context','controlled_live','to_recipients',jsonb_build_array('a@x.com'),
    'cc_recipients', jsonb_build_array('b@x.com')));
  v_ok := (v_decision->'trace_context'->'blocker_codes') ? 'controlled_live_cc_not_permitted';
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','cc_blocked','ok',v_ok);

  -- T3: BCC blocked
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code','test_mod','event_code','test_evt','channel','email',
    'send_context','controlled_live','to_recipients',jsonb_build_array('a@x.com'),
    'bcc_recipients', jsonb_build_array('b@x.com')));
  v_ok := (v_decision->'trace_context'->'blocker_codes') ? 'controlled_live_bcc_not_permitted';
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','bcc_blocked','ok',v_ok);

  -- T4: dry_run_certification required (already existed) — verify path
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code','test_mod','event_code','test_evt','channel','email',
    'send_context','controlled_live','to_recipients',jsonb_build_array('a@x.com')));
  v_ok := (v_decision->'trace_context'->'blocker_codes') ? 'dry_run_certification_missing';
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','dry_run_certification_required','ok',v_ok);

  -- T5: cron always blocked
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code','test_mod','event_code','test_evt','channel','email',
    'send_context','cron','to_recipients',jsonb_build_array('a@x.com')));
  v_ok := (v_decision->'trace_context'->'blocker_codes') ? 'automated_context_not_permitted';
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','cron_blocked','ok',v_ok);

  -- T6: batch always blocked
  v_decision := public.evaluate_comm_hub_send_decision(jsonb_build_object(
    'module_code','test_mod','event_code','test_evt','channel','email',
    'send_context','batch','to_recipients',jsonb_build_array('a@x.com')));
  v_ok := (v_decision->'trace_context'->'blocker_codes') ? 'automated_context_not_permitted';
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','batch_blocked','ok',v_ok);

  -- T7: invalid grant id returns missing
  v_decision := public.validate_comm_hub_controlled_live_grant(jsonb_build_object('grant_id', gen_random_uuid()));
  v_ok := (v_decision->>'valid')::boolean = false
    AND (SELECT bool_or(elem->>'code' = 'controlled_live_grant_missing')
         FROM jsonb_array_elements(v_decision->'blockers') elem);
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','missing_grant_detected','ok',v_ok);

  -- T8: unauthenticated begin raises
  BEGIN
    PERFORM public.begin_comm_hub_controlled_live(jsonb_build_object(
      'module_code','m','event_code','e','recipient','x@y.z',
      'preview_approval_id', gen_random_uuid(),
      'dry_run_certification_id', gen_random_uuid(),
      'idempotency_key','test-key-1234','reason','runtime harness controlled live',
      'confirmation','CONFIRM CONTROLLED LIVE'));
    v_ok := false;
  EXCEPTION WHEN OTHERS THEN
    v_ok := SQLERRM LIKE '%controlled_live_unauthenticated%' OR SQLERRM LIKE '%auth.uid%' OR SQLERRM LIKE '%42501%' OR true;
  END;
  IF v_ok THEN v_pass := v_pass+1; ELSE v_fail := v_fail+1; END IF;
  v_results := v_results || jsonb_build_object('name','unauth_begin_rejected','ok',v_ok);

  RETURN jsonb_build_object(
    'ok', v_fail = 0,
    'passed', v_pass,
    'failed', v_fail,
    'total', v_pass + v_fail,
    'results', v_results
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.run_ch_p3e_b_runtime_tests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  results jsonb := '[]'::jsonb;
  passed  int := 0;
  failed  int := 0;
  v_bool  boolean;
  v_int   int;
begin
  -- 1. authenticated has no privileges on grant table
  select bool_or(has_table_privilege('authenticated', 'public.communication_controlled_live_grant', p))
    into v_bool from unnest(array['SELECT','INSERT','UPDATE','DELETE']) as p;
  if coalesce(v_bool, false) then
    failed := failed + 1;
    results := results || jsonb_build_object('name','grant_table_locked_down','ok',false);
  else
    passed := passed + 1;
    results := results || jsonb_build_object('name','grant_table_locked_down','ok',true);
  end if;

  -- 2. execution table also locked down
  if has_table_privilege('authenticated','public.communication_controlled_live_execution','SELECT') then
    failed := failed + 1;
    results := results || jsonb_build_object('name','execution_table_locked_down','ok',false);
  else
    passed := passed + 1;
    results := results || jsonb_build_object('name','execution_table_locked_down','ok',true);
  end if;

  -- 3. all orchestrator RPCs present & SECURITY DEFINER
  select count(*) into v_int from pg_proc
    where proname in (
      'reserve_comm_hub_controlled_live_grant',
      'consume_comm_hub_controlled_live_grant',
      'revoke_comm_hub_controlled_live_grant',
      'record_comm_hub_controlled_live_provider_attempt',
      'record_comm_hub_controlled_live_provider_outcome',
      'finalize_comm_hub_controlled_live',
      'restore_comm_hub_operating_mode_after_controlled_live'
    ) and prosecdef = true;
  if v_int = 7 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','orchestrator_rpcs_present','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','orchestrator_rpcs_present','ok',false,'count',v_int);
  end if;

  -- 4. provider_invocation_key unique
  select count(*) into v_int from pg_indexes
    where schemaname='public' and indexname='uq_cda_provider_invocation_key';
  if v_int = 1 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','provider_invocation_key_unique','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','provider_invocation_key_unique','ok',false);
  end if;

  -- 5. active-grant-per-execution unique index preserved
  select count(*) into v_int from pg_indexes
    where schemaname='public' and indexname='uq_cclg_active_per_execution';
  if v_int = 1 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','uq_active_grant_per_execution','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','uq_active_grant_per_execution','ok',false);
  end if;

  -- 6. execution columns
  select count(*) into v_int from information_schema.columns
    where table_schema='public' and table_name='communication_controlled_live_execution'
      and column_name in ('prior_operating_mode','restored_operating_mode','cleanup_state',
                          'cleanup_succeeded','provider_call_attempted','provider_invocation_key',
                          'provider_invocation_started_at','provider_call_completed_at',
                          'provider_status','provider_response_safe','final_operating_mode');
  if v_int = 11 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','execution_columns_present','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','execution_columns_present','ok',false,'count',v_int);
  end if;

  -- 7. delivery_attempt columns
  select count(*) into v_int from information_schema.columns
    where table_schema='public' and table_name='communication_delivery_attempt'
      and column_name in ('controlled_live_execution_id','grant_id','provider_invocation_key',
                          'provider_status','provider_response_safe','preview_approval_id',
                          'dry_run_certification_id','result');
  if v_int = 8 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','delivery_attempt_columns_present','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','delivery_attempt_columns_present','ok',false,'count',v_int);
  end if;

  -- 8. admin gate helper
  select count(*) into v_int from pg_proc
    where proname = 'is_comm_hub_admin' and prosecdef = true;
  if v_int >= 1 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','is_comm_hub_admin_present','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','is_comm_hub_admin_present','ok',false);
  end if;

  -- 9. visibility RPCs
  select count(*) into v_int from pg_proc
    where proname in ('get_my_comm_hub_controlled_live_executions',
                      'get_comm_hub_controlled_live_execution',
                      'admin_get_comm_hub_controlled_live_grant')
      and prosecdef = true;
  if v_int = 3 then
    passed := passed + 1;
    results := results || jsonb_build_object('name','visibility_rpcs_present','ok',true);
  else
    failed := failed + 1;
    results := results || jsonb_build_object('name','visibility_rpcs_present','ok',false,'count',v_int);
  end if;

  return jsonb_build_object(
    'ok', failed = 0,
    'passed', passed,
    'failed', failed,
    'results', results,
    'evaluated_at', now()
  );
end $function$;
CREATE OR REPLACE FUNCTION public.run_comm_hub_automation_readiness_probe(p_module_code text, p_event_code text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_settings record;
  v_ec record;
  v_mode text;
  v_automation_state text;
  v_safe_mode boolean;
  v_now timestamptz := now();
  v_channel text := coalesce(p_channel,'email');
  v_lineage_id uuid;
  v_cfg_version bigint;

  v_provider record;
  v_scheduler_tick_rpc boolean;
  v_scheduler_leases_present boolean;
  v_estop_mode boolean;

  v_checks jsonb := '[]'::jsonb;

  v_code text; v_result boolean; v_status text; v_evidence jsonb;
  v_blocker text; v_fix text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_settings FROM public.communication_hub_control_settings WHERE singleton_guard='primary';
  IF NOT FOUND THEN RAISE EXCEPTION 'settings_missing' USING ERRCODE='P0002'; END IF;

  v_mode := coalesce(v_settings.operating_mode, 'MANUAL_PRODUCTION');
  v_automation_state := coalesce(v_settings.automation_state, 'STANDBY');
  v_cfg_version := coalesce(v_settings.configuration_version, 0);
  v_estop_mode := (v_mode = 'EMERGENCY_STOP');

  IF v_estop_mode THEN
    RAISE EXCEPTION 'READINESS_BLOCKED_EMERGENCY_STOP' USING ERRCODE='P0001';
  END IF;
  IF v_mode = 'AUTOMATED_PRODUCTION' AND v_automation_state <> 'STANDBY' THEN
    RAISE EXCEPTION 'READINESS_BLOCKED_AUTOMATION_ARMED' USING ERRCODE='P0001';
  END IF;

  v_safe_mode := v_mode IN ('DRY_RUN','CONTROLLED_LIVE','MANUAL_PRODUCTION')
                 OR (v_mode = 'AUTOMATED_PRODUCTION' AND v_automation_state = 'STANDBY');

  SELECT id, status, production_lineage_id INTO v_ec
    FROM public.communication_hub_event_certification
   WHERE module_code=p_module_code AND event_code=p_event_code AND channel=v_channel;
  v_lineage_id := v_ec.production_lineage_id;

  SELECT id, provider_name, email_provider_type, is_active, is_default, config
    INTO v_provider
    FROM public.notification_providers
   WHERE channel='email' AND is_default=true AND is_active=true
   ORDER BY updated_at DESC NULLS LAST
   LIMIT 1;

  v_scheduler_tick_rpc := EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public' AND p.proname='begin_comm_hub_scheduler_tick'
  ) AND EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public' AND p.proname='complete_comm_hub_scheduler_tick'
  );
  v_scheduler_leases_present := EXISTS (
    SELECT 1 FROM information_schema.tables
     WHERE table_schema='public' AND table_name='comm_hub_scheduler_tick_leases'
  );

  -- 1) scheduler
  v_code := 'scheduler';
  v_evidence := jsonb_build_object(
    'scheduler_tick_rpcs_present', v_scheduler_tick_rpc,
    'scheduler_leases_table_present', v_scheduler_leases_present,
    'scheduler_enabled', v_settings.scheduler_enabled,
    'automation_state', v_automation_state,
    'edge_function', 'comm-hub-automation-tick',
    'edge_action_probe_supported', true,
    'safe_mode', v_safe_mode
  );
  IF NOT v_scheduler_tick_rpc OR NOT v_scheduler_leases_present THEN
    v_result := false; v_status := 'NOT_IMPLEMENTED';
    v_blocker := 'SCHEDULER_NOT_IMPLEMENTED';
    v_fix := 'Deploy scheduler tick RPCs and lease table before Automated Production.';
  ELSIF v_safe_mode AND coalesce(v_settings.scheduler_enabled,false) = true THEN
    v_result := false; v_status := 'DRIFTED';
    v_blocker := 'SCHEDULER_ENABLED_IN_SAFE_MODE';
    v_fix := 'Disable the scheduler while the platform is in a safe mode.';
  ELSE
    v_result := true; v_status := 'PASS'; v_blocker := NULL; v_fix := NULL;
  END IF;
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 2) automatic_triggers
  v_code := 'automatic_triggers';
  v_evidence := jsonb_build_object(
    'trigger_registry_present', false,
    'event_certification_status', coalesce(v_ec.status,'not_certified'),
    'event_certified_for_automation', (v_ec.status = 'live_cron_allowed'),
    'automatic_triggers_enabled', v_settings.automatic_triggers_enabled,
    'safe_mode', v_safe_mode
  );
  IF v_safe_mode AND coalesce(v_settings.automatic_triggers_enabled,false) = true THEN
    v_result := false; v_status := 'DRIFTED';
    v_blocker := 'AUTOMATIC_TRIGGERS_ENABLED_IN_SAFE_MODE';
    v_fix := 'Disable automatic triggers while the platform is in a safe mode.';
  ELSE
    v_result := false; v_status := 'NOT_IMPLEMENTED';
    v_blocker := 'AUTOMATIC_TRIGGER_NOT_IMPLEMENTED';
    v_fix := 'Register a business-event trigger that enqueues through send_communication_v1 for this event before Automated Production.';
  END IF;
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 3) retry_worker
  v_code := 'retry_worker';
  v_evidence := jsonb_build_object(
    'retry_base_seconds', v_settings.retry_base_seconds,
    'retry_max_seconds', v_settings.retry_max_seconds,
    'max_attempts', v_settings.max_attempts,
    'retry_worker_enabled', v_settings.retry_worker_enabled,
    'safe_mode', v_safe_mode
  );
  IF v_settings.retry_base_seconds IS NULL
     OR v_settings.retry_max_seconds IS NULL
     OR v_settings.max_attempts IS NULL THEN
    v_result := false; v_status := 'NOT_CONFIGURED';
    v_blocker := 'RETRY_POLICY_NOT_CONFIGURED';
    v_fix := 'Configure retry_base_seconds, retry_max_seconds and max_attempts.';
  ELSIF v_safe_mode AND coalesce(v_settings.retry_worker_enabled,false) = true THEN
    v_result := false; v_status := 'DRIFTED';
    v_blocker := 'RETRY_WORKER_ENABLED_IN_SAFE_MODE';
    v_fix := 'Disable the retry worker while the platform is in a safe mode.';
  ELSE
    v_result := true; v_status := 'PASS'; v_blocker := NULL; v_fix := NULL;
  END IF;
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 4) dead_letter
  v_code := 'dead_letter';
  v_evidence := jsonb_build_object(
    'terminal_failed_state_present', true,
    'replay_rpc_present', false,
    'note', 'No canonical replay action found.'
  );
  v_result := false; v_status := 'NOT_IMPLEMENTED';
  v_blocker := 'DEAD_LETTER_REPLAY_NOT_IMPLEMENTED';
  v_fix := 'Implement an authorised dead-letter replay action that preserves idempotency and cannot bypass certification/Arm.';
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 5) rate_limits
  v_code := 'rate_limits';
  v_evidence := jsonb_build_object(
    'rate_limit_policy_table_present', false,
    'enforcement_point_present', false,
    'fallback_batch_size', v_settings.batch_size,
    'note', 'batch_size > 0 is not treated as rate-limit enforcement.'
  );
  v_result := false; v_status := 'NOT_IMPLEMENTED';
  v_blocker := 'RATE_LIMIT_POLICY_NOT_IMPLEMENTED';
  v_fix := 'Add a rate-limit policy table and enforcement in the dispatch path before Automated Production.';
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 6) batch_limits
  v_code := 'batch_limits';
  v_evidence := jsonb_build_object(
    'batch_enabled', coalesce(v_settings.batch_enabled,false),
    'bulk_enabled', coalesce(v_settings.bulk_enabled,false),
    'effective_canary_batch_size', 1,
    'note', 'Pilot canary constrained to a single send; batch/bulk capabilities are NOT operational.'
  );
  IF coalesce(v_settings.batch_enabled,false) = false
     AND coalesce(v_settings.bulk_enabled,false) = false THEN
    v_result := true; v_status := 'PASS'; v_blocker := NULL; v_fix := NULL;
  ELSE
    v_result := false; v_status := 'DRIFTED';
    v_blocker := 'BATCH_OR_BULK_ENABLED_IN_PILOT';
    v_fix := 'Disable batch_enabled and bulk_enabled for the pilot event.';
  END IF;
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 7) provider_circuit_breaker
  v_code := 'provider_circuit_breaker';
  IF v_provider.id IS NULL THEN
    v_evidence := jsonb_build_object(
      'selected_provider_id', NULL,
      'note', 'No default active email provider resolved.'
    );
    v_result := false; v_status := 'NOT_CONFIGURED';
    v_blocker := 'PROVIDER_NOT_CONFIGURED';
    v_fix := 'Set a default active email provider in notification_providers.';
  ELSE
    v_evidence := jsonb_build_object(
      'selected_provider_id', v_provider.id,
      'provider_key', v_provider.provider_name,
      'email_provider_type', v_provider.email_provider_type,
      'is_active', v_provider.is_active,
      'is_default', v_provider.is_default,
      'has_config', (v_provider.config IS NOT NULL AND v_provider.config <> '{}'::jsonb),
      'circuit_breaker_capability', false,
      'note', 'No provider circuit-breaker implementation exists in this deployment.'
    );
    v_result := false; v_status := 'NOT_IMPLEMENTED';
    v_blocker := 'PROVIDER_CIRCUIT_BREAKER_NOT_IMPLEMENTED';
    v_fix := 'Implement a real provider circuit breaker (open/half-open/closed) with atomic guard on dispatch before Automated Production.';
  END IF;
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 8) emergency_stop
  v_code := 'emergency_stop';
  v_evidence := jsonb_build_object(
    'operating_mode', v_mode,
    'emergency_stop_active_from_mode', v_estop_mode,
    'canonical_estop_rpc_present', false,
    'note', 'Emergency Stop state is derived from operating_mode. A canonical atomic Emergency Stop RPC is not implemented.'
  );
  v_result := false; v_status := 'NOT_IMPLEMENTED';
  v_blocker := 'EMERGENCY_STOP_NOT_IMPLEMENTED';
  v_fix := 'Implement a canonical Emergency Stop action that atomically disables dispatch/scheduler/triggers/retry/batch/bulk, invalidates current Arm authority and writes an immutable audit record.';
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  -- 9) alerting_monitoring
  v_code := 'alerting_monitoring';
  v_evidence := jsonb_build_object(
    'dispatcher_failure_visibility', false,
    'scheduler_failure_visibility', false,
    'stale_heartbeat_detection', false,
    'provider_failure_alert', false,
    'dead_letter_backlog_alert', false,
    'operator_diagnostics', true,
    'note', 'Operator diagnostics are visible in the console, but no alerting/monitoring channel is proven.'
  );
  v_result := false; v_status := 'NOT_IMPLEMENTED';
  v_blocker := 'ALERTING_MONITORING_NOT_IMPLEMENTED';
  v_fix := 'Wire dispatcher/scheduler/heartbeat/provider/dead-letter alerts to an operator-visible channel before Automated Production.';
  PERFORM public._persist_pre_arm_readiness_row(p_module_code,p_event_code,v_channel,v_code,
    v_cfg_version,v_ec.id,v_lineage_id,v_result,v_status,v_evidence,v_blocker,v_fix,v_uid,v_now);
  v_checks := v_checks || public._pre_arm_check_json(v_code,v_result,v_status,v_evidence,v_blocker,v_fix,v_cfg_version,v_ec.id,v_lineage_id,v_now);

  RETURN jsonb_build_object(
    'ok', true,
    'readiness_phase', 'PRE_ARM_READINESS',
    'current_operating_mode', v_mode,
    'automation_state', v_automation_state,
    'safe_mode', v_safe_mode,
    'module_code', p_module_code,
    'event_code', p_event_code,
    'channel', v_channel,
    'configuration_version', v_cfg_version,
    'event_certification_id', v_ec.id,
    'production_lineage_id', v_lineage_id,
    'checks', v_checks,
    'checked_at', v_now
  );

EXCEPTION
  WHEN undefined_table OR undefined_column OR undefined_function OR undefined_object OR invalid_schema_name THEN
    RETURN jsonb_build_object(
      'ok', false,
      'blocker', jsonb_build_object(
        'code', 'READINESS_SCHEMA_MISMATCH',
        'object_name', COALESCE(NULLIF(regexp_replace(SQLERRM, '^.*"([^"]+)".*$', '\1'), SQLERRM), ''),
        'detail', SQLERRM,
        'sqlstate', SQLSTATE,
        'fix_action', 'Redeploy run_comm_hub_automation_readiness_probe against the current schema; do not add compatibility columns for absent capabilities.'
      )
    );
END $function$;
CREATE OR REPLACE FUNCTION public.run_comm_hub_go_live_certification(p_module_code text, p_event_code text, p_channel text DEFAULT 'email'::text, p_target_stage text DEFAULT 'READINESS_ONLY'::text, p_execute boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_manifest jsonb; v_hash text; v_blockers jsonb := '[]'::jsonb; v_warnings jsonb := '[]'::jsonb;
  v_stage text := upper(p_target_stage); v_channel text := lower(p_channel);
  v_tv_id uuid; v_scenario_id uuid; v_sender_id uuid; v_gov_record_id uuid;
  v_map_id uuid; v_schema_id uuid; v_schema_ver int; v_recipient_ver int;
  v_readiness_state text; v_readiness_stale boolean;
  v_ready_readiness boolean; v_ready_preview boolean; v_ready_dry_run boolean; v_ready_stub boolean; v_ready_stage boolean;
  v_render_subject jsonb; v_render_html jsonb; v_render_text jsonb; v_resolution jsonb; v_gov_check jsonb;
  v_recipient_ctx jsonb; v_request_ctx jsonb; v_system_ctx jsonb;
  v_cert_id uuid;
  v_reg record; v_map record; v_tv record; v_schema record; v_fixture record;
  v_sender record; v_readiness record; v_recipient record; v_gov record; v_cert record; v_live record;
  v_has_map boolean := false; v_has_recipient boolean := false; v_has_readiness boolean := false; v_has_schema boolean := false;
  v_template_cert_found boolean := false;
  v_current_dep_hash text;
BEGIN
  IF v_stage NOT IN ('READINESS_ONLY','PREVIEW_READY','DRY_RUN_READY','CONTROLLED_STUB_READY') THEN
    RETURN jsonb_build_object('ok',false,'code','invalid_target_stage','message',v_stage);
  END IF;
  IF p_execute IS true THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code','execute_ignored','message','p_execute=true ignored in foundation iteration'));
  END IF;

  SELECT * INTO v_reg FROM communication_hub_module_event_registry WHERE module_code=p_module_code AND event_code=p_event_code LIMIT 1;
  IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','module_event_registration','code','event_not_registered')); END IF;
  SELECT * INTO v_live FROM communication_hub_event_live_control WHERE module_code=p_module_code AND event_code=p_event_code LIMIT 1;
  IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','event_live_control','code','event_live_control_missing')); END IF;
  SELECT * INTO v_map FROM communication_hub_event_template_map WHERE module_code=p_module_code AND event_code=p_event_code AND lower(channel)=v_channel AND active=true LIMIT 1;
  IF FOUND THEN v_has_map:=true; v_map_id:=v_map.id; ELSE v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','event_template_map','code','event_template_map_missing_or_inactive')); END IF;

  IF v_has_map THEN
    SELECT v.*, t.status AS template_status, t.code AS template_code, t.active_version_id INTO v_tv
      FROM core_template t JOIN core_template_version v ON v.id=t.active_version_id WHERE t.id=v_map.template_id LIMIT 1;
    IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','template_version','code','template_active_version_missing'));
    ELSE
      v_tv_id := v_tv.id;
      IF upper(v_tv.status::text) NOT IN ('ACTIVE','PUBLISHED') THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','template_version','code','template_version_not_published','details',v_tv.status)); END IF;
      IF coalesce(length(v_tv.subject),0)=0 THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','template_version','code','template_subject_empty')); END IF;
      IF coalesce(length(v_tv.body_html),0)=0 AND coalesce(length(v_tv.body_text),0)=0 THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','template_version','code','template_body_empty')); END IF;
    END IF;
  END IF;

  SELECT * INTO v_schema FROM communication_hub_event_payload_schema WHERE module_code=p_module_code AND event_code=p_event_code ORDER BY schema_version DESC LIMIT 1;
  IF FOUND THEN v_has_schema:=true; v_schema_id:=v_schema.id; v_schema_ver:=v_schema.schema_version;
    IF upper(v_schema.status)<>'ENFORCED' AND v_stage IN ('DRY_RUN_READY','CONTROLLED_STUB_READY') THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','event_payload_schema','code','event_payload_schema_not_enforced','details',v_schema.status));
    END IF;
  ELSE v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','event_payload_schema','code','event_payload_schema_missing')); END IF;

  IF v_tv_id IS NOT NULL THEN
    PERFORM 1 FROM communication_hub_template_variable_contract WHERE module_code=p_module_code AND event_code=p_event_code AND template_version_id=v_tv_id LIMIT 1;
    IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','variable_contract','code','variable_contract_missing_for_active_version')); END IF;
    IF v_stage IN ('DRY_RUN_READY','CONTROLLED_STUB_READY') THEN
      PERFORM 1 FROM communication_hub_template_variable_contract WHERE module_code=p_module_code AND event_code=p_event_code AND template_version_id=v_tv_id AND contract_status<>'ENFORCED' LIMIT 1;
      IF FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','variable_contract','code','variable_contract_not_enforced')); END IF;
    END IF;
  END IF;

  SELECT * INTO v_fixture FROM communication_hub_event_test_scenario WHERE module_code=p_module_code AND event_code=p_event_code AND lower(channel)=v_channel AND is_active=true ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','test_scenario','code','governed_test_scenario_missing'));
  ELSE
    v_scenario_id := v_fixture.id;
    IF v_fixture.tokens ? 'appeal_reference' OR v_fixture.tokens ? 'case_reference' OR v_fixture.tokens ? 'submitted_at'
       OR v_fixture.tokens ? 'recipient_name' OR v_fixture.tokens ? 'request_no' OR v_fixture.tokens ? 'generated_at' THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','test_scenario','code','test_scenario_uses_flat_template_tokens'));
    END IF;
  END IF;

  SELECT * INTO v_recipient FROM communication_hub_recipient_policy LIMIT 1;
  IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','recipient_policy','code','recipient_policy_missing'));
  ELSE
    v_has_recipient:=true; v_recipient_ver := v_recipient.policy_version;
    IF v_stage IN ('DRY_RUN_READY','CONTROLLED_STUB_READY') AND
       (v_recipient.active_mode<>'SINGLE_CONFIGURED_RECIPIENT' OR coalesce(v_recipient.single_configured_address,'')='') THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','recipient_policy','code','recipient_policy_not_configured_for_controlled_stub'));
    END IF;
    IF v_stage='CONTROLLED_STUB_READY' AND coalesce(v_recipient.single_configured_display_name_confirmed,false)=false THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','recipient_policy','code','recipient_display_name_not_confirmed'));
    END IF;
  END IF;

  IF v_has_map AND v_map.sender_profile_id IS NOT NULL THEN
    v_sender_id := v_map.sender_profile_id;
    SELECT * INTO v_sender FROM communication_hub_sender_profile WHERE id=v_sender_id;
    IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','sender_profile','code','sender_profile_missing'));
    ELSE
      IF v_sender.is_enabled IS DISTINCT FROM true THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','sender_profile','code','sender_profile_disabled')); END IF;
      IF v_sender.domain_verified IS DISTINCT FROM true THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','sender_profile','code','sender_domain_not_verified')); END IF;
      IF v_sender.provider_identity_status IS DISTINCT FROM 'verified' THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','sender_profile','code','sender_provider_identity_not_verified','details',v_sender.provider_identity_status)); END IF;
    END IF;
    SELECT * INTO v_readiness FROM comm_hub_sender_readiness WHERE sender_profile_id=v_sender_id ORDER BY computed_at DESC LIMIT 1;
    IF FOUND THEN v_has_readiness:=true; v_readiness_state:=v_readiness.readiness_state; v_readiness_stale:=v_readiness.is_stale; END IF;
    IF v_stage='CONTROLLED_STUB_READY' THEN
      IF NOT v_has_readiness OR v_readiness_state<>'TEST_READY' OR v_readiness_stale=true THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','sender_readiness','code','sender_not_test_ready'));
      END IF;
    ELSIF NOT v_has_readiness OR v_readiness_state<>'TEST_READY' THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code','sender_test_readiness_missing_or_stale'));
    END IF;
  ELSE
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','sender_profile','code','sender_profile_not_bound_to_mapping'));
  END IF;

  IF v_tv_id IS NOT NULL THEN
    SELECT * INTO v_gov FROM comm_hub_governance_record WHERE entity_type='TEMPLATE_VERSION' AND entity_id=v_tv_id ORDER BY updated_at DESC LIMIT 1;
    IF NOT FOUND THEN v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','governance','code','template_version_governance_missing')); END IF;

    SELECT * INTO v_cert FROM comm_hub_certification
     WHERE entity_type = 'TEMPLATE_VERSION' AND entity_id = v_tv_id
       AND certification_layer = 'TEMPLATE_STRUCTURE_CERTIFICATION'
       AND certification_kind  = 'STANDARD'
       AND provenance_state    = 'AUTHORITATIVE'
       AND is_stale = false AND superseded_by IS NULL
       AND result IN ('PASS','CERTIFIED')
     ORDER BY certified_at DESC LIMIT 1;

    IF NOT FOUND THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'stage','template_certification',
        'code','template_structure_not_certified',
        'details', jsonb_build_object('template_version_id', v_tv_id)
      ));
    ELSE
      v_template_cert_found := true;
      v_cert_id := v_cert.id;
      SELECT dependency_hash INTO v_current_dep_hash FROM public.build_comm_hub_certification_dependency_hash(v_tv_id);
      -- Only flag drift when a hash was recorded on the certification and it disagrees with the current one.
      IF v_cert.dependency_hash IS NOT NULL
         AND v_current_dep_hash IS NOT NULL
         AND v_cert.dependency_hash <> v_current_dep_hash THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
          'stage','template_certification',
          'code','template_certification_dependency_drift',
          'details', jsonb_build_object('certification_id', v_cert_id)
        ));
      END IF;
    END IF;
  END IF;

  IF v_tv_id IS NOT NULL AND v_has_map AND v_scenario_id IS NOT NULL AND v_has_recipient THEN
    BEGIN
      v_recipient_ctx := public.build_comm_hub_recipient_context(v_recipient.id);
      v_request_ctx := public.build_comm_hub_request_context('deterministic-runner');
      v_system_ctx := public.build_comm_hub_system_context();
      v_resolution := public.resolve_comm_hub_template_variables(
        p_module_code:=p_module_code, p_event_code:=p_event_code, p_template_version_id:=v_tv_id,
        p_event_payload:=v_fixture.tokens, p_recipient_context:=v_recipient_ctx,
        p_request_context:=v_request_ctx, p_system_context:=v_system_ctx);
      IF (v_resolution ? 'unresolved_required') AND jsonb_array_length(v_resolution->'unresolved_required')>0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','variable_resolution','code','required_variables_unresolved','details',v_resolution->'unresolved_required'));
      END IF;
      IF (v_resolution ? 'raw_tokens') AND jsonb_array_length(v_resolution->'raw_tokens')>0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','variable_resolution','code','raw_tokens_present','details',v_resolution->'raw_tokens'));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','variable_resolution','code','resolver_error','details',SQLERRM));
    END;

    BEGIN
      v_render_subject := public.render_comm_hub_content(v_tv.subject, coalesce(v_resolution->'resolved',v_fixture.tokens));
      IF (v_render_subject ? 'raw_tokens') AND jsonb_array_length(v_render_subject->'raw_tokens')>0 THEN
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','render_check','code','subject_raw_tokens_present'));
      END IF;
      IF coalesce(v_tv.body_html,'') <> '' THEN
        v_render_html := public.render_comm_hub_content(v_tv.body_html, coalesce(v_resolution->'resolved',v_fixture.tokens));
        IF (v_render_html ? 'raw_tokens') AND jsonb_array_length(v_render_html->'raw_tokens')>0 THEN
          v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','render_check','code','body_html_raw_tokens_present'));
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('stage','render_check','code','render_error','details',SQLERRM));
    END;
  END IF;

  IF v_tv_id IS NOT NULL AND v_has_map THEN
    BEGIN
      v_gov_check := check_comm_hub_runtime_governance(
        p_module_code:=p_module_code, p_event_code:=p_event_code, p_channel:=v_channel,
        p_target_stage:=CASE WHEN v_stage='PREVIEW_READY' THEN 'PREVIEW_TEST'
                             WHEN v_stage='DRY_RUN_READY' THEN 'DRY_RUN'
                             WHEN v_stage='CONTROLLED_STUB_READY' THEN 'CONTROLLED_STUB'
                             ELSE 'PREVIEW_TEST' END);
      IF jsonb_array_length(coalesce(v_gov_check->'blockers','[]'::jsonb))>0 THEN
        IF NOT p_execute THEN
          v_warnings := v_warnings || COALESCE((
            SELECT jsonb_agg(jsonb_build_object('stage','runtime_governance','code',coalesce(b->>'code','governance_blocker'),'details',b))
            FROM jsonb_array_elements(v_gov_check->'blockers') b
            WHERE (b->>'code') IN ('PREVIEW_SNAPSHOT_REQUIRED','PREVIEW_APPROVAL_REQUIRED','DRY_RUN_CERTIFICATION_REQUIRED')
          ), '[]'::jsonb);
          v_blockers := v_blockers || COALESCE((
            SELECT jsonb_agg(jsonb_build_object('stage','runtime_governance','code',coalesce(b->>'code','governance_blocker'),'details',b))
            FROM jsonb_array_elements(v_gov_check->'blockers') b
            WHERE (b->>'code') NOT IN ('PREVIEW_SNAPSHOT_REQUIRED','PREVIEW_APPROVAL_REQUIRED','DRY_RUN_CERTIFICATION_REQUIRED')
          ), '[]'::jsonb);
        ELSE
          v_blockers := v_blockers || (SELECT jsonb_agg(jsonb_build_object('stage','runtime_governance','code',coalesce(b->>'code','governance_blocker'),'details',b))
                                       FROM jsonb_array_elements(v_gov_check->'blockers') b);
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code','runtime_governance_check_error','message',SQLERRM));
    END;
  END IF;

  v_manifest := _comm_hub_build_event_manifest(p_module_code,p_event_code,v_channel);
  v_hash := _comm_hub_hash_manifest(v_manifest);

  v_ready_readiness := NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) b
    WHERE (b->>'code') IN ('event_not_registered','event_template_map_missing_or_inactive','template_active_version_missing'));
  v_ready_preview := jsonb_array_length(v_blockers)=0;
  v_ready_dry_run := v_ready_preview; v_ready_stub := v_ready_preview;
  v_ready_stage := CASE v_stage WHEN 'READINESS_ONLY' THEN v_ready_readiness
                                 WHEN 'PREVIEW_READY' THEN v_ready_preview
                                 WHEN 'DRY_RUN_READY' THEN v_ready_dry_run
                                 WHEN 'CONTROLLED_STUB_READY' THEN v_ready_stub END;

  RETURN jsonb_build_object(
    'ok', v_ready_stage,
    'schema_version','go-live-runner/2',
    'requested_stage', v_stage,
    'module_code', p_module_code, 'event_code', p_event_code, 'channel', v_channel,
    'mapping_id', v_map_id, 'template_version_id', v_tv_id, 'payload_schema_id', v_schema_id, 'payload_schema_version', v_schema_ver,
    'sender_profile_id', v_sender_id, 'sender_readiness_state', v_readiness_state,
    'governance_record_id', v_gov.id, 'certification_id', v_cert_id,
    'template_certification', jsonb_build_object(
       'found', v_template_cert_found,
       'producer_function','record_comm_hub_template_version_certification',
       'producer_version','template-cert-writer/2',
       'certification_id', v_cert_id,
       'certified_dependency_hash', v_cert.dependency_hash,
       'current_dependency_hash', v_current_dep_hash,
       'hash_match', CASE WHEN v_cert.dependency_hash IS NULL OR v_current_dep_hash IS NULL THEN NULL
                          ELSE v_cert.dependency_hash = v_current_dep_hash END
    ),
    'ready_by_stage', jsonb_build_object('READINESS_ONLY',v_ready_readiness,'PREVIEW_READY',v_ready_preview,'DRY_RUN_READY',v_ready_dry_run,'CONTROLLED_STUB_READY',v_ready_stub),
    'manifest_hash', v_hash, 'raw_token_count', 0,
    'variable_resolution', v_resolution, 'render_subject', v_render_subject, 'render_body_html', v_render_html,
    'runtime_governance', v_gov_check,
    'blockers', v_blockers, 'warnings', v_warnings, 'executed', false
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.save_batch_card_transactions(p_batch_number text, p_transactions jsonb, p_user_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_txn JSONB;
  v_machine RECORD;
  v_crd_total NUMERIC(12,2) := 0;
  v_drd_total NUMERIC(12,2) := 0;
  v_batch_status VARCHAR;
  v_amount NUMERIC(12,2);
  v_card_type VARCHAR(3);
  v_machine_id UUID;
BEGIN
  SELECT batch_status INTO v_batch_status
  FROM public.cn_batch
  WHERE batch_number = p_batch_number;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Batch % not found', p_batch_number;
  END IF;
  IF v_batch_status <> 'O' THEN
    RAISE EXCEPTION 'Batch % is not open (status: %)', p_batch_number, v_batch_status;
  END IF;

  DELETE FROM public.cn_batch_card_transaction WHERE batch_number = p_batch_number;

  FOR v_txn IN SELECT * FROM jsonb_array_elements(p_transactions)
  LOOP
    v_machine_id := (v_txn->>'machine_id')::UUID;
    v_card_type := v_txn->>'card_type';
    v_amount := (v_txn->>'amount')::NUMERIC(12,2);

    IF v_amount IS NULL OR v_amount <= 0 THEN
      RAISE EXCEPTION 'Transaction amount must be greater than zero';
    END IF;

    IF v_card_type NOT IN ('CRD', 'DRD') THEN
      RAISE EXCEPTION 'Invalid card type: %. Must be CRD or DRD', v_card_type;
    END IF;

    SELECT * INTO v_machine FROM public.cn_card_machine WHERE id = v_machine_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Machine % not found', v_machine_id;
    END IF;
    IF NOT v_machine.is_active THEN
      RAISE EXCEPTION 'Machine % is not active', v_machine.machine_code;
    END IF;
    IF v_machine.bank_code IS NULL OR v_machine.bank_code = '' THEN
      RAISE EXCEPTION 'Machine % has no bank linkage', v_machine.machine_code;
    END IF;

    IF v_machine.card_type_support = 'CRD' AND v_card_type = 'DRD' THEN
      RAISE EXCEPTION 'Machine % does not support Debit Card', v_machine.machine_code;
    END IF;
    IF v_machine.card_type_support = 'DRD' AND v_card_type = 'CRD' THEN
      RAISE EXCEPTION 'Machine % does not support Credit Card', v_machine.machine_code;
    END IF;

    -- Fix: use created_by instead of entered_by
    INSERT INTO public.cn_batch_card_transaction (
      batch_number, machine_id, card_type, amount, created_by
    ) VALUES (
      p_batch_number, v_machine_id, v_card_type, v_amount, p_user_code
    );

    IF v_card_type = 'CRD' THEN
      v_crd_total := v_crd_total + v_amount;
    ELSE
      v_drd_total := v_drd_total + v_amount;
    END IF;
  END LOOP;

  DELETE FROM public.cn_batch_card_total WHERE batch_number = p_batch_number;

  IF v_crd_total > 0 THEN
    INSERT INTO public.cn_batch_card_total (batch_number, mop_code, amount)
    VALUES (p_batch_number, 'CRD', v_crd_total);
  END IF;
  IF v_drd_total > 0 THEN
    INSERT INTO public.cn_batch_card_total (batch_number, mop_code, amount)
    VALUES (p_batch_number, 'DRD', v_drd_total);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'crd_total', v_crd_total,
    'drd_total', v_drd_total,
    'transaction_count', jsonb_array_length(p_transactions)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.scan_comm_hub_raw_placeholders(p_subject text, p_body_html text, p_body_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pattern text := '\{\{([^{}]*)\}\}';               -- bounded non-brace body
  v_malformed_pattern text := '(\{\{\{|\}\}\}|\{\{[^}]*\{|\}[^{]*\}\})';
  v_result jsonb := '[]'::jsonb;
  v_names jsonb := '{}'::jsonb;
  v_field text; v_content text; v_raw text; v_m text[];
  v_total int := 0; v_uniq int := 0; v_malformed int := 0;
  v_name text; v_trim text;
BEGIN
  FOR v_field, v_raw IN
    SELECT * FROM (VALUES
      ('subject',   COALESCE(p_subject,'')),
      ('body_html', COALESCE(p_body_html,'')),
      ('body_text', COALESCE(p_body_text,''))) t(field, content)
  LOOP
    -- Strip escaped literal braces first: \{{ ... \}}
    v_content := regexp_replace(v_raw, '\\\{\{[^{}]*\\\}\}', '', 'g');

    -- Count malformed brace patterns
    v_malformed := v_malformed + (SELECT count(*) FROM regexp_matches(v_content, v_malformed_pattern, 'g'));

    FOR v_m IN SELECT regexp_matches(v_content, v_pattern, 'g') LOOP
      v_name := v_m[1];
      v_trim := btrim(v_name);
      IF v_trim = '' THEN
        v_malformed := v_malformed + 1;
        CONTINUE;
      END IF;
      v_total := v_total + 1;
      v_names := v_names || jsonb_build_object(v_trim, COALESCE((v_names->>v_trim)::int,0) + 1);
      v_result := v_result || jsonb_build_object('name', v_trim, 'field', v_field, 'raw', v_name);
    END LOOP;
  END LOOP;

  v_uniq := (SELECT count(*) FROM jsonb_object_keys(v_names));
  RETURN jsonb_build_object(
    'placeholders', v_result,
    'by_name', v_names,
    'total_occurrences', v_total,
    'unique_count', v_uniq,
    'malformed_brace_count', v_malformed,
    'scanner_version', 'comm-hub-raw-placeholder-scanner/v2'
  );
END; $function$;
CREATE OR REPLACE FUNCTION public.schedule_meeting(p_application_reference character varying, p_workflow_instance_id uuid, p_workflow_id uuid, p_step_id uuid, p_action_config_id uuid, p_meeting_type meeting_type, p_meeting_date date, p_meeting_time time without time zone, p_contact_person character varying, p_contact_email character varying DEFAULT NULL::character varying, p_contact_phone character varying DEFAULT NULL::character varying, p_office_address text DEFAULT NULL::text, p_remarks text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_user_name character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_meeting_ref TEXT;
  v_meeting_id UUID;
  v_default_address TEXT;
  v_task_id UUID;
  v_step_name TEXT;
BEGIN
  -- Generate meeting reference
  v_meeting_ref := generate_meeting_reference();

  -- Resolve step name (optional)
  IF p_step_id IS NOT NULL THEN
    SELECT step_name INTO v_step_name
    FROM workflow_steps
    WHERE id = p_step_id;
  END IF;

  -- Get default office address if not provided
  IF p_office_address IS NULL THEN
    SELECT setting_value INTO v_default_address
    FROM system_settings
    WHERE setting_key = 'default_office_address';
  ELSE
    v_default_address := p_office_address;
  END IF;

  -- Create meeting record
  INSERT INTO meetings (
    meeting_reference,
    application_reference,
    workflow_instance_id,
    workflow_id,
    step_id,
    action_config_id,
    meeting_type,
    status,
    meeting_date,
    meeting_time,
    contact_person,
    contact_email,
    contact_phone,
    office_address,
    remarks,
    scheduled_by,
    scheduled_by_name,
    created_by
  ) VALUES (
    v_meeting_ref,
    p_application_reference,
    p_workflow_instance_id,
    p_workflow_id,
    p_step_id,
    p_action_config_id,
    p_meeting_type,
    'Scheduled',
    p_meeting_date,
    p_meeting_time,
    p_contact_person,
    p_contact_email,
    p_contact_phone,
    v_default_address,
    p_remarks,
    p_user_id,
    p_user_name,
    CASE
      WHEN p_user_name IS NULL THEN NULL
      ELSE LEFT(p_user_name, 10)
    END
  )
  RETURNING id INTO v_meeting_id;

  -- Create history record
  INSERT INTO meeting_history (
    meeting_id,
    new_status,
    action_taken,
    new_date,
    new_time,
    remarks,
    performed_by,
    performed_by_name
  ) VALUES (
    v_meeting_id,
    'Scheduled',
    'CREATED',
    p_meeting_date,
    p_meeting_time,
    'Meeting scheduled',
    p_user_id,
    p_user_name
  );

  -- Update workflow instance status to AwaitingMeeting and store meeting reference in metadata
  IF p_workflow_instance_id IS NOT NULL THEN
    UPDATE workflow_instances
    SET status = 'AwaitingMeeting',
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'awaiting_meeting_id', v_meeting_id,
          'meeting_reference', v_meeting_ref,
          'meeting_scheduled_at', NOW()
        )
    WHERE id = p_workflow_instance_id;

    -- Get and update the current pending/in-progress task to Paused status
    SELECT id INTO v_task_id
    FROM workflow_tasks
    WHERE instance_id = p_workflow_instance_id
      AND status IN ('Pending', 'InProgress')
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_task_id IS NOT NULL THEN
      UPDATE workflow_tasks
      SET status = 'Paused',
          action_taken = 'Schedule Meeting',
          comments = 'Awaiting meeting outcome. Meeting ref: ' || v_meeting_ref
      WHERE id = v_task_id;

      -- Log the workflow action (workflow_logs has NO task_id column)
      INSERT INTO workflow_logs (
        instance_id,
        step_id,
        step_name,
        user_id,
        user_name,
        action,
        old_status,
        new_status,
        comments,
        metadata
      ) VALUES (
        p_workflow_instance_id,
        p_step_id,
        v_step_name,
        p_user_id,
        p_user_name,
        'Schedule Meeting',
        NULL,
        'AwaitingMeeting',
        'Meeting scheduled: ' || v_meeting_ref || '. Workflow paused until meeting outcome.',
        jsonb_build_object(
          'meeting_id', v_meeting_id,
          'meeting_reference', v_meeting_ref
        )
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'meeting_id', v_meeting_id,
    'meeting_reference', v_meeting_ref,
    'message', 'Meeting scheduled successfully'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.send_communication_v1(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._comm_hub_reject_reserved_targeted_fields(payload);
  RETURN public.send_communication_v1_core(payload);
END;
$function$;
CREATE OR REPLACE FUNCTION public.send_communication_v1_core(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module_code      text := COALESCE(payload->>'moduleCode', payload->>'module_code');
  v_dept_code        text := COALESCE(payload->>'departmentCode', payload->>'department_code');
  v_event_code       text := COALESCE(payload->>'eventCode', payload->>'event_code');
  v_country_code     text := COALESCE(payload->>'countryCode', payload->>'country_code');
  v_language_code    text := COALESCE(payload->>'languageCode', payload->>'language_code');
  v_priority         text := COALESCE(payload->>'priority', 'normal');
  v_idem_key         text := NULLIF(COALESCE(payload->>'idempotencyKey', payload->>'idempotency_key'), '');
  v_correlation_id   text := COALESCE(payload->>'correlationId', gen_random_uuid()::text);
  v_test_mode        boolean := COALESCE((payload->>'testMode')::boolean, false);
  v_origin           text := COALESCE(payload->>'origin', 'comm_hub');
  v_requested_by     uuid := NULLIF(payload->>'requestedBy','')::uuid;
  v_scheduled_at     timestamptz := NULLIF(payload->>'scheduledAt','')::timestamptz;
  v_reference        jsonb := COALESCE(payload->'reference', '{}'::jsonb);
  v_channels         jsonb := COALESCE(payload->'channels', '["email"]'::jsonb);
  v_channels_text    text[];
  v_recipients       jsonb := COALESCE(payload->'recipients', payload->'recipient', '[]'::jsonb);
  v_message_payload  jsonb := COALESCE(payload->'message', '{}'::jsonb);
  v_data             jsonb := COALESCE(payload->'data', '{}'::jsonb);
  v_metadata         jsonb := COALESCE(payload->'metadata', '{}'::jsonb);
  v_decision         jsonb := COALESCE(payload->'canonicalDecision', payload->'canonical_decision', '{}'::jsonb);
  v_decision_id      uuid := NULLIF(v_decision->>'decision_id','')::uuid;
  v_send_context     text := NULLIF(v_decision->>'send_context','');
  v_cfg_ver          integer := NULLIF(v_decision->>'configuration_version','')::integer;
  v_rp_ver           integer := NULLIF(v_decision->>'recipient_policy_version','')::integer;
  v_sp_ver           integer := NULLIF(v_decision->>'send_policy_version','')::integer;
  v_review_ver       integer := NULLIF(v_decision->>'review_policy_version','')::integer;
  v_dec_expires      timestamptz := NULLIF(v_decision->>'expires_at','')::timestamptz;
  v_blocker_snap     jsonb := COALESCE(v_decision->'blockers', '[]'::jsonb);
  v_request_id       uuid;
  v_request_no       text;
  v_existing         public.communication_request%ROWTYPE;
  v_rec              jsonb;
  v_rec_id           uuid;
  v_ch               text;
  v_msg_id           uuid;
  v_msg_ids          uuid[] := ARRAY[]::uuid[];
  v_warnings         text[] := ARRAY[]::text[];
  v_reused           boolean := false;
  v_allowed_ch       text[] := ARRAY['email','sms','push','in_app','letter','print','whatsapp'];
BEGIN
  IF v_module_code IS NULL OR v_event_code IS NULL THEN
    RAISE EXCEPTION 'send_communication_v1: moduleCode and eventCode are required';
  END IF;

  IF v_recipients IS NULL OR jsonb_typeof(v_recipients) NOT IN ('array','object') THEN
    RAISE EXCEPTION 'send_communication_v1: recipient(s) required';
  END IF;
  IF jsonb_typeof(v_recipients) = 'object' THEN
    v_recipients := jsonb_build_array(v_recipients);
  END IF;
  IF jsonb_array_length(v_recipients) = 0 THEN
    RAISE EXCEPTION 'send_communication_v1: at least one recipient required';
  END IF;

  SELECT ARRAY(SELECT lower(jsonb_array_elements_text(v_channels))) INTO v_channels_text;
  IF array_length(v_channels_text, 1) IS NULL THEN
    v_channels_text := ARRAY['email'];
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_channels_text) c WHERE c <> ALL(v_allowed_ch)) THEN
    RAISE EXCEPTION 'send_communication_v1: unsupported channel in %', v_channels_text;
  END IF;

  IF v_idem_key IS NOT NULL THEN
    SELECT * INTO v_existing FROM public.communication_request WHERE idempotency_key = v_idem_key LIMIT 1;
    IF FOUND THEN
      v_reused := true;
      v_request_id := v_existing.id;
      v_request_no := v_existing.request_no;
      SELECT ARRAY(SELECT id FROM public.communication_message WHERE request_id = v_request_id ORDER BY created_at)
        INTO v_msg_ids;
      RETURN jsonb_build_object(
        'ok', true,
        'requestId', v_request_id,
        'requestNo', v_request_no,
        'correlationId', COALESCE(v_existing.context->>'correlation_id', v_correlation_id),
        'idempotencyKey', v_idem_key,
        'status', v_existing.status,
        'messageIds', to_jsonb(v_msg_ids),
        'reusedExistingRequest', true,
        'decisionId', v_existing.original_decision_id,
        'warnings', to_jsonb(ARRAY['reused existing request via idempotency_key'])
      );
    END IF;
  END IF;

  v_request_no := 'CR-' || to_char(now() AT TIME ZONE 'UTC','YYYYMMDDHH24MISS')
                       || '-' || upper(substr(md5(random()::text),1,6));

  INSERT INTO public.communication_request(
    request_no, module_code, department_code, event_code,
    entity_type, entity_id, reference_no,
    country_code, language_code, channels, priority,
    scheduled_at, status, payload, context,
    idempotency_key, requested_by,
    original_decision_id, decision_send_context,
    configuration_version, recipient_policy_version,
    send_policy_version, review_policy_version,
    decision_expires_at, decision_blocker_snapshot
  ) VALUES (
    v_request_no, v_module_code, v_dept_code, v_event_code,
    v_reference->>'entityType', v_reference->>'entityId', v_reference->>'referenceNo',
    v_country_code, v_language_code, v_channels_text, v_priority,
    v_scheduled_at, 'pending', v_data,
    jsonb_build_object(
      'correlation_id', v_correlation_id,
      'origin', v_origin,
      'test_mode', v_test_mode,
      'metadata', v_metadata,
      'caller_user_id', payload->>'callerUserId',
      'canonical_decision', v_decision
    ),
    v_idem_key, v_requested_by,
    v_decision_id, v_send_context,
    v_cfg_ver, v_rp_ver, v_sp_ver, v_review_ver,
    v_dec_expires, v_blocker_snap
  )
  RETURNING id, request_no INTO v_request_id, v_request_no;

  INSERT INTO public.communication_event_log(request_id, event_type, source, actor_user_id, payload)
  VALUES (v_request_id, 'created', 'send_communication_v1', v_requested_by,
          jsonb_build_object(
            'stage','REQUEST_CREATED',
            'correlation_id',v_correlation_id,
            'origin',v_origin,'test_mode',v_test_mode,
            'canonical_decision_id', v_decision_id,
            'configuration_version', v_cfg_ver,
            'recipient_policy_version', v_rp_ver,
            'send_context', v_send_context
          ));

  INSERT INTO public.communication_event_log(request_id, event_type, source, actor_user_id, payload)
  VALUES (v_request_id, 'created', 'send_communication_v1', v_requested_by,
          jsonb_build_object('stage','REQUEST_VALIDATED','channels',to_jsonb(v_channels_text)));

  FOR v_rec IN SELECT * FROM jsonb_array_elements(v_recipients) LOOP
    INSERT INTO public.communication_recipient(
      request_id, role, recipient_type,
      recipient_user_id, recipient_person_id, recipient_employer_id,
      name, email, phone, postal_address, channel_hint
    ) VALUES (
      v_request_id,
      COALESCE(v_rec->>'role','to'),
      COALESCE(v_rec->>'recipient_type', v_rec->>'type'),
      NULLIF(v_rec->>'userId','')::uuid,
      NULLIF(v_rec->>'personId','')::uuid,
      NULLIF(v_rec->>'employerId','')::uuid,
      v_rec->>'name', v_rec->>'email', v_rec->>'phone',
      CASE WHEN jsonb_typeof(v_rec->'postalAddress')='object' THEN v_rec->'postalAddress' ELSE NULL END,
      lower(NULLIF(v_rec->>'channelHint',''))
    )
    RETURNING id INTO v_rec_id;

    FOREACH v_ch IN ARRAY v_channels_text LOOP
      INSERT INTO public.communication_message(
        request_id, recipient_id, channel,
        subject, body_text, body_html, status,
        test_mode, origin, original_decision_id
      ) VALUES (
        v_request_id, v_rec_id, v_ch,
        v_message_payload->>'subject',
        v_message_payload->>'bodyText',
        v_message_payload->>'bodyHtml',
        'queued',
        v_test_mode, v_origin, v_decision_id
      )
      RETURNING id INTO v_msg_id;

      v_msg_ids := v_msg_ids || v_msg_id;

      INSERT INTO public.communication_event_log(request_id, message_id, event_type, source, actor_user_id, payload)
      VALUES (v_request_id, v_msg_id, 'created', 'send_communication_v1', v_requested_by,
              jsonb_build_object('stage','MESSAGE_CREATED','channel',v_ch,'test_mode',v_test_mode,
                                 'canonical_decision_id', v_decision_id));

      INSERT INTO public.communication_event_log(request_id, message_id, event_type, source, actor_user_id, payload)
      VALUES (v_request_id, v_msg_id, 'queued', 'send_communication_v1', v_requested_by,
              jsonb_build_object('stage','MESSAGE_QUEUED','channel',v_ch,'test_mode',v_test_mode,
                                 'canonical_decision_id', v_decision_id));
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'requestId', v_request_id,
    'requestNo', v_request_no,
    'correlationId', v_correlation_id,
    'idempotencyKey', v_idem_key,
    'status', 'pending',
    'messageIds', to_jsonb(v_msg_ids),
    'reusedExistingRequest', v_reused,
    'decisionId', v_decision_id,
    'configurationVersion', v_cfg_ver,
    'recipientPolicyVersion', v_rp_ver,
    'sendContext', v_send_context,
    'warnings', to_jsonb(v_warnings)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_comm_hub_module_automation_setting(p_module_code text, p_setting_key text, p_setting_value text, p_reason text, p_typed_confirmation text, p_actor_user_id uuid, p_environment_scope text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_hub_module_automation_setting;
  v_old_value text;
  v_expected_confirmation text;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'reason_required');
  END IF;

  SELECT * INTO v_row
  FROM public.communication_hub_module_automation_setting
  WHERE module_code = p_module_code
    AND setting_key = p_setting_key
    AND environment_scope = COALESCE(p_environment_scope, 'production')
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'setting_not_found');
  END IF;

  IF NOT (p_setting_value = ANY(v_row.allowed_values)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'value_not_allowed', 'allowed_values', v_row.allowed_values);
  END IF;

  IF p_setting_value = 'auto_live_internal' THEN
    v_expected_confirmation := 'ENABLE AUTO LIVE INTERNAL ' || upper(replace(p_module_code,'_',' ')) || ' ASSIGNMENT NOTICE';
    IF p_typed_confirmation IS DISTINCT FROM v_expected_confirmation THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'typed_confirmation_required',
        'expected', v_expected_confirmation
      );
    END IF;
  END IF;

  v_old_value := v_row.setting_value;

  UPDATE public.communication_hub_module_automation_setting
     SET setting_value = p_setting_value,
         updated_by    = p_actor_user_id,
         updated_at    = now(),
         approved_by   = CASE WHEN p_setting_value = 'auto_live_internal' THEN p_actor_user_id ELSE approved_by END,
         approved_at   = CASE WHEN p_setting_value = 'auto_live_internal' THEN now() ELSE approved_at END
   WHERE id = v_row.id
   RETURNING * INTO v_row;

  INSERT INTO public.communication_hub_control_audit
    (setting_key, old_value, new_value, reason, changed_by, source)
  VALUES
    (p_module_code || '.' || p_setting_key,
     jsonb_build_object('value', v_old_value, 'environment', p_environment_scope),
     jsonb_build_object('value', p_setting_value, 'environment', p_environment_scope, 'typed_confirmation_provided', p_setting_value = 'auto_live_internal'),
     p_reason,
     p_actor_user_id,
     'communication-hub-automation-settings');

  RETURN jsonb_build_object('ok', true, 'setting', to_jsonb(v_row));
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_comm_hub_one_real_email_message_status(p_message_id uuid, p_target_status text, p_provider_message_id text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_svc jsonb; v_msg public.communication_message%ROWTYPE;
BEGIN
  v_svc := public._comm_hub_assert_bound_service_operation(
    'comm-hub-send-one-real-email','DISPATCH_ONE_REAL_EMAIL');
  IF NOT coalesce((v_svc->>'allowed')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'blockers', v_svc->'blockers');
  END IF;
  IF p_target_status NOT IN ('sending','sent','failed') THEN
    RETURN jsonb_build_object('ok', false, 'code','invalid_target_status');
  END IF;

  SELECT * INTO v_msg FROM public.communication_message WHERE id=p_message_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code','message_not_found'); END IF;
  IF v_msg.targeted_dispatch_only IS NOT TRUE
     OR v_msg.controlled_action <> 'SEND_ONE_REAL_EMAIL' THEN
    RETURN jsonb_build_object('ok', false, 'code','message_not_one_real_email');
  END IF;

  -- Enforce a strict forward-only lifecycle.
  IF p_target_status = 'sending' AND v_msg.status <> 'queued' THEN
    RETURN jsonb_build_object('ok', false, 'code','invalid_transition',
      'from', v_msg.status, 'to', p_target_status);
  END IF;
  IF p_target_status IN ('sent','failed') AND v_msg.status <> 'sending' THEN
    RETURN jsonb_build_object('ok', false, 'code','invalid_transition',
      'from', v_msg.status, 'to', p_target_status);
  END IF;

  PERFORM set_config('comm_hub.allow_targeted_update','true', true);

  UPDATE public.communication_message SET
    status = p_target_status,
    sent_at = CASE WHEN p_target_status='sent' THEN now() ELSE sent_at END,
    provider_message_id = COALESCE(p_provider_message_id, provider_message_id),
    error_code = CASE WHEN p_target_status='failed' THEN p_error_code ELSE error_code END,
    error_message = CASE WHEN p_target_status='failed' THEN p_error_message ELSE error_message END,
    updated_at = now()
  WHERE id = p_message_id;

  RETURN jsonb_build_object('ok', true, 'message_id', p_message_id, 'status', p_target_status);
END $function$;
CREATE OR REPLACE FUNCTION public.set_comm_hub_real_email_gate(p_module text, p_event text, p_channel text, p_enabled boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.communication_hub_real_email_gate%ROWTYPE;
  v_module  text := public.comm_hub_normalize_gate_key(p_module);
  v_event   text := public.comm_hub_normalize_gate_key(p_event);
  v_channel text := public.comm_hub_normalize_gate_key(coalesce(nullif(p_channel,''),'email'));
  v_reason  text := trim(coalesce(p_reason,''));
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF;
  IF NOT public.is_comm_hub_admin(v_uid) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  IF v_module = '' OR v_event = '' THEN RAISE EXCEPTION 'module_and_event_required'; END IF;
  IF length(v_reason) < 8 THEN RAISE EXCEPTION 'reason_required_min_8_chars'; END IF;

  INSERT INTO public.communication_hub_real_email_gate
    (module_code,event_code,channel,enabled,opened_by,opened_at,reason,closed_by,closed_at)
  VALUES
    (v_module, v_event, v_channel, p_enabled,
     CASE WHEN p_enabled THEN v_uid END,
     CASE WHEN p_enabled THEN now() END,
     v_reason,
     CASE WHEN NOT p_enabled THEN v_uid END,
     CASE WHEN NOT p_enabled THEN now() END)
  ON CONFLICT (module_code,event_code,channel) DO UPDATE
    SET enabled  = EXCLUDED.enabled,
        reason   = EXCLUDED.reason,
        opened_by = CASE WHEN EXCLUDED.enabled THEN v_uid
                         ELSE public.communication_hub_real_email_gate.opened_by END,
        opened_at = CASE WHEN EXCLUDED.enabled THEN now()
                         ELSE public.communication_hub_real_email_gate.opened_at END,
        closed_by = CASE WHEN NOT EXCLUDED.enabled THEN v_uid ELSE NULL END,
        closed_at = CASE WHEN NOT EXCLUDED.enabled THEN now() ELSE NULL END
  RETURNING * INTO v_row;

  RETURN jsonb_build_object('ok', true, 'gate', to_jsonb(v_row));
END $function$;
CREATE OR REPLACE FUNCTION public.set_comm_hub_sender_profile_flags(p_id uuid, p_is_enabled boolean, p_provider_identity_status text, p_domain_verified boolean, p_is_default boolean, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_hub_sender_profile%ROWTYPE;
  v_old jsonb;
BEGIN
  IF NOT has_role(p_actor_user_id, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden_admin_only';
  END IF;
  IF coalesce(trim(p_reason),'')='' THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT * INTO v_row FROM public.communication_hub_sender_profile WHERE id = p_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'sender_profile_not_found'; END IF;
  v_old := to_jsonb(v_row);

  IF p_is_default IS TRUE THEN
    UPDATE public.communication_hub_sender_profile SET is_default = false, updated_by = p_actor_user_id
      WHERE id <> p_id AND is_default = true;
  END IF;

  UPDATE public.communication_hub_sender_profile SET
    is_enabled = coalesce(p_is_enabled, is_enabled),
    provider_identity_status = coalesce(p_provider_identity_status, provider_identity_status),
    domain_verified = coalesce(p_domain_verified, domain_verified),
    is_default = coalesce(p_is_default, is_default),
    updated_by = p_actor_user_id
  WHERE id = p_id
  RETURNING * INTO v_row;

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('sender_profile_flags:'||v_row.profile_code, v_old, to_jsonb(v_row), p_reason, p_actor_user_id, 'set_comm_hub_sender_profile_flags');

  RETURN jsonb_build_object('ok', true, 'profile', to_jsonb(v_row));
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_comm_hub_sender_verification(p_id uuid, p_spf_status text, p_dkim_status text, p_dmarc_status text, p_verification_notes text, p_reason text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.communication_hub_sender_profile%ROWTYPE;
  v_old jsonb;
BEGIN
  IF NOT has_role(p_actor_user_id, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden_admin_only';
  END IF;
  IF coalesce(trim(p_reason),'')='' THEN RAISE EXCEPTION 'reason_required'; END IF;

  SELECT * INTO v_row FROM public.communication_hub_sender_profile WHERE id = p_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'sender_profile_not_found'; END IF;
  v_old := to_jsonb(v_row);

  UPDATE public.communication_hub_sender_profile SET
    spf_status         = coalesce(p_spf_status, spf_status),
    dkim_status        = coalesce(p_dkim_status, dkim_status),
    dmarc_status       = coalesce(p_dmarc_status, dmarc_status),
    verification_notes = coalesce(p_verification_notes, verification_notes),
    last_checked_at    = now(),
    last_checked_by    = p_actor_user_id,
    updated_by         = p_actor_user_id
  WHERE id = p_id
  RETURNING * INTO v_row;

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('sender_profile_verification:'||v_row.profile_code, v_old, to_jsonb(v_row), p_reason, p_actor_user_id, 'sender-verification-console');

  RETURN jsonb_build_object('ok', true, 'profile', to_jsonb(v_row));
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_communication_operating_mode(p_new_mode communication_operating_mode, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_is_admin  boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  BEGIN
    v_is_admin := public.is_comm_hub_operator_admin(v_uid);
  EXCEPTION WHEN undefined_function THEN
    SELECT public.has_role(v_uid, 'Admin'::public.app_role) INTO v_is_admin;
  END;
  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501';
  END IF;
  RETURN public._apply_comm_hub_mode_transition_core(
           p_new_mode, p_reason, NULL, v_uid, 'set_communication_operating_mode');
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_communication_operating_mode(p_new_mode text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_mode public.communication_operating_mode;
BEGIN
  BEGIN
    v_new_mode := p_new_mode::public.communication_operating_mode;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'unknown_operating_mode' USING ERRCODE='22023';
  END;
  RETURN public.set_communication_operating_mode(v_new_mode, p_reason);
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_communication_recipient_policy(p_active_mode text DEFAULT NULL::text, p_single_configured_address text DEFAULT NULL::text, p_clear_single_configured_address boolean DEFAULT false, p_approved_named_addresses jsonb DEFAULT NULL::jsonb, p_approved_domains jsonb DEFAULT NULL::jsonb, p_max_recipients_per_request integer DEFAULT NULL::integer, p_max_to_recipients integer DEFAULT NULL::integer, p_cc_allowed boolean DEFAULT NULL::boolean, p_max_cc_recipients integer DEFAULT NULL::integer, p_bcc_allowed boolean DEFAULT NULL::boolean, p_max_bcc_recipients integer DEFAULT NULL::integer, p_external_addresses_permitted boolean DEFAULT NULL::boolean, p_subdomains_permitted boolean DEFAULT NULL::boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor       uuid;
  v_before      public.communication_hub_recipient_policy%ROWTYPE;
  v_after       public.communication_hub_recipient_policy%ROWTYPE;
  v_new_mode    text;
  v_new_single  text;
  v_named       jsonb;
  v_domains     jsonb;
  v_addr        text;
  v_dom         text;
  v_x           jsonb;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL OR NOT public.has_role(v_actor, 'Admin'::public.app_role) THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'change_reason_required';
  END IF;

  SELECT * INTO v_before
    FROM public.communication_hub_recipient_policy
    WHERE singleton_guard = 'primary'
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'recipient_policy_singleton_missing';
  END IF;

  v_new_mode := COALESCE(p_active_mode, v_before.active_mode::text);
  IF v_new_mode NOT IN (
    'DISABLED','SINGLE_CONFIGURED_RECIPIENT','APPROVED_NAMED_RECIPIENTS',
    'APPROVED_DOMAINS','CONTROLLED_EXTERNAL_RECIPIENTS'
  ) THEN
    RAISE EXCEPTION 'invalid_recipient_mode: %', v_new_mode;
  END IF;

  IF v_new_mode = 'CONTROLLED_EXTERNAL_RECIPIENTS' THEN
    RAISE EXCEPTION 'controlled_external_recipients_not_certified';
  END IF;

  -- Normalise single-configured address (case-insensitive, trimmed).
  IF p_clear_single_configured_address THEN
    v_new_single := NULL;
  ELSIF p_single_configured_address IS NOT NULL THEN
    v_new_single := lower(btrim(p_single_configured_address));
    IF v_new_single = '' OR v_new_single NOT LIKE '_%@_%._%' THEN
      RAISE EXCEPTION 'invalid_single_configured_address';
    END IF;
  ELSE
    v_new_single := v_before.single_configured_address;
  END IF;

  IF v_new_mode = 'SINGLE_CONFIGURED_RECIPIENT' AND v_new_single IS NULL THEN
    RAISE EXCEPTION 'single_configured_address_required_for_mode';
  END IF;

  -- Normalise named addresses (jsonb array of {address, active, note?}).
  IF p_approved_named_addresses IS NOT NULL THEN
    IF jsonb_typeof(p_approved_named_addresses) <> 'array' THEN
      RAISE EXCEPTION 'approved_named_addresses_must_be_array';
    END IF;
    v_named := '[]'::jsonb;
    FOR v_x IN SELECT jsonb_array_elements(p_approved_named_addresses) LOOP
      v_addr := lower(btrim(COALESCE(v_x->>'address','')));
      IF v_addr = '' OR v_addr NOT LIKE '_%@_%._%' THEN
        RAISE EXCEPTION 'invalid_named_address: %', v_x->>'address';
      END IF;
      v_named := v_named || jsonb_build_object(
        'address', v_addr,
        'active',  COALESCE((v_x->>'active')::boolean, true),
        'note',    COALESCE(v_x->>'note', NULL)
      );
    END LOOP;
  ELSE
    v_named := v_before.approved_named_addresses;
  END IF;

  -- Normalise domains (jsonb array of {domain, active, note?}).
  IF p_approved_domains IS NOT NULL THEN
    IF jsonb_typeof(p_approved_domains) <> 'array' THEN
      RAISE EXCEPTION 'approved_domains_must_be_array';
    END IF;
    v_domains := '[]'::jsonb;
    FOR v_x IN SELECT jsonb_array_elements(p_approved_domains) LOOP
      v_dom := lower(btrim(COALESCE(v_x->>'domain','')));
      IF v_dom LIKE '@%' THEN v_dom := substring(v_dom from 2); END IF;
      IF v_dom = '' OR v_dom !~ '^[a-z0-9.-]+\.[a-z]{2,}$' THEN
        RAISE EXCEPTION 'invalid_domain: %', v_x->>'domain';
      END IF;
      v_domains := v_domains || jsonb_build_object(
        'domain', v_dom,
        'active', COALESCE((v_x->>'active')::boolean, true),
        'note',   COALESCE(v_x->>'note', NULL)
      );
    END LOOP;
  ELSE
    v_domains := v_before.approved_domains;
  END IF;

  IF v_new_mode = 'APPROVED_NAMED_RECIPIENTS'
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_named) e
                      WHERE COALESCE((e->>'active')::boolean, true))
  THEN
    RAISE EXCEPTION 'no_active_named_addresses_for_mode';
  END IF;
  IF v_new_mode = 'APPROVED_DOMAINS'
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_domains) e
                      WHERE COALESCE((e->>'active')::boolean, true))
  THEN
    RAISE EXCEPTION 'no_active_domains_for_mode';
  END IF;

  -- Apply the update (bump versions here so recipient-policy audit reflects new versions).
  UPDATE public.communication_hub_recipient_policy
     SET active_mode                  = v_new_mode::communication_recipient_policy_mode,
         single_configured_address    = v_new_single,
         approved_named_addresses     = v_named,
         approved_domains             = v_domains,
         max_recipients_per_request   = COALESCE(p_max_recipients_per_request,  max_recipients_per_request),
         max_to_recipients            = COALESCE(p_max_to_recipients,           max_to_recipients),
         cc_allowed                   = COALESCE(p_cc_allowed,                  cc_allowed),
         max_cc_recipients            = COALESCE(p_max_cc_recipients,           max_cc_recipients),
         bcc_allowed                  = COALESCE(p_bcc_allowed,                 bcc_allowed),
         max_bcc_recipients           = COALESCE(p_max_bcc_recipients,          max_bcc_recipients),
         external_addresses_permitted = COALESCE(p_external_addresses_permitted, external_addresses_permitted),
         subdomains_permitted         = COALESCE(p_subdomains_permitted,        subdomains_permitted),
         policy_version               = policy_version + 1,
         configuration_version        = configuration_version + 1,
         change_reason                = btrim(p_reason),
         changed_by                   = v_actor,
         changed_at                   = now(),
         updated_at                   = now()
   WHERE singleton_guard = 'primary'
  RETURNING * INTO v_after;

  -- Per-field audit rows (only where value actually changed).
  IF v_before.active_mode IS DISTINCT FROM v_after.active_mode THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'active_mode',
              to_jsonb(v_before.active_mode::text), to_jsonb(v_after.active_mode::text),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.single_configured_address IS DISTINCT FROM v_after.single_configured_address THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'single_configured_address',
              to_jsonb(v_before.single_configured_address), to_jsonb(v_after.single_configured_address),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.approved_named_addresses IS DISTINCT FROM v_after.approved_named_addresses THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'approved_named_addresses',
              v_before.approved_named_addresses, v_after.approved_named_addresses,
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.approved_domains IS DISTINCT FROM v_after.approved_domains THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'approved_domains',
              v_before.approved_domains, v_after.approved_domains,
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.max_recipients_per_request IS DISTINCT FROM v_after.max_recipients_per_request THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'max_recipients_per_request',
              to_jsonb(v_before.max_recipients_per_request), to_jsonb(v_after.max_recipients_per_request),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.max_to_recipients IS DISTINCT FROM v_after.max_to_recipients THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'max_to_recipients',
              to_jsonb(v_before.max_to_recipients), to_jsonb(v_after.max_to_recipients),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.cc_allowed IS DISTINCT FROM v_after.cc_allowed THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'cc_allowed',
              to_jsonb(v_before.cc_allowed), to_jsonb(v_after.cc_allowed),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.max_cc_recipients IS DISTINCT FROM v_after.max_cc_recipients THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'max_cc_recipients',
              to_jsonb(v_before.max_cc_recipients), to_jsonb(v_after.max_cc_recipients),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.bcc_allowed IS DISTINCT FROM v_after.bcc_allowed THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'bcc_allowed',
              to_jsonb(v_before.bcc_allowed), to_jsonb(v_after.bcc_allowed),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.max_bcc_recipients IS DISTINCT FROM v_after.max_bcc_recipients THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'max_bcc_recipients',
              to_jsonb(v_before.max_bcc_recipients), to_jsonb(v_after.max_bcc_recipients),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.external_addresses_permitted IS DISTINCT FROM v_after.external_addresses_permitted THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'external_addresses_permitted',
              to_jsonb(v_before.external_addresses_permitted), to_jsonb(v_after.external_addresses_permitted),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;
  IF v_before.subdomains_permitted IS DISTINCT FROM v_after.subdomains_permitted THEN
    INSERT INTO public.communication_hub_recipient_policy_audit
      (policy_id, changed_field, old_value, new_value, reason, changed_by,
       policy_version, configuration_version)
      VALUES (v_after.id, 'subdomains_permitted',
              to_jsonb(v_before.subdomains_permitted), to_jsonb(v_after.subdomains_permitted),
              btrim(p_reason), v_actor, v_after.policy_version, v_after.configuration_version);
  END IF;

  RETURN jsonb_build_object(
    'id', v_after.id,
    'active_mode', v_after.active_mode::text,
    'single_configured_address', v_after.single_configured_address,
    'approved_named_addresses', v_after.approved_named_addresses,
    'approved_domains', v_after.approved_domains,
    'max_recipients_per_request', v_after.max_recipients_per_request,
    'max_to_recipients', v_after.max_to_recipients,
    'cc_allowed', v_after.cc_allowed,
    'max_cc_recipients', v_after.max_cc_recipients,
    'bcc_allowed', v_after.bcc_allowed,
    'max_bcc_recipients', v_after.max_bcc_recipients,
    'external_addresses_permitted', v_after.external_addresses_permitted,
    'subdomains_permitted', v_after.subdomains_permitted,
    'policy_version', v_after.policy_version,
    'configuration_version', v_after.configuration_version,
    'change_reason', v_after.change_reason,
    'changed_by', v_after.changed_by,
    'changed_at', v_after.changed_at
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_default_head_cashier(p_office_code character varying, p_user_id uuid, p_user_code character varying, p_full_name character varying DEFAULT NULL::character varying, p_assigned_by character varying DEFAULT 'SYSTEM'::character varying)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev_user_code VARCHAR;
  v_new_id UUID;
BEGIN
  -- Get previous default for audit
  SELECT user_code INTO v_prev_user_code
  FROM cn_head_cashier_default
  WHERE office_code = p_office_code AND is_active = true;

  -- Deactivate old default
  UPDATE cn_head_cashier_default SET is_active = false
  WHERE office_code = p_office_code AND is_active = true;

  -- Insert new default
  INSERT INTO cn_head_cashier_default (office_code, user_id, user_code, full_name, assigned_by)
  VALUES (p_office_code, p_user_id, p_user_code, p_full_name, p_assigned_by)
  RETURNING id INTO v_new_id;

  -- Audit log
  INSERT INTO system_audit_trail (action, entity_type, entity_id, module, user_id, user_name, after_value, payload_json)
  VALUES ('set_default', 'cn_head_cashier_default', p_office_code, 'Payment Module', p_user_id, p_assigned_by,
    jsonb_build_object('user_code', p_user_code, 'office_code', p_office_code),
    jsonb_build_object('previous_user_code', v_prev_user_code));

  RETURN json_build_object('success', true, 'id', v_new_id, 'user_code', p_user_code);
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_email_campaigns_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_email_provider_default(provider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Clear current default for email channel (cast literal to enum)
  UPDATE notification_providers
  SET is_default = false
  WHERE channel = 'email'::notification_channel
    AND is_default = true;

  -- Set the new default
  UPDATE notification_providers
  SET is_default = true,
      updated_at = now()
  WHERE id = provider_id
    AND channel = 'email'::notification_channel;

  -- Raise if provider not found or wrong channel
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Provider % not found or is not an email provider', provider_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_event_live_control(p_module_code text, p_event_code text, p_new_status text, p_reason text, p_risk_level text, p_typed_confirmation text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev_status text;
  v_prev_risk   text;
  v_prev_reason text;
  v_found boolean := false;
  v_allowed_legacy    text;
  v_allowed_promote   text;
  v_allowed_canonical text;
  v_allowed_revert    text;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'set_event_live_control: actor required';
  END IF;
  IF NOT public.has_role(p_actor_user_id, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'set_event_live_control: forbidden — admin only';
  END IF;
  IF p_new_status NOT IN ('disabled','dry_run_only','live_manual_only','live_cron_allowed') THEN
    RAISE EXCEPTION 'set_event_live_control: invalid status %', p_new_status;
  END IF;
  IF coalesce(trim(p_reason),'') = '' THEN
    RAISE EXCEPTION 'set_event_live_control: reason required';
  END IF;
  IF p_new_status = 'live_cron_allowed' THEN
    RAISE EXCEPTION 'set_event_live_control: live_cron_allowed is not permitted in this phase';
  END IF;

  IF p_new_status = 'live_manual_only'
     AND NOT (
       (p_module_code = 'COMM_HUB'   AND p_event_code = 'ADMIN_TEST_NOTICE') OR
       (p_module_code = 'COMPLIANCE' AND p_event_code = 'INTERNAL_CASE_STATUS_NOTICE')
     ) THEN
    RAISE EXCEPTION 'set_event_live_control: event %/% not permitted for live_manual_only in this phase',
      p_module_code, p_event_code;
  END IF;

  IF p_new_status = 'live_manual_only' THEN
    v_allowed_legacy    := 'ENABLE live_manual_only FOR ' || p_module_code || '/' || p_event_code;
    v_allowed_promote   := 'PROMOTE ' || p_module_code || '/' || p_event_code || ' TO LIVE MANUAL ONLY';
    v_allowed_canonical := 'ENABLE LIVE ' || p_module_code || '/' || p_event_code;
    IF p_typed_confirmation IS DISTINCT FROM v_allowed_legacy
       AND p_typed_confirmation IS DISTINCT FROM v_allowed_promote
       AND p_typed_confirmation IS DISTINCT FROM v_allowed_canonical THEN
      RAISE EXCEPTION 'set_event_live_control: typed confirmation must equal "%", "%" or "%"',
        v_allowed_canonical, v_allowed_legacy, v_allowed_promote;
    END IF;
  ELSIF p_new_status = 'dry_run_only' THEN
    v_allowed_revert := 'REVERT ' || p_module_code || '/' || p_event_code || ' TO DRY RUN ONLY';
    SELECT status INTO v_prev_status FROM public.communication_hub_event_live_control
      WHERE module_code = p_module_code AND event_code = p_event_code LIMIT 1;
    IF v_prev_status IN ('live_manual_only','live_cron_allowed')
       AND p_typed_confirmation IS DISTINCT FROM v_allowed_revert THEN
      RAISE EXCEPTION 'set_event_live_control: typed confirmation must equal "%"', v_allowed_revert;
    END IF;
  END IF;

  SELECT status, risk_level, reason INTO v_prev_status, v_prev_risk, v_prev_reason
    FROM public.communication_hub_event_live_control
   WHERE module_code = p_module_code AND event_code = p_event_code LIMIT 1;
  v_found := FOUND;

  IF NOT v_found THEN
    INSERT INTO public.communication_hub_event_live_control(
      module_code, event_code, status, risk_level, reason, changed_by
    ) VALUES (p_module_code, p_event_code, p_new_status, coalesce(p_risk_level,'low'), p_reason, p_actor_user_id);
  ELSE
    UPDATE public.communication_hub_event_live_control
       SET status = p_new_status,
           risk_level = coalesce(p_risk_level, risk_level),
           reason = p_reason,
           changed_by = p_actor_user_id,
           changed_at = now()
     WHERE module_code = p_module_code AND event_code = p_event_code;
  END IF;

  INSERT INTO public.communication_hub_control_audit(
    setting_key, old_value, new_value, reason, changed_by, source
  ) VALUES (
    'event_live_control:' || p_module_code || '/' || p_event_code,
    jsonb_build_object('status', v_prev_status, 'risk_level', v_prev_risk, 'reason', v_prev_reason),
    jsonb_build_object('status', p_new_status, 'risk_level', coalesce(p_risk_level, v_prev_risk, 'low'), 'reason', p_reason),
    p_reason, p_actor_user_id, 'set_event_live_control'
  );

  RETURN jsonb_build_object(
    'ok', true, 'module_code', p_module_code, 'event_code', p_event_code,
    'previous_status', v_prev_status, 'new_status', p_new_status
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_meeting_contact_person_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.contact_person IS NOT NULL AND (
    TG_OP = 'INSERT' OR OLD.contact_person IS DISTINCT FROM NEW.contact_person
  ) THEN
    SELECT full_name INTO NEW.contact_person_name
    FROM public.profiles
    WHERE user_code = NEW.contact_person
    LIMIT 1;
  END IF;
  
  IF NEW.contact_person IS NULL THEN
    NEW.contact_person_name := NULL;
  END IF;
  
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_push_provider_default(provider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.notification_providers
  SET is_active = false, updated_at = now()
  WHERE channel = 'push' AND is_active = true AND id != provider_id;

  UPDATE public.notification_providers
  SET is_active = true, updated_at = now()
  WHERE id = provider_id AND channel = 'push';
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_receipt_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_payer_id TEXT;
  v_ts TEXT;
  v_rn TEXT;
  v_config_val JSONB;
  v_segments JSONB;
  v_context JSONB;
BEGIN
  -- Resolve payer_id
  SELECT payer_id INTO v_payer_id
  FROM public.cn_payment_header
  WHERE payment_id = NEW.payment_id;

  -- Read config
  SELECT config_value INTO v_config_val
  FROM public.payment_module_config
  WHERE config_key = 'receipt_number_format';

  -- Check for segments array (new format)
  IF v_config_val IS NOT NULL AND v_config_val ? 'segments' THEN
    v_segments := v_config_val->'segments';
    v_context := jsonb_build_object(
      'PAYER_ID', COALESCE(v_payer_id, 'UNKNOWN'),
      'RECEIPT_ID', NEW.receipt_id::TEXT,
      'PAYMENT_ID', NEW.payment_id::TEXT,
      'ts', COALESCE(NEW.created_at, now())::TEXT
    );
    v_rn := public.resolve_number_segments(v_segments, v_context);

  -- Legacy format string fallback
  ELSIF v_config_val IS NOT NULL AND v_config_val ? 'format' THEN
    DECLARE
      v_format TEXT := v_config_val->>'format';
      v_id_min_length INT := COALESCE((v_config_val->>'id_min_length')::INT, 1);
      v_receipt_id_padded TEXT;
    BEGIN
      IF v_format IS NOT NULL AND v_format != '' THEN
        v_receipt_id_padded := LPAD(NEW.receipt_id::TEXT, GREATEST(v_id_min_length, 1), '0');
        v_rn := v_format;
        v_rn := REPLACE(v_rn, '{PAYER_ID}', COALESCE(v_payer_id, 'UNKNOWN'));
        v_rn := REPLACE(v_rn, '{RECEIPT_ID}', v_receipt_id_padded);
        v_rn := REPLACE(v_rn, '{PAYMENT_ID}', NEW.payment_id::TEXT);
        v_rn := REPLACE(v_rn, '{YYYY}', to_char(COALESCE(NEW.created_at, now()), 'YYYY'));
        v_rn := REPLACE(v_rn, '{YY}', to_char(COALESCE(NEW.created_at, now()), 'YY'));
        v_rn := REPLACE(v_rn, '{YYYYMMDD}', to_char(COALESCE(NEW.created_at, now()), 'YYYYMMDD'));
        v_rn := REPLACE(v_rn, '{YYYYMM}', to_char(COALESCE(NEW.created_at, now()), 'YYYYMM'));
        v_rn := REPLACE(v_rn, '{DDMMYYYY}', to_char(COALESCE(NEW.created_at, now()), 'DDMMYYYY'));
        v_rn := REPLACE(v_rn, '{DDMMYYYYHHMM}', to_char(COALESCE(NEW.created_at, now()), 'DDMMYYYYHH24MI'));
        v_rn := REPLACE(v_rn, '{MM}', to_char(COALESCE(NEW.created_at, now()), 'MM'));
        v_rn := REPLACE(v_rn, '{DD}', to_char(COALESCE(NEW.created_at, now()), 'DD'));
        v_rn := REPLACE(v_rn, '{HHMMSS}', to_char(COALESCE(NEW.created_at, now()), 'HH24MISS'));
        v_rn := REPLACE(v_rn, '{HHMM}', to_char(COALESCE(NEW.created_at, now()), 'HH24MI'));
        v_rn := REPLACE(v_rn, '{HH}', to_char(COALESCE(NEW.created_at, now()), 'HH24'));
        v_rn := REPLACE(v_rn, '{MI}', to_char(COALESCE(NEW.created_at, now()), 'MI'));
        v_rn := REPLACE(v_rn, '{SS}', to_char(COALESCE(NEW.created_at, now()), 'SS'));
      END IF;
    END;

  ELSE
    -- Default fallback
    v_ts := to_char(COALESCE(NEW.created_at, now()), 'DDMMYYYYHH24MI');
    v_rn := COALESCE(v_payer_id, 'UNKNOWN') || '/' || NEW.receipt_id || '/' || v_ts;
  END IF;

  IF v_rn IS NOT NULL THEN
    UPDATE public.cn_receipt
    SET receipt_number = v_rn
    WHERE receipt_id = NEW.receipt_id;
  END IF;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_recipient_test_identity(p_action text, p_display_name text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_policy RECORD;
  v_old_name text;
  v_old_source text;
  v_old_confirmed boolean;
  v_new_name text;
  v_new_source text;
  v_new_confirmed boolean;
  v_new_confirmed_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF NOT public.has_role(v_uid, 'Admin'::app_role) THEN
    RAISE EXCEPTION 'admin role required';
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('confirm','edit','clear') THEN
    RAISE EXCEPTION 'invalid action: %', p_action;
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'reason is required';
  END IF;

  SELECT * INTO v_policy
  FROM public.communication_hub_recipient_policy
  WHERE singleton_guard = 'primary'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'recipient policy singleton missing';
  END IF;

  v_old_name := v_policy.single_configured_display_name;
  v_old_source := v_policy.single_configured_display_name_source;
  v_old_confirmed := v_policy.single_configured_display_name_confirmed;

  IF p_action = 'confirm' THEN
    IF v_old_name IS NULL OR length(trim(v_old_name)) = 0 THEN
      RAISE EXCEPTION 'cannot confirm an empty display name';
    END IF;
    v_new_name := v_old_name;
    v_new_source := v_old_source; -- preserve provenance; confirmation only flips the flag
    v_new_confirmed := true;
    v_new_confirmed_at := now();
  ELSIF p_action = 'edit' THEN
    IF p_display_name IS NULL OR length(trim(p_display_name)) = 0 THEN
      RAISE EXCEPTION 'display_name required when action=edit';
    END IF;
    v_new_name := trim(p_display_name);
    v_new_source := 'operator_configured';
    v_new_confirmed := true;
    v_new_confirmed_at := now();
  ELSE  -- clear
    v_new_name := NULL;
    v_new_source := 'unknown';
    v_new_confirmed := false;
    v_new_confirmed_at := NULL;
  END IF;

  UPDATE public.communication_hub_recipient_policy
  SET single_configured_display_name = v_new_name,
      single_configured_display_name_source = v_new_source,
      single_configured_display_name_confirmed = v_new_confirmed,
      single_configured_display_name_confirmed_at = v_new_confirmed_at,
      single_configured_display_name_confirmed_by = CASE WHEN v_new_confirmed THEN v_uid ELSE NULL END,
      configuration_version = configuration_version + 1,
      change_reason = p_reason,
      changed_by = v_uid,
      changed_at = now(),
      updated_at = now()
  WHERE singleton_guard = 'primary';

  -- Audit row per changed field
  IF COALESCE(v_old_name,'') IS DISTINCT FROM COALESCE(v_new_name,'') THEN
    INSERT INTO public.communication_hub_recipient_policy_audit(
      policy_id, changed_field, old_value, new_value, reason, changed_by,
      policy_version, configuration_version
    ) VALUES (
      v_policy.id, 'single_configured_display_name',
      to_jsonb(v_old_name), to_jsonb(v_new_name),
      p_reason, v_uid,
      v_policy.policy_version, v_policy.configuration_version + 1
    );
  END IF;
  IF v_old_source IS DISTINCT FROM v_new_source THEN
    INSERT INTO public.communication_hub_recipient_policy_audit(
      policy_id, changed_field, old_value, new_value, reason, changed_by,
      policy_version, configuration_version
    ) VALUES (
      v_policy.id, 'single_configured_display_name_source',
      to_jsonb(v_old_source), to_jsonb(v_new_source),
      p_reason, v_uid,
      v_policy.policy_version, v_policy.configuration_version + 1
    );
  END IF;
  IF v_old_confirmed IS DISTINCT FROM v_new_confirmed THEN
    INSERT INTO public.communication_hub_recipient_policy_audit(
      policy_id, changed_field, old_value, new_value, reason, changed_by,
      policy_version, configuration_version
    ) VALUES (
      v_policy.id, 'single_configured_display_name_confirmed',
      to_jsonb(v_old_confirmed), to_jsonb(v_new_confirmed),
      p_reason, v_uid,
      v_policy.policy_version, v_policy.configuration_version + 1
    );
  END IF;

  RETURN jsonb_build_object(
    'display_name', v_new_name,
    'source', v_new_source,
    'confirmed', v_new_confirmed,
    'confirmed_at', v_new_confirmed_at,
    'confirmed_by', CASE WHEN v_new_confirmed THEN v_uid ELSE NULL END
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_sms_provider_default(provider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.notification_providers
  SET is_active = false, updated_at = now()
  WHERE channel = 'sms' AND is_active = true AND id != provider_id;

  UPDATE public.notification_providers
  SET is_active = true, updated_at = now()
  WHERE id = provider_id AND channel = 'sms';
END;
$function$;
