CREATE OR REPLACE FUNCTION public.start_comm_hub_revalidation_cycle(p_module_code text, p_event_code text, p_channel text, p_purpose comm_hub_revalidation_purpose, p_reason text, p_change_ticket_reference text DEFAULT NULL::text, p_declared_change_categories jsonb DEFAULT '[]'::jsonb, p_runtime_release_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := public._chrc_require_admin();
  v_assess jsonb;
  v_baseline jsonb;
  v_cycle_id uuid;
  v_release_id uuid;
  v_config_version bigint;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason)) < 6 THEN
    RAISE EXCEPTION 'reason_required_min_6_chars';
  END IF;

  v_assess := public.assess_comm_hub_revalidation_requirement(
    p_module_code,p_event_code,p_channel,p_declared_change_categories,p_runtime_release_reference
  );
  IF (v_assess->>'ok')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'assessment_failed: %', v_assess->>'error';
  END IF;
  v_baseline := v_assess->'baseline';

  IF p_runtime_release_reference IS NOT NULL THEN
    SELECT id INTO v_release_id FROM public.communication_hub_runtime_release
      WHERE release_reference = p_runtime_release_reference LIMIT 1;
  END IF;

  SELECT configuration_version INTO v_config_version
    FROM public.communication_hub_control_settings LIMIT 1;

  INSERT INTO public.communication_hub_revalidation_cycle(
    module_code,event_code,channel,purpose,reason,change_ticket_reference,
    status,started_by,
    baseline_event_certification_id, baseline_ore_certification_id, baseline_production_lineage_id,
    baseline_evidence_core_v2, baseline_evidence_fingerprint_v2,
    current_evidence_core_v2, current_evidence_fingerprint_v2,
    changed_components, runtime_changes, required_validation_level, required_stages,
    runtime_release_id, configuration_version_at_start
  ) VALUES (
    p_module_code,p_event_code,p_channel,p_purpose,p_reason,p_change_ticket_reference,
    CASE WHEN (v_assess->>'drift_detected')::boolean
         AND (v_assess->>'required_validation_level') <> 'NONE'
         THEN 'REVALIDATION_REQUIRED'::public.comm_hub_revalidation_status
         ELSE 'ASSESSING'::public.comm_hub_revalidation_status END,
    v_uid,
    (v_baseline->>'event_certification_id')::uuid,
    (v_baseline->>'ore_certification_id')::uuid,
    (v_baseline->>'production_lineage_id')::uuid,
    v_baseline->'evidence_core_v2',
    v_baseline->>'evidence_fingerprint_v2',
    v_assess->'current_evidence_core_v2',
    v_assess->>'current_fingerprint',
    v_assess->'changed_components',
    v_assess->'runtime_changes',
    (v_assess->>'required_validation_level')::public.comm_hub_revalidation_level,
    v_assess->'required_stages',
    v_release_id, v_config_version
  ) RETURNING id INTO v_cycle_id;

  RETURN jsonb_build_object('ok',true,'cycle_id',v_cycle_id,'assessment',v_assess);
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'unresolved_cycle_exists';
END $function$;
CREATE OR REPLACE FUNCTION public.start_comm_hub_trace(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_no text; v_email text;
BEGIN
  v_no := 'TRC-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('public.communication_hub_trace_no_seq')::text, 6, '0');
  v_email := NULLIF(p_payload->>'recipient_email', '');
  INSERT INTO public.communication_hub_trace (
    trace_no, correlation_id, module_code, event_code, channel,
    entity_type, entity_id, reference_no, source_module, source_screen, source_action,
    initiated_by, recipient_email_masked, recipient_domain, status, current_stage, metadata
  ) VALUES (
    v_no, NULLIF(p_payload->>'correlation_id',''), NULLIF(p_payload->>'module_code',''),
    NULLIF(p_payload->>'event_code',''), COALESCE(NULLIF(p_payload->>'channel',''), 'email'),
    NULLIF(p_payload->>'entity_type',''), NULLIF(p_payload->>'entity_id',''),
    NULLIF(p_payload->>'reference_no',''), NULLIF(p_payload->>'source_module',''),
    NULLIF(p_payload->>'source_screen',''), NULLIF(p_payload->>'source_action',''),
    NULLIF(p_payload->>'initiated_by','')::uuid,
    public._ch_mask_email(v_email), public._ch_extract_domain(v_email),
    COALESCE(NULLIF(p_payload->>'status',''), 'initiated'),
    NULLIF(p_payload->>'current_stage',''),
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  ) RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'trace_id', v_id, 'trace_no', v_no);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END; $function$;
CREATE OR REPLACE FUNCTION public.submit_c3_record(p_c3_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_record RECORD;
    v_user_name TEXT;
BEGIN
    -- Get user name if user_id provided
    IF p_user_id IS NOT NULL THEN
        SELECT full_name INTO v_user_name FROM profiles WHERE id = p_user_id;
    END IF;

    -- Lock the record
    SELECT * INTO v_record
    FROM cn_c3_reported
    WHERE id = p_c3_id
    FOR UPDATE;
    
    IF v_record IS NULL THEN
        RAISE EXCEPTION 'C3 record not found';
    END IF;
    
    -- Check for Draft status (DFT or legacy Z)
    IF v_record.posting_status NOT IN ('DFT', 'Z') THEN
        RAISE EXCEPTION 'Only draft records can be submitted. Current status: %', v_record.posting_status;
    END IF;
    
    -- Update C3 record status to Pending (PEN)
    UPDATE cn_c3_reported
    SET posting_status = 'PEN',
        date_entered = COALESCE(date_entered, NOW()),
        entered_by = COALESCE(entered_by, v_user_name),
        modified_date = NOW(),
        modified_by = v_user_name,
        updated_at = NOW()
    WHERE id = p_c3_id;
    
    -- Update all associated wage records
    UPDATE ip_wages
    SET posting_status = 'PEN',
        date_entered = COALESCE(date_entered, NOW()),
        entered_by = COALESCE(entered_by, v_user_name),
        date_modified = NOW(),
        modified_by = v_user_name,
        updated_at = NOW()
    WHERE c3_id = p_c3_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'c3_id', p_c3_id,
        'old_status', v_record.posting_status,
        'new_status', 'PEN',
        'message', 'C3 record submitted successfully'
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.submit_er_registration(p_temp_regno text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_new_regno TEXT;
  v_attempt INT;
  v_rowcount INT;
BEGIN
  SELECT * INTO v_record
  FROM public.er_master
  WHERE regno = p_temp_regno
  FOR UPDATE;

  IF v_record IS NULL THEN
    RAISE EXCEPTION 'Employer registration not found';
  END IF;

  IF v_record.status IS DISTINCT FROM 'Z' THEN
    RAISE EXCEPTION 'Only draft registrations can be submitted';
  END IF;

  IF v_record.regno IS NOT NULL AND v_record.regno ~ '^[0-9]{6}$' THEN
    v_new_regno := v_record.regno;
  ELSE
    v_new_regno := NULL;
  END IF;

  v_attempt := 0;
  LOOP
    v_attempt := v_attempt + 1;
    IF v_new_regno IS NULL THEN
      v_new_regno := public.generate_er_regno();
    END IF;
    BEGIN
      UPDATE public.er_master
      SET regno = v_new_regno, status = 'P', date_modified = NOW()
      WHERE regno = p_temp_regno;

      GET DIAGNOSTICS v_rowcount = ROW_COUNT;
      IF v_rowcount <> 1 THEN
        RAISE EXCEPTION 'Failed to update registration status';
      END IF;

      UPDATE public.er_owner SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_locations SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_notes SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_commence SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_visit SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_suit SET regno = v_new_regno WHERE regno = p_temp_regno;
      EXIT;
    EXCEPTION
      WHEN unique_violation THEN
        v_new_regno := NULL;
        IF v_attempt >= 10 THEN
          RAISE EXCEPTION 'Unable to generate a unique registration number after % attempts', v_attempt;
        END IF;
    END;
  END LOOP;

  -- Auto-create cn_payer record for ER
  PERFORM public.upsert_cn_payer('ER', v_new_regno, v_record.name, v_record.email, v_record.phone);

  RETURN jsonb_build_object(
    'success', true,
    'old_regno', p_temp_regno,
    'new_regno', v_new_regno,
    'status', 'P'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.submit_er_registration(p_temp_regno text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_new_regno TEXT;
  v_attempt INT;
  v_rowcount INT;
BEGIN
  -- Lock the row to prevent concurrent submissions
  SELECT *
  INTO v_record
  FROM public.er_master
  WHERE regno = p_temp_regno
  FOR UPDATE;

  IF v_record IS NULL THEN
    RAISE EXCEPTION 'Employer registration not found';
  END IF;

  IF v_record.status IS DISTINCT FROM 'Z' THEN
    RAISE EXCEPTION 'Only draft registrations can be submitted';
  END IF;

  -- If regno is already a permanent 6-digit numeric, keep it; otherwise generate a new one
  IF v_record.regno IS NOT NULL AND v_record.regno ~ '^[0-9]{6}$' THEN
    v_new_regno := v_record.regno;
  ELSE
    v_new_regno := NULL;
  END IF;

  v_attempt := 0;
  LOOP
    v_attempt := v_attempt + 1;

    IF v_new_regno IS NULL THEN
      v_new_regno := public.generate_er_regno();
    END IF;

    BEGIN
      -- Update the record with new permanent regno and Pending status
      UPDATE public.er_master
      SET
        regno = v_new_regno,
        status = 'P',
        date_modified = NOW()
      WHERE regno = p_temp_regno;

      GET DIAGNOSTICS v_rowcount = ROW_COUNT;
      IF v_rowcount <> 1 THEN
        RAISE EXCEPTION 'Failed to update registration status';
      END IF;

      -- Update related tables with new regno (only tables that have regno column)
      UPDATE public.er_owner SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_locations SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_notes SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_commence SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_visit SET regno = v_new_regno WHERE regno = p_temp_regno;
      UPDATE public.er_suit SET regno = v_new_regno WHERE regno = p_temp_regno;
      -- Note: er_notification table does not have regno column, so it's excluded

      EXIT; -- success

    EXCEPTION
      WHEN unique_violation THEN
        -- Collision on regno unique constraint - retry a few times
        v_new_regno := NULL;
        IF v_attempt >= 10 THEN
          RAISE EXCEPTION 'Unable to generate a unique registration number after % attempts', v_attempt;
        END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'old_regno', p_temp_regno,
    'new_regno', v_new_regno,
    'status', 'P'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.submit_ip_registration(p_unique_uuid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record record;
  v_new_ssn text;
  v_attempt int;
  v_rowcount int;
  v_name text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_record
  FROM public.ip_master
  WHERE unique_uuid = p_unique_uuid
  FOR UPDATE;

  IF v_record IS NULL THEN
    RAISE EXCEPTION 'Registration not found';
  END IF;

  IF v_record.status IS DISTINCT FROM 'Z' THEN
    RAISE EXCEPTION 'Only draft registrations can be submitted';
  END IF;

  IF v_record.ssn IS NOT NULL AND v_record.ssn ~ '^[0-9]{6}$' THEN
    v_new_ssn := v_record.ssn;
  ELSE
    v_new_ssn := NULL;
  END IF;

  v_attempt := 0;
  LOOP
    v_attempt := v_attempt + 1;
    IF v_new_ssn IS NULL THEN
      v_new_ssn := public.generate_ip_ssn();
    END IF;
    BEGIN
      UPDATE public.ip_master
      SET ssn = v_new_ssn, status = 'P',
          submitted_by = auth.uid(), submitted_at = now(),
          updated_by = auth.uid(), updated_at = now()
      WHERE unique_uuid = p_unique_uuid;

      GET DIAGNOSTICS v_rowcount = ROW_COUNT;
      IF v_rowcount <> 1 THEN
        RAISE EXCEPTION 'Failed to update registration status';
      END IF;
      EXIT;
    EXCEPTION
      WHEN unique_violation THEN
        v_new_ssn := NULL;
        IF v_attempt >= 10 THEN
          RAISE EXCEPTION 'Unable to generate a unique SSN after % attempts', v_attempt;
        END IF;
    END;
  END LOOP;

  -- Auto-create cn_payer record for IP
  v_name := TRIM(BOTH FROM CONCAT(v_record.firstname, ' ', v_record.surname));
  PERFORM public.upsert_cn_payer('IP', v_new_ssn, v_name, v_record.email_addr, v_record.phone);

  RETURN jsonb_build_object(
    'success', true,
    'unique_uuid', p_unique_uuid::text,
    'ssn', v_new_ssn,
    'status', 'P'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.suspend_comm_hub_event_certification_on_drift(p_module text, p_event text, p_channel text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_updated int;
BEGIN
  UPDATE public.communication_hub_event_certification
     SET status='SUSPENDED', drift_detected_at=now(),
         drift_reason=p_reason, suspended_at=now()
   WHERE module_code=p_module AND event_code=p_event AND channel=coalesce(p_channel,'email')
     AND status IN ('live_manual_only','live_cron_allowed');
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  UPDATE public.communication_hub_event_live_control
     SET status='dry_run_only', reason='drift: '||coalesce(p_reason,''),
         changed_at=now(), updated_at=now()
   WHERE module_code=p_module AND event_code=p_event
     AND status IN ('live_manual_only','live_cron_allowed');

  RETURN jsonb_build_object('ok',true,'suspended_rows',v_updated);
END $function$;
CREATE OR REPLACE FUNCTION public.test_data_policy(_test_user_id uuid, _module_name text, _action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result JSONB;
  module_record RECORD;
  user_profile RECORD;
  user_roles_list TEXT[];
  applied_scope_rules JSONB := '[]'::jsonb;
  applied_field_rules JSONB := '[]'::jsonb;
  user_overrides_list JSONB := '[]'::jsonb;
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RETURN jsonb_build_object('error', 'Only administrators can test policies');
  END IF;

  SELECT full_name, email INTO user_profile FROM profiles WHERE id = _test_user_id;
  SELECT array_agg(role::TEXT) INTO user_roles_list FROM user_roles WHERE user_id = _test_user_id;
  SELECT * INTO module_record FROM app_modules WHERE name = _module_name AND is_enabled = true;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', dsr.id, 'target_table', dsr.target_table, 'role', r.role_name,
    'condition_type', dsr.condition_type, 'condition_value', dsr.condition_value,
    'can_view', dsr.can_view, 'can_edit', dsr.can_edit, 'can_delete', dsr.can_delete,
    'priority', dsr.priority, 'is_active', dsr.is_active
  )), '[]'::jsonb)
  INTO applied_scope_rules
  FROM data_scope_rules dsr
  JOIN roles r ON r.id = dsr.role_id
  WHERE dsr.module_id = module_record.id AND r.role_name = ANY(user_roles_list);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', fsr.id, 'field_name', fsr.field_name, 'role', r.role_name,
    'can_view', fsr.can_view, 'can_edit', fsr.can_edit,
    'masking_type', fsr.masking_type, 'priority', fsr.priority, 'is_active', fsr.is_active
  )), '[]'::jsonb)
  INTO applied_field_rules
  FROM field_security_rules fsr
  JOIN roles r ON r.id = fsr.role_id
  WHERE fsr.module_id = module_record.id AND r.role_name = ANY(user_roles_list);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', udo.id, 'override_type', udo.override_type, 'field_name', udo.field_name,
    'reason', udo.reason, 'expires_at', udo.expires_at, 'is_active', udo.is_active
  )), '[]'::jsonb)
  INTO user_overrides_list
  FROM user_data_overrides udo
  WHERE udo.user_id = _test_user_id AND udo.module_id = module_record.id;

  RETURN jsonb_build_object(
    'user', jsonb_build_object(
      'id', _test_user_id, 'name', user_profile.full_name, 'email', user_profile.email,
      'roles', user_roles_list, 'is_admin', public.is_admin(_test_user_id)
    ),
    'module', jsonb_build_object('id', module_record.id, 'name', module_record.name, 'display_name', module_record.display_name),
    'action', _action,
    'scope_rules', applied_scope_rules,
    'field_rules', applied_field_rules,
    'user_overrides', user_overrides_list,
    'effective_access', public.check_row_access(_test_user_id, _module_name, '', _action)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.test_workflow_policy(_test_user_id uuid, _workflow_id uuid, _record_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user profiles;
  v_definition workflow_definitions;
  v_instance workflow_instances;
  v_module app_modules;
  v_task_access jsonb;
  v_field_rules jsonb;
  v_available_actions jsonb;
  v_result jsonb;
  v_is_admin boolean;
BEGIN
  -- Get user
  SELECT * INTO v_user FROM profiles WHERE id = _test_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'User not found');
  END IF;
  
  -- Check if admin
  v_is_admin := is_admin(_test_user_id);
  
  -- Get workflow definition
  SELECT * INTO v_definition FROM workflow_definitions WHERE id = _workflow_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Workflow not found');
  END IF;
  
  -- Get secured module if set
  IF v_definition.secured_module_id IS NOT NULL THEN
    SELECT * INTO v_module FROM app_modules WHERE id = v_definition.secured_module_id;
  END IF;
  
  -- If record_id provided, find matching workflow instance
  IF _record_id IS NOT NULL THEN
    SELECT * INTO v_instance FROM workflow_instances 
    WHERE workflow_id = _workflow_id AND source_record_id = _record_id::text
    LIMIT 1;
  END IF;
  
  -- Build result
  v_result := jsonb_build_object(
    'user', jsonb_build_object(
      'id', v_user.id,
      'name', v_user.full_name,
      'email', v_user.email,
      'is_admin', v_is_admin,
      'department_id', v_user.department_id
    ),
    'workflow', jsonb_build_object(
      'id', v_definition.id,
      'name', v_definition.name,
      'secured_module', v_module.display_name,
      'secured_table', v_definition.secured_table
    )
  );
  
  -- If no security binding, show full access
  IF v_definition.secured_table IS NULL OR v_definition.secured_table = '' THEN
    v_result := v_result || jsonb_build_object(
      'can_see_workflow', true,
      'reason', 'No security binding - full access',
      'visible_fields', '[]'::jsonb,
      'available_actions', '["approve","reject","query","send_back"]'::jsonb
    );
    RETURN v_result;
  END IF;
  
  -- Check if user is admin
  IF v_is_admin THEN
    v_result := v_result || jsonb_build_object(
      'can_see_workflow', true,
      'reason', 'Admin access',
      'visible_fields', '[]'::jsonb,
      'available_actions', '["approve","reject","query","send_back"]'::jsonb
    );
    RETURN v_result;
  END IF;
  
  -- Check row access
  v_task_access := check_row_access(_test_user_id, '', v_definition.secured_table, 'view');
  
  IF NOT COALESCE((v_task_access->>'allowed')::boolean, false) THEN
    v_result := v_result || jsonb_build_object(
      'can_see_workflow', false,
      'reason', COALESCE(v_task_access->>'reason', 'Access denied by scope rules'),
      'visible_fields', '[]'::jsonb,
      'available_actions', '[]'::jsonb,
      'scope_rules_applied', v_task_access->'rules_applied'
    );
    RETURN v_result;
  END IF;
  
  -- Get visible fields
  v_field_rules := get_visible_fields(_test_user_id, '', v_definition.secured_table);
  
  -- Check edit access for actions
  v_task_access := check_row_access(_test_user_id, '', v_definition.secured_table, 'edit');
  
  IF COALESCE((v_task_access->>'allowed')::boolean, false) THEN
    v_available_actions := '["approve","reject","query","send_back"]'::jsonb;
  ELSE
    v_available_actions := '["view"]'::jsonb;
  END IF;
  
  v_result := v_result || jsonb_build_object(
    'can_see_workflow', true,
    'reason', 'Access granted via data policies',
    'visible_fields', v_field_rules,
    'available_actions', v_available_actions,
    'scope_rules_applied', v_task_access->'rules_applied'
  );
  
  RETURN v_result;
END;
$function$;
