CREATE OR REPLACE FUNCTION public.trg_c3_config_periods_dual_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action TEXT;
  v_old_value TEXT;
  v_new_value TEXT;
  v_field_name TEXT;
  v_entity_name TEXT;
  v_user_code TEXT;
  v_user_name TEXT;
  v_user_id UUID;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE';
    v_old_value := NULL;
    v_new_value := to_jsonb(NEW)::text;
    v_field_name := NULL;
    v_user_code := NEW.created_by;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
      v_action := CASE WHEN NEW.is_active THEN 'ENABLE' ELSE 'DISABLE' END;
      v_field_name := 'is_active';
      v_old_value := OLD.is_active::text;
      v_new_value := NEW.is_active::text;
    ELSE
      v_action := 'UPDATE';
      v_field_name := NULL;
      v_old_value := to_jsonb(OLD)::text;
      v_new_value := to_jsonb(NEW)::text;
    END IF;
    v_user_code := NEW.modified_by;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'DELETE';
    v_old_value := to_jsonb(OLD)::text;
    v_new_value := NULL;
    v_field_name := NULL;
    v_user_code := OLD.modified_by;
  END IF;

  v_entity_name := 'Period Config (' || 
    COALESCE(to_char(COALESCE(NEW.start_date, OLD.start_date), 'DD Mon YYYY'), '?') || ' - ' ||
    COALESCE(to_char(COALESCE(NEW.end_date, OLD.end_date), 'DD Mon YYYY'), 'Current') || ')';

  -- Resolve user_code to full_name and user id from profiles
  IF v_user_code IS NOT NULL AND v_user_code <> '' THEN
    SELECT id, full_name INTO v_user_id, v_user_name
    FROM public.profiles
    WHERE user_code = v_user_code
    LIMIT 1;
  END IF;

  -- Fallback to auth.uid()
  IF v_user_id IS NULL THEN
    BEGIN
      v_user_id := auth.uid();
      IF v_user_id IS NOT NULL THEN
        SELECT user_code, full_name INTO v_user_code, v_user_name
        FROM public.profiles WHERE id = v_user_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  -- 1) Insert into c3_unified_audit_log (C3 Config audit tab)
  INSERT INTO public.c3_unified_audit_log (
    config_type, record_id, action, entity_name, field_name,
    old_value, new_value, changed_by, changed_by_name, changed_at, metadata
  ) VALUES (
    'period_config',
    COALESCE(NEW.id, OLD.id)::text,
    v_action,
    v_entity_name,
    v_field_name,
    v_old_value,
    v_new_value,
    COALESCE(v_user_code, v_user_id::text),
    v_user_name,
    NOW(),
    jsonb_build_object(
      'start_date', COALESCE(NEW.start_date, OLD.start_date),
      'end_date', COALESCE(NEW.end_date, OLD.end_date),
      'route', '/admin/c3-configuration',
      'module', 'C3 Configuration'
    )
  );

  -- 2) Insert into system_audit_trail (global System Monitoring)
  INSERT INTO public.system_audit_trail (
    user_id, user_name, action, entity_type, entity_id, module,
    before_value, after_value, severity, timestamp
  ) VALUES (
    v_user_id,
    COALESCE(v_user_name, v_user_code, 'SYSTEM'),
    v_action,
    'C3Configuration',
    COALESCE(NEW.id, OLD.id)::text,
    'C3 Configuration',
    CASE WHEN OLD IS NOT NULL THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN NEW IS NOT NULL THEN to_jsonb(NEW) ELSE NULL END,
    'info',
    NOW()
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'Error in trg_c3_config_periods_dual_audit: % %', SQLERRM, SQLSTATE;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_c3_config_to_system_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action TEXT;
  v_user_id UUID;
  v_user_code TEXT;
  v_user_name TEXT;
  v_record_id TEXT;
  v_modified_by TEXT;
BEGIN
  v_record_id := COALESCE(NEW.id, OLD.id)::text;

  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE';
    BEGIN v_modified_by := NEW.created_by; EXCEPTION WHEN OTHERS THEN v_modified_by := NULL; END;
  ELSIF TG_OP = 'UPDATE' THEN
    BEGIN
      IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
        v_action := CASE WHEN NEW.is_active THEN 'ENABLE' ELSE 'DISABLE' END;
      ELSE
        v_action := 'UPDATE';
      END IF;
    EXCEPTION WHEN OTHERS THEN v_action := 'UPDATE'; END;
    BEGIN v_modified_by := NEW.modified_by; EXCEPTION WHEN OTHERS THEN v_modified_by := NULL; END;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'DELETE';
    BEGIN v_modified_by := OLD.modified_by; EXCEPTION WHEN OTHERS THEN v_modified_by := NULL; END;
  END IF;

  -- Resolve: try user_code first, then UUID
  IF v_modified_by IS NOT NULL AND v_modified_by <> '' THEN
    SELECT id, full_name INTO v_user_id, v_user_name
    FROM public.profiles WHERE user_code = v_modified_by LIMIT 1;
    IF v_user_id IS NOT NULL THEN
      v_user_code := v_modified_by;
    ELSE
      BEGIN
        v_user_id := v_modified_by::uuid;
        SELECT user_code, full_name INTO v_user_code, v_user_name FROM public.profiles WHERE id = v_user_id;
      EXCEPTION WHEN OTHERS THEN v_user_id := NULL;
      END;
    END IF;
  END IF;

  IF v_user_id IS NULL THEN
    BEGIN
      v_user_id := auth.uid();
      IF v_user_id IS NOT NULL THEN
        SELECT user_code, full_name INTO v_user_code, v_user_name FROM public.profiles WHERE id = v_user_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  INSERT INTO public.system_audit_trail (
    user_id, user_name, action, entity_type, entity_id, module,
    before_value, after_value, severity, timestamp
  ) VALUES (
    v_user_id,
    COALESCE(v_user_name, v_user_code, v_modified_by, 'SYSTEM'),
    v_action, 'C3Configuration', v_record_id, 'C3 Configuration',
    CASE WHEN OLD IS NOT NULL THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN NEW IS NOT NULL THEN to_jsonb(NEW) ELSE NULL END,
    'info', NOW()
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'Error in trg_c3_config_to_system_audit for %: % %', TG_TABLE_NAME, SQLERRM, SQLSTATE;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_comm_hub_certification_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_CERTIFICATION_DELETE_FORBIDDEN';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.governance_record_id IS DISTINCT FROM OLD.governance_record_id
       OR NEW.entity_type IS DISTINCT FROM OLD.entity_type
       OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
       OR NEW.entity_version IS DISTINCT FROM OLD.entity_version
       OR NEW.certification_kind IS DISTINCT FROM OLD.certification_kind
       OR NEW.result IS DISTINCT FROM OLD.result
       OR NEW.dependency_manifest::text IS DISTINCT FROM OLD.dependency_manifest::text
       OR NEW.dependency_hash IS DISTINCT FROM OLD.dependency_hash
       OR NEW.renderer_version IS DISTINCT FROM OLD.renderer_version
       OR NEW.template_purpose IS DISTINCT FROM OLD.template_purpose
       OR NEW.channel IS DISTINCT FROM OLD.channel
       OR NEW.template_type IS DISTINCT FROM OLD.template_type
       OR NEW.validation_findings::text IS DISTINCT FROM OLD.validation_findings::text
       OR NEW.error_count IS DISTINCT FROM OLD.error_count
       OR NEW.warning_count IS DISTINCT FROM OLD.warning_count
       OR NEW.certified_by IS DISTINCT FROM OLD.certified_by
       OR NEW.certified_at IS DISTINCT FROM OLD.certified_at
       OR NEW.certification_reason IS DISTINCT FROM OLD.certification_reason
       OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id
       OR NEW.certification_layer IS DISTINCT FROM OLD.certification_layer
       OR NEW.producer_function IS DISTINCT FROM OLD.producer_function
       OR NEW.producer_version IS DISTINCT FROM OLD.producer_version
       OR NEW.diagnostic_function IS DISTINCT FROM OLD.diagnostic_function
       OR NEW.diagnostic_version IS DISTINCT FROM OLD.diagnostic_version
       OR NEW.canonicalization_version IS DISTINCT FROM OLD.canonicalization_version
       OR NEW.hash_algorithm IS DISTINCT FROM OLD.hash_algorithm
       OR NEW.manifest_hash IS DISTINCT FROM OLD.manifest_hash
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_CERTIFICATION_IMMUTABLE'; END IF;
    IF NEW.provenance_state IS DISTINCT FROM OLD.provenance_state
       AND NOT (OLD.provenance_state = 'AUTHORITATIVE' AND NEW.provenance_state = 'REVOKED')
    THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_CERTIFICATION_PROVENANCE_LOCKED'; END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.trg_comm_hub_governance_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_via_core text := current_setting('comm_hub.governance_transition', true);
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_GOVERNANCE_DELETE_FORBIDDEN';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.governance_status NOT IN ('DRAFT','DISCOVERED','NOT_CERTIFIED','BLOCKED')
       AND COALESCE(v_via_core,'') <> 'on' THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_GOVERNANCE_INSERT_MUST_START_LOW';
    END IF;
    RETURN NEW;
  END IF;
  IF COALESCE(v_via_core,'') <> 'on' THEN
    IF OLD.governance_status IN ('ACTIVE','ENFORCED','RETIRED') THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_GOVERNANCE_ACTIVE_LOCKED';
    END IF;
    IF NEW.governance_status IS DISTINCT FROM OLD.governance_status
       OR NEW.governance_version IS DISTINCT FROM OLD.governance_version THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='COMM_HUB_GOVERNANCE_DIRECT_LIFECYCLE_WRITE_FORBIDDEN';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.trg_comm_hub_invalidate_dependency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_type text := TG_ARGV[0]; v_category text := TG_ARGV[1]; v_id uuid;
BEGIN
  v_id := COALESCE(NEW.id, OLD.id);
  PERFORM public.mark_comm_hub_certifications_possibly_stale(v_type, v_id, v_category);
  IF v_type = 'CORE_TEMPLATE_SECTION' THEN
    PERFORM public.mark_comm_hub_certifications_possibly_stale(
      'TEMPLATE_VERSION', COALESCE(NEW.version_id, OLD.version_id), v_category);
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$;
CREATE OR REPLACE FUNCTION public.trg_ia_action_status_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trigger_config record;
  v_event_code text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_event_code := 'ACTION_ASSIGNED';
  ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    CASE NEW.status
      WHEN 'Completed' THEN v_event_code := 'ACTION_COMPLETED';
      WHEN 'Overdue' THEN v_event_code := 'ACTION_OVERDUE';
      ELSE v_event_code := NULL;
    END CASE;
  ELSE
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  IF v_event_code IS NOT NULL THEN
    SELECT * INTO v_trigger_config FROM ia_notification_triggers WHERE event_code = v_event_code AND is_enabled = true LIMIT 1;
    
    IF FOUND AND v_trigger_config.auto_fire THEN
      IF NEW.responsible_person IS NOT NULL THEN
        INSERT INTO ia_auto_notification_log (event_code, engagement_id, entity_type, entity_id, recipient_user_id, subject, channel, delivery_status)
        VALUES (v_event_code, NEW.engagement_id, 'action', NEW.id, NEW.responsible_person,
                v_event_code || ': ' || COALESCE(NEW.action_description, NEW.id::text), 'in_app', 'Queued');
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_ia_engagement_status_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trigger_config record;
  v_event_code text;
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    CASE NEW.status
      WHEN 'In Progress' THEN v_event_code := 'ENGAGEMENT_STARTED';
      WHEN 'Completed' THEN v_event_code := 'ENGAGEMENT_COMPLETED';
      ELSE v_event_code := NULL;
    END CASE;
    
    IF v_event_code IS NOT NULL THEN
      SELECT * INTO v_trigger_config FROM ia_notification_triggers WHERE event_code = v_event_code AND is_enabled = true LIMIT 1;
      
      IF FOUND AND v_trigger_config.auto_fire THEN
        IF v_trigger_config.notify_team_lead AND NEW.lead_auditor_id IS NOT NULL THEN
          INSERT INTO ia_auto_notification_log (event_code, engagement_id, entity_type, entity_id, recipient_user_id, subject, channel, delivery_status)
          VALUES (v_event_code, NEW.id, 'engagement', NEW.id, NEW.lead_auditor_id,
                  v_event_code || ': ' || COALESCE(NEW.engagement_name, NEW.id::text), 'in_app', 'Queued');
        END IF;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_ia_finding_created_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trigger_config record;
  v_lead_id uuid;
BEGIN
  SELECT * INTO v_trigger_config FROM ia_notification_triggers WHERE event_code = 'FINDING_CREATED' AND is_enabled = true LIMIT 1;
  
  IF FOUND AND v_trigger_config.auto_fire THEN
    SELECT lead_auditor_id INTO v_lead_id FROM ia_audit_engagements WHERE id = NEW.engagement_id;
    
    IF v_trigger_config.notify_team_lead AND v_lead_id IS NOT NULL THEN
      INSERT INTO ia_auto_notification_log (event_code, engagement_id, entity_type, entity_id, recipient_user_id, subject, channel, delivery_status)
      VALUES ('FINDING_CREATED', NEW.engagement_id, 'finding', NEW.id, v_lead_id,
              'New Finding: ' || COALESCE(NEW.title, NEW.id::text), 'in_app', 'Queued');
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_appeal_rollup()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new varchar(30);
  v_ord uuid := COALESCE(NEW.order_id, OLD.order_id);
BEGIN
  IF v_ord IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT status INTO v_new FROM public.lg_appeal
    WHERE order_id = v_ord
    ORDER BY created_at DESC LIMIT 1;
  IF v_new IS NULL THEN v_new := 'NONE'; END IF;
  UPDATE public.lg_order
     SET appeal_status = v_new,
         status = CASE
           WHEN v_new IN ('FILED','ACCEPTED','HEARING_SCHEDULED','UNDER_REVIEW','DECISION_RESERVED')
             AND status NOT IN ('CLOSED','CANCELLED')
             THEN 'UNDER_APPEAL'
           ELSE status
         END,
         updated_at = now()
   WHERE id = v_ord;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_assignment_audit_fn()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_changed JSONB := '{}'::jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    SELECT jsonb_object_agg(key, jsonb_build_object('before', to_jsonb(OLD) -> key, 'after', to_jsonb(NEW) -> key))
      INTO v_changed
      FROM jsonb_object_keys(to_jsonb(NEW)) AS key
     WHERE to_jsonb(OLD) -> key IS DISTINCT FROM to_jsonb(NEW) -> key
       AND key NOT IN ('updated_at');
    IF v_changed IS NOT NULL AND v_changed <> '{}'::jsonb THEN
      INSERT INTO public.lg_recovery_assignment_audit(assignment_id, action, changed_fields, before_json, after_json, actor_code)
      VALUES (NEW.id, 'UPDATE', v_changed, to_jsonb(OLD), to_jsonb(NEW), NEW.updated_by);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO public.lg_recovery_assignment_audit(assignment_id, action, after_json, actor_code)
    VALUES (NEW.id, 'INSERT', to_jsonb(NEW), NEW.created_by);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.lg_recovery_assignment_audit(assignment_id, action, before_json, actor_code)
    VALUES (OLD.id, 'DELETE', to_jsonb(OLD), OLD.updated_by);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_assignment_health_fn()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_days_since_action INT;
  v_outstanding_pct NUMERIC := 0;
BEGIN
  IF NEW.total_assessed > 0 THEN
    v_outstanding_pct := (NEW.total_outstanding / NEW.total_assessed) * 100;
  END IF;
  v_days_since_action := COALESCE(EXTRACT(DAY FROM (now() - NEW.last_action_at))::int, 999);

  IF NEW.status IN ('COMPLETED','CLOSED') THEN
    NEW.health := 'HEALTHY';
  ELSIF v_outstanding_pct > 80 AND v_days_since_action > 30 THEN
    NEW.health := 'CRITICAL';
  ELSIF v_outstanding_pct > 50 AND v_days_since_action > 14 THEN
    NEW.health := 'AT_RISK';
  ELSIF NEW.next_action_due_at IS NOT NULL AND NEW.next_action_due_at < now() THEN
    NEW.health := 'AT_RISK';
  ELSE
    NEW.health := 'HEALTHY';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_assignment_rollup_fn()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.lg_recompute_assignment_rollup(OLD.assignment_id);
    RETURN OLD;
  ELSE
    PERFORM public.lg_recompute_assignment_rollup(NEW.assignment_id);
    RETURN NEW;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_enforcement_rollup()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new varchar(30);
  v_ord uuid := COALESCE(NEW.order_id, OLD.order_id);
BEGIN
  IF v_ord IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT status INTO v_new FROM public.lg_enforcement_action
    WHERE order_id = v_ord
    ORDER BY created_at DESC LIMIT 1;
  IF v_new IS NULL THEN v_new := 'NONE'; END IF;
  UPDATE public.lg_order
     SET enforcement_status = v_new,
         status = CASE
           WHEN v_new = 'EXECUTED' AND status NOT IN ('CLOSED','CANCELLED') THEN 'ENFORCED'
           ELSE status
         END,
         updated_at = now()
   WHERE id = v_ord;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_hearing_adj_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.lg_hearing
    SET adjournment_count = COALESCE(adjournment_count,0) + 1,
        updated_at = now()
    WHERE id = NEW.lg_hearing_id;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trg_lg_hearing_auto_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_title text;
  v_priority varchar := 'NORMAL';
  v_due date;
BEGIN
  IF (TG_OP = 'UPDATE') THEN
    -- Adjourned: create follow-up
    IF NEW.status = 'ADJOURNED' AND COALESCE(OLD.status, '') <> 'ADJOURNED' THEN
      v_title := 'Follow up on adjourned hearing ' || COALESCE(NEW.hearing_number, NEW.id::text);
      v_due := COALESCE(NEW.next_hearing_date, (CURRENT_DATE + INTERVAL '7 days')::date);
      INSERT INTO public.lg_case_task (
        lg_case_id, title, description, priority_code, due_date, status, created_by, source_type, source_id
      ) VALUES (
        NEW.lg_case_id,
        v_title,
        'Auto-created by hearing adjournment. Reason: ' || COALESCE(NEW.adjournment_reason, 'N/A'),
        'HIGH', v_due, 'OPEN', COALESCE(NEW.created_by, 'SYSTEM'),
        'HEARING_ADJOURNMENT', NEW.id
      );
    END IF;
    -- Judgment reserved: reminder
    IF NEW.outcome_code = 'JUDGMENT_RESERVED' AND COALESCE(OLD.outcome_code, '') <> 'JUDGMENT_RESERVED' THEN
      INSERT INTO public.lg_case_task (
        lg_case_id, title, description, priority_code, due_date, status, created_by, source_type, source_id
      ) VALUES (
        NEW.lg_case_id,
        'Reminder: judgment reserved for hearing ' || COALESCE(NEW.hearing_number, NEW.id::text),
        'Auto-created by JUDGMENT_RESERVED outcome. Follow up with court for judgment date.',
        'HIGH', (CURRENT_DATE + INTERVAL '14 days')::date, 'OPEN', COALESCE(NEW.created_by, 'SYSTEM'),
        'HEARING_JUDGMENT_RESERVED', NEW.id
      );
    END IF;
    -- Order issued: recovery follow-up
    IF NEW.outcome_code = 'ORDER_ISSUED' AND COALESCE(OLD.outcome_code, '') <> 'ORDER_ISSUED' THEN
      INSERT INTO public.lg_case_task (
        lg_case_id, title, description, priority_code, due_date, status, created_by, source_type, source_id
      ) VALUES (
        NEW.lg_case_id,
        'Recovery follow-up for order issued at hearing ' || COALESCE(NEW.hearing_number, NEW.id::text),
        'Auto-created by ORDER_ISSUED outcome. Ensure court order recorded and recovery scheduled.',
        'HIGH', (CURRENT_DATE + INTERVAL '3 days')::date, 'OPEN', COALESCE(NEW.created_by, 'SYSTEM'),
        'HEARING_ORDER_ISSUED', NEW.id
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
