CREATE OR REPLACE FUNCTION public.update_comm_hub_registry_token_metadata(p_module_code text, p_event_code text, p_channel text, p_token_metadata jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_keys jsonb;
  v_old jsonb;
  v_new jsonb;
  v_row public.communication_hub_module_event_registry%ROWTYPE;
BEGIN
  PERFORM public._chub_assert_admin();
  IF p_reason IS NULL OR length(btrim(p_reason)) < 4 THEN
    RAISE EXCEPTION 'reason required';
  END IF;
  IF jsonb_typeof(p_token_metadata) <> 'array' THEN
    RAISE EXCEPTION 'token_metadata must be an array';
  END IF;

  SELECT jsonb_agg(elem->>'key') INTO v_keys
  FROM jsonb_array_elements(p_token_metadata) elem
  WHERE elem->>'key' IS NOT NULL;

  SELECT to_jsonb(r.*) INTO v_old
  FROM public.communication_hub_module_event_registry r
  WHERE r.module_code = p_module_code AND r.event_code = p_event_code AND r.channel = p_channel;

  UPDATE public.communication_hub_module_event_registry
     SET token_metadata = p_token_metadata,
         required_tokens = COALESCE(v_keys, '[]'::jsonb)
   WHERE module_code = p_module_code AND event_code = p_event_code AND channel = p_channel
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'registry row not found for %/%/%', p_module_code, p_event_code, p_channel;
  END IF;

  v_new := to_jsonb(v_row);

  INSERT INTO public.communication_hub_control_audit(setting_key, old_value, new_value, reason, changed_by, source)
  VALUES ('registry_tokens.' || p_module_code || '.' || p_event_code, v_old, v_new, p_reason, auth.uid(), 'event-template-onboarding-wizard');

  RETURN v_new;
END;
$function$;
CREATE OR REPLACE FUNCTION public.update_historical_risk_on_finding_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dept_id UUID;
  v_func RECORD;
BEGIN
  -- Only act when status changes to 'Closed'
  IF NEW.status = 'Closed' AND (OLD.status IS NULL OR OLD.status <> 'Closed') THEN
    -- Get department_id from the finding
    v_dept_id := NEW.department_id;
    IF v_dept_id IS NULL AND NEW.department_audit_id IS NOT NULL THEN
      SELECT department_id INTO v_dept_id FROM ia_department_audits WHERE id = NEW.department_audit_id;
    END IF;
    
    IF v_dept_id IS NOT NULL THEN
      -- Update all functions in this department
      FOR v_func IN SELECT id FROM ia_department_functions WHERE department_id = v_dept_id
      LOOP
        UPDATE ia_department_functions
        SET historical_risk_adjustment = calculate_historical_risk_adjustment(v_func.id)
        WHERE id = v_func.id;
      END LOOP;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$function$;
