DO $do$ BEGIN ALTER TABLE public.omni_comms_event_contract ADD CONSTRAINT omni_comms_event_contract_lifecycle_fields_chk CHECK (
CASE status
    WHEN 'draft'::text THEN ((published_at IS NULL) AND (published_by IS NULL) AND (retired_at IS NULL) AND (retired_by IS NULL))
    WHEN 'published'::text THEN ((published_at IS NOT NULL) AND (published_by IS NOT NULL) AND (checksum IS NOT NULL) AND (retired_at IS NULL) AND (retired_by IS NULL))
    WHEN 'retired'::text THEN ((published_at IS NOT NULL) AND (published_by IS NOT NULL) AND (retired_at IS NOT NULL) AND (retired_by IS NOT NULL) AND (checksum IS NOT NULL))
    ELSE NULL::boolean
END);
EXCEPTION WHEN duplicate_object THEN NULL WHEN duplicate_table THEN NULL; END $do$;
