    WHEN 'active'::text THEN ((activated_at IS NOT NULL) AND (activated_by IS NOT NULL) AND (retired_at IS NULL) AND (retired_by IS NULL) AND (retirement_reason IS NULL))
    WHEN 'retired'::text THEN ((retired_at IS NOT NULL) AND (retired_by IS NOT NULL) AND (retirement_reason IS NOT NULL) AND (btrim(retirement_reason) <> ''::text))
    ELSE NULL::boolean
END);
