    WHEN 'draft'::text THEN ((checksum IS NULL) AND (approved_at IS NULL) AND (approved_by IS NULL) AND (published_at IS NULL) AND (published_by IS NULL) AND (retired_at IS NULL) AND (retired_by IS NULL) AND (retirement_reason IS NULL))
    WHEN 'approved'::text THEN ((checksum IS NOT NULL) AND (approved_at IS NOT NULL) AND (approved_by IS NOT NULL) AND (published_at IS NULL) AND (published_by IS NULL) AND (retired_at IS NULL) AND (retired_by IS NULL) AND (retirement_reason IS NULL))
    WHEN 'published'::text THEN ((checksum IS NOT NULL) AND (approved_at IS NOT NULL) AND (approved_by IS NOT NULL) AND (published_at IS NOT NULL) AND (published_by IS NOT NULL) AND (retired_at IS NULL) AND (retired_by IS NULL) AND (retirement_reason IS NULL))
    WHEN 'retired'::text THEN ((checksum IS NOT NULL) AND (approved_at IS NOT NULL) AND (approved_by IS NOT NULL) AND (retired_at IS NOT NULL) AND (retired_by IS NOT NULL) AND (retirement_reason IS NOT NULL) AND (btrim(retirement_reason) <> ''::text))
