CREATE UNIQUE INDEX IF NOT EXISTS ux_ce_violations_active_auto_dedupe ON public.ce_violations USING btree (employer_id, violation_type_id, COALESCE("left"((period_from)::text, 7), ''::text)) WHERE ((is_deleted = false) AND ((status)::text = ANY ((ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'ESCALATED'::character varying, 'UNDER_REVIEW'::character varying])::text[])) AND ((source_type)::text = ANY ((ARRAY['AUTOMATED'::character varying, 'DETECTION_RULE'::character varying])::text[])) AND (employer_id IS NOT NULL) AND (violation_type_id IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS ux_chre_active_idempotency ON public.communication_hub_revalidation_execution USING btree (idempotency_key) WHERE (state = ANY (ARRAY['READY_FOR_PROVIDER'::text, 'PROVIDER_INVOKED'::text, 'RECONCILING'::text]));
CREATE UNIQUE INDEX IF NOT EXISTS ux_chre_active_per_cycle_version ON public.communication_hub_revalidation_execution USING btree (cycle_id, preparation_version) WHERE (state = ANY (ARRAY['PREPARING'::text, 'READY_FOR_PROVIDER'::text, 'PROVIDER_INVOKED'::text, 'RECONCILING'::text]));
CREATE UNIQUE INDEX IF NOT EXISTS ux_chre_provider_call_per_cycle ON public.communication_hub_revalidation_execution USING btree (cycle_id) WHERE (provider_call_attempted = true);
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_hub_cert_active_authoritative ON public.comm_hub_certification USING btree (certification_layer, certification_kind, entity_type, entity_id, COALESCE(channel, ''::text)) WHERE ((is_stale = false) AND (superseded_by IS NULL) AND (provenance_state = 'AUTHORITATIVE'::text));
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_hub_sender_readiness_current ON public.comm_hub_sender_readiness USING btree (sender_profile_id, sender_version, readiness_kind) WHERE (is_stale = false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_media_asset_code ON public.comm_media_asset USING btree (asset_code) WHERE (asset_code IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_media_asset_sys_default ON public.comm_media_asset USING btree (category) WHERE (is_system_default = true);
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_msg_targeted_execution_action_channel ON public.communication_message USING btree (controlled_live_execution_id, controlled_action, channel) WHERE (targeted_dispatch_only = true);
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_msg_targeted_grant ON public.communication_message USING btree (controlled_live_grant_id) WHERE (targeted_dispatch_only = true);
CREATE UNIQUE INDEX IF NOT EXISTS ux_comm_request_targeted_execution_action ON public.communication_request USING btree (controlled_live_execution_id, controlled_action) WHERE (targeted_dispatch_only = true);
CREATE UNIQUE INDEX IF NOT EXISTS ux_core_department_profile_department_id ON public.core_department_profile USING btree (department_id) WHERE (department_id IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ux_core_department_profile_org_dept ON public.core_department_profile USING btree (organization_id, department_code);
CREATE UNIQUE INDEX IF NOT EXISTS ux_core_dms_module_mapping ON public.core_dms_module_mapping USING btree (module_code, entity_type, document_category_code, document_type_code, COALESCE(stage_code, ''::text));
CREATE UNIQUE INDEX IF NOT EXISTS ux_core_number_sequence_active ON public.core_number_sequence USING btree (module_code, entity_type, country_code) WHERE (is_active = true);
CREATE INDEX IF NOT EXISTS workflow_step_actions_code_idx ON public.workflow_step_actions USING btree (step_id, action_code);
CREATE INDEX IF NOT EXISTS workflow_steps_from_status_idx ON public.workflow_steps USING btree (workflow_id, from_status);

-- ========================================================================
-- VIEWS AND MATERIALIZED VIEWS (dependency ordered)
-- ========================================================================
CREATE OR REPLACE VIEW public.bn_country_legal_ref AS
 SELECT id,
    country_code,
    ref_code,
    short_title AS ref_title,
    section AS ref_section,
    ref_url,
    applicable_products,
    effective_from,
    effective_to,
    version_number,
    supersedes_id,
    notes,
    is_active,
    created_by AS entered_by,
    created_at AS entered_at,
    created_by,
    created_at,
    updated_by,
    updated_at
   FROM core_legal_reference;
CREATE OR REPLACE VIEW public.bn_legal_reference AS
 SELECT id,
    country_code,
    ref_code,
    short_title,
    act_name,
    chapter,
    section,
    subsection,
    regulation,
    full_reference_text,
    ref_url,
    effective_from,
    effective_to,
    status,
    version_number,
    supersedes_id,
    tags,
    NULL::text[] AS applicable_products,
    notes,
    is_active,
    legacy_id,
    created_by,
    created_at,
    updated_by,
    updated_at
   FROM core_legal_reference;
CREATE OR REPLACE VIEW public.bn_reference_group AS
 SELECT id,
    group_code,
    group_name,
    module_code,
    description,
    is_system,
    is_active,
    created_by,
    created_at,
    updated_by,
    updated_at,
    module_name,
    group_category,
    owner_role_code,
    manage_permission_code,
    view_permission_code,
    is_system_group,
    sort_order
   FROM core_reference_group;
CREATE OR REPLACE VIEW public.bn_reference_value AS
 SELECT id,
    group_id,
    value_code,
    value_label,
    description,
    sort_order,
    is_default,
    is_system,
    is_active,
    effective_from,
    effective_to,
    metadata_json,
    created_by,
    created_at,
    updated_by,
    updated_at,
    module_code,
    status,
    value_description
   FROM core_reference_value;
CREATE OR REPLACE VIEW public.bn_rule_catalogue_group_usage AS
 SELECT i.catalogue_rule_id,
    count(*)::integer AS group_count,
    array_agg(DISTINCT g.group_code ORDER BY g.group_code) AS group_codes,
    array_agg(DISTINCT i.rule_group_id) AS group_ids
   FROM bn_rule_group_item i
     JOIN bn_rule_group g ON g.id = i.rule_group_id
  GROUP BY i.catalogue_rule_id;
CREATE OR REPLACE VIEW public.ce_allowed_status_transitions AS
 SELECT split_part(ws.step_name, ':'::text, 1) AS entity_type,
    ws.from_status,
    wsa.action_code,
    wsa.action_name AS action_label,
    wsa.result_status AS to_status,
    wsa.display_order,
    ws.workflow_id
   FROM workflow_steps ws
     JOIN workflow_step_actions wsa ON wsa.step_id = ws.id
     JOIN workflow_definitions wd ON wd.id = ws.workflow_id
  WHERE wd.name = 'CE Status — Trivial Transitions'::text AND ws.from_status IS NOT NULL AND wsa.action_code IS NOT NULL;
CREATE OR REPLACE VIEW public.ce_employer_contact_view AS
 SELECT em.regno AS employer_id,
    em.name AS employer_name,
    em.status AS employer_status,
    em.phone AS master_phone,
    em.fax AS master_fax,
    em.email AS master_email,
    em.maddr1 AS master_mail_address_1,
    em.maddr2 AS master_mail_address_2,
    em.hq_addr1 AS master_hq_address_1,
    em.hq_addr2 AS master_hq_address_2,
    em.mobile AS master_mobile,
    cp.id AS preference_id,
    cp.preferred_channel,
    cp.notice_email,
    cp.notice_phone,
    cp.notice_fax,
    cp.notice_address_line1,
    cp.notice_address_line2,
    cp.compliance_contact_name,
    cp.compliance_contact_title,
    cp.compliance_contact_phone,
    cp.compliance_contact_email,
    cp.authorized_contact_name,
    cp.authorized_contact_email,
    cp.authorized_contact_phone,
    cp.legal_representative_name,
    cp.legal_representative_firm,
    cp.legal_representative_phone,
    cp.legal_representative_email,
    cp.physical_delivery_address_1,
    cp.physical_delivery_address_2,
    cp.physical_delivery_parish,
    cp.consent_given,
    cp.consent_given_at,
    cp.opt_out_physical,
    cp.opt_out_email,
    COALESCE(cp.notice_email, em.email) AS effective_email,
    COALESCE(cp.notice_phone, em.phone) AS effective_phone,
    COALESCE(cp.notice_address_line1, em.maddr1) AS effective_address_1,
    COALESCE(cp.notice_address_line2, em.maddr2) AS effective_address_2,
    COALESCE(cp.preferred_channel, 'email'::character varying) AS effective_channel
   FROM er_master em
     LEFT JOIN ce_employer_contact_preferences cp ON cp.employer_id::text = em.regno::text AND cp.is_active = true;
CREATE OR REPLACE VIEW public.ce_employer_group_summary_view AS
 SELECT g.id AS group_id,
    g.group_name,
    g.group_code,
    g.territory,
    g.sector,
    g.is_active,
    count(DISTINCT gm.employer_id) AS member_count,
    COALESCE(sum(cs.current_arrears_amount), 0::numeric) AS total_group_arrears,
    COALESCE(sum(cs.current_penalty_amount), 0::numeric) AS total_group_penalties,
    COALESCE(sum(cs.active_violation_count), 0::bigint) AS total_group_violations,
    COALESCE(sum(cs.active_case_count), 0::bigint) AS total_group_cases,
    max(rp.total_score) AS max_risk_score,
    min(rp.total_score) AS min_risk_score,
    round(avg(rp.total_score), 1) AS avg_risk_score
   FROM ce_employer_groups g
     LEFT JOIN ce_employer_group_membership gm ON gm.group_id = g.id AND gm.is_active = true
     LEFT JOIN ce_employer_compliance_status cs ON cs.employer_id::text = gm.employer_id
     LEFT JOIN ce_risk_profiles rp ON rp.employer_id::text = gm.employer_id
  GROUP BY g.id, g.group_name, g.group_code, g.territory, g.sector, g.is_active;
CREATE OR REPLACE VIEW public.ce_employer_hierarchy_view AS
 SELECT r.id AS relationship_id,
    r.relationship_type,
    r.effective_from,
    r.effective_to,
    r.is_active AS relationship_active,
    r.verification_status,
    r.parent_employer_id AS source_employer_id,
    src.name AS source_employer_name,
    src.status AS source_employer_status,
    src.sector_code AS source_sector,
    src.office_code AS source_territory,
    r.child_employer_id AS target_employer_id,
    tgt.name AS target_employer_name,
    tgt.status AS target_employer_status,
    tgt.sector_code AS target_sector,
    tgt.office_code AS target_territory,
    src_cs.overall_compliance_status AS source_compliance_status,
    src_cs.current_arrears_amount AS source_arrears,
    src_cs.active_violation_count AS source_violations,
    src_cs.active_case_count AS source_cases,
    tgt_cs.overall_compliance_status AS target_compliance_status,
    tgt_cs.current_arrears_amount AS target_arrears,
    tgt_cs.active_violation_count AS target_violations,
    tgt_cs.active_case_count AS target_cases,
    src_rp.total_score AS source_risk_score,
    src_rp.risk_band AS source_risk_band,
    tgt_rp.total_score AS target_risk_score,
    tgt_rp.risk_band AS target_risk_band,
    gm_src.group_id AS source_group_id,
    g.group_name AS source_group_name
   FROM ce_employer_relationships r
     LEFT JOIN er_master src ON src.regno::text = r.parent_employer_id::text
     LEFT JOIN er_master tgt ON tgt.regno::text = r.child_employer_id::text
     LEFT JOIN ce_employer_compliance_status src_cs ON src_cs.employer_id::text = r.parent_employer_id::text
     LEFT JOIN ce_employer_compliance_status tgt_cs ON tgt_cs.employer_id::text = r.child_employer_id::text
     LEFT JOIN ce_risk_profiles src_rp ON src_rp.employer_id::text = r.parent_employer_id::text
     LEFT JOIN ce_risk_profiles tgt_rp ON tgt_rp.employer_id::text = r.child_employer_id::text
     LEFT JOIN ce_employer_group_membership gm_src ON gm_src.employer_id = r.parent_employer_id::text AND gm_src.is_active = true
     LEFT JOIN ce_employer_groups g ON g.id = gm_src.group_id;
CREATE OR REPLACE VIEW public.ce_employer_profile_view AS
 SELECT em.regno AS employer_id,
    em.name AS employer_name,
    em.status AS master_status,
    em.sector_code,
    em.village_code AS territory,
    em.office_code,
    em.inspector_code,
    em.phone,
    em.email,
    em.hq_addr1,
    em.hq_addr2,
    em.registration_date,
    em.trade_name,
    em.ownership_code,
    em.males_employed,
    em.females_employed,
    cs.compliance_status,
    cs.filing_status,
    cs.payment_status,
    cs.overall_compliance_status,
    cs.current_arrears_amount,
    cs.current_penalty_amount,
    cs.last_filing_period,
    cs.last_payment_date,
    cs.active_case_count,
    cs.active_violation_count,
    cs.active_arrangement_count,
    cs.effective_from AS compliance_effective_from,
    cs.assigned_officer_id,
    cs.review_due_date,
    cs.last_computed_at,
    cs.computed_by,
    rp.total_score AS risk_score,
    COALESCE(rp.override_band, rp.risk_band) AS risk_band,
    rp.scoring_version,
    rp.arrears_score,
    rp.violation_score,
    rp.filing_score,
    rp.payment_behavior_score,
    rp.legal_history_score,
    rp.enforcement_risk_score,
    rp.last_calculated_at AS risk_last_calculated,
    rp.next_review_date AS risk_next_review,
    rp.assessed_by AS risk_assessed_by,
    COALESCE(la.total_debits, 0::numeric) AS total_debits,
    COALESCE(la.total_credits, 0::numeric) AS total_credits,
    COALESCE(la.total_debits, 0::numeric) - COALESCE(la.total_credits, 0::numeric) AS outstanding_balance,
    COALESCE(fa.active_flags, 0::bigint) AS active_flags_count,
    fa.critical_flags,
    COALESCE(ra.related_employers, 0::bigint) AS related_employers_count
   FROM er_master em
     LEFT JOIN ce_employer_compliance_status cs ON cs.employer_id::text = em.regno::text AND cs.effective_to IS NULL
     LEFT JOIN ce_risk_profiles rp ON rp.employer_id::text = em.regno::text
     LEFT JOIN LATERAL ( SELECT sum(COALESCE(l.debit_amount, 0::numeric)) AS total_debits,
            sum(COALESCE(l.credit_amount, 0::numeric)) AS total_credits
           FROM ce_employer_financial_ledger l
          WHERE l.employer_id::text = em.regno::text AND l.reversal_of_id IS NULL) la ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS active_flags,
            count(*) FILTER (WHERE f.severity::text = 'critical'::text) AS critical_flags
           FROM ce_employer_compliance_flags f
          WHERE f.employer_id::text = em.regno::text AND f.is_active = true) fa ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS related_employers
           FROM ce_employer_relationships r
          WHERE (r.parent_employer_id::text = em.regno::text OR r.child_employer_id::text = em.regno::text) AND r.is_active = true) ra ON true;
CREATE OR REPLACE VIEW public.ce_inspector_profiles AS
 SELECT ci.id AS inspector_id,
    ci.inspector_code,
    ci.status,
    ci.is_active,
    ci.status_effective_from,
    ci.status_effective_to,
    ci.max_caseload,
    ci.can_handle_review,
    ci.can_handle_legal,
    ci.supervisor_id,
    ci.primary_zone_id,
    ci.office_code,
    ci.legacy_inspector_code,
    ci.transferred_to_zone_id,
    ci.transferred_from_zone_id,
    p.id AS profile_id,
    p.first_name,
    p.last_name,
    p.email,
    p.user_code,
    p.designation_id,
    d.name AS designation_name,
    cz.zone_name AS primary_zone_name,
    sup.inspector_code AS supervisor_code,
    sp.first_name AS supervisor_first_name,
    sp.last_name AS supervisor_last_name,
    ti.insp_name AS legacy_inspector_name
   FROM ce_inspectors ci
     LEFT JOIN profiles p ON p.id = ci.profile_id
     LEFT JOIN tb_designations d ON d.id = p.designation_id
     LEFT JOIN ce_zones cz ON cz.id = ci.primary_zone_id
     LEFT JOIN ce_inspectors sup ON sup.id = ci.supervisor_id
     LEFT JOIN profiles sp ON sp.id = sup.profile_id
     LEFT JOIN tb_inspector ti ON ti.code::text = ci.legacy_inspector_code::text;
CREATE OR REPLACE VIEW public.ce_ledger_reversals_v AS
 SELECT r.id AS reversal_entry_id,
    r.employer_id,
    r.employer_name,
    r.entry_type AS reversal_entry_type,
    r.fund_type,
    r.period,
    r.debit_amount AS reversal_debit,
    r.credit_amount AS reversal_credit,
    r.description AS reversal_description,
    r.reversal_reason,
    r.posted_by AS reversed_by,
    r.posted_at AS reversed_at,
    o.id AS original_entry_id,
    o.entry_type AS original_entry_type,
    o.debit_amount AS original_debit,
    o.credit_amount AS original_credit,
    o.description AS original_description,
    o.posted_by AS original_posted_by,
    o.posted_at AS original_posted_at
   FROM ce_employer_financial_ledger r
     JOIN ce_employer_financial_ledger o ON r.reversal_of_id = o.id
  WHERE r.reversal_of_id IS NOT NULL;
CREATE OR REPLACE VIEW public.ce_v_arrangement_health AS
 SELECT pa.id AS arrangement_id,
    pa.employer_id,
    regexp_replace(pa.employer_id::text, '^EMP-'::text, ''::text) AS regno,
    pa.employer_name,
    pa.status,
    pa.total_debt,
    pa.total_paid,
    pa.installments_paid,
    pa.missed_payments,
    pa.max_missed_before_breach,
    pa.breach_detected,
    pa.next_due_date,
    COALESCE(ub.unresolved_breach_count, 0::bigint) AS unresolved_breach_count,
        CASE
            WHEN pa.status::text = 'Breached'::text THEN 'BREACHED'::text
            WHEN pa.breach_detected = true THEN 'AT_RISK'::text
            WHEN pa.missed_payments >= COALESCE(pa.max_missed_before_breach, 3) THEN 'AT_RISK'::text
            WHEN pa.missed_payments > 0 THEN 'WARNING'::text
            WHEN pa.status::text = 'Active'::text THEN 'HEALTHY'::text
            ELSE 'INACTIVE'::text
        END AS health_status
   FROM ce_payment_arrangements pa
     LEFT JOIN ( SELECT ce_arrangement_breaches.arrangement_id,
            count(*) AS unresolved_breach_count
           FROM ce_arrangement_breaches
          WHERE ce_arrangement_breaches.resolved_at IS NULL
          GROUP BY ce_arrangement_breaches.arrangement_id) ub ON ub.arrangement_id = pa.id;
CREATE OR REPLACE VIEW public.ce_v_c3_aggregate_stats AS
 SELECT count(*) FILTER (WHERE posting_status::text = 'P'::text) AS total_on_time,
    count(*) FILTER (WHERE posting_status::text <> 'P'::text) AS total_late,
    ( SELECT count(*) AS count
           FROM cn_c3_missing) AS total_missing,
    count(*) AS total_submissions
   FROM cn_c3_reported;
CREATE OR REPLACE VIEW public.ce_v_c3_compliance_summary AS
 SELECT c3.payer_id AS employer_id,
    e.name AS employer_name,
    e.office_code AS zone,
    count(*) FILTER (WHERE c3.posting_status::text = 'P'::text) AS on_time,
    count(*) FILTER (WHERE c3.posting_status::text <> 'P'::text) AS late,
    COALESCE(m.missing_count, 0::bigint) AS missing,
        CASE
            WHEN count(*) > 0 THEN round(100.0 * count(*) FILTER (WHERE c3.posting_status::text = 'P'::text)::numeric / GREATEST(count(*) + COALESCE(m.missing_count, 0::bigint), 1::bigint)::numeric, 1)
            ELSE 0::numeric
        END AS compliance_rate
   FROM cn_c3_reported c3
     LEFT JOIN er_master e ON c3.payer_id::text = e.regno::text
     LEFT JOIN ( SELECT cn_c3_missing.payer_id,
            count(*) AS missing_count
           FROM cn_c3_missing
          GROUP BY cn_c3_missing.payer_id) m ON c3.payer_id::text = m.payer_id::text
  GROUP BY c3.payer_id, e.name, e.office_code, m.missing_count;
CREATE OR REPLACE VIEW public.ce_v_c3_unposted_to_ledger AS
 SELECT c3.id AS c3_id,
    c3.payer_id,
    c3.payer_type,
    c3.period,
    c3.sequence_no,
    c3.posting_status,
    c3.entered_by,
    c3.date_posted,
    COALESCE(c3.payer_name, em.name) AS employer_name,
    COALESCE(c3.emp_ss_amt_calc, 0::numeric) AS ss_dues,
    COALESCE(c3.emp_levy_amt_calc, 0::numeric) AS levy_dues,
    COALESCE(c3.emp_pe_amt_calc, 0::numeric) AS ei_dues,
    COALESCE(c3.emp_ss_fines_due, 0::numeric) AS ss_penalty,
    COALESCE(c3.emp_levy_penalty_amt, 0::numeric) AS levy_penalty,
    COALESCE(c3.emp_pe_penalty_amt, 0::numeric) AS pe_penalty,
    COALESCE(c3.emp_ss_amt_calc, 0::numeric) + COALESCE(c3.emp_levy_amt_calc, 0::numeric) + COALESCE(c3.emp_pe_amt_calc, 0::numeric) + COALESCE(c3.emp_ss_fines_due, 0::numeric) + COALESCE(c3.emp_levy_penalty_amt, 0::numeric) + COALESCE(c3.emp_pe_penalty_amt, 0::numeric) AS total_amount
   FROM cn_c3_reported c3
     LEFT JOIN er_master em ON em.regno::text = c3.payer_id::text
  WHERE (c3.posting_status::text = ANY (ARRAY['VAC'::character varying, 'Posted'::character varying]::text[])) AND NOT (EXISTS ( SELECT 1
           FROM ce_c3_ledger_sync_log sl
          WHERE sl.payer_id::text = c3.payer_id::text AND sl.period = c3.period AND sl.sequence_no = c3.sequence_no AND (sl.posting_status_snapshot::text = ANY (ARRAY['VAC'::character varying, 'Posted'::character varying]::text[])) AND sl.sync_status::text = 'success'::text)) AND NOT (EXISTS ( SELECT 1
           FROM ce_employer_financial_ledger l
          WHERE l.idempotency_key::text = ((((('c3-ss-'::text || c3.payer_id::text) || '-'::text) || c3.period::text) || '-'::text) || c3.sequence_no::text)));
CREATE OR REPLACE VIEW public.ce_v_case_monthly_trend AS
 SELECT to_char(created_at, 'YYYY-MM'::text) AS month_key,
    to_char(created_at, 'Mon'::text) AS month_label,
    count(*) AS created,
    count(*) FILTER (WHERE status::text = 'COMPLETED'::text OR status::text = 'CLOSED'::text) AS closed
   FROM ce_cases
  WHERE is_deleted = false
  GROUP BY (to_char(created_at, 'YYYY-MM'::text)), (to_char(created_at, 'Mon'::text))
  ORDER BY (to_char(created_at, 'YYYY-MM'::text));
CREATE OR REPLACE VIEW public.ce_v_case_resolution_stats AS
 SELECT case_type,
    round(avg(EXTRACT(epoch FROM COALESCE(closed_date::timestamp with time zone, now()) - opened_date::timestamp with time zone) / 86400::numeric))::integer AS avg_days,
    count(*) AS case_count
   FROM ce_cases
  WHERE is_deleted = false
  GROUP BY case_type;
CREATE OR REPLACE VIEW public.ce_v_compliance_kpis AS
 SELECT ( SELECT count(*) AS count
           FROM ce_violations
          WHERE NOT ce_violations.is_merged) AS total_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'OPEN'::text AND NOT ce_violations.is_merged) AS open_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'IN_PROGRESS'::text AND NOT ce_violations.is_merged) AS in_progress_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'UNDER_REVIEW'::text AND NOT ce_violations.is_merged) AS under_review_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'ESCALATED'::text AND NOT ce_violations.is_merged) AS escalated_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'RESOLVED'::text AND NOT ce_violations.is_merged) AS resolved_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'CLOSED'::text AND NOT ce_violations.is_merged) AS closed_violations,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.status::text = 'CANCELLED'::text AND NOT ce_violations.is_merged) AS cancelled_violations,
    ( SELECT count(*) AS count
           FROM ce_cases
          WHERE (ce_cases.status::text = ANY (ARRAY['ACTIVE'::character varying, 'ESCALATED_LEGAL'::character varying, 'UNDER_REVIEW'::character varying]::text[])) AND (ce_cases.is_deleted = false OR ce_cases.is_deleted IS NULL)) AS active_cases,
    ( SELECT count(*) AS count
           FROM ce_cases
          WHERE ce_cases.status::text = 'CLOSED'::text AND (ce_cases.is_deleted = false OR ce_cases.is_deleted IS NULL)) AS closed_cases,
    ( SELECT count(*) AS count
           FROM ce_notices
          WHERE ce_notices.response_received = true) AS notices_responded,
    ( SELECT count(*) AS count
           FROM ce_notices) AS total_notices,
    ( SELECT round(avg(EXTRACT(epoch FROM ce_violations.resolved_at - ce_violations.created_at) / 86400::numeric), 1) AS round
           FROM ce_violations
          WHERE ce_violations.resolved_at IS NOT NULL) AS avg_resolution_days,
    ( SELECT count(*) AS count
           FROM ce_violations
          WHERE ce_violations.due_date < now() AND (ce_violations.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying]::text[])) AND NOT ce_violations.is_merged) AS overdue_violations,
    ( SELECT count(DISTINCT ce_violations.employer_id) AS count
           FROM ce_violations
          WHERE (ce_violations.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying, 'ESCALATED'::character varying]::text[])) AND NOT ce_violations.is_merged) AS employers_with_active_violations;
CREATE OR REPLACE VIEW public.ce_v_compliance_monitoring AS
 SELECT cs.id,
    cs.employer_id,
    e.name AS employer_name,
    e.regno AS employer_regno,
    cs.overall_compliance_status,
    cs.filing_status,
    cs.payment_status,
    cs.current_arrears_amount,
    cs.current_penalty_amount,
    cs.active_violation_count,
    cs.active_case_count,
    cs.active_arrangement_count,
    cs.last_filing_period,
    cs.last_payment_date,
    cs.last_computed_at,
    cs.review_due_date,
    COALESCE(rp.risk_band, 'UNKNOWN'::character varying)::text AS risk_band,
    COALESCE(rp.total_score, 0::numeric) AS risk_score
   FROM ce_employer_compliance_status cs
     LEFT JOIN er_master e ON cs.employer_id::text = e.regno::text
     LEFT JOIN ce_risk_profiles rp ON cs.employer_id::text = rp.employer_id::text;
CREATE OR REPLACE VIEW public.ce_v_employer_arrears_summary AS
 WITH c3_dues AS (
         SELECT c.payer_id AS regno,
            COALESCE(sum(COALESCE(c.emp_ss_amt_calc, c.emp_ss_amt_rpt, 0::numeric) + COALESCE(c.emp_pe_amt_calc, c.emp_pe_amt_rpt, 0::numeric) + COALESCE(c.emp_levy_amt_calc, c.emp_levy_amt_rpt, 0::numeric)), 0::numeric) AS total_dues,
            COALESCE(sum(COALESCE(c.emp_ss_fines_due, 0::numeric) + COALESCE(c.emp_pe_penalty_amt, 0::numeric) + COALESCE(c.emp_levy_penalty_amt, 0::numeric)), 0::numeric) AS total_penalties
           FROM cn_c3_reported c
          GROUP BY c.payer_id
        ), payments AS (
         SELECT ph.payer_id AS regno,
            COALESCE(sum(p_1.payment_amount), 0::numeric) AS total_paid
           FROM cn_payment p_1
             JOIN cn_payment_header ph ON ph.payment_id = p_1.payment_id
          GROUP BY ph.payer_id
        )
 SELECT e.regno,
    e.name AS employer_name,
    GREATEST(COALESCE(d.total_dues, 0::numeric) - COALESCE(p.total_paid, 0::numeric), 0::numeric) AS current_arrears,
    COALESCE(d.total_penalties, 0::numeric) AS current_penalty,
    GREATEST(COALESCE(d.total_dues, 0::numeric) - COALESCE(p.total_paid, 0::numeric), 0::numeric) + COALESCE(d.total_penalties, 0::numeric) AS total_outstanding,
        CASE
            WHEN (COALESCE(d.total_dues, 0::numeric) - COALESCE(p.total_paid, 0::numeric)) > 0::numeric THEN true
            ELSE false
        END AS has_arrears
   FROM er_master e
     LEFT JOIN c3_dues d ON d.regno::text = e.regno::text
     LEFT JOIN payments p ON p.regno::text = e.regno::text
  WHERE e.status = ANY (ARRAY['A'::bpchar, 'V'::bpchar, 'I'::bpchar, 'D'::bpchar]);
CREATE OR REPLACE VIEW public.ce_v_employer_filing_status AS
 WITH periods AS (
         SELECT generate_series(date_trunc('month'::text, now() - '1 year'::interval)::date::timestamp with time zone, date_trunc('month'::text, now() - '1 mon'::interval)::date::timestamp with time zone, '1 mon'::interval)::date AS period_date
        ), employer_filings AS (
         SELECT e.regno,
            e.name AS employer_name,
            e.status AS employer_status,
            e.office_code,
            COALESCE(date_trunc('month'::text, e.date_wages_first_paid)::date, date_trunc('month'::text, e.registration_date)::date, date_trunc('month'::text, now() - '1 year'::interval)::date) AS compliance_start_period,
            count(DISTINCT c.period) AS total_filings_12m,
            max(c.period) AS last_filing_period,
            max(c.date_received) AS last_filing_date
           FROM er_master e
             LEFT JOIN cn_c3_reported c ON c.payer_id::text = e.regno::text AND c.period >= (now() - '1 year'::interval)::date AND c.posting_status::text IS DISTINCT FROM 'CANCELLED'::text
          WHERE e.status = ANY (ARRAY['A'::bpchar, 'V'::bpchar])
          GROUP BY e.regno, e.name, e.status, e.office_code, e.date_wages_first_paid, e.registration_date
        )
 SELECT regno,
    employer_name,
    employer_status,
    office_code,
    total_filings_12m,
    GREATEST((( SELECT count(*) AS count
           FROM periods p
          WHERE p.period_date >= ef.compliance_start_period))::integer - COALESCE(total_filings_12m::integer, 0), 0) AS missed_filings_12m,
    last_filing_period,
    last_filing_date,
    ( SELECT max(periods.period_date) AS max
           FROM periods) AS latest_period_due,
        CASE
            WHEN last_filing_period >= (( SELECT max(periods.period_date) AS max
               FROM periods)) THEN true
            ELSE false
        END AS is_current,
    (( SELECT count(*) AS count
           FROM periods p
          WHERE p.period_date >= ef.compliance_start_period))::integer AS expected_filings_12m,
    compliance_start_period
   FROM employer_filings ef;
CREATE OR REPLACE VIEW public.ce_v_employer_legal_status AS
 SELECT e.regno,
    e.name AS employer_name,
    COALESCE(le.active_escalation_count, 0::bigint) AS active_escalation_count,
    COALESCE(su.active_suit_count, 0::bigint) AS active_suit_count,
    le.latest_stage,
        CASE
            WHEN COALESCE(le.active_escalation_count, 0::bigint) > 0 OR COALESCE(su.active_suit_count, 0::bigint) > 0 THEN true
            ELSE false
        END AS has_active_legal
   FROM er_master e
     LEFT JOIN ( SELECT ce_legal_escalations.employer_id,
            count(*) AS active_escalation_count,
            max(ce_legal_escalations.current_stage::text) AS latest_stage
           FROM ce_legal_escalations
          WHERE ce_legal_escalations.current_stage::text <> ALL (ARRAY['Resolved'::character varying, 'Dismissed'::character varying, 'Withdrawn'::character varying]::text[])
          GROUP BY ce_legal_escalations.employer_id) le ON le.employer_id::text = e.regno::text
     LEFT JOIN ( SELECT er_suit.regno,
            count(*) AS active_suit_count
           FROM er_suit
          WHERE er_suit.suit_status <> ALL (ARRAY['C'::bpchar, 'D'::bpchar])
          GROUP BY er_suit.regno) su ON su.regno::text = e.regno::text
  WHERE e.status = ANY (ARRAY['A'::bpchar, 'V'::bpchar, 'I'::bpchar, 'D'::bpchar]);
CREATE OR REPLACE VIEW public.ce_v_employer_payment_status AS
 SELECT e.regno,
    e.name AS employer_name,
    count(DISTINCT cp.payment_id) AS total_payments_12m,
    COALESCE(sum(cp.payment_amount), 0::numeric) AS total_amount_12m,
    max(cp.payment_date) AS last_payment_date,
    max(cp.period) AS last_payment_period,
        CASE
            WHEN max(cp.payment_date) >= (now() - '60 days'::interval) THEN true
            ELSE false
        END AS has_recent_payment
   FROM er_master e
     LEFT JOIN cn_payment_header cph ON cph.payer_id::text = e.regno::text
     LEFT JOIN cn_payment cp ON cp.payment_id = cph.payment_id AND cp.payment_date >= (now() - '1 year'::interval)
  WHERE e.status = ANY (ARRAY['A'::bpchar, 'V'::bpchar])
  GROUP BY e.regno, e.name;
CREATE OR REPLACE VIEW public.ce_v_employer_timeline AS
 SELECT v.employer_id,
    v.created_at AS event_date,
    'VIOLATION_CREATED'::text AS event_type,
    'VIOLATION'::text AS event_category,
    'Violation Created: '::text || v.violation_number::text AS title,
    COALESCE(vt.name, v.summary::character varying, 'New violation'::character varying) AS description,
    v.status,
    v.id AS reference_id,
    'ce_violations'::text AS source_table
   FROM ce_violations v
     LEFT JOIN ce_violation_types vt ON v.violation_type_id = vt.id
  WHERE v.is_deleted = false
UNION ALL
 SELECT v.employer_id,
    vh.performed_at AS event_date,
    'VIOLATION_STATUS_CHANGE'::text AS event_type,
    'VIOLATION'::text AS event_category,
    (('Status: '::text || COALESCE(vh.from_value, '?'::character varying)::text) || ' → '::text) || COALESCE(vh.to_value, '?'::character varying)::text AS title,
    COALESCE(vh.notes, ''::text) AS description,
    vh.to_value AS status,
    v.id AS reference_id,
    'ce_violation_history'::text AS source_table
   FROM ce_violation_history vh
     JOIN ce_violations v ON vh.violation_id = v.id
  WHERE v.is_deleted = false
UNION ALL
 SELECT n.employer_id,
    COALESCE(n.sent_at, n.created_at) AS event_date,
        CASE n.status
            WHEN 'DRAFT'::text THEN 'NOTICE_CREATED'::text
            WHEN 'SENT'::text THEN 'NOTICE_SENT'::text
            WHEN 'DELIVERED'::text THEN 'NOTICE_DELIVERED'::text
            WHEN 'ACKNOWLEDGED'::text THEN 'NOTICE_ACKNOWLEDGED'::text
            ELSE 'NOTICE_UPDATED'::text
        END AS event_type,
    'NOTICE'::text AS event_category,
    (('Notice '::text || n.notice_number::text) || ': '::text) || COALESCE(replace(n.notice_type::text, '_'::text, ' '::text), ''::text) AS title,
    COALESCE(n.subject, ''::character varying) AS description,
    n.status,
    n.id AS reference_id,
    'ce_notices'::text AS source_table
   FROM ce_notices n
UNION ALL
 SELECT fa.employer_id,
    COALESCE(fa.due_date::timestamp with time zone, fa.created_at) AS event_date,
        CASE fa.status
            WHEN 'COMPLETED'::text THEN 'FOLLOWUP_COMPLETED'::text
            WHEN 'CANCELLED'::text THEN 'FOLLOWUP_CANCELLED'::text
            ELSE 'FOLLOWUP_SCHEDULED'::text
        END AS event_type,
    'FOLLOW_UP'::text AS event_category,
    replace(fa.action_type::text, '_'::text, ' '::text) || ' — Follow-up'::text AS title,
    COALESCE(fa.description, ''::text) AS description,
    fa.status,
    fa.id AS reference_id,
    'ce_follow_up_actions'::text AS source_table
   FROM ce_follow_up_actions fa
UNION ALL
 SELECT rp.employer_id,
    rsh.calculated_at AS event_date,
    'RISK_SCORE_CHANGE'::text AS event_type,
    'RISK'::text AS event_category,
    ((('Risk: '::text || round(rsh.new_score, 1)) || ' ('::text) || COALESCE(rsh.new_band, '?'::character varying)::text) || ')'::text AS title,
    ((('Previous: '::text || round(rsh.previous_score, 1)) || ' ('::text) || COALESCE(rsh.previous_band, '?'::character varying)::text) || ')'::text AS description,
    rsh.new_band AS status,
    rsh.id AS reference_id,
    'ce_risk_score_history'::text AS source_table
   FROM ce_risk_score_history rsh
     JOIN ce_risk_profiles rp ON rsh.risk_profile_id = rp.id;
CREATE OR REPLACE VIEW public.ce_v_employer_workforce AS
 WITH latest_c3 AS (
         SELECT DISTINCT ON (cn_c3_reported.payer_id) cn_c3_reported.payer_id,
            cn_c3_reported.number_employed AS last_reported_employees,
            cn_c3_reported.period AS last_reported_period
           FROM cn_c3_reported
          WHERE cn_c3_reported.posting_status::text IS DISTINCT FROM 'CANCELLED'::text
          ORDER BY cn_c3_reported.payer_id, cn_c3_reported.period DESC
        )
 SELECT e.regno,
    e.name AS employer_name,
    COALESCE(e.males_employed, 0::double precision) AS registered_males,
    COALESCE(e.females_employed, 0::double precision) AS registered_females,
    COALESCE(e.males_employed, 0::double precision) + COALESCE(e.females_employed, 0::double precision) AS registered_total,
    COALESCE(lc.last_reported_employees, 0) AS last_reported_employees,
    lc.last_reported_period,
    COALESCE(lc.last_reported_employees, 0)::double precision - (COALESCE(e.males_employed, 0::double precision) + COALESCE(e.females_employed, 0::double precision)) AS employee_delta
   FROM er_master e
     LEFT JOIN latest_c3 lc ON lc.payer_id::text = e.regno::text
  WHERE e.status = ANY (ARRAY['A'::bpchar, 'V'::bpchar]);
CREATE OR REPLACE VIEW public.ce_v_officer_performance AS
 SELECT v.assigned_to_user_id AS officer_id,
    COALESCE(p.full_name, 'Unassigned'::text) AS officer_name,
    count(*) AS total_assigned,
    count(*) FILTER (WHERE v.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying, 'ESCALATED'::character varying]::text[])) AS active_count,
    count(*) FILTER (WHERE v.status::text = ANY (ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying]::text[])) AS resolved_count,
    count(*) FILTER (WHERE v.due_date < now() AND (v.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying]::text[]))) AS overdue_count,
    round(avg(EXTRACT(epoch FROM v.resolved_at - v.created_at) / 86400::numeric) FILTER (WHERE v.resolved_at IS NOT NULL), 1) AS avg_resolution_days,
        CASE
            WHEN count(*) > 0 THEN round(count(*) FILTER (WHERE v.due_date < now() AND (v.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying]::text[])))::numeric / count(*)::numeric * 100::numeric, 1)
            ELSE 0::numeric
        END AS overdue_pct
   FROM ce_violations v
     LEFT JOIN profiles p ON p.id::text = v.assigned_to_user_id::text
  WHERE NOT v.is_merged
  GROUP BY v.assigned_to_user_id, p.full_name;
CREATE OR REPLACE VIEW public.ce_v_payment_reconciliation_exceptions AS
 SELECT 'unposted_payment'::text AS exception_type,
    'cn_payment'::text AS source_table,
    cp.payment_sequence_no AS source_id,
    cph.payer_id AS employer_id,
    cp.payment_amount AS source_amount,
    NULL::numeric AS ledger_amount,
    NULL::numeric AS allocated_amount,
    cp.payment_date::timestamp with time zone AS event_date,
    'Payment exists in source but not in compliance ledger'::text AS description
   FROM cn_payment cp
     JOIN cn_payment_header cph ON cp.payment_id = cph.payment_id
     LEFT JOIN cn_receipt cr ON cp.payment_id::numeric = cr.payment_id
  WHERE cph.payer_id IS NOT NULL AND (cr.status IS NULL OR (cr.status::text <> ALL (ARRAY['C'::character varying, 'V'::character varying, 'X'::character varying]::text[]))) AND (cph.status IS NULL OR cph.status <> 'deleted'::text) AND NOT (EXISTS ( SELECT 1
           FROM ce_payment_ledger_sync_log sl
          WHERE sl.source_table = 'cn_payment'::text AND sl.source_payment_id = cp.payment_sequence_no AND sl.sync_status = 'posted'::text))
UNION ALL
 SELECT 'unallocated_credit'::text AS exception_type,
    sl.source_table,
    sl.source_payment_id AS source_id,
    sl.employer_id,
    sl.amount_snapshot AS source_amount,
    NULL::numeric AS ledger_amount,
    NULL::numeric AS allocated_amount,
    sl.synced_at AS event_date,
    'Payment synced to ledger but not allocated to any dues'::text AS description
   FROM ce_payment_ledger_sync_log sl
  WHERE sl.sync_status = 'posted'::text AND sl.allocation_status = 'unallocated'::text
UNION ALL
 SELECT 'over_allocated'::text AS exception_type,
    sl.source_table,
    sl.source_payment_id AS source_id,
    sl.employer_id,
    sl.amount_snapshot AS source_amount,
    NULL::numeric AS ledger_amount,
    alloc_total.total_allocated AS allocated_amount,
    sl.synced_at AS event_date,
    'Sum of allocations exceeds source payment amount'::text AS description
   FROM ce_payment_ledger_sync_log sl
     JOIN LATERAL ( SELECT sum(pa.allocated_amount) AS total_allocated
           FROM ce_payment_allocations pa
          WHERE pa.source_payment_id = sl.source_payment_id AND pa.source_table = sl.source_table) alloc_total ON alloc_total.total_allocated > sl.amount_snapshot
  WHERE sl.sync_status = 'posted'::text
UNION ALL
 SELECT 'cancelled_source_active_credit'::text AS exception_type,
    'cn_payment'::text AS source_table,
    sl.source_payment_id AS source_id,
    sl.employer_id,
    sl.amount_snapshot AS source_amount,
    efl.credit_amount AS ledger_amount,
    NULL::numeric AS allocated_amount,
    cr.cancel_date::timestamp with time zone AS event_date,
    'Source receipt cancelled but ledger credit still active'::text AS description
   FROM ce_payment_ledger_sync_log sl
     JOIN cn_payment cp2 ON cp2.payment_sequence_no = sl.source_payment_id
     JOIN cn_receipt cr ON cr.payment_id = cp2.payment_id::numeric
     JOIN ce_employer_financial_ledger efl ON efl.idempotency_key::text = ('pay-cnpmt-'::text || sl.source_payment_id::text)
  WHERE sl.sync_status = 'posted'::text AND (cr.status::text = ANY (ARRAY['C'::character varying, 'V'::character varying, 'X'::character varying]::text[])) AND efl.status = 'POSTED'::ce_ledger_status;
CREATE OR REPLACE VIEW public.ce_v_payments_unposted_to_ledger AS
 SELECT 'cn_payment'::text AS payment_source_table,
    cp.payment_sequence_no AS source_payment_id,
    cr.receipt_id,
    cr.receipt_number,
    cph.payer_id AS employer_id,
    cp.payment_date,
    cp.payment_amount AS amount,
    cp.fund_code,
    cp.payment_code,
    cp.mop_code AS payment_method,
    cp.period,
    cph.batch_number,
    cb.entered_by AS cashier,
    cr.status AS receipt_status,
    COALESCE(cph.status, 'active'::text) AS header_status,
    'pay-cnpmt-'::text || cp.payment_sequence_no::text AS sync_key
   FROM cn_payment cp
     JOIN cn_payment_header cph ON cp.payment_id = cph.payment_id
     LEFT JOIN cn_receipt cr ON cp.payment_id::numeric = cr.payment_id
     LEFT JOIN cn_batch cb ON cph.batch_number::text = cb.batch_number::text
  WHERE cph.payer_id IS NOT NULL AND (cr.status IS NULL OR (cr.status::text <> ALL (ARRAY['C'::character varying, 'V'::character varying, 'X'::character varying]::text[]))) AND (cph.status IS NULL OR cph.status <> 'deleted'::text) AND NOT (EXISTS ( SELECT 1
           FROM ce_payment_ledger_sync_log sl
          WHERE sl.source_table = 'cn_payment'::text AND sl.source_payment_id = cp.payment_sequence_no AND NOT sl.fund_code::text IS DISTINCT FROM cp.fund_code::text AND sl.sync_status = 'posted'::text)) AND NOT (EXISTS ( SELECT 1
           FROM ce_employer_financial_ledger efl
          WHERE efl.idempotency_key::text = ('pay-cnpmt-'::text || cp.payment_sequence_no::text)));
CREATE OR REPLACE VIEW public.ce_v_pending_case_nominations AS
 SELECT a.id AS nomination_id,
    a.linked_case_id AS case_id,
    a.employer_id,
    a.week_start_date,
    a.requested_by_user_code AS officer_user_code,
    a.reason,
    a.notes,
    a.created_at,
    c.case_number,
    c.employer_name,
    c.risk_band,
    c.fund_type
   FROM ce_planner_candidate_actions a
     LEFT JOIN ce_cases c ON c.id = a.linked_case_id
  WHERE a.action_type = 'nominate_for_planning'::text AND a.is_active = true AND NOT (EXISTS ( SELECT 1
           FROM ce_weekly_plan_items i
             JOIN ce_weekly_plans p ON p.id = i.plan_id
          WHERE p.week_start_date = a.week_start_date AND p.created_by::text = a.requested_by_user_code::text AND i.employer_id::text = a.employer_id AND i.source_type::text = 'MANUAL_CASE_NOMINATION'::text AND COALESCE(i.source_id, ''::text) = a.id::text));
CREATE OR REPLACE VIEW public.ce_v_plan_employer_facts AS
 SELECT em.regno AS employer_id,
    em.name AS employer_name,
    em.village_code AS territory,
    rp.risk_band,
    rp.total_score AS risk_score,
    rp.arrears_score,
    rp.violation_score AS risk_violation_score,
    rp.filing_score,
    rp.payment_behavior_score,
    rp.enforcement_risk_score,
    insp.last_inspection_date,
    insp.last_inspection_type,
    EXTRACT(day FROM now() - insp.last_inspection_date::timestamp without time zone::timestamp with time zone)::integer AS days_since_last_inspection,
    COALESCE(viol.open_violation_count, 0::bigint) AS open_violation_count,
    COALESCE(viol.escalated_violation_count, 0::bigint) AS escalated_violation_count,
    viol.oldest_open_violation_date,
    EXTRACT(day FROM now() - viol.oldest_open_violation_date)::integer AS days_oldest_violation,
    COALESCE(viol.total_violation_exposure, 0::numeric) AS total_violation_exposure,
    COALESCE(fu.overdue_followup_count, 0::bigint) AS overdue_followup_count,
    COALESCE(fu.planned_followup_count, 0::bigint) AS planned_followup_count,
    fu.oldest_overdue_followup_date,
    COALESCE(ntc.pending_notice_count, 0::bigint) AS pending_notice_count,
    ntc.nearest_response_due,
    EXTRACT(day FROM ntc.nearest_response_due::timestamp with time zone - now())::integer AS notice_days_remaining,
    COALESCE(arr.active_arrangement_count, 0::bigint) AS active_arrangement_count,
    COALESCE(arr.breached_arrangement_count, 0::bigint) AS breached_arrangement_count,
    COALESCE(arr.total_arrangement_outstanding, 0::numeric) AS total_arrangement_outstanding,
    COALESCE(arr.any_breach_detected, false) AS any_breach_detected,
    COALESCE(arr.max_missed_payments, 0) AS max_missed_payments,
    COALESCE(scout.active_scouting_leads, 0::bigint) AS active_scouting_leads,
    COALESCE(cf.carry_forward_count, 0::bigint) AS carry_forward_count
   FROM er_master em
     LEFT JOIN ce_risk_profiles rp ON rp.employer_id::text = em.regno::text
     LEFT JOIN LATERAL ( SELECT max(i.scheduled_date) AS last_inspection_date,
            (array_agg(i.inspection_type ORDER BY i.scheduled_date DESC))[1] AS last_inspection_type
           FROM ce_inspections i
          WHERE i.employer_id::text = em.regno::text AND (i.status::text = ANY (ARRAY['COMPLETED'::character varying, 'IN_PROGRESS'::character varying]::text[]))) insp ON true
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE v.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying, 'ESCALATED'::character varying]::text[])) AS open_violation_count,
            count(*) FILTER (WHERE v.status::text = 'ESCALATED'::text) AS escalated_violation_count,
            min(v.created_at) FILTER (WHERE v.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying, 'ESCALATED'::character varying]::text[])) AS oldest_open_violation_date,
            COALESCE(sum(v.total_amount) FILTER (WHERE v.status::text = ANY (ARRAY['OPEN'::character varying, 'IN_PROGRESS'::character varying, 'UNDER_REVIEW'::character varying, 'ESCALATED'::character varying]::text[])), 0::numeric) AS total_violation_exposure
           FROM ce_violations v
          WHERE v.employer_id::text = em.regno::text AND v.is_deleted = false) viol ON true
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE fa.status::text = 'OVERDUE'::text) AS overdue_followup_count,
            count(*) FILTER (WHERE fa.status::text = ANY (ARRAY['PLANNED'::character varying, 'SCHEDULED'::character varying]::text[])) AS planned_followup_count,
            min(fa.due_date) FILTER (WHERE fa.status::text = 'OVERDUE'::text) AS oldest_overdue_followup_date
           FROM ce_follow_up_actions fa
          WHERE fa.employer_id::text = em.regno::text AND fa.is_deleted = false) fu ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS pending_notice_count,
            min(n.due_response_date) AS nearest_response_due
           FROM ce_notices n
          WHERE n.employer_id::text = em.regno::text AND (n.status::text = ANY (ARRAY['SENT'::character varying, 'DELIVERED'::character varying]::text[])) AND n.due_response_date >= CURRENT_DATE) ntc ON true
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE pa.status::text = 'ACTIVE'::text) AS active_arrangement_count,
            count(*) FILTER (WHERE pa.breach_detected = true) AS breached_arrangement_count,
            COALESCE(sum(pa.total_debt - pa.total_paid) FILTER (WHERE pa.status::text = 'ACTIVE'::text), 0::numeric) AS total_arrangement_outstanding,
            bool_or(pa.breach_detected) AS any_breach_detected,
            max(pa.missed_payments) AS max_missed_payments
           FROM ce_payment_arrangements pa
          WHERE pa.employer_id::text = em.regno::text) arr ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS active_scouting_leads
           FROM ce_scouting_leads sl
          WHERE sl.linked_employer_id::text = em.regno::text AND (sl.status::text = ANY (ARRAY['NEW'::character varying, 'UNDER_INVESTIGATION'::character varying]::text[]))) scout ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS carry_forward_count
           FROM ce_weekly_plan_items wpi
          WHERE wpi.employer_id::text = em.regno::text AND (wpi.execution_status::text = ANY (ARRAY['NOT_DONE'::character varying, 'RESCHEDULED'::character varying]::text[])) AND wpi.carried_forward_to IS NULL) cf ON true
  WHERE em.status = 'A'::bpchar;
CREATE OR REPLACE VIEW public.ce_v_unobserved_payment_entries AS
 SELECT l.id AS ledger_entry_id,
    l.employer_id,
    l.employer_name,
    l.entry_type,
    l.fund_type,
    l.period,
    l.credit_amount,
    l.idempotency_key AS ledger_idempotency_key,
    l.reference_type,
    l.reference_id,
    l.description,
    l.posted_by,
    l.posted_at
   FROM ce_employer_financial_ledger l
     LEFT JOIN ce_payment_observation_log o ON o.ledger_entry_id = l.id
  WHERE (l.entry_type = ANY (ARRAY['PAYMENT_RECEIVED'::ce_ledger_entry_type, 'ARRANGEMENT_CREDIT'::ce_ledger_entry_type, 'REFUND'::ce_ledger_entry_type])) AND l.status = 'POSTED'::ce_ledger_status AND l.reversal_of_id IS NULL AND o.id IS NULL;
CREATE OR REPLACE VIEW public.ce_v_violation_trends AS
 SELECT to_char(month_start.month_start, 'YYYY-MM'::text) AS month_key,
    to_char(month_start.month_start, 'Mon YYYY'::text) AS month_label,
    COALESCE(c.created_count, 0::bigint) AS created_count,
    COALESCE(r.resolved_count, 0::bigint) AS resolved_count,
    COALESCE(e.escalated_count, 0::bigint) AS escalated_count
   FROM generate_series(date_trunc('month'::text, now()) - '11 mons'::interval, date_trunc('month'::text, now()), '1 mon'::interval) month_start(month_start)
     LEFT JOIN ( SELECT date_trunc('month'::text, ce_violations.created_at) AS m,
            count(*) AS created_count
           FROM ce_violations
          WHERE NOT ce_violations.is_merged
          GROUP BY (date_trunc('month'::text, ce_violations.created_at))) c ON c.m = month_start.month_start
     LEFT JOIN ( SELECT date_trunc('month'::text, ce_violations.resolved_at) AS m,
            count(*) AS resolved_count
           FROM ce_violations
          WHERE ce_violations.resolved_at IS NOT NULL AND NOT ce_violations.is_merged
          GROUP BY (date_trunc('month'::text, ce_violations.resolved_at))) r ON r.m = month_start.month_start
     LEFT JOIN ( SELECT date_trunc('month'::text, ce_violation_history.performed_at) AS m,
            count(*) AS escalated_count
           FROM ce_violation_history
          WHERE ce_violation_history.action::text = 'status_change'::text AND ce_violation_history.to_value::text = 'ESCALATED'::text
          GROUP BY (date_trunc('month'::text, ce_violation_history.performed_at))) e ON e.m = month_start.month_start
  ORDER BY month_start.month_start;
CREATE OR REPLACE VIEW public.ce_v_visit_execution_metrics AS
 SELECT i.id AS inspection_id,
    i.plan_item_id,
    i.employer_id,
    i.status AS inspection_status,
    i.scheduled_date,
    COALESCE(c.total, 0::bigint) AS checklist_total,
    COALESCE(c.answered, 0::bigint) AS checklist_answered,
        CASE
            WHEN COALESCE(c.total, 0::bigint) = 0 THEN 0::numeric
            ELSE round(c.answered::numeric * 100.0 / c.total::numeric, 1)
        END AS checklist_pct,
    COALESCE(e.cnt, 0::bigint) AS evidence_count,
    COALESCE(f.cnt, 0::bigint) AS findings_count,
    COALESCE(f.critical, 0::bigint) AS findings_critical,
    COALESCE(f.high, 0::bigint) AS findings_high,
    COALESCE(f.medium, 0::bigint) AS findings_medium,
    COALESCE(f.low, 0::bigint) AS findings_low,
    COALESCE(fu.cnt, 0::bigint) AS followup_count,
    COALESCE(v.cnt, 0::bigint) AS violations_count,
    r.id AS report_id,
    r.status AS report_status,
    r.report_number
   FROM ce_inspections i
     LEFT JOIN ( SELECT ce_audit_checklist_responses.inspection_id,
            count(*) AS total,
            count(ce_audit_checklist_responses.response) AS answered
           FROM ce_audit_checklist_responses
          GROUP BY ce_audit_checklist_responses.inspection_id) c ON c.inspection_id = i.id
     LEFT JOIN ( SELECT ce_inspection_evidence.inspection_id,
            count(*) AS cnt
           FROM ce_inspection_evidence
          GROUP BY ce_inspection_evidence.inspection_id) e ON e.inspection_id = i.id
     LEFT JOIN ( SELECT ce_inspection_findings.inspection_id,
            count(*) AS cnt,
            count(*) FILTER (WHERE ce_inspection_findings.severity::text = 'Critical'::text) AS critical,
            count(*) FILTER (WHERE ce_inspection_findings.severity::text = 'High'::text) AS high,
            count(*) FILTER (WHERE ce_inspection_findings.severity::text = 'Medium'::text) AS medium,
            count(*) FILTER (WHERE ce_inspection_findings.severity::text = 'Low'::text) AS low
           FROM ce_inspection_findings
          GROUP BY ce_inspection_findings.inspection_id) f ON f.inspection_id = i.id
     LEFT JOIN ( SELECT fnd.inspection_id,
            count(*) AS cnt
           FROM ce_follow_up_actions fua
             JOIN ce_inspection_findings fnd ON fnd.id = fua.finding_id
          WHERE fua.is_deleted = false
          GROUP BY fnd.inspection_id) fu ON fu.inspection_id = i.id
     LEFT JOIN ( SELECT ce_inspection_findings.inspection_id,
            count(DISTINCT ce_inspection_findings.violation_id) AS cnt
           FROM ce_inspection_findings
          WHERE ce_inspection_findings.violation_id IS NOT NULL
          GROUP BY ce_inspection_findings.inspection_id) v ON v.inspection_id = i.id
     LEFT JOIN ce_employer_audit_reports r ON r.inspection_id = i.id;
CREATE OR REPLACE VIEW public.ce_v_weekly_plan_candidates AS
 SELECT 'VIOLATION'::text AS source_type,
    v.id AS source_id,
    v.violation_number AS source_ref,
    v.employer_id,
    COALESCE(v.employer_name, em.name) AS employer_name,
    v.territory,
    v.priority,
    v.status AS source_status,
    v.total_amount AS financial_exposure,
    v.due_date::timestamp with time zone AS due_date,
    v.assigned_to_user_id::text AS assigned_to_user_id,
    v.created_at AS source_created_at,
    'Violation: '::text || COALESCE(v.summary, v.violation_number::text) AS description
   FROM ce_violations v
     LEFT JOIN er_master em ON v.employer_id::text = em.regno::text
  WHERE v.status::text = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'UNDER_REVIEW'::text, 'ESCALATED'::text])
UNION ALL
 SELECT 'FOLLOW_UP'::text AS source_type,
    fa.id AS source_id,
    fa.id::text AS source_ref,
    fa.employer_id,
    fa.employer_name,
    NULL::character varying AS territory,
    fa.priority,
    fa.status AS source_status,
    NULL::numeric AS financial_exposure,
    fa.due_date::timestamp with time zone AS due_date,
    fa.assigned_to_user_id::text AS assigned_to_user_id,
    fa.created_at AS source_created_at,
    (('Follow-up: '::text || COALESCE(fa.action_type, ''::character varying)::text) || ' - '::text) || COALESCE(fa.description, ''::text) AS description
   FROM ce_follow_up_actions fa
  WHERE fa.status::text = ANY (ARRAY['PLANNED'::text, 'SCHEDULED'::text, 'OVERDUE'::text])
UNION ALL
 SELECT 'SCOUTING_LEAD'::text AS source_type,
    sl.id AS source_id,
    sl.lead_number AS source_ref,
    sl.linked_employer_id AS employer_id,
    sl.business_name AS employer_name,
    sl.territory,
    sl.confidence_level AS priority,
    sl.status AS source_status,
    NULL::numeric AS financial_exposure,
    NULL::timestamp with time zone AS due_date,
    sl.assigned_to_user_id::text AS assigned_to_user_id,
    sl.created_at AS source_created_at,
    (('Scouting: '::text || COALESCE(sl.lead_type, ''::character varying)::text) || ' - '::text) || COALESCE(sl.business_name, sl.location_description::character varying, ''::character varying)::text AS description
   FROM ce_scouting_leads sl
  WHERE sl.status::text = ANY (ARRAY['NEW'::text, 'UNDER_INVESTIGATION'::text])
UNION ALL
 SELECT 'CASE'::text AS source_type,
    c.id AS source_id,
    c.case_number AS source_ref,
    c.employer_id,
    c.employer_name,
    NULL::character varying AS territory,
    c.priority,
    c.status AS source_status,
    c.total_amount AS financial_exposure,
    NULL::timestamp with time zone AS due_date,
    c.assigned_officer_id::text AS assigned_to_user_id,
    c.created_at AS source_created_at,
    (('Case: '::text || COALESCE(c.case_number, ''::character varying)::text) || ' - '::text) || COALESCE(c.summary, ''::text) AS description
   FROM ce_cases c
  WHERE c.status::text = ANY (ARRAY['ACTIVE'::text, 'ESCALATED_LEGAL'::text])
UNION ALL
 SELECT 'NOTICE'::text AS source_type,
    n.id AS source_id,
    n.notice_number AS source_ref,
    n.employer_id,
    n.employer_name,
    NULL::character varying AS territory,
    'MEDIUM'::character varying AS priority,
    n.status AS source_status,
    NULL::numeric AS financial_exposure,
    n.due_response_date::timestamp with time zone AS due_date,
    NULL::text AS assigned_to_user_id,
    n.created_at AS source_created_at,
    (('Notice: '::text || COALESCE(n.notice_number, ''::character varying)::text) || ' response due '::text) || COALESCE(n.due_response_date::text, 'N/A'::text) AS description
   FROM ce_notices n
  WHERE (n.status::text = ANY (ARRAY['SENT'::text, 'DELIVERED'::text])) AND n.due_response_date IS NOT NULL AND n.due_response_date >= CURRENT_DATE;
CREATE OR REPLACE VIEW public.ce_v_weekly_plan_versions AS
 SELECT COALESCE(parent_plan_id, id) AS plan_family_id,
    id,
    plan_number,
    version_no,
    is_current_version,
    status,
    inspector_id,
    inspector_name,
    zone_id,
    week_start_date,
    week_end_date,
    parent_plan_id,
    revision_reason,
    superseded_at,
    superseded_by_plan_id,
    submitted_date,
    approved_date,
    approved_by,
    created_at,
    updated_at
   FROM ce_weekly_plans p;
CREATE OR REPLACE VIEW public.ce_v_weekly_report_summary AS
 SELECT p.id AS plan_id,
    p.plan_number,
    p.inspector_id,
    p.inspector_name,
    p.week_start_date,
    p.week_end_date,
    p.status AS plan_status,
    count(i.id) AS total_planned,
    count(i.id) FILTER (WHERE i.execution_status::text = 'COMPLETED'::text) AS completed_visits,
    count(i.id) FILTER (WHERE i.execution_status::text = 'RESCHEDULED'::text) AS rescheduled_visits,
    count(i.id) FILTER (WHERE i.execution_status::text = 'CANCELLED'::text) AS cancelled_visits,
    count(i.id) FILTER (WHERE i.execution_status::text = 'NOT_DONE'::text) AS not_done_visits,
    count(i.id) FILTER (WHERE i.execution_status::text = 'PLANNED'::text) AS still_planned,
    COALESCE(round(sum(
        CASE
            WHEN i.check_in_time IS NOT NULL AND i.check_out_time IS NOT NULL THEN EXTRACT(epoch FROM i.check_out_time - i.check_in_time) / 3600.0
            ELSE 0::numeric
        END), 1), 0::numeric) AS total_hours,
    COALESCE(( SELECT count(*) AS count
           FROM ce_inspection_evidence e
             JOIN ce_inspections insp ON insp.id = e.inspection_id
          WHERE insp.scheduled_date >= p.week_start_date AND insp.scheduled_date <= p.week_end_date AND insp.inspector_id::text = p.inspector_id::text), 0::bigint) AS evidence_count,
    COALESCE(( SELECT count(*) AS count
           FROM ce_inspection_findings f
             JOIN ce_inspections insp ON insp.id = f.inspection_id
          WHERE insp.scheduled_date >= p.week_start_date AND insp.scheduled_date <= p.week_end_date AND insp.inspector_id::text = p.inspector_id::text), 0::bigint) AS findings_count,
    COALESCE(( SELECT count(*) AS count
           FROM ce_inspection_findings f
             JOIN ce_inspections insp ON insp.id = f.inspection_id
          WHERE insp.scheduled_date >= p.week_start_date AND insp.scheduled_date <= p.week_end_date AND insp.inspector_id::text = p.inspector_id::text AND f.violation_created = true), 0::bigint) AS violations_created,
    p.outcome_narrative,
    p.outcome_submitted_at
   FROM ce_weekly_plans p
     LEFT JOIN ce_weekly_plan_items i ON i.plan_id = p.id
  GROUP BY p.id, p.plan_number, p.inspector_id, p.inspector_name, p.week_start_date, p.week_end_date, p.status, p.outcome_narrative, p.outcome_submitted_at;
CREATE OR REPLACE VIEW public.communication_hub_trace_unified_view AS
 SELECT t.id AS trace_id,
    t.trace_no,
    'native'::text AS trace_kind,
    t.module_code,
    t.event_code,
    t.channel,
    t.entity_type,
    t.entity_id,
    t.reference_no,
    t.recipient_email_masked,
    t.recipient_domain,
    t.status,
    t.current_stage,
    t.blocked_stage,
    t.blocker_codes,
    t.request_id,
    t.request_no,
    t.message_id,
    t.provider_message_id,
    t.correlation_id,
    t.source_module,
    t.created_at,
    t.updated_at,
    NULL::text AS reconstructed_note
   FROM communication_hub_trace t
UNION ALL
 SELECT r.id AS trace_id,
    'REC-'::text || r.request_no AS trace_no,
    'reconstructed'::text AS trace_kind,
    r.module_code,
    r.event_code,
    COALESCE(m.channel, 'email'::text) AS channel,
    r.entity_type,
    r.entity_id,
    r.reference_no,
    _ch_mask_email(cr.email) AS recipient_email_masked,
    _ch_extract_domain(cr.email) AS recipient_domain,
    COALESCE(r.status, 'unknown'::text) AS status,
    NULL::text AS current_stage,
    NULL::text AS blocked_stage,
    '{}'::text[] AS blocker_codes,
    r.id AS request_id,
    r.request_no,
    m.id AS message_id,
    m.provider_message_id,
    NULLIF(r.context ->> 'correlation_id'::text, ''::text) AS correlation_id,
    r.module_code AS source_module,
    r.created_at,
    COALESCE(r.updated_at, r.created_at) AS updated_at,
    'Legacy trace reconstructed from request/message/event logs'::text AS reconstructed_note
   FROM communication_request r
     LEFT JOIN LATERAL ( SELECT cm.id,
            cm.channel,
            cm.provider_message_id
           FROM communication_message cm
          WHERE cm.request_id = r.id
          ORDER BY cm.created_at
         LIMIT 1) m ON true
     LEFT JOIN LATERAL ( SELECT crx.email
           FROM communication_recipient crx
          WHERE crx.request_id = r.id
          ORDER BY crx.created_at
         LIMIT 1) cr ON true
  WHERE NOT (EXISTS ( SELECT 1
           FROM communication_hub_trace t2
          WHERE t2.request_id = r.id));
