CREATE OR REPLACE VIEW public.dashboard_v_active_alerts AS
 SELECT 'critical'::text AS severity,
    count(*) || ' violations overdue'::text AS title,
    'Past due date and unresolved'::text AS detail,
    'Action required'::text AS time_label
   FROM ce_violations
  WHERE ce_violations.due_date < now() AND (ce_violations.status::text <> ALL (ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying, 'DISMISSED'::character varying]::text[])) AND (ce_violations.is_deleted = false OR ce_violations.is_deleted IS NULL)
 HAVING count(*) > 0
UNION ALL
 SELECT 'warning'::text AS severity,
    count(*) || ' inspections pending'::text AS title,
    'Scheduled inspections not yet started'::text AS detail,
    'Review'::text AS time_label
   FROM ce_inspections
  WHERE (ce_inspections.status::text = ANY (ARRAY['SCHEDULED'::character varying, 'PENDING'::character varying]::text[])) AND ce_inspections.scheduled_date <= (now() + '7 days'::interval)::date
 HAVING count(*) > 0
UNION ALL
 SELECT 'warning'::text AS severity,
    count(*) || ' active breach monitors'::text AS title,
    'Payment arrangements at risk'::text AS detail,
    'Monitor'::text AS time_label
   FROM ce_breach_monitoring
  WHERE ce_breach_monitoring.status = 'ACTIVE'::text
 HAVING count(*) > 0;
CREATE OR REPLACE VIEW public.dashboard_v_admin_kpis AS
 SELECT (( SELECT count(*) AS count
           FROM er_master
          WHERE er_master.status = 'A'::bpchar))::integer AS total_employers,
    (( SELECT COALESCE(sum(COALESCE(er_master.males_employed, 0::double precision) + COALESCE(er_master.females_employed, 0::double precision)), 0::double precision) AS "coalesce"
           FROM er_master
          WHERE er_master.status = 'A'::bpchar))::integer AS insured_persons,
    (( SELECT count(*) AS count
           FROM cl_head
          WHERE cl_head.status = ANY (ARRAY['A'::bpchar, 'P'::bpchar, 'O'::bpchar])))::integer AS active_claims,
    (( SELECT count(*) AS count
           FROM ce_violations
          WHERE (ce_violations.status::text <> ALL (ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying, 'DISMISSED'::character varying]::text[])) AND (ce_violations.is_deleted = false OR ce_violations.is_deleted IS NULL)))::integer AS compliance_issues;
CREATE OR REPLACE VIEW public.dashboard_v_benefits_distribution AS
 SELECT
        CASE claim_type_code
            WHEN 'S'::text THEN 'Sickness'::character varying
            WHEN 'M'::text THEN 'Maternity'::character varying
            WHEN 'A'::text THEN 'Age'::character varying
            WHEN 'I'::text THEN 'Invalidity'::character varying
            WHEN 'F'::text THEN 'Funeral'::character varying
            WHEN 'E'::text THEN 'Employment Injury'::character varying
            WHEN 'V'::text THEN 'Survivors'::character varying
            ELSE COALESCE(claim_type_code, 'Other'::character varying)
        END AS type,
    COALESCE(sum(benefit_amount), 0::numeric) AS amount,
    count(*)::integer AS claim_count
   FROM cl_head
  GROUP BY claim_type_code
  ORDER BY (COALESCE(sum(benefit_amount), 0::numeric)) DESC;
CREATE OR REPLACE VIEW public.dashboard_v_contribution_trend AS
 WITH months AS (
         SELECT to_char(d.d, 'YYYY-MM'::text) AS month_key,
            to_char(d.d, 'Mon'::text) AS month_label
           FROM generate_series(date_trunc('month'::text, now() - '11 mons'::interval), date_trunc('month'::text, now()), '1 mon'::interval) d(d)
        ), c3 AS (
         SELECT to_char(cn_c3_reported.period::timestamp with time zone, 'YYYY-MM'::text) AS month_key,
            sum(COALESCE(cn_c3_reported.emp_ss_amt_rpt, cn_c3_reported.emp_ss_amt_calc, 0::numeric) + COALESCE(cn_c3_reported.emp_pe_amt_rpt, cn_c3_reported.emp_pe_amt_calc, 0::numeric) + COALESCE(cn_c3_reported.emp_levy_amt_rpt, cn_c3_reported.emp_levy_amt_calc, 0::numeric)) AS contributions
           FROM cn_c3_reported
          WHERE cn_c3_reported.period >= date_trunc('month'::text, now() - '11 mons'::interval)::date
          GROUP BY (to_char(cn_c3_reported.period::timestamp with time zone, 'YYYY-MM'::text))
        ), claims AS (
         SELECT to_char(cl_head.date_approved, 'YYYY-MM'::text) AS month_key,
            sum(COALESCE(cl_head.benefit_amount, 0::numeric)) AS benefits
           FROM cl_head
          WHERE cl_head.date_approved >= date_trunc('month'::text, now() - '11 mons'::interval)
          GROUP BY (to_char(cl_head.date_approved, 'YYYY-MM'::text))
        )
 SELECT m.month_label AS month,
    m.month_key,
    COALESCE(c.contributions, 0::numeric) AS contributions,
    COALESCE(cl.benefits, 0::numeric) AS benefits
   FROM months m
     LEFT JOIN c3 c ON c.month_key = m.month_key
     LEFT JOIN claims cl ON cl.month_key = m.month_key
  ORDER BY m.month_key;
CREATE OR REPLACE VIEW public.dashboard_v_employer_compliance_alerts AS
 SELECT rp.employer_id,
    rp.employer_name,
    cs.overall_compliance_status,
    rp.total_score AS risk_score,
    COALESCE(rp.override_band, rp.risk_band) AS risk_band,
    cs.active_violation_count,
    cs.current_arrears_amount,
    cs.last_computed_at
   FROM ce_risk_profiles rp
     LEFT JOIN ce_employer_compliance_status cs ON cs.employer_id::text = rp.employer_id::text
  WHERE (COALESCE(rp.override_band, rp.risk_band)::text = ANY (ARRAY['High'::character varying, 'Critical'::character varying]::text[])) OR COALESCE(cs.active_violation_count, 0) > 0
  ORDER BY rp.total_score DESC NULLS LAST
 LIMIT 50;
CREATE OR REPLACE VIEW public.dashboard_v_employer_compliance_status AS
 WITH active_employers AS (
         SELECT er_master.regno::text AS employer_id
           FROM er_master
          WHERE er_master.status = 'A'::bpchar
        ), latest_status AS (
         SELECT DISTINCT ON (s.employer_id) s.employer_id,
            s.compliance_status,
            s.overall_compliance_status,
            s.last_computed_at
           FROM ce_employer_compliance_status s
          WHERE s.overall_compliance_status IS NOT NULL
          ORDER BY s.employer_id, s.last_computed_at DESC NULLS LAST, s.updated_at DESC NULLS LAST
        ), open_violations AS (
         SELECT v.employer_id,
            max(
                CASE v.severity
                    WHEN 'CRITICAL'::text THEN 4
                    WHEN 'HIGH'::text THEN 3
                    WHEN 'MEDIUM'::text THEN 2
                    WHEN 'LOW'::text THEN 1
                    ELSE 0
                END) AS max_sev
           FROM ce_violations v
          WHERE v.employer_id IS NOT NULL AND (v.status::text <> ALL (ARRAY['RESOLVED'::text, 'CLOSED'::text, 'DISMISSED'::text])) AND (v.is_deleted = false OR v.is_deleted IS NULL)
          GROUP BY v.employer_id
        )
 SELECT ae.employer_id,
        CASE
            WHEN ls.overall_compliance_status IS NOT NULL THEN
            CASE
                WHEN ls.overall_compliance_status::text = ANY (ARRAY['non_compliant'::text, 'critical'::text]) THEN 'Non-Compliant'::text
                WHEN ls.overall_compliance_status::text = 'partially_compliant'::text AND ls.compliance_status::text = 'under_review'::text THEN 'Under Review'::text
                WHEN ls.overall_compliance_status::text = 'partially_compliant'::text THEN 'Minor Issues'::text
                WHEN ls.overall_compliance_status::text = 'compliant'::text THEN 'Compliant'::text
                ELSE 'Under Review'::text
            END
            WHEN ov.max_sev IS NULL THEN 'Compliant'::text
            WHEN ov.max_sev >= 3 THEN 'Non-Compliant'::text
            WHEN ov.max_sev = 2 THEN 'Under Review'::text
            WHEN ov.max_sev = 1 THEN 'Minor Issues'::text
            ELSE 'Compliant'::text
        END AS bucket
   FROM active_employers ae
     LEFT JOIN latest_status ls ON ls.employer_id::text = ae.employer_id
     LEFT JOIN open_violations ov ON ov.employer_id::text = ae.employer_id;
CREATE OR REPLACE VIEW public.dashboard_v_financial_summary AS
 SELECT COALESCE(( SELECT sum(COALESCE(cn_c3_reported.emp_ss_amt_rpt, cn_c3_reported.emp_ss_amt_calc, 0::numeric) + COALESCE(cn_c3_reported.emp_pe_amt_rpt, cn_c3_reported.emp_pe_amt_calc, 0::numeric) + COALESCE(cn_c3_reported.emp_levy_amt_rpt, cn_c3_reported.emp_levy_amt_calc, 0::numeric)) AS sum
           FROM cn_c3_reported
          WHERE cn_c3_reported.period >= date_trunc('month'::text, now())::date), 0::numeric) AS monthly_contributions,
    COALESCE(( SELECT sum(COALESCE(cl_head.benefit_amount, 0::numeric)) AS sum
           FROM cl_head
          WHERE cl_head.date_approved >= date_trunc('month'::text, now())), 0::numeric) AS benefits_paid_mtd,
    COALESCE(( SELECT sum(COALESCE(cn_c3_reported.emp_ss_amt_rpt, cn_c3_reported.emp_ss_amt_calc, 0::numeric) + COALESCE(cn_c3_reported.emp_pe_amt_rpt, cn_c3_reported.emp_pe_amt_calc, 0::numeric) + COALESCE(cn_c3_reported.emp_levy_amt_rpt, cn_c3_reported.emp_levy_amt_calc, 0::numeric)) AS sum
           FROM cn_c3_reported
          WHERE cn_c3_reported.period >= date_trunc('month'::text, now())::date), 0::numeric) - COALESCE(( SELECT sum(COALESCE(cl_head.benefit_amount, 0::numeric)) AS sum
           FROM cl_head
          WHERE cl_head.date_approved >= date_trunc('month'::text, now())), 0::numeric) AS net_surplus,
    COALESCE(( SELECT sum(COALESCE(ce_violations.total_amount, 0::numeric)) AS sum
           FROM ce_violations
          WHERE (ce_violations.status::text <> ALL (ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying, 'DISMISSED'::character varying]::text[])) AND (ce_violations.is_deleted = false OR ce_violations.is_deleted IS NULL)), 0::numeric) AS outstanding_arrears;
CREATE OR REPLACE VIEW public.dashboard_v_legal_escalation_summary AS
 SELECT COALESCE(current_stage, 'UNKNOWN'::character varying) AS escalation_stage,
    count(*)::integer AS escalation_count,
    COALESCE(sum(amount_in_dispute), 0::numeric) AS total_amount_in_dispute
   FROM ce_legal_escalations le
  GROUP BY current_stage;
CREATE OR REPLACE VIEW public.dashboard_v_payment_arrangement_risk AS
 SELECT COALESCE(status, 'UNKNOWN'::character varying) AS risk_status,
    count(*)::integer AS arrangement_count,
    COALESCE(sum(total_debt), 0::numeric) AS total_debt,
    COALESCE(sum(total_paid), 0::numeric) AS total_paid,
    COALESCE(sum(missed_payments), 0::bigint)::integer AS total_missed_payments
   FROM ce_payment_arrangements pa
  GROUP BY status;
CREATE OR REPLACE VIEW public.dashboard_v_recent_activity AS
 SELECT activity_type,
    action,
    entity,
    occurred_at
   FROM ( SELECT 'violation'::text AS activity_type,
            'Compliance violation: '::text || COALESCE(ce_violations.summary, ce_violations.violation_number::text) AS action,
            (COALESCE(ce_violations.employer_name, 'Unknown'::character varying)::text || ' – '::text) || ce_violations.violation_number::text AS entity,
            ce_violations.created_at AS occurred_at
           FROM ce_violations
          WHERE ce_violations.is_deleted = false OR ce_violations.is_deleted IS NULL
        UNION ALL
         SELECT 'inspection'::text AS text,
            (('Inspection '::text || COALESCE(ce_inspections.status, ''::character varying)::text) || ': '::text) || COALESCE(ce_inspections.inspection_type, ''::character varying)::text,
            (COALESCE(ce_inspections.employer_name, 'Unknown'::character varying)::text || ' – '::text) || COALESCE(ce_inspections.inspector_name, ''::character varying)::text,
            COALESCE(ce_inspections.actual_start, ce_inspections.scheduled_date::timestamp without time zone::timestamp with time zone) AS "coalesce"
           FROM ce_inspections) sub
  ORDER BY occurred_at DESC
 LIMIT 10;
CREATE OR REPLACE VIEW public.dashboard_v_registration_pipeline AS
 SELECT stage,
    count,
    fill
   FROM ( VALUES ('Active'::text,(( SELECT count(*) AS count
                   FROM er_master
                  WHERE er_master.status = 'A'::bpchar))::integer,'hsl(144 65% 34%)'::text), ('Pending'::text,(( SELECT count(*) AS count
                   FROM er_master
                  WHERE er_master.status = 'P'::bpchar))::integer,'hsl(44 90% 57%)'::text), ('Suspended'::text,(( SELECT count(*) AS count
                   FROM er_master
                  WHERE er_master.status = 'S'::bpchar))::integer,'hsl(217 91% 60%)'::text), ('Terminated'::text,(( SELECT count(*) AS count
                   FROM er_master
                  WHERE er_master.status = 'T'::bpchar))::integer,'hsl(2 74% 50%)'::text), ('De-registered'::text,(( SELECT count(*) AS count
                   FROM er_master
                  WHERE er_master.status = 'D'::bpchar))::integer,'hsl(153 73% 21%)'::text)) t(stage, count, fill);
CREATE OR REPLACE VIEW public.dashboard_v_sector_compliance AS
 SELECT COALESCE(sector_code, 'Unknown'::bpchar) AS sector,
    count(*)::integer AS total,
    count(*) FILTER (WHERE NOT (regno::text IN ( SELECT DISTINCT ce_violations.employer_id
           FROM ce_violations
          WHERE (ce_violations.status::text <> ALL (ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying, 'DISMISSED'::character varying]::text[])) AND (ce_violations.is_deleted = false OR ce_violations.is_deleted IS NULL) AND ce_violations.employer_id IS NOT NULL)))::integer AS compliant,
        CASE
            WHEN count(*) > 0 THEN round(100.0 * count(*) FILTER (WHERE NOT (regno::text IN ( SELECT DISTINCT ce_violations.employer_id
               FROM ce_violations
              WHERE (ce_violations.status::text <> ALL (ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying, 'DISMISSED'::character varying]::text[])) AND (ce_violations.is_deleted = false OR ce_violations.is_deleted IS NULL) AND ce_violations.employer_id IS NOT NULL)))::numeric / count(*)::numeric)::integer
            ELSE 100
        END AS rate
   FROM er_master e
  WHERE status = 'A'::bpchar
  GROUP BY sector_code
  ORDER BY (count(*)::integer) DESC;
CREATE OR REPLACE VIEW public.legal_reference AS
 SELECT id,
    country_code,
    ref_code,
    ref_type,
    short_title,
    act_name,
    chapter,
    section,
    subsection,
    regulation,
    full_reference_text,
    ref_url,
    jurisdiction,
    source,
    effective_from,
    effective_to,
    status,
    version_number,
    supersedes_id,
    tags,
    notes,
    is_active,
    legacy_id,
    created_by,
    created_at,
    updated_by,
    updated_at,
    applicable_products
   FROM core_legal_reference;
CREATE OR REPLACE VIEW public.lg_case_team_summary AS
 SELECT assigned_team_code,
    assigned_legal_officer_id,
    status_code,
    priority_code,
    count(*)::integer AS case_count
   FROM lg_case lc
  GROUP BY assigned_team_code, assigned_legal_officer_id, status_code, priority_code;
CREATE OR REPLACE VIEW public.lg_staff_workload AS
 SELECT s.id AS staff_id,
    s.user_id,
    s.user_code,
    s.full_name,
    s.team_id,
    s.max_active_cases,
    s.max_high_priority_cases,
    s.availability,
    COALESCE(open.cnt, 0) AS active_cases,
    COALESCE(hi.cnt, 0) AS high_priority_cases,
        CASE
            WHEN s.max_active_cases > 0 THEN round(COALESCE(open.cnt, 0)::numeric / s.max_active_cases::numeric * 100::numeric, 1)
            ELSE 0::numeric
        END AS capacity_pct
   FROM lg_staff s
     LEFT JOIN LATERAL ( SELECT count(*)::integer AS cnt
           FROM lg_case_assignment a
             JOIN lg_case c ON c.id = a.lg_case_id
          WHERE a.assigned_to_user_id = s.user_id AND a.is_current = true AND (c.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[]))) open ON true
     LEFT JOIN LATERAL ( SELECT count(*)::integer AS cnt
           FROM lg_case_assignment a
             JOIN lg_case c ON c.id = a.lg_case_id
          WHERE a.assigned_to_user_id = s.user_id AND a.is_current = true AND (c.priority_code::text = ANY (ARRAY['HIGH'::character varying, 'URGENT'::character varying, 'CRITICAL'::character varying]::text[])) AND (c.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[]))) hi ON true;
CREATE OR REPLACE VIEW public.lg_team_metrics AS
 SELECT t.id AS team_id,
    t.team_code,
    t.team_name,
    t.manager_user_id,
    COALESCE(c.open_cases, 0::bigint) AS open_cases,
    COALESCE(c.assigned_cases, 0::bigint) AS assigned_cases,
    COALESCE(c.unassigned_cases, 0::bigint) AS unassigned_cases,
    COALESCE(c.high_priority, 0::bigint) AS high_priority_cases,
    COALESCE(c.avg_age_days, 0::numeric) AS avg_age_days,
    COALESCE(s.total_capacity, 0) AS total_capacity,
    COALESCE(s.current_load, 0) AS current_load,
        CASE
            WHEN COALESCE(s.total_capacity, 0) > 0 THEN round(COALESCE(s.current_load, 0)::numeric / s.total_capacity::numeric * 100::numeric, 1)
            ELSE 0::numeric
        END AS capacity_pct
   FROM lg_team t
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE lc.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[])) AS open_cases,
            count(*) FILTER (WHERE lc.assigned_legal_officer_id IS NOT NULL AND (lc.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[]))) AS assigned_cases,
            count(*) FILTER (WHERE lc.assigned_legal_officer_id IS NULL AND (lc.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[]))) AS unassigned_cases,
            count(*) FILTER (WHERE (lc.priority_code::text = ANY (ARRAY['HIGH'::character varying, 'URGENT'::character varying, 'CRITICAL'::character varying]::text[])) AND (lc.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[]))) AS high_priority,
            round(avg(EXTRACT(epoch FROM now() - lc.opened_date::timestamp with time zone) / 86400::numeric) FILTER (WHERE lc.status_code::text <> ALL (ARRAY['CLOSED'::character varying, 'WITHDRAWN'::character varying, 'DISMISSED'::character varying]::text[]))) AS avg_age_days
           FROM lg_case lc
          WHERE lc.assigned_team_code::text = t.team_code::text) c ON true
     LEFT JOIN LATERAL ( SELECT sum(s_1.max_active_cases)::integer AS total_capacity,
            sum(w.active_cases)::integer AS current_load
           FROM lg_staff s_1
             LEFT JOIN lg_staff_workload w ON w.staff_id = s_1.id
          WHERE s_1.team_id = t.id AND s_1.is_active = true AND s_1.availability::text = 'available'::text) s ON true;
CREATE OR REPLACE VIEW public.module_legal_reference_mapping AS
 SELECT id,
    module_code,
    entity_table,
    entity_id,
    legal_reference_id,
    role,
    notes,
    created_by,
    created_at,
    updated_by,
    updated_at,
    entity_type,
    usage_context,
    is_required,
    is_default
   FROM core_module_legal_reference;
CREATE OR REPLACE VIEW public.v_bn_communication_log_unified AS
 SELECT 'legacy_bn'::text AS source,
    b.id AS row_id,
    NULL::uuid AS request_id,
    NULL::uuid AS message_id,
    b.claim_id::text AS claim_id,
    b.event_code::text AS event_code,
    b.channel::text AS channel,
    b.recipient_address,
    b.subject,
    b.status::text AS status,
    b.provider_message_id,
    b.error_message,
    b.retry_count,
    NULL::timestamp with time zone AS sent_at,
    NULL::timestamp with time zone AS delivered_at,
    b.created_at
   FROM bn_communication_log b
UNION ALL
 SELECT 'hub'::text AS source,
    m.id AS row_id,
    m.request_id,
    m.id AS message_id,
    r.entity_id AS claim_id,
    r.event_code,
    m.channel,
    NULL::text AS recipient_address,
    m.subject,
    m.status,
    m.provider_message_id,
    m.error_message,
    m.attempt_count AS retry_count,
    m.sent_at,
    m.delivered_at,
    m.created_at
   FROM communication_message m
     JOIN communication_request r ON r.id = m.request_id
  WHERE r.module_code = 'BN'::text AND r.entity_type = 'bn_claim'::text;
CREATE OR REPLACE VIEW public.v_bn_config_lifecycle AS
 SELECT 'bn_country_participant_type'::text AS entity_type,
    bn_country_participant_type.id::text AS entity_id,
    bn_normalise_lifecycle(bn_country_participant_type.lifecycle_status) AS lifecycle_state
   FROM bn_country_participant_type
UNION ALL
 SELECT 'bn_reference_value'::text AS entity_type,
    core_reference_value.id::text AS entity_id,
    bn_normalise_lifecycle(
        CASE
            WHEN core_reference_value.is_active THEN 'ACTIVE'::text
            ELSE 'RETIRED'::text
        END) AS lifecycle_state
   FROM core_reference_value
UNION ALL
 SELECT 'bn_product_version'::text AS entity_type,
    bn_product_version.id::text AS entity_id,
    bn_normalise_lifecycle(bn_product_version.status::text) AS lifecycle_state
   FROM bn_product_version
UNION ALL
 SELECT 'bn_formula_version'::text AS entity_type,
    bn_formula_version.id::text AS entity_id,
    bn_normalise_lifecycle(COALESCE(bn_formula_version.governance_status::text,
        CASE
            WHEN bn_formula_version.is_active THEN 'ACTIVE'::text
            ELSE 'DRAFT'::text
        END)) AS lifecycle_state
   FROM bn_formula_version
UNION ALL
 SELECT 'bn_rate_table'::text AS entity_type,
    bn_rate_table.id::text AS entity_id,
    bn_normalise_lifecycle(bn_rate_table.status::text) AS lifecycle_state
   FROM bn_rate_table
UNION ALL
 SELECT 'bn_medical_tariff_table'::text AS entity_type,
    bn_medical_tariff_table.id::text AS entity_id,
    bn_normalise_lifecycle(bn_medical_tariff_table.status::text) AS lifecycle_state
   FROM bn_medical_tariff_table
UNION ALL
 SELECT 'bn_rule_catalogue'::text AS entity_type,
    bn_rule_catalogue.id::text AS entity_id,
    bn_normalise_lifecycle(bn_rule_catalogue.rule_status::text) AS lifecycle_state
   FROM bn_rule_catalogue
UNION ALL
 SELECT 'bn_formula_template'::text AS entity_type,
    bn_formula_template.id::text AS entity_id,
    bn_normalise_lifecycle(COALESCE(bn_formula_template.governance_status::text,
        CASE
            WHEN bn_formula_template.is_active THEN 'ACTIVE'::text
            ELSE 'DRAFT'::text
        END)) AS lifecycle_state
   FROM bn_formula_template;
CREATE OR REPLACE VIEW public.v_bn_participant_type_usage AS
 WITH product_use AS (
         SELECT p.country_code,
            roles.role_code AS type_code,
            count(DISTINCT pv.id) AS product_version_count,
            count(DISTINCT pv.id) FILTER (WHERE pv.status::text = 'ACTIVE'::text) AS active_product_count
           FROM bn_product_participant_config ppc
             JOIN bn_product_version pv ON pv.id = ppc.product_version_id
             JOIN bn_product p ON p.id = pv.product_id
             CROSS JOIN LATERAL ( SELECT jsonb_array_elements_text((COALESCE(to_jsonb(ppc.required_roles), '[]'::jsonb) || COALESCE(to_jsonb(ppc.optional_roles), '[]'::jsonb)) || COALESCE(to_jsonb(ppc.allowed_applicant_kinds), '[]'::jsonb)) AS role_code) roles
          GROUP BY p.country_code, roles.role_code
        ), claim_use AS (
         SELECT p.country_code,
            cp.participant_type AS type_code,
            count(*) AS historical_claim_count
           FROM bn_claim_participant cp
             JOIN bn_claim c ON c.id = cp.claim_id
             JOIN bn_product p ON p.id = c.product_id
          WHERE cp.participant_type IS NOT NULL
          GROUP BY p.country_code, cp.participant_type
        )
 SELECT COALESCE(pu.country_code, cu.country_code) AS country_code,
    COALESCE(pu.type_code, cu.type_code) AS type_code,
    COALESCE(pu.product_version_count, 0::bigint) AS product_version_count,
    COALESCE(pu.active_product_count, 0::bigint) AS active_product_count,
    COALESCE(cu.historical_claim_count, 0::bigint) AS historical_claim_count
   FROM product_use pu
     FULL JOIN claim_use cu ON pu.country_code::text = cu.country_code::text AND pu.type_code = cu.type_code;
CREATE OR REPLACE VIEW public.v_bn_product_effective_payment_config AS
 SELECT pcc.id AS channel_config_id,
    pcc.product_id,
    pcc.product_version_id,
    pcc.channel_code,
    p.benefit_code,
    p.country_code,
    c.currency_code AS country_currency,
    c.allow_foreign_currency_products,
    c.allowed_alt_currencies,
    COALESCE(pcc.currency_code, c.currency_code) AS effective_currency,
    pcc.allowed_payment_methods AS product_allowed_methods,
    ARRAY( SELECT cpc.payment_method
           FROM bn_country_payment_config cpc
          WHERE cpc.country_code::text = p.country_code::text AND cpc.is_active AND cpc.is_method_enabled) AS country_enabled_methods,
        CASE
            WHEN pcc.payment_frequency IS NULL THEN NULL::character varying[]
            WHEN NOT (EXISTS ( SELECT 1
               FROM bn_country_payment_cycle_method m
              WHERE m.country_code::text = p.country_code::text AND m.payment_cycle::text = pcc.payment_frequency)) THEN NULL::character varying[]
            ELSE ARRAY( SELECT m.payment_method
               FROM bn_country_payment_cycle_method m
              WHERE m.country_code::text = p.country_code::text AND m.payment_cycle::text = pcc.payment_frequency AND m.is_enabled = true AND (m.effective_from IS NULL OR m.effective_from <= CURRENT_DATE) AND (m.effective_to IS NULL OR m.effective_to >= CURRENT_DATE))
        END AS cycle_enabled_methods,
    pcc.default_payment_method,
    pcc.payment_frequency,
    pcc.payment_pattern,
    pcc.allow_payee,
    pcc.allow_provider_direct_pay,
    pcc.approval_threshold_amount,
    pcc.approval_threshold_currency,
    pcc.payment_hold_rules
   FROM bn_product_channel_config pcc
     JOIN bn_product p ON p.id = pcc.product_id
     JOIN bn_country c ON c.country_code::text = p.country_code::text;
CREATE OR REPLACE VIEW public.v_bn_product_public_config_issues AS
 WITH cfg AS (
         SELECT pcc.id AS channel_config_id,
            pcc.product_id,
            pcc.product_version_id,
            pcc.public_online_enabled,
            pcc.allowed_applicant_types,
            pcc.allow_apply_for_self,
            pcc.allow_apply_for_deceased,
            pcc.allow_apply_for_child_dependant,
            pcc.allow_apply_as_guardian,
            pcc.allow_apply_as_payee,
            pcc.allow_apply_as_representative,
            pcc.allow_employer_initiated,
            pcc.allow_doctor_initiated,
            pcc.requires_self_verified_ssn,
            pcc.requires_deceased_person,
            pcc.requires_active_award,
            pcc.requires_existing_ei_claim,
            pcc.public_screen_template_id,
            pcc.applicant_must_equal_insured,
            p.benefit_code,
            p.benefit_name
           FROM bn_product_channel_config pcc
             LEFT JOIN bn_product p ON p.id = pcc.product_id
          WHERE pcc.channel_code::text = 'ONLINE'::text AND pcc.public_online_enabled = true
        )
 SELECT cfg.channel_config_id,
    cfg.product_id,
    cfg.product_version_id,
    cfg.benefit_code,
    cfg.benefit_name,
    'MISSING_PUBLIC_TEMPLATE'::text AS issue_code,
    'Public-enabled but public_screen_template_id is NULL'::text AS issue_message
   FROM cfg
  WHERE cfg.public_screen_template_id IS NULL
UNION ALL
 SELECT cfg.channel_config_id,
    cfg.product_id,
    cfg.product_version_id,
    cfg.benefit_code,
    cfg.benefit_name,
    'SELF_ONLY_MISSING_SSN_REQ'::text AS issue_code,
    'Self-only product must require a verified SELF SSN'::text AS issue_message
   FROM cfg
  WHERE cfg.allow_apply_for_self = true AND cfg.allow_apply_for_deceased = false AND cfg.allow_apply_for_child_dependant = false AND cfg.allow_apply_as_guardian = false AND cfg.allow_apply_as_payee = false AND cfg.allow_apply_as_representative = false AND cfg.requires_self_verified_ssn = false
UNION ALL
 SELECT cfg.channel_config_id,
    cfg.product_id,
    cfg.product_version_id,
    cfg.benefit_code,
    cfg.benefit_name,
    'DECEASED_PRODUCT_MISSING_FLAG'::text AS issue_code,
    'Survivor/funeral product must allow deceased person'::text AS issue_message
   FROM cfg
  WHERE cfg.allow_apply_for_deceased = false AND cfg.requires_deceased_person = true
UNION ALL
 SELECT cfg.channel_config_id,
    cfg.product_id,
    cfg.product_version_id,
    cfg.benefit_code,
    cfg.benefit_name,
    'SERVICE_MISSING_AWARD_REQ'::text AS issue_code,
    'Service product (life/school/EFT) must require an active award'::text AS issue_message
   FROM cfg
  WHERE (cfg.benefit_code::text = ANY (ARRAY['SKN-SVC-LIFE'::character varying, 'SKN-SVC-SCH'::character varying, 'SKN-SVC-EFT'::character varying]::text[])) AND cfg.requires_active_award = false
UNION ALL
 SELECT cfg.channel_config_id,
    cfg.product_id,
    cfg.product_version_id,
    cfg.benefit_code,
    cfg.benefit_name,
    'EIR_VISIBLE_TO_CLAIMANT'::text AS issue_code,
    'Employer Information Request must not appear in claimant apply list'::text AS issue_message
   FROM cfg
  WHERE cfg.benefit_code::text = 'SKN-SVC-EIR'::text;
CREATE OR REPLACE VIEW public.v_bn_user_effective_roles AS
 SELECT ur.user_id,
    ur.role AS role_name,
    'DIRECT'::text AS source
   FROM user_roles ur
UNION
 SELECT ur.user_id,
    brm.role_name,
    'BUNDLE'::text AS source
   FROM user_roles ur
     JOIN bn_role_bundle rb ON rb.code = ur.role AND rb.is_active = true
     JOIN bn_role_bundle_member brm ON brm.bundle_code = rb.code
UNION
 SELECT d.to_user_id AS user_id,
    d.role_name,
    'DELEGATION'::text AS source
   FROM bn_role_delegation d
  WHERE d.status = 'APPROVED'::text AND CURRENT_DATE >= d.valid_from AND CURRENT_DATE <= d.valid_to;
CREATE OR REPLACE VIEW public.v_ce_notice_delivery_log_unified AS
 SELECT 'legacy_ce'::text AS source,
    c.id AS row_id,
    NULL::uuid AS request_id,
    NULL::uuid AS message_id,
    c.notice_id::text AS notice_id,
    c.attempt_number AS attempt_no,
    c.channel::text AS channel,
    c.recipient_address::text AS recipient_address,
    c.status::text AS status,
    c.sent_at,
    c.delivered_at,
    c.failure_reason,
    c.provider_message_id::text AS provider_message_id,
    c.created_at
   FROM ce_notice_delivery_log c
UNION ALL
 SELECT 'hub'::text AS source,
    a.id AS row_id,
    m.request_id,
    m.id AS message_id,
    r.entity_id AS notice_id,
    a.attempt_no,
    m.channel,
    NULL::text AS recipient_address,
    a.status,
    a.started_at AS sent_at,
    a.finished_at AS delivered_at,
    a.error_message AS failure_reason,
    a.provider_message_id,
    a.created_at
   FROM communication_delivery_attempt a
     JOIN communication_message m ON m.id = a.message_id
     JOIN communication_request r ON r.id = m.request_id
  WHERE r.module_code = 'COMPLIANCE'::text AND r.entity_type = 'ce_notice'::text;
CREATE OR REPLACE VIEW public.v_comm_hub_manual_production_evidence AS
 SELECT o.id AS observation_id,
    o.request_id,
    o.message_id,
    o.delivery_attempt_id,
    o.trace_id,
    o.provider_id,
    o.provider_message_id,
    m.status AS message_status,
    a.status AS attempt_status,
    a.send_context,
    m.test_mode,
    o.recipient_email,
    o.inbox_confirmation_status,
    o.dispatched_at,
    o.event_certification_id,
    ec.approved_at AS manual_prod_approved_at,
    ec.status AS event_status,
    p.email_provider_type AS provider_mode,
    p.provider_name AS provider_display_name,
    o.status AS observation_status,
    o.module_code,
    o.event_code,
    o.channel,
    o.configuration_version
   FROM communication_manual_production_observation o
     LEFT JOIN communication_message m ON m.id = o.message_id
     LEFT JOIN communication_delivery_attempt a ON a.id = o.delivery_attempt_id
     LEFT JOIN notification_providers p ON p.id = o.provider_id
     LEFT JOIN communication_hub_event_certification ec ON ec.id = o.event_certification_id;
CREATE OR REPLACE VIEW public.v_comm_hub_transition_log_safe AS
 SELECT id,
    action,
    allowed,
    actor_id,
    context ->> 'actor_type'::text AS actor_type,
    module_code,
    event_code,
    channel,
    correlation_id,
    context - 'context_data'::text - 'to_recipients'::text - 'cc_recipients'::text - 'bcc_recipients'::text - 'subject'::text - 'body_html'::text - 'body_text'::text - 'tokens'::text - 'payload'::text - 'raw_placeholders'::text AS safe_context,
    denied_reasons,
    created_at
   FROM comm_hub_runtime_transition_log;
CREATE OR REPLACE VIEW public.v_communication_message_full AS
 SELECT m.id AS message_id,
    m.request_id,
    r.request_no,
    r.module_code,
    r.department_code,
    r.event_code,
    r.entity_type,
    r.entity_id,
    r.reference_no,
    m.recipient_id,
    m.channel,
    m.provider_id,
    m.subject,
    m.status AS message_status,
    r.status AS request_status,
    m.attempt_count,
    m.last_attempt_at,
    m.next_attempt_at,
    m.sent_at,
    m.delivered_at,
    m.provider_message_id,
    m.error_code,
    m.error_message,
    m.generated_document_id,
    m.created_at,
    m.updated_at,
    ( SELECT max(a.attempt_no) AS max
           FROM communication_delivery_attempt a
          WHERE a.message_id = m.id) AS latest_attempt_no,
    ( SELECT ev.event_type
           FROM communication_event_log ev
          WHERE ev.message_id = m.id
          ORDER BY ev.occurred_at DESC
         LIMIT 1) AS latest_event_type,
    ( SELECT ev.occurred_at
           FROM communication_event_log ev
          WHERE ev.message_id = m.id
          ORDER BY ev.occurred_at DESC
         LIMIT 1) AS latest_event_at
   FROM communication_message m
     JOIN communication_request r ON r.id = m.request_id;
CREATE OR REPLACE VIEW public.v_compliance_classic_reconciliation AS
 WITH RECURSIVE classic_tree AS (
         SELECT app_modules.id,
            app_modules.name,
            app_modules.display_name,
            app_modules.route,
            app_modules.parent_id,
            app_modules.sort_order,
            app_modules.display_name AS classic_path,
            1 AS depth
           FROM app_modules
          WHERE app_modules.id = 'cc000000-0000-0000-0000-000000000001'::uuid
        UNION ALL
         SELECT c.id,
            c.name,
            c.display_name,
            c.route,
            c.parent_id,
            c.sort_order,
            (ct_1.classic_path || ' / '::text) || c.display_name,
            ct_1.depth + 1
           FROM app_modules c
             JOIN classic_tree ct_1 ON c.parent_id = ct_1.id
        )
 SELECT ct.classic_path AS classic_menu_path,
    src.route AS old_route,
    ct.route AS current_route_used,
        CASE
            WHEN ct.route IS NULL THEN 'Section (no route)'::text
            ELSE ct.route
        END AS component,
    ct.id AS db_app_module_id,
    src.name AS permission_source,
        CASE
            WHEN ct.route IS NULL AND ct.id <> 'cc000000-0000-0000-0000-000000000001'::uuid THEN 'OK (Section)'::text
            WHEN ct.route IS NULL THEN 'OK (Root)'::text
            WHEN src.id IS NULL THEN 'Component Missing'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM module_actions ma
              WHERE ma.module_id = ct.id)) THEN 'Permission Missing'::text
            ELSE 'OK'::text
        END AS status
   FROM classic_tree ct
     LEFT JOIN app_modules src ON src.id =
        CASE
            WHEN "substring"(ct.id::text, 1, 2) = 'cc'::text THEN ('ca'::text || "substring"(ct.id::text, 3))::uuid
            WHEN "substring"(ct.id::text, 1, 2) = 'cd'::text THEN ('cb'::text || "substring"(ct.id::text, 3))::uuid
            ELSE NULL::uuid
        END
  ORDER BY ct.classic_path;
CREATE OR REPLACE VIEW public.v_core_legal_referral_packet AS
 SELECT id AS document_link_id,
    referral_id,
    referral_item_id,
    source_module,
    source_entity_type,
    source_entity_id,
    document_source,
    document_type_code,
    document_sub_type_code,
    display_title,
    file_name,
    mime_type,
    file_size,
    storage_bucket,
    storage_path,
    dms_document_id,
    transfer_status,
    is_required,
    is_legal_relevant,
    selected_by,
    selected_at,
    created_at
   FROM core_legal_referral_document d;
CREATE OR REPLACE VIEW public.v_ia_departments AS
 SELECT d.id,
    d.source_department_id,
    COALESCE(m.office_code, d.office_code::character varying) AS office_code,
    COALESCE(m.name, d.name) AS name,
    COALESCE(m.name, d.name) || COALESCE((' ('::text || NULLIF(COALESCE(m.office_code, d.office_code::character varying)::text, ''::text)) || ')'::text, ''::text) AS display_label,
    d.head,
    d.head_profile_id,
    d.email,
    d.phone,
    d.location,
    d.risk_rating,
    d.is_active,
    COALESCE(m.is_active, true) AS master_active,
    d.created_at,
    d.created_by,
    d.updated_at,
    d.updated_by,
    d.tb_office_code
   FROM ia_departments d
     LEFT JOIN tb_office_departments m ON m.id = d.source_department_id;
CREATE OR REPLACE VIEW public.v_legal_advanced_matter_summary AS
 SELECT m.id,
    m.matter_no,
    m.title,
    m.category,
    m.origin,
    m.status,
    m.stage,
    m.priority,
    mt.code AS matter_type_code,
    mt.display_name AS matter_type_name,
    wb.code AS workbasket_code,
    wb.display_name AS workbasket_name,
    m.assigned_user_code,
    m.due_date,
    m.is_legal_created,
    m.has_dms_document,
    m.legal_existing_case_id,
    ( SELECT count(*) AS count
           FROM la_matter_document d
          WHERE d.matter_id = m.id AND d.is_active) AS document_count,
    ( SELECT count(*) AS count
           FROM la_matter_action a
          WHERE a.matter_id = m.id AND (a.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text]))) AS open_action_count,
    m.created_at,
    m.updated_at
   FROM la_matter m
     LEFT JOIN la_matter_type mt ON mt.id = m.matter_type_id
     LEFT JOIN la_workbasket wb ON wb.id = m.current_workbasket_id;
CREATE OR REPLACE VIEW public.v_legal_advanced_source_referrals AS
 SELECT r.id AS referral_id,
    r.referral_no,
    r.source_module,
    r.source_record_id,
    r.source_reference_no,
    r.status AS referral_status,
    r.priority_code,
    r.exposure_amount,
    r.legal_case_id,
    r.created_at,
    m.id AS la_matter_id,
    m.matter_no AS la_matter_no,
    m.status AS la_matter_status
   FROM legal_referral r
     LEFT JOIN la_matter m ON m.source_module = r.source_module AND m.source_ref_id = r.id::text;
CREATE OR REPLACE VIEW public.v_legal_existing_cases_for_advanced AS
 SELECT id AS legal_case_id,
    lg_case_no AS legal_case_no,
    status_code AS legal_case_status,
    current_stage_code AS legal_case_stage,
    case_type_code AS legal_case_type,
    case_category_code AS legal_case_category,
    priority_code AS legal_priority,
    employer_id,
    person_id,
    assigned_legal_officer_id,
    assigned_team_code,
    summary,
    opened_date,
    created_at
   FROM lg_case c;
CREATE OR REPLACE VIEW public.v_lg_case_financials AS
 SELECT lg_case_id,
    count(*) AS liability_count,
    count(*) FILTER (WHERE status = 'ACTIVE'::text) AS active_liability_count,
    count(*) FILTER (WHERE status = 'WRITTEN_OFF'::text) AS writeoff_liability_count,
    COALESCE(sum(principal), 0::numeric)::numeric(18,2) AS total_principal,
    COALESCE(sum(interest), 0::numeric)::numeric(18,2) AS total_interest,
    COALESCE(sum(penalty), 0::numeric)::numeric(18,2) AS total_penalty,
    COALESCE(sum(court_cost), 0::numeric)::numeric(18,2) AS total_court_cost,
    COALESCE(sum(legal_cost), 0::numeric)::numeric(18,2) AS total_legal_cost,
    COALESCE(sum(other_cost), 0::numeric)::numeric(18,2) AS total_other_cost,
    COALESCE(sum(total_assessed), 0::numeric)::numeric(18,2) AS total_assessed,
    COALESCE(sum(paid), 0::numeric)::numeric(18,2) AS total_paid,
    COALESCE(sum(outstanding), 0::numeric)::numeric(18,2) AS total_outstanding,
    COALESCE(sum(total_assessed) FILTER (WHERE status = 'WRITTEN_OFF'::text), 0::numeric)::numeric(18,2) AS total_written_off,
    max(currency) AS currency,
    max(updated_at) AS last_liability_update
   FROM lg_recoverable_liability l
  GROUP BY lg_case_id;
CREATE OR REPLACE VIEW public.v_payment_arrangement_context AS
 SELECT id AS arrangement_id,
    arrangement_no,
    debtor_type,
    debtor_id,
    debtor_name,
    source_module_created_by AS source_module,
    arrangement_type,
    status,
    frequency,
    start_date,
    end_date,
    total_arranged_amount,
    total_paid,
    outstanding_balance,
    default_date,
    superseded_by_arrangement_id,
    superseded_from_arrangement_id,
    ( SELECT min(i.due_date) AS min
           FROM core_payment_schedule_installment i
          WHERE i.arrangement_id = a.id AND (i.status::text = ANY (ARRAY['PLANNED'::character varying, 'DUE'::character varying, 'PARTIAL'::character varying]::text[]))) AS next_due_date,
    ( SELECT count(*) AS count
           FROM core_payment_schedule_installment i
          WHERE i.arrangement_id = a.id AND i.status::text = 'MISSED'::text) AS missed_installments,
    ARRAY( SELECT DISTINCT it.compliance_case_id
           FROM core_payment_arrangement_item it
          WHERE it.arrangement_id = a.id AND it.compliance_case_id IS NOT NULL) AS compliance_case_ids,
    ARRAY( SELECT DISTINCT it.legal_case_id
           FROM core_payment_arrangement_item it
          WHERE it.arrangement_id = a.id AND it.legal_case_id IS NOT NULL) AS legal_case_ids,
    ARRAY( SELECT DISTINCT it.benefit_claim_id
           FROM core_payment_arrangement_item it
          WHERE it.arrangement_id = a.id AND it.benefit_claim_id IS NOT NULL) AS benefit_claim_ids,
    created_at,
    updated_at
   FROM core_payment_arrangement a;
CREATE OR REPLACE VIEW public.v_ssp_party_projection AS
 SELECT 'ip_master'::text AS source_system,
    ip.id::text AS source_id,
    COALESCE(ip.ssn, ip.id::text::character varying) AS legacy_ref,
    'PERSON'::text AS party_kind,
    TRIM(BOTH FROM (COALESCE(ip.firstname, ''::character varying)::text || ' '::text) || COALESCE(ip.surname, ''::character varying)::text) AS display_name,
    ip.ssn AS primary_identifier,
    'SSN'::text AS primary_identifier_type,
    ip.sex::text AS gender,
    ip.dob AS date_of_birth,
    ip.nationality AS nationality_code,
    ip.status::text AS legacy_status,
    ip.district AS geo_area_code,
    ip.mobile,
    ip.telephone AS phone,
    NULL::text AS email,
    ip.created_at,
    ip.updated_at,
    ARRAY['MEMBER'::text, 'CONTRIBUTOR'::text] AS projected_roles
   FROM ip_master ip
UNION ALL
 SELECT 'er_master'::text AS source_system,
    er.regno::text AS source_id,
    er.regno AS legacy_ref,
    'ORGANISATION'::text AS party_kind,
    COALESCE(er.trade_name, er.name) AS display_name,
    er.regno AS primary_identifier,
    'REGNO'::text AS primary_identifier_type,
    NULL::text AS gender,
    NULL::date AS date_of_birth,
    er.hq_country AS nationality_code,
    er.status::text AS legacy_status,
    er.village_code AS geo_area_code,
    er.mobile,
    er.phone,
    er.email,
    er.registration_date::timestamp with time zone AS created_at,
    er.date_modified::timestamp with time zone AS updated_at,
    ARRAY['EMPLOYER'::text] AS projected_roles
   FROM er_master er;
CREATE OR REPLACE VIEW public.ce_v_plan_candidates_v2 AS
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'VIOLATION'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    ef.total_violation_exposure AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
        CASE
            WHEN ef.escalated_violation_count > 0 THEN 'ESCALATED_VIOLATION'::text
            WHEN ef.days_oldest_violation > 90 THEN 'AGING_VIOLATION'::text
            WHEN ef.open_violation_count >= 3 THEN 'MULTIPLE_VIOLATIONS'::text
            ELSE 'OPEN_VIOLATION'::text
        END AS candidate_reason,
        CASE
            WHEN ef.escalated_violation_count > 0 THEN 'CRITICAL'::text
            WHEN ef.days_oldest_violation > 90 THEN 'HIGH'::text
            WHEN ef.open_violation_count >= 3 THEN 'HIGH'::text
            ELSE 'MEDIUM'::text
        END AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE ef.open_violation_count > 0
UNION ALL
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'OVERDUE_FOLLOW_UP'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    0::numeric AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
    'OVERDUE_FOLLOW_UP'::text AS candidate_reason,
    'HIGH'::text AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE ef.overdue_followup_count > 0
UNION ALL
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'ARRANGEMENT_BREACH'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    ef.total_arrangement_outstanding AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
        CASE
            WHEN ef.breached_arrangement_count > 0 THEN 'ARRANGEMENT_DEFAULT'::text
            ELSE 'ARRANGEMENT_AT_RISK'::text
        END AS candidate_reason,
    'CRITICAL'::text AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE ef.any_breach_detected = true OR ef.max_missed_payments > 0
UNION ALL
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'NOTICE_RESPONSE'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    0::numeric AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
    'NOTICE_RESPONSE_DUE'::text AS candidate_reason,
        CASE
            WHEN ef.notice_days_remaining <= 3 THEN 'CRITICAL'::text
            WHEN ef.notice_days_remaining <= 7 THEN 'HIGH'::text
            ELSE 'MEDIUM'::text
        END AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE ef.pending_notice_count > 0
UNION ALL
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'RISK_NO_VISIT'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    0::numeric AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
    'HIGH_RISK_NO_VISIT'::text AS candidate_reason,
        CASE
            WHEN ef.risk_band::text = 'CRITICAL'::text THEN 'CRITICAL'::text
            ELSE 'HIGH'::text
        END AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE (ef.risk_band::text = ANY (ARRAY['HIGH'::character varying, 'CRITICAL'::character varying]::text[])) AND (ef.days_since_last_inspection IS NULL OR ef.days_since_last_inspection > 90)
UNION ALL
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'CARRY_FORWARD'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    0::numeric AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
    'CARRY_FORWARD_INCOMPLETE'::text AS candidate_reason,
    'MEDIUM'::text AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE ef.carry_forward_count > 0
UNION ALL
 SELECT ef.employer_id,
    ef.employer_name,
    ef.territory,
    'AUDIT_RECENCY'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    ef.open_violation_count,
    ef.escalated_violation_count,
    ef.overdue_followup_count,
    0::numeric AS financial_exposure,
    ef.notice_days_remaining,
    ef.any_breach_detected,
    ef.carry_forward_count,
    'LAST_AUDIT_EXCEEDED'::text AS candidate_reason,
    'LOW'::text AS derived_priority
   FROM ce_v_plan_employer_facts ef
  WHERE ef.days_since_last_inspection > 180 OR ef.days_since_last_inspection IS NULL AND ef.open_violation_count = 0
UNION ALL
 SELECT COALESCE(sl.linked_employer_id, sl.id::text::character varying) AS employer_id,
    COALESCE(ef.employer_name, sl.business_name) AS employer_name,
    COALESCE(ef.territory, sl.territory) AS territory,
    'SCOUTING_LEAD'::text AS candidate_source,
    ef.risk_band,
    ef.risk_score,
    ef.days_since_last_inspection,
    COALESCE(ef.open_violation_count, 0::bigint) AS open_violation_count,
    COALESCE(ef.escalated_violation_count, 0::bigint) AS escalated_violation_count,
    COALESCE(ef.overdue_followup_count, 0::bigint) AS overdue_followup_count,
    0::numeric AS financial_exposure,
    ef.notice_days_remaining,
    COALESCE(ef.any_breach_detected, false) AS any_breach_detected,
    COALESCE(ef.carry_forward_count, 0::bigint) AS carry_forward_count,
    'SCOUTING_LEAD'::text AS candidate_reason,
        CASE sl.confidence_level
            WHEN 'HIGH'::text THEN 'HIGH'::text
            WHEN 'MEDIUM'::text THEN 'MEDIUM'::text
            ELSE 'LOW'::text
        END AS derived_priority
   FROM ce_scouting_leads sl
     LEFT JOIN ce_v_plan_employer_facts ef ON ef.employer_id::text = sl.linked_employer_id::text
  WHERE sl.status::text = ANY (ARRAY['NEW'::character varying, 'UNDER_INVESTIGATION'::character varying]::text[]);
CREATE OR REPLACE VIEW public.dashboard_v_compliance_distribution AS
 WITH base AS (
         SELECT dashboard_v_employer_compliance_status.bucket
           FROM dashboard_v_employer_compliance_status
        ), buckets(name, color, sort_order) AS (
         VALUES ('Compliant'::text,'hsl(144 65% 34%)'::text,1), ('Minor Issues'::text,'hsl(44 90% 57%)'::text,2), ('Under Review'::text,'hsl(217 91% 60%)'::text,3), ('Non-Compliant'::text,'hsl(2 74% 50%)'::text,4)
        )
 SELECT b.name,
    COALESCE(c.cnt, 0) AS value,
    b.color
   FROM buckets b
     LEFT JOIN ( SELECT base.bucket,
            count(*)::integer AS cnt
           FROM base
          GROUP BY base.bucket) c ON c.bucket = b.name
  ORDER BY b.sort_order;
CREATE OR REPLACE VIEW public.dashboard_v_compliance_metrics AS
 SELECT ( SELECT count(*)::integer AS count
           FROM er_master
          WHERE er_master.status = 'A'::bpchar) AS total_employers,
    ( SELECT count(*)::integer AS count
           FROM dashboard_v_employer_compliance_status
          WHERE dashboard_v_employer_compliance_status.bucket = 'Compliant'::text) AS compliant_employers,
    ( SELECT count(*)::integer AS count
           FROM ce_violations
          WHERE (ce_violations.status::text <> ALL (ARRAY['RESOLVED'::text, 'CLOSED'::text, 'DISMISSED'::text, 'CANCELLED'::text])) AND (ce_violations.is_deleted IS NULL OR ce_violations.is_deleted = false) AND (ce_violations.is_merged IS NULL OR ce_violations.is_merged = false) AND ce_violations.merged_into_id IS NULL) AS active_violations,
    ( SELECT count(*)::integer AS count
           FROM ce_inspections
          WHERE ce_inspections.status::text = ANY (ARRAY['SCHEDULED'::text, 'PENDING'::text])) AS pending_audits;

